/// Deterministic xoshiro256++ PRNG for reproducible random tensor generation.
#[derive(Debug, Clone)]
struct Xoshiro256PlusPlus {
    s: [u64; 4],
}

impl Xoshiro256PlusPlus {
    fn new(seed: u64) -> Self {
        // SplitMix64 to expand seed into state
        let mut z = seed;
        let mut s = [0u64; 4];
        for slot in &mut s {
            z = z.wrapping_add(0x9e37_79b9_7f4a_7c15);
            let mut x = z;
            x = (x ^ (x >> 30)).wrapping_mul(0xbf58_476d_1ce4_e5b9);
            x = (x ^ (x >> 27)).wrapping_mul(0x94d0_49bb_1331_11eb);
            *slot = x ^ (x >> 31);
        }
        Self { s }
    }

    fn next_u64(&mut self) -> u64 {
        let result = (self.s[0].wrapping_add(self.s[3]))
            .rotate_left(23)
            .wrapping_add(self.s[0]);
        let t = self.s[1] << 17;
        self.s[2] ^= self.s[0];
        self.s[3] ^= self.s[1];
        self.s[1] ^= self.s[2];
        self.s[0] ^= self.s[3];
        self.s[2] ^= t;
        self.s[3] = self.s[3].rotate_left(45);
        result
    }

    /// Uniform f64 in [0, 1).
    fn next_f64(&mut self) -> f64 {
        (self.next_u64() >> 11) as f64 / ((1u64 << 53) as f64)
    }

    /// Standard normal via Box-Muller transform.
    fn next_normal(&mut self) -> f64 {
        loop {
            let u1 = self.next_f64();
            let u2 = self.next_f64();
            if u1 > 0.0 {
                return (-2.0 * u1.ln()).sqrt() * (2.0 * std::f64::consts::PI * u2).cos();
            }
        }
    }

    /// Two independent standard normals from one Box-Muller transform.
    fn next_normal_pair(&mut self) -> (f64, f64) {
        loop {
            let u1 = self.next_f64();
            let u2 = self.next_f64();
            if u1 > 0.0 {
                let radius = (-2.0 * u1.ln()).sqrt();
                let theta = 2.0 * std::f64::consts::PI * u2;
                return (radius * theta.cos(), radius * theta.sin());
            }
        }
    }

    fn next_normal_values(&mut self, len: usize) -> Vec<f64> {
        // For large tensors, split the work: draw the raw RNG pairs SERIALLY (the RNG is
        // a sequential stream — cheap xoshiro steps + the exact `u1>0` retry) and apply
        // the expensive Box-Muller transcendentals (ln/sqrt/cos/sin, ~90% of the cost) in
        // PARALLEL. Bit-for-bit identical to the serial pair/single loop below: same draws
        // in the same order (retry preserved: `(g>>11)!=0` iff the serial `u1>0.0`), same
        // per-draw formula, same output layout ([a,b] per full pair, trailing single = cos
        // only). torch's randn is itself single-threaded, so this pulls ahead.
        // frankentorch-randn-par.
        const NORMAL_PAR_MIN: usize = 1 << 15;
        if len >= NORMAL_PAR_MIN {
            let n_draws = (len + 1) / 2;
            let mut raws: Vec<(u64, u64)> = Vec::with_capacity(n_draws);
            for _ in 0..n_draws {
                loop {
                    let g1 = self.next_u64();
                    let g2 = self.next_u64();
                    if (g1 >> 11) != 0 {
                        raws.push((g1, g2));
                        break;
                    }
                }
            }
            use rayon::prelude::*;
            let mut values = vec![0.0f64; len];
            let denom = (1u64 << 53) as f64;
            values
                .par_chunks_mut(2)
                .zip(raws.par_iter())
                .for_each(|(chunk, &(g1, g2))| {
                    let u1 = (g1 >> 11) as f64 / denom;
                    let u2 = (g2 >> 11) as f64 / denom;
                    let radius = (-2.0 * u1.ln()).sqrt();
                    let theta = 2.0 * std::f64::consts::PI * u2;
                    chunk[0] = radius * theta.cos();
                    if chunk.len() == 2 {
                        chunk[1] = radius * theta.sin();
                    }
                });
            return values;
        }
        let mut values = Vec::with_capacity(len);
        while values.len() + 1 < len {
            let (a, b) = self.next_normal_pair();
            values.push(a);
            values.push(b);
        }
        if values.len() < len {
            values.push(self.next_normal());
        }
        values
    }

    /// Draw `len` uniforms and apply a per-element inverse-CDF transform `f`. For large
    /// `len`, the sequential RNG draw is done SERIALLY (cheap xoshiro) and the (typically
    /// transcendental, expensive) transform is applied in PARALLEL. Bit-for-bit identical
    /// to the serial `(0..len).map(|_| f(self.next_f64()))` form: each output consumes
    /// exactly one `next_u64` in draw order, `u = (g>>11) as f64 / 2^53` == `next_f64()`,
    /// and `f` is applied in the same index order. Only valid for pure 1-draw-per-output
    /// inverse-CDF transforms (no rejection loop). frankentorch-randn-par.
    fn next_uniform_transformed<F>(&mut self, len: usize, f: F) -> Vec<f64>
    where
        F: Fn(f64) -> f64 + Sync + Send,
    {
        const UNIFORM_PAR_MIN: usize = 1 << 15;
        if len < UNIFORM_PAR_MIN {
            return (0..len).map(|_| f(self.next_f64())).collect();
        }
        let raws: Vec<u64> = (0..len).map(|_| self.next_u64()).collect();
        use rayon::prelude::*;
        let denom = (1u64 << 53) as f64;
        raws.par_iter()
            .map(|&g| f((g >> 11) as f64 / denom))
            .collect()
    }

    /// Like [`Self::next_uniform_transformed`] but each output is one `next_normal()`
    /// draw (single-value Box-Muller: cos branch, 2 uniforms per output with the `u1>0`
    /// retry) fed through `f`. The SERIAL pass draws the accepted `(g1,g2)` pairs; the
    /// PARALLEL pass does the Box-Muller transcendentals (ln/sqrt/cos) + `f`. Bit-for-bit
    /// identical to `(0..len).map(|_| f(self.next_normal()))`. frankentorch-randn-par.
    fn next_normal_transformed<F>(&mut self, len: usize, f: F) -> Vec<f64>
    where
        F: Fn(f64) -> f64 + Sync + Send,
    {
        const NORMAL_T_PAR_MIN: usize = 1 << 15;
        if len < NORMAL_T_PAR_MIN {
            return (0..len).map(|_| f(self.next_normal())).collect();
        }
        let mut raws: Vec<(u64, u64)> = Vec::with_capacity(len);
        for _ in 0..len {
            loop {
                let g1 = self.next_u64();
                let g2 = self.next_u64();
                if (g1 >> 11) != 0 {
                    raws.push((g1, g2));
                    break;
                }
            }
        }
        use rayon::prelude::*;
        let denom = (1u64 << 53) as f64;
        raws.par_iter()
            .map(|&(g1, g2)| {
                let u1 = (g1 >> 11) as f64 / denom;
                let u2 = (g2 >> 11) as f64 / denom;
                let n = (-2.0 * u1.ln()).sqrt() * (2.0 * std::f64::consts::PI * u2).cos();
                f(n)
            })
            .collect()
    }

    /// Gamma(shape) using Marsaglia-Tsang method.
    fn next_gamma(&mut self, shape: f64) -> f64 {
        if shape < 1.0 {
            let u = self.next_f64();
            return self.next_gamma(shape + 1.0) * u.powf(1.0 / shape);
        }
        let d = shape - 1.0 / 3.0;
        let c = 1.0 / (9.0 * d).sqrt();
        loop {
            let x = self.next_normal();
            let v = 1.0 + c * x;
            if v > 0.0 {
                let v = v * v * v;
                let u = self.next_f64();
                if u < 1.0 - 0.0331 * (x * x) * (x * x)
                    || u.ln() < 0.5 * x * x + d * (1.0 - v + v.ln())
                {
                    return d * v;
                }
            }
        }
    }

    /// Beta(alpha, beta) via ratio of Gamma variates.
    #[allow(dead_code)]
    fn next_beta(&mut self, alpha: f64, beta: f64) -> f64 {
        let x = self.next_gamma(alpha);
        let y = self.next_gamma(beta);
        x / (x + y)
    }

    /// Draw `len` independent samples, each produced by `f(index, sub_rng)` from its OWN
    /// deterministic sub-stream seeded from a single draw of this parent stream. Because
    /// output element `i` depends only on `seeds[i]` (via `Xoshiro256PlusPlus::new`), the
    /// map is ORDER-INDEPENDENT — the serial (small `len`) and parallel (large `len`)
    /// branches below produce BIT-IDENTICAL output. This is the standard split/counter RNG
    /// model (cf. JAX `split`, PyTorch Philox per-element offsets), and it is what lets the
    /// rejection samplers (gamma / beta / studentt / poisson / binomial / …) — whose
    /// per-element RNG-draw count is DATA-DEPENDENT and therefore cannot be parallelized
    /// within a single shared stream — run in parallel deterministically. The parent stream
    /// advances by exactly `len` steps regardless of how many draws each sample consumes, so
    /// subsequent draws stay reproducible. torch's CPU distribution samplers are
    /// single-threaded, so parallelizing pulls well ahead. frankentorch-dist-par.
    fn substream_sample<F>(&mut self, len: usize, f: F) -> Vec<f64>
    where
        F: Fn(usize, &mut Xoshiro256PlusPlus) -> f64 + Sync + Send,
    {
        let seeds: Vec<u64> = (0..len).map(|_| self.next_u64()).collect();
        const SUBSTREAM_PAR_MIN: usize = 1 << 14;
        if len < SUBSTREAM_PAR_MIN {
            seeds
                .iter()
                .enumerate()
                .map(|(i, &sd)| f(i, &mut Xoshiro256PlusPlus::new(sd)))
                .collect()
        } else {
            use rayon::prelude::*;
            seeds
                .par_iter()
                .enumerate()
                .map(|(i, &sd)| f(i, &mut Xoshiro256PlusPlus::new(sd)))
                .collect()
        }
    }
}

#[derive(Clone)]
struct BatchNorm1dSumShortcut {
    input: TensorNodeId,
    weight: TensorNodeId,
    bias: TensorNodeId,
    mean: Vec<f64>,
    var: Vec<f64>,
    batch_size: usize,
    channels: usize,
    spatial: usize,
    eps: f64,
}

#[derive(Clone)]
struct BatchNorm2dF32SumShortcut {
    input: TensorNodeId,
    weight: TensorNodeId,
    bias: TensorNodeId,
    mean: Vec<f32>,
    var: Vec<f32>,
    batch_size: usize,
    channels: usize,
    spatial: usize,
    eps: f32,
}

#[derive(Clone)]
struct GroupNormF32SumShortcut {
    input: TensorNodeId,
    weight: TensorNodeId,
    bias: TensorNodeId,
    batch_size: usize,
    num_groups: usize,
    channels_per_group: usize,
    spatial: usize,
    eps: f32,
}

/// Registered on the f64 grad-path output of `functional_avg_pool1d` so that a
/// following `tensor_sum` can reach the fused scalar-loss backward without the
/// caller having to know the `functional_avg_pool1d_sum` name
/// (`frankentorch-o4782`). Mirrors the norm shortcuts above.
#[derive(Clone, Copy)]
struct AvgPool1dSumShortcut {
    input: TensorNodeId,
    batch: usize,
    channels: usize,
    length: usize,
    kernel_size: usize,
    output_len: usize,
    stride: usize,
}

#[derive(Clone)]
pub struct FrankenTorchSession {
    tape: Tape,
    tensor_tape: TensorTape,
    runtime: RuntimeContext,
    rng: Xoshiro256PlusPlus,
    grad_enabled_stack: Vec<bool>,
    /// Autocast stack: each entry is either None (autocast disabled) or
    /// Some(target_dtype). The top of the stack determines current state.
    autocast_stack: Vec<Option<DType>>,
    /// Inference mode nesting depth (0 = normal mode, >0 = inference mode active).
    inference_mode_depth: usize,
    /// Module-level forward pre-hooks (called before any Module::forward).
    module_forward_pre_hooks: Vec<(ModuleHookHandle, ModuleForwardPreHook)>,
    /// Module-level forward hooks (called after any Module::forward).
    module_forward_hooks: Vec<(ModuleHookHandle, ModuleForwardHook)>,
    /// Counter for generating unique module hook handles.
    module_hook_counter: u64,
    batch_norm1d_sum_shortcuts: BTreeMap<usize, BatchNorm1dSumShortcut>,
    batch_norm2d_f32_sum_shortcuts: BTreeMap<usize, BatchNorm2dF32SumShortcut>,
    group_norm_f32_sum_shortcuts: BTreeMap<usize, GroupNormF32SumShortcut>,
    avg_pool1d_sum_shortcuts: BTreeMap<usize, AvgPool1dSumShortcut>,
}

impl std::fmt::Debug for FrankenTorchSession {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("FrankenTorchSession")
            .field("tape", &self.tape)
            .field("tensor_tape", &self.tensor_tape)
            .field("runtime", &self.runtime)
            .field("rng", &self.rng)
            .field("grad_enabled_stack", &self.grad_enabled_stack)
            .field("autocast_stack", &self.autocast_stack)
            .field("inference_mode_depth", &self.inference_mode_depth)
            .field(
                "module_forward_pre_hooks",
                &format!("[{} hooks]", self.module_forward_pre_hooks.len()),
            )
            .field(
                "module_forward_hooks",
                &format!("[{} hooks]", self.module_forward_hooks.len()),
            )
            .field("module_hook_counter", &self.module_hook_counter)
            .field(
                "batch_norm1d_sum_shortcuts",
                &self.batch_norm1d_sum_shortcuts.len(),
            )
            .field(
                "batch_norm2d_f32_sum_shortcuts",
                &self.batch_norm2d_f32_sum_shortcuts.len(),
            )
            .field(
                "group_norm_f32_sum_shortcuts",
                &self.group_norm_f32_sum_shortcuts.len(),
            )
            .field(
                "avg_pool1d_sum_shortcuts",
                &self.avg_pool1d_sum_shortcuts.len(),
            )
            .finish()
    }
}

