    pub fn tensor_values_f32(&self, node: TensorNodeId) -> Result<Vec<f32>, AutogradError> {
        self.tensor_tape.values_f32(node)
    }

    /// Mutable borrow of a contiguous f32 node's storage, for inference-only
    /// in-place elementwise rewrites of a dead intermediate (a fused softmax / GELU
    /// that avoids materializing a fresh tensor). Caller guarantees single ownership
    /// of the node's contents. Errors if the node is not contiguous f32.
    pub fn tensor_values_f32_mut(
        &mut self,
        node: TensorNodeId,
    ) -> Result<&mut [f32], AutogradError> {
        self.tensor_tape.values_f32_mut(node)
    }

    /// Borrowed (zero-copy) view of a contiguous f32 node's storage — the read-only
    /// counterpart of [`Self::tensor_values_f32`]. Lets an inference-only consumer
    /// feed the storage straight into a kernel (e.g. a fused attention) without the
    /// `to_vec` alloc+copy. Errors if the node is not contiguous f32.
    pub fn tensor_values_f32_borrowed(&self, node: TensorNodeId) -> Result<&[f32], AutogradError> {
        self.tensor_tape.values_f32_borrowed(node)
    }

    /// Int8 dynamic-quantized linear layer `y = x @ w_i8^T + bias`, the
    /// inference-only counterpart of an f32 linear. `x` is an f32 node of shape
    /// `[m, in_features]`; `w_i8`/`w_scales` are symmetric per-output-channel
    /// int8 weights of shape `[out_features, in_features]` (build them with
    /// [`quantize_per_output_channel_i8`]); `bias` is an optional
    /// `[out_features]` slice. Returns a fresh f32 leaf of shape
    /// `[m, out_features]`, detached from the autograd graph — this op is
    /// inference-only, so call it inside a no-grad region. The matmul
    /// accumulates in i32 and dequantizes with the per-row activation scale and
    /// per-channel weight scales (ONNX DynamicQuantizeLinear + MatMulInteger).
    pub fn tensor_linear_int8_dynamic(
        &mut self,
        x: TensorNodeId,
        w_i8: &[i8],
        w_scales: &[f32],
        out_features: usize,
        in_features: usize,
        bias: Option<&[f32]>,
    ) -> Result<TensorNodeId, AutogradError> {
        // Read the activation storage borrowed (no `to_vec`): this op runs once per
        // Linear, so the alloc+copy of `x` is pure per-layer overhead. The kernel
        // only reads `x`, and the borrow ends before the output node is created.
        let y = {
            let x_slice = self.tensor_tape.values_f32_borrowed(x)?;
            debug_assert_eq!(
                x_slice.len() % in_features,
                0,
                "x length must be a multiple of in_features"
            );
            let m = x_slice.len() / in_features;
            ft_kernel_cpu::linear_int8_dynamic_f32(
                x_slice,
                m,
                in_features,
                w_i8,
                w_scales,
                out_features,
                bias,
            )
        };
        let m = y.len() / out_features;
        self.tensor_variable_f32(y, vec![m, out_features], false)
    }

    /// Pre-packed twin of [`Self::tensor_linear_int8_dynamic`]: `w_packed` is the
    /// NR=4-packed weight from [`pack_int8_weights_nr4`] (`out_features % 4 == 0`,
    /// `in_features % 16 == 0`). Same f32 result, but the aarch64 SDOT kernel reads
    /// each output group's four weight rows as one contiguous cache line — the
    /// zero-per-forward weight-packing win for static-weight inference.
    pub fn tensor_linear_int8_dynamic_prepacked(
        &mut self,
        x: TensorNodeId,
        w_packed: &[i8],
        w_scales: &[f32],
        out_features: usize,
        in_features: usize,
        bias: Option<&[f32]>,
    ) -> Result<TensorNodeId, AutogradError> {
        let y = {
            let x_slice = self.tensor_tape.values_f32_borrowed(x)?;
            debug_assert_eq!(
                x_slice.len() % in_features,
                0,
                "x length must be a multiple of in_features"
            );
            let m = x_slice.len() / in_features;
            ft_kernel_cpu::linear_int8_dynamic_prepacked_f32(
                x_slice,
                m,
                in_features,
                w_packed,
                w_scales,
                out_features,
                bias,
            )
        };
        let m = y.len() / out_features;
        self.tensor_variable_f32(y, vec![m, out_features], false)
    }

