    /// Tape-level I32 conversion is not yet implemented; this call
    /// currently returns `AutogradError::DenseTensor(UnsupportedDType(I32))`.
    pub fn tensor_int(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        self.tensor_to_dtype(input, DType::I32)
    }

    /// PyTorch-style alias for casting a tensor to int64.
    ///
    /// Equivalent to `tensor.long()` in PyTorch.
    ///
    /// Tape-level I64 conversion is not yet implemented; this call
    /// currently returns `AutogradError::DenseTensor(UnsupportedDType(I64))`.
    pub fn tensor_long(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        self.tensor_to_dtype(input, DType::I64)
    }

    /// PyTorch-style alias for casting a tensor to bool.
    ///
    /// Equivalent to `tensor.bool()` in PyTorch.
    ///
    /// Tape-level Bool conversion is not yet implemented; this call
    /// currently returns `AutogradError::DenseTensor(UnsupportedDType(Bool))`.
    pub fn tensor_bool(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        self.tensor_to_dtype(input, DType::Bool)
    }

    /// PyTorch-style alias for casting a tensor to complex64.
    ///
    /// Equivalent to `tensor.cfloat()` in PyTorch. A real input becomes a
    /// complex tensor with a zero imaginary part; a complex input is re-cast to
    /// single precision. As elsewhere in this port, complex-valued autograd is
    /// unsupported, so a `requires_grad` input fails loud (matching `fft`/`polar`).
    pub fn tensor_cfloat(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        self.cast_real_to_complex(input, DType::F32, DType::Complex64)
    }

    /// PyTorch-style alias for casting a tensor to complex128.
    ///
    /// Equivalent to `tensor.cdouble()` in PyTorch. A real input becomes a
    /// complex tensor with a zero imaginary part; a complex input is re-cast to
    /// double precision. Complex-valued autograd is unsupported, so a
    /// `requires_grad` input fails loud (matching `fft`/`polar`).
    pub fn tensor_cdouble(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        self.cast_real_to_complex(input, DType::F64, DType::Complex128)
    }

    /// Cast `input` to a complex dtype: real input -> (input, 0i) at
    /// `real_dtype` precision; complex input -> re-cast both components to
    /// `real_dtype`. `complex_dtype` is the matching complex target
    /// (F32 -> Complex64, F64 -> Complex128). Composes through the existing
    /// (non-differentiable) `tensor_complex`, so it inherits its requires_grad
    /// guard. Backs `tensor_cfloat`/`tensor_cdouble`.
    fn cast_real_to_complex(
        &mut self,
        input: TensorNodeId,
        real_dtype: DType,
        complex_dtype: DType,
    ) -> Result<TensorNodeId, AutogradError> {
        let dtype = self.tensor_dtype(input)?;
        if dtype == complex_dtype {
            return Ok(input);
        }
        if dtype == DType::Complex64 || dtype == DType::Complex128 {
            // Complex -> complex precision change: split, re-cast, recombine.
            let re = self.tensor_real(input)?;
            let im = self.tensor_imag(input)?;
            let re_c = self.tensor_to_dtype(re, real_dtype)?;
            let im_c = self.tensor_to_dtype(im, real_dtype)?;
            return self.tensor_complex(re_c, im_c);
        }
        // Real input: real = input at target precision, imaginary = zeros.
        let re = self.tensor_to_dtype(input, real_dtype)?;
        let shape = self.tensor_shape(re)?;
        let zeros = self.tensor_zeros(shape, false)?;
        let zeros_c = self.tensor_to_dtype(zeros, real_dtype)?;
        self.tensor_complex(re, zeros_c)
    }

    /// Cast a tensor to the given dtype.
    ///
    /// Supported floating-point casts: F32, F64, F16, and BF16 (all
    /// differentiable with identity backward). Integer, bool, complex,
    /// and quantized targets surface
    /// `AutogradError::DenseTensor(UnsupportedDType(_))`. Returns the
    /// input unchanged when the source dtype already matches the target.
    pub fn tensor_to_dtype(
        &mut self,
        input: TensorNodeId,
        dtype: DType,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_tape.to_dtype(input, dtype)
    }

    /// Convert `input` to the same dtype as `other`.
    ///
    /// Equivalent to `input.type_as(other)` in PyTorch.
    pub fn tensor_type_as(
        &mut self,
        input: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let target_dtype = self.tensor_dtype(other)?;
        self.tensor_to_dtype(input, target_dtype)
    }

    /// Return the real component of a complex tensor.
    pub fn tensor_real(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let tensor = self.tensor_tape.tensor(input)?;
        let meta = tensor.meta().clone();
        let requires_grad =
            self.tensor_tape.tensor_requires_grad(input)? && self.tensor_tape.is_grad_enabled();

        let (output_meta, output_storage) = match tensor.typed_storage() {
            TensorStorage::Complex64(values) => (
                TensorMeta::from_shape(meta.shape().to_vec(), DType::F32, meta.device()),
                TensorStorage::F32(Arc::new(values.iter().map(|z| z.re).collect())),
            ),
            TensorStorage::Complex128(values) => (
                TensorMeta::from_shape(meta.shape().to_vec(), DType::F64, meta.device()),
                TensorStorage::F64(Arc::new(values.iter().map(|z| z.re).collect())),
            ),
            _ => {
                return Err(AutogradError::DenseTensor(
                    ft_core::DenseTensorError::UnsupportedDType(meta.dtype()),
                ));
            }
        };
        let output = DenseTensor::from_typed_storage(output_meta, output_storage)?;

        // Autograd: re = Re(z). The complex input's gradient is the interleaved real
        // buffer [dRe_0, dIm_0, ...]; d(re)/d(z) routes the incoming real grad into the
        // real lanes and leaves the imaginary lanes zero. frankentorch-ng1hw.
        let out = if requires_grad {
            self.tensor_tape
                .apply_complex_bridge(&[input], output, |_ctx, grad_outputs| {
                    let g = grad_outputs[0];
                    let mut grad_z = vec![0.0; g.len() * 2];
                    for (i, &gi) in g.iter().enumerate() {
                        grad_z[2 * i] = gi;
                    }
                    Ok(vec![Some(grad_z)])
                })?
        } else {
            self.tensor_tape.leaf_tensor(output, false)
        };
        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!("real input={} out={}", input.0, out.0),
        );
        Ok(out)
    }

    /// Return the imaginary component of a complex tensor.
    pub fn tensor_imag(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let tensor = self.tensor_tape.tensor(input)?;
        let meta = tensor.meta().clone();
        let requires_grad =
            self.tensor_tape.tensor_requires_grad(input)? && self.tensor_tape.is_grad_enabled();

        let (output_meta, output_storage) = match tensor.typed_storage() {
            TensorStorage::Complex64(values) => (
                TensorMeta::from_shape(meta.shape().to_vec(), DType::F32, meta.device()),
                TensorStorage::F32(Arc::new(values.iter().map(|z| z.im).collect())),
            ),
            TensorStorage::Complex128(values) => (
                TensorMeta::from_shape(meta.shape().to_vec(), DType::F64, meta.device()),
                TensorStorage::F64(Arc::new(values.iter().map(|z| z.im).collect())),
            ),
            _ => {
                return Err(AutogradError::DenseTensor(
                    ft_core::DenseTensorError::UnsupportedDType(meta.dtype()),
                ));
            }
        };
        let output = DenseTensor::from_typed_storage(output_meta, output_storage)?;

        // Autograd: im = Im(z). Incoming real grad routes into the imaginary lanes of
        // the interleaved [dRe_0, dIm_0, ...] complex gradient. frankentorch-ng1hw.
        let out = if requires_grad {
            self.tensor_tape
                .apply_complex_bridge(&[input], output, |_ctx, grad_outputs| {
                    let g = grad_outputs[0];
                    let mut grad_z = vec![0.0; g.len() * 2];
                    for (i, &gi) in g.iter().enumerate() {
                        grad_z[2 * i + 1] = gi;
                    }
                    Ok(vec![Some(grad_z)])
                })?
        } else {
            self.tensor_tape.leaf_tensor(output, false)
        };
        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!("imag input={} out={}", input.0, out.0),
        );
        Ok(out)
    }

    /// Return the element-wise complex conjugate of a complex tensor.
    pub fn tensor_conj(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let tensor = self.tensor_tape.tensor(input)?;
        let meta = tensor.meta().clone();
        let requires_grad =
            self.tensor_tape.tensor_requires_grad(input)? && self.tensor_tape.is_grad_enabled();

        let output_storage = match tensor.typed_storage() {
            TensorStorage::Complex64(values) => {
                TensorStorage::Complex64(Arc::new(values.iter().map(|z| z.conj()).collect()))
            }
            TensorStorage::Complex128(values) => {
                TensorStorage::Complex128(Arc::new(values.iter().map(|z| z.conj()).collect()))
            }
            _ => {
                return Err(AutogradError::DenseTensor(
                    ft_core::DenseTensorError::UnsupportedDType(meta.dtype()),
                ));
            }
        };
        let output = DenseTensor::from_typed_storage(meta, output_storage)?;

        // Autograd (frankentorch-ng1hw): conj(z) = (re, -im) is the C-linear conjugate.
        // Its adjoint negates the imaginary lanes of the incoming complex gradient:
        // grad_z = conj(grad_out) (torch convention), i.e. grad_z[2k]=g[2k],
        // grad_z[2k+1]=-g[2k+1] over the interleaved [dRe,dIm,...] buffer.
        let out = if requires_grad {
            self.tensor_tape
                .apply_complex_bridge(&[input], output, |_ctx, grad_outputs| {
                    let g = grad_outputs[0];
                    let mut grad_z = g.to_vec();
                    let mut i = 1;
                    while i < grad_z.len() {
                        grad_z[i] = -grad_z[i];
                        i += 2;
                    }
                    Ok(vec![Some(grad_z)])
                })?
        } else {
            self.tensor_tape.leaf_tensor(output, false)
        };
        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!("conj input={} out={}", input.0, out.0),
        );
        Ok(out)
    }

    /// Physical conjugate - materializes the conjugate (same as conj in FrankenTorch).
    pub fn tensor_conj_physical(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_conj(input)
    }

    /// Resolve conjugate view to materialized tensor.
    /// FrankenTorch doesn't use lazy conjugation, so this is an identity.
    pub fn tensor_resolve_conj(&self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        Ok(input)
    }

    /// Resolve negation view to materialized tensor.
    /// FrankenTorch doesn't use lazy negation, so this is an identity.
    pub fn tensor_resolve_neg(&self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        Ok(input)
    }

    /// Construct a complex tensor from separate real and imaginary tensors.
    pub fn tensor_complex(
        &mut self,
        real: TensorNodeId,
        imag: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let real_tensor = self.tensor_tape.tensor(real)?;
        let imag_tensor = self.tensor_tape.tensor(imag)?;
        let real_meta = real_tensor.meta().clone();
        let imag_meta = imag_tensor.meta().clone();

        let requires_grad = self.tensor_tape.is_grad_enabled()
            && (self.tensor_tape.tensor_requires_grad(real)?
                || self.tensor_tape.tensor_requires_grad(imag)?);
        if real_meta.shape() != imag_meta.shape() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "complex: real and imag must have identical shapes",
                },
            )));
        }

        let (output_meta, output_storage) =
            match (real_tensor.typed_storage(), imag_tensor.typed_storage()) {
                (TensorStorage::F32(real_values), TensorStorage::F32(imag_values)) => (
                    TensorMeta::from_shape(
                        real_meta.shape().to_vec(),
                        DType::Complex64,
                        real_meta.device(),
                    ),
                    TensorStorage::Complex64(Arc::new(
                        real_values
                            .iter()
                            .zip(imag_values.iter())
                            .map(|(&re, &im)| ft_core::Complex64::new(re, im))
                            .collect(),
                    )),
                ),
                (TensorStorage::F64(real_values), TensorStorage::F64(imag_values)) => (
                    TensorMeta::from_shape(
                        real_meta.shape().to_vec(),
                        DType::Complex128,
                        real_meta.device(),
                    ),
                    TensorStorage::Complex128(Arc::new(
                        real_values
                            .iter()
                            .zip(imag_values.iter())
                            .map(|(&re, &im)| ft_core::Complex128::new(re, im))
                            .collect(),
                    )),
                ),
                (TensorStorage::F64Inline4(real_values), TensorStorage::F64(imag_values)) => (
                    TensorMeta::from_shape(
                        real_meta.shape().to_vec(),
                        DType::Complex128,
                        real_meta.device(),
                    ),
                    TensorStorage::Complex128(Arc::new(
                        real_values
                            .iter()
                            .zip(imag_values.iter())
                            .map(|(&re, &im)| ft_core::Complex128::new(re, im))
                            .collect(),
                    )),
                ),
                (TensorStorage::F64(real_values), TensorStorage::F64Inline4(imag_values)) => (
                    TensorMeta::from_shape(
                        real_meta.shape().to_vec(),
                        DType::Complex128,
                        real_meta.device(),
                    ),
                    TensorStorage::Complex128(Arc::new(
                        real_values
                            .iter()
                            .zip(imag_values.iter())
                            .map(|(&re, &im)| ft_core::Complex128::new(re, im))
                            .collect(),
                    )),
                ),
                (
                    TensorStorage::F64Inline4(real_values),
                    TensorStorage::F64Inline4(imag_values),
                ) => (
                    TensorMeta::from_shape(
                        real_meta.shape().to_vec(),
                        DType::Complex128,
                        real_meta.device(),
                    ),
                    TensorStorage::Complex128(Arc::new(
                        real_values
                            .iter()
                            .zip(imag_values.iter())
                            .map(|(&re, &im)| ft_core::Complex128::new(re, im))
                            .collect(),
                    )),
                ),
                (TensorStorage::F64(real_values), TensorStorage::F32(imag_values)) => (
                    TensorMeta::from_shape(
                        real_meta.shape().to_vec(),
                        DType::Complex128,
                        real_meta.device(),
                    ),
                    TensorStorage::Complex128(Arc::new(
                        real_values
                            .iter()
                            .zip(imag_values.iter())
                            .map(|(&re, &im)| ft_core::Complex128::new(re, f64::from(im)))
                            .collect(),
                    )),
                ),
                (TensorStorage::F64Inline4(real_values), TensorStorage::F32(imag_values)) => (
                    TensorMeta::from_shape(
                        real_meta.shape().to_vec(),
                        DType::Complex128,
                        real_meta.device(),
                    ),
                    TensorStorage::Complex128(Arc::new(
                        real_values
                            .iter()
                            .zip(imag_values.iter())
                            .map(|(&re, &im)| ft_core::Complex128::new(re, f64::from(im)))
                            .collect(),
                    )),
                ),
                (TensorStorage::F32(real_values), TensorStorage::F64(imag_values)) => (
                    TensorMeta::from_shape(
                        real_meta.shape().to_vec(),
                        DType::Complex128,
                        real_meta.device(),
                    ),
                    TensorStorage::Complex128(Arc::new(
                        real_values
                            .iter()
                            .zip(imag_values.iter())
                            .map(|(&re, &im)| ft_core::Complex128::new(f64::from(re), im))
                            .collect(),
                    )),
                ),
                (TensorStorage::F32(real_values), TensorStorage::F64Inline4(imag_values)) => (
                    TensorMeta::from_shape(
                        real_meta.shape().to_vec(),
                        DType::Complex128,
                        real_meta.device(),
                    ),
                    TensorStorage::Complex128(Arc::new(
                        real_values
                            .iter()
                            .zip(imag_values.iter())
                            .map(|(&re, &im)| ft_core::Complex128::new(f64::from(re), im))
                            .collect(),
                    )),
                ),
                _ => {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "complex: real and imag must be float32 or float64 tensors",
                        },
                    )));
                }
            };

        let output = DenseTensor::from_typed_storage(output_meta, output_storage)?;

        // Autograd: z = re + i·im. The complex output's gradient is the interleaved real
        // buffer [dRe_0, dIm_0, ...]; backward de-interleaves it into the real and
        // imaginary inputs (the standard view_as_real adjoint). frankentorch-ng1hw.
        let out = if requires_grad {
            self.tensor_tape
                .apply_complex_bridge(&[real, imag], output, |ctx, grad_outputs| {
                    let g = grad_outputs[0];
                    let n = g.len() / 2;
                    let needs = ctx.needs_input_grad();
                    let grad_re = needs
                        .first()
                        .copied()
                        .unwrap_or(false)
                        .then(|| (0..n).map(|i| g[2 * i]).collect::<Vec<f64>>());
                    let grad_im = needs
                        .get(1)
                        .copied()
                        .unwrap_or(false)
                        .then(|| (0..n).map(|i| g[2 * i + 1]).collect::<Vec<f64>>());
                    Ok(vec![grad_re, grad_im])
                })?
        } else {
            self.tensor_tape.leaf_tensor(output, false)
        };
        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!("complex real={} imag={} out={}", real.0, imag.0, out.0),
        );
        Ok(out)
    }

    /// Return a real-valued view of a complex tensor with trailing dimension 2.
    pub fn tensor_view_as_real(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let tensor = self.tensor_tape.tensor(input)?;
        let meta = tensor.meta().clone();
        let requires_grad =
            self.tensor_tape.tensor_requires_grad(input)? && self.tensor_tape.is_grad_enabled();

        let mut output_shape = meta.shape().to_vec();
        output_shape.push(2);
        let (output_meta, output_storage) = match tensor.typed_storage() {
            TensorStorage::Complex64(values) => (
                TensorMeta::from_shape(output_shape, DType::F32, meta.device()),
                TensorStorage::F32(Arc::new(values.iter().flat_map(|z| [z.re, z.im]).collect())),
            ),
            TensorStorage::Complex128(values) => (
                TensorMeta::from_shape(output_shape, DType::F64, meta.device()),
                TensorStorage::F64(Arc::new(values.iter().flat_map(|z| [z.re, z.im]).collect())),
            ),
            _ => {
                return Err(AutogradError::DenseTensor(
                    ft_core::DenseTensorError::UnsupportedDType(meta.dtype()),
                ));
            }
        };
        let output = DenseTensor::from_typed_storage(output_meta, output_storage)?;

        // Autograd: view_as_real is a pure layout reinterpretation — the real output
        // [..., 2] already uses the same interleaved [re_0, im_0, ...] layout as the
        // complex node's gradient buffer, so the backward is an identity copy.
        // frankentorch-ng1hw.
        let out = if requires_grad {
            self.tensor_tape
                .apply_complex_bridge(&[input], output, |_ctx, grad_outputs| {
                    Ok(vec![Some(grad_outputs[0].to_vec())])
                })?
        } else {
            self.tensor_tape.leaf_tensor(output, false)
        };
        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!("view_as_real input={} out={}", input.0, out.0),
        );
        Ok(out)
    }

    /// Return a complex-valued view from a real tensor whose trailing dimension is 2.
    pub fn tensor_view_as_complex(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let tensor = self.tensor_tape.tensor(input)?;
        let meta = tensor.meta().clone();
        let requires_grad =
            self.tensor_tape.tensor_requires_grad(input)? && self.tensor_tape.is_grad_enabled();

        let shape = meta.shape().to_vec();
        let Some((&last_dim, leading_dims)) = shape.split_last() else {
            // ndim=0 explicitly signals 'no dimensions exist' so
            // the caller can distinguish rank-0 from a regular
            // dim-out-of-range rejection (frankentorch-8c9m).
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::InvalidDimension { dim: 0, ndim: 0 },
            )));
        };
        if last_dim != 2 {
            // ShapeMismatch carries both the actual shape and the
            // expected shape (same leading dims, final 2) so the
            // caller can pinpoint exactly which dim was wrong
            // (frankentorch-8c9m).
            let mut expected_shape = leading_dims.to_vec();
            expected_shape.push(2);
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: shape,
                    rhs: expected_shape,
                },
            )));
        }

        let output_shape = leading_dims.to_vec();
        let (output_meta, output_storage) = match tensor.typed_storage() {
            TensorStorage::F32(values) => (
                TensorMeta::from_shape(output_shape, DType::Complex64, meta.device()),
                TensorStorage::Complex64(Arc::new(
                    values
                        .chunks_exact(2)
                        .map(|pair| ft_core::Complex64::new(pair[0], pair[1]))
                        .collect(),
                )),
            ),
            TensorStorage::F64(values) => (
                TensorMeta::from_shape(output_shape, DType::Complex128, meta.device()),
                TensorStorage::Complex128(Arc::new(
                    values
                        .chunks_exact(2)
                        .map(|pair| ft_core::Complex128::new(pair[0], pair[1]))
                        .collect(),
                )),
            ),
            TensorStorage::F64Inline4(values) => (
                TensorMeta::from_shape(output_shape, DType::Complex128, meta.device()),
                TensorStorage::Complex128(Arc::new(
                    values
                        .chunks_exact(2)
                        .map(|pair| ft_core::Complex128::new(pair[0], pair[1]))
                        .collect(),
                )),
            ),
            _ => {
                return Err(AutogradError::DenseTensor(
                    ft_core::DenseTensorError::UnsupportedDType(meta.dtype()),
                ));
            }
        };

        let output = DenseTensor::from_typed_storage(output_meta, output_storage)?;

        // Autograd: view_as_complex is the inverse layout reinterpretation of
        // view_as_real. The complex output's interleaved gradient buffer
        // [dRe_0, dIm_0, ...] is exactly the real input's [...,2] gradient, so the
        // backward is an identity copy. frankentorch-ng1hw.
        let out = if requires_grad {
            self.tensor_tape
                .apply_complex_bridge(&[input], output, |_ctx, grad_outputs| {
                    Ok(vec![Some(grad_outputs[0].to_vec())])
                })?
        } else {
            self.tensor_tape.leaf_tensor(output, false)
        };
        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!("view_as_complex input={} out={}", input.0, out.0),
        );
        Ok(out)
    }

    /// Generate a Hann window of the requested length.
    pub fn hann_window(
        &mut self,
        window_length: usize,
        periodic: bool,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        if window_length == 0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "hann_window: window_length must be > 0",
                },
            )));
        }
        let denom = if periodic {
            window_length as f64
        } else if window_length == 1 {
            1.0
        } else {
            (window_length - 1) as f64
        };
        let values: Vec<f64> = (0..window_length)
            .map(|n| 0.5 - 0.5 * (2.0 * std::f64::consts::PI * n as f64 / denom).cos())
            .collect();
        self.tensor_variable(values, vec![window_length], requires_grad)
    }

    /// Kaiser window (Bessel-shaped) for signal processing.
    ///
    /// Equivalent to `torch.kaiser_window(window_length, periodic,
    /// beta)`. Parametric window with adjustable side-lobe
    /// suppression via beta:
    ///
    ///   w[n] = i0(beta * sqrt(1 - (2n/denom - 1)²)) / i0(beta)
    ///
    /// `denom = window_length` (periodic) or `window_length - 1`
    /// (symmetric). beta=0 gives a rectangular window;
    /// beta=14 gives ~120 dB side-lobe suppression. Tracked under
    /// frankentorch-8moo. Composes through bessel_i0_scalar (the
    /// helper from 2vxa).
    pub fn kaiser_window(
        &mut self,
        window_length: usize,
        periodic: bool,
        beta: f64,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        if window_length == 0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "kaiser_window: window_length must be > 0",
                },
            )));
        }
        if !beta.is_finite() || beta < 0.0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "kaiser_window: beta must be finite and non-negative",
                },
            )));
        }
        let denom = if periodic {
            window_length as f64
        } else if window_length == 1 {
            1.0
        } else {
            (window_length - 1) as f64
        };
        let i0_beta = bessel_i0_scalar(beta);
        let values: Vec<f64> = (0..window_length)
            .map(|n| {
                let t = 2.0 * n as f64 / denom - 1.0;
                let arg = beta * (1.0 - t * t).max(0.0).sqrt();
                bessel_i0_scalar(arg) / i0_beta
            })
            .collect();
        self.tensor_variable(values, vec![window_length], requires_grad)
    }

    /// Bartlett (triangular) window for signal processing.
    ///
    /// Equivalent to `torch.bartlett_window(window_length,
    /// periodic=True)`. Linear triangular shape:
    ///
    ///   w[n] = 1 - |2n/denom - 1|
    ///
    /// `denom = window_length` (periodic) or `window_length - 1`
    /// (symmetric). Tracked under frankentorch-q4hs.
    pub fn bartlett_window(
        &mut self,
        window_length: usize,
        periodic: bool,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        if window_length == 0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "bartlett_window: window_length must be > 0",
                },
            )));
        }
        let denom = if periodic {
            window_length as f64
        } else if window_length == 1 {
            1.0
        } else {
            (window_length - 1) as f64
        };
        let values: Vec<f64> = (0..window_length)
            .map(|n| 1.0 - (2.0 * n as f64 / denom - 1.0).abs())
            .collect();
        self.tensor_variable(values, vec![window_length], requires_grad)
    }

    /// Blackman window for signal processing.
    ///
    /// Equivalent to `torch.blackman_window(window_length,
    /// periodic=True)`. Three-term cosine window with lower
    /// side-lobe levels than Hann/Hamming:
    ///
    ///   w[n] = 0.42 - 0.5*cos(2πn/denom) + 0.08*cos(4πn/denom)
    ///
    /// `denom = window_length` (periodic) or `window_length - 1`
    /// (symmetric). Tracked under frankentorch-fhrd.
    pub fn blackman_window(
        &mut self,
        window_length: usize,
        periodic: bool,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        if window_length == 0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "blackman_window: window_length must be > 0",
                },
            )));
        }
        let denom = if periodic {
            window_length as f64
        } else if window_length == 1 {
            1.0
        } else {
            (window_length - 1) as f64
        };
        let two_pi = 2.0 * std::f64::consts::PI;
        let four_pi = 4.0 * std::f64::consts::PI;
        let values: Vec<f64> = (0..window_length)
            .map(|n| {
                let x = n as f64 / denom;
                0.42 - 0.5 * (two_pi * x).cos() + 0.08 * (four_pi * x).cos()
            })
            .collect();
        self.tensor_variable(values, vec![window_length], requires_grad)
    }

    /// Hamming window for signal processing.
    ///
    /// Equivalent to `torch.hamming_window(window_length,
    /// periodic=True, alpha=0.54, beta=0.46)`. Sister of
    /// `hann_window` with the canonical Hamming coefficients:
    ///
    ///   w[n] = 0.54 - 0.46 * cos(2πn / denom)
    ///
    /// `denom = window_length` when `periodic=true` (matches
    /// torch's default for spectral analysis); `denom =
    /// window_length - 1` when `periodic=false` (symmetric form).
    /// Tracked under frankentorch-lg75.
    pub fn hamming_window(
        &mut self,
        window_length: usize,
        periodic: bool,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        if window_length == 0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "hamming_window: window_length must be > 0",
                },
            )));
        }
        let denom = if periodic {
            window_length as f64
        } else if window_length == 1 {
            1.0
        } else {
            (window_length - 1) as f64
        };
        let values: Vec<f64> = (0..window_length)
            .map(|n| 0.54 - 0.46 * (2.0 * std::f64::consts::PI * n as f64 / denom).cos())
            .collect();
        self.tensor_variable(values, vec![window_length], requires_grad)
    }

    /// STFT spectrogram via per-frame FFT instead of the naive
    /// O(freq_bins * n_fft) per-(k,frame) DFT. For a power-of-two `n_fft` the
    /// shared radix-2 FFT replaces the O(N^2) inner sum with O(N log N) (the
    /// `stft/len32768_nfft512` bench drops ~28ms -> a few ms); for a
    /// non-power-of-two `n_fft` the same routine falls back to the dense DFT, so
    /// behaviour is preserved there. Each frame is an independent transform, so
    /// distributing frames across Rayon is deterministic. The result equals the
    /// dense DFT up to FFT round-off (~ULP) — matching PyTorch, which is also
    /// FFT-based; the DC bin is a pure sum and stays exact. Returns bin-major
    /// `[freq_bins, frames]` (re, im) pairs in f64.
    fn stft_fft_spectrogram(
        all_frames: &[f64],
        frames: usize,
        n_fft: usize,
        freq_bins: usize,
        scale: f64,
    ) -> Vec<(f64, f64)> {
        // Each frame is a REAL signal. For even n_fft with the standard onesided
        // n_fft/2+1 bins, use the real-input FFT (an n_fft/2-point complex
        // transform + recombine — HALF the work of the full n_fft complex FFT),
        // hoisting the shared half-point + recombine twiddles out of the per-frame
        // loop. Matches the full-complex path within ~ULP (torch's stft is also
        // real-FFT-based). Odd n_fft / two-sided bins keep the full-complex path.
        // frankentorch-hpo6.
        let m = n_fft / 2;
        let use_real = n_fft >= 2 && n_fft.is_multiple_of(2) && freq_bins == m + 1;
        let half_tw = (use_real && m.is_power_of_two()).then(|| Self::fft_stage_twiddles(m, false));
        let recombine_tw: Vec<(f64, f64)> = if use_real {
            let two_pi = 2.0 * std::f64::consts::PI;
            (0..freq_bins)
                .map(|k| {
                    let ang = two_pi * (k as f64) / (n_fft as f64);
                    (ang.cos(), -ang.sin())
                })
                .collect()
        } else {
            Vec::new()
        };
        let full_tw =
            (!use_real && n_fft.is_power_of_two()).then(|| Self::fft_stage_twiddles(n_fft, false));
        let mut frame_major = vec![(0.0_f64, 0.0_f64); frames * freq_bins];
        let compute = |frame_idx: usize, out_row: &mut [(f64, f64)]| {
            let fbase = frame_idx * n_fft;
            if use_real {
                let (re, im) = Self::real_fft_1d_f64_with_twiddles(
                    &all_frames[fbase..fbase + n_fft],
                    half_tw.as_deref(),
                    &recombine_tw,
                );
                for (k, slot) in out_row.iter_mut().enumerate() {
                    *slot = (re[k] * scale, im[k] * scale);
                }
            } else {
                let mut re: Vec<f64> = all_frames[fbase..fbase + n_fft].to_vec();
                let mut im = vec![0.0_f64; n_fft];
                Self::dft_inplace_1d_with_stage_twiddles(
                    &mut re,
                    &mut im,
                    false,
                    full_tw.as_deref(),
                );
                for (k, slot) in out_row.iter_mut().enumerate() {
                    *slot = (re[k] * scale, im[k] * scale);
                }
            }
        };
        if frames >= 2 && frames * freq_bins >= PARALLEL_ELEMENTWISE_MIN {
            use rayon::prelude::*;
            frame_major
                .par_chunks_mut(freq_bins)
                .enumerate()
                .for_each(|(frame_idx, row)| compute(frame_idx, row));
        } else {
            frame_major
                .chunks_mut(freq_bins)
                .enumerate()
                .for_each(|(frame_idx, row)| compute(frame_idx, row));
        }
        // Transpose frame-major [frames, freq_bins] -> bin-major [freq_bins, frames].
        let mut bin_major = vec![(0.0_f64, 0.0_f64); freq_bins * frames];
        for frame_idx in 0..frames {
            let fb = frame_idx * freq_bins;
            for k in 0..freq_bins {
                bin_major[k * frames + frame_idx] = frame_major[fb + k];
            }
        }
        bin_major
    }

    /// Short-time Fourier transform for 1-D real signals.
    pub fn tensor_stft(
        &mut self,
        input: TensorNodeId,
        n_fft: usize,
        options: StftOptions,
    ) -> Result<TensorNodeId, AutogradError> {
        if n_fft == 0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "stft: n_fft must be > 0",
                },
            )));
        }
        if self.tensor_tape.tensor_requires_grad(input)? {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "stft: autograd is not supported",
                },
            )));
        }

        let input_tensor = self.tensor_tape.tensor(input)?;
        let input_meta = input_tensor.meta().clone();
        if input_meta.shape().len() != 1 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "stft: only 1-D real input is currently supported",
                },
            )));
        }

        let hop_length = options.hop_length.unwrap_or(n_fft / 4).max(1);
        let win_length = options.win_length.unwrap_or(n_fft);
        if win_length == 0 || win_length > n_fft {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "stft: win_length must be in 1..=n_fft",
                },
            )));
        }

        let (signal, base_dtype) = match input_tensor.typed_storage() {
            TensorStorage::F32(values) => (
                values.iter().map(|&v| f64::from(v)).collect::<Vec<_>>(),
                DType::F32,
            ),
            TensorStorage::F64(values) => (values.as_ref().clone(), DType::F64),
            TensorStorage::F64Inline4(values) => (values.to_vec(), DType::F64),
            _ => {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "stft: input must be float32 or float64",
                    },
                )));
            }
        };
        let window_values = self.stft_window_values(options.window, win_length)?;

        let pad = if options.center { n_fft / 2 } else { 0 };
        let mut padded = vec![0.0; signal.len() + 2 * pad];
        padded[pad..pad + signal.len()].copy_from_slice(&signal);
        if padded.len() < n_fft {
            padded.resize(n_fft, 0.0);
        }

        let frames = (padded.len() - n_fft) / hop_length + 1;
        let freq_bins = if options.onesided {
            n_fft / 2 + 1
        } else {
            n_fft
        };
        let scale = if options.normalized {
            1.0 / (n_fft as f64).sqrt()
        } else {
            1.0
        };
        let window_pad = (n_fft - win_length) / 2;

        match base_dtype {
            DType::F32 => {
                let mut spectrogram = vec![ft_core::Complex64::new(0.0, 0.0); freq_bins * frames];
                // Precompute the windowed frames once (cheap, serial).
                let mut all_frames = vec![0.0_f64; frames * n_fft];
                for frame_idx in 0..frames {
                    let start = frame_idx * hop_length;
                    let fbase = frame_idx * n_fft;
                    for i in 0..win_length {
                        all_frames[fbase + window_pad + i] = padded[start + i] * window_values[i];
                    }
                }
                // FFT spectrogram (bin-major) cast to single precision.
                let bin_major =
                    Self::stft_fft_spectrogram(&all_frames, frames, n_fft, freq_bins, scale);
                for (slot, &(re, im)) in spectrogram.iter_mut().zip(bin_major.iter()) {
                    *slot = ft_core::Complex64::new(re as f32, im as f32);
                }
                let out = self.tensor_tape.leaf_tensor(
                    DenseTensor::from_typed_storage(
                        TensorMeta::from_shape(
                            vec![freq_bins, frames],
                            DType::Complex64,
                            input_meta.device(),
                        ),
                        TensorStorage::Complex64(Arc::new(spectrogram)),
                    )?,
                    false,
                );
                self.runtime.ledger_mut().record(
                    EvidenceKind::Dispatch,
                    format!("stft input={} out={} n_fft={n_fft}", input.0, out.0),
                );
                Ok(out)
            }
            DType::F64 => {
                let mut spectrogram = vec![ft_core::Complex128::new(0.0, 0.0); freq_bins * frames];
                // Precompute the windowed frames once (cheap, serial).
                let mut all_frames = vec![0.0_f64; frames * n_fft];
                for frame_idx in 0..frames {
                    let start = frame_idx * hop_length;
                    let fbase = frame_idx * n_fft;
                    for i in 0..win_length {
                        all_frames[fbase + window_pad + i] = padded[start + i] * window_values[i];
                    }
                }
                // FFT spectrogram (bin-major [freq_bins, frames]).
                let bin_major =
                    Self::stft_fft_spectrogram(&all_frames, frames, n_fft, freq_bins, scale);
                for (slot, &(re, im)) in spectrogram.iter_mut().zip(bin_major.iter()) {
                    *slot = ft_core::Complex128::new(re, im);
                }
                let out = self.tensor_tape.leaf_tensor(
                    DenseTensor::from_typed_storage(
                        TensorMeta::from_shape(
                            vec![freq_bins, frames],
                            DType::Complex128,
                            input_meta.device(),
                        ),
                        TensorStorage::Complex128(Arc::new(spectrogram)),
                    )?,
                    false,
                );
                self.runtime.ledger_mut().record(
                    EvidenceKind::Dispatch,
                    format!("stft input={} out={} n_fft={n_fft}", input.0, out.0),
                );
                Ok(out)
            }
            _ => Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "stft: unsupported base dtype",
                },
            ))),
        }
    }

    /// Inverse short-time Fourier transform for 2-D complex spectrograms.
    pub fn tensor_istft(
        &mut self,
        input: TensorNodeId,
        n_fft: usize,
        options: IstftOptions,
    ) -> Result<TensorNodeId, AutogradError> {
        if n_fft == 0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "istft: n_fft must be > 0",
                },
            )));
        }
        if self.tensor_tape.tensor_requires_grad(input)? {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "istft: autograd is not supported",
                },
            )));
        }

        let input_tensor = self.tensor_tape.tensor(input)?;
        let input_meta = input_tensor.meta().clone();
        if input_meta.shape().len() != 2 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "istft: only 2-D spectrogram input [freq, frames] is currently supported",
                },
            )));
        }

        let hop_length = options.hop_length.unwrap_or(n_fft / 4).max(1);
        let win_length = options.win_length.unwrap_or(n_fft);
        if win_length == 0 || win_length > n_fft {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "istft: win_length must be in 1..=n_fft",
                },
            )));
        }
        let window_values = self.stft_window_values(options.window, win_length)?;
        let window_pad = (n_fft - win_length) / 2;

        let shape = input_meta.shape().to_vec();
        let (freq_bins, frames) = (shape[0], shape[1]);
        let expected_bins = if options.onesided {
            n_fft / 2 + 1
        } else {
            n_fft
        };
        if freq_bins != expected_bins {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "istft: spectrogram frequency dimension does not match n_fft/onesided configuration",
                },
            )));
        }

        let plan = IstftReconstructPlan {
            freq_bins,
            frames,
            n_fft,
            hop_length,
            window_values: &window_values,
            window_pad,
            center: options.center,
            normalized: options.normalized,
            onesided: options.onesided,
            length: options.length,
        };

        match input_tensor.typed_storage() {
            TensorStorage::Complex64(values) => {
                let signal = self.istft_reconstruct_f64(
                    values
                        .iter()
                        .map(|z| ft_core::Complex128::new(f64::from(z.re), f64::from(z.im)))
                        .collect(),
                    plan,
                );
                let out = self.tensor_tape.leaf_tensor(
                    DenseTensor::from_typed_storage(
                        TensorMeta::from_shape(vec![signal.len()], DType::F32, input_meta.device()),
                        TensorStorage::F32(Arc::new(
                            signal.into_iter().map(|v| v as f32).collect(),
                        )),
                    )?,
                    false,
                );
                self.runtime.ledger_mut().record(
                    EvidenceKind::Dispatch,
                    format!("istft input={} out={} n_fft={n_fft}", input.0, out.0),
                );
                Ok(out)
            }
            TensorStorage::Complex128(values) => {
                let signal = self.istft_reconstruct_f64(values.as_ref().clone(), plan);
                let out = self.tensor_tape.leaf_tensor(
                    DenseTensor::from_typed_storage(
                        TensorMeta::from_shape(vec![signal.len()], DType::F64, input_meta.device()),
                        TensorStorage::F64(Arc::new(signal)),
                    )?,
                    false,
                );
                self.runtime.ledger_mut().record(
                    EvidenceKind::Dispatch,
                    format!("istft input={} out={} n_fft={n_fft}", input.0, out.0),
                );
                Ok(out)
            }
            _ => Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "istft: input must be complex64 or complex128",
                },
            ))),
        }
    }

    /// Create mel-scale filterbank matrix.
    ///
    /// Generates triangular filterbanks for computing mel spectrograms.
    ///
    /// Args:
    /// - n_mels: number of mel filterbanks
    /// - n_fft: FFT size (filterbank has n_fft/2 + 1 bins)
    /// - sample_rate: audio sample rate in Hz
    /// - f_min: minimum frequency in Hz (default 0)
    /// - f_max: maximum frequency in Hz (default sample_rate/2)
    ///
    /// Returns: [n_mels, n_fft/2 + 1] filterbank matrix
    pub fn mel_filterbank(
        &mut self,
        n_mels: usize,
        n_fft: usize,
        sample_rate: f64,
        f_min: f64,
        f_max: Option<f64>,
    ) -> Result<TensorNodeId, AutogradError> {
        let f_max = f_max.unwrap_or(sample_rate / 2.0);
        let n_freqs = n_fft / 2 + 1;
        let hz_to_mel = |hz: f64| 2595.0 * (1.0 + hz / 700.0).log10();
        let mel_to_hz = |mel: f64| 700.0 * (10.0_f64.powf(mel / 2595.0) - 1.0);
        let mel_min = hz_to_mel(f_min);
        let mel_max = hz_to_mel(f_max);
        let mel_points: Vec<f64> = (0..=n_mels + 1)
            .map(|i| mel_to_hz(mel_min + (mel_max - mel_min) * i as f64 / (n_mels + 1) as f64))
            .collect();
        let freq_bins: Vec<f64> = (0..n_freqs)
            .map(|i| i as f64 * sample_rate / n_fft as f64)
            .collect();
        let mut filterbank = vec![0.0; n_mels * n_freqs];
        for m in 0..n_mels {
            let f_left = mel_points[m];
            let f_center = mel_points[m + 1];
            let f_right = mel_points[m + 2];
            for (k, &freq) in freq_bins.iter().enumerate() {
                if freq >= f_left && freq <= f_center {
                    filterbank[m * n_freqs + k] = (freq - f_left) / (f_center - f_left).max(1e-10);
                } else if freq > f_center && freq <= f_right {
                    filterbank[m * n_freqs + k] =
                        (f_right - freq) / (f_right - f_center).max(1e-10);
                }
            }
        }
        self.tensor_variable(filterbank, vec![n_mels, n_freqs], false)
    }

    /// Compute mel spectrogram from power spectrogram.
    ///
    /// Args:
    /// - spectrogram: [freq_bins, frames] power spectrogram (from STFT magnitude squared)
    /// - mel_filterbank: [n_mels, freq_bins] mel filterbank matrix
    ///
    /// Returns: [n_mels, frames] mel spectrogram
    pub fn melspectrogram(
        &mut self,
        spectrogram: TensorNodeId,
        mel_filterbank: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let spec_shape = self.tensor_shape(spectrogram)?;
        let fb_shape = self.tensor_shape(mel_filterbank)?;
        if spec_shape.len() != 2 || fb_shape.len() != 2 {
            return Err(Self::incompatible_tensor_args(
                "melspectrogram: spectrogram and filterbank must be 2D",
            ));
        }
        if spec_shape[0] != fb_shape[1] {
            return Err(Self::incompatible_tensor_args(
                "melspectrogram: spectrogram freq bins must match filterbank columns",
            ));
        }
        self.tensor_matmul(mel_filterbank, spectrogram)
    }

    /// Convert amplitude/power to decibels.
    ///
    /// Computes: 10 * log10(x + amin) - ref_db
    ///
    /// Args:
    /// - x: input tensor (amplitude or power values)
    /// - amin: minimum amplitude to prevent log(0) (default 1e-10)
    /// - top_db: threshold maximum dynamic range (optional)
    ///
    /// Returns: tensor in decibels
    pub fn amplitude_to_db(
        &mut self,
        x: TensorNodeId,
        amin: f64,
        top_db: Option<f64>,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(x)?;
        let amin_t = self.full(shape.clone(), amin, false)?;
        let x_clamped = self.tensor_maximum(x, amin_t)?;
        let log_x = self.tensor_log10(x_clamped)?;
        let ten = self.full(shape.clone(), 10.0, false)?;
        let db = self.tensor_mul(ten, log_x)?;
        if let Some(top) = top_db {
            let db_vals = self.tensor_values(db)?;
            let max_val = db_vals.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
            let threshold = max_val - top;
            let thresh_t = self.full(shape, threshold, false)?;
            self.tensor_maximum(db, thresh_t)
        } else {
            Ok(db)
        }
    }

    /// Compute Mel-frequency cepstral coefficients (MFCCs).
    ///
    /// Args:
    /// - mel_spec: [n_mels, frames] mel spectrogram (log-scaled recommended)
    /// - n_mfcc: number of MFCCs to return
    ///
    /// Returns: [n_mfcc, frames] MFCC features
    pub fn mfcc(
        &mut self,
        mel_spec: TensorNodeId,
        n_mfcc: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(mel_spec)?;
        if shape.len() != 2 {
            return Err(Self::incompatible_tensor_args("mfcc: mel_spec must be 2D"));
        }
        let n_mels = shape[0];
        let _frames = shape[1];
        if n_mfcc > n_mels {
            return Err(Self::incompatible_tensor_args(
                "mfcc: n_mfcc must be <= n_mels",
            ));
        }
        let mut dct_matrix = vec![0.0; n_mfcc * n_mels];
        for (k, row) in dct_matrix.chunks_mut(n_mels).enumerate().take(n_mfcc) {
            for (n, value) in row.iter_mut().enumerate() {
                let angle = std::f64::consts::PI * k as f64 * (n as f64 + 0.5) / n_mels as f64;
                *value = angle.cos() * (2.0 / n_mels as f64).sqrt();
            }
        }
        if n_mfcc > 0 {
            for value in dct_matrix.iter_mut().take(n_mels) {
                *value *= (1.0 / 2.0_f64).sqrt();
            }
        }
        let dct = self.tensor_variable(dct_matrix, vec![n_mfcc, n_mels], false)?;
        self.tensor_matmul(dct, mel_spec)
    }

    /// Compute spectrogram magnitude from complex STFT output.
    ///
    /// Args:
    /// - stft_complex: complex-valued STFT output [freq, frames] (complex64/128)
    /// - power: exponent for magnitude (1.0 = amplitude, 2.0 = power)
    ///
    /// Returns: [freq, frames] magnitude spectrogram
    pub fn spectrogram_magnitude(
        &mut self,
        stft_complex: TensorNodeId,
        power: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let abs = self.tensor_abs(stft_complex)?;
        if (power - 1.0).abs() < 1e-10 {
            Ok(abs)
        } else if (power - 2.0).abs() < 1e-10 {
            self.tensor_mul(abs, abs)
        } else {
            let power_t = self.full(self.tensor_shape(abs)?, power, false)?;
            self.tensor_pow_tensor(abs, power_t)
        }
    }

    pub fn zeros_f32(
        &mut self,
        shape: Vec<usize>,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        let numel =
            Self::checked_shape_numel(&shape, "tensor factory shape volume overflow in zeros_f32")?;
        self.tensor_tape
            .leaf_f32(vec![0.0f32; numel], shape, requires_grad)
    }

    pub fn ones_f32(
        &mut self,
        shape: Vec<usize>,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        let numel =
            Self::checked_shape_numel(&shape, "tensor factory shape volume overflow in ones_f32")?;
        self.tensor_tape
            .leaf_f32(vec![1.0f32; numel], shape, requires_grad)
    }

    pub fn randn_f32(
        &mut self,
        shape: Vec<usize>,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        let numel =
            Self::checked_shape_numel(&shape, "tensor factory shape volume overflow in randn_f32")?;
        let values: Vec<f32> = (0..numel).map(|_| self.rng.next_normal() as f32).collect();
        self.tensor_tape.leaf_f32(values, shape, requires_grad)
    }

