    /// Create a tensor filled with normally distributed random values.
    ///
    /// Equivalent to `torch.normal(mean, std, size)`.
    /// Samples from N(mean, std²).
    pub fn tensor_normal(
        &mut self,
        mean: f64,
        std: f64,
        shape: Vec<usize>,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        if std < 0.0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "normal: std must be non-negative",
                },
            )));
        }
        let numel: usize = shape.iter().product();
        let values = self.rng.next_normal_transformed(numel, |n| mean + std * n);
        self.tensor_variable(values, shape, requires_grad)
    }

    /// Create a tensor filled with uniformly distributed random values.
    ///
    /// Equivalent to `torch.empty(size).uniform_(from, to)` or similar.
    /// Samples from U(from, to).
    pub fn tensor_uniform(
        &mut self,
        from: f64,
        to: f64,
        shape: Vec<usize>,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        if from >= to {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "uniform: 'from' must be less than 'to'",
                },
            )));
        }
        let numel: usize = shape.iter().product();
        let range = to - from;
        let values: Vec<f64> = (0..numel)
            .map(|_| from + range * self.rng.next_f64())
            .collect();
        self.tensor_variable(values, shape, requires_grad)
    }

    /// Create a tensor filled with exponentially distributed random values.
    ///
    /// Equivalent to `torch.empty(size).exponential_(lambd)`.
    /// Samples from Exp(lambda) with PDF: lambda * exp(-lambda * x).
    pub fn tensor_exponential(
        &mut self,
        lambd: f64,
        shape: Vec<usize>,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        if lambd <= 0.0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "exponential: lambda must be positive",
                },
            )));
        }
        let numel: usize = shape.iter().product();
        let values = self
            .rng
            .next_uniform_transformed(numel, |u| -u.ln() / lambd);
        self.tensor_variable(values, shape, requires_grad)
    }

    /// Create a tensor filled with geometrically distributed random values.
    ///
    /// Equivalent to `torch.empty(size).geometric_(p)`.
    /// Samples from Geom(p): number of Bernoulli trials until first success.
    pub fn tensor_geometric(
        &mut self,
        p: f64,
        shape: Vec<usize>,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        if p <= 0.0 || p > 1.0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "geometric: p must be in (0, 1]",
                },
            )));
        }
        let numel: usize = shape.iter().product();
        let log_1_minus_p = (1.0 - p).ln();
        // Inverse CDF: ceil(ln(U) / ln(1-p))
        let values = self
            .rng
            .next_uniform_transformed(numel, |u| (u.ln() / log_1_minus_p).ceil());
        self.tensor_variable(values, shape, requires_grad)
    }

    /// Create a tensor filled with log-normally distributed random values.
    ///
    /// Equivalent to `torch.empty(size).log_normal_(mean, std)`.
    /// Samples from LogNormal(mean, std): exp(N(mean, std²)).
    pub fn tensor_log_normal(
        &mut self,
        mean: f64,
        std: f64,
        shape: Vec<usize>,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        if std < 0.0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "log_normal: std must be non-negative",
                },
            )));
        }
        let numel: usize = shape.iter().product();
        let values = self
            .rng
            .next_normal_transformed(numel, |n| (mean + std * n).exp());
        self.tensor_variable(values, shape, requires_grad)
    }

    /// Create a tensor filled with Cauchy-distributed random values.
    ///
    /// Equivalent to `torch.empty(size).cauchy_(median, sigma)`.
    /// Samples from Cauchy(median, sigma).
    pub fn tensor_cauchy(
        &mut self,
        median: f64,
        sigma: f64,
        shape: Vec<usize>,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        if sigma <= 0.0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "cauchy: sigma must be positive",
                },
            )));
        }
        let numel: usize = shape.iter().product();
        // Inverse CDF: median + sigma * tan(pi * (U - 0.5))
        let values = self.rng.next_uniform_transformed(numel, |u| {
            median + sigma * (std::f64::consts::PI * (u - 0.5)).tan()
        });
        self.tensor_variable(values, shape, requires_grad)
    }

    /// Create a tensor filled with Gumbel-distributed random values.
    ///
    /// Equivalent to `torch.empty(size).gumbel_(mu, beta)` (beta is scale).
    /// Samples from Gumbel(mu, beta).
    pub fn tensor_gumbel(
        &mut self,
        mu: f64,
        beta: f64,
        shape: Vec<usize>,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        if beta <= 0.0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "gumbel: beta must be positive",
                },
            )));
        }
        let numel: usize = shape.iter().product();
        // Inverse CDF: mu - beta * ln(-ln(U))
        let values = self
            .rng
            .next_uniform_transformed(numel, |u| mu - beta * (-u.ln()).ln());
        self.tensor_variable(values, shape, requires_grad)
    }

    /// Create a tensor filled with Laplace-distributed random values.
    ///
    /// Samples from Laplace(loc, scale) with PDF: exp(-|x-loc|/scale) / (2*scale).
    pub fn tensor_laplace(
        &mut self,
        loc: f64,
        scale: f64,
        shape: Vec<usize>,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        if scale <= 0.0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "laplace: scale must be positive",
                },
            )));
        }
        let numel: usize = shape.iter().product();
        // Inverse CDF: loc - scale * sign(U-0.5) * ln(1 - 2|U-0.5|)
        let values = self.rng.next_uniform_transformed(numel, |u| {
            let u = u - 0.5;
            loc - scale * u.signum() * (1.0 - 2.0 * u.abs()).ln()
        });
        self.tensor_variable(values, shape, requires_grad)
    }

    /// Create a tensor filled with Weibull-distributed random values.
    ///
    /// Samples from Weibull(scale, concentration) with scale λ and shape k.
    pub fn tensor_weibull(
        &mut self,
        scale: f64,
        concentration: f64,
        shape: Vec<usize>,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        if scale <= 0.0 || concentration <= 0.0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "weibull: scale and concentration must be positive",
                },
            )));
        }
        let numel: usize = shape.iter().product();
        // Inverse CDF: scale * (-ln(1-U))^(1/k)
        let values = self.rng.next_uniform_transformed(numel, |u| {
            scale * (-((1.0 - u).ln())).powf(1.0 / concentration)
        });
        self.tensor_variable(values, shape, requires_grad)
    }

    /// Create a tensor filled with logistic-distributed random values.
    ///
    /// Samples from Logistic(loc, scale).
    pub fn tensor_logistic(
        &mut self,
        loc: f64,
        scale: f64,
        shape: Vec<usize>,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        if scale <= 0.0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "logistic: scale must be positive",
                },
            )));
        }
        let numel: usize = shape.iter().product();
        // Inverse CDF: loc + scale * ln(U / (1-U))
        let values = self
            .rng
            .next_uniform_transformed(numel, |u| loc + scale * (u / (1.0 - u)).ln());
        self.tensor_variable(values, shape, requires_grad)
    }

    /// Create a tensor filled with triangular-distributed random values.
    ///
    /// Samples from Triangular(low, high, mode).
    pub fn tensor_triangular(
        &mut self,
        low: f64,
        high: f64,
        mode: f64,
        shape: Vec<usize>,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        if low >= high {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "triangular: low must be less than high",
                },
            )));
        }
        if mode < low || mode > high {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "triangular: mode must be between low and high",
                },
            )));
        }
        let numel: usize = shape.iter().product();
        let fc = (mode - low) / (high - low);
        let values: Vec<f64> = (0..numel)
            .map(|_| {
                let u = self.rng.next_f64();
                if u < fc {
                    low + ((high - low) * (mode - low) * u).sqrt()
                } else {
                    high - ((high - low) * (high - mode) * (1.0 - u)).sqrt()
                }
            })
            .collect();
        self.tensor_variable(values, shape, requires_grad)
    }

    /// Create a tensor filled with Pareto-distributed random values.
    ///
    /// Samples from Pareto(scale, alpha) with x_m = scale and shape α.
    pub fn tensor_pareto(
        &mut self,
        scale: f64,
        alpha: f64,
        shape: Vec<usize>,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        if scale <= 0.0 || alpha <= 0.0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "pareto: scale and alpha must be positive",
                },
            )));
        }
        let numel: usize = shape.iter().product();
        let values: Vec<f64> = (0..numel)
            .map(|_| {
                // Inverse CDF: scale / (1-U)^(1/alpha)
                let u = self.rng.next_f64();
                scale / (1.0 - u).powf(1.0 / alpha)
            })
            .collect();
        self.tensor_variable(values, shape, requires_grad)
    }

    /// Create a tensor filled with half-normal distributed random values.
    ///
    /// Samples from HalfNormal(scale): |N(0, scale²)|.
    pub fn tensor_half_normal(
        &mut self,
        scale: f64,
        shape: Vec<usize>,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        if scale <= 0.0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "half_normal: scale must be positive",
                },
            )));
        }
        let numel: usize = shape.iter().product();
        let values = self
            .rng
            .next_normal_transformed(numel, |n| (scale * n).abs());
        self.tensor_variable(values, shape, requires_grad)
    }

    /// Create a tensor filled with half-Cauchy distributed random values.
    ///
    /// Samples from HalfCauchy(scale): |Cauchy(0, scale)|.
    pub fn tensor_half_cauchy(
        &mut self,
        scale: f64,
        shape: Vec<usize>,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        if scale <= 0.0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "half_cauchy: scale must be positive",
                },
            )));
        }
        let numel: usize = shape.iter().product();
        let values: Vec<f64> = (0..numel)
            .map(|_| {
                let u = self.rng.next_f64();
                (scale * (std::f64::consts::PI * (u - 0.5)).tan()).abs()
            })
            .collect();
        self.tensor_variable(values, shape, requires_grad)
    }

    /// Create a tensor filled with gamma-distributed random values.
    ///
    /// Samples from Gamma(concentration, rate) using Marsaglia-Tsang's method.
    /// Note: rate = 1/scale (PyTorch uses concentration/rate parameterization).
    pub fn tensor_gamma(
        &mut self,
        concentration: f64,
        rate: f64,
        shape: Vec<usize>,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        if concentration <= 0.0 || rate <= 0.0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "gamma: concentration and rate must be positive",
                },
            )));
        }
        let numel: usize = shape.iter().product();
        let values = self
            .rng
            .substream_sample(numel, |_, r| r.next_gamma(concentration) / rate);
        self.tensor_variable(values, shape, requires_grad)
    }

    /// Create a tensor filled with beta-distributed random values.
    ///
    /// Samples from Beta(concentration1, concentration0) using gamma samples.
    pub fn tensor_beta(
        &mut self,
        concentration1: f64,
        concentration0: f64,
        shape: Vec<usize>,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        if concentration1 <= 0.0 || concentration0 <= 0.0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "beta: both concentrations must be positive",
                },
            )));
        }
        let numel: usize = shape.iter().product();
        let values = self.rng.substream_sample(numel, |_, r| {
            let x = r.next_gamma(concentration1);
            let y = r.next_gamma(concentration0);
            x / (x + y)
        });
        self.tensor_variable(values, shape, requires_grad)
    }

    /// Create a tensor filled with chi-squared distributed random values.
    ///
    /// Samples from Chi2(df) = Gamma(df/2, 0.5).
    pub fn tensor_chi2(
        &mut self,
        df: f64,
        shape: Vec<usize>,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        if df <= 0.0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "chi2: degrees of freedom must be positive",
                },
            )));
        }
        self.tensor_gamma(df / 2.0, 0.5, shape, requires_grad)
    }

    /// Create a tensor filled with Student's t-distributed random values.
    ///
    /// Samples from StudentT(df) using Z / sqrt(V/df) where Z ~ N(0,1), V ~ Chi2(df).
    pub fn tensor_studentt(
        &mut self,
        df: f64,
        shape: Vec<usize>,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        if df <= 0.0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "studentt: degrees of freedom must be positive",
                },
            )));
        }
        let numel: usize = shape.iter().product();
        let values = self.rng.substream_sample(numel, |_, r| {
            let z = r.next_normal();
            let v = r.next_gamma(df / 2.0) * 2.0; // Chi2(df)
            z / (v / df).sqrt()
        });
        self.tensor_variable(values, shape, requires_grad)
    }

    /// Create a tensor filled with binomial distributed random values.
    ///
    /// Samples from Binomial(n, p) - number of successes in n trials with probability p.
    pub fn tensor_binomial(
        &mut self,
        n: u64,
        p: f64,
        shape: Vec<usize>,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        if !(0.0..=1.0).contains(&p) {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "binomial: p must be in [0, 1]",
                },
            )));
        }
        let numel: usize = shape.iter().product();
        let values = self.rng.substream_sample(numel, |_, r| {
            let mut successes = 0u64;
            for _ in 0..n {
                if r.next_f64() < p {
                    successes += 1;
                }
            }
            successes as f64
        });
        self.tensor_variable(values, shape, requires_grad)
    }

    /// Create a tensor filled with negative binomial distributed random values.
    ///
    /// Samples from NegativeBinomial(r, p) - number of failures before r successes.
    pub fn tensor_negative_binomial(
        &mut self,
        r: f64,
        p: f64,
        shape: Vec<usize>,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        if r <= 0.0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "negative_binomial: r must be positive",
                },
            )));
        }
        if !(0.0..=1.0).contains(&p) {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "negative_binomial: p must be in [0, 1]",
                },
            )));
        }
        let numel: usize = shape.iter().product();
        let values = self.rng.substream_sample(numel, |_, rng| {
            // NegBin(r,p) can be generated as Poisson(Gamma(r, p/(1-p)))
            let lambda = rng.next_gamma(r) * p / (1.0 - p + 1e-10);
            // Poisson sampling
            let l = (-lambda).exp();
            let mut k = 0u64;
            let mut pp = 1.0;
            loop {
                k += 1;
                pp *= rng.next_f64();
                if pp <= l {
                    break;
                }
            }
            (k - 1) as f64
        });
        self.tensor_variable(values, shape, requires_grad)
    }

    /// Create a tensor filled with Dirichlet distributed random values.
    ///
    /// Samples from Dir(alpha). The output shape is `shape + [len(alpha)]`.
    pub fn tensor_dirichlet(
        &mut self,
        alpha: &[f64],
        shape: Vec<usize>,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        if alpha.is_empty() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "dirichlet: alpha must not be empty",
                },
            )));
        }
        for &a in alpha {
            if a <= 0.0 {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "dirichlet: all alpha values must be positive",
                    },
                )));
            }
        }
        let k = alpha.len();
        let numel: usize = shape.iter().product();
        // Per-row independent sub-stream (see `substream_sample`): each of the `numel` rows
        // draws its own seed from the parent stream (advancing it by exactly `numel`), then
        // samples K gammas and normalizes from that seed's sub-stream. Because each row
        // depends only on its seed, the map is order-independent and the serial/parallel
        // branches are bit-identical. frankentorch-dist-par.
        let seeds: Vec<u64> = (0..numel).map(|_| self.rng.next_u64()).collect();
        let make_row = |sd: u64| -> Vec<f64> {
            let mut r = Xoshiro256PlusPlus::new(sd);
            let gammas: Vec<f64> = alpha.iter().map(|&a| r.next_gamma(a)).collect();
            let sum: f64 = gammas.iter().sum();
            gammas.into_iter().map(|g| g / sum).collect()
        };
        let values: Vec<f64> = if numel >= (1 << 14) {
            use rayon::prelude::*;
            seeds.par_iter().flat_map_iter(|&sd| make_row(sd)).collect()
        } else {
            seeds.iter().flat_map(|&sd| make_row(sd)).collect()
        };
        let mut full_shape = shape;
        full_shape.push(k);
        self.tensor_variable(values, full_shape, requires_grad)
    }

    /// Create a tensor filled with Fisher-Snedecor (F) distributed random values.
    ///
    /// Samples from F(df1, df2) = (Chi2(df1)/df1) / (Chi2(df2)/df2).
    pub fn tensor_fishersnedecor(
        &mut self,
        df1: f64,
        df2: f64,
        shape: Vec<usize>,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        if df1 <= 0.0 || df2 <= 0.0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "fishersnedecor: df1 and df2 must be positive",
                },
            )));
        }
        let numel: usize = shape.iter().product();
        let values = self.rng.substream_sample(numel, |_, r| {
            let chi1 = r.next_gamma(df1 / 2.0) * 2.0;
            let chi2 = r.next_gamma(df2 / 2.0) * 2.0;
            (chi1 / df1) / (chi2 / df2)
        });
        self.tensor_variable(values, shape, requires_grad)
    }

    /// Create a tensor filled with von Mises distributed random values.
    ///
    /// Samples from vonMises(loc, concentration) on the circle.
    /// Uses rejection sampling for concentration > 0.
    pub fn tensor_von_mises(
        &mut self,
        loc: f64,
        concentration: f64,
        shape: Vec<usize>,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        if concentration < 0.0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "von_mises: concentration must be non-negative",
                },
            )));
        }
        let numel: usize = shape.iter().product();
        let values = self.rng.substream_sample(numel, |_, rng| {
            if concentration == 0.0 {
                // Uniform on circle
                return loc + 2.0 * std::f64::consts::PI * rng.next_f64() - std::f64::consts::PI;
            }
            // Best-Fisher algorithm for von Mises sampling
            let tau = 1.0 + (1.0 + 4.0 * concentration * concentration).sqrt();
            let rho = (tau - (2.0 * tau).sqrt()) / (2.0 * concentration);
            let r = (1.0 + rho * rho) / (2.0 * rho);
            loop {
                let u1 = rng.next_f64();
                let z = (std::f64::consts::PI * u1).cos();
                let f = (1.0 + r * z) / (r + z);
                let c = concentration * (r - f);
                let u2 = rng.next_f64();
                if u2 < c * (2.0 - c) || u2 <= c * (-c).exp() {
                    let u3 = rng.next_f64();
                    let sign = if u3 < 0.5 { -1.0 } else { 1.0 };
                    return loc + sign * f.acos();
                }
            }
        });
        self.tensor_variable(values, shape, requires_grad)
    }

    /// Alias for `randint`. Equivalent to `torch.randint(low, high, shape)`.
    pub fn tensor_randint(
        &mut self,
        low: i64,
        high: i64,
        shape: Vec<usize>,
    ) -> Result<TensorNodeId, AutogradError> {
        self.randint(low, high, shape)
    }

    /// Create a tensor with same shape as input, filled with random integers.
    ///
    /// Equivalent to `torch.randint_like(input, low, high)`.
    pub fn tensor_randint_like(
        &mut self,
        input: TensorNodeId,
        low: i64,
        high: i64,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        self.randint(low, high, shape)
    }

    /// Create a random permutation of integers from 0 to n-1.
    ///
    /// Equivalent to `torch.randperm(n)`.
    pub fn tensor_randperm(&mut self, n: usize) -> Result<TensorNodeId, AutogradError> {
        let mut indices: Vec<f64> = (0..n).map(|i| i as f64).collect();
        // Fisher-Yates shuffle
        for i in (1..n).rev() {
            let j = (self.rng.next_f64() * (i + 1) as f64) as usize;
            indices.swap(i, j);
        }
        self.tensor_variable(indices, vec![n], false)
    }

    /// Sample from a multinomial distribution.
    ///
    /// Equivalent to `torch.multinomial(input, num_samples, replacement)`.
    /// Input is 1D tensor of probabilities (non-negative, need not sum to 1).
    /// Returns tensor of sampled indices.
    pub fn tensor_multinomial(
        &mut self,
        input: TensorNodeId,
        num_samples: usize,
        replacement: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        if shape.len() != 1 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "multinomial: input must be 1D",
                },
            )));
        }
        let n_classes = shape[0];
        if !replacement && num_samples > n_classes {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "multinomial: cannot sample more than n_classes without replacement",
                },
            )));
        }
        let weights = self.tensor_values(input)?;
        let total: f64 = weights.iter().sum();
        if total <= 0.0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "multinomial: sum of probabilities must be positive",
                },
            )));
        }
        let probs: Vec<f64> = weights.iter().map(|&w| w / total).collect();
        let mut cdf: Vec<f64> = Vec::with_capacity(n_classes);
        let mut cum = 0.0;
        for &p in &probs {
            cum += p;
            cdf.push(cum);
        }
        let mut samples = Vec::with_capacity(num_samples);
        let mut available = vec![true; n_classes];
        for _ in 0..num_samples {
            let r = self.rng.next_f64();
            let mut idx = 0;
            for (i, &c) in cdf.iter().enumerate() {
                if available[i] && r < c {
                    idx = i;
                    break;
                }
                if i == n_classes - 1 {
                    idx = i;
                }
            }
            // For without replacement, skip unavailable
            if !replacement {
                while !available[idx] {
                    idx = (idx + 1) % n_classes;
                }
                available[idx] = false;
            }
            samples.push(idx as f64);
        }
        self.tensor_variable(samples, vec![num_samples], false)
    }

    /// Alias for `arange`. Equivalent to `torch.arange(start, end, step)`.
    pub fn tensor_arange(
        &mut self,
        start: f64,
        end: f64,
        step: f64,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        self.arange(start, end, step, requires_grad)
    }

    /// Alias for `linspace`. Equivalent to `torch.linspace(start, end, steps)`.
    pub fn tensor_linspace(
        &mut self,
        start: f64,
        end: f64,
        steps: usize,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        self.linspace(start, end, steps, requires_grad)
    }

    /// Alias for `logspace`. Equivalent to `torch.logspace(start, end, steps, base)`.
    pub fn tensor_logspace(
        &mut self,
        start: f64,
        end: f64,
        steps: usize,
        base: f64,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        self.logspace(start, end, steps, base, requires_grad)
    }

    /// Create a 2-D identity matrix.
    ///
    /// Equivalent to `torch.eye(n, m)`. Creates an n x m matrix with ones on the diagonal.
    /// If m is None, creates a square n x n identity matrix.
    pub fn tensor_eye(
        &mut self,
        n: usize,
        m: Option<usize>,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        let cols = m.unwrap_or(n);
        let mut values = vec![0.0; n * cols];
        let diag_len = n.min(cols);
        for i in 0..diag_len {
            values[i * cols + i] = 1.0;
        }
        self.tensor_variable(values, vec![n, cols], requires_grad)
    }

    pub fn tensor_new_zeros(
        &mut self,
        _source: TensorNodeId,
        shape: Vec<usize>,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        self.zeros(shape, requires_grad)
    }

    pub fn tensor_new_ones(
        &mut self,
        _source: TensorNodeId,
        shape: Vec<usize>,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        self.ones(shape, requires_grad)
    }

    pub fn tensor_new_full(
        &mut self,
        _source: TensorNodeId,
        shape: Vec<usize>,
        fill_value: f64,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        self.full(shape, fill_value, requires_grad)
    }

    pub fn tensor_new_empty(
        &mut self,
        _source: TensorNodeId,
        shape: Vec<usize>,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        self.zeros(shape, requires_grad)
    }

    pub fn arange(
        &mut self,
        start: f64,
        end: f64,
        step: f64,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        if !start.is_finite() || !end.is_finite() || !step.is_finite() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "arange: start/end/step must be finite",
                },
            )));
        }
        if step == 0.0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "arange: step must not be zero",
                },
            )));
        }
        let mut values = Vec::new();
        let mut current = start;
        if step > 0.0 {
            while current < end {
                values.push(current);
                let next = current + step;
                if next <= current {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "arange: step does not advance at current floating-point precision",
                        },
                    )));
                }
                current = next;
            }
        } else {
            while current > end {
                values.push(current);
                let next = current + step;
                if next >= current {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "arange: step does not advance at current floating-point precision",
                        },
                    )));
                }
                current = next;
            }
        }
        let n = values.len();
        self.tensor_tape.leaf(values, vec![n], requires_grad)
    }

    /// Create a 2-D identity matrix of size n x n.
    /// Square subsequent mask for transformer decoder attention.
    ///
    /// Equivalent to `torch.nn.Transformer.generate_square_subsequent_mask(sz)`.
    /// Returns a `[sz, sz]` 2-D tensor where each element above the
    /// main diagonal is `-inf` and each element on or below is `0.0`.
    /// Added to attention scores (typically after the QK^T / sqrt(d_k)
    /// scaling) before softmax so that softmax(score + mask) zeros out
    /// the future positions. Tracked under frankentorch-2heg.
    pub fn causal_mask(&mut self, size: usize) -> Result<TensorNodeId, AutogradError> {
        if size == 0 {
            return self.tensor_variable(Vec::new(), vec![0, 0], false);
        }
        let mut data = vec![0.0_f64; size * size];
        for i in 0..size {
            for j in (i + 1)..size {
                data[i * size + j] = f64::NEG_INFINITY;
            }
        }
        self.tensor_variable(data, vec![size, size], false)
    }

    pub fn eye(&mut self, n: usize, requires_grad: bool) -> Result<TensorNodeId, AutogradError> {
        let numel = Self::checked_square_numel(n, "eye shape volume overflow")?;
        let mut values = vec![0.0; numel];
        for i in 0..n {
            values[i * n + i] = 1.0;
        }
        self.tensor_tape.leaf(values, vec![n, n], requires_grad)
    }

    /// Create a diagonal matrix from a 1-D tensor, or extract the diagonal of a 2-D tensor.
    ///
    /// If input is 1-D of length n, returns a 2-D tensor of shape [n, n] with the input as diagonal.
    /// If input is 2-D of shape [m, n], returns a 1-D tensor of length min(m, n) with the diagonal.
    ///
    /// Delegates to `tensor_diag(input, 0)` for the main-diagonal case
    /// (frankentorch-rikh). The previous 1-D path materialised a full
    /// [n, n] identity matrix and did n² multiplications to place n
    /// values; `tensor_diag_embed` (called via `tensor_diag`) writes
    /// only the diagonal positions directly. The previous 2-D path
    /// composed gather + narrow + reshape; `tensor_diagonal` is a
    /// dedicated shape op. Same surface, fewer allocations, single
    /// torch-parity path.
    pub fn diag(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        self.tensor_diag(input, 0)
    }

    /// Return the upper triangular part of a 2-D tensor.
    ///
    /// Elements below the k-th diagonal are set to 0. k=0 is the main diagonal,
    /// k>0 is above, k<0 is below.
    pub fn triu(&mut self, input: TensorNodeId, k: i64) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        if shape.len() != 2 {
            // Migrate to InvalidDimension to surface actual rank +
            // expected rank (frankentorch-qaux).
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::InvalidDimension {
                    dim: shape.len(),
                    ndim: 2,
                },
            )));
        }
        let m = shape[0];
        let n = shape[1];
        let numel = m.checked_mul(n).ok_or({
            AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "triu shape volume overflow",
                },
            ))
        })?;
        // Range-derived fill (frankentorch-98kt): per row i, the
        // upper-triangle column range is [max(0, i + k), n). Skip
        // the per-cell branch and let .fill() compile to memset
        // over the contiguous slice. -O(m*n / 2) iterations + no
        // mispredicts on attention-mask shapes.
        let mut mask = vec![0.0; numel];
        for i in 0..m {
            let start_signed = i as i64 + k;
            let start = start_signed.max(0).min(n as i64) as usize;
            mask[i * n + start..i * n + n].fill(1.0);
        }
        let mask_tensor = self.tensor_variable(mask, vec![m, n], false)?;
        self.tensor_mul(input, mask_tensor)
    }

    /// Return the lower triangular part of a 2-D tensor.
    ///
    /// Elements above the k-th diagonal are set to 0. k=0 is the main diagonal.
    pub fn tril(&mut self, input: TensorNodeId, k: i64) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        if shape.len() != 2 {
            // Migrate to InvalidDimension (frankentorch-qaux).
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::InvalidDimension {
                    dim: shape.len(),
                    ndim: 2,
                },
            )));
        }
        let m = shape[0];
        let n = shape[1];
        let numel = m.checked_mul(n).ok_or({
            AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "tril shape volume overflow",
                },
            ))
        })?;
        // Range-derived fill (frankentorch-98kt): per row i, the
        // lower-triangle column range is [0, min(n, max(0, i+k+1))).
        // .fill() compiles to memset over the contiguous slice.
        let mut mask = vec![0.0; numel];
        for i in 0..m {
            let end_signed = i as i64 + k + 1;
            let end = end_signed.max(0).min(n as i64) as usize;
            mask[i * n..i * n + end].fill(1.0);
        }
        let mask_tensor = self.tensor_variable(mask, vec![m, n], false)?;
        self.tensor_mul(input, mask_tensor)
    }

    /// Return the indices of the lower triangular part of a (row, col) matrix.
    ///
    /// Equivalent to `torch.tril_indices(row, col, offset=0)`.
    /// Returns a 2-D tensor of shape `[2, N]` where row 0 contains row indices
    /// and row 1 contains column indices.
    pub fn tril_indices(
        &mut self,
        row: usize,
        col: usize,
        offset: i64,
    ) -> Result<TensorNodeId, AutogradError> {
        // Range-derived push (frankentorch-nyzz): per row i, the
        // lower-triangle column range is [0, min(col, max(0, i+offset+1))).
        // Skip the per-cell branch and pre-allocate with the
        // worst-case capacity to avoid Vec realloc churn.
        let cap = row.saturating_mul(col);
        let mut rows = Vec::with_capacity(cap);
        let mut cols = Vec::with_capacity(cap);
        for i in 0..row {
            let end_signed = (i as i64) + offset + 1;
            let end = end_signed.max(0).min(col as i64) as usize;
            for j in 0..end {
                rows.push(i as f64);
                cols.push(j as f64);
            }
        }
        let n = rows.len();
        rows.extend(cols);
        self.tensor_variable(rows, vec![2, n], false)
    }

    /// Return the indices of the upper triangular part of a (row, col) matrix.
    ///
    /// Equivalent to `torch.triu_indices(row, col, offset=0)`.
    /// Returns a 2-D tensor of shape `[2, N]` where row 0 contains row indices
    /// and row 1 contains column indices.
    pub fn triu_indices(
        &mut self,
        row: usize,
        col: usize,
        offset: i64,
    ) -> Result<TensorNodeId, AutogradError> {
        // Range-derived push (frankentorch-nyzz): per row i, the
        // upper-triangle column range is [max(0, i+offset), col).
        // Skip the per-cell branch and pre-allocate with worst-case
        // capacity.
        let cap = row.saturating_mul(col);
        let mut rows = Vec::with_capacity(cap);
        let mut cols = Vec::with_capacity(cap);
        for i in 0..row {
            let start_signed = (i as i64) + offset;
            let start = start_signed.max(0).min(col as i64) as usize;
            for j in start..col {
                rows.push(i as f64);
                cols.push(j as f64);
            }
        }
        let n = rows.len();
        rows.extend(cols);
        self.tensor_variable(rows, vec![2, n], false)
    }

    /// Return the indices of the lower triangular part of a (row, col) matrix.
    ///
    /// Alias for `tril_indices`. Equivalent to `torch.tril_indices(row, col, offset)`.
    pub fn tensor_tril_indices(
        &mut self,
        row: usize,
        col: usize,
        offset: i64,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tril_indices(row, col, offset)
    }

    /// Return the indices of the upper triangular part of a (row, col) matrix.
    ///
    /// Alias for `triu_indices`. Equivalent to `torch.triu_indices(row, col, offset)`.
    pub fn tensor_triu_indices(
        &mut self,
        row: usize,
        col: usize,
        offset: i64,
    ) -> Result<TensorNodeId, AutogradError> {
        self.triu_indices(row, col, offset)
    }

    /// Return the indices for the diagonal of an n×n matrix.
    ///
    /// Equivalent to `torch.diag_indices(n)`. Returns a tuple of two
    /// tensors (row_indices, col_indices) each of shape `[n]`.
    pub fn diag_indices(
        &mut self,
        n: usize,
    ) -> Result<(TensorNodeId, TensorNodeId), AutogradError> {
        let indices: Vec<f64> = (0..n).map(|i| i as f64).collect();
        let row_indices = self.tensor_variable(indices.clone(), vec![n], false)?;
        let col_indices = self.tensor_variable(indices, vec![n], false)?;
        Ok((row_indices, col_indices))
    }

    /// Return the indices for the diagonal of an n×n matrix.
    ///
    /// Alias for `diag_indices`. Equivalent to `torch.diag_indices(n)`.
    pub fn tensor_diag_indices(
        &mut self,
        n: usize,
    ) -> Result<(TensorNodeId, TensorNodeId), AutogradError> {
        self.diag_indices(n)
    }

    /// Create a tensor filled with uniform random values in [0, 1).
    pub fn rand(
        &mut self,
        shape: Vec<usize>,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        let numel =
            Self::checked_shape_numel(&shape, "tensor factory shape volume overflow in rand")?;
        let values: Vec<f64> = (0..numel).map(|_| self.rng.next_f64()).collect();
        self.tensor_tape.leaf(values, shape, requires_grad)
    }

    /// Create a tensor filled with standard normal random values.
    pub fn randn(
        &mut self,
        shape: Vec<usize>,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        let numel =
            Self::checked_shape_numel(&shape, "tensor factory shape volume overflow in randn")?;
        let values = self.rng.next_normal_values(numel);
        self.tensor_tape.leaf(values, shape, requires_grad)
    }

    /// Create a tensor with the same shape as `other`, filled with uniform random values in [0, 1).
    pub fn rand_like(
        &mut self,
        other: TensorNodeId,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        let meta = self.tensor_tape.tensor_meta(other)?.clone();
        let shape = meta.shape().to_vec();
        let numel =
            Self::checked_shape_numel(&shape, "tensor factory shape volume overflow in rand_like")?;
        let tensor = match meta.dtype() {
            DType::F64 => {
                let mut values = Vec::with_capacity(numel);
                for _ in 0..numel {
                    values.push(self.rng.next_f64());
                }
                DenseTensor::from_contiguous_values(values, shape, meta.device())?
            }
            DType::F32 => {
                let mut values = Vec::with_capacity(numel);
                for _ in 0..numel {
                    values.push(self.rng.next_f64() as f32);
                }
                DenseTensor::from_contiguous_values_f32(values, shape, meta.device())?
            }
            DType::F16 => {
                let mut values = Vec::with_capacity(numel);
                for _ in 0..numel {
                    values.push(Float16::from_f32(self.rng.next_f64() as f32));
                }
                DenseTensor::from_contiguous_values_f16(values, shape, meta.device())?
            }
            DType::BF16 => {
                let mut values = Vec::with_capacity(numel);
                for _ in 0..numel {
                    values.push(BFloat16::from_f32(self.rng.next_f64() as f32));
                }
                DenseTensor::from_contiguous_values_bf16(values, shape, meta.device())?
            }
            DType::Complex64 => {
                let mut values = Vec::with_capacity(numel);
                for _ in 0..numel {
                    values.push(Complex64::new(
                        self.rng.next_f64() as f32,
                        self.rng.next_f64() as f32,
                    ));
                }
                DenseTensor::from_typed_storage(
                    meta.clone(),
                    TensorStorage::Complex64(Arc::new(values)),
                )?
            }
            DType::Complex128 => {
                let mut values = Vec::with_capacity(numel);
                for _ in 0..numel {
                    values.push(Complex128::new(self.rng.next_f64(), self.rng.next_f64()));
                }
                DenseTensor::from_typed_storage(
                    meta.clone(),
                    TensorStorage::Complex128(Arc::new(values)),
                )?
            }
            _ => {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "rand_like: unsupported dtype",
                    },
                )));
            }
        };
        Ok(self.tensor_tape.leaf_tensor(tensor, requires_grad))
    }

    /// Create a tensor with the same shape as `other`, filled with standard normal random values.
    pub fn randn_like(
        &mut self,
        other: TensorNodeId,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        let meta = self.tensor_tape.tensor_meta(other)?.clone();
        let shape = meta.shape().to_vec();
        let numel = Self::checked_shape_numel(
            &shape,
            "tensor factory shape volume overflow in randn_like",
        )?;
        let tensor = match meta.dtype() {
            DType::F64 => {
                let values = self.rng.next_normal_values(numel);
                DenseTensor::from_contiguous_values(values, shape, meta.device())?
            }
            DType::F32 => {
                let mut values = Vec::with_capacity(numel);
                for _ in 0..numel {
                    values.push(self.rng.next_normal() as f32);
                }
                DenseTensor::from_contiguous_values_f32(values, shape, meta.device())?
            }
            DType::F16 => {
                let mut values = Vec::with_capacity(numel);
                for _ in 0..numel {
                    values.push(Float16::from_f32(self.rng.next_normal() as f32));
                }
                DenseTensor::from_contiguous_values_f16(values, shape, meta.device())?
            }
            DType::BF16 => {
                let mut values = Vec::with_capacity(numel);
                for _ in 0..numel {
                    values.push(BFloat16::from_f32(self.rng.next_normal() as f32));
                }
                DenseTensor::from_contiguous_values_bf16(values, shape, meta.device())?
            }
            DType::Complex64 => {
                let mut values = Vec::with_capacity(numel);
                for _ in 0..numel {
                    values.push(Complex64::new(
                        self.rng.next_normal() as f32,
                        self.rng.next_normal() as f32,
                    ));
                }
                DenseTensor::from_typed_storage(
                    meta.clone(),
                    TensorStorage::Complex64(Arc::new(values)),
                )?
            }
            DType::Complex128 => {
                let mut values = Vec::with_capacity(numel);
                for _ in 0..numel {
                    values.push(Complex128::new(
                        self.rng.next_normal(),
                        self.rng.next_normal(),
                    ));
                }
                DenseTensor::from_typed_storage(
                    meta.clone(),
                    TensorStorage::Complex128(Arc::new(values)),
                )?
            }
            _ => {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "randn_like: unsupported dtype",
                    },
                )));
            }
        };
        Ok(self.tensor_tape.leaf_tensor(tensor, requires_grad))
    }

    /// Create a tensor filled with random integers in `[low, high)`.
    ///
    /// Equivalent to `torch.randint(low, high, size)`.
    pub fn randint(
        &mut self,
        low: i64,
        high: i64,
        shape: Vec<usize>,
    ) -> Result<TensorNodeId, AutogradError> {
        if high <= low {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "randint: high must be greater than low",
                },
            )));
        }
        let numel =
            Self::checked_shape_numel(&shape, "tensor factory shape volume overflow in randint")?;
        let range = high.checked_sub(low).ok_or({
            AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "randint: high - low range overflow",
                },
            ))
        })? as f64;
        let values: Vec<f64> = (0..numel)
            .map(|_| (self.rng.next_f64() * range).floor() + low as f64)
            .collect();
        self.tensor_tape.leaf(values, shape, false)
    }

    /// Create a 1-D tensor of a random permutation of integers `[0, n)`.
    ///
    /// Equivalent to `torch.randperm(n)`.
    pub fn randperm(&mut self, n: usize) -> Result<TensorNodeId, AutogradError> {
        let mut perm: Vec<f64> = (0..n).map(|i| i as f64).collect();
        // Fisher-Yates shuffle
        for i in (1..n).rev() {
            let j = (self.rng.next_f64() * (i + 1) as f64).floor() as usize;
            let j = j.min(i); // safety clamp
            perm.swap(i, j);
        }
        self.tensor_tape.leaf(perm, vec![n], false)
    }

    /// Sample indices from a probability distribution (with or without replacement).
    ///
    /// Equivalent to `torch.multinomial(input, num_samples, replacement=False)`.
    /// `input` is a 1-D or 2-D tensor of non-negative weights (not required to sum to 1).
    /// Returns a tensor of sampled indices.
    pub fn multinomial(
        &mut self,
        input: TensorNodeId,
        num_samples: usize,
        replacement: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        let input_tensor = self.tensor_tape.tensor(input)?;
        let input_dtype = input_tensor.meta().dtype();
        if !input_dtype.is_floating_point() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "multinomial: input must be a real floating-point tensor",
                },
            )));
        }
        let vals = input_tensor
            .contiguous_values_as_f64()
            .map_err(AutogradError::DenseTensor)?;
        let shape = self.tensor_shape(input)?;

        let (batch, num_categories) = match shape.len() {
            1 => (1, shape[0]),
            2 => (shape[0], shape[1]),
            _ => {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "multinomial: input must be 1-D or 2-D",
                    },
                )));
            }
        };

        if !replacement && num_samples > num_categories {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "multinomial: num_samples exceeds num_categories without replacement",
                },
            )));
        }

        let result_len = Self::checked_mul(batch, num_samples, "multinomial output size overflow")?;
        // Bound-check the largest row base once so the per-row slicing below can't overflow.
        Self::checked_mul(batch, num_categories, "multinomial index overflow")?;

        // Per-row independent sub-stream (cf. `substream_sample`): seed each row from the
        // parent stream (advancing it by exactly `batch`, so subsequent draws stay
        // reproducible), then sample that row's `num_samples` draws from its OWN local RNG.
        // Rows are independent, so the map is order-independent -> the serial (few rows) and
        // parallel (>= threshold) branches are BIT-IDENTICAL. With replacement the weight
        // vector is constant, so its sum is hoisted out of the sample loop (the old code
        // recomputed the full O(num_categories) sum EVERY sample -> the ~14x-slower ns>1
        // pathology). torch's num_samples=1 path is itself pathologically slow (single
        // threaded), so parallelizing across rows pulls well ahead. frankentorch-dist-par.
        let seeds: Vec<u64> = (0..batch).map(|_| self.rng.next_u64()).collect();
        let sample_row = |b: usize, sd: u64| -> Result<Vec<f64>, AutogradError> {
            let base = b * num_categories;
            let weights_src = &vals[base..base + num_categories];
            let mut total = 0.0f64;
            let mut positive_count = 0usize;
            for &weight in weights_src {
                if !weight.is_finite() || weight < 0.0 {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "multinomial: weights must be finite and non-negative",
                        },
                    )));
                }
                total += weight;
                if weight > 0.0 {
                    positive_count += 1;
                }
            }
            if total <= 0.0 {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "multinomial: sum of weights must be positive",
                    },
                )));
            }
            if !replacement && num_samples > positive_count {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "multinomial: num_samples exceeds positive-weight categories without replacement",
                    },
                )));
            }
            let mut rng = Xoshiro256PlusPlus::new(sd);
            let mut out = Vec::with_capacity(num_samples);
            if replacement {
                // The distribution is fixed across draws. For a single draw, an early-break
                // linear scan over the SOURCE slice (no copy) is optimal. For many draws,
                // build the prefix-sum CDF ONCE (accumulated left-to-right, bit-identical to
                // the linear scan's running `cumulative`) and binary-search per draw ->
                // O(num_categories + num_samples*log num_categories) instead of the old
                // O(num_samples*num_categories) rescans that made ns>1 pathologically slow.
                if num_samples == 1 {
                    let r = rng.next_f64() * total;
                    let mut cumulative = 0.0;
                    let mut chosen = num_categories - 1;
                    for (j, &w) in weights_src.iter().enumerate() {
                        cumulative += w;
                        if r < cumulative {
                            chosen = j;
                            break;
                        }
                    }
                    out.push(chosen as f64);
                } else {
                    let mut cdf = Vec::with_capacity(num_categories);
                    let mut acc = 0.0;
                    for &w in weights_src {
                        acc += w;
                        cdf.push(acc);
                    }
                    for _ in 0..num_samples {
                        let r = rng.next_f64() * total;
                        // first index whose inclusive prefix sum exceeds r (== the linear
                        // scan's `r < cumulative`); clamp to the last category for r==total.
                        let chosen = cdf.partition_point(|&c| c <= r).min(num_categories - 1);
                        out.push(chosen as f64);
                    }
                }
            } else {
                // Without replacement the weights mutate between draws, so the row is
                // sequential (still parallel ACROSS rows). A copy is required to zero picks.
                let mut weights: Vec<f64> = weights_src.to_vec();
                let mut w_sum = total;
                for _ in 0..num_samples {
                    let r = rng.next_f64() * w_sum;
                    let mut cumulative = 0.0;
                    let mut chosen = num_categories - 1;
                    for (j, &w) in weights.iter().enumerate() {
                        cumulative += w;
                        if r < cumulative {
                            chosen = j;
                            break;
                        }
                    }
                    out.push(chosen as f64);
                    weights[chosen] = 0.0;
                    w_sum = weights.iter().sum();
                }
            }
            Ok(out)
        };

        const MULTINOMIAL_PAR_MIN_ROWS: usize = 8;
        let rows: Vec<Vec<f64>> = if batch >= MULTINOMIAL_PAR_MIN_ROWS {
            use rayon::prelude::*;
            seeds
                .par_iter()
                .enumerate()
                .map(|(b, &sd)| sample_row(b, sd))
                .collect::<Result<Vec<_>, _>>()?
        } else {
            seeds
                .iter()
                .enumerate()
                .map(|(b, &sd)| sample_row(b, sd))
                .collect::<Result<Vec<_>, _>>()?
        };
        let mut result = Vec::with_capacity(result_len);
        for row in rows {
            result.extend(row);
        }

        let out_shape = if shape.len() == 1 {
            vec![num_samples]
        } else {
            vec![batch, num_samples]
        };
        self.tensor_variable(result, out_shape, false)
    }

    /// Sample from a Bernoulli distribution.
    ///
    /// Equivalent to `torch.bernoulli(input)`.
    /// `input` contains probabilities in [0, 1]. Returns a tensor of the same shape
    /// with values 0.0 or 1.0 sampled from Bernoulli(p) for each element p.
    pub fn bernoulli(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        if self.tensor_requires_grad(input)? {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "bernoulli: autograd not supported (sampling is non-differentiable; use rsample-style reparameterization for diff'able sampling). Tracked under frankentorch-vugw.",
                },
            )));
        }
        let probs = self.tensor_values(input)?;
        let shape = self.tensor_shape(input)?;
        for &p in &probs {
            Self::validate_probability(p, "bernoulli: probabilities must be finite and in [0, 1]")?;
        }
        let values: Vec<f64> = probs
            .iter()
            .map(|&p| if self.rng.next_f64() < p { 1.0 } else { 0.0 })
            .collect();
        self.tensor_variable(values, shape, false)
    }

    /// Create a tensor with each element sampled from a Bernoulli distribution
    /// with the given uniform probability.
    ///
    /// Equivalent to `torch.bernoulli(torch.full(shape, p))` or using `Tensor.bernoulli_(p)`.
    pub fn bernoulli_p(
        &mut self,
        shape: Vec<usize>,
        p: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        Self::validate_probability(p, "bernoulli_p: p must be finite and in [0, 1]")?;
        let numel =
            Self::checked_shape_numel(&shape, "tensor factory shape volume overflow in bernoulli")?;
        let values: Vec<f64> = (0..numel)
            .map(|_| if self.rng.next_f64() < p { 1.0 } else { 0.0 })
            .collect();
        self.tensor_variable(values, shape, false)
    }

    /// Sample from a Poisson distribution element-wise.
    ///
    /// Equivalent to `torch.poisson(input)`.
    /// Each element of `input` is the rate parameter λ; returns integer samples
    /// (as f64) from Poisson(λ) for each element.
    pub fn poisson(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        if self.tensor_requires_grad(input)? {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "poisson: autograd not supported (sampling is non-differentiable; use rsample-style reparameterization for diff'able sampling). Tracked under frankentorch-vugw.",
                },
            )));
        }
        let rates = self.tensor_values(input)?;
        let shape = self.tensor_shape(input)?;
        for &lambda in &rates {
            Self::validate_poisson_rate(lambda)?;
        }

        // Per-element independent sub-stream (see `substream_sample`): each element's Knuth
        // rejection loop consumes a data-dependent draw count, so it can't be parallelized
        // within one shared stream; a per-element seed makes it embarrassingly parallel and
        // deterministic. torch.poisson on CPU is single-threaded.
        let values = self.rng.substream_sample(rates.len(), |i, rng| {
            let lambda = rates[i];
            if lambda == 0.0 {
                return 0.0;
            }
            // Knuth's algorithm for Poisson sampling
            let l = (-lambda).exp();
            let mut k = 0u64;
            let mut p = 1.0;
            loop {
                k += 1;
                p *= rng.next_f64();
                if p <= l {
                    break;
                }
            }
            (k - 1) as f64
        });
        self.tensor_variable(values, shape, false)
    }

    /// Create a 1-D tensor with `steps` evenly spaced values from `start` to `end` (inclusive).
    pub fn linspace(
        &mut self,
        start: f64,
        end: f64,
        steps: usize,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        let values = if steps == 0 {
            vec![]
        } else if steps == 1 {
            vec![start]
        } else {
            (0..steps)
                .map(|i| start + (end - start) * (i as f64) / ((steps - 1) as f64))
                .collect()
        };
        self.tensor_tape.leaf(values, vec![steps], requires_grad)
    }

    /// Create a 1-D tensor with `steps` logarithmically spaced values.
    ///
    /// Values are `base^linspace(start, end, steps)`.
    /// Default base is 10.0.
    pub fn logspace(
        &mut self,
        start: f64,
        end: f64,
        steps: usize,
        base: f64,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        let values = if steps == 0 {
            vec![]
        } else if steps == 1 {
            vec![base.powf(start)]
        } else {
            (0..steps)
                .map(|i| {
                    let t = start + (end - start) * (i as f64) / ((steps - 1) as f64);
                    base.powf(t)
                })
                .collect()
        };
        self.tensor_tape.leaf(values, vec![steps], requires_grad)
    }

    /// Create a 1-D tensor with geometrically spaced values.
    ///
    /// Equivalent to `numpy.geomspace(start, end, steps)`.
    /// Values are evenly spaced on a log scale (geometric progression).
    pub fn geomspace(
        &mut self,
        start: f64,
        end: f64,
        steps: usize,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        if start == 0.0 || end == 0.0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "geomspace: start and end must be non-zero",
                },
            )));
        }
        if (start < 0.0) != (end < 0.0) {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "geomspace: start and end must have the same sign",
                },
            )));
        }
        let values = if steps == 0 {
            vec![]
        } else if steps == 1 {
            vec![start]
        } else {
            let ratio = (end / start).powf(1.0 / (steps - 1) as f64);
            (0..steps).map(|i| start * ratio.powi(i as i32)).collect()
        };
        self.tensor_tape.leaf(values, vec![steps], requires_grad)
    }

    /// Create a tensor without initializing values (filled with zeros in Rust).
    ///
    /// In Rust, memory is always initialized, so `empty` produces zeros.
    /// This is primarily for API compatibility with PyTorch.
    pub fn empty(
        &mut self,
        shape: Vec<usize>,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        let numel =
            Self::checked_shape_numel(&shape, "tensor factory shape volume overflow in empty")?;
        self.tensor_tape
            .leaf(vec![0.0; numel], shape, requires_grad)
    }

    /// Create an uninitialized tensor with the same shape as `other`.
    ///
    /// In Rust, this produces zeros (see `empty`).
    pub fn empty_like(
        &mut self,
        other: TensorNodeId,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        self.full_like(other, 0.0, requires_grad)
    }

    /// Create a tensor with the same shape as `other`, filled with `fill_value`.
    pub fn full_like(
        &mut self,
        other: TensorNodeId,
        fill_value: f64,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        let meta = self.tensor_tape.tensor_meta(other)?.clone();
        let shape = meta.shape().to_vec();
        let numel =
            Self::checked_shape_numel(&shape, "tensor factory shape volume overflow in full_like")?;
        let tensor = match meta.dtype() {
            DType::F64 => {
                DenseTensor::from_contiguous_values(vec![fill_value; numel], shape, meta.device())?
            }
            DType::F32 => DenseTensor::from_contiguous_values_f32(
                vec![fill_value as f32; numel],
                shape,
                meta.device(),
            )?,
            DType::F16 => {
                let value = Float16::from_f32(fill_value as f32);
                DenseTensor::from_contiguous_values_f16(vec![value; numel], shape, meta.device())?
            }
            DType::BF16 => {
                let value = BFloat16::from_f32(fill_value as f32);
                DenseTensor::from_contiguous_values_bf16(vec![value; numel], shape, meta.device())?
            }
            DType::Complex64 => {
                let value = Complex64::new(fill_value as f32, 0.0);
                DenseTensor::from_typed_storage(
                    meta.clone(),
                    TensorStorage::Complex64(Arc::new(vec![value; numel])),
                )?
            }
            DType::Complex128 => {
                let value = Complex128::new(fill_value, 0.0);
                DenseTensor::from_typed_storage(
                    meta.clone(),
                    TensorStorage::Complex128(Arc::new(vec![value; numel])),
                )?
            }
            _ => {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "full_like: unsupported dtype",
                    },
                )));
            }
        };
        Ok(self.tensor_tape.leaf_tensor(tensor, requires_grad))
    }

    /// Create a tensor of zeros with the same shape as `other`.
    pub fn zeros_like(
        &mut self,
        other: TensorNodeId,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        self.full_like(other, 0.0, requires_grad)
    }

    /// Create a tensor of ones with the same shape as `other`.
    pub fn ones_like(
        &mut self,
        other: TensorNodeId,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        self.full_like(other, 1.0, requires_grad)
    }

    /// Reverse a tensor along the specified dimensions.
    ///
    /// Equivalent to PyTorch's `torch.flip(input, dims)`.
    pub fn tensor_flip(
        &mut self,
        input: TensorNodeId,
        dims: &[usize],
    ) -> Result<TensorNodeId, AutogradError> {
        // No-grad fast path for flip along ANY set of dims. The tape path compacts (clones)
        // the input then runs a per-element division-based unravel (~ndim divisions x numel,
        // measured ~3.6x SLOWER than torch for a 2-D flip); the previous single-dim
        // block-reversal UNDER-PARALLELIZED when flipping an OUTER dim (it split over `outer`,
        // which is 1 for dim 0 → fully serial, measured ~3x SLOWER). Reorganize like the pad
        // col_map trick: the last dim's source-column map is identical for every row (reversed
        // iff the last dim is flipped), so precompute `col_map[in_last]` ONCE; then per output
        // ROW decode the OUTER coords, reverse the flipped outer dims to get the source row,
        // and gather via col_map. Parallel over OUTPUT ROWS (~outer rows) regardless of which
        // dims flip. Bit-identical to the tape flip. f64/f32 contiguous no-grad only; grad /
        // non-contiguous / empty-dims / out-of-range-or-duplicate dims fall through.
        if !dims.is_empty() && !self.tensor_requires_grad(input)? {
            let shape = self.tensor_shape(input)?;
            let ndim = shape.len();
            // Build the per-dim flip mask, bailing on out-of-range/duplicate dims (the tape
            // validates those — torch errors on duplicates).
            let mut flipped = vec![false; ndim];
            let mut valid = true;
            for &d in dims {
                if d >= ndim || flipped[d] {
                    valid = false;
                    break;
                }
                flipped[d] = true;
            }
            if valid && ndim >= 1 {
                let last = ndim - 1;
                let in_last = shape[last];
                let numel: usize = shape.iter().product();
                if in_last > 0 && numel > 0 {
                    // Source column for output column j: reversed iff the last dim is flipped.
                    // Computed INLINE (was a precomputed `col_map` Vec of `in_last` usizes —
                    // for a 1-D flip that's a 128MB index Vec allocated every call, which
                    // DOMINATED the op; ~9x SLOWER than torch).
                    let flip_last = flipped[last];
                    let outer_strides = ft_core::contiguous_strides(&shape[..last]);
                    let dtype = self.tensor_dtype(input)?;
                    let build_row = |orow: usize| -> usize {
                        let mut rem = orow;
                        let mut in_row = 0usize;
                        for d in 0..last {
                            let oc = rem / outer_strides[d];
                            rem %= outer_strides[d];
                            let sc = if flipped[d] { shape[d] - 1 - oc } else { oc };
                            in_row += sc * outer_strides[d];
                        }
                        in_row * in_last
                    };
                    let mut built_f64: Option<Vec<f64>> = None;
                    let mut built_f32: Option<Vec<f32>> = None;
                    {
                        let tensor = self.tensor_tape.tensor(input)?;
                        if tensor.meta().is_contiguous() {
                            use rayon::prelude::*;
                            // Grain-based flat fill that walks rows INTERNALLY (vs the old
                            // par_chunks_mut(in_last) = one chunk per output row). The old form
                            // left a 1-D flip (or any case where in_last==numel) SERIAL — a 16M
                            // reversal on one core = ~9x SLOWER than torch. Grain-chunking the
                            // flat output parallelizes regardless of row count; build_row is
                            // decoded once per row boundary. Bit-identical (same source map,
                            // same write order).
                            let threads = rayon::current_num_threads().max(1);
                            let grain = (numel / (threads * 4)).max(1);
                            macro_rules! flip_fill {
                                ($read:ident, $zero:expr) => {{
                                    let data = tensor.$read()?;
                                    let mut out = vec![$zero; numel];
                                    let fill = |ci: usize, chunk: &mut [_]| {
                                        let mut g = ci * grain;
                                        let mut w = 0usize;
                                        while w < chunk.len() {
                                            let orow = g / in_last;
                                            let within = g % in_last;
                                            let base = build_row(orow);
                                            let run = (in_last - within).min(chunk.len() - w);
                                            if flip_last {
                                                // src col = in_last-1-(within+k): reverse read
                                                let top = base + in_last - 1 - within;
                                                for k in 0..run {
                                                    chunk[w + k] = data[top - k];
                                                }
                                            } else {
                                                // identity col map → contiguous block copy
                                                let src = base + within;
                                                chunk[w..w + run]
                                                    .copy_from_slice(&data[src..src + run]);
                                            }
                                            w += run;
                                            g += run;
                                        }
                                    };
                                    // Pure movement/copy: gate at the fault-parallelism crossover
                                    // (MOVEMENT_COPY_PARALLEL_MIN), NOT unconditionally — parallel
                                    // regresses small/medium copies 2-14x; serial below the gate.
                                    // Bit-identical (same source map, same write order).
                                    if numel >= MOVEMENT_COPY_PARALLEL_MIN {
                                        out.par_chunks_mut(grain)
                                            .enumerate()
                                            .for_each(|(ci, chunk)| fill(ci, chunk));
                                    } else {
                                        out.chunks_mut(grain)
                                            .enumerate()
                                            .for_each(|(ci, chunk)| fill(ci, chunk));
                                    }
                                    out
                                }};
                            }
                            match dtype {
                                DType::F64 => {
                                    built_f64 = Some(flip_fill!(contiguous_values, 0.0_f64));
                                }
                                DType::F32 => {
                                    built_f32 = Some(flip_fill!(contiguous_values_f32, 0.0_f32));
                                }
                                _ => {}
                            }
                        }
                    }
                    if let Some(out) = built_f64 {
                        return self.tensor_variable(out, shape, false);
                    }
                    if let Some(out) = built_f32 {
                        return self.tensor_variable_f32(out, shape, false);
                    }
                }
            }
        }
        self.tensor_tape.flip(input, dims.to_vec())
    }

    /// Repeat a tensor along each dimension.
    ///
    /// `repeats` specifies the number of repetitions for each output dimension.
    /// Its length must be greater than or equal to the input rank; when larger,
    /// leading singleton dimensions are implicitly prepended (PyTorch-compatible).
    pub fn tensor_repeat(
        &mut self,
        input: TensorNodeId,
        repeats: &[usize],
    ) -> Result<TensorNodeId, AutogradError> {
        // No-grad fast path for ANY repeat pattern. The output is a pure TILE of the input —
        // out[coords] = in[coords_d % shape_eff[d]] — whose last (contiguous) dim is the
        // source row tiled `repeats[last]` times. The tape repeat clones + per-element
        // division-unravels (slow, esp. f32). Here: decode each output row's source-row base
        // ONCE (a few divs over the outer dims), then block-copy contiguous `src_last`-runs.
        // Grain-based parallel over the flat output — robust to few-large-rows (last-dim
        // repeat) AND many-small-rows (outer-dim repeat). Bit-identical (pure copy) for f64
        // AND f32; sequential-write / page-fault-distributing class (the cat/stack/repeat
        // lever). Grad / non-contiguous / rank-mismatch (repeats.len() < rank) / overflow /
        // empty (any repeat 0) fall through to the tape (which errors or handles them).
        let repeat_dtype = self.tensor_dtype(input)?;
        if !self.tensor_requires_grad(input)? && matches!(repeat_dtype, DType::F64 | DType::F32) {
            let shape = self.tensor_shape(input)?;
            let rank = shape.len();
            let rr = repeats.len();
            if rank >= 1 && rr >= rank {
                let lead = rr - rank;
                // Effective source shape: leading 1s prepended to match repeats.len().
                let shape_eff: Vec<usize> = (0..rr)
                    .map(|d| if d < lead { 1 } else { shape[d - lead] })
                    .collect();
                // Output shape with CHECKED overflow (fall through to the tape's CHECKED
                // error so the overflow-rejection test still sees a clean Err, not a panic).
                let mut out_shape = Vec::with_capacity(rr);
                let mut ok = true;
                for d in 0..rr {
                    match shape_eff[d].checked_mul(repeats[d]) {
                        Some(v) => out_shape.push(v),
                        None => {
                            ok = false;
                            break;
                        }
                    }
                }
                let total = if ok {
                    out_shape.iter().try_fold(1usize, |a, &x| a.checked_mul(x))
                } else {
                    None
                };
                let last = rr - 1;
                let src_last = shape_eff[last];
                if let Some(total) = total {
                    if total > 0 && src_last > 0 {
                        let out_last = out_shape[last];
                        let is_contiguous = self.tensor_tape.tensor(input)?.meta().is_contiguous();
                        if is_contiguous {
                            let in_strides = ft_core::contiguous_strides(&shape_eff);
                            let out_outer_strides = ft_core::contiguous_strides(&out_shape[..last]);
                            let shape_eff_outer = shape_eff[..last].to_vec();
                            // Source-row base (element offset of the contiguous src_last run)
                            // for output row `orow`: decode orow into out outer coords, fold
                            // each modulo its source extent. Depends only on orow.
                            let build_in_row_base = move |orow: usize| -> usize {
                                let mut rem = orow;
                                let mut base = 0usize;
                                for d in 0..last {
                                    let oc = rem / out_outer_strides[d];
                                    rem %= out_outer_strides[d];
                                    let sc = oc % shape_eff_outer[d];
                                    base += sc * in_strides[d];
                                }
                                base
                            };
                            macro_rules! general_repeat {
                                ($read:ident, $zero:expr) => {{
                                    let tensor = self.tensor_tape.tensor(input)?;
                                    let data = tensor.$read()?;
                                    use rayon::prelude::*;
                                    let mut out = vec![$zero; total];
                                    let threads = rayon::current_num_threads().max(1);
                                    let grain = (total / (threads * 4)).max(1);
                                    let fill = |ci: usize, chunk: &mut [_]| {
                                        let mut g = ci * grain;
                                        let mut w = 0usize;
                                        while w < chunk.len() {
                                            let orow = g / out_last;
                                            let within = g % out_last;
                                            let base = build_in_row_base(orow);
                                            let c = within % src_last;
                                            let avail = (src_last - c).min(chunk.len() - w);
                                            chunk[w..w + avail].copy_from_slice(
                                                &data[base + c..base + c + avail],
                                            );
                                            w += avail;
                                            g += avail;
                                        }
                                    };
                                    // Pure copy: gate at the fault-parallelism crossover, not
                                    // unconditionally (regresses small/medium 2-14x). Bit-identical.
                                    if total >= MOVEMENT_COPY_PARALLEL_MIN {
                                        out.par_chunks_mut(grain)
                                            .enumerate()
                                            .for_each(|(ci, chunk)| fill(ci, chunk));
                                    } else {
                                        out.chunks_mut(grain)
                                            .enumerate()
                                            .for_each(|(ci, chunk)| fill(ci, chunk));
                                    }
                                    out
                                }};
                            }
                            match repeat_dtype {
                                DType::F64 => {
                                    let out = general_repeat!(contiguous_values, 0.0_f64);
                                    return self.tensor_variable(out, out_shape, false);
                                }
                                DType::F32 => {
                                    let out = general_repeat!(contiguous_values_f32, 0.0_f32);
                                    return self.tensor_variable_f32(out, out_shape, false);
                                }
                                _ => unreachable!(),
                            }
                        }
                    }
                }
            }
        }
        self.tensor_tape.repeat(input, repeats.to_vec())
    }

    /// Roll tensor elements along the given dimension by `shift` positions.
    ///
    /// Elements that are shifted beyond the last position are re-introduced at
    /// the first position (circular shift).
    pub fn tensor_roll(
        &mut self,
        input: TensorNodeId,
        shift: i64,
        dim: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let shift = isize::try_from(shift).map_err(|_| {
            AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "tensor_roll shift is out of range for platform isize",
                },
            ))
        })?;
        // No-grad fast path: the tape path compacts (clones) the input then runs a
        // per-element division-based unravel. A circular shift along one axis is just a
        // ROTATION of the `mid`-axis = TWO contiguous block copies per outer slice, NO
        // division. `out[j] = in[(j+inv_shift) mod mid]` (matching the kernel's
        // `dst=(src+shift) mod n`). Borrow + parallelize over outer slices. Bit-exact.
        if !self.tensor_requires_grad(input)? {
            let shape = self.tensor_shape(input)?;
            if dim < shape.len() {
                let mid = shape[dim];
                let inner: usize = shape[dim + 1..].iter().product();
                let outer: usize = shape[..dim].iter().product();
                let block = mid * inner;
                let dtype = self.tensor_dtype(input)?;
                if block > 0 {
                    #[allow(clippy::cast_possible_wrap, clippy::cast_sign_loss)]
                    let shift_mod = shift.rem_euclid(mid as isize) as usize;
                    let inv_shift = (mid - shift_mod) % mid;
                    let cut = inv_shift * inner;
                    let split = block - cut;
                    let total = outer * block;
                    let built = {
                        let tensor = self.tensor_tape.tensor(input)?;
                        if tensor.meta().is_contiguous() {
                            use rayon::prelude::*;
                            let threads = rayon::current_num_threads().max(1);
                            let grain = (total / (threads * 4)).max(1);
                            // Grain-based flat rotation fill — parallel for ANY shape. The old
                            // par_chunks_mut(block) left a 1-D roll (outer==1) as ONE chunk =
                            // TWO serial 16M copies (~5.9x SLOWER than torch). Within each outer
                            // block: out[k<split] = in[cut+k], out[k>=split] = in[k-split], both
                            // CONTIGUOUS runs. Bit-identical to the two-copy form.
                            macro_rules! roll_fill {
                                ($read:ident, $zero:expr) => {{
                                    let data = tensor.$read()?;
                                    let mut out = vec![$zero; total];
                                    let fill = |ci: usize, chunk: &mut [_]| {
                                        let mut g = ci * grain;
                                        let mut w = 0usize;
                                        while w < chunk.len() {
                                            let o = g / block;
                                            let k = g - o * block;
                                            let base = o * block;
                                            let (src_off, seg_end) = if k < split {
                                                (base + cut + k, split)
                                            } else {
                                                (base + (k - split), block)
                                            };
                                            let run = (seg_end - k).min(chunk.len() - w);
                                            chunk[w..w + run]
                                                .copy_from_slice(&data[src_off..src_off + run]);
                                            w += run;
                                            g += run;
                                        }
                                    };
                                    // Pure copy: gate at the fault-parallelism crossover, not
                                    // unconditionally (regresses small/medium 2-14x). Bit-identical.
                                    if total >= MOVEMENT_COPY_PARALLEL_MIN {
                                        out.par_chunks_mut(grain)
                                            .enumerate()
                                            .for_each(|(ci, chunk)| fill(ci, chunk));
                                    } else {
                                        out.chunks_mut(grain)
                                            .enumerate()
                                            .for_each(|(ci, chunk)| fill(ci, chunk));
                                    }
                                    out
                                }};
                            }
                            match dtype {
                                DType::F64 => Some(Ok(roll_fill!(contiguous_values, 0.0_f64))),
                                DType::F32 => Some(Err(roll_fill!(contiguous_values_f32, 0.0_f32))),
                                _ => None,
                            }
                        } else {
                            None
                        }
                    };
                    match built {
                        Some(Ok(out)) => return self.tensor_variable(out, shape, false),
                        Some(Err(out)) => return self.tensor_variable_f32(out, shape, false),
                        None => {}
                    }
                }
            }
        }
        self.tensor_tape.roll(input, shift, dim)
    }

    /// `torch.roll(input, shifts, dims)` with multiple `(shift, dim)` pairs.
    /// roll is separable across dimensions, so the multi-dim roll equals rolling
    /// along each listed dim in turn. `shifts` and `dims` must have equal length.
    pub fn tensor_roll_dims(
        &mut self,
        input: TensorNodeId,
        shifts: &[i64],
        dims: &[usize],
    ) -> Result<TensorNodeId, AutogradError> {
        if shifts.len() != dims.len() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "roll: shifts and dims must have the same length",
                },
            )));
        }
        // No-grad single-pass fast path for rank-2 (the common 2-D multi-dim roll). The default
        // path below does N sequential tensor_roll calls — each MATERIALIZES a full intermediate
        // tensor (Vec + tape node), so a 2-D roll is 2 full passes + an intermediate (~11x SLOWER
        // than torch in release). Accumulate the per-dim shift and roll in ONE parallel pass: per
        // output row, pick the source row by the dim-0 shift, then block-copy the row rotated by
        // the dim-1 shift (2 contiguous runs). Bit-identical (pure positional movement). Grad /
        // rank!=2 / non-contiguous / out-of-range dim fall through to the sequential rolls.
        let shape = self.tensor_shape(input)?;
        if shape.len() == 2
            && !self.tensor_requires_grad(input)?
            && dims.iter().all(|&d| d < 2)
            && self.tensor_tape.tensor(input)?.meta().is_contiguous()
        {
            let (n0, n1) = (shape[0], shape[1]);
            if n0 > 0 && n1 > 0 {
                let mut s0 = 0i64;
                let mut s1 = 0i64;
                for (&sh, &d) in shifts.iter().zip(dims.iter()) {
                    if d == 0 {
                        s0 += sh;
                    } else {
                        s1 += sh;
                    }
                }
                let sh1 = s1.rem_euclid(n1 as i64) as usize; // row right-rotation amount
                let row_src =
                    |i: usize| -> usize { (i as i64 - s0).rem_euclid(n0 as i64) as usize };
                // out[i, 0..sh1] = src[n1-sh1..n1]; out[i, sh1..n1] = src[0..n1-sh1]
                macro_rules! roll2d {
                    ($read:ident, $zero:expr, $build:ident) => {{
                        let vals = self.tensor_tape.tensor(input)?.$read()?;
                        let mut out = vec![$zero; n0 * n1];
                        let fill = |i: usize, orow: &mut [_]| {
                            let base = row_src(i) * n1;
                            let src = &vals[base..base + n1];
                            orow[..sh1].copy_from_slice(&src[n1 - sh1..]);
                            orow[sh1..].copy_from_slice(&src[..n1 - sh1]);
                        };
                        if n0 * n1 >= PARALLEL_ELEMENTWISE_MIN && n0 > 1 {
                            use rayon::prelude::*;
                            out.par_chunks_mut(n1)
                                .enumerate()
                                .for_each(|(i, orow)| fill(i, orow));
                        } else {
                            out.chunks_mut(n1)
                                .enumerate()
                                .for_each(|(i, orow)| fill(i, orow));
                        }
                        return self.$build(out, shape, false);
                    }};
                }
                match self.tensor_dtype(input)? {
                    DType::F64 => roll2d!(contiguous_values, 0.0_f64, tensor_variable),
                    DType::F32 => roll2d!(contiguous_values_f32, 0.0_f32, tensor_variable_f32),
                    _ => {}
                }
            }
        }
        // General-rank single-pass fast path (rank != 2 lands here; rank 2 returned above). The
        // default path below does N sequential tensor_roll calls, each MATERIALIZING a full tensor
        // (Vec + tape node) — so a rank-3 multi-dim roll is 3 passes + 2 intermediates. Accumulate
        // the per-dim shift, then in ONE parallel pass over the output "rows" (contiguous last-dim
        // slices) pick the source row by un-rolling the outer coords and block-copy the row rotated
        // by the last-dim shift (2 contiguous runs). Bit-identical (pure positional movement). Grad
        // / non-contiguous / out-of-range dim / zero-size fall through to the sequential rolls.
        if !self.tensor_requires_grad(input)?
            && !shape.is_empty()
            && dims.iter().all(|&d| d < shape.len())
            && shape.iter().all(|&s| s > 0)
            && self.tensor_tape.tensor(input)?.meta().is_contiguous()
        {
            let ndim = shape.len();
            let last = ndim - 1;
            let last_size = shape[last];
            let numel: usize = shape.iter().product();
            let mut dim_shift = vec![0i64; ndim];
            for (&sh, &d) in shifts.iter().zip(dims.iter()) {
                dim_shift[d] += sh;
            }
            let sh_last = dim_shift[last].rem_euclid(last_size as i64) as usize;
            let n_rows = numel / last_size;
            // Row strides over the outer dims [0..last] (units of ROWS): stride[last-1]=1,
            // stride[d]=stride[d+1]*shape[d+1].
            let mut outer_stride = vec![1usize; last];
            for d in (0..last.saturating_sub(1)).rev() {
                outer_stride[d] = outer_stride[d + 1] * shape[d + 1];
            }
            let src_row = |r: usize| -> usize {
                let mut rem = r;
                let mut src = 0usize;
                for d in 0..last {
                    let c = rem / outer_stride[d];
                    rem %= outer_stride[d];
                    let cs = (c as i64 - dim_shift[d]).rem_euclid(shape[d] as i64) as usize;
                    src += cs * outer_stride[d];
                }
                src
            };
            macro_rules! rollnd {
                ($read:ident, $zero:expr, $build:ident) => {{
                    let vals = self.tensor_tape.tensor(input)?.$read()?;
                    let mut out = vec![$zero; numel];
                    let fill = |r: usize, orow: &mut [_]| {
                        let base = src_row(r) * last_size;
                        let src = &vals[base..base + last_size];
                        orow[..sh_last].copy_from_slice(&src[last_size - sh_last..]);
                        orow[sh_last..].copy_from_slice(&src[..last_size - sh_last]);
                    };
                    if numel >= PARALLEL_ELEMENTWISE_MIN && n_rows > 1 {
                        use rayon::prelude::*;
                        out.par_chunks_mut(last_size)
                            .enumerate()
                            .for_each(|(r, orow)| fill(r, orow));
                    } else {
                        out.chunks_mut(last_size)
                            .enumerate()
                            .for_each(|(r, orow)| fill(r, orow));
                    }
                    return self.$build(out, shape, false);
                }};
            }
            match self.tensor_dtype(input)? {
                DType::F64 => rollnd!(contiguous_values, 0.0_f64, tensor_variable),
                DType::F32 => rollnd!(contiguous_values_f32, 0.0_f32, tensor_variable_f32),
                _ => {}
            }
        }
        let mut out = input;
        for (&shift, &dim) in shifts.iter().zip(dims.iter()) {
            out = self.tensor_roll(out, shift, dim)?;
        }
        Ok(out)
    }

    /// `torch.roll(input, shift)` with no `dims`: roll the flattened tensor and
    /// restore the original shape.
    pub fn tensor_roll_flat(
        &mut self,
        input: TensorNodeId,
        shift: i64,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        let numel = Self::checked_shape_numel(&shape, "roll: shape volume overflow")?;
        let flat = self.tensor_reshape(input, vec![numel])?;
        let rolled = self.tensor_roll(flat, shift, 0)?;
        self.tensor_reshape(rolled, shape)
    }

    /// True when both operands are complex — the case where the real-elementwise
    /// tape path would either drop the imaginary part or compute the wrong
    /// backward, so the op is composed from real/imag arithmetic instead.
    /// frankentorch-hyi5x.
    fn complex_grad_pair(&self, a: TensorNodeId, b: TensorNodeId) -> Result<bool, AutogradError> {
        let both_complex = matches!(self.tensor_dtype(a)?, DType::Complex64 | DType::Complex128)
            && matches!(self.tensor_dtype(b)?, DType::Complex64 | DType::Complex128);
        Ok(both_complex)
    }

    /// No-grad fused LAST-DIM broadcast for the elementwise ops add/sub/mul/div: one operand is a
    /// contiguous `[.., M]` tensor, the other a vector broadcasting over every leading dim
    /// (shape `[M]` or `[1,..,1,M]`). The generic tape path materializes the vector EXPANDED to
    /// the full `[.., M]` shape (an extra output-sized buffer) then runs the matching-shape
    /// kernel; here we op the vector into each row in ONE pass with no expand. Bit-identical
    /// (`out[.., j] = op(big[.., j], vec[j])` — the same values the expand+op produces). f32/f64,
    /// contiguous, no-grad. For the non-commutative sub/div we track `big_is_lhs` so the operand
    /// order matches. Everything else (grad, other shapes/dtypes, non-contiguous) falls through.
    fn try_lastdim_bcast(
        &mut self,
        lhs: TensorNodeId,
        rhs: TensorNodeId,
        op: BcastBinOp,
    ) -> Result<Option<TensorNodeId>, AutogradError> {
        if self.tensor_requires_grad(lhs)? || self.tensor_requires_grad(rhs)? {
            return Ok(None);
        }
        let ls = self.tensor_shape(lhs)?;
        let rs = self.tensor_shape(rhs)?;
        if ls.is_empty() || rs.is_empty() || ls == rs {
            return Ok(None);
        }
        let last = |s: &[usize]| *s.last().unwrap();
        // A "vec" broadcasts over all leading dims => every dim but the last is 1.
        let is_vec = |s: &[usize]| s[..s.len() - 1].iter().all(|&d| d == 1);
        let numel = |s: &[usize]| s.iter().product::<usize>();
        // Pick (big, vec) unambiguously: the vec has fewer elements and matching last dim.
        // `big_is_lhs` records operand order for the non-commutative sub/div.
        let (big, vec, big_shape, big_is_lhs) =
            if is_vec(&rs) && last(&rs) == last(&ls) && numel(&ls) > numel(&rs) {
                (lhs, rhs, ls.clone(), true)
            } else if is_vec(&ls) && last(&ls) == last(&rs) && numel(&rs) > numel(&ls) {
                (rhs, lhs, rs.clone(), false)
            } else {
                return Ok(None);
            };
        let m = last(&big_shape);
        if m == 0 {
            return Ok(None);
        }
        let big_numel = numel(&big_shape);
        let dtype = self.tensor_dtype(big)?;
        if self.tensor_dtype(vec)? != dtype {
            return Ok(None);
        }
        macro_rules! fused {
            ($read:ident, $build:ident, $ty:ty) => {{
                let built = {
                    let bt = self.tensor_tape.tensor(big)?;
                    let vt = self.tensor_tape.tensor(vec)?;
                    if bt.meta().is_contiguous() && vt.meta().is_contiguous() {
                        let bd = bt.$read()?;
                        let vd = vt.$read()?;
                        if bd.len() == big_numel && vd.len() == m {
                            let mut out = vec![0 as $ty; big_numel];
                            use rayon::prelude::*;
                            // `b` = big element, `v` = vec element. big_is_lhs picks (b op v) vs
                            // (v op b) for the non-commutative sub/div.
                            let fill = |row: &mut [$ty], src: &[$ty]| match (op, big_is_lhs) {
                                (BcastBinOp::Add, _) => {
                                    for ((o, &b), &v) in row.iter_mut().zip(src).zip(vd.iter()) {
                                        *o = b + v;
                                    }
                                }
                                (BcastBinOp::Mul, _) => {
                                    for ((o, &b), &v) in row.iter_mut().zip(src).zip(vd.iter()) {
                                        *o = b * v;
                                    }
                                }
                                (BcastBinOp::Sub, true) => {
                                    for ((o, &b), &v) in row.iter_mut().zip(src).zip(vd.iter()) {
                                        *o = b - v;
                                    }
                                }
                                (BcastBinOp::Sub, false) => {
                                    for ((o, &b), &v) in row.iter_mut().zip(src).zip(vd.iter()) {
                                        *o = v - b;
                                    }
                                }
                                (BcastBinOp::Div, true) => {
                                    for ((o, &b), &v) in row.iter_mut().zip(src).zip(vd.iter()) {
                                        *o = b / v;
                                    }
                                }
                                (BcastBinOp::Div, false) => {
                                    for ((o, &b), &v) in row.iter_mut().zip(src).zip(vd.iter()) {
                                        *o = v / b;
                                    }
                                }
                                (BcastBinOp::Max, _) => {
                                    for ((o, &b), &v) in row.iter_mut().zip(src).zip(vd.iter()) {
                                        *o = if b.is_nan() || v.is_nan() {
                                            <$ty>::NAN
                                        } else {
                                            b.max(v)
                                        };
                                    }
                                }
                                (BcastBinOp::Min, _) => {
                                    for ((o, &b), &v) in row.iter_mut().zip(src).zip(vd.iter()) {
                                        *o = if b.is_nan() || v.is_nan() {
                                            <$ty>::NAN
                                        } else {
                                            b.min(v)
                                        };
                                    }
                                }
                            };
                            if big_numel >= PARALLEL_ELEMENTWISE_MIN {
                                out.par_chunks_mut(m)
                                    .zip(bd.par_chunks(m))
                                    .for_each(|(row, src)| fill(row, src));
                            } else {
                                out.chunks_mut(m)
                                    .zip(bd.chunks(m))
                                    .for_each(|(row, src)| fill(row, src));
                            }
                            Some(out)
                        } else {
                            None
                        }
                    } else {
                        None
                    }
                };
                match built {
                    Some(out) => Ok(Some(self.$build(out, big_shape.clone(), false)?)),
                    None => Ok(None),
                }
            }};
        }
        match dtype {
            DType::F64 => fused!(contiguous_values, tensor_variable, f64),
            DType::F32 => fused!(contiguous_values_f32, tensor_variable_f32, f32),
            _ => Ok(None),
        }
    }

    /// No-grad fused ROW-SCALAR (column) broadcast for add/sub/mul/div: one operand is a contiguous
    /// `[.., N, M]` tensor, the other is the same shape with the LAST dim collapsed to 1
    /// (`[.., N, 1]`) — a per-row scalar broadcasting over the last dim. The generic tape path
    /// materializes the small operand EXPANDED to the full `[.., N, M]` shape then runs the
    /// matching-shape kernel; here we op each row against its scalar in ONE pass, no expand.
    /// Bit-identical (`out[o, j] = op(big[o, j], vec[o])`). f32/f64, contiguous, no-grad; tracks
    /// `big_is_lhs` for the non-commutative sub/div. Everything else falls through.
    fn try_rowscalar_bcast(
        &mut self,
        lhs: TensorNodeId,
        rhs: TensorNodeId,
        op: BcastBinOp,
    ) -> Result<Option<TensorNodeId>, AutogradError> {
        if self.tensor_requires_grad(lhs)? || self.tensor_requires_grad(rhs)? {
            return Ok(None);
        }
        let ls = self.tensor_shape(lhs)?;
        let rs = self.tensor_shape(rhs)?;
        if ls.is_empty() || rs.is_empty() || ls == rs {
            return Ok(None);
        }
        // `v` is `big` with the last dim collapsed to 1: same rank, same leading dims, last == 1,
        // and big's last dim > 1 (a genuine per-row scalar broadcast over the last dim).
        let is_colvec = |big: &[usize], v: &[usize]| -> bool {
            v.len() == big.len()
                && *v.last().unwrap() == 1
                && *big.last().unwrap() > 1
                && v[..v.len() - 1] == big[..big.len() - 1]
        };
        let (big, vec, big_shape, big_is_lhs) = if is_colvec(&ls, &rs) {
            (lhs, rhs, ls.clone(), true)
        } else if is_colvec(&rs, &ls) {
            (rhs, lhs, rs.clone(), false)
        } else {
            return Ok(None);
        };
        let m = *big_shape.last().unwrap();
        let big_numel: usize = big_shape.iter().product();
        let outer = big_numel / m;
        let dtype = self.tensor_dtype(big)?;
        if self.tensor_dtype(vec)? != dtype {
            return Ok(None);
        }
        macro_rules! fused {
            ($read:ident, $build:ident, $ty:ty) => {{
                let built = {
                    let bt = self.tensor_tape.tensor(big)?;
                    let vt = self.tensor_tape.tensor(vec)?;
                    if bt.meta().is_contiguous() && vt.meta().is_contiguous() {
                        let bd = bt.$read()?;
                        let vd = vt.$read()?;
                        if bd.len() == big_numel && vd.len() == outer {
                            let mut out = vec![0 as $ty; big_numel];
                            use rayon::prelude::*;
                            // `b` = big element, `s` = the row's scalar. big_is_lhs picks (b op s)
                            // vs (s op b) for the non-commutative sub/div.
                            let fill = |o: usize, row: &mut [$ty], src: &[$ty]| {
                                let s = vd[o];
                                match (op, big_is_lhs) {
                                    (BcastBinOp::Add, _) => {
                                        for (d, &b) in row.iter_mut().zip(src) {
                                            *d = b + s;
                                        }
                                    }
                                    (BcastBinOp::Mul, _) => {
                                        for (d, &b) in row.iter_mut().zip(src) {
                                            *d = b * s;
                                        }
                                    }
                                    (BcastBinOp::Sub, true) => {
                                        for (d, &b) in row.iter_mut().zip(src) {
                                            *d = b - s;
                                        }
                                    }
                                    (BcastBinOp::Sub, false) => {
                                        for (d, &b) in row.iter_mut().zip(src) {
                                            *d = s - b;
                                        }
                                    }
                                    (BcastBinOp::Div, true) => {
                                        for (d, &b) in row.iter_mut().zip(src) {
                                            *d = b / s;
                                        }
                                    }
                                    (BcastBinOp::Div, false) => {
                                        for (d, &b) in row.iter_mut().zip(src) {
                                            *d = s / b;
                                        }
                                    }
                                    (BcastBinOp::Max, _) => {
                                        for (d, &b) in row.iter_mut().zip(src) {
                                            *d = if b.is_nan() || s.is_nan() {
                                                <$ty>::NAN
                                            } else {
                                                b.max(s)
                                            };
                                        }
                                    }
                                    (BcastBinOp::Min, _) => {
                                        for (d, &b) in row.iter_mut().zip(src) {
                                            *d = if b.is_nan() || s.is_nan() {
                                                <$ty>::NAN
                                            } else {
                                                b.min(s)
                                            };
                                        }
                                    }
                                }
                            };
                            if big_numel >= PARALLEL_ELEMENTWISE_MIN {
                                out.par_chunks_mut(m)
                                    .zip(bd.par_chunks(m))
                                    .enumerate()
                                    .for_each(|(o, (row, src))| fill(o, row, src));
                            } else {
                                out.chunks_mut(m)
                                    .zip(bd.chunks(m))
                                    .enumerate()
                                    .for_each(|(o, (row, src))| fill(o, row, src));
                            }
                            Some(out)
                        } else {
                            None
                        }
                    } else {
                        None
                    }
                };
                match built {
                    Some(out) => Ok(Some(self.$build(out, big_shape.clone(), false)?)),
                    None => Ok(None),
                }
            }};
        }
        match dtype {
            DType::F64 => fused!(contiguous_values, tensor_variable, f64),
            DType::F32 => fused!(contiguous_values_f32, tensor_variable_f32, f32),
            _ => Ok(None),
        }
    }

    /// No-grad fused FULL-SCALAR broadcast for add/sub/mul/div: one operand has exactly 1 element
    /// (shape `[1]`, `[1,..,1]`, or 0-d) and broadcasts over the whole other tensor — the
    /// `x - x.mean()` / `x / x.std()` / `x / x.norm()` global-normalization pattern. The generic
    /// tape path materializes the scalar EXPANDED to the full shape then runs the matching-shape
    /// kernel; here we op the single scalar into every element in ONE parallel pass, no expand.
    /// Bit-identical (`out[i] = op(big[i], scalar)`). f32/f64, contiguous, no-grad; tracks
    /// `big_is_lhs` for the non-commutative sub/div. Everything else falls through.
    fn try_fullscalar_bcast(
        &mut self,
        lhs: TensorNodeId,
        rhs: TensorNodeId,
        op: BcastBinOp,
    ) -> Result<Option<TensorNodeId>, AutogradError> {
        if self.tensor_requires_grad(lhs)? || self.tensor_requires_grad(rhs)? {
            return Ok(None);
        }
        let ls = self.tensor_shape(lhs)?;
        let rs = self.tensor_shape(rhs)?;
        let numel = |s: &[usize]| s.iter().product::<usize>();
        // One side is a single element (broadcasts to anything); the other is the full tensor.
        let (big, scal, big_shape, big_is_lhs) = if numel(&rs) == 1 && numel(&ls) > 1 {
            (lhs, rhs, ls.clone(), true)
        } else if numel(&ls) == 1 && numel(&rs) > 1 {
            (rhs, lhs, rs.clone(), false)
        } else {
            return Ok(None);
        };
        let big_numel = numel(&big_shape);
        let dtype = self.tensor_dtype(big)?;
        if self.tensor_dtype(scal)? != dtype {
            return Ok(None);
        }
        macro_rules! fused {
            ($read:ident, $build:ident, $ty:ty) => {{
                let built = {
                    let bt = self.tensor_tape.tensor(big)?;
                    let st = self.tensor_tape.tensor(scal)?;
                    if bt.meta().is_contiguous() && st.meta().is_contiguous() {
                        let bd = bt.$read()?;
                        let sd = st.$read()?;
                        if bd.len() == big_numel && sd.len() == 1 {
                            let s = sd[0];
                            use rayon::prelude::*;
                            let map = |b: $ty| -> $ty {
                                match (op, big_is_lhs) {
                                    (BcastBinOp::Add, _) => b + s,
                                    (BcastBinOp::Mul, _) => b * s,
                                    (BcastBinOp::Sub, true) => b - s,
                                    (BcastBinOp::Sub, false) => s - b,
                                    (BcastBinOp::Div, true) => b / s,
                                    (BcastBinOp::Div, false) => s / b,
                                    (BcastBinOp::Max, _) => {
                                        if b.is_nan() || s.is_nan() {
                                            <$ty>::NAN
                                        } else {
                                            b.max(s)
                                        }
                                    }
                                    (BcastBinOp::Min, _) => {
                                        if b.is_nan() || s.is_nan() {
                                            <$ty>::NAN
                                        } else {
                                            b.min(s)
                                        }
                                    }
                                }
                            };
                            let out: Vec<$ty> = if big_numel >= PARALLEL_ELEMENTWISE_MIN {
                                bd.par_iter().map(|&b| map(b)).collect()
                            } else {
                                bd.iter().map(|&b| map(b)).collect()
                            };
                            Some(out)
                        } else {
                            None
                        }
                    } else {
                        None
                    }
                };
                match built {
                    Some(out) => Ok(Some(self.$build(out, big_shape.clone(), false)?)),
                    None => Ok(None),
                }
            }};
        }
        match dtype {
            DType::F64 => fused!(contiguous_values, tensor_variable, f64),
            DType::F32 => fused!(contiguous_values_f32, tensor_variable_f32, f32),
            _ => Ok(None),
        }
    }

    /// No-grad fused broadcast-tile binop: one operand IS the full output shape (contiguous), the
    /// other broadcasts into it as a tile via `broadcast_offset_plan` (ANY broadcast). Covers the
    /// additive attention-bias pattern `scores[B,H,S,S] + bias[1,1,S,S]`, relative-position bias
    /// `[1,H,S,S]`, and key-padding `[B,1,1,S]` — none of which are the pure trailing-vec / per-row-
    /// scalar / full-scalar shapes the three helpers above handle, so they fall through to the tape
    /// op which `broadcast_to`s the tile to the full shape (a full-size clone — 128MB at [B,H,S,S]
    /// f64) then does the elementwise binop. Here we read the tile element straight from its plan
    /// offset and apply the op in ONE pass, no expand. Bit-identical to the tape op: same operands,
    /// same IEEE `lhs OP rhs` (broadcast_to only relocates tile values, it does not round). f32/f64,
    /// contiguous, no-grad, same dtype, exactly one operand full-size (the other strictly smaller);
    /// everything else falls through. frankentorch-bcast-tile-binop.
    fn try_bcast_tile_binop(
        &mut self,
        lhs: TensorNodeId,
        rhs: TensorNodeId,
        op: BcastBinOp,
    ) -> Result<Option<TensorNodeId>, AutogradError> {
        if self.tensor_requires_grad(lhs)? || self.tensor_requires_grad(rhs)? {
            return Ok(None);
        }
        let dtype = self.tensor_dtype(lhs)?;
        if self.tensor_dtype(rhs)? != dtype {
            return Ok(None);
        }
        let ls = self.tensor_shape(lhs)?;
        let rs = self.tensor_shape(rhs)?;
        let numel = |s: &[usize]| s.iter().product::<usize>();
        let out_shape = Self::broadcast_shape(&ls, &rs)?;
        let n = numel(&out_shape);
        // Exactly one operand must already BE the full output; the other is a strictly-smaller tile.
        // (Equal shapes -> both numel == n -> neither branch -> fall through to the same-shape path.)
        let (full, tile, tile_shape, full_is_lhs) = if ls == out_shape && numel(&rs) < n {
            (lhs, rhs, rs.clone(), true)
        } else if rs == out_shape && numel(&ls) < n {
            (rhs, lhs, ls.clone(), false)
        } else {
            return Ok(None);
        };
        let (inner, outer, block, rows_per_task) =
            match Self::broadcast_offset_plan(&tile_shape, &out_shape) {
                Some(p) => p,
                None => return Ok(None),
            };
        let tinner = numel(&tile_shape);
        macro_rules! fused {
            ($read:ident, $build:ident, $ty:ty) => {{
                let built = {
                    let ft = self.tensor_tape.tensor(full)?;
                    let tt = self.tensor_tape.tensor(tile)?;
                    if ft.meta().is_contiguous() && tt.meta().is_contiguous() {
                        let fd = ft.$read()?;
                        let td = tt.$read()?;
                        if fd.len() == n && td.len() == tinner {
                            use rayon::prelude::*;
                            // `a OP b` with (a,b) = (lhs,rhs) — preserves order for non-commutative
                            // sub/div. Matches the fullscalar helper's map + tape semantics exactly.
                            let map = |f: $ty, t: $ty| -> $ty {
                                let (a, b) = if full_is_lhs { (f, t) } else { (t, f) };
                                match op {
                                    BcastBinOp::Add => a + b,
                                    BcastBinOp::Mul => a * b,
                                    BcastBinOp::Sub => a - b,
                                    BcastBinOp::Div => a / b,
                                    BcastBinOp::Max => {
                                        if a.is_nan() || b.is_nan() { <$ty>::NAN } else { a.max(b) }
                                    }
                                    BcastBinOp::Min => {
                                        if a.is_nan() || b.is_nan() { <$ty>::NAN } else { a.min(b) }
                                    }
                                }
                            };
                            // per output row, the tile's trailing `inner` contiguous elems live at
                            // `mbase(row)` (sum over outer dims of (row-index-in-dim)*tile-stride,
                            // 0 for broadcast dims). Identical index math to try_where_one_scalar.
                            let mbase = |mut row: usize| -> usize {
                                let mut base = 0usize;
                                for &(radix, contrib) in outer.iter().rev() {
                                    let idx = row % radix;
                                    row /= radix;
                                    base += idx * contrib;
                                }
                                base
                            };
                            let fill = |row: usize, oc: &mut [$ty], fc: &[$ty]| {
                                let trow = &td[mbase(row)..mbase(row) + inner];
                                for j in 0..inner {
                                    oc[j] = map(fc[j], trow[j]);
                                }
                            };
                            let mut out = vec![0 as $ty; n];
                            if n >= PARALLEL_ELEMENTWISE_MIN {
                                out.par_chunks_mut(block)
                                    .zip(fd.par_chunks(block))
                                    .enumerate()
                                    .for_each(|(t, (ochunk, fchunk))| {
                                        let rb = t * rows_per_task;
                                        for (rr, (oc, fc)) in ochunk
                                            .chunks_mut(inner)
                                            .zip(fchunk.chunks(inner))
                                            .enumerate()
                                        {
                                            fill(rb + rr, oc, fc);
                                        }
                                    });
                            } else {
                                out.chunks_mut(inner)
                                    .zip(fd.chunks(inner))
                                    .enumerate()
                                    .for_each(|(row, (oc, fc))| fill(row, oc, fc));
                            }
                            Some(out)
                        } else {
                            None
                        }
                    } else {
                        None
                    }
                };
                match built {
                    Some(out) => Ok(Some(self.$build(out, out_shape.clone(), false)?)),
                    None => Ok(None),
                }
            }};
        }
        match dtype {
            DType::F64 => fused!(contiguous_values, tensor_variable, f64),
            DType::F32 => fused!(contiguous_values_f32, tensor_variable_f32, f32),
            _ => Ok(None),
        }
    }

    pub fn tensor_add(
        &mut self,
        lhs: TensorNodeId,
        rhs: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        if self.complex_grad_pair(lhs, rhs)? {
            // (ar+i·ai) + (br+i·bi) = (ar+br) + i·(ai+bi). Composed from real ops so
            // the gradient flows correctly through the complex<->real bridge.
            let ar = self.tensor_real(lhs)?;
            let ai = self.tensor_imag(lhs)?;
            let br = self.tensor_real(rhs)?;
            let bi = self.tensor_imag(rhs)?;
            let re = self.tensor_add(ar, br)?;
            let im = self.tensor_add(ai, bi)?;
            return self.tensor_complex(re, im);
        }
        if let Some(out) = self.try_lastdim_bcast(lhs, rhs, BcastBinOp::Add)? {
            return Ok(out);
        }
        if let Some(out) = self.try_rowscalar_bcast(lhs, rhs, BcastBinOp::Add)? {
            return Ok(out);
        }
        if let Some(out) = self.try_fullscalar_bcast(lhs, rhs, BcastBinOp::Add)? {
            return Ok(out);
        }
        if let Some(out) = self.try_bcast_tile_binop(lhs, rhs, BcastBinOp::Add)? {
            return Ok(out);
        }
        let (out, event) = self.tensor_tape.add(lhs, rhs, self.mode())?;
        self.record_tensor_operation(&event);
        Ok(out)
    }

    pub fn tensor_mul(
        &mut self,
        lhs: TensorNodeId,
        rhs: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        if self.complex_grad_pair(lhs, rhs)? {
            // (ar+i·ai)(br+i·bi) = (ar·br − ai·bi) + i·(ar·bi + ai·br). Composed from
            // real ops -> correct Wirtinger gradient via the complex<->real bridge.
            let ar = self.tensor_real(lhs)?;
            let ai = self.tensor_imag(lhs)?;
            let br = self.tensor_real(rhs)?;
            let bi = self.tensor_imag(rhs)?;
            let arbr = self.tensor_mul(ar, br)?;
            let aibi = self.tensor_mul(ai, bi)?;
            let re = self.tensor_sub(arbr, aibi)?;
            let arbi = self.tensor_mul(ar, bi)?;
            let aibr = self.tensor_mul(ai, br)?;
            let im = self.tensor_add(arbi, aibr)?;
            return self.tensor_complex(re, im);
        }
        if let Some(out) = self.try_lastdim_bcast(lhs, rhs, BcastBinOp::Mul)? {
            return Ok(out);
        }
        if let Some(out) = self.try_rowscalar_bcast(lhs, rhs, BcastBinOp::Mul)? {
            return Ok(out);
        }
        if let Some(out) = self.try_fullscalar_bcast(lhs, rhs, BcastBinOp::Mul)? {
            return Ok(out);
        }
        if let Some(out) = self.try_bcast_tile_binop(lhs, rhs, BcastBinOp::Mul)? {
            return Ok(out);
        }
        let (out, event) = self.tensor_tape.mul(lhs, rhs, self.mode())?;
        self.record_tensor_operation(&event);
        Ok(out)
    }

    pub fn tensor_mul_scalar(
        &mut self,
        input: TensorNodeId,
        scalar: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        // No-grad fast path: the tape mul_scalar clones the input (+ a tape node) and maps
        // `value * scalar` SERIALLY. For no-grad contiguous f64, borrow and multiply in
        // parallel — bit-identical (same `value * scalar`). This is a hot core op (e.g. it
        // was the residual ~136ms in huber_loss = delta * smooth_l1). f32 / grad /
        // non-contiguous fall through to the tape op.
        if !self.tensor_requires_grad(input)? && self.tensor_dtype(input)? == DType::F64 {
            let built = {
                let it = self.tensor_tape.tensor(input)?;
                if it.meta().is_contiguous() {
                    let xd = it.contiguous_values()?;
                    use rayon::prelude::*;
                    let out: Vec<f64> = xd.par_iter().map(|&x| x * scalar).collect();
                    Some(out)
                } else {
                    None
                }
            };
            if let Some(out) = built {
                let shape = self.tensor_shape(input)?;
                return self.tensor_variable(out, shape, false);
            }
        }
        // f32 sibling of the f64 fast path (the asymmetric-dtype gap): the tape mul_scalar maps
        // `value * (scalar as f32)` in f32 SERIALLY. For no-grad contiguous f32, borrow and
        // multiply in parallel — BIT-IDENTICAL (same `value * (scalar as f32)`, f32-native, the
        // exact op the tape performs). frankentorch-specf32.
        if !self.tensor_requires_grad(input)? && self.tensor_dtype(input)? == DType::F32 {
            let built = {
                let it = self.tensor_tape.tensor(input)?;
                if it.meta().is_contiguous() {
                    use rayon::prelude::*;
                    let xd = it.contiguous_values_f32()?;
                    #[allow(clippy::cast_possible_truncation)]
                    let s = scalar as f32;
                    let out: Vec<f32> = if xd.len() >= PARALLEL_ELEMENTWISE_MIN {
                        xd.par_iter().map(|&x| x * s).collect()
                    } else {
                        xd.iter().map(|&x| x * s).collect()
                    };
                    Some(out)
                } else {
                    None
                }
            };
            if let Some(out) = built {
                let shape = self.tensor_shape(input)?;
                return self.tensor_variable_f32(out, shape, false);
            }
        }
        let (out, event) = self.tensor_tape.mul_scalar(input, scalar)?;
        self.record_tensor_scalar_operation(&event);
        Ok(out)
    }

    pub fn tensor_sub(
        &mut self,
        lhs: TensorNodeId,
        rhs: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        if self.complex_grad_pair(lhs, rhs)? {
            // (ar+i·ai) − (br+i·bi) = (ar−br) + i·(ai−bi).
            let ar = self.tensor_real(lhs)?;
            let ai = self.tensor_imag(lhs)?;
            let br = self.tensor_real(rhs)?;
            let bi = self.tensor_imag(rhs)?;
            let re = self.tensor_sub(ar, br)?;
            let im = self.tensor_sub(ai, bi)?;
            return self.tensor_complex(re, im);
        }
        if let Some(out) = self.try_lastdim_bcast(lhs, rhs, BcastBinOp::Sub)? {
            return Ok(out);
        }
        if let Some(out) = self.try_rowscalar_bcast(lhs, rhs, BcastBinOp::Sub)? {
            return Ok(out);
        }
        if let Some(out) = self.try_fullscalar_bcast(lhs, rhs, BcastBinOp::Sub)? {
            return Ok(out);
        }
        if let Some(out) = self.try_bcast_tile_binop(lhs, rhs, BcastBinOp::Sub)? {
            return Ok(out);
        }
        let (out, event) = self.tensor_tape.sub(lhs, rhs, self.mode())?;
        self.record_tensor_operation(&event);
        Ok(out)
    }

    pub fn tensor_div(
        &mut self,
        lhs: TensorNodeId,
        rhs: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        if self.complex_grad_pair(lhs, rhs)? {
            // a/b = a·conj(b)/|b|²:
            //   re = (ar·br + ai·bi)/(br²+bi²), im = (ai·br − ar·bi)/(br²+bi²).
            // Composed from real ops -> correct Wirtinger gradient via the bridge.
            let ar = self.tensor_real(lhs)?;
            let ai = self.tensor_imag(lhs)?;
            let br = self.tensor_real(rhs)?;
            let bi = self.tensor_imag(rhs)?;
            let brbr = self.tensor_mul(br, br)?;
            let bibi = self.tensor_mul(bi, bi)?;
            let denom = self.tensor_add(brbr, bibi)?;
            let arbr = self.tensor_mul(ar, br)?;
            let aibi = self.tensor_mul(ai, bi)?;
            let re_num = self.tensor_add(arbr, aibi)?;
            let aibr = self.tensor_mul(ai, br)?;
            let arbi = self.tensor_mul(ar, bi)?;
            let im_num = self.tensor_sub(aibr, arbi)?;
            let re = self.tensor_div(re_num, denom)?;
            let im = self.tensor_div(im_num, denom)?;
            return self.tensor_complex(re, im);
        }
        if let Some(out) = self.try_lastdim_bcast(lhs, rhs, BcastBinOp::Div)? {
            return Ok(out);
        }
        if let Some(out) = self.try_rowscalar_bcast(lhs, rhs, BcastBinOp::Div)? {
            return Ok(out);
        }
        if let Some(out) = self.try_fullscalar_bcast(lhs, rhs, BcastBinOp::Div)? {
            return Ok(out);
        }
        if let Some(out) = self.try_bcast_tile_binop(lhs, rhs, BcastBinOp::Div)? {
            return Ok(out);
        }
        let (out, event) = self.tensor_tape.div(lhs, rhs, self.mode())?;
        self.record_tensor_operation(&event);
        Ok(out)
    }

    pub fn tensor_matmul(
        &mut self,
        lhs: TensorNodeId,
        rhs: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        if self.complex_grad_pair(lhs, rhs)? {
            // Complex matmul: (Ar+iAi)@(Br+iBi) = (Ar@Br − Ai@Bi) + i(Ar@Bi + Ai@Br).
            // Composed from the differentiable real tensor_matmul (which handles all
            // torch shape-polymorphism) + real/imag/complex bridge, so the gradient
            // flows correctly (the real-elementwise tape matmul backward reads only
            // the real part and is silently wrong for complex). frankentorch-0pbll.
            let ar = self.tensor_real(lhs)?;
            let ai = self.tensor_imag(lhs)?;
            let br = self.tensor_real(rhs)?;
            let bi = self.tensor_imag(rhs)?;
            let arbr = self.tensor_matmul(ar, br)?;
            let aibi = self.tensor_matmul(ai, bi)?;
            let cr = self.tensor_sub(arbr, aibi)?;
            let arbi = self.tensor_matmul(ar, bi)?;
            let aibr = self.tensor_matmul(ai, br)?;
            let ci = self.tensor_add(arbi, aibr)?;
            return self.tensor_complex(cr, ci);
        }
        let sa = self.tensor_shape(lhs)?;
        let sb = self.tensor_shape(rhs)?;
        let (na, nb) = (sa.len(), sb.len());
        // 2-D · 2-D: the existing tape primitive (unchanged — zero regression).
        if na == 2 && nb == 2 {
            let (out, event) = self.tensor_tape.matmul(lhs, rhs, self.mode())?;
            self.record_tensor_operation(&event);
            return Ok(out);
        }
        // torch.matmul shape-polymorphism (frankentorch-6tzgt). The tape MatMul
        // only accepts 2-D; replicate torch's full contract by composing
        // autograd-aware ops so gradients flow through the reshapes/bmm.
        if na == 0 || nb == 0 {
            return Err(Self::incompatible_tensor_args(
                "matmul: both arguments must be at least 1-D",
            ));
        }
        // 1-D · 1-D -> dot product (scalar).
        if na == 1 && nb == 1 {
            return self.tensor_dot(lhs, rhs);
        }
        // Promote a leading/trailing 1 onto 1-D operands (torch: prepend for the
        // left, append for the right), and remember to remove it from the result.
        let a_prepended = na == 1;
        let b_appended = nb == 1;
        let a2 = if a_prepended {
            self.tensor_unsqueeze(lhs, 0)?
        } else {
            lhs
        };
        let b2 = if b_appended {
            self.tensor_unsqueeze(rhs, 1)? // [k] -> [k, 1]
        } else {
            rhs
        };
        let sa2 = self.tensor_shape(a2)?;
        let sb2 = self.tensor_shape(b2)?;
        let (la, lb) = (sa2.len(), sb2.len());
        let (m, k) = (sa2[la - 2], sa2[la - 1]);
        let (k2, n) = (sb2[lb - 2], sb2[lb - 1]);
        if k != k2 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: sa.clone(),
                    rhs: sb.clone(),
                },
            )));
        }
        // Fast path: 3-D @ 3-D with an identical, already-aligned batch dim (the common batched-matmul
        // case, e.g. [B,m,k] @ [B,k,n]). The general path below would route through tensor_broadcast_to
        // + tensor_reshape, which are no-ops here yet cost ~47ms for B=100000 tiny planes (broadcast/
        // reshape dominate: a [100000,4,4] matmul was 51ms total vs 3.4ms for tensor_bmm alone). Calling
        // tensor_bmm directly is bit-identical (the skipped broadcast/reshape are identity) and ~15x
        // faster. frankentorch-matmul-bmm-fastpath. (BlackThrush)
        if la == 3 && lb == 3 && !a_prepended && !b_appended && sa2[0] == sb2[0] {
            return self.tensor_bmm(a2, b2);
        }
        // N-D (≥4-D) matched-batch no-grad fast path: the general path below routes through
        // tensor_broadcast_to + tensor_reshape, which MATERIALIZE full copies (~20ms/25MB, no zero-copy
        // views) even when they are no-ops here — making a [10000,8,16,16] matmul ~28x slower than torch.
        // For identical (already-aligned) batch dims we call the bmm kernel DIRECTLY on the contiguous
        // storage (leading dims flattened to one batch), bypassing both. Bit-identical (same kernel the
        // general path calls). No-grad contiguous f64/f32 only. frankentorch-matmul-bmm-fastpath.
        // (BlackThrush, f32 reopened by frankentorch-dxjn9 after the f32 bmm kernel became batch-parallel.)
        let a_dtype = self.tensor_dtype(a2)?;
        let b_dtype = self.tensor_dtype(b2)?;
        if la >= 4
            && lb == la
            && !a_prepended
            && !b_appended
            && sa2[..la - 2] == sb2[..lb - 2]
            && a_dtype == b_dtype
            && matches!(a_dtype, DType::F64 | DType::F32)
            && !self.tensor_requires_grad(a2)?
            && !self.tensor_requires_grad(b2)?
            && self.tensor_tape.tensor(a2)?.meta().is_contiguous()
            && self.tensor_tape.tensor(b2)?.meta().is_contiguous()
        {
            let bsz: usize = sa2[..la - 2].iter().product();
            let mut out_shape = sa2[..la - 2].to_vec();
            out_shape.push(m);
            out_shape.push(n);
            return match a_dtype {
                DType::F64 => {
                    let am = TensorMeta::from_shape(vec![bsz, m, k], DType::F64, Device::Cpu);
                    let bmeta = TensorMeta::from_shape(vec![bsz, k, n], DType::F64, Device::Cpu);
                    let out = {
                        let av = self.tensor_tape.tensor(a2)?.contiguous_values()?;
                        let bv = self.tensor_tape.tensor(b2)?.contiguous_values()?;
                        ft_kernel_cpu::bmm_tensor_contiguous_f64(av, bv, &am, &bmeta).map_err(
                            |e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)),
                        )?
                    };
                    self.tensor_variable(out, out_shape, false)
                }
                DType::F32 => {
                    let am = TensorMeta::from_shape(vec![bsz, m, k], DType::F32, Device::Cpu);
                    let bmeta = TensorMeta::from_shape(vec![bsz, k, n], DType::F32, Device::Cpu);
                    let out = {
                        let av = self.tensor_tape.tensor(a2)?.contiguous_values_f32()?;
                        let bv = self.tensor_tape.tensor(b2)?.contiguous_values_f32()?;
                        ft_kernel_cpu::bmm_tensor_contiguous_f32(av, bv, &am, &bmeta).map_err(
                            |e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)),
                        )?
                    };
                    self.tensor_variable_f32(out, out_shape, false)
                }
                _ => unreachable!("N-D matmul fast path is gated to f64/f32"),
            };
        }
        // ≥4-D matched-batch GRAD fast path: the general path below broadcasts (MATERIALIZES copies,
        // identity for matched batch) and its backward is slow — the 4-D matmul GRAD was ~100x the
        // forward. For matched batch dims, skip the broadcast and route through grad-aware reshape +
        // tensor_bmm (which uses the PARALLEL bmm backward) + reshape. Bit-identical (broadcast is a
        // no-op here). Covers the grad case (no-grad ≥4-D returned above via the direct kernel).
        // frankentorch matmul-4d-grad-fastpath.
        if la >= 4 && lb == la && !a_prepended && !b_appended && sa2[..la - 2] == sb2[..lb - 2] {
            let bsz: usize = sa2[..la - 2].iter().product();
            let a3 = self.tensor_reshape(a2, vec![bsz, m, k])?;
            let b3 = self.tensor_reshape(b2, vec![bsz, k, n])?;
            let r3 = self.tensor_bmm(a3, b3)?; // [bsz, m, n], parallel bmm + parallel bmm backward
            let mut out_shape = sa2[..la - 2].to_vec();
            out_shape.push(m);
            out_shape.push(n);
            return self.tensor_reshape(r3, out_shape);
        }
        // Broadcast the batch dims (everything but the trailing matrix dims).
        let batch = Self::broadcast_shape(&sa2[..la - 2], &sb2[..lb - 2])?;
        let mut a_target = batch.clone();
        a_target.extend_from_slice(&[m, k]);
        let mut b_target = batch.clone();
        b_target.extend_from_slice(&[k, n]);
        let a_exp = self.tensor_broadcast_to(a2, a_target)?;
        let b_exp = self.tensor_broadcast_to(b2, b_target)?;
        let bsz: usize = batch.iter().product();
        let a3 = self.tensor_reshape(a_exp, vec![bsz, m, k])?;
        let b3 = self.tensor_reshape(b_exp, vec![bsz, k, n])?;
        let r3 = self.tensor_bmm(a3, b3)?; // [bsz, m, n]
        let mut out_shape = batch;
        out_shape.extend_from_slice(&[m, n]);
        let out = self.tensor_reshape(r3, out_shape)?;
        // Un-promote (at most one of these fires; 1-D·1-D went to dot above).
        if a_prepended {
            let d = self.tensor_shape(out)?.len() - 2; // the size-1 m dim
            return self.tensor_squeeze(out, d);
        }
        if b_appended {
            let d = self.tensor_shape(out)?.len() - 1; // the size-1 n dim
            return self.tensor_squeeze(out, d);
        }
        Ok(out)
    }

    /// Alias for tensor_matmul. Equivalent to torch.mm (matrix multiplication).
    pub fn tensor_mm(
        &mut self,
        lhs: TensorNodeId,
        rhs: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_matmul(lhs, rhs)
    }

    pub fn tensor_dot(
        &mut self,
        lhs: TensorNodeId,
        rhs: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let (out, event) = self.tensor_tape.dot(lhs, rhs, self.mode())?;
        self.record_tensor_operation(&event);
        Ok(out)
    }

    /// Vector dot product of two 1D tensors.
    ///
    /// Equivalent to `torch.vdot(input, other)`. Both inputs must be 1D
    /// with the same number of elements. For complex tensors this would
    /// conjugate the first argument, but for real tensors it is
    /// equivalent to `tensor_dot`.
    pub fn tensor_vdot(
        &mut self,
        input: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape_a = self.tensor_shape(input)?;
        let shape_b = self.tensor_shape(other)?;

        if shape_a.len() != 1 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "vdot: input must be 1-D",
                },
            )));
        }
        if shape_b.len() != 1 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "vdot: other must be 1-D",
                },
            )));
        }
        if shape_a[0] != shape_b[0] {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "vdot: input and other must have the same number of elements",
                },
            )));
        }

        self.tensor_dot(input, other)
    }

    pub fn tensor_outer(
        &mut self,
        lhs: TensorNodeId,
        rhs: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let (out, event) = self.tensor_tape.outer(lhs, rhs, self.mode())?;
        self.record_tensor_operation(&event);
        Ok(out)
    }

    /// Alias for tensor_outer. Equivalent to torch.ger (generalized outer product).
    pub fn tensor_ger(
        &mut self,
        lhs: TensorNodeId,
        rhs: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_outer(lhs, rhs)
    }

    pub fn tensor_bmm(
        &mut self,
        lhs: TensorNodeId,
        rhs: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let (out, event) = self.tensor_tape.bmm(lhs, rhs, self.mode())?;
        self.record_tensor_operation(&event);
        Ok(out)
    }

    /// Batch matrix multiply with add: `out = beta * input + alpha * (batch1 @ batch2)`.
    ///
    /// Equivalent to `torch.baddbmm(input, batch1, batch2, beta=1, alpha=1)`.
    /// `batch1`: `[B, n, m]`, `batch2`: `[B, m, p]`, `input`: broadcastable to `[B, n, p]`.
    pub fn tensor_baddbmm(
        &mut self,
        input: TensorNodeId,
        batch1: TensorNodeId,
        batch2: TensorNodeId,
        beta: f64,
        alpha: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let bmm_result = self.tensor_bmm(batch1, batch2)?;
        let out_shape = self.tensor_shape(bmm_result)?;

        // Scale bmm result by alpha
        let alpha_tensor = self.full(out_shape.clone(), alpha, false)?;
        let scaled_bmm = self.tensor_mul(bmm_result, alpha_tensor)?;

        // Scale input by beta and add
        let input_expanded = self.tensor_expand(input, out_shape.clone())?;
        let beta_tensor = self.full(out_shape, beta, false)?;
        let scaled_input = self.tensor_mul(input_expanded, beta_tensor)?;

        self.tensor_add(scaled_input, scaled_bmm)
    }

    /// Batch matrix multiply reduced to 2D with add: `out = beta * M + alpha * sum_b(batch1[b] @ batch2[b])`.
    ///
    /// Equivalent to `torch.addbmm(M, batch1, batch2, beta=1, alpha=1)`.
    /// Sums the batch matrix products and adds to `M`.
    pub fn tensor_addbmm(
        &mut self,
        input: TensorNodeId,
        batch1: TensorNodeId,
        batch2: TensorNodeId,
        beta: f64,
        alpha: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let bmm_result = self.tensor_bmm(batch1, batch2)?;
        // Sum over batch dimension (dim 0)
        let summed = self.tensor_sum_dim(bmm_result, 0)?;
        let out_shape = self.tensor_shape(summed)?;

        let alpha_tensor = self.full(out_shape.clone(), alpha, false)?;
        let scaled = self.tensor_mul(summed, alpha_tensor)?;

        let input_expanded = self.tensor_expand(input, out_shape.clone())?;
        let beta_tensor = self.full(out_shape, beta, false)?;
        let scaled_input = self.tensor_mul(input_expanded, beta_tensor)?;

        self.tensor_add(scaled_input, scaled)
    }

    /// Scaled dot-product attention (PyTorch 2.0+).
    ///
    /// Equivalent to `torch.nn.functional.scaled_dot_product_attention(query, key, value, attn_mask, dropout_p, is_causal)`.
    ///
    /// Computes: `softmax(Q @ K^T / sqrt(d_k) + mask) @ V`
    ///
    /// `query`: `[*, L, E]`, `key`: `[*, S, E]`, `value`: `[*, S, Ev]`.
    /// Returns: `[*, L, Ev]`.
    pub fn scaled_dot_product_attention(
        &mut self,
        query: TensorNodeId,
        key: TensorNodeId,
        value: TensorNodeId,
        attn_mask: Option<TensorNodeId>,
        dropout_p: f64,
        is_causal: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        if is_causal && attn_mask.is_some() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "scaled_dot_product_attention: attn_mask cannot be combined with is_causal",
                },
            )));
        }
        let q_shape = self.tensor_shape(query)?;
        let k_shape = self.tensor_shape(key)?;

        if q_shape.len() < 2 || k_shape.len() < 2 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "scaled_dot_product_attention: Q/K must be at least 2-D",
                },
            )));
        }
        if !(0.0..=1.0).contains(&dropout_p) {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "scaled_dot_product_attention: dropout_p must be in [0, 1]",
                },
            )));
        }

        let d_k = q_shape.last().copied().ok_or(AutogradError::Dispatch(
            ft_dispatch::DispatchError::Key(ft_dispatch::DispatchKeyError::IncompatibleSet {
                reason: "scaled_dot_product_attention: missing head dimension",
            }),
        ))?;
        if d_k == 0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "scaled_dot_product_attention: head dimension must be non-zero",
                },
            )));
        }
        let scale = 1.0 / (d_k as f64).sqrt();

        // Fused no-grad SDPA fast path (f64/f32, batched, no dropout, no explicit
        // attn_mask): a block-row flash-attention kernel that never materialises
        // the [.., seq_q, seq_k] score matrix, the scale tensor, or the softmax
        // intermediate. Grad / masked / other dtype / 2-D fall through unchanged.
        let sdpa_dtype = self.tensor_dtype(query)?;
        if k_shape.len() >= 3
            && q_shape.len() == k_shape.len()
            && dropout_p == 0.0
            && attn_mask.is_none()
            && !self.tensor_tape.tensor_requires_grad(query)?
            && !self.tensor_tape.tensor_requires_grad(key)?
            && !self.tensor_tape.tensor_requires_grad(value)?
            && (sdpa_dtype == DType::F64 || sdpa_dtype == DType::F32)
            && self.tensor_dtype(key)? == sdpa_dtype
            && self.tensor_dtype(value)? == sdpa_dtype
        {
            let v_shape = self.tensor_shape(value)?;
            if v_shape.len() == q_shape.len() {
                let nd = q_shape.len();
                let seq_q = q_shape[nd - 2];
                let d_k_dim = q_shape[nd - 1];
                let seq_k = k_shape[nd - 2];
                let d_v = v_shape[nd - 1];
                let q_bh: usize = q_shape[..nd - 2].iter().product();
                let k_bh: usize = k_shape[..nd - 2].iter().product();
                let v_bh: usize = v_shape[..nd - 2].iter().product();
                if q_bh == k_bh
                    && q_bh == v_bh
                    && k_shape[nd - 1] == d_k_dim
                    && v_shape[nd - 2] == seq_k
                    && q_bh > 0
                    && seq_q > 0
                    && seq_k > 0
                    && d_k_dim > 0
                    && d_v > 0
                {
                    let mut out_shape = q_shape.clone();
                    out_shape[nd - 1] = d_v;
                    if sdpa_dtype == DType::F64 {
                        // Borrow q/k/v straight into the kernel: sdpa_forward_f64 takes &[f64], so the
                        // former 3x tensor_values clones (12 MB at [16,512,64]) were dead copies — they
                        // dominated the no-grad inference API overhead. Bit-exact (same data); borrows
                        // are scoped so tensor_variable(out) can take &mut self afterwards. (BlackThrush)
                        let out = {
                            let qv = self.tensor_tape.tensor(query)?.contiguous_values()?;
                            let kv = self.tensor_tape.tensor(key)?.contiguous_values()?;
                            let vv = self.tensor_tape.tensor(value)?.contiguous_values()?;
                            ft_kernel_cpu::sdpa_forward_f64(
                                qv, kv, vv, q_bh, seq_q, seq_k, d_k_dim, d_v, scale, is_causal,
                            )
                        };
                        return self.tensor_variable(out, out_shape, false);
                    }
                    // f32
                    // Borrow f32 q/k/v into the kernel (sdpa_forward_f32 takes &[f32]) — same dead-clone
                    // elision as the f64 branch; bit-exact, borrows scoped. (BlackThrush)
                    let out = {
                        let qv = self.tensor_tape.tensor(query)?.contiguous_values_f32()?;
                        let kv = self.tensor_tape.tensor(key)?.contiguous_values_f32()?;
                        let vv = self.tensor_tape.tensor(value)?.contiguous_values_f32()?;
                        ft_kernel_cpu::sdpa_forward_f32(
                            qv,
                            kv,
                            vv,
                            q_bh,
                            seq_q,
                            seq_k,
                            d_k_dim,
                            d_v,
                            scale as f32,
                            is_causal,
                        )
                    };
                    return self.tensor_tape.leaf_f32(out, out_shape, false);
                }
            }
        }

        // Fused no-grad MASKED SDPA fast path (f64, batched, additive attn_mask, no dropout,
        // not causal): flash kernel with the mask folded into the softmax — avoids the
        // bmm+softmax+bmm score materialization the explicit-mask path otherwise falls to (the
        // same f64 gap PyTorch CPU masked SDPA has). Guards all inputs contiguous so any
        // broadcast/view mask cleanly FALLS THROUGH to the composite. frankentorch-sdpamask. (BlackThrush)
        if let Some(mask_id) = attn_mask {
            if !is_causal
                && dropout_p == 0.0
                && k_shape.len() >= 3
                && q_shape.len() == k_shape.len()
                && self.tensor_dtype(query)? == DType::F64
                && self.tensor_dtype(key)? == DType::F64
                && self.tensor_dtype(value)? == DType::F64
                && self.tensor_dtype(mask_id)? == DType::F64
                && !self.tensor_tape.tensor_requires_grad(query)?
                && !self.tensor_tape.tensor_requires_grad(key)?
                && !self.tensor_tape.tensor_requires_grad(value)?
                && !self.tensor_tape.tensor_requires_grad(mask_id)?
                && self.tensor_tape.tensor(query)?.meta().is_contiguous()
                && self.tensor_tape.tensor(key)?.meta().is_contiguous()
                && self.tensor_tape.tensor(value)?.meta().is_contiguous()
                && self.tensor_tape.tensor(mask_id)?.meta().is_contiguous()
            {
                let v_shape = self.tensor_shape(value)?;
                let m_shape = self.tensor_shape(mask_id)?;
                if v_shape.len() == q_shape.len() {
                    let nd = q_shape.len();
                    let seq_q = q_shape[nd - 2];
                    let d_k_dim = q_shape[nd - 1];
                    let seq_k = k_shape[nd - 2];
                    let d_v = v_shape[nd - 1];
                    let q_bh: usize = q_shape[..nd - 2].iter().product();
                    let k_bh: usize = k_shape[..nd - 2].iter().product();
                    let v_bh: usize = v_shape[..nd - 2].iter().product();
                    // additive mask must be contiguous [seq_q, seq_k] (shared) or [q_bh, seq_q, seq_k].
                    let mask_bh_stride =
                        if m_shape.len() == 2 && m_shape[0] == seq_q && m_shape[1] == seq_k {
                            Some(0usize)
                        } else if m_shape.len() == 3
                            && m_shape[0] == q_bh
                            && m_shape[1] == seq_q
                            && m_shape[2] == seq_k
                        {
                            Some(seq_q * seq_k)
                        } else {
                            None
                        };
                    if let Some(mbs) = mask_bh_stride
                        && q_bh == k_bh
                        && q_bh == v_bh
                        && k_shape[nd - 1] == d_k_dim
                        && v_shape[nd - 2] == seq_k
                        && q_bh > 0
                        && seq_q > 0
                        && seq_k > 0
                        && d_k_dim > 0
                        && d_v > 0
                    {
                        let mut out_shape = q_shape.clone();
                        out_shape[nd - 1] = d_v;
                        let out = {
                            let qv = self.tensor_tape.tensor(query)?.contiguous_values()?;
                            let kv = self.tensor_tape.tensor(key)?.contiguous_values()?;
                            let vv = self.tensor_tape.tensor(value)?.contiguous_values()?;
                            let mv = self.tensor_tape.tensor(mask_id)?.contiguous_values()?;
                            ft_kernel_cpu::sdpa_forward_masked_f64(
                                qv, kv, vv, q_bh, seq_q, seq_k, d_k_dim, d_v, scale, mv, mbs,
                            )
                        };
                        return self.tensor_variable(out, out_shape, false);
                    }
                }
            }
        }

        // Fused GRAD MASKED SDPA fast path (f64): custom autograd op = flash masked forward +
        // sdpa_backward_masked_f64 (recomputes P with the mask). Training with an additive mask
        // (padding) otherwise composes through bmm+softmax+bmm. Mask is constant -> captured by
        // value into both closures. frankentorch-sdpamask. (BlackThrush)
        if let Some(mask_id) = attn_mask {
            let grad_needed_m = self.tensor_tape.tensor_requires_grad(query)?
                || self.tensor_tape.tensor_requires_grad(key)?
                || self.tensor_tape.tensor_requires_grad(value)?;
            if grad_needed_m
                && !is_causal
                && dropout_p == 0.0
                && k_shape.len() >= 3
                && q_shape.len() == k_shape.len()
                && self.tensor_dtype(query)? == DType::F64
                && self.tensor_dtype(key)? == DType::F64
                && self.tensor_dtype(value)? == DType::F64
                && self.tensor_dtype(mask_id)? == DType::F64
                && !self.tensor_tape.tensor_requires_grad(mask_id)?
                && self.tensor_tape.tensor(mask_id)?.meta().is_contiguous()
            {
                let v_shape = self.tensor_shape(value)?;
                let m_shape = self.tensor_shape(mask_id)?;
                if v_shape.len() == q_shape.len() {
                    let nd = q_shape.len();
                    let seq_q = q_shape[nd - 2];
                    let d_k_dim = q_shape[nd - 1];
                    let seq_k = k_shape[nd - 2];
                    let d_v = v_shape[nd - 1];
                    let q_bh: usize = q_shape[..nd - 2].iter().product();
                    let k_bh: usize = k_shape[..nd - 2].iter().product();
                    let v_bh: usize = v_shape[..nd - 2].iter().product();
                    let mask_bh_stride =
                        if m_shape.len() == 2 && m_shape[0] == seq_q && m_shape[1] == seq_k {
                            Some(0usize)
                        } else if m_shape.len() == 3
                            && m_shape[0] == q_bh
                            && m_shape[1] == seq_q
                            && m_shape[2] == seq_k
                        {
                            Some(seq_q * seq_k)
                        } else {
                            None
                        };
                    if let Some(mbs) = mask_bh_stride
                        && q_bh == k_bh
                        && q_bh == v_bh
                        && k_shape[nd - 1] == d_k_dim
                        && v_shape[nd - 2] == seq_k
                        && q_bh > 0
                        && seq_q > 0
                        && seq_k > 0
                        && d_k_dim > 0
                        && d_v > 0
                    {
                        let mask_fwd = self.tensor_values(mask_id)?;
                        let mask_bwd = mask_fwd.clone();
                        let qsh = q_shape.clone();
                        // Borrowed-inputs autograd (mirror of the tensor_* masked grad path):
                        // sdpa_backward_masked_f64 re-reads q/k/v from the live leaves instead of
                        // cloning all three into the ctx each step. Mask is captured by value into
                        // both closures (small [seq,seq], constant — no grad). frankentorch-3jmy3.
                        return self.tensor_apply_function_f64_borrowed_inputs(
                            &[query, key, value],
                            move |_ctx, ins| {
                                let (qv, _) = ins[0];
                                let (kv, _) = ins[1];
                                let (vv, _) = ins[2];
                                let out = ft_kernel_cpu::sdpa_forward_masked_f64(
                                    qv, kv, vv, q_bh, seq_q, seq_k, d_k_dim, d_v, scale, &mask_fwd,
                                    mbs,
                                );
                                let mut osh = qsh.clone();
                                osh[nd - 1] = d_v;
                                Ok((out, osh))
                            },
                            move |_ctx, grad_outputs, borrowed| {
                                let dout = grad_outputs[0];
                                let (dq, dk, dv) = ft_kernel_cpu::sdpa_backward_masked_f64(
                                    borrowed[0].0,
                                    borrowed[1].0,
                                    borrowed[2].0,
                                    dout,
                                    q_bh,
                                    seq_q,
                                    seq_k,
                                    d_k_dim,
                                    d_v,
                                    scale,
                                    &mask_bwd,
                                    mbs,
                                );
                                Ok(vec![Some(dq), Some(dk), Some(dv)])
                            },
                        );
                    }
                }
            }
        }

        // Fused GRAD SDPA fast path (f64, batched, no dropout, no explicit
        // attn_mask): a custom autograd op whose forward is the fused flash-
        // attention kernel and whose backward (sdpa_backward_f64) recomputes P per
        // block and emits dQ/dK/dV via gemms — no [.., seq, seq] score / softmax
        // tape nodes. Same gradients as the bmm+softmax+bmm graph, to tolerance.
        let grad_needed = self.tensor_tape.tensor_requires_grad(query)?
            || self.tensor_tape.tensor_requires_grad(key)?
            || self.tensor_tape.tensor_requires_grad(value)?;
        if grad_needed
            && k_shape.len() >= 3
            && q_shape.len() == k_shape.len()
            && dropout_p == 0.0
            && attn_mask.is_none()
            && self.tensor_dtype(query)? == DType::F64
            && self.tensor_dtype(key)? == DType::F64
            && self.tensor_dtype(value)? == DType::F64
        {
            let v_shape = self.tensor_shape(value)?;
            if v_shape.len() == q_shape.len() {
                let nd = q_shape.len();
                let seq_q = q_shape[nd - 2];
                let d_k_dim = q_shape[nd - 1];
                let seq_k = k_shape[nd - 2];
                let d_v = v_shape[nd - 1];
                let q_bh: usize = q_shape[..nd - 2].iter().product();
                let k_bh: usize = k_shape[..nd - 2].iter().product();
                let v_bh: usize = v_shape[..nd - 2].iter().product();
                if q_bh == k_bh
                    && q_bh == v_bh
                    && k_shape[nd - 1] == d_k_dim
                    && v_shape[nd - 2] == seq_k
                    && q_bh > 0
                    && seq_q > 0
                    && seq_k > 0
                    && d_k_dim > 0
                    && d_v > 0
                {
                    let causal = is_causal;
                    let qsh = q_shape.clone();
                    // Borrowed-inputs autograd (mirror of the tensor_scaled_dot_product_attention
                    // entry, frankentorch-3jmy3): sdpa_backward_f64 re-reads q/k/v from the live
                    // leaves instead of cloning all three large tensors into the ctx each step.
                    // The backward recomputes the attention internally, so nothing derived needs
                    // saving. Drops 3 full-size clones per training step on the dominant op.
                    return self.tensor_apply_function_f64_borrowed_inputs(
                        &[query, key, value],
                        move |_ctx, ins| {
                            let (qv, _) = ins[0];
                            let (kv, _) = ins[1];
                            let (vv, _) = ins[2];
                            let out = ft_kernel_cpu::sdpa_forward_f64(
                                qv, kv, vv, q_bh, seq_q, seq_k, d_k_dim, d_v, scale, causal,
                            );
                            let mut osh = qsh.clone();
                            osh[nd - 1] = d_v;
                            Ok((out, osh))
                        },
                        move |_ctx, grad_outputs, borrowed| {
                            let dout = grad_outputs[0];
                            let (dq, dk, dv) = ft_kernel_cpu::sdpa_backward_f64(
                                borrowed[0].0,
                                borrowed[1].0,
                                borrowed[2].0,
                                dout,
                                q_bh,
                                seq_q,
                                seq_k,
                                d_k_dim,
                                d_v,
                                scale,
                                causal,
                            );
                            Ok(vec![Some(dq), Some(dk), Some(dv)])
                        },
                    );
                }
            }
        }

        // Fused GRAD SDPA fast path (f32): same as the f64 path via the f32-output
        // custom op (frankentorch-48w0b) — native f32 attention training (forward
        // sdpa_forward_f32, backward sdpa_backward_f32), avoiding the composed
        // bmm+softmax+bmm path's [.., seq, seq] score/softmax materializations.
        if grad_needed
            && k_shape.len() >= 3
            && q_shape.len() == k_shape.len()
            && dropout_p == 0.0
            && attn_mask.is_none()
            && self.tensor_dtype(query)? == DType::F32
            && self.tensor_dtype(key)? == DType::F32
            && self.tensor_dtype(value)? == DType::F32
        {
            let v_shape = self.tensor_shape(value)?;
            if v_shape.len() == q_shape.len() {
                let nd = q_shape.len();
                let seq_q = q_shape[nd - 2];
                let d_k_dim = q_shape[nd - 1];
                let seq_k = k_shape[nd - 2];
                let d_v = v_shape[nd - 1];
                let q_bh: usize = q_shape[..nd - 2].iter().product();
                let k_bh: usize = k_shape[..nd - 2].iter().product();
                let v_bh: usize = v_shape[..nd - 2].iter().product();
                if q_bh == k_bh
                    && q_bh == v_bh
                    && k_shape[nd - 1] == d_k_dim
                    && v_shape[nd - 2] == seq_k
                    && q_bh > 0
                    && seq_q > 0
                    && seq_k > 0
                    && d_k_dim > 0
                    && d_v > 0
                {
                    let causal = is_causal;
                    let qsh = q_shape.clone();
                    let scale_f = scale as f32;
                    return self.tensor_apply_function_f32_output_borrowed_inputs(
                        &[query, key, value],
                        move |_ctx, ins| {
                            let (qv, _) = ins[0];
                            let (kv, _) = ins[1];
                            let (vv, _) = ins[2];
                            let out = ft_kernel_cpu::sdpa_forward_f32(
                                qv, kv, vv, q_bh, seq_q, seq_k, d_k_dim, d_v, scale_f, causal,
                            );
                            let mut osh = qsh.clone();
                            osh[nd - 1] = d_v;
                            Ok((out, osh))
                        },
                        move |_ctx, grad_outputs, borrowed| {
                            let (dq, dk, dv) = if Self::is_exact_all_ones_f64(grad_outputs[0]) {
                                ft_kernel_cpu::sdpa_backward_f32_unit_dout(
                                    borrowed[0].0,
                                    borrowed[1].0,
                                    borrowed[2].0,
                                    q_bh,
                                    seq_q,
                                    seq_k,
                                    d_k_dim,
                                    d_v,
                                    scale_f,
                                    causal,
                                )
                            } else {
                                let dout: Vec<f32> =
                                    grad_outputs[0].iter().map(|&v| v as f32).collect();
                                ft_kernel_cpu::sdpa_backward_f32(
                                    borrowed[0].0,
                                    borrowed[1].0,
                                    borrowed[2].0,
                                    &dout,
                                    q_bh,
                                    seq_q,
                                    seq_k,
                                    d_k_dim,
                                    d_v,
                                    scale_f,
                                    causal,
                                )
                            };
                            Ok(vec![
                                Some(dq.iter().map(|&v| v as f64).collect::<Vec<f64>>()),
                                Some(dk.iter().map(|&v| v as f64).collect::<Vec<f64>>()),
                                Some(dv.iter().map(|&v| v as f64).collect::<Vec<f64>>()),
                            ])
                        },
                    );
                }
            }
        }

        // Q @ K^T — use bmm for 3D batched inputs, matmul for 2D
        let ndim = k_shape.len();
        let key_t = self.tensor_transpose(key, ndim - 2, ndim - 1)?;
        let attn_weights = if ndim >= 3 {
            self.tensor_bmm(query, key_t)?
        } else {
            self.tensor_matmul(query, key_t)?
        };

        // Scale
        let aw_shape = self.tensor_shape(attn_weights)?;
        let softmax_dim = aw_shape.len() - 1;
        let scale_tensor = self.full(aw_shape.clone(), scale, false)?;
        let scaled = self.tensor_mul(attn_weights, scale_tensor)?;

        // Apply causal mask if requested
        let masked = if is_causal {
            let l = aw_shape[aw_shape.len() - 2];
            let s = aw_shape[aw_shape.len() - 1];
            if l == 0 || s == 0 {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "scaled_dot_product_attention: sequence length must be non-zero",
                    },
                )));
            }
            let total = Self::checked_shape_numel(
                &aw_shape,
                "scaled_dot_product_attention: attention shape volume overflow",
            )?;
            let Some(batch_area) = l.checked_mul(s) else {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "scaled_dot_product_attention: attention shape volume overflow",
                    },
                )));
            };
            let batch_count = total / batch_area;
            let mut mask_data = Vec::with_capacity(total);
            for _ in 0..batch_count {
                for i in 0..l {
                    for j in 0..s {
                        if j > i {
                            mask_data.push(f64::NEG_INFINITY);
                        } else {
                            mask_data.push(0.0);
                        }
                    }
                }
            }
            let causal_mask = self.tensor_variable(mask_data, aw_shape, false)?;
            self.tensor_add(scaled, causal_mask)?
        } else if let Some(mask) = attn_mask {
            self.tensor_add(scaled, mask)?
        } else {
            scaled
        };

        // Softmax along last dim
        let softmaxed = self.tensor_softmax(masked, softmax_dim)?;

        // Apply dropout
        let dropped = if dropout_p > 0.0 {
            self.functional_dropout(softmaxed, dropout_p, true)?
        } else {
            softmaxed
        };

        // attn_weights @ V
        if ndim >= 3 {
            self.tensor_bmm(dropped, value)
        } else {
            self.tensor_matmul(dropped, value)
        }
    }

    /// Multi-head attention forward pass.
    ///
    /// Equivalent to `torch.nn.functional.multi_head_attention_forward`.
    /// Projects query, key, value through linear layers, applies multi-head attention,
    /// and projects output.
    ///
    /// - `query`: `[tgt_len, batch, embed_dim]` or `[batch, tgt_len, embed_dim]` (if batch_first)
    /// - `key`: `[src_len, batch, embed_dim]` or `[batch, src_len, embed_dim]`
    /// - `value`: `[src_len, batch, embed_dim]` or `[batch, src_len, embed_dim]`
    /// - `in_proj_weight`: combined Q/K/V projection `[3*embed_dim, embed_dim]`
    /// - `in_proj_bias`: combined bias `[3*embed_dim]` (optional)
    /// - `out_proj_weight`: output projection `[embed_dim, embed_dim]`
    /// - `out_proj_bias`: output bias `[embed_dim]` (optional)
    /// - `num_heads`: number of attention heads
    /// - `dropout_p`: dropout probability
    /// - `batch_first`: if true, input shape is `[batch, seq, embed]`
    ///
    /// Returns `(attn_output, attn_weights)`.
    #[allow(clippy::too_many_arguments)]
    pub fn multi_head_attention_forward(
        &mut self,
        query: TensorNodeId,
        key: TensorNodeId,
        value: TensorNodeId,
        in_proj_weight: TensorNodeId,
        in_proj_bias: Option<TensorNodeId>,
        out_proj_weight: TensorNodeId,
        out_proj_bias: Option<TensorNodeId>,
        num_heads: usize,
        dropout_p: f64,
        attn_mask: Option<TensorNodeId>,
        key_padding_mask: Option<TensorNodeId>,
        need_weights: bool,
        is_causal: bool,
        batch_first: bool,
    ) -> Result<(TensorNodeId, Option<TensorNodeId>), AutogradError> {
        if num_heads == 0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "multi_head_attention_forward: num_heads must be positive",
                },
            )));
        }
        let q_shape = self.tensor_shape(query)?;
        if q_shape.len() != 3 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "multi_head_attention_forward: query must be 3-D",
                },
            )));
        }
        let (tgt_len, bsz, embed_dim) = if batch_first {
            (q_shape[1], q_shape[0], q_shape[2])
        } else {
            (q_shape[0], q_shape[1], q_shape[2])
        };
        if embed_dim % num_heads != 0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "multi_head_attention_forward: embed_dim must be divisible by num_heads",
                },
            )));
        }
        let head_dim = embed_dim / num_heads;
        let k_shape = self.tensor_shape(key)?;
        let src_len = if batch_first { k_shape[1] } else { k_shape[0] };

        // Transpose to [seq, batch, embed] if batch_first
        let (q, k, v) = if batch_first {
            let q_t = self.tensor_transpose(query, 0, 1)?;
            let k_t = self.tensor_transpose(key, 0, 1)?;
            let v_t = self.tensor_transpose(value, 0, 1)?;
            (q_t, k_t, v_t)
        } else {
            (query, key, value)
        };

        // Reshape [seq, batch, embed] -> [seq*batch, embed]
        let q_flat = self.tensor_reshape(q, vec![tgt_len * bsz, embed_dim])?;
        let k_flat = self.tensor_reshape(k, vec![src_len * bsz, embed_dim])?;
        let v_flat = self.tensor_reshape(v, vec![src_len * bsz, embed_dim])?;

        // Apply combined Q/K/V projection: [seq*batch, embed] @ [embed, 3*embed]^T
        let in_proj_weight_t = self.tensor_transpose(in_proj_weight, 0, 1)?;
        let w_q = self.tensor_narrow(in_proj_weight_t, 1, 0, embed_dim)?;
        let w_k = self.tensor_narrow(in_proj_weight_t, 1, embed_dim, embed_dim)?;
        let w_v = self.tensor_narrow(in_proj_weight_t, 1, 2 * embed_dim, embed_dim)?;
        let q_proj = self.tensor_matmul(q_flat, w_q)?;
        let k_proj = self.tensor_matmul(k_flat, w_k)?;
        let v_proj = self.tensor_matmul(v_flat, w_v)?;

        // Add biases if present
        let (q_proj, k_proj, v_proj) = if let Some(bias) = in_proj_bias {
            let q_bias = self.tensor_narrow(bias, 0, 0, embed_dim)?;
            let k_bias = self.tensor_narrow(bias, 0, embed_dim, embed_dim)?;
            let v_bias = self.tensor_narrow(bias, 0, 2 * embed_dim, embed_dim)?;
            let q_proj = self.tensor_add(q_proj, q_bias)?;
            let k_proj = self.tensor_add(k_proj, k_bias)?;
            let v_proj = self.tensor_add(v_proj, v_bias)?;
            (q_proj, k_proj, v_proj)
        } else {
            (q_proj, k_proj, v_proj)
        };

        // Reshape to [batch, num_heads, seq_len, head_dim]
        let q_heads = self.tensor_reshape(q_proj, vec![tgt_len, bsz, num_heads, head_dim])?;
        let q_heads = self.tensor_permute(q_heads, vec![1, 2, 0, 3])?;
        let k_heads = self.tensor_reshape(k_proj, vec![src_len, bsz, num_heads, head_dim])?;
        let k_heads = self.tensor_permute(k_heads, vec![1, 2, 0, 3])?;
        let v_heads = self.tensor_reshape(v_proj, vec![src_len, bsz, num_heads, head_dim])?;
        let v_heads = self.tensor_permute(v_heads, vec![1, 2, 0, 3])?;

        // Apply key_padding_mask if present
        let effective_mask = match (attn_mask, key_padding_mask) {
            (Some(am), Some(kpm)) => {
                // Combine: expand key_padding_mask and add to attn_mask
                let kpm_expanded = self.tensor_unsqueeze(kpm, 1)?;
                let kpm_expanded = self.tensor_unsqueeze(kpm_expanded, 2)?;
                let kpm_shape = self.tensor_shape(kpm_expanded)?;
                let zeros = self.tensor_zeros(kpm_shape, false)?;
                let kpm_float = self.tensor_masked_fill(zeros, kpm_expanded, f64::NEG_INFINITY)?;
                Some(self.tensor_add(am, kpm_float)?)
            }
            (Some(am), None) => Some(am),
            (None, Some(kpm)) => {
                let kpm_expanded = self.tensor_unsqueeze(kpm, 1)?;
                let kpm_expanded = self.tensor_unsqueeze(kpm_expanded, 2)?;
                let kpm_shape = self.tensor_shape(kpm_expanded)?;
                let zeros = self.tensor_zeros(kpm_shape, false)?;
                Some(self.tensor_masked_fill(zeros, kpm_expanded, f64::NEG_INFINITY)?)
            }
            (None, None) => None,
        };

        // Apply scaled_dot_product_attention
        let attn_output = self.scaled_dot_product_attention(
            q_heads,
            k_heads,
            v_heads,
            effective_mask,
            dropout_p,
            is_causal,
        )?;

        // Compute attention weights if needed
        let attn_weights_out = if need_weights {
            let scale = 1.0 / (head_dim as f64).sqrt();
            let k_t = self.tensor_transpose(k_heads, 2, 3)?;
            let scores = self.tensor_matmul(q_heads, k_t)?;
            let scores_shape = self.tensor_shape(scores)?;
            let scale_tensor = self.full(scores_shape.clone(), scale, false)?;
            let scaled = self.tensor_mul(scores, scale_tensor)?;
            let softmax_dim = scores_shape.len() - 1;
            let weights = self.tensor_softmax(scaled, softmax_dim)?;
            // Average over head dimension (dim 1)
            let avg_weights = self.tensor_mean_dim(weights, 1)?;
            Some(avg_weights)
        } else {
            None
        };

        // Reshape: [batch, num_heads, tgt_len, head_dim] -> [tgt_len, batch, embed_dim]
        let attn_output = self.tensor_permute(attn_output, vec![2, 0, 1, 3])?;
        let attn_output = self.tensor_reshape(attn_output, vec![tgt_len, bsz, embed_dim])?;

        // Flatten for output projection
        let attn_flat = self.tensor_reshape(attn_output, vec![tgt_len * bsz, embed_dim])?;
        let out_proj_weight_t = self.tensor_transpose(out_proj_weight, 0, 1)?;
        let mut output = self.tensor_matmul(attn_flat, out_proj_weight_t)?;
        if let Some(bias) = out_proj_bias {
            output = self.tensor_add(output, bias)?;
        }
        let output = self.tensor_reshape(output, vec![tgt_len, bsz, embed_dim])?;

        // Transpose back if batch_first
        let output = if batch_first {
            self.tensor_transpose(output, 0, 1)?
        } else {
            output
        };

        Ok((output, attn_weights_out))
    }

    /// Extract non-overlapping patches from images (Vision Transformer).
    ///
    /// Converts image into sequence of flattened patch embeddings.
    /// For ViT: image [B, C, H, W] -> patches [B, num_patches, patch_dim]
    ///
    /// Args:
    /// - images: [B, C, H, W] input images
    /// - patch_size: size of each square patch
    ///
    /// Returns: [B, num_patches, C * patch_size * patch_size]
    pub fn patch_embed(
        &mut self,
        images: TensorNodeId,
        patch_size: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(images)?;
        if shape.len() != 4 {
            return Err(Self::incompatible_tensor_args(
                "patch_embed: images must be [B, C, H, W]",
            ));
        }
        let (b, c, h, w) = (shape[0], shape[1], shape[2], shape[3]);
        if h % patch_size != 0 || w % patch_size != 0 {
            return Err(Self::incompatible_tensor_args(
                "patch_embed: H and W must be divisible by patch_size",
            ));
        }
        let nh = h / patch_size;
        let nw = w / patch_size;
        let num_patches = nh * nw;
        let patch_dim = c * patch_size * patch_size;
        // lossy_f64 so f32 images work (tensor_values is F64-only -> UnsupportedDType(F32)).
        let data = self.tensor_values_lossy_f64(images)?;
        let mut patches = vec![0.0; b * num_patches * patch_dim];
        for bi in 0..b {
            for ph in 0..nh {
                for pw in 0..nw {
                    let patch_idx = ph * nw + pw;
                    for ch in 0..c {
                        for py in 0..patch_size {
                            for px in 0..patch_size {
                                let ih = ph * patch_size + py;
                                let iw = pw * patch_size + px;
                                let src_idx = bi * c * h * w + ch * h * w + ih * w + iw;
                                let dst_idx = bi * num_patches * patch_dim
                                    + patch_idx * patch_dim
                                    + ch * patch_size * patch_size
                                    + py * patch_size
                                    + px;
                                patches[dst_idx] = data[src_idx];
                            }
                        }
                    }
                }
            }
        }
        let out = self.tensor_variable(patches, vec![b, num_patches, patch_dim], false)?;
        // Pure rearrange -> preserve the input dtype (f32 images -> f32 patches).
        match self.tensor_dtype(images)? {
            dt @ (DType::F32 | DType::F16 | DType::BF16) => self.tensor_tape.to_dtype(out, dt),
            _ => Ok(out),
        }
    }

    /// Partition tensor into non-overlapping windows (Swin Transformer).
    ///
    /// Args:
    /// - x: [B, H, W, C] input features
    /// - window_size: size of each square window
    ///
    /// Returns: [num_windows * B, window_size, window_size, C]
    pub fn window_partition(
        &mut self,
        x: TensorNodeId,
        window_size: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(x)?;
        if shape.len() != 4 {
            return Err(Self::incompatible_tensor_args(
                "window_partition: x must be [B, H, W, C]",
            ));
        }
        let (b, h, w, c) = (shape[0], shape[1], shape[2], shape[3]);
        if h % window_size != 0 || w % window_size != 0 {
            return Err(Self::incompatible_tensor_args(
                "window_partition: H and W must be divisible by window_size",
            ));
        }
        let nh = h / window_size;
        let nw = w / window_size;
        let num_windows = nh * nw;
        // lossy_f64 so f32 inputs work (tensor_values is F64-only -> UnsupportedDType(F32)).
        let data = self.tensor_values_lossy_f64(x)?;
        let mut windows = vec![0.0; b * num_windows * window_size * window_size * c];
        for bi in 0..b {
            for wh in 0..nh {
                for ww in 0..nw {
                    let win_idx = bi * num_windows + wh * nw + ww;
                    for wy in 0..window_size {
                        for wx in 0..window_size {
                            let ih = wh * window_size + wy;
                            let iw = ww * window_size + wx;
                            for ch in 0..c {
                                let src_idx = bi * h * w * c + ih * w * c + iw * c + ch;
                                let dst_idx = win_idx * window_size * window_size * c
                                    + wy * window_size * c
                                    + wx * c
                                    + ch;
                                windows[dst_idx] = data[src_idx];
                            }
                        }
                    }
                }
            }
        }
        let out = self.tensor_variable(
            windows,
            vec![b * num_windows, window_size, window_size, c],
            false,
        )?;
        // Pure rearrange -> preserve the input dtype (f32 -> f32).
        match self.tensor_dtype(x)? {
            dt @ (DType::F32 | DType::F16 | DType::BF16) => self.tensor_tape.to_dtype(out, dt),
            _ => Ok(out),
        }
    }

    /// Reverse window_partition operation (Swin Transformer).
    ///
    /// Args:
    /// - windows: [num_windows * B, window_size, window_size, C]
    /// - window_size: size of each square window
    /// - h, w: original height and width
    ///
    /// Returns: [B, H, W, C]
    pub fn window_reverse(
        &mut self,
        windows: TensorNodeId,
        window_size: usize,
        h: usize,
        w: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(windows)?;
        if shape.len() != 4 || shape[1] != window_size || shape[2] != window_size {
            return Err(Self::incompatible_tensor_args(
                "window_reverse: windows must be [N, window_size, window_size, C]",
            ));
        }
        let c = shape[3];
        let nh = h / window_size;
        let nw = w / window_size;
        let num_windows = nh * nw;
        let b = shape[0] / num_windows;
        // lossy_f64 so f32 inputs work (tensor_values is F64-only -> UnsupportedDType(F32)).
        let data = self.tensor_values_lossy_f64(windows)?;
        let mut output = vec![0.0; b * h * w * c];
        for bi in 0..b {
            for wh in 0..nh {
                for ww in 0..nw {
                    let win_idx = bi * num_windows + wh * nw + ww;
                    for wy in 0..window_size {
                        for wx in 0..window_size {
                            let ih = wh * window_size + wy;
                            let iw = ww * window_size + wx;
                            for ch in 0..c {
                                let src_idx = win_idx * window_size * window_size * c
                                    + wy * window_size * c
                                    + wx * c
                                    + ch;
                                let dst_idx = bi * h * w * c + ih * w * c + iw * c + ch;
                                output[dst_idx] = data[src_idx];
                            }
                        }
                    }
                }
            }
        }
        let out = self.tensor_variable(output, vec![b, h, w, c], false)?;
        // Pure rearrange -> preserve the input dtype (f32 -> f32).
        match self.tensor_dtype(windows)? {
            dt @ (DType::F32 | DType::F16 | DType::BF16) => self.tensor_tape.to_dtype(out, dt),
            _ => Ok(out),
        }
    }

    /// Alias for `multi_head_attention_forward`.
    #[allow(clippy::too_many_arguments)]
    pub fn functional_multi_head_attention_forward(
        &mut self,
        query: TensorNodeId,
        key: TensorNodeId,
        value: TensorNodeId,
        in_proj_weight: TensorNodeId,
        in_proj_bias: Option<TensorNodeId>,
        out_proj_weight: TensorNodeId,
        out_proj_bias: Option<TensorNodeId>,
        num_heads: usize,
        dropout_p: f64,
        attn_mask: Option<TensorNodeId>,
        key_padding_mask: Option<TensorNodeId>,
        need_weights: bool,
        is_causal: bool,
        batch_first: bool,
    ) -> Result<(TensorNodeId, Option<TensorNodeId>), AutogradError> {
        self.multi_head_attention_forward(
            query,
            key,
            value,
            in_proj_weight,
            in_proj_bias,
            out_proj_weight,
            out_proj_bias,
            num_heads,
            dropout_p,
            attn_mask,
            key_padding_mask,
            need_weights,
            is_causal,
            batch_first,
        )
    }

    /// Generate sinusoidal positional encodings for transformer models.
    ///
    /// Equivalent to the positional encoding from "Attention is All You Need".
    /// Returns tensor of shape `[max_len, d_model]` with sinusoidal patterns.
    ///
    /// PE(pos, 2i) = sin(pos / 10000^(2i/d_model))
    /// PE(pos, 2i+1) = cos(pos / 10000^(2i/d_model))
    pub fn sinusoidal_positional_encoding(
        &mut self,
        max_len: usize,
        d_model: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        if d_model == 0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "sinusoidal_positional_encoding: d_model must be positive",
                },
            )));
        }
        let mut pe = vec![0.0_f64; max_len * d_model];
        let frequency_cols = d_model.div_ceil(2);
        let mut denominators = Vec::with_capacity(frequency_cols);
        for i in 0..frequency_cols {
            denominators.push(10000.0_f64.powf((2 * i) as f64 / d_model as f64));
        }
        let fill_row = |pos: usize, row: &mut [f64]| {
            for i in 0..(d_model / 2) {
                let angle = (pos as f64) / denominators[i];
                row[2 * i] = angle.sin();
                row[2 * i + 1] = angle.cos();
            }
            if d_model % 2 == 1 {
                let i = d_model / 2;
                let angle = (pos as f64) / denominators[i];
                row[d_model - 1] = angle.sin();
            }
        };
        if max_len >= 2 && pe.len() >= PARALLEL_ELEMENTWISE_MIN {
            use rayon::prelude::*;
            pe.par_chunks_mut(d_model)
                .enumerate()
                .for_each(|(pos, row)| fill_row(pos, row));
        } else {
            pe.chunks_mut(d_model)
                .enumerate()
                .for_each(|(pos, row)| fill_row(pos, row));
        }
        self.tensor_variable(pe, vec![max_len, d_model], false)
    }

    /// Apply Rotary Position Embedding (RoPE) to query and key tensors.
    ///
    /// RoPE encodes position information through rotation matrices applied to
    /// pairs of dimensions. Used in LLaMA, GPT-NeoX, and many modern LLMs.
    ///
    /// - `q`: query tensor `[..., seq_len, head_dim]`
    /// - `k`: key tensor `[..., seq_len, head_dim]`
    /// - `cos_cached`: precomputed cos values `[seq_len, head_dim/2]` or `[max_seq, head_dim/2]`
    /// - `sin_cached`: precomputed sin values, same shape
    /// - `position_ids`: optional position indices `[batch, seq_len]`
    ///
    /// Returns `(rotated_q, rotated_k)`.
    pub fn apply_rotary_pos_emb(
        &mut self,
        q: TensorNodeId,
        k: TensorNodeId,
        cos_cached: TensorNodeId,
        sin_cached: TensorNodeId,
        position_ids: Option<TensorNodeId>,
    ) -> Result<(TensorNodeId, TensorNodeId), AutogradError> {
        let q_shape = self.tensor_shape(q)?;
        let head_dim =
            *q_shape
                .last()
                .ok_or(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "apply_rotary_pos_emb: q must have at least 1 dimension",
                    },
                )))?;
        if !head_dim.is_multiple_of(2) {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "apply_rotary_pos_emb: head_dim must be even for RoPE",
                },
            )));
        }
        let cos = if let Some(pos_ids) = position_ids {
            self.tensor_index_select(cos_cached, 0, pos_ids)?
        } else {
            cos_cached
        };
        let sin = if let Some(pos_ids) = position_ids {
            self.tensor_index_select(sin_cached, 0, pos_ids)?
        } else {
            sin_cached
        };
        // No-grad fused F64 fast path: the compose below runs ~6 tape ops PER q/k (narrow x2 + neg +
        // cat for rotate_half, then mul x2 + add), each materializing a full-size intermediate. When
        // q/k/cos/sin are all no-grad contiguous F64 and cos/sin are a trailing [seq, head_dim] tile
        // broadcasting over q/k's leading dims, fuse each into ONE parallel pass:
        //   out[f] = q[f]*cos[f%tile] + rot[f]*sin[f%tile],  rot[f] = (i<half) ? -q[f+half] : q[f-half]
        // BIT-IDENTICAL to the compose (mul-then-add, NO FMA; same rotate_half = cat(-x2,x1); same
        // trailing-tile broadcast tensor_mul does). Grad / non-F64 / non-contiguous / non-tile-broadcast
        // fall through unchanged. frankentorch (BlackThrush).
        {
            let ndim = q_shape.len();
            let k_shape = self.tensor_shape(k)?;
            let kdim = k_shape.len();
            let tile = if ndim >= 2 {
                q_shape[ndim - 2] * head_dim
            } else {
                head_dim
            };
            if ndim >= 2
                && kdim >= 2
                && k_shape[kdim - 1] == head_dim
                && k_shape[kdim - 2] == q_shape[ndim - 2]
                && !self.tensor_requires_grad(q)?
                && !self.tensor_requires_grad(k)?
                && !self.tensor_requires_grad(cos)?
                && !self.tensor_requires_grad(sin)?
                && self.tensor_dtype(q)? == DType::F64
                && self.tensor_dtype(k)? == DType::F64
                && self.tensor_dtype(cos)? == DType::F64
                && self.tensor_dtype(sin)? == DType::F64
            {
                let built = {
                    let qt = self.tensor_tape.tensor(q)?;
                    let kt = self.tensor_tape.tensor(k)?;
                    let ct = self.tensor_tape.tensor(cos)?;
                    let st = self.tensor_tape.tensor(sin)?;
                    if qt.meta().is_contiguous()
                        && kt.meta().is_contiguous()
                        && ct.meta().is_contiguous()
                        && st.meta().is_contiguous()
                    {
                        let qv = qt.contiguous_values()?;
                        let kv = kt.contiguous_values()?;
                        let cv = ct.contiguous_values()?;
                        let sv = st.contiguous_values()?;
                        if cv.len() == tile
                            && sv.len() == tile
                            && !qv.is_empty()
                            && qv.len() % tile == 0
                            && kv.len() % tile == 0
                        {
                            use rayon::prelude::*;
                            let half = head_dim / 2;
                            let fuse = |x: &[f64]| -> Vec<f64> {
                                x.par_iter()
                                    .enumerate()
                                    .map(|(f, &xf)| {
                                        let inner = f % tile;
                                        let i = f % head_dim;
                                        let rot = if i < half { -x[f + half] } else { x[f - half] };
                                        xf * cv[inner] + rot * sv[inner]
                                    })
                                    .collect()
                            };
                            Some((fuse(qv), fuse(kv)))
                        } else {
                            None
                        }
                    } else {
                        None
                    }
                };
                if let Some((qe, ke)) = built {
                    let q_out = self.tensor_variable(qe, q_shape.clone(), false)?;
                    let k_out = self.tensor_variable(ke, k_shape.clone(), false)?;
                    return Ok((q_out, k_out));
                }
            }
        }
        let rotate_half =
            |sess: &mut Self, x: TensorNodeId| -> Result<TensorNodeId, AutogradError> {
                let shape = sess.tensor_shape(x)?;
                let ndim = shape.len();
                let half = head_dim / 2;
                let x1 = sess.tensor_narrow(x, ndim - 1, 0, half)?;
                let x2 = sess.tensor_narrow(x, ndim - 1, half, half)?;
                let x2_neg = sess.tensor_neg(x2)?;
                sess.tensor_cat(&[x2_neg, x1], ndim - 1)
            };
        let q_embed = {
            let q_cos = self.tensor_mul(q, cos)?;
            let q_rot = rotate_half(self, q)?;
            let q_sin = self.tensor_mul(q_rot, sin)?;
            self.tensor_add(q_cos, q_sin)?
        };
        let k_embed = {
            let k_cos = self.tensor_mul(k, cos)?;
            let k_rot = rotate_half(self, k)?;
            let k_sin = self.tensor_mul(k_rot, sin)?;
            self.tensor_add(k_cos, k_sin)?
        };
        Ok((q_embed, k_embed))
    }

    /// Precompute RoPE frequencies for given max_seq_len and head_dim.
    ///
    /// Returns `(cos_cached, sin_cached)` both of shape `[max_seq_len, head_dim/2]`.
    /// These can be reused across batches and passed to `apply_rotary_pos_emb`.
    pub fn precompute_rope_freqs(
        &mut self,
        max_seq_len: usize,
        head_dim: usize,
        base: f64,
    ) -> Result<(TensorNodeId, TensorNodeId), AutogradError> {
        if head_dim % 2 != 0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "precompute_rope_freqs: head_dim must be even",
                },
            )));
        }
        let half_dim = head_dim / 2;
        let mut freqs = vec![0.0_f64; half_dim];
        for (i, freq) in freqs.iter_mut().enumerate().take(half_dim) {
            *freq = 1.0 / base.powf((2 * i) as f64 / head_dim as f64);
        }
        let mut cos_data = vec![0.0_f64; max_seq_len * half_dim];
        let mut sin_data = vec![0.0_f64; max_seq_len * half_dim];
        // Each position owns a contiguous half_dim row of both tables and every
        // element is an independent cos/sin (compute-bound), so distribute the
        // positions across Rayon workers. The per-element formula and the linear
        // write position (pos*half_dim + i) are unchanged, so the result is
        // bit-for-bit identical to the serial loop.
        let fill_row = |pos: usize, cos_row: &mut [f64], sin_row: &mut [f64]| {
            for (i, (c, s)) in cos_row.iter_mut().zip(sin_row.iter_mut()).enumerate() {
                let angle = (pos as f64) * freqs[i];
                *c = angle.cos();
                *s = angle.sin();
            }
        };
        if max_seq_len >= 2 && max_seq_len * half_dim >= PARALLEL_ELEMENTWISE_MIN {
            use rayon::prelude::*;
            cos_data
                .par_chunks_mut(half_dim)
                .zip(sin_data.par_chunks_mut(half_dim))
                .enumerate()
                .for_each(|(pos, (cos_row, sin_row))| fill_row(pos, cos_row, sin_row));
        } else {
            cos_data
                .chunks_mut(half_dim)
                .zip(sin_data.chunks_mut(half_dim))
                .enumerate()
                .for_each(|(pos, (cos_row, sin_row))| fill_row(pos, cos_row, sin_row));
        }
        let cos_node = self.tensor_variable(cos_data, vec![max_seq_len, half_dim], false)?;
        let sin_node = self.tensor_variable(sin_data, vec![max_seq_len, half_dim], false)?;
        Ok((cos_node, sin_node))
    }

    /// Alias for `sinusoidal_positional_encoding`.
    pub fn functional_sinusoidal_positional_encoding(
        &mut self,
        max_len: usize,
        d_model: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        self.sinusoidal_positional_encoding(max_len, d_model)
    }

    /// Generate ALiBi (Attention with Linear Biases) position biases.
    ///
    /// ALiBi is a simple, effective positional encoding method that adds linear
    /// biases to attention scores. Used in MPT, BLOOM, and other modern LLMs.
    ///
    /// Returns a bias tensor of shape `[num_heads, seq_len, seq_len]` to add to
    /// attention scores before softmax.
    ///
    /// The bias for head h at position i attending to position j is:
    ///   -slope[h] * |i - j|
    /// where slope[h] = 2^(-8 * h / num_heads) for h in 0..num_heads.
    pub fn alibi_bias(
        &mut self,
        num_heads: usize,
        seq_len: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        if num_heads == 0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "alibi_bias: num_heads must be positive",
                },
            )));
        }
        let mut slopes = Vec::with_capacity(num_heads);
        let ratio = 8.0 / num_heads as f64;
        for h in 0..num_heads {
            slopes.push(2.0_f64.powf(-ratio * (h + 1) as f64));
        }
        let mut bias = vec![0.0_f64; num_heads * seq_len * seq_len];
        for h in 0..num_heads {
            for i in 0..seq_len {
                for j in 0..seq_len {
                    let distance = (i as i64 - j as i64).abs() as f64;
                    bias[h * seq_len * seq_len + i * seq_len + j] = -slopes[h] * distance;
                }
            }
        }
        self.tensor_variable(bias, vec![num_heads, seq_len, seq_len], false)
    }

    /// Get ALiBi slopes for given number of heads.
    ///
    /// Returns slope values `[num_heads]` where slope[h] = 2^(-8*h/num_heads).
    /// Useful when you want to compute ALiBi bias manually or with different patterns.
    pub fn alibi_slopes(&mut self, num_heads: usize) -> Result<TensorNodeId, AutogradError> {
        if num_heads == 0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "alibi_slopes: num_heads must be positive",
                },
            )));
        }
        let ratio = 8.0 / num_heads as f64;
        let slopes: Vec<f64> = (0..num_heads)
            .map(|h| 2.0_f64.powf(-ratio * (h + 1) as f64))
            .collect();
        self.tensor_variable(slopes, vec![num_heads], false)
    }

    /// Generate a sliding window attention mask.
    ///
    /// Creates a mask for sliding window attention used in models like Mistral.
    /// Positions can only attend to positions within `window_size` distance.
    ///
    /// Returns a mask of shape `[seq_len, seq_len]` where:
    /// - 0.0 for positions within the window (allow attention)
    /// - -inf for positions outside the window (block attention)
    ///
    /// When `causal` is true, also enforces causal masking (no attending to future).
    pub fn sliding_window_mask(
        &mut self,
        seq_len: usize,
        window_size: usize,
        causal: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        let mut mask = vec![0.0_f64; seq_len * seq_len];
        for i in 0..seq_len {
            for j in 0..seq_len {
                let is_in_window = ((i as i64) - (j as i64)).abs() <= window_size as i64;
                let is_causal_ok = !causal || j <= i;
                if !(is_in_window && is_causal_ok) {
                    mask[i * seq_len + j] = f64::NEG_INFINITY;
                }
            }
        }
        self.tensor_variable(mask, vec![seq_len, seq_len], false)
    }

    /// Repeat key/value heads to match query heads for Grouped Query Attention.
    ///
    /// GQA uses fewer K/V heads than Q heads to reduce memory and compute.
    /// This function repeats K/V heads to match the number of Q heads.
    ///
    /// - `kv`: K or V tensor of shape `[batch, num_kv_heads, seq_len, head_dim]`
    /// - `num_q_heads`: number of query heads (must be divisible by num_kv_heads)
    ///
    /// Returns tensor of shape `[batch, num_q_heads, seq_len, head_dim]`.
    ///
    /// Used in LLaMA 2, Mistral, and other modern transformers.
    pub fn repeat_kv(
        &mut self,
        kv: TensorNodeId,
        num_q_heads: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(kv)?;
        if shape.len() != 4 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "repeat_kv: input must be 4-D [batch, num_kv_heads, seq_len, head_dim]",
                },
            )));
        }
        let num_kv_heads = shape[1];
        if !num_q_heads.is_multiple_of(num_kv_heads) {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "repeat_kv: num_q_heads must be divisible by num_kv_heads",
                },
            )));
        }
        if num_q_heads == num_kv_heads {
            return Ok(kv);
        }
        let n_rep = num_q_heads / num_kv_heads;
        let batch_size = shape[0];
        let seq_len = shape[2];
        let head_dim = shape[3];
        let expanded = self.tensor_unsqueeze(kv, 2)?;
        let new_shape = vec![batch_size, num_kv_heads, n_rep, seq_len, head_dim];
        let tiled = self.tensor_expand(expanded, new_shape.clone())?;
        let final_shape = vec![batch_size, num_q_heads, seq_len, head_dim];
        self.tensor_reshape(tiled, final_shape)
    }

    /// Update KV cache with new key/value tensors for incremental decoding.
    ///
    /// Concatenates new K/V with cached K/V along the sequence dimension.
    ///
    /// - `cache`: optional existing cache `[batch, num_heads, cache_len, head_dim]`
    /// - `new_kv`: new K or V tensor `[batch, num_heads, new_len, head_dim]`
    ///
    /// Returns updated cache tensor `[batch, num_heads, cache_len + new_len, head_dim]`.
    ///
    /// If cache is None, returns new_kv as-is.
    pub fn update_kv_cache(
        &mut self,
        cache: Option<TensorNodeId>,
        new_kv: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        match cache {
            Some(c) => {
                let seq_dim = 2;
                self.tensor_cat(&[c, new_kv], seq_dim)
            }
            None => Ok(new_kv),
        }
    }

    /// Truncate KV cache to maximum length for sliding window attention.
    ///
    /// Keeps only the last `max_len` positions in the cache.
    ///
    /// - `cache`: KV cache `[batch, num_heads, seq_len, head_dim]`
    /// - `max_len`: maximum sequence length to keep
    pub fn truncate_kv_cache(
        &mut self,
        cache: TensorNodeId,
        max_len: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(cache)?;
        if shape.len() != 4 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "truncate_kv_cache: cache must be 4-D",
                },
            )));
        }
        let seq_len = shape[2];
        if seq_len <= max_len {
            return Ok(cache);
        }
        let start = seq_len - max_len;
        self.tensor_narrow(cache, 2, start, max_len)
    }

    /// Tensor contraction over specified dimensions (generalised matrix multiply).
    ///
    /// `dims` is the number of trailing dimensions of `a` to contract with
    /// the leading dimensions of `b`.
    /// Equivalent to PyTorch's `torch.tensordot(a, b, dims=N)`.
    pub fn tensor_tensordot(
        &mut self,
        a: TensorNodeId,
        b: TensorNodeId,
        dims: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let a_shape = self.tensor_shape(a)?;
        let b_shape = self.tensor_shape(b)?;
        let a_ndim = a_shape.len();
        let b_ndim = b_shape.len();

        if dims > a_ndim || dims > b_ndim {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::InvalidDimension {
                    dim: dims,
                    ndim: a_ndim.min(b_ndim),
                },
            )));
        }

        // Check that contracted dimensions match
        for i in 0..dims {
            if a_shape[a_ndim - dims + i] != b_shape[i] {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                    ft_kernel_cpu::KernelError::ShapeMismatch {
                        lhs: a_shape.clone(),
                        rhs: b_shape.clone(),
                    },
                )));
            }
        }

        // Special case: dims=0 is outer product-like (no contraction)
        if dims == 0 {
            // Reshape a to [..., 1] and b to [1, ...], then matmul
            let a_total =
                Self::checked_shape_numel(&a_shape, "tensordot: lhs shape volume overflow")?;
            let b_total =
                Self::checked_shape_numel(&b_shape, "tensordot: rhs shape volume overflow")?;
            let a_flat = self.tensor_reshape(a, vec![a_total, 1])?;
            let b_flat = self.tensor_reshape(b, vec![1, b_total])?;
            let result = self.tensor_matmul(a_flat, b_flat)?;
            let mut out_shape = a_shape;
            out_shape.extend_from_slice(&b_shape);
            return self.tensor_reshape(result, out_shape);
        }

        // Reshape a: [free_a..., contract...] -> [prod(free_a), prod(contract)]
        let free_a = Self::checked_shape_numel(
            &a_shape[..a_ndim - dims],
            "tensordot: free lhs shape volume overflow",
        )?;
        let contract = Self::checked_shape_numel(
            &a_shape[a_ndim - dims..],
            "tensordot: contract shape volume overflow",
        )?;
        let a_2d = self.tensor_reshape(a, vec![free_a, contract])?;

        // Reshape b: [contract..., free_b...] -> [prod(contract), prod(free_b)]
        let free_b = Self::checked_shape_numel(
            &b_shape[dims..],
            "tensordot: free rhs shape volume overflow",
        )?;
        let b_2d = self.tensor_reshape(b, vec![contract, free_b])?;

        // Matmul: [free_a, contract] @ [contract, free_b] -> [free_a, free_b]
        let result = self.tensor_matmul(a_2d, b_2d)?;

        // Reshape back to [...free_a_dims, ...free_b_dims]
        let mut out_shape: Vec<usize> = a_shape[..a_ndim - dims].to_vec();
        out_shape.extend_from_slice(&b_shape[dims..]);
        if out_shape.is_empty() {
            out_shape.push(1);
        }
        self.tensor_reshape(result, out_shape)
    }

    /// `torch.tensordot(a, b, dims=(a_dims, b_dims))` — contract the paired axes
    /// `a_dims[i]`↔`b_dims[i]` (negatives allowed). The output is a's remaining
    /// axes (in order) followed by b's remaining axes (in order), matching
    /// torch. The int form is `tensor_tensordot`; this is the axis-list form,
    /// built from an einsum equation so gradients flow. frankentorch-ctkju.
    pub fn tensor_tensordot_dims(
        &mut self,
        a: TensorNodeId,
        b: TensorNodeId,
        a_dims: &[i64],
        b_dims: &[i64],
    ) -> Result<TensorNodeId, AutogradError> {
        let err = |reason: &'static str| {
            AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet { reason },
            ))
        };
        if a_dims.len() != b_dims.len() {
            return Err(err("tensordot: a_dims and b_dims must have equal length"));
        }
        let a_shape = self.tensor_shape(a)?;
        let b_shape = self.tensor_shape(b)?;
        let (ra, rb) = (a_shape.len(), b_shape.len());
        let norm = |d: i64, r: usize| -> Result<usize, AutogradError> {
            let n = if d < 0 { d + r as i64 } else { d };
            if n < 0 || n as usize >= r {
                Err(err("tensordot: dim out of range"))
            } else {
                Ok(n as usize)
            }
        };
        let a_ax: Vec<usize> = a_dims
            .iter()
            .map(|&d| norm(d, ra))
            .collect::<Result<_, _>>()?;
        let b_ax: Vec<usize> = b_dims
            .iter()
            .map(|&d| norm(d, rb))
            .collect::<Result<_, _>>()?;
        // Contracted axis sizes must match pairwise.
        for (&ai, &bi) in a_ax.iter().zip(&b_ax) {
            if a_shape[ai] != b_shape[bi] {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                    ft_kernel_cpu::KernelError::ShapeMismatch {
                        lhs: a_shape.clone(),
                        rhs: b_shape.clone(),
                    },
                )));
            }
        }
        // Letter assignment: a gets letters[0..ra]; each contracted b-axis reuses
        // a's paired letter; b's free axes take fresh letters. 26-letter cap.
        let letters: Vec<char> = ('a'..='z').collect();
        if ra + (rb - b_ax.len()) > letters.len() {
            return Err(err("tensordot: too many dimensions for einsum lowering"));
        }
        let a_sub: Vec<char> = letters[..ra].to_vec();
        let mut b_sub: Vec<char> = vec!['\0'; rb];
        for (i, &bi) in b_ax.iter().enumerate() {
            b_sub[bi] = a_sub[a_ax[i]];
        }
        let mut next = ra;
        for slot in b_sub.iter_mut() {
            if *slot == '\0' {
                *slot = letters[next];
                next += 1;
            }
        }
        let mut out: Vec<char> = Vec::new();
        for (i, &c) in a_sub.iter().enumerate() {
            if !a_ax.contains(&i) {
                out.push(c);
            }
        }
        for (j, &c) in b_sub.iter().enumerate() {
            if !b_ax.contains(&j) {
                out.push(c);
            }
        }
        let eq = format!(
            "{},{}->{}",
            a_sub.iter().collect::<String>(),
            b_sub.iter().collect::<String>(),
            out.iter().collect::<String>()
        );
        self.tensor_einsum(&eq, &[a, b])
    }

    /// Kronecker product of two tensors.
    ///
    /// If the inputs have different ranks, the lower-rank input is left-padded
    /// with singleton dimensions before multiplying each aligned dimension.
    pub fn tensor_kron(
        &mut self,
        a: TensorNodeId,
        b: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let a_shape = self.tensor_shape(a)?;
        let b_shape = self.tensor_shape(b)?;

        if a_shape.len() == 1 && b_shape.len() == 1 {
            let outer = self.tensor_outer(a, b)?;
            let total = Self::checked_mul(a_shape[0], b_shape[0], "kron: output shape overflow")?;
            return self.tensor_reshape(outer, vec![total]);
        }

        let rank = a_shape.len().max(b_shape.len());
        let mut a_aligned = vec![1usize; rank - a_shape.len()];
        a_aligned.extend_from_slice(&a_shape);
        let mut b_aligned = vec![1usize; rank - b_shape.len()];
        b_aligned.extend_from_slice(&b_shape);

        let mut out_shape = Vec::with_capacity(rank);
        for (&a_dim, &b_dim) in a_aligned.iter().zip(&b_aligned) {
            out_shape.push(Self::checked_mul(
                a_dim,
                b_dim,
                "kron: output shape overflow",
            )?);
        }
        let total = Self::checked_shape_numel(&out_shape, "kron: output shape volume overflow")?;

        if self.tensor_tape.tensor_requires_grad(a)? || self.tensor_tape.tensor_requires_grad(b)? {
            let mut a_kron_shape = Vec::with_capacity(rank * 2);
            let mut b_kron_shape = Vec::with_capacity(rank * 2);
            let mut interleaved_shape = Vec::with_capacity(rank * 2);
            for (&a_dim, &b_dim) in a_aligned.iter().zip(&b_aligned) {
                a_kron_shape.push(a_dim);
                a_kron_shape.push(1);
                b_kron_shape.push(1);
                b_kron_shape.push(b_dim);
                interleaved_shape.push(a_dim);
                interleaved_shape.push(b_dim);
            }

            let a_view = self.tensor_reshape(a, a_kron_shape)?;
            let b_view = self.tensor_reshape(b, b_kron_shape)?;
            let a_expanded = self.tensor_expand(a_view, interleaved_shape.clone())?;
            let b_expanded = self.tensor_expand(b_view, interleaved_shape)?;
            let product = self.tensor_mul(a_expanded, b_expanded)?;
            return self.tensor_reshape(product, out_shape);
        }

        // No-grad f32 path. The f64 path below reads `tensor_values` (F64-only), so f32 no-grad
        // kron ERRORED (UnsupportedDType(F32)) — a real bug (f32 WITH grad works via the
        // reshape/expand/mul path above; torch.kron(f32)->f32). Native f32 fast path for the
        // dominant rank==2 case (mirrors the f64 2-D fill; bit-exact since the f64 product of two
        // exact-f32 operands rounded to f32 equals the direct f32 product); rank>2 / non-contiguous
        // cast-recurse through the f64 path (rare; correctness). frankentorch-kron-f32-fix.
        if self.tensor_dtype(a)? == DType::F32 && self.tensor_dtype(b)? == DType::F32 {
            if total == 0 {
                return self.tensor_variable_f32(Vec::new(), out_shape, false);
            }
            if rank == 2 {
                let (_a_rows, a_cols) = (a_aligned[0], a_aligned[1]);
                let (b_rows, b_cols) = (b_aligned[0], b_aligned[1]);
                let out_cols = out_shape[1];
                let built = {
                    let at = self.tensor_tape.tensor(a)?;
                    let bt = self.tensor_tape.tensor(b)?;
                    if at.meta().is_contiguous() && bt.meta().is_contiguous() {
                        let a_vals = at.contiguous_values_f32()?;
                        let b_vals = bt.contiguous_values_f32()?;
                        let fill_row = |i: usize, out_row: &mut [f32]| {
                            let a_row = i / b_rows;
                            let b_row = i % b_rows;
                            let brow = &b_vals[b_row * b_cols..b_row * b_cols + b_cols];
                            for a_col in 0..a_cols {
                                let a_val = a_vals[a_row * a_cols + a_col];
                                let dst = &mut out_row[a_col * b_cols..a_col * b_cols + b_cols];
                                for (d, &bv) in dst.iter_mut().zip(brow) {
                                    *d = a_val * bv;
                                }
                            }
                        };
                        // Uninit first-touch: fill_row writes EVERY output element (sequential per
                        // row, never reads dst), so build uninitialized rather than par_zeroed (a
                        // full DEAD first write, 2N vs N). Measured 1.06-1.47x, bit-identical.
                        let result = ft_kernel_cpu::build_uninit(total, |result: &mut [f32]| {
                            if total >= PARALLEL_ELEMENTWISE_MIN
                                && out_cols > 0
                                && total / out_cols > 1
                            {
                                use rayon::prelude::*;
                                result
                                    .par_chunks_mut(out_cols)
                                    .enumerate()
                                    .for_each(|(i, row)| fill_row(i, row));
                            } else {
                                for (i, row) in result.chunks_mut(out_cols).enumerate() {
                                    fill_row(i, row);
                                }
                            }
                        });
                        Some(result)
                    } else {
                        None
                    }
                };
                if let Some(result) = built {
                    return self.tensor_variable_f32(result, out_shape, false);
                }
            }
            // rank != 2 or non-contiguous f32: cast-recurse through the f64 path (rare).
            let a64 = self.tensor_to_dtype(a, DType::F64)?;
            let b64 = self.tensor_to_dtype(b, DType::F64)?;
            let out64 = self.tensor_kron(a64, b64)?;
            return self.tensor_to_dtype(out64, DType::F32);
        }

        let a_vals = self.tensor_values(a)?;
        let b_vals = self.tensor_values(b)?;
        if total == 0 {
            return self.tensor_variable(Vec::new(), out_shape, false);
        }

        // 2-D fast path (the dominant kron case — also covers 1-D⊗2-D / 2-D⊗1-D via the rank-2
        // alignment). Output row i = a_row·b_rows + b_row, and within that row each a-column writes
        // the block `a[a_row,a_col] · B[b_row, :]` at columns [a_col·b_cols ..]. This is a per-row
        // scalar·vector fill — NO per-element div/mod (the general loop below did `rank` checked
        // divides + 2 checked muls + 2 checked adds PER OUTPUT ELEMENT = O(total·rank)) and parallel
        // over output rows. Bit-identical to the general loop (out_linear=i·out_cols+j, same a_val·b_val).
        if rank == 2 {
            let (_a_rows, a_cols) = (a_aligned[0], a_aligned[1]);
            let (b_rows, b_cols) = (b_aligned[0], b_aligned[1]);
            let out_cols = out_shape[1];
            // Parallel first-touch (see par_zeroed_f64): distributes the output page faults
            // that a serial vec![0.0; total] would pay on one thread before the parallel fill.
            let fill_row = |i: usize, out_row: &mut [f64]| {
                let a_row = i / b_rows;
                let b_row = i % b_rows;
                let brow = &b_vals[b_row * b_cols..b_row * b_cols + b_cols];
                for a_col in 0..a_cols {
                    let a_val = a_vals[a_row * a_cols + a_col];
                    let dst = &mut out_row[a_col * b_cols..a_col * b_cols + b_cols];
                    for (d, &bv) in dst.iter_mut().zip(brow) {
                        *d = a_val * bv;
                    }
                }
            };
            // Uninit first-touch: fill_row writes EVERY output element (sequential per row, never
            // reads dst), so build the output uninitialized rather than par_zeroed — that pre-fill
            // was a full DEAD first write of the output (2N writes vs N). Measured 1.06-1.47x,
            // bit-identical. See ft_kernel_cpu::build_uninit.
            let result = ft_kernel_cpu::build_uninit(total, |result: &mut [f64]| {
                if total >= PARALLEL_ELEMENTWISE_MIN && out_cols > 0 && total / out_cols > 1 {
                    use rayon::prelude::*;
                    result
                        .par_chunks_mut(out_cols)
                        .enumerate()
                        .for_each(|(i, row)| fill_row(i, row));
                } else {
                    for (i, row) in result.chunks_mut(out_cols).enumerate() {
                        fill_row(i, row);
                    }
                }
            });
            return self.tensor_variable(result, out_shape, false);
        }

        // Precompute contiguous strides for the aligned shapes ONCE before the
        // hot loop (frankentorch-ys3y). The earlier implementation allocated a
        // fresh `Vec<usize>` of length `rank` on every iteration of the
        // doubly-nested loop via a `decode_coords` closure, which made a 2D x
        // 2D kron of N x N inputs do O(N^4) Vec allocations. With strides in
        // hand we can decompose `a_linear` and `b_linear` into per-dim
        // coordinates with simple integer division and recombine into
        // `out_linear` without any per-iteration heap activity.
        //
        // All bounds below are mathematically guaranteed to fit in `usize`:
        // for any valid (a_linear, b_linear), each dim's `out_coord` is in
        // `[0, out_shape[dim])`, and the running `out_linear` stays in
        // `[0, total)` (already validated to fit in `usize` above). We keep
        // checked arithmetic anyway to match the surrounding hardening style
        // and to fail closed on any future invariant violation.
        let a_strides = contiguous_strides(&a_aligned);
        let b_strides = contiguous_strides(&b_aligned);

        let mut result = vec![0.0f64; total];
        for (a_linear, &a_val) in a_vals.iter().enumerate() {
            for (b_linear, &b_val) in b_vals.iter().enumerate() {
                let mut out_linear = 0usize;
                for dim in 0..rank {
                    // contiguous_strides guarantees stride >= 1 for every dim
                    // when the shape is non-empty, and we already short-
                    // circuited when `total == 0`.
                    let a_coord = (a_linear / a_strides[dim]) % a_aligned[dim];
                    let b_coord = (b_linear / b_strides[dim]) % b_aligned[dim];
                    let scaled_a = Self::checked_mul(
                        a_coord,
                        b_aligned[dim],
                        "kron: output coordinate overflow",
                    )?;
                    let out_coord =
                        Self::checked_add(scaled_a, b_coord, "kron: output coordinate overflow")?;
                    out_linear = Self::checked_add(
                        Self::checked_mul(
                            out_linear,
                            out_shape[dim],
                            "kron: output index overflow",
                        )?,
                        out_coord,
                        "kron: output index overflow",
                    )?;
                }
                result[out_linear] = a_val * b_val;
            }
        }

        self.tensor_variable(result, out_shape, false)
    }

    /// Einstein summation.
    ///
    /// Supports 1- and 2-operand equations via compact index notation.
    /// Decomposes into permute/reshape/matmul/sum operations for backward compatibility.
    ///
    /// Examples:
    /// - `"ij,jk->ik"` — matrix multiply
    /// - `"ii->"` — trace
    /// - `"ij->ji"` — transpose
    /// - `"i,j->ij"` — outer product
    /// - `"i,i->"` — dot product
    /// - `"bij,bjk->bik"` — batch matmul
    ///
    /// Expand torch.einsum ellipsis (`...`) into explicit fresh lowercase
    /// letters so the letter-only einsum core handles batched/broadcast forms.
    /// Each operand's `...` covers `ndim - explicit_letters` dims; the broadcast
    /// rank is the max across operands, and shorter operands take the RIGHTMOST
    /// letters (numpy/torch right-alignment). The output `...` (explicit or
    /// implicit) expands to the full broadcast letter set, placed first for the
    /// implicit case. frankentorch-s3iig.
    fn expand_einsum_ellipsis(equation: &str, ndims: &[usize]) -> Result<String, &'static str> {
        let (input_part, output_part) = match equation.find("->") {
            Some(p) => (&equation[..p], Some(&equation[p + 2..])),
            None => (equation, None),
        };
        let input_subs: Vec<&str> = input_part.split(',').collect();
        if input_subs.len() != ndims.len() {
            return Err("einsum: number of subscripts must match number of tensors");
        }
        let used: std::collections::HashSet<char> = equation
            .chars()
            .filter(|c| c.is_ascii_lowercase())
            .collect();
        // Per-operand ellipsis rank + the broadcast (max) rank.
        let mut ell_ranks = Vec::with_capacity(input_subs.len());
        let mut max_ell = 0usize;
        for (i, sub) in input_subs.iter().enumerate() {
            let n_letters = sub.chars().filter(|c| c.is_ascii_lowercase()).count();
            if sub.contains("...") {
                if ndims[i] < n_letters {
                    return Err("einsum: too many subscripts for operand");
                }
                let r = ndims[i] - n_letters;
                ell_ranks.push(r);
                max_ell = max_ell.max(r);
            } else {
                ell_ranks.push(0);
            }
        }
        let pool: Vec<char> = ('a'..='z').filter(|c| !used.contains(c)).collect();
        if pool.len() < max_ell {
            return Err("einsum: not enough free letters to expand ellipsis");
        }
        let ell_letters = &pool[..max_ell];
        let expand_sub = |sub: &str, rank: usize| -> String {
            if sub.contains("...") {
                // right-aligned subset of the broadcast letters
                let ell: String = ell_letters[max_ell - rank..].iter().collect();
                sub.replace("...", &ell)
                    .chars()
                    .filter(|c| c.is_ascii_lowercase())
                    .collect()
            } else {
                sub.chars().filter(|c| c.is_ascii_lowercase()).collect()
            }
        };
        let new_inputs: Vec<String> = input_subs
            .iter()
            .enumerate()
            .map(|(i, sub)| expand_sub(sub, ell_ranks[i]))
            .collect();
        let new_output: String = match output_part {
            Some(out) => {
                let ell: String = ell_letters.iter().collect();
                out.replace("...", &ell)
                    .chars()
                    .filter(|c| c.is_ascii_lowercase())
                    .collect()
            }
            None => {
                // implicit output: broadcast (ellipsis) dims first, then the
                // non-ellipsis indices appearing exactly once, sorted.
                let mut counts: std::collections::HashMap<char, usize> =
                    std::collections::HashMap::new();
                for sub in &new_inputs {
                    for c in sub.chars() {
                        if !ell_letters.contains(&c) {
                            *counts.entry(c).or_insert(0) += 1;
                        }
                    }
                }
                let mut once: Vec<char> = counts
                    .into_iter()
                    .filter(|(_, n)| *n == 1)
                    .map(|(c, _)| c)
                    .collect();
                once.sort_unstable();
                let mut o: String = ell_letters.iter().collect();
                o.extend(once);
                o
            }
        };
        Ok(format!("{}->{}", new_inputs.join(","), new_output))
    }

    pub fn tensor_einsum(
        &mut self,
        equation: &str,
        tensors: &[TensorNodeId],
    ) -> Result<TensorNodeId, AutogradError> {
        let make_err = |reason: &'static str| {
            AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet { reason },
            ))
        };

        // torch.einsum ellipsis ('...'): expand to fresh unused letters
        // (right-aligned across operands for broadcasting) so the letter-based
        // logic below runs unchanged. No-op when '...' is absent.
        // frankentorch-s3iig.
        let expanded_eq;
        let equation: &str = if equation.contains("...") {
            let ndims: Vec<usize> = tensors
                .iter()
                .map(|&t| self.tensor_shape(t).map(|s| s.len()))
                .collect::<Result<_, _>>()?;
            expanded_eq = Self::expand_einsum_ellipsis(equation, &ndims).map_err(make_err)?;
            expanded_eq.as_str()
        } else {
            equation
        };

        // Parse equation: "subscripts -> output" or just "subscripts" (implicit output)
        let (input_part, output_part) = if let Some(pos) = equation.find("->") {
            (&equation[..pos], Some(&equation[pos + 2..]))
        } else {
            (equation, None)
        };

        let input_subs: Vec<&str> = input_part.split(',').collect();
        if input_subs.len() != tensors.len() {
            return Err(make_err(
                "einsum: number of subscripts must match number of tensors",
            ));
        }

        // Validate characters: only lowercase ASCII letters
        for ch in equation.chars() {
            if ch != ',' && ch != '-' && ch != '>' && ch != ' ' && !ch.is_ascii_lowercase() {
                return Err(make_err(
                    "einsum: only lowercase ASCII letters allowed in subscripts",
                ));
            }
        }

        // Parse subscripts into index lists
        let input_indices: Vec<Vec<char>> = input_subs
            .iter()
            .map(|s| s.chars().filter(|c| c.is_ascii_lowercase()).collect())
            .collect();

        // Validate shapes match subscripts
        for (i, indices) in input_indices.iter().enumerate() {
            let shape = self.tensor_shape(tensors[i])?;
            if shape.len() != indices.len() {
                return Err(make_err("einsum: subscript length must match tensor ndim"));
            }
        }

        // Build dimension size map
        let mut dim_sizes: std::collections::HashMap<char, usize> =
            std::collections::HashMap::new();
        for (i, indices) in input_indices.iter().enumerate() {
            let shape = self.tensor_shape(tensors[i])?;
            for (d, &idx) in indices.iter().enumerate() {
                if let Some(&existing) = dim_sizes.get(&idx) {
                    if existing != shape[d] {
                        return Err(make_err(
                            "einsum: dimension size mismatch for repeated index",
                        ));
                    }
                } else {
                    dim_sizes.insert(idx, shape[d]);
                }
            }
        }

        // Determine output indices
        let output_indices: Vec<char> = if let Some(out) = output_part {
            out.chars().filter(|c| c.is_ascii_lowercase()).collect()
        } else {
            // Implicit: sorted unique indices that appear exactly once across all inputs
            let mut counts: std::collections::HashMap<char, usize> =
                std::collections::HashMap::new();
            for indices in &input_indices {
                for &ch in indices {
                    *counts.entry(ch).or_insert(0) += 1;
                }
            }
            let mut out: Vec<char> = counts
                .into_iter()
                .filter(|(_, count)| *count == 1)
                .map(|(ch, _)| ch)
                .collect();
            out.sort();
            out
        };

        // Handle based on number of operands
        match tensors.len() {
            1 => self.einsum_unary(&input_indices[0], &output_indices, tensors[0], &dim_sizes),
            2 => self.einsum_binary(
                &input_indices[0],
                &input_indices[1],
                &output_indices,
                tensors[0],
                tensors[1],
                &dim_sizes,
            ),
            _ => {
                // Multi-operand: pairwise reduction left-to-right
                // Determine which indices to contract at each step
                let mut current = tensors[0];
                let mut current_indices = input_indices[0].clone();
                for i in 1..tensors.len() {
                    let rhs_indices = &input_indices[i];
                    // For intermediate steps, keep all indices needed downstream
                    let is_last = i == tensors.len() - 1;
                    let intermediate_out: Vec<char> = if is_last {
                        output_indices.clone()
                    } else {
                        // Keep indices that appear in remaining inputs or final output
                        let mut needed: std::collections::HashSet<char> =
                            output_indices.iter().copied().collect();
                        for idx_set in &input_indices[(i + 1)..] {
                            for &ch in idx_set {
                                needed.insert(ch);
                            }
                        }
                        let mut out: Vec<char> = current_indices
                            .iter()
                            .chain(rhs_indices.iter())
                            .copied()
                            .filter(|ch| needed.contains(ch))
                            .collect();
                        // Deduplicate while preserving order
                        let mut seen = std::collections::HashSet::new();
                        out.retain(|ch| seen.insert(*ch));
                        out
                    };
                    current = self.einsum_binary(
                        &current_indices,
                        rhs_indices,
                        &intermediate_out,
                        current,
                        tensors[i],
                        &dim_sizes,
                    )?;
                    current_indices = intermediate_out;
                }
                Ok(current)
            }
        }
    }

    fn einsum_unary(
        &mut self,
        input_idx: &[char],
        output_idx: &[char],
        tensor: TensorNodeId,
        _dim_sizes: &std::collections::HashMap<char, usize>,
    ) -> Result<TensorNodeId, AutogradError> {
        let make_err = |reason: &'static str| {
            AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet { reason },
            ))
        };

        // Check for trace pattern: repeated index in input
        let mut repeated: Vec<char> = Vec::new();
        {
            let mut seen = std::collections::HashSet::new();
            for &ch in input_idx {
                if !seen.insert(ch) && !repeated.contains(&ch) {
                    repeated.push(ch);
                }
            }
        }

        if !repeated.is_empty() {
            // Trace-like: extract diagonal(s) then sum/permute
            if repeated.len() == 1 {
                let repeated_ch = repeated[0];
                let repeated_positions: Vec<usize> = input_idx
                    .iter()
                    .enumerate()
                    .filter_map(|(position, &ch)| (ch == repeated_ch).then_some(position))
                    .collect();
                if repeated_positions.len() == 2 {
                    return self.einsum_unary_single_repeated_index(
                        input_idx,
                        output_idx,
                        tensor,
                        &repeated_positions,
                    );
                }
            }
            return Err(make_err(
                "einsum: unsupported repeated-index pattern for single operand",
            ));
        }

        // No repeated indices: transpose + sum over contracted dims
        // First, figure out which input dims map to which output dims
        let contract_dims: Vec<usize> = input_idx
            .iter()
            .enumerate()
            .filter(|(_, ch)| !output_idx.contains(ch))
            .map(|(i, _)| i)
            .collect();

        let mut current = tensor;

        if output_idx.is_empty() && contract_dims.len() == input_idx.len() {
            // Sum all elements
            let shape = self.tensor_shape(current)?;
            let total = Self::checked_shape_numel(&shape, "einsum: input shape volume overflow")?;
            let flat = self.tensor_reshape(current, vec![total])?;
            return self.tensor_sum_dim(flat, 0);
        }

        // Permute to bring output indices first, then contracted dims
        let mut perm: Vec<usize> = Vec::with_capacity(input_idx.len());
        for &out_ch in output_idx {
            let pos = input_idx
                .iter()
                .position(|&ch| ch == out_ch)
                .ok_or_else(|| make_err("einsum: output index not found in input"))?;
            perm.push(pos);
        }
        for &cd in &contract_dims {
            perm.push(cd);
        }

        if perm.len() == input_idx.len() {
            // Check if permutation is identity
            let is_identity = perm.iter().enumerate().all(|(i, &v)| v == i);
            if !is_identity {
                current = self.tensor_permute(current, perm)?;
            }
        }

        // Sum over the trailing (contracted) dimensions from last to first
        for _ in 0..contract_dims.len() {
            let shape = self.tensor_shape(current)?;
            let last_dim = shape.len() - 1;
            current = self.tensor_sum_dim(current, last_dim)?;
        }

        // If output is scalar, ensure shape
        if output_idx.is_empty() {
            let shape = self.tensor_shape(current)?;
            if shape != [1] {
                current = self.tensor_reshape(current, vec![1])?;
            }
        }

        Ok(current)
    }

    fn einsum_unary_single_repeated_index(
        &mut self,
        input_idx: &[char],
        output_idx: &[char],
        tensor: TensorNodeId,
        repeated_positions: &[usize],
    ) -> Result<TensorNodeId, AutogradError> {
        let make_err = |reason: &'static str| {
            AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet { reason },
            ))
        };

        let mut seen_output = std::collections::HashSet::new();
        for &ch in output_idx {
            if !seen_output.insert(ch) {
                return Err(make_err("einsum: duplicate output index"));
            }
            if !input_idx.contains(&ch) {
                return Err(make_err("einsum: output index not found in input"));
            }
        }

        let shape = self.tensor_shape(tensor)?;
        let first_repeated = repeated_positions[0];
        let second_repeated = repeated_positions[1];
        if shape[first_repeated] != shape[second_repeated] {
            return Err(make_err(
                "einsum: dimension size mismatch for repeated index",
            ));
        }

        let output_positions: Vec<usize> = output_idx
            .iter()
            .map(|&ch| {
                input_idx
                    .iter()
                    .position(|&input_ch| input_ch == ch)
                    .expect("output index membership validated above")
            })
            .collect();
        let output_shape = if output_positions.is_empty() {
            vec![1]
        } else {
            output_positions
                .iter()
                .map(|&position| shape[position])
                .collect()
        };
        let output_len =
            Self::checked_shape_numel(&output_shape, "einsum: output shape volume overflow")?;
        let input_len = Self::checked_shape_numel(&shape, "einsum: input shape volume overflow")?;
        let input_strides = contiguous_strides(&shape);
        let output_strides = contiguous_strides(&output_shape);
        let mut input_to_output = Vec::new();

        for input_linear in 0..input_len {
            let first_coord =
                (input_linear / input_strides[first_repeated]) % shape[first_repeated];
            let second_coord =
                (input_linear / input_strides[second_repeated]) % shape[second_repeated];
            if first_coord != second_coord {
                continue;
            }

            let mut output_linear = 0usize;
            for (output_dim, &input_dim) in output_positions.iter().enumerate() {
                let coord = (input_linear / input_strides[input_dim]) % shape[input_dim];
                let offset = Self::checked_mul(
                    coord,
                    output_strides[output_dim],
                    "einsum: output index overflow",
                )?;
                output_linear =
                    Self::checked_add(output_linear, offset, "einsum: output index overflow")?;
            }
            input_to_output.push((input_linear, output_linear));
        }

        match self.tensor_dtype(tensor)? {
            DType::F64 | DType::F32 => {
                let forward_map = input_to_output.clone();
                let backward_map = input_to_output;
                let output_shape_for_forward = output_shape.clone();
                self.tensor_apply_function(
                    &[tensor],
                    move |_ctx, inputs| {
                        let (values, _shape) = inputs[0];
                        let mut output = vec![0.0_f64; output_len];
                        for &(input_linear, output_linear) in &forward_map {
                            output[output_linear] += values[input_linear];
                        }
                        Ok((output, output_shape_for_forward.clone()))
                    },
                    move |_ctx, grad_outputs| {
                        let grad_output = grad_outputs[0];
                        let mut grad_input = vec![0.0_f64; input_len];
                        for &(input_linear, output_linear) in &backward_map {
                            grad_input[input_linear] += grad_output[output_linear];
                        }
                        Ok(vec![Some(grad_input)])
                    },
                )
            }
            _ => Err(make_err(
                "einsum: repeated-index unary requires f32 or f64 tensor",
            )),
        }
    }

    fn einsum_binary(
        &mut self,
        lhs_idx: &[char],
        rhs_idx: &[char],
        output_idx: &[char],
        lhs: TensorNodeId,
        rhs: TensorNodeId,
        _dim_sizes: &std::collections::HashMap<char, usize>,
    ) -> Result<TensorNodeId, AutogradError> {
        let make_err = |reason: &'static str| {
            AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet { reason },
            ))
        };

        // Categorize indices:
        // - batch: appear in both inputs AND in output
        // - contract: appear in both inputs but NOT in output
        // - free_lhs: appear only in lhs (and in output)
        // - free_rhs: appear only in rhs (and in output)
        let lhs_set: std::collections::HashSet<char> = lhs_idx.iter().copied().collect();
        let rhs_set: std::collections::HashSet<char> = rhs_idx.iter().copied().collect();

        let mut batch_chars: Vec<char> = Vec::new();
        let mut contract_chars: Vec<char> = Vec::new();
        let mut free_lhs_chars: Vec<char> = Vec::new();
        let mut free_rhs_chars: Vec<char> = Vec::new();

        // Process lhs indices in order
        for &ch in lhs_idx {
            if rhs_set.contains(&ch) {
                if output_idx.contains(&ch) {
                    if !batch_chars.contains(&ch) {
                        batch_chars.push(ch);
                    }
                } else if !contract_chars.contains(&ch) {
                    contract_chars.push(ch);
                }
            } else if !free_lhs_chars.contains(&ch) {
                free_lhs_chars.push(ch);
            }
        }
        for &ch in rhs_idx {
            if !lhs_set.contains(&ch) && !free_rhs_chars.contains(&ch) {
                free_rhs_chars.push(ch);
            }
        }

        // Helpers to locate a subscript char's axis in the original index lists.
        // These chars are categorized FROM lhs_idx/rhs_idx, but return an error
        // if invariants are violated to avoid panics.
        let lhs_pos = |ch: &char| -> Result<usize, AutogradError> {
            lhs_idx
                .iter()
                .position(|c| c == ch)
                .ok_or_else(|| make_err("einsum: subscript char not found in lhs indices"))
        };
        let rhs_pos = |ch: &char| -> Result<usize, AutogradError> {
            rhs_idx
                .iter()
                .position(|c| c == ch)
                .ok_or_else(|| make_err("einsum: subscript char not found in rhs indices"))
        };

        // Build permutation for lhs: [batch..., free_lhs..., contract...]
        let mut lhs_perm =
            Vec::with_capacity(batch_chars.len() + free_lhs_chars.len() + contract_chars.len());
        for ch in batch_chars
            .iter()
            .chain(free_lhs_chars.iter())
            .chain(contract_chars.iter())
        {
            lhs_perm.push(lhs_pos(ch)?);
        }

        // Build permutation for rhs: [batch..., contract..., free_rhs...]
        let mut rhs_perm =
            Vec::with_capacity(batch_chars.len() + contract_chars.len() + free_rhs_chars.len());
        for ch in batch_chars
            .iter()
            .chain(contract_chars.iter())
            .chain(free_rhs_chars.iter())
        {
            rhs_perm.push(rhs_pos(ch)?);
        }

        let lhs_shape = self.tensor_shape(lhs)?;
        let rhs_shape = self.tensor_shape(rhs)?;

        // Compute dimension sizes after permutation
        let mut batch_size: usize = 1;
        for ch in &batch_chars {
            let dim = lhs_shape[lhs_pos(ch)?];
            batch_size = batch_size
                .checked_mul(dim)
                .ok_or_else(|| make_err("einsum: batch size overflow"))?;
        }
        let mut free_lhs_size: usize = 1;
        for ch in &free_lhs_chars {
            let dim = lhs_shape[lhs_pos(ch)?];
            free_lhs_size = free_lhs_size
                .checked_mul(dim)
                .ok_or_else(|| make_err("einsum: free lhs size overflow"))?;
        }
        let mut contract_size: usize = 1;
        for ch in &contract_chars {
            let dim = lhs_shape[lhs_pos(ch)?];
            contract_size = contract_size
                .checked_mul(dim)
                .ok_or_else(|| make_err("einsum: contract size overflow"))?;
        }
        let mut free_rhs_size: usize = 1;
        for ch in &free_rhs_chars {
            let dim = rhs_shape[rhs_pos(ch)?];
            free_rhs_size = free_rhs_size
                .checked_mul(dim)
                .ok_or_else(|| make_err("einsum: free rhs size overflow"))?;
        }

        if batch_chars.is_empty()
            && !contract_chars.is_empty()
            && !self.tensor_requires_grad(lhs)?
            && !self.tensor_requires_grad(rhs)?
            && self.tensor_dtype(lhs)? == DType::F64
            && self.tensor_dtype(rhs)? == DType::F64
        {
            let expected_lhs: Vec<char> = free_lhs_chars
                .iter()
                .chain(contract_chars.iter())
                .copied()
                .collect();
            let expected_rhs: Vec<char> = free_rhs_chars
                .iter()
                .chain(contract_chars.iter())
                .copied()
                .collect();
            let expected_out: Vec<char> = free_lhs_chars
                .iter()
                .chain(free_rhs_chars.iter())
                .copied()
                .collect();
            if lhs_idx == expected_lhs.as_slice()
                && rhs_idx == expected_rhs.as_slice()
                && output_idx == expected_out.as_slice()
            {
                let (lhs_values, lhs_meta) = self.tensor_values_meta(lhs)?;
                let (rhs_values, rhs_meta) = self.tensor_values_meta(rhs)?;
                let lhs_contiguous = lhs_meta.strides() == contiguous_strides(lhs_meta.shape());
                let rhs_contiguous = rhs_meta.strides() == contiguous_strides(rhs_meta.shape());
                let m = free_lhs_size.max(1);
                let k = contract_size.max(1);
                let n = free_rhs_size.max(1);
                let lhs_start = lhs_meta.storage_offset();
                let rhs_start = rhs_meta.storage_offset();
                if lhs_contiguous
                    && rhs_contiguous
                    && lhs_values.len() >= lhs_start + m * k
                    && rhs_values.len() >= rhs_start + n * k
                {
                    let out = ft_kernel_cpu::matmul_rhs_transposed_contiguous_f64(
                        m,
                        k,
                        n,
                        &lhs_values[lhs_start..lhs_start + m * k],
                        &rhs_values[rhs_start..rhs_start + n * k],
                    )
                    .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?;
                    let mut out_shape: Vec<usize> = Vec::new();
                    for ch in &free_lhs_chars {
                        out_shape.push(lhs_shape[lhs_pos(ch)?]);
                    }
                    for ch in &free_rhs_chars {
                        out_shape.push(rhs_shape[rhs_pos(ch)?]);
                    }
                    if out_shape.is_empty() {
                        out_shape.push(1);
                    }
                    return self.tensor_variable(out, out_shape, false);
                }
            }
        }

        if !batch_chars.is_empty()
            && !contract_chars.is_empty()
            && !self.tensor_requires_grad(lhs)?
            && !self.tensor_requires_grad(rhs)?
            && self.tensor_dtype(lhs)? == DType::F64
            && self.tensor_dtype(rhs)? == DType::F64
        {
            let expected_lhs: Vec<char> = batch_chars
                .iter()
                .chain(free_lhs_chars.iter())
                .chain(contract_chars.iter())
                .copied()
                .collect();
            let expected_rhs: Vec<char> = batch_chars
                .iter()
                .chain(free_rhs_chars.iter())
                .chain(contract_chars.iter())
                .copied()
                .collect();
            let expected_out: Vec<char> = batch_chars
                .iter()
                .chain(free_lhs_chars.iter())
                .chain(free_rhs_chars.iter())
                .copied()
                .collect();
            if lhs_idx == expected_lhs.as_slice()
                && rhs_idx == expected_rhs.as_slice()
                && output_idx == expected_out.as_slice()
            {
                let (lhs_values, lhs_meta) = self.tensor_values_meta(lhs)?;
                let (rhs_values, rhs_meta) = self.tensor_values_meta(rhs)?;
                let lhs_contiguous = lhs_meta.strides() == contiguous_strides(lhs_meta.shape());
                let rhs_contiguous = rhs_meta.strides() == contiguous_strides(rhs_meta.shape());
                let b = batch_size;
                let m = free_lhs_size;
                let k = contract_size;
                let n = free_rhs_size;
                let lhs_batch_stride = m
                    .checked_mul(k)
                    .ok_or_else(|| make_err("einsum: lhs batch stride overflow"))?;
                let rhs_batch_stride = n
                    .checked_mul(k)
                    .ok_or_else(|| make_err("einsum: rhs batch stride overflow"))?;
                let out_batch_stride = m
                    .checked_mul(n)
                    .ok_or_else(|| make_err("einsum: output batch stride overflow"))?;
                let lhs_start = lhs_meta.storage_offset();
                let rhs_start = rhs_meta.storage_offset();
                let lhs_required = b
                    .checked_mul(lhs_batch_stride)
                    .and_then(|len| lhs_start.checked_add(len))
                    .ok_or_else(|| make_err("einsum: lhs storage length overflow"))?;
                let rhs_required = b
                    .checked_mul(rhs_batch_stride)
                    .and_then(|len| rhs_start.checked_add(len))
                    .ok_or_else(|| make_err("einsum: rhs storage length overflow"))?;
                if lhs_contiguous
                    && rhs_contiguous
                    && b > 0
                    && m > 0
                    && k > 0
                    && n > 0
                    && lhs_values.len() >= lhs_required
                    && rhs_values.len() >= rhs_required
                {
                    let mut out = vec![0.0_f64; b * out_batch_stride];
                    use rayon::prelude::*;
                    out.par_chunks_mut(out_batch_stride)
                        .enumerate()
                        .try_for_each(|(batch_idx, out_chunk)| {
                            let lhs_offset = lhs_start + batch_idx * lhs_batch_stride;
                            let rhs_offset = rhs_start + batch_idx * rhs_batch_stride;
                            let batch_out = ft_kernel_cpu::matmul_rhs_transposed_contiguous_f64(
                                m,
                                k,
                                n,
                                &lhs_values[lhs_offset..lhs_offset + lhs_batch_stride],
                                &rhs_values[rhs_offset..rhs_offset + rhs_batch_stride],
                            )
                            .map_err(|e| {
                                AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                            })?;
                            out_chunk.copy_from_slice(&batch_out);
                            Ok::<(), AutogradError>(())
                        })?;
                    let mut out_shape: Vec<usize> = Vec::new();
                    for ch in &batch_chars {
                        out_shape.push(lhs_shape[lhs_pos(ch)?]);
                    }
                    for ch in &free_lhs_chars {
                        out_shape.push(lhs_shape[lhs_pos(ch)?]);
                    }
                    for ch in &free_rhs_chars {
                        out_shape.push(rhs_shape[rhs_pos(ch)?]);
                    }
                    if out_shape.is_empty() {
                        out_shape.push(1);
                    }
                    return self.tensor_variable(out, out_shape, false);
                }
            }
        }

        // Permute tensors
        let mut lhs_p = lhs;
        if !lhs_perm.iter().enumerate().all(|(i, &v)| v == i) {
            lhs_p = self.tensor_permute(lhs_p, lhs_perm)?;
        }
        let mut rhs_p = rhs;
        if !rhs_perm.iter().enumerate().all(|(i, &v)| v == i) {
            rhs_p = self.tensor_permute(rhs_p, rhs_perm)?;
        }

        // Handle the case where there are no contractions (element-wise or outer product)
        if contract_chars.is_empty() && batch_chars.is_empty() {
            // Outer product case: reshape lhs to [M, 1], rhs to [1, N], matmul
            let m = free_lhs_size.max(1);
            let n = free_rhs_size.max(1);
            let lhs_2d = self.tensor_reshape(lhs_p, vec![m, 1])?;
            let rhs_2d = self.tensor_reshape(rhs_p, vec![1, n])?;
            let result = self.tensor_matmul(lhs_2d, rhs_2d)?;
            // Reshape to output shape
            let mut out_shape: Vec<usize> = Vec::new();
            for &ch in output_idx {
                if free_lhs_chars.contains(&ch) {
                    out_shape.push(lhs_shape[lhs_pos(&ch)?]);
                } else if free_rhs_chars.contains(&ch) {
                    out_shape.push(rhs_shape[rhs_pos(&ch)?]);
                }
            }
            if out_shape.is_empty() {
                out_shape.push(1);
            }
            return self.tensor_reshape(result, out_shape);
        }

        if contract_chars.is_empty() {
            // Batch + free only: element-wise multiply with broadcasting
            let m = free_lhs_size.max(1);
            let n = free_rhs_size.max(1);
            let lhs_3d = self.tensor_reshape(lhs_p, vec![batch_size, m, 1])?;
            let rhs_3d = self.tensor_reshape(rhs_p, vec![batch_size, 1, n])?;
            let result = self.tensor_bmm(lhs_3d, rhs_3d)?;
            let mut out_shape: Vec<usize> = Vec::new();
            for &ch in output_idx {
                if batch_chars.contains(&ch) || free_lhs_chars.contains(&ch) {
                    out_shape.push(lhs_shape[lhs_pos(&ch)?]);
                } else if free_rhs_chars.contains(&ch) {
                    out_shape.push(rhs_shape[rhs_pos(&ch)?]);
                }
            }
            if out_shape.is_empty() {
                out_shape.push(1);
            }
            return self.tensor_reshape(result, out_shape);
        }

        // General case with contraction
        let m = free_lhs_size.max(1);
        let k = contract_size.max(1);
        let n = free_rhs_size.max(1);

        let result = if batch_chars.is_empty() {
            // No batch: 2D matmul [M, K] @ [K, N] -> [M, N]
            let lhs_2d = self.tensor_reshape(lhs_p, vec![m, k])?;
            let rhs_2d = self.tensor_reshape(rhs_p, vec![k, n])?;
            self.tensor_matmul(lhs_2d, rhs_2d)?
        } else {
            // Batch: 3D bmm [B, M, K] @ [B, K, N] -> [B, M, N]
            let b = batch_size;
            let lhs_3d = self.tensor_reshape(lhs_p, vec![b, m, k])?;
            let rhs_3d = self.tensor_reshape(rhs_p, vec![b, k, n])?;
            self.tensor_bmm(lhs_3d, rhs_3d)?
        };

        // Reshape to output shape
        let mut out_shape: Vec<usize> = Vec::new();
        for &ch in output_idx {
            if batch_chars.contains(&ch)
                || free_lhs_chars.contains(&ch)
                || contract_chars.contains(&ch)
            {
                out_shape.push(lhs_shape[lhs_pos(&ch)?]);
            } else if free_rhs_chars.contains(&ch) {
                out_shape.push(rhs_shape[rhs_pos(&ch)?]);
            }
        }

        if out_shape.is_empty() {
            // Scalar output: already [B, M, N] = [1, 1, 1]
            let flat = self.tensor_reshape(result, vec![1])?;
            return Ok(flat);
        }

        self.tensor_reshape(result, out_shape)
    }

    /// Apply a custom autograd function.
    ///
    /// `forward_fn` receives a `&mut FunctionCtx` and input data (values + shapes),
    /// returns output (values, shape).
    ///
    /// `backward_fn` receives the saved context and incoming gradients,
    /// returns one `Option<Vec<f64>>` per input.
    pub fn tensor_apply_function<F, B>(
        &mut self,
        inputs: &[TensorNodeId],
        forward_fn: F,
        backward_fn: B,
    ) -> Result<TensorNodeId, AutogradError>
    where
        F: FnOnce(
            &mut FunctionCtx,
            &[(&[f64], &[usize])],
        ) -> Result<(Vec<f64>, Vec<usize>), AutogradError>,
        B: Fn(&FunctionCtx, &[&[f64]]) -> Result<Vec<Option<Vec<f64>>>, AutogradError>
            + Send
            + Sync
            + 'static,
    {
        self.tensor_tape
            .apply_function(inputs, forward_fn, backward_fn)
    }

    /// Like [`Self::tensor_apply_function`] but also registers a create_graph
    /// backward so the custom function is DOUBLE-differentiable (2nd derivatives /
    /// Hessian / hvp). The `cg` closure builds the input-gradient nodes from
    /// differentiable tape ops (e.g. `tape.exp`/`tape.mul_scalar`) instead of
    /// detached values, so a second backward propagates through them.
    /// frankentorch-1avc3.
    pub fn tensor_apply_function_with_create_graph<F, B, CG>(
        &mut self,
        inputs: &[TensorNodeId],
        forward_fn: F,
        backward_fn: B,
        create_graph_backward_fn: CG,
    ) -> Result<TensorNodeId, AutogradError>
    where
        F: FnOnce(
            &mut FunctionCtx,
            &[(&[f64], &[usize])],
        ) -> Result<(Vec<f64>, Vec<usize>), AutogradError>,
        B: Fn(&FunctionCtx, &[&[f64]]) -> Result<Vec<Option<Vec<f64>>>, AutogradError>
            + Send
            + Sync
            + 'static,
        CG: Fn(
                &FunctionCtx,
                &[TensorNodeId],
                &[TensorNodeId],
                &mut ft_autograd::TensorTape,
            ) -> Result<Vec<Option<TensorNodeId>>, AutogradError>
            + Send
            + Sync
            + 'static,
    {
        self.tensor_tape.apply_function_with_create_graph(
            inputs,
            forward_fn,
            backward_fn,
            create_graph_backward_fn,
        )
    }

    /// Apply a f64-only custom autograd function whose backward closure borrows
    /// the immutable input slices from the tape instead of saving owned copies.
    pub fn tensor_apply_function_f64_borrowed_inputs<F, B>(
        &mut self,
        inputs: &[TensorNodeId],
        forward_fn: F,
        backward_fn: B,
    ) -> Result<TensorNodeId, AutogradError>
    where
        F: FnOnce(
            &mut FunctionCtx,
            &[(&[f64], &[usize])],
        ) -> Result<(Vec<f64>, Vec<usize>), AutogradError>,
        B: Fn(
                &FunctionCtx,
                &[&[f64]],
                &[(&[f64], &[usize])],
            ) -> Result<Vec<Option<Vec<f64>>>, AutogradError>
            + Send
            + Sync
            + 'static,
    {
        self.tensor_tape
            .apply_function_f64_borrowed_inputs(inputs, forward_fn, backward_fn)
    }

    /// Apply a f64-only custom autograd function whose forward borrows input
    /// slices, while backward uses only saved context plus output gradients.
    pub fn tensor_apply_function_f64_borrowed_forward<F, B>(
        &mut self,
        inputs: &[TensorNodeId],
        forward_fn: F,
        backward_fn: B,
    ) -> Result<TensorNodeId, AutogradError>
    where
        F: FnOnce(
            &mut FunctionCtx,
            &[(&[f64], &[usize])],
        ) -> Result<(Vec<f64>, Vec<usize>), AutogradError>,
        B: Fn(&FunctionCtx, &[&[f64]]) -> Result<Vec<Option<Vec<f64>>>, AutogradError>
            + Send
            + Sync
            + 'static,
    {
        self.tensor_tape
            .apply_function_f64_borrowed_forward(inputs, forward_fn, backward_fn)
    }

    /// f32-output custom autograd op: inputs read as f32, forward returns an f32
    /// output (F32 leaf), backward receives the f64 incoming grad + f32 borrowed
    /// inputs and returns f64 input grads. Enables f32 conv/depthwise/linear grad
    /// fast paths whose output must stay f32. frankentorch-48w0b.
    pub fn tensor_apply_function_f32_output_borrowed_inputs<F, B>(
        &mut self,
        inputs: &[TensorNodeId],
        forward_fn: F,
        backward_fn: B,
    ) -> Result<TensorNodeId, AutogradError>
    where
        F: FnOnce(
            &mut FunctionCtx,
            &[(&[f32], &[usize])],
        ) -> Result<(Vec<f32>, Vec<usize>), AutogradError>,
        B: Fn(
                &FunctionCtx,
                &[&[f64]],
                &[(&[f32], &[usize])],
            ) -> Result<Vec<Option<Vec<f64>>>, AutogradError>
            + Send
            + Sync
            + 'static,
    {
        self.tensor_tape
            .apply_function_f32_output_borrowed_inputs(inputs, forward_fn, backward_fn)
    }

    /// f32-native no-grad elementwise UNARY fast path: read the f32 input BORROWED and compute
    /// `f(x as f64) as f32` in one parallel pass — no f32->f64 upcast / generic `apply_function`
    /// (which is f64-oriented and upcasts the whole buffer = ~5-15x SLOWER for f32). Returns
    /// `Some(out)` on the fast path, `None` to fall through. BIT-IDENTICAL to the existing f32
    /// behaviour (which already computes each value in f64 then narrows to f32 — `x as f64` is
    /// exact), so conformance is unchanged BY CONSTRUCTION. f32 contiguous no-grad only.
    fn try_f32_unary_native<F: Fn(f64) -> f64 + Sync>(
        &mut self,
        input: TensorNodeId,
        f: F,
    ) -> Result<Option<TensorNodeId>, AutogradError> {
        if self.tensor_requires_grad(input)? || self.tensor_dtype(input)? != DType::F32 {
            return Ok(None);
        }
        let built = {
            let t = self.tensor_tape.tensor(input)?;
            if t.meta().is_contiguous() {
                use rayon::prelude::*;
                let v = t.contiguous_values_f32()?;
                let out: Vec<f32> = if v.len() >= PARALLEL_ELEMENTWISE_MIN {
                    v.par_iter().map(|&x| f(x as f64) as f32).collect()
                } else {
                    v.iter().map(|&x| f(x as f64) as f32).collect()
                };
                Some((out, t.meta().shape().to_vec()))
            } else {
                None
            }
        };
        match built {
            Some((out, shape)) => Ok(Some(self.tensor_variable_f32(out, shape, false)?)),
            None => Ok(None),
        }
    }

    /// f64-native no-grad elementwise UNARY fast path: compute `f(x)` in ONE parallel pass. Sibling of
    /// [`Self::try_f32_unary_native`] for the F64 case — many transcendental ops added the f32 native
    /// path but left F64 riding a multi-op autograd COMPOSE (e.g. atanh = 0.5*ln((1+x)/(1-x)) = ~7
    /// tape passes). When `f` is the SAME closure the f32 path uses (which the compose's f64 formula is
    /// built from, op-for-op), this is BIT-EXACT to the F64 compose — just fused. no-grad / contiguous
    /// / F64 only; everything else falls through.
    fn try_f64_unary_native<F: Fn(f64) -> f64 + Sync>(
        &mut self,
        input: TensorNodeId,
        f: F,
    ) -> Result<Option<TensorNodeId>, AutogradError> {
        if self.tensor_requires_grad(input)? || self.tensor_dtype(input)? != DType::F64 {
            return Ok(None);
        }
        let built = {
            let t = self.tensor_tape.tensor(input)?;
            if t.meta().is_contiguous() {
                use rayon::prelude::*;
                let v = t.contiguous_values()?;
                let out: Vec<f64> = if v.len() >= PARALLEL_ELEMENTWISE_MIN {
                    v.par_iter().map(|&x| f(x)).collect()
                } else {
                    v.iter().map(|&x| f(x)).collect()
                };
                Some((out, t.meta().shape().to_vec()))
            } else {
                None
            }
        };
        match built {
            Some((out, shape)) => Ok(Some(self.tensor_variable(out, shape, false)?)),
            None => Ok(None),
        }
    }

    /// f32-native no-grad elementwise BINARY fast path (equal-shape, both f32): compute
    /// `f(x as f64, y as f64) as f32` in one parallel pass — no f32->f64 upcast. Same
    /// bit-identical-to-current-f32 / conformance-preserved property as
    /// [`Self::try_f32_unary_native`]. Equal-shape contiguous no-grad only (broadcast /
    /// non-contiguous / non-f32 fall through).
    fn try_f32_binary_native<F: Fn(f64, f64) -> f64 + Sync>(
        &mut self,
        x: TensorNodeId,
        y: TensorNodeId,
        f: F,
    ) -> Result<Option<TensorNodeId>, AutogradError> {
        if self.tensor_requires_grad(x)?
            || self.tensor_requires_grad(y)?
            || self.tensor_dtype(x)? != DType::F32
            || self.tensor_dtype(y)? != DType::F32
            || self.tensor_shape(x)? != self.tensor_shape(y)?
        {
            return Ok(None);
        }
        let built = {
            let tx = self.tensor_tape.tensor(x)?;
            let ty = self.tensor_tape.tensor(y)?;
            if tx.meta().is_contiguous() && ty.meta().is_contiguous() {
                use rayon::prelude::*;
                let xv = tx.contiguous_values_f32()?;
                let yv = ty.contiguous_values_f32()?;
                if xv.len() == yv.len() {
                    let out: Vec<f32> = if xv.len() >= PARALLEL_ELEMENTWISE_MIN {
                        xv.par_iter()
                            .zip(yv.par_iter())
                            .map(|(&a, &b)| f(a as f64, b as f64) as f32)
                            .collect()
                    } else {
                        xv.iter()
                            .zip(yv.iter())
                            .map(|(&a, &b)| f(a as f64, b as f64) as f32)
                            .collect()
                    };
                    Some((out, tx.meta().shape().to_vec()))
                } else {
                    None
                }
            } else {
                None
            }
        };
        match built {
            Some((out, shape)) => Ok(Some(self.tensor_variable_f32(out, shape, false)?)),
            None => Ok(None),
        }
    }

    /// f64-native no-grad elementwise BINARY fast path (equal-shape, both f64): compute `f(x, y)` in
    /// ONE parallel pass. Sibling of [`Self::try_f32_binary_native`] for the F64 case — many binary
    /// special ops added the f32 native path but left F64 riding a multi-op autograd COMPOSE (e.g.
    /// rel_entr = ~13 tape ops). When `f` is the SAME closure the f32 path uses (which the compose's
    /// f64 formula is built from op-for-op), this is BIT-EXACT to the F64 compose — just fused.
    /// no-grad / equal-shape / contiguous / both-F64 only; everything else falls through.
    fn try_f64_binary_native<F: Fn(f64, f64) -> f64 + Sync>(
        &mut self,
        x: TensorNodeId,
        y: TensorNodeId,
        f: F,
    ) -> Result<Option<TensorNodeId>, AutogradError> {
        if self.tensor_requires_grad(x)?
            || self.tensor_requires_grad(y)?
            || self.tensor_dtype(x)? != DType::F64
            || self.tensor_dtype(y)? != DType::F64
            || self.tensor_shape(x)? != self.tensor_shape(y)?
        {
            return Ok(None);
        }
        let built = {
            let tx = self.tensor_tape.tensor(x)?;
            let ty = self.tensor_tape.tensor(y)?;
            if tx.meta().is_contiguous() && ty.meta().is_contiguous() {
                use rayon::prelude::*;
                let xv = tx.contiguous_values()?;
                let yv = ty.contiguous_values()?;
                if xv.len() == yv.len() {
                    let out: Vec<f64> = if xv.len() >= PARALLEL_ELEMENTWISE_MIN {
                        xv.par_iter()
                            .zip(yv.par_iter())
                            .map(|(&a, &b)| f(a, b))
                            .collect()
                    } else {
                        xv.iter().zip(yv.iter()).map(|(&a, &b)| f(a, b)).collect()
                    };
                    Some((out, tx.meta().shape().to_vec()))
                } else {
                    None
                }
            } else {
                None
            }
        };
        match built {
            Some((out, shape)) => Ok(Some(self.tensor_variable(out, shape, false)?)),
            None => Ok(None),
        }
    }

    /// Cross product of two 3-element vectors.
    ///
    /// Both inputs must be 1D tensors of length 3.
    /// Returns a 1D tensor of length 3: c = a × b.
    pub fn tensor_cross(
        &mut self,
        a: TensorNodeId,
        b: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let a_shape = self.tensor_shape(a)?;
        let b_shape = self.tensor_shape(b)?;
        // No-grad fast path: the batched cross composes narrow/mul/sub/cat (multi-pass) and
        // measured 17x SLOWER than torch at [5M,3]. When the (first) size-3 axis IS the last
        // dim — the common batched [..,3] case, matching FT's first-size-3-dim rule — each row
        // is a contiguous 3-vector; borrow both and compute the per-row cross in ONE parallel
        // pass. Bit-exact with the composed path (same a_i*b_j - a_j*b_i products). Grad /
        // non-f64 / non-contiguous / size-3-not-last fall through.
        if a_shape == b_shape
            && a_shape.iter().position(|&d| d == 3) == Some(a_shape.len().wrapping_sub(1))
            && !a_shape.is_empty()
            && !self.tensor_requires_grad(a)?
            && !self.tensor_requires_grad(b)?
            && self.tensor_dtype(a)? == self.tensor_dtype(b)?
            && matches!(self.tensor_dtype(a)?, DType::F64 | DType::F32)
        {
            // f32 MIRROR of the f64 per-row fast path: f32 input previously fell through to the
            // composed narrow/mul/sub/cat path (multi-pass, ~17x+ SLOWER as the comment notes —
            // measured 287x at [1M,3]). Borrow both f32 rows and compute the cross in ONE parallel
            // pass natively (no upcast). Bit-exact with the composed f32 path (same f32 a_i*b_j -
            // a_j*b_i mul-then-sub). f64 path unchanged below.
            if self.tensor_dtype(a)? == DType::F32 {
                let built = {
                    let at = self.tensor_tape.tensor(a)?;
                    let bt = self.tensor_tape.tensor(b)?;
                    if at.meta().is_contiguous() && bt.meta().is_contiguous() {
                        let ad = at.contiguous_values_f32()?;
                        let bd = bt.contiguous_values_f32()?;
                        if ad.len() == bd.len() && ad.len() % 3 == 0 {
                            use rayon::prelude::*;
                            let mut out = vec![0.0f32; ad.len()];
                            // Batch ~8192 rows per rayon task (par_chunks_mut(3) would spawn one
                            // tiny task PER 3-vector = millions of tasks, scheduling-bound). Inner
                            // loop walks the rows in each block; per-row arithmetic is unchanged,
                            // so bit-identical to the composed f32 path.
                            const ROWS_PER_TASK: usize = 8192;
                            out.par_chunks_mut(3 * ROWS_PER_TASK).enumerate().for_each(
                                |(blk, block)| {
                                    let row0 = blk * ROWS_PER_TASK;
                                    for (lr, c) in block.chunks_mut(3).enumerate() {
                                        let base = (row0 + lr) * 3;
                                        let (a0, a1, a2) = (ad[base], ad[base + 1], ad[base + 2]);
                                        let (b0, b1, b2) = (bd[base], bd[base + 1], bd[base + 2]);
                                        c[0] = a1 * b2 - a2 * b1;
                                        c[1] = a2 * b0 - a0 * b2;
                                        c[2] = a0 * b1 - a1 * b0;
                                    }
                                },
                            );
                            Some(out)
                        } else {
                            None
                        }
                    } else {
                        None
                    }
                };
                if let Some(out) = built {
                    return self.tensor_variable_f32(out, a_shape, false);
                }
            } else {
                let built = {
                    let at = self.tensor_tape.tensor(a)?;
                    let bt = self.tensor_tape.tensor(b)?;
                    if at.meta().is_contiguous() && bt.meta().is_contiguous() {
                        let ad = at.contiguous_values()?;
                        let bd = bt.contiguous_values()?;
                        if ad.len() == bd.len() && ad.len() % 3 == 0 {
                            use rayon::prelude::*;
                            let mut out = vec![0.0f64; ad.len()];
                            // Batch ~8192 rows per rayon task (mirrors the f32 path above):
                            // par_chunks_mut(3) spawns one tiny task PER 3-vector, which is
                            // scheduling-bound in the L3-resident regime (~2.2x slower at
                            // [1M,3]). Inner loop walks each block's rows; per-row arithmetic
                            // is unchanged → bit-identical to the composed f64 path.
                            const ROWS_PER_TASK: usize = 8192;
                            out.par_chunks_mut(3 * ROWS_PER_TASK).enumerate().for_each(
                                |(blk, block)| {
                                    let row0 = blk * ROWS_PER_TASK;
                                    for (lr, c) in block.chunks_mut(3).enumerate() {
                                        let base = (row0 + lr) * 3;
                                        let (a0, a1, a2) = (ad[base], ad[base + 1], ad[base + 2]);
                                        let (b0, b1, b2) = (bd[base], bd[base + 1], bd[base + 2]);
                                        c[0] = a1 * b2 - a2 * b1;
                                        c[1] = a2 * b0 - a0 * b2;
                                        c[2] = a0 * b1 - a1 * b0;
                                    }
                                },
                            );
                            Some(out)
                        } else {
                            None
                        }
                    } else {
                        None
                    }
                };
                if let Some(out) = built {
                    return self.tensor_variable(out, a_shape, false);
                }
            }
        }
        if a_shape != [3] || b_shape != [3] {
            // Batched cross product (torch.cross): broadcast the operands and take
            // the cross product along the FIRST dimension of size 3, matching
            // torch.cross's default-dim rule. Composed from autograd-aware
            // narrow/mul/sub/cat so gradients flow (bit-exact with the [3] path).
            let bcast = self.tensor_broadcast_tensors(&[a, b])?;
            let (ba, bb) = (bcast[0], bcast[1]);
            let shape = self.tensor_shape(ba)?;
            let dim = shape.iter().position(|&d| d == 3).ok_or_else(|| {
                Self::incompatible_tensor_args("cross: inputs must have a dimension of size 3")
            })?;
            return self.cross_along_dim(ba, bb, dim);
        }

        // Cross product is bilinear, so the Jacobian-vector products
        // are themselves cross products:
        //     grad_a = b × grad_c
        //     grad_b = grad_c × a
        // Wrap in tensor_apply_function with this analytical backward.
        // Save a and b for backward. Tracked under frankentorch-j2rj.
        self.tensor_apply_function(
            &[a, b],
            |ctx, inputs| {
                let (av, _a_shape) = inputs[0];
                let (bv, _b_shape) = inputs[1];
                let result = vec![
                    av[1] * bv[2] - av[2] * bv[1],
                    av[2] * bv[0] - av[0] * bv[2],
                    av[0] * bv[1] - av[1] * bv[0],
                ];
                ctx.save_for_backward(av.to_vec(), vec![3]);
                ctx.save_for_backward(bv.to_vec(), vec![3]);
                Ok((result, vec![3]))
            },
            |ctx, grad_outputs| {
                let g = grad_outputs[0];
                let saved = ctx.saved_tensors();
                let av = &saved[0];
                let bv = &saved[1];
                // grad_a = b × grad_c
                let grad_a = vec![
                    bv[1] * g[2] - bv[2] * g[1],
                    bv[2] * g[0] - bv[0] * g[2],
                    bv[0] * g[1] - bv[1] * g[0],
                ];
                // grad_b = grad_c × a
                let grad_b = vec![
                    g[1] * av[2] - g[2] * av[1],
                    g[2] * av[0] - g[0] * av[2],
                    g[0] * av[1] - g[1] * av[0],
                ];
                Ok(vec![Some(grad_a), Some(grad_b)])
            },
        )
    }

    /// Cross product of `a` and `b` along `dim` (which must have size 3).
    ///
    /// `a` and `b` must already share the same shape (broadcast beforehand).
    /// Composed from autograd-aware narrow/mul/sub/cat: extract the three
    /// components along `dim` and assemble `a × b` = [a1·b2−a2·b1, a2·b0−a0·b2,
    /// a0·b1−a1·b0]. The operand order matches the scalar [3] fast path, so
    /// values are bit-exact and gradients flow through the op graph.
    fn cross_along_dim(
        &mut self,
        a: TensorNodeId,
        b: TensorNodeId,
        dim: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let a0 = self.tensor_narrow(a, dim, 0, 1)?;
        let a1 = self.tensor_narrow(a, dim, 1, 1)?;
        let a2 = self.tensor_narrow(a, dim, 2, 1)?;
        let b0 = self.tensor_narrow(b, dim, 0, 1)?;
        let b1 = self.tensor_narrow(b, dim, 1, 1)?;
        let b2 = self.tensor_narrow(b, dim, 2, 1)?;

        let a1b2 = self.tensor_mul(a1, b2)?;
        let a2b1 = self.tensor_mul(a2, b1)?;
        let c0 = self.tensor_sub(a1b2, a2b1)?;

        let a2b0 = self.tensor_mul(a2, b0)?;
        let a0b2 = self.tensor_mul(a0, b2)?;
        let c1 = self.tensor_sub(a2b0, a0b2)?;

        let a0b1 = self.tensor_mul(a0, b1)?;
        let a1b0 = self.tensor_mul(a1, b0)?;
        let c2 = self.tensor_sub(a0b1, a1b0)?;

        self.tensor_cat(&[c0, c1, c2], dim)
    }

    /// Dot product along the last dimension (batched dot product).
    ///
    /// For 1D inputs: equivalent to `tensor_dot`.
    /// For N-D inputs: dot product along the last dimension, output has one fewer dim.
    pub fn tensor_vecdot(
        &mut self,
        a: TensorNodeId,
        b: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let a_shape = self.tensor_shape(a)?;
        let b_shape = self.tensor_shape(b)?;
        // torch.linalg.vecdot broadcasts the BATCH dimensions and reduces the last
        // (contracted) dimension, which must have equal size in both operands.
        // Equal shapes keep the original fast path; otherwise broadcast first.
        let (a, b, shape) = if a_shape == b_shape {
            (a, b, a_shape)
        } else {
            if a_shape.is_empty() || b_shape.is_empty() || a_shape.last() != b_shape.last() {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                    ft_kernel_cpu::KernelError::ShapeMismatch {
                        lhs: a_shape,
                        rhs: b_shape,
                    },
                )));
            }
            let bcast = self.tensor_broadcast_tensors(&[a, b])?;
            let s = self.tensor_shape(bcast[0])?;
            (bcast[0], bcast[1], s)
        };
        if shape.is_empty() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::InvalidDimension { dim: 0, ndim: 1 },
            )));
        }
        if shape.len() == 1 {
            return self.tensor_dot(a, b);
        }
        // For N-D: element-wise multiply then sum along last dim
        let prod = self.tensor_mul(a, b)?;
        let last_dim = shape.len() - 1;
        self.tensor_sum_dim(prod, last_dim)
    }

    /// Embed a 1D vector as the diagonal of a 2D matrix.
    ///
    /// `diag_embed([1,2,3])` produces `[[1,0,0],[0,2,0],[0,0,3]]`.
    /// `offset` controls which diagonal: 0=main, 1=super, -1=sub.
    pub fn tensor_diag_embed(
        &mut self,
        input: TensorNodeId,
        offset: i32,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        if shape.len() != 1 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::InvalidDimension {
                    dim: shape.len(),
                    ndim: 1,
                },
            )));
        }
        let k = shape[0];
        let abs_offset = offset.unsigned_abs() as usize;
        let n = Self::checked_add(k, abs_offset, "diag_embed: output size overflow")?;
        let numel = Self::checked_mul(n, n, "diag_embed: output size overflow")?;
        let _ = Self::checked_mul(
            numel,
            std::mem::size_of::<f64>(),
            "diag_embed: output size overflow",
        )?;

        // Forward is purely linear in the input — output[row, col] is
        // input[i] when (row, col) is on the requested diagonal,
        // 0 otherwise. Backward extracts the diagonal:
        //     grad_input[i] = grad_output[row, col]
        // for the same (row, col) the forward used. Wrap in
        // tensor_apply_function with this analytical backward.
        // Tracked under frankentorch-d180.
        let positive_offset = offset >= 0;
        // Native-f32 no-grad fast path. The generic apply_function path below UPCASTS the
        // f32 input to f64 and builds the dominant n*n output in f64 (8 bytes/elem) then
        // returns an F64 node -- both a 2x bandwidth waste on the n*n zero-init AND a dtype
        // divergence (torch.diag_embed(f32) -> f32, but apply_function yields f64). Build the
        // n*n result directly in f32. Bit-exact: a pure positional copy of input elements
        // onto the requested diagonal plus an exact 0.0 fill -- no arithmetic, no rounding.
        // Grad / f64 / non-contiguous fall through to the apply_function path (unchanged).
        if !self.tensor_requires_grad(input)? && self.tensor_dtype(input)? == DType::F32 {
            let built = {
                let t = self.tensor_tape.tensor(input)?;
                if t.meta().is_contiguous() {
                    let xd = t.contiguous_values_f32()?;
                    let mut result = vec![0.0_f32; n * n];
                    for (i, &v) in xd.iter().enumerate().take(k) {
                        let (row, col) = if positive_offset {
                            (i, i + abs_offset)
                        } else {
                            (i + abs_offset, i)
                        };
                        result[row * n + col] = v;
                    }
                    Some(result)
                } else {
                    None
                }
            };
            if let Some(result) = built {
                return self.tensor_variable_f32(result, vec![n, n], false);
            }
        }
        self.tensor_apply_function(
            &[input],
            move |_ctx, inputs| {
                let (vals, _in_shape) = inputs[0];
                let mut result = vec![0.0_f64; n * n];
                for (i, &v) in vals.iter().enumerate().take(k) {
                    let (row, col) = if positive_offset {
                        (i, i + abs_offset)
                    } else {
                        (i + abs_offset, i)
                    };
                    result[row * n + col] = v;
                }
                Ok((result, vec![n, n]))
            },
            move |_ctx, grad_outputs| {
                let grad_y = grad_outputs[0];
                let mut grad_in = vec![0.0_f64; k];
                for (i, slot) in grad_in.iter_mut().enumerate().take(k) {
                    let (row, col) = if positive_offset {
                        (i, i + abs_offset)
                    } else {
                        (i + abs_offset, i)
                    };
                    *slot = grad_y[row * n + col];
                }
                Ok(vec![Some(grad_in)])
            },
        )
    }

    /// `torch.diag(input, diagonal=0)` parity dispatch.
    ///
    /// torch.diag is overloaded: a 1-D input becomes a 2-D matrix with
    /// the input on the requested diagonal (delegates to
    /// `tensor_diag_embed`); a 2-D input returns the requested diagonal
    /// as a 1-D tensor (delegates to `tensor_diagonal`). Higher-rank
    /// inputs are rejected — torch raises a `RuntimeError` for them.
    /// Both delegate paths are autograd-aware via the existing
    /// implementations.
    pub fn tensor_diag(
        &mut self,
        input: TensorNodeId,
        diagonal: i64,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        match shape.len() {
            1 => {
                let offset_i32 = i32::try_from(diagonal).map_err(|_| {
                    AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "diag: 1-D diagonal offset out of i32 range",
                        },
                    ))
                })?;
                self.tensor_diag_embed(input, offset_i32)
            }
            2 => self.tensor_diagonal(input, diagonal),
            _ => Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::InvalidDimension {
                    dim: shape.len(),
                    ndim: 2,
                },
            ))),
        }
    }

    /// Return unique elements from a 1D tensor.
    ///
    /// If `sorted` is true (default), output is sorted ascending.
    /// If `return_inverse` is true, also returns index mapping input -> unique.
    /// If `return_counts` is true, also returns count of each unique value.
    pub fn tensor_unique(
        &mut self,
        input: TensorNodeId,
        sorted: bool,
        return_inverse: bool,
        return_counts: bool,
    ) -> Result<(TensorNodeId, Option<TensorNodeId>, Option<TensorNodeId>), AutogradError> {
        if self.tensor_requires_grad(input)? {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "unique: autograd not supported (set deduplication is non-differentiable). Tracked under frankentorch-gec0.",
                },
            )));
        }
        // Lossy f64 read so f32 / f16 / bf16 inputs are accepted instead of erroring in the old
        // F64-only `tensor_values` (f32 unique was entirely BROKEN: UnsupportedDType(F32)). Dedup is
        // exact for an f32 value read as f64 (its f64 bit pattern is the exact representation, so
        // `==` / total_cmp / NaN-handling all match); the unique-VALUE node is narrowed back to the
        // input dtype at each return. frankentorch-kgs4.
        let in_dtype = self.tensor_dtype(input)?;
        let vals = self.tensor_values_lossy_f64(input)?;

        // Collect unique values preserving first-occurrence order.
        //
        // Use IEEE 754 `==` to match torch.unique / numpy.unique:
        //   * 0.0 == -0.0 is true → merged (PyTorch behaviour)
        //   * NaN == NaN is false → every NaN is its own unique entry
        //   * Distinct subnormals (e.g. 5e-324 vs 1e-323) compare !=
        //     and stay distinct
        //
        // The previous heuristic `(u - v).abs() < f64::EPSILON ||
        // (u.is_nan() && v.is_nan())` silently merged any pair of
        // values within machine epsilon — incorrectly fusing
        // subnormals whose absolute distance is well below f64::EPSILON
        // — and merged every NaN bit pattern into one entry, both of
        // which violate the "Equivalent to torch.unique" contract.
        // Deduplicate by exact f64 equality (`u == v`) in O(n) via a hash map,
        // instead of the previous O(n^2) per-element linear scan of unique_vals.
        // The key reproduces `==` semantics exactly:
        //  - NaN never compares equal to anything (not even itself) -> never
        //    deduped, so each NaN element is its own unique;
        //  - +0.0 and -0.0 compare equal -> canonicalize the key to +0.0's bits;
        //  - every other finite value satisfies `u == v` iff identical bits, so
        //    the raw bit pattern is an exact key.
        // First-appearance order and inverse indices are identical to the scan.
        //
        // The map is keyed by the f64 BIT PATTERN (a `u64`), so std's SipHash — designed
        // for HashDoS resistance on adversarial string keys — is pure overhead here and
        // dominates the dedup (e.g. 33.5M elements = 33.5M hashes). Use a splitmix64 integer
        // finalizer instead: the hasher does NOT affect the keys, the insertion order, or the
        // output in ANY way — only its speed — so `unique_vals`, `inverse_indices`, and
        // `counts` are byte-for-byte identical to the std-hasher path. splitmix64 (not a weak
        // single-multiply Fx hash) gives full avalanche, so it does NOT cluster on the highly
        // structured f64 bit patterns of e.g. consecutive integers (which a single-multiply
        // hash buckets into a near-O(n^2) collision chain). Also switch to the `entry` API so a
        // never-before-seen value hashes ONCE (the old get-then-insert hashed twice per miss,
        // the hot path for high-cardinality input).
        #[derive(Default)]
        struct SplitMix64Hasher(u64);
        impl std::hash::Hasher for SplitMix64Hasher {
            #[inline]
            fn finish(&self) -> u64 {
                self.0
            }
            #[inline]
            fn write_u64(&mut self, i: u64) {
                let mut z = self.0 ^ i;
                z = (z ^ (z >> 30)).wrapping_mul(0xbf58_476d_1ce4_e5b9);
                z = (z ^ (z >> 27)).wrapping_mul(0x94d0_49bb_1331_11eb);
                self.0 = z ^ (z >> 31);
            }
            #[inline]
            fn write(&mut self, bytes: &[u8]) {
                for &b in bytes {
                    self.write_u64(u64::from(b));
                }
            }
        }

        if sorted && !return_inverse && !return_counts && vals.len() >= 8192 {
            let sample_len = vals.len().min(16_384);
            let mut sample_seen: std::collections::HashSet<
                u64,
                std::hash::BuildHasherDefault<SplitMix64Hasher>,
            > = std::collections::HashSet::default();
            for (sample_idx, &v) in vals[..sample_len].iter().enumerate() {
                let key = if v.is_nan() {
                    v.to_bits() ^ ((sample_idx as u64).wrapping_mul(0x9e37_79b9_7f4a_7c15))
                } else if v == 0.0 {
                    0.0_f64.to_bits()
                } else {
                    v.to_bits()
                };
                sample_seen.insert(key);
            }

            if sample_seen.len() * 100 >= sample_len * 98 {
                let zero_representative = vals.iter().copied().find(|&v| v == 0.0);
                let mut sorted_vals = vals;
                sorted_vals.sort_by(|a, b| a.total_cmp(b));
                sorted_vals.dedup_by(|a, b| *a == *b);
                if let Some(zero) = zero_representative
                    && let Some(out_zero) = sorted_vals.iter_mut().find(|v| **v == 0.0)
                {
                    *out_zero = zero;
                }
                let unique_len = sorted_vals.len();
                let unique_node = self.tensor_variable(sorted_vals, vec![unique_len], false)?;
                let unique_node = if in_dtype == DType::F64 {
                    unique_node
                } else {
                    self.tensor_to_dtype(unique_node, in_dtype)?
                };
                return Ok((unique_node, None, None));
            }
        }

        // Sorted-dedup fast path for return_inverse / return_counts on a large,
        // NaN-free input. The serial hash-map path below is ~4x SLOWER than torch
        // at 16M; here we sort ONCE (parallel radix) and derive the unique values,
        // inverse, and counts from the sorted runs + permutation — all
        // integer-exact, so the result is byte-for-byte identical to the hash-map
        // path. NaN (each NaN is its own unique, in first-occurrence order) and
        // small inputs fall through to the serial path unchanged.
        if sorted
            && (return_inverse || return_counts)
            && vals.len() >= 8192
            && !vals.iter().any(|v| v.is_nan())
        {
            let n = vals.len();
            let meta1d = TensorMeta::from_shape(vec![n], DType::F64, Device::Cpu);
            let (sorted_vals, perm) = ft_kernel_cpu::sort_tensor_contiguous_f64(
                &vals, &meta1d, 0, false,
            )
            .map_err(|error| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(error)))?;
            // Bucket id per sorted position (a new unique starts on `!=`; +0.0/-0.0
            // are `==` so they merge, matching `dedup_by(==)`). counts = run lengths.
            let mut bucket_id = vec![0usize; n];
            let mut uniq: Vec<f64> = Vec::new();
            let mut counts_vec: Vec<usize> = Vec::new();
            for j in 0..n {
                if j == 0 || sorted_vals[j] != sorted_vals[j - 1] {
                    if j > 0 {
                        bucket_id[j] = bucket_id[j - 1] + 1;
                    }
                    uniq.push(sorted_vals[j]);
                    counts_vec.push(1);
                } else {
                    bucket_id[j] = bucket_id[j - 1];
                    *counts_vec.last_mut().unwrap() += 1;
                }
            }
            // The serial path stores the FIRST-occurrence 0.0 (so its sign is
            // input-order-defined); replicate for the (single) zero bucket.
            if let Some(zero) = vals.iter().copied().find(|&v| v == 0.0)
                && let Some(slot) = uniq.iter_mut().find(|v| **v == 0.0)
            {
                *slot = zero;
            }
            let unique_len = uniq.len();
            let unique_node = self.tensor_variable(uniq, vec![unique_len], false)?;
            let unique_node = if in_dtype == DType::F64 {
                unique_node
            } else {
                self.tensor_to_dtype(unique_node, in_dtype)?
            };
            let inverse_node = if return_inverse {
                let mut inv = vec![0.0f64; n];
                for j in 0..n {
                    inv[perm[j]] = bucket_id[j] as f64;
                }
                Some(self.tensor_variable(inv, vec![n], false)?)
            } else {
                None
            };
            let counts_node = if return_counts {
                let c: Vec<f64> = counts_vec.iter().map(|&c| c as f64).collect();
                Some(self.tensor_variable(c, vec![unique_len], false)?)
            } else {
                None
            };
            return Ok((unique_node, inverse_node, counts_node));
        }

        let mut unique_vals: Vec<f64> = Vec::new();
        let mut inverse_indices: Vec<usize> = Vec::with_capacity(vals.len());

        let mut seen: std::collections::HashMap<
            u64,
            usize,
            std::hash::BuildHasherDefault<SplitMix64Hasher>,
        > = std::collections::HashMap::default();
        for &v in &vals {
            if v.is_nan() {
                inverse_indices.push(unique_vals.len());
                unique_vals.push(v);
                continue;
            }
            let key = if v == 0.0 {
                0.0_f64.to_bits()
            } else {
                v.to_bits()
            };
            let next = unique_vals.len();
            match seen.entry(key) {
                std::collections::hash_map::Entry::Occupied(e) => {
                    inverse_indices.push(*e.get());
                }
                std::collections::hash_map::Entry::Vacant(e) => {
                    e.insert(next);
                    inverse_indices.push(next);
                    unique_vals.push(v);
                }
            }
        }

        if sorted {
            // Sort unique values and remap inverse indices
            let mut order: Vec<usize> = (0..unique_vals.len()).collect();
            order.sort_by(|&a, &b| unique_vals[a].total_cmp(&unique_vals[b]));
            let mut remap = vec![0usize; unique_vals.len()];
            for (new_idx, &old_idx) in order.iter().enumerate() {
                remap[old_idx] = new_idx;
            }
            let sorted_vals: Vec<f64> = order.iter().map(|&i| unique_vals[i]).collect();
            unique_vals = sorted_vals;
            for idx in &mut inverse_indices {
                *idx = remap[*idx];
            }
        }

        let unique_len = unique_vals.len();
        let unique_node = self.tensor_variable(unique_vals, vec![unique_len], false)?;
        let unique_node = if in_dtype == DType::F64 {
            unique_node
        } else {
            self.tensor_to_dtype(unique_node, in_dtype)?
        };

        let inverse_node = if return_inverse {
            let inv_f64: Vec<f64> = inverse_indices.iter().map(|&i| i as f64).collect();
            let n = inv_f64.len();
            Some(self.tensor_variable(inv_f64, vec![n], false)?)
        } else {
            None
        };

        let counts_node = if return_counts {
            let mut counts = vec![0.0f64; unique_len];
            for &idx in &inverse_indices {
                counts[idx] += 1.0;
            }
            Some(self.tensor_variable(counts, vec![unique_len], false)?)
        } else {
            None
        };

        Ok((unique_node, inverse_node, counts_node))
    }

    /// Remove consecutive duplicate elements from a 1D tensor.
    ///
    /// Unlike `unique`, only removes adjacent duplicates (O(n) without sorting).
    pub fn tensor_unique_consecutive(
        &mut self,
        input: TensorNodeId,
        return_inverse: bool,
        return_counts: bool,
    ) -> Result<(TensorNodeId, Option<TensorNodeId>, Option<TensorNodeId>), AutogradError> {
        if self.tensor_requires_grad(input)? {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "unique_consecutive: autograd not supported (consecutive deduplication is non-differentiable). Tracked under frankentorch-gec0.",
                },
            )));
        }
        let vals = self.tensor_values_lossy_f64(input)?;

        let mut unique_vals: Vec<f64> = Vec::new();
        let mut inverse_indices: Vec<usize> = Vec::with_capacity(vals.len());
        let mut counts: Vec<f64> = Vec::new();

        for &v in &vals {
            // torch.unique_consecutive collapses adjacent elements by EXACT `==`
            // (not approximate): NaN != NaN so each NaN stays its own run, and
            // distinct values within machine epsilon (e.g. adjacent f64s) are NOT
            // merged. The previous `(last-v).abs() < f64::EPSILON || both-NaN`
            // heuristic violated both — it merged consecutive NaNs (torch keeps
            // them) and fused epsilon-close distinct values. Mirrors the same fix
            // already applied to `tensor_unique`.
            let is_duplicate = match unique_vals.last() {
                Some(&last) => last == v,
                None => false,
            };
            if !is_duplicate {
                unique_vals.push(v);
                counts.push(1.0);
            } else if let Some(count) = counts.last_mut() {
                *count += 1.0;
            } else {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "unique_consecutive: internal count state missing",
                    },
                )));
            }
            inverse_indices.push(unique_vals.len() - 1);
        }

        let unique_len = unique_vals.len();
        // torch.unique_consecutive preserves the input dtype, but the values were read as f64
        // (lossy) and rebuilt as an F64 leaf — so f32 input silently returned an F64 unique
        // tensor (cf. tensor_unique, which narrows back). unique is pure selection (the f64
        // values ARE the exact f32 inputs), so narrow to f32 for f32 input — bit-identical,
        // correct dtype.
        let unique_node = if self.tensor_dtype(input)? == DType::F32 {
            let uf32: Vec<f32> = unique_vals.iter().map(|&v| v as f32).collect();
            self.tensor_variable_f32(uf32, vec![unique_len], false)?
        } else {
            self.tensor_variable(unique_vals, vec![unique_len], false)?
        };

        let inverse_node = if return_inverse {
            let inv_f64: Vec<f64> = inverse_indices.iter().map(|&i| i as f64).collect();
            let n = inv_f64.len();
            Some(self.tensor_variable(inv_f64, vec![n], false)?)
        } else {
            None
        };

        let counts_node = if return_counts {
            Some(self.tensor_variable(counts, vec![unique_len], false)?)
        } else {
            None
        };

        Ok((unique_node, inverse_node, counts_node))
    }

    /// Return unique slices of the input tensor along a given dimension.
    ///
    /// Equivalent to `torch.unique(input, dim=dim)` or `torch.unique_dim`.
    /// Returns unique slices along the specified dimension, optionally with
    /// inverse indices and counts.
    pub fn tensor_unique_dim(
        &mut self,
        input: TensorNodeId,
        dim: usize,
        sorted: bool,
        return_inverse: bool,
        return_counts: bool,
    ) -> Result<(TensorNodeId, Option<TensorNodeId>, Option<TensorNodeId>), AutogradError> {
        if self.tensor_requires_grad(input)? {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "unique_dim: autograd not supported (uniqueness is non-differentiable)",
                },
            )));
        }
        let shape = self.tensor_shape(input)?;
        if dim >= shape.len() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "unique_dim: dimension out of range",
                },
            )));
        }
        // Lossy f64 read so f32 / f16 / bf16 inputs are accepted instead of erroring in the old
        // F64-only `tensor_values` (f32 unique_dim was BROKEN: UnsupportedDType(F32)); the
        // unique-slices output is narrowed back to the input dtype. Dedup keys on exact f64 bits, so
        // an f32 value read as f64 dedups exactly. frankentorch-kgs4.
        let in_dtype = self.tensor_dtype(input)?;
        let vals = self.tensor_values_lossy_f64(input)?;
        let dim_size = shape[dim];
        // Calculate the size of each slice along dim
        let outer_size: usize = shape[..dim].iter().product();
        let inner_size: usize = shape[dim + 1..].iter().product();
        let slice_numel = inner_size;
        let total_slices = outer_size * dim_size;
        // Extract slices and find unique ones
        let mut slices: Vec<(usize, Vec<f64>)> = Vec::with_capacity(total_slices);
        for outer in 0..outer_size {
            for d in 0..dim_size {
                let mut slice_data = Vec::with_capacity(slice_numel);
                for inner in 0..inner_size {
                    let idx = outer * dim_size * inner_size + d * inner_size + inner;
                    slice_data.push(vals[idx]);
                }
                slices.push((outer * dim_size + d, slice_data));
            }
        }
        // Group by outer and find unique within each
        // For simplicity, treat entire slice as key and deduplicate globally.
        //
        // Keys are `Vec<i64>` of slice bit patterns, so std's SipHash hashes every byte of
        // every slice through the HashDoS-hardened (slow) mixer — pure overhead for these
        // integer keys, and the dominant dedup cost when there are many/long slices. Use a
        // splitmix64 finalizer: the hasher affects ONLY bucketing (the HashMap still compares
        // the full `Vec<i64>` keys for equality on a hash hit), so `unique_indices`, `inverse`,
        // and `counts` are byte-for-byte identical to the std-hasher path. Same proven swap as
        // the 1-D `tensor_unique` dedup (splitmix64, full avalanche, no clustering).
        #[derive(Default)]
        struct SplitMix64Hasher(u64);
        impl std::hash::Hasher for SplitMix64Hasher {
            #[inline]
            fn finish(&self) -> u64 {
                self.0
            }
            #[inline]
            fn write_u64(&mut self, i: u64) {
                let mut z = self.0 ^ i;
                z = (z ^ (z >> 30)).wrapping_mul(0xbf58_476d_1ce4_e5b9);
                z = (z ^ (z >> 27)).wrapping_mul(0x94d0_49bb_1331_11eb);
                self.0 = z ^ (z >> 31);
            }
            #[inline]
            fn write_i64(&mut self, i: i64) {
                self.write_u64(i as u64);
            }
            #[inline]
            fn write(&mut self, bytes: &[u8]) {
                // Process 8 bytes per splitmix step so hashing a `[i64]` slice key (which std
                // routes through `write`) stays O(len) with a cheap per-word mixer rather than a
                // per-byte one.
                let mut chunks = bytes.chunks_exact(8);
                for c in &mut chunks {
                    let mut buf = [0u8; 8];
                    buf.copy_from_slice(c);
                    self.write_u64(u64::from_le_bytes(buf));
                }
                let rem = chunks.remainder();
                if !rem.is_empty() {
                    let mut buf = [0u8; 8];
                    buf[..rem.len()].copy_from_slice(rem);
                    self.write_u64(u64::from_le_bytes(buf));
                }
            }
        }
        let mut unique_indices: Vec<usize> = Vec::new();
        let mut seen: std::collections::HashMap<
            Vec<i64>,
            usize,
            std::hash::BuildHasherDefault<SplitMix64Hasher>,
        > = std::collections::HashMap::default();
        let mut inverse: Vec<f64> = Vec::with_capacity(slices.len());
        let mut counts_map: std::collections::HashMap<usize, usize> =
            std::collections::HashMap::new();
        for (idx, slice) in slices.iter() {
            // Convert to bits for comparison (handles NaN)
            let key: Vec<i64> = slice.iter().map(|&v| v.to_bits() as i64).collect();
            if let Some(&unique_idx) = seen.get(&key) {
                inverse.push(unique_idx as f64);
                *counts_map.entry(unique_idx).or_insert(0) += 1;
            } else {
                let new_idx = unique_indices.len();
                seen.insert(key, new_idx);
                unique_indices.push(*idx);
                inverse.push(new_idx as f64);
                counts_map.insert(new_idx, 1);
            }
        }
        if sorted {
            // Sort unique slices lexicographically
            unique_indices.sort_by(|&a, &b| {
                let slice_a = &slices[a].1;
                let slice_b = &slices[b].1;
                for (va, vb) in slice_a.iter().zip(slice_b.iter()) {
                    match va.partial_cmp(vb) {
                        Some(std::cmp::Ordering::Equal) => continue,
                        Some(ord) => return ord,
                        None => {
                            // Handle NaN
                            if va.is_nan() && vb.is_nan() {
                                continue;
                            } else if va.is_nan() {
                                return std::cmp::Ordering::Greater;
                            } else {
                                return std::cmp::Ordering::Less;
                            }
                        }
                    }
                }
                std::cmp::Ordering::Equal
            });
        }
        // Build output tensor
        let unique_count = unique_indices.len();
        let mut new_shape = shape.clone();
        new_shape[dim] = unique_count;
        let mut out_vals = Vec::with_capacity(outer_size * unique_count * inner_size);
        for outer in 0..outer_size {
            for &unique_index in unique_indices.iter().take(unique_count) {
                let orig_d = unique_index % dim_size;
                for inner in 0..inner_size {
                    let idx = outer * dim_size * inner_size + orig_d * inner_size + inner;
                    out_vals.push(vals[idx]);
                }
            }
        }
        let unique_node = self.tensor_variable(out_vals, new_shape, false)?;
        let unique_node = if in_dtype == DType::F64 {
            unique_node
        } else {
            self.tensor_to_dtype(unique_node, in_dtype)?
        };
        let inverse_node = if return_inverse {
            let n = inverse.len();
            Some(self.tensor_variable(inverse, vec![n], false)?)
        } else {
            None
        };
        let counts_node = if return_counts {
            let counts: Vec<f64> = (0..unique_count)
                .map(|i| *counts_map.get(&i).unwrap_or(&0) as f64)
                .collect();
            Some(self.tensor_variable(counts, vec![unique_count], false)?)
        } else {
            None
        };
        Ok((unique_node, inverse_node, counts_node))
    }

    /// Count the number of occurrences of each value in a 1-D non-negative integer tensor.
    ///
    /// Equivalent to `torch.bincount(input, weights=None, minlength=0)`.
    /// Input values are truncated to integers. Negative values cause an error.
    /// If `weights` is provided, it must have the same length and the output
    /// accumulates weights instead of unit counts.
    pub fn tensor_bincount(
        &mut self,
        input: TensorNodeId,
        weights: Option<TensorNodeId>,
        minlength: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        // F32 unweighted no-grad fast path: the generic path below `tensor_values_lossy_f64`
        // UPCASTS f32->f64 + runs a SERIAL validate/max pass AND a SERIAL counting loop
        // (~8.3x SLOWER than torch at 8M). Borrow f32, validate+max in parallel, count with
        // per-thread local arrays + merge — integer counts are order-invariant + `v as usize`
        // == `(v as f64) as usize` for integer v, so BIT-IDENTICAL. Weighted (scatter_add for
        // grad) / non-contiguous / huge-out_len fall through. frankentorch-kgs4.177.
        if weights.is_none()
            && !self.tensor_requires_grad(input)?
            && self.tensor_dtype(input)? == DType::F32
            && self.tensor_shape(input)?.len() == 1
        {
            use rayon::prelude::*;
            let mut invalid: Option<&'static str> = None;
            let counts_opt: Option<Vec<f64>> = {
                let it = self.tensor_tape.tensor(input)?;
                if !it.meta().is_contiguous() {
                    None
                } else {
                    let vals = it.contiguous_values_f32()?;
                    if vals.is_empty() {
                        Some(vec![0.0f64; minlength])
                    } else if vals.par_iter().any(|&v| !v.is_finite() || v != v.floor()) {
                        invalid = Some("bincount: input must contain finite integer values");
                        None
                    } else if vals.par_iter().any(|&v| v < 0.0) {
                        invalid = Some("bincount: input must be non-negative");
                        None
                    } else {
                        let max_v = vals.par_iter().copied().reduce(|| 0.0f32, f32::max);
                        #[allow(clippy::cast_possible_truncation, clippy::cast_sign_loss)]
                        let m = max_v as usize;
                        match m.checked_add(1).map(|b| b.max(minlength)) {
                            // Cap per-thread local-array memory (out_len * f64 * fold-jobs).
                            Some(out_len) if out_len <= (1usize << 16) => Some(
                                vals.par_iter()
                                    .fold(
                                        || vec![0.0f64; out_len],
                                        |mut acc, &v| {
                                            #[allow(
                                                clippy::cast_possible_truncation,
                                                clippy::cast_sign_loss
                                            )]
                                            let i = v as usize;
                                            acc[i] += 1.0;
                                            acc
                                        },
                                    )
                                    .reduce(
                                        || vec![0.0f64; out_len],
                                        |mut a, b| {
                                            for (ai, bi) in a.iter_mut().zip(b.iter()) {
                                                *ai += bi;
                                            }
                                            a
                                        },
                                    ),
                            ),
                            _ => None, // huge out_len / overflow -> generic path
                        }
                    }
                }
            };
            if let Some(reason) = invalid {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet { reason },
                )));
            }
            if let Some(counts) = counts_opt {
                let n = counts.len();
                return self.tensor_variable(counts, vec![n], false);
            }
        }

        // F64 sibling of the f32 fast path above. F64 is the COMMON case (FT stores integer
        // index tensors as f64), and it was falling through to the generic SERIAL path below
        // (tensor_values_lossy_f64 clone + serial validate/max + serial counting loop = ~6.5x
        // SLOWER than torch at 16M). Borrow f64, validate+max in parallel, count with
        // per-thread local arrays + merge. BIT-IDENTICAL (integer counts are order-invariant;
        // `v as usize` for integer v). Weighted / non-contiguous / huge-out_len fall through.
        if weights.is_none()
            && !self.tensor_requires_grad(input)?
            && self.tensor_dtype(input)? == DType::F64
            && self.tensor_shape(input)?.len() == 1
        {
            use rayon::prelude::*;
            let mut invalid: Option<&'static str> = None;
            let counts_opt: Option<Vec<f64>> = {
                let it = self.tensor_tape.tensor(input)?;
                if !it.meta().is_contiguous() {
                    None
                } else {
                    let vals = it.contiguous_values()?;
                    if vals.is_empty() {
                        Some(vec![0.0f64; minlength])
                    } else if vals.par_iter().any(|&v| !v.is_finite() || v != v.floor()) {
                        invalid = Some("bincount: input must contain finite integer values");
                        None
                    } else if vals.par_iter().any(|&v| v < 0.0) {
                        invalid = Some("bincount: input must be non-negative");
                        None
                    } else {
                        let max_v = vals.par_iter().copied().reduce(|| 0.0f64, f64::max);
                        #[allow(clippy::cast_possible_truncation, clippy::cast_sign_loss)]
                        let m = max_v as usize;
                        match m.checked_add(1).map(|b| b.max(minlength)) {
                            // Bound the accumulator count with par_chunks (~4x threads chunks)
                            // rather than par_iter().fold (one acc per work-steal split -> the
                            // merge cost grows with core count, making 64t SLOWER than 8t).
                            Some(out_len) if out_len <= (1usize << 16) => {
                                let nthreads = rayon::current_num_threads().max(1);
                                let grain = (vals.len() / (nthreads * 4)).max(4096);
                                Some(
                                    vals.par_chunks(grain)
                                        .map(|ch| {
                                            let mut h = vec![0.0f64; out_len];
                                            for &v in ch {
                                                #[allow(
                                                    clippy::cast_possible_truncation,
                                                    clippy::cast_sign_loss
                                                )]
                                                {
                                                    h[v as usize] += 1.0;
                                                }
                                            }
                                            h
                                        })
                                        .reduce(
                                            || vec![0.0f64; out_len],
                                            |mut a, b| {
                                                for (ai, bi) in a.iter_mut().zip(b.iter()) {
                                                    *ai += bi;
                                                }
                                                a
                                            },
                                        ),
                                )
                            }
                            _ => None,
                        }
                    }
                }
            };
            if let Some(reason) = invalid {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet { reason },
                )));
            }
            if let Some(counts) = counts_opt {
                let n = counts.len();
                return self.tensor_variable(counts, vec![n], false);
            }
        }

        let vals = self.tensor_values_lossy_f64(input)?;
        let input_shape = self.tensor_shape(input)?;
        if input_shape.len() != 1 {
            // Surface the actual rank so callers see 'expected 1-D
            // but got N-D' instead of an opaque static reason
            // (frankentorch-8sct).
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::InvalidDimension {
                    dim: 0,
                    ndim: input_shape.len(),
                },
            )));
        }

        if let Some(w) = weights {
            let w_shape = self.tensor_shape(w)?;
            if w_shape.len() != 1 || w_shape[0] != input_shape[0] {
                // ShapeMismatch carries both shapes so the caller can
                // distinguish 'wrong rank' from 'wrong length' without
                // reparsing a static string (frankentorch-8sct).
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                    ft_kernel_cpu::KernelError::ShapeMismatch {
                        lhs: input_shape.clone(),
                        rhs: w_shape,
                    },
                )));
            }
        }

        // Find max value to determine output size
        let mut max_val: Option<i64> = None;
        for &v in &vals {
            if !v.is_finite() || v != v.floor() {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "bincount: input must contain finite integer values",
                    },
                )));
            }
            let iv = v as i64;
            if iv < 0 {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "bincount: input must be non-negative",
                    },
                )));
            }
            let iv_u = iv as u128;
            if iv_u > usize::MAX as u128 {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "bincount: input value too large",
                    },
                )));
            }
            max_val = Some(max_val.map_or(iv, |cur| cur.max(iv)));
        }

        let out_len = match max_val {
            Some(m) => {
                let m_usize = usize::try_from(m).map_err(|_| {
                    AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "bincount: input value too large",
                        },
                    ))
                })?;
                let base = m_usize.checked_add(1).ok_or({
                    AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "bincount: output size overflow",
                        },
                    ))
                })?;
                base.max(minlength)
            }
            None => minlength, // empty input
        };
        let _ = Self::checked_mul(
            out_len,
            std::mem::size_of::<f64>(),
            "bincount output size overflow",
        )?;

        // Compose via tensor_scatter_add so gradients flow back to the
        // weights tensor when present. Tracked under frankentorch-9r3c.
        // Previous body extracted both input and weight values + rebuilt
        // a non-grad leaf, severing autograd through every weighted
        // bincount call (focal-loss-style class re-weighting, etc.).
        // The input (bin indices) is integer-valued and intrinsically
        // non-differentiable; only weights flow gradients.
        if vals.is_empty() {
            return self.tensor_variable(vec![0.0; out_len], vec![out_len], false);
        }
        if let Some(weights) = weights {
            // Weighted: compose via tensor_scatter_add so gradients flow back to
            // the weights tensor (frankentorch-9r3c). The index must be an f64
            // tensor — the raw `input` may be f32, which scatter_add rejects, so
            // build an f64 index leaf from the validated integer bin values
            // (the index is non-differentiable). frankentorch-dh5f.
            let zeros = self.full(vec![out_len], 0.0, false)?;
            let index = self.tensor_variable(vals.clone(), input_shape.clone(), false)?;
            self.tensor_scatter_add(zeros, 0, index, weights)
        } else {
            // Unweighted: counts are non-differentiable, so build them directly
            // from the (f64-converted) values. This is f32-safe (no scatter on
            // the possibly-f32 input) and avoids the scatter op entirely. Values
            // are already validated finite, non-negative, integer, < out_len.
            let mut counts = vec![0.0f64; out_len];
            for &v in &vals {
                counts[v as usize] += 1.0;
            }
            self.tensor_variable(counts, vec![out_len], false)
        }
    }

    /// Compute the histogram of a tensor.
    ///
    /// Equivalent to `torch.histc(input, bins=100, min=0, max=0)`.
    /// Divides the range `[min, max]` into `bins` equal-width bins and counts
    /// elements falling into each bin. If `min == max`, the range is set to
    /// `[input.min(), input.max()]`.
    ///
    /// Values outside `[min, max]` are *ignored* (not counted in any bin),
    /// matching PyTorch's `torch.histc` and NumPy's `numpy.histogram`. The
    /// upper boundary is inclusive: values exactly equal to `max` land in
    /// the last bin (`bins - 1`).
    pub fn tensor_histc(
        &mut self,
        input: TensorNodeId,
        bins: usize,
        min_val: f64,
        max_val: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        if self.tensor_requires_grad(input)? {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "histc: autograd not supported (integer counts are non-differentiable). Tracked under frankentorch-gec0.",
                },
            )));
        }
        if bins == 0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "histc: bins must be > 0",
                },
            )));
        }
        if !min_val.is_finite() || !max_val.is_finite() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "histc: min and max must be finite",
                },
            )));
        }
        if min_val > max_val {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "histc: min must be <= max",
                },
            )));
        }

        // F32 fast path: the generic path below `tensor_values_lossy_f64` UPCASTS f32->f64
        // (128MB clone at 16M) + runs a SERIAL finite-check, measured ~3.4x SLOWER than
        // torch. Borrow the f32 slice instead, parallel finite-check + parallel histogram
        // (already the kgs4.100 local-bins+merge pattern). BIT-IDENTICAL: each bin uses
        // `v as f64` (f32->f64 exact) in the same f64 bin math, and integer counts are
        // order-invariant. f32 grad already errors; non-contiguous falls through.
        // frankentorch-kgs4.176.
        if self.tensor_dtype(input)? == DType::F32 {
            use rayon::prelude::*;
            let mut non_finite = false;
            let counts_opt: Option<Vec<f64>> = {
                let it = self.tensor_tape.tensor(input)?;
                if it.meta().is_contiguous() {
                    let vals = it.contiguous_values_f32()?;
                    if vals.par_iter().any(|v| !v.is_finite()) {
                        non_finite = true;
                        None
                    } else {
                        let (lo, hi) = if (min_val - max_val).abs() < f64::EPSILON {
                            let data_min =
                                vals.par_iter().copied().reduce(|| f32::INFINITY, f32::min) as f64;
                            let data_max = vals
                                .par_iter()
                                .copied()
                                .reduce(|| f32::NEG_INFINITY, f32::max)
                                as f64;
                            if data_min == data_max {
                                (data_min - 0.5, data_max + 0.5)
                            } else {
                                (data_min, data_max)
                            }
                        } else {
                            (min_val, max_val)
                        };
                        let bin_width = (hi - lo) / bins as f64;
                        #[allow(clippy::cast_sign_loss, clippy::cast_possible_truncation)]
                        let bin_of = |v: f64| ((v - lo) / bin_width) as usize;
                        let counts = vals
                            .par_iter()
                            .fold(
                                || vec![0.0f64; bins],
                                |mut acc, &v| {
                                    let vd = v as f64;
                                    if vd >= lo && vd <= hi {
                                        acc[bin_of(vd).min(bins - 1)] += 1.0;
                                    }
                                    acc
                                },
                            )
                            .reduce(
                                || vec![0.0f64; bins],
                                |mut a, b| {
                                    for (ai, bi) in a.iter_mut().zip(b.iter()) {
                                        *ai += bi;
                                    }
                                    a
                                },
                            );
                        Some(counts)
                    }
                } else {
                    None
                }
            };
            if non_finite {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "histc: input values must be finite",
                    },
                )));
            }
            if let Some(counts) = counts_opt {
                return self.tensor_variable(counts, vec![bins], false);
            }
        }

        // F64 fast path (asymmetric-dtype mirror of the F32 path above): the generic path below
        // CLONES the f64 input via `tensor_values_lossy_f64` (a full to_vec — measured ~2x the
        // whole op at 16-64M) then runs a SERIAL finite-check / auto-range / bin. BORROW the f64
        // slice instead + the same parallel local-bins+merge histogram. BIT-IDENTICAL: same f64
        // values, same bin math, integer counts are order-invariant (exact 1.0 sums). Grad already
        // errors; non-contiguous falls through to the generic path. frankentorch (BlackThrush).
        if self.tensor_dtype(input)? == DType::F64 {
            use rayon::prelude::*;
            let mut non_finite = false;
            let counts_opt: Option<Vec<f64>> = {
                let it = self.tensor_tape.tensor(input)?;
                if it.meta().is_contiguous() {
                    let vals = it.contiguous_values()?;
                    if vals.par_iter().any(|v| !v.is_finite()) {
                        non_finite = true;
                        None
                    } else {
                        let (lo, hi) = if (min_val - max_val).abs() < f64::EPSILON {
                            let data_min =
                                vals.par_iter().copied().reduce(|| f64::INFINITY, f64::min);
                            let data_max = vals
                                .par_iter()
                                .copied()
                                .reduce(|| f64::NEG_INFINITY, f64::max);
                            if data_min == data_max {
                                (data_min - 0.5, data_max + 0.5)
                            } else {
                                (data_min, data_max)
                            }
                        } else {
                            (min_val, max_val)
                        };
                        let bin_width = (hi - lo) / bins as f64;
                        #[allow(clippy::cast_sign_loss, clippy::cast_possible_truncation)]
                        let bin_of = |v: f64| ((v - lo) / bin_width) as usize;
                        let counts = vals
                            .par_iter()
                            .fold(
                                || vec![0.0f64; bins],
                                |mut acc, &v| {
                                    if v >= lo && v <= hi {
                                        acc[bin_of(v).min(bins - 1)] += 1.0;
                                    }
                                    acc
                                },
                            )
                            .reduce(
                                || vec![0.0f64; bins],
                                |mut a, b| {
                                    for (ai, bi) in a.iter_mut().zip(b.iter()) {
                                        *ai += bi;
                                    }
                                    a
                                },
                            );
                        Some(counts)
                    }
                } else {
                    None
                }
            };
            if non_finite {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "histc: input values must be finite",
                    },
                )));
            }
            if let Some(counts) = counts_opt {
                return self.tensor_variable(counts, vec![bins], false);
            }
        }

        let vals = self.tensor_values_lossy_f64(input)?;
        for &v in &vals {
            if !v.is_finite() {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "histc: input values must be finite",
                    },
                )));
            }
        }

        let (lo, hi) = if (min_val - max_val).abs() < f64::EPSILON {
            // Auto-range from data
            let mut data_min = f64::INFINITY;
            let mut data_max = f64::NEG_INFINITY;
            for &v in &vals {
                if v < data_min {
                    data_min = v;
                }
                if v > data_max {
                    data_max = v;
                }
            }
            if data_min == data_max {
                (data_min - 0.5, data_max + 0.5)
            } else {
                (data_min, data_max)
            }
        } else {
            (min_val, max_val)
        };

        let mut counts = vec![0.0f64; bins];
        let bin_width = (hi - lo) / bins as f64;

        // Match PyTorch / numpy semantics: values outside [lo, hi] are
        // ignored (not counted in any bin). The upper boundary is
        // inclusive — values exactly equal to `hi` land in the last
        // bin (the floor((v-lo)/bin_width) computation maps `v == hi`
        // to bin `bins`, which we cap to `bins - 1`).
        //
        // Previously this clamped out-of-range values to the first /
        // last bin, which violated the "Equivalent to torch.histc"
        // contract: torch.histc(x=[-10, 0.5, 1.5, 100], bins=2,
        // min=0, max=2) returns [1, 1] (just the in-range elements),
        // not [2, 2].
        // Each in-range value adds EXACTLY 1.0 to its bin, so the counts are exact
        // integers in f64 and the result is invariant to summation order. That lets
        // us parallelize with per-thread local bin arrays merged at the end (the
        // classic parallel histogram) — bit-identical to the serial scatter, since
        // integer sums don't depend on order. The per-value bin math (div + floor +
        // cap) is the compute-bound cost. frankentorch-kgs4.100.
        #[allow(clippy::cast_sign_loss, clippy::cast_possible_truncation)]
        let bin_of = |v: f64| ((v - lo) / bin_width) as usize;
        if vals.len() >= PARALLEL_ELEMENTWISE_MIN {
            use rayon::prelude::*;
            counts = vals
                .par_iter()
                .fold(
                    || vec![0.0f64; bins],
                    |mut acc, &v| {
                        if v >= lo && v <= hi {
                            acc[bin_of(v).min(bins - 1)] += 1.0;
                        }
                        acc
                    },
                )
                .reduce(
                    || vec![0.0f64; bins],
                    |mut a, b| {
                        for (ai, bi) in a.iter_mut().zip(b.iter()) {
                            *ai += bi;
                        }
                        a
                    },
                );
        } else {
            for &v in &vals {
                if v < lo || v > hi {
                    continue;
                }
                counts[bin_of(v).min(bins - 1)] += 1.0;
            }
        }

        self.tensor_variable(counts, vec![bins], false)
    }

    /// Compute a histogram and return `(hist, bin_edges)`.
    ///
    /// Equivalent to `torch.histogram(input, bins, range=(min, max),
    /// weight=weight, density=density)` for integer `bins`. The input is
    /// flattened, values outside the range are ignored, and the rightmost
    /// edge is inclusive for the final bin.
    pub fn tensor_histogram(
        &mut self,
        input: TensorNodeId,
        bins: usize,
        min_val: f64,
        max_val: f64,
        weight: Option<TensorNodeId>,
        density: bool,
    ) -> Result<(TensorNodeId, TensorNodeId), AutogradError> {
        if self.tensor_requires_grad(input)? {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "histogram: autograd not supported (integer counts are non-differentiable). Tracked under frankentorch-jk0k.",
                },
            )));
        }
        if let Some(weight_id) = weight
            && self.tensor_requires_grad(weight_id)?
        {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "histogram: autograd not supported for weight. Tracked under frankentorch-jk0k.",
                },
            )));
        }
        if bins == 0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "histogram: bins must be > 0",
                },
            )));
        }
        if !min_val.is_finite() || !max_val.is_finite() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "histogram: min and max must be finite",
                },
            )));
        }
        if min_val > max_val {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "histogram: min must be <= max",
                },
            )));
        }

        // F32 UNWEIGHTED no-grad fast path: the generic path below `tensor_values_lossy_f64`
        // UPCASTS f32->f64 + a SERIAL finite-check + a SERIAL binning loop (~5.4x SLOWER than
        // torch). Borrow f32, parallel finite-check + auto-range + parallel local-bins
        // histogram (contribution = 1.0; integer counts are order-invariant). Each bin uses
        // `v as f64` (exact) in the SAME f64 bin math -> BIT-IDENTICAL. Weighted (float-weight
        // sums are order-sensitive) / non-contiguous fall through. frankentorch-kgs4.178.
        if weight.is_none() && self.tensor_dtype(input)? == DType::F32 {
            use rayon::prelude::*;
            let mut non_finite = false;
            let mut empty_autorange = false;
            let built: Option<(Vec<f64>, f64, f64)> = {
                let it = self.tensor_tape.tensor(input)?;
                if !it.meta().is_contiguous() {
                    None
                } else {
                    let vals = it.contiguous_values_f32()?;
                    if vals.par_iter().any(|v| !v.is_finite()) {
                        non_finite = true;
                        None
                    } else {
                        let range = if (min_val - max_val).abs() < f64::EPSILON {
                            if vals.is_empty() {
                                empty_autorange = true;
                                None
                            } else {
                                let dmin =
                                    vals.par_iter().copied().reduce(|| f32::INFINITY, f32::min)
                                        as f64;
                                let dmax = vals
                                    .par_iter()
                                    .copied()
                                    .reduce(|| f32::NEG_INFINITY, f32::max)
                                    as f64;
                                Some(if dmin == dmax {
                                    (dmin - 0.5, dmax + 0.5)
                                } else {
                                    (dmin, dmax)
                                })
                            }
                        } else {
                            Some((min_val, max_val))
                        };
                        range.map(|(lo, hi)| {
                            let bin_width = (hi - lo) / bins as f64;
                            #[allow(clippy::cast_sign_loss, clippy::cast_possible_truncation)]
                            let bin_of = |v: f64| ((v - lo) / bin_width) as usize;
                            let counts = vals
                                .par_iter()
                                .fold(
                                    || vec![0.0f64; bins],
                                    |mut acc, &v| {
                                        let vd = v as f64;
                                        if vd >= lo && vd <= hi {
                                            acc[bin_of(vd).min(bins - 1)] += 1.0;
                                        }
                                        acc
                                    },
                                )
                                .reduce(
                                    || vec![0.0f64; bins],
                                    |mut a, b| {
                                        for (ai, bi) in a.iter_mut().zip(b.iter()) {
                                            *ai += bi;
                                        }
                                        a
                                    },
                                );
                            (counts, lo, hi)
                        })
                    }
                }
            };
            if non_finite {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "histogram: input values must be finite",
                    },
                )));
            }
            if empty_autorange {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "histogram: auto range requires non-empty input",
                    },
                )));
            }
            if let Some((mut counts, lo, hi)) = built {
                let bin_width = (hi - lo) / bins as f64;
                if density {
                    let total: f64 = counts.iter().sum();
                    let scale = total * bin_width;
                    for count in &mut counts {
                        *count /= scale;
                    }
                }
                let edge_count = Self::checked_add(bins, 1, "histogram: edge count overflow")?;
                let mut edges = Vec::with_capacity(edge_count);
                for i in 0..edge_count {
                    edges.push(lo + bin_width * i as f64);
                }
                let hist = self.tensor_variable(counts, vec![bins], false)?;
                let bin_edges = self.tensor_variable(edges, vec![edge_count], false)?;
                return Ok((hist, bin_edges));
            }
        }

        // F64 UNWEIGHTED fast path (asymmetric-dtype mirror of the F32 path above): the generic
        // path below CLONES the f64 input via `tensor_values_lossy_f64` (128MB to_vec at 16M) +
        // SERIAL finite-check/auto-range/bin. Borrow `contiguous_values()` (&[f64], no clone) +
        // parallel finite-check + auto-range + parallel local-bins histogram. BIT-IDENTICAL (same
        // f64 values, same bin math, integer counts order-invariant). Weighted (float-weight sums
        // order-sensitive) / non-contiguous fall through. frankentorch (BlackThrush).
        if weight.is_none() && self.tensor_dtype(input)? == DType::F64 {
            use rayon::prelude::*;
            let mut non_finite = false;
            let mut empty_autorange = false;
            let built: Option<(Vec<f64>, f64, f64)> = {
                let it = self.tensor_tape.tensor(input)?;
                if !it.meta().is_contiguous() {
                    None
                } else {
                    let vals = it.contiguous_values()?;
                    if vals.par_iter().any(|v| !v.is_finite()) {
                        non_finite = true;
                        None
                    } else {
                        let range = if (min_val - max_val).abs() < f64::EPSILON {
                            if vals.is_empty() {
                                empty_autorange = true;
                                None
                            } else {
                                let dmin =
                                    vals.par_iter().copied().reduce(|| f64::INFINITY, f64::min);
                                let dmax = vals
                                    .par_iter()
                                    .copied()
                                    .reduce(|| f64::NEG_INFINITY, f64::max);
                                Some(if dmin == dmax {
                                    (dmin - 0.5, dmax + 0.5)
                                } else {
                                    (dmin, dmax)
                                })
                            }
                        } else {
                            Some((min_val, max_val))
                        };
                        range.map(|(lo, hi)| {
                            let bin_width = (hi - lo) / bins as f64;
                            #[allow(clippy::cast_sign_loss, clippy::cast_possible_truncation)]
                            let bin_of = |v: f64| ((v - lo) / bin_width) as usize;
                            let counts = vals
                                .par_iter()
                                .fold(
                                    || vec![0.0f64; bins],
                                    |mut acc, &v| {
                                        if v >= lo && v <= hi {
                                            acc[bin_of(v).min(bins - 1)] += 1.0;
                                        }
                                        acc
                                    },
                                )
                                .reduce(
                                    || vec![0.0f64; bins],
                                    |mut a, b| {
                                        for (ai, bi) in a.iter_mut().zip(b.iter()) {
                                            *ai += bi;
                                        }
                                        a
                                    },
                                );
                            (counts, lo, hi)
                        })
                    }
                }
            };
            if non_finite {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "histogram: input values must be finite",
                    },
                )));
            }
            if empty_autorange {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "histogram: auto range requires non-empty input",
                    },
                )));
            }
            if let Some((mut counts, lo, hi)) = built {
                let bin_width = (hi - lo) / bins as f64;
                if density {
                    let total: f64 = counts.iter().sum();
                    let scale = total * bin_width;
                    for count in &mut counts {
                        *count /= scale;
                    }
                }
                let edge_count = Self::checked_add(bins, 1, "histogram: edge count overflow")?;
                let mut edges = Vec::with_capacity(edge_count);
                for i in 0..edge_count {
                    edges.push(lo + bin_width * i as f64);
                }
                let hist = self.tensor_variable(counts, vec![bins], false)?;
                let bin_edges = self.tensor_variable(edges, vec![edge_count], false)?;
                return Ok((hist, bin_edges));
            }
        }

        let vals = self.tensor_values_lossy_f64(input)?;
        for &v in &vals {
            if !v.is_finite() {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "histogram: input values must be finite",
                    },
                )));
            }
        }

        let weight_vals = if let Some(weight_id) = weight {
            let weights = self.tensor_values_lossy_f64(weight_id)?;
            if weights.len() != vals.len() {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "histogram: weight must have the same number of elements as input",
                    },
                )));
            }
            for &w in &weights {
                if !w.is_finite() {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "histogram: weight values must be finite",
                        },
                    )));
                }
            }
            Some(weights)
        } else {
            None
        };

        let (lo, hi) = if (min_val - max_val).abs() < f64::EPSILON {
            if vals.is_empty() {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "histogram: auto range requires non-empty input",
                    },
                )));
            }
            let mut data_min = f64::INFINITY;
            let mut data_max = f64::NEG_INFINITY;
            for &v in &vals {
                if v < data_min {
                    data_min = v;
                }
                if v > data_max {
                    data_max = v;
                }
            }
            if data_min == data_max {
                (data_min - 0.5, data_max + 0.5)
            } else {
                (data_min, data_max)
            }
        } else {
            (min_val, max_val)
        };

        let bin_width = (hi - lo) / bins as f64;
        let mut counts = vec![0.0f64; bins];

        for (idx, &v) in vals.iter().enumerate() {
            if v < lo || v > hi {
                continue;
            }
            #[allow(clippy::cast_sign_loss, clippy::cast_possible_truncation)]
            let raw_bin = ((v - lo) / bin_width) as usize;
            let bin = raw_bin.min(bins - 1);
            let contribution = weight_vals.as_ref().map_or(1.0, |weights| weights[idx]);
            counts[bin] += contribution;
        }

        if density {
            let total: f64 = counts.iter().sum();
            let scale = total * bin_width;
            for count in &mut counts {
                *count /= scale;
            }
        }

        let edge_count = Self::checked_add(bins, 1, "histogram: edge count overflow")?;
        let mut edges = Vec::with_capacity(edge_count);
        for i in 0..edge_count {
            edges.push(lo + bin_width * i as f64);
        }

        let hist = self.tensor_variable(counts, vec![bins], false)?;
        let bin_edges = self.tensor_variable(edges, vec![edge_count], false)?;
        Ok((hist, bin_edges))
    }

    /// Compute a multi-dimensional histogram.
    ///
    /// Equivalent to `torch.histogramdd`. Input is a 2D tensor where each row is a sample
    /// and each column is a dimension. Returns histogram counts and list of bin edges per dimension.
    ///
    /// `bins` specifies the number of bins per dimension.
    /// `ranges` specifies (min, max) per dimension (or None for auto-range).
    pub fn tensor_histogramdd(
        &mut self,
        input: TensorNodeId,
        bins: &[usize],
        ranges: Option<&[(f64, f64)]>,
        density: bool,
    ) -> Result<(TensorNodeId, Vec<TensorNodeId>), AutogradError> {
        if self.tensor_requires_grad(input)? {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "histogramdd: autograd not supported (integer counts are non-differentiable)",
                },
            )));
        }

        let shape = self.tensor_shape(input)?;
        if shape.len() != 2 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "histogramdd: input must be 2D (N samples x D dimensions)",
                },
            )));
        }
        let n_samples = shape[0];
        let n_dims = shape[1];

        if bins.len() != n_dims {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "histogramdd: bins length must match number of dimensions",
                },
            )));
        }
        for &b in bins {
            if b == 0 {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "histogramdd: all bin counts must be > 0",
                    },
                )));
            }
        }

        if let Some(r) = ranges
            && r.len() != n_dims
        {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "histogramdd: ranges length must match number of dimensions",
                },
            )));
        }

        // F32 no-grad fast path: the generic path materializes a full f64 copy
        // through tensor_values_lossy_f64 before the already-parallel local-bin
        // histogram. Borrow contiguous f32 and cast each lane to f64 at the same
        // binning point instead; f32->f64 is exact, so bin/tie behavior is unchanged.
        // Local bins count integers and convert once to f64, matching count output
        // for all materializable tensors while avoiding per-sample f64 additions.
        if self.tensor_dtype(input)? == DType::F32 {
            let built: Option<(Vec<f64>, Vec<(f64, f64)>, Vec<f64>)> = {
                let it = self.tensor_tape.tensor(input)?;
                if !it.meta().is_contiguous() {
                    None
                } else {
                    use rayon::prelude::*;

                    let vals = it.contiguous_values_f32()?;
                    let dim_ranges: Vec<(f64, f64)> = if let Some(r) = ranges {
                        r.to_vec()
                    } else {
                        (0..n_dims)
                            .map(|d| {
                                let mut lo = f64::INFINITY;
                                let mut hi = f64::NEG_INFINITY;
                                for s in 0..n_samples {
                                    let v = f64::from(vals[s * n_dims + d]);
                                    if v < lo {
                                        lo = v;
                                    }
                                    if v > hi {
                                        hi = v;
                                    }
                                }
                                if lo == hi {
                                    (lo - 0.5, hi + 0.5)
                                } else {
                                    (lo, hi)
                                }
                            })
                            .collect()
                    };
                    let bin_widths: Vec<f64> = bins
                        .iter()
                        .zip(&dim_ranges)
                        .map(|(&b, &(lo, hi))| (hi - lo) / b as f64)
                        .collect();
                    let total_bins: usize = bins.iter().product();

                    let sample_bin = |sample: usize| -> Option<usize> {
                        let mut linear_idx = 0usize;
                        for d in 0..n_dims {
                            let v = f64::from(vals[sample * n_dims + d]);
                            let (lo, hi) = dim_ranges[d];
                            if v < lo || v > hi {
                                return None;
                            }
                            #[allow(clippy::cast_sign_loss, clippy::cast_possible_truncation)]
                            let raw_bin = ((v - lo) / bin_widths[d]) as usize;
                            let bin = raw_bin.min(bins[d] - 1);
                            linear_idx = linear_idx * bins[d] + bin;
                        }
                        Some(linear_idx)
                    };

                    let mut counts = vec![0usize; total_bins];
                    if n_samples >= PARALLEL_ELEMENTWISE_MIN && rayon::current_num_threads() > 1 {
                        counts = (0..n_samples)
                            .into_par_iter()
                            .fold(
                                || vec![0usize; total_bins],
                                |mut local, sample| {
                                    if let Some(bin) = sample_bin(sample) {
                                        local[bin] += 1;
                                    }
                                    local
                                },
                            )
                            .reduce(
                                || vec![0usize; total_bins],
                                |mut a, b| {
                                    for (ai, bi) in a.iter_mut().zip(b.iter()) {
                                        *ai += bi;
                                    }
                                    a
                                },
                            );
                    } else {
                        for sample in 0..n_samples {
                            if let Some(bin) = sample_bin(sample) {
                                counts[bin] += 1;
                            }
                        }
                    }

                    #[allow(clippy::cast_precision_loss)]
                    let mut counts: Vec<f64> =
                        counts.into_iter().map(|count| count as f64).collect();
                    if density {
                        let total: f64 = counts.iter().sum();
                        let cell_volume: f64 = bin_widths.iter().product();
                        let scale = total * cell_volume;
                        if scale > 0.0 {
                            for count in &mut counts {
                                *count /= scale;
                            }
                        }
                    }

                    Some((counts, dim_ranges, bin_widths))
                }
            };

            if let Some((counts, dim_ranges, bin_widths)) = built {
                let hist = self.tensor_variable(counts, bins.to_vec(), false)?;
                let mut edge_tensors = Vec::with_capacity(n_dims);
                for d in 0..n_dims {
                    let edge_count = bins[d] + 1;
                    let (lo, _) = dim_ranges[d];
                    let edges: Vec<f64> = (0..edge_count)
                        .map(|i| lo + bin_widths[d] * i as f64)
                        .collect();
                    let edge_tensor = self.tensor_variable(edges, vec![edge_count], false)?;
                    edge_tensors.push(edge_tensor);
                }
                return Ok((hist, edge_tensors));
            }
        }

        // F64 fast path (asymmetric-dtype mirror of the F32 path above): the generic path below
        // CLONES the f64 input via `tensor_values_lossy_f64` + runs a SERIAL binning loop. Borrow
        // `contiguous_values()` (&[f64], no clone) + the same parallel local-bins N-D histogram.
        // BIT-IDENTICAL (same f64 values, same bin math, integer counts order-invariant).
        // Non-contiguous falls through to the generic path. frankentorch (BlackThrush).
        if self.tensor_dtype(input)? == DType::F64 {
            let built: Option<(Vec<f64>, Vec<(f64, f64)>, Vec<f64>)> = {
                let it = self.tensor_tape.tensor(input)?;
                if !it.meta().is_contiguous() {
                    None
                } else {
                    use rayon::prelude::*;

                    let vals = it.contiguous_values()?;
                    let dim_ranges: Vec<(f64, f64)> = if let Some(r) = ranges {
                        r.to_vec()
                    } else {
                        (0..n_dims)
                            .map(|d| {
                                let mut lo = f64::INFINITY;
                                let mut hi = f64::NEG_INFINITY;
                                for s in 0..n_samples {
                                    let v = vals[s * n_dims + d];
                                    if v < lo {
                                        lo = v;
                                    }
                                    if v > hi {
                                        hi = v;
                                    }
                                }
                                if lo == hi {
                                    (lo - 0.5, hi + 0.5)
                                } else {
                                    (lo, hi)
                                }
                            })
                            .collect()
                    };
                    let bin_widths: Vec<f64> = bins
                        .iter()
                        .zip(&dim_ranges)
                        .map(|(&b, &(lo, hi))| (hi - lo) / b as f64)
                        .collect();
                    let total_bins: usize = bins.iter().product();

                    let sample_bin = |sample: usize| -> Option<usize> {
                        let mut linear_idx = 0usize;
                        for d in 0..n_dims {
                            let v = vals[sample * n_dims + d];
                            let (lo, hi) = dim_ranges[d];
                            if v < lo || v > hi {
                                return None;
                            }
                            #[allow(clippy::cast_sign_loss, clippy::cast_possible_truncation)]
                            let raw_bin = ((v - lo) / bin_widths[d]) as usize;
                            let bin = raw_bin.min(bins[d] - 1);
                            linear_idx = linear_idx * bins[d] + bin;
                        }
                        Some(linear_idx)
                    };

                    let mut counts = vec![0usize; total_bins];
                    if n_samples >= PARALLEL_ELEMENTWISE_MIN && rayon::current_num_threads() > 1 {
                        counts = (0..n_samples)
                            .into_par_iter()
                            .fold(
                                || vec![0usize; total_bins],
                                |mut local, sample| {
                                    if let Some(bin) = sample_bin(sample) {
                                        local[bin] += 1;
                                    }
                                    local
                                },
                            )
                            .reduce(
                                || vec![0usize; total_bins],
                                |mut a, b| {
                                    for (ai, bi) in a.iter_mut().zip(b.iter()) {
                                        *ai += bi;
                                    }
                                    a
                                },
                            );
                    } else {
                        for sample in 0..n_samples {
                            if let Some(bin) = sample_bin(sample) {
                                counts[bin] += 1;
                            }
                        }
                    }

                    #[allow(clippy::cast_precision_loss)]
                    let mut counts: Vec<f64> =
                        counts.into_iter().map(|count| count as f64).collect();
                    if density {
                        let total: f64 = counts.iter().sum();
                        let cell_volume: f64 = bin_widths.iter().product();
                        let scale = total * cell_volume;
                        if scale > 0.0 {
                            for count in &mut counts {
                                *count /= scale;
                            }
                        }
                    }

                    Some((counts, dim_ranges, bin_widths))
                }
            };

            if let Some((counts, dim_ranges, bin_widths)) = built {
                let hist = self.tensor_variable(counts, bins.to_vec(), false)?;
                let mut edge_tensors = Vec::with_capacity(n_dims);
                for d in 0..n_dims {
                    let edge_count = bins[d] + 1;
                    let (lo, _) = dim_ranges[d];
                    let edges: Vec<f64> = (0..edge_count)
                        .map(|i| lo + bin_widths[d] * i as f64)
                        .collect();
                    let edge_tensor = self.tensor_variable(edges, vec![edge_count], false)?;
                    edge_tensors.push(edge_tensor);
                }
                return Ok((hist, edge_tensors));
            }
        }

        let vals = self.tensor_values_lossy_f64(input)?;

        // Compute ranges per dimension
        let dim_ranges: Vec<(f64, f64)> = if let Some(r) = ranges {
            r.to_vec()
        } else {
            (0..n_dims)
                .map(|d| {
                    let mut lo = f64::INFINITY;
                    let mut hi = f64::NEG_INFINITY;
                    for s in 0..n_samples {
                        let v = vals[s * n_dims + d];
                        if v < lo {
                            lo = v;
                        }
                        if v > hi {
                            hi = v;
                        }
                    }
                    if lo == hi {
                        (lo - 0.5, hi + 0.5)
                    } else {
                        (lo, hi)
                    }
                })
                .collect()
        };

        // Compute bin widths per dimension
        let bin_widths: Vec<f64> = bins
            .iter()
            .zip(&dim_ranges)
            .map(|(&b, &(lo, hi))| (hi - lo) / b as f64)
            .collect();

        // Initialize histogram counts
        let total_bins: usize = bins.iter().product();
        let mut counts = vec![0.0f64; total_bins];

        let sample_bin = |sample: usize| -> Option<usize> {
            let mut linear_idx = 0usize;
            for d in 0..n_dims {
                let v = vals[sample * n_dims + d];
                let (lo, hi) = dim_ranges[d];
                if v < lo || v > hi {
                    return None;
                }
                #[allow(clippy::cast_sign_loss, clippy::cast_possible_truncation)]
                let raw_bin = ((v - lo) / bin_widths[d]) as usize;
                let bin = raw_bin.min(bins[d] - 1);
                linear_idx = linear_idx * bins[d] + bin;
            }
            Some(linear_idx)
        };

        // Process samples. Counts are exact integer f64 increments, so local
        // per-thread histograms merge bit-identically to the serial scatter.
        if n_samples >= PARALLEL_ELEMENTWISE_MIN && rayon::current_num_threads() > 1 {
            use rayon::prelude::*;
            counts = (0..n_samples)
                .into_par_iter()
                .fold(
                    || vec![0.0f64; total_bins],
                    |mut local, sample| {
                        if let Some(bin) = sample_bin(sample) {
                            local[bin] += 1.0;
                        }
                        local
                    },
                )
                .reduce(
                    || vec![0.0f64; total_bins],
                    |mut a, b| {
                        for (ai, bi) in a.iter_mut().zip(b.iter()) {
                            *ai += bi;
                        }
                        a
                    },
                );
        } else {
            for sample in 0..n_samples {
                if let Some(bin) = sample_bin(sample) {
                    counts[bin] += 1.0;
                }
            }
        }

        if density {
            let total: f64 = counts.iter().sum();
            let cell_volume: f64 = bin_widths.iter().product();
            let scale = total * cell_volume;
            if scale > 0.0 {
                for count in &mut counts {
                    *count /= scale;
                }
            }
        }

        let hist = self.tensor_variable(counts, bins.to_vec(), false)?;

        // Create bin edge tensors for each dimension
        let mut edge_tensors = Vec::with_capacity(n_dims);
        for d in 0..n_dims {
            let edge_count = bins[d] + 1;
            let (lo, _) = dim_ranges[d];
            let edges: Vec<f64> = (0..edge_count)
                .map(|i| lo + bin_widths[d] * i as f64)
                .collect();
            let edge_tensor = self.tensor_variable(edges, vec![edge_count], false)?;
            edge_tensors.push(edge_tensor);
        }

        Ok((hist, edge_tensors))
    }

    /// Create a block diagonal matrix from provided 2-D tensors.
    ///
    /// Equivalent to `torch.block_diag(*tensors)`. Each tensor is placed
    /// along the diagonal of the output matrix, with zeros elsewhere.
    /// 1-D tensors are treated as (1, N) matrices.
    pub fn tensor_block_diag(
        &mut self,
        tensors: &[TensorNodeId],
    ) -> Result<TensorNodeId, AutogradError> {
        if tensors.is_empty() {
            return self.tensor_variable(vec![], vec![0, 0], false);
        }

        // Pre-compute block (rows, cols), output total dimensions, and
        // (row_offset, col_offset) per block. The forward + backward
        // closures need both the per-block extents (to walk the block)
        // and the offsets (to map block coords ↔ output coords).
        // We also preserve the original input shape (1-D vs 2-D) so
        // gradients return as the same rank.
        let mut block_meta: Vec<(usize, usize, usize, usize, Vec<usize>)> =
            Vec::with_capacity(tensors.len());
        for &t in tensors {
            let shape = self.tensor_shape(t)?;
            let (rows, cols) = match shape.len() {
                1 => (1, shape[0]),
                2 => (shape[0], shape[1]),
                _ => {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "block_diag: all tensors must be 1-D or 2-D",
                        },
                    )));
                }
            };
            block_meta.push((rows, cols, 0, 0, shape.clone()));
        }
        // Fill row/col offsets sequentially.
        let mut row_offset = 0usize;
        let mut col_offset = 0usize;
        for entry in &mut block_meta {
            entry.2 = row_offset;
            entry.3 = col_offset;
            row_offset = Self::checked_add(row_offset, entry.0, "block_diag: output overflow")?;
            col_offset = Self::checked_add(col_offset, entry.1, "block_diag: output overflow")?;
        }
        let total_rows = row_offset;
        let total_cols = col_offset;
        let numel = Self::checked_mul(total_rows, total_cols, "block_diag: output overflow")?;
        let _ = Self::checked_mul(
            numel,
            std::mem::size_of::<f64>(),
            "block_diag: output overflow",
        )?;

        // No-grad f32 native fast path: the apply_function path below reads the f32 blocks as
        // f64, builds an f64 zero matrix (2x the bandwidth of the mostly-zero output), then
        // downcasts to F32 -> ~5-6x SLOWER than torch at [4096,4096]. Build the F32 block-diagonal
        // directly: `vec![0.0f32; numel]` is alloc_zeroed (lazy calloc; 0.0f32 is all-zero bytes)
        // so the off-diagonal zeros cost no write bandwidth, then copy each block's contiguous
        // rows. Bit-identical to the composed path (same positional row copies). Grad / non-F32 /
        // non-contiguous fall through. frankentorch-blockdiag-f32-fused.
        let f32_fast = numel > 0
            && tensors
                .iter()
                .try_fold(true, |acc, &t| -> Result<bool, AutogradError> {
                    Ok(acc
                        && self.tensor_dtype(t)? == DType::F32
                        && !self.tensor_requires_grad(t)?
                        && self.tensor_tape.tensor(t)?.meta().is_contiguous())
                })?;
        if f32_fast {
            let mut data = vec![0.0_f32; numel];
            for (i, &t) in tensors.iter().enumerate() {
                let (rows, cols, row_off, col_off, _) = block_meta[i];
                let vals = self.tensor_tape.tensor(t)?.contiguous_values_f32()?;
                if vals.len() != rows * cols {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "block_diag: values length does not match shape",
                        },
                    )));
                }
                for r in 0..rows {
                    let dst = (row_off + r) * total_cols + col_off;
                    let src = r * cols;
                    data[dst..dst + cols].copy_from_slice(&vals[src..src + cols]);
                }
            }
            return self.tensor_variable_f32(data, vec![total_rows, total_cols], false);
        }

        // Forward + backward closures need the metadata at backward
        // time. tensor_apply_function captures via Send + Sync, so we
        // clone into the closures.
        let block_meta_fwd = block_meta.clone();
        let block_meta_bwd = block_meta.clone();
        self.tensor_apply_function(
            tensors,
            move |_ctx, inputs| {
                let mut data = vec![0.0_f64; total_rows * total_cols];
                for (i, (vals, _shape)) in inputs.iter().enumerate() {
                    let (rows, cols, row_off, col_off, _) = block_meta_fwd[i];
                    let expected = rows.checked_mul(cols).ok_or(AutogradError::Dispatch(
                        ft_dispatch::DispatchError::Key(
                            ft_dispatch::DispatchKeyError::IncompatibleSet {
                                reason: "block_diag: block size overflow",
                            },
                        ),
                    ))?;
                    if vals.len() != expected {
                        return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                            ft_dispatch::DispatchKeyError::IncompatibleSet {
                                reason: "block_diag: values length does not match shape",
                            },
                        )));
                    }
                    // Copy each contiguous row as a slice to avoid per-cell scatter.
                    for r in 0..rows {
                        let dst_start = (row_off + r) * total_cols + col_off;
                        let src_start = r * cols;
                        data[dst_start..dst_start + cols]
                            .copy_from_slice(&vals[src_start..src_start + cols]);
                    }
                }
                Ok((data, vec![total_rows, total_cols]))
            },
            move |_ctx, grad_outputs| {
                let grad_y = grad_outputs[0];
                let mut grads: Vec<Option<Vec<f64>>> = Vec::with_capacity(block_meta_bwd.len());
                for (rows, cols, row_off, col_off, original_shape) in &block_meta_bwd {
                    let mut grad_block = vec![0.0_f64; rows * cols];
                    // Copy each contiguous gradient row back into the source block.
                    for r in 0..*rows {
                        let src_start = (row_off + r) * total_cols + col_off;
                        let dst_start = r * cols;
                        grad_block[dst_start..dst_start + *cols]
                            .copy_from_slice(&grad_y[src_start..src_start + *cols]);
                    }
                    // Original 1-D inputs deserve a flat-1-D gradient
                    // (rows == 1 && shape.len() == 1) — the storage
                    // is row-major so the same Vec works.
                    let _ = original_shape;
                    grads.push(Some(grad_block));
                }
                Ok(grads)
            },
        )
    }

    /// Generate a Vandermonde matrix from a 1-D input tensor.
    ///
    /// Equivalent to `torch.vander(x, N=None, increasing=False)`.
    /// If `n` is None, N = len(x). Each row `i` is `[x[i]^(N-1), ..., x[i]^0]`
    /// (decreasing) or `[x[i]^0, ..., x[i]^(N-1)]` (increasing).
    pub fn tensor_vander(
        &mut self,
        input: TensorNodeId,
        n: Option<usize>,
        increasing: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        if shape.len() != 1 {
            // Migrate to InvalidDimension (frankentorch-qaux).
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::InvalidDimension {
                    dim: shape.len(),
                    ndim: 1,
                },
            )));
        }
        let rows = shape[0];
        let cols = n.unwrap_or(rows);
        if cols > i32::MAX as usize {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "vander: N too large",
                },
            )));
        }
        let numel = Self::checked_mul(rows, cols, "vander: output size overflow")?;
        let _ = Self::checked_mul(
            numel,
            std::mem::size_of::<f64>(),
            "vander: output size overflow",
        )?;

        // Forward: output[i, j] = x[i]^exp_j   where
        //     exp_j = j if increasing else cols-1-j.
        // Backward (each row depends only on x[i]):
        //     d output[i, j] / d x[i] = exp_j * x[i]^(exp_j - 1)   (0 when exp_j == 0)
        //     grad_input[i] = sum_j grad_output[i, j] * exp_j * x[i]^(exp_j - 1)
        // Save x for backward. Tracked under frankentorch-j3kg.
        self.tensor_apply_function(
            &[input],
            move |ctx, inputs| {
                let (vals, _in_shape) = inputs[0];
                if vals.len() != rows {
                    // Surface both actual lengths so the caller
                    // can diagnose the closure-time mismatch
                    // without grepping a static reason
                    // (frankentorch-zurt).
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                        ft_kernel_cpu::KernelError::ShapeMismatch {
                            lhs: vec![vals.len()],
                            rhs: vec![rows],
                        },
                    )));
                }
                // Each row i is vals[i] raised to the column exponents — independent,
                // disjoint, and compute-bound (powi). Distribute the rows across the
                // rayon pool; bit-identical to the serial fill. frankentorch-kgs4.105.
                let mut data = vec![0.0_f64; numel];
                let fill = |i: usize, row: &mut [f64]| {
                    let xi = vals[i];
                    for (j, slot) in row.iter_mut().enumerate() {
                        let exp = if increasing { j } else { cols - 1 - j };
                        *slot = xi.powi(exp as i32);
                    }
                };
                if numel >= PARALLEL_ELEMENTWISE_MIN {
                    use rayon::prelude::*;
                    data.par_chunks_mut(cols.max(1))
                        .enumerate()
                        .for_each(|(i, row)| fill(i, row));
                } else {
                    data.chunks_mut(cols.max(1))
                        .enumerate()
                        .for_each(|(i, row)| fill(i, row));
                }
                ctx.save_for_backward(vals.to_vec(), vec![rows]);
                Ok((data, vec![rows, cols]))
            },
            move |ctx, grad_outputs| {
                let grad_y = grad_outputs[0];
                let saved = ctx.saved_tensors();
                let x_vals = &saved[0];
                let mut grad_in = vec![0.0_f64; rows];
                for i in 0..rows {
                    let xi = x_vals[i];
                    let mut acc = 0.0_f64;
                    for j in 0..cols {
                        let exp = if increasing { j } else { cols - 1 - j };
                        if exp == 0 {
                            // d x^0 / dx = 0; constant column contributes nothing.
                            continue;
                        }
                        let power = (exp - 1) as i32;
                        let coeff = exp as f64;
                        acc += grad_y[i * cols + j] * coeff * xi.powi(power);
                    }
                    grad_in[i] = acc;
                }
                Ok(vec![Some(grad_in)])
            },
        )
    }

    /// Create a complex tensor from magnitude and phase angle.
    ///
    /// Equivalent to `torch.polar(abs, angle)`.
    /// Returns a complex tensor where `real = abs * cos(angle)` and `imag = abs * sin(angle)`.
    ///
    /// Inputs should be F32 tensors (Complex64 output) or F64 tensors (Complex128 output).
    pub fn tensor_polar(
        &mut self,
        abs: TensorNodeId,
        angle: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // Compute real = abs * cos(angle), imag = abs * sin(angle) via autograd ops
        let cos_angle = self.tensor_cos(angle)?;
        let sin_angle = self.tensor_sin(angle)?;
        let real = self.tensor_mul(abs, cos_angle)?;
        let imag = self.tensor_mul(abs, sin_angle)?;
        self.tensor_complex(real, imag)
    }

    /// Cartesian product of 1-D tensors.
    ///
    /// Equivalent to `torch.cartesian_prod(*tensors)`.
    /// Returns a 2-D tensor where each row is one element of the Cartesian product.
    pub fn tensor_cartesian_prod(
        &mut self,
        tensors: &[TensorNodeId],
    ) -> Result<TensorNodeId, AutogradError> {
        if tensors.is_empty() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "cartesian_prod: need at least one tensor",
                },
            )));
        }

        // Validate shapes + collect lengths.
        let mut lengths: Vec<usize> = Vec::with_capacity(tensors.len());
        for &t in tensors {
            let s = self.tensor_shape(t)?;
            if s.len() != 1 {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "cartesian_prod: all inputs must be 1-D",
                    },
                )));
            }
            lengths.push(s[0]);
        }
        let n_tensors = lengths.len();
        let mut total_rows = 1usize;
        for &len in &lengths {
            total_rows = total_rows.checked_mul(len).ok_or(AutogradError::Dispatch(
                ft_dispatch::DispatchError::Key(ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "cartesian_prod: total row count overflow",
                }),
            ))?;
        }
        let _ = total_rows
            .checked_mul(n_tensors)
            .ok_or(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "cartesian_prod: output size overflow",
                },
            )))?;

        // F32 no-grad native fast path. The path below precomputes a Vec<Vec<usize>> mapping
        // SERIALLY over all total_rows (16.7M serial pushes for 2x[4096]) and then gathers through
        // apply_function (f64 upcast) -> measured ~14x SLOWER than torch. Decode each output row's
        // per-tensor index on the fly via mixed-radix division (stride_k = prod(lengths[k+1..])) and
        // gather the f32 values directly, parallel over output rows. Bit-exact (pure value gather, no
        // arithmetic). Grad / non-F32 / non-contiguous fall through. frankentorch-cartprod-f32-fused.
        let all_f32_nograd =
            tensors
                .iter()
                .try_fold(true, |acc, &t| -> Result<bool, AutogradError> {
                    Ok(acc
                        && self.tensor_dtype(t)? == DType::F32
                        && !self.tensor_requires_grad(t)?
                        && self.tensor_tape.tensor(t)?.meta().is_contiguous())
                })?;
        if all_f32_nograd && total_rows > 0 {
            let mut strides = vec![1usize; n_tensors];
            for k in (0..n_tensors.saturating_sub(1)).rev() {
                strides[k] = strides[k + 1] * lengths[k + 1];
            }
            let data = {
                let slices: Vec<&[f32]> = tensors
                    .iter()
                    .map(|&t| -> Result<&[f32], AutogradError> {
                        Ok(self.tensor_tape.tensor(t)?.contiguous_values_f32()?)
                    })
                    .collect::<Result<_, _>>()?;
                let mut data = vec![0.0_f32; total_rows * n_tensors];
                use rayon::prelude::*;
                data.par_chunks_mut(n_tensors)
                    .enumerate()
                    .for_each(|(r, row)| {
                        for k in 0..n_tensors {
                            let idx = (r / strides[k]) % lengths[k];
                            row[k] = slices[k][idx];
                        }
                    });
                data
            };
            return self.tensor_variable_f32(data, vec![total_rows, n_tensors], false);
        }

        // Pre-compute the (row, k) → input_index_in_tensor_k mapping.
        // The forward gathers; the backward scatters. Tracked under
        // frankentorch-7ude.
        let mut mapping: Vec<Vec<usize>> = vec![Vec::with_capacity(total_rows); n_tensors];
        let mut indices = vec![0usize; n_tensors];
        for _ in 0..total_rows {
            for k in 0..n_tensors {
                mapping[k].push(indices[k]);
            }
            for k in (0..n_tensors).rev() {
                indices[k] += 1;
                if indices[k] < lengths[k] {
                    break;
                }
                indices[k] = 0;
            }
        }

        let mapping_for_fwd = mapping.clone();
        let mapping_for_bwd = mapping;
        let lengths_clone = lengths;
        let total_rows_c = total_rows;
        let n_tensors_c = n_tensors;

        self.tensor_apply_function(
            tensors,
            move |_ctx, inputs| {
                let mut result = Vec::with_capacity(total_rows_c * n_tensors_c);
                for row in 0..total_rows_c {
                    for (k, mapping_k) in mapping_for_fwd.iter().enumerate() {
                        let idx = mapping_k[row];
                        let (vals, _shape) = inputs[k];
                        result.push(vals[idx]);
                    }
                }
                Ok((result, vec![total_rows_c, n_tensors_c]))
            },
            move |_ctx, grad_outputs| {
                let g = grad_outputs[0];
                // For each input tensor k, scatter g[row, k] back to
                // grad_input_k[mapping[k][row]].
                let mut grads: Vec<Option<Vec<f64>>> = Vec::with_capacity(n_tensors_c);
                for k in 0..n_tensors_c {
                    let mut grad_k = vec![0.0_f64; lengths_clone[k]];
                    for row in 0..total_rows_c {
                        let i = mapping_for_bwd[k][row];
                        grad_k[i] += g[row * n_tensors_c + k];
                    }
                    grads.push(Some(grad_k));
                }
                Ok(grads)
            },
        )
    }

    /// All r-length combinations of elements from a 1-D tensor.
    ///
    /// Equivalent to `torch.combinations(input, r, with_replacement)`.
    /// Returns a 2-D tensor where each row is one combination.
    pub fn tensor_combinations(
        &mut self,
        input: TensorNodeId,
        r: usize,
        with_replacement: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        if shape.len() != 1 {
            // Migrate to InvalidDimension (frankentorch-qaux).
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::InvalidDimension {
                    dim: shape.len(),
                    ndim: 1,
                },
            )));
        }
        let n = shape[0];

        // No-grad fast path for the dominant r==2 case (pairwise combinations). The general path
        // below builds the full combo index table with a SERIAL recursion (`generate_idx`), then
        // clones it and gathers through apply_function. For r==2 the output is fully described in
        // closed form — pairs (i, j) with j in (i+1 | i)..n in lexicographic order — so we skip
        // generate_idx entirely and fill the output in PARALLEL over the first element `i`,
        // gathering native f32/f64 (no upcast, no index table, no clone, no tape). flat_map_iter
        // preserves i-order, matching torch. Bit-identical (pure movement). Grad / r!=2 /
        // non-contiguous fall through to the general recursive path.
        if r == 2
            && !self.tensor_requires_grad(input)?
            && matches!(self.tensor_dtype(input)?, DType::F64 | DType::F32)
            && self.tensor_tape.tensor(input)?.meta().is_contiguous()
        {
            let num_combos = if with_replacement {
                Self::checked_mul(n, n + 1, "combinations output size overflow")? / 2
            } else if n >= 1 {
                Self::checked_mul(n, n - 1, "combinations output size overflow")? / 2
            } else {
                0
            };
            if num_combos == 0 {
                return self.tensor_variable(vec![], vec![0, r], false);
            }
            let total = num_combos * 2;
            let parallel = total >= PARALLEL_ELEMENTWISE_MIN;
            let start_of = move |i: usize| if with_replacement { i } else { i + 1 };
            if self.tensor_dtype(input)? == DType::F32 {
                let vals = self.tensor_tape.tensor(input)?.contiguous_values_f32()?;
                let result: Vec<f32> = if parallel {
                    use rayon::prelude::*;
                    (0..n)
                        .into_par_iter()
                        .flat_map_iter(|i| (start_of(i)..n).flat_map(move |j| [vals[i], vals[j]]))
                        .collect()
                } else {
                    (0..n)
                        .flat_map(|i| (start_of(i)..n).flat_map(move |j| [vals[i], vals[j]]))
                        .collect()
                };
                return self.tensor_variable_f32(result, vec![num_combos, r], false);
            }
            let vals = self.tensor_tape.tensor(input)?.contiguous_values()?;
            let result: Vec<f64> = if parallel {
                use rayon::prelude::*;
                (0..n)
                    .into_par_iter()
                    .flat_map_iter(|i| (start_of(i)..n).flat_map(move |j| [vals[i], vals[j]]))
                    .collect()
            } else {
                (0..n)
                    .flat_map(|i| (start_of(i)..n).flat_map(move |j| [vals[i], vals[j]]))
                    .collect()
            };
            return self.tensor_variable(result, vec![num_combos, r], false);
        }

        // Pre-compute the index-mapping: combo_indices is a flat list
        // of (input_position) for each (combo, slot_in_combo) cell of
        // the output. Use the same recursive enumeration as before
        // but track indices instead of values. The mapping is then
        // captured by the forward (gather) and backward (scatter)
        // closures in tensor_apply_function. Tracked under
        // frankentorch-d214 — previously this body extracted values,
        // built the output in plain f64, and rebuilt a non-grad leaf.
        let mut combo_indices: Vec<usize> = Vec::new();
        let mut current_indices: Vec<usize> = Vec::with_capacity(r);

        fn generate_idx(
            n: usize,
            r: usize,
            start: usize,
            current: &mut Vec<usize>,
            out: &mut Vec<usize>,
            with_replacement: bool,
        ) {
            if current.len() == r {
                out.extend_from_slice(current);
                return;
            }
            for i in start..n {
                current.push(i);
                let next = if with_replacement { i } else { i + 1 };
                generate_idx(n, r, next, current, out, with_replacement);
                current.pop();
            }
        }

        generate_idx(
            n,
            r,
            0,
            &mut current_indices,
            &mut combo_indices,
            with_replacement,
        );

        let num_combos = combo_indices.len().checked_div(r).unwrap_or(1);
        let total = Self::checked_mul(num_combos, r, "combinations output size overflow")?;

        if num_combos == 0 {
            return self.tensor_variable(vec![], vec![0, r], false);
        }

        // No-grad fast path (f32/f64): the gather table `combo_indices` is built. The grad path
        // below CLONES it (a second `total`-sized usize Vec just for the backward closure), gathers
        // through apply_function (which UPCASTS f32->f64), and builds a tape node. None of that is
        // needed without grad — gather the input NATIVELY (f32 stays f32) in PARALLEL, reusing
        // `combo_indices` directly (no clone, no upcast, no tape). Bit-identical (pure movement).
        // Non-contiguous / grad fall through to the general apply_function path.
        if !self.tensor_requires_grad(input)?
            && matches!(self.tensor_dtype(input)?, DType::F64 | DType::F32)
            && self.tensor_tape.tensor(input)?.meta().is_contiguous()
        {
            let parallel = total >= PARALLEL_ELEMENTWISE_MIN;
            if self.tensor_dtype(input)? == DType::F32 {
                let vals = self.tensor_tape.tensor(input)?.contiguous_values_f32()?;
                let result: Vec<f32> = if parallel {
                    use rayon::prelude::*;
                    combo_indices.par_iter().map(|&i| vals[i]).collect()
                } else {
                    combo_indices.iter().map(|&i| vals[i]).collect()
                };
                return self.tensor_variable_f32(result, vec![num_combos, r], false);
            }
            let vals = self.tensor_tape.tensor(input)?.contiguous_values()?;
            let result: Vec<f64> = if parallel {
                use rayon::prelude::*;
                combo_indices.par_iter().map(|&i| vals[i]).collect()
            } else {
                combo_indices.iter().map(|&i| vals[i]).collect()
            };
            return self.tensor_variable(result, vec![num_combos, r], false);
        }

        let mapping_for_fwd = combo_indices.clone();
        let mapping_for_bwd = combo_indices;
        self.tensor_apply_function(
            &[input],
            move |_ctx, inputs| {
                let (vals, _shape) = inputs[0];
                let result: Vec<f64> = mapping_for_fwd.iter().map(|&i| vals[i]).collect();
                Ok((result, vec![num_combos, r]))
            },
            move |_ctx, grad_outputs| {
                let g = grad_outputs[0];
                let mut grad_in = vec![0.0_f64; n];
                for (out_pos, &in_pos) in mapping_for_bwd.iter().enumerate() {
                    grad_in[in_pos] += g[out_pos];
                }
                let _ = total; // keep total in scope for size validation above
                Ok(vec![Some(grad_in)])
            },
        )
    }

    /// Compute r-length combinations with replacement from a 1D input tensor.
    ///
    /// Equivalent to `torch.combinations(input, r, with_replacement=True)`.
    /// This is a convenience wrapper around `tensor_combinations` with
    /// `with_replacement=true`.
    pub fn tensor_combinations_with_replacement(
        &mut self,
        input: TensorNodeId,
        r: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_combinations(input, r, true)
    }

    /// Compute batched pairwise distance between two sets of vectors.
    ///
    /// Equivalent to `torch.cdist(x1, x2, p=2.0)`.
    /// x1: (B, P, M) or (P, M), x2: (B, R, M) or (R, M).
    /// Returns: (B, P, R) or (P, R) matrix of Lp distances.
    pub fn tensor_cdist(
        &mut self,
        x1: TensorNodeId,
        x2: TensorNodeId,
        p: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let x1_shape = self.tensor_shape(x1)?;
        let x2_shape = self.tensor_shape(x2)?;
        Self::validate_nonnegative_norm_order(p, "cdist: p must be in [0, inf]")?;

        let (batch, p_dim, m1, r_dim, m2, batched) = match (x1_shape.len(), x2_shape.len()) {
            (2, 2) => (1, x1_shape[0], x1_shape[1], x2_shape[0], x2_shape[1], false),
            (3, 3) => {
                if x1_shape[0] != x2_shape[0] {
                    // Surface both shapes so the caller can see the
                    // actual batch sizes (frankentorch-zf6b).
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                        ft_kernel_cpu::KernelError::ShapeMismatch {
                            lhs: x1_shape,
                            rhs: x2_shape,
                        },
                    )));
                }
                (
                    x1_shape[0],
                    x1_shape[1],
                    x1_shape[2],
                    x2_shape[1],
                    x2_shape[2],
                    true,
                )
            }
            _ => {
                // Surface the actual x1 rank that was given so the
                // caller sees 'expected 2 or 3 but got N' instead
                // of an opaque static reason (frankentorch-zf6b).
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                    ft_kernel_cpu::KernelError::InvalidDimension {
                        dim: 0,
                        ndim: x1_shape.len(),
                    },
                )));
            }
        };

        if m1 != m2 {
            // Caller compares lhs/rhs at the last dim to see which
            // feature size disagreed (frankentorch-zf6b).
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: x1_shape,
                    rhs: x2_shape,
                },
            )));
        }
        let m = m1;
        let x1_requires_grad = self.tensor_tape.tensor_requires_grad(x1)?;
        let x2_requires_grad = self.tensor_tape.tensor_requires_grad(x2)?;
        let needs_grad = x1_requires_grad || x2_requires_grad;

        // Euclidean (p == 2) fast path — the dominant case AND torch's default
        // `compute_mode` for p=2. Uses the matmul identity
        //     d² = ‖x1‖² + ‖x2‖² − 2·x1·x2ᵀ
        // instead of materialising the broadcasted [P, R, M] (or [B, P, R, M])
        // difference tensor and reducing it: the cross term is one GEMM-routed
        // matmul/bmm, the norms are two M-axis reductions, and the result is
        // assembled with O(P·R) broadcast adds — no O(P·R·M) intermediate. The
        // whole chain is autograd-aware (matmul/bmm/sum/clamp/sqrt all record on
        // the tape), and for distinct points its gradient (x1−x2)/d is identical
        // to the direct path; coincident points (d=0) are clamped to 0 before the
        // sqrt exactly as torch's mm path does. Matches the direct sum to FFT-free
        // f64 round-off (~1e-12), well inside the cdist tolerance contract.
        // No-grad f64 p=2 FUSED fast path (2-D AND batched 3-D): the composed trick below builds ~8+
        // tape ops (mul×2, matmul/bmm, sum_dim×2, unsqueeze×2, EXPAND×2 to [P,R], add, mul_scalar, sub,
        // clamp, sqrt) — each materialising [..,P,R] even no-grad (measured 45x slower than PyTorch's
        // fused trick at 2-D). This does the SAME trick per batch in one GEMM + one fused assembly pass:
        // cross = X1·X2ᵀ (raw kernel), per-row ‖·‖², then out[i,j]=sqrt(max(nx[i]+ny[j]−2·cross[i,j],0)).
        // Same math as the composed path. frankentorch-cdist-p2-fused.
        if p == 2.0
            && m > 0
            && batch * p_dim * r_dim > 0
            && self.tensor_dtype(x1)? == DType::F64
            && self.tensor_dtype(x2)? == DType::F64
            && !x1_requires_grad
            && !x2_requires_grad
            && self.tensor_tape.tensor(x1)?.meta().is_contiguous()
            && self.tensor_tape.tensor(x2)?.meta().is_contiguous()
        {
            use rayon::prelude::*;
            let x1_vals = self.tensor_values(x1)?;
            let x2_vals = self.tensor_values(x2)?;
            let mut out = Vec::new();
            for b in 0..batch {
                let x1b = &x1_vals[b * p_dim * m..(b + 1) * p_dim * m];
                let x2b = &x2_vals[b * r_dim * m..(b + 1) * r_dim * m];
                let nx: Vec<f64> = (0..p_dim)
                    .map(|i| x1b[i * m..i * m + m].iter().map(|&v| v * v).sum())
                    .collect();
                let ny: Vec<f64> = (0..r_dim)
                    .map(|j| x2b[j * m..j * m + m].iter().map(|&v| v * v).sum())
                    .collect();
                let mut batch_out =
                    ft_kernel_cpu::matmul_rhs_transposed_contiguous_f64(p_dim, m, r_dim, x1b, x2b)
                        .map_err(|e| {
                            AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                        })?;
                batch_out
                    .par_chunks_mut(r_dim)
                    .enumerate()
                    .for_each(|(i, row)| {
                        let nxi = nx[i];
                        for j in 0..r_dim {
                            row[j] = (nxi + ny[j] - 2.0 * row[j]).max(0.0).sqrt();
                        }
                    });
                if batch == 1 {
                    out = batch_out;
                } else {
                    if out.capacity() == 0 {
                        out.reserve_exact(batch * p_dim * r_dim);
                    }
                    out.extend(batch_out);
                }
            }
            let out_shape = if batched {
                vec![batch, p_dim, r_dim]
            } else {
                vec![p_dim, r_dim]
            };
            return self.tensor_variable(out, out_shape, false);
        }

        if p == 2.0
            && m > 0
            && batch * p_dim * r_dim > 0
            && self.tensor_dtype(x1)? == DType::F32
            && self.tensor_dtype(x2)? == DType::F32
            && !x1_requires_grad
            && !x2_requires_grad
            && self.tensor_tape.tensor(x1)?.meta().is_contiguous()
            && self.tensor_tape.tensor(x2)?.meta().is_contiguous()
        {
            use rayon::prelude::*;
            let x1_vals = self.tensor_values_f32(x1)?;
            let x2_vals = self.tensor_values_f32(x2)?;
            let mut out = Vec::new();
            for b in 0..batch {
                let x1b = &x1_vals[b * p_dim * m..(b + 1) * p_dim * m];
                let x2b = &x2_vals[b * r_dim * m..(b + 1) * r_dim * m];
                let nx: Vec<f32> = (0..p_dim)
                    .map(|i| x1b[i * m..i * m + m].iter().map(|&v| v * v).sum())
                    .collect();
                let ny: Vec<f32> = (0..r_dim)
                    .map(|j| x2b[j * m..j * m + m].iter().map(|&v| v * v).sum())
                    .collect();
                let mut batch_out =
                    ft_kernel_cpu::matmul_rhs_transposed_contiguous_f32(p_dim, m, r_dim, x1b, x2b)
                        .map_err(|e| {
                            AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                        })?;
                batch_out
                    .par_chunks_mut(r_dim)
                    .enumerate()
                    .for_each(|(i, row)| {
                        let nxi = nx[i];
                        for j in 0..r_dim {
                            row[j] = (nxi + ny[j] - 2.0_f32 * row[j]).max(0.0_f32).sqrt();
                        }
                    });
                if batch == 1 {
                    out = batch_out;
                } else {
                    if out.capacity() == 0 {
                        out.reserve_exact(batch * p_dim * r_dim);
                    }
                    out.extend(batch_out);
                }
            }
            let out_shape = if batched {
                vec![batch, p_dim, r_dim]
            } else {
                vec![p_dim, r_dim]
            };
            return self.tensor_variable_f32(out, out_shape, false);
        }

        if needs_grad
            && (p == 1.0 || p == 2.0)
            && m > 0
            && batch * p_dim * r_dim > 0
            && self.tensor_dtype(x1)? == DType::F64
            && self.tensor_dtype(x2)? == DType::F64
            && self.tensor_tape.tensor(x1)?.meta().is_contiguous()
            && self.tensor_tape.tensor(x2)?.meta().is_contiguous()
        {
            use rayon::prelude::*;

            let out_shape = if batched {
                vec![batch, p_dim, r_dim]
            } else {
                vec![p_dim, r_dim]
            };
            return self.tensor_apply_function_f64_borrowed_inputs(
                &[x1, x2],
                move |_ctx, ins| {
                    let (x1_vals, _) = ins[0];
                    let (x2_vals, _) = ins[1];
                    let mut out = vec![0.0f64; batch * p_dim * r_dim];
                    if p == 2.0 {
                        for b in 0..batch {
                            let x1b = &x1_vals[b * p_dim * m..(b + 1) * p_dim * m];
                            let x2b = &x2_vals[b * r_dim * m..(b + 1) * r_dim * m];
                            let nx: Vec<f64> = (0..p_dim)
                                .map(|i| x1b[i * m..i * m + m].iter().map(|&v| v * v).sum())
                                .collect();
                            let ny: Vec<f64> = (0..r_dim)
                                .map(|j| x2b[j * m..j * m + m].iter().map(|&v| v * v).sum())
                                .collect();
                            let cross = ft_kernel_cpu::matmul_rhs_transposed_contiguous_f64(
                                p_dim, m, r_dim, x1b, x2b,
                            )
                            .map_err(|e| {
                                AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                            })?;
                            let obatch = &mut out[b * p_dim * r_dim..(b + 1) * p_dim * r_dim];
                            obatch
                                .par_chunks_mut(r_dim)
                                .zip(cross.par_chunks(r_dim))
                                .enumerate()
                                .for_each(|(i, (orow, crow))| {
                                    let nxi = nx[i];
                                    for j in 0..r_dim {
                                        orow[j] = (nxi + ny[j] - 2.0 * crow[j]).max(0.0).sqrt();
                                    }
                                });
                        }
                    } else {
                        out.par_chunks_mut(r_dim)
                            .enumerate()
                            .for_each(|(row, orow)| {
                                let b = row / p_dim;
                                let i = row % p_dim;
                                let x1_base = b * p_dim * m + i * m;
                                let x2_batch = b * r_dim * m;
                                for j in 0..r_dim {
                                    let mut acc = 0.0;
                                    let x2_base = x2_batch + j * m;
                                    for k in 0..m {
                                        acc += (x1_vals[x1_base + k] - x2_vals[x2_base + k]).abs();
                                    }
                                    orow[j] = acc;
                                }
                            });
                    }
                    Ok((out, out_shape))
                },
                move |_ctx, grad_outputs, borrowed| {
                    let gout = grad_outputs[0];
                    let expected = batch * p_dim * r_dim;
                    if gout.len() != expected {
                        return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                            ft_dispatch::DispatchKeyError::IncompatibleSet {
                                reason: "cdist backward: incoming gradient shape mismatch",
                            },
                        )));
                    }
                    let x1_vals = borrowed[0].0;
                    let x2_vals = borrowed[1].0;

                    let grad_x1 = if x1_requires_grad {
                        let mut grad = vec![0.0f64; x1_vals.len()];
                        grad.par_chunks_mut(m).enumerate().for_each(|(row, grow)| {
                            let b = row / p_dim;
                            let i = row % p_dim;
                            let x1_base = b * p_dim * m + i * m;
                            let x2_batch = b * r_dim * m;
                            let gout_row = b * p_dim * r_dim + i * r_dim;
                            for j in 0..r_dim {
                                let x2_base = x2_batch + j * m;
                                let g = gout[gout_row + j];
                                if p == 2.0 {
                                    let mut sumsq = 0.0;
                                    for k in 0..m {
                                        let d = x1_vals[x1_base + k] - x2_vals[x2_base + k];
                                        sumsq += d * d;
                                    }
                                    if sumsq > 0.0 {
                                        let coeff = g / sumsq.sqrt();
                                        for k in 0..m {
                                            let d = x1_vals[x1_base + k] - x2_vals[x2_base + k];
                                            grow[k] += coeff * d;
                                        }
                                    }
                                } else {
                                    for k in 0..m {
                                        let d = x1_vals[x1_base + k] - x2_vals[x2_base + k];
                                        grow[k] += g * d.signum();
                                    }
                                }
                            }
                        });
                        Some(grad)
                    } else {
                        None
                    };

                    let grad_x2 = if x2_requires_grad {
                        let mut grad = vec![0.0f64; x2_vals.len()];
                        grad.par_chunks_mut(m).enumerate().for_each(|(row, grow)| {
                            let b = row / r_dim;
                            let j = row % r_dim;
                            let x2_base = b * r_dim * m + j * m;
                            let x1_batch = b * p_dim * m;
                            let gout_batch = b * p_dim * r_dim;
                            for i in 0..p_dim {
                                let x1_base = x1_batch + i * m;
                                let g = gout[gout_batch + i * r_dim + j];
                                if p == 2.0 {
                                    let mut sumsq = 0.0;
                                    for k in 0..m {
                                        let d = x1_vals[x1_base + k] - x2_vals[x2_base + k];
                                        sumsq += d * d;
                                    }
                                    if sumsq > 0.0 {
                                        let coeff = g / sumsq.sqrt();
                                        for k in 0..m {
                                            let d = x1_vals[x1_base + k] - x2_vals[x2_base + k];
                                            grow[k] -= coeff * d;
                                        }
                                    }
                                } else {
                                    for k in 0..m {
                                        let d = x1_vals[x1_base + k] - x2_vals[x2_base + k];
                                        grow[k] -= g * d.signum();
                                    }
                                }
                            }
                        });
                        Some(grad)
                    } else {
                        None
                    };

                    Ok(vec![grad_x1, grad_x2])
                },
            );
        }

        if p == 2.0 && m > 0 && batch * p_dim * r_dim > 0 {
            let x1_sq = self.tensor_mul(x1, x1)?;
            let x2_sq = self.tensor_mul(x2, x2)?;
            let (cross, x1_norm_b, x2_norm_b, out_shape) = if batched {
                // x1 [B,P,M], x2 [B,R,M] -> cross [B,P,R].
                let x2_t = self.tensor_transpose(x2, 1, 2)?;
                let cross = self.tensor_bmm(x1, x2_t)?;
                let x1_norm = self.tensor_sum_dim(x1_sq, 2)?; // [B,P]
                let x2_norm = self.tensor_sum_dim(x2_sq, 2)?; // [B,R]
                let x1_u = self.tensor_unsqueeze(x1_norm, 2)?; // [B,P,1]
                let x2_u = self.tensor_unsqueeze(x2_norm, 1)?; // [B,1,R]
                let target = vec![batch, p_dim, r_dim];
                let x1_e = self.tensor_expand(x1_u, target.clone())?;
                let x2_e = self.tensor_expand(x2_u, target)?;
                (cross, x1_e, x2_e, vec![batch, p_dim, r_dim])
            } else {
                // x1 [P,M], x2 [R,M] -> cross [P,R].
                let x2_t = self.tensor_transpose(x2, 0, 1)?;
                let cross = self.tensor_matmul(x1, x2_t)?;
                let x1_norm = self.tensor_sum_dim(x1_sq, 1)?; // [P]
                let x2_norm = self.tensor_sum_dim(x2_sq, 1)?; // [R]
                let x1_u = self.tensor_unsqueeze(x1_norm, 1)?; // [P,1]
                let x2_u = self.tensor_unsqueeze(x2_norm, 0)?; // [1,R]
                let target = vec![p_dim, r_dim];
                let x1_e = self.tensor_expand(x1_u, target.clone())?;
                let x2_e = self.tensor_expand(x2_u, target)?;
                (cross, x1_e, x2_e, vec![p_dim, r_dim])
            };
            let norm_sum = self.tensor_add(x1_norm_b, x2_norm_b)?;
            let two_cross = self.tensor_mul_scalar(cross, 2.0)?;
            let d2 = self.tensor_sub(norm_sum, two_cross)?;
            // Clamp tiny negative round-off to 0 before sqrt (torch does the same).
            let d2_clamped = self.tensor_clamp_min(d2, 0.0)?;
            let dist = self.tensor_sqrt(d2_clamped)?;
            return self.tensor_reshape(dist, out_shape);
        }

        // No-grad fused fast path for finite p>0 (p≠2) or p=+inf. The autograd
        // path below materialises the broadcasted [P,R,M] (or [B,P,R,M])
        // difference and streams ~4 full-size passes (expand/sub/abs/pow/sum)
        // over it; when no gradient is needed, ft_kernel_cpu::cdist_forward_f64
        // reduces each (i,j) in ONE pass with no O(P·R·M) intermediate. Same
        // per-k accumulation order as the broadcast path -> matches to f64
        // round-off. p=2 already returned via the matmul identity above.
        // The fused fast path uses the F64-only cdist_forward_f64 kernel, so gate
        // it to F64 inputs; f32/half inputs fall through to the composed path
        // below (dtype-preserving, genuine-f32 arithmetic = torch parity).
        // frankentorch-fk5l.
        if !needs_grad
            && self.tensor_dtype(x1)? == DType::F64
            && self.tensor_dtype(x2)? == DType::F64
            && m > 0
            && batch * p_dim * r_dim > 0
            && (p == f64::INFINITY || (p.is_finite() && p > 0.0))
        {
            let x1_vals = self.tensor_values(x1)?;
            let x2_vals = self.tensor_values(x2)?;
            let result =
                ft_kernel_cpu::cdist_forward_f64(&x1_vals, &x2_vals, batch, p_dim, r_dim, m, p);
            let out_shape = if batched {
                vec![batch, p_dim, r_dim]
            } else {
                vec![p_dim, r_dim]
            };
            return self.tensor_variable(result, out_shape, false);
        }

        // F32 no-grad fused fast path (asymmetric-dtype sibling of the F64 one). f32 general-p
        // had NO fused path and fell through to the composed autograd path below, which
        // materialises the broadcasted [B,P,R,M] difference (P·R·M elems) — measured ~129x
        // SLOWER than torch at p=1, ~9.6x at p=3 ([2000,200]², a 3.2GB intermediate). The
        // INPUTS ([B,P,M]+[B,R,M]) are tiny, so upcast them to f64, run the same parallel
        // per-row `cdist_forward_f64` kernel (no O(P·R·M) intermediate), then narrow the
        // distances to f32. cdist is a TOLERANCE op (approx golden vs torch; powf is
        // libm-vs-SLEEF), and f64 distances narrowed to f32 are AT LEAST as accurate as
        // torch's own f32 path, so this is within tol; the output stays f32 (torch parity).
        // frankentorch-cdist-f32-fused.
        if !needs_grad
            && self.tensor_dtype(x1)? == DType::F32
            && self.tensor_dtype(x2)? == DType::F32
            && m > 0
            && batch * p_dim * r_dim > 0
            && (p == f64::INFINITY || (p.is_finite() && p > 0.0))
        {
            let x1_vals = self.tensor_values_lossy_f64(x1)?;
            let x2_vals = self.tensor_values_lossy_f64(x2)?;
            let result_f64 =
                ft_kernel_cpu::cdist_forward_f64(&x1_vals, &x2_vals, batch, p_dim, r_dim, m, p);
            use rayon::prelude::*;
            let result_f32: Vec<f32> = result_f64.par_iter().map(|&v| v as f32).collect();
            let out_shape = if batched {
                vec![batch, p_dim, r_dim]
            } else {
                vec![p_dim, r_dim]
            };
            return self.tensor_variable_f32(result_f32, out_shape, false);
        }

        // Autograd path for finite p > 0 composes through broadcasted
        // sub + abs + pow + sum_dim + pow. p == +inf uses the same
        // broadcasted difference and reduces through tensor_amax so
        // gradients route to the max-distance coordinate. p == 0 stays
        // fail-loud below because the count metric is not differentiable.
        if ((p.is_finite() && p > 0.0) || p == f64::INFINITY) && batch * p_dim * r_dim > 0 {
            let (x1_b, x2_b, expand_target, sum_dim_idx, out_shape) = if batched {
                // x1: [B, P, M], x2: [B, R, M]
                // x1_b: [B, P, 1, M], x2_b: [B, 1, R, M], target: [B, P, R, M]
                let x1_u = self.tensor_unsqueeze(x1, 2)?;
                let x2_u = self.tensor_unsqueeze(x2, 1)?;
                (
                    x1_u,
                    x2_u,
                    vec![batch, p_dim, r_dim, m],
                    3,
                    vec![batch, p_dim, r_dim],
                )
            } else {
                // x1: [P, M], x2: [R, M]
                // x1_b: [P, 1, M], x2_b: [1, R, M], target: [P, R, M]
                let x1_u = self.tensor_unsqueeze(x1, 1)?;
                let x2_u = self.tensor_unsqueeze(x2, 0)?;
                (x1_u, x2_u, vec![p_dim, r_dim, m], 2, vec![p_dim, r_dim])
            };
            let x1_e = self.tensor_expand(x1_b, expand_target.clone())?;
            let x2_e = self.tensor_expand(x2_b, expand_target)?;
            let diff = self.tensor_sub(x1_e, x2_e)?;
            let abs_diff = self.tensor_abs(diff)?;
            if p == f64::INFINITY {
                let result = self.tensor_amax(abs_diff, sum_dim_idx)?;
                return self.tensor_reshape(result, out_shape);
            }
            let pow_diff = self.tensor_pow(abs_diff, p)?;
            let sum = self.tensor_sum_dim(pow_diff, sum_dim_idx)?;
            let result = self.tensor_pow(sum, 1.0 / p)?;
            // Reshape ensures the output shape contract matches the
            // original direct-path output (sum_dim already reduces
            // the right axis; we just need to confirm the shape).
            return self.tensor_reshape(result, out_shape);
        }

        if p == 0.0
            && (self.tensor_tape.tensor_requires_grad(x1)?
                || self.tensor_tape.tensor_requires_grad(x2)?)
        {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "cdist: autograd not supported for p=0 counting metric",
                },
            )));
        }

        // Non-grad fallback path for p == 0, p == inf, or empty output. Lossy
        // reads so f32 inputs are accepted; the result is narrowed back to the
        // shared input dtype below (torch cdist(f32,f32) -> f32). frankentorch-fk5l.
        let x1_vals = self.tensor_values_lossy_f64(x1)?;
        let x2_vals = self.tensor_values_lossy_f64(x2)?;

        let mut result = vec![0.0f64; batch * p_dim * r_dim];

        for b in 0..batch {
            let x1_base = b * p_dim * m;
            let x2_base = b * r_dim * m;
            let out_base = b * p_dim * r_dim;

            for i in 0..p_dim {
                for j in 0..r_dim {
                    let mut dist = 0.0f64;
                    if p == f64::INFINITY {
                        for k in 0..m {
                            let diff =
                                (x1_vals[x1_base + i * m + k] - x2_vals[x2_base + j * m + k]).abs();
                            if diff > dist {
                                dist = diff;
                            }
                        }
                    } else if p == 0.0 {
                        for k in 0..m {
                            let diff =
                                (x1_vals[x1_base + i * m + k] - x2_vals[x2_base + j * m + k]).abs();
                            if diff > f64::EPSILON {
                                dist += 1.0;
                            }
                        }
                    } else {
                        for k in 0..m {
                            let diff =
                                (x1_vals[x1_base + i * m + k] - x2_vals[x2_base + j * m + k]).abs();
                            dist += diff.powf(p);
                        }
                        dist = dist.powf(1.0 / p);
                    }
                    result[out_base + i * r_dim + j] = dist;
                }
            }
        }

        let out_shape = if batched {
            vec![batch, p_dim, r_dim]
        } else {
            vec![p_dim, r_dim]
        };
        let out = self.tensor_variable(result, out_shape, false)?;
        match (self.tensor_dtype(x1)?, self.tensor_dtype(x2)?) {
            (dt @ (DType::F32 | DType::F16 | DType::BF16), other) if other == dt => {
                self.tensor_tape.to_dtype(out, dt)
            }
            _ => Ok(out),
        }
    }

    /// Compute pairwise distance between all pairs of row vectors in a 2-D tensor.
    ///
    /// Equivalent to `torch.nn.functional.pdist(input, p=2)`.
    /// Input: (N, M) tensor. Returns: 1-D tensor of N*(N-1)/2 distances.
    pub fn tensor_pdist(
        &mut self,
        input: TensorNodeId,
        p: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        if shape.len() != 2 {
            // Migrate to InvalidDimension (frankentorch-oitu).
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::InvalidDimension {
                    dim: shape.len(),
                    ndim: 2,
                },
            )));
        }
        Self::validate_nonnegative_norm_order(p, "pdist: p must be in [0, inf]")?;
        let n = shape[0];
        let m = shape[1];
        let out_len = n * (n - 1) / 2;

        // Euclidean (p == 2) fast path — same matmul identity as tensor_cdist
        // (frankentorch-fb6s). The full N×N distance matrix is
        //     d² = ‖x_i‖² + ‖x_j‖² − 2·x_i·x_jᵀ
        // where the cross term is one GEMM-routed `input @ inputᵀ`; the i<j
        // upper triangle is then gathered with a single index_select. This
        // avoids the [out_len, M] pair-difference tensor the broadcasted path
        // builds (out_len = N·(N−1)/2 row pairs × M each). Fully autograd-aware
        // (matmul/sum/clamp/sqrt/index_select record on the tape); for distinct
        // rows the gradient matches the direct path, and equal rows clamp to an
        // exact 0 before sqrt. Matches the direct sum to f64 round-off (~1e-12).
        // No-grad f64 p=2 FUSED fast path (mirrors the cdist p=2 fix): the composed trick below is
        // ~14 tape ops (mul/sum_dim/transpose/matmul/unsqueeze×2/EXPAND×2/add/mul_scalar/sub/clamp/
        // reshape/index_select/sqrt), each materialising [N,N] even no-grad. This does the same trick
        // in one GEMM + a parallel upper-triangle assembly: gram = X·Xᵀ (raw kernel), per-row ‖·‖²,
        // then condensed out = sqrt(max(nx[i]+nx[j]−2·gram[i,j], 0)) for i<j. Same math → bit-exact.
        // frankentorch-cdist-p2-fused.
        if p == 2.0
            && m > 0
            && out_len > 0
            && self.tensor_dtype(input)? == DType::F64
            && !self.tensor_tape.tensor_requires_grad(input)?
            && self.tensor_tape.tensor(input)?.meta().is_contiguous()
        {
            use rayon::prelude::*;
            let vals = self.tensor_values(input)?;
            let xnorm: Vec<f64> = (0..n)
                .map(|i| {
                    let r = &vals[i * m..i * m + m];
                    let mut s = 0.0;
                    for &v in r {
                        s += v * v;
                    }
                    s
                })
                .collect();
            let gram =
                ft_kernel_cpu::matmul_rhs_transposed_contiguous_f64(n, m, n, &vals, &vals)
                    .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?;
            let rows: Vec<Vec<f64>> = (0..n)
                .into_par_iter()
                .map(|i| {
                    let nxi = xnorm[i];
                    let base = i * n;
                    ((i + 1)..n)
                        .map(|j| (nxi + xnorm[j] - 2.0 * gram[base + j]).max(0.0).sqrt())
                        .collect()
                })
                .collect();
            let out: Vec<f64> = rows.into_iter().flatten().collect();
            return self.tensor_variable(out, vec![out_len], false);
        }

        if p == 2.0
            && m > 0
            && out_len > 0
            && self.tensor_dtype(input)? == DType::F32
            && !self.tensor_tape.tensor_requires_grad(input)?
            && self.tensor_tape.tensor(input)?.meta().is_contiguous()
        {
            let vals = self.tensor_values_f32(input)?;
            let xnorm: Vec<f32> = (0..n)
                .map(|i| {
                    let r = &vals[i * m..i * m + m];
                    let mut s = 0.0_f32;
                    for &v in r {
                        s += v * v;
                    }
                    s
                })
                .collect();
            let gram =
                ft_kernel_cpu::matmul_rhs_transposed_contiguous_f32(n, m, n, &vals, &vals)
                    .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?;
            let mut out = Vec::with_capacity(out_len);
            for i in 0..n {
                let nxi = xnorm[i];
                let base = i * n;
                for j in (i + 1)..n {
                    out.push(
                        (nxi + xnorm[j] - 2.0_f32 * gram[base + j])
                            .max(0.0_f32)
                            .sqrt(),
                    );
                }
            }
            return self.tensor_variable_f32(out, vec![out_len], false);
        }

        // Fused p=2 grad path (F64): the compose below materialises FOUR [n,n]
        // intermediates (gram/norm_sum/d2/d2_clamped) + their backward. Instead route
        // through apply_function: forward = the direct parallel pdist kernel; backward
        // computes grad_x[i] = Σ_{j≠i} grad_d[pair(i,j)]·(x[i]-x[j])/d(i,j) PARALLEL over
        // points i (disjoint rows, no [n,n] intermediate, no scatter conflict). pdist is
        // a TOLERANCE op; the analytic per-point backward matches torch within tol.
        // F32 keeps the dtype-preserving compose below. frankentorch-pdist-fused-bwd.
        if p == 2.0 && m > 0 && out_len > 0 && self.tensor_dtype(input)? == DType::F64 {
            let (n_pts, m_dim, olen) = (n, m, out_len);
            return self.tensor_apply_function(
                &[input],
                move |ctx, inputs| {
                    let (xv, _shape) = inputs[0];
                    let dist = ft_kernel_cpu::pdist_forward_f64(xv, n_pts, m_dim, 2.0);
                    ctx.save_for_backward(xv.to_vec(), vec![n_pts, m_dim]);
                    Ok((dist, vec![olen]))
                },
                move |ctx, grad_outputs| {
                    let x = &ctx.saved_tensors()[0];
                    let gd = grad_outputs[0];
                    let mut grad_x = vec![0.0_f64; n_pts * m_dim];
                    // Each point's grad row is an independent sum over its pairs; the
                    // per-point sum order (n = 0..n_pts) is fixed so parallel == serial
                    // bit-for-bit. Distances are recomputed with the same formula the
                    // forward kernel uses.
                    let fill = |mp: usize, row: &mut [f64]| {
                        let mbase = mp * m_dim;
                        for np in 0..n_pts {
                            if np == mp {
                                continue;
                            }
                            let (a, b) = if mp < np { (mp, np) } else { (np, mp) };
                            let k = a * n_pts - a * (a + 1) / 2 + (b - a - 1);
                            let nbase = np * m_dim;
                            let mut d2 = 0.0_f64;
                            for c in 0..m_dim {
                                let diff = x[mbase + c] - x[nbase + c];
                                d2 += diff * diff;
                            }
                            let d = d2.sqrt();
                            if d > 0.0 {
                                let coeff = gd[k] / d;
                                for c in 0..m_dim {
                                    row[c] += coeff * (x[mbase + c] - x[nbase + c]);
                                }
                            }
                        }
                    };
                    if n_pts >= 2 && n_pts * n_pts * m_dim >= PARALLEL_ELEMENTWISE_MIN {
                        use rayon::prelude::*;
                        grad_x
                            .par_chunks_mut(m_dim)
                            .enumerate()
                            .for_each(|(mp, row)| fill(mp, row));
                    } else {
                        grad_x
                            .chunks_mut(m_dim)
                            .enumerate()
                            .for_each(|(mp, row)| fill(mp, row));
                    }
                    Ok(vec![Some(grad_x)])
                },
            );
        }

        if p == 2.0 && m > 0 && out_len > 0 {
            let input_sq = self.tensor_mul(input, input)?;
            let xnorm = self.tensor_sum_dim(input_sq, 1)?; // [N]
            let input_t = self.tensor_transpose(input, 0, 1)?; // [M, N]
            let gram = self.tensor_matmul(input, input_t)?; // [N, N]
            let xnorm_i = self.tensor_unsqueeze(xnorm, 1)?; // [N, 1]
            let xnorm_j = self.tensor_unsqueeze(xnorm, 0)?; // [1, N]
            let target = vec![n, n];
            let xi_e = self.tensor_expand(xnorm_i, target.clone())?;
            let xj_e = self.tensor_expand(xnorm_j, target)?;
            let norm_sum = self.tensor_add(xi_e, xj_e)?;
            let two_gram = self.tensor_mul_scalar(gram, 2.0)?;
            let d2 = self.tensor_sub(norm_sum, two_gram)?;
            let d2_clamped = self.tensor_clamp_min(d2, 0.0)?; // [N, N]
            let d2_flat = self.tensor_reshape(d2_clamped, vec![n * n])?;
            // Gather the strict upper triangle (i < j) at flat index i·N + j,
            // THEN sqrt — so the always-zero diagonal (self-distances) is never
            // square-rooted, avoiding the 0/0 in sqrt's backward.
            #[allow(clippy::cast_precision_loss)]
            let mut tri_idx = Vec::with_capacity(out_len);
            for i in 0..n {
                for j in (i + 1)..n {
                    tri_idx.push((i * n + j) as f64);
                }
            }
            let tri_t = self.tensor_tape.leaf(tri_idx, vec![out_len], false)?;
            let d2_tri = self.tensor_index_select(d2_flat, 0, tri_t)?; // [out_len]
            return self.tensor_sqrt(d2_tri);
        }

        // No-grad fused fast path for finite p>0 (p≠2) or p=+inf. The autograd
        // path below gathers left/right row pairs and materialises the
        // [out_len, M] pair-difference tensor (out_len = N·(N-1)/2) through
        // index_select+sub+abs+pow+sum_dim+pow; with no gradient needed,
        // ft_kernel_cpu::pdist_forward_f64 streams each pair in ONE pass with no
        // O(out_len·M) intermediate. Same per-k order -> bit-exact. (p=2 used the
        // matmul identity above.)
        let needs_grad = self.tensor_tape.tensor_requires_grad(input)?;
        // The fused fast path uses the F64-only pdist_forward_f64 kernel, so gate
        // it to F64 inputs; f32/half inputs fall through to the composed path
        // below, which is dtype-preserving (index_select/sub/abs/pow/sum_dim) and
        // computes in genuine f32 (torch parity) rather than f64-then-narrow.
        // frankentorch-fk5l.
        if !needs_grad
            && self.tensor_dtype(input)? == DType::F64
            && m > 0
            && out_len > 0
            && (p == f64::INFINITY || (p.is_finite() && p > 0.0))
        {
            let vals = self.tensor_values(input)?;
            let result = ft_kernel_cpu::pdist_forward_f64(&vals, n, m, p);
            return self.tensor_variable(result, vec![out_len], false);
        }

        // F32 no-grad fused fast path (sibling of the F64 one; same recipe as the cdist f32
        // fix 72dae1f5). f32 general-p pdist had NO fused path and fell to the composed path
        // below, which MATERIALISES the [out_len, M] pair-difference (out_len = N·(N-1)/2 ~
        // 1.6GB at N=2000, M=200). The input ([N,M]) is tiny, so upcast it to f64, run the
        // same parallel `pdist_forward_f64` kernel (no O(out_len·M) intermediate), then narrow
        // the distances to f32. pdist is a TOLERANCE op (approx golden vs torch; powf is
        // libm-vs-SLEEF) and f64 distances narrowed to f32 are AT LEAST as accurate as torch's
        // own f32 path -> within tol; output stays f32 (torch parity). frankentorch-cdist-f32-fused.
        if !needs_grad
            && self.tensor_dtype(input)? == DType::F32
            && m > 0
            && out_len > 0
            && (p == f64::INFINITY || (p.is_finite() && p > 0.0))
        {
            let vals = self.tensor_values_lossy_f64(input)?;
            let result = ft_kernel_cpu::pdist_forward_f64(&vals, n, m, p);
            use rayon::prelude::*;
            let out: Vec<f32> = result.par_iter().map(|&v| v as f32).collect();
            return self.tensor_variable_f32(out, vec![out_len], false);
        }

        // For finite p > 0, compose through index_select + sub + abs +
        // pow + sum_dim + pow primitives so gradients flow to the
        // input. PyTorch's torch.nn.functional.pdist IS differentiable
        // for finite p > 0 (sub-gradient at the abs corner). p == +inf
        // uses the same row-pair diff and tensor_amax for max-routing
        // gradients. p == 0 (counting metric) remains fail-loud below.
        // Tracked under frankentorch-0i8u and frankentorch-hzc6.
        if ((p.is_finite() && p > 0.0) || p == f64::INFINITY) && out_len > 0 {
            // Build row_i and row_j index tensors of length out_len.
            #[allow(clippy::cast_precision_loss)]
            let mut row_i_idx = Vec::with_capacity(out_len);
            #[allow(clippy::cast_precision_loss)]
            let mut row_j_idx = Vec::with_capacity(out_len);
            for i in 0..n {
                for j in (i + 1)..n {
                    row_i_idx.push(i as f64);
                    row_j_idx.push(j as f64);
                }
            }
            let row_i_t = self.tensor_tape.leaf(row_i_idx, vec![out_len], false)?;
            let row_j_t = self.tensor_tape.leaf(row_j_idx, vec![out_len], false)?;
            let left = self.tensor_index_select(input, 0, row_i_t)?;
            let right = self.tensor_index_select(input, 0, row_j_t)?;
            let diff = self.tensor_sub(left, right)?;
            let abs_diff = self.tensor_abs(diff)?;
            if p == f64::INFINITY {
                return self.tensor_amax(abs_diff, 1);
            }
            let pow_diff = self.tensor_pow(abs_diff, p)?;
            let sum = self.tensor_sum_dim(pow_diff, 1)?; // [out_len]
            return self.tensor_pow(sum, 1.0 / p);
        }

        if p == 0.0 && self.tensor_tape.tensor_requires_grad(input)? {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "pdist: autograd not supported for p=0 counting metric",
                },
            )));
        }

        // Non-grad paths for p == 0, p == inf, or empty output —
        // fall back to the original direct computation. Lossy read so f32 inputs
        // are accepted; the result is narrowed back to the input dtype below
        // (torch pdist(f32) -> f32). frankentorch-fk5l.
        let vals = self.tensor_values_lossy_f64(input)?;
        let mut result = Vec::with_capacity(out_len);
        for i in 0..n {
            for j in (i + 1)..n {
                let mut dist = 0.0f64;
                if p == f64::INFINITY {
                    for k in 0..m {
                        let diff = (vals[i * m + k] - vals[j * m + k]).abs();
                        if diff > dist {
                            dist = diff;
                        }
                    }
                } else if p == 0.0 {
                    for k in 0..m {
                        let diff = (vals[i * m + k] - vals[j * m + k]).abs();
                        if diff > f64::EPSILON {
                            dist += 1.0;
                        }
                    }
                } else {
                    for k in 0..m {
                        let diff = (vals[i * m + k] - vals[j * m + k]).abs();
                        dist += diff.powf(p);
                    }
                    dist = dist.powf(1.0 / p);
                }
                result.push(dist);
            }
        }

        let out = self.tensor_variable(result, vec![out_len], false)?;
        match self.tensor_dtype(input)? {
            dt @ (DType::F32 | DType::F16 | DType::BF16) => self.tensor_tape.to_dtype(out, dt),
            _ => Ok(out),
        }
    }

    /// Convert class indices to one-hot encoded tensors.
    ///
    /// Equivalent to `torch.nn.functional.one_hot(input, num_classes)`.
    /// Input is an integer-index tensor of ANY shape (including a 0-D scalar);
    /// every index must be in `[0, num_classes)`. The output appends a trailing
    /// `num_classes` dimension: input shape `[*]` -> output `[*, num_classes]`
    /// (matching torch). A 1-D input of length `n` yields `[n, num_classes]`.
    pub fn tensor_one_hot(
        &mut self,
        input: TensorNodeId,
        num_classes: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        let numel: usize = shape.iter().product();
        // Lossy read so f32/f16/bf16 index tensors work (`tensor_values` is F64-only and
        // ERRORED UnsupportedDType(F32) on non-f64 labels — a latent crash for every caller
        // that one-hots f32 labels, e.g. multi_margin/arcface/cosface losses). Indices are
        // integers so the f64 read is exact; the output is a dtype-independent 0/1 mask
        // (F64, as before) so this is bit-identical for f64 input. frankentorch-fk5l.
        let values = self.tensor_values_lossy_f64(input)?;
        // Validate + resolve class indices in a cheap serial pre-pass (reads only the small input,
        // no big-output page faults), THEN scatter the 1.0s in PARALLEL over output rows. The old
        // single serial scatter over the [numel, num_classes] output zero-faulted every touched
        // page on ONE thread (the wall for large numel·num_classes); fanning the per-row writes
        // across rayon parallelizes that faulting. Bit-identical (disjoint one-hot positions).
        let mut class_idx: Vec<usize> = Vec::with_capacity(numel);
        for &idx in &values {
            if idx < 0.0 {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "one_hot: class index must be non-negative",
                    },
                )));
            }
            #[allow(clippy::cast_possible_truncation, clippy::cast_sign_loss)]
            let ci = idx as usize;
            if ci >= num_classes {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "one_hot: class index out of range",
                    },
                )));
            }
            class_idx.push(ci);
        }
        let mut result = vec![0.0_f64; numel * num_classes];
        if numel * num_classes >= PARALLEL_ELEMENTWISE_MIN && numel > 1 && num_classes > 0 {
            use rayon::prelude::*;
            result
                .par_chunks_mut(num_classes)
                .zip(class_idx.par_iter())
                .for_each(|(row, &ci)| {
                    row[ci] = 1.0;
                });
        } else {
            for (i, &ci) in class_idx.iter().enumerate() {
                result[i * num_classes + ci] = 1.0;
            }
        }
        let mut out_shape = shape;
        out_shape.push(num_classes);
        self.tensor_variable(result, out_shape, false)
    }

    /// Look up embeddings from a weight matrix.
    ///
    /// Equivalent to `torch.nn.functional.embedding(input, weight, padding_idx)`.
    /// Returns embeddings for each index in input.
    ///
    /// - `input`: Indices into the embedding table, any shape
    /// - `weight`: Embedding weight matrix, shape (num_embeddings, embedding_dim)
    /// - `padding_idx`: If set, entries at this index are zeroed
    pub fn tensor_embedding(
        &mut self,
        input: TensorNodeId,
        weight: TensorNodeId,
        padding_idx: Option<usize>,
    ) -> Result<TensorNodeId, AutogradError> {
        let input_shape = self.tensor_shape(input)?;
        let weight_shape = self.tensor_shape(weight)?;
        if weight_shape.len() != 2 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "embedding: weight must be 2D (num_embeddings, embedding_dim)",
                },
            )));
        }
        let num_embeddings = weight_shape[0];
        let embedding_dim = weight_shape[1];
        let input_vals = self.tensor_values(input)?;
        let num_indices: usize = input_shape.iter().product();
        // Resolve + bounds-check the (non-differentiable) lookup indices.
        let mut idx_usize: Vec<usize> = Vec::with_capacity(num_indices);
        for &v in &input_vals {
            let idx = v as usize;
            if idx >= num_embeddings {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "embedding: index out of range",
                    },
                )));
            }
            idx_usize.push(idx);
        }
        let mut out_shape = input_shape;
        out_shape.push(embedding_dim);

        if self.tensor_requires_grad(weight)? {
            // Embedding lookup is differentiable w.r.t. `weight`: the gradient
            // scatter-adds the upstream gradient back to each looked-up row
            // (accumulating for repeated indices; padding rows get none). The
            // indices are non-differentiable. The forward gathers the same rows,
            // so the value is bit-identical; the previous body rebuilt a
            // requires_grad=false leaf, silently severing the embedding gradient.
            let pad = padding_idx;
            let dim = embedding_dim;
            let ne = num_embeddings;
            let idx_fwd = idx_usize.clone();
            let out_shape_fwd = out_shape.clone();
            return self.tensor_apply_function(
                &[weight],
                move |ctx, inputs| {
                    let (wv, _wshape) = inputs[0];
                    // Each output row is an independent weight-row copy (or zeros for padding) →
                    // pre-alloc + parallel per-row copy_from_slice. Parallelizes both the gather and
                    // its page-faulting. Bit-identical to the serial extend (disjoint rows).
                    let mut result = vec![0.0_f64; idx_fwd.len() * dim];
                    let fill = |k: usize, row: &mut [f64]| {
                        let idx = idx_fwd[k];
                        if pad != Some(idx) {
                            let start = idx * dim;
                            row.copy_from_slice(&wv[start..start + dim]);
                        }
                    };
                    if dim > 0 {
                        if idx_fwd.len() * dim >= PARALLEL_ELEMENTWISE_MIN && idx_fwd.len() > 1 {
                            use rayon::prelude::*;
                            result
                                .par_chunks_mut(dim)
                                .enumerate()
                                .for_each(|(k, row)| fill(k, row));
                        } else {
                            for (k, row) in result.chunks_mut(dim).enumerate() {
                                fill(k, row);
                            }
                        }
                    }
                    let idx_f: Vec<f64> = idx_fwd.iter().map(|&i| i as f64).collect();
                    ctx.save_for_backward(idx_f, vec![idx_fwd.len()]);
                    Ok((result, out_shape_fwd.clone()))
                },
                move |ctx, grad_outputs| {
                    let saved = &ctx.saved_tensors()[0];
                    let g = grad_outputs[0];
                    let mut grad_w = vec![0.0_f64; ne * dim];
                    for (k, &idxf) in saved.iter().enumerate() {
                        let idx = idxf as usize;
                        if pad == Some(idx) {
                            continue;
                        }
                        for d in 0..dim {
                            grad_w[idx * dim + d] += g[k * dim + d];
                        }
                    }
                    Ok(vec![Some(grad_w)])
                },
            );
        }

        // f32 no-grad fast path (correctness bug + asymmetric-dtype): the f64 path below reads the
        // weight via `tensor_values`, which requires F64 storage and ERRORS (UnsupportedDType(F32))
        // for an f32 weight — so no-grad f32 embedding was broken, not merely slow. Gather f32 rows
        // DIRECTLY: fixes the crash, returns the correct F32 dtype (torch.embedding keeps f32), and
        // halves the gather bandwidth with bit-identical row copies. Non-contiguous falls through.
        if !self.tensor_requires_grad(weight)? && self.tensor_dtype(weight)? == DType::F32 {
            let built: Option<Vec<f32>> = {
                let wt = self.tensor_tape.tensor(weight)?;
                if wt.meta().is_contiguous() {
                    let weight_f32 = wt.contiguous_values_f32()?;
                    let mut result = vec![0.0_f32; num_indices * embedding_dim];
                    if embedding_dim > 0 && num_indices > 0 {
                        let fill = |i: usize, row: &mut [f32]| {
                            let idx = idx_usize[i];
                            if padding_idx != Some(idx) {
                                let start = idx * embedding_dim;
                                row.copy_from_slice(&weight_f32[start..start + embedding_dim]);
                            }
                        };
                        if num_indices * embedding_dim >= PARALLEL_ELEMENTWISE_MIN
                            && num_indices > 1
                        {
                            use rayon::prelude::*;
                            result
                                .par_chunks_mut(embedding_dim)
                                .enumerate()
                                .for_each(|(i, row)| fill(i, row));
                        } else {
                            for (i, row) in result.chunks_mut(embedding_dim).enumerate() {
                                fill(i, row);
                            }
                        }
                    }
                    Some(result)
                } else {
                    None
                }
            };
            if let Some(result) = built {
                return self.tensor_variable_f32(result, out_shape, false);
            }
        }

        // No-grad gather. For a contiguous F64 weight, BORROW the table instead of cloning it via
        // tensor_values — that clone materializes the whole [num_embeddings, embedding_dim] table per
        // forward, a large dead copy when few of many rows are looked up (same gap the f32 fast path
        // above fixed, and embedding_bag). Non-contiguous / non-F64 falls back to the tensor_values
        // clone. Each output row is an independent weight-row copy (or zeros for padding) → pre-alloc
        // + parallel per-row copy_from_slice. Bit-identical to the clone path (disjoint rows).
        let weight_contiguous_f64 = self.tensor_dtype(weight)? == DType::F64
            && self.tensor_tape.tensor(weight)?.meta().is_contiguous();
        let weight_owned: Vec<f64>;
        let weight_vals: &[f64] = if weight_contiguous_f64 {
            self.tensor_tape.tensor(weight)?.contiguous_values()?
        } else {
            weight_owned = self.tensor_values(weight)?;
            &weight_owned
        };
        let mut result = vec![0.0_f64; num_indices * embedding_dim];
        if embedding_dim > 0 && num_indices > 0 {
            let fill = |i: usize, row: &mut [f64]| {
                let idx = idx_usize[i];
                if padding_idx != Some(idx) {
                    let start = idx * embedding_dim;
                    row.copy_from_slice(&weight_vals[start..start + embedding_dim]);
                }
            };
            if num_indices * embedding_dim >= PARALLEL_ELEMENTWISE_MIN && num_indices > 1 {
                use rayon::prelude::*;
                result
                    .par_chunks_mut(embedding_dim)
                    .enumerate()
                    .for_each(|(i, row)| fill(i, row));
            } else {
                for (i, row) in result.chunks_mut(embedding_dim).enumerate() {
                    fill(i, row);
                }
            }
        }
        self.tensor_variable(result, out_shape, false)
    }

    /// Compute sums or means of embedding bags.
    ///
    /// Equivalent to `torch.nn.functional.embedding_bag(input, weight, offsets, mode)`.
    /// Groups embeddings by offsets and reduces each group.
    ///
    /// - `input`: 1D tensor of indices
    /// - `weight`: Embedding weight matrix, shape (num_embeddings, embedding_dim)
    /// - `offsets`: 1D tensor of starting indices for each bag
    /// - `mode`: "sum", "mean", or "max"
    pub fn tensor_embedding_bag(
        &mut self,
        input: TensorNodeId,
        weight: TensorNodeId,
        offsets: TensorNodeId,
        mode: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        let input_shape = self.tensor_shape(input)?;
        let weight_shape = self.tensor_shape(weight)?;
        let offsets_shape = self.tensor_shape(offsets)?;
        if input_shape.len() != 1 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "embedding_bag: input must be 1D",
                },
            )));
        }
        if weight_shape.len() != 2 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "embedding_bag: weight must be 2D",
                },
            )));
        }
        if offsets_shape.len() != 1 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "embedding_bag: offsets must be 1D",
                },
            )));
        }
        let num_embeddings = weight_shape[0];
        let embedding_dim = weight_shape[1];
        let num_bags = offsets_shape[0];
        match mode {
            "sum" | "mean" | "max" => {}
            _ => {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "embedding_bag: mode must be 'sum', 'mean', or 'max'",
                    },
                )));
            }
        }
        let input_vals = self.tensor_values(input)?;
        let offsets_vals = self.tensor_values(offsets)?;
        let input_len = input_vals.len();

        // No-grad f32 fast path (asymmetric-dtype bandwidth): the grad path routes `weight`
        // through apply_function, which UPCASTS the entire f32 table to f64 (read 25MB + write
        // 51MB) before gathering — pure overhead for the common inference case. Gather + reduce
        // f32 rows DIRECTLY (read the table once as f32, no upcast), reduce natively in f32 to
        // match torch's f32 embedding_bag, and return the correct F32 dtype. Same per-bag math,
        // tie-break, and out-of-range check as the f64 closure. Non-contiguous / grad / non-f32
        // weight falls through to the f64 apply_function path unchanged.
        if !self.tensor_requires_grad(weight)?
            && self.tensor_dtype(weight)? == DType::F32
            && self.tensor_tape.tensor(weight)?.meta().is_contiguous()
        {
            let weight_f32 = self.tensor_tape.tensor(weight)?.contiguous_values_f32()?;
            let one_bag_f32 = |b: usize| -> Result<Vec<f32>, AutogradError> {
                let start = offsets_vals[b] as usize;
                let end = if b + 1 < num_bags {
                    offsets_vals[b + 1] as usize
                } else {
                    input_len
                };
                let bag_size = end.saturating_sub(start);
                let mut agg = vec![0.0_f32; embedding_dim];
                for (i, &input_val) in input_vals
                    .iter()
                    .enumerate()
                    .take(end.min(input_len))
                    .skip(start)
                {
                    let idx = input_val as usize;
                    if idx >= num_embeddings {
                        return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                            ft_dispatch::DispatchKeyError::IncompatibleSet {
                                reason: "embedding_bag: index out of range",
                            },
                        )));
                    }
                    let emb_start = idx * embedding_dim;
                    for j in 0..embedding_dim {
                        let val = weight_f32[emb_start + j];
                        match mode {
                            "sum" | "mean" => agg[j] += val,
                            "max" => {
                                if i == start || val > agg[j] {
                                    agg[j] = val;
                                }
                            }
                            _ => {}
                        }
                    }
                }
                if mode == "mean" && bag_size > 0 {
                    let inv = bag_size as f32;
                    for v in &mut agg {
                        *v /= inv;
                    }
                }
                Ok(agg)
            };
            let result: Vec<f32> = if num_bags >= 2 && input_len >= PARALLEL_ELEMENTWISE_MIN {
                use rayon::prelude::*;
                let bags: Result<Vec<Vec<f32>>, AutogradError> =
                    (0..num_bags).into_par_iter().map(one_bag_f32).collect();
                bags?.into_iter().flatten().collect()
            } else {
                let mut result = Vec::with_capacity(num_bags * embedding_dim);
                for b in 0..num_bags {
                    result.extend(one_bag_f32(b)?);
                }
                result
            };
            return self.tensor_variable_f32(result, vec![num_bags, embedding_dim], false);
        }

        // Route through apply_function so the gradient reaches `weight` (input
        // indices and offsets are integer/non-differentiable). sum/mean
        // scatter-add grad_out back to each looked-up row (mean scaled by
        // 1/bag_size); max routes grad only to the argmax row per column.
        let mode_owned = mode.to_string();
        let mode_for_backward = mode.to_string();
        let input_for_backward = input_vals.clone();
        let offsets_for_backward = offsets_vals.clone();
        self.tensor_apply_function(
            &[weight],
            move |ctx, inputs| {
                let (weight_vals, _shape) = inputs[0];
                // Each bag independently gathers + reduces its slice of indices into a
                // disjoint output row, in index order — so distribute the bags across
                // the rayon pool: within-bag accumulation order is preserved and bags
                // never share output, so the result is bit-identical to the serial
                // loop. The per-item gather + embedding_dim adds carry enough work to
                // beat dispatch. frankentorch-kgs4.101.
                let one_bag = |b: usize| -> Result<Vec<f64>, AutogradError> {
                    let start = offsets_vals[b] as usize;
                    let end = if b + 1 < num_bags {
                        offsets_vals[b + 1] as usize
                    } else {
                        input_len
                    };
                    let bag_size = end.saturating_sub(start);
                    let mut agg = vec![0.0_f64; embedding_dim];
                    for (i, &input_val) in input_vals
                        .iter()
                        .enumerate()
                        .take(end.min(input_len))
                        .skip(start)
                    {
                        let idx = input_val as usize;
                        if idx >= num_embeddings {
                            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                                ft_dispatch::DispatchKeyError::IncompatibleSet {
                                    reason: "embedding_bag: index out of range",
                                },
                            )));
                        }
                        let emb_start = idx * embedding_dim;
                        for j in 0..embedding_dim {
                            let val = weight_vals[emb_start + j];
                            match mode_owned.as_str() {
                                "sum" | "mean" => agg[j] += val,
                                "max" => {
                                    if i == start || val > agg[j] {
                                        agg[j] = val;
                                    }
                                }
                                _ => {}
                            }
                        }
                    }
                    if mode_owned == "mean" && bag_size > 0 {
                        for v in &mut agg {
                            *v /= bag_size as f64;
                        }
                    }
                    Ok(agg)
                };
                let result: Vec<f64> = if num_bags >= 2 && input_len >= PARALLEL_ELEMENTWISE_MIN {
                    use rayon::prelude::*;
                    let bags: Result<Vec<Vec<f64>>, AutogradError> =
                        (0..num_bags).into_par_iter().map(one_bag).collect();
                    bags?.into_iter().flatten().collect()
                } else {
                    let mut result = Vec::with_capacity(num_bags * embedding_dim);
                    for b in 0..num_bags {
                        result.extend(one_bag(b)?);
                    }
                    result
                };
                // Only "max" backward needs the weight values (to recompute the per-column
                // argmax); "sum"/"mean" backward uses only indices/offsets/grad. Saving the
                // full [num_embeddings, embedding_dim] weight unconditionally was a dead clone
                // of the whole embedding table per forward for the common sum/mean modes.
                if mode_owned == "max" {
                    ctx.save_for_backward(
                        weight_vals.to_vec(),
                        vec![num_embeddings, embedding_dim],
                    );
                }
                Ok((result, vec![num_bags, embedding_dim]))
            },
            move |ctx, grad_outputs| {
                let g = grad_outputs[0];
                let saved = ctx.saved_tensors();
                let mut grad_weight = vec![0.0_f64; num_embeddings * embedding_dim];
                for b in 0..num_bags {
                    let start = offsets_for_backward[b] as usize;
                    let end = if b + 1 < num_bags {
                        offsets_for_backward[b + 1] as usize
                    } else {
                        input_len
                    };
                    let bag_size = end.saturating_sub(start);
                    let go = &g[b * embedding_dim..b * embedding_dim + embedding_dim];
                    match mode_for_backward.as_str() {
                        "sum" => {
                            for &input_val in input_for_backward
                                .iter()
                                .take(end.min(input_len))
                                .skip(start)
                            {
                                let idx = input_val as usize;
                                for j in 0..embedding_dim {
                                    grad_weight[idx * embedding_dim + j] += go[j];
                                }
                            }
                        }
                        "mean" => {
                            if bag_size > 0 {
                                let inv = 1.0 / bag_size as f64;
                                for &input_val in input_for_backward
                                    .iter()
                                    .take(end.min(input_len))
                                    .skip(start)
                                {
                                    let idx = input_val as usize;
                                    for j in 0..embedding_dim {
                                        grad_weight[idx * embedding_dim + j] += go[j] * inv;
                                    }
                                }
                            }
                        }
                        "max" => {
                            // Recompute argmax per column with the forward tie-break
                            // (first element initializes, strict `>` updates -> earliest max wins).
                            // weight_vals was saved only for this mode (see forward).
                            let weight_vals = &saved[0];
                            for j in 0..embedding_dim {
                                let mut best_idx: Option<usize> = None;
                                let mut best_val = 0.0_f64;
                                for (i, &input_val) in input_for_backward
                                    .iter()
                                    .enumerate()
                                    .take(end.min(input_len))
                                    .skip(start)
                                {
                                    let idx = input_val as usize;
                                    let val = weight_vals[idx * embedding_dim + j];
                                    if i == start || val > best_val {
                                        best_val = val;
                                        best_idx = Some(idx);
                                    }
                                }
                                if let Some(idx) = best_idx {
                                    grad_weight[idx * embedding_dim + j] += go[j];
                                }
                            }
                        }
                        _ => {}
                    }
                }
                Ok(vec![Some(grad_weight)])
            },
        )
    }

    /// Compute cosine similarity between tensors along a dimension.
    ///
    /// Equivalent to `torch.nn.functional.cosine_similarity(x1, x2, dim, eps)`.
    /// Returns cos(angle) = (x1 · x2) / (||x1|| * ||x2||).
    pub fn tensor_cosine_similarity(
        &mut self,
        x1: TensorNodeId,
        x2: TensorNodeId,
        dim: usize,
        eps: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape1 = self.tensor_shape(x1)?;
        let shape2 = self.tensor_shape(x2)?;
        if shape1 != shape2 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: shape1,
                    rhs: shape2,
                },
            )));
        }
        // Native-f32 no-grad fast path. The composed path below routes through tensor_sum_dim,
        // which UPCASTS f32->F64 (so f32 cosine_similarity returned F64 — wrong dtype, torch->f32 —
        // and paid 2x memory). For a contiguous f32 pair reducing over the LAST dim with grad off,
        // compute dot / ||x1|| / ||x2|| per row in f32 (one parallel pass over rows), output F32.
        // denom = max(n1*n2, eps) matching the composed tensor_maximum. Other dims / grad / non-
        // contiguous / non-f32 fall through.
        if !self.tensor_requires_grad(x1)?
            && !self.tensor_requires_grad(x2)?
            && self.tensor_dtype(x1)? == DType::F32
            && self.tensor_dtype(x2)? == DType::F32
            && !shape1.is_empty()
            && dim == shape1.len() - 1
        {
            let d = shape1[dim];
            #[allow(clippy::cast_possible_truncation)]
            let epsf = eps as f32;
            let built = {
                let a = self.tensor_tape.tensor(x1)?;
                let b = self.tensor_tape.tensor(x2)?;
                if a.meta().is_contiguous() && b.meta().is_contiguous() && d > 0 {
                    let av = a.contiguous_values_f32()?;
                    let bv = b.contiguous_values_f32()?;
                    let outer = av.len() / d;
                    use rayon::prelude::*;
                    let out: Vec<f32> = (0..outer)
                        .into_par_iter()
                        .map(|r| {
                            let row1 = &av[r * d..r * d + d];
                            let row2 = &bv[r * d..r * d + d];
                            let mut dot = 0.0f32;
                            let mut s1 = 0.0f32;
                            let mut s2 = 0.0f32;
                            for k in 0..d {
                                dot += row1[k] * row2[k];
                                s1 += row1[k] * row1[k];
                                s2 += row2[k] * row2[k];
                            }
                            let denom = (s1.sqrt() * s2.sqrt()).max(epsf);
                            dot / denom
                        })
                        .collect();
                    Some(out)
                } else {
                    None
                }
            };
            if let Some(out) = built {
                let out_shape: Vec<usize> = shape1[..dim].to_vec();
                let out_shape = if out_shape.is_empty() {
                    vec![1]
                } else {
                    out_shape
                };
                return self.tensor_variable_f32(out, out_shape, false);
            }
        }
        // Native-f64 no-grad fast path (asymmetric-dtype mirror of the f32 path above): the compose
        // below is ~10 tape ops (3 mul + 3 sum_dim + 2 sqrt + mul + full + max + div), materializing
        // three full-size products then reducing each. For a contiguous f64 pair reducing over the
        // LAST dim with grad off, compute dot/‖x1‖/‖x2‖ per row in ONE parallel pass. BIT-EXACT to the
        // compose: `dot`/`s1`/`s2` reduce the SAME materialized product lane through the SAME
        // `pairwise_sum_f64` that `sum_dim` uses (a per-thread scratch holds the product row), sqrt is
        // the identical IEEE `.sqrt()`, and `denom` replicates `tensor_maximum(norm_prod, eps)`
        // (NaN-propagating). Other dims / grad / non-contiguous fall through. frankentorch-cossim-f64.
        if !self.tensor_requires_grad(x1)?
            && !self.tensor_requires_grad(x2)?
            && self.tensor_dtype(x1)? == DType::F64
            && self.tensor_dtype(x2)? == DType::F64
            && !shape1.is_empty()
            && dim == shape1.len() - 1
        {
            let d = shape1[dim];
            let built = {
                let a = self.tensor_tape.tensor(x1)?;
                let b = self.tensor_tape.tensor(x2)?;
                if a.meta().is_contiguous() && b.meta().is_contiguous() && d > 0 {
                    let av = a.contiguous_values()?;
                    let bv = b.contiguous_values()?;
                    let outer = av.len() / d;
                    use rayon::prelude::*;
                    let out: Vec<f64> = (0..outer)
                        .into_par_iter()
                        .map_init(
                            || vec![0.0_f64; d],
                            |scratch, r| {
                                let row1 = &av[r * d..r * d + d];
                                let row2 = &bv[r * d..r * d + d];
                                // dot = pairwise_sum(x1*x2) == sum_dim(mul(x1,x2)).
                                for k in 0..d {
                                    scratch[k] = row1[k] * row2[k];
                                }
                                let dot = ft_kernel_cpu::pairwise_sum_f64(scratch);
                                for k in 0..d {
                                    scratch[k] = row1[k] * row1[k];
                                }
                                let s1 = ft_kernel_cpu::pairwise_sum_f64(scratch);
                                for k in 0..d {
                                    scratch[k] = row2[k] * row2[k];
                                }
                                let s2 = ft_kernel_cpu::pairwise_sum_f64(scratch);
                                let norm_prod = s1.sqrt() * s2.sqrt();
                                let denom = if norm_prod.is_nan() || eps.is_nan() {
                                    f64::NAN
                                } else {
                                    norm_prod.max(eps)
                                };
                                dot / denom
                            },
                        )
                        .collect();
                    Some(out)
                } else {
                    None
                }
            };
            if let Some(out) = built {
                let out_shape: Vec<usize> = shape1[..dim].to_vec();
                let out_shape = if out_shape.is_empty() {
                    vec![1]
                } else {
                    out_shape
                };
                return self.tensor_variable(out, out_shape, false);
            }
        }
        // dot = sum(x1 * x2, dim)
        let prod = self.tensor_mul(x1, x2)?;
        let dot = self.tensor_sum_dim(prod, dim)?;
        // norm1 = sqrt(sum(x1^2, dim))
        let x1_sq = self.tensor_mul(x1, x1)?;
        let norm1_sq = self.tensor_sum_dim(x1_sq, dim)?;
        let norm1 = self.tensor_sqrt(norm1_sq)?;
        // norm2 = sqrt(sum(x2^2, dim))
        let x2_sq = self.tensor_mul(x2, x2)?;
        let norm2_sq = self.tensor_sum_dim(x2_sq, dim)?;
        let norm2 = self.tensor_sqrt(norm2_sq)?;
        // denom = max(norm1 * norm2, eps)
        let norm_prod = self.tensor_mul(norm1, norm2)?;
        let eps_shape = self.tensor_shape(norm_prod)?;
        let eps_t = self.full(eps_shape, eps, false)?;
        let denom = self.tensor_maximum(norm_prod, eps_t)?;
        self.tensor_div(dot, denom)
    }

    /// Pairwise distance between two tensors.
    ///
    /// Equivalent to `torch.nn.functional.pairwise_distance(x1, x2, p, eps)`.
    /// Computes ||x1 - x2||_p along the last dimension.
    pub fn tensor_pairwise_distance(
        &mut self,
        x1: TensorNodeId,
        x2: TensorNodeId,
        p: f64,
        eps: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape1 = self.tensor_shape(x1)?;
        let shape2 = self.tensor_shape(x2)?;
        if shape1 != shape2 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: shape1,
                    rhs: shape2,
                },
            )));
        }
        let ndim = shape1.len();
        let last_dim = if ndim > 0 { ndim - 1 } else { 0 };

        // torch.nn.functional.pairwise_distance computes norm(x1 - x2 + eps, p, dim=-1):
        // the eps is added INSIDE the difference, BEFORE the p-norm (matching the ft-nn
        // `PairwiseDistance` module's distance_from_diff). The old composed path here added
        // eps AFTER the norm (a divergence vs torch), routed p=2 through `tensor_norm_dim`'s
        // libm `powf` (~10x a multiply), and built a full-size F64 const (so f32 input
        // returned F64 — wrong dtype, torch->f32). No-grad fused fast path: one parallel
        // pass per reduced row computing (sum |x1-x2+eps|^p)^(1/p) directly in the input
        // dtype. Grad / non-contiguous / mixed-dtype fall through. frankentorch-pwdist-fused.
        if ndim > 0
            && shape1[last_dim] > 0
            && !self.tensor_requires_grad(x1)?
            && !self.tensor_requires_grad(x2)?
        {
            let dim_size = shape1[last_dim];
            let outer: usize = shape1[..last_dim].iter().product();
            let p2 = p == 2.0;
            let dt = self.tensor_dtype(x1)?;
            let mut out_shape: Vec<usize> = shape1[..last_dim].to_vec();
            if out_shape.is_empty() {
                out_shape.push(1);
            }
            if dt == DType::F32 && self.tensor_dtype(x2)? == DType::F32 {
                #[allow(clippy::cast_possible_truncation)]
                let epsf = eps as f32;
                #[allow(clippy::cast_possible_truncation)]
                let pf = p as f32;
                let built = {
                    let a = self.tensor_tape.tensor(x1)?;
                    let b = self.tensor_tape.tensor(x2)?;
                    if a.meta().is_contiguous() && b.meta().is_contiguous() {
                        let av = a.contiguous_values_f32()?;
                        let bv = b.contiguous_values_f32()?;
                        use rayon::prelude::*;
                        let out: Vec<f32> = (0..outer)
                            .into_par_iter()
                            .map(|r| {
                                let base = r * dim_size;
                                let mut acc = 0.0f32;
                                for k in 0..dim_size {
                                    let d = av[base + k] - bv[base + k] + epsf;
                                    acc += if p2 { d * d } else { d.abs().powf(pf) };
                                }
                                if p2 { acc.sqrt() } else { acc.powf(1.0 / pf) }
                            })
                            .collect();
                        Some(out)
                    } else {
                        None
                    }
                };
                if let Some(out) = built {
                    return self.tensor_variable_f32(out, out_shape, false);
                }
            } else if dt == DType::F64 && self.tensor_dtype(x2)? == DType::F64 {
                let built = {
                    let a = self.tensor_tape.tensor(x1)?;
                    let b = self.tensor_tape.tensor(x2)?;
                    if a.meta().is_contiguous() && b.meta().is_contiguous() {
                        let av = a.contiguous_values()?;
                        let bv = b.contiguous_values()?;
                        use rayon::prelude::*;
                        let out: Vec<f64> = (0..outer)
                            .into_par_iter()
                            .map(|r| {
                                let base = r * dim_size;
                                let mut acc = 0.0f64;
                                for k in 0..dim_size {
                                    let d = av[base + k] - bv[base + k] + eps;
                                    acc += if p2 { d * d } else { d.abs().powf(p) };
                                }
                                if p2 { acc.sqrt() } else { acc.powf(1.0 / p) }
                            })
                            .collect();
                        Some(out)
                    } else {
                        None
                    }
                };
                if let Some(out) = built {
                    return self.tensor_variable(out, out_shape, false);
                }
            }
        }

        // Composed fallback (grad path / non-contiguous / mixed dtype): eps-inside to match
        // torch (norm(x1 - x2 + eps, p, -1)); full_like preserves the input float dtype.
        let diff = self.tensor_sub(x1, x2)?;
        let shifted = if eps == 0.0 {
            diff
        } else {
            let eps_t = self.full_like(diff, eps, false)?;
            self.tensor_add(diff, eps_t)?
        };
        self.tensor_norm_dim(shifted, p, last_dim)
    }

    /// Normalize a tensor along a dimension using Lp norm.
    ///
    /// Equivalent to `torch.nn.functional.normalize(input, p, dim, eps)`.
    /// Returns input / max(||input||_p, eps) along the specified dimension.
    pub fn tensor_normalize(
        &mut self,
        input: TensorNodeId,
        p: f64,
        dim: usize,
        eps: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        // norm = ||input||_p along dim
        let input_shape = self.tensor_shape(input)?;

        // No-grad f64 fast path: compute the per-slice L_p norm INLINE and divide each slice in
        // place by max(norm, eps) in one fused parallel pass. The composed path (a) used
        // `tensor_norm_dim`, which for p=2 takes |x|^p via libm `powf` (~10x a multiply), and (b)
        // materialised a full-size `tensor_expand` of the denom (numel copy) before dividing —
        // together the 8.44x wall. For p=2 the norm is `sqrt(sum x*x)` (x*x, the torch-correct fast
        // norm that `cosine_similarity` already uses and PyTorch's normalize uses); general p falls
        // back to powf. Same value as the x*x norm + division. frankentorch-normalize-fused.
        if dim < input_shape.len()
            && self.tensor_dtype(input)? == DType::F64
            && !self.tensor_requires_grad(input)?
            && self.tensor_tape.tensor(input)?.meta().is_contiguous()
        {
            let dim_size = input_shape[dim];
            let inner: usize = input_shape[dim + 1..].iter().product();
            let outer: usize = input_shape[..dim].iter().product();
            if dim_size > 0 && inner > 0 {
                use rayon::prelude::*;
                let p2 = p == 2.0;
                let out = {
                    let input_tensor = self.tensor_tape.tensor(input)?;
                    let input_vals = input_tensor.contiguous_values()?;
                    let block_len = dim_size * inner;
                    let mut out = vec![0.0_f64; input_vals.len()];
                    let lane = |out_block: &mut [f64], in_block: &[f64]| {
                        for i in 0..inner {
                            let mut acc = 0.0_f64;
                            for k in 0..dim_size {
                                let v = in_block[k * inner + i];
                                acc += if p2 { v * v } else { v.abs().powf(p) };
                            }
                            let norm = if p2 { acc.sqrt() } else { acc.powf(1.0 / p) };
                            let denom = norm.max(eps);
                            for k in 0..dim_size {
                                out_block[k * inner + i] = in_block[k * inner + i] / denom;
                            }
                        }
                    };
                    // normalize is BANDWIDTH-bound (the sqrt amortizes over `dim_size`
                    // elems), so parallel pays only at the fault-parallelism crossover
                    // (~4M), not the compute default — below it, parallel regresses
                    // 0.03-0.82x (measured). Bit-identical.
                    if input_vals.len() >= MOVEMENT_COPY_PARALLEL_MIN {
                        out.par_chunks_mut(block_len)
                            .zip(input_vals.par_chunks(block_len))
                            .for_each(|(o, i)| lane(o, i));
                    } else {
                        out.chunks_mut(block_len)
                            .zip(input_vals.chunks(block_len))
                            .for_each(|(o, i)| lane(o, i));
                    }
                    out
                };
                let _ = outer;
                return self.tensor_variable(out, input_shape, false);
            }
        }

        // No-grad f32 p=2 fast path for the dominant F.normalize lane. The
        // f64 fused path above does not cover f32, so f32 fell through
        // norm_dim -> unsqueeze -> maximum -> expand -> divide. Keep each
        // slice's r-ascending sum-of-squares order identical to the f32 norm
        // kernel, but fuse the denominator and divide into one parallel pass.
        if dim < input_shape.len()
            && p == 2.0
            && self.tensor_dtype(input)? == DType::F32
            && !self.tensor_requires_grad(input)?
            && self.tensor_tape.tensor(input)?.meta().is_contiguous()
        {
            let dim_size = input_shape[dim];
            let inner: usize = input_shape[dim + 1..].iter().product();
            let outer: usize = input_shape[..dim].iter().product();
            if dim_size > 0 && inner > 0 {
                use rayon::prelude::*;
                let eps_f = eps as f32;
                let out = {
                    let input_tensor = self.tensor_tape.tensor(input)?;
                    let input_vals = input_tensor.contiguous_values_f32()?;
                    let block_len = dim_size * inner;
                    let n_lanes = outer * inner;
                    // Phase 1: per-lane denom = max(sqrt(sum x*x), eps). The sum stays a SERIAL
                    // r-ascending f32 accumulation (bit-exact with the f32 norm kernel), but
                    // parallelizes ACROSS lanes. The old code chunked par_chunks_mut(block_len),
                    // so a 1-D / large-block normalize (1 lane, block==numel) ran ENTIRELY serial
                    // (sum AND divide) = ~3.4x SLOWER than torch.
                    // BANDWIDTH-bound: parallel pays only at the fault-parallelism crossover
                    // (~4M); below it parallel regresses (measured 0.03-0.82x). Gate BOTH
                    // phases on the same size check. Bit-identical either way.
                    let parallel = input_vals.len() >= MOVEMENT_COPY_PARALLEL_MIN;
                    let lane_denom = |lane: usize| -> f32 {
                        let outer_idx = lane / inner;
                        let i = lane % inner;
                        let base = outer_idx * block_len + i;
                        let mut acc = 0.0_f32;
                        for k in 0..dim_size {
                            let v = input_vals[base + k * inner];
                            acc += v * v;
                        }
                        let norm = acc.sqrt();
                        if norm.is_nan() {
                            f32::NAN
                        } else {
                            norm.max(eps_f)
                        }
                    };
                    let denoms: Vec<f32> = if parallel {
                        (0..n_lanes).into_par_iter().map(lane_denom).collect()
                    } else {
                        (0..n_lanes).map(lane_denom).collect()
                    };
                    // Phase 2: divide every element by its lane's denom (order-irrelevant).
                    let mut out = vec![0.0_f32; input_vals.len()];
                    let div_one = |g: usize, o: &mut f32| {
                        let outer_idx = g / block_len;
                        let i = (g % block_len) % inner;
                        let lane = outer_idx * inner + i;
                        *o = input_vals[g] / denoms[lane];
                    };
                    if parallel {
                        out.par_iter_mut()
                            .enumerate()
                            .for_each(|(g, o)| div_one(g, o));
                    } else {
                        out.iter_mut().enumerate().for_each(|(g, o)| div_one(g, o));
                    }
                    out
                };
                let _ = outer;
                return self.tensor_variable_f32(out, input_shape, false);
            }
        }

        let norm = self.tensor_norm_dim(input, p, dim)?;
        // unsqueeze norm back to original dim for broadcasting
        let norm_unsq = self.tensor_unsqueeze(norm, dim)?;
        // denom = max(norm, eps)
        let eps_shape = self.tensor_shape(norm_unsq)?;
        let eps_t = self.full(eps_shape, eps, false)?;
        let denom = self.tensor_maximum(norm_unsq, eps_t)?;
        // Broadcast the keepdim norm [.., 1, ..] up to the input shape before
        // dividing: the elementwise tensor_div does NOT itself broadcast a
        // size-1 axis in this codebase, so dividing [N, D] by [N, 1] failed with
        // a ShapeMismatch — silently breaking tensor_normalize for every
        // [N, D]-along-dim-1 input (cosine_similarity, info_nce_loss, SVD power
        // iteration). frankentorch-c5g4.
        let denom_b = self.tensor_expand(denom, input_shape)?;
        self.tensor_div(input, denom_b)
    }

    // ── Loss Functions ───────────────────────────────────────────────────

    /// Mean squared error loss.
    ///
    /// Equivalent to `torch.nn.functional.mse_loss(input, target, reduction)`.
    /// Reduction can be "none", "mean", or "sum".
    pub fn tensor_mse_loss(
        &mut self,
        input: TensorNodeId,
        target: TensorNodeId,
        reduction: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        // Fused no-grad mean/sum fast path (f64, same-shape): compute the
        // per-element (input-target)^2 once into a borrowed-input buffer and
        // reduce with the SAME reduction kernel as the composed path, so the
        // scalar is bit-identical while avoiding the diff/sq intermediate tape
        // nodes (gmuml retention) and a full-size allocation. frankentorch-3jmy3.
        if matches!(reduction, "mean" | "sum")
            && self.tensor_dtype(input)? == DType::F64
            && self.tensor_dtype(target)? == DType::F64
            && self.tensor_shape(target)? == self.tensor_shape(input)?
            && !self.tensor_tape.tensor_requires_grad(input)?
            && !self.tensor_tape.tensor_requires_grad(target)?
        {
            let in_shape = self.tensor_shape(input)?;
            let value = {
                let x_t = self.tensor_tape.tensor(input)?;
                let t_t = self.tensor_tape.tensor(target)?;
                let xv = x_t
                    .contiguous_values()
                    .map_err(AutogradError::DenseTensor)?;
                let tv = t_t
                    .contiguous_values()
                    .map_err(AutogradError::DenseTensor)?;
                let mut tmp = vec![0.0f64; xv.len()];
                for ((d, &a), &b) in tmp.iter_mut().zip(xv.iter()).zip(tv.iter()) {
                    let e = a - b;
                    *d = e * e;
                }
                let meta = TensorMeta::from_shape(in_shape, DType::F64, x_t.meta().device());
                if reduction == "mean" {
                    ft_kernel_cpu::mean_tensor_contiguous_f64(&tmp, &meta)
                } else {
                    ft_kernel_cpu::sum_tensor_contiguous_f64(&tmp, &meta)
                }
                .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?
            };
            return self.tensor_variable(vec![value], vec![1], false);
        }

        // No-grad reduction='none' fast path (f64 + f32): (input-target)^2 in ONE parallel borrowed
        // pass. The composed `sub` + `mul(diff,diff)` makes 2 tape nodes + operand clones (f32 was
        // ~6x SLOWER vs torch). Bit-exact: same sub-then-self-multiply in the input dtype. grad /
        // non-contiguous / mismatched-shape fall through.
        if reduction == "none"
            && !self.tensor_tape.tensor_requires_grad(input)?
            && !self.tensor_tape.tensor_requires_grad(target)?
            && self.tensor_shape(target)? == self.tensor_shape(input)?
        {
            let in_f64 =
                self.tensor_dtype(input)? == DType::F64 && self.tensor_dtype(target)? == DType::F64;
            let in_f32 =
                self.tensor_dtype(input)? == DType::F32 && self.tensor_dtype(target)? == DType::F32;
            if in_f64 {
                let built = {
                    let xt = self.tensor_tape.tensor(input)?;
                    let tt = self.tensor_tape.tensor(target)?;
                    if xt.meta().is_contiguous() && tt.meta().is_contiguous() {
                        let xv = xt.contiguous_values()?;
                        let tv = tt.contiguous_values()?;
                        (xv.len() == tv.len()).then(|| {
                            use rayon::prelude::*;
                            let out: Vec<f64> = (0..xv.len())
                                .into_par_iter()
                                .map(|i| {
                                    let e = xv[i] - tv[i];
                                    e * e
                                })
                                .collect();
                            (out, xt.meta().shape().to_vec())
                        })
                    } else {
                        None
                    }
                };
                if let Some((out, shape)) = built {
                    return self.tensor_variable(out, shape, false);
                }
            } else if in_f32 {
                let built = {
                    let xt = self.tensor_tape.tensor(input)?;
                    let tt = self.tensor_tape.tensor(target)?;
                    if xt.meta().is_contiguous() && tt.meta().is_contiguous() {
                        let xv = xt.contiguous_values_f32()?;
                        let tv = tt.contiguous_values_f32()?;
                        (xv.len() == tv.len()).then(|| {
                            use rayon::prelude::*;
                            let out: Vec<f32> = (0..xv.len())
                                .into_par_iter()
                                .map(|i| {
                                    let e = xv[i] - tv[i];
                                    e * e
                                })
                                .collect();
                            (out, xt.meta().shape().to_vec())
                        })
                    } else {
                        None
                    }
                };
                if let Some((out, shape)) = built {
                    return self.tensor_variable_f32(out, shape, false);
                }
            }
        }

        let diff = self.tensor_sub(input, target)?;
        let sq = self.tensor_mul(diff, diff)?;
        match reduction {
            "none" => Ok(sq),
            "mean" => self.tensor_mean(sq),
            "sum" => self.tensor_sum(sq),
            _ => Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "mse_loss: reduction must be 'none', 'mean', or 'sum'",
                },
            ))),
        }
    }

    /// L1 loss (mean absolute error).
    ///
    /// Equivalent to `torch.nn.functional.l1_loss(input, target, reduction)`.
    pub fn tensor_l1_loss(
        &mut self,
        input: TensorNodeId,
        target: TensorNodeId,
        reduction: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        // Fused no-grad mean/sum fast path (f64, same-shape): compute the
        // per-element |input-target| once into a borrowed-input buffer and reduce
        // with the SAME reduction kernel as the composed path, so the scalar is
        // bit-identical while avoiding the diff/abs intermediate tape nodes
        // (gmuml retention) and a full-size allocation. frankentorch-3jmy3.
        if matches!(reduction, "mean" | "sum")
            && self.tensor_dtype(input)? == DType::F64
            && self.tensor_dtype(target)? == DType::F64
            && self.tensor_shape(target)? == self.tensor_shape(input)?
            && !self.tensor_tape.tensor_requires_grad(input)?
            && !self.tensor_tape.tensor_requires_grad(target)?
        {
            let in_shape = self.tensor_shape(input)?;
            let value = {
                let x_t = self.tensor_tape.tensor(input)?;
                let t_t = self.tensor_tape.tensor(target)?;
                let xv = x_t
                    .contiguous_values()
                    .map_err(AutogradError::DenseTensor)?;
                let tv = t_t
                    .contiguous_values()
                    .map_err(AutogradError::DenseTensor)?;
                let mut tmp = vec![0.0f64; xv.len()];
                for ((d, &a), &b) in tmp.iter_mut().zip(xv.iter()).zip(tv.iter()) {
                    *d = (a - b).abs();
                }
                let meta = TensorMeta::from_shape(in_shape, DType::F64, x_t.meta().device());
                if reduction == "mean" {
                    ft_kernel_cpu::mean_tensor_contiguous_f64(&tmp, &meta)
                } else {
                    ft_kernel_cpu::sum_tensor_contiguous_f64(&tmp, &meta)
                }
                .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?
            };
            return self.tensor_variable(vec![value], vec![1], false);
        }

        // No-grad reduction='none' fast path (f64 + f32): |input-target| in ONE parallel borrowed
        // pass (composed `sub`+`abs` made 2 tape nodes + clones, ~3x SLOWER vs torch). Bit-exact.
        if reduction == "none"
            && !self.tensor_tape.tensor_requires_grad(input)?
            && !self.tensor_tape.tensor_requires_grad(target)?
            && self.tensor_shape(target)? == self.tensor_shape(input)?
        {
            let in_f64 =
                self.tensor_dtype(input)? == DType::F64 && self.tensor_dtype(target)? == DType::F64;
            let in_f32 =
                self.tensor_dtype(input)? == DType::F32 && self.tensor_dtype(target)? == DType::F32;
            if in_f64 {
                let built = {
                    let xt = self.tensor_tape.tensor(input)?;
                    let tt = self.tensor_tape.tensor(target)?;
                    if xt.meta().is_contiguous() && tt.meta().is_contiguous() {
                        let xv = xt.contiguous_values()?;
                        let tv = tt.contiguous_values()?;
                        (xv.len() == tv.len()).then(|| {
                            use rayon::prelude::*;
                            let out: Vec<f64> = (0..xv.len())
                                .into_par_iter()
                                .map(|i| (xv[i] - tv[i]).abs())
                                .collect();
                            (out, xt.meta().shape().to_vec())
                        })
                    } else {
                        None
                    }
                };
                if let Some((out, shape)) = built {
                    return self.tensor_variable(out, shape, false);
                }
            } else if in_f32 {
                let built = {
                    let xt = self.tensor_tape.tensor(input)?;
                    let tt = self.tensor_tape.tensor(target)?;
                    if xt.meta().is_contiguous() && tt.meta().is_contiguous() {
                        let xv = xt.contiguous_values_f32()?;
                        let tv = tt.contiguous_values_f32()?;
                        (xv.len() == tv.len()).then(|| {
                            use rayon::prelude::*;
                            let out: Vec<f32> = (0..xv.len())
                                .into_par_iter()
                                .map(|i| (xv[i] - tv[i]).abs())
                                .collect();
                            (out, xt.meta().shape().to_vec())
                        })
                    } else {
                        None
                    }
                };
                if let Some((out, shape)) = built {
                    return self.tensor_variable_f32(out, shape, false);
                }
            }
        }

        let diff = self.tensor_sub(input, target)?;
        let abs_diff = self.tensor_abs(diff)?;
        match reduction {
            "none" => Ok(abs_diff),
            "mean" => self.tensor_mean(abs_diff),
            "sum" => self.tensor_sum(abs_diff),
            _ => Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "l1_loss: reduction must be 'none', 'mean', or 'sum'",
                },
            ))),
        }
    }

    /// Smooth L1 loss (Huber loss with delta=1).
    ///
    /// Equivalent to `torch.nn.functional.smooth_l1_loss(input, target, reduction, beta)`.
    /// Uses L2 loss for |x| < beta, L1 loss otherwise.
    pub fn tensor_smooth_l1_loss(
        &mut self,
        input: TensorNodeId,
        target: TensorNodeId,
        reduction: &str,
        beta: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        if beta <= 0.0 || !beta.is_finite() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "smooth_l1_loss requires finite beta > 0",
                },
            )));
        }

        // Fused fast path (f64, same-shape input/target): no op-graph
        // intermediates. No-grad mean/sum use a pairwise map-reduce kernel that
        // preserves the materialized-vector reduction tree. Grad mean/sum use a
        // scalar custom op so backward does not materialize a uniform dloss
        // vector after a separate reduction node; "none" keeps the per-element
        // tensor path.
        let in_shape = self.tensor_shape(input)?;
        if matches!(reduction, "none" | "mean" | "sum")
            && self.tensor_dtype(input)? == DType::F64
            && self.tensor_dtype(target)? == DType::F64
            && self.tensor_shape(target)? == in_shape
        {
            let input_needs_grad = self.tensor_tape.tensor_requires_grad(input)?;
            let target_needs_grad = self.tensor_tape.tensor_requires_grad(target)?;
            let needs_grad = input_needs_grad || target_needs_grad;
            if !needs_grad && matches!(reduction, "mean" | "sum") {
                // Zero-copy borrow the contiguous inputs (no tensor_values clone of
                // two full-size tensors) — the fused kernel only READS them. The
                // borrows end before the tensor_variable/record below. frankentorch-3jmy3.
                let (value, kernel) = {
                    let x_t = self.tensor_tape.tensor(input)?;
                    let t_t = self.tensor_tape.tensor(target)?;
                    let xv = x_t
                        .contiguous_values()
                        .map_err(AutogradError::DenseTensor)?;
                    let tv = t_t
                        .contiguous_values()
                        .map_err(AutogradError::DenseTensor)?;
                    if reduction == "mean" {
                        (
                            ft_kernel_cpu::smooth_l1_mean_f64(xv, tv, beta),
                            "cpu::smooth_l1_mean_f64",
                        )
                    } else {
                        (
                            ft_kernel_cpu::smooth_l1_sum_f64(xv, tv, beta),
                            "cpu::smooth_l1_sum_f64",
                        )
                    }
                };
                let out = self.tensor_variable(vec![value], vec![1], false)?;
                self.record_tensor_smooth_l1_reduction_operation(
                    input, target, out, reduction, kernel,
                )?;
                return Ok(out);
            }
            if needs_grad && matches!(reduction, "mean" | "sum") {
                let bc = beta;
                let is_mean = reduction == "mean";
                let input_grad = input_needs_grad;
                let target_grad = target_needs_grad;
                let kernel = if is_mean {
                    "cpu::smooth_l1_mean_f64+backward_reduced"
                } else {
                    "cpu::smooth_l1_sum_f64+backward_reduced"
                };
                let out = self.tensor_apply_function_f64_borrowed_inputs(
                    &[input, target],
                    move |_ctx, ins| {
                        let (xv, _) = ins[0];
                        let (tv, _) = ins[1];
                        let value = if is_mean {
                            ft_kernel_cpu::smooth_l1_mean_f64(xv, tv, bc)
                        } else {
                            ft_kernel_cpu::smooth_l1_sum_f64(xv, tv, bc)
                        };
                        Ok((vec![value], vec![1]))
                    },
                    move |_ctx, grad_outputs, borrowed| {
                        let upstream = grad_outputs[0][0];
                        let scale = if is_mean {
                            if borrowed[0].0.is_empty() {
                                0.0
                            } else {
                                #[allow(clippy::cast_precision_loss)]
                                let n = borrowed[0].0.len() as f64;
                                upstream / n
                            }
                        } else {
                            upstream
                        };
                        let grads = match (input_grad, target_grad) {
                            (true, true) => {
                                let (di, dt) = ft_kernel_cpu::smooth_l1_backward_reduced_f64(
                                    scale,
                                    borrowed[0].0,
                                    borrowed[1].0,
                                    bc,
                                );
                                vec![Some(di), Some(dt)]
                            }
                            (true, false) => {
                                let di = ft_kernel_cpu::smooth_l1_backward_reduced_input_f64(
                                    scale,
                                    borrowed[0].0,
                                    borrowed[1].0,
                                    bc,
                                );
                                vec![Some(di), None]
                            }
                            (false, true) => {
                                let dt = ft_kernel_cpu::smooth_l1_backward_reduced_target_f64(
                                    scale,
                                    borrowed[0].0,
                                    borrowed[1].0,
                                    bc,
                                );
                                vec![None, Some(dt)]
                            }
                            (false, false) => vec![None, None],
                        };
                        Ok(grads)
                    },
                )?;
                self.record_tensor_smooth_l1_reduction_operation(
                    input, target, out, reduction, kernel,
                )?;
                return Ok(out);
            }

            let per = if needs_grad {
                let bc = beta;
                // Borrowed-inputs autograd: backward re-reads the live leaf
                // input/target from the tape instead of cloning both into the ctx
                // (2x full-size clones/call — gmuml grad-path cost, frankentorch-3jmy3).
                self.tensor_apply_function_f64_borrowed_inputs(
                    &[input, target],
                    move |_ctx, ins| {
                        let (xv, xs) = ins[0];
                        let (tv, _) = ins[1];
                        let out = ft_kernel_cpu::smooth_l1_forward_f64(xv, tv, bc);
                        Ok((out, xs.to_vec()))
                    },
                    move |_ctx, grad_outputs, borrowed| {
                        let dl = grad_outputs[0];
                        let (di, dt) = ft_kernel_cpu::smooth_l1_backward_f64(
                            dl,
                            borrowed[0].0,
                            borrowed[1].0,
                            bc,
                        );
                        Ok(vec![Some(di), Some(dt)])
                    },
                )?
            } else {
                // Borrow both contiguous inputs (the kernel only READS them); tensor_values
                // CLONES 2x full-size buffers, which dominated the no-grad 'none' path
                // (measured 5.77x SLOWER than torch). Bit-identical (same parallel kernel).
                let built = {
                    let x_t = self.tensor_tape.tensor(input)?;
                    let t_t = self.tensor_tape.tensor(target)?;
                    if x_t.meta().is_contiguous() && t_t.meta().is_contiguous() {
                        let xv = x_t
                            .contiguous_values()
                            .map_err(AutogradError::DenseTensor)?;
                        let tv = t_t
                            .contiguous_values()
                            .map_err(AutogradError::DenseTensor)?;
                        Some(ft_kernel_cpu::smooth_l1_forward_f64(xv, tv, beta))
                    } else {
                        None
                    }
                };
                let out = if let Some(out) = built {
                    out
                } else {
                    let xv = self.tensor_values(input)?;
                    let tv = self.tensor_values_lossy_f64(target)?;
                    ft_kernel_cpu::smooth_l1_forward_f64(&xv, &tv, beta)
                };
                self.tensor_variable(out, in_shape.clone(), false)?
            };
            return match reduction {
                "none" => Ok(per),
                "mean" => self.tensor_mean(per),
                _ => self.tensor_sum(per),
            };
        }

        // F32 no-grad fast path. f32 was BROKEN: the composed path below builds F64 full() consts,
        // so tensor_lt/where errored "matching dtypes" on f32. Mirror the composed formula EXACTLY
        // in f32 (same op order -> same f32 rounding): |d|<beta ? ((d*d)/beta)*0.5 : |d|-(0.5*beta).
        if matches!(reduction, "none" | "mean" | "sum")
            && !self.tensor_requires_grad(input)?
            && !self.tensor_requires_grad(target)?
            && self.tensor_dtype(input)? == DType::F32
            && self.tensor_dtype(target)? == DType::F32
            && self.tensor_shape(target)? == in_shape
        {
            #[allow(clippy::cast_possible_truncation)]
            let bf = beta as f32;
            #[allow(clippy::cast_possible_truncation)]
            let hbf = (0.5 * beta) as f32;
            let built = {
                let xt = self.tensor_tape.tensor(input)?;
                let tt = self.tensor_tape.tensor(target)?;
                if xt.meta().is_contiguous() && tt.meta().is_contiguous() {
                    let xd = xt.contiguous_values_f32()?;
                    let td = tt.contiguous_values_f32()?;
                    if xd.len() == td.len() {
                        use rayon::prelude::*;
                        let out: Vec<f32> = xd
                            .par_iter()
                            .zip(td.par_iter())
                            .map(|(&x, &t)| {
                                let d = x - t;
                                let ad = d.abs();
                                if ad < bf {
                                    d * d / bf * 0.5_f32
                                } else {
                                    ad - hbf
                                }
                            })
                            .collect();
                        Some(out)
                    } else {
                        None
                    }
                } else {
                    None
                }
            };
            if let Some(out) = built {
                let per = self.tensor_variable_f32(out, in_shape, false)?;
                return match reduction {
                    "none" => Ok(per),
                    "mean" => self.tensor_mean(per),
                    _ => self.tensor_sum(per),
                };
            }
        }
        let diff = self.tensor_sub(input, target)?;
        let abs_diff = self.tensor_abs(diff)?;
        // full_like (not full(), always F64) so the composed GRAD f32 path works; f64 unchanged.
        let beta_t = self.full_like(input, beta, false)?;
        let half = self.full_like(input, 0.5, false)?;
        let half_beta = self.full_like(input, 0.5 * beta, false)?;
        // L2 part: 0.5 * x^2 / beta
        let sq_scaled = self.tensor_mul(diff, diff)?;
        let l2_part = self.tensor_div(sq_scaled, beta_t)?;
        let l2_part = self.tensor_mul(l2_part, half)?;
        // L1 part: |x| - 0.5 * beta
        let l1_part = self.tensor_sub(abs_diff, half_beta)?;
        // mask: |x| < beta
        let abs_diff2 = self.tensor_abs(diff)?;
        let beta_t2 = self.full_like(input, beta, false)?;
        let mask = self.tensor_lt(abs_diff2, beta_t2)?;
        let loss = self.tensor_where(mask, l2_part, l1_part)?;
        match reduction {
            "none" => Ok(loss),
            "mean" => self.tensor_mean(loss),
            "sum" => self.tensor_sum(loss),
            _ => Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "smooth_l1_loss: reduction must be 'none', 'mean', or 'sum'",
                },
            ))),
        }
    }

    /// Binary cross entropy loss.
    ///
    /// Equivalent to `torch.nn.functional.binary_cross_entropy(input, target, reduction)`.
    /// Input should be probabilities in [0, 1].
    pub fn tensor_bce_loss(
        &mut self,
        input: TensorNodeId,
        target: TensorNodeId,
        reduction: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        // BCE = -[target * log(input) + (1-target) * log(1-input)]
        // Fused no-grad mean/sum fast path (f64, same-shape): compute the
        // per-element term once into a borrowed-input buffer (all std-f64 ops in
        // the SAME order as the composed path — log kernel is value.ln()) and
        // reduce with the SAME reduction kernel, so the scalar is bit-identical
        // while avoiding ~8 full-size intermediate tensors + their tape nodes
        // (gmuml retention). frankentorch-3jmy3.
        if matches!(reduction, "mean" | "sum")
            && self.tensor_dtype(input)? == DType::F64
            && self.tensor_dtype(target)? == DType::F64
            && self.tensor_shape(target)? == self.tensor_shape(input)?
            && !self.tensor_tape.tensor_requires_grad(input)?
            && !self.tensor_tape.tensor_requires_grad(target)?
        {
            let in_shape = self.tensor_shape(input)?;
            let value = {
                let x_t = self.tensor_tape.tensor(input)?;
                let t_t = self.tensor_tape.tensor(target)?;
                let xv = x_t
                    .contiguous_values()
                    .map_err(AutogradError::DenseTensor)?;
                let tv = t_t
                    .contiguous_values()
                    .map_err(AutogradError::DenseTensor)?;
                let mut tmp = vec![0.0f64; xv.len()];
                for ((d, &x), &t) in tmp.iter_mut().zip(xv.iter()).zip(tv.iter()) {
                    let term1 = t * x.ln();
                    let term2 = (1.0 - t) * (1.0 - x).ln();
                    *d = -(term1 + term2);
                }
                let meta = TensorMeta::from_shape(in_shape, DType::F64, x_t.meta().device());
                if reduction == "mean" {
                    ft_kernel_cpu::mean_tensor_contiguous_f64(&tmp, &meta)
                } else {
                    ft_kernel_cpu::sum_tensor_contiguous_f64(&tmp, &meta)
                }
                .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?
            };
            return self.tensor_variable(vec![value], vec![1], false);
        }

        // No-grad 'none' fast path: the composed path below (log + mul + full + sub + sub +
        // log + mul + add + neg = ~9 passes) measured 4.76x SLOWER than torch. Borrow both
        // contiguous f64 inputs and compute the per-element BCE term in ONE parallel pass
        // (SAME ops/order as the fused mean/sum path above: -(t*ln(x) + (1-t)*ln(1-x))).
        // Bit-exact with the composed path. grad / non-f64 / non-contiguous fall through.
        if reduction == "none"
            && self.tensor_dtype(input)? == DType::F64
            && self.tensor_dtype(target)? == DType::F64
            && self.tensor_shape(target)? == self.tensor_shape(input)?
            && !self.tensor_tape.tensor_requires_grad(input)?
            && !self.tensor_tape.tensor_requires_grad(target)?
        {
            let in_shape = self.tensor_shape(input)?;
            let built = {
                let x_t = self.tensor_tape.tensor(input)?;
                let t_t = self.tensor_tape.tensor(target)?;
                if x_t.meta().is_contiguous() && t_t.meta().is_contiguous() {
                    let xv = x_t
                        .contiguous_values()
                        .map_err(AutogradError::DenseTensor)?;
                    let tv = t_t
                        .contiguous_values()
                        .map_err(AutogradError::DenseTensor)?;
                    use rayon::prelude::*;
                    let out: Vec<f64> = xv
                        .par_iter()
                        .zip(tv.par_iter())
                        .map(|(&x, &t)| -(t * x.ln() + (1.0 - t) * (1.0 - x).ln()))
                        .collect();
                    Some(out)
                } else {
                    None
                }
            };
            if let Some(out) = built {
                return self.tensor_variable(out, in_shape, false);
            }
        }

        let log_input = self.tensor_log(input)?;
        let term1 = self.tensor_mul(target, log_input)?;
        let shape = self.tensor_shape(input)?;
        let ones = self.full(shape, 1.0, false)?;
        let one_minus_target = self.tensor_sub(ones, target)?;
        let one_minus_input = self.tensor_sub(ones, input)?;
        let log_one_minus_input = self.tensor_log(one_minus_input)?;
        let term2 = self.tensor_mul(one_minus_target, log_one_minus_input)?;
        let sum_terms = self.tensor_add(term1, term2)?;
        let loss = self.tensor_neg(sum_terms)?;
        match reduction {
            "none" => Ok(loss),
            "mean" => self.tensor_mean(loss),
            "sum" => self.tensor_sum(loss),
            _ => Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "bce_loss: reduction must be 'none', 'mean', or 'sum'",
                },
            ))),
        }
    }

    /// Alias for tensor_bce_loss.
    ///
    /// Equivalent to `torch.nn.functional.binary_cross_entropy(input, target, reduction)`.
    pub fn tensor_binary_cross_entropy(
        &mut self,
        input: TensorNodeId,
        target: TensorNodeId,
        reduction: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_bce_loss(input, target, reduction)
    }

    /// Binary cross entropy with logits (numerically stable).
    ///
    /// Equivalent to `torch.nn.functional.binary_cross_entropy_with_logits`.
    /// More numerically stable than sigmoid + BCE.
    pub fn tensor_bce_with_logits_loss(
        &mut self,
        input: TensorNodeId,
        target: TensorNodeId,
        reduction: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        // BCE_logits = max(input, 0) - input * target + log(1 + exp(-|input|))
        let shape = self.tensor_shape(input)?;
        // No-grad fused fast path: the compose below is 11 elementwise tape ops + 2 full() allocs
        // (~13 full-size materialisations; measured 5.4x SLOWER than torch). Compute the stable
        // per-element loss in ONE parallel pass over the borrowed contiguous storage, then reduce
        // via the existing tensor_mean/tensor_sum (so the reduction output is identical). It's a
        // transcendental (exp/log) tolerance loss; f64-accumulated per-element value is at-or-more
        // accurate than the f32 compose. Grad / shape-mismatch / non-contiguous / non-float fall
        // through. frankentorch-specf32.
        if !self.tensor_requires_grad(input)?
            && !self.tensor_requires_grad(target)?
            && self.tensor_shape(target)? == shape
            && reduction != "none"
        {
            let dt = self.tensor_dtype(input)?;
            let loss_built: Option<(Option<Vec<f64>>, Option<Vec<f32>>)> = {
                let xt = self.tensor_tape.tensor(input)?;
                let tt = self.tensor_tape.tensor(target)?;
                if xt.meta().is_contiguous()
                    && tt.meta().is_contiguous()
                    && matches!(dt, DType::F32 | DType::F64)
                    && self.tensor_dtype(target)? == dt
                {
                    use rayon::prelude::*;
                    match dt {
                        // f32: compute NATIVELY in f32 (f32 expf/lnf is ~2x faster than f64 exp/ln
                        // AND matches the f32 compose's per-op rounding).
                        DType::F32 => {
                            let xv = xt.contiguous_values_f32()?;
                            let zv = tt.contiguous_values_f32()?;
                            if xv.len() == zv.len() {
                                let l: Vec<f32> = xv
                                    .par_iter()
                                    .zip(zv.par_iter())
                                    .map(|(&x, &z)| {
                                        x.max(0.0) - x * z + (1.0_f32 + (-x.abs()).exp()).ln()
                                    })
                                    .collect();
                                Some((None, Some(l)))
                            } else {
                                None
                            }
                        }
                        _ => {
                            let xv = xt.contiguous_values()?;
                            let zv = tt.contiguous_values()?;
                            if xv.len() == zv.len() {
                                let l: Vec<f64> = xv
                                    .par_iter()
                                    .zip(zv.par_iter())
                                    .map(|(&x, &z)| {
                                        x.max(0.0) - x * z + (1.0 + (-x.abs()).exp()).ln()
                                    })
                                    .collect();
                                Some((Some(l), None))
                            } else {
                                None
                            }
                        }
                    }
                } else {
                    None
                }
            };
            let loss = match loss_built {
                Some((Some(l64), None)) => Some(self.tensor_variable(l64, shape.clone(), false)?),
                Some((None, Some(l32))) => {
                    Some(self.tensor_variable_f32(l32, shape.clone(), false)?)
                }
                _ => None,
            };
            if let Some(loss) = loss {
                return match reduction {
                    "mean" => self.tensor_mean(loss),
                    "sum" => self.tensor_sum(loss),
                    _ => unreachable!("reduction != none guarded above"),
                };
            }
        }
        let zeros = self.full(shape.clone(), 0.0, false)?;
        let relu_input = self.tensor_maximum(input, zeros)?;
        let input_target = self.tensor_mul(input, target)?;
        let term1 = self.tensor_sub(relu_input, input_target)?;
        let abs_input = self.tensor_abs(input)?;
        let neg_abs_input = self.tensor_neg(abs_input)?;
        let exp_term = self.tensor_exp(neg_abs_input)?;
        let ones = self.full(shape, 1.0, false)?;
        let one_plus_exp = self.tensor_add(ones, exp_term)?;
        let log_term = self.tensor_log(one_plus_exp)?;
        let loss = self.tensor_add(term1, log_term)?;
        match reduction {
            "none" => Ok(loss),
            "mean" => self.tensor_mean(loss),
            "sum" => self.tensor_sum(loss),
            _ => Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "bce_with_logits_loss: reduction must be 'none', 'mean', or 'sum'",
                },
            ))),
        }
    }

    /// Alias for tensor_bce_with_logits_loss.
    ///
    /// Equivalent to `torch.nn.functional.binary_cross_entropy_with_logits`.
    pub fn tensor_binary_cross_entropy_with_logits(
        &mut self,
        input: TensorNodeId,
        target: TensorNodeId,
        reduction: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_bce_with_logits_loss(input, target, reduction)
    }

    /// BCE-with-logits loss weighting the positive class by `pos_weight`,
    /// matching `torch.nn.functional.binary_cross_entropy_with_logits(input,
    /// target, pos_weight=pos_weight, reduction=reduction)` for a scalar
    /// `pos_weight` (the common per-binary-task imbalance weight).
    ///
    /// Derived from `l = pos_weight·t·softplus(-x) + (1-t)·softplus(x)` and
    /// `softplus(x) = softplus(-x) + x`:
    ///   l = (1-t)·x + log_weight·(max(-x, 0) + log(1 + e^{-|x|}))
    /// with `log_weight = 1 + (pos_weight-1)·t`. pos_weight=1 reduces to the
    /// plain stable BCE-with-logits. Composed from autograd-aware ops.
    pub fn tensor_bce_with_logits_pos_weight(
        &mut self,
        input: TensorNodeId,
        target: TensorNodeId,
        pos_weight: f64,
        reduction: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        if (pos_weight - 1.0).abs() < f64::EPSILON {
            return self.tensor_bce_with_logits_loss(input, target, reduction);
        }
        let shape = self.tensor_shape(input)?;
        // No-grad fused fast path: the compose below is 13 elementwise ops + 2 full() allocs.
        // loss = (1-z)·x + (1+(pw-1)·z)·(max(-x,0) + log(1+exp(-|x|))) in ONE parallel pass
        // (f32-native expf/lnf for f32), then reduce via tensor_mean/tensor_sum. Grad / "none" /
        // shape-mismatch / non-contiguous / non-float fall through. frankentorch-specf32.
        if reduction != "none"
            && !self.tensor_requires_grad(input)?
            && !self.tensor_requires_grad(target)?
            && self.tensor_shape(target)? == shape
        {
            let dt = self.tensor_dtype(input)?;
            let loss_built: Option<(Option<Vec<f64>>, Option<Vec<f32>>)> = {
                let xt = self.tensor_tape.tensor(input)?;
                let tt = self.tensor_tape.tensor(target)?;
                if xt.meta().is_contiguous()
                    && tt.meta().is_contiguous()
                    && matches!(dt, DType::F32 | DType::F64)
                    && self.tensor_dtype(target)? == dt
                {
                    use rayon::prelude::*;
                    match dt {
                        DType::F32 => {
                            let xv = xt.contiguous_values_f32()?;
                            let zv = tt.contiguous_values_f32()?;
                            if xv.len() == zv.len() {
                                #[allow(clippy::cast_possible_truncation)]
                                let pw_m1 = (pos_weight - 1.0) as f32;
                                let l: Vec<f32> = xv
                                    .par_iter()
                                    .zip(zv.par_iter())
                                    .map(|(&x, &z)| {
                                        let log_weight = 1.0 + pw_m1 * z;
                                        let softplus_neg =
                                            (-x).max(0.0) + (1.0_f32 + (-x.abs()).exp()).ln();
                                        (1.0 - z) * x + log_weight * softplus_neg
                                    })
                                    .collect();
                                Some((None, Some(l)))
                            } else {
                                None
                            }
                        }
                        _ => {
                            let xv = xt.contiguous_values()?;
                            let zv = tt.contiguous_values()?;
                            if xv.len() == zv.len() {
                                let pw_m1 = pos_weight - 1.0;
                                let l: Vec<f64> = xv
                                    .par_iter()
                                    .zip(zv.par_iter())
                                    .map(|(&x, &z)| {
                                        let log_weight = 1.0 + pw_m1 * z;
                                        let softplus_neg =
                                            (-x).max(0.0) + (1.0 + (-x.abs()).exp()).ln();
                                        (1.0 - z) * x + log_weight * softplus_neg
                                    })
                                    .collect();
                                Some((Some(l), None))
                            } else {
                                None
                            }
                        }
                    }
                } else {
                    None
                }
            };
            let loss = match loss_built {
                Some((Some(l64), None)) => Some(self.tensor_variable(l64, shape.clone(), false)?),
                Some((None, Some(l32))) => {
                    Some(self.tensor_variable_f32(l32, shape.clone(), false)?)
                }
                _ => None,
            };
            if let Some(loss) = loss {
                return match reduction {
                    "mean" => self.tensor_mean(loss),
                    "sum" => self.tensor_sum(loss),
                    _ => unreachable!("reduction != none guarded above"),
                };
            }
        }
        let ones = self.full(shape.clone(), 1.0, false)?;
        let zeros = self.full(shape, 0.0, false)?;

        // log_weight = 1 + (pos_weight - 1) * target
        let lw_scaled = self.tensor_mul_scalar(target, pos_weight - 1.0)?;
        let log_weight = self.tensor_add(ones, lw_scaled)?;

        // softplus(-x) = max(-x, 0) + log(1 + e^{-|x|})
        let neg_x = self.tensor_neg(input)?;
        let max_neg = self.tensor_maximum(neg_x, zeros)?;
        let abs_x = self.tensor_abs(input)?;
        let neg_abs = self.tensor_neg(abs_x)?;
        let exp_term = self.tensor_exp(neg_abs)?;
        let one_plus_exp = self.tensor_add(ones, exp_term)?;
        let log_term = self.tensor_log(one_plus_exp)?;
        let softplus_neg = self.tensor_add(max_neg, log_term)?;

        // term1 = (1 - t) * x ; term2 = log_weight * softplus(-x)
        let one_minus_t = self.tensor_sub(ones, target)?;
        let term1 = self.tensor_mul(one_minus_t, input)?;
        let term2 = self.tensor_mul(log_weight, softplus_neg)?;
        let loss = self.tensor_add(term1, term2)?;

        match reduction {
            "none" => Ok(loss),
            "mean" => self.tensor_mean(loss),
            "sum" => self.tensor_sum(loss),
            _ => Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "bce_with_logits: reduction must be 'none', 'mean', or 'sum'",
                },
            ))),
        }
    }

    /// Negative log likelihood loss.
    ///
    /// Equivalent to `torch.nn.functional.nll_loss(input, target, reduction)`.
    /// Input should be log-probabilities from log_softmax.
    /// Target contains class indices (not one-hot encoded).
    pub fn tensor_nll_loss(
        &mut self,
        input: TensorNodeId,
        target: TensorNodeId,
        reduction: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        let input_shape = self.tensor_shape(input)?;
        let target_shape = self.tensor_shape(target)?;
        if input_shape.len() != 2 || target_shape.len() != 1 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "nll_loss: input must be 2D (N, C), target must be 1D (N,)",
                },
            )));
        }
        if input_shape[0] != target_shape[0] {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "nll_loss: batch size mismatch",
                },
            )));
        }
        let n = input_shape[0];
        let c = input_shape[1];
        let target_vals = self.tensor_values_lossy_f64(target)?;
        for &t in &target_vals {
            let class_idx = t as usize;
            if class_idx >= c {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "nll_loss: target class index out of range",
                    },
                )));
            }
        }
        // Autograd-aware: gather the per-sample log-prob at the target class via
        // the autograd-tracked tensor_gather, then negate — the gradient scatters
        // −grad back to input[i, target[i]]. The previous body extracted values
        // and rebuilt a requires_grad=false leaf, silently severing the gradient
        // of nll_loss (and hence cross_entropy / functional_cross_entropy).
        // The gathered value is the same scalar, so the forward is bit-identical.
        let index = self.tensor_variable(target_vals, vec![n, 1], false)?;
        let gathered = self.tensor_gather(input, 1, index)?; // [n, 1]
        let neg = self.tensor_neg(gathered)?;
        let loss = self.tensor_reshape(neg, vec![n])?; // [n]
        match reduction {
            "none" => Ok(loss),
            "mean" => self.tensor_mean(loss),
            "sum" => self.tensor_sum(loss),
            _ => Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "nll_loss: reduction must be 'none', 'mean', or 'sum'",
                },
            ))),
        }
    }

    /// `torch.nn.functional.nll_loss` with optional per-class `weight` (shape
    /// `[C]`) and `ignore_index`. A sample whose target equals `ignore_index`
    /// contributes 0 and is excluded from the `mean` denominator. With weights,
    /// `mean` divides by the sum of the selected classes' weights (torch's
    /// weighted-mean convention); unweighted it divides by the count of
    /// non-ignored samples. An all-ignored batch yields NaN (0/0), matching torch.
    /// Autograd flows to `input` (and to `weight` when it requires grad); the mean
    /// denominator is treated as a constant.
    pub fn tensor_nll_loss_full(
        &mut self,
        input: TensorNodeId,
        target: TensorNodeId,
        weight: Option<TensorNodeId>,
        ignore_index: Option<i64>,
        reduction: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        if !matches!(reduction, "none" | "mean" | "sum") {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "nll_loss: reduction must be 'none', 'mean', or 'sum'",
                },
            )));
        }
        let input_shape = self.tensor_shape(input)?;
        let target_shape = self.tensor_shape(target)?;
        if input_shape.len() != 2 || target_shape.len() != 1 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "nll_loss: input must be 2D (N, C), target must be 1D (N,)",
                },
            )));
        }
        if input_shape[0] != target_shape[0] {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "nll_loss: batch size mismatch",
                },
            )));
        }
        let n = input_shape[0];
        let c = input_shape[1];
        if let Some(w) = weight
            && self.tensor_shape(w)? != vec![c]
        {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "nll_loss: weight must have shape [C]",
                },
            )));
        }
        // Split targets into a gather-safe class index (ignored -> 0, masked out)
        // and a 0/1 keep-mask.
        let target_vals = self.tensor_values_lossy_f64(target)?;
        let mut safe_idx: Vec<f64> = Vec::with_capacity(n);
        let mut mask: Vec<f64> = Vec::with_capacity(n);
        for &t in &target_vals {
            #[allow(clippy::cast_possible_truncation)]
            let ti = t as i64;
            if ignore_index == Some(ti) {
                safe_idx.push(0.0);
                mask.push(0.0);
            } else {
                if ti < 0 || (ti as usize) >= c {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "nll_loss: target class index out of range",
                        },
                    )));
                }
                safe_idx.push(t);
                mask.push(1.0);
            }
        }
        // nll_i = -input[i, target_i]
        let index = self.tensor_variable(safe_idx.clone(), vec![n, 1], false)?;
        let gathered = self.tensor_gather(input, 1, index)?;
        let neg = self.tensor_neg(gathered)?;
        let nll = self.tensor_reshape(neg, vec![n])?;
        // per-sample scale = mask_i * weight[target_i] (weight defaults to 1).
        let (scale_t, denom) = if let Some(w) = weight {
            let w_idx = self.tensor_variable(safe_idx.clone(), vec![n], false)?;
            let w_gathered = self.tensor_index_select(w, 0, w_idx)?;
            let mask_t = self.tensor_variable(mask.clone(), vec![n], false)?;
            let scale = self.tensor_mul(w_gathered, mask_t)?;
            let w_vals = self.tensor_values(w)?;
            #[allow(clippy::cast_possible_truncation, clippy::cast_sign_loss)]
            let denom: f64 = (0..n).map(|i| mask[i] * w_vals[safe_idx[i] as usize]).sum();
            (scale, denom)
        } else {
            let mask_t = self.tensor_variable(mask.clone(), vec![n], false)?;
            let denom: f64 = mask.iter().sum();
            (mask_t, denom)
        };
        let weighted = self.tensor_mul(nll, scale_t)?;
        match reduction {
            "none" => Ok(weighted),
            "sum" => self.tensor_sum(weighted),
            _ => {
                // "mean": sum / denom (0/0 -> NaN for an all-ignored batch).
                let sum = self.tensor_sum(weighted)?;
                let denom_t = self.full(vec![], denom, false)?;
                self.tensor_div(sum, denom_t)
            }
        }
    }

    /// `torch.nn.functional.cross_entropy` with optional per-class `weight` and
    /// `ignore_index` (= `log_softmax` + [`Self::tensor_nll_loss_full`]).
    pub fn tensor_cross_entropy_full(
        &mut self,
        input: TensorNodeId,
        target: TensorNodeId,
        weight: Option<TensorNodeId>,
        ignore_index: Option<i64>,
        reduction: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        let log_probs = self.tensor_log_softmax(input, 1)?;
        self.tensor_nll_loss_full(log_probs, target, weight, ignore_index, reduction)
    }

    /// Cross entropy loss (log_softmax + nll_loss combined).
    ///
    /// Equivalent to `torch.nn.functional.cross_entropy(input, target, reduction)`.
    /// Input should be raw logits. Target contains class indices.
    /// Soft-label cross entropy: `torch.nn.functional.cross_entropy` with a
    /// probability target of the same shape as `input` (`[N, C]`), used for label
    /// smoothing, distillation, and mixup. Per sample
    /// `loss_i = -Σ_c target[i, c] · log_softmax(input)[i, c]`, then reduced
    /// (`mean` averages over the batch). A one-hot soft target reproduces the
    /// hard-label result. Autograd flows to `input` and to `target`.
    pub fn tensor_cross_entropy_soft(
        &mut self,
        input: TensorNodeId,
        target: TensorNodeId,
        reduction: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        if !matches!(reduction, "none" | "mean" | "sum") {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "cross_entropy: reduction must be 'none', 'mean', or 'sum'",
                },
            )));
        }
        let in_shape = self.tensor_shape(input)?;
        if in_shape.len() != 2 || self.tensor_shape(target)? != in_shape {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "cross_entropy: soft-label target must have the same [N, C] shape as input",
                },
            )));
        }
        let n = in_shape[0];
        let log_probs = self.tensor_log_softmax(input, 1)?; // [N, C]
        let prod = self.tensor_mul(target, log_probs)?; // [N, C]
        let summed = self.tensor_sum_dim(prod, 1)?; // [N] (or [N,1])
        let summed = self.tensor_reshape(summed, vec![n])?;
        let per_sample = self.tensor_neg(summed)?; // [N]
        match reduction {
            "none" => Ok(per_sample),
            "sum" => self.tensor_sum(per_sample),
            _ => self.tensor_mean(per_sample),
        }
    }

    pub fn tensor_cross_entropy(
        &mut self,
        input: TensorNodeId,
        target: TensorNodeId,
        reduction: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        // Soft-label form: a probability target matching the input's [N, C] shape
        // (torch auto-detects this vs a [N] class-index target). Distillation /
        // mixup / label-smoothing all pass soft labels here.
        let in_shape = self.tensor_shape(input)?;
        if in_shape.len() == 2 && self.tensor_shape(target)? == in_shape {
            return self.tensor_cross_entropy_soft(input, target, reduction);
        }
        // Fused fast path: 2-D f64 logits with an in-range class-index target
        // [batch]. Computes per-row loss (lse - logits[target]) directly, never
        // materialising the [batch, classes] log-softmax tensor (nor its backward
        // intermediates) — then the requested reduction. Falls through for other
        // shapes / dtypes / out-of-range or non-integer targets (e.g. ignore_index).
        if matches!(reduction, "none" | "mean" | "sum")
            && in_shape.len() == 2
            && self.tensor_dtype(input)? == DType::F64
            && self.tensor_shape(target)? == vec![in_shape[0]]
        {
            let (batch, classes) = (in_shape[0], in_shape[1]);
            let tvals = self.tensor_values_lossy_f64(target)?;
            if classes > 0
                && tvals
                    .iter()
                    .all(|&t| t >= 0.0 && t.fract() == 0.0 && (t as usize) < classes)
            {
                let target_idx: Vec<usize> = tvals.iter().map(|&t| t as usize).collect();
                let per_row = if self.tensor_tape.tensor_requires_grad(input)? {
                    let (b, c) = (batch, classes);
                    let ti_fwd = target_idx.clone();
                    let ti_bwd = target_idx;
                    self.tensor_apply_function_f64_borrowed_inputs(
                        &[input],
                        move |_ctx, ins| {
                            let (logits, _) = ins[0];
                            let loss =
                                ft_kernel_cpu::cross_entropy_forward_f64(logits, &ti_fwd, b, c);
                            Ok((loss, vec![b]))
                        },
                        move |_ctx, grad_outputs, borrowed_inputs| {
                            let dloss = grad_outputs[0];
                            let logits = borrowed_inputs[0].0;
                            let dlogits = ft_kernel_cpu::cross_entropy_backward_f64(
                                logits, &ti_bwd, dloss, b, c,
                            );
                            Ok(vec![Some(dlogits)])
                        },
                    )?
                } else {
                    // Zero-copy borrow the contiguous logits (no tensor_values clone)
                    // — the kernel only READS them; borrow ends before tensor_variable
                    // below. frankentorch-3jmy3.
                    // Zero-copy borrow the contiguous logits (no tensor_values clone)
                    // — the kernel only READS them; borrow ends before tensor_variable
                    // below. frankentorch-3jmy3.
                    let loss = {
                        let l_t = self.tensor_tape.tensor(input)?;
                        let logits = l_t
                            .contiguous_values()
                            .map_err(AutogradError::DenseTensor)?;
                        ft_kernel_cpu::cross_entropy_forward_f64(
                            logits,
                            &target_idx,
                            batch,
                            classes,
                        )
                    };
                    self.tensor_variable(loss, vec![batch], false)?
                };
                return match reduction {
                    "none" => Ok(per_row),
                    "mean" => self.tensor_mean(per_row),
                    _ => self.tensor_sum(per_row),
                };
            }
        }
        // f32 fused fast path (dominant ML dtype): same streaming per-row
        // lse−logit[target] forward + softmax−onehot backward, never materialising
        // the [batch, classes] log-softmax (nor its grad tape). f32-output custom op
        // (48w0b) keeps the loss F32. Falls through for soft labels / other shapes /
        // out-of-range targets.
        if matches!(reduction, "none" | "mean" | "sum")
            && in_shape.len() == 2
            && self.tensor_dtype(input)? == DType::F32
            && self.tensor_shape(target)? == vec![in_shape[0]]
        {
            let (batch, classes) = (in_shape[0], in_shape[1]);
            // Target holds class indices; it may be stored F32 (matching the logits)
            // or F64. Read it by its actual dtype into f64 for the range/integer check.
            let tvals: Vec<f64> = if self.tensor_dtype(target)? == DType::F32 {
                self.tensor_values_f32(target)?
                    .iter()
                    .map(|&v| f64::from(v))
                    .collect()
            } else {
                self.tensor_values_lossy_f64(target)?
            };
            if classes > 0
                && tvals
                    .iter()
                    .all(|&t| t >= 0.0 && t.fract() == 0.0 && (t as usize) < classes)
            {
                let target_idx: Vec<usize> = tvals.iter().map(|&t| t as usize).collect();
                let per_row = if self.tensor_tape.tensor_requires_grad(input)? {
                    let (b, c) = (batch, classes);
                    let ti_fwd = target_idx.clone();
                    let ti_bwd = target_idx;
                    self.tensor_apply_function_f32_output_borrowed_inputs(
                        &[input],
                        move |_ctx, ins| {
                            let (logits, _) = ins[0];
                            let loss =
                                ft_kernel_cpu::cross_entropy_forward_f32(logits, &ti_fwd, b, c);
                            Ok((loss, vec![b]))
                        },
                        move |_ctx, grad_outputs, borrowed_inputs| {
                            let dloss: Vec<f32> =
                                grad_outputs[0].iter().map(|&v| v as f32).collect();
                            let logits = borrowed_inputs[0].0;
                            let dlogits = ft_kernel_cpu::cross_entropy_backward_f32(
                                logits, &ti_bwd, &dloss, b, c,
                            );
                            Ok(vec![Some(
                                dlogits.iter().map(|&v| v as f64).collect::<Vec<f64>>(),
                            )])
                        },
                    )?
                } else {
                    let loss = {
                        let l_t = self.tensor_tape.tensor(input)?;
                        let logits = l_t
                            .contiguous_values_f32()
                            .map_err(AutogradError::DenseTensor)?;
                        ft_kernel_cpu::cross_entropy_forward_f32(
                            logits,
                            &target_idx,
                            batch,
                            classes,
                        )
                    };
                    self.tensor_variable_f32(loss, vec![batch], false)?
                };
                return match reduction {
                    "none" => Ok(per_row),
                    "mean" => self.tensor_mean(per_row),
                    _ => self.tensor_sum(per_row),
                };
            }
        }

        let log_probs = self.tensor_log_softmax(input, 1)?;
        self.tensor_nll_loss(log_probs, target, reduction)
    }

    /// Cross-entropy with label smoothing, matching
    /// `torch.nn.functional.cross_entropy(input, target, label_smoothing=ε,
    /// reduction=reduction)` for class-index targets.
    ///
    /// With log-probabilities `log_p = log_softmax(input)`:
    ///   loss_i = (1−ε)·nll_loss(log_p, target)_i + ε·(−mean_c log_p[i, c])
    /// then reduced. ε=0 reduces to plain cross-entropy.
    pub fn tensor_cross_entropy_label_smoothing(
        &mut self,
        input: TensorNodeId,
        target: TensorNodeId,
        label_smoothing: f64,
        reduction: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        if !(0.0..=1.0).contains(&label_smoothing) {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "cross_entropy: label_smoothing must be in [0, 1]",
                },
            )));
        }
        if label_smoothing == 0.0 {
            return self.tensor_cross_entropy(input, target, reduction);
        }
        let log_probs = self.tensor_log_softmax(input, 1)?;
        // Per-sample negative log-likelihood at the target class.
        let nll = self.tensor_nll_loss(log_probs, target, "none")?;
        // Per-sample smoothing term: −mean over the class dimension of log_p.
        let mean_lp = self.tensor_mean_dim(log_probs, 1)?;
        let smooth = self.tensor_neg(mean_lp)?;
        let nll_w = self.tensor_mul_scalar(nll, 1.0 - label_smoothing)?;
        let smooth_w = self.tensor_mul_scalar(smooth, label_smoothing)?;
        let loss = self.tensor_add(nll_w, smooth_w)?;
        match reduction {
            "none" => Ok(loss),
            "mean" => self.tensor_mean(loss),
            "sum" => self.tensor_sum(loss),
            _ => Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "cross_entropy: reduction must be 'none', 'mean', or 'sum'",
                },
            ))),
        }
    }

    /// Kullback-Leibler divergence loss.
    ///
    /// Equivalent to `torch.nn.functional.kl_div(input, target, reduction, log_target)`.
    /// Input should be log-probabilities. If log_target=true, target is also log-probs.
    pub fn tensor_kl_div(
        &mut self,
        input: TensorNodeId,
        target: TensorNodeId,
        reduction: &str,
        log_target: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        // Fused no-grad mean/sum fast path (f64, same-shape): compute the
        // per-element KL term once into a borrowed-input buffer (all std-f64 ops
        // — exp/log kernels are value.exp()/value.ln() — in the SAME order as the
        // composed path) and reduce with the SAME reduction kernel, so the scalar
        // is bit-identical while avoiding the exp/log + sub + mul intermediate
        // tensors and their tape nodes (gmuml). batchmean keeps the composed
        // path. frankentorch-3jmy3.
        if matches!(reduction, "mean" | "sum")
            && self.tensor_dtype(input)? == DType::F64
            && self.tensor_dtype(target)? == DType::F64
            && self.tensor_shape(target)? == self.tensor_shape(input)?
            && !self.tensor_tape.tensor_requires_grad(input)?
            && !self.tensor_tape.tensor_requires_grad(target)?
        {
            let in_shape = self.tensor_shape(input)?;
            let value = {
                let x_t = self.tensor_tape.tensor(input)?;
                let t_t = self.tensor_tape.tensor(target)?;
                let xv = x_t
                    .contiguous_values()
                    .map_err(AutogradError::DenseTensor)?;
                let tv = t_t
                    .contiguous_values()
                    .map_err(AutogradError::DenseTensor)?;
                let mut tmp = vec![0.0f64; xv.len()];
                if log_target {
                    for ((d, &x), &t) in tmp.iter_mut().zip(xv.iter()).zip(tv.iter()) {
                        *d = t.exp() * (t - x);
                    }
                } else {
                    for ((d, &x), &t) in tmp.iter_mut().zip(xv.iter()).zip(tv.iter()) {
                        *d = t * (t.ln() - x);
                    }
                }
                let meta = TensorMeta::from_shape(in_shape, DType::F64, x_t.meta().device());
                if reduction == "mean" {
                    ft_kernel_cpu::mean_tensor_contiguous_f64(&tmp, &meta)
                } else {
                    ft_kernel_cpu::sum_tensor_contiguous_f64(&tmp, &meta)
                }
                .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?
            };
            return self.tensor_variable(vec![value], vec![1], false);
        }

        // No-grad 'none' fast path: the composed path below (exp/log + sub + mul, ~several
        // passes) measured ~2.6x SLOWER than torch. Borrow both contiguous f64 inputs and
        // compute the per-element KL term in ONE parallel pass (SAME formula/order as the
        // fused mean/sum path above). Bit-exact. grad / non-f64 / non-contiguous fall through.
        if reduction == "none"
            && self.tensor_dtype(input)? == DType::F64
            && self.tensor_dtype(target)? == DType::F64
            && self.tensor_shape(target)? == self.tensor_shape(input)?
            && !self.tensor_tape.tensor_requires_grad(input)?
            && !self.tensor_tape.tensor_requires_grad(target)?
        {
            let in_shape = self.tensor_shape(input)?;
            let built = {
                let x_t = self.tensor_tape.tensor(input)?;
                let t_t = self.tensor_tape.tensor(target)?;
                if x_t.meta().is_contiguous() && t_t.meta().is_contiguous() {
                    let xv = x_t
                        .contiguous_values()
                        .map_err(AutogradError::DenseTensor)?;
                    let tv = t_t
                        .contiguous_values()
                        .map_err(AutogradError::DenseTensor)?;
                    use rayon::prelude::*;
                    let out: Vec<f64> = if log_target {
                        xv.par_iter()
                            .zip(tv.par_iter())
                            .map(|(&x, &t)| t.exp() * (t - x))
                            .collect()
                    } else {
                        xv.par_iter()
                            .zip(tv.par_iter())
                            .map(|(&x, &t)| t * (t.ln() - x))
                            .collect()
                    };
                    Some(out)
                } else {
                    None
                }
            };
            if let Some(out) = built {
                return self.tensor_variable(out, in_shape, false);
            }
        }

        let loss = if log_target {
            let exp_target = self.tensor_exp(target)?;
            let diff = self.tensor_sub(target, input)?;
            self.tensor_mul(exp_target, diff)?
        } else {
            let log_target_t = self.tensor_log(target)?;
            let diff = self.tensor_sub(log_target_t, input)?;
            self.tensor_mul(target, diff)?
        };
        match reduction {
            "none" => Ok(loss),
            "mean" => self.tensor_mean(loss),
            "sum" => self.tensor_sum(loss),
            "batchmean" => {
                let sum = self.tensor_sum(loss)?;
                let shape = self.tensor_shape(input)?;
                let batch_size = shape[0] as f64;
                let batch_t = self.full(vec![], batch_size, false)?;
                self.tensor_div(sum, batch_t)
            }
            _ => Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "kl_div: reduction must be 'none', 'mean', 'sum', or 'batchmean'",
                },
            ))),
        }
    }

    /// Huber loss (smooth L1 with configurable delta).
    ///
    /// Equivalent to `torch.nn.functional.huber_loss(input, target, reduction, delta)`.
    pub fn tensor_huber_loss(
        &mut self,
        input: TensorNodeId,
        target: TensorNodeId,
        reduction: &str,
        delta: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        if delta <= 0.0 || !delta.is_finite() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "huber_loss requires finite delta > 0",
                },
            )));
        }
        // torch huber_loss(delta) == delta * smooth_l1_loss(beta=delta). The two
        // coincide ONLY at delta == 1: Huber's quadratic branch is 0.5*x^2 while
        // SmoothL1's is 0.5*x^2/beta, and Huber's linear branch is
        // delta*(|x| - 0.5*delta) vs SmoothL1's |x| - 0.5*beta. Elementwise,
        // Huber == delta * SmoothL1(beta=delta); the reductions (none/mean/sum)
        // are linear so scaling the reduced SmoothL1 by delta is exact, and the
        // gradient (delta*(x/delta)=x inside, delta*sign(x) outside) is right too.
        //
        // No-grad 'none' fast path: routing through smooth_l1 + mul_scalar is TWO full
        // passes (vs torch's fused one) — measured ~parity-to-1.6x SLOWER. Compute the
        // per-element huber in ONE parallel pass: s = smooth_l1_value(beta=delta) then
        // s*delta. Bit-identical to delta*smooth_l1_value (same s, then *delta — exactly
        // what smooth_l1_forward + mul_scalar produce, value-by-value). mean/sum keep the
        // composed route (fused smooth_l1 reduction + fast mul_scalar; reducing-then-scaling
        // is NOT bit-equal to scaling-then-reducing, so don't fold them).
        if reduction == "none"
            && !self.tensor_requires_grad(input)?
            && !self.tensor_requires_grad(target)?
            && self.tensor_dtype(input)? == DType::F64
            && self.tensor_dtype(target)? == DType::F64
            && self.tensor_shape(input)? == self.tensor_shape(target)?
        {
            let shape = self.tensor_shape(input)?;
            let half_delta = 0.5 * delta;
            let built = {
                let xt = self.tensor_tape.tensor(input)?;
                let tt = self.tensor_tape.tensor(target)?;
                if xt.meta().is_contiguous() && tt.meta().is_contiguous() {
                    let xd = xt.contiguous_values()?;
                    let td = tt.contiguous_values()?;
                    if xd.len() == td.len() {
                        use rayon::prelude::*;
                        let out: Vec<f64> = xd
                            .par_iter()
                            .zip(td.par_iter())
                            .map(|(&x, &t)| {
                                let d = x - t;
                                let ad = d.abs();
                                let s = if ad < delta {
                                    0.5 * d * d / delta
                                } else {
                                    ad - half_delta
                                };
                                s * delta
                            })
                            .collect();
                        Some(out)
                    } else {
                        None
                    }
                } else {
                    None
                }
            };
            if let Some(out) = built {
                return self.tensor_variable(out, shape, false);
            }
        }
        let smooth = self.tensor_smooth_l1_loss(input, target, reduction, delta)?;
        self.tensor_mul_scalar(smooth, delta)
    }

    /// Hinge embedding loss for margin-based classification.
    ///
    /// Equivalent to `torch.nn.functional.hinge_embedding_loss`.
    pub fn tensor_hinge_embedding_loss(
        &mut self,
        input: TensorNodeId,
        target: TensorNodeId,
        margin: f64,
        reduction: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        // No-grad fast path: the composed full x3 + sub + maximum + eq + where (~7 passes)
        // measured ~2.2x SLOWER than torch. For no-grad equal-shape contiguous f64, borrow
        // both and compute `t==1 ? x : maximum(0, margin-x)` in ONE parallel pass, then
        // reduce. Bit-exact with the composed path: the max is NaN-PROPAGATING to match
        // tensor_maximum (Rust's f64::max drops NaN, so guard it). grad / non-f64 /
        // non-contiguous / bad-reduction fall through.
        if matches!(reduction, "none" | "mean" | "sum")
            && !self.tensor_requires_grad(input)?
            && !self.tensor_requires_grad(target)?
            && self.tensor_dtype(input)? == DType::F64
            && self.tensor_dtype(target)? == DType::F64
            && self.tensor_shape(input)? == self.tensor_shape(target)?
        {
            let shape = self.tensor_shape(input)?;
            let built = {
                let xt = self.tensor_tape.tensor(input)?;
                let tt = self.tensor_tape.tensor(target)?;
                if xt.meta().is_contiguous() && tt.meta().is_contiguous() {
                    let xd = xt.contiguous_values()?;
                    let td = tt.contiguous_values()?;
                    if xd.len() == td.len() {
                        use rayon::prelude::*;
                        let out: Vec<f64> = xd
                            .par_iter()
                            .zip(td.par_iter())
                            .map(|(&x, &t)| {
                                if t == 1.0 {
                                    x
                                } else {
                                    let h = margin - x;
                                    if h.is_nan() { f64::NAN } else { h.max(0.0) }
                                }
                            })
                            .collect();
                        Some(out)
                    } else {
                        None
                    }
                } else {
                    None
                }
            };
            if let Some(out) = built {
                let per = self.tensor_variable(out, shape, false)?;
                return match reduction {
                    "none" => Ok(per),
                    "mean" => self.tensor_mean(per),
                    _ => self.tensor_sum(per),
                };
            }
        }
        // F32 no-grad fast path (sibling of the f64 one above). f32 was BROKEN: the composed path
        // built F64 full() consts, so tensor_eq/where errored on f32. Native f32 single pass
        // `t==1 ? x : max(0, margin-x)` (NaN-propagating max to match tensor_maximum), then reduce.
        if matches!(reduction, "none" | "mean" | "sum")
            && !self.tensor_requires_grad(input)?
            && !self.tensor_requires_grad(target)?
            && self.tensor_dtype(input)? == DType::F32
            && self.tensor_dtype(target)? == DType::F32
            && self.tensor_shape(input)? == self.tensor_shape(target)?
        {
            let shape = self.tensor_shape(input)?;
            #[allow(clippy::cast_possible_truncation)]
            let m = margin as f32;
            let built = {
                let xt = self.tensor_tape.tensor(input)?;
                let tt = self.tensor_tape.tensor(target)?;
                if xt.meta().is_contiguous() && tt.meta().is_contiguous() {
                    let xd = xt.contiguous_values_f32()?;
                    let td = tt.contiguous_values_f32()?;
                    if xd.len() == td.len() {
                        use rayon::prelude::*;
                        let out: Vec<f32> = xd
                            .par_iter()
                            .zip(td.par_iter())
                            .map(|(&x, &t)| {
                                if t == 1.0 {
                                    x
                                } else {
                                    let h = m - x;
                                    if h.is_nan() { f32::NAN } else { h.max(0.0) }
                                }
                            })
                            .collect();
                        Some(out)
                    } else {
                        None
                    }
                } else {
                    None
                }
            };
            if let Some(out) = built {
                let per = self.tensor_variable_f32(out, shape, false)?;
                return match reduction {
                    "none" => Ok(per),
                    "mean" => self.tensor_mean(per),
                    _ => self.tensor_sum(per),
                };
            }
        }
        // full_like (not full(), which is always F64) so the composed grad path works on f32 too
        // (eq/where need matching dtypes); f64 unchanged (full_like(f64)==full F64). frankentorch f32-parity.
        let zeros = self.full_like(input, 0.0, false)?;
        let margin_t = self.full_like(input, margin, false)?;
        let ones = self.full_like(input, 1.0, false)?;
        let margin_minus_input = self.tensor_sub(margin_t, input)?;
        let hinge = self.tensor_maximum(zeros, margin_minus_input)?;
        let mask_pos = self.tensor_eq(target, ones)?;
        let loss = self.tensor_where(mask_pos, input, hinge)?;
        match reduction {
            "none" => Ok(loss),
            "mean" => self.tensor_mean(loss),
            "sum" => self.tensor_sum(loss),
            _ => Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "hinge_embedding_loss: reduction must be 'none', 'mean', or 'sum'",
                },
            ))),
        }
    }

    /// Soft margin loss for binary classification.
    ///
    /// Equivalent to `torch.nn.functional.soft_margin_loss`.
    /// Loss = log(1 + exp(-target * input))
    pub fn tensor_soft_margin_loss(
        &mut self,
        input: TensorNodeId,
        target: TensorNodeId,
        reduction: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        // No-grad fast path: the composed mul + neg + exp + full + add + log (~6 passes)
        // measured 2.02x SLOWER than torch. For no-grad equal-shape contiguous f64, borrow
        // both and compute log(1 + exp(-target*input)) in ONE parallel pass, then reduce.
        // Bit-exact with the composed path (same target*input, exp, 1+exp, libm ln, and the
        // same tensor_mean/sum reduction). grad / non-f64 / non-contiguous / bad-reduction
        // fall through.
        if matches!(reduction, "none" | "mean" | "sum")
            && !self.tensor_requires_grad(input)?
            && !self.tensor_requires_grad(target)?
            && self.tensor_dtype(input)? == DType::F64
            && self.tensor_dtype(target)? == DType::F64
            && self.tensor_shape(input)? == self.tensor_shape(target)?
        {
            let shape = self.tensor_shape(input)?;
            let built = {
                let xt = self.tensor_tape.tensor(input)?;
                let tt = self.tensor_tape.tensor(target)?;
                if xt.meta().is_contiguous() && tt.meta().is_contiguous() {
                    let xd = xt.contiguous_values()?;
                    let td = tt.contiguous_values()?;
                    if xd.len() == td.len() {
                        use rayon::prelude::*;
                        let out: Vec<f64> = xd
                            .par_iter()
                            .zip(td.par_iter())
                            .map(|(&x, &t)| (1.0 + (-(t * x)).exp()).ln())
                            .collect();
                        Some(out)
                    } else {
                        None
                    }
                } else {
                    None
                }
            };
            if let Some(out) = built {
                let per = self.tensor_variable(out, shape, false)?;
                return match reduction {
                    "none" => Ok(per),
                    "mean" => self.tensor_mean(per),
                    _ => self.tensor_sum(per),
                };
            }
        }
        // F32 sibling of the f64 no-grad path above. The composed path used an
        // F64 `full()` constant, so f32 inputs returned an F64 result; compute
        // the same in-dtype formula in one pass, then reduce through the
        // existing reduction API to preserve scalar reduction behavior.
        if matches!(reduction, "none" | "mean" | "sum")
            && !self.tensor_requires_grad(input)?
            && !self.tensor_requires_grad(target)?
            && self.tensor_dtype(input)? == DType::F32
            && self.tensor_dtype(target)? == DType::F32
            && self.tensor_shape(input)? == self.tensor_shape(target)?
        {
            let shape = self.tensor_shape(input)?;
            let built = {
                let xt = self.tensor_tape.tensor(input)?;
                let tt = self.tensor_tape.tensor(target)?;
                if xt.meta().is_contiguous() && tt.meta().is_contiguous() {
                    let xd = xt.contiguous_values_f32()?;
                    let td = tt.contiguous_values_f32()?;
                    if xd.len() == td.len() {
                        use rayon::prelude::*;
                        let out: Vec<f32> = xd
                            .par_iter()
                            .zip(td.par_iter())
                            .map(|(&x, &t)| (1.0_f32 + (-(t * x)).exp()).ln())
                            .collect();
                        Some(out)
                    } else {
                        None
                    }
                } else {
                    None
                }
            };
            if let Some(out) = built {
                let per = self.tensor_variable_f32(out, shape, false)?;
                return match reduction {
                    "none" => Ok(per),
                    "mean" => self.tensor_mean(per),
                    _ => self.tensor_sum(per),
                };
            }
        }
        let prod = self.tensor_mul(target, input)?;
        let neg_prod = self.tensor_neg(prod)?;
        let exp_term = self.tensor_exp(neg_prod)?;
        let ones = self.full_like(exp_term, 1.0, false)?;
        let one_plus_exp = self.tensor_add(ones, exp_term)?;
        let loss = self.tensor_log(one_plus_exp)?;
        match reduction {
            "none" => Ok(loss),
            "mean" => self.tensor_mean(loss),
            "sum" => self.tensor_sum(loss),
            _ => Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "soft_margin_loss: reduction must be 'none', 'mean', or 'sum'",
                },
            ))),
        }
    }

    /// Gaussian negative log-likelihood loss.
    ///
    /// Equivalent to `torch.nn.functional.gaussian_nll_loss`.
    /// Loss = 0.5 * (log(var) + (target - input)^2 / var + log(2π))
    ///
    /// - `input`: mean predictions
    /// - `target`: observed values
    /// - `var`: variance (must be positive)
    /// - `full`: if true, include the constant log(2π) term
    pub fn tensor_gaussian_nll_loss(
        &mut self,
        input: TensorNodeId,
        target: TensorNodeId,
        var: TensorNodeId,
        reduction: &str,
        full: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        // Fused fast path (f64, same-shape input/target/var): per-element Gaussian
        // NLL in one pass, then the reduction — never the ~7 op-graph intermediates.
        // Broadcast / non-f64 fall through.
        let in_shape = self.tensor_shape(input)?;
        if matches!(reduction, "none" | "mean" | "sum")
            && self.tensor_dtype(input)? == DType::F64
            && self.tensor_dtype(target)? == DType::F64
            && self.tensor_dtype(var)? == DType::F64
            && self.tensor_shape(target)? == in_shape
            && self.tensor_shape(var)? == in_shape
        {
            let needs_grad = self.tensor_tape.tensor_requires_grad(input)?
                || self.tensor_tape.tensor_requires_grad(target)?
                || self.tensor_tape.tensor_requires_grad(var)?;
            // No-grad mean/sum: fuse the per-element NLL + reduction into a single
            // scalar with NO retained per-element session tensor (the op-graph path
            // materializes an 8M `per` node every call — on a long-lived session
            // that retention dominates, frankentorch-gmuml). Zero-copy borrow the
            // contiguous inputs (no tensor_values clone), reduce with the SAME
            // kernel tensor_mean/tensor_sum use, so bit-identical to the
            // tensor_mean(per) path. Mirrors smooth_l1's fast path.
            if !needs_grad && matches!(reduction, "mean" | "sum") {
                let x_t = self.tensor_tape.tensor(input)?;
                let t_t = self.tensor_tape.tensor(target)?;
                let v_t = self.tensor_tape.tensor(var)?;
                let xv = x_t
                    .contiguous_values()
                    .map_err(AutogradError::DenseTensor)?;
                let tv = t_t
                    .contiguous_values()
                    .map_err(AutogradError::DenseTensor)?;
                let vv = v_t
                    .contiguous_values()
                    .map_err(AutogradError::DenseTensor)?;
                let out = ft_kernel_cpu::gaussian_nll_forward_f64(xv, tv, vv, full);
                let meta = TensorMeta::from_shape(in_shape.clone(), DType::F64, Device::Cpu);
                let value = if reduction == "mean" {
                    ft_kernel_cpu::mean_tensor_contiguous_f64(&out, &meta).map_err(|e| {
                        AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                    })?
                } else {
                    ft_kernel_cpu::sum_tensor_contiguous_f64(&out, &meta).map_err(|e| {
                        AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                    })?
                };
                return self.tensor_variable(vec![value], vec![1], false);
            }
            let per = if needs_grad {
                let fl = full;
                // Borrowed-inputs autograd: the backward re-reads the live leaf
                // input/target/var from the tape instead of cloning all three
                // into the ctx via save_for_backward (3x full-size clones per
                // call — the dominant grad-path cost for large losses; the
                // session tape never frees them, frankentorch-gmuml/3jmy3).
                self.tensor_apply_function_f64_borrowed_inputs(
                    &[input, target, var],
                    move |_ctx, ins| {
                        let (xv, xs) = ins[0];
                        let (tv, _) = ins[1];
                        let (vv, _) = ins[2];
                        let out = ft_kernel_cpu::gaussian_nll_forward_f64(xv, tv, vv, fl);
                        Ok((out, xs.to_vec()))
                    },
                    move |_ctx, grad_outputs, borrowed| {
                        let dl = grad_outputs[0];
                        let (di, dt, dv) = ft_kernel_cpu::gaussian_nll_backward_f64(
                            dl,
                            borrowed[0].0,
                            borrowed[1].0,
                            borrowed[2].0,
                        );
                        Ok(vec![Some(di), Some(dt), Some(dv)])
                    },
                )?
            } else {
                // Borrow the three contiguous inputs (the kernel only READS them);
                // tensor_values CLONES 3x full-size buffers, which dominated the no-grad
                // 'none' path. Bit-identical (same parallel kernel).
                let built = {
                    let x_t = self.tensor_tape.tensor(input)?;
                    let t_t = self.tensor_tape.tensor(target)?;
                    let v_t = self.tensor_tape.tensor(var)?;
                    if x_t.meta().is_contiguous()
                        && t_t.meta().is_contiguous()
                        && v_t.meta().is_contiguous()
                    {
                        let xv = x_t
                            .contiguous_values()
                            .map_err(AutogradError::DenseTensor)?;
                        let tv = t_t
                            .contiguous_values()
                            .map_err(AutogradError::DenseTensor)?;
                        let vv = v_t
                            .contiguous_values()
                            .map_err(AutogradError::DenseTensor)?;
                        Some(ft_kernel_cpu::gaussian_nll_forward_f64(xv, tv, vv, full))
                    } else {
                        None
                    }
                };
                let out = if let Some(out) = built {
                    out
                } else {
                    let xv = self.tensor_values(input)?;
                    let tv = self.tensor_values_lossy_f64(target)?;
                    let vv = self.tensor_values(var)?;
                    ft_kernel_cpu::gaussian_nll_forward_f64(&xv, &tv, &vv, full)
                };
                self.tensor_variable(out, in_shape.clone(), false)?
            };
            return match reduction {
                "none" => Ok(per),
                "mean" => self.tensor_mean(per),
                _ => self.tensor_sum(per),
            };
        }

        // F32 sibling of the f64 fast path (the asymmetric-dtype gap): there is no f32 kernel, and
        // the compose below upcasts f32 via F64 full() consts (returning F64 — torch keeps f32).
        // Compute the same per-element formula 0.5·(log(var) + (target-input)²/var + c) inline in
        // f32 (f32-native lnf), then reduce via tensor_mean/tensor_sum. Grad / broadcast /
        // non-contiguous / non-float fall through. frankentorch-specf32.
        if matches!(reduction, "none" | "mean" | "sum")
            && self.tensor_dtype(input)? == DType::F32
            && self.tensor_dtype(target)? == DType::F32
            && self.tensor_dtype(var)? == DType::F32
            && self.tensor_shape(target)? == in_shape
            && self.tensor_shape(var)? == in_shape
            && !self.tensor_requires_grad(input)?
            && !self.tensor_requires_grad(target)?
            && !self.tensor_requires_grad(var)?
        {
            let built = {
                let xt = self.tensor_tape.tensor(input)?;
                let tt = self.tensor_tape.tensor(target)?;
                let vt = self.tensor_tape.tensor(var)?;
                if xt.meta().is_contiguous()
                    && tt.meta().is_contiguous()
                    && vt.meta().is_contiguous()
                {
                    let xv = xt.contiguous_values_f32()?;
                    let tv = tt.contiguous_values_f32()?;
                    let vv = vt.contiguous_values_f32()?;
                    if xv.len() == tv.len() && xv.len() == vv.len() {
                        use rayon::prelude::*;
                        let c = if full {
                            (2.0_f32 * std::f32::consts::PI).ln()
                        } else {
                            0.0_f32
                        };
                        let out: Vec<f32> = (0..xv.len())
                            .into_par_iter()
                            .map(|i| {
                                let d = tv[i] - xv[i];
                                0.5 * (vv[i].ln() + d * d / vv[i] + c)
                            })
                            .collect();
                        Some(out)
                    } else {
                        None
                    }
                } else {
                    None
                }
            };
            if let Some(out) = built {
                let per = self.tensor_variable_f32(out, in_shape.clone(), false)?;
                return match reduction {
                    "none" => Ok(per),
                    "mean" => self.tensor_mean(per),
                    _ => self.tensor_sum(per),
                };
            }
        }

        let diff = self.tensor_sub(target, input)?;
        let diff_sq = self.tensor_mul(diff, diff)?;
        let scaled = self.tensor_div(diff_sq, var)?;
        let log_var = self.tensor_log(var)?;
        let term = self.tensor_add(log_var, scaled)?;
        let loss = if full {
            let shape = self.tensor_shape(term)?;
            let log_2pi = self.full(shape, (2.0 * std::f64::consts::PI).ln(), false)?;
            let with_const = self.tensor_add(term, log_2pi)?;
            let half = self.full(self.tensor_shape(with_const)?, 0.5, false)?;
            self.tensor_mul(half, with_const)?
        } else {
            let half = self.full(self.tensor_shape(term)?, 0.5, false)?;
            self.tensor_mul(half, term)?
        };
        match reduction {
            "none" => Ok(loss),
            "mean" => self.tensor_mean(loss),
            "sum" => self.tensor_sum(loss),
            _ => Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "gaussian_nll_loss: reduction must be 'none', 'mean', or 'sum'",
                },
            ))),
        }
    }

    /// Poisson negative log-likelihood loss.
    ///
    /// Equivalent to `torch.nn.functional.poisson_nll_loss`.
    /// Loss = exp(input) - target * input     if log_input=true
    /// Loss = input - target * log(input)     if log_input=false
    ///
    /// - `input`: predicted rate (or log-rate if log_input=true)
    /// - `target`: observed counts (non-negative integers)
    /// - `log_input`: if true, input is log(rate)
    /// - `full`: if true, add Stirling approx of log(target!)
    /// - `eps`: small value for numerical stability when log_input=false
    pub fn tensor_poisson_nll_loss(
        &mut self,
        input: TensorNodeId,
        target: TensorNodeId,
        log_input: bool,
        full: bool,
        eps: f64,
        reduction: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        // No-grad fused fast path (full=false, mean/sum): the compose materialises 3-5 full-size
        // tensors (measured 2.61x SLOWER than torch). Compute the per-element loss in ONE parallel
        // pass — NATIVELY in f32 for f32 input (f32 expf/lnf, matching the f32 compose) — then
        // reduce via the existing tensor_mean/tensor_sum. Grad / full / "none" / shape-mismatch /
        // non-contiguous / non-float fall through. frankentorch-specf32.
        if !full
            && reduction != "none"
            && !self.tensor_requires_grad(input)?
            && !self.tensor_requires_grad(target)?
            && self.tensor_shape(target)? == self.tensor_shape(input)?
        {
            let shape = self.tensor_shape(input)?;
            let dt = self.tensor_dtype(input)?;
            let loss_built: Option<(Option<Vec<f64>>, Option<Vec<f32>>)> = {
                let xt = self.tensor_tape.tensor(input)?;
                let tt = self.tensor_tape.tensor(target)?;
                if xt.meta().is_contiguous()
                    && tt.meta().is_contiguous()
                    && matches!(dt, DType::F32 | DType::F64)
                    && self.tensor_dtype(target)? == dt
                {
                    use rayon::prelude::*;
                    match dt {
                        DType::F32 => {
                            let xv = xt.contiguous_values_f32()?;
                            let zv = tt.contiguous_values_f32()?;
                            if xv.len() == zv.len() {
                                #[allow(clippy::cast_possible_truncation)]
                                let epsf = eps as f32;
                                let l: Vec<f32> = if log_input {
                                    xv.par_iter()
                                        .zip(zv.par_iter())
                                        .map(|(&x, &z)| x.exp() - z * x)
                                        .collect()
                                } else {
                                    xv.par_iter()
                                        .zip(zv.par_iter())
                                        .map(|(&x, &z)| x - z * (x + epsf).ln())
                                        .collect()
                                };
                                Some((None, Some(l)))
                            } else {
                                None
                            }
                        }
                        _ => {
                            let xv = xt.contiguous_values()?;
                            let zv = tt.contiguous_values()?;
                            if xv.len() == zv.len() {
                                let l: Vec<f64> = if log_input {
                                    xv.par_iter()
                                        .zip(zv.par_iter())
                                        .map(|(&x, &z)| x.exp() - z * x)
                                        .collect()
                                } else {
                                    xv.par_iter()
                                        .zip(zv.par_iter())
                                        .map(|(&x, &z)| x - z * (x + eps).ln())
                                        .collect()
                                };
                                Some((Some(l), None))
                            } else {
                                None
                            }
                        }
                    }
                } else {
                    None
                }
            };
            let loss = match loss_built {
                Some((Some(l64), None)) => Some(self.tensor_variable(l64, shape, false)?),
                Some((None, Some(l32))) => Some(self.tensor_variable_f32(l32, shape, false)?),
                _ => None,
            };
            if let Some(loss) = loss {
                return match reduction {
                    "mean" => self.tensor_mean(loss),
                    "sum" => self.tensor_sum(loss),
                    _ => unreachable!("reduction != none guarded above"),
                };
            }
        }

        let loss = if log_input {
            let exp_input = self.tensor_exp(input)?;
            let target_times_input = self.tensor_mul(target, input)?;
            self.tensor_sub(exp_input, target_times_input)?
        } else {
            let shape = self.tensor_shape(input)?;
            let eps_t = self.full(shape, eps, false)?;
            let input_plus_eps = self.tensor_add(input, eps_t)?;
            let log_input_eps = self.tensor_log(input_plus_eps)?;
            let target_log = self.tensor_mul(target, log_input_eps)?;
            self.tensor_sub(input, target_log)?
        };
        let loss = if full {
            let shape = self.tensor_shape(target)?;
            let ones = self.full(shape.clone(), 1.0, false)?;
            let half = self.full(shape.clone(), 0.5, false)?;
            let log_2pi = self.full(shape, (2.0 * std::f64::consts::PI).ln(), false)?;
            let target_plus_1 = self.tensor_add(target, ones)?;
            let log_target_p1 = self.tensor_log(target_plus_1)?;
            let target_log_t = self.tensor_mul(target, log_target_p1)?;
            let stirling_1 = self.tensor_sub(target_log_t, target)?;
            let half_log_2pi_t = self.tensor_mul(half, log_2pi)?;
            let stirling = self.tensor_add(stirling_1, half_log_2pi_t)?;
            self.tensor_add(loss, stirling)?
        } else {
            loss
        };
        match reduction {
            "none" => Ok(loss),
            "mean" => self.tensor_mean(loss),
            "sum" => self.tensor_sum(loss),
            _ => Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "poisson_nll_loss: reduction must be 'none', 'mean', or 'sum'",
                },
            ))),
        }
    }

    /// Margin ranking loss for ranking tasks.
    ///
    /// Equivalent to `torch.nn.functional.margin_ranking_loss`.
    /// Loss = max(0, -y * (x1 - x2) + margin)
    /// where y is +1 if x1 should be ranked higher, -1 otherwise.
    pub fn tensor_margin_ranking_loss(
        &mut self,
        input1: TensorNodeId,
        input2: TensorNodeId,
        target: TensorNodeId,
        margin: f64,
        reduction: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        // No-grad fused fast path. f32 was BROKEN (composed full() consts are F64 -> add/maximum
        // dtype-mismatch on f32). Per-element `max(0, margin - t*(x1-x2))` (NaN-propagating max to
        // match tensor_maximum; margin - t*d == the composed (-(t*d))+margin bit-for-bit), then
        // reduce. f64 had no fast path either -> also accelerated. grad / mixed-dtype / non-
        // contiguous / shape-mismatch fall through to the composed (full_like) path.
        let s1 = self.tensor_shape(input1)?;
        if matches!(reduction, "none" | "mean" | "sum")
            && !self.tensor_requires_grad(input1)?
            && !self.tensor_requires_grad(input2)?
            && !self.tensor_requires_grad(target)?
            && self.tensor_shape(input2)? == s1
            && self.tensor_shape(target)? == s1
        {
            let dt = self.tensor_dtype(input1)?;
            if dt == DType::F64
                && self.tensor_dtype(input2)? == DType::F64
                && self.tensor_dtype(target)? == DType::F64
            {
                let built = {
                    let a = self.tensor_tape.tensor(input1)?;
                    let b = self.tensor_tape.tensor(input2)?;
                    let t = self.tensor_tape.tensor(target)?;
                    if a.meta().is_contiguous()
                        && b.meta().is_contiguous()
                        && t.meta().is_contiguous()
                    {
                        let av = a.contiguous_values()?;
                        let bv = b.contiguous_values()?;
                        let tv = t.contiguous_values()?;
                        if av.len() == bv.len() && av.len() == tv.len() {
                            use rayon::prelude::*;
                            let out: Vec<f64> = (0..av.len())
                                .into_par_iter()
                                .map(|i| {
                                    let wm = margin - tv[i] * (av[i] - bv[i]);
                                    if wm.is_nan() { f64::NAN } else { wm.max(0.0) }
                                })
                                .collect();
                            Some(out)
                        } else {
                            None
                        }
                    } else {
                        None
                    }
                };
                if let Some(out) = built {
                    let per = self.tensor_variable(out, s1, false)?;
                    return match reduction {
                        "none" => Ok(per),
                        "mean" => self.tensor_mean(per),
                        _ => self.tensor_sum(per),
                    };
                }
            } else if dt == DType::F32
                && self.tensor_dtype(input2)? == DType::F32
                && self.tensor_dtype(target)? == DType::F32
            {
                #[allow(clippy::cast_possible_truncation)]
                let mf = margin as f32;
                let built = {
                    let a = self.tensor_tape.tensor(input1)?;
                    let b = self.tensor_tape.tensor(input2)?;
                    let t = self.tensor_tape.tensor(target)?;
                    if a.meta().is_contiguous()
                        && b.meta().is_contiguous()
                        && t.meta().is_contiguous()
                    {
                        let av = a.contiguous_values_f32()?;
                        let bv = b.contiguous_values_f32()?;
                        let tv = t.contiguous_values_f32()?;
                        if av.len() == bv.len() && av.len() == tv.len() {
                            use rayon::prelude::*;
                            let out: Vec<f32> = (0..av.len())
                                .into_par_iter()
                                .map(|i| {
                                    let wm = mf - tv[i] * (av[i] - bv[i]);
                                    if wm.is_nan() { f32::NAN } else { wm.max(0.0) }
                                })
                                .collect();
                            Some(out)
                        } else {
                            None
                        }
                    } else {
                        None
                    }
                };
                if let Some(out) = built {
                    let per = self.tensor_variable_f32(out, s1, false)?;
                    return match reduction {
                        "none" => Ok(per),
                        "mean" => self.tensor_mean(per),
                        _ => self.tensor_sum(per),
                    };
                }
            }
        }
        let diff = self.tensor_sub(input1, input2)?;
        let target_diff = self.tensor_mul(target, diff)?;
        let neg_target_diff = self.tensor_neg(target_diff)?;
        // full_like (not full(), always F64) so the composed GRAD f32 path works; f64 unchanged.
        let margin_t = self.full_like(neg_target_diff, margin, false)?;
        let with_margin = self.tensor_add(neg_target_diff, margin_t)?;
        let zeros = self.full_like(with_margin, 0.0, false)?;
        let loss = self.tensor_maximum(zeros, with_margin)?;
        match reduction {
            "none" => Ok(loss),
            "mean" => self.tensor_mean(loss),
            "sum" => self.tensor_sum(loss),
            _ => Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "margin_ranking_loss: reduction must be 'none', 'mean', or 'sum'",
                },
            ))),
        }
    }

    /// Cosine embedding loss for similarity learning.
    ///
    /// Equivalent to `torch.nn.functional.cosine_embedding_loss`.
    /// For target=1: loss = 1 - cos(x1, x2)
    /// For target=-1: loss = max(0, cos(x1, x2) - margin)
    pub fn tensor_cosine_embedding_loss(
        &mut self,
        input1: TensorNodeId,
        input2: TensorNodeId,
        target: TensorNodeId,
        margin: f64,
        reduction: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        // Compute cosine similarity (assuming last dimension)
        let shape1 = self.tensor_shape(input1)?;
        let dim = shape1.len() - 1;

        // F32 no-grad fused fast path. The composed path computes cos via cosine_similarity
        // then mixes it with self.full[F64] ones/margin/zeros and `tensor_eq(target, ones[F64])`
        // -> on f32 input that comparison hits a dtype mismatch (target is F32, ones is F64)
        // and the whole op ERRORS (a pre-existing f32 bug; torch.cosine_embedding_loss(f32)->f32).
        // Compute per row: cos = dot / max(||x1||*||x2||, eps); loss = (y==1) ? 1-cos :
        // max(0, cos-margin); then reduce. eps=1e-8 matches the composed cosine_similarity call.
        // F64 / grad / non-contiguous fall through unchanged (the F64 golden path is untouched).
        // frankentorch-cosemb-f32-fused.
        if !shape1.is_empty()
            && *shape1.last().unwrap() > 0
            && matches!(reduction, "none" | "sum" | "mean")
            && self.tensor_dtype(input1)? == DType::F32
            && self.tensor_dtype(input2)? == DType::F32
            && self.tensor_dtype(target)? == DType::F32
            && shape1 == self.tensor_shape(input2)?
            && !self.tensor_requires_grad(input1)?
            && !self.tensor_requires_grad(input2)?
            && !self.tensor_requires_grad(target)?
        {
            let d = *shape1.last().unwrap();
            let outer: usize = shape1[..shape1.len() - 1].iter().product();
            let tnumel: usize = self.tensor_shape(target)?.iter().product();
            let contiguous = self.tensor_tape.tensor(input1)?.meta().is_contiguous()
                && self.tensor_tape.tensor(input2)?.meta().is_contiguous()
                && self.tensor_tape.tensor(target)?.meta().is_contiguous();
            if contiguous && tnumel == outer {
                #[allow(clippy::cast_possible_truncation)]
                let (mf, epsf) = (margin as f32, 1e-8f32);
                let mut out_shape: Vec<usize> = shape1[..shape1.len() - 1].to_vec();
                if out_shape.is_empty() {
                    out_shape.push(1);
                }
                let rows: Vec<f32> = {
                    let v1 = self.tensor_tape.tensor(input1)?.contiguous_values_f32()?;
                    let v2 = self.tensor_tape.tensor(input2)?.contiguous_values_f32()?;
                    let ty = self.tensor_tape.tensor(target)?.contiguous_values_f32()?;
                    use rayon::prelude::*;
                    (0..outer)
                        .into_par_iter()
                        .map(|r| {
                            let b = r * d;
                            let (mut dot, mut s1, mut s2) = (0.0f32, 0.0f32, 0.0f32);
                            for k in 0..d {
                                let a = v1[b + k];
                                let c = v2[b + k];
                                dot += a * c;
                                s1 += a * a;
                                s2 += c * c;
                            }
                            let cos = dot / (s1.sqrt() * s2.sqrt()).max(epsf);
                            if ty[r] == 1.0 {
                                1.0 - cos
                            } else {
                                (cos - mf).max(0.0)
                            }
                        })
                        .collect()
                };
                return match reduction {
                    "none" => self.tensor_variable_f32(rows, out_shape, false),
                    "sum" => {
                        let s: f32 = rows.iter().sum();
                        self.tensor_variable_f32(vec![s], vec![1], false)
                    }
                    _ => {
                        let s: f32 = rows.iter().sum();
                        #[allow(clippy::cast_precision_loss)]
                        let m = s / outer as f32;
                        self.tensor_variable_f32(vec![m], vec![1], false)
                    }
                };
            }
        }

        let cos_sim = self.tensor_cosine_similarity(input1, input2, dim, 1e-8)?;
        let shape = self.tensor_shape(cos_sim)?;
        let ones = self.full(shape.clone(), 1.0, false)?;
        let pos_loss = self.tensor_sub(ones, cos_sim)?;
        let margin_t = self.full(shape.clone(), margin, false)?;
        let neg_margin = self.tensor_sub(cos_sim, margin_t)?;
        let zeros = self.full(shape.clone(), 0.0, false)?;
        let neg_loss = self.tensor_maximum(zeros, neg_margin)?;
        let mask_pos = self.tensor_eq(target, ones)?;
        let loss = self.tensor_where(mask_pos, pos_loss, neg_loss)?;
        match reduction {
            "none" => Ok(loss),
            "mean" => self.tensor_mean(loss),
            "sum" => self.tensor_sum(loss),
            _ => Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "cosine_embedding_loss: reduction must be 'none', 'mean', or 'sum'",
                },
            ))),
        }
    }

    /// Triplet margin loss for metric learning.
    ///
    /// Equivalent to `torch.nn.functional.triplet_margin_loss`.
    /// Loss = max(0, d(anchor, positive) - d(anchor, negative) + margin)
    pub fn tensor_triplet_margin_loss(
        &mut self,
        anchor: TensorNodeId,
        positive: TensorNodeId,
        negative: TensorNodeId,
        margin: f64,
        p: f64,
        reduction: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_triplet_margin_loss_swap(
            anchor, positive, negative, margin, p, false, reduction,
        )
    }

    /// `torch.nn.functional.triplet_margin_loss` with the distance-`swap` option.
    /// loss = relu(d(a,p) − d_neg + margin), where the p-norm distances are taken
    /// along the last dim. When `swap` is true the negative distance uses the
    /// closer of anchor-negative and positive-negative,
    /// `d_neg = min(d(a, n), d(p, n))` (the "anchor swap" of Wang et al. 2014),
    /// which `tensor_triplet_margin_loss` leaves false.
    pub fn tensor_triplet_margin_loss_swap(
        &mut self,
        anchor: TensorNodeId,
        positive: TensorNodeId,
        negative: TensorNodeId,
        margin: f64,
        p: f64,
        swap: bool,
        reduction: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        // No-grad fused fast path (f32 + f64). The composed path below routes each
        // distance through tensor_norm_dim (libm `powf` even for p=2) plus 2x
        // `self.full(...)` (always F64 -> f32 input returned F64, a dtype bug;
        // torch->f32) plus several full-size allocs. For a contiguous same-shape triplet
        // reducing over the LAST dim with grad off, compute relu(d_pos - d_neg + margin)
        // per row in one parallel pass (eps=0, matching the existing norm + the
        // eps-tolerant ft-nn golden). Grad / non-contiguous / mixed-dtype / other
        // reductions fall through. frankentorch-triplet-fused.
        let a_shape = self.tensor_shape(anchor)?;
        if !a_shape.is_empty()
            && *a_shape.last().unwrap() > 0
            && matches!(reduction, "none" | "sum" | "mean")
            && a_shape == self.tensor_shape(positive)?
            && a_shape == self.tensor_shape(negative)?
            && !self.tensor_requires_grad(anchor)?
            && !self.tensor_requires_grad(positive)?
            && !self.tensor_requires_grad(negative)?
        {
            let dim_size = *a_shape.last().unwrap();
            let outer: usize = a_shape[..a_shape.len() - 1].iter().product();
            let p2 = p == 2.0;
            let dt = self.tensor_dtype(anchor)?;
            let same = dt == self.tensor_dtype(positive)? && dt == self.tensor_dtype(negative)?;
            let mut none_shape: Vec<usize> = a_shape[..a_shape.len() - 1].to_vec();
            if none_shape.is_empty() {
                none_shape.push(1);
            }
            let contiguous = self.tensor_tape.tensor(anchor)?.meta().is_contiguous()
                && self.tensor_tape.tensor(positive)?.meta().is_contiguous()
                && self.tensor_tape.tensor(negative)?.meta().is_contiguous();
            if same && contiguous && dt == DType::F32 {
                #[allow(clippy::cast_possible_truncation)]
                let (mf, pf) = (margin as f32, p as f32);
                let rows: Vec<f32> = {
                    let av = self.tensor_tape.tensor(anchor)?.contiguous_values_f32()?;
                    let pv = self.tensor_tape.tensor(positive)?.contiguous_values_f32()?;
                    let nv = self.tensor_tape.tensor(negative)?.contiguous_values_f32()?;
                    use rayon::prelude::*;
                    (0..outer)
                        .into_par_iter()
                        .map(|r| {
                            let b = r * dim_size;
                            let (mut sp, mut sn, mut spn) = (0.0f32, 0.0f32, 0.0f32);
                            for k in 0..dim_size {
                                let dp = av[b + k] - pv[b + k];
                                let dn = av[b + k] - nv[b + k];
                                if p2 {
                                    sp += dp * dp;
                                    sn += dn * dn;
                                } else {
                                    sp += dp.abs().powf(pf);
                                    sn += dn.abs().powf(pf);
                                }
                                if swap {
                                    let dpn = pv[b + k] - nv[b + k];
                                    if p2 {
                                        spn += dpn * dpn;
                                    } else {
                                        spn += dpn.abs().powf(pf);
                                    }
                                }
                            }
                            let dpos = if p2 { sp.sqrt() } else { sp.powf(1.0 / pf) };
                            let mut dneg = if p2 { sn.sqrt() } else { sn.powf(1.0 / pf) };
                            if swap {
                                let dpn = if p2 { spn.sqrt() } else { spn.powf(1.0 / pf) };
                                dneg = dneg.min(dpn);
                            }
                            (dpos - dneg + mf).max(0.0)
                        })
                        .collect()
                };
                return match reduction {
                    "none" => self.tensor_variable_f32(rows, none_shape, false),
                    "sum" => {
                        let s: f32 = rows.iter().sum();
                        self.tensor_variable_f32(vec![s], vec![1], false)
                    }
                    _ => {
                        let s: f32 = rows.iter().sum();
                        #[allow(clippy::cast_precision_loss)]
                        let m = s / outer as f32;
                        self.tensor_variable_f32(vec![m], vec![1], false)
                    }
                };
            } else if same && contiguous && dt == DType::F64 {
                let rows: Vec<f64> = {
                    let av = self.tensor_tape.tensor(anchor)?.contiguous_values()?;
                    let pv = self.tensor_tape.tensor(positive)?.contiguous_values()?;
                    let nv = self.tensor_tape.tensor(negative)?.contiguous_values()?;
                    use rayon::prelude::*;
                    (0..outer)
                        .into_par_iter()
                        .map(|r| {
                            let b = r * dim_size;
                            let (mut sp, mut sn, mut spn) = (0.0f64, 0.0f64, 0.0f64);
                            for k in 0..dim_size {
                                let dp = av[b + k] - pv[b + k];
                                let dn = av[b + k] - nv[b + k];
                                if p2 {
                                    sp += dp * dp;
                                    sn += dn * dn;
                                } else {
                                    sp += dp.abs().powf(p);
                                    sn += dn.abs().powf(p);
                                }
                                if swap {
                                    let dpn = pv[b + k] - nv[b + k];
                                    if p2 {
                                        spn += dpn * dpn;
                                    } else {
                                        spn += dpn.abs().powf(p);
                                    }
                                }
                            }
                            let dpos = if p2 { sp.sqrt() } else { sp.powf(1.0 / p) };
                            let mut dneg = if p2 { sn.sqrt() } else { sn.powf(1.0 / p) };
                            if swap {
                                let dpn = if p2 { spn.sqrt() } else { spn.powf(1.0 / p) };
                                dneg = dneg.min(dpn);
                            }
                            (dpos - dneg + margin).max(0.0)
                        })
                        .collect()
                };
                return match reduction {
                    "none" => self.tensor_variable(rows, none_shape, false),
                    "sum" => {
                        let s: f64 = rows.iter().sum();
                        self.tensor_variable(vec![s], vec![1], false)
                    }
                    _ => {
                        let s: f64 = rows.iter().sum();
                        #[allow(clippy::cast_precision_loss)]
                        let m = s / outer as f64;
                        self.tensor_variable(vec![m], vec![1], false)
                    }
                };
            }
        }

        let diff_pos = self.tensor_sub(anchor, positive)?;
        let diff_neg = self.tensor_sub(anchor, negative)?;
        let shape = self.tensor_shape(diff_pos)?;
        let dim = shape.len() - 1;
        let d_pos = self.tensor_norm_dim(diff_pos, p, dim)?;
        let d_neg = self.tensor_norm_dim(diff_neg, p, dim)?;
        let d_neg = if swap {
            // d_neg = min(d(anchor, negative), d(positive, negative))
            let diff_pn = self.tensor_sub(positive, negative)?;
            let d_pn = self.tensor_norm_dim(diff_pn, p, dim)?;
            self.tensor_minimum(d_neg, d_pn)?
        } else {
            d_neg
        };
        let diff = self.tensor_sub(d_pos, d_neg)?;
        let margin_shape = self.tensor_shape(diff)?;
        let margin_t = self.full(margin_shape.clone(), margin, false)?;
        let with_margin = self.tensor_add(diff, margin_t)?;
        let zeros = self.full(margin_shape, 0.0, false)?;
        let loss = self.tensor_maximum(zeros, with_margin)?;
        match reduction {
            "none" => Ok(loss),
            "mean" => self.tensor_mean(loss),
            "sum" => self.tensor_sum(loss),
            _ => Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "triplet_margin_loss: reduction must be 'none', 'mean', or 'sum'",
                },
            ))),
        }
    }

    /// Connectionist Temporal Classification loss.
    ///
    /// Equivalent to `torch.nn.functional.ctc_loss`.
    /// Used for sequence-to-sequence problems where alignment is unknown.
    ///
    /// - `log_probs`: Log probabilities, shape (T, N, C) - time, batch, classes
    /// - `targets`: Target sequences concatenated, shape (sum of target lengths,)
    /// - `input_lengths`: Length of each input sequence, shape (N,)
    /// - `target_lengths`: Length of each target sequence, shape (N,)
    /// - `blank`: Index of the blank label (default 0)
    /// - `zero_infinity`: If true, infinities in loss are zeroed
    pub fn tensor_ctc_loss(
        &mut self,
        log_probs: TensorNodeId,
        targets: TensorNodeId,
        input_lengths: TensorNodeId,
        target_lengths: TensorNodeId,
        blank: usize,
        reduction: &str,
        zero_infinity: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        let lp_shape = self.tensor_shape(log_probs)?;
        if lp_shape.len() != 3 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "ctc_loss: log_probs must be 3D (T, N, C)",
                },
            )));
        }
        let t_len = lp_shape[0];
        let batch_size = lp_shape[1];
        let num_classes = lp_shape[2];
        if blank >= num_classes {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "ctc_loss: blank index out of range",
                },
            )));
        }
        let tgt_vals = self.tensor_values(targets)?;
        let in_lens = self.tensor_values(input_lengths)?;
        let tgt_lens = self.tensor_values(target_lengths)?;
        if in_lens.len() != batch_size || tgt_lens.len() != batch_size {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "ctc_loss: length arrays must match batch size",
                },
            )));
        }
        // Route through apply_function so the gradient reaches `log_probs`
        // (targets and the length arrays are integer/non-differentiable). The
        // CTC gradient w.r.t. log_probs is the negative occupation density
        // d(-logZ)/d log_probs[t][k] = -gamma_t(k), where gamma is the sum over
        // CTC states s with label(s)=k of the forward-backward occupation
        // alpha_t(s)*beta_t(s)/Z. We recompute alpha (matching the forward) and
        // beta (the time-reversed recursion) in the backward pass.
        let tgt_vals_bwd = tgt_vals.clone();
        let in_lens_bwd = in_lens.clone();
        let tgt_lens_bwd = tgt_lens.clone();
        // Retained for the "mean" reduction, which divides each per-batch loss
        // by its target length (clamped to >= 1) before averaging (torch parity).
        let tgt_lens_red = tgt_lens.clone();
        // Batch elements are independent CTC problems; process them in parallel
        // once the batch is large enough to amortize rayon dispatch. Serial below
        // this gate keeps small-batch (and the lib unit tests) on the exact same
        // per-b closure, so parallel == serial bit-for-bit by construction.
        const CTC_PARALLEL_MIN: usize = 4;
        let loss = self.tensor_apply_function(
            &[log_probs],
            move |ctx, inputs| {
                let (lp_vals, _shape) = inputs[0];
                // Per-batch target offsets (prefix sum) so each b's target slice is
                // known without the serial running accumulator — this decouples the
                // batch elements so they can be processed in parallel.
                let mut tgt_offsets = Vec::with_capacity(batch_size);
                let mut acc = 0usize;
                for b in 0..batch_size {
                    tgt_offsets.push(acc);
                    acc += tgt_lens[b] as usize;
                }
                // Validate input lengths up front so the per-batch map is infallible.
                for b in 0..batch_size {
                    if in_lens[b] as usize > t_len {
                        return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                            ft_dispatch::DispatchKeyError::IncompatibleSet {
                                reason: "ctc_loss: input length exceeds time dimension",
                            },
                        )));
                    }
                }
                // Each batch element's CTC alpha recursion is fully independent, so
                // compute per-b loss in parallel. Bit-identical to the serial loop:
                // the alpha DP + final_score is computed the same way per b, and the
                // losses Vec is indexed by b so ordering is preserved.
                let compute_b = |b: usize| -> f64 {
                    let in_len = in_lens[b] as usize;
                    let tgt_len = tgt_lens[b] as usize;
                    let target_seq: Vec<usize> = tgt_vals[tgt_offsets[b]..tgt_offsets[b] + tgt_len]
                        .iter()
                        .map(|&x| x as usize)
                        .collect();
                    // CTC forward pass with alpha probabilities
                    // State space: 2*L + 1 where L is target length (interleaved with blanks)
                    let state_len = 2 * tgt_len + 1;
                    let neg_inf = f64::NEG_INFINITY;
                    let mut alpha = vec![vec![neg_inf; state_len]; in_len + 1];
                    alpha[0][0] = 0.0; // Start at blank
                    if state_len > 1 {
                        alpha[0][1] = 0.0; // Or first label
                    }
                    let get_label = |s: usize| -> usize {
                        if s.is_multiple_of(2) {
                            blank
                        } else {
                            target_seq[s / 2]
                        }
                    };
                    for t in 0..in_len {
                        let lp_offset = (t * batch_size + b) * num_classes;
                        for s in 0..state_len {
                            let label = get_label(s);
                            let lp = lp_vals[lp_offset + label];
                            let mut score = alpha[t][s];
                            if s > 0 {
                                score = log_sum_exp(score, alpha[t][s - 1]);
                            }
                            if s > 1 && get_label(s) != get_label(s - 2) {
                                score = log_sum_exp(score, alpha[t][s - 2]);
                            }
                            alpha[t + 1][s] = score + lp;
                        }
                    }
                    let final_score = if state_len > 1 {
                        log_sum_exp(alpha[in_len][state_len - 1], alpha[in_len][state_len - 2])
                    } else if state_len == 1 {
                        alpha[in_len][0]
                    } else {
                        0.0
                    };
                    let loss = -final_score;
                    if zero_infinity && !loss.is_finite() {
                        0.0
                    } else {
                        loss
                    }
                };
                let losses: Vec<f64> = if batch_size >= CTC_PARALLEL_MIN {
                    use rayon::prelude::*;
                    (0..batch_size).into_par_iter().map(compute_b).collect()
                } else {
                    (0..batch_size).map(compute_b).collect()
                };
                ctx.save_for_backward(lp_vals.to_vec(), vec![t_len, batch_size, num_classes]);
                Ok((losses, vec![batch_size]))
            },
            move |ctx, grad_outputs| {
                let g = grad_outputs[0];
                let saved = ctx.saved_tensors();
                let lp_vals = &saved[0];
                let neg_inf = f64::NEG_INFINITY;
                // Per-batch target offsets (prefix sum) so each b is self-contained.
                let mut tgt_offsets = Vec::with_capacity(batch_size);
                let mut acc0 = 0usize;
                for b in 0..batch_size {
                    tgt_offsets.push(acc0);
                    acc0 += tgt_lens_bwd[b] as usize;
                }
                // Each batch element writes to DISJOINT grad columns (the flat index
                // carries `+ b`) and its alpha/beta recursion is independent, so
                // compute each b's dense [in_len, num_classes] gradient block in
                // parallel then scatter. Bit-identical to the serial loop: the
                // per-(t) state accumulation order (s = 0..state_len) is preserved
                // inside each block, and blocks land at the same strided positions.
                let compute_grad_b = |b: usize| -> Option<(usize, Vec<f64>)> {
                    let in_len = in_lens_bwd[b] as usize;
                    let tgt_len = tgt_lens_bwd[b] as usize;
                    let gb = g[b];
                    if in_len == 0 || gb == 0.0 {
                        return None;
                    }
                    let target_seq: Vec<usize> = tgt_vals_bwd
                        [tgt_offsets[b]..tgt_offsets[b] + tgt_len]
                        .iter()
                        .map(|&x| x as usize)
                        .collect();
                    let state_len = 2 * tgt_len + 1;
                    let get_label = |s: usize| -> usize {
                        if s.is_multiple_of(2) {
                            blank
                        } else {
                            target_seq[s / 2]
                        }
                    };
                    // Forward variable alpha (A_t(s) = alpha[t+1][s]).
                    let mut alpha = vec![vec![neg_inf; state_len]; in_len + 1];
                    alpha[0][0] = 0.0;
                    if state_len > 1 {
                        alpha[0][1] = 0.0;
                    }
                    for t in 0..in_len {
                        let lp_offset = (t * batch_size + b) * num_classes;
                        for s in 0..state_len {
                            let lp = lp_vals[lp_offset + get_label(s)];
                            let mut score = alpha[t][s];
                            if s > 0 {
                                score = log_sum_exp(score, alpha[t][s - 1]);
                            }
                            if s > 1 && get_label(s) != get_label(s - 2) {
                                score = log_sum_exp(score, alpha[t][s - 2]);
                            }
                            alpha[t + 1][s] = score + lp;
                        }
                    }
                    let logz = if state_len > 1 {
                        log_sum_exp(alpha[in_len][state_len - 1], alpha[in_len][state_len - 2])
                    } else {
                        alpha[in_len][0]
                    };
                    if !logz.is_finite() {
                        // Infeasible alignment / zeroed infinity -> no gradient.
                        return None;
                    }
                    // Backward variable beta (B_t(s), emission at t included).
                    let mut beta = vec![vec![neg_inf; state_len]; in_len];
                    let last_off = ((in_len - 1) * batch_size + b) * num_classes;
                    beta[in_len - 1][state_len - 1] = lp_vals[last_off + get_label(state_len - 1)];
                    if state_len > 1 {
                        beta[in_len - 1][state_len - 2] =
                            lp_vals[last_off + get_label(state_len - 2)];
                    }
                    for t in (0..in_len.saturating_sub(1)).rev() {
                        let lp_offset = (t * batch_size + b) * num_classes;
                        for s in 0..state_len {
                            let mut acc = beta[t + 1][s];
                            if s + 1 < state_len {
                                acc = log_sum_exp(acc, beta[t + 1][s + 1]);
                            }
                            if s + 2 < state_len && get_label(s + 2) != get_label(s) {
                                acc = log_sum_exp(acc, beta[t + 1][s + 2]);
                            }
                            if acc > neg_inf {
                                beta[t][s] = lp_vals[lp_offset + get_label(s)] + acc;
                            }
                        }
                    }
                    // Dense per-b grad block [in_len, num_classes], accumulated in the
                    // SAME (t, s) order as the serial version.
                    // grad log_probs[t][k] = gb * (-gamma_t(k)),
                    // gamma_t(s) = exp(alpha_t(s) + beta_t(s) - y_t(label(s)) - logZ).
                    let mut dense = vec![0.0f64; in_len * num_classes];
                    for t in 0..in_len {
                        let lp_offset = (t * batch_size + b) * num_classes;
                        let dbase = t * num_classes;
                        for s in 0..state_len {
                            let a = alpha[t + 1][s];
                            let bta = beta[t][s];
                            if a == neg_inf || bta == neg_inf {
                                continue;
                            }
                            let k = get_label(s);
                            let occ = (a + bta - lp_vals[lp_offset + k] - logz).exp();
                            dense[dbase + k] -= gb * occ;
                        }
                    }
                    Some((in_len, dense))
                };
                let per_b: Vec<Option<(usize, Vec<f64>)>> = if batch_size >= CTC_PARALLEL_MIN {
                    use rayon::prelude::*;
                    (0..batch_size)
                        .into_par_iter()
                        .map(compute_grad_b)
                        .collect()
                } else {
                    (0..batch_size).map(compute_grad_b).collect()
                };
                let mut grad = vec![0.0f64; t_len * batch_size * num_classes];
                for (b, item) in per_b.into_iter().enumerate() {
                    if let Some((in_len, dense)) = item {
                        for t in 0..in_len {
                            let dst = (t * batch_size + b) * num_classes;
                            let src = t * num_classes;
                            grad[dst..dst + num_classes]
                                .copy_from_slice(&dense[src..src + num_classes]);
                        }
                    }
                }
                Ok(vec![Some(grad)])
            },
        )?;
        match reduction {
            "none" => Ok(loss),
            "sum" => self.tensor_sum(loss),
            "mean" => {
                // torch divides each per-batch loss by its target length
                // (clamped to a minimum of 1 to avoid division by zero for
                // empty targets), then averages over the batch. The divisor is
                // a non-differentiable constant, so autograd scales each
                // -gamma gradient by 1/(N * L_b) as required.
                let divisors: Vec<f64> = tgt_lens_red
                    .iter()
                    .map(|&l| (l as usize).max(1) as f64)
                    .collect();
                let div_t = self.tensor_variable(divisors, vec![batch_size], false)?;
                let scaled = self.tensor_div(loss, div_t)?;
                self.tensor_mean(scaled)
            }
            _ => Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "ctc_loss: reduction must be 'none', 'mean', or 'sum'",
                },
            ))),
        }
    }

    /// Multi-class margin loss (SVM-style).
    ///
    /// Equivalent to `torch.nn.functional.multi_margin_loss`.
    /// Loss = sum_j max(0, margin - x[y] + x[j])^p / C for j != y
    /// where C is the number of classes.
    ///
    /// - `input`: Shape (N, C), raw scores for each class
    /// - `target`: Shape (N,), target class indices
    /// - `p`: Power (1 or 2)
    /// - `margin`: Margin value (default 1.0)
    /// - `weight`: Optional per-class weights, shape (C,)
    pub fn tensor_multi_margin_loss(
        &mut self,
        input: TensorNodeId,
        target: TensorNodeId,
        p: usize,
        margin: f64,
        weight: Option<TensorNodeId>,
        reduction: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        if p != 1 && p != 2 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "multi_margin_loss: p must be 1 or 2",
                },
            )));
        }
        let input_shape = self.tensor_shape(input)?;
        let target_shape = self.tensor_shape(target)?;
        if input_shape.len() != 2 || target_shape.len() != 1 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "multi_margin_loss: input must be 2D (N, C), target must be 1D (N,)",
                },
            )));
        }
        let n = input_shape[0];
        let c = input_shape[1];
        if target_shape[0] != n {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "multi_margin_loss: batch size mismatch",
                },
            )));
        }
        let target_vals = self.tensor_values_lossy_f64(target)?;
        let weights = if let Some(w) = weight {
            let w_shape = self.tensor_shape(w)?;
            if w_shape.len() != 1 || w_shape[0] != c {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "multi_margin_loss: weight must be 1D with length C",
                    },
                )));
            }
            Some(self.tensor_values(w)?)
        } else {
            None
        };

        // F32 no-grad fused fast path. The apply_function path below upcasts the f32 input to
        // f64, runs the O(N*C) hinge SERIALLY, and clones the input for backward — measured ~16x
        // SLOWER than torch on f32 ([200k,128]). Borrow the f32 storage, parallelize over the N
        // samples, compute the per-sample multi-margin in f32, output F32 (same per-sample math
        // as the composed closure; weight is indexed by the true class y, treated as a constant —
        // the composed path only differentiates w.r.t. input). Grad / non-contiguous / non-F32
        // and other reductions fall through unchanged. frankentorch-multimargin-f32-fused.
        if self.tensor_dtype(input)? == DType::F32
            && !self.tensor_requires_grad(input)?
            && matches!(reduction, "none" | "sum" | "mean")
            && self.tensor_tape.tensor(input)?.meta().is_contiguous()
        {
            for &tv in target_vals.iter() {
                if (tv as usize) >= c {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "multi_margin_loss: target class index out of range",
                        },
                    )));
                }
            }
            #[allow(clippy::cast_possible_truncation)]
            let marginf = margin as f32;
            let p1 = p == 1;
            let wf: Option<Vec<f32>> = weights
                .as_ref()
                .map(|ws| ws.iter().map(|&w| w as f32).collect());
            let rows: Vec<f32> = {
                let v = self.tensor_tape.tensor(input)?.contiguous_values_f32()?;
                use rayon::prelude::*;
                (0..n)
                    .into_par_iter()
                    .map(|i| {
                        let y = target_vals[i] as usize;
                        let x_y = v[i * c + y];
                        let wy = wf.as_ref().map_or(1.0_f32, |ws| ws[y]);
                        let mut sum = 0.0_f32;
                        for j in 0..c {
                            if j != y {
                                let mt = marginf - x_y + v[i * c + j];
                                if mt > 0.0 {
                                    let lj = if p1 { mt } else { mt * mt };
                                    sum += wy * lj;
                                }
                            }
                        }
                        #[allow(clippy::cast_precision_loss)]
                        let out = sum / c as f32;
                        out
                    })
                    .collect()
            };
            return match reduction {
                "none" => self.tensor_variable_f32(rows, vec![n], false),
                "sum" => {
                    let s: f32 = rows.iter().sum();
                    self.tensor_variable_f32(vec![s], vec![1], false)
                }
                _ => {
                    let s: f32 = rows.iter().sum();
                    #[allow(clippy::cast_precision_loss)]
                    let m = s / n as f32;
                    self.tensor_variable_f32(vec![m], vec![1], false)
                }
            };
        }

        // F64 no-grad fast path (asymmetric-dtype mirror of the f32 path above): the apply_function
        // path below runs the O(N*C) hinge SERIALLY and clones `input` twice (apply_function's
        // materialized `inputs` + save_for_backward's to_vec) — all dead in no-grad. Borrow the f64
        // storage and parallelize the per-sample multi-margin over N, then reduce via the SAME
        // tensor_sum/tensor_mean the composed path uses (bit-exact pairwise reduction). Each row is
        // bit-identical to the closure's per-sample loss (same j-ascending accumulation, same
        // `w*loss_j` where w = weight[true class], treated as a constant). Grad / non-contiguous /
        // other reductions fall through.
        if self.tensor_dtype(input)? == DType::F64
            && !self.tensor_requires_grad(input)?
            && matches!(reduction, "none" | "sum" | "mean")
            && self.tensor_tape.tensor(input)?.meta().is_contiguous()
        {
            for &tv in target_vals.iter() {
                if (tv as usize) >= c {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "multi_margin_loss: target class index out of range",
                        },
                    )));
                }
            }
            let p1 = p == 1;
            let rows: Vec<f64> = {
                let v = self.tensor_tape.tensor(input)?.contiguous_values()?;
                use rayon::prelude::*;
                (0..n)
                    .into_par_iter()
                    .map(|i| {
                        let y = target_vals[i] as usize;
                        let x_y = v[i * c + y];
                        let wy = weights.as_ref().map_or(1.0_f64, |ws| ws[y]);
                        let mut sum = 0.0_f64;
                        for j in 0..c {
                            if j != y {
                                let mt = margin - x_y + v[i * c + j];
                                if mt > 0.0 {
                                    let lj = if p1 { mt } else { mt * mt };
                                    sum += wy * lj;
                                }
                            }
                        }
                        sum / c as f64
                    })
                    .collect()
            };
            let loss_none = self.tensor_variable(rows, vec![n], false)?;
            return match reduction {
                "none" => Ok(loss_none),
                "sum" => self.tensor_sum(loss_none),
                _ => self.tensor_mean(loss_none),
            };
        }

        // Route through apply_function so the gradient reaches `input` (target is
        // an integer class index, non-differentiable). The hinge term
        // `t = margin - x_y + x_j > 0` has subgradient w_y/C * d(t^p): for p=1
        // that is +1 to x_j and -1 to x_y; for p=2 it is 2t scaled likewise.
        let target_for_backward = target_vals.clone();
        let weights_for_backward = weights.clone();
        let loss = self.tensor_apply_function(
            &[input],
            move |ctx, inputs| {
                let (input_vals, _shape) = inputs[0];
                let mut losses = Vec::with_capacity(n);
                for i in 0..n {
                    let y = target_vals[i] as usize;
                    if y >= c {
                        return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                            ft_dispatch::DispatchKeyError::IncompatibleSet {
                                reason: "multi_margin_loss: target class index out of range",
                            },
                        )));
                    }
                    let x_y = input_vals[i * c + y];
                    let mut sum = 0.0;
                    for j in 0..c {
                        if j != y {
                            let x_j = input_vals[i * c + j];
                            let margin_term = margin - x_y + x_j;
                            if margin_term > 0.0 {
                                let loss_j = if p == 1 {
                                    margin_term
                                } else {
                                    margin_term * margin_term
                                };
                                let w = weights.as_ref().map_or(1.0, |ws| ws[y]);
                                sum += w * loss_j;
                            }
                        }
                    }
                    losses.push(sum / c as f64);
                }
                ctx.save_for_backward(input_vals.to_vec(), vec![n, c]);
                Ok((losses, vec![n]))
            },
            move |ctx, grad_outputs| {
                let g = grad_outputs[0];
                let saved = ctx.saved_tensors();
                let input_vals = &saved[0];
                let inv_c = 1.0 / c as f64;
                let mut grad_input = vec![0.0; n * c];
                for i in 0..n {
                    let gi = g[i];
                    if gi == 0.0 {
                        continue;
                    }
                    let y = target_for_backward[i] as usize;
                    if y >= c {
                        continue;
                    }
                    let x_y = input_vals[i * c + y];
                    let w = weights_for_backward.as_ref().map_or(1.0, |ws| ws[y]);
                    for j in 0..c {
                        if j != y {
                            let x_j = input_vals[i * c + j];
                            let t = margin - x_y + x_j;
                            if t > 0.0 {
                                let dp = if p == 1 { 1.0 } else { 2.0 * t };
                                let factor = gi * inv_c * w * dp;
                                grad_input[i * c + j] += factor;
                                grad_input[i * c + y] -= factor;
                            }
                        }
                    }
                }
                Ok(vec![Some(grad_input)])
            },
        )?;
        match reduction {
            "none" => Ok(loss),
            "mean" => self.tensor_mean(loss),
            "sum" => self.tensor_sum(loss),
            _ => Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "multi_margin_loss: reduction must be 'none', 'mean', or 'sum'",
                },
            ))),
        }
    }

    /// Multilabel margin loss for multi-label classification.
    ///
    /// Equivalent to `torch.nn.functional.multilabel_margin_loss`.
    /// Loss = sum_j max(0, 1 - (x[y_j] - x[i])) / x.size(1) for i not in y and j in y
    ///
    /// - `input`: Shape (N, C), scores for each label
    /// - `target`: Shape (N, C), target labels where positive indices are valid labels
    ///   and negative values (e.g., -1) mark ignored positions
    pub fn tensor_multilabel_margin_loss(
        &mut self,
        input: TensorNodeId,
        target: TensorNodeId,
        reduction: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        let input_shape = self.tensor_shape(input)?;
        let target_shape = self.tensor_shape(target)?;
        if input_shape.len() != 2 || target_shape.len() != 2 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "multilabel_margin_loss: input and target must be 2D (N, C)",
                },
            )));
        }
        if input_shape != target_shape {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "multilabel_margin_loss: input and target shapes must match",
                },
            )));
        }
        let n = input_shape[0];
        let c = input_shape[1];
        let target_vals = self.tensor_values_lossy_f64(target)?;
        // F64 no-grad fast path (mirrors multi_margin_loss 1625665c): the apply_function forward below
        // runs the O(N*C*|pos|) hinge SERIALLY and clones `input` via save_for_backward's to_vec — both
        // dead in no-grad. Borrow the contiguous f64 input, parallelize the per-sample loss over N,
        // then reduce via the SAME tensor_sum/tensor_mean the composed path uses. Bit-identical: each
        // per-sample sum walks the same positive-index set + same k-ascending hinge order. Grad /
        // non-contiguous fall through.
        if !self.tensor_requires_grad(input)?
            && self.tensor_dtype(input)? == DType::F64
            && self.tensor_tape.tensor(input)?.meta().is_contiguous()
        {
            let rows: Vec<f64> = {
                let v = self.tensor_tape.tensor(input)?.contiguous_values()?;
                use rayon::prelude::*;
                (0..n)
                    .into_par_iter()
                    .map(|i| {
                        let row_offset = i * c;
                        let positive_indices: Vec<usize> = (0..c)
                            .filter(|&j| target_vals[row_offset + j] >= 0.0)
                            .map(|j| target_vals[row_offset + j] as usize)
                            .filter(|&idx| idx < c)
                            .collect();
                        let mut sum = 0.0;
                        for &y_j in &positive_indices {
                            let x_y = v[row_offset + y_j];
                            for k in 0..c {
                                if !positive_indices.contains(&k) {
                                    let x_k = v[row_offset + k];
                                    let margin_term = 1.0 - x_y + x_k;
                                    if margin_term > 0.0 {
                                        sum += margin_term;
                                    }
                                }
                            }
                        }
                        sum / c as f64
                    })
                    .collect()
            };
            let loss_none = self.tensor_variable(rows, vec![n], false)?;
            return match reduction {
                "none" => Ok(loss_none),
                "sum" => self.tensor_sum(loss_none),
                _ => self.tensor_mean(loss_none),
            };
        }
        // Route through apply_function so the gradient reaches `input` (target is
        // integer label indices, non-differentiable). The hinge is piecewise
        // linear: each active margin term `1 - x[y] + x[k] > 0` contributes
        // -1/C to grad x[y] and +1/C to grad x[k] (subgradient at the kink = 0).
        let target_for_backward = target_vals.clone();
        let loss = self.tensor_apply_function(
            &[input],
            move |ctx, inputs| {
                let (input_vals, _shape) = inputs[0];
                let mut losses = Vec::with_capacity(n);
                for i in 0..n {
                    let row_offset = i * c;
                    // Collect positive label indices (non-negative target values)
                    let positive_indices: Vec<usize> = (0..c)
                        .filter(|&j| target_vals[row_offset + j] >= 0.0)
                        .map(|j| target_vals[row_offset + j] as usize)
                        .filter(|&idx| idx < c)
                        .collect();
                    let mut sum = 0.0;
                    for &y_j in &positive_indices {
                        let x_y = input_vals[row_offset + y_j];
                        for k in 0..c {
                            if !positive_indices.contains(&k) {
                                let x_k = input_vals[row_offset + k];
                                let margin_term = 1.0 - x_y + x_k;
                                if margin_term > 0.0 {
                                    sum += margin_term;
                                }
                            }
                        }
                    }
                    losses.push(sum / c as f64);
                }
                ctx.save_for_backward(input_vals.to_vec(), vec![n, c]);
                Ok((losses, vec![n]))
            },
            move |ctx, grad_outputs| {
                let g = grad_outputs[0];
                let saved = ctx.saved_tensors();
                let input_vals = &saved[0];
                let inv_c = 1.0 / c as f64;
                let mut grad_input = vec![0.0; n * c];
                for i in 0..n {
                    let gi = g[i];
                    if gi == 0.0 {
                        continue;
                    }
                    let row_offset = i * c;
                    let positive_indices: Vec<usize> = (0..c)
                        .filter(|&j| target_for_backward[row_offset + j] >= 0.0)
                        .map(|j| target_for_backward[row_offset + j] as usize)
                        .filter(|&idx| idx < c)
                        .collect();
                    for &y_j in &positive_indices {
                        let x_y = input_vals[row_offset + y_j];
                        for k in 0..c {
                            if !positive_indices.contains(&k) {
                                let x_k = input_vals[row_offset + k];
                                if 1.0 - x_y + x_k > 0.0 {
                                    grad_input[row_offset + y_j] -= gi * inv_c;
                                    grad_input[row_offset + k] += gi * inv_c;
                                }
                            }
                        }
                    }
                }
                Ok(vec![Some(grad_input)])
            },
        )?;
        match reduction {
            "none" => Ok(loss),
            "mean" => self.tensor_mean(loss),
            "sum" => self.tensor_sum(loss),
            _ => Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "multilabel_margin_loss: reduction must be 'none', 'mean', or 'sum'",
                },
            ))),
        }
    }

    /// Multilabel soft margin loss for multi-label classification.
    ///
    /// Equivalent to `torch.nn.functional.multilabel_soft_margin_loss`.
    /// Loss = -1/C * sum_j (y_j * log(sigmoid(x_j)) + (1-y_j) * log(1-sigmoid(x_j)))
    ///
    /// - `input`: Shape (N, C), raw scores (logits)
    /// - `target`: Shape (N, C), binary targets (0 or 1)
    /// - `weight`: Optional per-label weights, shape (C,)
    pub fn tensor_multilabel_soft_margin_loss(
        &mut self,
        input: TensorNodeId,
        target: TensorNodeId,
        weight: Option<TensorNodeId>,
        reduction: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        let input_shape = self.tensor_shape(input)?;
        let target_shape = self.tensor_shape(target)?;
        if input_shape.len() != 2 || target_shape.len() != 2 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "multilabel_soft_margin_loss: input and target must be 2D (N, C)",
                },
            )));
        }
        if input_shape != target_shape {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "multilabel_soft_margin_loss: input and target shapes must match",
                },
            )));
        }
        let n = input_shape[0];
        let c = input_shape[1];

        if weight.is_none()
            && matches!(reduction, "none" | "mean" | "sum")
            && !self.tensor_tape.tensor_requires_grad(input)?
            && !self.tensor_tape.tensor_requires_grad(target)?
        {
            let input_dtype = self.tensor_dtype(input)?;
            if self.tensor_dtype(target)? == input_dtype {
                match input_dtype {
                    DType::F64 => {
                        let built = {
                            let xt = self.tensor_tape.tensor(input)?;
                            let tt = self.tensor_tape.tensor(target)?;
                            if xt.meta().is_contiguous() && tt.meta().is_contiguous() {
                                let xv = xt.contiguous_values()?;
                                let tv = tt.contiguous_values()?;
                                if xv.len() == tv.len() && xv.len() == n * c {
                                    use rayon::prelude::*;
                                    let losses: Vec<f64> = xv
                                        .par_chunks(c)
                                        .zip(tv.par_chunks(c))
                                        .map(|(xrow, trow)| {
                                            let mut sum = 0.0;
                                            for (&x, &y) in xrow.iter().zip(trow.iter()) {
                                                sum += y * stable_softplus(-x)
                                                    + (1.0 - y) * stable_softplus(x);
                                            }
                                            sum / c as f64
                                        })
                                        .collect();
                                    Some(losses)
                                } else {
                                    None
                                }
                            } else {
                                None
                            }
                        };
                        if let Some(losses) = built {
                            return match reduction {
                                "none" => self.tensor_variable(losses, vec![n], false),
                                "mean" => {
                                    let mean = losses.iter().copied().sum::<f64>() / n as f64;
                                    self.tensor_variable(vec![mean], vec![1], false)
                                }
                                _ => {
                                    let sum = losses.iter().copied().sum::<f64>();
                                    self.tensor_variable(vec![sum], vec![1], false)
                                }
                            };
                        }
                    }
                    DType::F32 => {
                        let built = {
                            let xt = self.tensor_tape.tensor(input)?;
                            let tt = self.tensor_tape.tensor(target)?;
                            if xt.meta().is_contiguous() && tt.meta().is_contiguous() {
                                let xv = xt.contiguous_values_f32()?;
                                let tv = tt.contiguous_values_f32()?;
                                if xv.len() == tv.len() && xv.len() == n * c {
                                    use rayon::prelude::*;
                                    let losses: Vec<f32> = xv
                                        .par_chunks(c)
                                        .zip(tv.par_chunks(c))
                                        .map(|(xrow, trow)| {
                                            let mut sum = 0.0_f32;
                                            for (&x, &y) in xrow.iter().zip(trow.iter()) {
                                                sum += y * stable_softplus_f32(-x)
                                                    + (1.0 - y) * stable_softplus_f32(x);
                                            }
                                            sum / c as f32
                                        })
                                        .collect();
                                    Some(losses)
                                } else {
                                    None
                                }
                            } else {
                                None
                            }
                        };
                        if let Some(losses) = built {
                            return match reduction {
                                "none" => self.tensor_variable_f32(losses, vec![n], false),
                                "mean" => {
                                    let mean = losses.iter().copied().map(f64::from).sum::<f64>()
                                        / n as f64;
                                    self.tensor_variable_f32(vec![mean as f32], vec![1], false)
                                }
                                _ => {
                                    let sum = losses.iter().copied().map(f64::from).sum::<f64>();
                                    self.tensor_variable_f32(vec![sum as f32], vec![1], false)
                                }
                            };
                        }
                    }
                    _ => {}
                }
            }
        }

        let weights = if let Some(w) = weight {
            let w_shape = self.tensor_shape(w)?;
            if w_shape.len() != 1 || w_shape[0] != c {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "multilabel_soft_margin_loss: weight must be 1D with length C",
                    },
                )));
            }
            Some(self.tensor_values(w)?)
        } else {
            None
        };
        let target_vals = self.tensor_values_lossy_f64(target)?;
        // Route through apply_function so the gradient reaches `input`. The loss
        // is smooth: d/dx_j [y log sigmoid(x) + (1-y) log(1-sigmoid(x))] = y - sigmoid(x),
        // so d loss_i/d x_j = w_j/C * (sigmoid(x_j) - y_j).
        let target_for_backward = target_vals.clone();
        let weights_for_backward = weights.clone();
        let loss = self.tensor_apply_function(
            &[input],
            move |ctx, inputs| {
                let (input_vals, _shape) = inputs[0];
                // Each row i is an independent per-class-sum loss, so compute rows in
                // parallel. Bit-identical to the serial loop: the per-row inner sum
                // order is unchanged and losses is indexed by i.
                let row_loss = |i: usize| -> f64 {
                    let row_offset = i * c;
                    let mut sum = 0.0;
                    for j in 0..c {
                        let x = input_vals[row_offset + j];
                        let y = target_vals[row_offset + j];
                        let w = weights.as_ref().map_or(1.0, |ws| ws[j]);
                        // log(sigmoid(x)) = x - softplus(x) = -softplus(-x)
                        // log(1 - sigmoid(x)) = -softplus(x)
                        let softplus_x = stable_softplus(x);
                        let softplus_neg_x = stable_softplus(-x);
                        let log_sigmoid = -softplus_neg_x;
                        let log_one_minus_sigmoid = -softplus_x;
                        sum += w * (y * log_sigmoid + (1.0 - y) * log_one_minus_sigmoid);
                    }
                    -sum / c as f64
                };
                let losses: Vec<f64> = if n >= 2 && n * c >= PARALLEL_ELEMENTWISE_MIN {
                    use rayon::prelude::*;
                    (0..n).into_par_iter().map(row_loss).collect()
                } else {
                    (0..n).map(row_loss).collect()
                };
                ctx.save_for_backward(input_vals.to_vec(), vec![n, c]);
                Ok((losses, vec![n]))
            },
            move |ctx, grad_outputs| {
                let g = grad_outputs[0];
                let saved = ctx.saved_tensors();
                let input_vals = &saved[0];
                let inv_c = 1.0 / c as f64;
                let mut grad_input = vec![0.0; n * c];
                // Each row i writes a DISJOINT [c] grad slot, so fill rows in parallel.
                // Bit-identical to the serial loop: per-element math unchanged; a row
                // with gi == 0 stays at its zero init (same as the serial `continue`).
                let fill_row = |i: usize, row: &mut [f64]| {
                    let gi = g[i];
                    if gi == 0.0 {
                        return;
                    }
                    let row_offset = i * c;
                    for (j, slot) in row.iter_mut().enumerate() {
                        let x = input_vals[row_offset + j];
                        let y = target_for_backward[row_offset + j];
                        let w = weights_for_backward.as_ref().map_or(1.0, |ws| ws[j]);
                        let sigmoid = 1.0 / (1.0 + (-x).exp());
                        *slot = gi * inv_c * w * (sigmoid - y);
                    }
                };
                if n >= 2 && n * c >= PARALLEL_ELEMENTWISE_MIN {
                    use rayon::prelude::*;
                    grad_input
                        .par_chunks_mut(c)
                        .enumerate()
                        .for_each(|(i, row)| fill_row(i, row));
                } else {
                    grad_input
                        .chunks_mut(c)
                        .enumerate()
                        .for_each(|(i, row)| fill_row(i, row));
                }
                Ok(vec![Some(grad_input)])
            },
        )?;
        match reduction {
            "none" => Ok(loss),
            "mean" => self.tensor_mean(loss),
            "sum" => self.tensor_sum(loss),
            _ => Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "multilabel_soft_margin_loss: reduction must be 'none', 'mean', or 'sum'",
                },
            ))),
        }
    }

    pub fn tensor_trace(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let (out, event) = self.tensor_tape.trace(input, self.mode())?;
        self.record_tensor_reduction_operation(&event);
        Ok(out)
    }

    pub fn tensor_lerp(
        &mut self,
        start: TensorNodeId,
        end: TensorNodeId,
        weight: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        // No-grad fast path: the tape path routes through dispatch and records a backward op.
        // For equal-shape contiguous inputs, borrow both operands and compute directly. The f32
        // branch calls the kernel's PyTorch-compatible FMA formula instead of composing through
        // f64 temporaries.
        if !self.tensor_requires_grad(start)? && !self.tensor_requires_grad(end)? {
            let s_shape = self.tensor_shape(start)?;
            if s_shape == self.tensor_shape(end)? {
                match (self.tensor_dtype(start)?, self.tensor_dtype(end)?) {
                    (DType::F64, DType::F64) => {
                        let built = {
                            let st = self.tensor_tape.tensor(start)?;
                            let et = self.tensor_tape.tensor(end)?;
                            if st.meta().is_contiguous() && et.meta().is_contiguous() {
                                let sd = st.contiguous_values()?;
                                let ed = et.contiguous_values()?;
                                if sd.len() == ed.len() {
                                    use rayon::prelude::*;
                                    // torch's lerp is a single-rounding FMA `fmadd(coeff, end-start,
                                    // base)` with |w|<0.5 => (coeff=w, base=start) else (coeff=w-1,
                                    // base=end); the plain `sv + w*(ev-sv)` (two roundings + first
                                    // branch only) is ~1 ULP off for |w|>=0.5. `weight` is a scalar so
                                    // coeff/branch hoist out of the map. Bit-exact vs torch (parity fix
                                    // for |w|>=0.5); mul_add == hardware FMA. (f32 path already FMA.)
                                    let small = weight.abs() < 0.5;
                                    let coeff = if small { weight } else { weight - 1.0 };
                                    let out: Vec<f64> = sd
                                        .par_iter()
                                        .zip(ed.par_iter())
                                        .map(|(&sv, &ev)| {
                                            let base = if small { sv } else { ev };
                                            coeff.mul_add(ev - sv, base)
                                        })
                                        .collect();
                                    Some(out)
                                } else {
                                    None
                                }
                            } else {
                                None
                            }
                        };
                        if let Some(out) = built {
                            return self.tensor_variable(out, s_shape, false);
                        }
                    }
                    (DType::F32, DType::F32) => {
                        let built = {
                            let st = self.tensor_tape.tensor(start)?;
                            let et = self.tensor_tape.tensor(end)?;
                            if st.meta().is_contiguous() && et.meta().is_contiguous() {
                                let sd = st.contiguous_values_f32()?;
                                let ed = et.contiguous_values_f32()?;
                                if sd.len() == ed.len() {
                                    let meta = TensorMeta::from_shape(
                                        s_shape.clone(),
                                        DType::F32,
                                        st.meta().device(),
                                    );
                                    Some(
                                        ft_kernel_cpu::lerp_tensor_contiguous_f32(
                                            sd,
                                            ed,
                                            weight as f32,
                                            &meta,
                                        )
                                        .map_err(|e| {
                                            AutogradError::Dispatch(
                                                ft_dispatch::DispatchError::Kernel(e),
                                            )
                                        })?,
                                    )
                                } else {
                                    None
                                }
                            } else {
                                None
                            }
                        };
                        if let Some(out) = built {
                            return self.tensor_variable_f32(out, s_shape, false);
                        }
                    }
                    _ => {}
                }
            }
        }
        let (out, event) = self.tensor_tape.lerp(start, end, weight, self.mode())?;
        self.record_tensor_lerp_operation(&event);
        Ok(out)
    }

    /// Linear interpolation with a per-element **tensor** weight.
    ///
    /// Equivalent to `torch.lerp(start, end, weight)` when `weight` is a Tensor:
    /// `out = start + weight * (end - start)`, broadcasting `weight` (and the
    /// inputs) together — torch.lerp's weight may be a Number (see
    /// [`Self::tensor_lerp`]) or a Tensor, but ft only had the scalar overload.
    /// Composed from autograd-aware sub/mul/add so gradients flow to `start`,
    /// `end`, and `weight`; the `end - start`, `* weight`, `start +` order
    /// matches torch's kernel, so values are bit-exact.
    pub fn tensor_lerp_weighted(
        &mut self,
        start: TensorNodeId,
        end: TensorNodeId,
        weight: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // No-grad fast path: the compose below (sub + mul + add) is 3 passes + tape nodes AND is ~1
        // ULP off torch for |w|>=0.5 (torch uses a single-rounding FMA). For no-grad equal-shape
        // contiguous inputs, compute torch's exact FMA lerp in ONE parallel pass -> BIT-EXACT to
        // torch (a perf win + a parity fix for |w|>=0.5). This is intentionally NOT bit-equal to the
        // grad fallthrough, which can't FMA via autograd ops (see the note there). grad /
        // dtype-mismatch / non-contiguous / broadcast fall through.
        if !self.tensor_requires_grad(start)?
            && !self.tensor_requires_grad(end)?
            && !self.tensor_requires_grad(weight)?
        {
            let ss = self.tensor_shape(start)?;
            let dt = self.tensor_dtype(start)?;
            if ss == self.tensor_shape(end)?
                && ss == self.tensor_shape(weight)?
                && self.tensor_dtype(end)? == dt
                && self.tensor_dtype(weight)? == dt
            {
                macro_rules! fused {
                    ($read:ident, $build:ident, $ty:ty) => {{
                        let built = {
                            let st = self.tensor_tape.tensor(start)?;
                            let et = self.tensor_tape.tensor(end)?;
                            let wt = self.tensor_tape.tensor(weight)?;
                            if st.meta().is_contiguous()
                                && et.meta().is_contiguous()
                                && wt.meta().is_contiguous()
                            {
                                let sd = st.$read()?;
                                let ed = et.$read()?;
                                let wd = wt.$read()?;
                                if sd.len() == ed.len() && ed.len() == wd.len() {
                                    use rayon::prelude::*;
                                    // torch's vectorized lerp (aten LerpKernel.cpp) computed in the
                                    // input dtype: fmadd(coeff, end-start, base) where |w|<0.5 =>
                                    // (coeff=w, base=start), else (coeff=w-1, base=end). The SINGLE
                                    // FMA rounding is what makes it bit-exact to torch — a plain
                                    // mul+sub (two roundings) is 1 ULP off for |w|>=0.5. mul_add maps
                                    // to the hardware FMA (verified 0/11 bit-match vs torch f32+f64).
                                    let out: Vec<$ty> = (0..sd.len())
                                        .into_par_iter()
                                        .map(|i| {
                                            let (s, e, w) = (sd[i], ed[i], wd[i]);
                                            let small = w.abs() < (0.5 as $ty);
                                            let coeff = if small { w } else { w - (1.0 as $ty) };
                                            let base = if small { s } else { e };
                                            coeff.mul_add(e - s, base)
                                        })
                                        .collect();
                                    Some(out)
                                } else {
                                    None
                                }
                            } else {
                                None
                            }
                        };
                        if let Some(out) = built {
                            return self.$build(out, ss.clone(), false);
                        }
                    }};
                }
                match dt {
                    DType::F64 => fused!(contiguous_values, tensor_variable, f64),
                    DType::F32 => fused!(contiguous_values_f32, tensor_variable_f32, f32),
                    _ => {}
                }
            }
        }
        // Fallthrough (grad / broadcast / dtype-mismatch / non-contiguous): the autograd-aware
        // `start + weight*(end - start)` compose. NOTE: torch's lerp uses a single-rounding FMA
        // (`fmadd(coeff, end-start, base)`) which this multi-op compose cannot reproduce, so the grad
        // path is ~1 ULP off torch for |weight|>=0.5 — a PRE-EXISTING gap (unchanged from HEAD; the
        // no-grad fast path above IS torch-exact). Closing it needs an FMA tensor primitive; tracked
        // as a follow-up in docs/NEGATIVE_EVIDENCE.md.
        let diff = self.tensor_sub(end, start)?;
        let weighted = self.tensor_mul(diff, weight)?;
        self.tensor_add(start, weighted)
    }

    /// In-place lerp: target = target + weight * (end - target).
    pub fn tensor_lerp_(
        &mut self,
        target: TensorNodeId,
        end: TensorNodeId,
        weight: f64,
    ) -> Result<(), AutogradError> {
        self.validate_tensor_in_place_target(target)?;
        // F64 borrow+parallel fast path: the generic path below CLONES BOTH operands via
        // `tensor_values_lossy_f64` + maps SERIALLY. Borrow both contiguous f64 + parallel.
        // BIT-IDENTICAL to the serial `s + weight*(e-s)` (each lane independent). NOTE: mirrors the
        // EXISTING naive formula (parity-vs-original); the FMA-vs-torch gap (cf. the non-in-place
        // lerp fix 23ca42e0) is a separate follow-up, NOT changed here. Other dtypes / non-contiguous
        // / shape-mismatch fall through to the generic path. frankentorch (BlackThrush).
        if self.tensor_dtype(target)? == DType::F64 && self.tensor_dtype(end)? == DType::F64 {
            let built = {
                let tt = self.tensor_tape.tensor(target)?;
                let et = self.tensor_tape.tensor(end)?;
                if tt.meta().is_contiguous() && et.meta().is_contiguous() {
                    let tv = tt.contiguous_values()?;
                    let ev = et.contiguous_values()?;
                    if tv.len() == ev.len() {
                        use rayon::prelude::*;
                        Some(
                            tv.par_iter()
                                .zip(ev.par_iter())
                                .map(|(&s, &e)| s + weight * (e - s))
                                .collect::<Vec<f64>>(),
                        )
                    } else {
                        None
                    }
                } else {
                    None
                }
            };
            if let Some(result) = built {
                self.update_tensor_values_for_float(target, result, INPLACE_FLOAT_REASON)?;
                self.record_tensor_in_place_operation(
                    "lerp_",
                    target,
                    Some(format!("weight={weight}")),
                );
                return Ok(());
            }
        }
        let target_vals = self.tensor_values_lossy_f64(target)?;
        let end_vals = self.tensor_values_lossy_f64(end)?;
        if target_vals.len() != end_vals.len() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: self.tensor_shape(target)?,
                    rhs: self.tensor_shape(end)?,
                },
            )));
        }
        let result: Vec<f64> = target_vals
            .iter()
            .zip(end_vals.iter())
            .map(|(&s, &e)| s + weight * (e - s))
            .collect();
        self.update_tensor_values_for_float(target, result, INPLACE_FLOAT_REASON)?;
        self.record_tensor_in_place_operation("lerp_", target, Some(format!("weight={weight}")));
        Ok(())
    }

    /// `torch.addcmul`: `input + value * tensor1 * tensor2`.
    ///
    /// Composed through autograd-aware primitives, so gradients flow to
    /// `input`, `tensor1`, and `tensor2` (`grad_t1 = value*t2*g`,
    /// `grad_t2 = value*t1*g`). Matches torch 2.12 (frankentorch-tf10).
    pub fn tensor_addcmul(
        &mut self,
        input: TensorNodeId,
        tensor1: TensorNodeId,
        tensor2: TensorNodeId,
        value: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        // F32 no-grad fast path: torch's CPU addcmul rounds value*tensor1 to f32,
        // then performs fused multiply-add with tensor2 and input. Preserve that
        // bit pattern instead of reusing the composed mul/scale/add path.
        if !self.tensor_requires_grad(input)?
            && !self.tensor_requires_grad(tensor1)?
            && !self.tensor_requires_grad(tensor2)?
            && self.tensor_dtype(input)? == DType::F32
            && self.tensor_dtype(tensor1)? == DType::F32
            && self.tensor_dtype(tensor2)? == DType::F32
        {
            let s_in = self.tensor_shape(input)?;
            if s_in == self.tensor_shape(tensor1)? && s_in == self.tensor_shape(tensor2)? {
                let built = {
                    let it = self.tensor_tape.tensor(input)?;
                    let t1 = self.tensor_tape.tensor(tensor1)?;
                    let t2 = self.tensor_tape.tensor(tensor2)?;
                    if it.meta().is_contiguous()
                        && t1.meta().is_contiguous()
                        && t2.meta().is_contiguous()
                    {
                        let id = it.contiguous_values_f32()?;
                        let d1 = t1.contiguous_values_f32()?;
                        let d2 = t2.contiguous_values_f32()?;
                        if id.len() == d1.len() && d1.len() == d2.len() {
                            use rayon::prelude::*;
                            let value = value as f32;
                            let out: Vec<f32> = (0..id.len())
                                .into_par_iter()
                                .map(|i| (value * d1[i]).mul_add(d2[i], id[i]))
                                .collect();
                            Some(out)
                        } else {
                            None
                        }
                    } else {
                        None
                    }
                };
                if let Some(out) = built {
                    return self.tensor_variable_f32(out, s_in, false);
                }
            }
        }

        // No-grad fast path: the composed mul + scale + add (3 passes over numel) measured
        // 3.16x SLOWER than torch's fused addcmul. For no-grad equal-shape contiguous f64,
        // borrow all three operands and compute input + value*(t1*t2) in ONE parallel pass.
        // Bit-exact with the composed path (same t1*t2 product grouping, then value scale
        // [scalar mul commutes], then add). grad / non-f64 / non-contiguous / broadcast fall
        // through.
        if !self.tensor_requires_grad(input)?
            && !self.tensor_requires_grad(tensor1)?
            && !self.tensor_requires_grad(tensor2)?
            && self.tensor_dtype(input)? == DType::F64
            && self.tensor_dtype(tensor1)? == DType::F64
            && self.tensor_dtype(tensor2)? == DType::F64
        {
            let s_in = self.tensor_shape(input)?;
            if s_in == self.tensor_shape(tensor1)? && s_in == self.tensor_shape(tensor2)? {
                let built = {
                    let it = self.tensor_tape.tensor(input)?;
                    let t1 = self.tensor_tape.tensor(tensor1)?;
                    let t2 = self.tensor_tape.tensor(tensor2)?;
                    if it.meta().is_contiguous()
                        && t1.meta().is_contiguous()
                        && t2.meta().is_contiguous()
                    {
                        let id = it.contiguous_values()?;
                        let d1 = t1.contiguous_values()?;
                        let d2 = t2.contiguous_values()?;
                        if id.len() == d1.len() && d1.len() == d2.len() {
                            use rayon::prelude::*;
                            let out: Vec<f64> = (0..id.len())
                                .into_par_iter()
                                .map(|i| id[i] + value * (d1[i] * d2[i]))
                                .collect();
                            Some(out)
                        } else {
                            None
                        }
                    } else {
                        None
                    }
                };
                if let Some(out) = built {
                    return self.tensor_variable(out, s_in, false);
                }
            }
        }
        let prod = self.tensor_mul(tensor1, tensor2)?;
        let scaled = self.scale_by_constant(prod, value)?;
        self.tensor_add(input, scaled)
    }

    /// `torch.addcdiv`: `input + value * tensor1 / tensor2`.
    ///
    /// Composed through autograd-aware primitives (frankentorch-tf10).
    pub fn tensor_addcdiv(
        &mut self,
        input: TensorNodeId,
        tensor1: TensorNodeId,
        tensor2: TensorNodeId,
        value: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        // No-grad fast path mirroring tensor_addcmul: the composed div + scale + add (3 passes)
        // measured 3.36x SLOWER than torch's fused addcdiv. For no-grad equal-shape contiguous
        // f64, borrow all three and compute input + value*(t1/t2) in ONE parallel pass. Bit-
        // exact (same t1/t2 quotient then value scale then add). grad / non-f64 / non-contiguous
        // / broadcast fall through.
        if !self.tensor_requires_grad(input)?
            && !self.tensor_requires_grad(tensor1)?
            && !self.tensor_requires_grad(tensor2)?
            && self.tensor_dtype(input)? == DType::F64
            && self.tensor_dtype(tensor1)? == DType::F64
            && self.tensor_dtype(tensor2)? == DType::F64
        {
            let s_in = self.tensor_shape(input)?;
            if s_in == self.tensor_shape(tensor1)? && s_in == self.tensor_shape(tensor2)? {
                let built = {
                    let it = self.tensor_tape.tensor(input)?;
                    let t1 = self.tensor_tape.tensor(tensor1)?;
                    let t2 = self.tensor_tape.tensor(tensor2)?;
                    if it.meta().is_contiguous()
                        && t1.meta().is_contiguous()
                        && t2.meta().is_contiguous()
                    {
                        let id = it.contiguous_values()?;
                        let d1 = t1.contiguous_values()?;
                        let d2 = t2.contiguous_values()?;
                        if id.len() == d1.len() && d1.len() == d2.len() {
                            use rayon::prelude::*;
                            let out: Vec<f64> = (0..id.len())
                                .into_par_iter()
                                .map(|i| id[i] + value * (d1[i] / d2[i]))
                                .collect();
                            Some(out)
                        } else {
                            None
                        }
                    } else {
                        None
                    }
                };
                if let Some(out) = built {
                    return self.tensor_variable(out, s_in, false);
                }
            }
        }
        // F32 sibling: the composed path (div f32 -> scale_by_constant = mul by `value as f32`
        // -> add, all f32) is 3 passes = ~7.5x SLOWER than torch's fused addcdiv. One parallel
        // pass with the IDENTICAL f32 arithmetic `id[i] + (d1[i]/d2[i]) * (value as f32)` is
        // BIT-EXACT with the compose (same f32 quotient, same f32 scalar, same f32 order).
        if !self.tensor_requires_grad(input)?
            && !self.tensor_requires_grad(tensor1)?
            && !self.tensor_requires_grad(tensor2)?
            && self.tensor_dtype(input)? == DType::F32
            && self.tensor_dtype(tensor1)? == DType::F32
            && self.tensor_dtype(tensor2)? == DType::F32
        {
            let s_in = self.tensor_shape(input)?;
            if s_in == self.tensor_shape(tensor1)? && s_in == self.tensor_shape(tensor2)? {
                let built = {
                    let it = self.tensor_tape.tensor(input)?;
                    let t1 = self.tensor_tape.tensor(tensor1)?;
                    let t2 = self.tensor_tape.tensor(tensor2)?;
                    if it.meta().is_contiguous()
                        && t1.meta().is_contiguous()
                        && t2.meta().is_contiguous()
                    {
                        let id = it.contiguous_values_f32()?;
                        let d1 = t1.contiguous_values_f32()?;
                        let d2 = t2.contiguous_values_f32()?;
                        if id.len() == d1.len() && d1.len() == d2.len() {
                            use rayon::prelude::*;
                            let vf = value as f32;
                            let out: Vec<f32> = (0..id.len())
                                .into_par_iter()
                                .map(|i| id[i] + (d1[i] / d2[i]) * vf)
                                .collect();
                            Some(out)
                        } else {
                            None
                        }
                    } else {
                        None
                    }
                };
                if let Some(out) = built {
                    return self.tensor_variable_f32(out, s_in, false);
                }
            }
        }
        let quot = self.tensor_div(tensor1, tensor2)?;
        let scaled = self.scale_by_constant(quot, value)?;
        self.tensor_add(input, scaled)
    }

    /// In-place addcmul: target += value * tensor1 * tensor2.
    pub fn tensor_addcmul_(
        &mut self,
        target: TensorNodeId,
        tensor1: TensorNodeId,
        tensor2: TensorNodeId,
        value: f64,
    ) -> Result<(), AutogradError> {
        self.validate_tensor_in_place_target(target)?;
        if self.try_inplace_ternary_f64(
            target,
            tensor1,
            tensor2,
            "addcmul_",
            Some(format!("value={value}")),
            |t, t1, t2| t + value * t1 * t2,
        )? {
            return Ok(());
        }
        let target_vals = self.tensor_values_lossy_f64(target)?;
        let t1_vals = self.tensor_values_lossy_f64(tensor1)?;
        let t2_vals = self.tensor_values_lossy_f64(tensor2)?;
        if target_vals.len() != t1_vals.len() || target_vals.len() != t2_vals.len() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: self.tensor_shape(target)?,
                    rhs: self.tensor_shape(tensor1)?,
                },
            )));
        }
        let result: Vec<f64> = target_vals
            .iter()
            .zip(t1_vals.iter())
            .zip(t2_vals.iter())
            .map(|((&t, &t1), &t2)| t + value * t1 * t2)
            .collect();
        self.update_tensor_values_for_float(target, result, INPLACE_FLOAT_REASON)?;
        self.record_tensor_in_place_operation("addcmul_", target, Some(format!("value={value}")));
        Ok(())
    }

    /// In-place addcdiv: target += value * tensor1 / tensor2.
    pub fn tensor_addcdiv_(
        &mut self,
        target: TensorNodeId,
        tensor1: TensorNodeId,
        tensor2: TensorNodeId,
        value: f64,
    ) -> Result<(), AutogradError> {
        self.validate_tensor_in_place_target(target)?;
        if self.try_inplace_ternary_f64(
            target,
            tensor1,
            tensor2,
            "addcdiv_",
            Some(format!("value={value}")),
            |t, t1, t2| t + value * t1 / t2,
        )? {
            return Ok(());
        }
        let target_vals = self.tensor_values_lossy_f64(target)?;
        let t1_vals = self.tensor_values_lossy_f64(tensor1)?;
        let t2_vals = self.tensor_values_lossy_f64(tensor2)?;
        if target_vals.len() != t1_vals.len() || target_vals.len() != t2_vals.len() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: self.tensor_shape(target)?,
                    rhs: self.tensor_shape(tensor1)?,
                },
            )));
        }
        let result: Vec<f64> = target_vals
            .iter()
            .zip(t1_vals.iter())
            .zip(t2_vals.iter())
            .map(|((&t, &t1), &t2)| t + value * t1 / t2)
            .collect();
        self.update_tensor_values_for_float(target, result, INPLACE_FLOAT_REASON)?;
        self.record_tensor_in_place_operation("addcdiv_", target, Some(format!("value={value}")));
        Ok(())
    }

    /// Multiplies `node` by a non-grad scalar constant. `value == 1.0`
    /// is returned unchanged so the common default adds no tape node.
    fn scale_by_constant(
        &mut self,
        node: TensorNodeId,
        value: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        if value == 1.0 {
            return Ok(node);
        }
        let shape = self.tensor_shape(node)?;
        let constant = self.const_tensor_like(node, shape, value)?;
        self.tensor_mul(node, constant)
    }

    pub fn tensor_addmm(
        &mut self,
        input: TensorNodeId,
        mat1: TensorNodeId,
        mat2: TensorNodeId,
        beta: f64,
        alpha: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let (out, event) = self
            .tensor_tape
            .addmm(input, mat1, mat2, beta, alpha, self.mode())?;
        self.record_tensor_addmm_operation(&event);
        Ok(out)
    }

    pub fn tensor_addmv(
        &mut self,
        input: TensorNodeId,
        mat: TensorNodeId,
        vec_input: TensorNodeId,
        beta: f64,
        alpha: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let (out, event) =
            self.tensor_tape
                .addmv(input, mat, vec_input, beta, alpha, self.mode())?;
        self.record_tensor_addmv_operation(&event);
        Ok(out)
    }

    /// Ensure `input` has at least 1 dimension.
    ///
    /// Equivalent to `torch.atleast_1d(input)`. 0-D scalars are
    /// reshaped to `[1]`; tensors with rank ≥ 1 are returned
    /// unchanged. Composes through autograd-aware tensor_reshape.
    /// Tracked under frankentorch-oi03.
    pub fn tensor_atleast_1d(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        if shape.is_empty() {
            self.tensor_reshape(input, vec![1])
        } else {
            Ok(input)
        }
    }

    /// Ensure `input` has at least 2 dimensions.
    ///
    /// Equivalent to `torch.atleast_2d(input)`. 0-D scalars become
    /// `[1, 1]`; 1-D `[N]` becomes `[1, N]`; tensors with rank ≥ 2
    /// are returned unchanged. Tracked under frankentorch-oi03.
    pub fn tensor_atleast_2d(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        match shape.len() {
            0 => self.tensor_reshape(input, vec![1, 1]),
            1 => {
                let n = shape[0];
                self.tensor_reshape(input, vec![1, n])
            }
            _ => Ok(input),
        }
    }

    /// Ensure `input` has at least 3 dimensions.
    ///
    /// Equivalent to `torch.atleast_3d(input)`. 0-D becomes `[1, 1, 1]`;
    /// 1-D `[N]` becomes `[1, N, 1]`; 2-D `[N, M]` becomes `[N, M, 1]`;
    /// tensors with rank ≥ 3 are returned unchanged. The asymmetric
    /// padding (left for the 1-D case, right for the 2-D case) matches
    /// PyTorch and numpy semantics. Tracked under frankentorch-oi03.
    pub fn tensor_atleast_3d(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        match shape.len() {
            0 => self.tensor_reshape(input, vec![1, 1, 1]),
            1 => {
                let n = shape[0];
                self.tensor_reshape(input, vec![1, n, 1])
            }
            2 => {
                let (n, m) = (shape[0], shape[1]);
                self.tensor_reshape(input, vec![n, m, 1])
            }
            _ => Ok(input),
        }
    }

    /// Matrix-vector product: `out = M @ v`.
    ///
    /// Equivalent to `torch.mv(input, vec_input)`. `input` must be a 2-D
    /// matrix of shape `[m, n]` and `vec_input` a 1-D vector of shape
    /// `[n]`; the result is a 1-D vector of shape `[m]`.
    /// Composes through autograd-aware tensor_reshape + tensor_matmul,
    /// so gradients flow to both inputs. Tracked under frankentorch-256l.
    pub fn tensor_mv(
        &mut self,
        input: TensorNodeId,
        vec_input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let m_shape = self.tensor_shape(input)?;
        let v_shape = self.tensor_shape(vec_input)?;
        if m_shape.len() != 2 {
            // Migrate to InvalidDimension (frankentorch-oitu).
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::InvalidDimension {
                    dim: m_shape.len(),
                    ndim: 2,
                },
            )));
        }
        if v_shape.len() != 1 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::InvalidDimension {
                    dim: v_shape.len(),
                    ndim: 1,
                },
            )));
        }
        if m_shape[1] != v_shape[0] {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: m_shape.clone(),
                    rhs: v_shape.clone(),
                },
            )));
        }
        let n = v_shape[0];
        let m = m_shape[0];
        let v_2d = self.tensor_reshape(vec_input, vec![n, 1])?;
        let out_2d = self.tensor_matmul(input, v_2d)?;
        self.tensor_reshape(out_2d, vec![m])
    }

    pub fn tensor_neg(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        // Complex negation -z = (-re, -im) (torch.neg(complex)); the unary
        // dispatch rejects complex. Non-differentiable here (complex grad is
        // ng1hw). frankentorch-b91f3.
        {
            let tensor = self.tensor_tape.tensor(input)?;
            let dtype = tensor.meta().dtype();
            if matches!(dtype, DType::Complex64 | DType::Complex128) {
                let meta = tensor.meta().clone();
                if self.tensor_tape.tensor_requires_grad(input)? {
                    return Err(AutogradError::TensorRequiresGradNonFloating {
                        node: input,
                        dtype,
                    });
                }
                let output_storage = match tensor.typed_storage() {
                    TensorStorage::Complex64(values) => {
                        TensorStorage::Complex64(Arc::new(values.iter().map(|z| -z).collect()))
                    }
                    TensorStorage::Complex128(values) => {
                        TensorStorage::Complex128(Arc::new(values.iter().map(|z| -z).collect()))
                    }
                    _ => unreachable!("dtype is complex"),
                };
                let out = self.tensor_tape.leaf_tensor(
                    DenseTensor::from_typed_storage(meta, output_storage)?,
                    false,
                );
                self.runtime.ledger_mut().record(
                    EvidenceKind::Dispatch,
                    format!("neg(complex) input={} out={}", input.0, out.0),
                );
                return Ok(out);
            }
        }
        let (out, event) = self.tensor_tape.neg(input, self.mode())?;
        self.record_tensor_unary_operation(&event);
        Ok(out)
    }

    pub fn tensor_abs(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        // Complex |z| = hypot(re, im) -> real output (torch.abs(complex)); the
        // unary dispatch rejects complex. Differentiable via the complex-bridge:
        // d|z|/dz interleaved = (re/|z|, im/|z|) (0 at z=0). frankentorch-ng1hw.
        {
            let tensor = self.tensor_tape.tensor(input)?;
            let dtype = tensor.meta().dtype();
            if matches!(dtype, DType::Complex64 | DType::Complex128) {
                let meta = tensor.meta().clone();
                let requires_grad = self.tensor_tape.tensor_requires_grad(input)?
                    && self.tensor_tape.is_grad_enabled();
                // Capture re/im (f64) for the Wirtinger backward.
                let (re_im, output_meta, output_storage): (Vec<(f64, f64)>, _, _) = match tensor
                    .typed_storage()
                {
                    TensorStorage::Complex64(values) => (
                        values
                            .iter()
                            .map(|z| (f64::from(z.re), f64::from(z.im)))
                            .collect(),
                        TensorMeta::from_shape(meta.shape().to_vec(), DType::F32, meta.device()),
                        TensorStorage::F32(Arc::new(
                            values.iter().map(|z| z.re.hypot(z.im)).collect(),
                        )),
                    ),
                    TensorStorage::Complex128(values) => (
                        values.iter().map(|z| (z.re, z.im)).collect(),
                        TensorMeta::from_shape(meta.shape().to_vec(), DType::F64, meta.device()),
                        TensorStorage::F64(Arc::new(
                            values.iter().map(|z| z.re.hypot(z.im)).collect(),
                        )),
                    ),
                    _ => unreachable!("dtype is complex"),
                };
                let output = DenseTensor::from_typed_storage(output_meta, output_storage)?;
                let out = if requires_grad {
                    self.tensor_tape.apply_complex_bridge(
                        &[input],
                        output,
                        move |_ctx, grad_outputs| {
                            let g = grad_outputs[0];
                            let mut grad_z = vec![0.0; g.len() * 2];
                            for (i, &(re, im)) in re_im.iter().enumerate() {
                                let mag = re.hypot(im);
                                if mag > 0.0 {
                                    grad_z[2 * i] = g[i] * re / mag;
                                    grad_z[2 * i + 1] = g[i] * im / mag;
                                }
                            }
                            Ok(vec![Some(grad_z)])
                        },
                    )?
                } else {
                    self.tensor_tape.leaf_tensor(output, false)
                };
                self.runtime.ledger_mut().record(
                    EvidenceKind::Dispatch,
                    format!("abs(complex) input={} out={}", input.0, out.0),
                );
                return Ok(out);
            }
        }
        let (out, event) = self.tensor_tape.abs(input, self.mode())?;
        self.record_tensor_unary_operation(&event);
        Ok(out)
    }

    pub fn tensor_exp(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        // Complex exp: e^z = e^re·(cos im + i·sin im) (torch.exp(complex)).
        // frankentorch-b91f3 / hyi5x.
        {
            let tensor = self.tensor_tape.tensor(input)?;
            let dtype = tensor.meta().dtype();
            if matches!(dtype, DType::Complex64 | DType::Complex128) {
                let meta = tensor.meta().clone();
                if self.tensor_tape.tensor_requires_grad(input)?
                    && self.tensor_tape.is_grad_enabled()
                {
                    // Differentiable via composition: exp(z) = complex(e^re·cos(im),
                    // e^re·sin(im)) over the complex<->real bridge (hyi5x).
                    let re = self.tensor_real(input)?;
                    let im = self.tensor_imag(input)?;
                    let er = self.tensor_exp(re)?;
                    let c = self.tensor_cos(im)?;
                    let sn = self.tensor_sin(im)?;
                    let out_re = self.tensor_mul(er, c)?;
                    let out_im = self.tensor_mul(er, sn)?;
                    return self.tensor_complex(out_re, out_im);
                }
                // Complex exp = e^a·(cos b + i·sin b) — exp+sin+cos per element, very
                // compute-bound, so parallelize above PARALLEL_ELEMENTWISE_MIN. Pure
                // per-element map → bit-identical to serial. frankentorch-kgs4.92.
                use rayon::prelude::*;
                let output_storage = match tensor.typed_storage() {
                    TensorStorage::Complex64(values) => {
                        let out: Vec<ft_core::Complex64> =
                            if values.len() >= PARALLEL_ELEMENTWISE_MIN {
                                values.par_iter().map(|z| z.exp()).collect()
                            } else {
                                values.iter().map(|z| z.exp()).collect()
                            };
                        TensorStorage::Complex64(Arc::new(out))
                    }
                    TensorStorage::Complex128(values) => {
                        let out: Vec<ft_core::Complex128> =
                            if values.len() >= PARALLEL_ELEMENTWISE_MIN {
                                values.par_iter().map(|z| z.exp()).collect()
                            } else {
                                values.iter().map(|z| z.exp()).collect()
                            };
                        TensorStorage::Complex128(Arc::new(out))
                    }
                    _ => unreachable!("dtype is complex"),
                };
                let out = self.tensor_tape.leaf_tensor(
                    DenseTensor::from_typed_storage(meta, output_storage)?,
                    false,
                );
                self.runtime.ledger_mut().record(
                    EvidenceKind::Dispatch,
                    format!("exp(complex) input={} out={}", input.0, out.0),
                );
                return Ok(out);
            }
        }
        let (out, event) = self.tensor_tape.exp(input, self.mode())?;
        self.record_tensor_unary_operation(&event);
        Ok(out)
    }

    /// Apply an element-wise complex unary op (forward only). torch supports
    /// most unary ops on complex; ft's unary dispatch rejects complex, so the
    /// complex callers route here. Non-differentiable (complex grad is ng1hw);
    /// fail loud on requires_grad like the other complex-reading ops.
    /// frankentorch-pohu8.
    fn complex_unary_fast(
        &mut self,
        input: TensorNodeId,
        label: &str,
        f32op: impl Fn(ft_core::Complex64) -> ft_core::Complex64 + Sync,
        f64op: impl Fn(ft_core::Complex128) -> ft_core::Complex128 + Sync,
    ) -> Result<TensorNodeId, AutogradError> {
        use rayon::prelude::*;
        let tensor = self.tensor_tape.tensor(input)?;
        let meta = tensor.meta().clone();
        let dtype = meta.dtype();
        if self.tensor_tape.tensor_requires_grad(input)? {
            return Err(AutogradError::TensorRequiresGradNonFloating { node: input, dtype });
        }
        // Complex transcendentals (log/sin/cos/tan/asin/.../tanh/sinh/cosh) are very
        // compute-bound — each is several real transcendentals per element — so
        // spread them across the rayon pool above PARALLEL_ELEMENTWISE_MIN. Pure
        // per-element map (index order preserved) → bit-identical to serial.
        // frankentorch-kgs4.92.
        let storage = match tensor.typed_storage() {
            TensorStorage::Complex64(values) => {
                let out: Vec<ft_core::Complex64> = if values.len() >= PARALLEL_ELEMENTWISE_MIN {
                    values.par_iter().map(|z| f32op(*z)).collect()
                } else {
                    values.iter().map(|z| f32op(*z)).collect()
                };
                TensorStorage::Complex64(Arc::new(out))
            }
            TensorStorage::Complex128(values) => {
                let out: Vec<ft_core::Complex128> = if values.len() >= PARALLEL_ELEMENTWISE_MIN {
                    values.par_iter().map(|z| f64op(*z)).collect()
                } else {
                    values.iter().map(|z| f64op(*z)).collect()
                };
                TensorStorage::Complex128(Arc::new(out))
            }
            _ => unreachable!("complex_unary_fast called on non-complex dtype"),
        };
        let out = self
            .tensor_tape
            .leaf_tensor(DenseTensor::from_typed_storage(meta, storage)?, false);
        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!("{label}(complex) input={} out={}", input.0, out.0),
        );
        Ok(out)
    }

    pub fn tensor_log(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        if matches!(
            self.tensor_dtype(input)?,
            DType::Complex64 | DType::Complex128
        ) {
            if self.tensor_tape.tensor_requires_grad(input)? && self.tensor_tape.is_grad_enabled() {
                // Differentiable complex log: ln(z) = ½·ln(re²+im²) + i·atan2(im, re),
                // composed over the complex<->real bridge (hyi5x).
                let re = self.tensor_real(input)?;
                let im = self.tensor_imag(input)?;
                let re2 = self.tensor_mul(re, re)?;
                let im2 = self.tensor_mul(im, im)?;
                let mag2 = self.tensor_add(re2, im2)?;
                let ln_mag2 = self.tensor_log(mag2)?;
                let out_re = self.tensor_mul_scalar(ln_mag2, 0.5)?;
                let out_im = self.tensor_atan2(im, re)?;
                return self.tensor_complex(out_re, out_im);
            }
            return self.complex_unary_fast(input, "log", |z| z.ln(), |z| z.ln());
        }
        let (out, event) = self.tensor_tape.log(input, self.mode())?;
        self.record_tensor_unary_operation(&event);
        Ok(out)
    }

    pub fn tensor_relu(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let (out, event) = self.tensor_tape.relu(input, self.mode())?;
        self.record_tensor_unary_operation(&event);
        Ok(out)
    }

    /// ReLU6 activation: min(max(0, x), 6).
    ///
    /// Equivalent to `F.relu6(input)` in PyTorch.
    pub fn tensor_relu6(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        // f32/half: compute in f64 then cast back (the f64 borrowed-inputs path
        // errors on non-f64 storage). torch keeps the input dtype. frankentorch-x9yuq.
        let dt = self.tensor_dtype(input)?;
        // No-grad f32 fast path: the upcast roundtrip (f32->f64 clone + clamp in f64
        // + f64->f32 clone = 3 passes + 2 full allocs) measured 15.3x SLOWER than
        // torch. relu6 = clamp(x, 0, 6) is a pure min/max compare with no rounding,
        // so an in-dtype f32 clamp is bit-exact with torch's f32 relu6 (NaN -> NaN in
        // both: f32::clamp returns self for NaN since the < / > tests are false).
        // frankentorch-x9yuq.
        if dt == DType::F32 && !self.tensor_requires_grad(input)? {
            let built = {
                let it = self.tensor_tape.tensor(input)?;
                if it.meta().is_contiguous() {
                    use rayon::prelude::*;
                    let xd = it.contiguous_values_f32()?;
                    let out: Vec<f32> = xd.par_iter().map(|&x| x.clamp(0.0_f32, 6.0_f32)).collect();
                    Some(out)
                } else {
                    None
                }
            };
            if let Some(out) = built {
                let shape = self.tensor_shape(input)?;
                return self.tensor_variable_f32(out, shape, false);
            }
        }
        if dt != DType::F64 {
            let in64 = self.tensor_to_dtype(input, DType::F64)?;
            let out64 = self.tensor_relu6(in64)?;
            return self.tensor_to_dtype(out64, dt);
        }
        let out = self.tensor_apply_function_f64_borrowed_inputs(
            &[input],
            |_ctx, inputs| {
                let (vals, shape) = inputs[0];
                let values: Vec<f64> = vals.iter().map(|&x| x.clamp(0.0, 6.0)).collect();
                Ok((values, shape.to_vec()))
            },
            // Borrowed-inputs: backward re-reads x from the live leaf. frankentorch-3jmy3.
            |_ctx, grad_outputs, borrowed| {
                let grad_out = grad_outputs[0];
                let input_vals = borrowed[0].0;
                let grad_in: Vec<f64> = input_vals
                    .iter()
                    .zip(grad_out.iter())
                    .map(|(&x, &go)| if x > 0.0 && x < 6.0 { go } else { 0.0 })
                    .collect();
                Ok(vec![Some(grad_in)])
            },
        )?;
        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!("relu6 in={} out={}", input.0, out.0),
        );
        Ok(out)
    }

