    pub fn tensor_tanh(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        if matches!(
            self.tensor_dtype(input)?,
            DType::Complex64 | DType::Complex128
        ) {
            if self.tensor_tape.tensor_requires_grad(input)? && self.tensor_tape.is_grad_enabled() {
                // Differentiable complex tanh activation (frankentorch-4kome):
                // tanh(re+i·im) = [sinh(2re) + i·sin(2im)] / [cosh(2re) + cos(2im)],
                // composed over the complex<->real bridge.
                let re = self.tensor_real(input)?;
                let im = self.tensor_imag(input)?;
                let re2 = self.tensor_mul_scalar(re, 2.0)?;
                let im2 = self.tensor_mul_scalar(im, 2.0)?;
                let sh = self.tensor_sinh(re2)?;
                let ch = self.tensor_cosh(re2)?;
                let sn = self.tensor_sin(im2)?;
                let cs = self.tensor_cos(im2)?;
                let denom = self.tensor_add(ch, cs)?;
                let out_re = self.tensor_div(sh, denom)?;
                let out_im = self.tensor_div(sn, denom)?;
                return self.tensor_complex(out_re, out_im);
            }
            return self.complex_unary_fast(input, "tanh", |z| z.tanh(), |z| z.tanh());
        }
        let (out, event) = self.tensor_tape.tanh(input, self.mode())?;
        self.record_tensor_unary_operation(&event);
        Ok(out)
    }

