    /// Element-wise logical NOT: `1 if x == 0 else 0`.
    ///
    /// Equivalent to `torch.logical_not(input)`. Composes through
    /// tensor_eq against a zeros constant. Returns 0/1 floats
    /// (matches the convention for tensor_eq, tensor_lt, etc.).
    /// Non-differentiable: fail-loud on requires_grad.
    /// Tracked under frankentorch-nezf.
    pub fn tensor_logical_not(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        if self.tensor_requires_grad(input)? {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "logical_not: autograd not supported (boolean negation is non-differentiable). Tracked under frankentorch-nezf.",
                },
            )));
        }
        let shape = self.tensor_shape(input)?;
        let zeros = self.full(shape, 0.0, false)?;
        self.tensor_eq(input, zeros)
    }

    /// Element-wise logical AND.
    ///
    /// Equivalent to `torch.logical_and(input, other)`. Returns 1.0 where
    /// both inputs are non-zero, 0.0 otherwise. Non-differentiable.
    pub fn tensor_logical_and(
        &mut self,
        input: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        if self.tensor_requires_grad(input)? || self.tensor_requires_grad(other)? {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "logical_and: autograd not supported (boolean ops are non-differentiable)",
                },
            )));
        }
        let shape = self.tensor_shape(input)?;
        let zeros = self.full(shape, 0.0, false)?;
        let a_bool = self.tensor_ne(input, zeros)?;
        let zeros2 = self.full(self.tensor_shape(other)?, 0.0, false)?;
        let b_bool = self.tensor_ne(other, zeros2)?;
        self.tensor_mul(a_bool, b_bool)
    }

    /// Element-wise logical OR.
    ///
    /// Equivalent to `torch.logical_or(input, other)`. Returns 1.0 where
    /// at least one input is non-zero, 0.0 otherwise. Non-differentiable.
    pub fn tensor_logical_or(
        &mut self,
        input: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        if self.tensor_requires_grad(input)? || self.tensor_requires_grad(other)? {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "logical_or: autograd not supported (boolean ops are non-differentiable)",
                },
            )));
        }
        let shape = self.tensor_shape(input)?;
        let zeros = self.full(shape.clone(), 0.0, false)?;
        let a_bool = self.tensor_ne(input, zeros)?;
        let zeros2 = self.full(self.tensor_shape(other)?, 0.0, false)?;
        let b_bool = self.tensor_ne(other, zeros2)?;
        let sum = self.tensor_add(a_bool, b_bool)?;
        let ones = self.full(shape, 1.0, false)?;
        self.tensor_minimum(sum, ones)
    }

    /// Element-wise logical XOR.
    ///
    /// Equivalent to `torch.logical_xor(input, other)`. Returns 1.0 where
    /// exactly one input is non-zero, 0.0 otherwise. Non-differentiable.
    pub fn tensor_logical_xor(
        &mut self,
        input: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        if self.tensor_requires_grad(input)? || self.tensor_requires_grad(other)? {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "logical_xor: autograd not supported (boolean ops are non-differentiable)",
                },
            )));
        }
        let shape = self.tensor_shape(input)?;
        let zeros = self.full(shape, 0.0, false)?;
        let a_bool = self.tensor_ne(input, zeros)?;
        let zeros2 = self.full(self.tensor_shape(other)?, 0.0, false)?;
        let b_bool = self.tensor_ne(other, zeros2)?;
        self.tensor_ne(a_bool, b_bool)
    }

    /// In-place logical AND: target = target && other (as 1.0/0.0).
    pub fn tensor_logical_and_(
        &mut self,
        target: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<(), AutogradError> {
        self.validate_tensor_in_place_target(target)?;
        let result = self.tensor_logical_and(target, other)?;
        let result_vals = self.tensor_values(result)?;
        self.update_tensor_values_for_float(target, result_vals, INPLACE_FLOAT_REASON)?;
        self.record_tensor_in_place_operation("logical_and_", target, None);
        Ok(())
    }

    /// In-place logical OR: target = target || other (as 1.0/0.0).
    pub fn tensor_logical_or_(
        &mut self,
        target: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<(), AutogradError> {
        self.validate_tensor_in_place_target(target)?;
        let result = self.tensor_logical_or(target, other)?;
        let result_vals = self.tensor_values(result)?;
        self.update_tensor_values_for_float(target, result_vals, INPLACE_FLOAT_REASON)?;
        self.record_tensor_in_place_operation("logical_or_", target, None);
        Ok(())
    }

    /// In-place logical XOR: target = target ^ other (as 1.0/0.0).
    pub fn tensor_logical_xor_(
        &mut self,
        target: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<(), AutogradError> {
        self.validate_tensor_in_place_target(target)?;
        let result = self.tensor_logical_xor(target, other)?;
        let result_vals = self.tensor_values(result)?;
        self.update_tensor_values_for_float(target, result_vals, INPLACE_FLOAT_REASON)?;
        self.record_tensor_in_place_operation("logical_xor_", target, None);
        Ok(())
    }

    /// In-place logical NOT: target = !target (as 1.0/0.0).
    pub fn tensor_logical_not_(&mut self, target: TensorNodeId) -> Result<(), AutogradError> {
        self.validate_tensor_in_place_target(target)?;
        let result = self.tensor_logical_not(target)?;
        let result_vals = self.tensor_values(result)?;
        self.update_tensor_values_for_float(target, result_vals, INPLACE_FLOAT_REASON)?;
        self.record_tensor_in_place_operation("logical_not_", target, None);
        Ok(())
    }

    /// Element-wise bitwise AND.
    ///
    /// Casts to i64, performs bitwise AND, casts back to f64. Non-differentiable.
    // Shared no-grad binary-bitwise path: the old per-op code CLONED input via tensor_values (a
    // serial to_vec first-touch) + other via lossy_f64, then serially zip-mapped. When BOTH operands
    // are contiguous f64 (the common case) borrow them zero-copy and par_zip_map `f`; else fall back
    // to the clone. Bit-identical (order-invariant elementwise; `f` applied to the same i64 casts as
    // the per-op closures). frankentorch-bitwise-par.
    fn bitwise_binary_par_f64(
        &mut self,
        input: TensorNodeId,
        other: TensorNodeId,
        f: impl Fn(i64, i64) -> i64 + Sync,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        let numel = Self::checked_shape_numel(&shape, "bitwise: shape volume overflow")?;
        let other_numel =
            Self::checked_shape_numel(&self.tensor_shape(other)?, "bitwise: other shape overflow")?;
        if numel != other_numel {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: shape,
                    rhs: self.tensor_shape(other)?,
                },
            )));
        }
        let both_f64_contig = self.tensor_dtype(input)? == DType::F64
            && self.tensor_dtype(other)? == DType::F64
            && self.tensor_tape.tensor(input)?.meta().is_contiguous()
            && self.tensor_tape.tensor(other)?.meta().is_contiguous();
        let result: Vec<f64> = if both_f64_contig && numel >= PARALLEL_ELEMENTWISE_MIN {
            use rayon::prelude::*;
            let iv = self.tensor_tape.tensor(input)?.contiguous_values()?;
            let ov = self.tensor_tape.tensor(other)?.contiguous_values()?;
            iv.par_iter()
                .zip(ov.par_iter())
                .map(|(&a, &b)| f(a as i64, b as i64) as f64)
                .collect()
        } else {
            let input_vals = self.tensor_values(input)?;
            let other_vals = self.tensor_values_lossy_f64(other)?;
            input_vals
                .iter()
                .zip(other_vals.iter())
                .map(|(&a, &b)| f(a as i64, b as i64) as f64)
                .collect()
        };
        self.tensor_variable(result, shape, false)
    }

    pub fn tensor_bitwise_and(
        &mut self,
        input: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        if self.tensor_requires_grad(input)? || self.tensor_requires_grad(other)? {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "bitwise_and: autograd not supported (bitwise ops are non-differentiable)",
                },
            )));
        }
        self.bitwise_binary_par_f64(input, other, |a, b| a & b)
    }

    /// Element-wise bitwise OR.
    ///
    /// Casts to i64, performs bitwise OR, casts back to f64. Non-differentiable.
    pub fn tensor_bitwise_or(
        &mut self,
        input: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        if self.tensor_requires_grad(input)? || self.tensor_requires_grad(other)? {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "bitwise_or: autograd not supported (bitwise ops are non-differentiable)",
                },
            )));
        }
        self.bitwise_binary_par_f64(input, other, |a, b| a | b)
    }

    /// Element-wise bitwise XOR.
    ///
    /// Casts to i64, performs bitwise XOR, casts back to f64. Non-differentiable.
    pub fn tensor_bitwise_xor(
        &mut self,
        input: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        if self.tensor_requires_grad(input)? || self.tensor_requires_grad(other)? {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "bitwise_xor: autograd not supported (bitwise ops are non-differentiable)",
                },
            )));
        }
        self.bitwise_binary_par_f64(input, other, |a, b| a ^ b)
    }

    /// Element-wise bitwise NOT (complement).
    ///
    /// Casts to i64, performs bitwise NOT, casts back to f64. Non-differentiable.
    /// Equivalent to `torch.bitwise_not(input)`.
    pub fn tensor_bitwise_not(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        if self.tensor_requires_grad(input)? {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "bitwise_not: autograd not supported (bitwise ops are non-differentiable)",
                },
            )));
        }
        let shape = self.tensor_shape(input)?;
        let numel = Self::checked_shape_numel(&shape, "bitwise_not: shape volume overflow")?;
        // No-grad elementwise: the old path CLONED input via tensor_values (serial first-touch) then
        // mapped serially. Borrow the contiguous f64 input + par_map — bit-identical (order-invariant
        // elementwise). Non-contiguous / non-f64 / small fall back to the serial clone.
        let result: Vec<f64> = {
            let is_f64_contig = self.tensor_dtype(input)? == DType::F64
                && self.tensor_tape.tensor(input)?.meta().is_contiguous();
            if is_f64_contig && numel >= PARALLEL_ELEMENTWISE_MIN {
                use rayon::prelude::*;
                self.tensor_tape
                    .tensor(input)?
                    .contiguous_values()?
                    .par_iter()
                    .map(|&a| (!(a as i64)) as f64)
                    .collect()
            } else {
                self.tensor_values(input)?
                    .iter()
                    .map(|&a| (!(a as i64)) as f64)
                    .collect()
            }
        };
        self.tensor_variable(result, shape, false)
    }

    /// Element-wise bitwise left shift.
    ///
    /// Casts to i64, performs left shift, casts back to f64. Non-differentiable.
    pub fn tensor_bitwise_left_shift(
        &mut self,
        input: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        if self.tensor_requires_grad(input)? || self.tensor_requires_grad(other)? {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "bitwise_left_shift: autograd not supported (bitwise ops are non-differentiable)",
                },
            )));
        }
        self.bitwise_binary_par_f64(input, other, |a, b| {
            if (0..=63).contains(&b) {
                a.wrapping_shl(b as u32)
            } else {
                0
            }
        })
    }

    /// Element-wise bitwise right shift.
    ///
    /// Casts to i64, performs arithmetic right shift, casts back to f64. Non-differentiable.
    pub fn tensor_bitwise_right_shift(
        &mut self,
        input: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        if self.tensor_requires_grad(input)? || self.tensor_requires_grad(other)? {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "bitwise_right_shift: autograd not supported (bitwise ops are non-differentiable)",
                },
            )));
        }
        self.bitwise_binary_par_f64(input, other, |a, b| {
            if (0..=63).contains(&b) {
                a.wrapping_shr(b as u32)
            } else if a < 0 {
                -1
            } else {
                0
            }
        })
    }

    /// Element-wise copysign: `|magnitude| * sign(sign_tensor)`.
    ///
    /// Equivalent to `torch.copysign(magnitude, sign)`. Both inputs
    /// must have the same shape. Composes through tensor_abs +
    /// tensor_sign + tensor_mul. Non-differentiable through the sign
    /// branch (Dirac at 0); fail-loud on requires_grad on either input
    /// to avoid silently severing the autograd tape.
    /// Tracked under frankentorch-nezf.
    pub fn tensor_copysign(
        &mut self,
        magnitude: TensorNodeId,
        sign: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        if self.tensor_requires_grad(magnitude)? || self.tensor_requires_grad(sign)? {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "copysign: autograd not supported (sign is non-differentiable at 0). Tracked under frankentorch-nezf.",
                },
            )));
        }
        let m_shape = self.tensor_shape(magnitude)?;
        let s_shape = self.tensor_shape(sign)?;
        // torch.copysign broadcasts magnitude and sign; expand to the common
        // shape (a non-broadcastable mismatch still errors via broadcast_shape).
        let (magnitude, sign, m_shape) = if m_shape == s_shape {
            (magnitude, sign, m_shape)
        } else {
            let out = Self::broadcast_shape(&m_shape, &s_shape)?;
            (
                self.tensor_broadcast_to(magnitude, out.clone())?,
                self.tensor_broadcast_to(sign, out.clone())?,
                out,
            )
        };
        // Compute via f64::copysign on the raw values rather than
        // composing |m| * sign(s): tensor_sign returns 0 for both +0.0
        // and -0.0, so the previous abs * sign composition produced 0
        // when `sign` had any zero element. torch.copysign preserves
        // the IEEE 754 sign-of-zero (copysign(2.0, -0.0) == -2.0),
        // and so does Rust's f64::copysign. Dtype is preserved by
        // dispatching on the magnitude's dtype.
        let m_dtype = self.tensor_dtype(magnitude)?;
        // No-grad fast path (copysign is no-grad-only — it errors on grad above): the lossy
        // f64 reads CLONE both operands and the per-element copysign ran SERIALLY (measured
        // 7.46x SLOWER than torch). For equal-shape contiguous F64 operands, BORROW both and
        // copysign in parallel — no clones. Bit-exact (per-element, IEEE sign-of-zero
        // preserved by f64::copysign). f32 / non-contiguous fall through to the lossy read
        // (now also parallel).
        if m_dtype == DType::F64 && self.tensor_dtype(sign)? == DType::F64 {
            let built = {
                let mt = self.tensor_tape.tensor(magnitude)?;
                let st = self.tensor_tape.tensor(sign)?;
                if mt.meta().is_contiguous() && st.meta().is_contiguous() {
                    let md = mt.contiguous_values()?;
                    let sd = st.contiguous_values()?;
                    if md.len() == sd.len() {
                        use rayon::prelude::*;
                        let result: Vec<f64> = md
                            .par_iter()
                            .zip(sd.par_iter())
                            .map(|(&m, &s)| m.copysign(s))
                            .collect();
                        Some(result)
                    } else {
                        None
                    }
                } else {
                    None
                }
            };
            if let Some(result) = built {
                return self.tensor_variable(result, m_shape, false);
            }
        }
        // F32 fast path (was F64-only → f32 took the lossy path below: 2× f64 CLONES of both
        // operands + a f64→f32 conversion pass = ~17x SLOWER vs torch). Borrow both contiguous f32
        // buffers and copysign in parallel. Bit-exact — copysign is pure sign-bit (no rounding),
        // IEEE sign-of-zero preserved by f32::copysign.
        if m_dtype == DType::F32 && self.tensor_dtype(sign)? == DType::F32 {
            let built = {
                let mt = self.tensor_tape.tensor(magnitude)?;
                let st = self.tensor_tape.tensor(sign)?;
                if mt.meta().is_contiguous() && st.meta().is_contiguous() {
                    let md = mt.contiguous_values_f32()?;
                    let sd = st.contiguous_values_f32()?;
                    if md.len() == sd.len() {
                        use rayon::prelude::*;
                        let result: Vec<f32> = md
                            .par_iter()
                            .zip(sd.par_iter())
                            .map(|(&m, &s)| m.copysign(s))
                            .collect();
                        Some(result)
                    } else {
                        None
                    }
                } else {
                    None
                }
            };
            if let Some(result) = built {
                return self.tensor_variable_f32(result, m_shape, false);
            }
        }
        // Lossy f64 reads so f32 inputs are accepted (tensor_values is F64-only,
        // which made the F32 output branch below dead code). frankentorch-fk5l.
        let m_vals = self.tensor_values_lossy_f64(magnitude)?;
        let s_vals = self.tensor_values_lossy_f64(sign)?;
        let result: Vec<f64> = if m_vals.len() >= PARALLEL_ELEMENTWISE_MIN {
            use rayon::prelude::*;
            m_vals
                .par_iter()
                .zip(s_vals.par_iter())
                .map(|(&m, &s)| m.copysign(s))
                .collect()
        } else {
            m_vals
                .iter()
                .zip(s_vals.iter())
                .map(|(&m, &s)| m.copysign(s))
                .collect()
        };
        match m_dtype {
            DType::F32 => {
                let f32_result: Vec<f32> = result.into_iter().map(|v| v as f32).collect();
                self.tensor_variable_f32(f32_result, m_shape, false)
            }
            _ => self.tensor_variable(result, m_shape, false),
        }
    }

    /// In-place copysign: target = copysign(target, sign).
    pub fn tensor_copysign_(
        &mut self,
        target: TensorNodeId,
        sign: TensorNodeId,
    ) -> Result<(), AutogradError> {
        self.validate_tensor_in_place_target(target)?;
        if self.try_inplace_binary_f64(target, sign, "copysign_", |m, s| m.copysign(s))? {
            return Ok(());
        }
        let target_vals = self.tensor_values_lossy_f64(target)?;
        let sign_vals = self.tensor_values(sign)?;
        if target_vals.len() != sign_vals.len() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: self.tensor_shape(target)?,
                    rhs: self.tensor_shape(sign)?,
                },
            )));
        }
        let result: Vec<f64> = target_vals
            .iter()
            .zip(sign_vals.iter())
            .map(|(&m, &s)| m.copysign(s))
            .collect();
        self.update_tensor_values_for_float(target, result, INPLACE_FLOAT_REASON)?;
        self.record_tensor_in_place_operation("copysign_", target, None);
        Ok(())
    }

    /// `torch.nextafter(input, other)` parity: per-element next IEEE
    /// 754 representable value of `input` toward `other`.
    ///
    /// Routes through Rust's `f64::next_up` / `next_down` (and
    /// `f32` analogues for F32 inputs), which respect IEEE 754
    /// semantics: NaN propagates, `nextafter(x, x) == x`,
    /// `nextafter(±inf, _)` saturates correctly.
    ///
    /// Broadcasts operands with the same NumPy/PyTorch shape rules as
    /// other elementwise ops. Tracked under frankentorch-izkh.
    ///
    /// Non-differentiable (discontinuous at every representable f64
    /// step); fails loud on `requires_grad` like the other
    /// floor/round/discrete ops. Tracked under frankentorch-uh6t.
    pub fn tensor_nextafter(
        &mut self,
        input: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        if self.tensor_requires_grad(input)? || self.tensor_requires_grad(other)? {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "nextafter: autograd not supported (discontinuous at every IEEE 754 representable step). Tracked under frankentorch-uh6t.",
                },
            )));
        }
        let in_shape = self.tensor_shape(input)?;
        let oth_shape = self.tensor_shape(other)?;
        let dtype = self.tensor_dtype(input)?;
        let oth_dtype = self.tensor_dtype(other)?;
        if dtype != oth_dtype {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "nextafter: input and other must have the same dtype",
                },
            )));
        }
        if !matches!(dtype, DType::F32 | DType::F64) {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "nextafter requires f32 or f64 tensors",
                },
            )));
        }
        // No-grad fast path (nextafter is no-grad-only): the broadcast+`tensor_values` route
        // CLONES both operands and steps each element SERIALLY (measured 22.12x SLOWER than
        // torch). For equal-shape contiguous f64, BORROW both and step in parallel — no
        // clones. Bit-exact (same IEEE next_up/next_down predicate). f32 / broadcast /
        // non-contiguous fall through to the (now parallel) clone path below.
        if in_shape == oth_shape && dtype == DType::F64 {
            let built = {
                let it = self.tensor_tape.tensor(input)?;
                let ot = self.tensor_tape.tensor(other)?;
                if it.meta().is_contiguous() && ot.meta().is_contiguous() {
                    let id = it.contiguous_values()?;
                    let od = ot.contiguous_values()?;
                    if id.len() == od.len() {
                        use rayon::prelude::*;
                        let stepped: Vec<f64> = id
                            .par_iter()
                            .zip(od.par_iter())
                            .map(|(&x, &y)| {
                                if x.is_nan() || y.is_nan() {
                                    f64::NAN
                                } else if x == y {
                                    y
                                } else if x < y {
                                    x.next_up()
                                } else {
                                    x.next_down()
                                }
                            })
                            .collect();
                        Some(stepped)
                    } else {
                        None
                    }
                } else {
                    None
                }
            };
            if let Some(stepped) = built {
                return self.tensor_variable(stepped, in_shape, false);
            }
        }
        // Same lever for f32 (the asymmetric-dtype gap): the broadcast fall-through below upcasts
        // f32->f64 (two clones), downcasts back (two more Vecs), then steps SERIALLY — measured
        // 9.97x SLOWER than torch. For equal-shape contiguous f32, BORROW both and step in
        // parallel using the SAME f32 next_up/next_down predicate the serial path uses
        // (bit-exact to the current f32 output, which matches torch's nextafterf). frankentorch-specf32.
        if in_shape == oth_shape && dtype == DType::F32 {
            let built = {
                let it = self.tensor_tape.tensor(input)?;
                let ot = self.tensor_tape.tensor(other)?;
                if it.meta().is_contiguous() && ot.meta().is_contiguous() {
                    let id = it.contiguous_values_f32()?;
                    let od = ot.contiguous_values_f32()?;
                    if id.len() == od.len() {
                        use rayon::prelude::*;
                        let stepped: Vec<f32> = id
                            .par_iter()
                            .zip(od.par_iter())
                            .map(|(&x, &y)| {
                                if x.is_nan() || y.is_nan() {
                                    f32::NAN
                                } else if x == y {
                                    y
                                } else if x < y {
                                    x.next_up()
                                } else {
                                    x.next_down()
                                }
                            })
                            .collect();
                        Some(stepped)
                    } else {
                        None
                    }
                } else {
                    None
                }
            };
            if let Some(stepped) = built {
                return self.tensor_variable_f32(stepped, in_shape, false);
            }
        }
        let out_shape = Self::broadcast_shape(&in_shape, &oth_shape)?;
        let input_b = self.tensor_broadcast_to(input, out_shape.clone())?;
        let other_b = self.tensor_broadcast_to(other, out_shape.clone())?;
        let in_vals = self.tensor_values(input_b)?;
        let oth_vals = self.tensor_values(other_b)?;

        match dtype {
            DType::F32 => {
                // Round-trip via f32 to preserve dtype. f32 has its own
                // next_up/next_down; recompute on f32 to avoid f64↔f32
                // boundary mismatches at the next-representable step.
                let in_f32: Vec<f32> = in_vals.into_iter().map(|v| v as f32).collect();
                let oth_f32: Vec<f32> = oth_vals.into_iter().map(|v| v as f32).collect();
                let stepped_f32: Vec<f32> = in_f32
                    .iter()
                    .zip(oth_f32.iter())
                    .map(|(&x, &y)| {
                        if x.is_nan() || y.is_nan() {
                            f32::NAN
                        } else if x == y {
                            y
                        } else if x < y {
                            x.next_up()
                        } else {
                            x.next_down()
                        }
                    })
                    .collect();
                self.tensor_variable_f32(stepped_f32, out_shape, false)
            }
            _ => {
                // f64::next_up / next_down: IEEE 754-aware single-step
                // neighbors with correct NaN / ±inf semantics.
                let stepped: Vec<f64> = in_vals
                    .iter()
                    .zip(oth_vals.iter())
                    .map(|(&x, &y)| {
                        if x.is_nan() || y.is_nan() {
                            f64::NAN
                        } else if x == y {
                            y
                        } else if x < y {
                            x.next_up()
                        } else {
                            x.next_down()
                        }
                    })
                    .collect();
                self.tensor_variable(stepped, out_shape, false)
            }
        }
    }

    /// F64 borrow+parallel fast path for an in-place elementwise-binary op (asymmetric-dtype
    /// vein): the generic paths CLONE BOTH operands via `tensor_values_lossy_f64` then map
    /// SERIALLY. When both are F64 + contiguous + equal-length, borrow both `contiguous_values()`
    /// (`&[f64]`, no clone) and apply `f` in parallel — BIT-IDENTICAL to the serial
    /// `.iter().zip().map(f)` (each lane is independent). Returns `Ok(true)` if handled, `Ok(false)`
    /// to fall through to the generic clone-both path. frankentorch (BlackThrush).
    fn try_inplace_binary_f64<F: Fn(f64, f64) -> f64 + Sync>(
        &mut self,
        target: TensorNodeId,
        other: TensorNodeId,
        op_name: &'static str,
        f: F,
    ) -> Result<bool, AutogradError> {
        if self.tensor_dtype(target)? != DType::F64 || self.tensor_dtype(other)? != DType::F64 {
            return Ok(false);
        }
        let built = {
            let tt = self.tensor_tape.tensor(target)?;
            let ot = self.tensor_tape.tensor(other)?;
            if tt.meta().is_contiguous() && ot.meta().is_contiguous() {
                let tv = tt.contiguous_values()?;
                let ov = ot.contiguous_values()?;
                if tv.len() == ov.len() {
                    use rayon::prelude::*;
                    Some(
                        tv.par_iter()
                            .zip(ov.par_iter())
                            .map(|(&a, &b)| f(a, b))
                            .collect::<Vec<f64>>(),
                    )
                } else {
                    None
                }
            } else {
                None
            }
        };
        match built {
            Some(result) => {
                self.update_tensor_values_for_float(target, result, INPLACE_FLOAT_REASON)?;
                self.record_tensor_in_place_operation(op_name, target, None);
                Ok(true)
            }
            None => Ok(false),
        }
    }

    /// F64 borrow+parallel fast path for an in-place elementwise-TERNARY op (addcmul_/addcdiv_):
    /// the generic paths CLONE ALL THREE operands via `tensor_values_lossy_f64` then map SERIALLY.
    /// When all three are F64 + contiguous + equal-length, borrow all three `contiguous_values()`
    /// (no clone) and apply `f(t, t1, t2)` in parallel — BIT-IDENTICAL to the serial
    /// `.iter().zip().zip().map(f)`. Returns `Ok(true)` if handled, `Ok(false)` to fall through.
    fn try_inplace_ternary_f64<F: Fn(f64, f64, f64) -> f64 + Sync>(
        &mut self,
        target: TensorNodeId,
        t1: TensorNodeId,
        t2: TensorNodeId,
        op_name: &'static str,
        detail: Option<String>,
        f: F,
    ) -> Result<bool, AutogradError> {
        if self.tensor_dtype(target)? != DType::F64
            || self.tensor_dtype(t1)? != DType::F64
            || self.tensor_dtype(t2)? != DType::F64
        {
            return Ok(false);
        }
        let built = {
            let tt = self.tensor_tape.tensor(target)?;
            let t1t = self.tensor_tape.tensor(t1)?;
            let t2t = self.tensor_tape.tensor(t2)?;
            if tt.meta().is_contiguous() && t1t.meta().is_contiguous() && t2t.meta().is_contiguous()
            {
                let tv = tt.contiguous_values()?;
                let av = t1t.contiguous_values()?;
                let bv = t2t.contiguous_values()?;
                if tv.len() == av.len() && tv.len() == bv.len() {
                    use rayon::prelude::*;
                    Some(
                        tv.par_iter()
                            .zip(av.par_iter())
                            .zip(bv.par_iter())
                            .map(|((&t, &a), &b)| f(t, a, b))
                            .collect::<Vec<f64>>(),
                    )
                } else {
                    None
                }
            } else {
                None
            }
        };
        match built {
            Some(result) => {
                self.update_tensor_values_for_float(target, result, INPLACE_FLOAT_REASON)?;
                self.record_tensor_in_place_operation(op_name, target, detail);
                Ok(true)
            }
            None => Ok(false),
        }
    }

    /// In-place nextafter: target = nextafter(target, other).
    pub fn tensor_nextafter_(
        &mut self,
        target: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<(), AutogradError> {
        self.validate_tensor_in_place_target(target)?;
        if self.try_inplace_binary_f64(target, other, "nextafter_", |x, y| {
            if x.is_nan() || y.is_nan() {
                f64::NAN
            } else if x == y {
                y
            } else if x < y {
                x.next_up()
            } else {
                x.next_down()
            }
        })? {
            return Ok(());
        }
        let target_vals = self.tensor_values_lossy_f64(target)?;
        let other_vals = self.tensor_values_lossy_f64(other)?;
        if target_vals.len() != other_vals.len() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: self.tensor_shape(target)?,
                    rhs: self.tensor_shape(other)?,
                },
            )));
        }
        let result: Vec<f64> = target_vals
            .iter()
            .zip(other_vals.iter())
            .map(|(&x, &y)| {
                if x.is_nan() || y.is_nan() {
                    f64::NAN
                } else if x == y {
                    y
                } else if x < y {
                    x.next_up()
                } else {
                    x.next_down()
                }
            })
            .collect();
        self.update_tensor_values_for_float(target, result, INPLACE_FLOAT_REASON)?;
        self.record_tensor_in_place_operation("nextafter_", target, None);
        Ok(())
    }

    /// Heaviside step function: `0 if x<0, 1 if x>0, values[i] if x==0`.
    ///
    /// Equivalent to `torch.heaviside(input, values)`. `values` must
    /// have the same shape as `input` (the value taken at the
    /// discontinuity is supplied per-element).
    ///
    /// Non-differentiable: the step has a Dirac delta at 0. Fail-loud
    /// on tracked input to avoid silently severing the autograd tape.
    /// Tracked under frankentorch-b4m6.
    pub fn tensor_heaviside(
        &mut self,
        input: TensorNodeId,
        values: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        if self.tensor_requires_grad(input)? || self.tensor_requires_grad(values)? {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "heaviside: autograd not supported (step function is non-differentiable). Tracked under frankentorch-b4m6.",
                },
            )));
        }
        let in_shape = self.tensor_shape(input)?;
        let v_shape = self.tensor_shape(values)?;
        // torch.heaviside broadcasts input and values; expand to the common shape
        // so the composed step/where output broadcasts (mismatch still errors).
        let (input, values, in_shape) = if in_shape == v_shape {
            (input, values, in_shape)
        } else {
            let out = Self::broadcast_shape(&in_shape, &v_shape)?;
            (
                self.tensor_broadcast_to(input, out.clone())?,
                self.tensor_broadcast_to(values, out.clone())?,
                out,
            )
        };
        // No-grad fast path (heaviside is no-grad-only): the tensor_values reads CLONE both
        // operands and the per-element step ran SERIALLY (measured 8.82x SLOWER than torch).
        // For equal-shape contiguous f64, BORROW both and step in parallel — no clones.
        // Bit-exact (same predicate; NaN input → 0, no propagation). f32 / broadcast /
        // non-contiguous fall through to the clone path below.
        if self.tensor_dtype(input)? == DType::F64 && self.tensor_dtype(values)? == DType::F64 {
            let built = {
                let it = self.tensor_tape.tensor(input)?;
                let vt = self.tensor_tape.tensor(values)?;
                if it.meta().is_contiguous() && vt.meta().is_contiguous() {
                    let xd = it.contiguous_values()?;
                    let vd = vt.contiguous_values()?;
                    if xd.len() == vd.len() {
                        use rayon::prelude::*;
                        let out: Vec<f64> = xd
                            .par_iter()
                            .zip(vd.par_iter())
                            .map(|(&x, &v)| {
                                if x > 0.0 {
                                    1.0
                                } else if x == 0.0 {
                                    v
                                } else {
                                    0.0
                                }
                            })
                            .collect();
                        Some(out)
                    } else {
                        None
                    }
                } else {
                    None
                }
            };
            if let Some(out) = built {
                return self.tensor_variable(out, in_shape, false);
            }
        }
        // F32 fast path mirroring the F64 one. CRITICAL: this also FIXES A BUG — f32 heaviside
        // previously fell through to the `tensor_values` (F64-only) fallback below, which ERRORS
        // `UnsupportedDType(F32)`, so f32 heaviside was entirely broken (torch supports it). Borrow
        // both contiguous f32 buffers and step in parallel. Bit-exact (deterministic step: x>0→1,
        // x==0→v, else 0; NaN→0).
        if self.tensor_dtype(input)? == DType::F32 && self.tensor_dtype(values)? == DType::F32 {
            let built = {
                let it = self.tensor_tape.tensor(input)?;
                let vt = self.tensor_tape.tensor(values)?;
                if it.meta().is_contiguous() && vt.meta().is_contiguous() {
                    let xd = it.contiguous_values_f32()?;
                    let vd = vt.contiguous_values_f32()?;
                    if xd.len() == vd.len() {
                        use rayon::prelude::*;
                        let out: Vec<f32> = xd
                            .par_iter()
                            .zip(vd.par_iter())
                            .map(|(&x, &v)| {
                                if x > 0.0 {
                                    1.0
                                } else if x == 0.0 {
                                    v
                                } else {
                                    0.0
                                }
                            })
                            .collect();
                        Some(out)
                    } else {
                        None
                    }
                } else {
                    None
                }
            };
            if let Some(out) = built {
                return self.tensor_variable_f32(out, in_shape, false);
            }
        }
        // F64 fast path (asymmetric-dtype mirror of the F32 path above): the generic path below
        // CLONES BOTH operands via `tensor_values_lossy_f64` (2x to_vec) then steps SERIALLY. Borrow
        // both contiguous f64 buffers + step in parallel. BIT-IDENTICAL (same deterministic step:
        // x>0→1, x==0→v, else 0; NaN→0). Broadcast / non-contiguous fall through to the generic path.
        // frankentorch (BlackThrush).
        if self.tensor_dtype(input)? == DType::F64 && self.tensor_dtype(values)? == DType::F64 {
            let built = {
                let it = self.tensor_tape.tensor(input)?;
                let vt = self.tensor_tape.tensor(values)?;
                if it.meta().is_contiguous() && vt.meta().is_contiguous() {
                    let xd = it.contiguous_values()?;
                    let vd = vt.contiguous_values()?;
                    if xd.len() == vd.len() {
                        use rayon::prelude::*;
                        let out: Vec<f64> = xd
                            .par_iter()
                            .zip(vd.par_iter())
                            .map(|(&x, &v)| {
                                if x > 0.0 {
                                    1.0
                                } else if x == 0.0 {
                                    v
                                } else {
                                    0.0
                                }
                            })
                            .collect();
                        Some(out)
                    } else {
                        None
                    }
                } else {
                    None
                }
            };
            if let Some(out) = built {
                return self.tensor_variable(out, in_shape, false);
            }
        }
        // torch.heaviside(x, v) = (x > 0) ? 1 : (x == 0) ? v : 0.
        //
        // A NaN input falls through BOTH comparisons → 0: torch does NOT
        // propagate NaN here (verified torch 2.12: heaviside(NaN, _) == 0.0;
        // the prior impl wrongly forced NaN under frankentorch-cc2o). `v` is
        // consulted ONLY at x == 0, so a non-finite `v` never leaks into a
        // non-zero / NaN x — the old mask form `pos + zero_mask * v` produced
        // 0 * inf = NaN there (e.g. heaviside(-1, inf) → NaN, torch → 0).
        // Computed eagerly since heaviside is non-differentiable (the
        // requires_grad guard above already rejected the tracked case).
        // Lossy f64 reads so f32 (broadcast / non-contiguous) inputs are accepted instead of erroring
        // in the old F64-only `tensor_values` reads; the dtype-preserve narrow below restores f32.
        // frankentorch-ft3fp.
        let xv = self.tensor_values_lossy_f64(input)?;
        let vv = self.tensor_values_lossy_f64(values)?;
        let out: Vec<f64> = xv
            .iter()
            .zip(vv.iter())
            .map(|(&x, &v)| {
                if x > 0.0 {
                    1.0
                } else if x == 0.0 {
                    v
                } else {
                    0.0
                }
            })
            .collect();
        let result = self.tensor_variable(out, in_shape, false)?;
        // torch.heaviside requires input.dtype == values.dtype and returns it;
        // preserve the input dtype (a no-op when it is already f64).
        let in_dtype = self.tensor_dtype(input)?;
        if in_dtype == DType::F64 {
            Ok(result)
        } else {
            self.tensor_to_dtype(result, in_dtype)
        }
    }

    /// In-place heaviside: target = 0 if target < 0, 1 if target > 0, values[i] if target == 0.
    pub fn tensor_heaviside_(
        &mut self,
        target: TensorNodeId,
        values: TensorNodeId,
    ) -> Result<(), AutogradError> {
        self.validate_tensor_in_place_target(target)?;
        // F64 borrow+parallel fast path (same idiom as atan2_/hypot_/xlogy_): the
        // serial path clones BOTH operands (lossy_f64 + tensor_values) then maps
        // serially. Bit-identical to the fallback (torch.heaviside step, no NaN
        // propagation), f64+contiguous only. frankentorch-inplace-binary-fastpath.
        if self.try_inplace_binary_f64(target, values, "heaviside_", |x, v| {
            if x > 0.0 {
                1.0
            } else if x == 0.0 {
                v
            } else {
                0.0
            }
        })? {
            return Ok(());
        }
        let target_vals = self.tensor_values_lossy_f64(target)?;
        let values_vals = self.tensor_values(values)?;
        if target_vals.len() != values_vals.len() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: self.tensor_shape(target)?,
                    rhs: self.tensor_shape(values)?,
                },
            )));
        }
        let result: Vec<f64> = target_vals
            .iter()
            .zip(values_vals.iter())
            // torch.heaviside(x, v) = (x > 0) ? 1 : (x == 0) ? v : 0. NaN falls
            // through both comparisons → 0 (torch does NOT propagate NaN here;
            // frankentorch-ft3fp). Matches the out-of-place tensor_heaviside.
            .map(|(&x, &v)| {
                if x > 0.0 {
                    1.0
                } else if x == 0.0 {
                    v
                } else {
                    0.0
                }
            })
            .collect();
        self.update_tensor_values_for_float(target, result, INPLACE_FLOAT_REASON)?;
        self.record_tensor_in_place_operation("heaviside_", target, None);
        Ok(())
    }

    /// Normalized sinc function: `sin(pi*x) / (pi*x)`, with `sinc(0) = 1`.
    ///
    /// Equivalent to `torch.sinc(input)`. Handles the x = 0 case via
    /// a tensor_where + safe denominator: at x=0 we route to the
    /// constant tensor 1 instead of evaluating 0/0. Gradient at x=0
    /// is correctly 0 (the where routes there to a no-grad constant).
    /// Composes through autograd-aware tensor_mul + tensor_sin +
    /// tensor_div + tensor_eq + tensor_where. Tracked under
    /// frankentorch-zl65.
    pub fn tensor_sinc(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        // No-grad fast path: the composed path below (full_like x3 + mul + sin + eq +
        // where x2 + div = ~9 passes over numel) measured 4.01x SLOWER than torch. For
        // no-grad contiguous f64, borrow the input and compute sinc(x) = sin(pi*x)/(pi*x)
        // (1.0 at x == 0) in ONE parallel pass. Bit-exact with the composed path: pi*x is
        // the same IEEE product (commutative), the sin is the same libm f64::sin, and the
        // x == 0 -> 1.0 select matches the final tensor_where (incl. -0.0 and NaN). f32 /
        // grad / non-contiguous fall through to the composed (autograd-aware) path.
        // f32-native fast path (same closure as the f64 one): the f32 case fell to the ~9-pass
        // compose = ~5x SLOWER. Bit-identical to current f32 (composed in f64 then narrowed).
        if let Some(out) = self.try_f32_unary_native(input, |x| {
            if x == 0.0 {
                1.0
            } else {
                let px = std::f64::consts::PI * x;
                px.sin() / px
            }
        })? {
            return Ok(out);
        }
        if !self.tensor_requires_grad(input)? && self.tensor_dtype(input)? == DType::F64 {
            let built = {
                let it = self.tensor_tape.tensor(input)?;
                if it.meta().is_contiguous() {
                    let xd = it.contiguous_values()?;
                    use rayon::prelude::*;
                    let out: Vec<f64> = xd
                        .par_iter()
                        .map(|&x| {
                            if x == 0.0 {
                                1.0
                            } else {
                                let px = std::f64::consts::PI * x;
                                px.sin() / px
                            }
                        })
                        .collect();
                    Some(out)
                } else {
                    None
                }
            };
            if let Some(out) = built {
                let shape = self.tensor_shape(input)?;
                return self.tensor_variable(out, shape, false);
            }
        }
        // Constants are built with full_like(input, ..) (not full(shape, ..))
        // so they match the input's dtype: an f32 input keeps f32 through the
        // mul/eq/where chain (torch sinc(f32) -> f32), and tensor_eq no longer
        // hits a dtype mismatch against an f64 zeros tensor. frankentorch-fk5l.
        let pi_t = self.full_like(input, std::f64::consts::PI, false)?;
        let pi_x = self.tensor_mul(input, pi_t)?;
        let sin_pi_x = self.tensor_sin(pi_x)?;

        // Build the zero mask and the safe denominator. The safe
        // denominator is pi*x where x != 0, and 1 where x == 0 — the
        // exact value at masked positions doesn't matter because
        // tensor_where will discard it.
        //
        // Single zero / ones / zero_mask shared across both
        // tensor_where stages (frankentorch-d521): tensor_mul /
        // tensor_eq / tensor_where only READ their constant inputs,
        // and pi_x_safe_a was identical to pi_x — feeding pi_x into
        // both safe_denom and ratio drops one tensor_mul. Saves 3
        // full() allocations + 1 tensor_mul + 1 tensor_eq + 5 graph
        // nodes per sinc call, no behavior change.
        let zeros = self.full_like(input, 0.0, false)?;
        let zero_mask = self.tensor_eq(input, zeros)?;
        let ones = self.full_like(input, 1.0, false)?;
        let safe_denom = self.tensor_where(zero_mask, ones, pi_x)?;
        let ratio = self.tensor_div(sin_pi_x, safe_denom)?;

        // Final select: at x = 0 → 1.0; otherwise the ratio.
        self.tensor_where(zero_mask, ones, ratio)
    }

    /// Spherical Bessel function of the first kind, order 0.
    ///
    /// Equivalent to `torch.special.spherical_bessel_j0(input)`:
    ///   j0(x) = sin(x) / x,  with the removable singularity j0(0) = 1.
    /// Composed from autograd-aware primitives, so the gradient
    /// (j0'(x) = cos(x)/x − sin(x)/x², and j0'(0) = 0) flows automatically;
    /// the x = 0 branch is the constant 1, matching torch's zero gradient there.
    pub fn tensor_special_spherical_bessel_j0(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // f32-native fast path (no-grad): the autograd compose below is 7 tape ops (sin +
        // full_like×2 + eq + where×2 + div), each a full pass over the data plus a 64MB
        // intermediate — measured 3.30x SLOWER than torch's single vectorized sin(x)/x. Compute
        // j0(x) = (x==0 ? 1 : sin(x)/x) in ONE parallel f64-narrowed pass. This is a <1e-5
        // tolerance special fn (not bit-exact; torch uses an FMA/vectorized kernel), and the
        // f64-then-narrow value is at-or-more-accurate than the prior f32 compose. The grad path
        // (and f64 / non-contiguous) keep the compose. frankentorch-specf32.
        if let Some(out) =
            self.try_f32_unary_native(input, |x| if x == 0.0 { 1.0 } else { x.sin() / x })?
        {
            return Ok(out);
        }
        let sin_x = self.tensor_sin(input)?;
        // Safe denominator: x where x != 0, else 1 (the masked value is discarded
        // by the final where, so it only needs to avoid a 0/0 NaN). Constants via
        // full_like so an f32 input keeps f32 (torch parity) and tensor_eq matches
        // dtype. frankentorch-fk5l.
        let zeros = self.full_like(input, 0.0, false)?;
        let zero_mask = self.tensor_eq(input, zeros)?;
        let ones = self.full_like(input, 1.0, false)?;
        let safe_denom = self.tensor_where(zero_mask, ones, input)?;
        let ratio = self.tensor_div(sin_x, safe_denom)?;
        // At x = 0 → 1.0; otherwise sin(x)/x.
        self.tensor_where(zero_mask, ones, ratio)
    }

    /// Airy function of the first kind, Ai(x).
    ///
    /// Equivalent to `torch.special.airy_ai(input)`. Elementwise. Like the other
    /// Airy/Bessel special functions in torch.special, this is forward-only
    /// (torch registers no backward for it), so the result is a non-grad leaf.
    /// torch float type-promotion for a binary elementwise op: f64 if either
    /// operand is f64, else f32 if either is f32, else the (equal) input dtype.
    /// Used by the f32 cast-recurse prepends (frankentorch-77o4c).
    fn promote_float_pair(a: DType, b: DType) -> DType {
        if a == DType::F64 || b == DType::F64 {
            DType::F64
        } else if a == DType::F32 || b == DType::F32 {
            DType::F32
        } else {
            a
        }
    }

    pub fn tensor_special_airy_ai(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // f32-native fast path (no f32->f64 upcast = ~2.7x SLOWER). Bit-identical.
        if let Some(out) = self.try_f32_unary_native(input, airy_ai_scalar)? {
            return Ok(out);
        }
        // No-grad f64 borrow fast path: the no-grad path below CLONES the input via
        // contiguous_values_as_f64().to_vec() / tensor_values; try_f64_unary_native BORROWS it.
        // Bit-exact (same airy_ai_scalar). frankentorch-airy_ai_scalar-f64-borrow.
        if let Some(out) = self.try_f64_unary_native(input, airy_ai_scalar)? {
            return Ok(out);
        }
        // f32/half: compute in f64 then cast back (the read is f64-only). torch
        // keeps the input dtype. frankentorch-77o4c.
        let dt = self.tensor_dtype(input)?;
        if dt != DType::F64 {
            let in64 = self.tensor_to_dtype(input, DType::F64)?;
            let out64 = self.tensor_special_airy_ai(in64)?;
            return self.tensor_to_dtype(out64, dt);
        }
        let (vals, meta) = self.tensor_values_meta(input)?;
        let result: Vec<f64> = par_map_f64(&vals, airy_ai_scalar);
        self.tensor_variable(result, meta.shape().to_vec(), false)
    }

    /// L2 hypotenuse.
    ///
    /// Equivalent to `torch.hypot(x, y)`. Element-wise. Uses the stable
    /// hypot primitive instead of expanding to `sqrt(x*x + y*y)`, preserving
    /// PyTorch/C99 behavior for overflow and inf/nan pairs. Gradients are
    /// ∂hypot/∂x = x / hypot, ∂hypot/∂y = y / hypot. Tracked under
    /// frankentorch-k3p4.
    pub fn tensor_hypot(
        &mut self,
        x: TensorNodeId,
        y: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // f32-native fast path: the path below UPCASTS both f32 operands to f64 (tensor_to_f64
        // x2 = 256MB) before the `xi.hypot(yi)` kernel = ~13x SLOWER than torch. Same value
        // (`(x as f64).hypot(y as f64) as f32` == the f64-kernel-then-narrow), bit-identical to
        // the current f32 behaviour. Equal-shape contiguous no-grad; broadcast falls through.
        if let Some(out) = self.try_f32_binary_native(x, y, |a, b| a.hypot(b))? {
            return Ok(out);
        }
        let x_shape = self.tensor_shape(x)?;
        let y_shape = self.tensor_shape(y)?;
        // torch.hypot broadcasts x and y; compute the common shape and expand the
        // (dtype-normalized) operands below before the element-wise kernel. A
        // non-broadcastable mismatch still errors here via broadcast_shape.
        let hypot_out_shape = if x_shape == y_shape {
            None
        } else {
            Some(Self::broadcast_shape(&x_shape, &y_shape)?)
        };
        let x_dtype = self.tensor_dtype(x)?;
        let y_dtype = self.tensor_dtype(y)?;
        let output_dtype = if x_dtype == DType::F32 && y_dtype == DType::F32 {
            DType::F32
        } else {
            DType::F64
        };
        let x_input = if x_dtype == DType::F64 {
            x
        } else {
            self.tensor_to_f64(x)?
        };
        let y_input = if y_dtype == DType::F64 {
            y
        } else {
            self.tensor_to_f64(y)?
        };
        let (x_input, y_input) = if let Some(out_shape) = hypot_out_shape {
            (
                self.tensor_broadcast_to(x_input, out_shape.clone())?,
                self.tensor_broadcast_to(y_input, out_shape)?,
            )
        } else {
            (x_input, y_input)
        };

        let out = self.tensor_apply_function(
            &[x_input, y_input],
            |ctx, inputs| {
                let (x_vals, x_shape) = inputs[0];
                let (y_vals, y_shape) = inputs[1];
                if x_shape != y_shape {
                    // Migrate to ShapeMismatch to surface lhs + rhs
                    // shapes in the diagnostic (frankentorch-c991).
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                        ft_kernel_cpu::KernelError::ShapeMismatch {
                            lhs: x_shape.to_vec(),
                            rhs: y_shape.to_vec(),
                        },
                    )));
                }

                // Only clone the operands for backward when a gradient is actually
                // needed — apply_function runs this forward unconditionally, so in the
                // no-grad case the two save_for_backward to_vec()s were 2*numel dead
                // clones (measured 10x SLOWER than torch). And the per-element hypot is
                // compute-bound, so parallelize it across the rayon pool. Bit-exact
                // (per-element, order-independent). frankentorch-kgs4.
                if ctx.needs_input_grad().iter().any(|&g| g) {
                    ctx.save_for_backward(x_vals.to_vec(), x_shape.to_vec());
                    ctx.save_for_backward(y_vals.to_vec(), y_shape.to_vec());
                }
                let values: Vec<f64> = if x_vals.len() >= PARALLEL_ELEMENTWISE_MIN {
                    use rayon::prelude::*;
                    x_vals
                        .par_iter()
                        .zip(y_vals.par_iter())
                        .map(|(&xi, &yi)| xi.hypot(yi))
                        .collect()
                } else {
                    x_vals
                        .iter()
                        .zip(y_vals.iter())
                        .map(|(&xi, &yi)| xi.hypot(yi))
                        .collect()
                };
                Ok((values, x_shape.to_vec()))
            },
            |ctx, grad_outputs| {
                let grad_out = grad_outputs[0];
                let x_vals = &ctx.saved_tensors()[0];
                let y_vals = &ctx.saved_tensors()[1];
                if grad_out.len() != x_vals.len() || x_vals.len() != y_vals.len() {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "hypot backward: incoming gradient length mismatch",
                        },
                    )));
                }

                let needs_grad = ctx.needs_input_grad();
                let mut grad_x = Vec::with_capacity(x_vals.len());
                let mut grad_y = Vec::with_capacity(y_vals.len());
                for ((&xi, &yi), &go) in x_vals.iter().zip(y_vals.iter()).zip(grad_out.iter()) {
                    let h = xi.hypot(yi);
                    grad_x.push(go * xi / h);
                    grad_y.push(go * yi / h);
                }

                Ok(vec![
                    needs_grad[0].then_some(grad_x),
                    needs_grad[1].then_some(grad_y),
                ])
            },
        )?;
        if output_dtype == DType::F32 {
            self.tensor_to_f32(out)
        } else {
            Ok(out)
        }
    }

    /// In-place hypot: target = sqrt(target^2 + other^2).
    pub fn tensor_hypot_(
        &mut self,
        target: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<(), AutogradError> {
        self.validate_tensor_in_place_target(target)?;
        if self.try_inplace_binary_f64(target, other, "hypot_", |x, y| x.hypot(y))? {
            return Ok(());
        }
        let target_vals = self.tensor_values_lossy_f64(target)?;
        let other_vals = self.tensor_values_lossy_f64(other)?;
        if target_vals.len() != other_vals.len() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: self.tensor_shape(target)?,
                    rhs: self.tensor_shape(other)?,
                },
            )));
        }
        let result: Vec<f64> = target_vals
            .iter()
            .zip(other_vals.iter())
            .map(|(&x, &y)| x.hypot(y))
            .collect();
        self.update_tensor_values_for_float(target, result, INPLACE_FLOAT_REASON)?;
        self.record_tensor_in_place_operation("hypot_", target, None);
        Ok(())
    }

    /// Convert from degrees to radians.
    ///
    /// Equivalent to `torch.deg2rad(input)`. Element-wise multiply by
    /// pi / 180. Composes through autograd-aware tensor_mul.
    /// Tracked under frankentorch-obts.
    pub fn tensor_deg2rad(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        // f32-native fast path: the compose below builds a 128MB f64 constant tensor via full()
        // then tensor_mul = ~13x SLOWER than torch for a TRIVIAL scale. `x * (pi/180)` in one
        // pass = bit-identical (same f64 constant, same product narrowed to f32).
        if let Some(out) =
            self.try_f32_unary_native(input, |x| x * (std::f64::consts::PI / 180.0))?
        {
            return Ok(out);
        }
        if let Some(out) =
            self.try_f64_unary_native(input, |x| x * (std::f64::consts::PI / 180.0))?
        {
            return Ok(out);
        }
        let shape = self.tensor_shape(input)?;
        let factor = self.full(shape, std::f64::consts::PI / 180.0, false)?;
        self.tensor_mul(input, factor)
    }

    /// Convert from radians to degrees.
    ///
    /// Equivalent to `torch.rad2deg(input)`. Element-wise multiply by
    /// 180 / pi. Composes through autograd-aware tensor_mul.
    /// Tracked under frankentorch-obts.
    pub fn tensor_rad2deg(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        // f32-native fast path (sibling of deg2rad): `x * (180/pi)` in one pass instead of a
        // 128MB-full() + tensor_mul compose (~14x SLOWER for a trivial scale). Bit-identical.
        if let Some(out) =
            self.try_f32_unary_native(input, |x| x * (180.0 / std::f64::consts::PI))?
        {
            return Ok(out);
        }
        if let Some(out) =
            self.try_f64_unary_native(input, |x| x * (180.0 / std::f64::consts::PI))?
        {
            return Ok(out);
        }
        let shape = self.tensor_shape(input)?;
        let factor = self.full(shape, 180.0 / std::f64::consts::PI, false)?;
        self.tensor_mul(input, factor)
    }

    /// SoftShrink activation: soft thresholding by `lambd`.
    ///
    /// `out = x - lambd if x > lambd; x + lambd if x < -lambd; else 0`.
    /// Equivalent to `torch.nn.functional.softshrink(input, lambd)`.
    /// Common as the proximal operator of the L1 norm in
    /// ISTA/FISTA/sparse-coding training loops.
    ///
    /// Composes through autograd-aware tensor_gt/lt + tensor_where +
    /// tensor_sub/add. Gradient is 1 outside [-lambd, lambd] and 0
    /// inside (the where routes the inside region to the no-grad
    /// zeros constant). Tracked under frankentorch-t503.
    pub fn tensor_softshrink(
        &mut self,
        input: TensorNodeId,
        lambd: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        if !lambd.is_finite() || lambd < 0.0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "softshrink: lambd must be finite and non-negative",
                },
            )));
        }
        let shape = self.tensor_shape(input)?;
        // No-grad fast path: the composed path below (const_tensor_like x3 + gt + lt + sub +
        // add + where x2 = ~9 passes over numel) measured 8.14x SLOWER than torch. For no-grad
        // contiguous f64, borrow the input and compute softshrink in ONE parallel pass:
        // x > λ ? x-λ : (x < -λ ? x+λ : 0). Bit-exact with the composed three-way where (the
        // two masks are mutually exclusive; boundary/NaN match: x==±λ and NaN fall to 0).
        // f32 / grad / non-contiguous fall through.
        if !self.tensor_requires_grad(input)? && self.tensor_dtype(input)? == DType::F64 {
            let built = {
                let it = self.tensor_tape.tensor(input)?;
                if it.meta().is_contiguous() {
                    let xd = it.contiguous_values()?;
                    use rayon::prelude::*;
                    let out: Vec<f64> = xd
                        .par_iter()
                        .map(|&x| {
                            if x > lambd {
                                x - lambd
                            } else if x < -lambd {
                                x + lambd
                            } else {
                                0.0
                            }
                        })
                        .collect();
                    Some(out)
                } else {
                    None
                }
            };
            if let Some(out) = built {
                return self.tensor_variable(out, shape, false);
            }
        }
        // F32 mirror (was F64-only → f32 took the ~9-pass composed path, ~43x SLOWER vs torch).
        // The composed path's const_tensor_like casts λ to f32 and runs f32 gt/sub/add, so a single
        // f32 pass with `lambd as f32` is bit-exact (same comparisons + shifts; x==±λ and NaN → 0).
        if !self.tensor_requires_grad(input)? && self.tensor_dtype(input)? == DType::F32 {
            #[allow(clippy::cast_possible_truncation)]
            let lf = lambd as f32;
            let built = {
                let it = self.tensor_tape.tensor(input)?;
                if it.meta().is_contiguous() {
                    let xd = it.contiguous_values_f32()?;
                    use rayon::prelude::*;
                    let out: Vec<f32> = xd
                        .par_iter()
                        .map(|&x| {
                            if x > lf {
                                x - lf
                            } else if x < -lf {
                                x + lf
                            } else {
                                0.0
                            }
                        })
                        .collect();
                    Some(out)
                } else {
                    None
                }
            };
            if let Some(out) = built {
                return self.tensor_variable_f32(out, shape, false);
            }
        }
        // Single shared lambd_t across the gt mask, sub-shift, and
        // add-shift call sites (frankentorch-10mv) — tensor_gt /
        // tensor_sub / tensor_add only READ their operands, so one
        // full(shape, lambd) suffices for all three. -2 full() +
        // -2 tape nodes per call.
        let zeros = self.const_tensor_like(input, shape.clone(), 0.0)?;
        let lambd_t = self.const_tensor_like(input, shape.clone(), lambd)?;
        let neg_lambd_t = self.const_tensor_like(input, shape, -lambd)?;

        let pos_mask = self.tensor_gt(input, lambd_t)?;
        let neg_mask = self.tensor_lt(input, neg_lambd_t)?;

        let shifted_pos = self.tensor_sub(input, lambd_t)?;
        let shifted_neg = self.tensor_add(input, lambd_t)?;

        // First branch: positive side
        let step1 = self.tensor_where(pos_mask, shifted_pos, zeros)?;
        // Second branch: negative side overrides only where neg_mask
        // is true; otherwise keep step1's choice. The two masks are
        // mutually exclusive (x > lambd and x < -lambd can't both
        // hold for lambd >= 0), so this gives the correct three-way
        // split.
        self.tensor_where(neg_mask, shifted_neg, step1)
    }

    /// HardShrink activation: hard thresholding by `lambd`.
    ///
    /// `out = x if |x| > lambd, else 0`. Equivalent to
    /// `torch.nn.functional.hardshrink(input, lambd)`. Composes
    /// through autograd-aware tensor_abs + tensor_gt + tensor_where.
    /// Gradient is 1 where |x| > lambd, 0 inside [-lambd, lambd]
    /// (the where routes the inside region to the no-grad zeros
    /// constant). Tracked under frankentorch-t503.
    pub fn tensor_hardshrink(
        &mut self,
        input: TensorNodeId,
        lambd: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        if !lambd.is_finite() || lambd < 0.0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "hardshrink: lambd must be finite and non-negative",
                },
            )));
        }
        // No-grad f32 fast path: the composed path (const_tensor_like x2 [F64 full] + abs
        // + gt + where = ~5 passes + several allocs) measured 23.1x SLOWER than torch.
        // hardshrink is a pure compare+select with no rounding. torch's CPU kernel zeros
        // the INSIDE region [-λ, λ] and keeps x otherwise: `(x >= -λ && x <= λ) ? 0 : x`.
        // This differs from `|x| > λ ? x : 0` ONLY at NaN — NaN is not inside (both compares
        // false) so torch KEEPS NaN, verified bit-exact vs torch.nn.functional.hardshrink.
        // Boundaries x==±λ -> 0 (inclusive). frankentorch-t503.
        if self.tensor_dtype(input)? == DType::F32 && !self.tensor_requires_grad(input)? {
            let l = lambd as f32;
            let built = {
                let it = self.tensor_tape.tensor(input)?;
                if it.meta().is_contiguous() {
                    use rayon::prelude::*;
                    let xd = it.contiguous_values_f32()?;
                    let out: Vec<f32> = xd
                        .par_iter()
                        .map(|&x| if x >= -l && x <= l { 0.0_f32 } else { x })
                        .collect();
                    Some(out)
                } else {
                    None
                }
            };
            if let Some(out) = built {
                let shape = self.tensor_shape(input)?;
                return self.tensor_variable_f32(out, shape, false);
            }
        }
        // No-grad f64 fast path (the f64 sibling of the f32 one above; f64 fell through to the
        // ~5-pass composed path below — same ~23x SLOWER). Same inside-zeroing `(x>=-λ && x<=λ)?0:x`
        // (boundaries inclusive, NaN kept) in ONE parallel pass; bit-exact with the composed where.
        if self.tensor_dtype(input)? == DType::F64 && !self.tensor_requires_grad(input)? {
            let built = {
                let it = self.tensor_tape.tensor(input)?;
                if it.meta().is_contiguous() {
                    use rayon::prelude::*;
                    let xd = it.contiguous_values()?;
                    let out: Vec<f64> = xd
                        .par_iter()
                        .map(|&x| {
                            if x >= -lambd && x <= lambd {
                                0.0_f64
                            } else {
                                x
                            }
                        })
                        .collect();
                    Some(out)
                } else {
                    None
                }
            };
            if let Some(out) = built {
                let shape = self.tensor_shape(input)?;
                return self.tensor_variable(out, shape, false);
            }
        }
        let shape = self.tensor_shape(input)?;
        let zeros = self.const_tensor_like(input, shape.clone(), 0.0)?;
        let lambd_t = self.const_tensor_like(input, shape, lambd)?;
        let abs_x = self.tensor_abs(input)?;
        let mask = self.tensor_gt(abs_x, lambd_t)?;
        self.tensor_where(mask, input, zeros)
    }

    /// TanhShrink activation: `x - tanh(x)`.
    ///
    /// Equivalent to `torch.nn.functional.tanhshrink(input)`. Composes
    /// through autograd-aware tensor_tanh + tensor_sub. The function
    /// is monotonic and odd; useful in specialized normalization
    /// layers. Tracked under frankentorch-uykm.
    pub fn tensor_tanhshrink(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // No-grad f64 fast path: the compose materializes the full tanh(x) tensor (128MB write +
        // read) then subtracts = two passes. Fuse `x - tanh(x)` into ONE parallel pass. Bit-exact to
        // the compose: tensor_tanh uses `value.tanh()` and tensor_sub is `x - t`, so `x - x.tanh()`
        // with the SAME std tanh is identical. grad / f32 / non-contiguous fall through.
        // frankentorch-tanhshrink-fused.
        if let Some(out) = self.try_f64_unary_native(input, |x| x - x.tanh())? {
            return Ok(out);
        }
        let t = self.tensor_tanh(input)?;
        self.tensor_sub(input, t)
    }

    /// SoftSign activation: `x / (1 + |x|)`.
    ///
    /// Equivalent to `torch.nn.functional.softsign(input)`. Composes
    /// through autograd-aware tensor_abs + tensor_add (with constant 1)
    /// + tensor_div. Smoothly maps R → (-1, 1).
    ///
    /// Tracked under frankentorch-uykm.
    pub fn tensor_softsign(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        // f32-native fast path (no-grad): the compose below is 4 tape ops (abs + full_like + add
        // + div), each a full pass over the data plus a 64MB intermediate — measured 1.39x SLOWER
        // than torch's single fused kernel. Compute softsign in ONE parallel pass. softsign is a
        // rational VALUE op (parity absolute), so this must be BIT-EXACT to torch's pure-f32
        // `a/(1+|a|)`, NOT f64-then-narrow: doing the f32 arithmetic INSIDE the closure (x as f32
        // round-trips exactly through the helper's f64 boundary) reproduces torch's exact f32
        // rounding. frankentorch-specf32.
        if let Some(out) = self.try_f32_unary_native(input, |x| {
            let xf = x as f32;
            (xf / (1.0_f32 + xf.abs())) as f64
        })? {
            return Ok(out);
        }
        // f64-native no-grad fast path (the f64 compose below is 4 tape passes: abs + full_like + add
        // + div). x/(1+|x|) in ONE pass — bit-exact to the compose (div(x, add(1.0, abs(x)))).
        if let Some(out) = self.try_f64_unary_native(input, |x| x / (1.0 + x.abs()))? {
            return Ok(out);
        }
        // Build the `1` constant in the INPUT dtype (full() is always F64, which
        // upcast f32/half inputs to F64; torch keeps the input dtype).
        // frankentorch-37czu.
        let abs_x = self.tensor_abs(input)?;
        let one = self.full_like(input, 1.0, false)?;
        let denom = self.tensor_add(one, abs_x)?;
        self.tensor_div(input, denom)
    }

    /// Power-of-two exponential: `2^x`.
    ///
    /// Equivalent to `torch.exp2(input)`. Uses the native base-2 exponential
    /// so f64 overflow/underflow cliffs match power-of-two semantics instead
    /// of rounded `exp(input * ln(2))` composition. Autograd-aware; gradient
    /// is `2^x * ln(2)`. Tracked under frankentorch-lcxs.
    pub fn tensor_exp2(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        self.tensor_apply_function_with_create_graph(
            &[input],
            |ctx, inputs| {
                let (values, shape) = inputs[0];
                // Skip the backward-only input clone in no-grad inference:
                // apply_function returns a plain Leaf and discards ctx unless an
                // input needs grad. Grad path unchanged. frankentorch-1lo5l.
                if ctx.needs_input_grad().iter().any(|&g| g) {
                    ctx.save_for_backward(values.to_vec(), shape.to_vec());
                }
                // 2^x per element — fan the independent lanes over Rayon
                // (par_map preserves index order => bit-for-bit == serial map).
                let output = par_map_f64(values, f64::exp2);
                Ok((output, shape.to_vec()))
            },
            |ctx, grad_outputs| {
                let grad_out = grad_outputs[0];
                let input_values = &ctx.saved_tensors()[0];
                if grad_out.len() != input_values.len() {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "exp2 backward: incoming gradient length mismatch",
                        },
                    )));
                }
                let grad = par_zip_map_f64(grad_out, input_values, |go, value| {
                    go * value.exp2() * std::f64::consts::LN_2
                });
                Ok(vec![ctx.needs_input_grad()[0].then_some(grad)])
            },
            // create_graph backward: d(2^x)/dx = ln2 · 2^x. Build it as
            // ln2 · exp(x·ln2) from DIFFERENTIABLE tape ops so a second backward
            // propagates (2^x''= ln2²·2^x), instead of erroring. The exp(x·ln2)
            // form matches torch's exp2 gradient to f64 tolerance. frankentorch-1avc3.
            |_ctx, grad_outs, inputs, tape| {
                let ln2 = std::f64::consts::LN_2;
                let mode = ft_core::ExecutionMode::Strict;
                let x_ln2 = tape.mul_scalar(inputs[0], ln2)?.0;
                let two_pow_x = tape.exp(x_ln2, mode)?.0;
                let deriv = tape.mul_scalar(two_pow_x, ln2)?.0;
                let grad_in = tape.mul(grad_outs[0], deriv, mode)?.0;
                Ok(vec![Some(grad_in)])
            },
        )
    }

    /// Base-10 exponential: `10^x`.
    ///
    /// Equivalent to `torch.special.exp10(input)`. Companion to
    /// `tensor_exp2`. Composes through `tensor_exp(input * ln(10))`.
    /// Autograd-aware; gradient is `10^x * ln(10)`.
    /// Tracked under frankentorch-fvt1.
    pub fn tensor_exp10(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        let ln10 = self.full(shape, std::f64::consts::LN_10, false)?;
        let scaled = self.tensor_mul(input, ln10)?;
        self.tensor_exp(scaled)
    }

    /// Multiply input by `2^other`: `ldexp(x, n) = x * 2^n`.
    ///
    /// Equivalent to `torch.ldexp(input, other)`, the inverse-frexp
    /// companion. Composes through `tensor_mul(input, tensor_exp2(other))`
    /// so autograd flows through the existing exp2 / mul nodes:
    /// gradient w.r.t. input is `2^other`, gradient w.r.t. other is
    /// `input * 2^other * ln(2)`. Tracked under frankentorch-4gbs.
    pub fn tensor_ldexp(
        &mut self,
        input: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let two_pow = self.tensor_exp2(other)?;
        self.tensor_mul(input, two_pow)
    }

    /// In-place ldexp: target = target * 2^other.
    pub fn tensor_ldexp_(
        &mut self,
        target: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<(), AutogradError> {
        self.validate_tensor_in_place_target(target)?;
        if self.try_inplace_binary_f64(target, other, "ldexp_", |x, e| x * 2.0_f64.powf(e))? {
            return Ok(());
        }
        let target_vals = self.tensor_values_lossy_f64(target)?;
        let other_vals = self.tensor_values_lossy_f64(other)?;
        if target_vals.len() != other_vals.len() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: self.tensor_shape(target)?,
                    rhs: self.tensor_shape(other)?,
                },
            )));
        }
        let result: Vec<f64> = target_vals
            .iter()
            .zip(other_vals.iter())
            .map(|(&x, &e)| x * 2.0_f64.powf(e))
            .collect();
        self.update_tensor_values_for_float(target, result, INPLACE_FLOAT_REASON)?;
        self.record_tensor_in_place_operation("ldexp_", target, None);
        Ok(())
    }

    /// Scale by power of 2: `scalbn(input, n) = input * 2^n`.
    ///
    /// Equivalent to `torch.special.scalbn(input, n)`. Alias for ldexp.
    pub fn tensor_scalbn(
        &mut self,
        input: TensorNodeId,
        n: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_ldexp(input, n)
    }

    /// In-place scalbn: target = target * 2^n.
    pub fn tensor_scalbn_(
        &mut self,
        target: TensorNodeId,
        n: TensorNodeId,
    ) -> Result<(), AutogradError> {
        self.tensor_ldexp_(target, n)
    }

    /// Numerically stable log-sigmoid: `log(sigmoid(x)) = -softplus(-x)`.
    ///
    /// Equivalent to `torch.nn.functional.logsigmoid(input)`. Avoids
    /// the numerical underflow of `log(sigmoid(x))` for very negative
    /// x (where sigmoid → 0 and log → -inf). Composes via
    /// `tensor_neg(tensor_softplus(tensor_neg(input)))`. Autograd-aware.
    /// Tracked under frankentorch-lcxs.
    pub fn tensor_logsigmoid(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // No-grad fast path: the compose below is neg -> softplus -> neg = THREE passes over numel.
        // logsigmoid(x) = -softplus(-x); fuse into ONE pass, replicating the softplus KERNEL formula
        // exactly (`if y > 20 { y } else { y.exp().ln_1p() }`, beta=1/threshold=20) so the result is
        // BIT-EXACT to the compose (neg is exact IEEE negation; same softplus per-element math; same
        // libm exp/ln_1p). f32 uses the f32 softplus formula (identical structure). grad /
        // non-contiguous / non-f32-f64 fall through.
        if !self.tensor_requires_grad(input)? {
            let dt = self.tensor_dtype(input)?;
            macro_rules! fused {
                ($read:ident, $build:ident, $ty:ty, $thr:expr) => {{
                    let built = {
                        let it = self.tensor_tape.tensor(input)?;
                        if it.meta().is_contiguous() {
                            use rayon::prelude::*;
                            let out: Vec<$ty> = it
                                .$read()?
                                .par_iter()
                                .map(|&x| {
                                    let y = -x;
                                    let sp = if y > $thr { y } else { y.exp().ln_1p() };
                                    -sp
                                })
                                .collect();
                            Some(out)
                        } else {
                            None
                        }
                    };
                    if let Some(out) = built {
                        let shape = self.tensor_shape(input)?;
                        return self.$build(out, shape, false);
                    }
                }};
            }
            match dt {
                DType::F64 => fused!(contiguous_values, tensor_variable, f64, 20.0_f64),
                DType::F32 => fused!(contiguous_values_f32, tensor_variable_f32, f32, 20.0_f32),
                _ => {}
            }
        }
        let neg_x = self.tensor_neg(input)?;
        let sp = self.tensor_softplus(neg_x)?;
        self.tensor_neg(sp)
    }

    /// Inverse hyperbolic sine.
    ///
    /// Equivalent to `torch.asinh(input)`. Composes via the closed
    /// form `asinh(x) = log(x + sqrt(x^2 + 1))`. Defined for all real x.
    /// Tracked under frankentorch-2vc0.
    pub fn tensor_asinh(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        // f32-native fast path: the composed path below is 6 tape passes (full/mul/add/sqrt/
        // add/log) = ~12x SLOWER than torch. Same formula `ln(x + sqrt(x*x+1))` in one f64
        // pass narrowed to f32 (tolerance op; conformance-verified).
        if let Some(out) = self.try_f32_unary_native(input, |x| (x + (x * x + 1.0).sqrt()).ln())? {
            return Ok(out);
        }
        // f64-native no-grad fast path (the f64 compose below is ~6 tape passes). Same formula as the
        // f32 closure -> bit-exact to the compose (x*x+1.0 == add(x*x,one); x+sqrt == add(x,sqrt)).
        if let Some(out) = self.try_f64_unary_native(input, |x| (x + (x * x + 1.0).sqrt()).ln())? {
            return Ok(out);
        }
        let shape = self.tensor_shape(input)?;
        let one = self.full(shape, 1.0, false)?;
        let x_sq = self.tensor_mul(input, input)?;
        let inner = self.tensor_add(x_sq, one)?;
        let sqrt_term = self.tensor_sqrt(inner)?;
        let sum = self.tensor_add(input, sqrt_term)?;
        self.tensor_log(sum)
    }

    /// Inverse hyperbolic cosine (defined for x >= 1).
    ///
    /// Equivalent to `torch.acosh(input)`. Forward uses the accurate
    /// `f64::acosh` (== `libm::acosh` == `torch.acosh` bit-for-bit, and the
    /// same function the in-place `tensor_acosh_` calls). The earlier
    /// `log(x + sqrt(x^2 - 1))` composition was 1 ULP off `torch.acosh` at
    /// several points (e.g. x=1.1, 3.7, 100) and — worse — produced a NaN
    /// second derivative at the domain boundary x=1 (0·inf in the composed
    /// sqrt/log chain) where torch gives -inf. Inputs less than 1 produce
    /// NaN (matches PyTorch). Gradient is `1/sqrt(x^2-1)`; the create_graph
    /// form is built from `rsqrt(x^2-1)` so a second backward yields the
    /// clean `-x·(x^2-1)^(-3/2)` (= -inf at x=1). frankentorch-2vc0,
    /// frankentorch-j43r8.
    pub fn tensor_acosh(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        // f32-native fast path: the apply_function path UPCASTS f32->f64 = ~6.5x SLOWER.
        // f64::acosh is bit-for-bit torch.acosh (per the doc above); (x as f64).acosh() as f32
        // is the same value the f64-then-narrow apply_function produces -> bit-identical.
        if let Some(out) = self.try_f32_unary_native(input, |x| x.acosh())? {
            return Ok(out);
        }
        self.tensor_apply_function_with_create_graph(
            &[input],
            |ctx, inputs| {
                let (values, shape) = inputs[0];
                // Skip the backward-only input clone in no-grad inference:
                // apply_function returns a plain Leaf and discards ctx unless an
                // input needs grad, so this save is provably dead work there.
                // Grad path byte-for-byte unchanged. frankentorch-xxymp.
                if ctx.needs_input_grad().iter().any(|&g| g) {
                    ctx.save_for_backward(values.to_vec(), shape.to_vec());
                }
                // acosh is a heavy transcendental per element — fan the
                // independent lanes over Rayon. par_map_f64 preserves index
                // order => bit-for-bit identical to the serial map.
                let output = par_map_f64(values, f64::acosh);
                Ok((output, shape.to_vec()))
            },
            |ctx, grad_outputs| {
                let grad_out = grad_outputs[0];
                let input_values = &ctx.saved_tensors()[0];
                if grad_out.len() != input_values.len() {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "acosh backward: incoming gradient length mismatch",
                        },
                    )));
                }
                // d(acosh(x))/dx = 1/sqrt(x^2-1). At x=1 this is +inf; for
                // x<1 the radicand is negative -> NaN (both match torch).
                let grad = grad_out
                    .iter()
                    .zip(input_values.iter())
                    .map(|(&go, &x)| go / (x * x - 1.0).sqrt())
                    .collect::<Vec<_>>();
                Ok(vec![ctx.needs_input_grad()[0].then_some(grad)])
            },
            // create_graph backward: d(acosh)/dx = rsqrt(x^2-1), built from
            // differentiable tape ops so a second backward propagates the
            // boundary singularity (acosh'' = -x·(x^2-1)^(-3/2) -> -inf at
            // x=1) instead of collapsing to NaN. frankentorch-j43r8.
            |_ctx, grad_outs, inputs, tape| {
                let mode = ft_core::ExecutionMode::Strict;
                let shape = tape.tensor_meta(inputs[0])?.shape().to_vec();
                let numel: usize = shape.iter().product();
                let one = tape.leaf(vec![1.0; numel], shape, false)?;
                let x_sq = tape.mul(inputs[0], inputs[0], mode)?.0;
                let inner = tape.sub(x_sq, one, mode)?.0;
                let deriv = tape.rsqrt(inner, mode)?.0; // (x^2-1)^(-1/2)
                let grad_in = tape.mul(grad_outs[0], deriv, mode)?.0;
                Ok(vec![Some(grad_in)])
            },
        )
    }

    /// Inverse hyperbolic tangent (defined for |x| < 1).
    ///
    /// Equivalent to `torch.atanh(input)`. Composes via the closed
    /// form `atanh(x) = 0.5 * log((1 + x) / (1 - x))`. Inputs at
    /// |x| = 1 produce ±inf and |x| > 1 produces NaN (matches PyTorch).
    /// Tracked under frankentorch-2vc0.
    pub fn tensor_atanh(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        // f32-native fast path: the composed path below is 7 tape passes = SLOWER than torch.
        // Same formula `0.5*ln((1+x)/(1-x))` in one f64 pass narrowed (tolerance op).
        if let Some(out) =
            self.try_f32_unary_native(input, |x| 0.5 * ((1.0 + x) / (1.0 - x)).ln())?
        {
            return Ok(out);
        }
        // f64-native no-grad fast path (the f64 compose below is ~7 tape passes). Same formula as the
        // f32 closure -> bit-exact to the compose (`0.5*L` == `L*0.5` commuted; `1.0+x`/`1.0-x` match
        // add(one,x)/sub(one,x)).
        if let Some(out) =
            self.try_f64_unary_native(input, |x| 0.5 * ((1.0 + x) / (1.0 - x)).ln())?
        {
            return Ok(out);
        }
        let shape = self.tensor_shape(input)?;
        // Single ones tensor shared between tensor_add (1+x) and
        // tensor_sub (1-x) — both ops only read their operands.
        // Tracked under frankentorch-4w7g.
        let one = self.full(shape.clone(), 1.0, false)?;
        let half = self.full(shape, 0.5, false)?;
        let num = self.tensor_add(one, input)?;
        let den = self.tensor_sub(one, input)?;
        let ratio = self.tensor_div(num, den)?;
        let log_ratio = self.tensor_log(ratio)?;
        self.tensor_mul(log_ratio, half)
    }

    pub fn tensor_arcsinh(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        self.tensor_asinh(input)
    }

    pub fn tensor_arccosh(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        self.tensor_acosh(input)
    }

    pub fn tensor_arctanh(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        self.tensor_atanh(input)
    }

    pub fn tensor_gelu(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let (out, event) = self.tensor_tape.gelu(input, self.mode())?;
        self.record_tensor_unary_operation(&event);
        Ok(out)
    }

    /// GELU with the tanh approximation, matching `F.gelu(x, approximate='tanh')`
    /// (the GPT-2 / BERT form). `tensor_gelu` is the exact erf form
    /// (`approximate='none'`, torch's default).
    ///
    /// `0.5 * x * (1 + tanh(sqrt(2/pi) * (x + 0.044715 * x^3)))`. Composed from
    /// autograd-aware ops so gradients flow. `x^3` is built as `x*x*x` (not pow,
    /// which would NaN on negative inputs) and the operation order matches torch's
    /// kernel — `0.5*x` then `*(1 + tanh(...))` — so values are bit-exact.
    pub fn tensor_gelu_tanh(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        const BETA: f64 = 0.797_884_560_802_865_4; // sqrt(2/pi)
        const KAPPA: f64 = 0.044_715;
        // No-grad fast path: the compose below is ~9 passes over numel (mul, mul, mul_scalar, add,
        // mul_scalar, tanh, add, mul_scalar, mul) — the GPT-2/BERT GELU, very hot in transformers.
        // Fuse into ONE pass, replicating the EXACT op order so the result is bit-exact to the compose
        // (same groupings: x3 = (x*x)*x; 0.5*x then *(1+tanh(beta*(x+kappa*x3))); Rust tanh == the
        // kernel/libm tanh). f32 computes natively in f32 (matching the f32 compose after the full_like
        // dtype fix below). grad / non-contiguous / non-f32-f64 fall through.
        if !self.tensor_requires_grad(input)? {
            let dt = self.tensor_dtype(input)?;
            macro_rules! fused {
                ($read:ident, $build:ident, $ty:ty) => {{
                    let built = {
                        let it = self.tensor_tape.tensor(input)?;
                        if it.meta().is_contiguous() {
                            use rayon::prelude::*;
                            let (beta, kappa, half) = (BETA as $ty, KAPPA as $ty, 0.5 as $ty);
                            let data = it.$read()?;
                            let f = |&x: &$ty| {
                                let x3 = (x * x) * x;
                                let inner = beta * (x + kappa * x3);
                                (half * x) * ((1.0 as $ty) + inner.tanh())
                            };
                            // gelu's per-element tanh is compute-bound, so parallel pays only
                            // above the elementwise gate; below it (e.g. a single-token
                            // [1,hidden] decode gelu, hidden < 8192) rayon fork overhead > gain
                            // and it REGRESSES — worse under core contention. Bit-identical.
                            let out: Vec<$ty> = if data.len() >= PARALLEL_ELEMENTWISE_MIN {
                                data.par_iter().map(f).collect()
                            } else {
                                data.iter().map(f).collect()
                            };
                            Some(out)
                        } else {
                            None
                        }
                    };
                    if let Some(out) = built {
                        let shape = self.tensor_shape(input)?;
                        return self.$build(out, shape, false);
                    }
                }};
            }
            match dt {
                DType::F64 => fused!(contiguous_values, tensor_variable, f64),
                DType::F32 => fused!(contiguous_values_f32, tensor_variable_f32, f32),
                _ => {}
            }
        }
        let x2 = self.tensor_mul(input, input)?;
        let x3 = self.tensor_mul(x2, input)?;
        let kappa_x3 = self.tensor_mul_scalar(x3, KAPPA)?;
        let inner_sum = self.tensor_add(input, kappa_x3)?;
        let inner = self.tensor_mul_scalar(inner_sum, BETA)?;
        let t = self.tensor_tanh(inner)?;
        // full_like (matches input dtype) not full (always F64): with full(), an f32 input's
        // `1 + t` promoted through a F64 const so gelu_tanh(f32) wrongly returned F64. full_like
        // keeps f32 -> f32 (torch preserves dtype). frankentorch dtype-parity fix.
        let ones = self.full_like(input, 1.0, false)?;
        let one_plus_t = self.tensor_add(ones, t)?;
        let half_x = self.tensor_mul_scalar(input, 0.5)?;
        self.tensor_mul(half_x, one_plus_t)
    }

    pub fn tensor_silu(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let (out, event) = self.tensor_tape.silu(input, self.mode())?;
        self.record_tensor_unary_operation(&event);
        Ok(out)
    }

    /// Swish activation (alias for SiLU).
    ///
    /// swish(x) = x * sigmoid(x). Also known as SiLU.
    pub fn tensor_swish(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        self.tensor_silu(input)
    }

    /// In-place swish activation (alias for silu_).
    pub fn tensor_swish_(&mut self, target: TensorNodeId) -> Result<(), AutogradError> {
        self.tensor_silu_(target)
    }

    pub fn tensor_leaky_relu(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let (out, event) = self.tensor_tape.leaky_relu(input, self.mode())?;
        self.record_tensor_unary_operation(&event);
        Ok(out)
    }

    pub fn tensor_elu(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let (out, event) = self.tensor_tape.elu(input, self.mode())?;
        self.record_tensor_unary_operation(&event);
        Ok(out)
    }

    /// Scaled Exponential Linear Unit.
    ///
    /// selu(x) = scale * (max(0,x) + min(0, alpha*(exp(x)-1)))
    /// where scale and alpha are fixed for self-normalizing networks.
    /// Tracked under frankentorch-8g3v.
    pub fn tensor_selu(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        const ALPHA: f64 = 1.6732632423543772848170429916717;
        const SCALE: f64 = 1.0507009873554804934193349852946;
        // f32-native fast path (sibling of celu): the f32 branch below UPCASTS to f64 +
        // apply_function + narrows = ~8.5x SLOWER than torch. Same value, bit-identical.
        if let Some(out) = self.try_f32_unary_native(input, |x| {
            if x > 0.0 {
                SCALE * x
            } else {
                SCALE * ALPHA * x.exp_m1()
            }
        })? {
            return Ok(out);
        }
        // f32/half: compute in f64 then cast back (torch keeps the input dtype;
        // the f64 borrowed-inputs path errors on non-f64 storage). frankentorch-x9yuq.
        let dt = self.tensor_dtype(input)?;
        if dt != DType::F64 {
            let in64 = self.tensor_to_dtype(input, DType::F64)?;
            let out64 = self.tensor_selu(in64)?;
            return self.tensor_to_dtype(out64, dt);
        }
        let out = self.tensor_apply_function_with_create_graph(
            &[input],
            |ctx, inputs| {
                let (vals, shape) = inputs[0];
                // Skip the backward-only input clone in no-grad inference:
                // apply_function returns a plain Leaf and discards ctx unless an
                // input needs grad. Grad path unchanged. frankentorch-zva0u.
                if ctx.needs_input_grad().iter().any(|&g| g) {
                    ctx.save_for_backward(vals.to_vec(), shape.to_vec());
                }
                // The negative branch evaluates exp_m1 per element — fan the
                // independent lanes over Rayon (par_map preserves index order =>
                // bit-for-bit identical to the serial map).
                let values = par_map_f64(vals, |x| {
                    if x > 0.0 {
                        SCALE * x
                    } else {
                        SCALE * ALPHA * x.exp_m1()
                    }
                });
                Ok((values, shape.to_vec()))
            },
            // 1st-order backward (reads the saved input).
            |ctx, grad_outputs| {
                let grad_out = grad_outputs[0];
                let x_vals = &ctx.saved_tensors()[0];
                if grad_out.len() != x_vals.len() {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "selu backward: gradient length mismatch",
                        },
                    )));
                }
                let grad_in = par_zip_map_f64(x_vals, grad_out, |x, go| {
                    if x > 0.0 {
                        go * SCALE
                    } else {
                        go * SCALE * ALPHA * x.exp()
                    }
                });
                Ok(vec![Some(grad_in)])
            },
            // create_graph backward: selu'(x) = SCALE·(x>0?1:ALPHA·exp(x)), built
            // from differentiable tape ops (constant masks + exp) so selu''(x<0) =
            // SCALE·ALPHA·exp(x) propagates instead of erroring. frankentorch-1avc3.
            |_ctx, grad_outs, inputs, tape| {
                let mode = ft_core::ExecutionMode::Strict;
                let (xv, shape) = {
                    let t = tape.tensor(inputs[0])?;
                    (t.contiguous_values_as_f64()?, t.meta().shape().to_vec())
                };
                let pos: Vec<f64> = xv
                    .iter()
                    .map(|&x| if x > 0.0 { SCALE } else { 0.0 })
                    .collect();
                let negf: Vec<f64> = xv
                    .iter()
                    .map(|&x| if x > 0.0 { 0.0 } else { SCALE * ALPHA })
                    .collect();
                let pos_node = tape.leaf(pos, shape.clone(), false)?;
                let negf_node = tape.leaf(negf, shape, false)?;
                let exp_node = tape.exp(inputs[0], mode)?.0;
                let neg_term = tape.mul(negf_node, exp_node, mode)?.0;
                let deriv = tape.add(pos_node, neg_term, mode)?.0;
                let grad_in = tape.mul(grad_outs[0], deriv, mode)?.0;
                Ok(vec![Some(grad_in)])
            },
        )?;
        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!("selu in={} out={}", input.0, out.0),
        );
        Ok(out)
    }

    /// Continuously Differentiable Exponential Linear Unit.
    ///
    /// celu(x, alpha) = max(0,x) + min(0, alpha*(exp(x/alpha)-1))
    /// Default alpha = 1.0.
    /// Tracked under frankentorch-fk1i.
    pub fn tensor_celu(
        &mut self,
        input: TensorNodeId,
        alpha: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        // f32-native fast path: the f32 branch below UPCASTS to f64 (to_dtype) + apply_function
        // + narrows = ~17x SLOWER than torch. Same value (`x>0 ? x : alpha*expm1(x/alpha)` in
        // f64, narrowed) = bit-identical to current f32. frankentorch-asymf32.
        if let Some(out) = self.try_f32_unary_native(input, move |x| {
            if x > 0.0 {
                x
            } else {
                alpha * (x / alpha).exp_m1()
            }
        })? {
            return Ok(out);
        }
        // f32/half: compute in f64 then cast back (torch keeps the input dtype;
        // the f64 borrowed-inputs path errors on non-f64 storage). frankentorch-x9yuq.
        let dt = self.tensor_dtype(input)?;
        if dt != DType::F64 {
            let in64 = self.tensor_to_dtype(input, DType::F64)?;
            let out64 = self.tensor_celu(in64, alpha)?;
            return self.tensor_to_dtype(out64, dt);
        }
        let out = self.tensor_apply_function_f64_borrowed_inputs(
            &[input],
            move |_ctx, inputs| {
                let (vals, shape) = inputs[0];
                let values: Vec<f64> = vals
                    .iter()
                    .map(|&x| {
                        if x > 0.0 {
                            x
                        } else {
                            alpha * (x / alpha).exp_m1()
                        }
                    })
                    .collect();
                Ok((values, shape.to_vec()))
            },
            // Borrowed-inputs: backward re-reads x from the live leaf. frankentorch-3jmy3.
            move |_ctx, grad_outputs, borrowed| {
                let grad_out = grad_outputs[0];
                let x_vals = borrowed[0].0;
                if grad_out.len() != x_vals.len() {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "celu backward: gradient length mismatch",
                        },
                    )));
                }
                let grad_in: Vec<f64> = x_vals
                    .iter()
                    .zip(grad_out.iter())
                    .map(
                        |(&x, &go)| {
                            if x > 0.0 { go } else { go * (x / alpha).exp() }
                        },
                    )
                    .collect();
                Ok(vec![Some(grad_in)])
            },
        )?;
        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!("celu in={} out={}", input.0, out.0),
        );
        Ok(out)
    }

    /// Elementwise PReLU forward values, shared by the autograd and non-grad
    /// paths so they stay bit-identical. `x >= 0 ? x : w_c * x`, where `w_c` is
    /// the single shared weight (len 1) or the per-channel weight.
    fn prelu_forward_values(
        input_vals: &[f64],
        input_shape: &[usize],
        weight_vals: &[f64],
    ) -> Vec<f64> {
        // Per-element select+multiply are independent, so parallelize large inputs (par_iter +
        // enumerate preserves index order => bit-identical to the serial map). Mirrors the already-
        // parallel prelu_forward_values_f32; the f64 version had been left serial. Used by the no-grad
        // fast path AND the grad-path forward, so both benefit.
        let prelu_at = |i: usize, x: f64| -> f64 {
            if weight_vals.len() == 1 {
                if x >= 0.0 { x } else { weight_vals[0] * x }
            } else {
                let num_channels = weight_vals.len();
                let channel_size: usize = if input_shape.len() >= 2 {
                    input_shape[2..].iter().product()
                } else {
                    1
                };
                let c = if input_shape.len() >= 2 {
                    (i / channel_size) % num_channels
                } else {
                    i % num_channels
                };
                if x >= 0.0 { x } else { weight_vals[c] * x }
            }
        };
        if input_vals.len() >= PARALLEL_ELEMENTWISE_MIN {
            use rayon::prelude::*;
            input_vals
                .par_iter()
                .enumerate()
                .map(|(i, &x)| prelu_at(i, x))
                .collect()
        } else {
            input_vals
                .iter()
                .enumerate()
                .map(|(i, &x)| prelu_at(i, x))
                .collect()
        }
    }

    /// Native-f32 PReLU forward (no-grad fast path). Mirrors `prelu_forward_values`
    /// but computes in f32 so the result is bit-identical to torch's f32 `prelu`
    /// (the f64 path crashes on f32 storage via `tensor_values`, which is F64-only).
    /// Parallelized for large inputs; the per-element select+multiply are independent.
    fn prelu_forward_values_f32(
        input_vals: &[f32],
        input_shape: &[usize],
        weight_vals: &[f32],
    ) -> Vec<f32> {
        let prelu_at = |i: usize, x: f32| -> f32 {
            if weight_vals.len() == 1 {
                if x >= 0.0 { x } else { weight_vals[0] * x }
            } else {
                let num_channels = weight_vals.len();
                let channel_size: usize = if input_shape.len() >= 2 {
                    input_shape[2..].iter().product()
                } else {
                    1
                };
                let c = if input_shape.len() >= 2 {
                    (i / channel_size) % num_channels
                } else {
                    i % num_channels
                };
                if x >= 0.0 { x } else { weight_vals[c] * x }
            }
        };
        if input_vals.len() >= PARALLEL_ELEMENTWISE_MIN {
            use rayon::prelude::*;
            input_vals
                .par_iter()
                .enumerate()
                .map(|(i, &x)| prelu_at(i, x))
                .collect()
        } else {
            input_vals
                .iter()
                .enumerate()
                .map(|(i, &x)| prelu_at(i, x))
                .collect()
        }
    }

    /// Parametric ReLU activation.
    ///
    /// prelu(x, weight) = max(0,x) + weight * min(0,x)
    /// Weight is a 1D tensor (per-channel) or scalar broadcasted.
    /// Tracked under frankentorch-bf19.
    pub fn tensor_prelu(
        &mut self,
        input: TensorNodeId,
        weight: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let input_shape = self.tensor_shape(input)?;

        if self.tensor_requires_grad(input)? || self.tensor_requires_grad(weight)? {
            // PReLU(x, w) = x if x>=0 else w_c * x (w_c is the per-channel weight,
            // or the single shared weight). Linear in both args on each side of 0:
            //   d/dx = 1 if x>=0 else w_c
            //   d/dw_c = sum over x<0 in channel c of (grad_out * x)
            // 2-input borrowed apply_function; forward is identical to the non-grad
            // path while backward reads x/w directly from the immutable tape slices.
            // frankentorch-avfl.
            let ndim = input_shape.len();
            let shape_f64: Vec<f64> = input_shape.iter().map(|&d| d as f64).collect();
            return self.tensor_apply_function_f64_borrowed_inputs(
                &[input, weight],
                move |_ctx, inputs| {
                    let (xv, x_shape) = inputs[0];
                    let (wv, _w_shape) = inputs[1];
                    let result = Self::prelu_forward_values(xv, x_shape, wv);
                    Ok((result, x_shape.to_vec()))
                },
                move |_ctx, grad_outputs, borrowed| {
                    let g = grad_outputs[0];
                    let xv = borrowed[0].0;
                    let wv = borrowed[1].0;
                    let nch = wv.len();
                    let channel_size: usize = if ndim >= 2 {
                        #[allow(clippy::cast_possible_truncation, clippy::cast_sign_loss)]
                        let cs = shape_f64[2..].iter().product::<f64>() as usize;
                        cs.max(1)
                    } else {
                        1
                    };
                    let parallel_backward = xv.len() >= 65_536;
                    let (grad_x, grad_w) = if parallel_backward {
                        use rayon::prelude::*;

                        let grad_x: Vec<f64> = (0..xv.len())
                            .into_par_iter()
                            .map(|i| {
                                let x = xv[i];
                                let c = if nch == 1 {
                                    0
                                } else if ndim >= 2 {
                                    (i / channel_size) % nch
                                } else {
                                    i % nch
                                };
                                if x >= 0.0 { g[i] } else { g[i] * wv[c] }
                            })
                            .collect();
                        let mut grad_w = vec![0.0_f64; nch];
                        if nch == 1 {
                            for (i, &x) in xv.iter().enumerate() {
                                if x < 0.0 {
                                    grad_w[0] += g[i] * x;
                                }
                            }
                        } else {
                            grad_w.par_iter_mut().enumerate().for_each(|(c, slot)| {
                                let mut acc = 0.0_f64;
                                if ndim >= 2 {
                                    let channel_span = nch * channel_size;
                                    let outer = xv.len() / channel_span;
                                    if outer * channel_span == xv.len() {
                                        for n in 0..outer {
                                            let start = n * channel_span + c * channel_size;
                                            let end = start + channel_size;
                                            for i in start..end {
                                                let x = xv[i];
                                                if x < 0.0 {
                                                    acc += g[i] * x;
                                                }
                                            }
                                        }
                                    } else {
                                        for (i, &x) in xv.iter().enumerate() {
                                            if (i / channel_size) % nch == c && x < 0.0 {
                                                acc += g[i] * x;
                                            }
                                        }
                                    }
                                } else {
                                    let mut i = c;
                                    while i < xv.len() {
                                        let x = xv[i];
                                        if x < 0.0 {
                                            acc += g[i] * x;
                                        }
                                        i += nch;
                                    }
                                }
                                *slot = acc;
                            });
                        }
                        (grad_x, grad_w)
                    } else {
                        let mut grad_x = vec![0.0_f64; xv.len()];
                        let mut grad_w = vec![0.0_f64; nch];
                        for (i, &x) in xv.iter().enumerate() {
                            let c = if nch == 1 {
                                0
                            } else if ndim >= 2 {
                                (i / channel_size) % nch
                            } else {
                                i % nch
                            };
                            if x >= 0.0 {
                                grad_x[i] = g[i];
                            } else {
                                grad_x[i] = g[i] * wv[c];
                                grad_w[c] += g[i] * x;
                            }
                        }
                        (grad_x, grad_w)
                    };
                    Ok(vec![Some(grad_x), Some(grad_w)])
                },
            );
        }

        // No-grad f32 fast path (correctness bug + asymmetric-dtype): the f64 path below reads
        // input/weight via `tensor_values`, which is F64-only and ERRORS (UnsupportedDType(F32))
        // for f32 storage — so no-grad f32 PReLU was broken, not merely slow. Compute natively in
        // f32 (bit-identical to torch's f32 prelu) and return the correct F32 dtype. Requires both
        // operands f32 + contiguous; any other combination falls through to the f64 path unchanged.
        if !self.tensor_requires_grad(input)?
            && !self.tensor_requires_grad(weight)?
            && self.tensor_dtype(input)? == DType::F32
            && self.tensor_dtype(weight)? == DType::F32
        {
            let built: Option<Vec<f32>> = {
                let it = self.tensor_tape.tensor(input)?;
                let wt = self.tensor_tape.tensor(weight)?;
                if it.meta().is_contiguous() && wt.meta().is_contiguous() {
                    let input_f32 = it.contiguous_values_f32()?;
                    let weight_f32 = wt.contiguous_values_f32()?;
                    Some(Self::prelu_forward_values_f32(
                        input_f32,
                        &input_shape,
                        weight_f32,
                    ))
                } else {
                    None
                }
            };
            if let Some(result) = built {
                let out = self.tensor_variable_f32(result, input_shape, false)?;
                self.runtime.ledger_mut().record(
                    EvidenceKind::Dispatch,
                    format!("prelu f32 in={} weight={} out={}", input.0, weight.0, out.0),
                );
                return Ok(out);
            }
        }

        // No-grad f64 fast path (asymmetric-dtype mirror of the f32 path above): the fallback below
        // CLONES the whole (large) input via tensor_values before computing. Borrow the contiguous
        // f64 input + weight and run the SAME prelu_forward_values on the borrowed slices — no clone.
        // Bit-identical (same function, same values). Non-contiguous falls through to the clone.
        if !self.tensor_requires_grad(input)?
            && !self.tensor_requires_grad(weight)?
            && self.tensor_dtype(input)? == DType::F64
            && self.tensor_dtype(weight)? == DType::F64
        {
            let built: Option<Vec<f64>> = {
                let it = self.tensor_tape.tensor(input)?;
                let wt = self.tensor_tape.tensor(weight)?;
                if it.meta().is_contiguous() && wt.meta().is_contiguous() {
                    let iv = it.contiguous_values()?;
                    let wv = wt.contiguous_values()?;
                    Some(Self::prelu_forward_values(iv, &input_shape, wv))
                } else {
                    None
                }
            };
            if let Some(result) = built {
                let out = self.tensor_variable(result, input_shape, false)?;
                self.runtime.ledger_mut().record(
                    EvidenceKind::Dispatch,
                    format!("prelu in={} weight={} out={}", input.0, weight.0, out.0),
                );
                return Ok(out);
            }
        }

        let weight_vals = self.tensor_values(weight)?;
        let input_vals = self.tensor_values(input)?;

        let result = Self::prelu_forward_values(&input_vals, &input_shape, &weight_vals);

        let out = self.tensor_variable(result, input_shape, false)?;
        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!("prelu in={} weight={} out={}", input.0, weight.0, out.0),
        );
        Ok(out)
    }

    /// Randomized Leaky ReLU (inference mode).
    ///
    /// rrelu(x, lower, upper) = x if x >= 0, else x * (lower + upper) / 2
    /// Uses midpoint slope for deterministic inference.
    /// Tracked under frankentorch-r8ik.
    pub fn tensor_rrelu(
        &mut self,
        input: TensorNodeId,
        lower: f64,
        upper: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let slope = (lower + upper) / 2.0;
        // Borrowed-inputs: the backward only needs the SIGN of x (x>=0), an input leaf, so
        // re-read it from the live leaf instead of cloning the whole input into ctx every
        // forward. rrelu(eval) is a trivially cheap op (one compare+mul/elem), so that
        // full-input clone was the dominant cost; eliding it helps both no-grad inference and
        // training. Bit-exact (same values read). frankentorch-3jmy3 pattern.
        let out = self.tensor_apply_function_f64_borrowed_inputs(
            &[input],
            move |_ctx, inputs| {
                let (vals, shape) = inputs[0];
                let values: Vec<f64> = vals
                    .iter()
                    .map(|&x| if x >= 0.0 { x } else { slope * x })
                    .collect();
                Ok((values, shape.to_vec()))
            },
            move |_ctx, grad_outputs, borrowed| {
                let grad_out = grad_outputs[0];
                let x_vals = borrowed[0].0;
                if grad_out.len() != x_vals.len() {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "rrelu backward: gradient length mismatch",
                        },
                    )));
                }
                let grad_in: Vec<f64> = x_vals
                    .iter()
                    .zip(grad_out.iter())
                    .map(|(&x, &go)| if x >= 0.0 { go } else { go * slope })
                    .collect();
                Ok(vec![Some(grad_in)])
            },
        )?;
        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!("rrelu in={} out={}", input.0, out.0),
        );
        Ok(out)
    }

    pub fn tensor_rsqrt(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let (out, event) = self.tensor_tape.rsqrt(input, self.mode())?;
        self.record_tensor_unary_operation(&event);
        Ok(out)
    }

    pub fn tensor_erf(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let (out, event) = self.tensor_tape.erf(input, self.mode())?;
        self.record_tensor_unary_operation(&event);
        Ok(out)
    }

    pub fn tensor_erfc(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let (out, event) = self.tensor_tape.erfc(input, self.mode())?;
        self.record_tensor_unary_operation(&event);
        Ok(out)
    }

    /// Modified Bessel function of the first kind, order 0.
    ///
    /// Equivalent to `torch.special.i0(input)`. Uses the
    /// Abramowitz & Stegun 9.8.1 / 9.8.2 piecewise polynomial.
    /// Even in `x`. Autograd-aware via the analytical backward
    /// `d/dx i0(x) = i1(x)` — wired through tensor_apply_function
    /// using the i1 scalar helper from frankentorch-ner6. Tracked
    /// under frankentorch-2vxa (forward) + frankentorch-urmm
    /// (autograd unblock).
    pub fn tensor_special_i0(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        self.special_unary_with_deriv(input, bessel_i0_scalar, bessel_i1_scalar)
    }

    /// Exponentially scaled modified Bessel of the first kind,
    /// order 0: `i0e(x) = exp(-|x|) * i0(x)`.
    ///
    /// Equivalent to `torch.special.i0e(input)`. Stays bounded
    /// for large `|x|` where `i0(x)` would overflow. Same
    /// fail-loud autograd policy as `tensor_special_i0`. Tracked
    /// under frankentorch-2vxa.
    pub fn tensor_special_i0e(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // Autograd-aware via product rule (frankentorch-0wcm,
        // unblocked by ner6's i1e):
        //   d/dx i0e(x) = i1e(x) - sign(x) * i0e(x)
        //
        // i0e has a corner at x = 0 (derivative jumps from -1 to
        // +1). Convention: sign(0) = 0 gives gradient = i1e(0) =
        // 0, matching torch's autograd choice for the
        // non-differentiable point.
        // f32-native fast path (no apply_function f32->f64 upcast); same value as the f64 path.
        if let Some(out) = self.try_f32_unary_native(input, bessel_i0e_scalar)? {
            return Ok(out);
        }
        // No-grad f64 fast path: the apply_function below unconditionally save_for_backward-clones
        // the input (128MB no-grad waste). par_map bessel_i0e_scalar into a leaf. Bit-exact.
        if let Some(out) = self.try_f64_unary_native(input, bessel_i0e_scalar)? {
            return Ok(out);
        }
        self.tensor_apply_function(
            &[input],
            |ctx, inputs| {
                let (vals, shape) = inputs[0];
                // Bessel i0e is compute-bound (continued fraction / series), so
                // spread it across the rayon pool above the threshold like the other
                // special functions. Pure per-element map → bit-identical. kgs4.98.
                let result: Vec<f64> = par_map_f64(vals, |x| bessel_i0e_scalar(x));
                ctx.save_for_backward(vals.to_vec(), shape.to_vec());
                Ok((result, shape.to_vec()))
            },
            |ctx, grad_outputs| {
                let saved = ctx.saved_tensors();
                let x_vals = &saved[0];
                let grad_y = grad_outputs[0];
                let grad_x: Vec<f64> = x_vals
                    .iter()
                    .zip(grad_y.iter())
                    .map(|(&x, &gy)| {
                        let signum = if x > 0.0 {
                            1.0
                        } else if x < 0.0 {
                            -1.0
                        } else {
                            0.0
                        };
                        gy * (bessel_i1e_scalar(x) - signum * bessel_i0e_scalar(x))
                    })
                    .collect();
                Ok(vec![Some(grad_x)])
            },
        )
    }

    /// Modified Bessel function of the first kind, order 1.
    ///
    /// Equivalent to `torch.special.i1(input)`. Uses A&S 9.8.3
    /// / 9.8.4 piecewise polynomials. Odd in x:
    /// `i1(-x) = -i1(x)`. Used in von Mises gradients and
    /// heat-equation kernels. Tracked under frankentorch-ner6.
    ///
    /// Autograd-aware via the analytical backward
    /// `d/dx i1(x) = i0(x) - i1(x) / x`, with the removable
    /// zero-limit set to 0.5.
    pub fn tensor_special_i1(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // f32-native fast path: f32 input rode apply_function (upcast->f64) and returned F64 —
        // WRONG dtype (torch special.i1(f32)->f32) + slow. bessel_i1_scalar in f64 narrowed to f32,
        // matching torch's f32 kernel (same approach as the special_i0e/i1e f32 paths).
        if let Some(out) = self.try_f32_unary_native(input, bessel_i1_scalar)? {
            return Ok(out);
        }
        // No-grad f64 fast path: the apply_function below unconditionally save_for_backward-clones
        // the input (128MB no-grad waste). par_map bessel_i1_scalar into a leaf. Bit-exact.
        if let Some(out) = self.try_f64_unary_native(input, bessel_i1_scalar)? {
            return Ok(out);
        }
        self.tensor_apply_function(
            &[input],
            |ctx, inputs| {
                let (vals, shape) = inputs[0];
                let result: Vec<f64> = par_map_f64(vals, |x| bessel_i1_scalar(x));
                ctx.save_for_backward(vals.to_vec(), shape.to_vec());
                Ok((result, shape.to_vec()))
            },
            |ctx, grad_outputs| {
                let saved = ctx.saved_tensors();
                let x_vals = &saved[0];
                let grad_y = grad_outputs[0];
                let grad_x: Vec<f64> = x_vals
                    .iter()
                    .zip(grad_y.iter())
                    .map(|(&x, &gy)| gy * bessel_i1_derivative_scalar(x))
                    .collect();
                Ok(vec![Some(grad_x)])
            },
        )
    }

    /// Exponentially scaled modified Bessel of the first kind,
    /// order 1: `i1e(x) = exp(-|x|) * i1(x)`.
    ///
    /// Equivalent to `torch.special.i1e(input)`. Stays bounded for
    /// large `|x|` where `i1(x)` would overflow. Autograd-aware
    /// via the scaled analytical backward. Tracked under
    /// frankentorch-ner6 and frankentorch-ar9i.
    pub fn tensor_special_i1e(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // f32-native fast path (no apply_function f32->f64 upcast = ~15x SLOWER): same value
        // (bessel_i1e_scalar in f64, narrowed to f32) as the f64 path below. frankentorch-asymf32.
        if let Some(out) = self.try_f32_unary_native(input, bessel_i1e_scalar)? {
            return Ok(out);
        }
        // No-grad f64 fast path (sibling): skip the apply_function's unconditional save-clone.
        if let Some(out) = self.try_f64_unary_native(input, bessel_i1e_scalar)? {
            return Ok(out);
        }
        self.tensor_apply_function(
            &[input],
            |ctx, inputs| {
                let (vals, shape) = inputs[0];
                let result: Vec<f64> = par_map_f64(vals, |x| bessel_i1e_scalar(x));
                ctx.save_for_backward(vals.to_vec(), shape.to_vec());
                Ok((result, shape.to_vec()))
            },
            |ctx, grad_outputs| {
                let saved = ctx.saved_tensors();
                let x_vals = &saved[0];
                let grad_y = grad_outputs[0];
                let grad_x: Vec<f64> = x_vals
                    .iter()
                    .zip(grad_y.iter())
                    .map(|(&x, &gy)| gy * bessel_i1e_derivative_scalar(x))
                    .collect();
                Ok(vec![Some(grad_x)])
            },
        )
    }

    /// Bessel function of the first kind, order 0.
    ///
    /// Equivalent to `torch.special.bessel_j0(input)`. No autograd support.
    /// Shared implementation for an elementwise special function `fwd` with a
    /// known scalar derivative `deriv` (used for the Bessel family). Under
    /// requires_grad, routes through `tensor_apply_function` saving the input x;
    /// the backward is `grad_in[i] = deriv(x[i]) * grad_out[i]`. The forward uses
    /// the same `par_map_f64(.., fwd)` as the non-grad path, so the value is
    /// bit-identical and only the previously-severed gradient is restored.
    fn special_unary_with_deriv(
        &mut self,
        input: TensorNodeId,
        fwd: fn(f64) -> f64,
        deriv: fn(f64) -> f64,
    ) -> Result<TensorNodeId, AutogradError> {
        // f32-native fast path (no-grad): skip the f32->f64 lossy-read upcast below by computing
        // `fwd(x as f64) as f32` in one parallel pass. BIT-IDENTICAL to the lossy-read-then-cast
        // (x as f64 is exact). Fixes the WHOLE special-fn family using this helper (bessel_y0/y1,
        // modified_bessel_i0/i1/k0/k1, scaled_modified_bessel_k0/k1, ...) at once — each was
        // ~2-5x SLOWER for f32 via the upcast. frankentorch-specf32.
        if let Some(out) = self.try_f32_unary_native(input, fwd)? {
            return Ok(out);
        }
        // torch keeps the input float dtype (f32/half). Compute in f64 then cast
        // back: the no-grad path previously read f64-only `tensor_values_meta`
        // (errored on f32) and rebuilt F64; the grad path's f64 result also
        // upcast f32. Lossy-read + final cast fixes both; f64 inputs are
        // bit-identical (lossy_f64 == values, cast is a no-op). frankentorch-37czu.
        let dtype = self.tensor_dtype(input)?;
        let out = if self.tensor_requires_grad(input)? {
            self.tensor_apply_function(
                &[input],
                move |ctx, inputs| {
                    let (vals, in_shape) = inputs[0];
                    let result = par_map_f64(vals, fwd);
                    ctx.save_for_backward(vals.to_vec(), in_shape.to_vec());
                    Ok((result, in_shape.to_vec()))
                },
                move |ctx, grad_outputs| {
                    let x = &ctx.saved_tensors()[0];
                    let g = grad_outputs[0];
                    let grad_in: Vec<f64> = x
                        .iter()
                        .zip(g.iter())
                        .map(|(&xi, &gi)| deriv(xi) * gi)
                        .collect();
                    Ok(vec![Some(grad_in)])
                },
            )?
        } else {
            let vals = self.tensor_values_lossy_f64(input)?;
            let shape = self.tensor_shape(input)?;
            let result: Vec<f64> = par_map_f64(&vals, fwd);
            self.tensor_variable(result, shape, false)?
        };
        if dtype == DType::F64 {
            Ok(out)
        } else {
            self.tensor_to_dtype(out, dtype)
        }
    }

    /// Like `special_unary_with_deriv` but for a degree-parameterized special
    /// function `fwd(n, x)` whose scalar derivative in x is `deriv(n, x)`. Used
    /// for the orthogonal-polynomial family, where the degree `n` is an integer
    /// constant (non-differentiable) and only the `x` gradient flows.
    fn special_unary_n_with_deriv(
        &mut self,
        input: TensorNodeId,
        n: i64,
        fwd: fn(i64, f64) -> f64,
        deriv: fn(i64, f64) -> f64,
    ) -> Result<TensorNodeId, AutogradError> {
        // f32-native fast path (no-grad): same one-helper-fixes-N-ops lever as
        // special_unary_with_deriv. Fixes the whole degree-parameterized polynomial family
        // (chebyshev t/u/v/w + shifted, hermite h/he, laguerre, legendre) that routes through
        // here. Computes fwd(n, x as f64) as f32 in one parallel pass — values identical to the
        // prior f64 compute, but now correctly returned as F32 (torch keeps the input float
        // dtype; the old no-grad fall-through returned F64 via tensor_variable). 2.7-3.1x vs
        // torch @ ~16M f32. frankentorch-specf32.
        if let Some(out) = self.try_f32_unary_native(input, move |x| fwd(n, x))? {
            return Ok(out);
        }
        if self.tensor_requires_grad(input)? {
            return self.tensor_apply_function(
                &[input],
                move |ctx, inputs| {
                    let (vals, in_shape) = inputs[0];
                    let result = par_map_f64(vals, |x| fwd(n, x));
                    ctx.save_for_backward(vals.to_vec(), in_shape.to_vec());
                    Ok((result, in_shape.to_vec()))
                },
                move |ctx, grad_outputs| {
                    let x = &ctx.saved_tensors()[0];
                    let g = grad_outputs[0];
                    let grad_in: Vec<f64> = x
                        .iter()
                        .zip(g.iter())
                        .map(|(&xi, &gi)| deriv(n, xi) * gi)
                        .collect();
                    Ok(vec![Some(grad_in)])
                },
            );
        }
        let (vals, meta) = self.tensor_values_meta(input)?;
        let result: Vec<f64> = par_map_f64(&vals, |x| fwd(n, x));
        self.tensor_variable(result, meta.shape().to_vec(), false)
    }

    pub fn tensor_special_bessel_j0(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // f32-native fast path (no apply_function upcast = ~5x SLOWER). Bit-identical.
        if let Some(out) = self.try_f32_unary_native(input, bessel_j0_scalar)? {
            return Ok(out);
        }
        // J0'(x) = -J1(x).
        self.special_unary_with_deriv(input, bessel_j0_scalar, |x| -bessel_j1_scalar(x))
    }

    /// Bessel function of the first kind, order 1.
    ///
    /// Equivalent to `torch.special.bessel_j1(input)`. No autograd support.
    pub fn tensor_special_bessel_j1(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // f32-native fast path (no apply_function upcast = ~5.5x SLOWER). Bit-identical.
        if let Some(out) = self.try_f32_unary_native(input, bessel_j1_scalar)? {
            return Ok(out);
        }
        // J1'(x) = J0(x) - J1(x)/x.
        self.special_unary_with_deriv(input, bessel_j1_scalar, |x| {
            bessel_j0_scalar(x) - bessel_j1_scalar(x) / x
        })
    }

    /// Bessel function of the second kind, order 0.
    ///
    /// Equivalent to `torch.special.bessel_y0(input)`. No autograd support.
    pub fn tensor_special_bessel_y0(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // Y0'(x) = -Y1(x).
        self.special_unary_with_deriv(input, bessel_y0_scalar, |x| -bessel_y1_scalar(x))
    }

    /// Bessel function of the second kind, order 1.
    ///
    /// Equivalent to `torch.special.bessel_y1(input)`. No autograd support.
    pub fn tensor_special_bessel_y1(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // Y1'(x) = Y0(x) - Y1(x)/x.
        self.special_unary_with_deriv(input, bessel_y1_scalar, |x| {
            bessel_y0_scalar(x) - bessel_y1_scalar(x) / x
        })
    }

    /// Modified Bessel function of the first kind, order 0.
    ///
    /// Equivalent to `torch.special.modified_bessel_i0(input)` — the same values
    /// as [`Self::tensor_special_i0`] under torch's distinct `special.` entry
    /// point. Even in x. Autograd-aware via `i0'(x) = i1(x)`.
    pub fn tensor_special_modified_bessel_i0(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        self.special_unary_with_deriv(input, bessel_i0_scalar, bessel_i1_scalar)
    }

    /// Modified Bessel function of the first kind, order 1.
    ///
    /// Equivalent to `torch.special.modified_bessel_i1(input)` — the same values
    /// as [`Self::tensor_special_i1`] under torch's distinct `special.` entry
    /// point. Odd in x. Autograd-aware via `i1'(x) = i0(x) - i1(x)/x` (removable
    /// zero-limit 0.5).
    pub fn tensor_special_modified_bessel_i1(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        self.special_unary_with_deriv(input, bessel_i1_scalar, bessel_i1_derivative_scalar)
    }

    /// Modified Bessel function of the second kind, order 0.
    ///
    /// Equivalent to `torch.special.modified_bessel_k0(input)`. No autograd support.
    pub fn tensor_special_modified_bessel_k0(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // f32-native fast path (no f32->f64 upcast = ~1.9x SLOWER). Bit-identical.
        if let Some(out) = self.try_f32_unary_native(input, bessel_k0_scalar)? {
            return Ok(out);
        }
        // K0'(x) = -K1(x).
        self.special_unary_with_deriv(input, bessel_k0_scalar, |x| -bessel_k1_scalar(x))
    }

    /// Modified Bessel function of the second kind, order 1.
    ///
    /// Equivalent to `torch.special.modified_bessel_k1(input)`. No autograd support.
    pub fn tensor_special_modified_bessel_k1(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // K1'(x) = -K0(x) - K1(x)/x.
        self.special_unary_with_deriv(input, bessel_k1_scalar, |x| {
            -bessel_k0_scalar(x) - bessel_k1_scalar(x) / x
        })
    }

    /// Scaled modified Bessel K0: exp(x) * K0(x).
    ///
    /// Equivalent to `torch.special.scaled_modified_bessel_k0(input)`. No autograd support.
    pub fn tensor_special_scaled_modified_bessel_k0(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // d/dx [e^x K0(x)] = e^x(K0 - K1) = k0e(x) - k1e(x).
        self.special_unary_with_deriv(input, bessel_k0e_scalar, |x| {
            bessel_k0e_scalar(x) - bessel_k1e_scalar(x)
        })
    }

    /// Scaled modified Bessel K1: exp(x) * K1(x).
    ///
    /// Equivalent to `torch.special.scaled_modified_bessel_k1(input)`. No autograd support.
    pub fn tensor_special_scaled_modified_bessel_k1(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // d/dx [e^x K1(x)] = e^x(K1 - K0 - K1/x) = k1e(x) - k0e(x) - k1e(x)/x.
        self.special_unary_with_deriv(input, bessel_k1e_scalar, |x| {
            bessel_k1e_scalar(x) - bessel_k0e_scalar(x) - bessel_k1e_scalar(x) / x
        })
    }

    /// Chebyshev polynomial of the first kind T_n(x).
    ///
    /// Equivalent to `torch.special.chebyshev_polynomial_t(x, n)`.
    pub fn tensor_special_chebyshev_polynomial_t(
        &mut self,
        input: TensorNodeId,
        n: i64,
    ) -> Result<TensorNodeId, AutogradError> {
        // d/dx T_n(x) = n * U_{n-1}(x).
        self.special_unary_n_with_deriv(input, n, chebyshev_t_scalar, |n, x| {
            if n <= 0 {
                0.0
            } else {
                n as f64 * chebyshev_u_scalar(n - 1, x)
            }
        })
    }

    /// Chebyshev polynomial of the second kind U_n(x).
    ///
    /// Equivalent to `torch.special.chebyshev_polynomial_u(x, n)`.
    pub fn tensor_special_chebyshev_polynomial_u(
        &mut self,
        input: TensorNodeId,
        n: i64,
    ) -> Result<TensorNodeId, AutogradError> {
        // U_n'(x) = ((n+1)·T_{n+1}(x) − x·U_n(x)) / (x²−1).
        self.special_unary_n_with_deriv(input, n, chebyshev_u_scalar, chebyshev_u_deriv)
    }

    /// Chebyshev polynomial of the third kind V_n(x).
    ///
    /// Equivalent to `torch.special.chebyshev_polynomial_v(x, n)`.
    pub fn tensor_special_chebyshev_polynomial_v(
        &mut self,
        input: TensorNodeId,
        n: i64,
    ) -> Result<TensorNodeId, AutogradError> {
        // V_n = U_n − U_{n-1} ⇒ V_n' = U_n' − U_{n-1}'.
        self.special_unary_n_with_deriv(input, n, chebyshev_v_scalar, |n, x| {
            chebyshev_u_deriv(n, x) - chebyshev_u_deriv(n - 1, x)
        })
    }

    /// Chebyshev polynomial of the fourth kind W_n(x).
    ///
    /// Equivalent to `torch.special.chebyshev_polynomial_w(x, n)`.
    pub fn tensor_special_chebyshev_polynomial_w(
        &mut self,
        input: TensorNodeId,
        n: i64,
    ) -> Result<TensorNodeId, AutogradError> {
        // W_n = U_n + U_{n-1} ⇒ W_n' = U_n' + U_{n-1}'.
        self.special_unary_n_with_deriv(input, n, chebyshev_w_scalar, |n, x| {
            chebyshev_u_deriv(n, x) + chebyshev_u_deriv(n - 1, x)
        })
    }

    /// Shifted Chebyshev polynomial T*_n(x) = T_n(2x-1).
    ///
    /// Equivalent to `torch.special.shifted_chebyshev_polynomial_t(x, n)`.
    pub fn tensor_special_shifted_chebyshev_polynomial_t(
        &mut self,
        input: TensorNodeId,
        n: i64,
    ) -> Result<TensorNodeId, AutogradError> {
        // T*_n(x) = T_n(2x−1) ⇒ deriv = 2·T_n'(2x−1) = 2n·U_{n-1}(2x−1).
        self.special_unary_n_with_deriv(input, n, shifted_chebyshev_t_scalar, |n, x| {
            if n <= 0 {
                0.0
            } else {
                2.0 * n as f64 * chebyshev_u_scalar(n - 1, 2.0 * x - 1.0)
            }
        })
    }

    /// Shifted Chebyshev polynomial U*_n(x) = U_n(2x-1).
    ///
    /// Equivalent to `torch.special.shifted_chebyshev_polynomial_u(x, n)`.
    pub fn tensor_special_shifted_chebyshev_polynomial_u(
        &mut self,
        input: TensorNodeId,
        n: i64,
    ) -> Result<TensorNodeId, AutogradError> {
        // U*_n(x) = U_n(2x−1) ⇒ deriv = 2·U_n'(2x−1).
        self.special_unary_n_with_deriv(input, n, shifted_chebyshev_u_scalar, |n, x| {
            2.0 * chebyshev_u_deriv(n, 2.0 * x - 1.0)
        })
    }

    /// Shifted Chebyshev polynomial V*_n(x) = V_n(2x-1).
    ///
    /// Equivalent to `torch.special.shifted_chebyshev_polynomial_v(x, n)`.
    pub fn tensor_special_shifted_chebyshev_polynomial_v(
        &mut self,
        input: TensorNodeId,
        n: i64,
    ) -> Result<TensorNodeId, AutogradError> {
        // V*_n(x) = V_n(2x−1) ⇒ deriv = 2·(U_n'(2x−1) − U_{n-1}'(2x−1)).
        self.special_unary_n_with_deriv(input, n, shifted_chebyshev_v_scalar, |n, x| {
            let y = 2.0 * x - 1.0;
            2.0 * (chebyshev_u_deriv(n, y) - chebyshev_u_deriv(n - 1, y))
        })
    }

    /// Shifted Chebyshev polynomial W*_n(x) = W_n(2x-1).
    ///
    /// Equivalent to `torch.special.shifted_chebyshev_polynomial_w(x, n)`.
    pub fn tensor_special_shifted_chebyshev_polynomial_w(
        &mut self,
        input: TensorNodeId,
        n: i64,
    ) -> Result<TensorNodeId, AutogradError> {
        // W*_n(x) = W_n(2x−1) ⇒ deriv = 2·(U_n'(2x−1) + U_{n-1}'(2x−1)).
        self.special_unary_n_with_deriv(input, n, shifted_chebyshev_w_scalar, |n, x| {
            let y = 2.0 * x - 1.0;
            2.0 * (chebyshev_u_deriv(n, y) + chebyshev_u_deriv(n - 1, y))
        })
    }

    /// Physicist's Hermite polynomial H_n(x).
    ///
    /// Equivalent to `torch.special.hermite_polynomial_h(x, n)`.
    pub fn tensor_special_hermite_polynomial_h(
        &mut self,
        input: TensorNodeId,
        n: i64,
    ) -> Result<TensorNodeId, AutogradError> {
        // d/dx H_n(x) = 2n * H_{n-1}(x).
        self.special_unary_n_with_deriv(input, n, hermite_h_scalar, |n, x| {
            if n <= 0 {
                0.0
            } else {
                2.0 * n as f64 * hermite_h_scalar(n - 1, x)
            }
        })
    }

    /// Probabilist's Hermite polynomial He_n(x).
    ///
    /// Equivalent to `torch.special.hermite_polynomial_he(x, n)`.
    pub fn tensor_special_hermite_polynomial_he(
        &mut self,
        input: TensorNodeId,
        n: i64,
    ) -> Result<TensorNodeId, AutogradError> {
        // d/dx He_n(x) = n * He_{n-1}(x).
        self.special_unary_n_with_deriv(input, n, hermite_he_scalar, |n, x| {
            if n <= 0 {
                0.0
            } else {
                n as f64 * hermite_he_scalar(n - 1, x)
            }
        })
    }

    /// Laguerre polynomial L_n(x).
    ///
    /// Equivalent to `torch.special.laguerre_polynomial_l(x, n)`.
    pub fn tensor_special_laguerre_polynomial_l(
        &mut self,
        input: TensorNodeId,
        n: i64,
    ) -> Result<TensorNodeId, AutogradError> {
        // x L_n'(x) = n (L_n(x) - L_{n-1}(x)) ⇒ L_n'(x) = n (L_n - L_{n-1}) / x.
        self.special_unary_n_with_deriv(input, n, laguerre_l_scalar, |n, x| {
            if n <= 0 {
                0.0
            } else {
                n as f64 * (laguerre_l_scalar(n, x) - laguerre_l_scalar(n - 1, x)) / x
            }
        })
    }

    /// Legendre polynomial P_n(x).
    ///
    /// Equivalent to `torch.special.legendre_polynomial_p(x, n)`.
    pub fn tensor_special_legendre_polynomial_p(
        &mut self,
        input: TensorNodeId,
        n: i64,
    ) -> Result<TensorNodeId, AutogradError> {
        // (x²-1) P_n'(x) = n (x P_n(x) - P_{n-1}(x))
        //   ⇒ P_n'(x) = n (x P_n - P_{n-1}) / (x² - 1).  Singular at x = ±1.
        self.special_unary_n_with_deriv(input, n, legendre_p_scalar, |n, x| {
            if n <= 0 {
                0.0
            } else {
                n as f64 * (x * legendre_p_scalar(n, x) - legendre_p_scalar(n - 1, x))
                    / (x * x - 1.0)
            }
        })
    }

    /// Numerically stable log of the standard normal CDF.
    ///
    /// Equivalent to `torch.special.log_ndtr(input)`. Uses
    /// piecewise composition for stability:
    ///   - for `x >= -1`: `log(ndtr(x))` directly
    ///   - for `x < -1`: asymptotic expansion
    ///     `-x²/2 - log(-x) - 0.5*log(2π)
    ///       + log(1 - 1/x² + 3/x⁴ - 15/x⁶ + 105/x⁸)`
    ///
    /// Without the asymptotic, `log(ndtr(x))` underflows to `-inf`
    /// at roughly `x < -38` because `ndtr(x)` falls below f64's
    /// minimum subnormal. The asymptotic stays accurate to ~1e-15
    /// for `x <= -1`.
    ///
    /// Backward: `d/dx log_ndtr(x) = pdf(x) / ndtr(x)` (the
    /// inverse Mills ratio). For `x < -7` the ratio asymptotes to
    /// `-x` so we use that form to keep the gradient finite well
    /// past the forward's asymptotic boundary. Tracked under
    /// frankentorch-2mb1.
    pub fn tensor_special_log_ndtr(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // f32-native fast path (no-grad): apply_function below upcasts f32->f64 and clones
        // the input twice (forward read + save_for_backward) — all dead in no-grad. Compute
        // log_ndtr_scalar(x as f64) as f32 in one parallel pass = bit-identical to the prior
        // f64 compute. frankentorch-specf32.
        if let Some(out) = self.try_f32_unary_native(input, log_ndtr_scalar)? {
            return Ok(out);
        }
        // No-grad f64 fast path: apply_function clones the input twice (forward read +
        // save_for_backward) — dead in no-grad. par_map log_ndtr_scalar into a leaf. Bit-exact.
        if let Some(out) = self.try_f64_unary_native(input, log_ndtr_scalar)? {
            return Ok(out);
        }
        self.tensor_apply_function(
            &[input],
            |ctx, inputs| {
                let (vals, shape) = inputs[0];
                let result: Vec<f64> = par_map_f64(vals, log_ndtr_scalar);
                ctx.save_for_backward(vals.to_vec(), shape.to_vec());
                Ok((result, shape.to_vec()))
            },
            |ctx, grad_outputs| {
                let saved = ctx.saved_tensors();
                let x_vals = &saved[0];
                let grad_y = grad_outputs[0];
                let grad_x: Vec<f64> =
                    par_zip_map_f64(x_vals, grad_y, |x, gy| gy * log_ndtr_grad_scalar(x));
                Ok(vec![Some(grad_x)])
            },
        )
    }

    /// Inverse standard normal cumulative distribution function.
    ///
    /// Equivalent to `torch.special.ndtri(input)`. Composes
    /// through the autograd-aware `tensor_erfinv` via the
    /// closed-form identity:
    ///
    ///   ndtri(p) = sqrt(2) * erfinv(2*p - 1)
    ///
    /// Used in Gaussian sampling (inverse-CDF method), quantile
    /// transforms, and probit regression. Real-world sanity
    /// checks: `ndtri(0.5) = 0`, `ndtri(0.025) ≈ -1.96`,
    /// `ndtri(0.975) ≈ +1.96`. Tracked under frankentorch-gf4d.
    pub fn tensor_special_ndtri(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // f32-native fast path: the compose below is full x3 + mul + sub + erfinv + mul
        // (~7 passes incl. 128MB constant tensors) = ~14x SLOWER. `sqrt(2)*erfinv(2p-1)` in one
        // f64 pass (same erfinv_approx + SQRT_2 the compose uses) = bit-identical to current.
        if let Some(out) = self.try_f32_unary_native(input, |p| {
            std::f64::consts::SQRT_2 * erfinv_approx(2.0 * p - 1.0)
        })? {
            return Ok(out);
        }
        let shape = self.tensor_shape(input)?;
        // 2*p - 1 maps [0, 1] to [-1, 1] which is erfinv's domain.
        let two = self.full(shape.clone(), 2.0, false)?;
        let one = self.full(shape.clone(), 1.0, false)?;
        let sqrt2 = self.full(shape, std::f64::consts::SQRT_2, false)?;
        let two_p = self.tensor_mul(input, two)?;
        let two_p_minus_one = self.tensor_sub(two_p, one)?;
        let erfinv_val = self.tensor_erfinv(two_p_minus_one)?;
        self.tensor_mul(erfinv_val, sqrt2)
    }

    /// Standard normal cumulative distribution function.
    ///
    /// Equivalent to `torch.special.ndtr(input)`. Composes through
    /// the autograd-aware tensor_erf:
    ///
    ///   ndtr(x) = 0.5 * (1 + erf(x / sqrt(2)))
    ///
    /// Used in Gaussian probability calculations, importance-
    /// sampling weights, Bayesian inference, and Black-Scholes
    /// pricing. Gradient is the standard normal PDF
    /// (1/sqrt(2π)) * exp(-x²/2), which flows automatically
    /// through the erf chain. Tracked under frankentorch-7qh9.
    pub fn tensor_special_ndtr(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // f32-native fast path: the compose below is mul + erf + full + add + full + mul
        // (~6 passes incl. a 128MB full() constant) = ~6x SLOWER. `0.5*(1+erf(x/sqrt2))` in one
        // f64 pass (same FRAC_1_SQRT_2 + libm::erf the compose uses) = bit-identical to current.
        if let Some(out) = self.try_f32_unary_native(input, |x| {
            0.5 * (1.0 + libm::erf(x * std::f64::consts::FRAC_1_SQRT_2))
        })? {
            return Ok(out);
        }
        let shape = self.tensor_shape(input)?;
        // x / sqrt(2) — multiply by 1/sqrt(2) instead of dividing
        // since the autograd-aware path is tensor_mul + a constant.
        const INV_SQRT_2: f64 = std::f64::consts::FRAC_1_SQRT_2;
        let inv_sqrt2 = self.full(shape.clone(), INV_SQRT_2, false)?;
        let scaled = self.tensor_mul(input, inv_sqrt2)?;
        let erf_val = self.tensor_erf(scaled)?;
        let one = self.full(shape.clone(), 1.0, false)?;
        let summed = self.tensor_add(one, erf_val)?;
        let half = self.full(shape, 0.5, false)?;
        self.tensor_mul(summed, half)
    }

