    /// Element-wise threshold activation.
    ///
    /// Equivalent to `torch.threshold(input, threshold, value)` and
    /// `torch.nn.functional.threshold(input, threshold, value)`:
    /// returns `x` where `x > threshold`, else `value`. The
    /// distinguishing trait from `tensor_relu` is that the cutoff
    /// and the replacement are independent parameters — useful for
    /// gating layers in inference and for sparsifying logits with a
    /// custom sentinel. Composes through autograd-aware
    /// `tensor_gt` + `tensor_where`; gradient is 1 where x >
    /// threshold and 0 elsewhere (matches torch). Tracked under
    /// frankentorch-hptx.
    pub fn tensor_threshold(
        &mut self,
        input: TensorNodeId,
        threshold: f64,
        value: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        // For non-NaN input x: return x if x > threshold else value.
        // For NaN input: propagate NaN (matches current torch.threshold;
        // older torch returned the value branch since NaN > t is false,
        // but the current upstream behavior propagates NaN through
        // threshold). frankentorch-w9kc.
        let shape = self.tensor_shape(input)?;
        // F32 no-grad fast path: the composed implementation builds full-size
        // threshold/value/NaN tensors, then runs isnan + gt + two where passes.
        // Threshold is a positional select, so contiguous no-grad f32 can do the
        // same scalar-cast semantics and canonical NaN propagation in one pass.
        if !self.tensor_requires_grad(input)? && self.tensor_dtype(input)? == DType::F32 {
            let built = {
                let it = self.tensor_tape.tensor(input)?;
                if it.meta().is_contiguous() {
                    let values = it.contiguous_values_f32()?;
                    let threshold = threshold as f32;
                    let value = value as f32;
                    let out: Vec<f32> = if values.len() >= THRESHOLD_F32_PARALLEL_MIN {
                        use rayon::prelude::*;
                        values
                            .par_iter()
                            .map(|&x| {
                                if x.is_nan() {
                                    f32::NAN
                                } else if x > threshold {
                                    x
                                } else {
                                    value
                                }
                            })
                            .collect()
                    } else {
                        values
                            .iter()
                            .map(|&x| {
                                if x.is_nan() {
                                    f32::NAN
                                } else if x > threshold {
                                    x
                                } else {
                                    value
                                }
                            })
                            .collect()
                    };
                    Some(out)
                } else {
                    None
                }
            };
            if let Some(out) = built {
                return self.tensor_variable_f32(out, shape, false);
            }
        }
        // F64 no-grad fast path (the f64 sibling; f64 fell through to the composed path below —
        // const_tensor_like x3 [full-size F64 allocs] + isnan + gt + where x2 = ~6 passes). One
        // parallel pass: NaN -> NaN, x>threshold -> x, else value. Bit-exact with the composed
        // form (same select + canonical NaN propagation).
        if !self.tensor_requires_grad(input)? && self.tensor_dtype(input)? == DType::F64 {
            let built = {
                let it = self.tensor_tape.tensor(input)?;
                if it.meta().is_contiguous() {
                    let values = it.contiguous_values()?;
                    use rayon::prelude::*;
                    Some(
                        values
                            .par_iter()
                            .map(|&x| {
                                if x.is_nan() {
                                    f64::NAN
                                } else if x > threshold {
                                    x
                                } else {
                                    value
                                }
                            })
                            .collect::<Vec<f64>>(),
                    )
                } else {
                    None
                }
            };
            if let Some(out) = built {
                return self.tensor_variable(out, shape, false);
            }
        }
        let threshold_t = self.const_tensor_like(input, shape.clone(), threshold)?;
        let value_t = self.const_tensor_like(input, shape.clone(), value)?;
        let nan_t = self.const_tensor_like(input, shape, f64::NAN)?;
        let nan_mask = self.tensor_isnan(input)?;
        let above_mask = self.tensor_gt(input, threshold_t)?;
        let above_or_value = self.tensor_where(above_mask, input, value_t)?;
        self.tensor_where(nan_mask, nan_t, above_or_value)
    }

