    /// Element-wise cube root.
    ///
    /// Forward uses the accurate `libm::cbrt` so the out-of-place op is
    /// bit-exact with the in-place `tensor_cbrt_` (which also calls
    /// `libm::cbrt`). The earlier `sign(x) * |x|^(1/3)` composition was
    /// 1 ULP off `libm::cbrt` at small |x| (e.g. ±0.1) because `pow(.,1/3)`
    /// is not correctly-rounded — torch has no `cbrt` op, so `libm::cbrt`
    /// (the accurate cube root) is the parity reference and both paths must
    /// agree. Gradient is `1 / (3 · cbrt(x)^2) = (1/3)·|x|^(-2/3)`; the
    /// create_graph form is built from differentiable tape ops so a second
    /// backward propagates. frankentorch-aj23w.
    pub fn tensor_cbrt(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        self.tensor_apply_function_with_create_graph(
            &[input],
            |ctx, inputs| {
                let (values, shape) = inputs[0];
                // Skip the backward-only input clone in no-grad inference:
                // apply_function returns a plain Leaf and discards ctx unless an
                // input needs grad. Grad path unchanged. frankentorch-zva0u.
                if ctx.needs_input_grad().iter().any(|&g| g) {
                    ctx.save_for_backward(values.to_vec(), shape.to_vec());
                }
                // libm::cbrt (correctly-rounded cube root) is a heavy per-element
                // kernel — fan the independent lanes over Rayon (par_map preserves
                // index order => bit-for-bit identical to the serial map).
                let output = par_map_f64(values, libm::cbrt);
                Ok((output, shape.to_vec()))
            },
            |ctx, grad_outputs| {
                let grad_out = grad_outputs[0];
                let input_values = &ctx.saved_tensors()[0];
                if grad_out.len() != input_values.len() {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "cbrt backward: incoming gradient length mismatch",
                        },
                    )));
                }
                // d(cbrt(x))/dx = 1 / (3 · cbrt(x)^2). At x=0 this is +inf,
                // matching the cube-root tangent (vertical at the origin).
                let grad = par_zip_map_f64(grad_out, input_values, |go, value| {
                    let y = libm::cbrt(value);
                    go / (3.0 * y * y)
                });
                Ok(vec![ctx.needs_input_grad()[0].then_some(grad)])
            },
            // create_graph backward: d(cbrt(x))/dx = (1/3)·|x|^(-2/3), built
            // from differentiable tape ops so a second backward propagates
            // (cbrt'' = -(2/9)·sign(x)·|x|^(-5/3)). frankentorch-aj23w.
            |_ctx, grad_outs, inputs, tape| {
                let mode = ft_core::ExecutionMode::Strict;
                let abs_x = tape.abs(inputs[0], mode)?.0;
                let deriv = tape.pow(abs_x, -2.0 / 3.0, mode)?.0;
                let scaled = tape.mul_scalar(deriv, 1.0 / 3.0)?.0;
                let grad_in = tape.mul(grad_outs[0], scaled, mode)?.0;
                Ok(vec![Some(grad_in)])
            },
        )
    }

