    pub fn tensor_max(
        &mut self,
        lhs: TensorNodeId,
        rhs: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let (out, event) = self.tensor_tape.tensor_max(lhs, rhs, self.mode())?;
        self.record_tensor_operation(&event);
        Ok(out)
    }

    /// NumPy-style broadcast shape of two input shapes.
    ///
    /// Returns the element-wise max of the right-aligned dims after
    /// validating each pair is broadcast-compatible (equal or one is 1).
    /// Tracked under frankentorch-h2m0 (used by tensor_maximum / minimum).
    fn broadcast_shape(
        lhs_shape: &[usize],
        rhs_shape: &[usize],
    ) -> Result<Vec<usize>, AutogradError> {
        let lhs_len = lhs_shape.len();
        let rhs_len = rhs_shape.len();
        let out_len = lhs_len.max(rhs_len);
        let mut out = Vec::with_capacity(out_len);
        for i in 0..out_len {
            let l = if i + lhs_len >= out_len {
                lhs_shape[i + lhs_len - out_len]
            } else {
                1
            };
            let r = if i + rhs_len >= out_len {
                rhs_shape[i + rhs_len - out_len]
            } else {
                1
            };
            if l == r {
                out.push(l);
            } else if l == 1 {
                out.push(r);
            } else if r == 1 {
                out.push(l);
            } else {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                    ft_kernel_cpu::KernelError::ShapeMismatch {
                        lhs: lhs_shape.to_vec(),
                        rhs: rhs_shape.to_vec(),
                    },
                )));
            }
        }
        Ok(out)
    }

    /// Element-wise maximum with NumPy-style broadcasting.
    ///
    /// Equivalent to `torch.maximum(a, b)`. Broadcasts both operands
    /// to a common shape via tensor_broadcast_to and dispatches
    /// tensor_max on the matched-shape result. Autograd-aware:
    /// max routes upstream gradient to whichever operand achieved
    /// the per-element maximum, and broadcast_to's backward sums
    /// gradient over the broadcasted dims. Tracked under
    /// frankentorch-h2m0.
    pub fn tensor_maximum(
        &mut self,
        lhs: TensorNodeId,
        rhs: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let lhs_shape = self.tensor_shape(lhs)?;
        let rhs_shape = self.tensor_shape(rhs)?;
        // No-grad fast path: tensor_max routes through the tape op (clones both operands +
        // saves for backward even with grad off) — measured ~14.67x SLOWER than torch at
        // [4000,4000]. For equal-shape contiguous f64 with grad off, borrow both and call the
        // parallel max kernel directly (NaN-propagating, bit-identical to the tape op). No
        // clones, no tape node. Broadcast / non-contiguous / grad / non-f64 fall through.
        if lhs_shape == rhs_shape
            && !self.tensor_requires_grad(lhs)?
            && !self.tensor_requires_grad(rhs)?
            && self.tensor_dtype(lhs)? == DType::F64
            && self.tensor_dtype(rhs)? == DType::F64
        {
            let built = {
                let lt = self.tensor_tape.tensor(lhs)?;
                let rt = self.tensor_tape.tensor(rhs)?;
                if lt.meta().is_contiguous() && rt.meta().is_contiguous() {
                    let ld = lt.contiguous_values()?;
                    let rd = rt.contiguous_values()?;
                    Some(
                        ft_kernel_cpu::max_tensor_contiguous_f64(ld, rd, lt.meta(), rt.meta())
                            .map_err(|e| {
                                AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                            })?,
                    )
                } else {
                    None
                }
            };
            if let Some(out) = built {
                return self.tensor_variable(out, lhs_shape, false);
            }
        }
        // F32 mirror (was F64-only → f32 fell to the tape max, ~12x SLOWER vs torch).
        if lhs_shape == rhs_shape
            && !self.tensor_requires_grad(lhs)?
            && !self.tensor_requires_grad(rhs)?
            && self.tensor_dtype(lhs)? == DType::F32
            && self.tensor_dtype(rhs)? == DType::F32
        {
            let built = {
                let lt = self.tensor_tape.tensor(lhs)?;
                let rt = self.tensor_tape.tensor(rhs)?;
                if lt.meta().is_contiguous() && rt.meta().is_contiguous() {
                    let ld = lt.contiguous_values_f32()?;
                    let rd = rt.contiguous_values_f32()?;
                    Some(
                        ft_kernel_cpu::max_tensor_contiguous_f32(ld, rd, lt.meta(), rt.meta())
                            .map_err(|e| {
                                AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                            })?,
                    )
                } else {
                    None
                }
            };
            if let Some(out) = built {
                return self.tensor_variable_f32(out, lhs_shape, false);
            }
        }
        if let Some(out) = self.try_lastdim_bcast(lhs, rhs, BcastBinOp::Max)? {
            return Ok(out);
        }
        if let Some(out) = self.try_rowscalar_bcast(lhs, rhs, BcastBinOp::Max)? {
            return Ok(out);
        }
        if let Some(out) = self.try_fullscalar_bcast(lhs, rhs, BcastBinOp::Max)? {
            return Ok(out);
        }
        let out_shape = Self::broadcast_shape(&lhs_shape, &rhs_shape)?;
        let lhs_b = self.tensor_broadcast_to(lhs, out_shape.clone())?;
        let rhs_b = self.tensor_broadcast_to(rhs, out_shape)?;
        self.tensor_max(lhs_b, rhs_b)
    }

    /// Element-wise minimum with NumPy-style broadcasting.
    ///
    /// Sister to `tensor_maximum`, equivalent to `torch.minimum(a, b)`.
    /// Tracked under frankentorch-h2m0.
    pub fn tensor_minimum(
        &mut self,
        lhs: TensorNodeId,
        rhs: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let lhs_shape = self.tensor_shape(lhs)?;
        let rhs_shape = self.tensor_shape(rhs)?;
        // No-grad fast path mirroring tensor_maximum (see there): borrow both equal-shape
        // contiguous f64 operands and call the parallel min kernel directly, skipping the
        // tape op's clones + save-for-backward. Bit-identical (NaN-propagating).
        if lhs_shape == rhs_shape
            && !self.tensor_requires_grad(lhs)?
            && !self.tensor_requires_grad(rhs)?
            && self.tensor_dtype(lhs)? == DType::F64
            && self.tensor_dtype(rhs)? == DType::F64
        {
            let built = {
                let lt = self.tensor_tape.tensor(lhs)?;
                let rt = self.tensor_tape.tensor(rhs)?;
                if lt.meta().is_contiguous() && rt.meta().is_contiguous() {
                    let ld = lt.contiguous_values()?;
                    let rd = rt.contiguous_values()?;
                    Some(
                        ft_kernel_cpu::min_tensor_contiguous_f64(ld, rd, lt.meta(), rt.meta())
                            .map_err(|e| {
                                AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                            })?,
                    )
                } else {
                    None
                }
            };
            if let Some(out) = built {
                return self.tensor_variable(out, lhs_shape, false);
            }
        }
        // F32 mirror (was F64-only → f32 fell to the tape min, ~12x SLOWER vs torch).
        if lhs_shape == rhs_shape
            && !self.tensor_requires_grad(lhs)?
            && !self.tensor_requires_grad(rhs)?
            && self.tensor_dtype(lhs)? == DType::F32
            && self.tensor_dtype(rhs)? == DType::F32
        {
            let built = {
                let lt = self.tensor_tape.tensor(lhs)?;
                let rt = self.tensor_tape.tensor(rhs)?;
                if lt.meta().is_contiguous() && rt.meta().is_contiguous() {
                    let ld = lt.contiguous_values_f32()?;
                    let rd = rt.contiguous_values_f32()?;
                    Some(
                        ft_kernel_cpu::min_tensor_contiguous_f32(ld, rd, lt.meta(), rt.meta())
                            .map_err(|e| {
                                AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                            })?,
                    )
                } else {
                    None
                }
            };
            if let Some(out) = built {
                return self.tensor_variable_f32(out, lhs_shape, false);
            }
        }
        if let Some(out) = self.try_lastdim_bcast(lhs, rhs, BcastBinOp::Min)? {
            return Ok(out);
        }
        if let Some(out) = self.try_rowscalar_bcast(lhs, rhs, BcastBinOp::Min)? {
            return Ok(out);
        }
        if let Some(out) = self.try_fullscalar_bcast(lhs, rhs, BcastBinOp::Min)? {
            return Ok(out);
        }
        let out_shape = Self::broadcast_shape(&lhs_shape, &rhs_shape)?;
        let lhs_b = self.tensor_broadcast_to(lhs, out_shape.clone())?;
        let rhs_b = self.tensor_broadcast_to(rhs, out_shape)?;
        self.tensor_min(lhs_b, rhs_b)
    }

    /// In-place maximum: target = max(target, other) element-wise.
    pub fn tensor_maximum_(
        &mut self,
        target: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<(), AutogradError> {
        self.validate_tensor_in_place_target(target)?;
        // F64 borrow+parallel fast path (asymmetric-dtype): the generic path below CLONES BOTH
        // operands via `tensor_values_lossy_f64` + maps SERIALLY. Borrow both contiguous f64 buffers
        // + parallel max. BIT-IDENTICAL (elementwise a.max(b) is order-independent). Other dtypes /
        // non-contiguous / shape-mismatch fall through to the generic path. frankentorch (BlackThrush).
        if self.tensor_dtype(target)? == DType::F64 && self.tensor_dtype(other)? == DType::F64 {
            let built = {
                let tt = self.tensor_tape.tensor(target)?;
                let ot = self.tensor_tape.tensor(other)?;
                if tt.meta().is_contiguous() && ot.meta().is_contiguous() {
                    let tv = tt.contiguous_values()?;
                    let ov = ot.contiguous_values()?;
                    if tv.len() == ov.len() {
                        use rayon::prelude::*;
                        Some(
                            tv.par_iter()
                                .zip(ov.par_iter())
                                .map(|(&a, &b)| a.max(b))
                                .collect::<Vec<f64>>(),
                        )
                    } else {
                        None
                    }
                } else {
                    None
                }
            };
            if let Some(result) = built {
                self.update_tensor_values_for_float(target, result, INPLACE_FLOAT_REASON)?;
                self.record_tensor_in_place_operation("maximum_", target, None);
                return Ok(());
            }
        }
        let target_vals = self.tensor_values_lossy_f64(target)?;
        let other_vals = self.tensor_values_lossy_f64(other)?;
        if target_vals.len() != other_vals.len() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: self.tensor_shape(target)?,
                    rhs: self.tensor_shape(other)?,
                },
            )));
        }
        let result: Vec<f64> = target_vals
            .iter()
            .zip(other_vals.iter())
            .map(|(&a, &b)| a.max(b))
            .collect();
        self.update_tensor_values_for_float(target, result, INPLACE_FLOAT_REASON)?;
        self.record_tensor_in_place_operation("maximum_", target, None);
        Ok(())
    }

    /// In-place minimum: target = min(target, other) element-wise.
    pub fn tensor_minimum_(
        &mut self,
        target: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<(), AutogradError> {
        self.validate_tensor_in_place_target(target)?;
        // F64 borrow+parallel fast path (see tensor_maximum_): borrow both contiguous f64 buffers +
        // parallel min instead of the generic clone-both + serial map. BIT-IDENTICAL (elementwise
        // a.min(b) is order-independent). Other dtypes / non-contiguous / shape-mismatch fall through.
        if self.tensor_dtype(target)? == DType::F64 && self.tensor_dtype(other)? == DType::F64 {
            let built = {
                let tt = self.tensor_tape.tensor(target)?;
                let ot = self.tensor_tape.tensor(other)?;
                if tt.meta().is_contiguous() && ot.meta().is_contiguous() {
                    let tv = tt.contiguous_values()?;
                    let ov = ot.contiguous_values()?;
                    if tv.len() == ov.len() {
                        use rayon::prelude::*;
                        Some(
                            tv.par_iter()
                                .zip(ov.par_iter())
                                .map(|(&a, &b)| a.min(b))
                                .collect::<Vec<f64>>(),
                        )
                    } else {
                        None
                    }
                } else {
                    None
                }
            };
            if let Some(result) = built {
                self.update_tensor_values_for_float(target, result, INPLACE_FLOAT_REASON)?;
                self.record_tensor_in_place_operation("minimum_", target, None);
                return Ok(());
            }
        }
        let target_vals = self.tensor_values_lossy_f64(target)?;
        let other_vals = self.tensor_values_lossy_f64(other)?;
        if target_vals.len() != other_vals.len() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: self.tensor_shape(target)?,
                    rhs: self.tensor_shape(other)?,
                },
            )));
        }
        let result: Vec<f64> = target_vals
            .iter()
            .zip(other_vals.iter())
            .map(|(&a, &b)| a.min(b))
            .collect();
        self.update_tensor_values_for_float(target, result, INPLACE_FLOAT_REASON)?;
        self.record_tensor_in_place_operation("minimum_", target, None);
        Ok(())
    }

