    /// In-place atan2: target = atan2(target, other).
    pub fn tensor_atan2_(
        &mut self,
        target: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<(), AutogradError> {
        self.validate_tensor_in_place_target(target)?;
        // F64 borrow+parallel fast path (transcendental atan2 -> big compute win), same idiom as
        // hypot_/xlogy_/etc. Bit-identical to the serial fallback (order-preserving par map, f64+
        // contiguous only). frankentorch-inplace-binary-fastpath.
        if self.try_inplace_binary_f64(target, other, "atan2_", |y, x| y.atan2(x))? {
            return Ok(());
        }
        let target_vals = self.tensor_values_lossy_f64(target)?;
        let other_vals = self.tensor_values_lossy_f64(other)?;
        if target_vals.len() != other_vals.len() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: self.tensor_shape(target)?,
                    rhs: self.tensor_shape(other)?,
                },
            )));
        }
        let result: Vec<f64> = target_vals
            .iter()
            .zip(other_vals.iter())
            .map(|(&y, &x)| y.atan2(x))
            .collect();
        self.update_tensor_values_for_float(target, result, INPLACE_FLOAT_REASON)?;
        self.record_tensor_in_place_operation("atan2_", target, None);
        Ok(())
    }

    /// Element-wise angle (in radians) for real tensors.
    ///
    /// Equivalent to `torch.angle(input)` for real-valued tensors:
    /// returns 0 where `x >= 0`, `π` where `x < 0`, and NaN where
    /// `x` is NaN. Composes through autograd-aware `tensor_atan2`
    /// with a zero left operand: `angle(x) = atan2(0, x)`. Useful
    /// in pipelines that ingest signed-magnitude data and need
    /// the phase channel separately. Tracked under
    /// frankentorch-66hu.
    pub fn tensor_angle(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let dtype = self.tensor_dtype(input)?;
        if matches!(dtype, DType::Complex64 | DType::Complex128) {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "angle: complex inputs not supported (would require atan2(imag, real) with Wirtinger semantics). Tracked under frankentorch-66hu.",
                },
            )));
        }
        // For real inputs, torch.angle returns 0 if x >= 0 and π if
        // x < 0. The previous formulation atan2(0, x) gave π for both
        // x = -0 and x < 0 (per IEEE 754 atan2(+0, -0) = π), which
        // diverges from torch for the x = -0 case (torch treats -0
        // and +0 identically since -0 == 0). Reformulated as
        // where(isnan(x), NaN, where(x < 0, π, 0)) to also preserve
        // NaN propagation. frankentorch-q76p.
        // f32-native fast path: the where-chain below builds THREE 128MB f64 constant tensors
        // (0/π/NaN) + lt + isnan + where x2 = ~9x SLOWER. `isnan ? NaN : x<0 ? π : 0` in one
        // pass = bit-identical (x<0 is false for -0.0, matching the lt mask; NaN preserved).
        if let Some(out) = self.try_f32_unary_native(input, |x| {
            if x.is_nan() {
                f64::NAN
            } else if x < 0.0 {
                std::f64::consts::PI
            } else {
                0.0
            }
        })? {
            return Ok(out);
        }
        let shape = self.tensor_shape(input)?;
        let zero_scalar = self.full(shape.clone(), 0.0, false)?;
        let pi_scalar = self.full(shape.clone(), std::f64::consts::PI, false)?;
        let nan_scalar = self.full(shape, f64::NAN, false)?;
        let negative_mask = self.tensor_lt(input, zero_scalar)?;
        let neg_or_zero = self.tensor_where(negative_mask, pi_scalar, zero_scalar)?;
        let nan_mask = self.tensor_isnan(input)?;
        self.tensor_where(nan_mask, nan_scalar, neg_or_zero)
    }

    /// IEEE 754-2008 maxNum: NaN-tolerant element-wise maximum.
    ///
    /// Equivalent to `torch.fmax(input, other)`. Differs from
    /// `tensor_maximum` (torch.maximum) in NaN handling: if exactly
    /// one operand is NaN at a given position, the non-NaN operand
    /// is returned; only when BOTH operands are NaN does the output
    /// hold NaN. This is the variant used in NaN-as-sentinel
    /// pipelines for safe clamping. Composes through autograd-aware
    /// where + isnan + maximum, so gradients flow through whichever
    /// operand wins (zero through the loser, including the NaN
    /// branches). Tracked under frankentorch-suux.
    /// No-grad same-shape fused fast path for fmax/fmin: both ops otherwise compose
    /// `broadcast_to(lhs) + broadcast_to(rhs) + max + isnan(lhs) + isnan(rhs) + where + where`
    /// (~7 full-tensor passes) EVEN for equal shapes. Fuse to ONE NaN-TOLERANT pass — fmax ignores
    /// NaN (`a.is_nan() ? b : b.is_nan() ? a : a.max(b)`; NaN only if both), matching the compose
    /// exactly (verified). f32/f64, contiguous, no-grad, equal shapes; else falls through.
    fn try_fmaxmin_sameshape(
        &mut self,
        lhs: TensorNodeId,
        rhs: TensorNodeId,
        is_max: bool,
    ) -> Result<Option<TensorNodeId>, AutogradError> {
        let ls = self.tensor_shape(lhs)?;
        if ls != self.tensor_shape(rhs)?
            || self.tensor_requires_grad(lhs)?
            || self.tensor_requires_grad(rhs)?
        {
            return Ok(None);
        }
        let dtype = self.tensor_dtype(lhs)?;
        if self.tensor_dtype(rhs)? != dtype {
            return Ok(None);
        }
        let n: usize = ls.iter().product();
        macro_rules! fused {
            ($read:ident, $build:ident, $ty:ty) => {{
                let built = {
                    let lt = self.tensor_tape.tensor(lhs)?;
                    let rt = self.tensor_tape.tensor(rhs)?;
                    if lt.meta().is_contiguous() && rt.meta().is_contiguous() {
                        let ld = lt.$read()?;
                        let rd = rt.$read()?;
                        if ld.len() == n && rd.len() == n {
                            use rayon::prelude::*;
                            let map = |(&a, &b): (&$ty, &$ty)| -> $ty {
                                if a.is_nan() {
                                    b
                                } else if b.is_nan() {
                                    a
                                } else if is_max {
                                    a.max(b)
                                } else {
                                    a.min(b)
                                }
                            };
                            let out = if n >= PARALLEL_ELEMENTWISE_MIN {
                                ld.par_iter().zip(rd.par_iter()).map(map).collect()
                            } else {
                                ld.iter().zip(rd.iter()).map(map).collect()
                            };
                            Some(out)
                        } else {
                            None
                        }
                    } else {
                        None
                    }
                };
                match built {
                    Some(out) => Ok(Some(self.$build(out, ls.clone(), false)?)),
                    None => Ok(None),
                }
            }};
        }
        match dtype {
            DType::F64 => fused!(contiguous_values, tensor_variable, f64),
            DType::F32 => fused!(contiguous_values_f32, tensor_variable_f32, f32),
            _ => Ok(None),
        }
    }

    pub fn tensor_fmax(
        &mut self,
        lhs: TensorNodeId,
        rhs: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        if let Some(out) = self.try_fmaxmin_sameshape(lhs, rhs, true)? {
            return Ok(out);
        }
        // Broadcast first so the where masks have the same shape
        // as the operands (matches the maximum/minimum convention).
        let lhs_shape = self.tensor_shape(lhs)?;
        let rhs_shape = self.tensor_shape(rhs)?;
        let out_shape = Self::broadcast_shape(&lhs_shape, &rhs_shape)?;
        let lhs_b = self.tensor_broadcast_to(lhs, out_shape.clone())?;
        let rhs_b = self.tensor_broadcast_to(rhs, out_shape)?;
        let raw_max = self.tensor_max(lhs_b, rhs_b)?;
        let nan_lhs = self.tensor_isnan(lhs_b)?;
        let nan_rhs = self.tensor_isnan(rhs_b)?;
        // step1: when rhs is NaN, take lhs (which may be NaN -> handled below).
        let step1 = self.tensor_where(nan_rhs, lhs_b, raw_max)?;
        // step2: when lhs is NaN, take rhs (NaN preserved iff both NaN).
        self.tensor_where(nan_lhs, rhs_b, step1)
    }

    /// IEEE 754-2008 minNum: NaN-tolerant element-wise minimum.
    ///
    /// Sister to `tensor_fmax`; equivalent to `torch.fmin(input, other)`.
    /// Tracked under frankentorch-suux.
    pub fn tensor_fmin(
        &mut self,
        lhs: TensorNodeId,
        rhs: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        if let Some(out) = self.try_fmaxmin_sameshape(lhs, rhs, false)? {
            return Ok(out);
        }
        let lhs_shape = self.tensor_shape(lhs)?;
        let rhs_shape = self.tensor_shape(rhs)?;
        let out_shape = Self::broadcast_shape(&lhs_shape, &rhs_shape)?;
        let lhs_b = self.tensor_broadcast_to(lhs, out_shape.clone())?;
        let rhs_b = self.tensor_broadcast_to(rhs, out_shape)?;
        let raw_min = self.tensor_min(lhs_b, rhs_b)?;
        let nan_lhs = self.tensor_isnan(lhs_b)?;
        let nan_rhs = self.tensor_isnan(rhs_b)?;
        let step1 = self.tensor_where(nan_rhs, lhs_b, raw_min)?;
        self.tensor_where(nan_lhs, rhs_b, step1)
    }

    /// In-place fmax: NaN-tolerant maximum (ignores NaN if other is finite).
    pub fn tensor_fmax_(
        &mut self,
        target: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<(), AutogradError> {
        self.validate_tensor_in_place_target(target)?;
        if self.try_inplace_binary_f64(target, other, "fmax_", |a, b| {
            if a.is_nan() && !b.is_nan() {
                b
            } else if b.is_nan() && !a.is_nan() {
                a
            } else {
                a.max(b)
            }
        })? {
            return Ok(());
        }
        let target_vals = self.tensor_values_lossy_f64(target)?;
        let other_vals = self.tensor_values_lossy_f64(other)?;
        if target_vals.len() != other_vals.len() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: self.tensor_shape(target)?,
                    rhs: self.tensor_shape(other)?,
                },
            )));
        }
        let result: Vec<f64> = target_vals
            .iter()
            .zip(other_vals.iter())
            .map(|(&a, &b)| {
                if a.is_nan() && !b.is_nan() {
                    b
                } else if b.is_nan() && !a.is_nan() {
                    a
                } else {
                    a.max(b)
                }
            })
            .collect();
        self.update_tensor_values_for_float(target, result, INPLACE_FLOAT_REASON)?;
        self.record_tensor_in_place_operation("fmax_", target, None);
        Ok(())
    }

    /// In-place fmin: NaN-tolerant minimum (ignores NaN if other is finite).
    pub fn tensor_fmin_(
        &mut self,
        target: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<(), AutogradError> {
        self.validate_tensor_in_place_target(target)?;
        if self.try_inplace_binary_f64(target, other, "fmin_", |a, b| {
            if a.is_nan() && !b.is_nan() {
                b
            } else if b.is_nan() && !a.is_nan() {
                a
            } else {
                a.min(b)
            }
        })? {
            return Ok(());
        }
        let target_vals = self.tensor_values_lossy_f64(target)?;
        let other_vals = self.tensor_values_lossy_f64(other)?;
        if target_vals.len() != other_vals.len() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: self.tensor_shape(target)?,
                    rhs: self.tensor_shape(other)?,
                },
            )));
        }
        let result: Vec<f64> = target_vals
            .iter()
            .zip(other_vals.iter())
            .map(|(&a, &b)| {
                if a.is_nan() && !b.is_nan() {
                    b
                } else if b.is_nan() && !a.is_nan() {
                    a
                } else {
                    a.min(b)
                }
            })
            .collect();
        self.update_tensor_values_for_float(target, result, INPLACE_FLOAT_REASON)?;
        self.record_tensor_in_place_operation("fmin_", target, None);
        Ok(())
    }

