    /// Gated Linear Unit: split `input` in half along `dim` and gate.
    ///
    /// Equivalent to `torch.nn.functional.glu(input, dim)`. Returns
    /// `a * sigmoid(b)` where `a` is the first half and `b` the second
    /// half along `dim`. The size of `dim` must be even. Composes
    /// through autograd-aware tensor_narrow + tensor_sigmoid +
    /// tensor_mul. Tracked under frankentorch-47fn.
    /// No-grad fused GLU-variant fast path: split `input` in half along `dim` and compute
    /// `a * act(b)` in ONE pass. Shared by swiglu (act = silu) and reglu (act = relu); their compose
    /// (narrow a + narrow b + act(b) + mul) rides STRIDED views through the tape = ~180ms (like glu,
    /// 6-8x SLOWER than torch). `act64`/`act32` must replicate the activation KERNEL's exact per-element
    /// formula for bit-exactness to the compose. Caller validates dim/even. no-grad / contiguous /
    /// f32-f64 only.
    fn try_glu_variant_fused(
        &mut self,
        input: TensorNodeId,
        dim: usize,
        dim_size: usize,
        half: usize,
        act64: impl Fn(f64) -> f64 + Sync,
        act32: impl Fn(f32) -> f32 + Sync,
    ) -> Result<Option<TensorNodeId>, AutogradError> {
        if self.tensor_requires_grad(input)? {
            return Ok(None);
        }
        let shape = self.tensor_shape(input)?;
        let dt = self.tensor_dtype(input)?;
        let outer: usize = shape[..dim].iter().product();
        let inner: usize = shape[dim + 1..].iter().product();
        let mut out_shape = shape.clone();
        out_shape[dim] = half;
        macro_rules! fused {
            ($read:ident, $build:ident, $ty:ty, $act:expr) => {{
                let built = {
                    let it = self.tensor_tape.tensor(input)?;
                    if it.meta().is_contiguous() {
                        use rayon::prelude::*;
                        let v = it.$read()?;
                        let in_ob = dim_size * inner;
                        let out_ob = half * inner;
                        let mut out = vec![0 as $ty; outer * out_ob];
                        out.par_chunks_mut(out_ob)
                            .enumerate()
                            .for_each(|(oi, ochunk)| {
                                let base = oi * in_ob;
                                for ok in 0..half {
                                    for j in 0..inner {
                                        let a = v[base + ok * inner + j];
                                        let b = v[base + (half + ok) * inner + j];
                                        ochunk[ok * inner + j] = a * $act(b);
                                    }
                                }
                            });
                        Some(out)
                    } else {
                        None
                    }
                };
                match built {
                    Some(out) => Ok(Some(self.$build(out, out_shape.clone(), false)?)),
                    None => Ok(None),
                }
            }};
        }
        match dt {
            DType::F64 => fused!(contiguous_values, tensor_variable, f64, act64),
            DType::F32 => fused!(contiguous_values_f32, tensor_variable_f32, f32, act32),
            _ => Ok(None),
        }
    }

    pub fn tensor_glu(
        &mut self,
        input: TensorNodeId,
        dim: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        if dim >= shape.len() {
            // KernelError::InvalidDimension carries the offending dim
            // and the input rank in the diagnostic, matching the
            // dim-bounds error policy used by tensor_diag,
            // tensor_diag_embed, tensor_dot, etc. The previous
            // IncompatibleSet { reason: &'static str } path forced
            // callers to print their own dim/rank to debug.
            // Tracked under frankentorch-oagi.
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::InvalidDimension {
                    dim,
                    ndim: shape.len(),
                },
            )));
        }
        let dim_size = shape[dim];
        if dim_size % 2 != 0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "glu: input size along dim must be even",
                },
            )));
        }
        let half = dim_size / 2;
        // No-grad fast path: the compose (narrow a + narrow b + sigmoid + mul) rides STRIDED views
        // through the tape — MEASURED ~180ms (6-8x SLOWER than torch) for [B,S,2D]. Fuse into ONE pass:
        // out[.,ok,j] = a * sigmoid(b), where a/b are the two halves along `dim`. Bit-exact to the
        // compose (sigmoid == the kernel's 1/(1+exp(-b)); the `a * sig` order matches mul(a,sigmoid(b))).
        // f32/f64, contiguous, no-grad; grad / non-contiguous / other dtype fall through.
        if !self.tensor_requires_grad(input)? {
            let dt = self.tensor_dtype(input)?;
            let outer: usize = shape[..dim].iter().product();
            let inner: usize = shape[dim + 1..].iter().product();
            let mut out_shape = shape.clone();
            out_shape[dim] = half;
            macro_rules! fused {
                ($read:ident, $build:ident, $ty:ty) => {{
                    let built = {
                        let it = self.tensor_tape.tensor(input)?;
                        if it.meta().is_contiguous() {
                            use rayon::prelude::*;
                            let v = it.$read()?;
                            let in_ob = dim_size * inner; // input outer-block stride
                            let out_ob = half * inner; // output outer-block stride
                            let mut out = vec![0 as $ty; outer * out_ob];
                            out.par_chunks_mut(out_ob)
                                .enumerate()
                                .for_each(|(oi, ochunk)| {
                                    let base = oi * in_ob;
                                    for ok in 0..half {
                                        for j in 0..inner {
                                            let a = v[base + ok * inner + j];
                                            let b = v[base + (half + ok) * inner + j];
                                            ochunk[ok * inner + j] =
                                                a * ((1.0 as $ty) / ((1.0 as $ty) + (-b).exp()));
                                        }
                                    }
                                });
                            Some(out)
                        } else {
                            None
                        }
                    };
                    if let Some(out) = built {
                        return self.$build(out, out_shape.clone(), false);
                    }
                }};
            }
            match dt {
                DType::F64 => fused!(contiguous_values, tensor_variable, f64),
                DType::F32 => fused!(contiguous_values_f32, tensor_variable_f32, f32),
                _ => {}
            }
        }
        let a = self.tensor_narrow(input, dim, 0, half)?;
        let b = self.tensor_narrow(input, dim, half, half)?;
        let b_sig = self.tensor_sigmoid(b)?;
        self.tensor_mul(a, b_sig)
    }

    /// SwiGLU activation (Swish-Gated Linear Unit).
    ///
    /// Splits the input tensor in half along `dim`. The size of `dim` must be even.
    /// Computes: `a * swish(b)` where `swish(x) = x * sigmoid(x)`.
    /// Used in modern LLMs like LLaMA and PaLM.
    pub fn tensor_swiglu(
        &mut self,
        input: TensorNodeId,
        dim: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        if dim >= shape.len() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::InvalidDimension {
                    dim,
                    ndim: shape.len(),
                },
            )));
        }
        let dim_size = shape[dim];
        if dim_size % 2 != 0 {
            return Err(Self::incompatible_tensor_args(
                "swiglu: input size along dim must be even",
            ));
        }
        let half = dim_size / 2;
        // No-grad fast path (shared with glu/reglu): a * silu(b) in ONE pass. silu = the kernel's
        // x/(1+exp(-x)); bit-exact to mul(a, silu(b)).
        if let Some(out) = self.try_glu_variant_fused(
            input,
            dim,
            dim_size,
            half,
            |x| x / (1.0 + (-x).exp()),
            |x| x / (1.0_f32 + (-x).exp()),
        )? {
            return Ok(out);
        }
        let a = self.tensor_narrow(input, dim, 0, half)?;
        let b = self.tensor_narrow(input, dim, half, half)?;
        let b_swish = self.tensor_silu(b)?;
        self.tensor_mul(a, b_swish)
    }

    /// GeGLU activation (GELU-Gated Linear Unit).
    ///
    /// Splits the input tensor in half along `dim`. The size of `dim` must be even.
    /// Computes: `a * gelu(b)`.
    /// Used in some transformer architectures.
    pub fn tensor_geglu(
        &mut self,
        input: TensorNodeId,
        dim: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        if dim >= shape.len() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::InvalidDimension {
                    dim,
                    ndim: shape.len(),
                },
            )));
        }
        let dim_size = shape[dim];
        if dim_size % 2 != 0 {
            return Err(Self::incompatible_tensor_args(
                "geglu: input size along dim must be even",
            ));
        }
        let half = dim_size / 2;
        // No-grad fast path (shared with glu/swiglu/reglu): a * gelu(b) in ONE pass. gelu = the exact
        // erf kernel 0.5*x*(1+erf(x/sqrt2)) (libm::erf/erff, matching gelu_value/gelu_value_f32);
        // bit-exact to mul(a, gelu(b)).
        if let Some(out) = self.try_glu_variant_fused(
            input,
            dim,
            dim_size,
            half,
            |x| 0.5 * x * (1.0 + libm::erf(x * std::f64::consts::FRAC_1_SQRT_2)),
            |x| 0.5_f32 * x * (1.0_f32 + libm::erff(x * std::f32::consts::FRAC_1_SQRT_2)),
        )? {
            return Ok(out);
        }
        let a = self.tensor_narrow(input, dim, 0, half)?;
        let b = self.tensor_narrow(input, dim, half, half)?;
        let b_gelu = self.tensor_gelu(b)?;
        self.tensor_mul(a, b_gelu)
    }

    /// ReGLU activation (ReLU-Gated Linear Unit).
    ///
    /// Splits the input tensor in half along `dim`. The size of `dim` must be even.
    /// Computes: `a * relu(b)`.
    pub fn tensor_reglu(
        &mut self,
        input: TensorNodeId,
        dim: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        if dim >= shape.len() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::InvalidDimension {
                    dim,
                    ndim: shape.len(),
                },
            )));
        }
        let dim_size = shape[dim];
        if dim_size % 2 != 0 {
            return Err(Self::incompatible_tensor_args(
                "reglu: input size along dim must be even",
            ));
        }
        let half = dim_size / 2;
        // No-grad fast path (shared with glu/swiglu): a * relu(b) in ONE pass. relu = the kernel's
        // b.max(0.0) (NaN -> 0, matching the kernel); bit-exact to mul(a, relu(b)).
        if let Some(out) = self.try_glu_variant_fused(
            input,
            dim,
            dim_size,
            half,
            |x| x.max(0.0),
            |x| x.max(0.0_f32),
        )? {
            return Ok(out);
        }
        let a = self.tensor_narrow(input, dim, 0, half)?;
        let b = self.tensor_narrow(input, dim, half, half)?;
        let b_relu = self.tensor_relu(b)?;
        self.tensor_mul(a, b_relu)
    }

