    /// Scaled dot-product attention. Alias for tensor_scaled_dot_product_attention.
    pub fn functional_scaled_dot_product_attention(
        &mut self,
        query: TensorNodeId,
        key: TensorNodeId,
        value: TensorNodeId,
        attn_mask: Option<TensorNodeId>,
        is_causal: bool,
        scale: Option<f64>,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_scaled_dot_product_attention(query, key, value, attn_mask, is_causal, scale)
    }

    /// Interleave-repeat the head axis (dim `nd-3` of a `[.., H, S, D]` tensor)
    /// `group` times, so head `h` becomes `group` consecutive copies — the
    /// `repeat_interleave(group, dim=heads)` used to broadcast K/V heads up to the
    /// query head count for grouped-query attention. Done with unsqueeze / expand
    /// / reshape (autograd-aware); `group == 1` is a no-op.
    fn repeat_kv_heads(
        &mut self,
        tensor: TensorNodeId,
        group: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        if group == 1 {
            return Ok(tensor);
        }
        let shape = self.tensor_shape(tensor)?;
        let nd = shape.len();
        let head_dim = nd - 3;
        let heads = shape[head_dim];
        let unsqueezed = self.tensor_unsqueeze(tensor, head_dim + 1)?;
        let mut expand_shape = self.tensor_shape(unsqueezed)?;
        expand_shape[head_dim + 1] = group;
        let expanded = self.tensor_expand(unsqueezed, expand_shape)?;
        let contiguous = self.tensor_contiguous(expanded)?;
        let mut merged = shape;
        merged[head_dim] = heads * group;
        self.tensor_reshape(contiguous, merged)
    }

    /// Scaled dot-product attention with grouped-query attention (GQA / MQA),
    /// matching `torch.nn.functional.scaled_dot_product_attention(..., scale,
    /// enable_gqa)`.
    ///
    /// When `enable_gqa` is true and the key/value head count is smaller than the
    /// query head count (a multiple of it), the K/V heads are broadcast up to the
    /// query head count by interleave-repeating the head axis, then ordinary SDPA
    /// runs — bit-exact with torch (verified torch.allclose). This is the
    /// attention used by Llama-2/3 and Mistral. `enable_gqa == false` (or equal
    /// head counts) is exactly [`Self::tensor_scaled_dot_product_attention`].
    pub fn tensor_scaled_dot_product_attention_gqa(
        &mut self,
        query: TensorNodeId,
        key: TensorNodeId,
        value: TensorNodeId,
        attn_mask: Option<TensorNodeId>,
        is_causal: bool,
        scale: Option<f64>,
        enable_gqa: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        if !enable_gqa {
            return self.tensor_scaled_dot_product_attention(
                query, key, value, attn_mask, is_causal, scale,
            );
        }
        let q_shape = self.tensor_shape(query)?;
        let k_shape = self.tensor_shape(key)?;
        if q_shape.len() < 3 || k_shape.len() < 3 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "scaled_dot_product_attention: enable_gqa requires >=3-D [.., H, S, D]",
                },
            )));
        }
        let h_q = q_shape[q_shape.len() - 3];
        let h_kv = k_shape[k_shape.len() - 3];
        let (key, value) = if h_q == h_kv {
            (key, value)
        } else {
            if h_kv == 0 || h_q % h_kv != 0 {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "scaled_dot_product_attention: query heads must be a multiple of key/value heads for enable_gqa",
                    },
                )));
            }
            let group = h_q / h_kv;
            // Direct grouped masked flash fast path (no-grad f64): index kv_head = q_head/group
            // instead of materialising `group`-repeated K/V heads, keeping each K/V head hot
            // across its whole group. Bit-exact with the expand-then-flash path below.
            // frankentorch-sdpamask-gqa.
            if let Some(mask_id) = attn_mask
                && !is_causal
                && q_shape.len() >= 3
                && q_shape.len() == k_shape.len()
                && self.tensor_dtype(query)? == DType::F64
                && self.tensor_dtype(key)? == DType::F64
                && self.tensor_dtype(value)? == DType::F64
                && self.tensor_dtype(mask_id)? == DType::F64
                && !self.tensor_tape.tensor_requires_grad(query)?
                && !self.tensor_tape.tensor_requires_grad(key)?
                && !self.tensor_tape.tensor_requires_grad(value)?
                && !self.tensor_tape.tensor_requires_grad(mask_id)?
                && self.tensor_tape.tensor(query)?.meta().is_contiguous()
                && self.tensor_tape.tensor(key)?.meta().is_contiguous()
                && self.tensor_tape.tensor(value)?.meta().is_contiguous()
                && self.tensor_tape.tensor(mask_id)?.meta().is_contiguous()
            {
                let v_shape = self.tensor_shape(value)?;
                let m_shape = self.tensor_shape(mask_id)?;
                if v_shape.len() == q_shape.len() {
                    let nd = q_shape.len();
                    let seq_q = q_shape[nd - 2];
                    let d_k_dim = q_shape[nd - 1];
                    let seq_k = k_shape[nd - 2];
                    let d_v = v_shape[nd - 1];
                    let batch: usize = q_shape[..nd - 2].iter().product::<usize>() / h_q;
                    let q_lead: usize = q_shape[..nd - 2].iter().product();
                    let mask_bh_stride =
                        if m_shape.len() == 2 && m_shape[0] == seq_q && m_shape[1] == seq_k {
                            Some(0usize)
                        } else if m_shape.len() == 3
                            && m_shape[0] == q_lead
                            && m_shape[1] == seq_q
                            && m_shape[2] == seq_k
                        {
                            Some(seq_q * seq_k)
                        } else {
                            None
                        };
                    if let Some(mbs) = mask_bh_stride
                        && q_lead == batch * h_q
                        && k_shape[nd - 3] == h_kv
                        && v_shape[nd - 3] == h_kv
                        && k_shape[..nd - 3] == q_shape[..nd - 3]
                        && v_shape[..nd - 3] == q_shape[..nd - 3]
                        && k_shape[nd - 1] == d_k_dim
                        && v_shape[nd - 2] == seq_k
                        && batch > 0
                        && seq_q > 0
                        && seq_k > 0
                        && d_k_dim > 0
                        && d_v > 0
                    {
                        let scale_factor = scale.unwrap_or(1.0 / (d_k_dim as f64).sqrt());
                        let mut out_shape = q_shape.clone();
                        out_shape[nd - 1] = d_v;
                        let out = {
                            let qv = self.tensor_tape.tensor(query)?.contiguous_values()?;
                            let kv = self.tensor_tape.tensor(key)?.contiguous_values()?;
                            let vv = self.tensor_tape.tensor(value)?.contiguous_values()?;
                            let mv = self.tensor_tape.tensor(mask_id)?.contiguous_values()?;
                            ft_kernel_cpu::sdpa_forward_masked_gqa_f64(
                                qv,
                                kv,
                                vv,
                                batch,
                                h_q,
                                h_kv,
                                seq_q,
                                seq_k,
                                d_k_dim,
                                d_v,
                                scale_factor,
                                mv,
                                mbs,
                            )
                        };
                        return self.tensor_variable(out, out_shape, false);
                    }
                }
            }
            let key_rep = self.repeat_kv_heads(key, group)?;
            let value_rep = self.repeat_kv_heads(value, group)?;
            (key_rep, value_rep)
        };
        self.tensor_scaled_dot_product_attention(query, key, value, attn_mask, is_causal, scale)
    }

