    pub fn tensor_argmax(
        &mut self,
        input: TensorNodeId,
        dim: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        // f32 fast path: the tape's argmax reads `contiguous_values_as_f64()` which UPCASTS the
        // whole f32 buffer to f64 (128MB clone at 16M) before the f64 kernel = ~40x SLOWER than
        // torch. The native f32 kernel is parallel; f32->f64 is order-preserving (incl. NaN), so
        // the argmax INDEX is bit-identical. Indices fit f32 exactly for dims < 2^24; widen to
        // f64 to match the tape's F64 index output. argmax is non-differentiable (index output)
        // so there is no grad path to preserve. frankentorch-argf32.
        if let Some((values, out_shape)) = self.argextremum_f32_fast(input, dim, true)? {
            return self.tensor_variable(values, out_shape, false);
        }
        // f64 borrow fast path: the tape's argmax below CLONES via contiguous_values_as_f64()
        // (128MB serial copy at 16M — the F64 branch is `.to_vec()`) before the SAME f64 kernel.
        // Borrow the contiguous f64 buffer + call the identical kernel = bit-exact indices, no clone.
        if let Some((values, out_shape)) = self.argextremum_f64_fast(input, dim, true)? {
            return self.tensor_variable(values, out_shape, false);
        }
        self.tensor_tape.argmax(input, dim)
    }

    pub fn tensor_argmin(
        &mut self,
        input: TensorNodeId,
        dim: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        if let Some((values, out_shape)) = self.argextremum_f32_fast(input, dim, false)? {
            return self.tensor_variable(values, out_shape, false);
        }
        if let Some((values, out_shape)) = self.argextremum_f64_fast(input, dim, false)? {
            return self.tensor_variable(values, out_shape, false);
        }
        self.tensor_tape.argmin(input, dim)
    }

    /// Native f64 argmax/argmin index fast path (avoids the tape's `contiguous_values_as_f64()`
    /// `.to_vec()` CLONE of an already-f64 input). Borrows the contiguous f64 buffer and runs the
    /// SAME `argmax/argmin_dim_tensor_contiguous_f64` kernel the tape uses, so the indices are
    /// bit-identical. Returns `Some((indices_as_f64, out_shape))` for contiguous f64 input.
    fn argextremum_f64_fast(
        &mut self,
        input: TensorNodeId,
        dim: usize,
        is_max: bool,
    ) -> Result<Option<(Vec<f64>, Vec<usize>)>, AutogradError> {
        if self.tensor_dtype(input)? != DType::F64 {
            return Ok(None);
        }
        let t = self.tensor_tape.tensor(input)?;
        if !t.meta().is_contiguous() {
            return Ok(None);
        }
        let meta = t.meta().clone();
        let vals = t.contiguous_values()?;
        let values = if is_max {
            ft_kernel_cpu::argmax_dim_tensor_contiguous_f64(vals, &meta, dim)
        } else {
            ft_kernel_cpu::argmin_dim_tensor_contiguous_f64(vals, &meta, dim)
        }
        .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?;
        let mut out_shape = meta.shape().to_vec();
        out_shape.remove(dim);
        if out_shape.is_empty() {
            out_shape.push(1);
        }
        Ok(Some((values, out_shape)))
    }

    /// Native f32 argmax/argmin index fast path (avoids the tape's f32->f64 upcast). Returns
    /// `Some((indices_as_f64, out_shape))` for contiguous f32 input, else `None` to fall through.
    fn argextremum_f32_fast(
        &mut self,
        input: TensorNodeId,
        dim: usize,
        is_max: bool,
    ) -> Result<Option<(Vec<f64>, Vec<usize>)>, AutogradError> {
        if self.tensor_dtype(input)? != DType::F32 {
            return Ok(None);
        }
        let t = self.tensor_tape.tensor(input)?;
        if !t.meta().is_contiguous() {
            return Ok(None);
        }
        let meta = t.meta().clone();
        let vals = t.contiguous_values_f32()?;
        let idx_f32 = if is_max {
            ft_kernel_cpu::argmax_dim_tensor_contiguous_f32(vals, &meta, dim)
        } else {
            ft_kernel_cpu::argmin_dim_tensor_contiguous_f32(vals, &meta, dim)
        }
        .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?;
        let mut out_shape = meta.shape().to_vec();
        out_shape.remove(dim);
        if out_shape.is_empty() {
            out_shape.push(1);
        }
        let values: Vec<f64> = idx_f32.iter().map(|&v| f64::from(v)).collect();
        Ok(Some((values, out_shape)))
    }

    pub fn tensor_max_dim(
        &mut self,
        input: TensorNodeId,
        dim: usize,
    ) -> Result<(TensorNodeId, TensorNodeId), AutogradError> {
        if let Some((vals, idx, out_shape)) = self.extremum_dim_f32_fast(input, dim, true)? {
            let v = self.tensor_variable_f32(vals, out_shape.clone(), false)?;
            let i = self.tensor_variable(idx, out_shape, false)?;
            return Ok((v, i));
        }
        if let Some((vals, idx, out_shape)) = self.extremum_dim_f64_fast(input, dim, true)? {
            let v = self.tensor_variable(vals, out_shape.clone(), false)?;
            let i = self.tensor_variable(idx, out_shape, false)?;
            return Ok((v, i));
        }
        self.tensor_tape.max_dim(input, dim)
    }

    pub fn tensor_min_dim(
        &mut self,
        input: TensorNodeId,
        dim: usize,
    ) -> Result<(TensorNodeId, TensorNodeId), AutogradError> {
        if let Some((vals, idx, out_shape)) = self.extremum_dim_f32_fast(input, dim, false)? {
            let v = self.tensor_variable_f32(vals, out_shape.clone(), false)?;
            let i = self.tensor_variable(idx, out_shape, false)?;
            return Ok((v, i));
        }
        if let Some((vals, idx, out_shape)) = self.extremum_dim_f64_fast(input, dim, false)? {
            let v = self.tensor_variable(vals, out_shape.clone(), false)?;
            let i = self.tensor_variable(idx, out_shape, false)?;
            return Ok((v, i));
        }
        self.tensor_tape.min_dim(input, dim)
    }

    /// Native f32 (value, index) fast path for max_dim/min_dim — the tape upcasts f32->f64
    /// (128MB clone) before the f64 kernel, like argmax. The value comes from the native f32
    /// extremum kernel (the extremum is one input element, so f32-native == f64-upcast-narrowed,
    /// BIT-EXACT) and the index from the native f32 argmax/argmin kernel (f32->f64
    /// order-preserving so the index matches the tape's f64 kernel; tie/NaN rules verified vs
    /// torch). Indices widened f32->f64 to match the tape's F64 index output, values stay F32
    /// (torch.max(f32) -> f32). No-grad contiguous f32 only (grad falls to the tape's backward).
    fn extremum_dim_f32_fast(
        &mut self,
        input: TensorNodeId,
        dim: usize,
        is_max: bool,
    ) -> Result<Option<(Vec<f32>, Vec<f64>, Vec<usize>)>, AutogradError> {
        if self.tensor_requires_grad(input)? || self.tensor_dtype(input)? != DType::F32 {
            return Ok(None);
        }
        let t = self.tensor_tape.tensor(input)?;
        if !t.meta().is_contiguous() {
            return Ok(None);
        }
        let meta = t.meta().clone();
        let vals = t.contiguous_values_f32()?;
        // ONE pass returns both value and index (vs a separate extremum + argmax = 2 scans).
        let (values, idx_f32) = if is_max {
            ft_kernel_cpu::max_dim_values_indices_contiguous_f32(vals, &meta, dim)
        } else {
            ft_kernel_cpu::min_dim_values_indices_contiguous_f32(vals, &meta, dim)
        }
        .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?;
        let mut out_shape = meta.shape().to_vec();
        out_shape.remove(dim);
        if out_shape.is_empty() {
            out_shape.push(1);
        }
        let indices: Vec<f64> = idx_f32.iter().map(|&v| f64::from(v)).collect();
        Ok(Some((values, indices, out_shape)))
    }

    /// Native f64 max/min-dim (values + indices) fast path: the tape's max_dim/min_dim CLONES the
    /// input via `contiguous_values_as_f64()` (F64-branch `.to_vec()`) before the SAME kernel.
    /// Borrow the contiguous f64 buffer + the identical `{max,min}_dim_tensor_contiguous_f64` kernel
    /// (ONE pass returns both value and index) = bit-exact. No-grad only (the values output is
    /// differentiable via the argmax-routed gradient — grad falls through to the tape).
    fn extremum_dim_f64_fast(
        &mut self,
        input: TensorNodeId,
        dim: usize,
        is_max: bool,
    ) -> Result<Option<(Vec<f64>, Vec<f64>, Vec<usize>)>, AutogradError> {
        if self.tensor_requires_grad(input)? || self.tensor_dtype(input)? != DType::F64 {
            return Ok(None);
        }
        let t = self.tensor_tape.tensor(input)?;
        if !t.meta().is_contiguous() {
            return Ok(None);
        }
        let meta = t.meta().clone();
        let vals = t.contiguous_values()?;
        let (values, indices) = if is_max {
            ft_kernel_cpu::max_dim_tensor_contiguous_f64(vals, &meta, dim)
        } else {
            ft_kernel_cpu::min_dim_tensor_contiguous_f64(vals, &meta, dim)
        }
        .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?;
        let mut out_shape = meta.shape().to_vec();
        out_shape.remove(dim);
        if out_shape.is_empty() {
            out_shape.push(1);
        }
        Ok(Some((values, indices, out_shape)))
    }

    /// Reduce along `dim` returning only the maximum values (no indices).
    ///
    /// Equivalent to `torch.amax(input, dim)`. Wraps `tensor_max_dim`
    /// and discards the index tensor — the values output keeps the
    /// argmax-routed gradient. Tracked under frankentorch-wehk.
    pub fn tensor_amax(
        &mut self,
        input: TensorNodeId,
        dim: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_amax_amin_split(input, dim, true)
    }

    /// `amax`/`amin` reduction along `dim` with torch's tie-splitting backward:
    /// when several elements share the extremum, the upstream gradient is divided
    /// EQUALLY among them. max_dim/min_dim instead route the whole gradient to the
    /// single argmax — correct for `torch.max(dim)` (which returns indices) but
    /// NOT for `torch.amax`/`amin`, which split (verified vs torch 2.12,
    /// frankentorch-cwyr sibling). Forward preserves the input dtype (the extremum
    /// is one of the inputs, so the f64->dtype cast is exact).
    fn tensor_amax_amin_split(
        &mut self,
        input: TensorNodeId,
        dim: usize,
        is_max: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        let in_shape = self.tensor_shape(input)?;
        let ndim = in_shape.len();
        if dim >= ndim {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::InvalidDimension { dim, ndim },
            )));
        }
        if in_shape[dim] == 0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "amax/amin: reduction dim must have non-zero size",
                },
            )));
        }
        let input_dtype = self.tensor_tape.dtype(input)?;
        let requires_grad =
            self.tensor_tape.tensor_requires_grad(input)? && self.tensor_tape.is_grad_enabled();
        if !requires_grad && input_dtype == DType::F64 {
            let (out_meta, out_values) = {
                let tensor = self.tensor_tape.tensor(input)?;
                let meta = tensor.meta().clone();
                let values = match tensor.typed_storage() {
                    TensorStorage::F64(values) => values.as_slice(),
                    TensorStorage::F64Inline4(values) => values.as_slice(),
                    _ => unreachable!("dtype checked as f64"),
                };
                let out_values =
                    ft_kernel_cpu::extremum_dim_values_contiguous_f64(values, &meta, dim, is_max)
                        .map_err(|err| {
                        AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(err))
                    })?;
                let mut out_shape = meta.shape().to_vec();
                out_shape.remove(dim);
                (
                    TensorMeta::from_shape(out_shape, DType::F64, meta.device()),
                    out_values,
                )
            };
            let output = DenseTensor::from_storage(out_meta, out_values)?;
            return Ok(self.tensor_variable_from_storage(output, false));
        }
        // No-grad f32 fast path: the upcast (f32->f64 clone) + apply_function SERIAL
        // scalar triple loop measured ~122x SLOWER than torch (97ms vs 0.8ms on a
        // [4000,4000] amax). Route contiguous f32 straight to the native f32 SIMD+
        // parallel extremum kernel. The extremum is one input element so f32-native
        // == f64-upcast-then-round (bit-exact); strided f32 falls through to the
        // unchanged upcast path. frankentorch-kgs4.168.
        if !requires_grad && input_dtype == DType::F32 {
            let built = {
                let tensor = self.tensor_tape.tensor(input)?;
                let meta = tensor.meta().clone();
                if meta.is_contiguous() {
                    let values = match tensor.typed_storage() {
                        TensorStorage::F32(values) => values.as_slice(),
                        _ => unreachable!("dtype checked as f32"),
                    };
                    let out_values = ft_kernel_cpu::extremum_dim_values_contiguous_f32(
                        values, &meta, dim, is_max,
                    )
                    .map_err(|err| {
                        AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(err))
                    })?;
                    Some(out_values)
                } else {
                    None
                }
            };
            if let Some(out_values) = built {
                let mut out_shape = in_shape.clone();
                out_shape.remove(dim);
                return self.tensor_variable_f32(out_values, out_shape, false);
            }
        }
        // apply_function operates on f64 inputs; upcast non-f64 first (the
        // f32/half -> f64 cast is exact and differentiable, so the split gradient
        // still flows back to the original input).
        let f64_input = if input_dtype == DType::F64 {
            input
        } else {
            self.tensor_to_dtype(input, DType::F64)?
        };
        let dim_c = dim;
        let result = self.tensor_apply_function_f64_borrowed_inputs(
            &[f64_input],
            move |_ctx, ins| {
                let (vals, shape) = ins[0];
                let dsz = shape[dim_c];
                let outer: usize = shape[..dim_c].iter().product();
                let inner: usize = shape[dim_c + 1..].iter().product();
                let mut out = vec![0.0_f64; outer * inner];
                for o in 0..outer {
                    for i in 0..inner {
                        let base = o * dsz * inner + i;
                        let mut best = vals[base];
                        for r in 1..dsz {
                            let v = vals[base + r * inner];
                            // NaN propagates (torch parity); once best is NaN it
                            // stays NaN since `v > NaN` / `v < NaN` are false.
                            if v.is_nan() || (is_max && v > best) || (!is_max && v < best) {
                                best = v;
                            }
                        }
                        out[o * inner + i] = best;
                    }
                }
                let mut out_shape: Vec<usize> = shape.to_vec();
                out_shape.remove(dim_c);
                Ok((out, out_shape))
            },
            move |_ctx, grads, ins| {
                let g = grads[0];
                let (vals, shape) = ins[0];
                let dsz = shape[dim_c];
                let outer: usize = shape[..dim_c].iter().product();
                let inner: usize = shape[dim_c + 1..].iter().product();
                let mut grad_in = vec![0.0_f64; vals.len()];
                for o in 0..outer {
                    for i in 0..inner {
                        let base = o * dsz * inner + i;
                        let mut best = vals[base];
                        for r in 1..dsz {
                            let v = vals[base + r * inner];
                            if v.is_nan() || (is_max && v > best) || (!is_max && v < best) {
                                best = v;
                            }
                        }
                        let mut count = 0usize;
                        for r in 0..dsz {
                            if vals[base + r * inner] == best {
                                count += 1;
                            }
                        }
                        if count == 0 {
                            continue;
                        }
                        #[allow(clippy::cast_precision_loss)]
                        let share = g[o * inner + i] / count as f64;
                        for r in 0..dsz {
                            let idx = base + r * inner;
                            if vals[idx] == best {
                                grad_in[idx] = share;
                            }
                        }
                    }
                }
                Ok(vec![Some(grad_in)])
            },
        )?;
        // apply_function yields F64; restore the input's dtype (exact — the
        // extremum is one of the inputs).
        match input_dtype {
            DType::F64 => Ok(result),
            dt => self.tensor_to_dtype(result, dt),
        }
    }

    /// Reduce along `dim` returning only the minimum values (no indices).
    ///
    /// Equivalent to `torch.amin(input, dim)`. Sister to `tensor_amax`.
    /// Tracked under frankentorch-wehk.
    pub fn tensor_amin(
        &mut self,
        input: TensorNodeId,
        dim: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_amax_amin_split(input, dim, false)
    }

    fn validate_index_tensor_values(
        input_shape: &[usize],
        dim: usize,
        index_values: &[f64],
    ) -> Result<(), AutogradError> {
        let Some(&dim_size) = input_shape.get(dim) else {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "index operation dimension out of bounds",
                },
            )));
        };

        let dim_size_i = isize::try_from(dim_size).map_err(|_| {
            AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "index operation dimension is out of range for platform isize",
                },
            ))
        })?;
        // Validate every index value is a finite integer in [-dim_size, dim_size). This is a
        // pure per-element check over the (often multi-million-element) index tensor, so for
        // large tensors fan it out across the rayon pool; `try_for_each` still surfaces the
        // first violation (any error short-circuits). frankentorch-idxvalpar.
        let check = |&idx: &f64| -> Result<(), AutogradError> {
            let idx_i = Self::exact_integer_index_to_isize(
                idx,
                "index tensors must contain finite integer values",
            )?;
            if idx_i < -dim_size_i || idx_i >= dim_size_i {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "index tensor value out of bounds for input dimension",
                    },
                )));
            }
            Ok(())
        };
        if index_values.len() >= PARALLEL_ELEMENTWISE_MIN {
            use rayon::prelude::*;
            index_values.par_iter().try_for_each(check)?;
        } else {
            index_values.iter().try_for_each(check)?;
        }

        Ok(())
    }

    fn stft_window_values(
        &self,
        window: Option<TensorNodeId>,
        win_length: usize,
    ) -> Result<Vec<f64>, AutogradError> {
        match window {
            Some(window_node) => {
                if self.tensor_tape.tensor_requires_grad(window_node)? {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "stft/istft: autograd for window tensors is not supported",
                        },
                    )));
                }
                let window_tensor = self.tensor_tape.tensor(window_node)?;
                if window_tensor.meta().shape() != [win_length] {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "stft/istft: window must be 1-D with length win_length",
                        },
                    )));
                }
                match window_tensor.typed_storage() {
                    TensorStorage::F32(values) => {
                        Ok(values.iter().map(|&v| f64::from(v)).collect::<Vec<_>>())
                    }
                    TensorStorage::F64(values) => Ok(values.as_ref().clone()),
                    TensorStorage::F64Inline4(values) => Ok(values.to_vec()),
                    _ => Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "stft/istft: window must be float32 or float64",
                        },
                    ))),
                }
            }
            None => Ok(vec![1.0; win_length]),
        }
    }

    fn affine_grid_axis_coordinate(index: usize, size: usize, align_corners: bool) -> f64 {
        if size <= 1 {
            0.0
        } else if align_corners {
            -1.0 + 2.0 * index as f64 / (size - 1) as f64
        } else {
            -1.0 + (2.0 * index as f64 + 1.0) / size as f64
        }
    }

    fn grid_sampler_unnormalize(coord: f64, size: usize, align_corners: bool) -> f64 {
        if align_corners {
            ((coord + 1.0) * (size.saturating_sub(1)) as f64) / 2.0
        } else {
            ((coord + 1.0) * size as f64 - 1.0) / 2.0
        }
    }

    fn grid_sampler_reflect(coord: f64, size: usize, align_corners: bool) -> f64 {
        Self::grid_sampler_reflect_with_grad(coord, size, align_corners).0
    }

    fn grid_sampler_reflect_with_grad(coord: f64, size: usize, align_corners: bool) -> (f64, f64) {
        if size <= 1 {
            return (0.0, 0.0);
        }
        let (low, high) = if align_corners {
            (0.0, (size - 1) as f64)
        } else {
            (-0.5, size as f64 - 0.5)
        };
        let span = high - low;
        if span == 0.0 {
            return (0.0, 0.0);
        }
        let shifted = coord - low;
        let sign = if shifted < 0.0 { -1.0 } else { 1.0 };
        let shifted_abs = shifted.abs();
        let extra = shifted_abs % span;
        let flips = (shifted_abs / span).floor();
        let (reflected, reflect_grad) = if flips % 2.0 == 0.0 {
            (low + extra, sign)
        } else {
            (low + span - extra, -sign)
        };
        let upper = (size - 1) as f64;
        let clipped = reflected.clamp(0.0, upper);
        let clip_grad = if reflected <= 0.0 || reflected >= upper {
            0.0
        } else {
            1.0
        };
        (clipped, reflect_grad * clip_grad)
    }

    fn grid_sample_reflect_coordinate_derivative(
        raw_coord: f64,
        size: usize,
        align_corners: bool,
    ) -> f64 {
        let base = if align_corners {
            size.saturating_sub(1) as f64 / 2.0
        } else {
            size as f64 / 2.0
        };
        let (_, reflect_grad) =
            Self::grid_sampler_reflect_with_grad(raw_coord, size, align_corners);
        base * reflect_grad
    }

    fn grid_sample_f64<T>(input: &[T], grid: &[f64], plan: GridSamplePlan) -> Vec<f64>
    where
        T: Copy + Sync,
        f64: From<T>,
    {
        // Generic over the input element type so the f32 path can gather f32 DIRECTLY (half the
        // bytes + no whole-input f32->f64 conversion pass) — the bilinear gather is cache-miss
        // bound, so reading f32 storage instead of an f64 copy is the lever. Math stays f64
        // (`f64::from(input[idx])` is exact for f32), so the result is bit-identical to the prior
        // "convert input to f64, then grid_sample_f64" path. frankentorch-specf32.
        let mut output = vec![0.0; plan.batch * plan.channels * plan.out_h * plan.out_w];
        let plane = plan.out_h * plan.out_w;
        if plane == 0 || plan.channels == 0 {
            return output;
        }

        let sample_value = |n: usize, c: usize, y: isize, x: isize| -> f64 {
            if y < 0 || y >= plan.in_h as isize || x < 0 || x >= plan.in_w as isize {
                0.0
            } else {
                let idx =
                    ((n * plan.channels + c) * plan.in_h + y as usize) * plan.in_w + x as usize;
                f64::from(input[idx])
            }
        };

        // grid_sample is per-output-position independent and the gather (4 reads +
        // interp PER CHANNEL) dominates the per-(n,h,w) coordinate math. Resolve
        // the source coordinate (ix, iy) once per (n,h,w) in PASS 1, then PASS 2
        // distributes the [out_h*out_w] (n,c) output planes across the rayon pool
        // and gathers. Both passes use identical float ops to the original single
        // loop, so the output is bit-for-bit identical. (A prior row-parallel
        // attempt got only ~1.3x; resolving coords once + parallelising over the
        // C·N planes makes it compute-bound: 9.3x on a 1M-element grid_sample.)
        let positions = plan.batch * plane;
        let mut coords = vec![(0.0_f64, 0.0_f64); positions];
        let resolve = |idx: usize, slot: &mut (f64, f64)| {
            let grid_base = idx * 2;
            let mut x = grid[grid_base];
            let mut y = grid[grid_base + 1];
            if x.is_nan() {
                x = -1.0;
            }
            if y.is_nan() {
                y = -1.0;
            }
            let mut ix = Self::grid_sampler_unnormalize(x, plan.in_w, plan.align_corners);
            let mut iy = Self::grid_sampler_unnormalize(y, plan.in_h, plan.align_corners);
            match plan.padding_mode {
                GridSamplePaddingMode::Zeros => {}
                GridSamplePaddingMode::Border => {
                    ix = ix.clamp(0.0, (plan.in_w.saturating_sub(1)) as f64);
                    iy = iy.clamp(0.0, (plan.in_h.saturating_sub(1)) as f64);
                }
                GridSamplePaddingMode::Reflection => {
                    ix = Self::grid_sampler_reflect(ix, plan.in_w, plan.align_corners);
                    iy = Self::grid_sampler_reflect(iy, plan.in_h, plan.align_corners);
                }
            }
            *slot = (ix, iy);
        };
        let gather = |ix: f64, iy: f64, n: usize, c: usize| -> f64 {
            match plan.mode {
                GridSampleMode::Nearest => {
                    // torch's grid_sampler nearest uses std::nearbyint (round half
                    // to EVEN), not round-half-away — they differ at exactly-half
                    // pixel coords and pick a different source pixel. frankentorch-n4bi2.
                    let nearest_x = ix.round_ties_even() as isize;
                    let nearest_y = iy.round_ties_even() as isize;
                    match plan.padding_mode {
                        GridSamplePaddingMode::Zeros => sample_value(n, c, nearest_y, nearest_x),
                        GridSamplePaddingMode::Border | GridSamplePaddingMode::Reflection => {
                            sample_value(
                                n,
                                c,
                                nearest_y.clamp(0, plan.in_h as isize - 1),
                                nearest_x.clamp(0, plan.in_w as isize - 1),
                            )
                        }
                    }
                }
                GridSampleMode::Bilinear => {
                    let x0 = ix.floor();
                    let y0 = iy.floor();
                    let x1 = x0 + 1.0;
                    let y1 = y0 + 1.0;
                    let wx1 = ix - x0;
                    let wy1 = iy - y0;
                    let wx0 = 1.0 - wx1;
                    let wy0 = 1.0 - wy1;
                    let v00 = sample_value(n, c, y0 as isize, x0 as isize);
                    let v01 = sample_value(n, c, y0 as isize, x1 as isize);
                    let v10 = sample_value(n, c, y1 as isize, x0 as isize);
                    let v11 = sample_value(n, c, y1 as isize, x1 as isize);
                    v00 * wx0 * wy0 + v01 * wx1 * wy0 + v10 * wx0 * wy1 + v11 * wx1 * wy1
                }
            }
        };
        const GRID_SAMPLE_PARALLEL_NUMEL: usize = 1 << 15;
        let parallel =
            output.len() >= GRID_SAMPLE_PARALLEL_NUMEL && plan.batch * plan.channels >= 2;

        // Pass 1: resolve (ix, iy) per (n, h, w).
        if parallel {
            use rayon::prelude::*;
            coords
                .par_iter_mut()
                .enumerate()
                .for_each(|(idx, slot)| resolve(idx, slot));
        } else {
            coords
                .iter_mut()
                .enumerate()
                .for_each(|(idx, slot)| resolve(idx, slot));
        }

        // Pass 2: gather over (n, c) output planes (coords now read-only).
        let process_plane = |nc: usize, out_plane: &mut [f64]| {
            let n = nc / plan.channels;
            let c = nc % plan.channels;
            let coord_base = n * plane;
            for (p, slot) in out_plane.iter_mut().enumerate() {
                let (ix, iy) = coords[coord_base + p];
                *slot = gather(ix, iy, n, c);
            }
        };
        if parallel {
            use rayon::prelude::*;
            output
                .par_chunks_mut(plane)
                .enumerate()
                .for_each(|(nc, out_plane)| process_plane(nc, out_plane));
        } else {
            output
                .chunks_mut(plane)
                .enumerate()
                .for_each(|(nc, out_plane)| process_plane(nc, out_plane));
        }

        output
    }

    fn grid_sample_add_input_grad(
        grad_input: &mut [f64],
        plan: GridSamplePlan,
        point: GridSamplePoint,
        value: f64,
    ) {
        if point.y < 0
            || point.y >= plan.in_h as isize
            || point.x < 0
            || point.x >= plan.in_w as isize
        {
            return;
        }
        let idx = ((point.n * plan.channels + point.c) * plan.in_h + point.y as usize) * plan.in_w
            + point.x as usize;
        grad_input[idx] += value;
    }

    fn grid_sample_coordinate_derivative(
        raw_coord: f64,
        size: usize,
        align_corners: bool,
        padding_mode: GridSamplePaddingMode,
    ) -> f64 {
        let base = if align_corners {
            size.saturating_sub(1) as f64 / 2.0
        } else {
            size as f64 / 2.0
        };
        match padding_mode {
            GridSamplePaddingMode::Zeros => base,
            GridSamplePaddingMode::Border => {
                let upper = size.saturating_sub(1) as f64;
                if raw_coord <= 0.0 || raw_coord >= upper {
                    0.0
                } else {
                    base
                }
            }
            GridSamplePaddingMode::Reflection => {
                Self::grid_sample_reflect_coordinate_derivative(raw_coord, size, align_corners)
            }
        }
    }

    fn grid_sample_bilinear_backward_f64(
        input: &[f64],
        grid: &[f64],
        grad_output: &[f64],
        plan: GridSamplePlan,
    ) -> Result<(Vec<f64>, Vec<f64>), AutogradError> {
        let expected_out = plan.batch * plan.channels * plan.out_h * plan.out_w;
        if grad_output.len() != expected_out {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "grid_sample backward: incoming gradient shape mismatch",
                },
            )));
        }

        let mut grad_input = vec![0.0; input.len()];
        let mut grad_grid = vec![0.0; grid.len()];
        let sample_value = |n: usize, c: usize, y: isize, x: isize| -> f64 {
            if y < 0 || y >= plan.in_h as isize || x < 0 || x >= plan.in_w as isize {
                0.0
            } else {
                let idx =
                    ((n * plan.channels + c) * plan.in_h + y as usize) * plan.in_w + x as usize;
                input[idx]
            }
        };

        // grad_input[n] and grad_grid[n] are DISJOINT per batch (the scatter-add
        // conflicts are only WITHIN a batch's (h,w) positions), so fan the batch
        // across rayon — the per-(n,h,w) coordinate math + per-channel bilinear
        // scatter/derivative is compute-heavy. Each closure writes only its own
        // gi_n/gg_n slice; input/grid/grad_output reads stay global (immutable).
        // Bit-identical: within a batch the (h,w,c) accumulation order is unchanged
        // and batches are disjoint. frankentorch-gridsample-backward-par.
        let plane_in = plan.channels * plan.in_h * plan.in_w;
        let plane_grid = plan.out_h * plan.out_w * 2;
        let process = |n: usize, gi_n: &mut [f64], gg_n: &mut [f64]| {
            for h in 0..plan.out_h {
                for w in 0..plan.out_w {
                    let grid_base = ((n * plan.out_h + h) * plan.out_w + w) * 2;
                    let grid_local = (h * plan.out_w + w) * 2;
                    let mut x = grid[grid_base];
                    let mut y = grid[grid_base + 1];
                    if x.is_nan() {
                        x = -1.0;
                    }
                    if y.is_nan() {
                        y = -1.0;
                    }

                    let raw_ix = Self::grid_sampler_unnormalize(x, plan.in_w, plan.align_corners);
                    let raw_iy = Self::grid_sampler_unnormalize(y, plan.in_h, plan.align_corners);
                    let (ix, iy) = match plan.padding_mode {
                        GridSamplePaddingMode::Zeros => (raw_ix, raw_iy),
                        GridSamplePaddingMode::Border => (
                            raw_ix.clamp(0.0, (plan.in_w.saturating_sub(1)) as f64),
                            raw_iy.clamp(0.0, (plan.in_h.saturating_sub(1)) as f64),
                        ),
                        GridSamplePaddingMode::Reflection => (
                            Self::grid_sampler_reflect(raw_ix, plan.in_w, plan.align_corners),
                            Self::grid_sampler_reflect(raw_iy, plan.in_h, plan.align_corners),
                        ),
                    };

                    let x0 = ix.floor();
                    let y0 = iy.floor();
                    let x1 = x0 + 1.0;
                    let y1 = y0 + 1.0;
                    let wx1 = ix - x0;
                    let wy1 = iy - y0;
                    let wx0 = 1.0 - wx1;
                    let wy0 = 1.0 - wy1;
                    let x0i = x0 as isize;
                    let x1i = x1 as isize;
                    let y0i = y0 as isize;
                    let y1i = y1 as isize;

                    let dix_dgrid = Self::grid_sample_coordinate_derivative(
                        raw_ix,
                        plan.in_w,
                        plan.align_corners,
                        plan.padding_mode,
                    );
                    let diy_dgrid = Self::grid_sample_coordinate_derivative(
                        raw_iy,
                        plan.in_h,
                        plan.align_corners,
                        plan.padding_mode,
                    );

                    let mut grad_x = 0.0;
                    let mut grad_y = 0.0;
                    for c in 0..plan.channels {
                        let out_idx = ((n * plan.channels + c) * plan.out_h + h) * plan.out_w + w;
                        let go = grad_output[out_idx];
                        // n: 0 -> index into the per-batch gi_n slice (no n offset).
                        Self::grid_sample_add_input_grad(
                            gi_n,
                            plan,
                            GridSamplePoint {
                                n: 0,
                                c,
                                y: y0i,
                                x: x0i,
                            },
                            go * wx0 * wy0,
                        );
                        Self::grid_sample_add_input_grad(
                            gi_n,
                            plan,
                            GridSamplePoint {
                                n: 0,
                                c,
                                y: y0i,
                                x: x1i,
                            },
                            go * wx1 * wy0,
                        );
                        Self::grid_sample_add_input_grad(
                            gi_n,
                            plan,
                            GridSamplePoint {
                                n: 0,
                                c,
                                y: y1i,
                                x: x0i,
                            },
                            go * wx0 * wy1,
                        );
                        Self::grid_sample_add_input_grad(
                            gi_n,
                            plan,
                            GridSamplePoint {
                                n: 0,
                                c,
                                y: y1i,
                                x: x1i,
                            },
                            go * wx1 * wy1,
                        );

                        let v00 = sample_value(n, c, y0i, x0i);
                        let v01 = sample_value(n, c, y0i, x1i);
                        let v10 = sample_value(n, c, y1i, x0i);
                        let v11 = sample_value(n, c, y1i, x1i);
                        grad_x += go * ((v01 - v00) * wy0 + (v11 - v10) * wy1) * dix_dgrid;
                        grad_y += go * ((v10 - v00) * wx0 + (v11 - v01) * wx1) * diy_dgrid;
                    }
                    gg_n[grid_local] += grad_x;
                    gg_n[grid_local + 1] += grad_y;
                }
            }
        };
        // FT_GRIDSAMPLE_SERIAL forces the serial path (A/B lever; negligible one-shot
        // env read per backward, not per element).
        if plan.batch >= 2
            && plan.batch * plan.out_h * plan.out_w * plan.channels >= 4096
            && std::env::var_os("FT_GRIDSAMPLE_SERIAL").is_none()
        {
            use rayon::prelude::*;
            grad_input
                .par_chunks_mut(plane_in)
                .zip(grad_grid.par_chunks_mut(plane_grid))
                .enumerate()
                .for_each(|(n, (gi_n, gg_n))| process(n, gi_n, gg_n));
        } else {
            grad_input
                .chunks_mut(plane_in)
                .zip(grad_grid.chunks_mut(plane_grid))
                .enumerate()
                .for_each(|(n, (gi_n, gg_n))| process(n, gi_n, gg_n));
        }

        Ok((grad_input, grad_grid))
    }

    fn grid_sample_nearest_backward_f64(
        input: &[f64],
        grid: &[f64],
        grad_output: &[f64],
        plan: GridSamplePlan,
    ) -> Result<(Vec<f64>, Vec<f64>), AutogradError> {
        let expected_out = plan.batch * plan.channels * plan.out_h * plan.out_w;
        if grad_output.len() != expected_out {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "grid_sample nearest backward: incoming gradient shape mismatch",
                },
            )));
        }

        let mut grad_input = vec![0.0; input.len()];
        // Nearest has ZERO coordinate gradient, so grad_grid stays all-zeros; only the
        // grad_input scatter needs work. grad_input[n] is DISJOINT per batch (same as the
        // bilinear backward), so fan the batch across rayon — each task owns its gi_n slice
        // (scatter uses GridSamplePoint{n:0,..} = local index); grid/grad_output reads stay
        // global. Bit-identical (within-batch scatter order unchanged, batches disjoint).
        // frankentorch-gridsample-backward-par.
        let grad_grid = vec![0.0; grid.len()];
        let plane_in = plan.channels * plan.in_h * plan.in_w;
        let process = |n: usize, gi_n: &mut [f64]| {
            for h in 0..plan.out_h {
                for w in 0..plan.out_w {
                    let grid_base = ((n * plan.out_h + h) * plan.out_w + w) * 2;
                    let mut x = grid[grid_base];
                    let mut y = grid[grid_base + 1];
                    if x.is_nan() {
                        x = -1.0;
                    }
                    if y.is_nan() {
                        y = -1.0;
                    }

                    let mut ix = Self::grid_sampler_unnormalize(x, plan.in_w, plan.align_corners);
                    let mut iy = Self::grid_sampler_unnormalize(y, plan.in_h, plan.align_corners);
                    match plan.padding_mode {
                        GridSamplePaddingMode::Zeros => {}
                        GridSamplePaddingMode::Border => {
                            ix = ix.clamp(0.0, (plan.in_w.saturating_sub(1)) as f64);
                            iy = iy.clamp(0.0, (plan.in_h.saturating_sub(1)) as f64);
                        }
                        GridSamplePaddingMode::Reflection => {
                            ix = Self::grid_sampler_reflect(ix, plan.in_w, plan.align_corners);
                            iy = Self::grid_sampler_reflect(iy, plan.in_h, plan.align_corners);
                        }
                    }

                    // Match the forward's round-half-to-even (frankentorch-n4bi2)
                    // so the gradient scatters to the same source pixel.
                    let mut nearest_x = ix.round_ties_even() as isize;
                    let mut nearest_y = iy.round_ties_even() as isize;
                    if matches!(
                        plan.padding_mode,
                        GridSamplePaddingMode::Border | GridSamplePaddingMode::Reflection
                    ) {
                        nearest_x = nearest_x.clamp(0, plan.in_w as isize - 1);
                        nearest_y = nearest_y.clamp(0, plan.in_h as isize - 1);
                    }

                    for c in 0..plan.channels {
                        let out_idx = ((n * plan.channels + c) * plan.out_h + h) * plan.out_w + w;
                        Self::grid_sample_add_input_grad(
                            gi_n,
                            plan,
                            GridSamplePoint {
                                n: 0,
                                c,
                                y: nearest_y,
                                x: nearest_x,
                            },
                            grad_output[out_idx],
                        );
                    }
                }
            }
        };
        if plan.batch >= 2
            && plan.batch * plan.out_h * plan.out_w * plan.channels >= 4096
            && std::env::var_os("FT_GRIDSAMPLE_SERIAL").is_none()
        {
            use rayon::prelude::*;
            grad_input
                .par_chunks_mut(plane_in)
                .enumerate()
                .for_each(|(n, gi_n)| process(n, gi_n));
        } else {
            grad_input
                .chunks_mut(plane_in)
                .enumerate()
                .for_each(|(n, gi_n)| process(n, gi_n));
        }

        Ok((grad_input, grad_grid))
    }

    fn istft_reconstruct_f64(
        &self,
        spectrogram: Vec<ft_core::Complex128>,
        plan: IstftReconstructPlan<'_>,
    ) -> Vec<f64> {
        let output_len = if plan.frames == 0 {
            0
        } else {
            plan.n_fft + plan.hop_length * (plan.frames - 1)
        };
        let mut signal = vec![0.0; output_len];
        let mut envelope = vec![0.0; output_len];
        let scale = if plan.normalized {
            1.0 / (plan.n_fft as f64).sqrt()
        } else {
            1.0 / plan.n_fft as f64
        };
        // Inverse FFT per frame instead of the dense O(n_fft^2) inverse DFT.
        // `dft_inplace_1d_with_stage_twiddles(inverse=true)` already applies the
        // 1/n_fft normalization, so the dense path's `* scale` becomes a single
        // post-multiply `n_fft * scale` (= 1.0 unnormalized, sqrt(n_fft)
        // normalized). Power-of-two n_fft uses the radix-2 FFT; otherwise the
        // routine falls back to the dense DFT, preserving behaviour there.
        let inverse_fft_twiddles = plan
            .n_fft
            .is_power_of_two()
            .then(|| Self::fft_stage_twiddles(plan.n_fft, true));
        let fft_post_scale = plan.n_fft as f64 * scale;

        // Each frame's inverse transform is independent and dominates the cost
        // (direct O(n_fft^2) DFT). Compute every frame's time-domain signal in
        // parallel into a contiguous n_fft block, then
        // overlap-add them SERIALLY in ascending frame order so the accumulation
        // into `signal`/`envelope` (a reduction over overlapping regions) stays
        // bit-for-bit identical to the original interleaved loop.
        let mut frame_times = vec![0.0_f64; plan.frames * plan.n_fft];
        let compute_frame = |frame_idx: usize, ft_slice: &mut [f64]| {
            // Reconstruct the full Hermitian spectrum into re/im buffers.
            let mut re = vec![0.0_f64; plan.n_fft];
            let mut im = vec![0.0_f64; plan.n_fft];
            if plan.onesided {
                for k in 0..plan.freq_bins {
                    let c = spectrogram[k * plan.frames + frame_idx];
                    re[k] = c.re;
                    im[k] = c.im;
                }
                let upper = if plan.n_fft.is_multiple_of(2) {
                    plan.freq_bins.saturating_sub(1)
                } else {
                    plan.freq_bins
                };
                for k in 1..upper {
                    // full_spectrum[n_fft - k] = full_spectrum[k].conj()
                    re[plan.n_fft - k] = re[k];
                    im[plan.n_fft - k] = -im[k];
                }
            } else {
                for k in 0..plan.n_fft {
                    let c = spectrogram[k * plan.frames + frame_idx];
                    re[k] = c.re;
                    im[k] = c.im;
                }
            }
            Self::dft_inplace_1d_with_stage_twiddles(
                &mut re,
                &mut im,
                true,
                inverse_fft_twiddles.as_deref(),
            );
            for (n, sample) in ft_slice.iter_mut().enumerate() {
                *sample = re[n] * fft_post_scale;
            }
        };
        if plan.frames >= 2 && plan.frames * plan.n_fft >= PARALLEL_ELEMENTWISE_MIN {
            use rayon::prelude::*;
            frame_times
                .par_chunks_mut(plan.n_fft)
                .enumerate()
                .for_each(|(frame_idx, ft_slice)| compute_frame(frame_idx, ft_slice));
        } else {
            frame_times
                .chunks_mut(plan.n_fft)
                .enumerate()
                .for_each(|(frame_idx, ft_slice)| compute_frame(frame_idx, ft_slice));
        }

        for frame_idx in 0..plan.frames {
            let start = frame_idx * plan.hop_length;
            let frame_time = &frame_times[frame_idx * plan.n_fft..(frame_idx + 1) * plan.n_fft];
            for i in 0..plan.window_values.len() {
                let sample = frame_time[plan.window_pad + i] * plan.window_values[i];
                signal[start + i] += sample;
                envelope[start + i] += plan.window_values[i] * plan.window_values[i];
            }
        }

        for (sample, norm) in signal.iter_mut().zip(envelope.iter()) {
            if *norm > 1e-12 {
                *sample /= *norm;
            }
        }

        let mut trimmed = if plan.center {
            let pad = plan.n_fft / 2;
            if signal.len() >= 2 * pad {
                signal[pad..signal.len() - pad].to_vec()
            } else {
                Vec::new()
            }
        } else {
            signal
        };

        if let Some(target_len) = plan.length {
            match trimmed.len().cmp(&target_len) {
                std::cmp::Ordering::Greater => trimmed.truncate(target_len),
                std::cmp::Ordering::Less => trimmed.resize(target_len, 0.0),
                std::cmp::Ordering::Equal => {}
            }
        }
        trimmed
    }

    pub fn tensor_index_select(
        &mut self,
        input: TensorNodeId,
        dim: usize,
        indices: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let input_shape = self.tensor_shape(input)?;
        let indices_data = self.tensor_tape.values(indices)?;
        Self::validate_index_tensor_values(&input_shape, dim, &indices_data)?;
        // No-grad fast path: the tape index_select clones the input + runs a per-element
        // division-based unravel + saves for backward. A gather along `dim` is a CONTIGUOUS
        // block copy (`inner` elements) per (outer, picked-index) — out[o,i,k] = in[o,idx[i],k].
        // Borrow the contiguous storage and parallelize over output blocks (one cheap
        // division per BLOCK, not per element). Bit-exact. Non-contiguous / grad fall through.
        if !self.tensor_requires_grad(input)? {
            let n_idx = indices_data.len();
            let mid = input_shape[dim];
            let inner: usize = input_shape[dim + 1..].iter().product();
            let outer: usize = input_shape[..dim].iter().product();
            if inner > 0 && n_idx > 0 {
                let mut out_shape = input_shape.clone();
                out_shape[dim] = n_idx;
                #[allow(clippy::cast_possible_truncation, clippy::cast_sign_loss)]
                let idx_usize: Vec<usize> = indices_data.iter().map(|&v| v as usize).collect();
                let dtype = self.tensor_dtype(input)?;
                let built = {
                    let tensor = self.tensor_tape.tensor(input)?;
                    if tensor.meta().is_contiguous() {
                        use rayon::prelude::*;
                        match dtype {
                            DType::F64 => {
                                let in_data = tensor.contiguous_values()?;
                                let mut out = vec![0.0_f64; outer * n_idx * inner];
                                out.par_chunks_mut(inner)
                                    .enumerate()
                                    .for_each(|(b, chunk)| {
                                        let o = b / n_idx;
                                        let i = b % n_idx;
                                        let src = (o * mid + idx_usize[i]) * inner;
                                        chunk.copy_from_slice(&in_data[src..src + inner]);
                                    });
                                Some(Ok(out))
                            }
                            DType::F32 => {
                                let in_data = tensor.contiguous_values_f32()?;
                                let mut out = vec![0.0_f32; outer * n_idx * inner];
                                out.par_chunks_mut(inner)
                                    .enumerate()
                                    .for_each(|(b, chunk)| {
                                        let o = b / n_idx;
                                        let i = b % n_idx;
                                        let src = (o * mid + idx_usize[i]) * inner;
                                        chunk.copy_from_slice(&in_data[src..src + inner]);
                                    });
                                Some(Err(out))
                            }
                            _ => None,
                        }
                    } else {
                        None
                    }
                };
                match built {
                    Some(Ok(out)) => return self.tensor_variable(out, out_shape, false),
                    Some(Err(out)) => return self.tensor_variable_f32(out, out_shape, false),
                    None => {}
                }
            }
        }
        self.tensor_tape.index_select(input, dim, &indices_data)
    }

    /// Gather elements via flat (row-major) indices, reshaped like indices.
    ///
    /// Equivalent to `torch.take(input, indices)` — i.e.
    /// `input.flatten()[indices].reshape(indices.shape)`. Composes
    /// through tensor_reshape (flatten input + flatten indices) +
    /// tensor_index_select + tensor_reshape (back to indices shape),
    /// so gradients flow back to input via the index_select backward.
    /// Tracked under frankentorch-1qxf.
    pub fn tensor_take(
        &mut self,
        input: TensorNodeId,
        indices: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let input_shape = self.tensor_shape(input)?;
        let indices_shape = self.tensor_shape(indices)?;
        let numel = Self::checked_shape_numel(&input_shape, "take: input shape volume overflow")?;
        let n_idx =
            Self::checked_shape_numel(&indices_shape, "take: indices shape volume overflow")?;

        // Flatten input to [numel] and indices to [n_idx].
        let flat_input = if input_shape == [numel] {
            input
        } else {
            self.tensor_reshape(input, vec![numel])?
        };
        let flat_idx = if indices_shape == [n_idx] {
            indices
        } else {
            self.tensor_reshape(indices, vec![n_idx])?
        };
        let gathered = self.tensor_index_select(flat_input, 0, flat_idx)?;

        // Reshape result back to indices' original shape.
        if indices_shape == [n_idx] {
            Ok(gathered)
        } else {
            self.tensor_reshape(gathered, indices_shape)
        }
    }

    /// Replace elements at flat indices with values.
    ///
    /// Equivalent to `torch.put(input, indices, values)`. Treats input
    /// as flattened and places values at the corresponding flat indices.
    /// Returns a new tensor with the same shape as input.
    ///
    /// Unlike scatter, indices and values are flat (1D). Autograd is not
    /// supported (non-differentiable at replaced positions).
    /// Tracked under frankentorch-y2ui.
    pub fn tensor_put(
        &mut self,
        input: TensorNodeId,
        indices: TensorNodeId,
        values: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let input_shape = self.tensor_shape(input)?;
        let indices_vals = self.tensor_values(indices)?;
        // Don't read `values` as f64 here — `tensor_values`/`tensor_values_len` are F64-only and
        // ERROR on f32 storage (so no-grad f32 `put` crashed). We only need its element count for
        // the length check, so take it from the SHAPE (metadata); each path reads `values` natively.
        let values_len =
            Self::checked_shape_numel(&self.tensor_shape(values)?, "put: values shape overflow")?;

        if indices_vals.len() != values_len {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "put: indices and values must have the same length",
                },
            )));
        }

        let numel = Self::checked_shape_numel(&input_shape, "put: input shape volume overflow")?;

        // Resolve + bounds-check the (non-differentiable) destination indices.
        let mut idx_usize: Vec<usize> = Vec::with_capacity(indices_vals.len());
        for &idx in &indices_vals {
            let i = idx as usize;
            if i >= numel {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "put: index out of bounds",
                    },
                )));
            }
            idx_usize.push(i);
        }

        if self.tensor_requires_grad(input)? || self.tensor_requires_grad(values)? {
            // put overwrites input[idx] = value at each (flat) index, so the
            // gradient splits: grad flows to `input` everywhere except the
            // overwritten slots (zeroed there), and to `values` from the slot each
            // value was written to (grad_values[j] = grad_out[idx[j]] — matching
            // torch's take(grad, index), so duplicate indices each receive the
            // upstream gradient at that position). Forward is identical to the
            // non-grad path → value bit-identical. frankentorch-avfl.
            let idx_fwd = idx_usize.clone();
            return self.tensor_apply_function(
                &[input, values],
                move |_ctx, inputs| {
                    let (in_vals, in_shape) = inputs[0];
                    let (val_vals, _) = inputs[1];
                    let mut result = in_vals.to_vec();
                    for (&i, &v) in idx_fwd.iter().zip(val_vals.iter()) {
                        result[i] = v;
                    }
                    Ok((result, in_shape.to_vec()))
                },
                move |_ctx, grad_outputs| {
                    let g = grad_outputs[0];
                    let mut grad_input = g.to_vec();
                    let mut grad_values = vec![0.0_f64; idx_usize.len()];
                    for (j, &i) in idx_usize.iter().enumerate() {
                        grad_values[j] = g[i];
                    }
                    for &i in &idx_usize {
                        grad_input[i] = 0.0;
                    }
                    Ok(vec![Some(grad_input), Some(grad_values)])
                },
            );
        }

        // No-grad fast path (correctness + dtype): the f64 reads below ERROR on f32 storage, so
        // no-grad f32 `put` (input + values both f32) used to crash. Read at the native f32
        // dtype, do the flat overwrite, and return F32 (torch put_ keeps the input dtype).
        if self.tensor_tape.dtype(input)? == DType::F32 {
            let mut result = self.tensor_tape.values_f32(input)?;
            let values_vals = self.tensor_tape.values_f32(values)?;
            for (&i, &val) in idx_usize.iter().zip(values_vals.iter()) {
                result[i] = val;
            }
            return self.tensor_variable_f32(result, input_shape, false);
        }

        let values_vals = self.tensor_values(values)?;
        // Build the base output by BORROWING input + a PARALLEL copy (the old `tensor_values(input)`
        // is a serial to_vec whose page first-touch is the wall for large numel), then scatter the
        // puts. Bit-identical (puts overwrite the same flat positions). Non-contiguous / non-f64 /
        // small fall back to the serial clone. Mirrors the slice_scatter fix (dc96043a).
        let mut result = {
            let is_f64_contig = self.tensor_dtype(input)? == DType::F64
                && self.tensor_tape.tensor(input)?.meta().is_contiguous();
            if is_f64_contig && numel >= MOVEMENT_COPY_PARALLEL_MIN {
                let in_vals = self.tensor_tape.tensor(input)?.contiguous_values()?;
                let mut out = vec![0.0_f64; numel];
                use rayon::prelude::*;
                out.par_chunks_mut(1 << 16)
                    .zip(in_vals.par_chunks(1 << 16))
                    .for_each(|(o, i)| o.copy_from_slice(i));
                out
            } else {
                self.tensor_values(input)?
            }
        };
        for (&i, &val) in idx_usize.iter().zip(values_vals.iter()) {
            result[i] = val;
        }

        self.tensor_variable(result, input_shape, false)
    }

    /// Put values into a tensor along a specific dimension using indices.
    ///
    /// Equivalent to `numpy.put_along_axis` / PyTorch's `scatter` with
    /// values. For each position in the index tensor, places the
    /// corresponding value from `src` at that index position along `dim`.
    ///
    /// This is the inverse of `take_along_dim`.
    pub fn tensor_put_along_dim(
        &mut self,
        input: TensorNodeId,
        dim: usize,
        indices: TensorNodeId,
        src: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // This is essentially tensor_scatter with specific semantics.
        // Use scatter to implement: out = input.scatter(dim, indices, src)
        self.tensor_scatter(input, dim, indices, src)
    }

    /// Like `tensor_index_select`, but the input's gradient is also
    /// surfaced as a sparse COO tensor on the backward report
    /// (`TensorBackwardReport::sparse_gradient`). Only meaningful for
    /// `dim=0`; other dims fall back to the standard dense gradient.
    pub fn tensor_index_select_sparse(
        &mut self,
        input: TensorNodeId,
        dim: usize,
        indices: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let input_shape = self.tensor_shape(input)?;
        let indices_data = self.tensor_tape.values(indices)?;
        Self::validate_index_tensor_values(&input_shape, dim, &indices_data)?;
        self.tensor_tape
            .index_select_sparse(input, dim, &indices_data)
    }

    pub fn tensor_gather(
        &mut self,
        input: TensorNodeId,
        dim: usize,
        index: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let input_shape = self.tensor_shape(input)?;
        let index_data = self.tensor_tape.values(index)?;
        Self::validate_index_tensor_values(&input_shape, dim, &index_data)?;
        let index_shape = self.tensor_tape.tensor(index)?.meta().shape().to_vec();
        self.tensor_tape
            .gather(input, dim, &index_data, index_shape)
    }

    pub fn tensor_scatter(
        &mut self,
        input: TensorNodeId,
        dim: usize,
        index: TensorNodeId,
        src: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let input_shape = self.tensor_shape(input)?;
        let index_data = self.tensor_tape.values(index)?;
        Self::validate_index_tensor_values(&input_shape, dim, &index_data)?;
        let index_shape = self.tensor_tape.tensor(index)?.meta().shape().to_vec();
        let input_dtype = self.tensor_tape.dtype(input)?;
        let src_dtype = self.tensor_tape.dtype(src)?;
        if src_dtype != input_dtype {
            return Err(AutogradError::Dispatch(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "scatter requires input and src to have matching dtypes",
                }
                .into(),
            ));
        }
        // No-grad fast path (f32/f64): scatter is an OVERWRITE = scatter_reduce reduce="copy".
        // The generic tape path clones the index, UPCASTS f32 src -> f64, and runs the autograd
        // kernel. For the no-grad case write DIRECTLY — borrow src zero-copy (no upcast), read
        // input into result, bucket-parallelize over disjoint output rows; each source assigns
        // its slot in ascending flat order so the LAST writer wins (bit-identical to the tape
        // kernel's flat last-write-wins, and pure movement => exact in any dtype). Requires
        // index shape == input shape except at `dim`; other layouts / half / grad fall through.
        let ndim = input_shape.len();
        let shape_matches = dim < ndim
            && index_shape.len() == ndim
            && (0..ndim).all(|d| d == dim || index_shape[d] == input_shape[d]);
        if !self.tensor_requires_grad(input)?
            && !self.tensor_requires_grad(src)?
            && matches!(input_dtype, DType::F64 | DType::F32)
            && shape_matches
        {
            let inner: usize = input_shape[dim + 1..].iter().product();
            let outer: usize = input_shape[..dim].iter().product();
            let dim_size = input_shape[dim];
            let idx_dim_size = index_shape[dim];
            let parallel = outer >= 2 && index_data.len() >= PARALLEL_ELEMENTWISE_MIN;
            if input_dtype == DType::F64 {
                let mut result = self.tensor_tape.values(input)?;
                let src_owned: Vec<f64>;
                let src_vals: &[f64] = if self.tensor_tape.tensor(src)?.meta().is_contiguous() {
                    self.tensor_tape.tensor(src)?.contiguous_values()?
                } else {
                    src_owned = self.tensor_tape.values(src)?;
                    &src_owned
                };
                Self::scatter_reduce_apply(
                    &mut result,
                    &index_data,
                    src_vals,
                    "copy",
                    outer,
                    idx_dim_size,
                    inner,
                    dim_size,
                    parallel,
                    |_, _| {},
                );
                return self.tensor_variable(result, input_shape, false);
            }
            let mut result = self.tensor_tape.values_f32(input)?;
            let src_owned: Vec<f32>;
            let src_vals: &[f32] = if self.tensor_tape.tensor(src)?.meta().is_contiguous() {
                self.tensor_tape.tensor(src)?.contiguous_values_f32()?
            } else {
                src_owned = self.tensor_tape.values_f32(src)?;
                &src_owned
            };
            Self::scatter_reduce_apply(
                &mut result,
                &index_data,
                src_vals,
                "copy",
                outer,
                idx_dim_size,
                inner,
                dim_size,
                parallel,
                |_, _| {},
            );
            return self.tensor_variable_f32(result, input_shape, false);
        }

        let src_data = match input_dtype {
            DType::F64 => self.tensor_tape.values(src)?,
            DType::F32 => self
                .tensor_tape
                .values_f32(src)?
                .into_iter()
                .map(f64::from)
                .collect(),
            // scatter is pure movement (overwrite, no arithmetic), so reading the
            // half src losslessly as f64 and letting the tape narrow the result
            // back to the input's half dtype is bit-exact (frankentorch-u78p).
            DType::F16 | DType::BF16 => self.tensor_tape.values_lossy_f64(src)?,
            _ => {
                return Err(AutogradError::Dispatch(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "scatter requires f32, f64, f16, or bf16 tensors",
                    }
                    .into(),
                ));
            }
        };
        self.tensor_tape
            .scatter(input, src, dim, &index_data, index_shape, &src_data)
    }

    pub fn tensor_scatter_add(
        &mut self,
        input: TensorNodeId,
        dim: usize,
        index: TensorNodeId,
        src: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let input_shape = self.tensor_shape(input)?;
        let index_data = self.tensor_tape.values(index)?;
        Self::validate_index_tensor_values(&input_shape, dim, &index_data)?;
        let index_shape = self.tensor_tape.tensor(index)?.meta().shape().to_vec();
        let input_dtype = self.tensor_tape.dtype(input)?;
        let src_dtype = self.tensor_tape.dtype(src)?;
        if src_dtype != input_dtype {
            return Err(AutogradError::Dispatch(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "scatter_add requires input and src to have matching dtypes",
                }
                .into(),
            ));
        }
        // No-grad fast path (f32/f64): scatter_add is scatter_reduce with reduce="sum".
        // The generic tape path clones the index, UPCASTS f32 src -> f64, and runs the
        // autograd kernel. For the no-grad case accumulate DIRECTLY — borrow src zero-copy
        // (no upcast), read input into result, bucket-parallelize over disjoint output rows.
        // Sums in flat index order = the tape kernel's order, so bit-identical. Requires
        // index shape == input shape except at `dim` (the FT scatter constraint, enforced for
        // the same-shape case); other layouts / half / grad fall through to the tape op.
        let ndim = input_shape.len();
        let shape_matches = dim < ndim
            && index_shape.len() == ndim
            && (0..ndim).all(|d| d == dim || index_shape[d] == input_shape[d]);
        if !self.tensor_requires_grad(input)?
            && !self.tensor_requires_grad(src)?
            && matches!(input_dtype, DType::F64 | DType::F32)
            && shape_matches
        {
            let inner: usize = input_shape[dim + 1..].iter().product();
            let outer: usize = input_shape[..dim].iter().product();
            let dim_size = input_shape[dim];
            let idx_dim_size = index_shape[dim];
            let parallel = outer >= 2 && index_data.len() >= PARALLEL_ELEMENTWISE_MIN;
            if input_dtype == DType::F64 {
                let mut result = self.tensor_tape.values(input)?;
                let src_owned: Vec<f64>;
                let src_vals: &[f64] = if self.tensor_tape.tensor(src)?.meta().is_contiguous() {
                    self.tensor_tape.tensor(src)?.contiguous_values()?
                } else {
                    src_owned = self.tensor_tape.values(src)?;
                    &src_owned
                };
                Self::scatter_reduce_apply(
                    &mut result,
                    &index_data,
                    src_vals,
                    "sum",
                    outer,
                    idx_dim_size,
                    inner,
                    dim_size,
                    parallel,
                    |_, _| {},
                );
                return self.tensor_variable(result, input_shape, false);
            }
            let mut result = self.tensor_tape.values_f32(input)?;
            let src_owned: Vec<f32>;
            let src_vals: &[f32] = if self.tensor_tape.tensor(src)?.meta().is_contiguous() {
                self.tensor_tape.tensor(src)?.contiguous_values_f32()?
            } else {
                src_owned = self.tensor_tape.values_f32(src)?;
                &src_owned
            };
            Self::scatter_reduce_apply(
                &mut result,
                &index_data,
                src_vals,
                "sum",
                outer,
                idx_dim_size,
                inner,
                dim_size,
                parallel,
                |_, _| {},
            );
            return self.tensor_variable_f32(result, input_shape, false);
        }

        let src_data = match input_dtype {
            DType::F64 => self.tensor_tape.values(src)?,
            DType::F32 => self
                .tensor_tape
                .values_f32(src)?
                .into_iter()
                .map(f64::from)
                .collect(),
            // torch CPU scatter_add on half accumulates in fp32 then narrows to
            // half (verified vs torch 2.12, frankentorch-uv4l). Read the half src
            // losslessly as f64; the tape upcasts to f32, accumulates, and narrows.
            DType::F16 | DType::BF16 => self.tensor_tape.values_lossy_f64(src)?,
            _ => {
                return Err(AutogradError::Dispatch(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "scatter_add requires f32, f64, f16, or bf16 tensors",
                    }
                    .into(),
                ));
            }
        };
        self.tensor_tape
            .scatter_add(input, src, dim, &index_data, index_shape, &src_data)
    }

    pub fn tensor_index_put(
        &mut self,
        input: TensorNodeId,
        indices: &[TensorNodeId],
        values: TensorNodeId,
        accumulate: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        // No-grad fast path: index_put with a SINGLE 1-D index that selects whole dim-0 slices
        // (values shaped [n, input[1..]]) is exactly index_copy (overwrite) / index_add
        // (accumulate) along dim 0 — route to those, which have direct borrowed-read no-grad
        // kernels. The generic tape path below clones every index AND UPCASTS f32 values -> f64.
        // Bit-identical for in-range indices (torch index_put on duplicate indices with
        // accumulate=false is unspecified, as is index_copy). Multi-index / broadcasting / grad
        // / non-f32f64 / dtype-mismatch fall through to the tape path unchanged.
        if indices.len() == 1
            && matches!(self.tensor_tape.dtype(input)?, DType::F64 | DType::F32)
            && self.tensor_tape.dtype(values)? == self.tensor_tape.dtype(input)?
            && !self.tensor_requires_grad(input)?
            && !self.tensor_requires_grad(values)?
        {
            let input_shape = self.tensor_shape(input)?;
            let idx_shape = self.tensor_shape(indices[0])?;
            if idx_shape.len() == 1 && !input_shape.is_empty() {
                let mut expected = idx_shape.clone();
                expected.extend_from_slice(&input_shape[1..]);
                if self.tensor_shape(values)? == expected {
                    return if accumulate {
                        self.tensor_index_add(input, 0, indices[0], values)
                    } else {
                        self.tensor_index_copy(input, 0, indices[0], values)
                    };
                }
            }
        }

        let idx_data: Vec<Vec<f64>> = indices
            .iter()
            .map(|&idx| self.tensor_tape.values(idx))
            .collect::<Result<_, _>>()?;
        let input_dtype = self.tensor_tape.dtype(input)?;
        let values_dtype = self.tensor_tape.dtype(values)?;
        if values_dtype != input_dtype {
            return Err(AutogradError::Dispatch(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "index_put requires input and values to have matching dtypes",
                }
                .into(),
            ));
        }
        let vals_data = match input_dtype {
            DType::F64 => self.tensor_tape.values(values)?,
            DType::F32 => self
                .tensor_tape
                .values_f32(values)?
                .into_iter()
                .map(f64::from)
                .collect(),
            // Read the half values losslessly as f64. accumulate=false (overwrite)
            // is pure movement and narrows back bit-exactly via the tape; the
            // accumulate=true half case is routed to index_put_accumulate_half
            // below (per-add-half rounding, frankentorch-k4wr).
            DType::F16 | DType::BF16 => self.tensor_tape.values_lossy_f64(values)?,
            _ => {
                return Err(AutogradError::Dispatch(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "index_put requires f32 or f64 tensors",
                    }
                    .into(),
                ));
            }
        };
        // index_put with accumulate=true on f16/bf16 uses PER-ADD half rounding
        // (narrow to half after every +=), unlike the f64/f32 kernel's plain
        // accumulation — same per-add-half semantics as index_add, distinct from
        // scatter_add's fp32-accumulate. Verified vs torch 2.12 (frankentorch-k4wr).
        if accumulate && matches!(input_dtype, DType::F16 | DType::BF16) {
            return self.index_put_accumulate_half(
                input,
                values,
                &idx_data,
                &vals_data,
                input_dtype,
            );
        }
        self.tensor_tape
            .index_put(input, values, &idx_data, &vals_data, accumulate)
    }

    /// `index_put(accumulate=true)` on f16/bf16. torch accumulates on half with
    /// per-add rounding: after every `+=` the running value is narrowed back to
    /// the half dtype (verified vs torch 2.12, frankentorch-k4wr). The forward is
    /// computed via `apply_function` with per-add narrowing in index order — the
    /// sum of two half values is exact in f32/f64, so narrowing per add reproduces
    /// torch bit-for-bit — then the f64 result is cast to the half dtype. Backward
    /// matches the IndexPut(accumulate=true) rule: grad_input passthrough,
    /// grad_values gather at each written position (scalar broadcast sums).
    fn index_put_accumulate_half(
        &mut self,
        input: TensorNodeId,
        values: TensorNodeId,
        idx_data: &[Vec<f64>],
        vals_data: &[f64],
        input_dtype: DType,
    ) -> Result<TensorNodeId, AutogradError> {
        let key_err = |reason: &'static str| {
            AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet { reason },
            ))
        };
        let shape = self.tensor_shape(input)?;
        let ndim = shape.len();
        if idx_data.is_empty() {
            return Err(key_err("index_put requires at least one index tensor"));
        }
        let num_indexed = idx_data.len();
        if num_indexed > ndim {
            return Err(key_err("index_put: more index tensors than dimensions"));
        }
        let n_indices = idx_data[0].len();
        for d in &idx_data[1..] {
            if d.len() != n_indices {
                return Err(key_err(
                    "index_put: all index tensors must have the same length",
                ));
            }
        }
        let suffix_size =
            Self::checked_shape_numel(&shape[num_indexed..], "index_put: suffix shape overflow")?;
        let values_needed =
            Self::checked_mul(n_indices, suffix_size, "index_put: values shape overflow")?;
        let scalar_broadcast = vals_data.len() == 1 && values_needed > 1;
        if !scalar_broadcast && vals_data.len() < values_needed {
            return Err(key_err("index_put: values tensor has too few elements"));
        }
        let mut strides = vec![0usize; num_indexed];
        for d in 0..num_indexed {
            strides[d] =
                Self::checked_shape_numel(&shape[d + 1..], "index_put: stride shape overflow")?;
        }
        // Wrapped-index base offsets, matching kernel `normalize_wrapped_index_value`.
        let mut bases = Vec::with_capacity(n_indices);
        for i in 0..n_indices {
            let mut base = 0usize;
            for d in 0..num_indexed {
                let dim_size = shape[d];
                let dim_size_i = isize::try_from(dim_size)
                    .map_err(|_| key_err("index_put: dimension out of range for platform isize"))?;
                let mut idx_i = Self::exact_integer_index_to_isize(
                    idx_data[d][i],
                    "index_put: index values must be finite integers",
                )?;
                if idx_i < 0 {
                    idx_i += dim_size_i;
                }
                if idx_i < 0 || idx_i >= dim_size_i {
                    return Err(key_err("index_put: index value out of range"));
                }
                base += (idx_i as usize) * strides[d];
            }
            bases.push(base);
        }

        let is_bf16 = matches!(input_dtype, DType::BF16);
        let bases_fwd = bases.clone();
        let bases_bwd = bases;
        let suffix = suffix_size;
        let vn = values_needed;
        let result = self.tensor_apply_function(
            &[input, values],
            move |_ctx, ins| {
                let (in_vals, in_shape) = ins[0];
                let (val_vals, _) = ins[1];
                let mut out = in_vals.to_vec();
                for (i, &base) in bases_fwd.iter().enumerate() {
                    for s in 0..suffix {
                        let v = if scalar_broadcast {
                            val_vals[0]
                        } else {
                            val_vals[i * suffix + s]
                        };
                        // Sum of two half values is exact in f32/f64; narrow to
                        // half after EACH add to match torch's per-add rounding.
                        let sum = (out[base + s] + v) as f32;
                        out[base + s] = if is_bf16 {
                            f64::from(ft_core::BFloat16::from_f32(sum).to_f32())
                        } else {
                            f64::from(ft_core::Float16::from_f32(sum).to_f32())
                        };
                    }
                }
                Ok((out, in_shape.to_vec()))
            },
            move |_ctx, grads| {
                // accumulate=true backward: grad_input passthrough (out = input +
                // contributions), grad_values gather at each written position; a
                // one-element (broadcast) values tensor collapses to the sum.
                let g = grads[0];
                let grad_input = g.to_vec();
                let grad_values = if scalar_broadcast {
                    let mut acc = 0.0_f64;
                    for &base in &bases_bwd {
                        for s in 0..suffix {
                            acc += g[base + s];
                        }
                    }
                    vec![acc]
                } else {
                    let mut gv = vec![0.0_f64; vn];
                    for (i, &base) in bases_bwd.iter().enumerate() {
                        for s in 0..suffix {
                            gv[i * suffix + s] = g[base + s];
                        }
                    }
                    gv
                };
                Ok(vec![Some(grad_input), Some(grad_values)])
            },
        )?;
        // apply_function yields F64; cast to the half dtype (exact — the
        // accumulated values are already half-representable).
        if is_bf16 {
            self.tensor_bfloat16(result)
        } else {
            self.tensor_half(result)
        }
    }

    pub fn tensor_masked_fill(
        &mut self,
        input: TensorNodeId,
        mask: TensorNodeId,
        value: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        // F32 no-grad fast path: the composition below builds an F64 `full(value)` (128MB at
        // 4k×4k) + composes the f64 `tensor_where` = ~3.5x SLOWER than torch. For equal-shape
        // contiguous f32 input + f32 mask with grad off, fill in ONE parallel pass:
        // `mask != 0 ? value_f32 : input` — the SAME predicate as where_tensor_contiguous_f32
        // (`c != 0.0`), value cast to f32 (== torch). Pure select -> BIT-EXACT. Broadcast mask /
        // non-f32 / grad / non-contiguous fall through. frankentorch-kgs4.181.
        if !self.tensor_requires_grad(input)?
            && !self.tensor_requires_grad(mask)?
            && self.tensor_dtype(input)? == DType::F32
            && self.tensor_dtype(mask)? == DType::F32
            && self.tensor_shape(mask)? == shape
        {
            let built = {
                let it = self.tensor_tape.tensor(input)?;
                let mt = self.tensor_tape.tensor(mask)?;
                if it.meta().is_contiguous() && mt.meta().is_contiguous() {
                    let iv = it.contiguous_values_f32()?;
                    let mv = mt.contiguous_values_f32()?;
                    let v = value as f32;
                    use rayon::prelude::*;
                    let out: Vec<f32> = iv
                        .par_iter()
                        .zip(mv.par_iter())
                        .map(|(&x, &m)| if m != 0.0 { v } else { x })
                        .collect();
                    Some(out)
                } else {
                    None
                }
            };
            if let Some(out) = built {
                return self.tensor_variable_f32(out, shape, false);
            }
        }
        // F64 sibling: the composed path below builds a full(value) [128MB at 4k×4k] + an f64
        // tensor_where (~2 passes + alloc). For equal-shape contiguous f64 input + f64 mask with
        // grad off, fill in ONE parallel pass `mask != 0 ? value : input` — the SAME predicate as
        // where_tensor_contiguous_f64 (`c != 0.0`). Pure select -> BIT-EXACT. Broadcast mask /
        // non-f64-mask / grad / non-contiguous fall through.
        if !self.tensor_requires_grad(input)?
            && !self.tensor_requires_grad(mask)?
            && self.tensor_dtype(input)? == DType::F64
            && self.tensor_dtype(mask)? == DType::F64
            && self.tensor_shape(mask)? == shape
        {
            let built = {
                let it = self.tensor_tape.tensor(input)?;
                let mt = self.tensor_tape.tensor(mask)?;
                if it.meta().is_contiguous() && mt.meta().is_contiguous() {
                    let iv = it.contiguous_values()?;
                    let mv = mt.contiguous_values()?;
                    use rayon::prelude::*;
                    let out: Vec<f64> = iv
                        .par_iter()
                        .zip(mv.par_iter())
                        .map(|(&x, &m)| if m != 0.0 { value } else { x })
                        .collect();
                    Some(out)
                } else {
                    None
                }
            };
            if let Some(out) = built {
                return self.tensor_variable(out, shape, false);
            }
        }
        if let Some(out) = self.try_masked_fill_tile(input, mask, value)? {
            return Ok(out);
        }
        if let Some(out) = self.try_masked_fill_broadcast(input, mask, value)? {
            return Ok(out);
        }
        let fill_tensor = self.full(shape, value, false)?;
        self.tensor_where(mask, fill_tensor, input)
    }

    /// No-grad fast path for `masked_fill` with a BROADCAST mask that TILES into `input` — the
    /// attention pattern `scores.masked_fill(mask[1,1,S,S], -inf)` (mask repeats over batch/heads).
    /// The fallthrough materializes a full-size `full(value)` const + broadcasts mask/fill/input +
    /// where. Here we fill in ONE pass per tile (`out[k] = mask[k%cinner]!=0 ? value : input[k]`,
    /// mask cache-resident and reused each tile), no expand. Bit-identical to torch (value cast to
    /// the input dtype, same as the same-shape fast paths). f32/f64, contiguous, mask a trailing
    /// tile of input; grad / middle-broadcast mask / non-f32-f64 fall through.
    fn try_masked_fill_tile(
        &mut self,
        input: TensorNodeId,
        mask: TensorNodeId,
        value: f64,
    ) -> Result<Option<TensorNodeId>, AutogradError> {
        if self.tensor_requires_grad(input)? || self.tensor_requires_grad(mask)? {
            return Ok(None);
        }
        let shape = self.tensor_shape(input)?;
        let ms = self.tensor_shape(mask)?;
        if ms == shape {
            return Ok(None); // same-shape handled by the fast paths above
        }
        let dtype = self.tensor_dtype(input)?;
        if self.tensor_dtype(mask)? != dtype {
            return Ok(None);
        }
        // mask must tile into input: strip mask's leading 1s, remainder an exact suffix of `shape`.
        let mut i = 0;
        while i < ms.len() && ms[i] == 1 {
            i += 1;
        }
        let eff = &ms[i..];
        if eff.len() > shape.len() || shape[shape.len() - eff.len()..] != *eff {
            return Ok(None);
        }
        let cinner: usize = ms.iter().product();
        let n: usize = shape.iter().product();
        if cinner == 0 || n == 0 || n % cinner != 0 {
            return Ok(None);
        }
        macro_rules! fused {
            ($read:ident, $build:ident, $ty:ty) => {{
                let built = {
                    let it = self.tensor_tape.tensor(input)?;
                    let mt = self.tensor_tape.tensor(mask)?;
                    if it.meta().is_contiguous() && mt.meta().is_contiguous() {
                        let iv = it.$read()?;
                        let mv = mt.$read()?;
                        if iv.len() == n && mv.len() == cinner {
                            let v = value as $ty;
                            use rayon::prelude::*;
                            let fill = |ochunk: &mut [$ty], ichunk: &[$ty]| {
                                for j in 0..cinner {
                                    ochunk[j] = if mv[j] != (0 as $ty) { v } else { ichunk[j] };
                                }
                            };
                            let mut out = vec![0 as $ty; n];
                            if n >= PARALLEL_ELEMENTWISE_MIN {
                                out.par_chunks_mut(cinner)
                                    .zip(iv.par_chunks(cinner))
                                    .for_each(|(oc, ic)| fill(oc, ic));
                            } else {
                                out.chunks_mut(cinner)
                                    .zip(iv.chunks(cinner))
                                    .for_each(|(oc, ic)| fill(oc, ic));
                            }
                            Some(out)
                        } else {
                            None
                        }
                    } else {
                        None
                    }
                };
                match built {
                    Some(out) => Ok(Some(self.$build(out, shape.clone(), false)?)),
                    None => Ok(None),
                }
            }};
        }
        match dtype {
            DType::F64 => fused!(contiguous_values, tensor_variable, f64),
            DType::F32 => fused!(contiguous_values_f32, tensor_variable_f32, f32),
            _ => Ok(None),
        }
    }

    /// No-grad fast path for `masked_fill` with ANY broadcast mask (generalizes `try_masked_fill_tile`,
    /// which only covers TRAILING tiles) — the KEY-PADDING attention mask `scores.masked_fill(
    /// mask[B,1,1,S], -inf)` / `mask[B,1,S,S]` where the batch dim varies but heads/query broadcast (a
    /// MIDDLE/leading size-1 dim, NOT a pure trailing tile). The fallthrough materializes a full-size
    /// `full(value)` const + broadcasts mask/fill/input + where. Here we right-align the mask to
    /// `input`, find the longest trailing NON-broadcast run (`inner`, contiguous in both), then for each
    /// output row select `inner` elements from the mask block whose offset is the sum of the outer
    /// non-broadcast index contributions (broadcast dims contribute 0). Bit-identical to torch (value
    /// cast to input dtype). f32/f64, contiguous, no-grad; non-broadcastable mask falls through.
    fn try_masked_fill_broadcast(
        &mut self,
        input: TensorNodeId,
        mask: TensorNodeId,
        value: f64,
    ) -> Result<Option<TensorNodeId>, AutogradError> {
        if self.tensor_requires_grad(input)? || self.tensor_requires_grad(mask)? {
            return Ok(None);
        }
        let shape = self.tensor_shape(input)?;
        let ms = self.tensor_shape(mask)?;
        let dtype = self.tensor_dtype(input)?;
        if self.tensor_dtype(mask)? != dtype {
            return Ok(None);
        }
        let r = shape.len();
        // mask must have rank <= input and broadcast into input: right-align (prepend 1s) and require
        // every dim to be 1 (broadcast) or equal the output dim. A non-broadcastable mask falls
        // through (the generic path errors). mask.numel > 1 and a non-trailing broadcast (else the tile
        // path already handled it); mask.numel < input.numel (else same-shape).
        if ms.len() > r {
            return Ok(None);
        }
        let mut ma = vec![1usize; r]; // right-aligned mask shape
        for (k, &d) in ms.iter().enumerate() {
            ma[r - ms.len() + k] = d;
        }
        for d in 0..r {
            if ma[d] != 1 && ma[d] != shape[d] {
                return Ok(None); // non-broadcastable
            }
        }
        let n: usize = shape.iter().product();
        let mnum: usize = ms.iter().product();
        if n == 0 || mnum == 0 || mnum == 1 || mnum == n {
            return Ok(None);
        }
        // mask contiguous strides over its right-aligned shape `ma`.
        let mut mstride = vec![0usize; r];
        let mut acc = 1usize;
        for d in (0..r).rev() {
            mstride[d] = acc;
            acc *= ma[d];
        }
        // longest trailing run of NON-broadcast dims (mask advances contiguously with output there).
        let mut run = 0usize;
        let mut inner = 1usize;
        for d in (0..r).rev() {
            if ma[d] == shape[d] && ma[d] != 1 {
                run += 1;
                inner *= shape[d];
            } else {
                break;
            }
        }
        if inner == 0 || n % inner != 0 {
            return Ok(None);
        }
        let outer_len = r - run;
        // Parallel granularity is decoupled from `inner` (a small inner — e.g. key-padding [B,1,1,S]
        // — would make par_chunks_mut(inner) a dispatch storm): group ~32K output elems per task and
        // iterate the rows within.
        let rows_per_task = (32_768 / inner).max(1);
        let block = rows_per_task * inner;
        // per outer dim: (radix = output size, contribution = mask stride if non-broadcast else 0).
        let outer: Vec<(usize, usize)> = (0..outer_len)
            .map(|d| (shape[d], if ma[d] == 1 { 0 } else { mstride[d] }))
            .collect();
        macro_rules! fused {
            ($read:ident, $build:ident, $ty:ty) => {{
                let built = {
                    let it = self.tensor_tape.tensor(input)?;
                    let mt = self.tensor_tape.tensor(mask)?;
                    if it.meta().is_contiguous() && mt.meta().is_contiguous() {
                        let iv = it.$read()?;
                        let mv = mt.$read()?;
                        if iv.len() == n && mv.len() == mnum {
                            let v = value as $ty;
                            use rayon::prelude::*;
                            // row r -> mask block offset: decompose r over the outer output dims and
                            // sum non-broadcast contributions; broadcast dims contribute 0.
                            let mbase = |mut row: usize| -> usize {
                                let mut base = 0usize;
                                for &(radix, contrib) in outer.iter().rev() {
                                    let idx = row % radix;
                                    row /= radix;
                                    base += idx * contrib;
                                }
                                base
                            };
                            let fill = |row: usize, oc: &mut [$ty], ic: &[$ty]| {
                                let b = mbase(row);
                                let mrow = &mv[b..b + inner];
                                for j in 0..inner {
                                    oc[j] = if mrow[j] != (0 as $ty) { v } else { ic[j] };
                                }
                            };
                            let mut out = vec![0 as $ty; n];
                            if n >= PARALLEL_ELEMENTWISE_MIN {
                                out.par_chunks_mut(block)
                                    .zip(iv.par_chunks(block))
                                    .enumerate()
                                    .for_each(|(t, (ochunk, ichunk))| {
                                        let row_base = t * rows_per_task;
                                        for (rr, (oc, ic)) in ochunk
                                            .chunks_mut(inner)
                                            .zip(ichunk.chunks(inner))
                                            .enumerate()
                                        {
                                            fill(row_base + rr, oc, ic);
                                        }
                                    });
                            } else {
                                out.chunks_mut(inner)
                                    .zip(iv.chunks(inner))
                                    .enumerate()
                                    .for_each(|(row, (oc, ic))| fill(row, oc, ic));
                            }
                            Some(out)
                        } else {
                            None
                        }
                    } else {
                        None
                    }
                };
                match built {
                    Some(out) => Ok(Some(self.$build(out, shape.clone(), false)?)),
                    None => Ok(None),
                }
            }};
        }
        match dtype {
            DType::F64 => fused!(contiguous_values, tensor_variable, f64),
            DType::F32 => fused!(contiguous_values_f32, tensor_variable_f32, f32),
            _ => Ok(None),
        }
    }

    /// Accumulate `src` into `self` at positions specified by `index` along `dim`.
    ///
    /// Equivalent to `tensor.index_add_(dim, index, source)`.
    /// For each `i`, adds `src[i]` to `self[index[i]]` along `dim`.
    pub fn tensor_index_add(
        &mut self,
        input: TensorNodeId,
        dim: usize,
        index: TensorNodeId,
        src: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        let index_shape = self.tensor_shape(index)?;
        if index_shape.len() != 1 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "index_add: index tensor must be 1D",
                },
            )));
        }
        let index_len = index_shape[0];
        let idx_vals = self.tensor_values(index)?;
        let src_shape = self.tensor_shape(src)?;
        let input_dtype = self.tensor_tape.dtype(input)?;
        let src_dtype = self.tensor_tape.dtype(src)?;
        if src_dtype != input_dtype {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "index_add requires input and src to have matching dtypes",
                },
            )));
        }
        if src_shape.len() != shape.len() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "index_add: src rank must match input rank",
                },
            )));
        }
        for (dim_idx, &size) in shape.iter().enumerate() {
            if dim_idx != dim && src_shape[dim_idx] != size {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "index_add: src shape must match input shape except at dim",
                    },
                )));
            }
        }

        let ndim = shape.len();
        if dim >= ndim {
            // Migrate to InvalidDimension to surface dim + ndim in
            // the diagnostic (frankentorch-6zyy).
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::InvalidDimension { dim, ndim },
            )));
        }

        let dim_size = shape[dim];
        let outer = Self::checked_shape_numel(&shape[..dim], "index_add: outer shape overflow")?;
        let inner =
            Self::checked_shape_numel(&shape[dim + 1..], "index_add: inner shape overflow")?;
        let src_dim_size = src_shape[dim];
        if src_dim_size != index_len {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "index_add: src dimension must match index length",
                },
            )));
        }
        let dim_size_i = isize::try_from(dim_size).map_err(|_| {
            AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "index_add: index dimension out of range for platform isize",
                },
            ))
        })?;
        let normalize_index = |idx_f: f64| -> Result<usize, AutogradError> {
            let idx_i = Self::exact_integer_index_to_isize(
                idx_f,
                "index_add: index values must be finite integers",
            )?;
            // torch `index_add_` rejects negative indices outright
            // (`IndexError: index out of range in self`); it does not
            // wrap them like advanced indexing. Verified vs torch 2.12
            // (frankentorch-n0un).
            if idx_i < 0 || idx_i >= dim_size_i {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "index_add: index value out of range",
                    },
                )));
            }
            usize::try_from(idx_i).map_err(|_| {
                AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "index_add: index value out of range",
                    },
                ))
            })
        };

        // Validate every supplied index up-front so the composition
        // below sees only well-formed indices. (tensor_scatter_add
        // performs its own validation but produces less specific
        // error messages.)
        for &idx_f in &idx_vals {
            normalize_index(idx_f)?;
        }
        // f32/f64: torch index_add accumulates in the input dtype; per-add
        // rounding equals straight accumulation there, so composing through
        // scatter_add (below) is exact. f16/bf16 DIFFER: torch uses PER-ADD HALF
        // rounding (narrow back to half after every `+=`), unlike scatter_add's
        // fp32-accumulate-then-narrow. Verified bit-exact vs torch 2.12 over
        // golden cases (frankentorch-k4wr). So compute the half forward directly
        // with per-add half narrowing via apply_function, then cast to half.
        match input_dtype {
            DType::F64 | DType::F32 => {}
            DType::F16 | DType::BF16 => {
                let is_bf16 = matches!(input_dtype, DType::BF16);
                let norm_idx: Vec<usize> = idx_vals
                    .iter()
                    .map(|&f| normalize_index(f))
                    .collect::<Result<_, _>>()?;
                let (outer_c, inner_c, dim_c, srcd_c) = (outer, inner, dim_size, src_dim_size);
                let nidx_fwd = norm_idx.clone();
                let nidx_bwd = norm_idx;
                let result = self.tensor_apply_function(
                    &[input, src],
                    move |_ctx, ins| {
                        let (in_vals, in_shape) = ins[0];
                        let (src_vals, _) = ins[1];
                        let mut out = in_vals.to_vec();
                        for o in 0..outer_c {
                            for r in 0..srcd_c {
                                let target = nidx_fwd[r];
                                for i in 0..inner_c {
                                    let sp = o * srcd_c * inner_c + r * inner_c + i;
                                    let dst = o * dim_c * inner_c + target * inner_c + i;
                                    // The sum of two half values is exact in f64
                                    // and f32; narrow to half after EACH add to
                                    // match torch's per-add rounding.
                                    let sum = (out[dst] + src_vals[sp]) as f32;
                                    out[dst] = if is_bf16 {
                                        f64::from(ft_core::BFloat16::from_f32(sum).to_f32())
                                    } else {
                                        f64::from(ft_core::Float16::from_f32(sum).to_f32())
                                    };
                                }
                            }
                        }
                        Ok((out, in_shape.to_vec()))
                    },
                    move |_ctx, grads| {
                        // index_add backward: grad flows through `input` as a
                        // passthrough (out = input + scattered src) and through
                        // `src` by gathering grad_out at each written position.
                        let g = grads[0];
                        let grad_input = g.to_vec();
                        let mut grad_src = vec![0.0_f64; outer_c * srcd_c * inner_c];
                        for o in 0..outer_c {
                            for r in 0..srcd_c {
                                let target = nidx_bwd[r];
                                for i in 0..inner_c {
                                    let sp = o * srcd_c * inner_c + r * inner_c + i;
                                    let dst = o * dim_c * inner_c + target * inner_c + i;
                                    grad_src[sp] = g[dst];
                                }
                            }
                        }
                        Ok(vec![Some(grad_input), Some(grad_src)])
                    },
                )?;
                // apply_function yields F64; cast to the half dtype (exact — the
                // accumulated values are already half-representable).
                return if is_bf16 {
                    self.tensor_bfloat16(result)
                } else {
                    self.tensor_half(result)
                };
            }
            _ => {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "index_add requires f32, f64, f16, or bf16 tensors",
                    },
                )));
            }
        }

        // No-grad fast path: index_add is a bucketed SUM along `dim`
        // (out[.., idx[r], ..] += src[.., r, ..]). The autograd composition below
        // materializes a full [outer, src_dim, inner] EXPANDED index (megabytes) and routes
        // through scatter_add's apply_function. For the no-grad case accumulate DIRECTLY:
        // borrow the src storage zero-copy, read input straight into `result`, and
        // bucket-parallelize over disjoint output rows. Bit-identical — sources accumulate in
        // ascending `r` order (same as scatter_add's flat walk) and `include_self=true` keeps
        // the input value as the base. Non-contiguous src falls back to a clone.
        if !self.tensor_requires_grad(input)? && !self.tensor_requires_grad(src)? {
            let src_outer_stride = src_dim_size * inner;
            match input_dtype {
                DType::F64 => {
                    let mut result = self.tensor_tape.values(input)?;
                    let src_owned: Vec<f64>;
                    let src_vals: &[f64] = if self.tensor_tape.tensor(src)?.meta().is_contiguous() {
                        self.tensor_tape.tensor(src)?.contiguous_values()?
                    } else {
                        src_owned = self.tensor_tape.values(src)?;
                        &src_owned
                    };
                    Self::index_reduce_apply(
                        &mut result,
                        src_vals,
                        &idx_vals,
                        "sum",
                        true,
                        outer,
                        dim_size,
                        inner,
                        src_outer_stride,
                        |_, _| {},
                    )?;
                    return self.tensor_variable(result, shape.clone(), false);
                }
                DType::F32 => {
                    let mut result = self.tensor_tape.values_f32(input)?;
                    let src_owned: Vec<f32>;
                    let src_vals: &[f32] = if self.tensor_tape.tensor(src)?.meta().is_contiguous() {
                        self.tensor_tape.tensor(src)?.contiguous_values_f32()?
                    } else {
                        src_owned = self.tensor_tape.values_f32(src)?;
                        &src_owned
                    };
                    Self::index_reduce_apply(
                        &mut result,
                        src_vals,
                        &idx_vals,
                        "sum",
                        true,
                        outer,
                        dim_size,
                        inner,
                        src_outer_stride,
                        |_, _| {},
                    )?;
                    return self.tensor_variable_f32(result, shape.clone(), false);
                }
                _ => {}
            }
        }

        // Compose index_add through tensor_scatter_add so the
        // autograd tape carries gradients to both `input` and `src`.
        // The previous body extracted values and rebuilt a fresh
        // requires_grad=false leaf, silently severing the tape — the
        // same severed-autograd pattern Scatter / ScatterAdd /
        // IndexPut had until 5d4b5a1 / 56c5165 / 692d90e.
        //
        // index_add(input, dim, idx_1d, src) writes
        //     output[..., idx_1d[r], ...] += src[..., r, ...]
        // for each r in 0..src_dim_size, broadcasting across every
        // outer/inner position. tensor_scatter_add already implements
        // exactly this when given an index tensor of the same shape
        // as src, so we just expand the 1-D `idx_1d` into a full
        // [outer, src_dim_size, inner] index where every element at
        // position (o, r, i) is `idx_1d[r]`.
        let expanded_numel = Self::checked_mul(
            Self::checked_mul(
                outer,
                src_dim_size,
                "index_add: expanded index outer overflow",
            )?,
            inner,
            "index_add: expanded index inner overflow",
        )?;
        let mut expanded_idx_vals = Vec::with_capacity(expanded_numel);
        for _o in 0..outer {
            for &idx_f in &idx_vals {
                for _i in 0..inner {
                    expanded_idx_vals.push(idx_f);
                }
            }
        }
        let expanded_idx_node =
            self.tensor_tape
                .leaf(expanded_idx_vals, src_shape.clone(), false)?;

        // Note: tensor_scatter_add propagates gradients through both
        // `input` (passthrough) and `src` (gather). Output dtype
        // matches `input` dtype.
        self.tensor_scatter_add(input, dim, expanded_idx_node, src)
    }

    /// Copy `src` into `self` at positions specified by `index` along `dim`.
    ///
    /// Equivalent to `tensor.index_copy_(dim, index, source)`.
    pub fn tensor_index_copy(
        &mut self,
        input: TensorNodeId,
        dim: usize,
        index: TensorNodeId,
        src: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        let index_shape = self.tensor_shape(index)?;
        if index_shape.len() != 1 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "index_copy: index tensor must be 1D",
                },
            )));
        }
        let index_len = index_shape[0];
        let idx_vals = self.tensor_values(index)?;
        let src_shape = self.tensor_shape(src)?;
        let input_dtype = self.tensor_tape.dtype(input)?;
        let src_dtype = self.tensor_tape.dtype(src)?;
        if src_dtype != input_dtype {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "index_copy requires input and src to have matching dtypes",
                },
            )));
        }
        if src_shape.len() != shape.len() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "index_copy: src rank must match input rank",
                },
            )));
        }
        for (dim_idx, &size) in shape.iter().enumerate() {
            if dim_idx != dim && src_shape[dim_idx] != size {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "index_copy: src shape must match input shape except at dim",
                    },
                )));
            }
        }

        let ndim = shape.len();
        if dim >= ndim {
            // Migrate to InvalidDimension (frankentorch-6zyy).
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::InvalidDimension { dim, ndim },
            )));
        }

        let dim_size = shape[dim];
        let outer = Self::checked_shape_numel(&shape[..dim], "index_copy: outer shape overflow")?;
        let inner =
            Self::checked_shape_numel(&shape[dim + 1..], "index_copy: inner shape overflow")?;
        let src_dim_size = src_shape[dim];
        if src_dim_size != index_len {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "index_copy: src dimension must match index length",
                },
            )));
        }
        let dim_size_i = isize::try_from(dim_size).map_err(|_| {
            AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "index_copy: index dimension out of range for platform isize",
                },
            ))
        })?;
        let normalize_index = |idx_f: f64| -> Result<usize, AutogradError> {
            let idx_i = Self::exact_integer_index_to_isize(
                idx_f,
                "index_copy: index values must be finite integers",
            )?;
            // torch `index_copy_` rejects negative indices outright
            // (`IndexError: index_copy_(): index N is out of bounds`);
            // it does not wrap them like advanced indexing. Verified
            // vs torch 2.12 (frankentorch-n0un).
            if idx_i < 0 || idx_i >= dim_size_i {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "index_copy: index value out of range",
                    },
                )));
            }
            usize::try_from(idx_i).map_err(|_| {
                AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "index_copy: index value out of range",
                    },
                ))
            })
        };

        // Validate every supplied index up-front so the composition
        // below sees only well-formed indices.
        for &idx_f in &idx_vals {
            normalize_index(idx_f)?;
        }
        // index_copy composes through tensor_scatter (overwrite); that path is
        // bit-exact for f16/bf16 (pure movement, frankentorch-u78p), so half
        // inputs are accepted here too.
        if !matches!(
            input_dtype,
            DType::F64 | DType::F32 | DType::F16 | DType::BF16
        ) {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "index_copy requires f32, f64, f16, or bf16 tensors",
                },
            )));
        }

        // No-grad fast path (f32/f64): index_copy OVERWRITES along `dim`
        // (out[.., idx[r], ..] = src[.., r, ..], last-write-wins on duplicate idx). The
        // autograd composition below materializes a full [outer, src_dim, inner] EXPANDED
        // index and routes through tensor_scatter's apply_function. For the no-grad case write
        // DIRECTLY: borrow src zero-copy, read input straight into result, bucket-parallelize
        // over disjoint output rows. Each source assigns its slot in ascending `r` order so the
        // LAST writer wins — bit-identical to tensor_scatter's flat last-write-wins. Positions
        // with no source keep the input value (include_self=true; half dtypes fall through).
        if !self.tensor_requires_grad(input)?
            && !self.tensor_requires_grad(src)?
            && matches!(input_dtype, DType::F64 | DType::F32)
        {
            let src_outer_stride = src_dim_size * inner;
            if input_dtype == DType::F64 {
                let mut result = self.tensor_tape.values(input)?;
                let src_owned: Vec<f64>;
                let src_vals: &[f64] = if self.tensor_tape.tensor(src)?.meta().is_contiguous() {
                    self.tensor_tape.tensor(src)?.contiguous_values()?
                } else {
                    src_owned = self.tensor_tape.values(src)?;
                    &src_owned
                };
                Self::index_reduce_apply(
                    &mut result,
                    src_vals,
                    &idx_vals,
                    "copy",
                    true,
                    outer,
                    dim_size,
                    inner,
                    src_outer_stride,
                    |_, _| {},
                )?;
                return self.tensor_variable(result, shape.clone(), false);
            }
            let mut result = self.tensor_tape.values_f32(input)?;
            let src_owned: Vec<f32>;
            let src_vals: &[f32] = if self.tensor_tape.tensor(src)?.meta().is_contiguous() {
                self.tensor_tape.tensor(src)?.contiguous_values_f32()?
            } else {
                src_owned = self.tensor_tape.values_f32(src)?;
                &src_owned
            };
            Self::index_reduce_apply(
                &mut result,
                src_vals,
                &idx_vals,
                "copy",
                true,
                outer,
                dim_size,
                inner,
                src_outer_stride,
                |_, _| {},
            )?;
            return self.tensor_variable_f32(result, shape.clone(), false);
        }

        // Compose index_copy through tensor_scatter (non-add) so the
        // autograd tape carries gradients through both `input` and
        // `src`. Same severed-autograd pattern fix as in
        // tensor_index_add (this commit) and the earlier Scatter /
        // ScatterAdd / IndexPut fixes.
        //
        // index_copy(input, dim, idx_1d, src) writes
        //     output[..., idx_1d[r], ...] = src[..., r, ...]
        // for each r, broadcasting across every outer/inner position.
        // tensor_scatter implements this with overwrite (and the
        // updated last-write semantics for duplicate indices, fixed
        // in this branch). We expand the 1-D `idx_1d` to a full
        // [outer, src_dim_size, inner] index where every element at
        // (o, r, i) is `idx_1d[r]`.
        let expanded_numel = Self::checked_mul(
            Self::checked_mul(
                outer,
                src_dim_size,
                "index_copy: expanded index outer overflow",
            )?,
            inner,
            "index_copy: expanded index inner overflow",
        )?;
        let mut expanded_idx_vals = Vec::with_capacity(expanded_numel);
        for _o in 0..outer {
            for &idx_f in &idx_vals {
                for _i in 0..inner {
                    expanded_idx_vals.push(idx_f);
                }
            }
        }
        let expanded_idx_node =
            self.tensor_tape
                .leaf(expanded_idx_vals, src_shape.clone(), false)?;

        // tensor_scatter propagates gradients through both `input`
        // (passthrough with overwritten positions zeroed) and `src`
        // (gather, last-write-wins on duplicates). Output dtype
        // matches `input` dtype.
        self.tensor_scatter(input, dim, expanded_idx_node, src)
    }

    /// Fill positions specified by `index` along `dim` with a scalar value.
    ///
    /// Equivalent to `tensor.index_fill_(dim, index, value)`.
    pub fn tensor_index_fill(
        &mut self,
        input: TensorNodeId,
        dim: usize,
        index: TensorNodeId,
        value: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        let index_shape = self.tensor_shape(index)?;
        if index_shape.len() != 1 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "index_fill: index tensor must be 1D",
                },
            )));
        }
        let idx_vals = self.tensor_values(index)?;
        let input_dtype = self.tensor_tape.dtype(input)?;

        let ndim = shape.len();
        if dim >= ndim {
            // Migrate to InvalidDimension (frankentorch-6zyy).
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::InvalidDimension { dim, ndim },
            )));
        }

        let dim_size = shape[dim];
        let outer = Self::checked_shape_numel(&shape[..dim], "index_fill: outer shape overflow")?;
        let inner =
            Self::checked_shape_numel(&shape[dim + 1..], "index_fill: inner shape overflow")?;
        let dim_size_i = isize::try_from(dim_size).map_err(|_| {
            AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "index_fill: index dimension out of range for platform isize",
                },
            ))
        })?;
        let normalize_index = |idx_f: f64| -> Result<usize, AutogradError> {
            let idx_i = Self::exact_integer_index_to_isize(
                idx_f,
                "index_fill: index values must be finite integers",
            )?;
            if idx_i < -dim_size_i || idx_i >= dim_size_i {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "index_fill: index value out of range",
                    },
                )));
            }
            let wrapped = if idx_i < 0 { idx_i + dim_size_i } else { idx_i };
            usize::try_from(wrapped).map_err(|_| {
                AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "index_fill: index value out of range",
                    },
                ))
            })
        };

        // Validate and Python-wrap every supplied index up-front. The
        // scatter composition below must see non-negative, in-range
        // indices — and `torch.index_fill_` *does* wrap negatives (it
        // is one of the few index ops that does), so the wrapped value
        // is what the composition must use (frankentorch-n0un).
        let wrapped_idx_vals: Vec<f64> = idx_vals
            .iter()
            .map(|&idx_f| normalize_index(idx_f).map(|i| i as f64))
            .collect::<Result<_, _>>()?;
        // index_fill composes through tensor_scatter (overwrite); that path is
        // bit-exact for f16/bf16 (pure movement, frankentorch-u78p). The half
        // src_const below is cast to the input dtype, so the scalar is rounded to
        // half exactly as torch does before filling.
        if !matches!(
            input_dtype,
            DType::F64 | DType::F32 | DType::F16 | DType::BF16
        ) {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "index_fill requires f32, f64, f16, or bf16 tensors",
                },
            )));
        }

        // No-grad fast path (f32/f64): index_fill OVERWRITES each indexed dim-slice with the
        // scalar `value` (out[.., idx[r], ..] = value). The autograd composition below
        // materializes BOTH a full constant `src` tensor AND a full expanded index, then routes
        // through tensor_scatter's apply_function. For the no-grad case fill DIRECTLY: read input
        // into result, mark which dim positions are indexed, and parallel-fill those disjoint
        // output rows with `value` (idempotent — duplicate indices fill the same row). Half/grad
        // fall through to the scatter compose unchanged.
        if !self.tensor_requires_grad(input)? && matches!(input_dtype, DType::F64 | DType::F32) {
            let mut fill_mask = vec![false; dim_size];
            for &d_f in &wrapped_idx_vals {
                fill_mask[d_f as usize] = true;
            }
            let do_parallel = outer * dim_size >= 2
                && Self::checked_shape_numel(&shape, "index_fill: numel overflow")?
                    >= PARALLEL_ELEMENTWISE_MIN;
            if input_dtype == DType::F64 {
                let mut result = self.tensor_tape.values(input)?;
                let fill = |c: usize, ch: &mut [f64]| {
                    if fill_mask[c % dim_size] {
                        ch.iter_mut().for_each(|x| *x = value);
                    }
                };
                if do_parallel {
                    use rayon::prelude::*;
                    result
                        .par_chunks_mut(inner)
                        .enumerate()
                        .for_each(|(c, ch)| fill(c, ch));
                } else {
                    result
                        .chunks_mut(inner)
                        .enumerate()
                        .for_each(|(c, ch)| fill(c, ch));
                }
                return self.tensor_variable(result, shape.clone(), false);
            }
            let mut result = self.tensor_tape.values_f32(input)?;
            let vf = value as f32;
            let fill = |c: usize, ch: &mut [f32]| {
                if fill_mask[c % dim_size] {
                    ch.iter_mut().for_each(|x| *x = vf);
                }
            };
            if do_parallel {
                use rayon::prelude::*;
                result
                    .par_chunks_mut(inner)
                    .enumerate()
                    .for_each(|(c, ch)| fill(c, ch));
            } else {
                result
                    .chunks_mut(inner)
                    .enumerate()
                    .for_each(|(c, ch)| fill(c, ch));
            }
            return self.tensor_variable_f32(result, shape.clone(), false);
        }

        // Compose index_fill through tensor_scatter (non-add) with a
        // constant `src` tensor of the fill value. The previous body
        // extracted input values and rebuilt a requires_grad=false
        // leaf, silently severing the tape — same severed-autograd
        // pattern as the recently-fixed index_add / index_copy.
        //
        // Mathematically:
        //   output[..., idx_1d[r], ...] = value          (r in 0..idx_len)
        //   output[..., other,       ...] = input[...]
        //
        // tensor_scatter(input, dim, expanded_idx, src_const) does
        // exactly this when src_const is shaped like the indexed
        // region and uniformly equal to `value`. Backward correctness:
        //   grad_input gets passthrough with overwritten positions
        //     zeroed (the autograd-aware scatter we just built); this
        //     is what we want for index_fill since the filled
        //     positions no longer carry input's contribution.
        //   grad_src would be a gather of incoming, but src_const has
        //     requires_grad=false (it's a constant value), so that
        //     gradient is correctly dropped — no backprop into the
        //     scalar fill value.
        let idx_len = idx_vals.len();
        let expanded_numel = Self::checked_mul(
            Self::checked_mul(outer, idx_len, "index_fill: expanded index outer overflow")?,
            inner,
            "index_fill: expanded index inner overflow",
        )?;
        let mut expanded_idx_vals = Vec::with_capacity(expanded_numel);
        for _o in 0..outer {
            for &idx_f in &wrapped_idx_vals {
                for _i in 0..inner {
                    expanded_idx_vals.push(idx_f);
                }
            }
        }
        let mut src_shape = shape.clone();
        src_shape[dim] = idx_len;
        let expanded_idx_node =
            self.tensor_tape
                .leaf(expanded_idx_vals, src_shape.clone(), false)?;

        let src_const = match input_dtype {
            DType::F64 => self.tensor_variable(vec![value; expanded_numel], src_shape, false)?,
            DType::F32 => {
                #[allow(clippy::cast_possible_truncation)]
                let value_f32 = value as f32;
                self.tensor_variable_f32(vec![value_f32; expanded_numel], src_shape, false)?
            }
            // Build an f64 const then cast to the input's half dtype: the cast
            // rounds the fill scalar to half exactly as torch does. tensor_scatter
            // requires src_dtype == input_dtype (both half here).
            DType::F16 => {
                let c = self.tensor_variable(vec![value; expanded_numel], src_shape, false)?;
                self.tensor_half(c)?
            }
            DType::BF16 => {
                let c = self.tensor_variable(vec![value; expanded_numel], src_shape, false)?;
                self.tensor_bfloat16(c)?
            }
            _ => unreachable!("dtype already validated above"),
        };

        self.tensor_scatter(input, dim, expanded_idx_node, src_const)
    }

    pub fn tensor_cat(
        &mut self,
        inputs: &[TensorNodeId],
        dim: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        // No-grad fast path: the tape cat clones each input + runs a per-element
        // division-based unravel. A concatenation along `dim` is a CONTIGUOUS block copy
        // per (outer slice, input): out[o, offset_k.., :] = input_k[o, :, :]. Borrow all
        // inputs and parallelize over outer slices, NO division. Bit-exact. Falls through
        // unless all inputs are no-grad, contiguous F64 with shapes matching off `dim`.
        let fast_ok = !inputs.is_empty()
            && inputs
                .iter()
                .all(|&id| matches!(self.tensor_requires_grad(id), Ok(false)))
            && inputs
                .iter()
                .all(|&id| matches!(self.tensor_dtype(id), Ok(DType::F64)));
        if fast_ok {
            let shapes: Vec<Vec<usize>> = inputs
                .iter()
                .map(|&id| self.tensor_shape(id))
                .collect::<Result<_, _>>()?;
            let rank = shapes[0].len();
            let shapes_ok = dim < rank
                && shapes.iter().all(|s| s.len() == rank)
                && shapes
                    .iter()
                    .all(|s| (0..rank).all(|d| d == dim || s[d] == shapes[0][d]));
            if shapes_ok {
                let inner: usize = shapes[0][dim + 1..].iter().product();
                let outer: usize = shapes[0][..dim].iter().product();
                let mids: Vec<usize> = shapes.iter().map(|s| s[dim]).collect();
                let total_mid: usize = mids.iter().sum();
                if inner > 0 && total_mid > 0 {
                    let mut out_shape = shapes[0].clone();
                    out_shape[dim] = total_mid;
                    let built = {
                        let tensors: Vec<_> = inputs
                            .iter()
                            .map(|&id| self.tensor_tape.tensor(id))
                            .collect::<Result<_, _>>()?;
                        if tensors.iter().all(|t| t.meta().is_contiguous()) {
                            let all_slices: Vec<&[f64]> = tensors
                                .iter()
                                .map(|t| t.contiguous_values())
                                .collect::<Result<_, _>>()?;
                            use rayon::prelude::*;
                            let out_row_len = total_mid * inner;
                            // (slice, block_len) per NON-EMPTY input; skip mid==0 inputs
                            // (legal zero-size cat) so binary_search has no duplicate offsets.
                            let blocks: Vec<(&[f64], usize)> = all_slices
                                .iter()
                                .zip(mids.iter())
                                .filter(|&(_, &m)| m != 0)
                                .map(|(&sl, &m)| (sl, m * inner))
                                .collect();
                            // Cumulative element offset of each block within a row.
                            let cum_off: Vec<usize> = blocks
                                .iter()
                                .scan(0usize, |a, &(_, bl)| {
                                    let s = *a;
                                    *a += bl;
                                    Some(s)
                                })
                                .collect();
                            let mut out = vec![0.0_f64; outer * out_row_len];
                            const CHUNK: usize = 1 << 16;
                            if out_row_len == blocks.len() && inner == 1 {
                                // Interleave fast path (dstack / column_stack / stack-along-last-
                                // dim): every block is a SINGLE element, so the flat fill below
                                // degenerates to a per-element binary_search + division (out_row_len
                                // tiny, `outer` huge — measured ~67-100x SLOWER vs torch). Read
                                // block k's element straight into column k — no search, no division.
                                // Coarse outer chunks keep it parallel. Bit-identical.
                                let k = blocks.len();
                                let slices: Vec<&[f64]> =
                                    blocks.iter().map(|&(sl, _)| sl).collect();
                                let rows_per_task = (CHUNK / k).max(1);
                                out.par_chunks_mut(k * rows_per_task).enumerate().for_each(
                                    |(blk, chunk)| {
                                        let o0 = blk * rows_per_task;
                                        for (lr, row) in chunk.chunks_mut(k).enumerate() {
                                            let o = o0 + lr;
                                            for (kk, slot) in row.iter_mut().enumerate() {
                                                *slot = slices[kk][o];
                                            }
                                        }
                                    },
                                );
                            } else {
                                // Flat global-chunk fill: parallel for ANY outer (the old
                                // par_chunks_mut(out_row_len) made dim=0 / 1-D cat ONE chunk =
                                // SERIAL at ~2 GB/s first-touch-fault speed). Bit-identical.
                                let fill = |g0: usize, oc: &mut [f64]| {
                                    let end = g0 + oc.len();
                                    let mut g = g0;
                                    while g < end {
                                        let o = g / out_row_len;
                                        let w = g - o * out_row_len;
                                        let b = match cum_off.binary_search(&w) {
                                            Ok(i) => i,
                                            Err(i) => i - 1,
                                        };
                                        let (sl, bl) = blocks[b];
                                        let within = w - cum_off[b];
                                        let copy = (bl - within).min(end - g);
                                        let src_base = o * bl + within;
                                        let off = g - g0;
                                        oc[off..off + copy]
                                            .copy_from_slice(&sl[src_base..src_base + copy]);
                                        g += copy;
                                    }
                                };
                                out.par_chunks_mut(CHUNK)
                                    .enumerate()
                                    .for_each(|(ci, oc)| fill(ci * CHUNK, oc));
                            }
                            Some(out)
                        } else {
                            None
                        }
                    };
                    if let Some(out) = built {
                        return self.tensor_variable(out, out_shape, false);
                    }
                }
            }
        }
        // F32 mirror of the no-grad fast path above (the f64-only branch left f32 cat on the slow
        // tape path = clone-each-input + per-element unravel; ~250ms at [4000,4000]x2 f32). Borrow
        // the contiguous f32 inputs and parallel block-copy per outer slice. Bit-exact.
        let fast_ok_f32 = !inputs.is_empty()
            && inputs
                .iter()
                .all(|&id| matches!(self.tensor_requires_grad(id), Ok(false)))
            && inputs
                .iter()
                .all(|&id| matches!(self.tensor_dtype(id), Ok(DType::F32)));
        if fast_ok_f32 {
            let shapes: Vec<Vec<usize>> = inputs
                .iter()
                .map(|&id| self.tensor_shape(id))
                .collect::<Result<_, _>>()?;
            let rank = shapes[0].len();
            let shapes_ok = dim < rank
                && shapes.iter().all(|s| s.len() == rank)
                && shapes
                    .iter()
                    .all(|s| (0..rank).all(|d| d == dim || s[d] == shapes[0][d]));
            if shapes_ok {
                let inner: usize = shapes[0][dim + 1..].iter().product();
                let outer: usize = shapes[0][..dim].iter().product();
                let mids: Vec<usize> = shapes.iter().map(|s| s[dim]).collect();
                let total_mid: usize = mids.iter().sum();
                if inner > 0 && total_mid > 0 {
                    let mut out_shape = shapes[0].clone();
                    out_shape[dim] = total_mid;
                    let built = {
                        let tensors: Vec<_> = inputs
                            .iter()
                            .map(|&id| self.tensor_tape.tensor(id))
                            .collect::<Result<_, _>>()?;
                        if tensors.iter().all(|t| t.meta().is_contiguous()) {
                            let all_slices: Vec<&[f32]> = tensors
                                .iter()
                                .map(|t| t.contiguous_values_f32())
                                .collect::<Result<_, _>>()?;
                            use rayon::prelude::*;
                            let out_row_len = total_mid * inner;
                            // (slice, block_len) per NON-EMPTY input; skip mid==0 inputs
                            // (legal zero-size cat) so binary_search has no duplicate offsets.
                            let blocks: Vec<(&[f32], usize)> = all_slices
                                .iter()
                                .zip(mids.iter())
                                .filter(|&(_, &m)| m != 0)
                                .map(|(&sl, &m)| (sl, m * inner))
                                .collect();
                            // Cumulative element offset of each block within a row.
                            let cum_off: Vec<usize> = blocks
                                .iter()
                                .scan(0usize, |a, &(_, bl)| {
                                    let s = *a;
                                    *a += bl;
                                    Some(s)
                                })
                                .collect();
                            let mut out = vec![0.0_f32; outer * out_row_len];
                            const CHUNK: usize = 1 << 16;
                            if out_row_len == blocks.len() && inner == 1 {
                                // Interleave fast path (dstack / column_stack / stack-along-last-
                                // dim): every block is a SINGLE element, so the flat fill below
                                // degenerates to a per-element binary_search + division (out_row_len
                                // tiny, `outer` huge — measured ~67-100x SLOWER vs torch). Read
                                // block k's element straight into column k — no search, no division.
                                // Coarse outer chunks keep it parallel. Bit-identical.
                                let k = blocks.len();
                                let slices: Vec<&[f32]> =
                                    blocks.iter().map(|&(sl, _)| sl).collect();
                                let rows_per_task = (CHUNK / k).max(1);
                                out.par_chunks_mut(k * rows_per_task).enumerate().for_each(
                                    |(blk, chunk)| {
                                        let o0 = blk * rows_per_task;
                                        for (lr, row) in chunk.chunks_mut(k).enumerate() {
                                            let o = o0 + lr;
                                            for (kk, slot) in row.iter_mut().enumerate() {
                                                *slot = slices[kk][o];
                                            }
                                        }
                                    },
                                );
                            } else {
                                // Flat global-chunk fill: parallel for ANY outer (the old
                                // par_chunks_mut(out_row_len) made dim=0 / 1-D cat ONE chunk =
                                // SERIAL at ~2 GB/s first-touch-fault speed). Bit-identical.
                                let fill = |g0: usize, oc: &mut [f32]| {
                                    let end = g0 + oc.len();
                                    let mut g = g0;
                                    while g < end {
                                        let o = g / out_row_len;
                                        let w = g - o * out_row_len;
                                        let b = match cum_off.binary_search(&w) {
                                            Ok(i) => i,
                                            Err(i) => i - 1,
                                        };
                                        let (sl, bl) = blocks[b];
                                        let within = w - cum_off[b];
                                        let copy = (bl - within).min(end - g);
                                        let src_base = o * bl + within;
                                        let off = g - g0;
                                        oc[off..off + copy]
                                            .copy_from_slice(&sl[src_base..src_base + copy]);
                                        g += copy;
                                    }
                                };
                                out.par_chunks_mut(CHUNK)
                                    .enumerate()
                                    .for_each(|(ci, oc)| fill(ci * CHUNK, oc));
                            }
                            Some(out)
                        } else {
                            None
                        }
                    };
                    if let Some(out) = built {
                        return self.tensor_variable_f32(out, out_shape, false);
                    }
                }
            }
        }
        let (out, event) = self.tensor_tape.cat(inputs, dim, self.mode())?;
        self.record_tensor_join_operation(&event);
        Ok(out)
    }

    /// Alias for `tensor_cat`. Equivalent to `torch.concat`.
    pub fn tensor_concat(
        &mut self,
        inputs: &[TensorNodeId],
        dim: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_cat(inputs, dim)
    }

    /// Alias for `tensor_cat`. NumPy-style naming.
    pub fn tensor_concatenate(
        &mut self,
        inputs: &[TensorNodeId],
        dim: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_cat(inputs, dim)
    }

    pub fn tensor_stack(
        &mut self,
        inputs: &[TensorNodeId],
        dim: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        // No-grad fast path (sibling of tensor_cat): stack inserts a new dim of size
        // len(inputs); out[o, k, i] = input_k[o, i]. A CONTIGUOUS block copy of `inner`
        // elements per (outer slice, input). Borrow all inputs and parallelize over output
        // blocks (one cheap division per block). Bit-exact. Falls through unless all inputs
        // are no-grad, contiguous, identically-shaped F64.
        let fast_ok = !inputs.is_empty()
            && inputs
                .iter()
                .all(|&id| matches!(self.tensor_requires_grad(id), Ok(false)))
            && inputs
                .iter()
                .all(|&id| matches!(self.tensor_dtype(id), Ok(DType::F64)));
        if fast_ok {
            let shapes: Vec<Vec<usize>> = inputs
                .iter()
                .map(|&id| self.tensor_shape(id))
                .collect::<Result<_, _>>()?;
            let s0 = shapes[0].clone();
            if dim <= s0.len() && shapes.iter().all(|s| *s == s0) {
                let inner: usize = s0[dim..].iter().product();
                let outer: usize = s0[..dim].iter().product();
                let num = inputs.len();
                if inner > 0 {
                    let mut out_shape = s0[..dim].to_vec();
                    out_shape.push(num);
                    out_shape.extend_from_slice(&s0[dim..]);
                    let built = {
                        let tensors: Vec<_> = inputs
                            .iter()
                            .map(|&id| self.tensor_tape.tensor(id))
                            .collect::<Result<_, _>>()?;
                        if tensors.iter().all(|t| t.meta().is_contiguous()) {
                            let slices: Vec<&[f64]> = tensors
                                .iter()
                                .map(|t| t.contiguous_values())
                                .collect::<Result<_, _>>()?;
                            use rayon::prelude::*;
                            let total = outer * num * inner;
                            let mut out = vec![0.0_f64; total];
                            // Grain-based parallel copy: chunking by `inner` (one chunk per
                            // output block) under-parallelizes when there are few blocks but
                            // a huge `inner` (e.g. stack(dim=0) of 2 tensors = 2 blocks).
                            // Instead chunk into ~4x num_threads pieces; each resolves its
                            // source block by integer-div of its start (one division per
                            // boundary crossing, not per element) and copies up to each
                            // block boundary. Bit-exact (pure copy).
                            let threads = rayon::current_num_threads().max(1);
                            let grain = (total / (threads * 4)).max(1);
                            let fill = |ci: usize, chunk: &mut [_]| {
                                let mut out_off = ci * grain;
                                let mut written = 0usize;
                                while written < chunk.len() {
                                    let b = out_off / inner;
                                    let within = out_off % inner;
                                    let k = b % num;
                                    let o = b / num;
                                    let src_base = o * inner + within;
                                    let avail = (inner - within).min(chunk.len() - written);
                                    chunk[written..written + avail]
                                        .copy_from_slice(&slices[k][src_base..src_base + avail]);
                                    written += avail;
                                    out_off += avail;
                                }
                            };
                            // Pure copy: gate at the fault-parallelism crossover, not
                            // unconditionally (parallel copy regresses small/medium 2-14x).
                            // Bit-identical (serial==parallel output).
                            if total >= MOVEMENT_COPY_PARALLEL_MIN {
                                out.par_chunks_mut(grain)
                                    .enumerate()
                                    .for_each(|(ci, chunk)| fill(ci, chunk));
                            } else {
                                out.chunks_mut(grain)
                                    .enumerate()
                                    .for_each(|(ci, chunk)| fill(ci, chunk));
                            }
                            Some(out)
                        } else {
                            None
                        }
                    };
                    if let Some(out) = built {
                        return self.tensor_variable(out, out_shape, false);
                    }
                }
            }
        }
        let (out, event) = self.tensor_tape.stack(inputs, dim, self.mode())?;
        self.record_tensor_join_operation(&event);
        Ok(out)
    }

    pub fn tensor_reshape(
        &mut self,
        input: TensorNodeId,
        new_shape: Vec<usize>,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_tape.reshape(input, new_shape)
    }

    /// Reshape `input` to have the same shape as `other`.
    ///
    /// Equivalent to `torch.reshape(input, other.shape)` or
    /// `input.reshape_as(other)`. Element counts must match.
    pub fn tensor_reshape_as(
        &mut self,
        input: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let target_shape = self.tensor_shape(other)?;
        self.tensor_reshape(input, target_shape)
    }

    pub fn tensor_view(
        &mut self,
        input: TensorNodeId,
        new_shape: Vec<usize>,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_tape.view(input, new_shape)
    }

    /// View `input` with the same shape as `other`.
    ///
    /// Equivalent to `torch.Tensor.view_as(other)` — thin wrapper
    /// over `tensor_view` that takes a reference tensor instead of
    /// an explicit shape. Element counts must match (a strict view,
    /// not a broadcast). Tracked under frankentorch-0uc1.
    pub fn tensor_view_as(
        &mut self,
        input: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let other_shape = self.tensor_shape(other)?;
        self.tensor_view(input, other_shape)
    }

    /// Create a tensor with specified size and stride, reading from input storage.
    /// PyTorch's as_strided creates a view; FrankenTorch materializes a copy.
    pub fn tensor_as_strided(
        &mut self,
        input: TensorNodeId,
        size: Vec<usize>,
        stride: Vec<usize>,
        storage_offset: Option<usize>,
    ) -> Result<TensorNodeId, AutogradError> {
        if size.len() != stride.len() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "as_strided: size and stride must have same length",
                },
            )));
        }
        let offset = storage_offset.unwrap_or(0);
        let values = self.tensor_tape.values(input)?;
        let numel: usize = size.iter().product();
        let mut result = Vec::with_capacity(numel);

        fn index_to_offset(idx: usize, size: &[usize], stride: &[usize]) -> usize {
            let mut offset = 0;
            let mut remaining = idx;
            for (i, &dim_size) in size.iter().enumerate().rev() {
                let coord = remaining % dim_size;
                remaining /= dim_size;
                offset += coord * stride[i];
            }
            offset
        }

        for i in 0..numel {
            let src_idx = offset + index_to_offset(i, &size, &stride);
            if src_idx >= values.len() {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "as_strided: index out of bounds",
                    },
                )));
            }
            result.push(values[src_idx]);
        }
        self.tensor_variable(result, size, false)
    }

    pub fn tensor_squeeze(
        &mut self,
        input: TensorNodeId,
        dim: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_tape.squeeze(input, dim)
    }

    pub fn tensor_unsqueeze(
        &mut self,
        input: TensorNodeId,
        dim: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_tape.unsqueeze(input, dim)
    }

    /// `torch.unsqueeze(input, dim)` accepting a NEGATIVE `dim` counted from the
    /// end. Insertion is into a tensor of rank `rank+1`, so the valid range is
    /// `[-(rank+1), rank]` and a negative `dim` resolves to `dim + rank + 1`
    /// (e.g. `unsqueeze(x, -1)` appends a trailing size-1 axis). Pure reshape:
    /// bit-exact and autograd-aware.
    pub fn tensor_unsqueeze_dim(
        &mut self,
        input: TensorNodeId,
        dim: i64,
    ) -> Result<TensorNodeId, AutogradError> {
        let rank = self.tensor_shape(input)?.len();
        let bound = rank as i64 + 1; // unsqueeze can insert at position `rank`.
        let resolved = if dim < 0 { dim + bound } else { dim };
        if resolved < 0 || resolved >= bound {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "unsqueeze: dim out of range",
                },
            )));
        }
        self.tensor_unsqueeze(input, resolved as usize)
    }

    /// `torch.squeeze(input, dim)` accepting a NEGATIVE `dim` counted from the
    /// end (resolves to `dim + rank`). Pure reshape: bit-exact and
    /// autograd-aware.
    pub fn tensor_squeeze_neg_dim(
        &mut self,
        input: TensorNodeId,
        dim: i64,
    ) -> Result<TensorNodeId, AutogradError> {
        let rank = self.tensor_shape(input)?.len();
        let resolved = if dim < 0 { dim + rank as i64 } else { dim };
        if resolved < 0 || resolved as usize >= rank {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "squeeze: dim out of range",
                },
            )));
        }
        self.tensor_squeeze(input, resolved as usize)
    }

    pub fn tensor_transpose(
        &mut self,
        input: TensorNodeId,
        dim0: usize,
        dim1: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_tape.transpose(input, dim0, dim1)
    }

    /// Transpose the last two dimensions of `input`.
    ///
    /// Equivalent to `torch.Tensor.mT` and
    /// `torch.transpose(input, -2, -1)`. Works on any input of rank
    /// ≥ 2 — common in batched matmul code where the rank may not
    /// be known at the call site. Composes through autograd-aware
    /// tensor_transpose; gradient flows unchanged.
    /// Tracked under frankentorch-1mcj.
    pub fn tensor_matrix_transpose(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        if shape.len() < 2 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "matrix_transpose: input must have at least 2 dimensions",
                },
            )));
        }
        let last = shape.len() - 1;
        self.tensor_transpose(input, last - 1, last)
    }

    /// Transpose a 0-D, 1-D, or 2-D tensor.
    ///
    /// Equivalent to `torch.t(input)`. For 0-D and 1-D tensors returns
    /// the input unchanged; for 2-D tensors transposes dimensions 0 and
    /// 1. Errors on tensors with more than 2 dimensions.
    pub fn tensor_t(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        match shape.len() {
            0 | 1 => Ok(input),
            2 => self.tensor_transpose(input, 0, 1),
            _ => Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "t: input must have <= 2 dimensions",
                },
            ))),
        }
    }

    /// Conjugate transpose (Hermitian adjoint) of the last two dimensions.
    ///
    /// Equivalent to `torch.adjoint(input)`. For complex tensors this
    /// performs conjugation and transpose; for real tensors it is
    /// equivalent to `tensor_matrix_transpose`. Requires at least 2D.
    pub fn tensor_adjoint(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let transposed = self.tensor_matrix_transpose(input)?;
        let dtype = self.tensor_dtype(transposed)?;
        if dtype == DType::Complex64 || dtype == DType::Complex128 {
            self.tensor_conj(transposed)
        } else {
            Ok(transposed)
        }
    }

    /// Hermitian transpose; alias for `tensor_adjoint`.
    ///
    /// Equivalent to accessing `.H` on a tensor in PyTorch.
    #[allow(non_snake_case)]
    pub fn tensor_H(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        self.tensor_adjoint(input)
    }

    #[allow(non_snake_case)]
    pub fn tensor_mT(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        self.tensor_matrix_transpose(input)
    }

    #[allow(non_snake_case)]
    pub fn tensor_mH(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        self.tensor_adjoint(input)
    }

    /// 2-D tensor transpose property.
    ///
    /// Equivalent to `tensor.T` in PyTorch. For 2-D tensors, swaps dimensions.
    /// For 0-D and 1-D tensors, returns the input unchanged.
    #[allow(non_snake_case)]
    pub fn tensor_T(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        let ndim = shape.len();
        if ndim <= 1 {
            Ok(input)
        } else if ndim == 2 {
            self.tensor_transpose(input, 0, 1)
        } else {
            Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "tensor.T is only valid for tensors with <= 2 dimensions",
                },
            )))
        }
    }

    /// Copy variant of tensor.T.
    ///
    /// Equivalent to `tensor.t_copy()`.
    /// Since ft-api creates copies, this is identical to `tensor_T`.
    #[allow(non_snake_case)]
    pub fn tensor_t_copy(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        self.tensor_T(input)
    }

    /// Swap two dimensions; alias for `tensor_transpose`.
    ///
    /// Equivalent to `torch.swapaxes(input, dim0, dim1)`. PyTorch
    /// keeps both names for numpy compatibility (numpy uses
    /// `swapaxes`). Tracked under frankentorch-1qxf.
    pub fn tensor_swapaxes(
        &mut self,
        input: TensorNodeId,
        dim0: usize,
        dim1: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_transpose(input, dim0, dim1)
    }

    /// Swap two dimensions; alias for `tensor_transpose`.
    ///
    /// Equivalent to `torch.swapdims(input, dim0, dim1)`. PyTorch
    /// keeps swapaxes / swapdims as separate aliases for transpose.
    /// Tracked under frankentorch-1qxf.
    pub fn tensor_swapdims(
        &mut self,
        input: TensorNodeId,
        dim0: usize,
        dim1: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_transpose(input, dim0, dim1)
    }

    pub fn tensor_permute(
        &mut self,
        input: TensorNodeId,
        dims: Vec<usize>,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_tape.permute(input, dims)
    }

    pub fn tensor_flatten(
        &mut self,
        input: TensorNodeId,
        start_dim: usize,
        end_dim: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_tape.flatten(input, start_dim, end_dim)
    }

    /// `torch.flatten(input, start_dim=start_dim, end_dim=end_dim)` accepting
    /// NEGATIVE dims (counted from the end, like torch — whose default
    /// `end_dim` is `-1`). Resolves both endpoints against the input rank and
    /// delegates to [`Self::tensor_flatten`]. Pure reshape: bit-exact and
    /// autograd-aware. `flatten(x, 1, -1)` is the common "flatten all but the
    /// batch dim" form that previously needed the caller to compute `rank-1`.
    pub fn tensor_flatten_dims(
        &mut self,
        input: TensorNodeId,
        start_dim: i64,
        end_dim: i64,
    ) -> Result<TensorNodeId, AutogradError> {
        let rank = self.tensor_shape(input)?.len();
        let resolve = |d: i64| -> Result<usize, AutogradError> {
            let r = if d < 0 { d + rank as i64 } else { d };
            if r < 0 || r as usize >= rank {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "flatten: dim out of range",
                    },
                )));
            }
            Ok(r as usize)
        };
        let s = resolve(start_dim)?;
        let e = resolve(end_dim)?;
        if s > e {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "flatten: start_dim must be <= end_dim",
                },
            )));
        }
        self.tensor_flatten(input, s, e)
    }

    pub fn tensor_unflatten(
        &mut self,
        input: TensorNodeId,
        dim: usize,
        sizes: Vec<usize>,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_tape.unflatten(input, dim, sizes)
    }

    /// `torch.unflatten(input, dim, sizes)` accepting a NEGATIVE `dim` (counted
    /// from the end) and a single inferred `-1` entry in `sizes` (its size is
    /// `input.size(dim) / product(other sizes)`), matching torch. Pure reshape:
    /// bit-exact and autograd-aware.
    pub fn tensor_unflatten_dim(
        &mut self,
        input: TensorNodeId,
        dim: i64,
        sizes: &[i64],
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        let rank = shape.len();
        let d = if dim < 0 { dim + rank as i64 } else { dim };
        if d < 0 || d as usize >= rank {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "unflatten: dim out of range",
                },
            )));
        }
        let dim = d as usize;
        let dim_size = shape[dim];

        if sizes.is_empty() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "unflatten: sizes must be non-empty",
                },
            )));
        }
        // At most one -1 (inferred from the remaining product).
        let neg_count = sizes.iter().filter(|&&s| s == -1).count();
        if neg_count > 1 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "unflatten: only one dimension can be inferred (-1)",
                },
            )));
        }
        let mut known: usize = 1;
        for &s in sizes {
            if s == -1 {
                continue;
            }
            if s < 0 {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "unflatten: sizes must be positive (or a single -1)",
                    },
                )));
            }
            known = known.saturating_mul(s as usize);
        }
        let resolved: Vec<usize> = if neg_count == 1 {
            if known == 0 || dim_size % known != 0 {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "unflatten: inferred -1 does not divide the unflattened dim size",
                    },
                )));
            }
            let inferred = dim_size / known;
            sizes
                .iter()
                .map(|&s| if s == -1 { inferred } else { s as usize })
                .collect()
        } else {
            if known != dim_size {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "unflatten: sizes product must equal the unflattened dim size",
                    },
                )));
            }
            sizes.iter().map(|&s| s as usize).collect()
        };
        self.tensor_unflatten(input, dim, resolved)
    }

    /// Flatten a tensor to 1-D.
    ///
    /// Equivalent to `torch.ravel(input)` — returns a 1-D tensor
    /// containing all elements in row-major (C-contiguous) order.
    /// Empty input returns an empty 1-D tensor. Composes through
    /// autograd-aware tensor_flatten over the full rank.
    /// Tracked under frankentorch-icld.
    pub fn tensor_ravel(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        if shape.is_empty() {
            // 0-D scalar → 1-element 1-D tensor.
            return self.tensor_reshape(input, vec![1]);
        }
        let last_dim = shape.len() - 1;
        self.tensor_flatten(input, 0, last_dim)
    }

    /// In-place flatten.
    ///
    /// Equivalent to `tensor.flatten_(start_dim, end_dim)`.
    /// Since ft-api creates new nodes rather than views, this copies the
    /// flattened values back to the target tensor.
    pub fn tensor_flatten_(
        &mut self,
        target: TensorNodeId,
        start_dim: usize,
        end_dim: usize,
    ) -> Result<(), AutogradError> {
        self.validate_tensor_in_place_target(target)?;
        let result = self.tensor_flatten(target, start_dim, end_dim)?;
        let result_vals = self.tensor_values(result)?;
        self.update_tensor_values_for_float(target, result_vals, INPLACE_FLOAT_REASON)?;
        self.record_tensor_in_place_operation(
            "flatten_",
            target,
            Some(format!("start_dim={start_dim}, end_dim={end_dim}")),
        );
        Ok(())
    }

    /// Convert multi-dimensional indices to flat indices.
    ///
    /// Equivalent to `torch.ravel_multi_index(multi_index, dims)`.
    /// Takes a tensor of shape `(ndim, ...)` where each row contains
    /// indices for that dimension, and returns flat indices of shape `(...)`.
    ///
    /// Example: for dims=[2,3], indices [[0,1], [1,2]] -> [1, 5]
    /// i.e., (0,1) -> 0*3+1=1, (1,2) -> 1*3+2=5
    pub fn tensor_ravel_multi_index(
        &mut self,
        multi_index: TensorNodeId,
        dims: Vec<usize>,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(multi_index)?;
        if shape.is_empty() || shape[0] != dims.len() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "ravel_multi_index: first dim of multi_index must match dims length",
                },
            )));
        }
        let ndim = dims.len();
        let out_shape: Vec<usize> = shape[1..].to_vec();
        let out_size: usize = out_shape.iter().product();

        let strides: Vec<usize> = {
            let mut s = vec![1usize; ndim];
            for i in (0..ndim - 1).rev() {
                s[i] = s[i + 1] * dims[i + 1];
            }
            s
        };

        let strides_clone = strides.clone();
        self.tensor_apply_function(
            &[multi_index],
            move |_ctx, inputs| {
                let (vals, in_shape) = inputs[0];
                let ndim = in_shape[0];
                let n = in_shape[1..].iter().product::<usize>();
                let mut result = vec![0.0_f64; n];
                for i in 0..n {
                    let mut flat_idx = 0usize;
                    for d in 0..ndim {
                        let idx = vals[d * n + i] as usize;
                        flat_idx += idx * strides_clone[d];
                    }
                    result[i] = flat_idx as f64;
                }
                let out = if in_shape.len() == 1 {
                    vec![1]
                } else {
                    in_shape[1..].to_vec()
                };
                Ok((result, out))
            },
            move |_ctx, _grad_outputs| {
                // Index operations have undefined gradients
                let _ = out_size;
                Ok(vec![None])
            },
        )
    }

    /// Convert flat indices to multi-dimensional indices.
    ///
    /// Equivalent to `torch.unravel_index(indices, shape)`.
    /// Takes flat indices and returns a tuple of tensors, one per dimension,
    /// containing the multi-dimensional indices.
    pub fn tensor_unravel_index(
        &mut self,
        indices: TensorNodeId,
        shape: Vec<usize>,
    ) -> Result<Vec<TensorNodeId>, AutogradError> {
        let idx_shape = self.tensor_shape(indices)?;
        let ndim = shape.len();

        let strides: Vec<usize> = {
            let mut s = vec![1usize; ndim];
            for i in (0..ndim - 1).rev() {
                s[i] = s[i + 1] * shape[i + 1];
            }
            s
        };

        let mut result_tensors = Vec::with_capacity(ndim);
        for d in 0..ndim {
            let stride = strides[d];
            let dim_size = shape[d];
            let out_shape = idx_shape.clone();
            self.tensor_apply_function(
                &[indices],
                move |_ctx, inputs| {
                    let (vals, _in_shape) = inputs[0];
                    let result: Vec<f64> = vals
                        .iter()
                        .map(|&v| ((v as usize / stride) % dim_size) as f64)
                        .collect();
                    Ok((result, out_shape.clone()))
                },
                move |_ctx, _grad_outputs| {
                    // Index operations have undefined gradients
                    Ok(vec![None])
                },
            )
            .map(|t| result_tensors.push(t))?;
        }
        Ok(result_tensors)
    }

    /// Remove all size-1 dimensions from `input`.
    ///
    /// Equivalent to `torch.squeeze(input)` (no-dim variant). Removes
    /// every dimension whose size is 1, in any position. Composes
    /// through autograd-aware tensor_reshape with the size-1-stripped
    /// shape. Tracked under frankentorch-icld.
    pub fn tensor_squeeze_all(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        let new_shape: Vec<usize> = shape.iter().copied().filter(|&d| d != 1).collect();
        if new_shape == shape {
            // No 1-dims to strip — return unchanged.
            return Ok(input);
        }
        self.tensor_reshape(input, new_shape)
    }

    pub fn tensor_narrow(
        &mut self,
        input: TensorNodeId,
        dim: usize,
        start: usize,
        length: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_tape.narrow(input, dim, start, length)
    }

    /// Equivalent to `torch.narrow_copy`. Returns a contiguous copy of the
    /// narrowed tensor.
    ///
    /// In FrankenTorch, all tensors use value semantics (no aliasing views),
    /// so this is functionally identical to `tensor_narrow`. Provided for
    /// PyTorch API compatibility.
    pub fn tensor_narrow_copy(
        &mut self,
        input: TensorNodeId,
        dim: usize,
        start: usize,
        length: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        // In FrankenTorch tensors are already value-based; narrow doesn't
        // create aliases. contiguous() would be a no-op; just delegate.
        self.tensor_narrow(input, dim, start, length)
    }

    pub fn tensor_expand(
        &mut self,
        input: TensorNodeId,
        target_shape: Vec<usize>,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_tape.expand(input, target_shape)
    }

    /// Broadcast `input` to `target_shape` with full broadcasting rules.
    ///
    /// Equivalent to `torch.broadcast_to(input, shape)`. Differs from
    /// `tensor_expand` in two ways:
    ///   - accepts a target shape with HIGHER rank than input;
    ///     prepends size-1 dims on the left to match rank.
    ///   - validates broadcast compatibility per dim: each input dim
    ///     must be either 1 or exactly the target dim.
    ///
    /// Composes through autograd-aware tensor_reshape + tensor_expand,
    /// so gradients flow unchanged. Tracked under frankentorch-h2zt.
    pub fn tensor_broadcast_to(
        &mut self,
        input: TensorNodeId,
        target_shape: Vec<usize>,
    ) -> Result<TensorNodeId, AutogradError> {
        let input_shape = self.tensor_shape(input)?;
        if input_shape.len() > target_shape.len() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "broadcast_to: target rank must be >= input rank",
                },
            )));
        }
        let prefix = target_shape.len() - input_shape.len();
        // Validate each input dim is broadcast-compatible with the
        // corresponding (right-aligned) target dim.
        for (i, &in_dim) in input_shape.iter().enumerate() {
            let tgt_dim = target_shape[prefix + i];
            if in_dim != tgt_dim && in_dim != 1 {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                    ft_kernel_cpu::KernelError::ShapeMismatch {
                        lhs: input_shape.clone(),
                        rhs: target_shape.clone(),
                    },
                )));
            }
        }
        // Prepend size-1 dims to match target rank, then expand.
        let mut padded_shape = vec![1usize; prefix];
        padded_shape.extend_from_slice(&input_shape);
        let reshaped = if padded_shape == input_shape {
            input
        } else {
            self.tensor_reshape(input, padded_shape)?
        };
        self.tensor_expand(reshaped, target_shape)
    }

    /// Broadcast a list of tensors to a common shape.
    ///
    /// Equivalent to `torch.broadcast_tensors(*tensors)`. Computes
    /// the right-aligned per-dim broadcast of every input shape and
    /// returns each input broadcast to that joint shape via
    /// tensor_broadcast_to. Autograd-aware: the broadcast_to backward
    /// sums gradient over broadcasted dims, so each input's gradient
    /// flows back unaffected by sibling shapes. Tracked under
    /// frankentorch-j0yz.
    pub fn tensor_broadcast_tensors(
        &mut self,
        tensors: &[TensorNodeId],
    ) -> Result<Vec<TensorNodeId>, AutogradError> {
        if tensors.is_empty() {
            return Ok(Vec::new());
        }
        let mut joint_shape = self.tensor_shape(tensors[0])?;
        for &t in &tensors[1..] {
            let shape = self.tensor_shape(t)?;
            joint_shape = Self::broadcast_shape(&joint_shape, &shape)?;
        }
        let mut out = Vec::with_capacity(tensors.len());
        for &t in tensors {
            out.push(self.tensor_broadcast_to(t, joint_shape.clone())?);
        }
        Ok(out)
    }

    /// Compute the broadcast shape of multiple tensor shapes.
    ///
    /// Equivalent to `torch.broadcast_shapes(*shapes)`. Returns the shape
    /// that would result from broadcasting tensors of the given shapes together.
    /// Does not create any tensors - pure shape computation.
    pub fn tensor_broadcast_shapes(
        &self,
        tensors: &[TensorNodeId],
    ) -> Result<Vec<usize>, AutogradError> {
        if tensors.is_empty() {
            return Ok(Vec::new());
        }
        let mut joint_shape = self.tensor_shape(tensors[0])?;
        for &t in &tensors[1..] {
            let shape = self.tensor_shape(t)?;
            joint_shape = Self::broadcast_shape(&joint_shape, &shape)?;
        }
        Ok(joint_shape)
    }

    /// Indices of non-zero elements; alias for `tensor_nonzero`.
    ///
    /// Equivalent to `torch.argwhere(input)` — a numpy-compatible
    /// alias for `torch.nonzero(input)` that returns indices as a
    /// `[M, ndim]` 2-D non-grad tensor. Tracked under frankentorch-j0yz.
    pub fn tensor_argwhere(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        self.tensor_nonzero(input)
    }

    /// Broadcast `input` to match `other`'s shape.
    ///
    /// Equivalent to `torch.Tensor.expand_as(other)` — thin wrapper
    /// around `tensor_broadcast_to(input, other.shape)`. Tracked
    /// under frankentorch-h2zt.
    pub fn tensor_expand_as(
        &mut self,
        input: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let target_shape = self.tensor_shape(other)?;
        self.tensor_broadcast_to(input, target_shape)
    }

    pub fn tensor_split(
        &mut self,
        input: TensorNodeId,
        split_sizes: &[usize],
        dim: usize,
    ) -> Result<Vec<TensorNodeId>, AutogradError> {
        self.tensor_tape.split(input, split_sizes, dim)
    }

    pub fn tensor_chunk(
        &mut self,
        input: TensorNodeId,
        chunks: usize,
        dim: usize,
    ) -> Result<Vec<TensorNodeId>, AutogradError> {
        self.tensor_tape.chunk(input, chunks, dim)
    }

    /// `torch.split_with_sizes(input, split_sizes, dim)` parity
    /// alias for `tensor_split`. PyTorch exposes the named
    /// variant of split that mirrors the original argument name.
    /// Tracked under frankentorch-8uxl.
    pub fn tensor_split_with_sizes(
        &mut self,
        input: TensorNodeId,
        split_sizes: &[usize],
        dim: usize,
    ) -> Result<Vec<TensorNodeId>, AutogradError> {
        self.tensor_split(input, split_sizes, dim)
    }

    /// Split tensor into sections, allowing uneven splits.
    ///
    /// Equivalent to `numpy.array_split(ary, indices_or_sections, axis)`.
    /// Unlike tensor_chunk which requires even division, array_split handles
    /// cases where dim_size % sections != 0 by making first (dim_size % sections)
    /// chunks have one extra element.
    pub fn tensor_array_split(
        &mut self,
        input: TensorNodeId,
        sections: usize,
        dim: usize,
    ) -> Result<Vec<TensorNodeId>, AutogradError> {
        if sections == 0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "array_split: sections must be > 0",
                },
            )));
        }
        let shape = self.tensor_shape(input)?;
        let ndim = shape.len();
        if dim >= ndim {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::InvalidDimension { dim, ndim },
            )));
        }
        let dim_size = shape[dim];
        let base_size = dim_size / sections;
        let remainder = dim_size % sections;
        let mut split_sizes = Vec::with_capacity(sections);
        for i in 0..sections {
            if i < remainder {
                split_sizes.push(base_size + 1);
            } else {
                split_sizes.push(base_size);
            }
        }
        self.tensor_split(input, &split_sizes, dim)
    }

    /// `torch.unsafe_chunk(input, chunks, dim)` parity alias for
    /// `tensor_chunk`. In PyTorch the difference is that
    /// unsafe_chunk skips a runtime autograd safety check; in
    /// ft-api both go through the same tensor_tape path so they
    /// are equivalent. Tracked under frankentorch-8uxl.
    pub fn tensor_unsafe_chunk(
        &mut self,
        input: TensorNodeId,
        chunks: usize,
        dim: usize,
    ) -> Result<Vec<TensorNodeId>, AutogradError> {
        self.tensor_chunk(input, chunks, dim)
    }

    pub fn tensor_unbind(
        &mut self,
        input: TensorNodeId,
        dim: usize,
    ) -> Result<Vec<TensorNodeId>, AutogradError> {
        let shape = self.tensor_shape(input)?;
        let ndim = shape.len();
        if dim >= ndim {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::InvalidDimension { dim, ndim },
            )));
        }
        let dim_size = shape[dim];
        let mut results = Vec::with_capacity(dim_size);
        for i in 0..dim_size {
            let narrowed = self.tensor_narrow(input, dim, i, 1)?;
            let squeezed = self.tensor_squeeze(narrowed, dim)?;
            results.push(squeezed);
        }
        Ok(results)
    }

    pub fn tensor_meshgrid(
        &mut self,
        inputs: &[TensorNodeId],
    ) -> Result<Vec<TensorNodeId>, AutogradError> {
        if inputs.is_empty() {
            return Ok(Vec::new());
        }
        let mut sizes = Vec::with_capacity(inputs.len());
        for &id in inputs {
            let shape = self.tensor_shape(id)?;
            if shape.len() != 1 {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                    ft_kernel_cpu::KernelError::ShapeMismatch {
                        lhs: shape,
                        rhs: vec![0],
                    },
                )));
            }
            sizes.push(shape[0]);
        }
        let ndim = sizes.len();
        let mut results = Vec::with_capacity(ndim);
        for (i, &id) in inputs.iter().enumerate() {
            // Reshape to have size 1 in all dims except dim i
            let mut reshape_dims = vec![1; ndim];
            reshape_dims[i] = sizes[i];
            let reshaped = self.tensor_reshape(id, reshape_dims)?;
            // Expand to full grid shape
            let expanded = self.tensor_expand(reshaped, sizes.clone())?;
            results.push(expanded);
        }
        Ok(results)
    }

    /// Generates a normalized 2-D sampling grid from affine transforms.
    pub fn tensor_affine_grid(
        &mut self,
        theta: TensorNodeId,
        output_size: Vec<usize>,
        align_corners: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        if output_size.len() != 4 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "affine_grid: only 2-D output_size [N, C, H, W] is supported",
                },
            )));
        }

        let theta_tensor = self.tensor_tape.tensor(theta)?;
        let theta_meta = theta_tensor.meta().clone();
        if theta_meta.shape().len() != 3 || theta_meta.shape()[1] != 2 || theta_meta.shape()[2] != 3
        {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "affine_grid: theta must have shape [N, 2, 3]",
                },
            )));
        }

        let batch = output_size[0];
        let out_h = output_size[2];
        let out_w = output_size[3];
        if theta_meta.shape()[0] != batch {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "affine_grid: theta batch must match output_size batch",
                },
            )));
        }

        let output_shape = vec![batch, out_h, out_w, 2];
        let numel =
            Self::checked_shape_numel(&output_shape, "affine_grid output shape volume overflow")?;

        // Autograd path: tensor_apply_function computes in f64 and
        // materializes the output in theta's floating dtype. The
        // forward is linear in theta (each grid cell is
        // t00*x + t01*y + t02 / t10*x + t11*y + t12), so backward is
        // the same accumulator with grad_grid in place of the
        // constant 1. Tracked under frankentorch-bfj5 and extended to
        // F32 under frankentorch-8mrg.
        if self.tensor_tape.tensor_requires_grad(theta)? {
            if !matches!(
                theta_tensor.typed_storage(),
                TensorStorage::F32(_) | TensorStorage::F64(_) | TensorStorage::F64Inline4(_)
            ) {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "affine_grid: theta must be float32 or float64",
                    },
                )));
            }
            let out_h_c = out_h;
            let out_w_c = out_w;
            let batch_c = batch;
            let output_shape_c = output_shape.clone();
            let align_corners_c = align_corners;
            let out_id = self.tensor_apply_function(
                &[theta],
                move |_ctx, inputs| {
                    let (theta_vals, _shape) = inputs[0];
                    let mut grid = Vec::with_capacity(numel);
                    for n in 0..batch_c {
                        let base = n * 6;
                        let t00 = theta_vals[base];
                        let t01 = theta_vals[base + 1];
                        let t02 = theta_vals[base + 2];
                        let t10 = theta_vals[base + 3];
                        let t11 = theta_vals[base + 4];
                        let t12 = theta_vals[base + 5];
                        for h in 0..out_h_c {
                            let y = Self::affine_grid_axis_coordinate(h, out_h_c, align_corners_c);
                            for w in 0..out_w_c {
                                let x =
                                    Self::affine_grid_axis_coordinate(w, out_w_c, align_corners_c);
                                grid.push(t00 * x + t01 * y + t02);
                                grid.push(t10 * x + t11 * y + t12);
                            }
                        }
                    }
                    Ok((grid, output_shape_c.clone()))
                },
                move |_ctx, grad_outputs| {
                    let grad_grid = grad_outputs[0];
                    // grad_theta has shape [batch, 2, 3], flat layout.
                    let mut grad_theta = vec![0.0_f64; batch_c * 2 * 3];
                    for n in 0..batch_c {
                        let base = n * 6;
                        for h in 0..out_h_c {
                            let y = Self::affine_grid_axis_coordinate(h, out_h_c, align_corners_c);
                            for w in 0..out_w_c {
                                let x =
                                    Self::affine_grid_axis_coordinate(w, out_w_c, align_corners_c);
                                let cell = (n * out_h_c * out_w_c + h * out_w_c + w) * 2;
                                let g0 = grad_grid[cell];
                                let g1 = grad_grid[cell + 1];
                                grad_theta[base] += g0 * x;
                                grad_theta[base + 1] += g0 * y;
                                grad_theta[base + 2] += g0;
                                grad_theta[base + 3] += g1 * x;
                                grad_theta[base + 4] += g1 * y;
                                grad_theta[base + 5] += g1;
                            }
                        }
                    }
                    Ok(vec![Some(grad_theta)])
                },
            )?;
            self.runtime.ledger_mut().record(
                EvidenceKind::Dispatch,
                format!(
                    "affine_grid theta={} out={} align_corners={align_corners} (autograd)",
                    theta.0, out_id.0
                ),
            );
            return Ok(out_id);
        }

        match theta_tensor.typed_storage() {
            TensorStorage::F32(values) => {
                // Hoist the per-axis normalized coords: the old loop recomputed
                // `affine_grid_axis_coordinate` (an int->f64 divide) for EVERY cell — out_h*
                // out_w*batch divides. Precompute the out_w x-coords + out_h y-coords ONCE,
                // then index them. ~2.4x: the op was compute-bound on those divides; hoisting
                // makes it bandwidth-bound on the grid write. Bit-identical (same per-cell f64
                // math + f32 cast). (A rayon pass over the rows measured ~0-gain — the write
                // is already bandwidth-saturated single-threaded — so it stays serial.)
                // frankentorch-affgridhoist.
                let theta6: Vec<f64> = (0..batch * 6).map(|i| f64::from(values[i])).collect();
                let xs: Vec<f64> = (0..out_w)
                    .map(|w| Self::affine_grid_axis_coordinate(w, out_w, align_corners))
                    .collect();
                let ys: Vec<f64> = (0..out_h)
                    .map(|h| Self::affine_grid_axis_coordinate(h, out_h, align_corners))
                    .collect();
                let mut grid = vec![0.0_f32; numel];
                let fill = |r: usize, row: &mut [f32]| {
                    let n = r / out_h;
                    let h = r % out_h;
                    let base = n * 6;
                    let (t00, t01, t02, t10, t11, t12) = (
                        theta6[base],
                        theta6[base + 1],
                        theta6[base + 2],
                        theta6[base + 3],
                        theta6[base + 4],
                        theta6[base + 5],
                    );
                    let y = ys[h];
                    for w in 0..out_w {
                        let x = xs[w];
                        row[w * 2] = (t00 * x + t01 * y + t02) as f32;
                        row[w * 2 + 1] = (t10 * x + t11 * y + t12) as f32;
                    }
                };
                grid.chunks_mut(out_w * 2)
                    .enumerate()
                    .for_each(|(r, row)| fill(r, row));
                let out = self.tensor_tape.leaf_tensor(
                    DenseTensor::from_typed_storage(
                        TensorMeta::from_shape(output_shape, DType::F32, theta_meta.device()),
                        TensorStorage::F32(Arc::new(grid)),
                    )?,
                    false,
                );
                self.runtime.ledger_mut().record(
                    EvidenceKind::Dispatch,
                    format!(
                        "affine_grid theta={} out={} align_corners={align_corners}",
                        theta.0, out.0
                    ),
                );
                Ok(out)
            }
            TensorStorage::F64(values) => {
                // Hoist per-axis coords (see the F32 arm): precompute out_w x-coords +
                // out_h y-coords once instead of recomputing the divide per cell.
                // Bit-identical to the serial push loop. frankentorch-affgridhoist.
                let theta6: Vec<f64> = (0..batch * 6).map(|i| values[i]).collect();
                let xs: Vec<f64> = (0..out_w)
                    .map(|w| Self::affine_grid_axis_coordinate(w, out_w, align_corners))
                    .collect();
                let ys: Vec<f64> = (0..out_h)
                    .map(|h| Self::affine_grid_axis_coordinate(h, out_h, align_corners))
                    .collect();
                let mut grid = vec![0.0_f64; numel];
                let fill = |r: usize, row: &mut [f64]| {
                    let n = r / out_h;
                    let h = r % out_h;
                    let base = n * 6;
                    let (t00, t01, t02, t10, t11, t12) = (
                        theta6[base],
                        theta6[base + 1],
                        theta6[base + 2],
                        theta6[base + 3],
                        theta6[base + 4],
                        theta6[base + 5],
                    );
                    let y = ys[h];
                    for w in 0..out_w {
                        let x = xs[w];
                        row[w * 2] = t00 * x + t01 * y + t02;
                        row[w * 2 + 1] = t10 * x + t11 * y + t12;
                    }
                };
                grid.chunks_mut(out_w * 2)
                    .enumerate()
                    .for_each(|(r, row)| fill(r, row));
                let out = self.tensor_tape.leaf_tensor(
                    DenseTensor::from_typed_storage(
                        TensorMeta::from_shape(output_shape, DType::F64, theta_meta.device()),
                        TensorStorage::F64(Arc::new(grid)),
                    )?,
                    false,
                );
                self.runtime.ledger_mut().record(
                    EvidenceKind::Dispatch,
                    format!(
                        "affine_grid theta={} out={} align_corners={align_corners}",
                        theta.0, out.0
                    ),
                );
                Ok(out)
            }
            TensorStorage::F64Inline4(values) => {
                // Hoist per-axis coords (see the F32 arm): precompute out_w x-coords +
                // out_h y-coords once instead of recomputing the divide per cell.
                // Bit-identical to the serial push loop. frankentorch-affgridhoist.
                let theta6: Vec<f64> = (0..batch * 6).map(|i| values[i]).collect();
                let xs: Vec<f64> = (0..out_w)
                    .map(|w| Self::affine_grid_axis_coordinate(w, out_w, align_corners))
                    .collect();
                let ys: Vec<f64> = (0..out_h)
                    .map(|h| Self::affine_grid_axis_coordinate(h, out_h, align_corners))
                    .collect();
                let mut grid = vec![0.0_f64; numel];
                let fill = |r: usize, row: &mut [f64]| {
                    let n = r / out_h;
                    let h = r % out_h;
                    let base = n * 6;
                    let (t00, t01, t02, t10, t11, t12) = (
                        theta6[base],
                        theta6[base + 1],
                        theta6[base + 2],
                        theta6[base + 3],
                        theta6[base + 4],
                        theta6[base + 5],
                    );
                    let y = ys[h];
                    for w in 0..out_w {
                        let x = xs[w];
                        row[w * 2] = t00 * x + t01 * y + t02;
                        row[w * 2 + 1] = t10 * x + t11 * y + t12;
                    }
                };
                grid.chunks_mut(out_w * 2)
                    .enumerate()
                    .for_each(|(r, row)| fill(r, row));
                let out = self.tensor_tape.leaf_tensor(
                    DenseTensor::from_typed_storage(
                        TensorMeta::from_shape(output_shape, DType::F64, theta_meta.device()),
                        TensorStorage::F64(Arc::new(grid)),
                    )?,
                    false,
                );
                self.runtime.ledger_mut().record(
                    EvidenceKind::Dispatch,
                    format!(
                        "affine_grid theta={} out={} align_corners={align_corners}",
                        theta.0, out.0
                    ),
                );
                Ok(out)
            }
            _ => Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "affine_grid: theta must be float32 or float64",
                },
            ))),
        }
    }

    /// Samples a 4-D `NCHW` input using a normalized 2-D grid.
    pub fn tensor_grid_sample(
        &mut self,
        input: TensorNodeId,
        grid: TensorNodeId,
        mode: GridSampleMode,
        padding_mode: GridSamplePaddingMode,
        align_corners: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        let input_tensor = self.tensor_tape.tensor(input)?;
        let grid_tensor = self.tensor_tape.tensor(grid)?;
        let input_meta = input_tensor.meta().clone();
        let grid_meta = grid_tensor.meta().clone();

        if input_meta.shape().len() != 4 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "grid_sample: only 4-D input [N, C, H, W] is supported",
                },
            )));
        }
        if grid_meta.shape().len() != 4 || grid_meta.shape()[3] != 2 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "grid_sample: grid must have shape [N, H, W, 2]",
                },
            )));
        }

        let batch = input_meta.shape()[0];
        let channels = input_meta.shape()[1];
        let in_h = input_meta.shape()[2];
        let in_w = input_meta.shape()[3];
        let out_batch = grid_meta.shape()[0];
        let out_h = grid_meta.shape()[1];
        let out_w = grid_meta.shape()[2];
        if batch != out_batch {
            // Surface both full shapes so the caller can see
            // which batch sizes were given (frankentorch-p947).
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: input_meta.shape().to_vec(),
                    rhs: grid_meta.shape().to_vec(),
                },
            )));
        }

        let grid_values = match grid_tensor.typed_storage() {
            TensorStorage::F32(values) => values.iter().map(|&v| f64::from(v)).collect::<Vec<_>>(),
            TensorStorage::F64(values) => values.as_ref().clone(),
            TensorStorage::F64Inline4(values) => values.to_vec(),
            _ => {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "grid_sample: grid must be float32 or float64",
                    },
                )));
            }
        };

        let output_shape = vec![batch, channels, out_h, out_w];
        let plan = GridSamplePlan {
            batch,
            channels,
            in_h,
            in_w,
            out_h,
            out_w,
            mode,
            padding_mode,
            align_corners,
        };

        let input_requires_grad = self.tensor_tape.tensor_requires_grad(input)?;
        let grid_requires_grad = self.tensor_tape.tensor_requires_grad(grid)?;
        if input_requires_grad || grid_requires_grad {
            let matching_float_dtype = matches!(
                (input_tensor.typed_storage(), grid_tensor.typed_storage()),
                (TensorStorage::F32(_), TensorStorage::F32(_))
                    | (TensorStorage::F64(_), TensorStorage::F64(_))
                    | (TensorStorage::F64Inline4(_), TensorStorage::F64(_))
                    | (TensorStorage::F64(_), TensorStorage::F64Inline4(_))
                    | (TensorStorage::F64Inline4(_), TensorStorage::F64Inline4(_))
            );
            if !matching_float_dtype {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "grid_sample: autograd requires matching f32 or f64 input and grid tensors",
                    },
                )));
            }

            let plan_c = plan;
            let output_shape_c = output_shape.clone();
            let out = self.tensor_apply_function(
                &[input, grid],
                move |ctx, inputs| {
                    let (input_values, input_shape) = inputs[0];
                    let (grid_values, grid_shape) = inputs[1];
                    let output = Self::grid_sample_f64(input_values, grid_values, plan_c);
                    ctx.save_for_backward(input_values.to_vec(), input_shape.to_vec());
                    ctx.save_for_backward(grid_values.to_vec(), grid_shape.to_vec());
                    Ok((output, output_shape_c.clone()))
                },
                move |ctx, grad_outputs| {
                    let saved = ctx.saved_tensors();
                    let input_values = &saved[0];
                    let grid_values = &saved[1];
                    let (grad_input, grad_grid) = match plan_c.mode {
                        GridSampleMode::Bilinear => Self::grid_sample_bilinear_backward_f64(
                            input_values,
                            grid_values,
                            grad_outputs[0],
                            plan_c,
                        )?,
                        GridSampleMode::Nearest => Self::grid_sample_nearest_backward_f64(
                            input_values,
                            grid_values,
                            grad_outputs[0],
                            plan_c,
                        )?,
                    };
                    Ok(vec![Some(grad_input), Some(grad_grid)])
                },
            )?;
            self.runtime.ledger_mut().record(
                EvidenceKind::Dispatch,
                format!(
                    "grid_sample input={} grid={} out={} mode={mode:?} padding={padding_mode:?} align_corners={align_corners} (autograd)",
                    input.0, grid.0, out.0
                ),
            );
            return Ok(out);
        }

        match input_tensor.typed_storage() {
            TensorStorage::F32(values) => {
                // Gather f32 storage DIRECTLY (grid_sample_f64 is generic; math stays f64 so the
                // result is bit-identical to the prior convert-to-f64-then-sample path) — skips the
                // whole-input f32->f64 conversion and halves the cache-miss gather traffic.
                let output = Self::grid_sample_f64(values.as_ref(), &grid_values, plan);
                let out = self.tensor_tape.leaf_tensor(
                    DenseTensor::from_typed_storage(
                        TensorMeta::from_shape(output_shape, DType::F32, input_meta.device()),
                        TensorStorage::F32(Arc::new(
                            output.into_iter().map(|v| v as f32).collect(),
                        )),
                    )?,
                    false,
                );
                self.runtime.ledger_mut().record(
                    EvidenceKind::Dispatch,
                    format!(
                        "grid_sample input={} grid={} out={} mode={mode:?} padding={padding_mode:?} align_corners={align_corners}",
                        input.0, grid.0, out.0
                    ),
                );
                Ok(out)
            }
            TensorStorage::F64(values) => {
                let output = Self::grid_sample_f64(values.as_ref(), &grid_values, plan);
                let out = self.tensor_tape.leaf_tensor(
                    DenseTensor::from_typed_storage(
                        TensorMeta::from_shape(output_shape, DType::F64, input_meta.device()),
                        TensorStorage::F64(Arc::new(output)),
                    )?,
                    false,
                );
                self.runtime.ledger_mut().record(
                    EvidenceKind::Dispatch,
                    format!(
                        "grid_sample input={} grid={} out={} mode={mode:?} padding={padding_mode:?} align_corners={align_corners}",
                        input.0, grid.0, out.0
                    ),
                );
                Ok(out)
            }
            TensorStorage::F64Inline4(values) => {
                let output = Self::grid_sample_f64(values.as_slice(), &grid_values, plan);
                let out = self.tensor_tape.leaf_tensor(
                    DenseTensor::from_typed_storage(
                        TensorMeta::from_shape(output_shape, DType::F64, input_meta.device()),
                        TensorStorage::F64(Arc::new(output)),
                    )?,
                    false,
                );
                self.runtime.ledger_mut().record(
                    EvidenceKind::Dispatch,
                    format!(
                        "grid_sample input={} grid={} out={} mode={mode:?} padding={padding_mode:?} align_corners={align_corners}",
                        input.0, grid.0, out.0
                    ),
                );
                Ok(out)
            }
            _ => Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "grid_sample: input must be float32 or float64",
                },
            ))),
        }
    }

    /// Diagonal of a matrix along its last two dimensions. Equivalent to
    /// `torch.linalg.diagonal(A, offset=offset)` (whose default `dim1=-2,
    /// dim2=-1` matches `tensor_diagonal`'s last-two-dim convention).
    pub fn tensor_linalg_diagonal(
        &mut self,
        input: TensorNodeId,
        offset: i64,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_diagonal(input, offset)
    }

    pub fn tensor_diagonal(
        &mut self,
        input: TensorNodeId,
        offset: i64,
    ) -> Result<TensorNodeId, AutogradError> {
        let dtype = self.tensor_dtype(input)?;
        if !matches!(dtype, DType::F64 | DType::F32 | DType::F16 | DType::BF16) {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "tensor_diagonal requires a float tensor",
                },
            )));
        }
        let shape = self.tensor_shape(input)?;
        if shape.len() != 2 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::InvalidDimension {
                    dim: shape.len(),
                    ndim: 2,
                },
            )));
        }
        let m = shape[0];
        let n = shape[1];
        // Out-of-range offsets yield an empty diagonal (diag_len = 0). The
        // index_select below with empty indices produces a [0] tensor of the
        // input dtype, so no per-dtype early-return is needed — and f16/bf16 now
        // gather correctly through index_select. frankentorch-u78p.
        let (row_start, col_start, diag_len) = if offset >= 0 {
            let col_start = offset as usize;
            if col_start >= n {
                (0, 0, 0)
            } else {
                (0, col_start, m.min(n - col_start))
            }
        } else {
            let row_start = (-offset) as usize;
            if row_start >= m {
                (0, 0, 0)
            } else {
                (row_start, 0, n.min(m - row_start))
            }
        };
        let flat_len = Self::checked_mul(m, n, "tensor_diagonal input shape overflow")?;
        // No-grad f64 fast path: read the diag_len strided diagonal elements DIRECTLY, avoiding the
        // reshape([m*n]) below — which materialises (clones) the whole m*n storage — plus the
        // index_select gather, just to keep diag_len elements. Bit-identical (same diagonal values,
        // same f64 dtype, same no-grad leaf). Falls through for grad / non-f64 / non-contiguous.
        if diag_len > 0 && dtype == DType::F64 && !self.tensor_tape.tensor_requires_grad(input)? {
            let fast = {
                let tensor = self.tensor_tape.tensor(input)?;
                if tensor.meta().is_contiguous() {
                    let vals = tensor.contiguous_values()?;
                    if vals.len() == flat_len {
                        let mut out = vec![0.0_f64; diag_len];
                        for (i, slot) in out.iter_mut().enumerate() {
                            *slot = vals[(row_start + i) * n + col_start + i];
                        }
                        Some(out)
                    } else {
                        None
                    }
                } else {
                    None
                }
            };
            if let Some(out) = fast {
                return self.tensor_variable(out, vec![diag_len], false);
            }
        }
        // Same lever for f32 (the asymmetric-dtype gap): f64 reads the diagonal directly above,
        // but f32 fell through to reshape (which clones the whole m*n storage) + index_select —
        // O(m*n) work + a 2nd gather to keep diag_len elements. Read the diag_len strided f32
        // elements DIRECTLY instead. Bit-identical (same diagonal values, same f32 no-grad leaf).
        // frankentorch-specf32.
        if diag_len > 0 && dtype == DType::F32 && !self.tensor_tape.tensor_requires_grad(input)? {
            let fast = {
                let tensor = self.tensor_tape.tensor(input)?;
                if tensor.meta().is_contiguous() {
                    let vals = tensor.contiguous_values_f32()?;
                    if vals.len() == flat_len {
                        let mut out = vec![0.0_f32; diag_len];
                        for (i, slot) in out.iter_mut().enumerate() {
                            *slot = vals[(row_start + i) * n + col_start + i];
                        }
                        Some(out)
                    } else {
                        None
                    }
                } else {
                    None
                }
            };
            if let Some(out) = fast {
                return self.tensor_variable_f32(out, vec![diag_len], false);
            }
        }
        // Extract diagonal elements by gathering flat indices. This composes
        // through reshape + index_select, so dtype and autograd behavior are
        // inherited from the shared tape path for f64/f32/f16/bf16.
        let flat = self.tensor_reshape(input, vec![flat_len])?;
        let indices: Vec<f64> = (0..diag_len)
            .map(|i| ((row_start + i) * n + col_start + i) as f64)
            .collect();
        let index_node = self.tensor_variable(indices, vec![diag_len], false)?;
        self.tensor_index_select(flat, 0, index_node)
    }

    /// Copy variant of diagonal.
    ///
    /// Equivalent to `tensor.diagonal_copy(offset)`.
    /// Since ft-api creates copies, this is identical to `tensor_diagonal`.
    pub fn tensor_diagonal_copy(
        &mut self,
        input: TensorNodeId,
        offset: i64,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_diagonal(input, offset)
    }

    /// Embed values from src into the diagonal of input.
    ///
    /// Equivalent to `torch.diagonal_scatter(input, src, offset)`.
    /// Returns a copy of input with the diagonal replaced by src values.
    /// Tracked under frankentorch-ac92.
    pub fn tensor_diagonal_scatter(
        &mut self,
        input: TensorNodeId,
        src: TensorNodeId,
        offset: i64,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        if shape.len() != 2 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "diagonal_scatter: input must be 2-D",
                },
            )));
        }
        let m = shape[0];
        let n = shape[1];

        let (row_start, col_start, diag_len) = if offset >= 0 {
            let col_start = offset as usize;
            if col_start >= n {
                return Ok(input);
            }
            let diag_len = m.min(n - col_start);
            (0, col_start, diag_len)
        } else {
            let row_start = (-offset) as usize;
            if row_start >= m {
                return Ok(input);
            }
            let diag_len = n.min(m - row_start);
            (row_start, 0, diag_len)
        };

        let src_len = self.tensor_shape(src)?.iter().product::<usize>();
        if src_len != diag_len {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "diagonal_scatter: src length must match diagonal length",
                },
            )));
        }

        if self.tensor_requires_grad(input)? || self.tensor_requires_grad(src)? {
            // diagonal_scatter copies `input` and overwrites the `offset`-diagonal
            // with `src`. So the gradient splits: grad flows to `input` everywhere
            // except the overwritten diagonal (zeroed there), and to `src` from the
            // diagonal positions. Forward is identical to the non-grad path → value
            // bit-identical; only the severed gradient is restored. frankentorch-avfl.
            return self.tensor_apply_function(
                &[input, src],
                move |_ctx, inputs| {
                    let (in_vals, in_shape) = inputs[0];
                    let (src_vals, _src_shape) = inputs[1];
                    let mut result = in_vals.to_vec();
                    for (i, &value) in src_vals.iter().enumerate() {
                        result[(row_start + i) * n + col_start + i] = value;
                    }
                    Ok((result, in_shape.to_vec()))
                },
                move |_ctx, grad_outputs| {
                    let g = grad_outputs[0];
                    let mut grad_input = g.to_vec();
                    let mut grad_src = vec![0.0_f64; diag_len];
                    for (i, gs) in grad_src.iter_mut().enumerate() {
                        let idx = (row_start + i) * n + col_start + i;
                        *gs = g[idx];
                        grad_input[idx] = 0.0;
                    }
                    Ok(vec![Some(grad_input), Some(grad_src)])
                },
            );
        }

        // No-grad f32 fast path (correctness + dtype): the f64 reads below are F64-only and
        // ERROR on f32 storage — no-grad f32 diagonal_scatter crashed. diagonal_scatter is pure
        // movement (copy input, overwrite the offset-diagonal with src), so reading natively in
        // f32 is bit-identical and returns the correct F32 dtype.
        if !self.tensor_requires_grad(input)?
            && !self.tensor_requires_grad(src)?
            && self.tensor_dtype(input)? == DType::F32
        {
            let mut result = self.tensor_tape.values_f32(input)?;
            let src_vals = self.tensor_tape.values_f32(src)?;
            for (i, &value) in src_vals.iter().enumerate() {
                let idx = (row_start + i) * n + col_start + i;
                result[idx] = value;
            }
            return self.tensor_variable_f32(result, shape, false);
        }

        let src_vals = self.tensor_values(src)?;
        let numel = Self::checked_shape_numel(&shape, "diagonal_scatter: shape volume overflow")?;
        // Build the base output by BORROWING input + a PARALLEL copy (the old `tensor_values(input)`
        // is a serial to_vec whose page first-touch is the wall for large numel), then overwrite the
        // offset diagonal. Bit-identical (the diagonal overwrites the same positions). Non-contiguous
        // / non-f64 / small fall back to the serial clone. Mirrors slice_scatter (dc96043a).
        let mut result = {
            let is_f64_contig = self.tensor_dtype(input)? == DType::F64
                && self.tensor_tape.tensor(input)?.meta().is_contiguous();
            if is_f64_contig && numel >= MOVEMENT_COPY_PARALLEL_MIN {
                let in_vals = self.tensor_tape.tensor(input)?.contiguous_values()?;
                let mut out = vec![0.0_f64; numel];
                use rayon::prelude::*;
                out.par_chunks_mut(1 << 16)
                    .zip(in_vals.par_chunks(1 << 16))
                    .for_each(|(o, i)| o.copy_from_slice(i));
                out
            } else {
                self.tensor_values(input)?
            }
        };
        for (i, &value) in src_vals.iter().enumerate() {
            let idx = (row_start + i) * n + col_start + i;
            result[idx] = value;
        }

        self.tensor_variable(result, shape, false)
    }

    /// Extract lower triangular part of a 2D matrix.
    ///
    /// Equivalent to `torch.tril(input, diagonal)`.
    /// Elements above the k-th diagonal are zeroed.
    /// Tracked under frankentorch-avfl.
    pub fn tensor_tril(
        &mut self,
        input: TensorNodeId,
        diagonal: i64,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        if shape.len() != 2 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "tril: input must be a 2-D tensor",
                },
            )));
        }

        let (m, n) = (shape[0], shape[1]);
        let dtype = self.tensor_dtype(input)?;
        // F32 no-grad fast path: apply_function below reads f32 as f64 (upcast clone) +
        // writes an f64 result + narrows back to f32 = ~5x memory traffic, measured ~11x
        // SLOWER than torch at [4000,4000]. tril is a pure positional select (keep src[j]
        // for j <= i+diagonal, else 0.0) with NO rounding, so an f32-native per-row fill is
        // BIT-IDENTICAL (kept values are the exact f32 inputs; the f64 round-trip is exact).
        // frankentorch-kgs4.180.
        if !self.tensor_requires_grad(input)? && dtype == DType::F32 {
            let built = {
                let it = self.tensor_tape.tensor(input)?;
                if it.meta().is_contiguous() {
                    let vals = it.contiguous_values_f32()?;
                    let mut result = vec![0.0f32; m * n];
                    let fill = |i: usize, row: &mut [f32]| {
                        let lim = (i as i64) + diagonal;
                        let src = &vals[i * n..i * n + n];
                        for (j, slot) in row.iter_mut().enumerate() {
                            if (j as i64) <= lim {
                                *slot = src[j];
                            }
                        }
                    };
                    if m * n >= PARALLEL_ELEMENTWISE_MIN && m > 1 {
                        use rayon::prelude::*;
                        result
                            .par_chunks_mut(n)
                            .enumerate()
                            .for_each(|(i, row)| fill(i, row));
                    } else {
                        for (i, row) in result.chunks_mut(n).enumerate() {
                            fill(i, row);
                        }
                    }
                    Some(result)
                } else {
                    None
                }
            };
            if let Some(result) = built {
                return self.tensor_variable_f32(result, vec![m, n], false);
            }
        }
        // tril keeps positions j <= i + diagonal and zeros the rest; its gradient
        // applies the same mask. apply_function handles both grad and non-grad in
        // one path (the old non-grad branch read f64-only values and errored on
        // f32/f16). The explicit 0.0 (not a mask-multiply) keeps torch semantics
        // for NaN/inf/-0.0 in zeroed positions. The f64 result is narrowed back to
        // the input dtype so f16/bf16/f32 are preserved. frankentorch-u78p (was
        // frankentorch-avfl for the grad restore).
        let out = self.tensor_apply_function(
            &[input],
            move |_ctx, inputs| {
                let (vals, _shape) = inputs[0];
                let mut result = vec![0.0_f64; m * n];
                // tril mask is per-row independent (row i keeps j <= i+diagonal) → parallelize
                // over rows. Bit-identical to the serial nested loop (same values, indexed write).
                let fill = |i: usize, row: &mut [f64]| {
                    let lim = (i as i64) + diagonal;
                    let src = &vals[i * n..i * n + n];
                    for (j, slot) in row.iter_mut().enumerate() {
                        if (j as i64) <= lim {
                            *slot = src[j];
                        }
                    }
                };
                if m * n >= PARALLEL_ELEMENTWISE_MIN && m > 1 {
                    use rayon::prelude::*;
                    result
                        .par_chunks_mut(n)
                        .enumerate()
                        .for_each(|(i, row)| fill(i, row));
                } else {
                    for (i, row) in result.chunks_mut(n).enumerate() {
                        fill(i, row);
                    }
                }
                Ok((result, vec![m, n]))
            },
            move |_ctx, grad_outputs| {
                let g = grad_outputs[0];
                let mut grad_in = vec![0.0_f64; m * n];
                let fill = |i: usize, row: &mut [f64]| {
                    let lim = (i as i64) + diagonal;
                    let src = &g[i * n..i * n + n];
                    for (j, slot) in row.iter_mut().enumerate() {
                        if (j as i64) <= lim {
                            *slot = src[j];
                        }
                    }
                };
                if m * n >= PARALLEL_ELEMENTWISE_MIN && m > 1 {
                    use rayon::prelude::*;
                    grad_in
                        .par_chunks_mut(n)
                        .enumerate()
                        .for_each(|(i, row)| fill(i, row));
                } else {
                    for (i, row) in grad_in.chunks_mut(n).enumerate() {
                        fill(i, row);
                    }
                }
                Ok(vec![Some(grad_in)])
            },
        )?;
        match dtype {
            DType::F16 | DType::BF16 | DType::F32 => self.tensor_tape.to_dtype(out, dtype),
            _ => Ok(out),
        }
    }

    /// Extract upper triangular part of a 2D matrix.
    ///
    /// Equivalent to `torch.triu(input, diagonal)`.
    /// Elements below the k-th diagonal are zeroed.
    /// Tracked under frankentorch-avfl.
    pub fn tensor_triu(
        &mut self,
        input: TensorNodeId,
        diagonal: i64,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        if shape.len() != 2 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "triu: input must be a 2-D tensor",
                },
            )));
        }

        let (m, n) = (shape[0], shape[1]);
        let dtype = self.tensor_dtype(input)?;
        // F32 no-grad fast path: sibling of the tril fast path (apply_function upcasts f32->f64
        // + narrows = ~11x SLOWER than torch). triu keeps src[j] for j >= i+diagonal else 0.0 =
        // pure positional select -> f32-native per-row fill is BIT-IDENTICAL. frankentorch-kgs4.180.
        if !self.tensor_requires_grad(input)? && dtype == DType::F32 {
            let built = {
                let it = self.tensor_tape.tensor(input)?;
                if it.meta().is_contiguous() {
                    let vals = it.contiguous_values_f32()?;
                    let mut result = vec![0.0f32; m * n];
                    let fill = |i: usize, row: &mut [f32]| {
                        let lim = (i as i64) + diagonal;
                        let src = &vals[i * n..i * n + n];
                        for (j, slot) in row.iter_mut().enumerate() {
                            if (j as i64) >= lim {
                                *slot = src[j];
                            }
                        }
                    };
                    if m * n >= PARALLEL_ELEMENTWISE_MIN && m > 1 {
                        use rayon::prelude::*;
                        result
                            .par_chunks_mut(n)
                            .enumerate()
                            .for_each(|(i, row)| fill(i, row));
                    } else {
                        for (i, row) in result.chunks_mut(n).enumerate() {
                            fill(i, row);
                        }
                    }
                    Some(result)
                } else {
                    None
                }
            };
            if let Some(result) = built {
                return self.tensor_variable_f32(result, vec![m, n], false);
            }
        }
        // triu keeps positions j >= i + diagonal and zeros the rest (see tensor_tril
        // for the unified grad/non-grad + dtype-narrow rationale). frankentorch-u78p.
        let out = self.tensor_apply_function(
            &[input],
            move |_ctx, inputs| {
                let (vals, _shape) = inputs[0];
                let mut result = vec![0.0_f64; m * n];
                // triu mask is per-row independent (row i keeps j >= i+diagonal) → parallelize
                // over rows. Bit-identical to the serial nested loop.
                let fill = |i: usize, row: &mut [f64]| {
                    let lim = (i as i64) + diagonal;
                    let src = &vals[i * n..i * n + n];
                    for (j, slot) in row.iter_mut().enumerate() {
                        if (j as i64) >= lim {
                            *slot = src[j];
                        }
                    }
                };
                if m * n >= PARALLEL_ELEMENTWISE_MIN && m > 1 {
                    use rayon::prelude::*;
                    result
                        .par_chunks_mut(n)
                        .enumerate()
                        .for_each(|(i, row)| fill(i, row));
                } else {
                    for (i, row) in result.chunks_mut(n).enumerate() {
                        fill(i, row);
                    }
                }
                Ok((result, vec![m, n]))
            },
            move |_ctx, grad_outputs| {
                let g = grad_outputs[0];
                let mut grad_in = vec![0.0_f64; m * n];
                let fill = |i: usize, row: &mut [f64]| {
                    let lim = (i as i64) + diagonal;
                    let src = &g[i * n..i * n + n];
                    for (j, slot) in row.iter_mut().enumerate() {
                        if (j as i64) >= lim {
                            *slot = src[j];
                        }
                    }
                };
                if m * n >= PARALLEL_ELEMENTWISE_MIN && m > 1 {
                    use rayon::prelude::*;
                    grad_in
                        .par_chunks_mut(n)
                        .enumerate()
                        .for_each(|(i, row)| fill(i, row));
                } else {
                    for (i, row) in grad_in.chunks_mut(n).enumerate() {
                        fill(i, row);
                    }
                }
                Ok(vec![Some(grad_in)])
            },
        )?;
        match dtype {
            DType::F16 | DType::BF16 | DType::F32 => self.tensor_tape.to_dtype(out, dtype),
            _ => Ok(out),
        }
    }

    /// In-place lower triangular: zero elements above the k-th diagonal.
    pub fn tensor_tril_(
        &mut self,
        target: TensorNodeId,
        diagonal: i64,
    ) -> Result<(), AutogradError> {
        self.validate_tensor_in_place_target(target)?;
        let shape = self.tensor_shape(target)?;
        if shape.len() != 2 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "tril_: input must be a 2-D tensor",
                },
            )));
        }
        let (m, n) = (shape[0], shape[1]);
        let mut vals = self.tensor_values_lossy_f64(target)?;
        for i in 0..m {
            for j in 0..n {
                if (j as i64) > (i as i64) + diagonal {
                    vals[i * n + j] = 0.0;
                }
            }
        }
        self.update_tensor_values_for_float(target, vals, INPLACE_FLOAT_REASON)?;
        self.record_tensor_in_place_operation(
            "tril_",
            target,
            Some(format!("diagonal={diagonal}")),
        );
        Ok(())
    }

    /// In-place upper triangular: zero elements below the k-th diagonal.
    pub fn tensor_triu_(
        &mut self,
        target: TensorNodeId,
        diagonal: i64,
    ) -> Result<(), AutogradError> {
        self.validate_tensor_in_place_target(target)?;
        let shape = self.tensor_shape(target)?;
        if shape.len() != 2 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "triu_: input must be a 2-D tensor",
                },
            )));
        }
        let (m, n) = (shape[0], shape[1]);
        let mut vals = self.tensor_values_lossy_f64(target)?;
        for i in 0..m {
            for j in 0..n {
                if (j as i64) < (i as i64) + diagonal {
                    vals[i * n + j] = 0.0;
                }
            }
        }
        self.update_tensor_values_for_float(target, vals, INPLACE_FLOAT_REASON)?;
        self.record_tensor_in_place_operation(
            "triu_",
            target,
            Some(format!("diagonal={diagonal}")),
        );
        Ok(())
    }

    /// Embed src tensor at a selected index along a dimension.
    ///
    /// Equivalent to `torch.select_scatter(input, src, dim, index)`.
    /// Tracked under frankentorch-ksqe.
    pub fn tensor_select_scatter(
        &mut self,
        input: TensorNodeId,
        src: TensorNodeId,
        dim: i64,
        index: i64,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        let ndim = shape.len();
        if ndim == 0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "select_scatter: input must have at least 1 dimension",
                },
            )));
        }

        let dim = if dim < 0 { ndim as i64 + dim } else { dim } as usize;
        if dim >= ndim {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "select_scatter: dim out of range",
                },
            )));
        }

        let dim_size = shape[dim];
        let index = if index < 0 {
            dim_size as i64 + index
        } else {
            index
        } as usize;
        if index >= dim_size {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "select_scatter: index out of range",
                },
            )));
        }

        let src_shape = self.tensor_shape(src)?;
        let expected_src_shape: Vec<usize> = shape
            .iter()
            .enumerate()
            .filter(|&(i, _)| i != dim)
            .map(|(_, &s)| s)
            .collect();
        if src_shape != expected_src_shape {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "select_scatter: src shape must match input shape with dim removed",
                },
            )));
        }

        let src_vals = self.tensor_values(src)?;

        let stride: usize = shape[dim + 1..].iter().product();
        let outer_stride: usize = shape[dim..].iter().product();
        let numel = Self::checked_shape_numel(&shape, "select_scatter: shape volume overflow")?;

        // Build the base output by BORROWING input + a PARALLEL copy (the old `tensor_values(input)`
        // is a serial to_vec memcpy whose page first-touch is the wall for large numel), then
        // overwrite the selected index below. Bit-identical (the scatter overwrites the same
        // positions regardless of how the base copy was produced). Non-contiguous / non-f64 / small
        // fall back to the serial clone. Mirrors the slice_scatter fix (dc96043a).
        let mut result = {
            let is_f64_contig = self.tensor_dtype(input)? == DType::F64
                && self.tensor_tape.tensor(input)?.meta().is_contiguous();
            if is_f64_contig && numel >= MOVEMENT_COPY_PARALLEL_MIN {
                let in_vals = self.tensor_tape.tensor(input)?.contiguous_values()?;
                let mut out = vec![0.0_f64; numel];
                use rayon::prelude::*;
                out.par_chunks_mut(1 << 16)
                    .zip(in_vals.par_chunks(1 << 16))
                    .for_each(|(o, i)| o.copy_from_slice(i));
                out
            } else {
                self.tensor_values(input)?
            }
        };

        for (src_idx, &val) in src_vals.iter().enumerate() {
            let outer = src_idx / stride;
            let inner = src_idx % stride;
            let dst_idx = outer * outer_stride + index * stride + inner;
            result[dst_idx] = val;
        }

        self.tensor_variable(result, shape, false)
    }

    /// Embed src tensor into a slice of input along a dimension.
    ///
    /// Equivalent to `torch.slice_scatter(input, src, dim, start, end, step)`.
    /// Tracked under frankentorch-eikp.
    pub fn tensor_slice_scatter(
        &mut self,
        input: TensorNodeId,
        src: TensorNodeId,
        dim: i64,
        start: Option<i64>,
        end: Option<i64>,
        step: i64,
    ) -> Result<TensorNodeId, AutogradError> {
        if step <= 0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "slice_scatter: step must be positive",
                },
            )));
        }

        let shape = self.tensor_shape(input)?;
        let ndim = shape.len();
        if ndim == 0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "slice_scatter: input must have at least 1 dimension",
                },
            )));
        }

        let dim = if dim < 0 { ndim as i64 + dim } else { dim } as usize;
        if dim >= ndim {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "slice_scatter: dim out of range",
                },
            )));
        }

        let dim_size = shape[dim] as i64;
        let start = start
            .map(|s| if s < 0 { dim_size + s } else { s })
            .unwrap_or(0)
            .max(0)
            .min(dim_size) as usize;
        let end = end
            .map(|e| if e < 0 { dim_size + e } else { e })
            .unwrap_or(dim_size)
            .max(0)
            .min(dim_size) as usize;
        let step = step as usize;

        let slice_len = if end > start {
            (end - start).div_ceil(step)
        } else {
            0
        };

        let src_shape = self.tensor_shape(src)?;
        let mut expected_shape = shape.clone();
        expected_shape[dim] = slice_len;
        if src_shape != expected_shape {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "slice_scatter: src shape must match slice shape",
                },
            )));
        }

        let src_vals = self.tensor_values(src)?;

        let inner_stride: usize = shape[dim + 1..].iter().product();
        let outer_stride: usize = shape[dim..].iter().product();
        let outer_count: usize = shape[..dim].iter().product();
        let numel = Self::checked_shape_numel(&shape, "slice_scatter: shape volume overflow")?;

        // Build the output by BORROWING input + a PARALLEL copy (the old `tensor_values(input)` is a
        // serial memcpy whose page first-touch is the wall for large numel), then overwrite the slice
        // below. Non-contiguous / non-f64 / small fall back to the serial clone. Bit-identical (the
        // scatter overwrites the same positions regardless of how the base copy was produced).
        let mut result = {
            let is_f64_contig = self.tensor_dtype(input)? == DType::F64
                && self.tensor_tape.tensor(input)?.meta().is_contiguous();
            if is_f64_contig && numel >= MOVEMENT_COPY_PARALLEL_MIN {
                let in_vals = self.tensor_tape.tensor(input)?.contiguous_values()?;
                let mut out = vec![0.0_f64; numel];
                use rayon::prelude::*;
                out.par_chunks_mut(1 << 16)
                    .zip(in_vals.par_chunks(1 << 16))
                    .for_each(|(o, i)| o.copy_from_slice(i));
                out
            } else {
                self.tensor_values(input)?
            }
        };

        for outer in 0..outer_count {
            for (slice_idx, dim_idx) in (start..end).step_by(step).enumerate() {
                for inner in 0..inner_stride {
                    let src_idx =
                        outer * (slice_len * inner_stride) + slice_idx * inner_stride + inner;
                    let dst_idx = outer * outer_stride + dim_idx * inner_stride + inner;
                    result[dst_idx] = src_vals[src_idx];
                }
            }
        }

        self.tensor_variable(result, shape, false)
    }

    /// Reduce source into input at indices using specified reduce operation.
    ///
    /// Equivalent to `torch.index_reduce(input, dim, index, source, reduce)`.
    /// Reduce modes: "prod", "mean", "amax", "amin".
    /// Tracked under frankentorch-p78l.
    /// No-grad index_reduce kernel over a `[outer, dim_size, inner]` view. Sources are
    /// bucketed by their target dim index (in ascending source order, so prod/mean reduce
    /// in the same order as the serial loop → bit-identical), then each `(outer, dst_dim)`
    /// output row — a disjoint `[inner]` slice — is reduced independently across the rayon
    /// pool. `reduce` is pre-validated to prod/mean/amax/amin. `mean_div(&mut v, total)`
    /// applies the mean divisor in the element dtype.
    #[allow(clippy::too_many_arguments)]
    fn index_reduce_apply<T>(
        result: &mut [T],
        src_vals: &[T],
        idx_vals: &[f64],
        reduce: &str,
        include_self: bool,
        outer_count: usize,
        dim_size: usize,
        inner_stride: usize,
        src_outer_stride: usize,
        mean_div: fn(&mut T, usize),
    ) -> Result<(), AutogradError>
    where
        T: Copy + Send + Sync + PartialOrd + std::ops::AddAssign + std::ops::MulAssign,
    {
        if inner_stride == 0 || dim_size == 0 || result.is_empty() {
            return Ok(());
        }
        // Bucket source-dim indices by target dim index, preserving ascending source order.
        let mut bucket: Vec<Vec<usize>> = vec![Vec::new(); dim_size];
        for (s, &idx_f) in idx_vals.iter().enumerate() {
            let d = idx_f as usize;
            if d >= dim_size {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "index_reduce: index out of bounds",
                    },
                )));
            }
            bucket[d].push(s);
        }
        // result is [outer, dim_size, inner] row-major, so chunk c == (outer, dst) at
        // inner-stride granularity owns a disjoint output row → no cross-chunk conflict.
        let reduce_chunk = |c: usize, out_chunk: &mut [T]| {
            let outer = c / dim_size;
            let dst = c % dim_size;
            let b = &bucket[dst];
            let src_outer = outer * src_outer_stride;
            for (k, &s) in b.iter().enumerate() {
                let src_base = src_outer + s * inner_stride;
                // First source under include_self=False REPLACES the base self value.
                let replace = k == 0 && !include_self;
                for inner in 0..inner_stride {
                    let sv = src_vals[src_base + inner];
                    let slot = &mut out_chunk[inner];
                    if replace {
                        *slot = sv;
                    } else {
                        match reduce {
                            "copy" => *slot = sv,
                            "prod" => *slot *= sv,
                            "sum" | "mean" => *slot += sv,
                            "amax" => {
                                if sv > *slot {
                                    *slot = sv;
                                }
                            }
                            "amin" => {
                                if sv < *slot {
                                    *slot = sv;
                                }
                            }
                            _ => {}
                        }
                    }
                }
            }
            if reduce == "mean" && !b.is_empty() {
                let total = if include_self { b.len() + 1 } else { b.len() };
                for v in out_chunk.iter_mut() {
                    mean_div(v, total);
                }
            }
        };
        let parallel = outer_count * dim_size >= 2 && result.len() >= PARALLEL_ELEMENTWISE_MIN;
        if parallel {
            use rayon::prelude::*;
            result
                .par_chunks_mut(inner_stride)
                .enumerate()
                .for_each(|(c, out_chunk)| reduce_chunk(c, out_chunk));
        } else {
            result
                .chunks_mut(inner_stride)
                .enumerate()
                .for_each(|(c, out_chunk)| reduce_chunk(c, out_chunk));
        }
        Ok(())
    }

    pub fn tensor_index_reduce(
        &mut self,
        input: TensorNodeId,
        dim: i64,
        index: TensorNodeId,
        source: TensorNodeId,
        reduce: &str,
        include_self: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        let ndim = shape.len();
        if ndim == 0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "index_reduce: input must have at least 1 dimension",
                },
            )));
        }

        let dim = if dim < 0 { ndim as i64 + dim } else { dim } as usize;
        if dim >= ndim {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "index_reduce: dim out of range",
                },
            )));
        }

        let index_shape = self.tensor_shape(index)?;
        if index_shape.len() != 1 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "index_reduce: index must be 1D",
                },
            )));
        }

        let src_shape = self.tensor_shape(source)?;
        if src_shape.len() != ndim {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "index_reduce: source rank must match input rank",
                },
            )));
        }
        if src_shape[dim] != index_shape[0] {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "index_reduce: source dim size must match index length",
                },
            )));
        }

        let dim_size = shape[dim];
        let idx_vals = self.tensor_values(index)?;

        let inner_stride: usize = shape[dim + 1..].iter().product();
        let outer_count: usize = shape[..dim].iter().product();
        let src_outer_stride: usize = src_shape[dim..].iter().product();

        // Validate the reduce mode up front so empty-index / empty-inner
        // cases still error rather than silently no-op'ing.
        if !matches!(reduce, "prod" | "mean" | "amax" | "amin") {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "index_reduce: reduce must be prod, mean, amax, or amin",
                },
            )));
        }

        // Native per-dtype no-grad path. Reading input/source via the F64-only
        // `tensor_values` ERRORED on f32 storage (no-grad f32 index_reduce crashed); read
        // each dtype natively and keep the input dtype (torch parity). `result` starts from
        // the input in BOTH include_self modes — positions that receive no source element
        // keep their original input value (include_self=False only drops the *self* term at
        // positions actually reduced into). The reduction is bucket-parallel over disjoint
        // output rows; include_self / first-replace / mean-divide match the prior serial loop
        // exactly (sources reduced in ascending order → bit-identical prod/mean).
        let out = match self.tensor_tape.dtype(input)? {
            DType::F64 => {
                // Borrow the (often huge) source storage zero-copy instead of cloning it via
                // `values()` — the kernel only reads `&[f64]`. Non-contiguous falls back to the
                // f64-gathering clone. This removes the dominant materialization pass.
                let src_contiguous = self.tensor_tape.tensor(source)?.meta().is_contiguous();
                let mut result = self.tensor_tape.values(input)?;
                if src_contiguous {
                    let src_t = self.tensor_tape.tensor(source)?;
                    let src_vals = src_t.contiguous_values()?;
                    Self::index_reduce_apply(
                        &mut result,
                        src_vals,
                        &idx_vals,
                        reduce,
                        include_self,
                        outer_count,
                        dim_size,
                        inner_stride,
                        src_outer_stride,
                        |v, total| *v /= total as f64,
                    )?;
                } else {
                    let src_vals = self.tensor_tape.values(source)?;
                    Self::index_reduce_apply(
                        &mut result,
                        &src_vals,
                        &idx_vals,
                        reduce,
                        include_self,
                        outer_count,
                        dim_size,
                        inner_stride,
                        src_outer_stride,
                        |v, total| *v /= total as f64,
                    )?;
                }
                self.tensor_variable(result, shape, false)?
            }
            DType::F32 => {
                // Borrow the source storage zero-copy (see the F64 arm).
                let src_contiguous = self.tensor_tape.tensor(source)?.meta().is_contiguous();
                let mut result = self.tensor_tape.values_f32(input)?;
                if src_contiguous {
                    let src_t = self.tensor_tape.tensor(source)?;
                    let src_vals = src_t.contiguous_values_f32()?;
                    Self::index_reduce_apply(
                        &mut result,
                        src_vals,
                        &idx_vals,
                        reduce,
                        include_self,
                        outer_count,
                        dim_size,
                        inner_stride,
                        src_outer_stride,
                        |v, total| *v /= total as f32,
                    )?;
                } else {
                    let src_vals = self.tensor_tape.values_f32(source)?;
                    Self::index_reduce_apply(
                        &mut result,
                        &src_vals,
                        &idx_vals,
                        reduce,
                        include_self,
                        outer_count,
                        dim_size,
                        inner_stride,
                        src_outer_stride,
                        |v, total| *v /= total as f32,
                    )?;
                }
                self.tensor_variable_f32(result, shape, false)?
            }
            _ => {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "index_reduce: input must be float32 or float64",
                    },
                )));
            }
        };
        Ok(out)
    }

    pub fn tensor_values(&self, node: TensorNodeId) -> Result<Vec<f64>, AutogradError> {
        self.tensor_tape.values(node)
    }

    /// Read a tensor's values as f64 regardless of its float dtype (F32/F16/BF16
    /// are converted). Unlike `tensor_values` (which requires F64 storage), this
    /// lets non-grad value-reading ops accept f32 inputs.
    pub fn tensor_values_lossy_f64(&self, node: TensorNodeId) -> Result<Vec<f64>, AutogradError> {
        self.tensor_tape.values_lossy_f64(node)
    }

    pub fn tensor_values_len(&self, node: TensorNodeId) -> Result<usize, AutogradError> {
        self.tensor_tape.values_len(node)
    }

    /// Return both the contiguous values and metadata for a tensor node.
    pub fn tensor_values_meta(
        &self,
        node: TensorNodeId,
    ) -> Result<(Vec<f64>, TensorMeta), AutogradError> {
        let values = self.tensor_tape.values(node)?;
        let meta = self.tensor_tape.tensor_meta(node)?.clone();
        Ok((values, meta))
    }

    /// In-place subtraction: target = target - other.
    /// Shared driver for the equal-shape in-place tensor-tensor binary ops
    /// (`add_`/`sub_`/`mul_`/`div_`). The old body cloned BOTH operands
    /// (`values(target)` + `values(other)`), built a fresh result Vec by a SERIAL
    /// zip-map, then `update_tensor_values` wrote it back = 4 serial passes. This
    /// clones only `other` (owned) and mutates `target` IN PLACE via
    /// `update_tensor_values_with` + `par_iter_mut` for tensors >=
    /// PARALLEL_ELEMENTWISE_MIN: drops the `target` clone AND the writeback memcpy
    /// AND parallelizes (incl. first-touch). Bit-identical: `*a = f(*a, *b)` per
    /// element, order-independent; contiguity contract unchanged (the old
    /// `update_tensor_values` writeback ALSO required `is_contiguous()`). f32 has
    /// no in-place `_with` accessor, so it keeps clone->map->writeback but
    /// parallelizes the (order-preserving) map with a NATIVE f32 op (no f64
    /// round-trip that would double-round). frankentorch-inplace-binary-par.
    fn apply_tensor_binary_in_place<F64f, F32f>(
        &mut self,
        op: &'static str,
        target: TensorNodeId,
        other: TensorNodeId,
        f64_op: F64f,
        f32_op: F32f,
    ) -> Result<(), AutogradError>
    where
        F64f: Fn(f64, f64) -> f64 + Sync,
        F32f: Fn(f32, f32) -> f32 + Sync,
    {
        use rayon::prelude::*;
        self.validate_tensor_in_place_binary_compatibility(target, other)?;
        match self.tensor_tape.dtype(target)? {
            DType::F64 => {
                let other_vals = self.tensor_tape.values(other)?;
                self.tensor_tape
                    .update_tensor_values_with(target, |t_vals| {
                        if t_vals.len() >= PARALLEL_ELEMENTWISE_MIN {
                            t_vals
                                .par_iter_mut()
                                .zip(other_vals.par_iter())
                                .for_each(|(a, b)| *a = f64_op(*a, *b));
                        } else {
                            for (a, b) in t_vals.iter_mut().zip(other_vals.iter()) {
                                *a = f64_op(*a, *b);
                            }
                        }
                    })?;
            }
            DType::F32 => {
                let target_vals = self.tensor_tape.values_f32(target)?;
                let other_vals = self.tensor_tape.values_f32(other)?;
                let new_values: Vec<f32> = if target_vals.len() >= PARALLEL_ELEMENTWISE_MIN {
                    target_vals
                        .par_iter()
                        .zip(other_vals.par_iter())
                        .map(|(&a, &b)| f32_op(a, b))
                        .collect()
                } else {
                    target_vals
                        .iter()
                        .zip(other_vals.iter())
                        .map(|(&a, &b)| f32_op(a, b))
                        .collect()
                };
                self.tensor_tape
                    .update_tensor_values_f32(target, new_values)?;
            }
            _ => {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: INPLACE_FLOAT_REASON,
                    },
                )));
            }
        }
        self.record_tensor_in_place_operation(op, target, Some(format!("other={}", other.0)));
        Ok(())
    }

    pub fn tensor_sub_(
        &mut self,
        target: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<(), AutogradError> {
        self.apply_tensor_binary_in_place("sub_", target, other, |a, b| a - b, |a, b| a - b)
    }

    /// In-place addition: target = target + other.
    pub fn tensor_add_(
        &mut self,
        target: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<(), AutogradError> {
        self.apply_tensor_binary_in_place("add_", target, other, |a, b| a + b, |a, b| a + b)
    }

    /// In-place multiplication: target = target * other.
    pub fn tensor_mul_(
        &mut self,
        target: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<(), AutogradError> {
        self.apply_tensor_binary_in_place("mul_", target, other, |a, b| a * b, |a, b| a * b)
    }

    /// In-place division: target = target / other.
    pub fn tensor_div_(
        &mut self,
        target: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<(), AutogradError> {
        self.apply_tensor_binary_in_place("div_", target, other, |a, b| a / b, |a, b| a / b)
    }

    /// In-place zero: target = zeros.
    /// Shared driver for the constant in-place fills (`zero_`/`ones_`/`fill_`). The
    /// old body built `vec![value; numel]` (a serial alloc that page-faults for
    /// non-zero values) then `update_tensor_values_for_float` copied it into storage
    /// = 2 passes. For a contiguous F64 target this fills the storage IN PLACE in
    /// ONE parallel pass (no intermediate Vec, no writeback copy), fanning the
    /// first-touch across cores. Bit-identical (constant fill). f32 / non-contiguous
    /// fall through to the generic writeback path unchanged. frankentorch-inplace-fill-par.
    fn fill_inplace_scalar(
        &mut self,
        target: TensorNodeId,
        value: f64,
        op: &'static str,
        extra: Option<String>,
    ) -> Result<(), AutogradError> {
        use rayon::prelude::*;
        self.validate_tensor_in_place_target(target)?;
        let fast = self.tensor_tape.dtype(target)? == DType::F64
            && self.tensor_tape.tensor(target)?.meta().is_contiguous();
        if fast {
            self.tensor_tape.update_tensor_values_with(target, |v| {
                if v.len() >= PARALLEL_ELEMENTWISE_MIN {
                    v.par_iter_mut().for_each(|x| *x = value);
                } else {
                    for x in v.iter_mut() {
                        *x = value;
                    }
                }
            })?;
        } else {
            let numel = self.tensor_numel(target)?;
            self.update_tensor_values_for_float(target, vec![value; numel], INPLACE_FLOAT_REASON)?;
        }
        self.record_tensor_in_place_operation(op, target, extra);
        Ok(())
    }

    pub fn tensor_zero_(&mut self, target: TensorNodeId) -> Result<(), AutogradError> {
        self.fill_inplace_scalar(target, 0.0, "zero_", None)
    }

    /// In-place ones: target = ones.
    pub fn tensor_ones_(&mut self, target: TensorNodeId) -> Result<(), AutogradError> {
        self.fill_inplace_scalar(target, 1.0, "ones_", None)
    }

    /// In-place Bernoulli: fill with 0 or 1 based on probability p.
    pub fn tensor_bernoulli_(&mut self, target: TensorNodeId, p: f64) -> Result<(), AutogradError> {
        self.validate_tensor_in_place_target(target)?;
        let numel = self.tensor_numel(target)?;
        let values: Vec<f64> = (0..numel)
            .map(|_| if self.rng.next_f64() < p { 1.0 } else { 0.0 })
            .collect();
        self.update_tensor_values_for_float(target, values, INPLACE_FLOAT_REASON)?;
        self.record_tensor_in_place_operation("bernoulli_", target, Some(format!("p={p}")));
        Ok(())
    }

    /// Sample from Bernoulli distribution with element-wise probabilities.
    ///
    /// Equivalent to `torch.bernoulli(prob)`. Each output element is 1 with
    /// probability prob[i], 0 otherwise. Returns a new tensor with same shape.
    pub fn tensor_bernoulli(&mut self, prob: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(prob)?;
        let prob_vals = self.tensor_values(prob)?;
        let values: Vec<f64> = prob_vals
            .iter()
            .map(|&p| if self.rng.next_f64() < p { 1.0 } else { 0.0 })
            .collect();
        self.tensor_variable(values, shape, false)
    }

    /// In-place random: fill with uniform integers from [from, to).
    pub fn tensor_random_(
        &mut self,
        target: TensorNodeId,
        from: i64,
        to: i64,
    ) -> Result<(), AutogradError> {
        self.validate_tensor_in_place_target(target)?;
        let numel = self.tensor_numel(target)?;
        let range = (to - from) as f64;
        let values: Vec<f64> = (0..numel)
            .map(|_| from as f64 + (self.rng.next_f64() * range).floor())
            .collect();
        self.update_tensor_values_for_float(target, values, INPLACE_FLOAT_REASON)?;
        self.record_tensor_in_place_operation(
            "random_",
            target,
            Some(format!("from={from} to={to}")),
        );
        Ok(())
    }

    /// In-place randint: fill with random integers in [low, high).
    pub fn tensor_randint_(
        &mut self,
        target: TensorNodeId,
        low: i64,
        high: i64,
    ) -> Result<(), AutogradError> {
        self.validate_tensor_in_place_target(target)?;
        if low >= high {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "randint_: low must be less than high",
                },
            )));
        }
        let numel = self.tensor_numel(target)?;
        let range = (high - low) as f64;
        let values: Vec<f64> = (0..numel)
            .map(|_| low as f64 + (self.rng.next_f64() * range).floor())
            .collect();
        self.update_tensor_values_for_float(target, values, INPLACE_FLOAT_REASON)?;
        self.record_tensor_in_place_operation(
            "randint_",
            target,
            Some(format!("low={low} high={high}")),
        );
        Ok(())
    }

    /// In-place fill: target = fill_value.
    pub fn tensor_fill_(
        &mut self,
        target: TensorNodeId,
        fill_value: f64,
    ) -> Result<(), AutogradError> {
        self.fill_inplace_scalar(
            target,
            fill_value,
            "fill_",
            Some(format!("fill_value={fill_value}")),
        )
    }

    pub fn tensor_copy_(
        &mut self,
        target: TensorNodeId,
        source: TensorNodeId,
    ) -> Result<(), AutogradError> {
        self.validate_tensor_in_place_target(target)?;
        let target_shape = self.tensor_shape(target)?;
        let source_shape = self.tensor_shape(source)?;
        if target_shape != source_shape {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: target_shape,
                    rhs: source_shape,
                },
            )));
        }
        let source_vals = self.tensor_values(source)?;
        self.update_tensor_values_for_float(target, source_vals, INPLACE_FLOAT_REASON)?;
        self.record_tensor_in_place_operation("copy_", target, None);
        Ok(())
    }

    /// Check if tensor can be resized to match another tensor's shape.
    ///
    /// Equivalent to `torch.Tensor.resize_as_(other)`. In FrankenTorch,
    /// true in-place resize of the underlying storage is not supported.
    /// Resize tensor in-place to specified shape.
    /// FrankenTorch doesn't support true in-place resize; this validates shape matches
    /// (no-op) or returns an error. For shape changes, create a new tensor.
    pub fn tensor_resize_(
        &mut self,
        target: TensorNodeId,
        size: Vec<usize>,
    ) -> Result<(), AutogradError> {
        self.validate_tensor_in_place_target(target)?;
        let target_shape = self.tensor_shape(target)?;
        if target_shape == size {
            self.record_tensor_in_place_operation("resize_", target, None);
            return Ok(());
        }
        Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
            ft_dispatch::DispatchKeyError::IncompatibleSet {
                reason: "resize_: in-place resize not supported; create new tensor with desired shape",
            },
        )))
    }

    /// This function validates shapes match (no-op) or returns an error.
    ///
    /// For actual shape changes, create a new tensor with the desired
    /// shape and copy values as needed.
    pub fn tensor_resize_as_(
        &mut self,
        target: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<(), AutogradError> {
        self.validate_tensor_in_place_target(target)?;
        let other_shape = self.tensor_shape(other)?;
        let target_shape = self.tensor_shape(target)?;
        if target_shape == other_shape {
            self.record_tensor_in_place_operation("resize_as_", target, None);
            return Ok(());
        }
        Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
            ft_dispatch::DispatchKeyError::IncompatibleSet {
                reason: "resize_as_: in-place resize not supported; create new tensor with desired shape",
            },
        )))
    }

    pub fn tensor_fill_diagonal_(
        &mut self,
        target: TensorNodeId,
        fill_value: f64,
    ) -> Result<(), AutogradError> {
        self.validate_tensor_in_place_target(target)?;
        let shape = self.tensor_shape(target)?;
        if shape.len() != 2 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "fill_diagonal_: input must be 2D",
                },
            )));
        }
        let (rows, cols) = (shape[0], shape[1]);
        let diag_len = rows.min(cols);
        let mut values = self.tensor_values_lossy_f64(target)?;
        for i in 0..diag_len {
            values[i * cols + i] = fill_value;
        }
        self.update_tensor_values_for_float(target, values, INPLACE_FLOAT_REASON)?;
        self.record_tensor_in_place_operation(
            "fill_diagonal_",
            target,
            Some(format!("fill_value={fill_value}")),
        );
        Ok(())
    }

    /// In-place scalar multiplication: target = target * scalar.
    pub fn tensor_mul_scalar_(
        &mut self,
        target: TensorNodeId,
        scalar: f64,
    ) -> Result<(), AutogradError> {
        self.validate_tensor_in_place_target(target)?;
        match self.tensor_tape.dtype(target)? {
            DType::F64 => {
                let target_vals = self.tensor_tape.values(target)?;
                let new_values: Vec<f64> = target_vals.iter().map(|v| v * scalar).collect();
                self.tensor_tape.update_tensor_values(target, new_values)?;
            }
            DType::F32 => {
                let target_vals = self.tensor_tape.values_f32(target)?;
                let scalar32 = scalar as f32;
                let new_values: Vec<f32> = target_vals.iter().map(|v| v * scalar32).collect();
                self.tensor_tape
                    .update_tensor_values_f32(target, new_values)?;
            }
            _ => {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: INPLACE_FLOAT_REASON,
                    },
                )));
            }
        }
        self.record_tensor_in_place_operation(
            "mul_scalar_",
            target,
            Some(format!("scalar={scalar}")),
        );
        Ok(())
    }

    /// In-place scalar addition: target = target + scalar.
    pub fn tensor_add_scalar_(
        &mut self,
        target: TensorNodeId,
        scalar: f64,
    ) -> Result<(), AutogradError> {
        self.validate_tensor_in_place_target(target)?;
        match self.tensor_tape.dtype(target)? {
            DType::F64 => {
                let target_vals = self.tensor_tape.values(target)?;
                let new_values: Vec<f64> = target_vals.iter().map(|v| v + scalar).collect();
                self.tensor_tape.update_tensor_values(target, new_values)?;
            }
            DType::F32 => {
                let target_vals = self.tensor_tape.values_f32(target)?;
                let scalar32 = scalar as f32;
                let new_values: Vec<f32> = target_vals.iter().map(|v| v + scalar32).collect();
                self.tensor_tape
                    .update_tensor_values_f32(target, new_values)?;
            }
            _ => {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: INPLACE_FLOAT_REASON,
                    },
                )));
            }
        }
        self.record_tensor_in_place_operation(
            "add_scalar_",
            target,
            Some(format!("scalar={scalar}")),
        );
        Ok(())
    }

