    /// Compute gradients of outputs w.r.t. inputs without accumulating into .grad.
    ///
    /// Equivalent to `torch.autograd.grad(outputs, inputs, grad_outputs, retain_graph, create_graph)`.
    /// Unlike `backward()` which accumulates gradients, this returns them directly.
    ///
    /// # Arguments
    /// * `outputs` - Tensors from which to differentiate (must have requires_grad=True)
    /// * `inputs` - Tensors w.r.t. which to differentiate
    /// * `grad_outputs` - Gradients for outputs (defaults to ones if None)
    /// * `retain_graph` - Keep the computation graph for multiple backward passes
    /// * `create_graph` - Allow higher-order derivatives
    ///
    /// # Returns
    /// A vector of gradients, one for each input tensor (None if input has no gradient).
    pub fn tensor_autograd_grad(
        &mut self,
        outputs: &[TensorNodeId],
        inputs: &[TensorNodeId],
        grad_outputs: Option<&[Vec<f64>]>,
        retain_graph: bool,
        create_graph: bool,
    ) -> Result<Vec<Option<Vec<f64>>>, AutogradError> {
        if outputs.is_empty() {
            return Ok(vec![]);
        }

        // The vector-Jacobian product torch.autograd.grad returns is
        //   grad[inp] = Σ_k J_kᵀ v_k
        // where J_k is the Jacobian of output_k w.r.t. the inputs and v_k is
        // grad_outputs[k] (defaulting to ones). Because
        //   d/dx Σ_k Σ_j output_k[j] · v_k[j]  =  Σ_k J_kᵀ v_k,
        // we build a single scalar surrogate s = Σ_k <output_k, v_k> (with v_k
        // a non-grad constant) and run one ordinary backward over it. This is
        // mathematically exact for arbitrary (non-diagonal) Jacobians, unlike a
        // post-hoc elementwise scaling of the per-input gradient.
        if let Some(go) = grad_outputs {
            if go.len() != outputs.len() {
                return Err(Self::incompatible_tensor_args(
                    "autograd_grad: grad_outputs length must match outputs length",
                ));
            }
        }

        let mut surrogate: Option<TensorNodeId> = None;
        for (k, &output) in outputs.iter().enumerate() {
            let weighted = match grad_outputs {
                Some(go) => {
                    let v = &go[k];
                    let out_shape = self.tensor_shape(output)?;
                    let out_numel: usize = out_shape.iter().product();
                    if v.len() != out_numel {
                        return Err(Self::incompatible_tensor_args(
                            "autograd_grad: each grad_outputs entry must match its output's element count",
                        ));
                    }
                    let v_tensor = self.tensor_variable(v.clone(), out_shape, false)?;
                    let prod = self.tensor_mul(output, v_tensor)?;
                    self.tensor_sum(prod)?
                }
                None => self.tensor_sum(output)?,
            };
            surrogate = Some(match surrogate {
                Some(acc) => self.tensor_add(acc, weighted)?,
                None => weighted,
            });
        }

        let surrogate = surrogate.expect("outputs is non-empty");
        let options = BackwardOptions::for_mode(self.mode())
            .with_retain_graph(retain_graph)
            .with_create_graph(create_graph);
        let report = self.tensor_tape.backward_with_options(surrogate, options)?;

        let mut result = Vec::with_capacity(inputs.len());
        for &inp in inputs {
            result.push(report.gradient(inp).map(<[f64]>::to_vec));
        }

        Ok(result)
    }

    /// Compute the vector-Jacobian product (VJP).
    ///
    /// Equivalent to `torch.autograd.functional.vjp(func, inputs, v)`.
    /// Given a function f: inputs -> outputs and a vector v with same shape as outputs,
    /// computes v^T @ J where J is the Jacobian of f.
    ///
    /// # Arguments
    /// * `output` - The output of the function (must be computed from inputs)
    /// * `inputs` - The inputs to the function
    /// * `v` - Vector to multiply with Jacobian (same shape as output)
    ///
    /// # Returns
    /// A vector of VJPs, one for each input.
    pub fn tensor_functional_vjp(
        &mut self,
        output: TensorNodeId,
        inputs: &[TensorNodeId],
        v: Vec<f64>,
    ) -> Result<Vec<Option<Vec<f64>>>, AutogradError> {
        // VJP is essentially backward with a custom grad_output
        self.tensor_autograd_grad(&[output], inputs, Some(&[v]), true, false)
    }

    /// Compute the Jacobian-vector product (JVP) via forward-mode AD approximation.
    ///
    /// Equivalent to `torch.autograd.functional.jvp(func, inputs, v)`.
    /// Given a function f and a vector v with same shape as inputs,
    /// computes J @ v where J is the Jacobian of f.
    ///
    /// Note: This uses numerical differentiation since FrankenTorch doesn't have
    /// forward-mode AD. For exact JVP, use finite differences with small epsilon.
    ///
    /// # Arguments
    /// * `func` - A closure that computes the forward pass
    /// * `inputs` - The input tensors
    /// * `v` - Tangent vectors (perturbation directions), one per input
    /// * `eps` - Epsilon for finite differences (default: 1e-6)
    pub fn tensor_functional_jvp<F>(
        &mut self,
        func: F,
        inputs: &[TensorNodeId],
        v: &[Vec<f64>],
        eps: Option<f64>,
    ) -> Result<(TensorNodeId, Vec<f64>), AutogradError>
    where
        F: Fn(&mut Self, &[TensorNodeId]) -> Result<TensorNodeId, AutogradError>,
    {
        let eps = eps.unwrap_or(1e-6);

        // Compute f(x)
        let output = func(self, inputs)?;
        let out_vals = self.tensor_values(output)?;

        // Compute f(x + eps*v) using finite differences
        let mut perturbed_inputs = Vec::with_capacity(inputs.len());
        for (i, &inp) in inputs.iter().enumerate() {
            let inp_vals = self.tensor_values(inp)?;
            let shape = self.tensor_shape(inp)?;
            let perturbed: Vec<f64> = inp_vals
                .iter()
                .zip(v.get(i).unwrap_or(&vec![0.0; inp_vals.len()]).iter())
                .map(|(x, vi)| x + eps * vi)
                .collect();
            let p = self.tensor_variable(perturbed, shape, false)?;
            perturbed_inputs.push(p);
        }

        let perturbed_output = func(self, &perturbed_inputs)?;
        let perturbed_vals = self.tensor_values(perturbed_output)?;

        // JVP = (f(x + eps*v) - f(x)) / eps
        let jvp: Vec<f64> = perturbed_vals
            .iter()
            .zip(out_vals.iter())
            .map(|(p, o)| (p - o) / eps)
            .collect();

        Ok((output, jvp))
    }

    /// Compute the Hessian-vector product (HVP).
    ///
    /// Equivalent to `torch.autograd.functional.hvp(func, inputs, v)`.
    /// Given a scalar function f and vectors v, computes H @ v where H is the Hessian.
    ///
    /// # Arguments
    /// * `output` - Scalar output of the function (must have shape [1] or [])
    /// * `inputs` - Input tensors
    /// * `v` - Vectors to multiply with Hessian, one per input
    pub fn tensor_functional_hvp(
        &mut self,
        output: TensorNodeId,
        inputs: &[TensorNodeId],
        v: &[Vec<f64>],
    ) -> Result<Vec<Option<Vec<f64>>>, AutogradError> {
        self.hessian_vector_product(output, inputs, v)
    }

    /// Compute the vector-Hessian product (VHP).
    ///
    /// Equivalent to `torch.autograd.functional.vhp(func, inputs, v)`.
    /// Given a scalar function f, computes `vᵀ H`. The Hessian of a scalar
    /// function is symmetric, so this equals the Hessian-vector product `H v`.
    ///
    /// # Arguments
    /// * `output` - Scalar output of the function (shape `[1]` or `[]`)
    /// * `inputs` - Input tensors
    /// * `v` - Vectors to multiply with the Hessian, one per input
    pub fn tensor_functional_vhp(
        &mut self,
        output: TensorNodeId,
        inputs: &[TensorNodeId],
        v: &[Vec<f64>],
    ) -> Result<Vec<Option<Vec<f64>>>, AutogradError> {
        self.hessian_vector_product(output, inputs, v)
    }

    /// Shared core for `hvp`/`vhp`: `H v` via the double-backward trick.
    ///
    /// A first `create_graph` backward exposes the gradient `g = ∇f` as
    /// differentiable tape nodes (`gradient_node`). The scalar
    /// `s = Σᵢ ⟨gᵢ, vᵢ⟩` (with each `vᵢ` a non-grad constant) then satisfies
    ///   ∂s/∂xⱼ = Σᵢ vᵢ · ∂gᵢ/∂xⱼ = Σᵢ vᵢ Hᵢⱼ = (H v)ⱼ,
    /// so a second backward over `s` yields the Hessian-vector product exactly.
    /// Returns `None` for any input not connected to `output`.
    fn hessian_vector_product(
        &mut self,
        output: TensorNodeId,
        inputs: &[TensorNodeId],
        v: &[Vec<f64>],
    ) -> Result<Vec<Option<Vec<f64>>>, AutogradError> {
        let first = BackwardOptions::for_mode(self.mode())
            .with_create_graph(true)
            .with_retain_graph(true);
        let report1 = self.tensor_backward_with_options(output, first)?;

        let mut s_node: Option<TensorNodeId> = None;
        for (i, &inp) in inputs.iter().enumerate() {
            let Some(grad_node) = report1.gradient_node(inp) else {
                continue;
            };
            let shape = self.tensor_shape(inp)?;
            let numel: usize = shape.iter().product();
            let vi = v.get(i).ok_or_else(|| {
                Self::incompatible_tensor_args("hessian product: one v vector required per input")
            })?;
            if vi.len() != numel {
                return Err(Self::incompatible_tensor_args(
                    "hessian product: each v vector must match its input's element count",
                ));
            }
            let v_tensor = self.tensor_variable(vi.clone(), shape, false)?;
            let prod = self.tensor_mul(grad_node, v_tensor)?;
            let dotted = self.tensor_sum(prod)?;
            s_node = Some(match s_node {
                Some(acc) => self.tensor_add(acc, dotted)?,
                None => dotted,
            });
        }

        let Some(s_node) = s_node else {
            return Ok(inputs.iter().map(|_| None).collect());
        };

        let report2 =
            self.tensor_backward_with_options(s_node, BackwardOptions::for_mode(self.mode()))?;
        Ok(inputs
            .iter()
            .map(|&inp| report2.gradient(inp).map(<[f64]>::to_vec))
            .collect())
    }

    /// Compute the full Jacobian of `output` with respect to each input.
    ///
    /// Equivalent to `torch.autograd.functional.jacobian`. Returns, per input,
    /// the Jacobian flattened in row-major order with logical shape
    /// `[output_numel, input_numel]`: row `j` is `∂output_j/∂input` (the
    /// gradient of the `j`-th output element). An input not connected to
    /// `output` yields an all-zero block.
    ///
    /// This is reverse-mode: it runs one backward pass per output element
    /// (`output_numel` passes), matching PyTorch's default `jacobian`.
    pub fn tensor_functional_jacobian(
        &mut self,
        output: TensorNodeId,
        inputs: &[TensorNodeId],
    ) -> Result<Vec<Vec<f64>>, AutogradError> {
        let out_numel: usize = self.tensor_shape(output)?.iter().product();
        let in_numels: Vec<usize> = inputs
            .iter()
            .map(|&inp| self.tensor_shape(inp).map(|s| s.iter().product()))
            .collect::<Result<_, _>>()?;
        let mut jac: Vec<Vec<f64>> = in_numels
            .iter()
            .map(|&n| vec![0.0; out_numel * n])
            .collect();

        for j in 0..out_numel {
            let mut seed = vec![0.0; out_numel];
            seed[j] = 1.0;
            // A VJP with the unit seed eⱼ yields exactly row j of the Jacobian:
            //   result_i = Σ_k J[k,i] (eⱼ)_k = J[j,i].
            let row = self.tensor_autograd_grad(&[output], inputs, Some(&[seed]), true, false)?;
            for (i, grad_opt) in row.iter().enumerate() {
                if let Some(g) = grad_opt {
                    let n = in_numels[i];
                    jac[i][j * n..j * n + n].copy_from_slice(g);
                }
            }
        }
        Ok(jac)
    }

    /// Compute the Hessian of a scalar `output` with respect to `input`.
    ///
    /// Equivalent to `torch.autograd.functional.hessian` for a single input
    /// tensor. `output` must be a scalar (one element). Returns the Hessian
    /// flattened in row-major order with logical shape `[n, n]` where `n` is
    /// the input's element count; row `k` is `∂²output/∂x_k∂x`.
    ///
    /// Implemented as the Jacobian of the gradient: a `create_graph` backward
    /// exposes `g = ∇f` as differentiable nodes, then each row `k` is obtained
    /// by a VJP of `g` seeded with the unit vector `e_k`.
    pub fn tensor_functional_hessian(
        &mut self,
        output: TensorNodeId,
        input: TensorNodeId,
    ) -> Result<Vec<f64>, AutogradError> {
        let out_numel: usize = self.tensor_shape(output)?.iter().product();
        if out_numel != 1 {
            return Err(Self::incompatible_tensor_args(
                "hessian: output must be a scalar (one element)",
            ));
        }
        let first = BackwardOptions::for_mode(self.mode())
            .with_create_graph(true)
            .with_retain_graph(true);
        let report1 = self.tensor_backward_with_options(output, first)?;
        let grad_node = report1.gradient_node(input).ok_or_else(|| {
            Self::incompatible_tensor_args("hessian: output does not depend on input")
        })?;

        let n: usize = self.tensor_shape(input)?.iter().product();
        let mut hess = vec![0.0; n * n];
        for k in 0..n {
            let mut seed = vec![0.0; n];
            seed[k] = 1.0;
            // VJP of g seeded with e_k gives ∂g_k/∂x = row k of the Hessian.
            let row =
                self.tensor_autograd_grad(&[grad_node], &[input], Some(&[seed]), true, false)?;
            if let Some(g) = &row[0] {
                hess[k * n..k * n + n].copy_from_slice(g);
            }
        }
        Ok(hess)
    }

    pub fn tensor_set_accumulated_gradient(
        &mut self,
        node: TensorNodeId,
        gradient: Vec<f64>,
    ) -> Result<(), AutogradError> {
        self.tensor_tape
            .set_tensor_accumulated_gradient(node, gradient)
    }

    /// Update a parameter's values directly, bypassing the leaf-grad in-place guard.
    ///
    /// This is the correct way for optimizers to update parameter values.
    /// In PyTorch, `param.data -= update` also bypasses the autograd guard.
    pub fn tensor_update_param_values(
        &mut self,
        param: TensorNodeId,
        new_values: Vec<f64>,
    ) -> Result<(), AutogradError> {
        self.update_tensor_values_for_float(param, new_values, PARAM_UPDATE_FLOAT_REASON)
    }

    /// Mutate a parameter's f64 values directly, bypassing the leaf-grad in-place guard.
    ///
    /// The closure cannot fail, so callers must perform all validation before
    /// mutating the parameter slice.
    pub fn tensor_update_param_values_f64_with<F>(
        &mut self,
        param: TensorNodeId,
        update: F,
    ) -> Result<(), AutogradError>
    where
        F: FnOnce(&mut [f64]),
    {
        self.tensor_tape.update_tensor_values_with(param, update)
    }

    /// Mutate a parameter while borrowing its persistent gradient from the tape.
    ///
    /// Returns `Ok(false)` when the parameter has no accumulated gradient.
    pub fn tensor_update_param_values_f64_with_accumulated_gradient<F>(
        &mut self,
        param: TensorNodeId,
        update: F,
    ) -> Result<bool, AutogradError>
    where
        F: FnOnce(&[f64], &mut [f64]),
    {
        self.tensor_tape
            .update_tensor_values_with_accumulated_gradient(param, update)
    }

    // ── Gradient Clipping Utilities ────────────────────────────────────

    /// Clip the total gradient norm of a set of parameters.
    ///
    /// Equivalent to `torch.nn.utils.clip_grad_norm_(parameters, max_norm, norm_type)`.
    /// Scales all gradients so that the total norm does not exceed `max_norm`.
    /// Returns the total norm before clipping.
    pub fn clip_grad_norm_(
        &mut self,
        params: &[TensorNodeId],
        max_norm: f64,
        norm_type: f64,
    ) -> Result<f64, AutogradError> {
        // Compute total norm across all parameter gradients
        let mut total_norm = 0.0_f64;

        if norm_type == f64::INFINITY {
            // Max norm: find the largest absolute gradient value
            for &p in params {
                if let Some(grad) = self.tensor_accumulated_gradient(p)? {
                    for &g in &grad {
                        let abs_g = g.abs();
                        if abs_g > total_norm {
                            total_norm = abs_g;
                        }
                    }
                }
            }
        } else {
            // Lp norm
            for &p in params {
                if let Some(grad) = self.tensor_accumulated_gradient(p)? {
                    for &g in &grad {
                        total_norm += g.abs().powf(norm_type);
                    }
                }
            }
            total_norm = total_norm.powf(1.0 / norm_type);
        }

        // Scale gradients if total_norm exceeds max_norm
        let clip_coef = max_norm / (total_norm + 1e-6);
        if clip_coef < 1.0 {
            for &p in params {
                if let Some(grad) = self.tensor_accumulated_gradient(p)? {
                    let clipped: Vec<f64> = grad.iter().map(|&g| g * clip_coef).collect();
                    self.tensor_set_accumulated_gradient(p, clipped)?;
                }
            }
        }

        self.runtime.ledger_mut().record(
            EvidenceKind::Policy,
            format!(
                "clip_grad_norm_ total_norm={total_norm} max_norm={max_norm} norm_type={norm_type} clipped={}",
                clip_coef < 1.0
            ),
        );

        Ok(total_norm)
    }

    /// Clip individual gradient values to a specified range.
    ///
    /// Equivalent to `torch.nn.utils.clip_grad_value_(parameters, clip_value)`.
    /// Clamps all gradient values to `[-clip_value, clip_value]`.
    pub fn clip_grad_value_(
        &mut self,
        params: &[TensorNodeId],
        clip_value: f64,
    ) -> Result<(), AutogradError> {
        for &p in params {
            if let Some(grad) = self.tensor_accumulated_gradient(p)? {
                let clipped: Vec<f64> = grad
                    .iter()
                    .map(|&g| g.clamp(-clip_value, clip_value))
                    .collect();
                self.tensor_set_accumulated_gradient(p, clipped)?;
            }
        }

        self.runtime.ledger_mut().record(
            EvidenceKind::Policy,
            format!(
                "clip_grad_value_ clip_value={clip_value} params={}",
                params.len()
            ),
        );

        Ok(())
    }

    // ── Learning Rate Schedulers ───────────────────────────────────────

    /// Cosine annealing learning rate schedule.
    ///
    /// Decays learning rate following a cosine curve from base_lr to eta_min.
    /// lr = eta_min + (base_lr - eta_min) * (1 + cos(pi * t / T_max)) / 2
    ///
    /// Args:
    /// - base_lr: initial learning rate
    /// - step: current step/epoch
    /// - t_max: maximum number of steps in a cycle
    /// - eta_min: minimum learning rate (default 0.0)
    pub fn cosine_annealing_lr(
        &self,
        base_lr: f64,
        step: usize,
        t_max: usize,
        eta_min: f64,
    ) -> f64 {
        if t_max == 0 {
            return base_lr;
        }
        let t = (step % t_max) as f64;
        let t_max_f = t_max as f64;
        eta_min + (base_lr - eta_min) * (1.0 + (std::f64::consts::PI * t / t_max_f).cos()) / 2.0
    }

    /// Cosine annealing with warm restarts (SGDR).
    ///
    /// Similar to cosine_annealing_lr but with restarts every T_0 * T_mult^i epochs.
    ///
    /// Args:
    /// - base_lr: initial learning rate
    /// - step: current step/epoch
    /// - t_0: initial period length
    /// - t_mult: period multiplier after each restart
    /// - eta_min: minimum learning rate
    pub fn cosine_annealing_warm_restarts_lr(
        &self,
        base_lr: f64,
        step: usize,
        t_0: usize,
        t_mult: f64,
        eta_min: f64,
    ) -> f64 {
        if t_0 == 0 {
            return base_lr;
        }
        let mut t_cur = step;
        let mut t_i = t_0;
        while t_cur >= t_i {
            t_cur -= t_i;
            t_i = (t_i as f64 * t_mult).ceil() as usize;
        }
        let t_f = t_cur as f64 / t_i as f64;
        eta_min + (base_lr - eta_min) * (1.0 + (std::f64::consts::PI * t_f).cos()) / 2.0
    }

    /// Step learning rate decay.
    ///
    /// Decays learning rate by gamma every step_size epochs.
    /// lr = base_lr * gamma^(step // step_size)
    pub fn step_lr(&self, base_lr: f64, step: usize, step_size: usize, gamma: f64) -> f64 {
        if step_size == 0 {
            return base_lr;
        }
        base_lr * gamma.powi((step / step_size) as i32)
    }

    /// Multi-step learning rate decay.
    ///
    /// Decays by gamma when step reaches each milestone.
    pub fn multistep_lr(&self, base_lr: f64, step: usize, milestones: &[usize], gamma: f64) -> f64 {
        let count = milestones.iter().filter(|&&m| step >= m).count();
        base_lr * gamma.powi(count as i32)
    }

    /// Exponential learning rate decay.
    ///
    /// lr = base_lr * gamma^step
    pub fn exponential_lr(&self, base_lr: f64, step: usize, gamma: f64) -> f64 {
        base_lr * gamma.powi(step as i32)
    }

    /// Linear warmup schedule.
    ///
    /// Linearly increases from start_factor * base_lr to base_lr over warmup_steps.
    pub fn linear_warmup_lr(
        &self,
        base_lr: f64,
        step: usize,
        warmup_steps: usize,
        start_factor: f64,
    ) -> f64 {
        if warmup_steps == 0 || step >= warmup_steps {
            return base_lr;
        }
        let progress = step as f64 / warmup_steps as f64;
        base_lr * (start_factor + (1.0 - start_factor) * progress)
    }

    /// Polynomial learning rate decay.
    ///
    /// lr = (base_lr - end_lr) * (1 - step/total_steps)^power + end_lr
    pub fn polynomial_lr(
        &self,
        base_lr: f64,
        step: usize,
        total_steps: usize,
        power: f64,
        end_lr: f64,
    ) -> f64 {
        if total_steps == 0 || step >= total_steps {
            return end_lr;
        }
        let progress = step as f64 / total_steps as f64;
        (base_lr - end_lr) * (1.0 - progress).powf(power) + end_lr
    }

    /// One-cycle learning rate policy (Smith & Topin).
    ///
    /// Three phases:
    /// 1. Linear warmup from max_lr/div_factor to max_lr (pct_start of cycle)
    /// 2. Cosine annealing from max_lr to max_lr/div_factor (to 1-final_div_pct)
    /// 3. Linear decay to max_lr/(div_factor*final_div_factor)
    pub fn one_cycle_lr(
        &self,
        max_lr: f64,
        step: usize,
        total_steps: usize,
        pct_start: f64,
        div_factor: f64,
        final_div_factor: f64,
    ) -> f64 {
        if total_steps == 0 {
            return max_lr;
        }
        let initial_lr = max_lr / div_factor;
        let min_lr = initial_lr / final_div_factor;
        let pct = step as f64 / total_steps as f64;
        if pct < pct_start {
            let scale = pct / pct_start;
            initial_lr + (max_lr - initial_lr) * scale
        } else {
            let down_pct = (pct - pct_start) / (1.0 - pct_start);
            let cos_scale = (1.0 + (std::f64::consts::PI * down_pct).cos()) / 2.0;
            min_lr + (initial_lr - min_lr) * cos_scale
        }
    }

    // ── Weight Normalization Utilities ─────────────────────────────────

    /// Apply weight normalization to a weight tensor.
    ///
    /// Equivalent to `torch.nn.utils.weight_norm`.
    /// Reparametrizes weight as `w = g * (v / ||v||)` where g is a scalar
    /// and v is the original weight direction.
    ///
    /// Returns `(weight_g, weight_v)` where:
    /// - `weight_g`: scalar magnitude per output feature `[out_features]`
    /// - `weight_v`: unnormalized direction, same shape as weight
    pub fn weight_norm_decompose(
        &mut self,
        weight: TensorNodeId,
        dim: usize,
    ) -> Result<(TensorNodeId, TensorNodeId), AutogradError> {
        let shape = self.tensor_shape(weight)?;
        if dim >= shape.len() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "weight_norm_decompose: dim out of range",
                },
            )));
        }
        let v = weight;
        let g_shape = vec![shape[dim]];
        let g_vals = vec![1.0_f64; shape[dim]];
        let g = self.tensor_variable(g_vals, g_shape, true)?;
        Ok((g, v))
    }

    /// Compute the normalized weight from weight_norm parameters.
    ///
    /// Given `(g, v)` from `weight_norm_decompose`, computes `g * (v / ||v||)`.
    pub fn weight_norm_compute(
        &mut self,
        weight_g: TensorNodeId,
        weight_v: TensorNodeId,
        dim: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let v_shape = self.tensor_shape(weight_v)?;
        if dim >= v_shape.len() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "weight_norm_compute: dim out of range",
                },
            )));
        }
        let dims_to_reduce: Vec<usize> = (0..v_shape.len()).filter(|&d| d != dim).collect();
        let mut norm_sq = weight_v;
        for &d in &dims_to_reduce {
            let sq = self.tensor_square(norm_sq)?;
            norm_sq = self.tensor_sum_dim(sq, d)?;
        }
        let norm = self.tensor_sqrt(norm_sq)?;
        let eps = 1e-12;
        let eps_tensor = self.full(self.tensor_shape(norm)?, eps, false)?;
        let norm_safe = self.tensor_add(norm, eps_tensor)?;
        let v_normalized = self.tensor_div(weight_v, norm_safe)?;
        let mut g_expanded = weight_g;
        for d in 0..v_shape.len() {
            if d != dim {
                g_expanded = self.tensor_unsqueeze(g_expanded, d)?;
            }
        }
        self.tensor_mul(g_expanded, v_normalized)
    }

    /// Apply spectral normalization to a weight tensor.
    ///
    /// Equivalent to `torch.nn.utils.spectral_norm`.
    /// Normalizes weight by its spectral norm (largest singular value).
    /// Uses power iteration to approximate the spectral norm.
    ///
    /// - `weight`: weight tensor to normalize
    /// - `n_power_iterations`: number of power iterations (default: 1)
    ///
    /// Returns normalized weight `w / sigma(w)`.
    pub fn spectral_norm(
        &mut self,
        weight: TensorNodeId,
        n_power_iterations: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(weight)?;
        if shape.len() < 2 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "spectral_norm: weight must be at least 2-D",
                },
            )));
        }
        let out_features = shape[0];
        let in_features: usize = shape[1..].iter().product();
        let w_flat = self.tensor_reshape(weight, vec![out_features, in_features])?;
        let mut u_data = vec![0.0_f64; out_features];
        for i in 0..out_features {
            u_data[i] = 1.0 / (out_features as f64).sqrt();
        }
        let mut u = self.tensor_variable(u_data, vec![out_features, 1], false)?;
        let w_t = self.tensor_transpose(w_flat, 0, 1)?;
        for _ in 0..n_power_iterations.max(1) {
            let v = self.tensor_matmul(w_t, u)?;
            let v_norm = self.tensor_norm(v, 2.0)?;
            let v_norm_shape = self.tensor_shape(v_norm)?;
            let eps = self.full(v_norm_shape, 1e-12, false)?;
            let v_norm_safe = self.tensor_add(v_norm, eps)?;
            let v_normalized = self.tensor_div(v, v_norm_safe)?;
            let u_new = self.tensor_matmul(w_flat, v_normalized)?;
            let u_norm = self.tensor_norm(u_new, 2.0)?;
            let u_norm_shape = self.tensor_shape(u_norm)?;
            let eps_u = self.full(u_norm_shape, 1e-12, false)?;
            let u_norm_safe = self.tensor_add(u_norm, eps_u)?;
            u = self.tensor_div(u_new, u_norm_safe)?;
        }
        let v_final = self.tensor_matmul(w_t, u)?;
        let v_norm_final = self.tensor_norm(v_final, 2.0)?;
        let v_norm_shape = self.tensor_shape(v_norm_final)?;
        let eps = self.full(v_norm_shape, 1e-12, false)?;
        let v_norm_safe = self.tensor_add(v_norm_final, eps)?;
        let v_normalized = self.tensor_div(v_final, v_norm_safe)?;
        let u_t = self.tensor_transpose(u, 0, 1)?;
        let wv = self.tensor_matmul(w_flat, v_normalized)?;
        let sigma_mat = self.tensor_matmul(u_t, wv)?;
        let sigma_vals = self.tensor_values(sigma_mat)?;
        let sigma_val = sigma_vals.first().copied().unwrap_or(1.0).max(1e-12);
        let sigma_tensor = self.full(shape.clone(), sigma_val, false)?;
        self.tensor_div(weight, sigma_tensor)
    }

    /// Flatten a list of parameter tensors into a single 1-D vector.
    ///
    /// Equivalent to `torch.nn.utils.convert_parameters.parameters_to_vector(parameters)`.
    /// Useful for optimization algorithms that work on flat parameter vectors.
    pub fn parameters_to_vector(
        &mut self,
        params: &[TensorNodeId],
    ) -> Result<TensorNodeId, AutogradError> {
        if params.is_empty() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "parameters_to_vector: empty parameter list",
                },
            )));
        }
        let mut all_vals = Vec::new();
        for &p in params {
            let vals = self.tensor_values(p)?;
            all_vals.extend(vals);
        }
        let total_len = all_vals.len();
        self.tensor_variable(all_vals, vec![total_len], false)
    }

    /// Unflatten a 1-D vector into parameter tensors.
    ///
    /// Equivalent to `torch.nn.utils.convert_parameters.vector_to_parameters(vec, parameters)`.
    /// Copies values from `vec` into `params` tensors in-place.
    pub fn vector_to_parameters(
        &mut self,
        vec: TensorNodeId,
        params: &[TensorNodeId],
    ) -> Result<(), AutogradError> {
        let vec_vals = self.tensor_values(vec)?;
        let mut offset = 0;
        for &p in params {
            let shape = self.tensor_shape(p)?;
            let numel: usize = shape.iter().product();
            if offset + numel > vec_vals.len() {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "vector_to_parameters: vector too short for parameters",
                    },
                )));
            }
            let vals: Vec<f64> = vec_vals[offset..offset + numel].to_vec();
            self.tensor_tape.update_tensor_values(p, vals)?;
            offset += numel;
        }
        Ok(())
    }

    /// Compute the total number of elements in a list of parameters.
    ///
    /// Useful for pre-allocating vectors or checking sizes.
    pub fn count_parameters(&mut self, params: &[TensorNodeId]) -> Result<usize, AutogradError> {
        let mut total = 0;
        for &p in params {
            let shape = self.tensor_shape(p)?;
            let numel: usize = shape.iter().product();
            total += numel;
        }
        Ok(total)
    }

    /// Get shapes of all parameters as a vector.
    pub fn parameter_shapes(
        &mut self,
        params: &[TensorNodeId],
    ) -> Result<Vec<Vec<usize>>, AutogradError> {
        let mut shapes = Vec::with_capacity(params.len());
        for &p in params {
            shapes.push(self.tensor_shape(p)?);
        }
        Ok(shapes)
    }

    /// Fuse convolutional weights and batch normalization parameters.
    ///
    /// Equivalent to `torch.nn.utils.fuse_conv_bn_weights`.
    /// Computes fused weight and bias that absorb the BN transformation:
    ///   w_fused = w * (gamma / sqrt(running_var + eps))
    ///   b_fused = (bias - running_mean) * (gamma / sqrt(running_var + eps)) + beta
    ///
    /// Returns `(fused_weight, fused_bias)`.
    pub fn fuse_conv_bn_weights(
        &mut self,
        conv_weight: TensorNodeId,
        conv_bias: Option<TensorNodeId>,
        bn_running_mean: TensorNodeId,
        bn_running_var: TensorNodeId,
        bn_gamma: TensorNodeId,
        bn_beta: TensorNodeId,
        eps: f64,
    ) -> Result<(TensorNodeId, TensorNodeId), AutogradError> {
        let w_shape = self.tensor_shape(conv_weight)?;
        if w_shape.is_empty() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "fuse_conv_bn_weights: conv_weight must be at least 1-D",
                },
            )));
        }
        let out_channels = w_shape[0];
        let eps_tensor = self.full(vec![out_channels], eps, false)?;
        let std = self.tensor_add(bn_running_var, eps_tensor)?;
        let std = self.tensor_sqrt(std)?;
        let scale = self.tensor_div(bn_gamma, std)?;
        let mut scale_shape = vec![1usize; w_shape.len()];
        scale_shape[0] = out_channels;
        let scale_expanded = self.tensor_reshape(scale, scale_shape)?;
        let fused_weight = self.tensor_mul(conv_weight, scale_expanded)?;
        let bias = match conv_bias {
            Some(b) => b,
            None => self.tensor_zeros(vec![out_channels], false)?,
        };
        let shifted_bias = self.tensor_sub(bias, bn_running_mean)?;
        let scaled_bias = self.tensor_mul(shifted_bias, scale)?;
        let fused_bias = self.tensor_add(scaled_bias, bn_beta)?;
        Ok((fused_weight, fused_bias))
    }

    // ── Pruning Utilities ──────────────────────────────────────────────

    /// Create a pruning mask based on L1 magnitude.
    ///
    /// Equivalent to `torch.nn.utils.prune.l1_unstructured`.
    /// Returns a binary mask where `amount` fraction of smallest-magnitude weights are zeroed.
    ///
    /// - `tensor`: weight tensor to create mask for
    /// - `amount`: fraction of weights to prune (0.0 to 1.0)
    pub fn prune_l1_unstructured_mask(
        &mut self,
        tensor: TensorNodeId,
        amount: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        if !(0.0..=1.0).contains(&amount) {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "prune_l1_unstructured_mask: amount must be in [0, 1]",
                },
            )));
        }
        let vals = self.tensor_values(tensor)?;
        let shape = self.tensor_shape(tensor)?;
        let numel = vals.len();
        let num_to_prune = (numel as f64 * amount).round() as usize;
        if num_to_prune == 0 {
            return self.tensor_ones(shape, false);
        }
        if num_to_prune >= numel {
            return self.tensor_zeros(shape, false);
        }
        let mut indexed: Vec<(usize, f64)> = vals.iter().map(|&v| v.abs()).enumerate().collect();
        indexed.sort_by(|a, b| a.1.partial_cmp(&b.1).unwrap_or(std::cmp::Ordering::Equal));
        let mut mask = vec![1.0_f64; numel];
        for i in 0..num_to_prune {
            mask[indexed[i].0] = 0.0;
        }
        self.tensor_variable(mask, shape, false)
    }

    /// Create a random pruning mask.
    ///
    /// Equivalent to `torch.nn.utils.prune.random_unstructured`.
    /// Returns a binary mask with `amount` fraction of weights randomly zeroed.
    pub fn prune_random_unstructured_mask(
        &mut self,
        tensor: TensorNodeId,
        amount: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        if !(0.0..=1.0).contains(&amount) {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "prune_random_unstructured_mask: amount must be in [0, 1]",
                },
            )));
        }
        let shape = self.tensor_shape(tensor)?;
        let _numel: usize = shape.iter().product();
        let rand_tensor = self.tensor_rand(shape.clone(), false)?;
        let rand_vals = self.tensor_values(rand_tensor)?;
        let mask: Vec<f64> = rand_vals
            .iter()
            .map(|&v| if v >= amount { 1.0 } else { 0.0 })
            .collect();
        self.tensor_variable(mask, shape, false)
    }

    /// Apply a pruning mask to a tensor.
    ///
    /// Returns `tensor * mask`, zeroing out pruned weights.
    pub fn apply_pruning_mask(
        &mut self,
        tensor: TensorNodeId,
        mask: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_mul(tensor, mask)
    }

    /// Compute sparsity of a tensor (fraction of zeros).
    pub fn compute_sparsity(&mut self, tensor: TensorNodeId) -> Result<f64, AutogradError> {
        let vals = self.tensor_values(tensor)?;
        if vals.is_empty() {
            return Ok(0.0);
        }
        let num_zeros = vals.iter().filter(|&&v| v == 0.0).count();
        Ok(num_zeros as f64 / vals.len() as f64)
    }

    // ── RNN Sequence Utilities ─────────────────────────────────────────

    /// Pad a list of variable-length sequences with a given padding value.
    ///
    /// Equivalent to `torch.nn.utils.rnn.pad_sequence(sequences, batch_first, padding_value)`.
    /// Takes a list of sequences (each as TensorNodeId) and pads them to the same length.
    /// Returns a single tensor with shape:
    /// - `[max_len, batch_size, *]` if `batch_first=false`
    /// - `[batch_size, max_len, *]` if `batch_first=true`
    pub fn pad_sequence(
        &mut self,
        sequences: &[TensorNodeId],
        batch_first: bool,
        padding_value: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        if sequences.is_empty() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "pad_sequence: sequences list must not be empty",
                },
            )));
        }

        let shapes: Vec<_> = sequences
            .iter()
            .map(|&s| self.tensor_shape(s))
            .collect::<Result<_, _>>()?;

        let max_len = shapes.iter().map(|s| s[0]).max().unwrap_or(0);
        let batch_size = sequences.len();
        let trailing_shape: Vec<usize> = if shapes[0].len() > 1 {
            shapes[0][1..].to_vec()
        } else {
            vec![]
        };

        let trailing_numel: usize = trailing_shape.iter().product::<usize>().max(1);
        let total_numel = if batch_first {
            batch_size * max_len * trailing_numel
        } else {
            max_len * batch_size * trailing_numel
        };

        let mut padded = vec![padding_value; total_numel];

        for (b, (&seq, shape)) in sequences.iter().zip(shapes.iter()).enumerate() {
            let seq_len = shape[0];
            let seq_data = self.tensor_values(seq)?;

            for t in 0..seq_len {
                for f in 0..trailing_numel {
                    let src_idx = t * trailing_numel + f;
                    let dst_idx = if batch_first {
                        b * max_len * trailing_numel + t * trailing_numel + f
                    } else {
                        t * batch_size * trailing_numel + b * trailing_numel + f
                    };
                    if src_idx < seq_data.len() {
                        padded[dst_idx] = seq_data[src_idx];
                    }
                }
            }
        }

        let out_shape = if batch_first {
            let mut s = vec![batch_size, max_len];
            s.extend(&trailing_shape);
            s
        } else {
            let mut s = vec![max_len, batch_size];
            s.extend(&trailing_shape);
            s
        };

        self.tensor_variable(padded, out_shape, false)
    }

    /// Pack a list of variable-length sequences (already sorted by length, descending).
    ///
    /// Equivalent to `torch.nn.utils.rnn.pack_sequence(sequences, enforce_sorted)`.
    /// Returns a tuple of (packed_data, batch_sizes, sorted_indices, unsorted_indices).
    /// - `packed_data`: Flattened tensor containing all timesteps
    /// - `batch_sizes`: Number of sequences at each timestep
    /// - `sorted_indices`: Permutation used for sorting (if any)
    /// - `unsorted_indices`: Inverse permutation
    pub fn pack_sequence(
        &mut self,
        sequences: &[TensorNodeId],
        enforce_sorted: bool,
    ) -> Result<(TensorNodeId, Vec<usize>, Vec<usize>, Vec<usize>), AutogradError> {
        if sequences.is_empty() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "pack_sequence: sequences list must not be empty",
                },
            )));
        }

        let shapes: Vec<_> = sequences
            .iter()
            .map(|&s| self.tensor_shape(s))
            .collect::<Result<_, _>>()?;
        let lengths: Vec<usize> = shapes.iter().map(|s| s[0]).collect();
        // Preserve input dtype (f32 sequences read via lossy_f64 -> narrow output). frankentorch-fk5l.
        let in_dtype = self.tensor_dtype(sequences[0])?;

        let sorted_indices: Vec<usize> = if enforce_sorted {
            (0..lengths.len()).collect()
        } else {
            let mut idx: Vec<usize> = (0..lengths.len()).collect();
            idx.sort_by(|&a, &b| lengths[b].cmp(&lengths[a]));
            idx
        };

        let sorted_lengths: Vec<usize> = sorted_indices.iter().map(|&i| lengths[i]).collect();

        let max_len = sorted_lengths[0];
        let trailing_shape: Vec<usize> = if shapes[0].len() > 1 {
            shapes[0][1..].to_vec()
        } else {
            vec![]
        };
        let trailing_numel: usize = trailing_shape.iter().product::<usize>().max(1);

        let mut batch_sizes = Vec::with_capacity(max_len);
        for t in 0..max_len {
            let count = sorted_lengths.iter().filter(|&&len| len > t).count();
            batch_sizes.push(count);
        }

        let total_elements: usize = batch_sizes.iter().sum();
        let mut packed_data = Vec::with_capacity(total_elements * trailing_numel);

        for t in 0..max_len {
            for (b, &orig_idx) in sorted_indices.iter().enumerate() {
                if sorted_lengths[b] > t {
                    let seq_data = self.tensor_values_lossy_f64(sequences[orig_idx])?;
                    for f in 0..trailing_numel {
                        let idx = t * trailing_numel + f;
                        if idx < seq_data.len() {
                            packed_data.push(seq_data[idx]);
                        }
                    }
                }
            }
        }

        let mut unsorted_indices = vec![0usize; sorted_indices.len()];
        for (sorted_pos, &orig_idx) in sorted_indices.iter().enumerate() {
            unsorted_indices[orig_idx] = sorted_pos;
        }

        let packed_shape = if trailing_shape.is_empty() {
            vec![packed_data.len()]
        } else {
            let mut s = vec![total_elements];
            s.extend(&trailing_shape);
            s
        };

        let packed_tensor = self.tensor_variable(packed_data, packed_shape, false)?;
        let packed_tensor = match in_dtype {
            dt @ (DType::F32 | DType::F16 | DType::BF16) => {
                self.tensor_to_dtype(packed_tensor, dt)?
            }
            _ => packed_tensor,
        };
        Ok((packed_tensor, batch_sizes, sorted_indices, unsorted_indices))
    }

    /// Pack a padded batch of sequences.
    ///
    /// Equivalent to `torch.nn.utils.rnn.pack_padded_sequence(input, lengths, batch_first, enforce_sorted)`.
    /// Takes a padded tensor and sequence lengths, returns packed representation.
    pub fn pack_padded_sequence(
        &mut self,
        input: TensorNodeId,
        lengths: &[usize],
        batch_first: bool,
        enforce_sorted: bool,
    ) -> Result<(TensorNodeId, Vec<usize>, Vec<usize>, Vec<usize>), AutogradError> {
        let shape = self.tensor_shape(input)?;
        // lossy_f64 so f32 sequences work (tensor_values is F64-only -> UnsupportedDType(F32)).
        let data = self.tensor_values_lossy_f64(input)?;
        let in_dtype = self.tensor_dtype(input)?;

        let (max_len, batch_size) = if batch_first {
            (shape[1], shape[0])
        } else {
            (shape[0], shape[1])
        };

        if lengths.len() != batch_size {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "pack_padded_sequence: lengths count must equal batch_size",
                },
            )));
        }

        let trailing_shape: Vec<usize> = if shape.len() > 2 {
            shape[2..].to_vec()
        } else {
            vec![]
        };
        let trailing_numel: usize = trailing_shape.iter().product::<usize>().max(1);

        let sorted_indices: Vec<usize> = if enforce_sorted {
            (0..batch_size).collect()
        } else {
            let mut idx: Vec<usize> = (0..batch_size).collect();
            idx.sort_by(|&a, &b| lengths[b].cmp(&lengths[a]));
            idx
        };

        let sorted_lengths: Vec<usize> = sorted_indices.iter().map(|&i| lengths[i]).collect();

        let actual_max_len = *sorted_lengths.iter().max().unwrap_or(&0);
        let mut batch_sizes = Vec::with_capacity(actual_max_len);
        for t in 0..actual_max_len {
            let count = sorted_lengths.iter().filter(|&&len| len > t).count();
            batch_sizes.push(count);
        }

        let total_elements: usize = batch_sizes.iter().sum();
        let mut packed_data = Vec::with_capacity(total_elements * trailing_numel);

        for t in 0..actual_max_len {
            for (b, &orig_idx) in sorted_indices.iter().enumerate() {
                if sorted_lengths[b] > t {
                    for f in 0..trailing_numel {
                        let idx = if batch_first {
                            orig_idx * max_len * trailing_numel + t * trailing_numel + f
                        } else {
                            t * batch_size * trailing_numel + orig_idx * trailing_numel + f
                        };
                        if idx < data.len() {
                            packed_data.push(data[idx]);
                        }
                    }
                }
            }
        }

        let mut unsorted_indices = vec![0usize; sorted_indices.len()];
        for (sorted_pos, &orig_idx) in sorted_indices.iter().enumerate() {
            unsorted_indices[orig_idx] = sorted_pos;
        }

        let packed_shape = if trailing_shape.is_empty() {
            vec![packed_data.len()]
        } else {
            let mut s = vec![total_elements];
            s.extend(&trailing_shape);
            s
        };

        let packed_tensor = self.tensor_variable(packed_data, packed_shape, false)?;
        let packed_tensor = match in_dtype {
            dt @ (DType::F32 | DType::F16 | DType::BF16) => {
                self.tensor_to_dtype(packed_tensor, dt)?
            }
            _ => packed_tensor,
        };
        Ok((packed_tensor, batch_sizes, sorted_indices, unsorted_indices))
    }

    /// Unpack a packed sequence back to padded form.
    ///
    /// Equivalent to `torch.nn.utils.rnn.pad_packed_sequence(packed, batch_first, padding_value, total_length)`.
    /// Takes packed data and batch_sizes, returns (padded_tensor, lengths).
    pub fn pad_packed_sequence(
        &mut self,
        packed_data: TensorNodeId,
        batch_sizes: &[usize],
        batch_first: bool,
        padding_value: f64,
        total_length: Option<usize>,
    ) -> Result<(TensorNodeId, Vec<usize>), AutogradError> {
        // lossy_f64 so f32 sequences work (tensor_values is F64-only -> UnsupportedDType(F32)).
        let data = self.tensor_values_lossy_f64(packed_data)?;
        let packed_shape = self.tensor_shape(packed_data)?;

        let trailing_shape: Vec<usize> = if packed_shape.len() > 1 {
            packed_shape[1..].to_vec()
        } else {
            vec![]
        };
        let trailing_numel: usize = trailing_shape.iter().product::<usize>().max(1);

        let max_len = total_length.unwrap_or(batch_sizes.len());
        let batch_size = *batch_sizes.first().unwrap_or(&0);

        let total_numel = if batch_first {
            batch_size * max_len * trailing_numel
        } else {
            max_len * batch_size * trailing_numel
        };

        let mut padded = vec![padding_value; total_numel];

        let mut lengths = vec![0usize; batch_size];
        for (t, &bs) in batch_sizes.iter().enumerate() {
            for b in 0..bs {
                if lengths[b] <= t {
                    lengths[b] = t + 1;
                }
            }
        }

        let mut data_idx = 0;
        for (t, &bs) in batch_sizes.iter().enumerate() {
            for b in 0..bs {
                for f in 0..trailing_numel {
                    let dst_idx = if batch_first {
                        b * max_len * trailing_numel + t * trailing_numel + f
                    } else {
                        t * batch_size * trailing_numel + b * trailing_numel + f
                    };
                    if data_idx < data.len() && dst_idx < padded.len() {
                        padded[dst_idx] = data[data_idx];
                    }
                    data_idx += 1;
                }
            }
        }

        let out_shape = if batch_first {
            let mut s = vec![batch_size, max_len];
            s.extend(&trailing_shape);
            s
        } else {
            let mut s = vec![max_len, batch_size];
            s.extend(&trailing_shape);
            s
        };

        let out_tensor = self.tensor_variable(padded, out_shape, false)?;
        // Preserve the packed_data dtype (f32 -> f32).
        let out_tensor = match self.tensor_dtype(packed_data)? {
            dt @ (DType::F32 | DType::F16 | DType::BF16) => self.tensor_to_dtype(out_tensor, dt)?,
            _ => out_tensor,
        };
        Ok((out_tensor, lengths))
    }

    // ── RNN Cell Functions ─────────────────────────────────────────────

    /// Single step of a vanilla RNN cell with tanh activation.
    ///
    /// Equivalent to `torch.nn.RNNCell` with `nonlinearity='tanh'`.
    /// Computes: `h' = tanh(W_ih @ x + b_ih + W_hh @ h + b_hh)`
    pub fn rnn_tanh_cell(
        &mut self,
        input: TensorNodeId,
        hidden: TensorNodeId,
        w_ih: TensorNodeId,
        w_hh: TensorNodeId,
        b_ih: Option<TensorNodeId>,
        b_hh: Option<TensorNodeId>,
    ) -> Result<TensorNodeId, AutogradError> {
        let igates = self.tensor_mm(input, w_ih)?;
        let hgates = self.tensor_mm(hidden, w_hh)?;
        let mut gates = self.tensor_add(igates, hgates)?;

        if let Some(bias_ih) = b_ih {
            gates = self.tensor_add(gates, bias_ih)?;
        }
        if let Some(bias_hh) = b_hh {
            gates = self.tensor_add(gates, bias_hh)?;
        }

        self.tensor_tanh(gates)
    }

    /// Single step of a vanilla RNN cell with ReLU activation.
    ///
    /// Equivalent to `torch.nn.RNNCell` with `nonlinearity='relu'`.
    /// Computes: `h' = relu(W_ih @ x + b_ih + W_hh @ h + b_hh)`
    pub fn rnn_relu_cell(
        &mut self,
        input: TensorNodeId,
        hidden: TensorNodeId,
        w_ih: TensorNodeId,
        w_hh: TensorNodeId,
        b_ih: Option<TensorNodeId>,
        b_hh: Option<TensorNodeId>,
    ) -> Result<TensorNodeId, AutogradError> {
        let igates = self.tensor_mm(input, w_ih)?;
        let hgates = self.tensor_mm(hidden, w_hh)?;
        let mut gates = self.tensor_add(igates, hgates)?;

        if let Some(bias_ih) = b_ih {
            gates = self.tensor_add(gates, bias_ih)?;
        }
        if let Some(bias_hh) = b_hh {
            gates = self.tensor_add(gates, bias_hh)?;
        }

        self.tensor_relu(gates)
    }

    /// Single step of an LSTM cell.
    ///
    /// Equivalent to `torch.nn.LSTMCell`.
    /// Returns (h', c') tuple for the new hidden and cell states.
    pub fn lstm_cell(
        &mut self,
        input: TensorNodeId,
        hx: (TensorNodeId, TensorNodeId),
        w_ih: TensorNodeId,
        w_hh: TensorNodeId,
        b_ih: Option<TensorNodeId>,
        b_hh: Option<TensorNodeId>,
    ) -> Result<(TensorNodeId, TensorNodeId), AutogradError> {
        let (h, c) = hx;

        let mut gates = self.tensor_mm(input, w_ih)?;
        let hgates = self.tensor_mm(h, w_hh)?;
        gates = self.tensor_add(gates, hgates)?;

        if let Some(bias_ih) = b_ih {
            gates = self.tensor_add(gates, bias_ih)?;
        }
        if let Some(bias_hh) = b_hh {
            gates = self.tensor_add(gates, bias_hh)?;
        }

        let hidden_size = self.tensor_shape(h)?[self.tensor_shape(h)?.len() - 1];
        let gates_data = self.tensor_values(gates)?;
        let c_data = self.tensor_values(c)?;

        let batch_size = gates_data.len() / (4 * hidden_size);
        let mut new_h = Vec::with_capacity(batch_size * hidden_size);
        let mut new_c = Vec::with_capacity(batch_size * hidden_size);

        for b in 0..batch_size {
            for i in 0..hidden_size {
                let gate_base = b * 4 * hidden_size;
                let i_gate = gates_data[gate_base + i];
                let f_gate = gates_data[gate_base + hidden_size + i];
                let g_gate = gates_data[gate_base + 2 * hidden_size + i];
                let o_gate = gates_data[gate_base + 3 * hidden_size + i];

                let i_gate = 1.0 / (1.0 + (-i_gate).exp());
                let f_gate = 1.0 / (1.0 + (-f_gate).exp());
                let g_gate = g_gate.tanh();
                let o_gate = 1.0 / (1.0 + (-o_gate).exp());

                let c_idx = b * hidden_size + i;
                let c_val = f_gate * c_data[c_idx] + i_gate * g_gate;
                let h_val = o_gate * c_val.tanh();

                new_c.push(c_val);
                new_h.push(h_val);
            }
        }

        let h_shape = self.tensor_shape(h)?;
        let new_h_tensor = self.tensor_variable(new_h, h_shape.clone(), false)?;
        let new_c_tensor = self.tensor_variable(new_c, h_shape, false)?;

        Ok((new_h_tensor, new_c_tensor))
    }

    /// Single step of a GRU cell.
    ///
    /// Equivalent to `torch.nn.GRUCell`.
    /// Returns h' for the new hidden state.
    pub fn gru_cell(
        &mut self,
        input: TensorNodeId,
        hidden: TensorNodeId,
        w_ih: TensorNodeId,
        w_hh: TensorNodeId,
        b_ih: Option<TensorNodeId>,
        b_hh: Option<TensorNodeId>,
    ) -> Result<TensorNodeId, AutogradError> {
        let mut gi = self.tensor_mm(input, w_ih)?;
        let mut gh = self.tensor_mm(hidden, w_hh)?;

        if let Some(bias_ih) = b_ih {
            gi = self.tensor_add(gi, bias_ih)?;
        }
        if let Some(bias_hh) = b_hh {
            gh = self.tensor_add(gh, bias_hh)?;
        }

        let hidden_size = self.tensor_shape(hidden)?[self.tensor_shape(hidden)?.len() - 1];
        let gi_data = self.tensor_values(gi)?;
        let gh_data = self.tensor_values(gh)?;
        let h_data = self.tensor_values(hidden)?;

        let batch_size = gi_data.len() / (3 * hidden_size);
        let mut new_h = Vec::with_capacity(batch_size * hidden_size);

        for b in 0..batch_size {
            for i in 0..hidden_size {
                let gi_base = b * 3 * hidden_size;
                let gh_base = b * 3 * hidden_size;

                let r_i = gi_data[gi_base + i];
                let z_i = gi_data[gi_base + hidden_size + i];
                let n_i = gi_data[gi_base + 2 * hidden_size + i];

                let r_h = gh_data[gh_base + i];
                let z_h = gh_data[gh_base + hidden_size + i];
                let n_h = gh_data[gh_base + 2 * hidden_size + i];

                let r = 1.0 / (1.0 + (-(r_i + r_h)).exp());
                let z = 1.0 / (1.0 + (-(z_i + z_h)).exp());
                let n = (n_i + r * n_h).tanh();

                let h_idx = b * hidden_size + i;
                let h_val = (1.0 - z) * n + z * h_data[h_idx];

                new_h.push(h_val);
            }
        }

        let h_shape = self.tensor_shape(hidden)?;
        self.tensor_variable(new_h, h_shape, false)
    }

    /// Process a sequence through an LSTM layer.
    ///
    /// Equivalent to `torch.nn.LSTM` forward pass.
    /// Input shape: (seq_len, batch, input_size) if batch_first=false, else (batch, seq_len, input_size)
    /// Returns (output, (h_n, c_n)) where output has shape (seq_len, batch, hidden_size * num_directions)
    ///
    /// # Arguments
    /// * `input` - Input sequence
    /// * `hx` - Initial hidden state (h_0, c_0), each of shape (num_layers * num_directions, batch, hidden_size)
    /// * `weights` - List of weight tensors [(w_ih_l0, w_hh_l0, b_ih_l0, b_hh_l0), ...]
    /// * `batch_first` - If true, input is (batch, seq_len, input_size)
    /// * `bidirectional` - If true, use bidirectional LSTM
    pub fn tensor_lstm(
        &mut self,
        input: TensorNodeId,
        hx: Option<(TensorNodeId, TensorNodeId)>,
        weights: &[(
            TensorNodeId,
            TensorNodeId,
            Option<TensorNodeId>,
            Option<TensorNodeId>,
        )],
        batch_first: bool,
        bidirectional: bool,
    ) -> Result<(TensorNodeId, (TensorNodeId, TensorNodeId)), AutogradError> {
        let input_shape = self.tensor_shape(input)?;
        if input_shape.len() != 3 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "lstm: input must be 3-D",
                },
            )));
        }

        // f32 inputs ERROR (UnsupportedDType(F32)): the raw f64 forward reads input/hx/weights
        // via the F64-only tensor_values. Compute in f64 (upcast input + hidden + all weights,
        // exact) then narrow the (non-grad) outputs back to f32. torch lstm(f32) -> f32.
        // frankentorch-fk5l.
        if self.tensor_dtype(input)? == DType::F32 {
            let in64 = self.tensor_to_dtype(input, DType::F64)?;
            let hx64 = match hx {
                Some((h, c)) => Some((
                    self.tensor_to_dtype(h, DType::F64)?,
                    self.tensor_to_dtype(c, DType::F64)?,
                )),
                None => None,
            };
            let mut weights64 = Vec::with_capacity(weights.len());
            for &(wih, whh, bih, bhh) in weights {
                let wih64 = self.tensor_to_dtype(wih, DType::F64)?;
                let whh64 = self.tensor_to_dtype(whh, DType::F64)?;
                let bih64 = match bih {
                    Some(b) => Some(self.tensor_to_dtype(b, DType::F64)?),
                    None => None,
                };
                let bhh64 = match bhh {
                    Some(b) => Some(self.tensor_to_dtype(b, DType::F64)?),
                    None => None,
                };
                weights64.push((wih64, whh64, bih64, bhh64));
            }
            let (out, (hn, cn)) =
                self.tensor_lstm(in64, hx64, &weights64, batch_first, bidirectional)?;
            return Ok((
                self.tensor_to_dtype(out, DType::F32)?,
                (
                    self.tensor_to_dtype(hn, DType::F32)?,
                    self.tensor_to_dtype(cn, DType::F32)?,
                ),
            ));
        }

        let (seq_len, batch_size, _input_size) = if batch_first {
            (input_shape[1], input_shape[0], input_shape[2])
        } else {
            (input_shape[0], input_shape[1], input_shape[2])
        };

        let num_layers = weights.len();
        let num_directions = if bidirectional { 2 } else { 1 };

        // Get hidden size from first weight
        let w_hh_shape = self.tensor_shape(weights[0].1)?;
        let hidden_size = w_hh_shape[1];

        // Initialize hidden states if not provided
        let (mut h_all, mut c_all) = if let Some((h0, c0)) = hx {
            (self.tensor_values(h0)?, self.tensor_values(c0)?)
        } else {
            let total = num_layers * num_directions * batch_size * hidden_size;
            (vec![0.0; total], vec![0.0; total])
        };

        // Convert input to seq-first if needed
        let input_data = self.tensor_values(input)?;
        let input_size = if batch_first {
            input_shape[2]
        } else {
            input_shape[2]
        };

        let mut layer_input: Vec<Vec<f64>> = Vec::with_capacity(seq_len);

        // Extract sequences
        for t in 0..seq_len {
            let mut seq_data = Vec::with_capacity(batch_size * input_size);
            for b in 0..batch_size {
                for i in 0..input_size {
                    let idx = if batch_first {
                        b * seq_len * input_size + t * input_size + i
                    } else {
                        t * batch_size * input_size + b * input_size + i
                    };
                    seq_data.push(input_data[idx]);
                }
            }
            layer_input.push(seq_data);
        }

        let mut outputs: Vec<Vec<f64>> =
            vec![vec![0.0; batch_size * hidden_size * num_directions]; seq_len];

        // Raw no-grad forward (frankentorch-3k4v). tensor_lstm already produces
        // non-grad leaves, so the whole sweep can run in raw f64 with ZERO per-
        // timestep session ops / tape nodes / leaf allocations. The two matmuls
        // are routed through ft_kernel_cpu::matmul_rhs_transposed_contiguous_f64
        // (= x @ W^T via dgemm_bt) — the SAME kernel tensor_mm uses, so the
        // values are bit-for-bit identical to the previous session-op path
        // (guarded by lstm_raw_forward_golden_isomorphism). The input projection
        // x @ W_ih^T is hoisted out of the timestep loop and batched over the
        // whole sequence in ONE gemm (its rows are independent of h; matrixmultiply's
        // K-accumulation is independent of the M tiling, so batching is exact);
        // only the recurrent h @ W_hh^T stays per-step.
        let four_h = 4 * hidden_size;
        let kernel_err = |e: ft_kernel_cpu::KernelError| {
            AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
        };

        for layer in 0..num_layers {
            let (w_ih, w_hh, b_ih, b_hh) = &weights[layer];
            let in_sz = if layer == 0 {
                input_size
            } else {
                hidden_size * num_directions
            };

            // Materialise the (small) weights/biases as contiguous f64 once.
            let w_ih_vals = self.tensor_values(*w_ih)?; // [4h, in_sz]
            let w_hh_vals = self.tensor_values(*w_hh)?; // [4h, hidden]
            let b_ih_vals = match b_ih {
                Some(b) => Some(self.tensor_values(*b)?),
                None => None,
            };
            let b_hh_vals = match b_hh {
                Some(b) => Some(self.tensor_values(*b)?),
                None => None,
            };

            // Batched input projection over ALL timesteps: [seq*batch, in] @ W_ih^T.
            let mut x_all = Vec::with_capacity(seq_len * batch_size * in_sz);
            for seq_data in layer_input.iter().take(seq_len) {
                x_all.extend_from_slice(seq_data);
            }
            let xw_all = ft_kernel_cpu::matmul_rhs_transposed_contiguous_f64(
                seq_len * batch_size,
                in_sz,
                four_h,
                &x_all,
                &w_ih_vals,
            )
            .map_err(kernel_err)?; // [seq*batch, 4h], row (t*batch+b)

            // One recurrent step: gates = ((xw_row + h @ W_hh^T) + b_ih) + b_hh,
            // then the LSTM gate soup, written into caller-owned buffers. The
            // recurrent matmul reuses `hg` (via the _into kernel) and the cell
            // writes into h_out/c_out, so the whole timestep loop allocates
            // NOTHING per step. Add order matches the old tensor_add chain exactly
            // so the result is bit-identical (frankentorch-3k4v).
            let bh = batch_size * hidden_size;
            let step = |h: &[f64],
                        c: &[f64],
                        xw_row: &[f64],
                        hg: &mut Vec<f64>,
                        h_out: &mut [f64],
                        c_out: &mut [f64]|
             -> Result<(), AutogradError> {
                ft_kernel_cpu::matmul_rhs_transposed_contiguous_f64_into(
                    hg,
                    batch_size,
                    hidden_size,
                    four_h,
                    h,
                    &w_hh_vals,
                )
                .map_err(kernel_err)?;
                for b in 0..batch_size {
                    let gate_base = b * four_h;
                    for i in 0..hidden_size {
                        let gate = |off: usize| {
                            let mut v = xw_row[gate_base + off] + hg[gate_base + off];
                            if let Some(bih) = &b_ih_vals {
                                v += bih[off];
                            }
                            if let Some(bhh) = &b_hh_vals {
                                v += bhh[off];
                            }
                            v
                        };
                        let i_gate = 1.0 / (1.0 + (-gate(i)).exp());
                        let f_gate = 1.0 / (1.0 + (-gate(hidden_size + i)).exp());
                        let g_gate = gate(2 * hidden_size + i).tanh();
                        let o_gate = 1.0 / (1.0 + (-gate(3 * hidden_size + i)).exp());
                        let c_idx = b * hidden_size + i;
                        let c_val = f_gate * c[c_idx] + i_gate * g_gate;
                        c_out[c_idx] = c_val;
                        h_out[c_idx] = o_gate * c_val.tanh();
                    }
                }
                Ok(())
            };

            let row_len = batch_size * four_h;
            let layer_base = layer * num_directions * batch_size * hidden_size;

            // Persistent scratch reused across every timestep (and both
            // directions): the recurrent-matmul output and the double-buffered
            // next h/c. mem::swap rotates current<->next with no allocation.
            let mut hg: Vec<f64> = Vec::with_capacity(batch_size * four_h);
            let mut h_next = vec![0.0_f64; bh];
            let mut c_next = vec![0.0_f64; bh];

            // Forward direction.
            let mut h = h_all[layer_base..layer_base + bh].to_vec();
            let mut c = c_all[layer_base..layer_base + bh].to_vec();
            for t in 0..seq_len {
                let xw_row = &xw_all[t * row_len..t * row_len + row_len];
                step(&h, &c, xw_row, &mut hg, &mut h_next, &mut c_next)?;
                outputs[t][..bh].copy_from_slice(&h_next);
                std::mem::swap(&mut h, &mut h_next);
                std::mem::swap(&mut c, &mut c_next);
            }
            h_all[layer_base..layer_base + bh].copy_from_slice(&h);
            c_all[layer_base..layer_base + bh].copy_from_slice(&c);

            // Bidirectional: backward direction reuses the SAME weights and the
            // SAME batched input projection (matching the original).
            if bidirectional {
                let rev_base = layer_base + bh;
                let mut h_rev = h_all[rev_base..rev_base + bh].to_vec();
                let mut c_rev = c_all[rev_base..rev_base + bh].to_vec();
                for t in (0..seq_len).rev() {
                    let xw_row = &xw_all[t * row_len..t * row_len + row_len];
                    step(&h_rev, &c_rev, xw_row, &mut hg, &mut h_next, &mut c_next)?;
                    outputs[t][bh..].copy_from_slice(&h_next);
                    std::mem::swap(&mut h_rev, &mut h_next);
                    std::mem::swap(&mut c_rev, &mut c_next);
                }
                h_all[rev_base..rev_base + bh].copy_from_slice(&h_rev);
                c_all[rev_base..rev_base + bh].copy_from_slice(&c_rev);
            }

            // Prepare input for next layer.
            if layer < num_layers - 1 {
                layer_input = outputs.clone();
            }
        }

        // Flatten outputs
        let out_size = hidden_size * num_directions;
        let mut flat_output = Vec::with_capacity(seq_len * batch_size * out_size);
        for t in 0..seq_len {
            flat_output.extend_from_slice(&outputs[t]);
        }

        let out_shape = if batch_first {
            vec![batch_size, seq_len, out_size]
        } else {
            vec![seq_len, batch_size, out_size]
        };
        let output = self.tensor_variable(flat_output, out_shape, false)?;

        let h_n = self.tensor_variable(
            h_all,
            vec![num_layers * num_directions, batch_size, hidden_size],
            false,
        )?;
        let c_n = self.tensor_variable(
            c_all,
            vec![num_layers * num_directions, batch_size, hidden_size],
            false,
        )?;

        Ok((output, (h_n, c_n)))
    }

    /// Process a sequence through a GRU layer.
    ///
    /// Equivalent to `torch.nn.GRU` forward pass.
    /// Input shape: (seq_len, batch, input_size) if batch_first=false
    /// Returns (output, h_n) where output has shape (seq_len, batch, hidden_size * num_directions)
    pub fn tensor_gru(
        &mut self,
        input: TensorNodeId,
        hx: Option<TensorNodeId>,
        weights: &[(
            TensorNodeId,
            TensorNodeId,
            Option<TensorNodeId>,
            Option<TensorNodeId>,
        )],
        batch_first: bool,
        bidirectional: bool,
    ) -> Result<(TensorNodeId, TensorNodeId), AutogradError> {
        let input_shape = self.tensor_shape(input)?;
        if input_shape.len() != 3 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "gru: input must be 3-D",
                },
            )));
        }

        // f32 inputs ERROR (UnsupportedDType(F32)): raw f64 forward reads via F64-only
        // tensor_values. Compute in f64 (upcast input/hidden/weights) then narrow the outputs.
        // frankentorch-fk5l.
        if self.tensor_dtype(input)? == DType::F32 {
            let in64 = self.tensor_to_dtype(input, DType::F64)?;
            let hx64 = match hx {
                Some(h) => Some(self.tensor_to_dtype(h, DType::F64)?),
                None => None,
            };
            let mut weights64 = Vec::with_capacity(weights.len());
            for &(wih, whh, bih, bhh) in weights {
                let wih64 = self.tensor_to_dtype(wih, DType::F64)?;
                let whh64 = self.tensor_to_dtype(whh, DType::F64)?;
                let bih64 = match bih {
                    Some(b) => Some(self.tensor_to_dtype(b, DType::F64)?),
                    None => None,
                };
                let bhh64 = match bhh {
                    Some(b) => Some(self.tensor_to_dtype(b, DType::F64)?),
                    None => None,
                };
                weights64.push((wih64, whh64, bih64, bhh64));
            }
            let (out, hn) = self.tensor_gru(in64, hx64, &weights64, batch_first, bidirectional)?;
            return Ok((
                self.tensor_to_dtype(out, DType::F32)?,
                self.tensor_to_dtype(hn, DType::F32)?,
            ));
        }

        let (seq_len, batch_size, _input_size) = if batch_first {
            (input_shape[1], input_shape[0], input_shape[2])
        } else {
            (input_shape[0], input_shape[1], input_shape[2])
        };

        let num_layers = weights.len();
        let num_directions = if bidirectional { 2 } else { 1 };

        let w_hh_shape = self.tensor_shape(weights[0].1)?;
        let hidden_size = w_hh_shape[1];

        let mut h_all = if let Some(h0) = hx {
            self.tensor_values(h0)?
        } else {
            vec![0.0; num_layers * num_directions * batch_size * hidden_size]
        };

        let input_data = self.tensor_values(input)?;
        let input_size = if batch_first {
            input_shape[2]
        } else {
            input_shape[2]
        };

        let mut layer_input: Vec<Vec<f64>> = Vec::with_capacity(seq_len);
        for t in 0..seq_len {
            let mut seq_data = Vec::with_capacity(batch_size * input_size);
            for b in 0..batch_size {
                for i in 0..input_size {
                    let idx = if batch_first {
                        b * seq_len * input_size + t * input_size + i
                    } else {
                        t * batch_size * input_size + b * input_size + i
                    };
                    seq_data.push(input_data[idx]);
                }
            }
            layer_input.push(seq_data);
        }

        let mut outputs: Vec<Vec<f64>> =
            vec![vec![0.0; batch_size * hidden_size * num_directions]; seq_len];

        // Raw no-grad forward (frankentorch-3k4v) — same scheme as tensor_lstm:
        // ZERO per-timestep session ops / tape nodes / allocations. GRU keeps the
        // input projection gi and the recurrent projection gh SEPARATE (the new
        // gate uses r * gh_n, so gi and gh cannot be summed), so the batched
        // gi = x @ W_ih^T (+ b_ih, broadcast once) is hoisted out of the loop and
        // only gh = h @ W_hh^T (+ b_hh) runs per step. Matmuls route through the
        // same dgemm_bt kernel tensor_mm uses; the gate math/add order replicate
        // gru_cell exactly, so results are bit-identical (guarded by
        // gru_raw_forward_golden_isomorphism).
        let three_h = 3 * hidden_size;
        let bh = batch_size * hidden_size;
        let kernel_err = |e: ft_kernel_cpu::KernelError| {
            AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
        };

        for layer in 0..num_layers {
            let (w_ih, w_hh, b_ih, b_hh) = &weights[layer];
            let in_sz = if layer == 0 {
                input_size
            } else {
                hidden_size * num_directions
            };

            let w_ih_vals = self.tensor_values(*w_ih)?; // [3h, in_sz]
            let w_hh_vals = self.tensor_values(*w_hh)?; // [3h, hidden]
            let b_ih_vals = match b_ih {
                Some(b) => Some(self.tensor_values(*b)?),
                None => None,
            };
            let b_hh_vals = match b_hh {
                Some(b) => Some(self.tensor_values(*b)?),
                None => None,
            };

            // Batched input projection gi = x_all @ W_ih^T, with b_ih added once
            // per row (matches gru_cell's add(gi, b_ih) elementwise).
            let mut x_all = Vec::with_capacity(seq_len * batch_size * in_sz);
            for seq_data in layer_input.iter().take(seq_len) {
                x_all.extend_from_slice(seq_data);
            }
            let mut gi_all = ft_kernel_cpu::matmul_rhs_transposed_contiguous_f64(
                seq_len * batch_size,
                in_sz,
                three_h,
                &x_all,
                &w_ih_vals,
            )
            .map_err(kernel_err)?;
            if let Some(bih) = &b_ih_vals {
                for row in gi_all.chunks_mut(three_h) {
                    for (j, slot) in row.iter_mut().enumerate() {
                        *slot += bih[j];
                    }
                }
            }

            // One GRU step: gh = h @ W_hh^T (+ b_hh), then the gate soup, writing
            // into h_out. gh reuses the persistent buffer (no per-step alloc).
            let step = |h: &[f64],
                        gi_row: &[f64],
                        gh: &mut Vec<f64>,
                        h_out: &mut [f64]|
             -> Result<(), AutogradError> {
                ft_kernel_cpu::matmul_rhs_transposed_contiguous_f64_into(
                    gh,
                    batch_size,
                    hidden_size,
                    three_h,
                    h,
                    &w_hh_vals,
                )
                .map_err(kernel_err)?;
                for b in 0..batch_size {
                    let gate_base = b * three_h;
                    for i in 0..hidden_size {
                        let gh_at = |off: usize| {
                            let mut v = gh[gate_base + off];
                            if let Some(bhh) = &b_hh_vals {
                                v += bhh[off];
                            }
                            v
                        };
                        let r = 1.0 / (1.0 + (-(gi_row[gate_base + i] + gh_at(i))).exp());
                        let z = 1.0
                            / (1.0
                                + (-(gi_row[gate_base + hidden_size + i]
                                    + gh_at(hidden_size + i)))
                                .exp());
                        let n = (gi_row[gate_base + 2 * hidden_size + i]
                            + r * gh_at(2 * hidden_size + i))
                        .tanh();
                        let h_idx = b * hidden_size + i;
                        h_out[h_idx] = (1.0 - z) * n + z * h[h_idx];
                    }
                }
                Ok(())
            };

            let row_len = batch_size * three_h;
            let layer_base = layer * num_directions * batch_size * hidden_size;
            let mut gh: Vec<f64> = Vec::with_capacity(row_len);
            let mut h_next = vec![0.0_f64; bh];

            // Forward direction.
            let mut h = h_all[layer_base..layer_base + bh].to_vec();
            for t in 0..seq_len {
                let gi_row = &gi_all[t * row_len..t * row_len + row_len];
                step(&h, gi_row, &mut gh, &mut h_next)?;
                outputs[t][..bh].copy_from_slice(&h_next);
                std::mem::swap(&mut h, &mut h_next);
            }
            h_all[layer_base..layer_base + bh].copy_from_slice(&h);

            // Bidirectional: backward direction reuses the SAME weights/gi.
            if bidirectional {
                let rev_base = layer_base + bh;
                let mut h_rev = h_all[rev_base..rev_base + bh].to_vec();
                for t in (0..seq_len).rev() {
                    let gi_row = &gi_all[t * row_len..t * row_len + row_len];
                    step(&h_rev, gi_row, &mut gh, &mut h_next)?;
                    outputs[t][bh..].copy_from_slice(&h_next);
                    std::mem::swap(&mut h_rev, &mut h_next);
                }
                h_all[rev_base..rev_base + bh].copy_from_slice(&h_rev);
            }

            if layer < num_layers - 1 {
                layer_input = outputs.clone();
            }
        }

        let out_size = hidden_size * num_directions;
        let mut flat_output = Vec::with_capacity(seq_len * batch_size * out_size);
        for t in 0..seq_len {
            flat_output.extend_from_slice(&outputs[t]);
        }

        let out_shape = if batch_first {
            vec![batch_size, seq_len, out_size]
        } else {
            vec![seq_len, batch_size, out_size]
        };
        let output = self.tensor_variable(flat_output, out_shape, false)?;
        let h_n = self.tensor_variable(
            h_all,
            vec![num_layers * num_directions, batch_size, hidden_size],
            false,
        )?;

        Ok((output, h_n))
    }

    /// Process a sequence through an RNN layer (Elman RNN).
    ///
    /// Equivalent to `torch.nn.RNN` forward pass with tanh nonlinearity.
    /// Input shape: (seq_len, batch, input_size) if batch_first=false
    /// Returns (output, h_n)
    pub fn tensor_rnn(
        &mut self,
        input: TensorNodeId,
        hx: Option<TensorNodeId>,
        weights: &[(
            TensorNodeId,
            TensorNodeId,
            Option<TensorNodeId>,
            Option<TensorNodeId>,
        )],
        batch_first: bool,
        bidirectional: bool,
        nonlinearity: &str,
    ) -> Result<(TensorNodeId, TensorNodeId), AutogradError> {
        let input_shape = self.tensor_shape(input)?;
        if input_shape.len() != 3 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "rnn: input must be 3-D",
                },
            )));
        }

        // f32 inputs ERROR (UnsupportedDType(F32)): raw f64 forward reads via F64-only
        // tensor_values. Compute in f64 (upcast input/hidden/weights) then narrow the outputs.
        // frankentorch-fk5l.
        if self.tensor_dtype(input)? == DType::F32 {
            let in64 = self.tensor_to_dtype(input, DType::F64)?;
            let hx64 = match hx {
                Some(h) => Some(self.tensor_to_dtype(h, DType::F64)?),
                None => None,
            };
            let mut weights64 = Vec::with_capacity(weights.len());
            for &(wih, whh, bih, bhh) in weights {
                let wih64 = self.tensor_to_dtype(wih, DType::F64)?;
                let whh64 = self.tensor_to_dtype(whh, DType::F64)?;
                let bih64 = match bih {
                    Some(b) => Some(self.tensor_to_dtype(b, DType::F64)?),
                    None => None,
                };
                let bhh64 = match bhh {
                    Some(b) => Some(self.tensor_to_dtype(b, DType::F64)?),
                    None => None,
                };
                weights64.push((wih64, whh64, bih64, bhh64));
            }
            let (out, hn) = self.tensor_rnn(
                in64,
                hx64,
                &weights64,
                batch_first,
                bidirectional,
                nonlinearity,
            )?;
            return Ok((
                self.tensor_to_dtype(out, DType::F32)?,
                self.tensor_to_dtype(hn, DType::F32)?,
            ));
        }

        let (seq_len, batch_size, _input_size) = if batch_first {
            (input_shape[1], input_shape[0], input_shape[2])
        } else {
            (input_shape[0], input_shape[1], input_shape[2])
        };

        let num_layers = weights.len();
        let num_directions = if bidirectional { 2 } else { 1 };

        let w_hh_shape = self.tensor_shape(weights[0].1)?;
        let hidden_size = w_hh_shape[1];

        let mut h_all = if let Some(h0) = hx {
            self.tensor_values(h0)?
        } else {
            vec![0.0; num_layers * num_directions * batch_size * hidden_size]
        };

        let input_data = self.tensor_values(input)?;
        let input_size = if batch_first {
            input_shape[2]
        } else {
            input_shape[2]
        };

        let mut layer_input: Vec<Vec<f64>> = Vec::with_capacity(seq_len);
        for t in 0..seq_len {
            let mut seq_data = Vec::with_capacity(batch_size * input_size);
            for b in 0..batch_size {
                for i in 0..input_size {
                    let idx = if batch_first {
                        b * seq_len * input_size + t * input_size + i
                    } else {
                        t * batch_size * input_size + b * input_size + i
                    };
                    seq_data.push(input_data[idx]);
                }
            }
            layer_input.push(seq_data);
        }

        let mut outputs: Vec<Vec<f64>> =
            vec![vec![0.0; batch_size * hidden_size * num_directions]; seq_len];

        let use_relu = nonlinearity == "relu";

        // Raw no-grad forward (frankentorch-3k4v) — same scheme as tensor_lstm,
        // single gate. gates = ((x@W_ih^T + h@W_hh^T) + b_ih) + b_hh then the
        // nonlinearity. The input projection is batched over the whole sequence
        // in ONE matmul; only h@W_hh^T runs per step (into a reused buffer); h is
        // double-buffered. relu replicates the kernel's v.max(0.0) and tanh is
        // libm, so results are bit-identical to the rnn_*_cell session path
        // (guarded by rnn_raw_forward_golden_isomorphism).
        let bh = batch_size * hidden_size;
        let kernel_err = |e: ft_kernel_cpu::KernelError| {
            AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
        };

        for layer in 0..num_layers {
            let (w_ih, w_hh, b_ih, b_hh) = &weights[layer];
            let in_sz = if layer == 0 {
                input_size
            } else {
                hidden_size * num_directions
            };

            let w_ih_vals = self.tensor_values(*w_ih)?; // [hidden, in_sz]
            let w_hh_vals = self.tensor_values(*w_hh)?; // [hidden, hidden]
            let b_ih_vals = match b_ih {
                Some(b) => Some(self.tensor_values(*b)?),
                None => None,
            };
            let b_hh_vals = match b_hh {
                Some(b) => Some(self.tensor_values(*b)?),
                None => None,
            };

            // Batched input projection over ALL timesteps: [seq*batch, in] @ W_ih^T.
            let mut x_all = Vec::with_capacity(seq_len * batch_size * in_sz);
            for seq_data in layer_input.iter().take(seq_len) {
                x_all.extend_from_slice(seq_data);
            }
            let xw_all = ft_kernel_cpu::matmul_rhs_transposed_contiguous_f64(
                seq_len * batch_size,
                in_sz,
                hidden_size,
                &x_all,
                &w_ih_vals,
            )
            .map_err(kernel_err)?; // [seq*batch, hidden]

            // One RNN step: act(((xw_row + h @ W_hh^T) + b_ih) + b_hh).
            let step = |h: &[f64],
                        xw_row: &[f64],
                        hg: &mut Vec<f64>,
                        h_out: &mut [f64]|
             -> Result<(), AutogradError> {
                ft_kernel_cpu::matmul_rhs_transposed_contiguous_f64_into(
                    hg,
                    batch_size,
                    hidden_size,
                    hidden_size,
                    h,
                    &w_hh_vals,
                )
                .map_err(kernel_err)?;
                for b in 0..batch_size {
                    let base = b * hidden_size;
                    for i in 0..hidden_size {
                        let mut v = xw_row[base + i] + hg[base + i];
                        if let Some(bih) = &b_ih_vals {
                            v += bih[i];
                        }
                        if let Some(bhh) = &b_hh_vals {
                            v += bhh[i];
                        }
                        h_out[base + i] = if use_relu { v.max(0.0) } else { v.tanh() };
                    }
                }
                Ok(())
            };

            let layer_base = layer * num_directions * batch_size * hidden_size;
            let mut hg: Vec<f64> = Vec::with_capacity(bh);
            let mut h_next = vec![0.0_f64; bh];

            // Forward direction.
            let mut h = h_all[layer_base..layer_base + bh].to_vec();
            for t in 0..seq_len {
                let xw_row = &xw_all[t * bh..t * bh + bh];
                step(&h, xw_row, &mut hg, &mut h_next)?;
                outputs[t][..bh].copy_from_slice(&h_next);
                std::mem::swap(&mut h, &mut h_next);
            }
            h_all[layer_base..layer_base + bh].copy_from_slice(&h);

            if bidirectional {
                let rev_base = layer_base + bh;
                let mut h_rev = h_all[rev_base..rev_base + bh].to_vec();
                for t in (0..seq_len).rev() {
                    let xw_row = &xw_all[t * bh..t * bh + bh];
                    step(&h_rev, xw_row, &mut hg, &mut h_next)?;
                    outputs[t][bh..].copy_from_slice(&h_next);
                    std::mem::swap(&mut h_rev, &mut h_next);
                }
                h_all[rev_base..rev_base + bh].copy_from_slice(&h_rev);
            }

            if layer < num_layers - 1 {
                layer_input = outputs.clone();
            }
        }

        let out_size = hidden_size * num_directions;
        let mut flat_output = Vec::with_capacity(seq_len * batch_size * out_size);
        for t in 0..seq_len {
            flat_output.extend_from_slice(&outputs[t]);
        }

        let out_shape = if batch_first {
            vec![batch_size, seq_len, out_size]
        } else {
            vec![seq_len, batch_size, out_size]
        };
        let output = self.tensor_variable(flat_output, out_shape, false)?;
        let h_n = self.tensor_variable(
            h_all,
            vec![num_layers * num_directions, batch_size, hidden_size],
            false,
        )?;

        Ok((output, h_n))
    }

    /// Save a tensor to a file.
    ///
    /// Equivalent to `torch.save(tensor, path)` for single tensors.
    /// Uses a simple binary format: magic + shape + dtype + requires_grad + values.
    ///
    /// # Arguments
    /// * `tensor` - Tensor to save
    /// * `path` - File path to save to
    pub fn tensor_save(
        &self,
        tensor: TensorNodeId,
        path: &std::path::Path,
    ) -> Result<(), AutogradError> {
        use std::io::Write;

        let values = self.tensor_values(tensor)?;
        let shape = self.tensor_shape(tensor)?;
        let dtype = self.tensor_dtype(tensor)?;
        let requires_grad = self.tensor_requires_grad(tensor)?;

        let mut file = std::fs::File::create(path).map_err(|e| {
            AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: Box::leak(format!("tensor_save: {}", e).into_boxed_str()),
                },
            ))
        })?;

        // Magic bytes
        file.write_all(b"FTENSOR\0").map_err(|e| {
            AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: Box::leak(format!("tensor_save: write error: {}", e).into_boxed_str()),
                },
            ))
        })?;

        // Number of dimensions
        let ndim = shape.len() as u32;
        file.write_all(&ndim.to_le_bytes()).map_err(|_| {
            AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "tensor_save: write error",
                },
            ))
        })?;

        // Shape
        for &dim in &shape {
            file.write_all(&(dim as u64).to_le_bytes()).map_err(|_| {
                AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "tensor_save: write error",
                    },
                ))
            })?;
        }

        // DType (as u8)
        let dtype_byte: u8 = match dtype {
            DType::F32 => 0,
            DType::F64 => 1,
            DType::I32 => 2,
            DType::I64 => 3,
            DType::Bool => 4,
            DType::Complex64 => 5,
            DType::Complex128 => 6,
            _ => 1, // default to F64
        };
        file.write_all(&[dtype_byte]).map_err(|_| {
            AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "tensor_save: write error",
                },
            ))
        })?;

        // requires_grad flag
        file.write_all(&[if requires_grad { 1 } else { 0 }])
            .map_err(|_| {
                AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "tensor_save: write error",
                    },
                ))
            })?;

        // Values as f64 bytes
        for &val in &values {
            file.write_all(&val.to_le_bytes()).map_err(|_| {
                AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "tensor_save: write error",
                    },
                ))
            })?;
        }

        Ok(())
    }

    /// Load a tensor from a file.
    ///
    /// Equivalent to `torch.load(path)` for single tensors.
    /// Reads the binary format written by `tensor_save`.
    ///
    /// # Arguments
    /// * `path` - File path to load from
    ///
    /// # Returns
    /// The loaded tensor
    pub fn tensor_load(&mut self, path: &std::path::Path) -> Result<TensorNodeId, AutogradError> {
        use std::io::Read;

        let mut file = std::fs::File::open(path).map_err(|e| {
            AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: Box::leak(format!("tensor_load: {}", e).into_boxed_str()),
                },
            ))
        })?;

        // Read magic bytes
        let mut magic = [0u8; 8];
        file.read_exact(&mut magic).map_err(|_| {
            AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "tensor_load: invalid file format",
                },
            ))
        })?;
        if &magic != b"FTENSOR\0" {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "tensor_load: invalid magic bytes",
                },
            )));
        }

        // Read ndim
        let mut ndim_buf = [0u8; 4];
        file.read_exact(&mut ndim_buf).map_err(|_| {
            AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "tensor_load: read error",
                },
            ))
        })?;
        let ndim = u32::from_le_bytes(ndim_buf) as usize;

        // Read shape
        let mut shape = Vec::with_capacity(ndim);
        for _ in 0..ndim {
            let mut dim_buf = [0u8; 8];
            file.read_exact(&mut dim_buf).map_err(|_| {
                AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "tensor_load: read error",
                    },
                ))
            })?;
            shape.push(u64::from_le_bytes(dim_buf) as usize);
        }

        // Read dtype
        let mut dtype_buf = [0u8; 1];
        file.read_exact(&mut dtype_buf).map_err(|_| {
            AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "tensor_load: read error",
                },
            ))
        })?;

        // Read requires_grad
        let mut rg_buf = [0u8; 1];
        file.read_exact(&mut rg_buf).map_err(|_| {
            AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "tensor_load: read error",
                },
            ))
        })?;
        let requires_grad = rg_buf[0] != 0;

        // Compute numel
        let numel: usize = shape.iter().product();

        // Read values
        let mut values = Vec::with_capacity(numel);
        for _ in 0..numel {
            let mut val_buf = [0u8; 8];
            file.read_exact(&mut val_buf).map_err(|_| {
                AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "tensor_load: read error",
                    },
                ))
            })?;
            values.push(f64::from_le_bytes(val_buf));
        }

        self.tensor_variable(values, shape, requires_grad)
    }

    /// Save multiple tensors to a file as a state dict.
    ///
    /// Equivalent to `torch.save(state_dict, path)`.
    /// Uses a simple format with named tensors.
    ///
    /// # Arguments
    /// * `tensors` - List of (name, tensor) pairs
    /// * `path` - File path to save to
    pub fn tensor_save_state_dict(
        &self,
        tensors: &[(&str, TensorNodeId)],
        path: &std::path::Path,
    ) -> Result<(), AutogradError> {
        use std::io::Write;

        let mut file = std::fs::File::create(path).map_err(|e| {
            AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: Box::leak(format!("tensor_save_state_dict: {}", e).into_boxed_str()),
                },
            ))
        })?;

        // Magic for state dict
        file.write_all(b"FTSTDICT").map_err(|_| {
            AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "tensor_save_state_dict: write error",
                },
            ))
        })?;

        // Number of tensors
        let count = tensors.len() as u32;
        file.write_all(&count.to_le_bytes()).map_err(|_| {
            AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "tensor_save_state_dict: write error",
                },
            ))
        })?;

        for &(name, tensor) in tensors {
            // Name length and bytes
            let name_bytes = name.as_bytes();
            file.write_all(&(name_bytes.len() as u32).to_le_bytes())
                .map_err(|_| {
                    AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "tensor_save_state_dict: write error",
                        },
                    ))
                })?;
            file.write_all(name_bytes).map_err(|_| {
                AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "tensor_save_state_dict: write error",
                    },
                ))
            })?;

            // Tensor data (inline, same as tensor_save)
            let values = self.tensor_values(tensor)?;
            let shape = self.tensor_shape(tensor)?;

            let ndim = shape.len() as u32;
            file.write_all(&ndim.to_le_bytes()).map_err(|_| {
                AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "tensor_save_state_dict: write error",
                    },
                ))
            })?;

            for &dim in &shape {
                file.write_all(&(dim as u64).to_le_bytes()).map_err(|_| {
                    AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "tensor_save_state_dict: write error",
                        },
                    ))
                })?;
            }

            for &val in &values {
                file.write_all(&val.to_le_bytes()).map_err(|_| {
                    AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "tensor_save_state_dict: write error",
                        },
                    ))
                })?;
            }
        }

        Ok(())
    }

    /// Load a state dict from a file.
    ///
    /// Equivalent to `torch.load(path)` for state dicts.
    /// Returns a list of (name, tensor) pairs.
    pub fn tensor_load_state_dict(
        &mut self,
        path: &std::path::Path,
    ) -> Result<Vec<(String, TensorNodeId)>, AutogradError> {
        use std::io::Read;

        let mut file = std::fs::File::open(path).map_err(|e| {
            AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: Box::leak(format!("tensor_load_state_dict: {}", e).into_boxed_str()),
                },
            ))
        })?;

        let mut magic = [0u8; 8];
        file.read_exact(&mut magic).map_err(|_| {
            AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "tensor_load_state_dict: invalid format",
                },
            ))
        })?;
        if &magic != b"FTSTDICT" {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "tensor_load_state_dict: invalid magic",
                },
            )));
        }

        let mut count_buf = [0u8; 4];
        file.read_exact(&mut count_buf).map_err(|_| {
            AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "tensor_load_state_dict: read error",
                },
            ))
        })?;
        let count = u32::from_le_bytes(count_buf) as usize;

        let mut result = Vec::with_capacity(count);

        for _ in 0..count {
            // Read name
            let mut name_len_buf = [0u8; 4];
            file.read_exact(&mut name_len_buf).map_err(|_| {
                AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "tensor_load_state_dict: read error",
                    },
                ))
            })?;
            let name_len = u32::from_le_bytes(name_len_buf) as usize;

            let mut name_bytes = vec![0u8; name_len];
            file.read_exact(&mut name_bytes).map_err(|_| {
                AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "tensor_load_state_dict: read error",
                    },
                ))
            })?;
            let name = String::from_utf8(name_bytes).map_err(|_| {
                AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "tensor_load_state_dict: invalid name",
                    },
                ))
            })?;

            // Read tensor
            let mut ndim_buf = [0u8; 4];
            file.read_exact(&mut ndim_buf).map_err(|_| {
                AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "tensor_load_state_dict: read error",
                    },
                ))
            })?;
            let ndim = u32::from_le_bytes(ndim_buf) as usize;

            let mut shape = Vec::with_capacity(ndim);
            for _ in 0..ndim {
                let mut dim_buf = [0u8; 8];
                file.read_exact(&mut dim_buf).map_err(|_| {
                    AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "tensor_load_state_dict: read error",
                        },
                    ))
                })?;
                shape.push(u64::from_le_bytes(dim_buf) as usize);
            }

            let numel: usize = shape.iter().product();
            let mut values = Vec::with_capacity(numel);
            for _ in 0..numel {
                let mut val_buf = [0u8; 8];
                file.read_exact(&mut val_buf).map_err(|_| {
                    AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "tensor_load_state_dict: read error",
                        },
                    ))
                })?;
                values.push(f64::from_le_bytes(val_buf));
            }

            let tensor = self.tensor_variable(values, shape, false)?;
            result.push((name, tensor));
        }

        Ok(result)
    }

    #[must_use]
    pub fn evidence(&self) -> &[EvidenceEntry] {
        self.runtime.ledger().entries()
    }

    #[must_use]
    pub fn evidence_len(&self) -> usize {
        self.runtime.ledger().len()
    }

    fn checked_shape_numel(
        shape: &[usize],
        overflow_reason: &'static str,
    ) -> Result<usize, AutogradError> {
        let mut product = 1usize;
        for dim in shape.iter().copied() {
            if dim == 0 {
                return Ok(0);
            }
            let Some(next) = product.checked_mul(dim) else {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: overflow_reason,
                    },
                )));
            };
            product = next;
        }
        Ok(product)
    }

    fn checked_mul(
        lhs: usize,
        rhs: usize,
        overflow_reason: &'static str,
    ) -> Result<usize, AutogradError> {
        lhs.checked_mul(rhs).ok_or({
            AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: overflow_reason,
                },
            ))
        })
    }

    fn checked_add(
        lhs: usize,
        rhs: usize,
        overflow_reason: &'static str,
    ) -> Result<usize, AutogradError> {
        lhs.checked_add(rhs).ok_or({
            AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: overflow_reason,
                },
            ))
        })
    }

    fn require_f64_tensor_storage(&self, input: TensorNodeId) -> Result<(), AutogradError> {
        let dtype = self.tensor_tape.tensor_meta(input)?.dtype();
        if dtype != DType::F64 {
            return Err(AutogradError::DenseTensor(
                ft_core::DenseTensorError::UnsupportedStorageAccess { dtype },
            ));
        }
        Ok(())
    }

    fn adaptive_avg_pool_window(
        output_index: usize,
        input_size: usize,
        output_size: usize,
        overflow_reason: &'static str,
    ) -> Result<(usize, usize), AutogradError> {
        let start_num = Self::checked_mul(output_index, input_size, overflow_reason)?;
        let start = start_num / output_size;
        let next_output_index = Self::checked_add(output_index, 1, overflow_reason)?;
        let end_num = Self::checked_mul(next_output_index, input_size, overflow_reason)?;
        let end = end_num.div_ceil(output_size);
        if end <= start {
            return Err(Self::incompatible_tensor_args(
                "adaptive_avg_pool: pooling window contains no input elements",
            ));
        }
        Ok((start, end))
    }

    fn checked_conv_transpose_output_dim(
        spec: ConvTransposeOutputDimSpec,
        errors: ConvTransposeOutputDimErrors,
    ) -> Result<usize, AutogradError> {
        let span = Self::checked_mul(spec.input - 1, spec.stride, errors.overflow)?;
        let base = Self::checked_add(span, spec.kernel, errors.overflow)?;
        let base = Self::checked_add(base, spec.output_padding, errors.overflow)?;
        let padding = Self::checked_mul(spec.padding, 2, errors.padding_overflow)?;
        if base <= padding {
            return Err(Self::incompatible_tensor_args(errors.underflow));
        }
        Ok(base - padding)
    }

    fn checked_square_numel(
        n: usize,
        overflow_reason: &'static str,
    ) -> Result<usize, AutogradError> {
        n.checked_mul(n).ok_or({
            AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: overflow_reason,
                },
            ))
        })
    }

    fn exact_integer_index_to_isize(
        value: f64,
        invalid_reason: &'static str,
    ) -> Result<isize, AutogradError> {
        if !value.is_finite() || value.trunc() != value {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: invalid_reason,
                },
            )));
        }
        if value < isize::MIN as f64 || value > isize::MAX as f64 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: invalid_reason,
                },
            )));
        }
        let converted = value as isize;
        if converted as f64 != value {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: invalid_reason,
                },
            )));
        }
        Ok(converted)
    }

    fn exact_nonnegative_index_to_usize(
        value: f64,
        invalid_reason: &'static str,
    ) -> Result<usize, AutogradError> {
        if !value.is_finite() || value < 0.0 || value.trunc() != value {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: invalid_reason,
                },
            )));
        }
        if value > usize::MAX as f64 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: invalid_reason,
                },
            )));
        }
        let converted = value as usize;
        if converted as f64 != value {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: invalid_reason,
                },
            )));
        }
        Ok(converted)
    }

    fn update_tensor_values_for_float(
        &mut self,
        target: TensorNodeId,
        values: Vec<f64>,
        reason: &'static str,
    ) -> Result<(), AutogradError> {
        match self.tensor_tape.dtype(target)? {
            DType::F64 => self.tensor_tape.update_tensor_values(target, values),
            DType::F32 => {
                let values_f32: Vec<f32> = values.iter().map(|&v| v as f32).collect();
                self.tensor_tape
                    .update_tensor_values_f32(target, values_f32)
            }
            _ => Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet { reason },
            ))),
        }
    }

    fn validate_tensor_in_place_binary_compatibility(
        &self,
        target: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<(), AutogradError> {
        self.validate_tensor_in_place_target(target)?;
        let target_meta = self.tensor_tape.tensor_meta(target)?;
        let other_meta = self.tensor_tape.tensor_meta(other)?;
        if target_meta.shape() != other_meta.shape() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: target_meta.shape().to_vec(),
                    rhs: other_meta.shape().to_vec(),
                },
            )));
        }
        if target_meta.dtype() != other_meta.dtype() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::Incompatible(TensorCompatError::DTypeMismatch {
                    lhs: target_meta.dtype(),
                    rhs: other_meta.dtype(),
                }),
            )));
        }
        if target_meta.device() != other_meta.device() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::Incompatible(TensorCompatError::DeviceMismatch {
                    lhs: target_meta.device(),
                    rhs: other_meta.device(),
                }),
            )));
        }
        Ok(())
    }

    fn validate_tensor_in_place_target(&self, target: TensorNodeId) -> Result<(), AutogradError> {
        if self.is_grad_enabled()
            && self.tensor_tape.tensor_is_leaf(target)?
            && self.tensor_tape.tensor_requires_grad(target)?
        {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "in-place mutation on leaf tensors that require grad is forbidden",
                },
            )));
        }
        Ok(())
    }

    fn apply_tensor_unary_in_place<F>(
        &mut self,
        op: &'static str,
        target: TensorNodeId,
        extra: Option<String>,
        transform: F,
    ) -> Result<(), AutogradError>
    where
        F: Fn(f64) -> f64 + Sync,
    {
        use rayon::prelude::*;
        self.validate_tensor_in_place_target(target)?;
        match self.tensor_tape.dtype(target)? {
            DType::F64 => {
                // True in-place transform: ONE pass over the contiguous storage, vs the
                // old clone (values()) -> serial map+collect -> writeback (3 serial passes).
                // The map is compute-heavy for the transcendental in-place ops routed
                // through this helper (exp_/log_/erf_/lgamma_/digamma_/gelu_/silu_/i0_/...),
                // so parallelizing it scales with cores; the in-place-with also drops 2
                // full-size memcpys. Bit-identical: `*v = transform(*v)` per element,
                // order-independent. Contiguity contract is unchanged — the old
                // update_contiguous_values writeback ALSO required is_contiguous() (same
                // UnsupportedLayout error otherwise). frankentorch-inplace-unary-par.
                self.tensor_tape.update_tensor_values_with(target, |vals| {
                    if vals.len() >= PARALLEL_ELEMENTWISE_MIN {
                        vals.par_iter_mut().for_each(|v| *v = transform(*v));
                    } else {
                        for v in vals.iter_mut() {
                            *v = transform(*v);
                        }
                    }
                })?;
            }
            DType::F32 => {
                // f32 has no in-place `_with` accessor, so keep clone -> map -> writeback,
                // but parallelize the (compute-heavy) map. Bit-identical: par collect
                // preserves index order.
                let target_vals = self.tensor_tape.values_f32(target)?;
                let new_values: Vec<f32> = if target_vals.len() >= PARALLEL_ELEMENTWISE_MIN {
                    target_vals
                        .par_iter()
                        .map(|&v| transform(v as f64) as f32)
                        .collect()
                } else {
                    target_vals
                        .iter()
                        .map(|&v| transform(v as f64) as f32)
                        .collect()
                };
                self.tensor_tape
                    .update_tensor_values_f32(target, new_values)?;
            }
            _ => {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: INPLACE_FLOAT_REASON,
                    },
                )));
            }
        }
        self.record_tensor_in_place_operation(op, target, extra);
        Ok(())
    }

    fn record_operation(&mut self, event: &OperationEvent) {
        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!(
                "op={:?} lhs={} rhs={} out={} mode={:?} kernel={} key={:?} backend={:?} keyset=0x{:016x} fallback={}",
                event.op,
                event.lhs.0,
                event.rhs.0,
                event.out.0,
                event.decision.mode,
                event.decision.kernel,
                event.decision.selected_key,
                event.decision.backend_key,
                event.decision.keyset_bits,
                event.decision.fallback_used
            ),
        );
    }

