    fn record_tensor_smooth_l1_reduction_operation(
        &mut self,
        input: TensorNodeId,
        target: TensorNodeId,
        out: TensorNodeId,
        reduction: &str,
        kernel: &'static str,
    ) -> Result<(), AutogradError> {
        let meta = self.tensor_tape.tensor(input)?.meta();
        let keyset = dispatch_keyset_for_single_tensor_meta(meta, false);
        let selected_key = keyset
            .highest_priority_type_id()
            .map_err(|err| AutogradError::Dispatch(err.into()))?;
        let backend_key = keyset
            .highest_priority_backend_type_id()
            .map_err(|err| AutogradError::Dispatch(err.into()))?;
        let mode = self.mode();
        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!(
                "tensor_smooth_l1_reduction input={} target={} out={} reduction={} mode={:?} kernel={} key={:?} backend={:?} keyset=0x{:016x} fallback=false",
                input.0,
                target.0,
                out.0,
                reduction,
                mode,
                kernel,
                selected_key,
                backend_key,
                keyset.bits()
            ),
        );
        Ok(())
    }

