    fn scalar_comparison(
        &mut self,
        op: ComparisonOp,
        lhs: NodeId,
        rhs: NodeId,
    ) -> Result<NodeId, AutogradError> {
        let lhs_value = self.tape.value(lhs)?;
        let rhs_value = self.tape.value(rhs)?;
        let lhs_scalar = ft_core::ScalarTensor::new(lhs_value, ft_core::DType::F64, Device::Cpu);
        let rhs_scalar = ft_core::ScalarTensor::new(rhs_value, ft_core::DType::F64, Device::Cpu);

        let outcome = dispatch_scalar_comparison(op, self.mode(), &lhs_scalar, &rhs_scalar, false)
            .map_err(AutogradError::Dispatch)?;

        let out = self.tape.leaf(outcome.tensor.value(), false);
        self.record_comparison_operation(op, &outcome.decision);
        Ok(out)
    }

    fn tensor_comparison(
        &mut self,
        op: ComparisonOp,
        lhs: TensorNodeId,
        rhs: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let (lhs_meta, rhs_meta) = {
            let lhs_tensor = self.tensor_tape.tensor(lhs)?;
            let rhs_tensor = self.tensor_tape.tensor(rhs)?;
            (lhs_tensor.meta().clone(), rhs_tensor.meta().clone())
        };

        // No-grad fast path: the f64/f32 arms below CLONE both operands via
        // `storage()?.to_vec()` (2*numel) before the kernel — measured ~40-50x SLOWER than
        // torch at [4000,4000]. For equal-shape contiguous f64 with grad off, BORROW both
        // operands and pass the borrowed slices to the same (already-parallel) dispatch
        // kernel — identical result, no clones. Broadcast / non-contiguous / grad /
        // mixed-or-non-f64 dtype fall through to the cloning arms below.
        if !self.tensor_requires_grad(lhs)?
            && !self.tensor_requires_grad(rhs)?
            && lhs_meta.dtype() == DType::F64
            && rhs_meta.dtype() == DType::F64
            && lhs_meta.shape() == rhs_meta.shape()
        {
            let outcome = {
                let lhs_tensor = self.tensor_tape.tensor(lhs)?;
                let rhs_tensor = self.tensor_tape.tensor(rhs)?;
                if lhs_tensor.meta().is_contiguous() && rhs_tensor.meta().is_contiguous() {
                    let lhs_vals = lhs_tensor.contiguous_values()?;
                    let rhs_vals = rhs_tensor.contiguous_values()?;
                    Some(
                        dispatch_tensor_comparison_contiguous_f64(
                            op,
                            self.mode(),
                            lhs_vals,
                            rhs_vals,
                            &lhs_meta,
                            &rhs_meta,
                            false,
                        )
                        .map_err(AutogradError::Dispatch)?,
                    )
                } else {
                    None
                }
            };
            if let Some(outcome) = outcome {
                let out =
                    self.tensor_tape
                        .leaf(outcome.values, lhs_meta.shape().to_vec(), false)?;
                self.record_comparison_operation(op, &outcome.decision);
                return Ok(out);
            }
        }

        // F32 sibling of the above no-grad borrow fast path: the F32 arm below
        // clones BOTH operands via `as_f32().to_vec()` (2*numel) before the
        // already-parallel f32 comparison kernel — measured ~40x SLOWER than torch
        // at [4000,4000] (eq 93ms vs 2.5ms). For equal-shape contiguous f32 with grad
        // off, BORROW both operands instead — identical result (comparison is a pure
        // value test, no rounding), no clones. frankentorch-kgs4.169.
        if !self.tensor_requires_grad(lhs)?
            && !self.tensor_requires_grad(rhs)?
            && lhs_meta.dtype() == DType::F32
            && rhs_meta.dtype() == DType::F32
            && lhs_meta.shape() == rhs_meta.shape()
        {
            let outcome = {
                let lhs_tensor = self.tensor_tape.tensor(lhs)?;
                let rhs_tensor = self.tensor_tape.tensor(rhs)?;
                if lhs_tensor.meta().is_contiguous() && rhs_tensor.meta().is_contiguous() {
                    let lhs_vals = lhs_tensor.contiguous_values_f32()?;
                    let rhs_vals = rhs_tensor.contiguous_values_f32()?;
                    Some(
                        dispatch_tensor_comparison_contiguous_f32(
                            op,
                            self.mode(),
                            lhs_vals,
                            rhs_vals,
                            &lhs_meta,
                            &rhs_meta,
                            false,
                        )
                        .map_err(AutogradError::Dispatch)?,
                    )
                } else {
                    None
                }
            };
            if let Some(outcome) = outcome {
                let out =
                    self.tensor_tape
                        .leaf_f32(outcome.values, lhs_meta.shape().to_vec(), false)?;
                self.record_comparison_operation(op, &outcome.decision);
                return Ok(out);
            }
        }

        match (lhs_meta.dtype(), rhs_meta.dtype()) {
            (DType::F64, DType::F64) => {
                let (lhs_storage, rhs_storage) = {
                    let lhs_tensor = self.tensor_tape.tensor(lhs)?;
                    let rhs_tensor = self.tensor_tape.tensor(rhs)?;
                    (
                        lhs_tensor.storage()?.to_vec(),
                        rhs_tensor.storage()?.to_vec(),
                    )
                };
                let outcome = dispatch_tensor_comparison_contiguous_f64(
                    op,
                    self.mode(),
                    &lhs_storage,
                    &rhs_storage,
                    &lhs_meta,
                    &rhs_meta,
                    false,
                )
                .map_err(AutogradError::Dispatch)?;

                let out =
                    self.tensor_tape
                        .leaf(outcome.values, lhs_meta.shape().to_vec(), false)?;
                self.record_comparison_operation(op, &outcome.decision);
                Ok(out)
            }
            (DType::F32, DType::F32) => {
                let (lhs_storage, rhs_storage) = {
                    let lhs_tensor = self.tensor_tape.tensor(lhs)?;
                    let rhs_tensor = self.tensor_tape.tensor(rhs)?;
                    let lhs_vals =
                        lhs_tensor
                            .typed_storage()
                            .as_f32()
                            .ok_or(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                                ft_dispatch::DispatchKeyError::IncompatibleSet {
                                    reason: "tensor comparison requires f32 storage",
                                },
                            )))?;
                    let rhs_vals =
                        rhs_tensor
                            .typed_storage()
                            .as_f32()
                            .ok_or(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                                ft_dispatch::DispatchKeyError::IncompatibleSet {
                                    reason: "tensor comparison requires f32 storage",
                                },
                            )))?;
                    (lhs_vals.to_vec(), rhs_vals.to_vec())
                };

                let outcome = dispatch_tensor_comparison_contiguous_f32(
                    op,
                    self.mode(),
                    &lhs_storage,
                    &rhs_storage,
                    &lhs_meta,
                    &rhs_meta,
                    false,
                )
                .map_err(AutogradError::Dispatch)?;

                let out =
                    self.tensor_tape
                        .leaf_f32(outcome.values, lhs_meta.shape().to_vec(), false)?;
                self.record_comparison_operation(op, &outcome.decision);
                Ok(out)
            }
            (DType::F16, DType::F16) | (DType::BF16, DType::BF16) => {
                // Comparison is value-only (no arithmetic): upcast both operands to
                // f64 (lossless for f16/bf16), run the f64 comparison, then narrow
                // the 0.0/1.0 mask back to the input half dtype so the result keeps
                // the input dtype (matching the f32 path's f32 mask). The half mask
                // is exact (0/1 are representable) and matches the operand dtype so
                // downstream ops like nan_to_num's tensor_where line up.
                // frankentorch-u78p.
                let half_dtype = lhs_meta.dtype();
                let (lhs_f64, rhs_f64) = {
                    let lhs_tensor = self.tensor_tape.tensor(lhs)?;
                    let rhs_tensor = self.tensor_tape.tensor(rhs)?;
                    (
                        lhs_tensor.contiguous_values_as_f64()?,
                        rhs_tensor.contiguous_values_as_f64()?,
                    )
                };
                let lhs_f64_meta = TensorMeta::from_shape(
                    lhs_meta.shape().to_vec(),
                    DType::F64,
                    lhs_meta.device(),
                );
                let rhs_f64_meta = TensorMeta::from_shape(
                    rhs_meta.shape().to_vec(),
                    DType::F64,
                    rhs_meta.device(),
                );
                let outcome = dispatch_tensor_comparison_contiguous_f64(
                    op,
                    self.mode(),
                    &lhs_f64,
                    &rhs_f64,
                    &lhs_f64_meta,
                    &rhs_f64_meta,
                    false,
                )
                .map_err(AutogradError::Dispatch)?;
                let mask =
                    self.tensor_tape
                        .leaf(outcome.values, lhs_meta.shape().to_vec(), false)?;
                let out = self.tensor_tape.to_dtype(mask, half_dtype)?;
                self.record_comparison_operation(op, &outcome.decision);
                Ok(out)
            }
            _ => Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "tensor comparison requires matching f32, f64, f16, or bf16 dtypes",
                },
            ))),
        }
    }

    fn scalar_float_classify(
        &mut self,
        op: UnaryOp,
        input: NodeId,
    ) -> Result<NodeId, AutogradError> {
        let value = self.tape.value(input)?;
        let scalar = ft_core::ScalarTensor::new(value, ft_core::DType::F64, Device::Cpu);

        let outcome = dispatch_scalar_unary(op, self.mode(), &scalar, false)
            .map_err(AutogradError::Dispatch)?;

        let out = self.tape.leaf(outcome.tensor.value(), false);
        self.record_float_classify_operation(op, &outcome.decision);
        Ok(out)
    }

    fn tensor_float_classify(
        &mut self,
        op: UnaryOp,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let (meta, dtype) = {
            let tensor = self.tensor_tape.tensor(input)?;
            (tensor.meta().clone(), tensor.meta().dtype())
        };

        match dtype {
            DType::F64 => {
                let storage = {
                    let tensor = self.tensor_tape.tensor(input)?;
                    tensor.storage()?.to_vec()
                };
                let outcome =
                    dispatch_tensor_unary_contiguous_f64(op, self.mode(), &storage, &meta, false)
                        .map_err(AutogradError::Dispatch)?;

                let out = self
                    .tensor_tape
                    .leaf(outcome.values, meta.shape().to_vec(), false)?;
                self.record_float_classify_operation(op, &outcome.decision);
                Ok(out)
            }
            DType::F32 => {
                let storage = {
                    let tensor = self.tensor_tape.tensor(input)?;
                    let vals = tensor
                        .typed_storage()
                        .as_f32()
                        .ok_or(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                            ft_dispatch::DispatchKeyError::IncompatibleSet {
                                reason: "float classify requires f32 storage",
                            },
                        )))?;
                    vals.to_vec()
                };
                let outcome =
                    dispatch_tensor_unary_contiguous_f32(op, self.mode(), &storage, &meta, false)
                        .map_err(AutogradError::Dispatch)?;

                let out =
                    self.tensor_tape
                        .leaf_f32(outcome.values, meta.shape().to_vec(), false)?;
                self.record_float_classify_operation(op, &outcome.decision);
                Ok(out)
            }
            DType::F16 | DType::BF16 => {
                // isnan/isinf are value-only predicates: upcast to f64 (lossless;
                // f16/bf16 NaN/inf map to f64 NaN/inf) and run the f64 classify,
                // then narrow the 0.0/1.0 mask back to the input half dtype so the
                // result matches the operand dtype (like the f32 path). frankentorch-u78p.
                let half_dtype = dtype;
                let storage = {
                    let tensor = self.tensor_tape.tensor(input)?;
                    tensor.contiguous_values_as_f64()?
                };
                let f64_meta =
                    TensorMeta::from_shape(meta.shape().to_vec(), DType::F64, meta.device());
                let outcome = dispatch_tensor_unary_contiguous_f64(
                    op,
                    self.mode(),
                    &storage,
                    &f64_meta,
                    false,
                )
                .map_err(AutogradError::Dispatch)?;
                let mask = self
                    .tensor_tape
                    .leaf(outcome.values, meta.shape().to_vec(), false)?;
                let out = self.tensor_tape.to_dtype(mask, half_dtype)?;
                self.record_float_classify_operation(op, &outcome.decision);
                Ok(out)
            }
            _ => Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "float classify requires f32, f64, f16, or bf16 tensors",
                },
            ))),
        }
    }

    fn record_float_classify_operation(&mut self, op: UnaryOp, decision: &UnaryDispatchDecision) {
        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!(
                "float_classify_op={:?} mode={:?} kernel={} key={:?} backend={:?} keyset=0x{:016x} fallback={}",
                op,
                decision.mode,
                decision.kernel,
                decision.selected_key,
                decision.backend_key,
                decision.keyset_bits,
                decision.fallback_used
            ),
        );
    }

