    pub fn tensor_contiguous(&self, node: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        Ok(node)
    }

    /// Create a copy of a tensor detached from the computation graph.
    /// The resulting tensor has `requires_grad = false`.
    pub fn tensor_detach(&mut self, node: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        self.tensor_clone(node, false)
    }

    /// Return the tensor's data without gradient tracking.
    ///
    /// Equivalent to `tensor.data` in PyTorch. In FrankenTorch, this is
    /// an alias for `tensor_detach` since tensors are immutable and
    /// value-semantics based (no shared storage).
    pub fn tensor_data(&mut self, node: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        self.tensor_detach(node)
    }

    /// Return true (1.0) if any element in the tensor is non-zero.
    pub fn tensor_any(&self, node: TensorNodeId) -> Result<bool, AutogradError> {
        // Borrow the storage zero-copy — `values()` cloned the full input (the same
        // 128MB clone that cost count_nonzero ~84ms) just to short-circuit-scan it.
        match self.tensor_tape.values_borrowed(node) {
            Ok(v) => Ok(v.iter().any(|&x| x != 0.0)),
            Err(_) => Ok(self.tensor_tape.values(node)?.iter().any(|&x| x != 0.0)),
        }
    }

    /// Return true (1.0) if all elements in the tensor are non-zero.
    pub fn tensor_all(&self, node: TensorNodeId) -> Result<bool, AutogradError> {
        match self.tensor_tape.values_borrowed(node) {
            Ok(v) => Ok(v.iter().all(|&x| x != 0.0)),
            Err(_) => Ok(self.tensor_tape.values(node)?.iter().all(|&x| x != 0.0)),
        }
    }

    /// Return the median value of all elements in the tensor.
    ///
    /// For an even number of elements, returns the lower of the two middle values
    /// (matching PyTorch's behavior for integer-like cases).
    /// Quickselect the rank-`k` (0-indexed) smallest VALUE of `vals` in O(n) (vs a
    /// full sort O(n log n)). Used by the no-grad nan-reduction paths, which need
    /// only the value. `vals` must be NaN-free (callers filter NaN first), so
    /// `partial_cmp` is a total order. frankentorch-kgs4.60.
    fn nan_kth_value(vals: &mut [f64], k: usize) -> f64 {
        let (_, v, _) = vals.select_nth_unstable_by(k, |a, b| {
            a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal)
        });
        *v
    }

    /// Quickselect the rank-`k` (0-indexed) `(value, original_index)` of `pairs`
    /// (NaN-free `(value, orig)` tuples) in O(n), reproducing a stable
    /// `sort_by(value)` bit-for-bit: among elements equal to the rank-k value the
    /// stable order is ascending original index, so the rank-k pair is the
    /// `(k - #strictly-less)`-th equal pair in `pairs` iteration order (which is
    /// already ascending original index). frankentorch-kgs4.60.
    fn nan_kth_pair(pairs: &[(f64, usize)], k: usize) -> (f64, usize) {
        use std::cmp::Ordering;
        let mut vc: Vec<f64> = pairs.iter().map(|p| p.0).collect();
        let (_, kv, _) =
            vc.select_nth_unstable_by(k, |a, b| a.partial_cmp(b).unwrap_or(Ordering::Equal));
        let kv = *kv;
        let less = pairs
            .iter()
            .filter(|p| p.0.partial_cmp(&kv) == Some(Ordering::Less))
            .count();
        let off = k - less;
        let orig = pairs
            .iter()
            .filter(|p| p.0 == kv)
            .nth(off)
            .map(|p| p.1)
            .expect("rank-k pair must exist after quickselect");
        (kv, orig)
    }

    pub fn tensor_median(&mut self, node: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(node)?;
        let numel = Self::checked_shape_numel(&shape, "median shape volume overflow")?;
        if numel == 0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "median requires non-empty tensor",
                },
            )));
        }
        if !self.tensor_requires_grad(node)? && self.tensor_dtype(node)? == DType::F64 {
            let median_idx = (numel - 1) / 2;
            // torch.median propagates NaN: ANY NaN -> NaN. total_cmp would instead sort
            // NaN to the end and return the k-th finite value. frankentorch-kgs4.175.
            use rayon::prelude::*;
            // total_cmp quickselect fallback replaced with the parallel masked-histogram
            // radix-select (u64 keys) — no 128MB clone, no per-compare total_cmp closure.
            // Bit-identical (median is a unique order statistic). frankentorch-median-radixselect.
            let median_val = match self.tensor_tape.values_borrowed(node) {
                Ok(vals) => {
                    if vals.par_iter().any(|v| v.is_nan()) {
                        f64::NAN
                    } else {
                        Self::bounded_integer_median_f64(vals, median_idx)
                            .unwrap_or_else(|| Self::radix_select_f64_no_nan(vals, median_idx))
                    }
                }
                Err(_) => {
                    let scratch = self.tensor_values(node)?;
                    if scratch.par_iter().any(|v| v.is_nan()) {
                        f64::NAN
                    } else {
                        Self::bounded_integer_median_f64(&scratch, median_idx)
                            .unwrap_or_else(|| Self::radix_select_f64_no_nan(&scratch, median_idx))
                    }
                }
            };
            return self.tensor_tape.leaf(vec![median_val], vec![1], false);
        }
        // F32 no-grad: mirror the f64 quickselect fast path directly on the BORROWED f32
        // values. The kthvalue fallback below reads `tensor_values_lossy_f64` (f32->f64
        // upcast = 128MB) + a second clone + a less-count + index_select for the gradient
        // — all dead in no-grad — measured ~4.2x SLOWER than torch (215ms vs 51ms at 16M).
        // The median is the rank-((numel-1)/2) order statistic, which is a UNIQUE value, so
        // `select_nth_unstable_by(total_cmp)` on f32 gives the SAME value as the f64 path
        // (f32->f64 is exact + order-preserving) = bit-identical to torch. frankentorch-kgs4.175.
        if !self.tensor_requires_grad(node)? && self.tensor_dtype(node)? == DType::F32 {
            use rayon::prelude::*;
            let median_idx = (numel - 1) / 2;
            let median_val = {
                let it = self.tensor_tape.tensor(node)?;
                if it.meta().is_contiguous() {
                    let data = it.contiguous_values_f32()?;
                    // torch.median propagates NaN: ANY NaN -> NaN (total_cmp would instead
                    // sort NaN to the end and return the k-th finite value). frankentorch-kgs4.175.
                    if data.par_iter().any(|v| v.is_nan()) {
                        Some(f32::NAN)
                    } else {
                        // Parallel radix-select on sortable-u32 keys (no 64MB clone, no
                        // total_cmp quickselect): ~4.5x faster than select_nth_unstable_by at
                        // 16M, ~2.8x FASTER than torch.median. Bit-identical (the median is a
                        // unique order statistic; the u32 key is an order-preserving bijection
                        // on non-NaN f32). frankentorch-median-radixselect.
                        Some(Self::radix_select_f32_no_nan(data, median_idx))
                    }
                } else {
                    None
                }
            };
            if let Some(v) = median_val {
                return self.tensor_variable_f32(vec![v], vec![1], false);
            }
        }
        // The lower-median is the rank-((numel-1)/2 + 1) order statistic. Compose on
        // tensor_kthvalue, which finds it via quickselect in O(n) (vs the previous
        // full sort O(n log n)) and routes the gradient to the median element's
        // original position via index_select — same observable VALUE (the median is
        // well-defined) and, for unique values, the same single-element gradient as
        // the old sort+narrow. frankentorch-kgs4.58.
        let flat = self.tensor_reshape(node, vec![numel])?;
        let median_idx = (numel - 1) / 2;
        let (value, _index) = self.tensor_kthvalue(flat, median_idx + 1)?;
        Ok(value)
    }

    /// The rank-th order statistic (0-based, ascending) of `values`, assuming NO NaN,
    /// via a parallel MASKED-histogram radix-select on sortable u32 keys — 4 fixed
    /// MSB-to-LSB byte passes, each a full-array parallel scan that histograms only the
    /// elements matching the prefix found so far (no filtering / no per-pass allocation,
    /// so it is DISTRIBUTION-INDEPENDENT — a filter-and-narrow variant degrades to a full
    /// sort's cost when the data is clustered and the active set never shrinks). The key
    /// `b|0x8000_0000` (positive) / `!b` (negative) is an order-preserving bijection on
    /// non-NaN f32, so the selected value is bit-identical to
    /// `select_nth_unstable_by(total_cmp)`. ~3.7x faster than the total_cmp quickselect at
    /// 16M (and ~2.6x FASTER than torch.median) regardless of distribution.
    #[inline]
    fn radix_select_f32_no_nan(values: &[f32], rank: usize) -> f32 {
        use rayon::prelude::*;
        #[inline]
        fn key(v: f32) -> u32 {
            let b = v.to_bits();
            if b & 0x8000_0000 != 0 {
                !b
            } else {
                b | 0x8000_0000
            }
        }
        let keys: Vec<u32> = values.par_iter().map(|&v| key(v)).collect();
        let mut rank = rank;
        let mut prefix = 0u32;
        let mut prefix_mask = 0u32;
        for byte in (0..4).rev() {
            let shift = byte * 8;
            let hist = keys
                .par_chunks(1 << 16)
                .map(|ch| {
                    let mut h = [0usize; 256];
                    for &k in ch {
                        if k & prefix_mask == prefix {
                            h[((k >> shift) & 0xff) as usize] += 1;
                        }
                    }
                    h
                })
                .reduce(
                    || [0usize; 256],
                    |mut a, b| {
                        for i in 0..256 {
                            a[i] += b[i];
                        }
                        a
                    },
                );
            let mut cum = 0usize;
            let mut chosen = 0u8;
            for (bk, &c) in hist.iter().enumerate() {
                if cum + c > rank {
                    chosen = bk as u8;
                    break;
                }
                cum += c;
            }
            prefix |= (chosen as u32) << shift;
            prefix_mask |= 0xffu32 << shift;
            rank -= cum;
        }
        let b = if prefix & 0x8000_0000 != 0 {
            prefix & 0x7fff_ffff
        } else {
            !prefix
        };
        f32::from_bits(b)
    }

    /// f64 sibling of [`Self::radix_select_f32_no_nan`]: rank-th order statistic of
    /// `values` (ascending, NO NaN) via a parallel masked-histogram radix-select on
    /// sortable u64 keys (8 fixed MSB->LSB byte passes). Bit-identical to
    /// `select_nth_unstable_by(total_cmp)`. ~4x faster than the total_cmp quickselect at
    /// 16M f64 (and faster than torch.median, which is ~parity to the old quickselect).
    #[inline]
    fn radix_select_f64_no_nan(values: &[f64], rank: usize) -> f64 {
        use rayon::prelude::*;
        #[inline]
        fn key(v: f64) -> u64 {
            let b = v.to_bits();
            if b & 0x8000_0000_0000_0000 != 0 {
                !b
            } else {
                b | 0x8000_0000_0000_0000
            }
        }
        let keys: Vec<u64> = values.par_iter().map(|&v| key(v)).collect();
        let mut rank = rank;
        let mut prefix = 0u64;
        let mut prefix_mask = 0u64;
        for byte in (0..8).rev() {
            let shift = byte * 8;
            let hist = keys
                .par_chunks(1 << 16)
                .map(|ch| {
                    let mut h = [0usize; 256];
                    for &k in ch {
                        if k & prefix_mask == prefix {
                            h[((k >> shift) & 0xff) as usize] += 1;
                        }
                    }
                    h
                })
                .reduce(
                    || [0usize; 256],
                    |mut a, b| {
                        for i in 0..256 {
                            a[i] += b[i];
                        }
                        a
                    },
                );
            let mut cum = 0usize;
            let mut chosen = 0u8;
            for (bk, &c) in hist.iter().enumerate() {
                if cum + c > rank {
                    chosen = bk as u8;
                    break;
                }
                cum += c;
            }
            prefix |= (chosen as u64) << shift;
            prefix_mask |= 0xffu64 << shift;
            rank -= cum;
        }
        let b = if prefix & 0x8000_0000_0000_0000 != 0 {
            prefix & 0x7fff_ffff_ffff_ffff
        } else {
            !prefix
        };
        f64::from_bits(b)
    }

    #[allow(clippy::cast_possible_truncation, clippy::cast_precision_loss)]
    fn bounded_integer_median_f64(values: &[f64], median_idx: usize) -> Option<f64> {
        const MAX_HISTOGRAM_RANGE: i64 = 65_536;
        let mut min_value = i64::MAX;
        let mut max_value = i64::MIN;
        let mut negative_zero_count = 0usize;
        let mut positive_zero_count = 0usize;
        for &value in values {
            if !value.is_finite()
                || value.fract() != 0.0
                || value < i64::MIN as f64
                || value > i64::MAX as f64
            {
                return None;
            }
            if value == 0.0 {
                if value.is_sign_negative() {
                    negative_zero_count += 1;
                } else {
                    positive_zero_count += 1;
                }
            }
            let int_value = value as i64;
            min_value = min_value.min(int_value);
            max_value = max_value.max(int_value);
        }
        let range = max_value.checked_sub(min_value)?.checked_add(1)?;
        if range > MAX_HISTOGRAM_RANGE {
            return None;
        }
        let mut counts = vec![0usize; usize::try_from(range).ok()?];
        for &value in values {
            let int_value = value as i64;
            let bin = usize::try_from(int_value.checked_sub(min_value)?).ok()?;
            counts[bin] += 1;
        }
        let mut rank = median_idx;
        for (bin, &count) in counts.iter().enumerate() {
            if count == 0 {
                continue;
            }
            let int_value = min_value + i64::try_from(bin).ok()?;
            if int_value == 0 {
                if rank < negative_zero_count {
                    return Some(-0.0);
                }
                rank -= negative_zero_count;
                if rank < positive_zero_count {
                    return Some(0.0);
                }
                rank -= positive_zero_count;
                continue;
            }
            if rank < count {
                return Some(int_value as f64);
            }
            rank -= count;
        }
        None
    }

    /// NaN-aware median: equivalent to `torch.nanmedian(input)`.
    ///
    /// Computes the median of non-NaN values. All-NaN input returns NaN.
    /// Tracked under frankentorch-o4j2.
    pub fn tensor_nanmedian(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        let numel = Self::checked_shape_numel(&shape, "nanmedian shape volume overflow")?;
        if numel == 0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "nanmedian requires non-empty tensor",
                },
            )));
        }

        if self.tensor_requires_grad(input)? {
            // nanmedian selects a single element (the lower-median of the
            // non-NaN values), so the gradient is a scatter: the full upstream
            // gradient flows to that element's original position, all others 0.
            // The forward filter+sort+select is identical to the non-grad path
            // below, so the value is bit-identical; only the gradient is
            // restored (this op silently returned a non-grad leaf). frankentorch-o4j2.
            return self.tensor_apply_function(
                &[input],
                move |ctx, inputs| {
                    let (vals, _in_shape) = inputs[0];
                    let n = vals.len();
                    let pairs: Vec<(f64, usize)> = vals
                        .iter()
                        .enumerate()
                        .filter(|(_, v)| !v.is_nan())
                        .map(|(i, &v)| (v, i))
                        .collect();
                    if pairs.is_empty() {
                        // All-NaN: constant NaN output, zero gradient. Encode a
                        // weight-0 scatter so backward needs no special case.
                        ctx.save_for_backward(vec![n as f64, 0.0, 0.0], vec![3]);
                        return Ok((vec![f64::NAN], vec![1]));
                    }
                    let median_idx = (pairs.len() - 1) / 2;
                    let (val, orig) = Self::nan_kth_pair(&pairs, median_idx);
                    ctx.save_for_backward(vec![n as f64, orig as f64, 1.0], vec![3]);
                    Ok((vec![val], vec![1]))
                },
                move |ctx, grad_outputs| {
                    let saved = &ctx.saved_tensors()[0];
                    let n = saved[0] as usize;
                    let orig = saved[1] as usize;
                    let weight = saved[2];
                    let g = grad_outputs[0][0];
                    let mut grad = vec![0.0_f64; n];
                    grad[orig] += weight * g;
                    Ok(vec![Some(grad)])
                },
            );
        }

        // F32 no-grad fast path: the generic path below `tensor_values_lossy_f64` UPCASTS
        // f32->f64 (clone) before the NaN-filter + quickselect — measured ~1.42x SLOWER than
        // torch. Borrow f32, filter NaN + quickselect on f32 directly (no upcast). The
        // nanmedian is the rank-((m-1)/2) order statistic of the non-NaN values = a unique
        // value, selected by the SAME comparator (`partial_cmp`) as the f64 path; f32->f64 is
        // exact + order-preserving, so the selected element is BIT-IDENTICAL. frankentorch-kgs4.179.
        if !self.tensor_requires_grad(input)? && self.tensor_dtype(input)? == DType::F32 {
            let median_val: Option<f32> = {
                let it = self.tensor_tape.tensor(input)?;
                if it.meta().is_contiguous() {
                    let vals = it.contiguous_values_f32()?;
                    let mut non_nan: Vec<f32> =
                        vals.iter().copied().filter(|x| !x.is_nan()).collect();
                    if non_nan.is_empty() {
                        Some(f32::NAN)
                    } else {
                        let median_idx = (non_nan.len() - 1) / 2;
                        let (_, v, _) = non_nan.select_nth_unstable_by(median_idx, |a, b| {
                            a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal)
                        });
                        Some(*v)
                    }
                } else {
                    None
                }
            };
            if let Some(v) = median_val {
                return self.tensor_variable_f32(vec![v], vec![1], false);
            }
        }

        // Lossy read + dtype-matched leaf so f32 inputs are accepted and the
        // result keeps the input dtype (torch nanmedian(f32) -> f32); the old
        // tensor_values read was F64-only and rebuilt an F64 leaf. frankentorch-fk5l.
        let vals = self.tensor_values_lossy_f64(input)?;
        let mut non_nan: Vec<f64> = vals.into_iter().filter(|x| !x.is_nan()).collect();

        if non_nan.is_empty() {
            return self.scalar_leaf_matching_dtype(input, f64::NAN);
        }

        let median_idx = (non_nan.len() - 1) / 2;
        let median_val = Self::nan_kth_value(&mut non_nan, median_idx);

        self.scalar_leaf_matching_dtype(input, median_val)
    }

    /// NaN-aware quantile: equivalent to `torch.nanquantile(input, q)`.
    ///
    /// Computes the q-th quantile (0 <= q <= 1) of non-NaN values.
    /// All-NaN input returns NaN.
    /// Tracked under frankentorch-o4j2.
    pub fn tensor_nanquantile(
        &mut self,
        input: TensorNodeId,
        q: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_nanquantile_interpolation(input, q, "linear")
    }

    /// `torch.nanquantile(input, q, interpolation=...)`: the quantile of the
    /// non-NaN values, with the same five interpolation modes as
    /// [`Self::tensor_quantile_interpolation`] ("linear" default, "lower",
    /// "higher", "nearest" = round-half-to-even index, "midpoint"). All-NaN input
    /// yields NaN. Autograd-aware: the gradient scatters back to the original
    /// (pre-filter) positions of the selected order statistic(s).
    pub fn tensor_nanquantile_interpolation(
        &mut self,
        input: TensorNodeId,
        q: f64,
        interpolation: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        // mode codes: 0 linear, 1 lower, 2 higher, 3 nearest, 4 midpoint.
        let mode: u8 = match interpolation {
            "linear" => 0,
            "lower" => 1,
            "higher" => 2,
            "nearest" => 3,
            "midpoint" => 4,
            _ => {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "nanquantile: interpolation must be one of linear, lower, higher, nearest, midpoint",
                    },
                )));
            }
        };
        if !(0.0..=1.0).contains(&q) {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "nanquantile: q must be in [0, 1]",
                },
            )));
        }

        if self.tensor_requires_grad(input)? {
            // nanquantile selects one or two order statistics of the non-NaN
            // values; the gradient is a (≤2)-element scatter back to those
            // elements' ORIGINAL positions. Forward filter+sort is identical to
            // the non-grad path so the value is bit-identical; only the gradient
            // is restored (was a silent non-grad leaf). frankentorch-o4j2.
            return self.tensor_apply_function(
                &[input],
                move |ctx, inputs| {
                    let (vals, _in_shape) = inputs[0];
                    let total = vals.len();
                    let pairs: Vec<(f64, usize)> = vals
                        .iter()
                        .enumerate()
                        .filter(|(_, v)| !v.is_nan())
                        .map(|(i, &v)| (v, i))
                        .collect();
                    if pairs.is_empty() {
                        ctx.save_for_backward(vec![total as f64, 0.0, 0.0, 0.0, 0.0], vec![5]);
                        return Ok((vec![f64::NAN], vec![1]));
                    }
                    let n = pairs.len();
                    let idx_f = q * (n - 1) as f64;
                    let idx_lo = idx_f.floor() as usize;
                    let idx_hi = idx_f.ceil() as usize;
                    let frac = idx_f - idx_lo as f64;
                    let (lo_val, lo_orig) = Self::nan_kth_pair(&pairs, idx_lo);
                    let (hi_val, hi_orig) = Self::nan_kth_pair(&pairs, idx_hi);
                    let (result, lo_o, w_lo, hi_o, w_hi) = match mode {
                        1 => (lo_val, lo_orig, 1.0, lo_orig, 0.0),
                        2 => (hi_val, hi_orig, 0.0, hi_orig, 1.0),
                        3 => {
                            let ni = idx_f.round_ties_even() as usize;
                            let (nv, no) = Self::nan_kth_pair(&pairs, ni);
                            (nv, no, 1.0, no, 0.0)
                        }
                        4 if idx_lo != idx_hi => {
                            ((lo_val + hi_val) * 0.5, lo_orig, 0.5, hi_orig, 0.5)
                        }
                        0 if idx_lo != idx_hi => (
                            lo_val * (1.0 - frac) + hi_val * frac,
                            lo_orig,
                            1.0 - frac,
                            hi_orig,
                            frac,
                        ),
                        // idx_lo == idx_hi: single order statistic for every mode.
                        _ => (lo_val, lo_orig, 1.0, lo_orig, 0.0),
                    };
                    ctx.save_for_backward(
                        vec![total as f64, lo_o as f64, w_lo, hi_o as f64, w_hi],
                        vec![5],
                    );
                    Ok((vec![result], vec![1]))
                },
                move |ctx, grad_outputs| {
                    let saved = &ctx.saved_tensors()[0];
                    let total = saved[0] as usize;
                    let lo_orig = saved[1] as usize;
                    let w_lo = saved[2];
                    let hi_orig = saved[3] as usize;
                    let w_hi = saved[4];
                    let g = grad_outputs[0][0];
                    let mut grad = vec![0.0_f64; total];
                    grad[lo_orig] += w_lo * g;
                    grad[hi_orig] += w_hi * g;
                    Ok(vec![Some(grad)])
                },
            );
        }

        // F32 no-grad native fast path. The f64 path below reads `tensor_values` (F64-only), so f32
        // nanquantile ERRORED (UnsupportedDType(F32)); torch.nanquantile is itself pathologically slow
        // (full sort + NaN handling, ~704ms at 16M, while FT's f64 quickselect is ~127ms). Filter NaN
        // + quickselect the needed order statistic(s) in f32 directly (same idx math + 5 interpolation
        // modes as the f64 path; bit-exact since order statistics are exact f32 values and the interp
        // is the same f32 arithmetic). Non-contiguous f32 falls through (pre-existing, rare).
        // frankentorch-nanquantile-f32.
        if self.tensor_dtype(input)? == DType::F32 {
            let nn: Option<Vec<f32>> = match self.tensor_tape.tensor(input)?.contiguous_values_f32()
            {
                Ok(slice) => Some(slice.iter().copied().filter(|x| !x.is_nan()).collect()),
                Err(_) => None,
            };
            if let Some(mut non_nan) = nn {
                if non_nan.is_empty() {
                    return self.tensor_variable_f32(vec![f32::NAN], vec![1], false);
                }
                let n = non_nan.len();
                let idx_f = q * (n - 1) as f64;
                let idx_lo = idx_f.floor() as usize;
                let idx_hi = idx_f.ceil() as usize;
                #[allow(clippy::cast_possible_truncation)]
                let frac = (idx_f - idx_lo as f64) as f32;
                let kth = |v: &mut [f32], k: usize| -> f32 {
                    *v.select_nth_unstable_by(k, |a, b| a.total_cmp(b)).1
                };
                let result: f32 = match mode {
                    1 => kth(&mut non_nan, idx_lo),
                    2 => kth(&mut non_nan, idx_hi),
                    3 => kth(&mut non_nan, idx_f.round_ties_even() as usize),
                    4 if idx_lo != idx_hi => {
                        (kth(&mut non_nan, idx_lo) + kth(&mut non_nan, idx_hi)) * 0.5
                    }
                    0 if idx_lo != idx_hi => {
                        let lo = kth(&mut non_nan, idx_lo);
                        let hi = kth(&mut non_nan, idx_hi);
                        lo * (1.0 - frac) + hi * frac
                    }
                    _ => kth(&mut non_nan, idx_lo),
                };
                return self.tensor_variable_f32(vec![result], vec![1], false);
            }
        }

        let vals = self.tensor_values(input)?;
        let mut non_nan: Vec<f64> = vals.into_iter().filter(|x| !x.is_nan()).collect();

        if non_nan.is_empty() {
            return self.tensor_variable(vec![f64::NAN], vec![1], false);
        }

        let n = non_nan.len();
        let idx_f = q * (n - 1) as f64;
        let idx_lo = idx_f.floor() as usize;
        let idx_hi = idx_f.ceil() as usize;
        let frac = idx_f - idx_lo as f64;

        // Quickselect the needed order statistic(s) (O(n)) instead of a full sort.
        let result = match mode {
            1 => Self::nan_kth_value(&mut non_nan, idx_lo),
            2 => Self::nan_kth_value(&mut non_nan, idx_hi),
            3 => Self::nan_kth_value(&mut non_nan, idx_f.round_ties_even() as usize),
            4 if idx_lo != idx_hi => {
                (Self::nan_kth_value(&mut non_nan, idx_lo)
                    + Self::nan_kth_value(&mut non_nan, idx_hi))
                    * 0.5
            }
            0 if idx_lo != idx_hi => {
                let lo = Self::nan_kth_value(&mut non_nan, idx_lo);
                let hi = Self::nan_kth_value(&mut non_nan, idx_hi);
                lo * (1.0 - frac) + hi * frac
            }
            _ => Self::nan_kth_value(&mut non_nan, idx_lo),
        };

        self.tensor_variable(vec![result], vec![1], false)
    }

    // ── Similarity Functions ────────────────────────────────────────────

    /// Cosine similarity between two tensors along a dimension.
    ///
    /// `cos_sim(x1, x2, dim) =
    /// sum(x1 * x2, dim) / (max(norm(x1, dim), eps) * max(norm(x2, dim), eps))`
    ///
    /// Returns a tensor with the specified dimension reduced.
    /// `eps` prevents division by zero when one or both inputs have zero norm.
    ///
    /// Equivalent to PyTorch's `F.cosine_similarity(x1, x2, dim, eps)`.
    pub fn cosine_similarity(
        &mut self,
        x1: TensorNodeId,
        x2: TensorNodeId,
        dim: usize,
        eps: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        // dot_product = sum(x1 * x2, dim)
        let prod = self.tensor_mul(x1, x2)?;
        let dot = self.tensor_sum_dim(prod, dim)?;

        // Denominator = max(norm(x1, dim), eps) * max(norm(x2, dim), eps)
        let norm1 = self.tensor_norm_dim(x1, 2.0, dim)?;
        let norm2 = self.tensor_norm_dim(x2, 2.0, dim)?;
        let norm1 = self.tensor_clamp_min(norm1, eps)?;
        let norm2 = self.tensor_clamp_min(norm2, eps)?;
        let denom = self.tensor_mul(norm1, norm2)?;

        // cos_sim = dot / denom
        self.tensor_div(dot, denom)
    }

    // ── Loss Functions ──────────────────────────────────────────────────

    /// Mean Squared Error loss: `mean((pred - target)^2)`
    ///
    /// Composed from existing tensor operations so backward/autograd works
    /// automatically.
    pub fn mse_loss(
        &mut self,
        pred: TensorNodeId,
        target: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let diff = self.tensor_sub(pred, target)?;
        let sq = self.tensor_mul(diff, diff)?;
        self.tensor_mean(sq)
    }

    /// L1 (Mean Absolute Error) loss: `mean(|pred - target|)`
    pub fn l1_loss(
        &mut self,
        pred: TensorNodeId,
        target: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let diff = self.tensor_sub(pred, target)?;
        let abs_diff = self.tensor_abs(diff)?;
        self.tensor_mean(abs_diff)
    }

    /// Binary Cross-Entropy loss:
    /// `-mean(target * log(pred) + (1 - target) * log(1 - pred))`
    ///
    /// Clamps `pred` to `[eps, 1 - eps]` (eps = 1e-7) for numerical stability.
    pub fn bce_loss(
        &mut self,
        pred: TensorNodeId,
        target: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let eps: f64 = 1e-7;
        let shape = self.tensor_shape(target)?;

        // clamp pred to [eps, 1-eps]
        let clamped = self.tensor_clamp(pred, eps, 1.0 - eps)?;

        // log(pred_clamped)
        let log_pred = self.tensor_log(clamped)?;

        // target * log(pred_clamped)
        let term_a = self.tensor_mul(target, log_pred)?;

        // Construct (1 - target) and (1 - pred_clamped) via a ones constant.
        let ones = self.full(shape, 1.0, false)?;

        // 1 - target
        let one_minus_target = self.tensor_sub(ones, target)?;

        // 1 - pred_clamped  (reuse `ones` node id — DAG allows multiple refs)
        let one_minus_pred = self.tensor_sub(ones, clamped)?;

        // log(1 - pred_clamped)
        let log_one_minus_pred = self.tensor_log(one_minus_pred)?;

        // (1 - target) * log(1 - pred_clamped)
        let term_b = self.tensor_mul(one_minus_target, log_one_minus_pred)?;

        // target * log(pred) + (1 - target) * log(1 - pred)
        let sum_terms = self.tensor_add(term_a, term_b)?;

        // mean(...)
        let mean_val = self.tensor_mean(sum_terms)?;

        // negate: -mean(...)
        self.tensor_neg(mean_val)
    }

    /// KL divergence loss: `KL(target || input)`.
    ///
    /// Equivalent to `torch.nn.functional.kl_div(input, target, reduction, log_target)`.
    /// `input` is expected to be log-probabilities; `target` is
    /// probabilities (or log-probabilities if `log_target=true`).
    ///
    /// Forward (log_target=false): `target * (log(target) - input)`
    /// Forward (log_target=true):  `exp(target) * (target - input)`
    ///
    /// `reduction` accepts:
    ///   - "none": element-wise loss tensor
    ///   - "sum": sum of all elements
    ///   - "mean": sum / numel (PyTorch's misnomer "mean" — a per-element average)
    ///   - "batchmean": sum / batch_size (mathematically correct KL —
    ///     divide only by the leading dim)
    ///
    /// Composes through autograd-aware tensor_log + tensor_sub +
    /// tensor_mul + reduction. For numerical stability when target
    /// is given as probabilities (log_target=false), a small eps is
    /// added before log. Tracked under frankentorch-5qs5.
    pub fn kl_div_loss(
        &mut self,
        input: TensorNodeId,
        target: TensorNodeId,
        reduction: &str,
        log_target: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        let target_shape = self.tensor_shape(target)?;
        let input_shape = self.tensor_shape(input)?;
        if target_shape != input_shape {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: input_shape,
                    rhs: target_shape,
                },
            )));
        }

        let elem = if log_target {
            // exp(target) * (target - input)
            let target_exp = self.tensor_exp(target)?;
            let diff = self.tensor_sub(target, input)?;
            self.tensor_mul(target_exp, diff)?
        } else {
            // target * (log(target + eps) - input). The eps avoids
            // log(0) when target has zero entries (a common case in
            // teacher-forcing where the target distribution is
            // sparse).
            let eps = 1e-8;
            let eps_t = self.full(target_shape.clone(), eps, false)?;
            let safe_target = self.tensor_add(target, eps_t)?;
            let log_target_t = self.tensor_log(safe_target)?;
            let diff = self.tensor_sub(log_target_t, input)?;
            self.tensor_mul(target, diff)?
        };

        match reduction {
            "none" => Ok(elem),
            "sum" => self.tensor_sum(elem),
            "mean" => self.tensor_mean(elem),
            "batchmean" => {
                if target_shape.is_empty() {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "kl_div_loss: batchmean requires at least 1-D input",
                        },
                    )));
                }
                let batch_size = target_shape[0];
                let summed = self.tensor_sum(elem)?;
                let summed_shape = self.tensor_shape(summed)?;
                let divisor = self.full(summed_shape, batch_size as f64, false)?;
                self.tensor_div(summed, divisor)
            }
            _ => Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "kl_div_loss: unsupported reduction (use none, sum, mean, batchmean)",
                },
            ))),
        }
    }

    /// Binary cross-entropy with logits loss (numerically stable):
    /// `mean(max(x, 0) - x * y + log1p(exp(-|x|)))`
    ///
    /// This is equivalent to `sigmoid(x)` followed by BCE loss but avoids
    /// the numerical instability of computing `log(sigmoid(x))` for extreme
    /// input values.
    pub fn bce_with_logits_loss(
        &mut self,
        logits: TensorNodeId,
        target: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // max(x, 0) = relu(x)
        let relu_x = self.tensor_relu(logits)?;

        // x * y
        let x_times_y = self.tensor_mul(logits, target)?;

        // |x|
        let abs_x = self.tensor_abs(logits)?;

        // -|x|
        let neg_abs_x = self.tensor_neg(abs_x)?;

        // exp(-|x|)
        let exp_neg_abs = self.tensor_exp(neg_abs_x)?;

        // log1p(exp(-|x|)) = log(1 + exp(-|x|))
        let log_term = self.tensor_log1p(exp_neg_abs)?;

        // relu(x) - x * y
        let diff = self.tensor_sub(relu_x, x_times_y)?;

        // relu(x) - x * y + log1p(exp(-|x|))
        let elementwise = self.tensor_add(diff, log_term)?;

        // mean reduction
        self.tensor_mean(elementwise)
    }

    /// Smooth L1 (Huber) loss:
    /// - When `|d| < beta`: `0.5 * d^2 / beta`
    /// - When `|d| >= beta`: `|d| - 0.5 * beta`
    ///
    /// Returns `mean(element_wise_huber)`.
    ///
    /// The two branches are blended using a comparison mask so that gradients
    /// flow through the active branch at each element.
    pub fn smooth_l1_loss(
        &mut self,
        pred: TensorNodeId,
        target: TensorNodeId,
        beta: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        if beta <= 0.0 || !beta.is_finite() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "smooth_l1_loss requires finite beta > 0",
                },
            )));
        }

        let shape = self.tensor_shape(pred)?;

        let diff = self.tensor_sub(pred, target)?;
        let abs_diff = self.tensor_abs(diff)?;

        // Quadratic branch: 0.5 * diff^2 / beta
        let diff_sq = self.tensor_mul(diff, diff)?;
        let half_over_beta = self.full(shape.clone(), 0.5 / beta, false)?;
        let quadratic = self.tensor_mul(diff_sq, half_over_beta)?;

        // Linear branch: |diff| - 0.5 * beta
        let half_beta = self.full(shape.clone(), 0.5 * beta, false)?;
        let linear = self.tensor_sub(abs_diff, half_beta)?;

        // Build mask: 1.0 where |diff| < beta, 0.0 otherwise.
        // tensor_gt returns 1.0 where lhs > rhs. We want |diff| < beta,
        // i.e. beta > |diff|, so: mask = tensor_gt(beta_tensor, abs_diff).
        let beta_tensor = self.full(shape, beta, false)?;
        let mask = self.tensor_gt(beta_tensor, abs_diff)?;

        // Blend via autograd-aware tensor_where instead of the
        // textbook mask*quadratic + (1-mask)*linear chain.
        // tensor_where routes gradients to whichever branch the
        // mask selects, matching the original backward semantics
        // exactly. -1 full() allocation, -1 sub + -2 mul + -1 add
        // collapsed into one where. Tracked under frankentorch-uqtq.
        let huber = self.tensor_where(mask, quadratic, linear)?;

        self.tensor_mean(huber)
    }

    /// Huber loss (robust regression loss).
    ///
    /// Behaves as L2 loss when the error is small (`|pred - target| <= delta`)
    /// and as L1 loss when the error is large (`|pred - target| > delta`).
    ///
    /// When `|diff| <= delta`: loss = 0.5 * diff^2
    /// When `|diff| > delta`:  loss = delta * (|diff| - 0.5 * delta)
    ///
    /// Returns the mean loss over all elements.
    ///
    /// Equivalent to PyTorch's `F.huber_loss(pred, target, delta=delta)`.
    pub fn huber_loss(
        &mut self,
        pred: TensorNodeId,
        target: TensorNodeId,
        delta: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        if delta <= 0.0 || !delta.is_finite() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "huber_loss requires finite delta > 0",
                },
            )));
        }

        let shape = self.tensor_shape(pred)?;

        let diff = self.tensor_sub(pred, target)?;
        let abs_diff = self.tensor_abs(diff)?;

        // Quadratic branch: 0.5 * diff^2
        let diff_sq = self.tensor_mul(diff, diff)?;
        let half = self.full(shape.clone(), 0.5, false)?;
        let quadratic = self.tensor_mul(diff_sq, half)?;

        // Linear branch: delta * (|diff| - 0.5 * delta)
        let half_delta = self.full(shape.clone(), 0.5 * delta, false)?;
        let shifted = self.tensor_sub(abs_diff, half_delta)?;
        let delta_tensor = self.full(shape.clone(), delta, false)?;
        let linear = self.tensor_mul(delta_tensor, shifted)?;

        // Mask: 1.0 where |diff| <= delta (i.e., delta >= |diff|)
        // Reuses delta_tensor — DAG allows multiple refs
        let in_quadratic = self.tensor_ge(delta_tensor, abs_diff)?;

        // Blend via autograd-aware tensor_where instead of the
        // textbook mask*quadratic + (1-mask)*linear chain. Same
        // simplification as smooth_l1_loss (uqtq) — tensor_where
        // routes gradients to whichever branch the mask selects,
        // preserving the original backward semantics. -1 full()
        // allocation, -1 sub + -2 mul + -1 add collapsed into 1
        // where node. Tracked under frankentorch-yt94.
        let result = self.tensor_where(in_quadratic, quadratic, linear)?;

        self.tensor_mean(result)
    }

    /// Cosine embedding loss for similarity learning.
    ///
    /// Measures whether two inputs are similar or dissimilar, using a target label:
    /// - When `target[i] = 1.0`: loss = `1 - cos_sim(x1[i], x2[i])`
    /// - When `target[i] = -1.0`: loss = `max(0, cos_sim(x1[i], x2[i]) - margin)`
    ///
    /// `x1` and `x2` must have shape `[batch, features]`. `target` must have shape
    /// `[batch]` with values `1.0` or `-1.0`. Returns the mean loss.
    ///
    /// Equivalent to PyTorch's `F.cosine_embedding_loss(x1, x2, target, margin)`.
    pub fn cosine_embedding_loss(
        &mut self,
        x1: TensorNodeId,
        x2: TensorNodeId,
        target: TensorNodeId,
        margin: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let x1_shape = self.tensor_shape(x1)?;
        if x1_shape.len() != 2 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "cosine_embedding_loss expects 2-D inputs [batch, features]",
                },
            )));
        }

        let batch_size = x1_shape[0];

        // Validate target values: must be exactly 1.0 or -1.0
        let target_vals = self.tensor_values_lossy_f64(target)?;
        for &t in &target_vals {
            if t != 1.0 && t != -1.0 {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "cosine_embedding_loss target must contain only 1.0 or -1.0",
                    },
                )));
            }
        }

        // F32 inputs would mix the F64 constants below (self.full is always F64) with an F32
        // `cos_sim` in tensor_sub/tensor_max/tensor_where and ERROR on the dtype mismatch (a
        // pre-existing f32 crash; torch.cosine_embedding_loss(f32) -> f32). The sibling
        // `tensor_cosine_embedding_loss` has an f32 fused fast path computing the IDENTICAL
        // mean loss natively (same eps=1e-8, same (y==1)?1-cos:max(0,cos-margin) selection for
        // the validated target∈{1,-1}), so route f32 there. The 2-D + target validations above
        // are preserved (they still run first). frankentorch-cosemb-f32-fused.
        if self.tensor_dtype(x1)? == DType::F32
            && self.tensor_dtype(x2)? == DType::F32
            && self.tensor_dtype(target)? == DType::F32
        {
            return self.tensor_cosine_embedding_loss(x1, x2, target, margin, "mean");
        }

        // cos_sim along dim=1 (feature dimension) -> [batch]
        let cos_sim = self.cosine_similarity(x1, x2, 1, 1e-8)?;

        // Positive pairs (target=1): loss = 1 - cos_sim
        let ones = self.full(vec![batch_size], 1.0, false)?;
        let pos_loss = self.tensor_sub(ones, cos_sim)?;

        // Negative pairs (target=-1): loss = max(0, cos_sim - margin)
        let margin_t = self.full(vec![batch_size], margin, false)?;
        let neg_diff = self.tensor_sub(cos_sim, margin_t)?;
        let zeros = self.full(vec![batch_size], 0.0, false)?;
        let neg_loss = self.tensor_max(neg_diff, zeros)?;

        // Select based on target: mask = (target + 1) / 2 -> 1.0 for positive, 0.0 for negative.
        let mask_vals: Vec<f64> = target_vals.iter().map(|t| (t + 1.0) / 2.0).collect();
        let mask = self.tensor_variable(mask_vals, vec![batch_size], false)?;
        // Blend via tensor_where instead of mask*pos + (1-mask)*neg
        // (frankentorch-qw5a — mirrors uqtq/yt94). For target in
        // {-1, +1} (documented domain), mask is 0/1 so tensor_where
        // produces the same result with -1 sub + -2 mul + -1 add
        // collapsed into 1 where node.
        let total = self.tensor_where(mask, pos_loss, neg_loss)?;

        self.tensor_mean(total)
    }

    /// Focal loss for dense object detection.
    ///
    /// Equivalent to a focal variant of BCE: `FL(p_t) = -alpha_t * (1 - p_t)^gamma * log(p_t)`.
    /// `input` contains logits, `target` contains binary labels (0 or 1).
    /// Returns the mean focal loss.
    pub fn focal_loss(
        &mut self,
        input: TensorNodeId,
        target: TensorNodeId,
        alpha: f64,
        gamma: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let in_shape = self.tensor_shape(input)?;
        let tgt_shape = self.tensor_shape(target)?;
        if in_shape != tgt_shape {
            // Migrate to ShapeMismatch (frankentorch-c991).
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: in_shape,
                    rhs: tgt_shape,
                },
            )));
        }
        // Compose through autograd-aware primitives. Tracked under
        // frankentorch-m6uk (child of frankentorch-2med).
        // Math:
        //   p          = sigmoid(input)
        //   p_t        = target * p + (1 - target) * (1 - p)
        //   alpha_t    = target * alpha + (1 - target) * (1 - alpha)
        //   inner      = (1 - p_t)^gamma * log(clamp_min(p_t, 1e-15))
        //   per_elem   = -alpha_t * inner
        //   loss       = mean(per_elem)
        // target is treated as a {0, 1} mask (binary labels).
        // Single ones tensor shared across all three (1 - x) sub
        // call sites (frankentorch-4w7g): tensor_sub only reads its
        // operands. Saves 2 full() allocations + 2 tape nodes per
        // focal_loss call.
        let p = self.tensor_sigmoid(input)?;
        // Constants must match the INPUT dtype: `self.full` is always F64, so on f32 input the
        // tensor_sub/mul below (p, target, p_t are all F32) hit a dtype mismatch and ERROR
        // (torch.ops focal-style loss on f32 -> f32). `full_like(input, ..)` builds the constant
        // in input's dtype + shape -> native-f32 compose, bit-identical for f64. frankentorch-fk5l.
        let ones = self.full_like(input, 1.0, false)?;
        let one_minus_p = self.tensor_sub(ones, p)?;
        let one_minus_target = self.tensor_sub(ones, target)?;

        // p_t = target * p + (1 - target) * (1 - p)
        let term_pos = self.tensor_mul(target, p)?;
        let term_neg = self.tensor_mul(one_minus_target, one_minus_p)?;
        let p_t = self.tensor_add(term_pos, term_neg)?;

        // alpha_t = target * alpha + (1 - target) * (1 - alpha)
        let alpha_t_pos = self.full_like(input, alpha, false)?;
        let alpha_t_neg = self.full_like(input, 1.0 - alpha, false)?;
        let alpha_pos_term = self.tensor_mul(target, alpha_t_pos)?;
        let alpha_neg_term = self.tensor_mul(one_minus_target, alpha_t_neg)?;
        let alpha_t = self.tensor_add(alpha_pos_term, alpha_neg_term)?;

        // inner = (1 - p_t)^gamma * log(clamp_min(p_t, 1e-15))
        let one_minus_p_t = self.tensor_sub(ones, p_t)?;
        let focal_factor = self.tensor_pow(one_minus_p_t, gamma)?;
        let p_t_clamped = self.tensor_clamp_min(p_t, 1e-15)?;
        let log_p_t = self.tensor_log(p_t_clamped)?;
        let inner = self.tensor_mul(focal_factor, log_p_t)?;

        // per_elem = -alpha_t * inner
        let alpha_inner = self.tensor_mul(alpha_t, inner)?;
        let per_elem = self.tensor_neg(alpha_inner)?;
        self.tensor_mean(per_elem)
    }

    /// Dice loss for segmentation tasks.
    ///
    /// Computes `1 - (2 * intersection + smooth) / (union + smooth)` where
    /// intersection = sum(pred * target), union = sum(pred) + sum(target).
    /// Common in medical image segmentation. Input/target are probability maps.
    pub fn dice_loss(
        &mut self,
        input: TensorNodeId,
        target: TensorNodeId,
        smooth: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        // f32 input returned an F64 loss (self.full/tensor_sum constants are F64): compute in
        // f64, narrow to f32 so f32 training gets an f32 output + f32 grads (torch
        // dice_loss(f32) -> f32). to_dtype is grad-aware. frankentorch-fk5l.
        if self.tensor_dtype(input)? == DType::F32 {
            let in64 = self.tensor_to_dtype(input, DType::F64)?;
            let tgt64 = self.tensor_to_dtype(target, DType::F64)?;
            let loss64 = self.dice_loss(in64, tgt64, smooth)?;
            return self.tensor_to_dtype(loss64, DType::F32);
        }
        let in_shape = self.tensor_shape(input)?;
        let tgt_shape = self.tensor_shape(target)?;
        if in_shape != tgt_shape {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: in_shape,
                    rhs: tgt_shape,
                },
            )));
        }
        let intersection = self.tensor_mul(input, target)?;
        let intersection_sum = self.tensor_sum(intersection)?;
        let input_sum = self.tensor_sum(input)?;
        let target_sum = self.tensor_sum(target)?;
        let two = self.full(vec![1], 2.0, false)?;
        let smooth_tensor = self.full(vec![1], smooth, false)?;
        let numerator = self.tensor_mul(two, intersection_sum)?;
        let numerator = self.tensor_add(numerator, smooth_tensor)?;
        let denominator = self.tensor_add(input_sum, target_sum)?;
        let denominator = self.tensor_add(denominator, smooth_tensor)?;
        let dice_coeff = self.tensor_div(numerator, denominator)?;
        let one = self.full(vec![1], 1.0, false)?;
        self.tensor_sub(one, dice_coeff)
    }

    /// Tversky loss for segmentation tasks.
    ///
    /// Generalization of Dice loss with adjustable false positive/negative weights.
    /// `loss = 1 - (TP + smooth) / (TP + alpha*FP + beta*FN + smooth)`
    /// where TP = sum(pred * target), FP = sum(pred * (1-target)), FN = sum((1-pred) * target).
    /// alpha=beta=0.5 reduces to Dice loss.
    pub fn tversky_loss(
        &mut self,
        input: TensorNodeId,
        target: TensorNodeId,
        alpha: f64,
        beta: f64,
        smooth: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        // f32 -> F64 loss; compute in f64, narrow to f32 (torch tversky_loss(f32) -> f32).
        if self.tensor_dtype(input)? == DType::F32 {
            let in64 = self.tensor_to_dtype(input, DType::F64)?;
            let tgt64 = self.tensor_to_dtype(target, DType::F64)?;
            let loss64 = self.tversky_loss(in64, tgt64, alpha, beta, smooth)?;
            return self.tensor_to_dtype(loss64, DType::F32);
        }
        let in_shape = self.tensor_shape(input)?;
        let tgt_shape = self.tensor_shape(target)?;
        if in_shape != tgt_shape {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: in_shape,
                    rhs: tgt_shape,
                },
            )));
        }
        let ones = self.full(in_shape, 1.0, false)?;
        let one_minus_input = self.tensor_sub(ones, input)?;
        let one_minus_target = self.tensor_sub(ones, target)?;
        let tp = self.tensor_mul(input, target)?;
        let tp_sum = self.tensor_sum(tp)?;
        let fp = self.tensor_mul(input, one_minus_target)?;
        let fp_sum = self.tensor_sum(fp)?;
        let fn_term = self.tensor_mul(one_minus_input, target)?;
        let fn_sum = self.tensor_sum(fn_term)?;
        let smooth_tensor = self.full(vec![1], smooth, false)?;
        let numerator = self.tensor_add(tp_sum, smooth_tensor)?;
        let alpha_fp = self.full(vec![1], alpha, false)?;
        let alpha_fp = self.tensor_mul(alpha_fp, fp_sum)?;
        let beta_fn = self.full(vec![1], beta, false)?;
        let beta_fn = self.tensor_mul(beta_fn, fn_sum)?;
        let denominator = self.tensor_add(tp_sum, alpha_fp)?;
        let denominator = self.tensor_add(denominator, beta_fn)?;
        let denominator = self.tensor_add(denominator, smooth_tensor)?;
        let tversky = self.tensor_div(numerator, denominator)?;
        let one = self.full(vec![1], 1.0, false)?;
        self.tensor_sub(one, tversky)
    }

    /// IoU (Intersection over Union) loss for segmentation tasks.
    ///
    /// Computes `1 - (intersection + smooth) / (union + smooth)` where
    /// intersection = sum(pred * target), union = sum(pred) + sum(target) - intersection.
    /// Also known as Jaccard loss.
    pub fn iou_loss(
        &mut self,
        input: TensorNodeId,
        target: TensorNodeId,
        smooth: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        // f32 -> F64 loss; compute in f64, narrow to f32 (torch iou_loss(f32) -> f32).
        if self.tensor_dtype(input)? == DType::F32 {
            let in64 = self.tensor_to_dtype(input, DType::F64)?;
            let tgt64 = self.tensor_to_dtype(target, DType::F64)?;
            let loss64 = self.iou_loss(in64, tgt64, smooth)?;
            return self.tensor_to_dtype(loss64, DType::F32);
        }
        let in_shape = self.tensor_shape(input)?;
        let tgt_shape = self.tensor_shape(target)?;
        if in_shape != tgt_shape {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: in_shape,
                    rhs: tgt_shape,
                },
            )));
        }
        let intersection = self.tensor_mul(input, target)?;
        let intersection_sum = self.tensor_sum(intersection)?;
        let input_sum = self.tensor_sum(input)?;
        let target_sum = self.tensor_sum(target)?;
        let smooth_tensor = self.full(vec![1], smooth, false)?;
        let numerator = self.tensor_add(intersection_sum, smooth_tensor)?;
        let union = self.tensor_add(input_sum, target_sum)?;
        let union = self.tensor_sub(union, intersection_sum)?;
        let denominator = self.tensor_add(union, smooth_tensor)?;
        let iou = self.tensor_div(numerator, denominator)?;
        let one = self.full(vec![1], 1.0, false)?;
        self.tensor_sub(one, iou)
    }

    /// Contrastive loss for siamese networks.
    ///
    /// Given pairs of embeddings and a binary label (1=similar, 0=dissimilar):
    /// `loss = y * d^2 + (1-y) * max(0, margin - d)^2`
    /// where d = ||x1 - x2||_2 is the Euclidean distance.
    pub fn contrastive_loss(
        &mut self,
        x1: TensorNodeId,
        x2: TensorNodeId,
        y: TensorNodeId,
        margin: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let diff = self.tensor_sub(x1, x2)?;
        let x1_shape = self.tensor_shape(x1)?;
        let last_dim = x1_shape.len().saturating_sub(1);
        let diff_sq = self.tensor_square(diff)?;
        let dist_sq = self.tensor_sum_dim(diff_sq, last_dim)?;
        let dist = self.tensor_sqrt(dist_sq)?;
        // Constants in the INPUT dtype: `self.full` is always F64 so f32 inputs ERROR on the
        // tensor_sub below; `full_like(y, ..)` matches y's dtype+shape (x1/x2/y share dtype),
        // native-f32 compose, bit-identical for f64. frankentorch-fk5l.
        let ones = self.full_like(y, 1.0, false)?;
        let one_minus_y = self.tensor_sub(ones, y)?;
        let positive_loss = self.tensor_mul(y, dist_sq)?;
        let margin_tensor = self.full_like(y, margin, false)?;
        let margin_diff = self.tensor_sub(margin_tensor, dist)?;
        let margin_clamped = self.tensor_clamp_min(margin_diff, 0.0)?;
        let margin_sq = self.tensor_square(margin_clamped)?;
        let negative_loss = self.tensor_mul(one_minus_y, margin_sq)?;
        let loss = self.tensor_add(positive_loss, negative_loss)?;
        self.tensor_mean(loss)
    }

    /// InfoNCE (NT-Xent) loss for contrastive learning.
    ///
    /// Computes the InfoNCE loss used in SimCLR/CLIP:
    /// For each anchor i, computes -log(exp(sim(i,i+)/tau) / sum_j(exp(sim(i,j)/tau)))
    /// where i+ is the positive and all j are negatives.
    ///
    /// Input: embeddings [N, D] where consecutive pairs are positives.
    /// Returns mean loss over all anchors.
    pub fn info_nce_loss(
        &mut self,
        embeddings: TensorNodeId,
        temperature: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(embeddings)?;
        if shape.len() != 2 {
            return Err(Self::incompatible_tensor_args(
                "info_nce_loss: embeddings must be 2D [N, D]",
            ));
        }
        let n = shape[0];
        if n < 2 || n % 2 != 0 {
            return Err(Self::incompatible_tensor_args(
                "info_nce_loss: N must be even and >= 2 (pairs of positives)",
            ));
        }
        let normalized = self.tensor_normalize(embeddings, 2.0, 1, 1e-12)?;
        let transposed = self.tensor_transpose(normalized, 0, 1)?;
        let sim_matrix = self.tensor_matmul(normalized, transposed)?;
        // Scale by 1/temperature via a scalar op — dividing the [N,N] matrix by a
        // full([1]) tensor hits the same non-broadcasting tensor_div that broke
        // tensor_normalize (ShapeMismatch [N,N] vs [1]). frankentorch-c5g4.
        let scaled_sim = self.tensor_mul_scalar(sim_matrix, 1.0 / temperature)?;
        let n_half = n / 2;
        let mut losses = Vec::with_capacity(n);
        for i in 0..n {
            let positive_idx = if i < n_half { i + n_half } else { i - n_half };
            let row = self.tensor_narrow(scaled_sim, 0, i, 1)?;
            let row = self.tensor_squeeze(row, 0)?;
            let positive_score = self.tensor_narrow(row, 0, positive_idx, 1)?;
            let exp_row = self.tensor_exp(row)?;
            let sum_exp = self.tensor_sum(exp_row)?;
            let log_sum_exp = self.tensor_log(sum_exp)?;
            let loss_i = self.tensor_sub(log_sum_exp, positive_score)?;
            losses.push(loss_i);
        }
        let stacked = self.tensor_cat(&losses, 0)?;
        self.tensor_mean(stacked)
    }

    /// Supervised Contrastive Loss (SupCon).
    ///
    /// Unlike InfoNCE which uses only augmentation-based positives,
    /// SupCon uses class labels to identify all positives within the batch.
    /// Loss: -sum_i( 1/|P(i)| * sum_{p in P(i)}( log(exp(z_i·z_p/tau) / sum_a(exp(z_i·z_a/tau))) ) )
    ///
    /// Args:
    /// - embeddings: L2-normalized features [N, D]
    /// - labels: class labels [N]
    /// - temperature: temperature scaling factor
    pub fn supcon_loss(
        &mut self,
        embeddings: TensorNodeId,
        labels: TensorNodeId,
        temperature: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(embeddings)?;
        if shape.len() != 2 {
            return Err(Self::incompatible_tensor_args(
                "supcon_loss: embeddings must be [N, D]",
            ));
        }
        let n = shape[0];
        let d = shape[1];
        let label_data = self.tensor_values(labels)?;
        #[allow(clippy::cast_possible_truncation)]
        let labels_i: Vec<i64> = label_data.iter().map(|&x| x as i64).collect();

        // Label-derived CONSTANT masks (non-grad). pos_mask[i,j]=1 for a positive
        // pair (same label, i≠j); diag_mask pushes the self entry to -1e30 so it
        // underflows out of the log-sum-exp denominator; pos_count is |P(i)|;
        // valid marks anchors that have at least one positive.
        let mut pos_mask = vec![0.0f64; n * n];
        let mut diag_mask = vec![0.0f64; n * n];
        let mut pos_count = vec![0.0f64; n];
        let mut valid = vec![0.0f64; n];
        let mut count = 0usize;
        for i in 0..n {
            diag_mask[i * n + i] = -1e30;
            let mut c = 0.0;
            for j in 0..n {
                if i != j && labels_i[i] == labels_i[j] {
                    pos_mask[i * n + j] = 1.0;
                    c += 1.0;
                }
            }
            pos_count[i] = c;
            if c > 0.0 {
                valid[i] = 1.0;
                count += 1;
            }
        }
        if count == 0 {
            // No anchor has a positive — loss is a constant 0 (matches the prior
            // behaviour and torch when no positive pairs exist).
            return self.tensor_variable(vec![0.0], vec![1], false);
        }
        // Avoid div-by-zero for invalid anchors; their term is zeroed by `valid`.
        let pos_count_safe: Vec<f64> = pos_count.iter().map(|&c| c.max(1.0)).collect();

        // No-grad fused fast path. The autograd op-graph below L2-normalizes,
        // forms the [N,N] cosine gram (one matmul), materialises TWO [N,N] label
        // masks as leaves, and streams ~6 more [N,N] passes (mul_scalar/add/
        // logsumexp/mul/sum_dim) plus tape nodes for a scalar loss. With no grad
        // needed, ft_kernel_cpu::supcon_loss_forward_f64 keeps only the gram GEMM
        // and fuses every reduction into one pass over the gram rows (masks read
        // inline from labels), matching the op-graph arithmetic/order to f64
        // round-off. The grad path (training) is unchanged below.
        if !self.tensor_tape.tensor_requires_grad(embeddings)? {
            let emb_vals = self.tensor_values(embeddings)?;
            let loss = ft_kernel_cpu::supcon_loss_forward_f64(
                &emb_vals,
                &labels_i,
                &pos_count_safe,
                &valid,
                count,
                temperature,
                n,
                d,
            );
            return self.tensor_variable(vec![loss], vec![1], false);
        }

        // L2-normalize each row (autograd-aware), then the [N,N] cosine
        // similarity matrix is ONE GEMM-routed matmul — replacing the old naive
        // O(N^2*D) dot-product sweep that ALSO rebuilt a requires_grad=false leaf
        // and severed the tape (supcon could not train). frankentorch-qd4p.
        let sq = self.tensor_mul(embeddings, embeddings)?;
        let sumsq = self.tensor_sum_dim(sq, 1)?; // [N]
        let norm = self.tensor_sqrt(sumsq)?; // [N]
        let norm_safe = self.tensor_clamp_min(norm, 1e-12)?;
        let norm_col = self.tensor_unsqueeze(norm_safe, 1)?; // [N,1]
        let norm_exp = self.tensor_expand(norm_col, vec![n, d])?;
        let normalized = self.tensor_div(embeddings, norm_exp)?; // [N,D]
        let normalized_t = self.tensor_transpose(normalized, 0, 1)?; // [D,N]
        let gram = self.tensor_matmul(normalized, normalized_t)?; // [N,N]
        let sim = self.tensor_mul_scalar(gram, 1.0 / temperature)?; // [N,N]

        // Denominator: log Σ_{j≠i} exp(sim[i,j]) via a masked log-sum-exp.
        let diag_t = self.tensor_variable(diag_mask, vec![n, n], false)?;
        let sim_masked = self.tensor_add(sim, diag_t)?;
        let log_denom = self.tensor_logsumexp(sim_masked, 1)?; // [N]

        // Numerator: mean over positives of sim[i,p] = (Σ_j posmask·sim)/|P(i)|.
        let pos_t = self.tensor_variable(pos_mask, vec![n, n], false)?;
        let masked_sim = self.tensor_mul(sim, pos_t)?;
        let num = self.tensor_sum_dim(masked_sim, 1)?; // [N]
        let pos_count_t = self.tensor_variable(pos_count_safe, vec![n], false)?;
        let mean_pos = self.tensor_div(num, pos_count_t)?; // [N]

        // term_i = mean_pos_i − log_denom_i; zero out anchors with no positives,
        // sum, and scale by −1/count to form the SupCon (out) mean loss.
        let term = self.tensor_sub(mean_pos, log_denom)?; // [N]
        let valid_t = self.tensor_variable(valid, vec![n], false)?;
        let masked_term = self.tensor_mul(term, valid_t)?; // [N]
        let summed = self.tensor_sum(masked_term)?;
        #[allow(clippy::cast_precision_loss)]
        let scaled = self.tensor_mul_scalar(summed, -1.0 / count as f64)?;
        self.tensor_reshape(scaled, vec![1])
    }

    /// Barlow Twins loss for self-supervised learning.
    ///
    /// Encourages embeddings of augmented views to be similar while
    /// decorrelating feature dimensions. Loss = sum((C - I)^2) where
    /// C is the cross-correlation matrix and I is identity.
    ///
    /// Args:
    /// - z1, z2: embeddings of two augmented views [N, D]
    /// - lambda_coeff: weight for off-diagonal terms (default 0.005)
    pub fn barlow_twins_loss(
        &mut self,
        z1: TensorNodeId,
        z2: TensorNodeId,
        lambda_coeff: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape1 = self.tensor_shape(z1)?;
        let shape2 = self.tensor_shape(z2)?;
        if shape1 != shape2 || shape1.len() != 2 {
            return Err(Self::incompatible_tensor_args(
                "barlow_twins_loss: z1 and z2 must have same shape [N, D]",
            ));
        }
        let (n, d) = (shape1[0], shape1[1]);
        let mean1 = self.tensor_mean_dim(z1, 0)?;
        let mean2 = self.tensor_mean_dim(z2, 0)?;
        let z1_centered = self.tensor_sub(z1, mean1)?;
        let z2_centered = self.tensor_sub(z2, mean2)?;
        let std1 = self.tensor_std_dim(z1_centered, 0, 1)?;
        let std2 = self.tensor_std_dim(z2_centered, 0, 1)?;
        let eps = self.full(vec![d], 1e-6, false)?;
        let std1_safe = self.tensor_add(std1, eps)?;
        let std2_safe = self.tensor_add(std2, eps)?;
        let z1_norm = self.tensor_div(z1_centered, std1_safe)?;
        let z2_norm = self.tensor_div(z2_centered, std2_safe)?;
        let z1_t = self.tensor_transpose(z1_norm, 0, 1)?;
        let cross_corr = self.tensor_matmul(z1_t, z2_norm)?;
        let scale = self.full(vec![d, d], 1.0 / n as f64, false)?;
        let cross_corr = self.tensor_mul(cross_corr, scale)?;
        let mut loss_diag = 0.0;
        let mut loss_off = 0.0;
        let cc_data = self.tensor_values(cross_corr)?;
        for i in 0..d {
            for j in 0..d {
                let val = cc_data[i * d + j];
                if i == j {
                    loss_diag += (1.0 - val).powi(2);
                } else {
                    loss_off += val.powi(2);
                }
            }
        }
        let total_loss = loss_diag + lambda_coeff * loss_off;
        self.tensor_variable(vec![total_loss], vec![1], false)
    }

    /// VICReg (Variance-Invariance-Covariance Regularization) loss.
    ///
    /// Three-term loss for self-supervised learning:
    /// - Invariance: MSE between representations of augmented views
    /// - Variance: hinge loss to keep std > 1
    /// - Covariance: decorrelation of feature dimensions
    ///
    /// Args:
    /// - z1, z2: embeddings of two views [N, D]
    /// - sim_coeff, std_coeff, cov_coeff: loss term weights
    pub fn vicreg_loss(
        &mut self,
        z1: TensorNodeId,
        z2: TensorNodeId,
        sim_coeff: f64,
        std_coeff: f64,
        cov_coeff: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape1 = self.tensor_shape(z1)?;
        let shape2 = self.tensor_shape(z2)?;
        if shape1 != shape2 || shape1.len() != 2 {
            return Err(Self::incompatible_tensor_args(
                "vicreg_loss: z1 and z2 must have same shape [N, D]",
            ));
        }
        // f32 inputs ERRORED (UnsupportedDType(F32)): the compose below mixes z1/z2 (F32) with
        // f64 `self.full()`/reduction intermediates whose mixed-dtype path reads the f32
        // operand via an F64-only accessor. Compute in f64 then narrow the scalar loss to f32;
        // to_dtype is grad-aware. frankentorch-fk5l.
        if self.tensor_dtype(z1)? == DType::F32 {
            let z1_64 = self.tensor_to_dtype(z1, DType::F64)?;
            let z2_64 = self.tensor_to_dtype(z2, DType::F64)?;
            let loss64 = self.vicreg_loss(z1_64, z2_64, sim_coeff, std_coeff, cov_coeff)?;
            return self.tensor_to_dtype(loss64, DType::F32);
        }
        let (n, d) = (shape1[0], shape1[1]);
        let diff = self.tensor_sub(z1, z2)?;
        let diff_sq = self.tensor_mul(diff, diff)?;
        let sim_loss = self.tensor_mean(diff_sq)?;
        let mean1 = self.tensor_mean_dim(z1, 0)?;
        let mean2 = self.tensor_mean_dim(z2, 0)?;
        let z1_c = self.tensor_sub(z1, mean1)?;
        let z2_c = self.tensor_sub(z2, mean2)?;
        let std1 = self.tensor_std_dim(z1_c, 0, 1)?;
        let std2 = self.tensor_std_dim(z2_c, 0, 1)?;
        let std_data1 = self.tensor_values(std1)?;
        let std_data2 = self.tensor_values(std2)?;
        let var_loss: f64 = std_data1
            .iter()
            .chain(std_data2.iter())
            .map(|&s| (1.0 - s).max(0.0).powi(2))
            .sum::<f64>()
            / (2.0 * d as f64);
        let z1_t = self.tensor_transpose(z1_c, 0, 1)?;
        let z2_t = self.tensor_transpose(z2_c, 0, 1)?;
        let cov1 = self.tensor_matmul(z1_t, z1_c)?;
        let cov2 = self.tensor_matmul(z2_t, z2_c)?;
        let scale = self.full(vec![d, d], 1.0 / (n - 1).max(1) as f64, false)?;
        let cov1 = self.tensor_mul(cov1, scale)?;
        let cov2 = self.tensor_mul(cov2, scale)?;
        let cov1_data = self.tensor_values(cov1)?;
        let cov2_data = self.tensor_values(cov2)?;
        let mut cov_loss = 0.0;
        for i in 0..d {
            for j in 0..d {
                if i != j {
                    cov_loss += cov1_data[i * d + j].powi(2) + cov2_data[i * d + j].powi(2);
                }
            }
        }
        cov_loss /= d as f64;
        let sim_val = self.tensor_values(sim_loss)?[0];
        let total = sim_coeff * sim_val + std_coeff * var_loss + cov_coeff * cov_loss;
        self.tensor_variable(vec![total], vec![1], false)
    }

    // ── Point Cloud Operations ─────────────────────────────────────────

    /// Farthest point sampling for point clouds (PointNet++).
    ///
    /// Iteratively selects points that are farthest from the already selected set.
    /// Used to downsample point clouds while preserving spatial coverage.
    ///
    /// Args:
    /// - points: [N, 3] or [B, N, 3] input point cloud coordinates
    /// - num_samples: number of points to sample
    ///
    /// Returns: [num_samples] or [B, num_samples] indices of selected points
    pub fn farthest_point_sampling(
        &mut self,
        points: TensorNodeId,
        num_samples: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(points)?;
        let (batch_size, n_points, coords) = match shape.len() {
            2 => (1, shape[0], shape[1]),
            3 => (shape[0], shape[1], shape[2]),
            _ => {
                return Err(Self::incompatible_tensor_args(
                    "farthest_point_sampling: points must be [N, 3] or [B, N, 3]",
                ));
            }
        };
        if coords != 3 {
            return Err(Self::incompatible_tensor_args(
                "farthest_point_sampling: last dimension must be 3 (xyz)",
            ));
        }
        if num_samples > n_points {
            return Err(Self::incompatible_tensor_args(
                "farthest_point_sampling: num_samples > number of points",
            ));
        }
        let data = self.tensor_values_lossy_f64(points)?;
        // The ONLY RNG use is the random first point per batch. Pre-draw all firsts
        // serially in batch order so the Xoshiro sequence is byte-identical to the
        // serial version (the greedy loop draws no RNG), then run the independent,
        // deterministic per-batch greedy farthest-point loops in parallel over batch.
        // Bit-identical: each batch's result is fully determined by its first index.
        let firsts: Vec<usize> = (0..batch_size)
            .map(|_| self.rng.next_u64() as usize % n_points)
            .collect();
        let fps_one = |b: usize| -> Vec<f64> {
            let batch_offset = b * n_points * 3;
            let mut distances = vec![f64::MAX; n_points];
            let mut indices = Vec::with_capacity(num_samples);
            indices.push(firsts[b]);
            for _ in 1..num_samples {
                let last = *indices.last().unwrap();
                let (lx, ly, lz) = (
                    data[batch_offset + last * 3],
                    data[batch_offset + last * 3 + 1],
                    data[batch_offset + last * 3 + 2],
                );
                let mut farthest_idx = 0;
                let mut max_dist = f64::NEG_INFINITY;
                for i in 0..n_points {
                    let (px, py, pz) = (
                        data[batch_offset + i * 3],
                        data[batch_offset + i * 3 + 1],
                        data[batch_offset + i * 3 + 2],
                    );
                    let d = (px - lx).powi(2) + (py - ly).powi(2) + (pz - lz).powi(2);
                    distances[i] = distances[i].min(d);
                    if distances[i] > max_dist {
                        max_dist = distances[i];
                        farthest_idx = i;
                    }
                }
                indices.push(farthest_idx);
            }
            indices.into_iter().map(|i| i as f64).collect()
        };
        let all_indices: Vec<f64> =
            if batch_size >= 2 && batch_size * num_samples * n_points >= (1 << 16) {
                use rayon::prelude::*;
                let per_b: Vec<Vec<f64>> = (0..batch_size).into_par_iter().map(fps_one).collect();
                per_b.into_iter().flatten().collect()
            } else {
                (0..batch_size).flat_map(fps_one).collect()
            };
        let out_shape = if shape.len() == 2 {
            vec![num_samples]
        } else {
            vec![batch_size, num_samples]
        };
        self.tensor_variable(all_indices, out_shape, false)
    }

    /// Ball query: find all points within a radius of query points.
    ///
    /// For each query point, finds up to `max_samples` points within `radius`.
    /// Used in PointNet++ for local neighborhood aggregation.
    ///
    /// Args:
    /// - points: [N, 3] or [B, N, 3] point cloud coordinates
    /// - queries: [M, 3] or [B, M, 3] query point coordinates
    /// - radius: search radius
    /// - max_samples: maximum number of neighbors per query
    ///
    /// Returns: [M, max_samples] or [B, M, max_samples] neighbor indices (padded with -1)
    pub fn ball_query(
        &mut self,
        points: TensorNodeId,
        queries: TensorNodeId,
        radius: f64,
        max_samples: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let p_shape = self.tensor_shape(points)?;
        let q_shape = self.tensor_shape(queries)?;
        let (batch_size, n_points, n_queries) = match (p_shape.len(), q_shape.len()) {
            (2, 2) => (1, p_shape[0], q_shape[0]),
            (3, 3) if p_shape[0] == q_shape[0] => (p_shape[0], p_shape[1], q_shape[1]),
            _ => {
                return Err(Self::incompatible_tensor_args(
                    "ball_query: points and queries must have compatible shapes",
                ));
            }
        };
        let p_data = self.tensor_values_lossy_f64(points)?;
        let q_data = self.tensor_values_lossy_f64(queries)?;
        let r_sq = radius * radius;
        let mut indices = vec![-1.0; batch_size * n_queries * max_samples];
        // Each (b, qi) query independently scans points in order, taking the first
        // max_samples within radius, and writes a DISJOINT max_samples-sized slot.
        // Lay the output out as [batch*n_queries] chunks of max_samples and fill each
        // in parallel — bit-identical to the serial loops: every query's scan order
        // and result are unchanged; only the outer (b, qi) iteration parallelizes.
        let fill = |chunk_idx: usize, slot: &mut [f64]| {
            let b = chunk_idx / n_queries;
            let qi = chunk_idx % n_queries;
            let p_off = b * n_points * 3;
            let q_off = b * n_queries * 3;
            let qx = q_data[q_off + qi * 3];
            let qy = q_data[q_off + qi * 3 + 1];
            let qz = q_data[q_off + qi * 3 + 2];
            let mut count = 0;
            for pi in 0..n_points {
                if count >= max_samples {
                    break;
                }
                let px = p_data[p_off + pi * 3];
                let py = p_data[p_off + pi * 3 + 1];
                let pz = p_data[p_off + pi * 3 + 2];
                let d_sq = (px - qx).powi(2) + (py - qy).powi(2) + (pz - qz).powi(2);
                if d_sq <= r_sq {
                    slot[count] = pi as f64;
                    count += 1;
                }
            }
        };
        if max_samples > 0 {
            if batch_size * n_queries * n_points >= (1 << 16) {
                use rayon::prelude::*;
                indices
                    .par_chunks_mut(max_samples)
                    .enumerate()
                    .for_each(|(chunk_idx, slot)| fill(chunk_idx, slot));
            } else {
                for (chunk_idx, slot) in indices.chunks_mut(max_samples).enumerate() {
                    fill(chunk_idx, slot);
                }
            }
        }
        let out_shape = if p_shape.len() == 2 {
            vec![n_queries, max_samples]
        } else {
            vec![batch_size, n_queries, max_samples]
        };
        self.tensor_variable(indices, out_shape, false)
    }

    /// K-nearest neighbors search for point clouds.
    ///
    /// For each query point, finds the k nearest points.
    ///
    /// Args:
    /// - points: [N, 3] or [B, N, 3] point cloud coordinates
    /// - queries: [M, 3] or [B, M, 3] query point coordinates
    /// - k: number of nearest neighbors to find
    ///
    /// Returns: ([M, k] or [B, M, k] indices, [M, k] or [B, M, k] distances)
    pub fn knn_search(
        &mut self,
        points: TensorNodeId,
        queries: TensorNodeId,
        k: usize,
    ) -> Result<(TensorNodeId, TensorNodeId), AutogradError> {
        let p_shape = self.tensor_shape(points)?;
        let q_shape = self.tensor_shape(queries)?;
        let (batch_size, n_points, n_queries) = match (p_shape.len(), q_shape.len()) {
            (2, 2) => (1, p_shape[0], q_shape[0]),
            (3, 3) if p_shape[0] == q_shape[0] => (p_shape[0], p_shape[1], q_shape[1]),
            _ => {
                return Err(Self::incompatible_tensor_args(
                    "knn_search: points and queries must have compatible shapes",
                ));
            }
        };
        if k > n_points {
            return Err(Self::incompatible_tensor_args(
                "knn_search: k > number of points",
            ));
        }
        if k == 0 {
            let out_shape = if p_shape.len() == 2 {
                vec![n_queries, k]
            } else {
                vec![batch_size, n_queries, k]
            };
            let idx_t = self.tensor_variable(Vec::<f64>::new(), out_shape.clone(), false)?;
            let dist_t = self.tensor_variable(Vec::<f64>::new(), out_shape, false)?;
            return Ok((idx_t, dist_t));
        }
        fn consider_knn_candidate(
            best_idx: &mut [usize],
            best_dist: &mut [f64],
            best_len: &mut usize,
            k: usize,
            pi: usize,
            d: f64,
        ) {
            // Early-reject once the top-k buffer is full. The retained prefix is
            // sorted ascending, so best_dist[k-1] is the worst retained distance.
            // Strict `<` preserves the prior tie behavior: equal distances keep
            // their earlier point order and equal-to-worst candidates are ignored.
            if *best_len == k && d.partial_cmp(&best_dist[k - 1]) != Some(std::cmp::Ordering::Less)
            {
                return;
            }

            let mut insert_at = *best_len;
            for (pos, &best_d) in best_dist[..*best_len].iter().enumerate() {
                if d.partial_cmp(&best_d) == Some(std::cmp::Ordering::Less) {
                    insert_at = pos;
                    break;
                }
            }

            if insert_at < *best_len {
                let new_len = (*best_len + 1).min(k);
                for pos in (insert_at + 1..new_len).rev() {
                    best_idx[pos] = best_idx[pos - 1];
                    best_dist[pos] = best_dist[pos - 1];
                }
                best_idx[insert_at] = pi;
                best_dist[insert_at] = d;
                if *best_len < k {
                    *best_len += 1;
                }
            } else if *best_len < k {
                best_idx[*best_len] = pi;
                best_dist[*best_len] = d;
                *best_len += 1;
            }
        }
        #[inline]
        fn consider_knn_candidate_k8(
            best_idx: &mut [usize; 8],
            best_dist: &mut [f64; 8],
            best_len: &mut usize,
            pi: usize,
            d: f64,
        ) {
            if *best_len == 8 && d.partial_cmp(&best_dist[7]) != Some(std::cmp::Ordering::Less) {
                return;
            }

            let len = *best_len;
            let mut insert_at = len;
            for (pos, &best_d) in best_dist[..len].iter().enumerate() {
                if d.partial_cmp(&best_d) == Some(std::cmp::Ordering::Less) {
                    insert_at = pos;
                    break;
                }
            }

            if insert_at < len {
                let new_len = (len + 1).min(8);
                for pos in (insert_at + 1..new_len).rev() {
                    best_idx[pos] = best_idx[pos - 1];
                    best_dist[pos] = best_dist[pos - 1];
                }
                best_idx[insert_at] = pi;
                best_dist[insert_at] = d;
                if len < 8 {
                    *best_len = len + 1;
                }
            } else if len < 8 {
                best_idx[len] = pi;
                best_dist[len] = d;
                *best_len = len + 1;
            }
        }
        #[derive(Clone, Copy)]
        struct KnnKdNode {
            start: usize,
            end: usize,
            left: usize,
            right: usize,
            min: [f64; 3],
            max: [f64; 3],
        }
        impl KnnKdNode {
            #[inline]
            fn is_leaf(self) -> bool {
                self.left == usize::MAX
            }
        }
        #[inline]
        fn knn_point_coord(p_data: &[f64], p_off: usize, pi: usize, dim: usize) -> f64 {
            p_data[p_off + pi * 3 + dim]
        }
        #[inline]
        fn knn_tie_less(d: f64, pi: usize, best_d: f64, best_i: usize) -> bool {
            match d.partial_cmp(&best_d) {
                Some(std::cmp::Ordering::Less) => true,
                Some(std::cmp::Ordering::Equal) => pi < best_i,
                _ => false,
            }
        }
        #[inline]
        fn consider_knn_candidate_k8_by_index(
            best_idx: &mut [usize; 8],
            best_dist: &mut [f64; 8],
            best_len: &mut usize,
            pi: usize,
            d: f64,
        ) {
            if *best_len == 8 && !knn_tie_less(d, pi, best_dist[7], best_idx[7]) {
                return;
            }

            let len = *best_len;
            let mut insert_at = len;
            for pos in 0..len {
                if knn_tie_less(d, pi, best_dist[pos], best_idx[pos]) {
                    insert_at = pos;
                    break;
                }
            }

            if insert_at < len {
                let new_len = (len + 1).min(8);
                for pos in (insert_at + 1..new_len).rev() {
                    best_idx[pos] = best_idx[pos - 1];
                    best_dist[pos] = best_dist[pos - 1];
                }
                best_idx[insert_at] = pi;
                best_dist[insert_at] = d;
                if len < 8 {
                    *best_len = len + 1;
                }
            } else if len < 8 {
                best_idx[len] = pi;
                best_dist[len] = d;
                *best_len = len + 1;
            }
        }
        #[inline]
        fn knn_bbox_lower_bound(node: KnnKdNode, qx: f64, qy: f64, qz: f64) -> f64 {
            let dx = if qx < node.min[0] {
                node.min[0] - qx
            } else if qx > node.max[0] {
                qx - node.max[0]
            } else {
                0.0
            };
            let dy = if qy < node.min[1] {
                node.min[1] - qy
            } else if qy > node.max[1] {
                qy - node.max[1]
            } else {
                0.0
            };
            let dz = if qz < node.min[2] {
                node.min[2] - qz
            } else if qz > node.max[2] {
                qz - node.max[2]
            } else {
                0.0
            };
            dx * dx + dy * dy + dz * dz
        }
        fn build_knn_kd_tree(
            nodes: &mut Vec<KnnKdNode>,
            order: &mut [usize],
            p_data: &[f64],
            p_off: usize,
            start: usize,
            end: usize,
        ) -> usize {
            const KNN_KD_LEAF_POINTS: usize = 32;

            let mut min = [f64::INFINITY; 3];
            let mut max = [f64::NEG_INFINITY; 3];
            for &pi in &order[start..end] {
                for dim in 0..3 {
                    let value = knn_point_coord(p_data, p_off, pi, dim);
                    min[dim] = min[dim].min(value);
                    max[dim] = max[dim].max(value);
                }
            }

            let node_idx = nodes.len();
            nodes.push(KnnKdNode {
                start,
                end,
                left: usize::MAX,
                right: usize::MAX,
                min,
                max,
            });
            if end - start <= KNN_KD_LEAF_POINTS {
                return node_idx;
            }

            let spread = [max[0] - min[0], max[1] - min[1], max[2] - min[2]];
            let split_dim = if spread[1] > spread[0] && spread[1] >= spread[2] {
                1
            } else if spread[2] > spread[0] && spread[2] > spread[1] {
                2
            } else {
                0
            };
            order[start..end].sort_by(|&a, &b| {
                knn_point_coord(p_data, p_off, a, split_dim)
                    .partial_cmp(&knn_point_coord(p_data, p_off, b, split_dim))
                    .unwrap_or(std::cmp::Ordering::Equal)
                    .then_with(|| a.cmp(&b))
            });
            let mid = start + (end - start) / 2;
            let left = build_knn_kd_tree(nodes, order, p_data, p_off, start, mid);
            let right = build_knn_kd_tree(nodes, order, p_data, p_off, mid, end);
            nodes[node_idx].left = left;
            nodes[node_idx].right = right;
            node_idx
        }
        fn search_knn_kd_tree_k8(
            nodes: &[KnnKdNode],
            order: &[usize],
            p_data: &[f64],
            p_off: usize,
            root: usize,
            qx: f64,
            qy: f64,
            qz: f64,
            best_idx: &mut [usize; 8],
            best_dist: &mut [f64; 8],
            best_len: &mut usize,
            stack: &mut Vec<usize>,
        ) {
            stack.clear();
            stack.push(root);
            while let Some(node_idx) = stack.pop() {
                let node = nodes[node_idx];
                if *best_len == 8 {
                    let lower = knn_bbox_lower_bound(node, qx, qy, qz);
                    if lower.partial_cmp(&best_dist[7]) == Some(std::cmp::Ordering::Greater) {
                        continue;
                    }
                }

                if node.is_leaf() {
                    for &pi in &order[node.start..node.end] {
                        let px = p_data[p_off + pi * 3];
                        let py = p_data[p_off + pi * 3 + 1];
                        let pz = p_data[p_off + pi * 3 + 2];
                        let dx = px - qx;
                        let dy = py - qy;
                        let dz = pz - qz;
                        let d = dx * dx + dy * dy + dz * dz;
                        consider_knn_candidate_k8_by_index(best_idx, best_dist, best_len, pi, d);
                    }
                } else {
                    let left = nodes[node.left];
                    let right = nodes[node.right];
                    let left_lower = knn_bbox_lower_bound(left, qx, qy, qz);
                    let right_lower = knn_bbox_lower_bound(right, qx, qy, qz);
                    let worst = if *best_len == 8 {
                        best_dist[7]
                    } else {
                        f64::INFINITY
                    };
                    let visit_left =
                        left_lower.partial_cmp(&worst) != Some(std::cmp::Ordering::Greater);
                    let visit_right =
                        right_lower.partial_cmp(&worst) != Some(std::cmp::Ordering::Greater);
                    if left_lower <= right_lower {
                        if visit_right {
                            stack.push(node.right);
                        }
                        if visit_left {
                            stack.push(node.left);
                        }
                    } else {
                        if visit_left {
                            stack.push(node.left);
                        }
                        if visit_right {
                            stack.push(node.right);
                        }
                    }
                }
            }
        }
        let p_data = self.tensor_values_lossy_f64(points)?;
        let q_data = self.tensor_values_lossy_f64(queries)?;
        let mut indices = vec![0.0; batch_size * n_queries * k];
        let mut distances = vec![0.0; batch_size * n_queries * k];
        const KNN_QUERY_TILE: usize = 16;
        const KNN_POINT_PANEL: usize = 64;
        const KNN_KD_MIN_POINTS: usize = 1024;
        const KNN_KD_MIN_QUERIES: usize = 64;
        let knn_coords_are_finite = p_data.iter().all(|value| value.is_finite())
            && q_data.iter().all(|value| value.is_finite());
        if k == 8
            && knn_coords_are_finite
            && n_points >= KNN_KD_MIN_POINTS
            && n_queries >= KNN_KD_MIN_QUERIES
        {
            for b in 0..batch_size {
                let p_off = b * n_points * 3;
                let q_off = b * n_queries * 3;
                let out_off = b * n_queries * 8;
                let mut order = (0..n_points).collect::<Vec<_>>();
                let mut nodes = Vec::with_capacity((n_points / 16).max(1));
                let root = build_knn_kd_tree(&mut nodes, &mut order, &p_data, p_off, 0, n_points);
                let mut stack = Vec::with_capacity(64);
                for qi in 0..n_queries {
                    let qx = q_data[q_off + qi * 3];
                    let qy = q_data[q_off + qi * 3 + 1];
                    let qz = q_data[q_off + qi * 3 + 2];
                    let mut best_idx = [0usize; 8];
                    let mut best_dist = [0.0f64; 8];
                    let mut best_len = 0usize;
                    search_knn_kd_tree_k8(
                        &nodes,
                        &order,
                        &p_data,
                        p_off,
                        root,
                        qx,
                        qy,
                        qz,
                        &mut best_idx,
                        &mut best_dist,
                        &mut best_len,
                        &mut stack,
                    );
                    for j in 0..best_len {
                        indices[out_off + qi * 8 + j] = best_idx[j] as f64;
                        distances[out_off + qi * 8 + j] = best_dist[j].sqrt();
                    }
                }
            }
            let out_shape = if p_shape.len() == 2 {
                vec![n_queries, k]
            } else {
                vec![batch_size, n_queries, k]
            };
            let idx_t = self.tensor_variable(indices, out_shape.clone(), false)?;
            let dist_t = self.tensor_variable(distances, out_shape, false)?;
            return Ok((idx_t, dist_t));
        }
        if k == 8 {
            for b in 0..batch_size {
                let p_off = b * n_points * 3;
                let q_off = b * n_queries * 3;
                let out_off = b * n_queries * 8;
                let mut best_indices = [[0usize; 8]; KNN_QUERY_TILE];
                let mut best_distances = [[0.0f64; 8]; KNN_QUERY_TILE];
                let mut best_lens = [0usize; KNN_QUERY_TILE];
                let mut tile_qx = [0.0f64; KNN_QUERY_TILE];
                let mut tile_qy = [0.0f64; KNN_QUERY_TILE];
                let mut tile_qz = [0.0f64; KNN_QUERY_TILE];
                let mut panel_px = [0.0f64; KNN_POINT_PANEL];
                let mut panel_py = [0.0f64; KNN_POINT_PANEL];
                let mut panel_pz = [0.0f64; KNN_POINT_PANEL];
                for q_start in (0..n_queries).step_by(KNN_QUERY_TILE) {
                    let tile_len = (n_queries - q_start).min(KNN_QUERY_TILE);
                    for local_q in 0..tile_len {
                        let qi = q_start + local_q;
                        tile_qx[local_q] = q_data[q_off + qi * 3];
                        tile_qy[local_q] = q_data[q_off + qi * 3 + 1];
                        tile_qz[local_q] = q_data[q_off + qi * 3 + 2];
                        best_lens[local_q] = 0;
                    }
                    for p_start in (0..n_points).step_by(KNN_POINT_PANEL) {
                        let point_panel_len = (n_points - p_start).min(KNN_POINT_PANEL);
                        for local_p in 0..point_panel_len {
                            let pi = p_start + local_p;
                            panel_px[local_p] = p_data[p_off + pi * 3];
                            panel_py[local_p] = p_data[p_off + pi * 3 + 1];
                            panel_pz[local_p] = p_data[p_off + pi * 3 + 2];
                        }
                        if knn_coords_are_finite {
                            for local_q in 0..tile_len {
                                let qx = tile_qx[local_q];
                                let qy = tile_qy[local_q];
                                let qz = tile_qz[local_q];
                                let qxv = f64x4::splat(qx);
                                let qyv = f64x4::splat(qy);
                                let qzv = f64x4::splat(qz);
                                let mut local_p = 0;
                                while local_p + 4 <= point_panel_len {
                                    let px = f64x4::new([
                                        panel_px[local_p],
                                        panel_px[local_p + 1],
                                        panel_px[local_p + 2],
                                        panel_px[local_p + 3],
                                    ]);
                                    let py = f64x4::new([
                                        panel_py[local_p],
                                        panel_py[local_p + 1],
                                        panel_py[local_p + 2],
                                        panel_py[local_p + 3],
                                    ]);
                                    let pz = f64x4::new([
                                        panel_pz[local_p],
                                        panel_pz[local_p + 1],
                                        panel_pz[local_p + 2],
                                        panel_pz[local_p + 3],
                                    ]);
                                    let dx = px - qxv;
                                    let dy = py - qyv;
                                    let dz = pz - qzv;
                                    let dist = dx * dx + dy * dy + dz * dz;
                                    let lane_dist = dist.to_array();
                                    for (lane, &d) in lane_dist.iter().enumerate() {
                                        consider_knn_candidate_k8(
                                            &mut best_indices[local_q],
                                            &mut best_distances[local_q],
                                            &mut best_lens[local_q],
                                            p_start + local_p + lane,
                                            d,
                                        );
                                    }
                                    local_p += 4;
                                }
                                while local_p < point_panel_len {
                                    let dx = panel_px[local_p] - qx;
                                    let dy = panel_py[local_p] - qy;
                                    let dz = panel_pz[local_p] - qz;
                                    let d = dx * dx + dy * dy + dz * dz;
                                    consider_knn_candidate_k8(
                                        &mut best_indices[local_q],
                                        &mut best_distances[local_q],
                                        &mut best_lens[local_q],
                                        p_start + local_p,
                                        d,
                                    );
                                    local_p += 1;
                                }
                            }
                        } else {
                            for local_q in 0..tile_len {
                                let qx = tile_qx[local_q];
                                let qy = tile_qy[local_q];
                                let qz = tile_qz[local_q];
                                for local_p in 0..point_panel_len {
                                    let dx = panel_px[local_p] - qx;
                                    let dy = panel_py[local_p] - qy;
                                    let dz = panel_pz[local_p] - qz;
                                    let d = dx * dx + dy * dy + dz * dz;
                                    consider_knn_candidate_k8(
                                        &mut best_indices[local_q],
                                        &mut best_distances[local_q],
                                        &mut best_lens[local_q],
                                        p_start + local_p,
                                        d,
                                    );
                                }
                            }
                        }
                    }
                    for local_q in 0..tile_len {
                        let qi = q_start + local_q;
                        for j in 0..best_lens[local_q] {
                            let pi = best_indices[local_q][j];
                            let d = best_distances[local_q][j];
                            indices[out_off + qi * 8 + j] = pi as f64;
                            distances[out_off + qi * 8 + j] = d.sqrt();
                        }
                    }
                }
            }
            let out_shape = if p_shape.len() == 2 {
                vec![n_queries, k]
            } else {
                vec![batch_size, n_queries, k]
            };
            let idx_t = self.tensor_variable(indices, out_shape.clone(), false)?;
            let dist_t = self.tensor_variable(distances, out_shape, false)?;
            return Ok((idx_t, dist_t));
        }
        for b in 0..batch_size {
            let p_off = b * n_points * 3;
            let q_off = b * n_queries * 3;
            let out_off = b * n_queries * k;
            let mut best_indices = vec![0usize; KNN_QUERY_TILE * k];
            let mut best_distances = vec![0.0f64; KNN_QUERY_TILE * k];
            let mut best_lens = [0usize; KNN_QUERY_TILE];
            let mut tile_qx = [0.0f64; KNN_QUERY_TILE];
            let mut tile_qy = [0.0f64; KNN_QUERY_TILE];
            let mut tile_qz = [0.0f64; KNN_QUERY_TILE];
            let mut panel_px = [0.0f64; KNN_POINT_PANEL];
            let mut panel_py = [0.0f64; KNN_POINT_PANEL];
            let mut panel_pz = [0.0f64; KNN_POINT_PANEL];
            for q_start in (0..n_queries).step_by(KNN_QUERY_TILE) {
                let tile_len = (n_queries - q_start).min(KNN_QUERY_TILE);
                for local_q in 0..tile_len {
                    let qi = q_start + local_q;
                    tile_qx[local_q] = q_data[q_off + qi * 3];
                    tile_qy[local_q] = q_data[q_off + qi * 3 + 1];
                    tile_qz[local_q] = q_data[q_off + qi * 3 + 2];
                    best_lens[local_q] = 0;
                }
                for p_start in (0..n_points).step_by(KNN_POINT_PANEL) {
                    let point_panel_len = (n_points - p_start).min(KNN_POINT_PANEL);
                    for local_p in 0..point_panel_len {
                        let pi = p_start + local_p;
                        panel_px[local_p] = p_data[p_off + pi * 3];
                        panel_py[local_p] = p_data[p_off + pi * 3 + 1];
                        panel_pz[local_p] = p_data[p_off + pi * 3 + 2];
                    }
                    for local_q in 0..tile_len {
                        let best_start = local_q * k;
                        let best_idx = &mut best_indices[best_start..best_start + k];
                        let best_dist = &mut best_distances[best_start..best_start + k];
                        let best_len = &mut best_lens[local_q];
                        let qx = tile_qx[local_q];
                        let qy = tile_qy[local_q];
                        let qz = tile_qz[local_q];
                        for local_p in 0..point_panel_len {
                            let dx = panel_px[local_p] - qx;
                            let dy = panel_py[local_p] - qy;
                            let dz = panel_pz[local_p] - qz;
                            let d = dx * dx + dy * dy + dz * dz;
                            consider_knn_candidate(
                                best_idx,
                                best_dist,
                                best_len,
                                k,
                                p_start + local_p,
                                d,
                            );
                        }
                    }
                }
                for local_q in 0..tile_len {
                    let qi = q_start + local_q;
                    let best_start = local_q * k;
                    for j in 0..best_lens[local_q] {
                        let pi = best_indices[best_start + j];
                        let d = best_distances[best_start + j];
                        indices[out_off + qi * k + j] = pi as f64;
                        distances[out_off + qi * k + j] = d.sqrt();
                    }
                }
            }
        }
        let out_shape = if p_shape.len() == 2 {
            vec![n_queries, k]
        } else {
            vec![batch_size, n_queries, k]
        };
        let idx_t = self.tensor_variable(indices, out_shape.clone(), false)?;
        let dist_t = self.tensor_variable(distances, out_shape, false)?;
        Ok((idx_t, dist_t))
    }

    /// Group points by indices for PointNet++ set abstraction.
    ///
    /// Gathers point features according to index tensor.
    ///
    /// Args:
    /// - points: [N, C] or [B, N, C] point features
    /// - indices: [M, K] or [B, M, K] indices to gather
    ///
    /// Returns: [M, K, C] or [B, M, K, C] grouped features
    pub fn group_points(
        &mut self,
        points: TensorNodeId,
        indices: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let p_shape = self.tensor_shape(points)?;
        let i_shape = self.tensor_shape(indices)?;
        let (batch_size, n_points, c, m, k) = match (p_shape.len(), i_shape.len()) {
            (2, 2) => (1, p_shape[0], p_shape[1], i_shape[0], i_shape[1]),
            (3, 3) if p_shape[0] == i_shape[0] => {
                (p_shape[0], p_shape[1], p_shape[2], i_shape[1], i_shape[2])
            }
            _ => {
                return Err(Self::incompatible_tensor_args(
                    "group_points: shapes must be compatible",
                ));
            }
        };
        let p_data = self.tensor_values_lossy_f64(points)?;
        let i_data = self.tensor_values_lossy_f64(indices)?;
        let mut output = vec![0.0; batch_size * m * k * c];
        // Each (b, mi, ki) group copies a DISJOINT contiguous c-block (or leaves it 0
        // for an out-of-range index), so lay the output as [batch*m*k] chunks of c and
        // fill each in parallel. Bit-identical to the serial loops: a pure gather-copy
        // (order-independent), disjoint writes; only the outer iteration parallelizes.
        let mk = m * k;
        let fill = |chunk_idx: usize, slot: &mut [f64]| {
            let b = chunk_idx / mk;
            let rem = chunk_idx % mk;
            let mi = rem / k;
            let ki = rem % k;
            let idx = i_data[b * m * k + mi * k + ki] as i64;
            if idx >= 0 && (idx as usize) < n_points {
                let src = b * n_points * c + idx as usize * c;
                slot.copy_from_slice(&p_data[src..src + c]);
            }
        };
        if c > 0 && batch_size * m * k * c >= (1 << 14) {
            use rayon::prelude::*;
            output
                .par_chunks_mut(c)
                .enumerate()
                .for_each(|(chunk_idx, slot)| fill(chunk_idx, slot));
        } else if c > 0 {
            for (chunk_idx, slot) in output.chunks_mut(c).enumerate() {
                fill(chunk_idx, slot);
            }
        }
        let out_shape = if p_shape.len() == 2 {
            vec![m, k, c]
        } else {
            vec![batch_size, m, k, c]
        };
        let out = self.tensor_variable(output, out_shape, false)?;
        // group_points gathers point VALUES -> preserve the points dtype (f32 -> f32).
        match self.tensor_dtype(points)? {
            dt @ (DType::F32 | DType::F16 | DType::BF16) => self.tensor_to_dtype(out, dt),
            _ => Ok(out),
        }
    }

    // ── Image Augmentation Operations ──────────────────────────────────

    /// Cutout augmentation: randomly mask out square regions.
    ///
    /// Sets random square patches to zero. Improves model robustness
    /// by forcing reliance on multiple features.
    ///
    /// Args:
    /// - images: [B, C, H, W] input images
    /// - num_holes: number of patches to cut out
    /// - hole_size: size of each square hole
    pub fn cutout(
        &mut self,
        images: TensorNodeId,
        num_holes: usize,
        hole_size: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(images)?;
        if shape.len() != 4 {
            return Err(Self::incompatible_tensor_args(
                "cutout: images must be [B, C, H, W]",
            ));
        }
        let (b, c, h, w) = (shape[0], shape[1], shape[2], shape[3]);
        let mut data = self.tensor_values(images)?;
        for bi in 0..b {
            for _ in 0..num_holes {
                let cy = self.rng.next_u64() as usize % h;
                let cx = self.rng.next_u64() as usize % w;
                let y1 = cy.saturating_sub(hole_size / 2);
                let y2 = (cy + hole_size / 2 + 1).min(h);
                let x1 = cx.saturating_sub(hole_size / 2);
                let x2 = (cx + hole_size / 2 + 1).min(w);
                for ci in 0..c {
                    for yi in y1..y2 {
                        for xi in x1..x2 {
                            data[bi * c * h * w + ci * h * w + yi * w + xi] = 0.0;
                        }
                    }
                }
            }
        }
        self.tensor_variable(data, shape, false)
    }

    /// Random erasing augmentation.
    ///
    /// Like cutout but with random aspect ratio and fills with random values.
    ///
    /// Args:
    /// - images: [B, C, H, W] input images
    /// - p: probability of applying erasing
    /// - scale: (min, max) fraction of image area to erase
    /// - ratio: (min, max) aspect ratio of erased region
    pub fn random_erasing(
        &mut self,
        images: TensorNodeId,
        p: f64,
        scale: (f64, f64),
        ratio: (f64, f64),
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(images)?;
        if shape.len() != 4 {
            return Err(Self::incompatible_tensor_args(
                "random_erasing: images must be [B, C, H, W]",
            ));
        }
        let (b, c, h, w) = (shape[0], shape[1], shape[2], shape[3]);
        let area = (h * w) as f64;
        let mut data = self.tensor_values(images)?;
        for bi in 0..b {
            if self.rng.next_f64() >= p {
                continue;
            }
            for _ in 0..10 {
                let target_area = area * (scale.0 + self.rng.next_f64() * (scale.1 - scale.0));
                let aspect = ratio.0 * (ratio.1 / ratio.0).powf(self.rng.next_f64());
                let rh = (target_area / aspect).sqrt() as usize;
                let rw = (target_area * aspect).sqrt() as usize;
                if rh < h && rw < w {
                    let y = self.rng.next_u64() as usize % (h - rh);
                    let x = self.rng.next_u64() as usize % (w - rw);
                    for ci in 0..c {
                        for yi in y..y + rh {
                            for xi in x..x + rw {
                                data[bi * c * h * w + ci * h * w + yi * w + xi] =
                                    self.rng.next_f64();
                            }
                        }
                    }
                    break;
                }
            }
        }
        self.tensor_variable(data, shape, false)
    }

    /// Random crop and resize.
    ///
    /// Crops a random region and resizes to target size.
    /// Standard augmentation for image classification.
    ///
    /// Args:
    /// - images: [B, C, H, W] input images
    /// - output_size: (target_h, target_w)
    /// - scale: (min, max) fraction of area to crop
    /// - ratio: (min, max) aspect ratio of crop
    pub fn random_resized_crop(
        &mut self,
        images: TensorNodeId,
        output_size: (usize, usize),
        scale: (f64, f64),
        ratio: (f64, f64),
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(images)?;
        if shape.len() != 4 {
            return Err(Self::incompatible_tensor_args(
                "random_resized_crop: images must be [B, C, H, W]",
            ));
        }
        let (b, c, h, w) = (shape[0], shape[1], shape[2], shape[3]);
        let (out_h, out_w) = output_size;
        let area = (h * w) as f64;
        let data = self.tensor_values(images)?;
        let mut output = vec![0.0; b * c * out_h * out_w];
        for bi in 0..b {
            let (crop_y, crop_x, crop_h, crop_w) = {
                let mut found = None;
                for _ in 0..10 {
                    let target_area = area * (scale.0 + self.rng.next_f64() * (scale.1 - scale.0));
                    let aspect =
                        (ratio.0.ln() + self.rng.next_f64() * (ratio.1.ln() - ratio.0.ln())).exp();
                    let ch = (target_area / aspect).sqrt() as usize;
                    let cw = (target_area * aspect).sqrt() as usize;
                    if ch > 0 && cw > 0 && ch <= h && cw <= w {
                        let y = self.rng.next_u64() as usize % (h - ch + 1);
                        let x = self.rng.next_u64() as usize % (w - cw + 1);
                        found = Some((y, x, ch, cw));
                        break;
                    }
                }
                found.unwrap_or_else(|| {
                    let min_dim = h.min(w);
                    let offset_h = (h - min_dim) / 2;
                    let offset_w = (w - min_dim) / 2;
                    (offset_h, offset_w, min_dim, min_dim)
                })
            };
            for ci in 0..c {
                for oy in 0..out_h {
                    for ox in 0..out_w {
                        let sy = crop_y as f64 + (oy as f64 + 0.5) * crop_h as f64 / out_h as f64;
                        let sx = crop_x as f64 + (ox as f64 + 0.5) * crop_w as f64 / out_w as f64;
                        let iy = (sy as usize).min(h - 1);
                        let ix = (sx as usize).min(w - 1);
                        output[bi * c * out_h * out_w + ci * out_h * out_w + oy * out_w + ox] =
                            data[bi * c * h * w + ci * h * w + iy * w + ix];
                    }
                }
            }
        }
        self.tensor_variable(output, vec![b, c, out_h, out_w], false)
    }

    /// Color jitter augmentation.
    ///
    /// Randomly adjusts brightness, contrast, saturation, and hue.
    ///
    /// Args:
    /// - images: [B, C, H, W] RGB images (C must be 3)
    /// - brightness: max brightness adjustment factor
    /// - contrast: max contrast adjustment factor
    /// - saturation: max saturation adjustment factor
    /// - hue: max hue shift (fraction of full rotation)
    pub fn color_jitter(
        &mut self,
        images: TensorNodeId,
        brightness: f64,
        contrast: f64,
        saturation: f64,
        hue: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(images)?;
        if shape.len() != 4 || shape[1] != 3 {
            return Err(Self::incompatible_tensor_args(
                "color_jitter: images must be [B, 3, H, W]",
            ));
        }
        let (b, _, h, w) = (shape[0], shape[1], shape[2], shape[3]);
        let mut data = self.tensor_values(images)?;
        // Pre-draw the 4 per-image RNG factors serially (identical Xoshiro sequence to
        // the serial version, since the pixel transform draws no RNG), then apply the
        // per-pixel color transform to each image's [3,H,W] chunk in parallel. Bit-
        // identical: each pixel's math is unchanged, factors are drawn in the same
        // order, and image chunks are disjoint.
        let factors: Vec<[f64; 4]> = (0..b)
            .map(|_| {
                [
                    1.0 + (self.rng.next_f64() * 2.0 - 1.0) * brightness,
                    1.0 + (self.rng.next_f64() * 2.0 - 1.0) * contrast,
                    1.0 + (self.rng.next_f64() * 2.0 - 1.0) * saturation,
                    (self.rng.next_f64() * 2.0 - 1.0) * hue,
                ]
            })
            .collect();
        let hw = h * w;
        let apply_image = |bi: usize, img: &mut [f64]| {
            let [b_factor, c_factor, s_factor, h_shift] = factors[bi];
            for yi in 0..h {
                for xi in 0..w {
                    let idx_r = yi * w + xi;
                    let idx_g = hw + yi * w + xi;
                    let idx_b = 2 * hw + yi * w + xi;
                    let (mut r, mut g, mut b_val) = (img[idx_r], img[idx_g], img[idx_b]);
                    r *= b_factor;
                    g *= b_factor;
                    b_val *= b_factor;
                    let gray = 0.299 * r + 0.587 * g + 0.114 * b_val;
                    r = gray + (r - gray) * c_factor;
                    g = gray + (g - gray) * c_factor;
                    b_val = gray + (b_val - gray) * c_factor;
                    r = gray + (r - gray) * s_factor;
                    g = gray + (g - gray) * s_factor;
                    b_val = gray + (b_val - gray) * s_factor;
                    if h_shift.abs() > 1e-6 {
                        let max_c = r.max(g).max(b_val);
                        let min_c = r.min(g).min(b_val);
                        let chroma = max_c - min_c;
                        if chroma > 1e-6 {
                            let mut hue_angle = if (max_c - r).abs() < 1e-6 {
                                ((g - b_val) / chroma) % 6.0
                            } else if (max_c - g).abs() < 1e-6 {
                                (b_val - r) / chroma + 2.0
                            } else {
                                (r - g) / chroma + 4.0
                            };
                            hue_angle = (hue_angle + h_shift * 6.0) % 6.0;
                            if hue_angle < 0.0 {
                                hue_angle += 6.0;
                            }
                            let x = chroma * (1.0 - ((hue_angle % 2.0) - 1.0).abs());
                            let (r1, g1, b1) = match hue_angle as usize {
                                0 => (chroma, x, 0.0),
                                1 => (x, chroma, 0.0),
                                2 => (0.0, chroma, x),
                                3 => (0.0, x, chroma),
                                4 => (x, 0.0, chroma),
                                _ => (chroma, 0.0, x),
                            };
                            let m = min_c;
                            r = r1 + m;
                            g = g1 + m;
                            b_val = b1 + m;
                        }
                    }
                    img[idx_r] = r.clamp(0.0, 1.0);
                    img[idx_g] = g.clamp(0.0, 1.0);
                    img[idx_b] = b_val.clamp(0.0, 1.0);
                }
            }
        };
        if b >= 2 && data.len() >= (1 << 14) {
            use rayon::prelude::*;
            data.par_chunks_mut(3 * hw)
                .enumerate()
                .for_each(|(bi, img)| apply_image(bi, img));
        } else {
            for (bi, img) in data.chunks_mut(3 * hw).enumerate() {
                apply_image(bi, img);
            }
        }
        self.tensor_variable(data, shape, false)
    }

    // ── Time Series Operations ─────────────────────────────────────────

    /// Simple moving average over a sliding window.
    ///
    /// Args:
    /// - input: [..., seq_len] input tensor
    /// - window_size: size of the averaging window
    ///
    /// Returns: [..., seq_len] moving averages (first window_size-1 values use partial windows)
    pub fn moving_average(
        &mut self,
        input: TensorNodeId,
        window_size: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        if window_size == 0 {
            return Err(Self::incompatible_tensor_args(
                "moving_average: window_size must be > 0",
            ));
        }
        let shape = self.tensor_shape(input)?;
        if shape.is_empty() {
            return Err(Self::incompatible_tensor_args(
                "moving_average: input must be non-empty",
            ));
        }
        let seq_len = *shape.last().unwrap();
        let batch_size: usize = shape[..shape.len() - 1].iter().product();
        let data = self.tensor_values(input)?;
        let mut output = vec![0.0; data.len()];
        for bi in 0..batch_size {
            let mut window_sum = 0.0;
            for i in 0..seq_len {
                window_sum += data[bi * seq_len + i];
                if i >= window_size {
                    window_sum -= data[bi * seq_len + i - window_size];
                    output[bi * seq_len + i] = window_sum / window_size as f64;
                } else {
                    output[bi * seq_len + i] = window_sum / (i + 1) as f64;
                }
            }
        }
        self.tensor_variable(output, shape, false)
    }

    /// Exponential weighted moving average (EWMA).
    ///
    /// EWMA_t = alpha * x_t + (1 - alpha) * EWMA_{t-1}
    ///
    /// Args:
    /// - input: [..., seq_len] input tensor
    /// - alpha: smoothing factor in (0, 1]. Higher = more weight on recent values.
    pub fn ewma(&mut self, input: TensorNodeId, alpha: f64) -> Result<TensorNodeId, AutogradError> {
        if alpha <= 0.0 || alpha > 1.0 {
            return Err(Self::incompatible_tensor_args(
                "ewma: alpha must be in (0, 1]",
            ));
        }
        let shape = self.tensor_shape(input)?;
        if shape.is_empty() {
            return Err(Self::incompatible_tensor_args(
                "ewma: input must be non-empty",
            ));
        }
        let seq_len = *shape.last().unwrap();
        let batch_size: usize = shape[..shape.len() - 1].iter().product();
        let data = self.tensor_values(input)?;
        let mut output = vec![0.0; data.len()];
        for bi in 0..batch_size {
            let mut ewma_val = data[bi * seq_len];
            output[bi * seq_len] = ewma_val;
            for i in 1..seq_len {
                ewma_val = alpha * data[bi * seq_len + i] + (1.0 - alpha) * ewma_val;
                output[bi * seq_len + i] = ewma_val;
            }
        }
        self.tensor_variable(output, shape, false)
    }

    /// Lag features for time series.
    ///
    /// Creates lagged versions of the input for autoregressive modeling.
    ///
    /// Args:
    /// - input: [..., seq_len] input tensor
    /// - lags: list of lag values (e.g., [1, 7, 30] for day, week, month)
    ///
    /// Returns: [..., seq_len, num_lags] tensor with lagged values (padded with 0)
    pub fn lag_features(
        &mut self,
        input: TensorNodeId,
        lags: &[usize],
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        if shape.is_empty() || lags.is_empty() {
            return Err(Self::incompatible_tensor_args(
                "lag_features: invalid input",
            ));
        }
        let seq_len = *shape.last().unwrap();
        let batch_size: usize = shape[..shape.len() - 1].iter().product();
        let num_lags = lags.len();
        let data = self.tensor_values(input)?;
        let mut output = vec![0.0; batch_size * seq_len * num_lags];
        for bi in 0..batch_size {
            for i in 0..seq_len {
                for (li, &lag) in lags.iter().enumerate() {
                    if i >= lag {
                        output[bi * seq_len * num_lags + i * num_lags + li] =
                            data[bi * seq_len + i - lag];
                    }
                }
            }
        }
        let mut out_shape = shape.clone();
        out_shape.push(num_lags);
        self.tensor_variable(output, out_shape, false)
    }

    /// Rolling statistics (min, max, mean, std) over a window.
    ///
    /// Args:
    /// - input: [..., seq_len] input tensor
    /// - window_size: size of the rolling window
    ///
    /// Returns: [..., seq_len, 4] tensor with (min, max, mean, std) per position
    pub fn rolling_stats(
        &mut self,
        input: TensorNodeId,
        window_size: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        if window_size == 0 {
            return Err(Self::incompatible_tensor_args(
                "rolling_stats: window_size must be > 0",
            ));
        }
        let shape = self.tensor_shape(input)?;
        if shape.is_empty() {
            return Err(Self::incompatible_tensor_args(
                "rolling_stats: input must be non-empty",
            ));
        }
        let seq_len = *shape.last().unwrap();
        let batch_size: usize = shape[..shape.len() - 1].iter().product();
        let data = self.tensor_values(input)?;
        let mut output = vec![0.0; batch_size * seq_len * 4];
        for bi in 0..batch_size {
            for i in 0..seq_len {
                let start = i.saturating_sub(window_size - 1);
                let window: Vec<f64> = (start..=i).map(|j| data[bi * seq_len + j]).collect();
                let n = window.len() as f64;
                let min_v = window.iter().cloned().fold(f64::INFINITY, f64::min);
                let max_v = window.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
                let mean_v = window.iter().sum::<f64>() / n;
                let var_v = window.iter().map(|&x| (x - mean_v).powi(2)).sum::<f64>() / n;
                let std_v = var_v.sqrt();
                let base = bi * seq_len * 4 + i * 4;
                output[base] = min_v;
                output[base + 1] = max_v;
                output[base + 2] = mean_v;
                output[base + 3] = std_v;
            }
        }
        let mut out_shape = shape.clone();
        out_shape.push(4);
        self.tensor_variable(output, out_shape, false)
    }

    /// Seasonal decomposition (additive model).
    ///
    /// Decomposes time series into trend, seasonal, and residual components.
    /// Uses simple moving average for trend extraction.
    ///
    /// Args:
    /// - input: [seq_len] 1D time series
    /// - period: seasonal period (e.g., 7 for weekly, 12 for monthly)
    ///
    /// Returns: (trend, seasonal, residual) each of shape [seq_len]
    pub fn seasonal_decompose(
        &mut self,
        input: TensorNodeId,
        period: usize,
    ) -> Result<(TensorNodeId, TensorNodeId, TensorNodeId), AutogradError> {
        let shape = self.tensor_shape(input)?;
        if shape.len() != 1 {
            return Err(Self::incompatible_tensor_args(
                "seasonal_decompose: input must be 1D [seq_len]",
            ));
        }
        let seq_len = shape[0];
        if period == 0 || period > seq_len {
            return Err(Self::incompatible_tensor_args(
                "seasonal_decompose: invalid period",
            ));
        }
        let data = self.tensor_values(input)?;
        let mut trend = vec![0.0; seq_len];
        let half = period / 2;
        for i in half..(seq_len - half) {
            let window: f64 = (i - half..i + half + period % 2).map(|j| data[j]).sum();
            trend[i] = window / period as f64;
        }
        for i in 0..half {
            trend[i] = trend[half];
        }
        for i in (seq_len - half)..seq_len {
            trend[i] = trend[seq_len - half - 1];
        }
        let detrended: Vec<f64> = data.iter().zip(trend.iter()).map(|(d, t)| d - t).collect();
        let mut seasonal_pattern = vec![0.0; period];
        let mut counts = vec![0; period];
        for (i, &val) in detrended.iter().enumerate() {
            seasonal_pattern[i % period] += val;
            counts[i % period] += 1;
        }
        for i in 0..period {
            if counts[i] > 0 {
                seasonal_pattern[i] /= counts[i] as f64;
            }
        }
        let pattern_mean: f64 = seasonal_pattern.iter().sum::<f64>() / period as f64;
        for v in &mut seasonal_pattern {
            *v -= pattern_mean;
        }
        let seasonal: Vec<f64> = (0..seq_len).map(|i| seasonal_pattern[i % period]).collect();
        let residual: Vec<f64> = data
            .iter()
            .zip(trend.iter())
            .zip(seasonal.iter())
            .map(|((d, t), s)| d - t - s)
            .collect();
        let trend_t = self.tensor_variable(trend, vec![seq_len], false)?;
        let seasonal_t = self.tensor_variable(seasonal, vec![seq_len], false)?;
        let residual_t = self.tensor_variable(residual, vec![seq_len], false)?;
        Ok((trend_t, seasonal_t, residual_t))
    }

    // ── Graph Neural Network Operations ────────────────────────────────

    /// Scatter mean aggregation for GNN message passing.
    ///
    /// Aggregates source node features to destination nodes using mean.
    /// Used in GCN, GraphSAGE, etc.
    ///
    /// Args:
    /// - src: [E, D] source features (one per edge)
    /// - index: [E] destination node indices
    /// - num_nodes: total number of nodes
    ///
    /// Returns: [num_nodes, D] aggregated features
    pub fn scatter_mean(
        &mut self,
        src: TensorNodeId,
        index: TensorNodeId,
        num_nodes: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let src_shape = self.tensor_shape(src)?;
        let idx_shape = self.tensor_shape(index)?;
        if src_shape.len() != 2 || idx_shape.len() != 1 || src_shape[0] != idx_shape[0] {
            return Err(Self::incompatible_tensor_args(
                "scatter_mean: src must be [E, D], index must be [E]",
            ));
        }
        let (e, d) = (src_shape[0], src_shape[1]);
        let src_data = self.tensor_values_lossy_f64(src)?;
        let idx_data = self.tensor_values_lossy_f64(index)?;
        let mut output = vec![0.0; num_nodes * d];
        let mut counts = vec![0usize; num_nodes];
        for ei in 0..e {
            let dst = idx_data[ei] as usize;
            if dst < num_nodes {
                counts[dst] += 1;
                for di in 0..d {
                    output[dst * d + di] += src_data[ei * d + di];
                }
            }
        }
        for ni in 0..num_nodes {
            if counts[ni] > 0 {
                for di in 0..d {
                    output[ni * d + di] /= counts[ni] as f64;
                }
            }
        }
        let out = self.tensor_variable(output, vec![num_nodes, d], false)?;
        // Preserve src dtype (torch_geometric scatter(f32) -> f32); the f64 accumulator is
        // narrowed back. Reads above use lossy_f64 so f32 src no longer crashes. frankentorch-fk5l.
        match self.tensor_dtype(src)? {
            dt @ (DType::F32 | DType::F16 | DType::BF16) => self.tensor_tape.to_dtype(out, dt),
            _ => Ok(out),
        }
    }

    /// Scatter max aggregation for GNN message passing.
    ///
    /// Takes maximum of incoming messages per node.
    /// Used in PointNet, DGCNN, etc.
    pub fn scatter_max(
        &mut self,
        src: TensorNodeId,
        index: TensorNodeId,
        num_nodes: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let src_shape = self.tensor_shape(src)?;
        let idx_shape = self.tensor_shape(index)?;
        if src_shape.len() != 2 || idx_shape.len() != 1 || src_shape[0] != idx_shape[0] {
            return Err(Self::incompatible_tensor_args(
                "scatter_max: src must be [E, D], index must be [E]",
            ));
        }
        let (e, d) = (src_shape[0], src_shape[1]);
        let src_data = self.tensor_values_lossy_f64(src)?;
        let idx_data = self.tensor_values_lossy_f64(index)?;
        let mut output = vec![f64::NEG_INFINITY; num_nodes * d];
        for ei in 0..e {
            let dst = idx_data[ei] as usize;
            if dst < num_nodes {
                for di in 0..d {
                    output[dst * d + di] = output[dst * d + di].max(src_data[ei * d + di]);
                }
            }
        }
        for v in &mut output {
            if v.is_infinite() {
                *v = 0.0;
            }
        }
        let out = self.tensor_variable(output, vec![num_nodes, d], false)?;
        // Preserve src dtype (torch_geometric scatter(f32) -> f32); the f64 accumulator is
        // narrowed back. Reads above use lossy_f64 so f32 src no longer crashes. frankentorch-fk5l.
        match self.tensor_dtype(src)? {
            dt @ (DType::F32 | DType::F16 | DType::BF16) => self.tensor_tape.to_dtype(out, dt),
            _ => Ok(out),
        }
    }

    /// Scatter sum aggregation for GNN message passing.
    pub fn scatter_sum(
        &mut self,
        src: TensorNodeId,
        index: TensorNodeId,
        num_nodes: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let src_shape = self.tensor_shape(src)?;
        let idx_shape = self.tensor_shape(index)?;
        if src_shape.len() != 2 || idx_shape.len() != 1 || src_shape[0] != idx_shape[0] {
            return Err(Self::incompatible_tensor_args(
                "scatter_sum: src must be [E, D], index must be [E]",
            ));
        }
        let (e, d) = (src_shape[0], src_shape[1]);
        let src_data = self.tensor_values_lossy_f64(src)?;
        let idx_data = self.tensor_values_lossy_f64(index)?;
        let mut output = vec![0.0; num_nodes * d];
        for ei in 0..e {
            let dst = idx_data[ei] as usize;
            if dst < num_nodes {
                for di in 0..d {
                    output[dst * d + di] += src_data[ei * d + di];
                }
            }
        }
        let out = self.tensor_variable(output, vec![num_nodes, d], false)?;
        // Preserve src dtype (torch_geometric scatter(f32) -> f32); the f64 accumulator is
        // narrowed back. Reads above use lossy_f64 so f32 src no longer crashes. frankentorch-fk5l.
        match self.tensor_dtype(src)? {
            dt @ (DType::F32 | DType::F16 | DType::BF16) => self.tensor_tape.to_dtype(out, dt),
            _ => Ok(out),
        }
    }

    /// Edge index to adjacency matrix conversion.
    ///
    /// Converts sparse edge list [2, E] to dense adjacency matrix [N, N].
    pub fn edge_index_to_adj(
        &mut self,
        edge_index: TensorNodeId,
        num_nodes: usize,
        add_self_loops: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(edge_index)?;
        if shape.len() != 2 || shape[0] != 2 {
            return Err(Self::incompatible_tensor_args(
                "edge_index_to_adj: edge_index must be [2, E]",
            ));
        }
        let e = shape[1];
        let data = self.tensor_values(edge_index)?;
        let mut adj = vec![0.0; num_nodes * num_nodes];
        for ei in 0..e {
            let src = data[ei] as usize;
            let dst = data[e + ei] as usize;
            if src < num_nodes && dst < num_nodes {
                adj[src * num_nodes + dst] = 1.0;
            }
        }
        if add_self_loops {
            for i in 0..num_nodes {
                adj[i * num_nodes + i] = 1.0;
            }
        }
        self.tensor_variable(adj, vec![num_nodes, num_nodes], false)
    }

    /// Add self-loops to edge index.
    ///
    /// Appends (i, i) edges for all nodes.
    pub fn add_self_loops(
        &mut self,
        edge_index: TensorNodeId,
        num_nodes: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(edge_index)?;
        if shape.len() != 2 || shape[0] != 2 {
            return Err(Self::incompatible_tensor_args(
                "add_self_loops: edge_index must be [2, E]",
            ));
        }
        let e = shape[1];
        let data = self.tensor_values(edge_index)?;
        let mut new_edges = Vec::with_capacity(2 * (e + num_nodes));
        for i in 0..e {
            new_edges.push(data[i]);
        }
        for i in 0..num_nodes {
            new_edges.push(i as f64);
        }
        for i in 0..e {
            new_edges.push(data[e + i]);
        }
        for i in 0..num_nodes {
            new_edges.push(i as f64);
        }
        self.tensor_variable(new_edges, vec![2, e + num_nodes], false)
    }

    /// Compute node degrees from edge index.
    ///
    /// Args:
    /// - edge_index: [2, E] edge list
    /// - num_nodes: total number of nodes
    /// - direction: "in" (in-degree), "out" (out-degree), or "both" (total)
    pub fn degree(
        &mut self,
        edge_index: TensorNodeId,
        num_nodes: usize,
        direction: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(edge_index)?;
        if shape.len() != 2 || shape[0] != 2 {
            return Err(Self::incompatible_tensor_args(
                "degree: edge_index must be [2, E]",
            ));
        }
        let e = shape[1];
        let data = self.tensor_values(edge_index)?;
        let mut degrees = vec![0.0; num_nodes];
        match direction {
            "out" => {
                for i in 0..e {
                    let src = data[i] as usize;
                    if src < num_nodes {
                        degrees[src] += 1.0;
                    }
                }
            }
            "in" => {
                for i in 0..e {
                    let dst = data[e + i] as usize;
                    if dst < num_nodes {
                        degrees[dst] += 1.0;
                    }
                }
            }
            "both" | _ => {
                for i in 0..e {
                    let src = data[i] as usize;
                    let dst = data[e + i] as usize;
                    if src < num_nodes {
                        degrees[src] += 1.0;
                    }
                    if dst < num_nodes {
                        degrees[dst] += 1.0;
                    }
                }
            }
        }
        self.tensor_variable(degrees, vec![num_nodes], false)
    }

    // ── Gradient Checking Utilities ────────────────────────────────────

    /// Compute numerical gradient using finite differences.
    ///
    /// For debugging autograd implementations. Uses central difference:
    /// grad ~= (f(x+eps) - f(x-eps)) / (2*eps)
    ///
    /// Args:
    /// - input: input tensor
    /// - idx: linear index of element to perturb
    /// - eps: perturbation size (default 1e-5)
    /// - loss_fn: returns scalar output given perturbed input
    ///
    /// Returns: numerical gradient at specified index
    pub fn numerical_gradient<F>(
        &mut self,
        input: TensorNodeId,
        idx: usize,
        eps: f64,
        loss_fn: F,
    ) -> Result<f64, AutogradError>
    where
        F: Fn(&mut Self, TensorNodeId) -> Result<f64, AutogradError>,
    {
        let data = self.tensor_values(input)?;
        let shape = self.tensor_shape(input)?;
        if idx >= data.len() {
            return Err(Self::incompatible_tensor_args(
                "numerical_gradient: idx out of bounds",
            ));
        }
        let mut data_plus = data.clone();
        data_plus[idx] += eps;
        let input_plus = self.tensor_variable(data_plus, shape.clone(), false)?;
        let loss_plus = loss_fn(self, input_plus)?;
        let mut data_minus = data;
        data_minus[idx] -= eps;
        let input_minus = self.tensor_variable(data_minus, shape, false)?;
        let loss_minus = loss_fn(self, input_minus)?;
        Ok((loss_plus - loss_minus) / (2.0 * eps))
    }

    /// Check if two gradient vectors are approximately equal.
    ///
    /// Returns maximum absolute and relative errors between gradients.
    pub fn gradient_check_stats(analytical: &[f64], numerical: &[f64]) -> (f64, f64) {
        let mut max_abs_err = 0.0_f64;
        let mut max_rel_err = 0.0_f64;
        for (&a, &n) in analytical.iter().zip(numerical.iter()) {
            let abs_err = (a - n).abs();
            let rel_err = abs_err / (a.abs().max(n.abs()).max(1e-8));
            max_abs_err = max_abs_err.max(abs_err);
            max_rel_err = max_rel_err.max(rel_err);
        }
        (max_abs_err, max_rel_err)
    }

    /// Print tensor statistics for debugging.
    ///
    /// Returns: (min, max, mean, std, num_nan, num_inf)
    pub fn tensor_stats(
        &self,
        node: TensorNodeId,
    ) -> Result<(f64, f64, f64, f64, usize, usize), AutogradError> {
        let data = self.tensor_values(node)?;
        if data.is_empty() {
            return Ok((f64::NAN, f64::NAN, f64::NAN, f64::NAN, 0, 0));
        }
        let mut min = f64::INFINITY;
        let mut max = f64::NEG_INFINITY;
        let mut sum = 0.0;
        let mut num_nan = 0;
        let mut num_inf = 0;
        for &v in &data {
            if v.is_nan() {
                num_nan += 1;
            } else if v.is_infinite() {
                num_inf += 1;
            } else {
                min = min.min(v);
                max = max.max(v);
                sum += v;
            }
        }
        let n_valid = data.len() - num_nan - num_inf;
        let mean = if n_valid > 0 {
            sum / n_valid as f64
        } else {
            f64::NAN
        };
        let var: f64 = data
            .iter()
            .filter(|v| !v.is_nan() && !v.is_infinite())
            .map(|&v| (v - mean).powi(2))
            .sum::<f64>()
            / n_valid.max(1) as f64;
        let std = var.sqrt();
        Ok((min, max, mean, std, num_nan, num_inf))
    }

    /// Detect gradient anomalies (NaN, Inf, extreme values).
    ///
    /// Useful for debugging training instabilities.
    pub fn detect_gradient_anomaly(
        &self,
        params: &[TensorNodeId],
        threshold: f64,
    ) -> Result<Vec<(TensorNodeId, String)>, AutogradError> {
        let mut anomalies = Vec::new();
        for &p in params {
            if let Some(grad) = self.tensor_accumulated_gradient(p)? {
                let mut has_nan = false;
                let mut has_inf = false;
                let mut max_abs = 0.0_f64;
                for &g in &grad {
                    if g.is_nan() {
                        has_nan = true;
                    } else if g.is_infinite() {
                        has_inf = true;
                    } else {
                        max_abs = max_abs.max(g.abs());
                    }
                }
                if has_nan {
                    anomalies.push((p, "NaN gradient".to_string()));
                } else if has_inf {
                    anomalies.push((p, "Inf gradient".to_string()));
                } else if max_abs > threshold {
                    anomalies.push((p, format!("Large gradient: {:.2e}", max_abs)));
                }
            }
        }
        Ok(anomalies)
    }

    // ── Landmark Detection Losses ──────────────────────────────────────

    /// Wing loss for facial landmark detection.
    ///
    /// Behaves like log loss for small errors and linear for large errors.
    /// wing(x) = w * ln(1 + |x|/eps) if |x| < w, else |x| - C
    /// where C = w - w * ln(1 + w/eps)
    ///
    /// Args:
    /// - pred: predicted coordinates
    /// - target: ground truth coordinates
    /// - w: threshold where loss transitions from log to linear
    /// - eps: controls curvature of log region
    pub fn wing_loss(
        &mut self,
        pred: TensorNodeId,
        target: TensorNodeId,
        w: f64,
        eps: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let pred_shape = self.tensor_shape(pred)?;
        let target_shape = self.tensor_shape(target)?;
        if pred_shape != target_shape {
            return Err(Self::incompatible_tensor_args(
                "wing_loss: shapes must match",
            ));
        }
        let pred_data = self.tensor_values(pred)?;
        let target_data = self.tensor_values_lossy_f64(target)?;
        let c = w - w * (1.0 + w / eps).ln();
        let loss: Vec<f64> = pred_data
            .iter()
            .zip(target_data.iter())
            .map(|(&p, &t)| {
                let diff = (p - t).abs();
                if diff < w {
                    w * (1.0 + diff / eps).ln()
                } else {
                    diff - c
                }
            })
            .collect();
        let loss_t = self.tensor_variable(loss, pred_shape, false)?;
        self.tensor_mean(loss_t)
    }

    /// Adaptive Wing loss for robust facial landmark detection.
    ///
    /// Addresses limitations of Wing loss by using adaptive parameter
    /// based on the ground truth position.
    ///
    /// Args:
    /// - pred: predicted landmarks [N, num_landmarks, 2]
    /// - target: ground truth landmarks [N, num_landmarks, 2]
    /// - omega, theta, eps, alpha: loss parameters
    pub fn adaptive_wing_loss(
        &mut self,
        pred: TensorNodeId,
        target: TensorNodeId,
        omega: f64,
        theta: f64,
        eps: f64,
        alpha: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let pred_shape = self.tensor_shape(pred)?;
        let target_shape = self.tensor_shape(target)?;
        if pred_shape != target_shape {
            return Err(Self::incompatible_tensor_args(
                "adaptive_wing_loss: shapes must match",
            ));
        }
        let pred_data = self.tensor_values(pred)?;
        let target_data = self.tensor_values_lossy_f64(target)?;
        let a = omega * (1.0 / (1.0 + (theta / eps).powf(alpha - target_data[0])));
        let c = theta * a - omega * ((1.0 + (theta / eps).powf(alpha - target_data[0])).ln());
        let loss: Vec<f64> = pred_data
            .iter()
            .zip(target_data.iter())
            .map(|(&p, &t)| {
                let diff = (p - t).abs();
                if diff < theta {
                    omega * ((1.0 + (diff / eps).powf(alpha - t)).ln())
                } else {
                    a * diff - c
                }
            })
            .collect();
        let loss_t = self.tensor_variable(loss, pred_shape, false)?;
        self.tensor_mean(loss_t)
    }

    /// Weighted mean squared error for heatmap-based landmark detection.
    ///
    /// Commonly used in stacked hourglass networks.
    /// Applies higher weight to pixels near the ground truth position.
    pub fn heatmap_mse_loss(
        &mut self,
        pred_heatmap: TensorNodeId,
        target_heatmap: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let diff = self.tensor_sub(pred_heatmap, target_heatmap)?;
        let sq_diff = self.tensor_mul(diff, diff)?;
        self.tensor_mean(sq_diff)
    }

    /// Ordinal regression loss for depth/age estimation.
    ///
    /// Converts regression to classification of ordinal ranks.
    /// loss = sum_k BCE(pred_k, [k <= target])
    ///
    /// Args:
    /// - pred: [N, K] logits for K ordinal ranks
    /// - target: [N] integer target values in [0, K]
    pub fn ordinal_regression_loss(
        &mut self,
        pred: TensorNodeId,
        target: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let pred_shape = self.tensor_shape(pred)?;
        let target_shape = self.tensor_shape(target)?;
        if pred_shape.len() != 2 || target_shape.len() != 1 {
            return Err(Self::incompatible_tensor_args(
                "ordinal_regression_loss: pred must be [N, K], target must be [N]",
            ));
        }
        let (n, k) = (pred_shape[0], pred_shape[1]);
        if target_shape[0] != n {
            return Err(Self::incompatible_tensor_args(
                "ordinal_regression_loss: batch sizes must match",
            ));
        }
        let pred_data = self.tensor_values(pred)?;
        let target_data = self.tensor_values_lossy_f64(target)?;
        let mut total_loss = 0.0;
        for i in 0..n {
            let t = target_data[i] as usize;
            for j in 0..k {
                let p = 1.0 / (1.0 + (-pred_data[i * k + j]).exp());
                let y = if j < t { 1.0 } else { 0.0 };
                let bce = -y * p.max(1e-10).ln() - (1.0 - y) * (1.0 - p).max(1e-10).ln();
                total_loss += bce;
            }
        }
        self.tensor_variable(vec![total_loss / (n * k) as f64], vec![1], false)
    }

    // ── Feature Engineering Operations ─────────────────────────────────

    /// Generate polynomial features up to degree d.
    ///
    /// For input [x1, x2], degree 2: [1, x1, x2, x1^2, x1*x2, x2^2]
    ///
    /// Args:
    /// - x: [N, D] input features
    /// - degree: maximum polynomial degree
    /// - include_bias: whether to include the bias (1) term
    ///
    /// Returns: [N, num_features] polynomial features
    pub fn polynomial_features(
        &mut self,
        x: TensorNodeId,
        degree: usize,
        include_bias: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(x)?;
        if shape.len() != 2 {
            return Err(Self::incompatible_tensor_args(
                "polynomial_features: x must be [N, D]",
            ));
        }
        let (n, d) = (shape[0], shape[1]);
        let data = self.tensor_values(x)?;
        let mut features: Vec<Vec<f64>> = vec![vec![]; n];
        for i in 0..n {
            if include_bias {
                features[i].push(1.0);
            }
        }
        for deg in 1..=degree {
            let combos = Self::polynomial_combinations(d, deg);
            for combo in combos {
                for i in 0..n {
                    let mut val = 1.0_f64;
                    for &j in &combo {
                        val *= data[i * d + j];
                    }
                    features[i].push(val);
                }
            }
        }
        let num_features = features[0].len();
        let output: Vec<f64> = features.into_iter().flatten().collect();
        self.tensor_variable(output, vec![n, num_features], false)
    }

    fn polynomial_combinations(d: usize, degree: usize) -> Vec<Vec<usize>> {
        let mut result = Vec::new();
        let mut combo = vec![0; degree];
        Self::poly_combo_helper(d, degree, 0, 0, &mut combo, &mut result);
        result
    }

    fn poly_combo_helper(
        d: usize,
        degree: usize,
        start: usize,
        pos: usize,
        combo: &mut [usize],
        result: &mut Vec<Vec<usize>>,
    ) {
        if pos == degree {
            result.push(combo.to_vec());
            return;
        }
        for i in start..d {
            combo[pos] = i;
            Self::poly_combo_helper(d, degree, i, pos + 1, combo, result);
        }
    }

    /// Generate interaction features between columns.
    ///
    /// Creates pairwise products of all feature columns.
    ///
    /// Args:
    /// - x: [N, D] input features
    /// - include_self: whether to include x_i * x_i terms
    ///
    /// Returns: [N, D*(D-1)/2 or D*(D+1)/2] interaction features
    pub fn interaction_features(
        &mut self,
        x: TensorNodeId,
        include_self: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(x)?;
        if shape.len() != 2 {
            return Err(Self::incompatible_tensor_args(
                "interaction_features: x must be [N, D]",
            ));
        }
        let (n, d) = (shape[0], shape[1]);
        let data = self.tensor_values(x)?;
        let num_features = if include_self {
            d * (d + 1) / 2
        } else {
            d * (d - 1) / 2
        };
        let mut output = Vec::with_capacity(n * num_features);
        for i in 0..n {
            for j in 0..d {
                let start = if include_self { j } else { j + 1 };
                for k in start..d {
                    output.push(data[i * d + j] * data[i * d + k]);
                }
            }
        }
        self.tensor_variable(output, vec![n, num_features], false)
    }

    /// Bucketize continuous features into bins.
    ///
    /// Args:
    /// - x: [N, D] input features
    /// - boundaries: [B] bin boundaries (sorted)
    ///
    /// Returns: [N, D] indices of bins each value falls into
    pub fn bucketize_features(
        &mut self,
        x: TensorNodeId,
        boundaries: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let x_shape = self.tensor_shape(x)?;
        let b_shape = self.tensor_shape(boundaries)?;
        if b_shape.len() != 1 {
            return Err(Self::incompatible_tensor_args(
                "bucketize: boundaries must be 1D",
            ));
        }
        let data = self.tensor_values(x)?;
        let bounds = self.tensor_values(boundaries)?;
        let output: Vec<f64> = data
            .iter()
            .map(|&v| bounds.iter().filter(|&&b| v >= b).count() as f64)
            .collect();
        self.tensor_variable(output, x_shape, false)
    }

    /// Target encoding for categorical features.
    ///
    /// Encodes categories by mean of target variable.
    /// With smoothing: (n_cat * mean_cat + m * global_mean) / (n_cat + m)
    ///
    /// Args:
    /// - categories: [N] integer category indices
    /// - targets: [N] target values
    /// - num_categories: number of unique categories
    /// - smoothing: smoothing parameter m
    pub fn target_encode(
        &mut self,
        categories: TensorNodeId,
        targets: TensorNodeId,
        num_categories: usize,
        smoothing: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let cat_shape = self.tensor_shape(categories)?;
        let tgt_shape = self.tensor_shape(targets)?;
        if cat_shape != tgt_shape || cat_shape.len() != 1 {
            return Err(Self::incompatible_tensor_args(
                "target_encode: mismatched shapes",
            ));
        }
        let n = cat_shape[0];
        let cat_data = self.tensor_values(categories)?;
        let tgt_data = self.tensor_values(targets)?;
        let global_mean: f64 = tgt_data.iter().sum::<f64>() / n as f64;
        let mut cat_sums = vec![0.0; num_categories];
        let mut cat_counts = vec![0usize; num_categories];
        for i in 0..n {
            let c = cat_data[i] as usize;
            if c < num_categories {
                cat_sums[c] += tgt_data[i];
                cat_counts[c] += 1;
            }
        }
        let output: Vec<f64> = cat_data
            .iter()
            .map(|&c| {
                let ci = c as usize;
                if ci >= num_categories {
                    return global_mean;
                }
                let nc = cat_counts[ci] as f64;
                let mean_c = if nc > 0.0 {
                    cat_sums[ci] / nc
                } else {
                    global_mean
                };
                (nc * mean_c + smoothing * global_mean) / (nc + smoothing)
            })
            .collect();
        self.tensor_variable(output, cat_shape, false)
    }

    // ── Attention Modules ──────────────────────────────────────────────

    /// Squeeze-and-Excitation (SE) channel attention.
    ///
    /// Recalibrates channel-wise feature responses.
    /// SE(x) = x * sigmoid(fc2(relu(fc1(gap(x)))))
    ///
    /// Args:
    /// - x: [N, C, H, W] input features
    /// - reduction: channel reduction ratio (typically 16)
    /// - fc1_weight, fc1_bias: first FC layer [C/r, C]
    /// - fc2_weight, fc2_bias: second FC layer [C, C/r]
    #[allow(clippy::too_many_arguments)]
    pub fn squeeze_excitation(
        &mut self,
        x: TensorNodeId,
        fc1_weight: TensorNodeId,
        fc1_bias: Option<TensorNodeId>,
        fc2_weight: TensorNodeId,
        fc2_bias: Option<TensorNodeId>,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(x)?;
        if shape.len() != 4 {
            return Err(Self::incompatible_tensor_args(
                "squeeze_excitation: x must be [N, C, H, W]",
            ));
        }
        let (n, c, _h, _w) = (shape[0], shape[1], shape[2], shape[3]);
        let gap = self.tensor_adaptive_avg_pool2d(x, (1, 1))?;
        let gap_flat = self.tensor_reshape(gap, vec![n, c])?;
        let fc1_out = self.tensor_linear(gap_flat, fc1_weight, fc1_bias)?;
        let relu_out = self.tensor_relu(fc1_out)?;
        let fc2_out = self.tensor_linear(relu_out, fc2_weight, fc2_bias)?;
        let scale = self.tensor_sigmoid(fc2_out)?;
        let scale_4d = self.tensor_reshape(scale, vec![n, c, 1, 1])?;
        self.tensor_mul(x, scale_4d)
    }

    /// Channel attention module (from CBAM).
    ///
    /// Combines max and average pooling for channel attention.
    /// CA(x) = sigmoid(MLP(MaxPool(x)) + MLP(AvgPool(x)))
    #[allow(clippy::too_many_arguments)]
    pub fn channel_attention(
        &mut self,
        x: TensorNodeId,
        fc1_weight: TensorNodeId,
        fc2_weight: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(x)?;
        if shape.len() != 4 {
            return Err(Self::incompatible_tensor_args(
                "channel_attention: x must be [N, C, H, W]",
            ));
        }
        let (n, c, _, _) = (shape[0], shape[1], shape[2], shape[3]);
        let avg_pool = self.tensor_adaptive_avg_pool2d(x, (1, 1))?;
        let (max_pool, _) = self.tensor_adaptive_max_pool2d(x, (1, 1))?;
        let avg_flat = self.tensor_reshape(avg_pool, vec![n, c])?;
        let max_flat = self.tensor_reshape(max_pool, vec![n, c])?;
        let avg_fc1 = self.tensor_linear(avg_flat, fc1_weight, None)?;
        let avg_relu = self.tensor_relu(avg_fc1)?;
        let avg_fc2 = self.tensor_linear(avg_relu, fc2_weight, None)?;
        let max_fc1 = self.tensor_linear(max_flat, fc1_weight, None)?;
        let max_relu = self.tensor_relu(max_fc1)?;
        let max_fc2 = self.tensor_linear(max_relu, fc2_weight, None)?;
        let combined = self.tensor_add(avg_fc2, max_fc2)?;
        let scale = self.tensor_sigmoid(combined)?;
        let scale_4d = self.tensor_reshape(scale, vec![n, c, 1, 1])?;
        self.tensor_mul(x, scale_4d)
    }

    /// Spatial attention module (from CBAM).
    ///
    /// Attends to important spatial locations.
    /// SA(x) = sigmoid(conv(concat(MaxPool(x, dim=1), AvgPool(x, dim=1))))
    pub fn spatial_attention(
        &mut self,
        x: TensorNodeId,
        conv_weight: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(x)?;
        if shape.len() != 4 {
            return Err(Self::incompatible_tensor_args(
                "spatial_attention: x must be [N, C, H, W]",
            ));
        }
        let (n, _, h, w) = (shape[0], shape[1], shape[2], shape[3]);
        let avg_map = self.tensor_mean_dim(x, 1)?;
        let (max_map, _) = self.tensor_max_dim(x, 1)?;
        let avg_map_4d = self.tensor_reshape(avg_map, vec![n, 1, h, w])?;
        let max_map_4d = self.tensor_reshape(max_map, vec![n, 1, h, w])?;
        let concat = self.tensor_cat(&[avg_map_4d, max_map_4d], 1)?;
        let conv_out = self.tensor_conv2d(concat, conv_weight, None, (1, 1), (3, 3))?;
        let scale = self.tensor_sigmoid(conv_out)?;
        self.tensor_mul(x, scale)
    }

    /// Efficient Channel Attention (ECA) module.
    ///
    /// Uses 1D convolution instead of FC layers for efficiency.
    /// ECA(x) = x * sigmoid(conv1d(gap(x)))
    pub fn efficient_channel_attention(
        &mut self,
        x: TensorNodeId,
        conv_weight: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(x)?;
        if shape.len() != 4 {
            return Err(Self::incompatible_tensor_args(
                "efficient_channel_attention: x must be [N, C, H, W]",
            ));
        }
        let (n, c, _, _) = (shape[0], shape[1], shape[2], shape[3]);
        let gap = self.tensor_adaptive_avg_pool2d(x, (1, 1))?;
        let gap_squeezed = self.tensor_reshape(gap, vec![n, 1, c])?;
        let conv_out = self.tensor_conv1d(gap_squeezed, conv_weight, None, 1, 0)?;
        let scale = self.tensor_sigmoid(conv_out)?;
        let scale_4d = self.tensor_reshape(scale, vec![n, c, 1, 1])?;
        self.tensor_mul(x, scale_4d)
    }

    /// ArcFace (Additive Angular Margin) loss for face recognition.
    ///
    /// Given L2-normalized features [N, D] and L2-normalized weight [C, D],
    /// computes cosine similarity then applies angular margin penalty
    /// cos(arccos(cos_theta_y) + m) for target class. Commonly used in
    /// face verification/identification.
    ///
    /// Args:
    /// - features: L2-normalized embeddings [N, D]
    /// - weight: L2-normalized class centers [C, D]
    /// - labels: integer class indices [N]
    /// - s: scale factor (commonly 64.0)
    /// - m: angular margin in radians (commonly 0.5)
    pub fn arcface_loss(
        &mut self,
        features: TensorNodeId,
        weight: TensorNodeId,
        labels: TensorNodeId,
        s: f64,
        m: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let feat_shape = self.tensor_shape(features)?;
        let weight_shape = self.tensor_shape(weight)?;
        if feat_shape.len() != 2 || weight_shape.len() != 2 {
            return Err(Self::incompatible_tensor_args(
                "arcface_loss: features and weight must be 2D",
            ));
        }
        let n = feat_shape[0];
        let d = feat_shape[1];
        let c = weight_shape[0];
        if weight_shape[1] != d {
            return Err(Self::incompatible_tensor_args(
                "arcface_loss: feature dim must match weight dim",
            ));
        }
        // f32 features/weight ERROR: cos_theta (matmul, F32) mixes with F64 `self.full()`
        // constants (m_tensor/ones/scale) in tensor_add/sub/mul -> mixed-dtype read crash.
        // Compute in f64, narrow the scalar loss to f32; to_dtype is grad-aware. frankentorch-fk5l.
        if self.tensor_dtype(features)? == DType::F32 {
            let f64f = self.tensor_to_dtype(features, DType::F64)?;
            let f64w = self.tensor_to_dtype(weight, DType::F64)?;
            // labels too: tensor_one_hot reads them via an F64-only accessor (f32 -> crash).
            let f64l = self.tensor_to_dtype(labels, DType::F64)?;
            let loss64 = self.arcface_loss(f64f, f64w, f64l, s, m)?;
            return self.tensor_to_dtype(loss64, DType::F32);
        }
        let weight_t = self.tensor_transpose(weight, 0, 1)?;
        let cos_theta = self.tensor_matmul(features, weight_t)?;
        let cos_theta_clamped = self.tensor_clamp(cos_theta, -1.0 + 1e-7, 1.0 - 1e-7)?;
        let theta = self.tensor_acos(cos_theta_clamped)?;
        let m_tensor = self.full(vec![n, c], m, false)?;
        let theta_plus_m = self.tensor_add(theta, m_tensor)?;
        let cos_theta_plus_m = self.tensor_cos(theta_plus_m)?;
        let one_hot = self.tensor_one_hot(labels, c)?;
        let ones = self.full(vec![n, c], 1.0, false)?;
        let not_one_hot = self.tensor_sub(ones, one_hot)?;
        let target_cos = self.tensor_mul(one_hot, cos_theta_plus_m)?;
        let other_cos = self.tensor_mul(not_one_hot, cos_theta)?;
        let logits = self.tensor_add(target_cos, other_cos)?;
        let scale_tensor = self.full(vec![1], s, false)?;
        let scaled_logits = self.tensor_mul(logits, scale_tensor)?;
        self.tensor_cross_entropy(scaled_logits, labels, "mean")
    }

    /// CosFace (Large Margin Cosine) loss for face recognition.
    ///
    /// Similar to ArcFace but applies margin in cosine space: cos(theta) - m
    /// instead of cos(theta + m). Simpler and often achieves similar results.
    ///
    /// Args:
    /// - features: L2-normalized embeddings [N, D]
    /// - weight: L2-normalized class centers [C, D]
    /// - labels: integer class indices [N]
    /// - s: scale factor (commonly 64.0)
    /// - m: cosine margin (commonly 0.35)
    pub fn cosface_loss(
        &mut self,
        features: TensorNodeId,
        weight: TensorNodeId,
        labels: TensorNodeId,
        s: f64,
        m: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let feat_shape = self.tensor_shape(features)?;
        let weight_shape = self.tensor_shape(weight)?;
        if feat_shape.len() != 2 || weight_shape.len() != 2 {
            return Err(Self::incompatible_tensor_args(
                "cosface_loss: features and weight must be 2D",
            ));
        }
        let n = feat_shape[0];
        let d = feat_shape[1];
        let c = weight_shape[0];
        if weight_shape[1] != d {
            return Err(Self::incompatible_tensor_args(
                "cosface_loss: feature dim must match weight dim",
            ));
        }
        // f32 features/weight ERROR: cos_theta (matmul, F32) mixes with F64 `self.full()`
        // constants (margin_tensor/scale) in tensor_sub/mul -> mixed-dtype read crash. Compute
        // in f64, narrow the scalar loss to f32; to_dtype is grad-aware. frankentorch-fk5l.
        if self.tensor_dtype(features)? == DType::F32 {
            let f64f = self.tensor_to_dtype(features, DType::F64)?;
            let f64w = self.tensor_to_dtype(weight, DType::F64)?;
            // labels too: tensor_one_hot reads them via an F64-only accessor (f32 -> crash).
            let f64l = self.tensor_to_dtype(labels, DType::F64)?;
            let loss64 = self.cosface_loss(f64f, f64w, f64l, s, m)?;
            return self.tensor_to_dtype(loss64, DType::F32);
        }
        let weight_t = self.tensor_transpose(weight, 0, 1)?;
        let cos_theta = self.tensor_matmul(features, weight_t)?;
        let one_hot = self.tensor_one_hot(labels, c)?;
        let margin_tensor = self.full(vec![n, c], m, false)?;
        let margin_penalty = self.tensor_mul(one_hot, margin_tensor)?;
        let penalized_logits = self.tensor_sub(cos_theta, margin_penalty)?;
        let scale_tensor = self.full(vec![1], s, false)?;
        let scaled_logits = self.tensor_mul(penalized_logits, scale_tensor)?;
        self.tensor_cross_entropy(scaled_logits, labels, "mean")
    }

    /// Center loss for embedding learning.
    ///
    /// Penalizes distance from class centers to encourage intra-class
    /// compactness. Commonly used with softmax loss for face recognition.
    ///
    /// Args:
    /// - features: embeddings [N, D]
    /// - labels: class indices [N]
    /// - centers: class centers [C, D]
    ///
    /// Returns: mean squared distance from each sample to its class center.
    pub fn center_loss(
        &mut self,
        features: TensorNodeId,
        labels: TensorNodeId,
        centers: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let feat_shape = self.tensor_shape(features)?;
        let centers_shape = self.tensor_shape(centers)?;
        if feat_shape.len() != 2 || centers_shape.len() != 2 {
            return Err(Self::incompatible_tensor_args(
                "center_loss: features and centers must be 2D",
            ));
        }
        let _n = feat_shape[0];
        let d = feat_shape[1];
        if centers_shape[1] != d {
            return Err(Self::incompatible_tensor_args(
                "center_loss: feature dim must match center dim",
            ));
        }
        let c = centers_shape[0];
        let one_hot = self.tensor_one_hot(labels, c)?;
        let selected_centers = self.tensor_matmul(one_hot, centers)?;
        let diff = self.tensor_sub(features, selected_centers)?;
        let diff_sq = self.tensor_mul(diff, diff)?;
        let sum_sq = self.tensor_sum_dim(diff_sq, 1)?;
        let half = self.full(vec![1], 0.5, false)?;
        let scaled = self.tensor_mul(sum_sq, half)?;
        self.tensor_mean(scaled)
    }

    /// Ring loss for unit-norm feature regularization.
    ///
    /// Encourages feature vectors to have unit norm by penalizing
    /// deviation: L = mean((||x|| - R)^2) where R is the target radius.
    /// Commonly used with softmax loss to normalize features.
    ///
    /// Args:
    /// - features: embeddings [N, D]
    /// - radius: target L2 norm (typically 1.0)
    pub fn ring_loss(
        &mut self,
        features: TensorNodeId,
        radius: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(features)?;
        if shape.len() != 2 {
            return Err(Self::incompatible_tensor_args(
                "ring_loss: features must be 2D [N, D]",
            ));
        }
        let n = shape[0];
        let norms = self.tensor_norm_dim(features, 2.0, 1)?;
        let target = self.full(vec![n], radius, false)?;
        let diff = self.tensor_sub(norms, target)?;
        let diff_sq = self.tensor_mul(diff, diff)?;
        self.tensor_mean(diff_sq)
    }

    /// N-pair loss for deep metric learning.
    ///
    /// Multi-class extension of triplet loss. For N pairs of (anchor, positive),
    /// compares each anchor to all N-1 negative samples. More efficient than
    /// triplet loss as it uses all negatives in the batch.
    ///
    /// Args:
    /// - anchors: anchor embeddings [N, D]
    /// - positives: positive embeddings [N, D]
    /// - temperature: temperature scaling (default 1.0)
    ///
    /// Returns: mean N-pair loss over all anchors.
    pub fn n_pair_loss(
        &mut self,
        anchors: TensorNodeId,
        positives: TensorNodeId,
        temperature: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let anchor_shape = self.tensor_shape(anchors)?;
        let pos_shape = self.tensor_shape(positives)?;
        if anchor_shape.len() != 2 || pos_shape.len() != 2 {
            return Err(Self::incompatible_tensor_args(
                "n_pair_loss: anchors and positives must be 2D",
            ));
        }
        if anchor_shape != pos_shape {
            return Err(Self::incompatible_tensor_args(
                "n_pair_loss: anchors and positives must have same shape",
            ));
        }
        let n = anchor_shape[0];
        let pos_t = self.tensor_transpose(positives, 0, 1)?;
        let similarity = self.tensor_matmul(anchors, pos_t)?;
        let temp = self.full(vec![1], temperature, false)?;
        let scaled_sim = self.tensor_div(similarity, temp)?;
        let labels = self.arange(0.0, n as f64, 1.0, false)?;
        self.tensor_cross_entropy(scaled_sim, labels, "mean")
    }

    /// Knowledge distillation loss.
    ///
    /// Combines cross-entropy with hard labels and KL divergence with
    /// soft teacher logits. Standard approach for model compression.
    ///
    /// Args:
    /// - student_logits: student model logits [N, C]
    /// - teacher_logits: teacher model logits [N, C]
    /// - labels: hard labels [N]
    /// - temperature: softening temperature (typically 4.0)
    /// - alpha: weight for soft loss (typically 0.9)
    ///
    /// Returns: alpha * soft_loss + (1-alpha) * hard_loss
    pub fn distillation_loss(
        &mut self,
        student_logits: TensorNodeId,
        teacher_logits: TensorNodeId,
        labels: TensorNodeId,
        temperature: f64,
        alpha: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let student_shape = self.tensor_shape(student_logits)?;
        let teacher_shape = self.tensor_shape(teacher_logits)?;
        if student_shape.len() != 2 || teacher_shape.len() != 2 {
            return Err(Self::incompatible_tensor_args(
                "distillation_loss: logits must be 2D [N, C]",
            ));
        }
        if student_shape != teacher_shape {
            return Err(Self::incompatible_tensor_args(
                "distillation_loss: student and teacher must have same shape",
            ));
        }
        let temp_tensor = self.full(vec![1], temperature, false)?;
        let student_scaled = self.tensor_div(student_logits, temp_tensor)?;
        let teacher_scaled = self.tensor_div(teacher_logits, temp_tensor)?;
        let student_log_soft = self.tensor_log_softmax(student_scaled, 1)?;
        let teacher_soft = self.tensor_softmax(teacher_scaled, 1)?;
        let kl_elem = self.tensor_mul(teacher_soft, student_log_soft)?;
        let neg_kl_elem = self.tensor_neg(kl_elem)?;
        let soft_loss = self.tensor_mean(neg_kl_elem)?;
        let t_sq = self.full(vec![1], temperature * temperature, false)?;
        let soft_loss_scaled = self.tensor_mul(soft_loss, t_sq)?;
        let hard_loss = self.tensor_cross_entropy(student_logits, labels, "mean")?;
        let alpha_tensor = self.full(vec![1], alpha, false)?;
        let one_minus_alpha = self.full(vec![1], 1.0 - alpha, false)?;
        let soft_term = self.tensor_mul(alpha_tensor, soft_loss_scaled)?;
        let hard_term = self.tensor_mul(one_minus_alpha, hard_loss)?;
        self.tensor_add(soft_term, hard_term)
    }

    /// Non-maximum suppression for object detection.
    ///
    /// Filters overlapping boxes keeping only highest-scoring ones.
    /// Returns indices of kept boxes.
    ///
    /// Args:
    /// - boxes: [N, 4] in format (x1, y1, x2, y2)
    /// - scores: [N] confidence scores
    /// - iou_threshold: IoU threshold for suppression
    ///
    /// Note: This is non-differentiable (used for inference only).
    pub fn nms(
        &mut self,
        boxes: TensorNodeId,
        scores: TensorNodeId,
        iou_threshold: f64,
    ) -> Result<Vec<usize>, AutogradError> {
        let boxes_shape = self.tensor_shape(boxes)?;
        let scores_shape = self.tensor_shape(scores)?;
        if boxes_shape.len() != 2 || boxes_shape[1] != 4 {
            return Err(Self::incompatible_tensor_args("nms: boxes must be [N, 4]"));
        }
        if scores_shape.len() != 1 || scores_shape[0] != boxes_shape[0] {
            return Err(Self::incompatible_tensor_args(
                "nms: scores must be [N] matching boxes",
            ));
        }
        let n = boxes_shape[0];
        if n == 0 {
            return Ok(vec![]);
        }
        let boxes_data = self.tensor_values_lossy_f64(boxes)?;
        let scores_data = self.tensor_values_lossy_f64(scores)?;
        let mut order: Vec<usize> = (0..n).collect();
        order.sort_by(|&a, &b| {
            scores_data[b]
                .partial_cmp(&scores_data[a])
                .unwrap_or(std::cmp::Ordering::Equal)
        });
        let mut keep = Vec::new();
        let mut suppressed = vec![false; n];
        for &i in &order {
            if suppressed[i] {
                continue;
            }
            keep.push(i);
            let x1_i = boxes_data[i * 4];
            let y1_i = boxes_data[i * 4 + 1];
            let x2_i = boxes_data[i * 4 + 2];
            let y2_i = boxes_data[i * 4 + 3];
            let area_i = (x2_i - x1_i).max(0.0) * (y2_i - y1_i).max(0.0);
            for &j in &order {
                if suppressed[j] || j == i {
                    continue;
                }
                let x1_j = boxes_data[j * 4];
                let y1_j = boxes_data[j * 4 + 1];
                let x2_j = boxes_data[j * 4 + 2];
                let y2_j = boxes_data[j * 4 + 3];
                let area_j = (x2_j - x1_j).max(0.0) * (y2_j - y1_j).max(0.0);
                let inter_x1 = x1_i.max(x1_j);
                let inter_y1 = y1_i.max(y1_j);
                let inter_x2 = x2_i.min(x2_j);
                let inter_y2 = y2_i.min(y2_j);
                let inter_area = (inter_x2 - inter_x1).max(0.0) * (inter_y2 - inter_y1).max(0.0);
                let union_area = area_i + area_j - inter_area;
                let iou = if union_area > 0.0 {
                    inter_area / union_area
                } else {
                    0.0
                };
                if iou > iou_threshold {
                    suppressed[j] = true;
                }
            }
        }
        Ok(keep)
    }

    /// Batched non-maximum suppression.
    ///
    /// Like nms but handles multiple images with class labels.
    /// Returns indices of kept boxes.
    ///
    /// Args:
    /// - boxes: [N, 4] in format (x1, y1, x2, y2)
    /// - scores: [N] confidence scores
    /// - idxs: [N] class/image indices (boxes with different idx don't suppress each other)
    /// - iou_threshold: IoU threshold for suppression
    pub fn batched_nms(
        &mut self,
        boxes: TensorNodeId,
        scores: TensorNodeId,
        idxs: TensorNodeId,
        iou_threshold: f64,
    ) -> Result<Vec<usize>, AutogradError> {
        let boxes_shape = self.tensor_shape(boxes)?;
        if boxes_shape.len() != 2 || boxes_shape[1] != 4 {
            return Err(Self::incompatible_tensor_args(
                "batched_nms: boxes must be [N, 4]",
            ));
        }
        let n = boxes_shape[0];
        if n == 0 {
            return Ok(vec![]);
        }
        let boxes_data = self.tensor_values_lossy_f64(boxes)?;
        let idxs_data = self.tensor_values_lossy_f64(idxs)?;
        let max_coord = boxes_data.iter().copied().fold(0.0_f64, f64::max);
        let mut offset_boxes = Vec::with_capacity(n * 4);
        for i in 0..n {
            let offset = idxs_data[i] * (max_coord + 1.0);
            offset_boxes.push(boxes_data[i * 4] + offset);
            offset_boxes.push(boxes_data[i * 4 + 1] + offset);
            offset_boxes.push(boxes_data[i * 4 + 2] + offset);
            offset_boxes.push(boxes_data[i * 4 + 3] + offset);
        }
        let offset_boxes_tensor = self.tensor_variable(offset_boxes, vec![n, 4], false)?;
        self.nms(offset_boxes_tensor, scores, iou_threshold)
    }

    /// Soft non-maximum suppression.
    ///
    /// Instead of removing overlapping boxes, decay their scores based on IoU.
    /// Returns (indices, new_scores) for all boxes above score_threshold.
    ///
    /// Args:
    /// - boxes: [N, 4] in format (x1, y1, x2, y2)
    /// - scores: [N] confidence scores
    /// - iou_threshold: IoU threshold for starting suppression
    /// - score_threshold: minimum score to keep
    /// - sigma: Gaussian decay parameter (typical 0.5)
    /// - method: "linear" or "gaussian"
    pub fn soft_nms(
        &mut self,
        boxes: TensorNodeId,
        scores: TensorNodeId,
        iou_threshold: f64,
        score_threshold: f64,
        sigma: f64,
        method: &str,
    ) -> Result<(Vec<usize>, Vec<f64>), AutogradError> {
        let boxes_shape = self.tensor_shape(boxes)?;
        let scores_shape = self.tensor_shape(scores)?;
        if boxes_shape.len() != 2 || boxes_shape[1] != 4 {
            return Err(Self::incompatible_tensor_args(
                "soft_nms: boxes must be [N, 4]",
            ));
        }
        if scores_shape.len() != 1 || scores_shape[0] != boxes_shape[0] {
            return Err(Self::incompatible_tensor_args(
                "soft_nms: scores must be [N]",
            ));
        }
        let n = boxes_shape[0];
        if n == 0 {
            return Ok((vec![], vec![]));
        }
        let boxes_data = self.tensor_values_lossy_f64(boxes)?;
        let mut scores_vec = self.tensor_values_lossy_f64(scores)?;
        let use_gaussian = method == "gaussian";
        let mut keep = Vec::new();
        let mut new_scores = Vec::new();
        for _ in 0..n {
            let (max_idx, _) = scores_vec
                .iter()
                .enumerate()
                .max_by(|(_, a), (_, b)| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal))
                .unwrap_or((0, &f64::NEG_INFINITY));
            if scores_vec[max_idx] < score_threshold {
                break;
            }
            keep.push(max_idx);
            new_scores.push(scores_vec[max_idx]);
            let x1_i = boxes_data[max_idx * 4];
            let y1_i = boxes_data[max_idx * 4 + 1];
            let x2_i = boxes_data[max_idx * 4 + 2];
            let y2_i = boxes_data[max_idx * 4 + 3];
            let area_i = (x2_i - x1_i).max(0.0) * (y2_i - y1_i).max(0.0);
            scores_vec[max_idx] = f64::NEG_INFINITY;
            for j in 0..n {
                if scores_vec[j] <= score_threshold {
                    continue;
                }
                let x1_j = boxes_data[j * 4];
                let y1_j = boxes_data[j * 4 + 1];
                let x2_j = boxes_data[j * 4 + 2];
                let y2_j = boxes_data[j * 4 + 3];
                let area_j = (x2_j - x1_j).max(0.0) * (y2_j - y1_j).max(0.0);
                let inter_x1 = x1_i.max(x1_j);
                let inter_y1 = y1_i.max(y1_j);
                let inter_x2 = x2_i.min(x2_j);
                let inter_y2 = y2_i.min(y2_j);
                let inter_area = (inter_x2 - inter_x1).max(0.0) * (inter_y2 - inter_y1).max(0.0);
                let union_area = area_i + area_j - inter_area;
                let iou = if union_area > 0.0 {
                    inter_area / union_area
                } else {
                    0.0
                };
                if iou > iou_threshold {
                    if use_gaussian {
                        scores_vec[j] *= (-iou * iou / sigma).exp();
                    } else {
                        scores_vec[j] *= 1.0 - iou;
                    }
                }
            }
        }
        Ok((keep, new_scores))
    }

    /// Matrix NMS for instance segmentation (YOLACT, SOLOv2).
    ///
    /// Decays scores based on IoU with all higher-scoring instances.
    /// More efficient than sequential NMS for instance segmentation.
    ///
    /// Args:
    /// - scores: [N] confidence scores
    /// - masks: [N, H, W] instance masks
    /// - sigma: decay coefficient
    /// - pre_nms_top_k: keep top-k before NMS
    /// - post_nms_top_k: keep top-k after NMS
    ///
    /// Returns: (indices, new_scores) of kept instances
    pub fn matrix_nms(
        &mut self,
        scores: TensorNodeId,
        masks: TensorNodeId,
        sigma: f64,
        pre_nms_top_k: usize,
        post_nms_top_k: usize,
    ) -> Result<(Vec<usize>, Vec<f64>), AutogradError> {
        let scores_shape = self.tensor_shape(scores)?;
        let masks_shape = self.tensor_shape(masks)?;
        if scores_shape.len() != 1 || masks_shape.len() != 3 {
            return Err(Self::incompatible_tensor_args(
                "matrix_nms: scores [N], masks [N, H, W]",
            ));
        }
        let n = scores_shape[0];
        if n == 0 {
            return Ok((vec![], vec![]));
        }
        let (h, w) = (masks_shape[1], masks_shape[2]);
        let mask_area = h * w;
        let scores_data = self.tensor_values_lossy_f64(scores)?;
        let masks_data = self.tensor_values(masks)?;
        let mut indices: Vec<usize> = (0..n).collect();
        indices.sort_by(|&a, &b| {
            scores_data[b]
                .partial_cmp(&scores_data[a])
                .unwrap_or(std::cmp::Ordering::Equal)
        });
        let top_k = pre_nms_top_k.min(n);
        indices.truncate(top_k);
        let k = indices.len();
        let bits_per_word = u64::BITS as usize;
        let words_per_mask = mask_area.div_ceil(bits_per_word);
        let mut packed_masks = vec![0_u64; k * words_per_mask];
        let mut mask_areas = vec![0_usize; k];
        for (row_idx, &mask_idx) in indices.iter().enumerate() {
            let mask = &masks_data[mask_idx * mask_area..(mask_idx + 1) * mask_area];
            let packed =
                &mut packed_masks[row_idx * words_per_mask..(row_idx + 1) * words_per_mask];
            let mut area = 0_usize;
            for (pixel_idx, &value) in mask.iter().enumerate() {
                if value > 0.5 {
                    packed[pixel_idx / bits_per_word] |= 1_u64 << (pixel_idx % bits_per_word);
                    area += 1;
                }
            }
            mask_areas[row_idx] = area;
        }

        // Decay only depends on higher-scoring masks, so compute each row's
        // factor directly instead of materializing a dense K x K IoU matrix.
        let compute_decay = |i: usize| {
            let row_start = i * words_per_mask;
            let row_words = &packed_masks[row_start..row_start + words_per_mask];
            let row_area = mask_areas[i];
            let mut factor = 1.0_f64;
            for j in 0..i {
                let other_start = j * words_per_mask;
                let other_words = &packed_masks[other_start..other_start + words_per_mask];
                let mut inter = 0_usize;
                for (&a, &b) in row_words.iter().zip(other_words.iter()) {
                    inter += (a & b).count_ones() as usize;
                }
                let union_count = row_area + mask_areas[j] - inter;
                let union_val = (union_count as f64).max(1e-6_f64);
                let iou = (inter as f64) / union_val;
                factor *= (-iou * iou / sigma).exp();
            }
            factor
        };
        let decay_factors: Vec<f64> = if k >= 2 && k * k >= PARALLEL_ELEMENTWISE_MIN {
            use rayon::prelude::*;
            (0..k).into_par_iter().map(compute_decay).collect()
        } else {
            (0..k).map(compute_decay).collect()
        };
        let new_scores: Vec<f64> = indices
            .iter()
            .enumerate()
            .map(|(i, &idx)| scores_data[idx] * decay_factors[i])
            .collect();
        let mut sorted_indices: Vec<usize> = (0..k).collect();
        sorted_indices.sort_by(|&a, &b| {
            new_scores[b]
                .partial_cmp(&new_scores[a])
                .unwrap_or(std::cmp::Ordering::Equal)
        });
        let final_k = post_nms_top_k.min(k);
        let final_indices: Vec<usize> = sorted_indices[..final_k]
            .iter()
            .map(|&i| indices[i])
            .collect();
        let final_scores: Vec<f64> = sorted_indices[..final_k]
            .iter()
            .map(|&i| new_scores[i])
            .collect();
        Ok((final_indices, final_scores))
    }

    /// Generate anchor boxes for object detection.
    ///
    /// Creates anchors at each spatial location for given aspect ratios and scales.
    /// Returns anchors in (x1, y1, x2, y2) format.
    ///
    /// Args:
    /// - feature_map_size: (H, W) of feature map
    /// - stride: stride between feature map and input image
    /// - base_size: base anchor size
    /// - ratios: aspect ratios (e.g., [0.5, 1.0, 2.0])
    /// - scales: scale multipliers (e.g., [1.0, 2.0, 4.0])
    ///
    /// Returns: [H*W*num_anchors, 4] anchors
    pub fn generate_anchors(
        &mut self,
        feature_map_size: (usize, usize),
        stride: usize,
        base_size: f64,
        ratios: &[f64],
        scales: &[f64],
    ) -> Result<TensorNodeId, AutogradError> {
        let (h, w) = feature_map_size;
        let num_anchors = ratios.len() * scales.len();
        let total_anchors = h * w * num_anchors;
        let mut anchors = Vec::with_capacity(total_anchors * 4);
        let _half_base = base_size / 2.0;
        for y in 0..h {
            let center_y = (y * stride) as f64 + stride as f64 / 2.0;
            for x in 0..w {
                let center_x = (x * stride) as f64 + stride as f64 / 2.0;
                for &ratio in ratios {
                    let sqrt_ratio = ratio.sqrt();
                    for &scale in scales {
                        let anchor_w = base_size * scale / sqrt_ratio;
                        let anchor_h = base_size * scale * sqrt_ratio;
                        let x1 = center_x - anchor_w / 2.0;
                        let y1 = center_y - anchor_h / 2.0;
                        let x2 = center_x + anchor_w / 2.0;
                        let y2 = center_y + anchor_h / 2.0;
                        anchors.push(x1);
                        anchors.push(y1);
                        anchors.push(x2);
                        anchors.push(y2);
                    }
                }
            }
        }
        self.tensor_variable(anchors, vec![total_anchors, 4], false)
    }

    /// Encode target boxes relative to anchor boxes (box parameterization).
    ///
    /// Computes (tx, ty, tw, th) where:
    /// - tx = (target_cx - anchor_cx) / anchor_w
    /// - ty = (target_cy - anchor_cy) / anchor_h
    /// - tw = log(target_w / anchor_w)
    /// - th = log(target_h / anchor_h)
    ///
    /// Used for training detection heads. Both inputs in (x1, y1, x2, y2) format.
    pub fn encode_boxes(
        &mut self,
        anchors: TensorNodeId,
        targets: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let anchor_shape = self.tensor_shape(anchors)?;
        let target_shape = self.tensor_shape(targets)?;
        if anchor_shape.len() != 2 || anchor_shape[1] != 4 {
            return Err(Self::incompatible_tensor_args(
                "encode_boxes: anchors must be [N, 4]",
            ));
        }
        if target_shape != anchor_shape {
            return Err(Self::incompatible_tensor_args(
                "encode_boxes: shapes must match",
            ));
        }
        let n = anchor_shape[0];
        let a_x1 = self.tensor_narrow(anchors, 1, 0, 1)?;
        let a_y1 = self.tensor_narrow(anchors, 1, 1, 1)?;
        let a_x2 = self.tensor_narrow(anchors, 1, 2, 1)?;
        let a_y2 = self.tensor_narrow(anchors, 1, 3, 1)?;
        let t_x1 = self.tensor_narrow(targets, 1, 0, 1)?;
        let t_y1 = self.tensor_narrow(targets, 1, 1, 1)?;
        let t_x2 = self.tensor_narrow(targets, 1, 2, 1)?;
        let t_y2 = self.tensor_narrow(targets, 1, 3, 1)?;
        let a_w = self.tensor_sub(a_x2, a_x1)?;
        let a_h = self.tensor_sub(a_y2, a_y1)?;
        let t_w = self.tensor_sub(t_x2, t_x1)?;
        let t_h = self.tensor_sub(t_y2, t_y1)?;
        let two = self.full(vec![n, 1], 2.0, false)?;
        let a_cx = self.tensor_add(a_x1, a_x2)?;
        let a_cx = self.tensor_div(a_cx, two)?;
        let a_cy = self.tensor_add(a_y1, a_y2)?;
        let a_cy = self.tensor_div(a_cy, two)?;
        let t_cx = self.tensor_add(t_x1, t_x2)?;
        let t_cx = self.tensor_div(t_cx, two)?;
        let t_cy = self.tensor_add(t_y1, t_y2)?;
        let t_cy = self.tensor_div(t_cy, two)?;
        let eps = self.full(vec![n, 1], 1e-7, false)?;
        let a_w_safe = self.tensor_add(a_w, eps)?;
        let a_h_safe = self.tensor_add(a_h, eps)?;
        let t_w_safe = self.tensor_add(t_w, eps)?;
        let t_h_safe = self.tensor_add(t_h, eps)?;
        let dx = self.tensor_sub(t_cx, a_cx)?;
        let tx = self.tensor_div(dx, a_w_safe)?;
        let dy = self.tensor_sub(t_cy, a_cy)?;
        let ty = self.tensor_div(dy, a_h_safe)?;
        let w_ratio = self.tensor_div(t_w_safe, a_w_safe)?;
        let tw = self.tensor_log(w_ratio)?;
        let h_ratio = self.tensor_div(t_h_safe, a_h_safe)?;
        let th = self.tensor_log(h_ratio)?;
        self.tensor_cat(&[tx, ty, tw, th], 1)
    }

    /// Decode predicted deltas to boxes using anchor boxes.
    ///
    /// Inverse of encode_boxes. Converts (tx, ty, tw, th) predictions
    /// back to (x1, y1, x2, y2) format.
    pub fn decode_boxes(
        &mut self,
        anchors: TensorNodeId,
        deltas: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let anchor_shape = self.tensor_shape(anchors)?;
        let delta_shape = self.tensor_shape(deltas)?;
        if anchor_shape.len() != 2 || anchor_shape[1] != 4 {
            return Err(Self::incompatible_tensor_args(
                "decode_boxes: anchors must be [N, 4]",
            ));
        }
        if delta_shape != anchor_shape {
            return Err(Self::incompatible_tensor_args(
                "decode_boxes: shapes must match",
            ));
        }
        let n = anchor_shape[0];
        let a_x1 = self.tensor_narrow(anchors, 1, 0, 1)?;
        let a_y1 = self.tensor_narrow(anchors, 1, 1, 1)?;
        let a_x2 = self.tensor_narrow(anchors, 1, 2, 1)?;
        let a_y2 = self.tensor_narrow(anchors, 1, 3, 1)?;
        let tx = self.tensor_narrow(deltas, 1, 0, 1)?;
        let ty = self.tensor_narrow(deltas, 1, 1, 1)?;
        let tw = self.tensor_narrow(deltas, 1, 2, 1)?;
        let th = self.tensor_narrow(deltas, 1, 3, 1)?;
        let a_w = self.tensor_sub(a_x2, a_x1)?;
        let a_h = self.tensor_sub(a_y2, a_y1)?;
        let two = self.full(vec![n, 1], 2.0, false)?;
        let a_cx = self.tensor_add(a_x1, a_x2)?;
        let a_cx = self.tensor_div(a_cx, two)?;
        let a_cy = self.tensor_add(a_y1, a_y2)?;
        let a_cy = self.tensor_div(a_cy, two)?;
        let dx = self.tensor_mul(tx, a_w)?;
        let pred_cx = self.tensor_add(dx, a_cx)?;
        let dy = self.tensor_mul(ty, a_h)?;
        let pred_cy = self.tensor_add(dy, a_cy)?;
        let exp_tw = self.tensor_exp(tw)?;
        let pred_w = self.tensor_mul(exp_tw, a_w)?;
        let exp_th = self.tensor_exp(th)?;
        let pred_h = self.tensor_mul(exp_th, a_h)?;
        let half_w = self.tensor_div(pred_w, two)?;
        let half_h = self.tensor_div(pred_h, two)?;
        let x1 = self.tensor_sub(pred_cx, half_w)?;
        let y1 = self.tensor_sub(pred_cy, half_h)?;
        let x2 = self.tensor_add(pred_cx, half_w)?;
        let y2 = self.tensor_add(pred_cy, half_h)?;
        self.tensor_cat(&[x1, y1, x2, y2], 1)
    }

    /// Clip boxes to image boundaries.
    ///
    /// Clamps box coordinates to [0, width/height] for valid predictions.
    ///
    /// Args:
    /// - boxes: [N, 4] in format (x1, y1, x2, y2)
    /// - image_size: (height, width) of image
    ///
    /// Returns: [N, 4] clipped boxes
    pub fn clip_boxes(
        &mut self,
        boxes: TensorNodeId,
        image_size: (usize, usize),
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(boxes)?;
        if shape.len() != 2 || shape[1] != 4 {
            return Err(Self::incompatible_tensor_args(
                "clip_boxes: boxes must be [N, 4]",
            ));
        }
        let (h, w) = image_size;
        let _n = shape[0];
        let x1 = self.tensor_narrow(boxes, 1, 0, 1)?;
        let y1 = self.tensor_narrow(boxes, 1, 1, 1)?;
        let x2 = self.tensor_narrow(boxes, 1, 2, 1)?;
        let y2 = self.tensor_narrow(boxes, 1, 3, 1)?;
        let x1 = self.tensor_clamp(x1, 0.0, w as f64)?;
        let y1 = self.tensor_clamp(y1, 0.0, h as f64)?;
        let x2 = self.tensor_clamp(x2, 0.0, w as f64)?;
        let y2 = self.tensor_clamp(y2, 0.0, h as f64)?;
        self.tensor_cat(&[x1, y1, x2, y2], 1)
    }

    /// Remove small boxes below minimum size.
    ///
    /// Filters out boxes with width or height below threshold.
    ///
    /// Args:
    /// - boxes: [N, 4] in format (x1, y1, x2, y2)
    /// - min_size: minimum box dimension
    ///
    /// Returns: indices of kept boxes
    pub fn remove_small_boxes(
        &mut self,
        boxes: TensorNodeId,
        min_size: f64,
    ) -> Result<Vec<usize>, AutogradError> {
        let shape = self.tensor_shape(boxes)?;
        if shape.len() != 2 || shape[1] != 4 {
            return Err(Self::incompatible_tensor_args(
                "remove_small_boxes: boxes must be [N, 4]",
            ));
        }
        let n = shape[0];
        let boxes_data = self.tensor_values_lossy_f64(boxes)?;
        let mut keep = Vec::new();
        for i in 0..n {
            let x1 = boxes_data[i * 4];
            let y1 = boxes_data[i * 4 + 1];
            let x2 = boxes_data[i * 4 + 2];
            let y2 = boxes_data[i * 4 + 3];
            let w = x2 - x1;
            let h = y2 - y1;
            if w >= min_size && h >= min_size {
                keep.push(i);
            }
        }
        Ok(keep)
    }

    /// Compute mask IoU for instance segmentation.
    ///
    /// Computes IoU between binary masks by summing pixel-wise
    /// intersection and union.
    ///
    /// Args:
    /// - masks1: [N, H, W] binary masks
    /// - masks2: [M, H, W] binary masks
    ///
    /// Returns: [N, M] IoU matrix
    pub fn mask_iou(
        &mut self,
        masks1: TensorNodeId,
        masks2: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape1 = self.tensor_shape(masks1)?;
        let shape2 = self.tensor_shape(masks2)?;
        if shape1.len() != 3 {
            return Err(Self::incompatible_tensor_args(
                "mask_iou: masks1 must be [N, H, W]",
            ));
        }
        if shape2.len() != 3 {
            return Err(Self::incompatible_tensor_args(
                "mask_iou: masks2 must be [M, H, W]",
            ));
        }
        if shape1[1] != shape2[1] || shape1[2] != shape2[2] {
            return Err(Self::incompatible_tensor_args(
                "mask_iou: mask dimensions must match",
            ));
        }
        let n = shape1[0];
        let m = shape2[0];
        let h = shape1[1];
        let w = shape1[2];
        let masks1_flat = self.tensor_reshape(masks1, vec![n, h * w])?;
        let masks2_flat = self.tensor_reshape(masks2, vec![m, h * w])?;
        let masks2_t = self.tensor_transpose(masks2_flat, 0, 1)?;
        let intersection = self.tensor_matmul(masks1_flat, masks2_t)?;
        let area1 = self.tensor_sum_dim(masks1_flat, 1)?;
        let area2 = self.tensor_sum_dim(masks2_flat, 1)?;
        let area1_exp = self.tensor_unsqueeze(area1, 1)?;
        let area1_exp = self.tensor_expand(area1_exp, vec![n, m])?;
        let area2_exp = self.tensor_unsqueeze(area2, 0)?;
        let area2_exp = self.tensor_expand(area2_exp, vec![n, m])?;
        let union = self.tensor_add(area1_exp, area2_exp)?;
        let union = self.tensor_sub(union, intersection)?;
        let eps = self.full(vec![n, m], 1e-7, false)?;
        let union_safe = self.tensor_add(union, eps)?;
        self.tensor_div(intersection, union_safe)
    }

    /// Convert boxes from (x1, y1, x2, y2) to (cx, cy, w, h) format.
    pub fn box_xyxy_to_cxcywh(
        &mut self,
        boxes: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(boxes)?;
        if shape.len() != 2 || shape[1] != 4 {
            return Err(Self::incompatible_tensor_args(
                "box_xyxy_to_cxcywh: boxes must be [N, 4]",
            ));
        }
        let n = shape[0];
        let x1 = self.tensor_narrow(boxes, 1, 0, 1)?;
        let y1 = self.tensor_narrow(boxes, 1, 1, 1)?;
        let x2 = self.tensor_narrow(boxes, 1, 2, 1)?;
        let y2 = self.tensor_narrow(boxes, 1, 3, 1)?;
        let two = self.full(vec![n, 1], 2.0, false)?;
        let cx = self.tensor_add(x1, x2)?;
        let cx = self.tensor_div(cx, two)?;
        let cy = self.tensor_add(y1, y2)?;
        let cy = self.tensor_div(cy, two)?;
        let w = self.tensor_sub(x2, x1)?;
        let h = self.tensor_sub(y2, y1)?;
        self.tensor_cat(&[cx, cy, w, h], 1)
    }

    /// Convert boxes from (cx, cy, w, h) to (x1, y1, x2, y2) format.
    pub fn box_cxcywh_to_xyxy(
        &mut self,
        boxes: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(boxes)?;
        if shape.len() != 2 || shape[1] != 4 {
            return Err(Self::incompatible_tensor_args(
                "box_cxcywh_to_xyxy: boxes must be [N, 4]",
            ));
        }
        let n = shape[0];
        let cx = self.tensor_narrow(boxes, 1, 0, 1)?;
        let cy = self.tensor_narrow(boxes, 1, 1, 1)?;
        let w = self.tensor_narrow(boxes, 1, 2, 1)?;
        let h = self.tensor_narrow(boxes, 1, 3, 1)?;
        let two = self.full(vec![n, 1], 2.0, false)?;
        let half_w = self.tensor_div(w, two)?;
        let half_h = self.tensor_div(h, two)?;
        let x1 = self.tensor_sub(cx, half_w)?;
        let y1 = self.tensor_sub(cy, half_h)?;
        let x2 = self.tensor_add(cx, half_w)?;
        let y2 = self.tensor_add(cy, half_h)?;
        self.tensor_cat(&[x1, y1, x2, y2], 1)
    }

    /// Compute box areas.
    ///
    /// Args:
    /// - boxes: [N, 4] in format (x1, y1, x2, y2)
    ///
    /// Returns: [N] areas
    pub fn box_area(&mut self, boxes: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(boxes)?;
        if shape.len() != 2 || shape[1] != 4 {
            return Err(Self::incompatible_tensor_args(
                "box_area: boxes must be [N, 4]",
            ));
        }
        let x1 = self.tensor_narrow(boxes, 1, 0, 1)?;
        let y1 = self.tensor_narrow(boxes, 1, 1, 1)?;
        let x2 = self.tensor_narrow(boxes, 1, 2, 1)?;
        let y2 = self.tensor_narrow(boxes, 1, 3, 1)?;
        let w = self.tensor_sub(x2, x1)?;
        let h = self.tensor_sub(y2, y1)?;
        let area = self.tensor_mul(w, h)?;
        self.tensor_squeeze(area, 1)
    }

    /// Compute IoU (Intersection over Union) between two sets of boxes.
    ///
    /// Args:
    /// - boxes1: [N, 4] in format (x1, y1, x2, y2)
    /// - boxes2: [M, 4] in format (x1, y1, x2, y2)
    ///
    /// Returns: [N, M] IoU matrix
    pub fn box_iou(
        &mut self,
        boxes1: TensorNodeId,
        boxes2: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape1 = self.tensor_shape(boxes1)?;
        let shape2 = self.tensor_shape(boxes2)?;
        if shape1.len() != 2 || shape1[1] != 4 {
            return Err(Self::incompatible_tensor_args(
                "box_iou: boxes1 must be [N, 4]",
            ));
        }
        if shape2.len() != 2 || shape2[1] != 4 {
            return Err(Self::incompatible_tensor_args(
                "box_iou: boxes2 must be [M, 4]",
            ));
        }
        let n = shape1[0];
        let m = shape2[0];
        let b1_x1 = self.tensor_narrow(boxes1, 1, 0, 1)?;
        let b1_y1 = self.tensor_narrow(boxes1, 1, 1, 1)?;
        let b1_x2 = self.tensor_narrow(boxes1, 1, 2, 1)?;
        let b1_y2 = self.tensor_narrow(boxes1, 1, 3, 1)?;
        let b2_x1 = self.tensor_narrow(boxes2, 1, 0, 1)?;
        let b2_y1 = self.tensor_narrow(boxes2, 1, 1, 1)?;
        let b2_x2 = self.tensor_narrow(boxes2, 1, 2, 1)?;
        let b2_y2 = self.tensor_narrow(boxes2, 1, 3, 1)?;
        let b1_w = self.tensor_sub(b1_x2, b1_x1)?;
        let b1_h = self.tensor_sub(b1_y2, b1_y1)?;
        let b2_w = self.tensor_sub(b2_x2, b2_x1)?;
        let b2_h = self.tensor_sub(b2_y2, b2_y1)?;
        let area1 = self.tensor_mul(b1_w, b1_h)?;
        let area2 = self.tensor_mul(b2_w, b2_h)?;
        let b1_x1_exp = self.tensor_expand(b1_x1, vec![n, m])?;
        let b1_y1_exp = self.tensor_expand(b1_y1, vec![n, m])?;
        let b1_x2_exp = self.tensor_expand(b1_x2, vec![n, m])?;
        let b1_y2_exp = self.tensor_expand(b1_y2, vec![n, m])?;
        let b2_x1_t = self.tensor_transpose(b2_x1, 0, 1)?;
        let b2_y1_t = self.tensor_transpose(b2_y1, 0, 1)?;
        let b2_x2_t = self.tensor_transpose(b2_x2, 0, 1)?;
        let b2_y2_t = self.tensor_transpose(b2_y2, 0, 1)?;
        let b2_x1_exp = self.tensor_expand(b2_x1_t, vec![n, m])?;
        let b2_y1_exp = self.tensor_expand(b2_y1_t, vec![n, m])?;
        let b2_x2_exp = self.tensor_expand(b2_x2_t, vec![n, m])?;
        let b2_y2_exp = self.tensor_expand(b2_y2_t, vec![n, m])?;
        let inter_x1 = self.tensor_maximum(b1_x1_exp, b2_x1_exp)?;
        let inter_y1 = self.tensor_maximum(b1_y1_exp, b2_y1_exp)?;
        let inter_x2 = self.tensor_minimum(b1_x2_exp, b2_x2_exp)?;
        let inter_y2 = self.tensor_minimum(b1_y2_exp, b2_y2_exp)?;
        let inter_w = self.tensor_sub(inter_x2, inter_x1)?;
        let inter_h = self.tensor_sub(inter_y2, inter_y1)?;
        let zero = self.full(vec![n, m], 0.0, false)?;
        let inter_w = self.tensor_maximum(inter_w, zero)?;
        let inter_h = self.tensor_maximum(inter_h, zero)?;
        let inter_area = self.tensor_mul(inter_w, inter_h)?;
        let area1_exp = self.tensor_expand(area1, vec![n, m])?;
        let area2_t = self.tensor_transpose(area2, 0, 1)?;
        let area2_exp = self.tensor_expand(area2_t, vec![n, m])?;
        let union_area = self.tensor_add(area1_exp, area2_exp)?;
        let union_area = self.tensor_sub(union_area, inter_area)?;
        let eps = self.full(vec![n, m], 1e-7, false)?;
        let union_area_safe = self.tensor_add(union_area, eps)?;
        self.tensor_div(inter_area, union_area_safe)
    }

    /// Generalized IoU (GIoU) loss for bounding box regression.
    ///
    /// GIoU = IoU - (C - Union) / C where C is the smallest enclosing box.
    /// Loss = 1 - GIoU. Differentiable alternative to IoU loss.
    ///
    /// Args:
    /// - pred_boxes: [N, 4] predicted boxes (x1, y1, x2, y2)
    /// - target_boxes: [N, 4] target boxes (x1, y1, x2, y2)
    ///
    /// Returns: mean GIoU loss
    pub fn giou_loss(
        &mut self,
        pred_boxes: TensorNodeId,
        target_boxes: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let pred_shape = self.tensor_shape(pred_boxes)?;
        let target_shape = self.tensor_shape(target_boxes)?;
        if pred_shape.len() != 2 || pred_shape[1] != 4 {
            return Err(Self::incompatible_tensor_args(
                "giou_loss: pred_boxes must be [N, 4]",
            ));
        }
        if target_shape != pred_shape {
            return Err(Self::incompatible_tensor_args(
                "giou_loss: pred and target must have same shape",
            ));
        }
        let n = pred_shape[0];
        let p_x1 = self.tensor_narrow(pred_boxes, 1, 0, 1)?;
        let p_y1 = self.tensor_narrow(pred_boxes, 1, 1, 1)?;
        let p_x2 = self.tensor_narrow(pred_boxes, 1, 2, 1)?;
        let p_y2 = self.tensor_narrow(pred_boxes, 1, 3, 1)?;
        let t_x1 = self.tensor_narrow(target_boxes, 1, 0, 1)?;
        let t_y1 = self.tensor_narrow(target_boxes, 1, 1, 1)?;
        let t_x2 = self.tensor_narrow(target_boxes, 1, 2, 1)?;
        let t_y2 = self.tensor_narrow(target_boxes, 1, 3, 1)?;
        let p_w = self.tensor_sub(p_x2, p_x1)?;
        let p_h = self.tensor_sub(p_y2, p_y1)?;
        let t_w = self.tensor_sub(t_x2, t_x1)?;
        let t_h = self.tensor_sub(t_y2, t_y1)?;
        let pred_area = self.tensor_mul(p_w, p_h)?;
        let target_area = self.tensor_mul(t_w, t_h)?;
        let inter_x1 = self.tensor_maximum(p_x1, t_x1)?;
        let inter_y1 = self.tensor_maximum(p_y1, t_y1)?;
        let inter_x2 = self.tensor_minimum(p_x2, t_x2)?;
        let inter_y2 = self.tensor_minimum(p_y2, t_y2)?;
        let inter_w = self.tensor_sub(inter_x2, inter_x1)?;
        let inter_h = self.tensor_sub(inter_y2, inter_y1)?;
        let zero = self.full(vec![n, 1], 0.0, false)?;
        let inter_w = self.tensor_maximum(inter_w, zero)?;
        let inter_h = self.tensor_maximum(inter_h, zero)?;
        let inter_area = self.tensor_mul(inter_w, inter_h)?;
        let union_area = self.tensor_add(pred_area, target_area)?;
        let union_area = self.tensor_sub(union_area, inter_area)?;
        let eps = self.full(vec![n, 1], 1e-7, false)?;
        let union_safe = self.tensor_add(union_area, eps)?;
        let iou = self.tensor_div(inter_area, union_safe)?;
        let enc_x1 = self.tensor_minimum(p_x1, t_x1)?;
        let enc_y1 = self.tensor_minimum(p_y1, t_y1)?;
        let enc_x2 = self.tensor_maximum(p_x2, t_x2)?;
        let enc_y2 = self.tensor_maximum(p_y2, t_y2)?;
        let enc_w = self.tensor_sub(enc_x2, enc_x1)?;
        let enc_h = self.tensor_sub(enc_y2, enc_y1)?;
        let enc_area = self.tensor_mul(enc_w, enc_h)?;
        let enc_safe = self.tensor_add(enc_area, eps)?;
        let c_minus_union = self.tensor_sub(enc_area, union_area)?;
        let penalty = self.tensor_div(c_minus_union, enc_safe)?;
        let giou = self.tensor_sub(iou, penalty)?;
        let one = self.full(vec![n, 1], 1.0, false)?;
        let loss = self.tensor_sub(one, giou)?;
        self.tensor_mean(loss)
    }

    /// Distance-IoU (DIoU) loss for bounding box regression.
    ///
    /// DIoU = IoU - rho^2(b, b_gt) / c^2, where rho is center distance
    /// and c is diagonal of enclosing box. Better convergence than GIoU.
    ///
    /// Args:
    /// - pred_boxes: [N, 4] predicted boxes (x1, y1, x2, y2)
    /// - target_boxes: [N, 4] target boxes (x1, y1, x2, y2)
    ///
    /// Returns: mean DIoU loss
    pub fn diou_loss(
        &mut self,
        pred_boxes: TensorNodeId,
        target_boxes: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let pred_shape = self.tensor_shape(pred_boxes)?;
        let target_shape = self.tensor_shape(target_boxes)?;
        if pred_shape.len() != 2 || pred_shape[1] != 4 {
            return Err(Self::incompatible_tensor_args(
                "diou_loss: pred_boxes must be [N, 4]",
            ));
        }
        if target_shape != pred_shape {
            return Err(Self::incompatible_tensor_args(
                "diou_loss: pred and target must have same shape",
            ));
        }
        let n = pred_shape[0];
        let p_x1 = self.tensor_narrow(pred_boxes, 1, 0, 1)?;
        let p_y1 = self.tensor_narrow(pred_boxes, 1, 1, 1)?;
        let p_x2 = self.tensor_narrow(pred_boxes, 1, 2, 1)?;
        let p_y2 = self.tensor_narrow(pred_boxes, 1, 3, 1)?;
        let t_x1 = self.tensor_narrow(target_boxes, 1, 0, 1)?;
        let t_y1 = self.tensor_narrow(target_boxes, 1, 1, 1)?;
        let t_x2 = self.tensor_narrow(target_boxes, 1, 2, 1)?;
        let t_y2 = self.tensor_narrow(target_boxes, 1, 3, 1)?;
        let two = self.full(vec![n, 1], 2.0, false)?;
        let p_cx = self.tensor_add(p_x1, p_x2)?;
        let p_cx = self.tensor_div(p_cx, two)?;
        let p_cy = self.tensor_add(p_y1, p_y2)?;
        let p_cy = self.tensor_div(p_cy, two)?;
        let t_cx = self.tensor_add(t_x1, t_x2)?;
        let t_cx = self.tensor_div(t_cx, two)?;
        let t_cy = self.tensor_add(t_y1, t_y2)?;
        let t_cy = self.tensor_div(t_cy, two)?;
        let dx = self.tensor_sub(p_cx, t_cx)?;
        let dy = self.tensor_sub(p_cy, t_cy)?;
        let dx_sq = self.tensor_mul(dx, dx)?;
        let dy_sq = self.tensor_mul(dy, dy)?;
        let rho_sq = self.tensor_add(dx_sq, dy_sq)?;
        let enc_x1 = self.tensor_minimum(p_x1, t_x1)?;
        let enc_y1 = self.tensor_minimum(p_y1, t_y1)?;
        let enc_x2 = self.tensor_maximum(p_x2, t_x2)?;
        let enc_y2 = self.tensor_maximum(p_y2, t_y2)?;
        let enc_w = self.tensor_sub(enc_x2, enc_x1)?;
        let enc_h = self.tensor_sub(enc_y2, enc_y1)?;
        let enc_w_sq = self.tensor_mul(enc_w, enc_w)?;
        let enc_h_sq = self.tensor_mul(enc_h, enc_h)?;
        let c_sq = self.tensor_add(enc_w_sq, enc_h_sq)?;
        let eps = self.full(vec![n, 1], 1e-7, false)?;
        let c_sq_safe = self.tensor_add(c_sq, eps)?;
        let center_penalty = self.tensor_div(rho_sq, c_sq_safe)?;
        let p_w = self.tensor_sub(p_x2, p_x1)?;
        let p_h = self.tensor_sub(p_y2, p_y1)?;
        let t_w = self.tensor_sub(t_x2, t_x1)?;
        let t_h = self.tensor_sub(t_y2, t_y1)?;
        let pred_area = self.tensor_mul(p_w, p_h)?;
        let target_area = self.tensor_mul(t_w, t_h)?;
        let inter_x1 = self.tensor_maximum(p_x1, t_x1)?;
        let inter_y1 = self.tensor_maximum(p_y1, t_y1)?;
        let inter_x2 = self.tensor_minimum(p_x2, t_x2)?;
        let inter_y2 = self.tensor_minimum(p_y2, t_y2)?;
        let inter_w = self.tensor_sub(inter_x2, inter_x1)?;
        let inter_h = self.tensor_sub(inter_y2, inter_y1)?;
        let zero = self.full(vec![n, 1], 0.0, false)?;
        let inter_w = self.tensor_maximum(inter_w, zero)?;
        let inter_h = self.tensor_maximum(inter_h, zero)?;
        let inter_area = self.tensor_mul(inter_w, inter_h)?;
        let union_area = self.tensor_add(pred_area, target_area)?;
        let union_area = self.tensor_sub(union_area, inter_area)?;
        let union_safe = self.tensor_add(union_area, eps)?;
        let iou = self.tensor_div(inter_area, union_safe)?;
        let diou = self.tensor_sub(iou, center_penalty)?;
        let one = self.full(vec![n, 1], 1.0, false)?;
        let loss = self.tensor_sub(one, diou)?;
        self.tensor_mean(loss)
    }

    /// Complete-IoU (CIoU) loss for bounding box regression.
    ///
    /// CIoU = DIoU + aspect ratio consistency term v.
    /// State-of-the-art for YOLOv5/v7/v8 box regression.
    ///
    /// Args:
    /// - pred_boxes: [N, 4] predicted boxes (x1, y1, x2, y2)
    /// - target_boxes: [N, 4] target boxes (x1, y1, x2, y2)
    ///
    /// Returns: mean CIoU loss
    pub fn ciou_loss(
        &mut self,
        pred_boxes: TensorNodeId,
        target_boxes: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let pred_shape = self.tensor_shape(pred_boxes)?;
        let target_shape = self.tensor_shape(target_boxes)?;
        if pred_shape.len() != 2 || pred_shape[1] != 4 {
            return Err(Self::incompatible_tensor_args(
                "ciou_loss: pred_boxes must be [N, 4]",
            ));
        }
        if target_shape != pred_shape {
            return Err(Self::incompatible_tensor_args(
                "ciou_loss: pred and target must have same shape",
            ));
        }
        let n = pred_shape[0];
        let p_x1 = self.tensor_narrow(pred_boxes, 1, 0, 1)?;
        let p_y1 = self.tensor_narrow(pred_boxes, 1, 1, 1)?;
        let p_x2 = self.tensor_narrow(pred_boxes, 1, 2, 1)?;
        let p_y2 = self.tensor_narrow(pred_boxes, 1, 3, 1)?;
        let t_x1 = self.tensor_narrow(target_boxes, 1, 0, 1)?;
        let t_y1 = self.tensor_narrow(target_boxes, 1, 1, 1)?;
        let t_x2 = self.tensor_narrow(target_boxes, 1, 2, 1)?;
        let t_y2 = self.tensor_narrow(target_boxes, 1, 3, 1)?;
        let p_w = self.tensor_sub(p_x2, p_x1)?;
        let p_h = self.tensor_sub(p_y2, p_y1)?;
        let t_w = self.tensor_sub(t_x2, t_x1)?;
        let t_h = self.tensor_sub(t_y2, t_y1)?;
        let eps = self.full(vec![n, 1], 1e-7, false)?;
        let p_h_safe = self.tensor_add(p_h, eps)?;
        let t_h_safe = self.tensor_add(t_h, eps)?;
        let p_ratio = self.tensor_div(p_w, p_h_safe)?;
        let t_ratio = self.tensor_div(t_w, t_h_safe)?;
        let p_atan = self.tensor_atan(p_ratio)?;
        let t_atan = self.tensor_atan(t_ratio)?;
        let atan_diff = self.tensor_sub(t_atan, p_atan)?;
        let atan_diff_sq = self.tensor_mul(atan_diff, atan_diff)?;
        let four_over_pi_sq = self.full(
            vec![n, 1],
            4.0 / (std::f64::consts::PI * std::f64::consts::PI),
            false,
        )?;
        let v = self.tensor_mul(four_over_pi_sq, atan_diff_sq)?;
        let pred_area = self.tensor_mul(p_w, p_h)?;
        let target_area = self.tensor_mul(t_w, t_h)?;
        let inter_x1 = self.tensor_maximum(p_x1, t_x1)?;
        let inter_y1 = self.tensor_maximum(p_y1, t_y1)?;
        let inter_x2 = self.tensor_minimum(p_x2, t_x2)?;
        let inter_y2 = self.tensor_minimum(p_y2, t_y2)?;
        let inter_w = self.tensor_sub(inter_x2, inter_x1)?;
        let inter_h = self.tensor_sub(inter_y2, inter_y1)?;
        let zero = self.full(vec![n, 1], 0.0, false)?;
        let inter_w = self.tensor_maximum(inter_w, zero)?;
        let inter_h = self.tensor_maximum(inter_h, zero)?;
        let inter_area = self.tensor_mul(inter_w, inter_h)?;
        let union_area = self.tensor_add(pred_area, target_area)?;
        let union_area = self.tensor_sub(union_area, inter_area)?;
        let union_safe = self.tensor_add(union_area, eps)?;
        let iou = self.tensor_div(inter_area, union_safe)?;
        let two = self.full(vec![n, 1], 2.0, false)?;
        let p_cx = self.tensor_add(p_x1, p_x2)?;
        let p_cx = self.tensor_div(p_cx, two)?;
        let p_cy = self.tensor_add(p_y1, p_y2)?;
        let p_cy = self.tensor_div(p_cy, two)?;
        let t_cx = self.tensor_add(t_x1, t_x2)?;
        let t_cx = self.tensor_div(t_cx, two)?;
        let t_cy = self.tensor_add(t_y1, t_y2)?;
        let t_cy = self.tensor_div(t_cy, two)?;
        let dx = self.tensor_sub(p_cx, t_cx)?;
        let dy = self.tensor_sub(p_cy, t_cy)?;
        let dx_sq = self.tensor_mul(dx, dx)?;
        let dy_sq = self.tensor_mul(dy, dy)?;
        let rho_sq = self.tensor_add(dx_sq, dy_sq)?;
        let enc_x1 = self.tensor_minimum(p_x1, t_x1)?;
        let enc_y1 = self.tensor_minimum(p_y1, t_y1)?;
        let enc_x2 = self.tensor_maximum(p_x2, t_x2)?;
        let enc_y2 = self.tensor_maximum(p_y2, t_y2)?;
        let enc_w = self.tensor_sub(enc_x2, enc_x1)?;
        let enc_h = self.tensor_sub(enc_y2, enc_y1)?;
        let enc_w_sq = self.tensor_mul(enc_w, enc_w)?;
        let enc_h_sq = self.tensor_mul(enc_h, enc_h)?;
        let c_sq = self.tensor_add(enc_w_sq, enc_h_sq)?;
        let c_sq_safe = self.tensor_add(c_sq, eps)?;
        let center_penalty = self.tensor_div(rho_sq, c_sq_safe)?;
        let one = self.full(vec![n, 1], 1.0, false)?;
        let one_minus_iou = self.tensor_sub(one, iou)?;
        let one_minus_iou_v = self.tensor_add(one_minus_iou, v)?;
        let one_minus_iou_v_safe = self.tensor_add(one_minus_iou_v, eps)?;
        let alpha = self.tensor_div(v, one_minus_iou_v_safe)?;
        let alpha_v = self.tensor_mul(alpha, v)?;
        let ciou = self.tensor_sub(iou, center_penalty)?;
        let ciou = self.tensor_sub(ciou, alpha_v)?;
        let loss = self.tensor_sub(one, ciou)?;
        self.tensor_mean(loss)
    }

    /// ROI Align: extract fixed-size feature maps from regions of interest.
    ///
    /// Used in Mask R-CNN and modern detection architectures.
    /// Uses bilinear interpolation for sub-pixel sampling.
    ///
    /// Args:
    /// - features: [N, C, H, W] input feature map
    /// - boxes: [K, 5] boxes in format (batch_idx, x1, y1, x2, y2), normalized [0, 1]
    /// - output_size: (height, width) of output feature maps
    /// - spatial_scale: scale factor mapping input coords to feature map coords
    /// - sampling_ratio: number of sampling points per bin (0 = adaptive)
    ///
    /// Returns: [K, C, output_h, output_w] extracted features
    pub fn roi_align(
        &mut self,
        features: TensorNodeId,
        boxes: TensorNodeId,
        output_size: (usize, usize),
        spatial_scale: f64,
        sampling_ratio: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let feat_shape = self.tensor_shape(features)?;
        let box_shape = self.tensor_shape(boxes)?;
        if feat_shape.len() != 4 {
            return Err(Self::incompatible_tensor_args(
                "roi_align: features must be [N, C, H, W]",
            ));
        }
        if box_shape.len() != 2 || box_shape[1] != 5 {
            return Err(Self::incompatible_tensor_args(
                "roi_align: boxes must be [K, 5] with (batch_idx, x1, y1, x2, y2)",
            ));
        }
        let c = feat_shape[1];
        let h = feat_shape[2];
        let w = feat_shape[3];
        let k = box_shape[0];
        let (out_h, out_w) = output_size;
        let feat_data = self.tensor_values_lossy_f64(features)?;
        let box_data = self.tensor_values_lossy_f64(boxes)?;
        let mut output = vec![0.0; k * c * out_h * out_w];
        let sample_pts = if sampling_ratio == 0 {
            2
        } else {
            sampling_ratio
        };
        // Every output element [roi_idx, ch, ph, pw] is an INDEPENDENT bilinear-
        // sampled average, so compute each via one closure and parallelize over the
        // flat output index. Bit-identical to the serial nested loops: the per-output
        // (iy, ix) accumulation order is unchanged and the box params are the same
        // f64 values (recomputed per output — cheap vs the sample_pts^2 taps). The
        // parallel path only changes the OUTER iteration order over disjoint slots.
        let cohw = c * out_h * out_w;
        let ohw = out_h * out_w;
        let compute = |out_idx: usize| -> f64 {
            let roi_idx = out_idx / cohw;
            let rem = out_idx % cohw;
            let ch = rem / ohw;
            let rem2 = rem % ohw;
            let ph = rem2 / out_w;
            let pw = rem2 % out_w;
            let batch_idx = box_data[roi_idx * 5] as usize;
            let x1 = box_data[roi_idx * 5 + 1] * spatial_scale;
            let y1 = box_data[roi_idx * 5 + 2] * spatial_scale;
            let x2 = box_data[roi_idx * 5 + 3] * spatial_scale;
            let y2 = box_data[roi_idx * 5 + 4] * spatial_scale;
            let roi_w = (x2 - x1).max(1e-6);
            let roi_h = (y2 - y1).max(1e-6);
            let bin_w = roi_w / out_w as f64;
            let bin_h = roi_h / out_h as f64;
            let mut sum = 0.0;
            let mut count = 0;
            for iy in 0..sample_pts {
                for ix in 0..sample_pts {
                    let y = y1 + bin_h * (ph as f64 + (iy as f64 + 0.5) / sample_pts as f64);
                    let x = x1 + bin_w * (pw as f64 + (ix as f64 + 0.5) / sample_pts as f64);
                    if y >= 0.0 && y < h as f64 && x >= 0.0 && x < w as f64 {
                        let y_low = y.floor() as usize;
                        let x_low = x.floor() as usize;
                        let y_high = (y_low + 1).min(h - 1);
                        let x_high = (x_low + 1).min(w - 1);
                        let ly = y - y.floor();
                        let lx = x - x.floor();
                        let hy = 1.0 - ly;
                        let hx = 1.0 - lx;
                        let base = batch_idx * c * h * w + ch * h * w;
                        let v1 = feat_data[base + y_low * w + x_low];
                        let v2 = feat_data[base + y_low * w + x_high];
                        let v3 = feat_data[base + y_high * w + x_low];
                        let v4 = feat_data[base + y_high * w + x_high];
                        sum += hy * hx * v1 + hy * lx * v2 + ly * hx * v3 + ly * lx * v4;
                        count += 1;
                    }
                }
            }
            if count > 0 { sum / count as f64 } else { 0.0 }
        };
        const ROI_ALIGN_PARALLEL_MIN: usize = 1 << 12;
        if output.len() >= ROI_ALIGN_PARALLEL_MIN {
            use rayon::prelude::*;
            output
                .par_iter_mut()
                .enumerate()
                .for_each(|(out_idx, slot)| *slot = compute(out_idx));
        } else {
            for (out_idx, slot) in output.iter_mut().enumerate() {
                *slot = compute(out_idx);
            }
        }
        let out = self.tensor_variable(output, vec![k, c, out_h, out_w], false)?;
        // Preserve features dtype (torch roi ops on f32 -> f32); reads above use lossy_f64 so
        // f32 features/boxes no longer crash. frankentorch-fk5l.
        match self.tensor_dtype(features)? {
            dt @ (DType::F32 | DType::F16 | DType::BF16) => self.tensor_tape.to_dtype(out, dt),
            _ => Ok(out),
        }
    }

    /// ROI Pool: extract fixed-size feature maps using max pooling.
    ///
    /// Original operation from Faster R-CNN. For better gradients,
    /// prefer roi_align which uses bilinear interpolation.
    ///
    /// Args:
    /// - features: [N, C, H, W] input feature map
    /// - boxes: [K, 5] boxes in format (batch_idx, x1, y1, x2, y2)
    /// - output_size: (height, width) of output feature maps
    /// - spatial_scale: scale factor mapping input coords to feature map coords
    ///
    /// Returns: [K, C, output_h, output_w] extracted features
    pub fn roi_pool(
        &mut self,
        features: TensorNodeId,
        boxes: TensorNodeId,
        output_size: (usize, usize),
        spatial_scale: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let feat_shape = self.tensor_shape(features)?;
        let box_shape = self.tensor_shape(boxes)?;
        if feat_shape.len() != 4 {
            return Err(Self::incompatible_tensor_args(
                "roi_pool: features must be [N, C, H, W]",
            ));
        }
        if box_shape.len() != 2 || box_shape[1] != 5 {
            return Err(Self::incompatible_tensor_args(
                "roi_pool: boxes must be [K, 5] with (batch_idx, x1, y1, x2, y2)",
            ));
        }
        let c = feat_shape[1];
        let h = feat_shape[2];
        let w = feat_shape[3];
        let k = box_shape[0];
        let (out_h, out_w) = output_size;
        let feat_data = self.tensor_values_lossy_f64(features)?;
        let box_data = self.tensor_values_lossy_f64(boxes)?;
        let mut output = vec![f64::NEG_INFINITY; k * c * out_h * out_w];
        // Each output element [roi_idx, ch, ph, pw] is an independent max over a
        // window, so compute each via one closure and parallelize over the flat
        // output. max() returns an exact element (no rounding), so it is
        // order-independent -> bit-identical to the serial nested loops; only the
        // outer iteration order changes.
        let cohw = c * out_h * out_w;
        let ohw = out_h * out_w;
        let compute = |out_idx: usize| -> f64 {
            let roi_idx = out_idx / cohw;
            let rem = out_idx % cohw;
            let ch = rem / ohw;
            let rem2 = rem % ohw;
            let ph = rem2 / out_w;
            let pw = rem2 % out_w;
            let batch_idx = box_data[roi_idx * 5] as usize;
            let x1 = (box_data[roi_idx * 5 + 1] * spatial_scale).round() as i64;
            let y1 = (box_data[roi_idx * 5 + 2] * spatial_scale).round() as i64;
            let x2 = (box_data[roi_idx * 5 + 3] * spatial_scale).round() as i64;
            let y2 = (box_data[roi_idx * 5 + 4] * spatial_scale).round() as i64;
            let roi_w = (x2 - x1).max(1) as usize;
            let roi_h = (y2 - y1).max(1) as usize;
            let h_start = (ph * roi_h / out_h) as i64 + y1;
            let h_end = ((ph + 1) * roi_h / out_h) as i64 + y1;
            let w_start = (pw * roi_w / out_w) as i64 + x1;
            let w_end = ((pw + 1) * roi_w / out_w) as i64 + x1;
            let mut max_val = f64::NEG_INFINITY;
            for iy in h_start.max(0)..h_end.min(h as i64) {
                for ix in w_start.max(0)..w_end.min(w as i64) {
                    let idx = batch_idx * c * h * w + ch * h * w + iy as usize * w + ix as usize;
                    max_val = max_val.max(feat_data[idx]);
                }
            }
            if max_val.is_finite() { max_val } else { 0.0 }
        };
        const ROI_POOL_PARALLEL_MIN: usize = 1 << 12;
        if output.len() >= ROI_POOL_PARALLEL_MIN {
            use rayon::prelude::*;
            output
                .par_iter_mut()
                .enumerate()
                .for_each(|(out_idx, slot)| *slot = compute(out_idx));
        } else {
            for (out_idx, slot) in output.iter_mut().enumerate() {
                *slot = compute(out_idx);
            }
        }
        let out = self.tensor_variable(output, vec![k, c, out_h, out_w], false)?;
        // Preserve features dtype (torch roi ops on f32 -> f32); reads above use lossy_f64 so
        // f32 features/boxes no longer crash. frankentorch-fk5l.
        match self.tensor_dtype(features)? {
            dt @ (DType::F32 | DType::F16 | DType::BF16) => self.tensor_tape.to_dtype(out, dt),
            _ => Ok(out),
        }
    }

    /// PS (Position-Sensitive) ROI Pool for R-FCN detection.
    ///
    /// Pools from position-sensitive score maps where different spatial
    /// regions of an ROI pool from different channels.
    ///
    /// Args:
    /// - features: [N, C, H, W] where C = num_classes * output_h * output_w
    /// - boxes: [K, 5] boxes (batch_idx, x1, y1, x2, y2)
    /// - output_size: spatial size of output (same for h and w)
    /// - spatial_scale: scale factor for coordinates
    ///
    /// Returns: [K, num_classes, output_size, output_size]
    pub fn ps_roi_pool(
        &mut self,
        features: TensorNodeId,
        boxes: TensorNodeId,
        output_size: usize,
        spatial_scale: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let feat_shape = self.tensor_shape(features)?;
        let box_shape = self.tensor_shape(boxes)?;
        if feat_shape.len() != 4 {
            return Err(Self::incompatible_tensor_args(
                "ps_roi_pool: features must be [N, C, H, W]",
            ));
        }
        if box_shape.len() != 2 || box_shape[1] != 5 {
            return Err(Self::incompatible_tensor_args(
                "ps_roi_pool: boxes must be [K, 5]",
            ));
        }
        let c = feat_shape[1];
        let h = feat_shape[2];
        let w = feat_shape[3];
        let k = box_shape[0];
        let bins = output_size * output_size;
        if c % bins != 0 {
            return Err(Self::incompatible_tensor_args(
                "ps_roi_pool: C must be divisible by output_size^2",
            ));
        }
        let num_classes = c / bins;
        let feat_data = self.tensor_values_lossy_f64(features)?;
        let box_data = self.tensor_values_lossy_f64(boxes)?;
        let mut output = vec![0.0; k * num_classes * output_size * output_size];
        // Each output element [roi_idx, cls, ph, pw] is an independent average over a
        // position-sensitive window, so compute each via one closure and parallelize
        // over the flat output. Bit-identical to the serial nested loops: the per-output
        // (iy, ix) sum order is unchanged; only the outer iteration order changes.
        let ncoo = num_classes * output_size * output_size;
        let oo = output_size * output_size;
        let compute = |out_idx: usize| -> f64 {
            let roi_idx = out_idx / ncoo;
            let rem = out_idx % ncoo;
            let cls = rem / oo;
            let rem2 = rem % oo;
            let ph = rem2 / output_size;
            let pw = rem2 % output_size;
            let batch_idx = box_data[roi_idx * 5] as usize;
            let x1 = box_data[roi_idx * 5 + 1] * spatial_scale;
            let y1 = box_data[roi_idx * 5 + 2] * spatial_scale;
            let x2 = box_data[roi_idx * 5 + 3] * spatial_scale;
            let y2 = box_data[roi_idx * 5 + 4] * spatial_scale;
            let roi_w = (x2 - x1).max(1e-6);
            let roi_h = (y2 - y1).max(1e-6);
            let bin_w = roi_w / output_size as f64;
            let bin_h = roi_h / output_size as f64;
            let ch = cls * bins + ph * output_size + pw;
            let h_start = (y1 + ph as f64 * bin_h).floor() as i64;
            let h_end = (y1 + (ph + 1) as f64 * bin_h).ceil() as i64;
            let w_start = (x1 + pw as f64 * bin_w).floor() as i64;
            let w_end = (x1 + (pw + 1) as f64 * bin_w).ceil() as i64;
            let mut sum = 0.0;
            let mut count = 0;
            for iy in h_start.max(0)..h_end.min(h as i64) {
                for ix in w_start.max(0)..w_end.min(w as i64) {
                    let idx = batch_idx * c * h * w + ch * h * w + iy as usize * w + ix as usize;
                    sum += feat_data[idx];
                    count += 1;
                }
            }
            if count > 0 { sum / count as f64 } else { 0.0 }
        };
        const PS_ROI_POOL_PARALLEL_MIN: usize = 1 << 12;
        if output.len() >= PS_ROI_POOL_PARALLEL_MIN {
            use rayon::prelude::*;
            output
                .par_iter_mut()
                .enumerate()
                .for_each(|(out_idx, slot)| *slot = compute(out_idx));
        } else {
            for (out_idx, slot) in output.iter_mut().enumerate() {
                *slot = compute(out_idx);
            }
        }
        let out = self.tensor_variable(
            output,
            vec![k, num_classes, output_size, output_size],
            false,
        )?;
        // Preserve features dtype (f32 -> f32); lossy_f64 reads above fixed the f32 crash.
        match self.tensor_dtype(features)? {
            dt @ (DType::F32 | DType::F16 | DType::BF16) => self.tensor_tape.to_dtype(out, dt),
            _ => Ok(out),
        }
    }

    /// Quantile (pinball) loss for quantile regression.
    ///
    /// Computes: `q * max(0, target - pred) + (1-q) * max(0, pred - target)`
    /// where q is the quantile (0 < q < 1). q=0.5 gives median regression.
    pub fn quantile_loss(
        &mut self,
        input: TensorNodeId,
        target: TensorNodeId,
        quantile: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        if !(0.0..=1.0).contains(&quantile) {
            return Err(Self::incompatible_tensor_args(
                "quantile_loss: quantile must be in [0, 1]",
            ));
        }
        let in_shape = self.tensor_shape(input)?;
        let tgt_shape = self.tensor_shape(target)?;
        if in_shape != tgt_shape {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: in_shape.clone(),
                    rhs: tgt_shape,
                },
            )));
        }
        let diff = self.tensor_sub(target, input)?;
        let neg_diff = self.tensor_neg(diff)?;
        let pos_part = self.tensor_clamp_min(diff, 0.0)?;
        let neg_part = self.tensor_clamp_min(neg_diff, 0.0)?;
        // full_like keeps constants in the input dtype (self.full is F64 -> f32 ERRORS on the
        // tensor_mul below); native-f32 compose, bit-identical for f64. frankentorch-fk5l.
        let q_tensor = self.full_like(input, quantile, false)?;
        let one_minus_q = self.full_like(input, 1.0 - quantile, false)?;
        let pos_loss = self.tensor_mul(q_tensor, pos_part)?;
        let neg_loss = self.tensor_mul(one_minus_q, neg_part)?;
        let loss = self.tensor_add(pos_loss, neg_loss)?;
        self.tensor_mean(loss)
    }

    /// Log-cosh loss for regression.
    ///
    /// Computes `mean(log(cosh(pred - target)))`.
    /// Smooth alternative to L1 loss, approximates L1 for large errors
    /// and L2 for small errors. Less sensitive to outliers than MSE.
    pub fn log_cosh_loss(
        &mut self,
        input: TensorNodeId,
        target: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let in_shape = self.tensor_shape(input)?;
        let tgt_shape = self.tensor_shape(target)?;
        if in_shape != tgt_shape {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: in_shape,
                    rhs: tgt_shape,
                },
            )));
        }
        let diff = self.tensor_sub(input, target)?;
        let cosh_diff = self.tensor_cosh(diff)?;
        let log_cosh = self.tensor_log(cosh_diff)?;
        self.tensor_mean(log_cosh)
    }

    /// Mixup data augmentation.
    ///
    /// Performs mixup: `mixed_x = lambda * x1 + (1 - lambda) * x2`
    /// where lambda is sampled from Beta(alpha, alpha).
    /// Returns (mixed_x, lambda) for use with mixed labels.
    pub fn mixup_data(
        &mut self,
        x1: TensorNodeId,
        x2: TensorNodeId,
        alpha: f64,
    ) -> Result<(TensorNodeId, f64), AutogradError> {
        let lambda = if alpha > 0.0 {
            let gamma1 = self.rng.next_gamma(alpha);
            let gamma2 = self.rng.next_gamma(alpha);
            gamma1 / (gamma1 + gamma2)
        } else {
            1.0
        };
        let x1_shape = self.tensor_shape(x1)?;
        let lambda_tensor = self.full(x1_shape.clone(), lambda, false)?;
        let one_minus_lambda = self.full(x1_shape, 1.0 - lambda, false)?;
        let term1 = self.tensor_mul(lambda_tensor, x1)?;
        let term2 = self.tensor_mul(one_minus_lambda, x2)?;
        let mixed = self.tensor_add(term1, term2)?;
        Ok((mixed, lambda))
    }

    /// Cutmix data augmentation.
    ///
    /// Performs cutmix: replaces a random rectangular region of x1 with x2.
    /// Returns (mixed_x, lambda) where lambda is the area ratio (portion from x1).
    /// Input must be 4D [N, C, H, W].
    pub fn cutmix_data(
        &mut self,
        x1: TensorNodeId,
        x2: TensorNodeId,
        alpha: f64,
    ) -> Result<(TensorNodeId, f64), AutogradError> {
        let shape = self.tensor_shape(x1)?;
        if shape.len() != 4 {
            return Err(Self::incompatible_tensor_args(
                "cutmix_data: input must be 4D [N, C, H, W]",
            ));
        }
        let h = shape[2];
        let w = shape[3];
        let lambda = if alpha > 0.0 {
            let gamma1 = self.rng.next_gamma(alpha);
            let gamma2 = self.rng.next_gamma(alpha);
            gamma1 / (gamma1 + gamma2)
        } else {
            1.0
        };
        let cut_ratio = (1.0_f64 - lambda).sqrt();
        let cut_h = (h as f64 * cut_ratio) as usize;
        let cut_w = (w as f64 * cut_ratio) as usize;
        let cy = (self.rng.next_f64() * h as f64) as usize;
        let cx = (self.rng.next_f64() * w as f64) as usize;
        let y1 = cy.saturating_sub(cut_h / 2);
        let y2 = (cy + cut_h / 2).min(h);
        let x1_coord = cx.saturating_sub(cut_w / 2);
        let x2_coord = (cx + cut_w / 2).min(w);
        let actual_lambda = 1.0 - ((y2 - y1) * (x2_coord - x1_coord)) as f64 / (h * w) as f64;
        let mut mask_data = vec![1.0_f64; h * w];
        for row in y1..y2 {
            for col in x1_coord..x2_coord {
                mask_data[row * w + col] = 0.0;
            }
        }
        let mask = self.tensor_variable(mask_data, vec![1, 1, h, w], false)?;
        let ones = self.full(vec![1, 1, h, w], 1.0, false)?;
        let inv_mask = self.tensor_sub(ones, mask)?;
        let term1 = self.tensor_mul(x1, mask)?;
        let term2 = self.tensor_mul(x2, inv_mask)?;
        let mixed = self.tensor_add(term1, term2)?;
        Ok((mixed, actual_lambda))
    }

    /// Poisson negative log likelihood loss.
    ///
    /// Equivalent to `torch.nn.functional.poisson_nll_loss(input, target, log_input, full, eps)`.
    /// When `log_input=true`: `loss = exp(input) - target * input`
    /// When `log_input=false`: `loss = input - target * log(input + eps)`
    pub fn poisson_nll_loss(
        &mut self,
        input: TensorNodeId,
        target: TensorNodeId,
        log_input: bool,
        full: bool,
        eps: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        // Compose through autograd primitives so gradients flow to
        // input (and target — though target is typically constant
        // labels, the formula is differentiable wrt both). Tracked
        // under frankentorch-zl3n (child of frankentorch-2med).
        // Previously this body extracted values, computed the
        // per-element loss in plain f64, built a non-grad leaf,
        // then took tensor_mean — the tensor_mean preserved the tape
        // from there but the prior leaf had already severed it.
        //
        // Math:
        //   log_input=True:   loss_i = exp(input_i) - target_i * input_i
        //   log_input=False:  loss_i = input_i - target_i * log(input_i + eps)
        // Stirling correction (full=true) is a function of target
        // only; it shifts the loss by a target-dependent constant
        // and doesn't affect input gradient.
        let per_elem = if log_input {
            let exp_inp = self.tensor_exp(input)?;
            let tgt_times_inp = self.tensor_mul(target, input)?;
            self.tensor_sub(exp_inp, tgt_times_inp)?
        } else {
            let eps_t = self.full(shape.clone(), eps, false)?;
            let inp_plus_eps = self.tensor_add(input, eps_t)?;
            let log_term = self.tensor_log(inp_plus_eps)?;
            let tgt_times_log = self.tensor_mul(target, log_term)?;
            self.tensor_sub(input, tgt_times_log)?
        };

        let main = self.tensor_mean(per_elem)?;

        if full {
            // Stirling correction depends only on target — compute
            // as a non-grad constant scalar and add to the loss.
            // PyTorch only adds when target > 1 (since for target
            // <= 1 the Stirling approximation is poor; PyTorch uses
            // 0 there). We replicate that.
            let target_vals = self.tensor_values_lossy_f64(target)?;
            let n = target_vals.len() as f64;
            let stirling: f64 = target_vals
                .iter()
                .map(|&t| {
                    if t > 1.0 {
                        t * t.ln() - t + 0.5 * (2.0 * std::f64::consts::PI * t).ln()
                    } else {
                        0.0
                    }
                })
                .sum::<f64>()
                / n;
            let stirling_t = self.full(vec![1], stirling, false)?;
            self.tensor_add(main, stirling_t)
        } else {
            Ok(main)
        }
    }

    /// Gaussian negative log likelihood loss.
    ///
    /// Equivalent to `torch.nn.functional.gaussian_nll_loss(input, target, var, full, eps)`.
    /// `loss = 0.5 * (log(var) + (input - target)^2 / var)`
    /// With `full=true`, adds the constant `0.5 * log(2*pi)`.
    pub fn gaussian_nll_loss(
        &mut self,
        input: TensorNodeId,
        target: TensorNodeId,
        var: TensorNodeId,
        full: bool,
        eps: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        // Compose through autograd primitives so gradients flow to
        // input / target / var. Tracked under frankentorch-vjow
        // (child of frankentorch-2med). Math:
        //   v'      = max(var, eps)
        //   diff    = input - target
        //   loss_i  = 0.5 * (log(v') + diff^2 / v')
        //   loss    = mean(loss_i) [+ 0.5 * log(2π) if full]
        let v_clamped = self.tensor_clamp_min(var, eps)?;
        let log_v = self.tensor_log(v_clamped)?;
        let diff = self.tensor_sub(input, target)?;
        let diff_sq = self.tensor_mul(diff, diff)?;
        let ratio = self.tensor_div(diff_sq, v_clamped)?;
        let sum_term = self.tensor_add(log_v, ratio)?;
        let half = self.full(shape, 0.5, false)?;
        let per_elem = self.tensor_mul(sum_term, half)?;
        let main = self.tensor_mean(per_elem)?;

        if full {
            let const_offset = 0.5 * (2.0 * std::f64::consts::PI).ln();
            let offset_t = self.full(vec![1], const_offset, false)?;
            self.tensor_add(main, offset_t)
        } else {
            Ok(main)
        }
    }

    /// Soft margin loss.
    ///
    /// Equivalent to `torch.nn.functional.soft_margin_loss(input, target)`.
    /// `loss = mean(log(1 + exp(-target * input)))`
    pub fn soft_margin_loss(
        &mut self,
        input: TensorNodeId,
        target: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // Compose through autograd-aware primitives so gradients flow
        // to input (target is typically constant ±1 but the formula
        // treats it as a tensor for full generality).
        // Math: with z = -t * x,
        //     soft_margin = log1p(exp(z))
        //                 = max(0, z) + log1p(exp(-|z|))
        //                 = relu(z) + log1p(exp(-abs(z)))
        // Same numerical-stability form as the prior body. Tracked
        // under frankentorch-tr2a — previously this body extracted
        // values, computed the per-element loss in plain f64, and
        // built a requires_grad=false leaf, silently severing the
        // tape.
        let neg_target = self.tensor_neg(target)?;
        let z = self.tensor_mul(neg_target, input)?;
        let relu_z = self.tensor_relu(z)?;
        let abs_z = self.tensor_abs(z)?;
        let neg_abs_z = self.tensor_neg(abs_z)?;
        let exp_neg_abs = self.tensor_exp(neg_abs_z)?;
        let log_term = self.tensor_log1p(exp_neg_abs)?;
        let loss_per_elem = self.tensor_add(relu_z, log_term)?;
        self.tensor_mean(loss_per_elem)
    }

    /// Multi-class margin (hinge) loss.
    ///
    /// Equivalent to `torch.nn.functional.multi_margin_loss(input, target, p, margin)`.
    /// `loss = mean(max(0, margin - input[y] + input[j])^p for j != y)`
    pub fn multi_margin_loss(
        &mut self,
        input: TensorNodeId,
        target: TensorNodeId,
        p: f64,
        margin: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let make_err = |reason: &'static str| {
            AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet { reason },
            ))
        };

        let p_bits = p.to_bits();
        if ![1.0_f64.to_bits(), 2.0_f64.to_bits()].contains(&p_bits) {
            return Err(make_err("multi_margin_loss: p must be 1 or 2"));
        }

        let shape = self.tensor_shape(input)?;
        if shape.len() != 2 {
            return Err(make_err(
                "multi_margin_loss: input must be 2-D [batch, classes]",
            ));
        }
        let (batch, classes) = (shape[0], shape[1]);
        if classes < 1 {
            return Err(make_err(
                "multi_margin_loss: class dimension must be greater than zero",
            ));
        }

        // f32 inputs ERRORED (UnsupportedDType(F32)): the compose below mixes `input` (F32)
        // with `one_hot(target)` + `self.full()` constants (F64) in tensor_mul/tensor_sub,
        // whose mixed-dtype path reads the f32 operand via an F64-only accessor and crashes
        // (torch.nn.functional.multi_margin_loss(f32) -> f32). Compute in f64 (upcast the small
        // [batch,classes] input + target, exact) then narrow the scalar loss back to f32.
        // to_dtype is grad-aware (CastF64/CastF32 nodes), so gradients still flow to the f32
        // input. frankentorch-fk5l.
        if self.tensor_dtype(input)? == DType::F32 {
            let in64 = self.tensor_to_dtype(input, DType::F64)?;
            let tgt64 = self.tensor_to_dtype(target, DType::F64)?;
            let loss64 = self.multi_margin_loss(in64, tgt64, p, margin)?;
            return self.tensor_to_dtype(loss64, DType::F32);
        }

        // Compose through autograd primitives. The forward formula is
        //     loss = mean over batch of [sum_{j != y_i} relu(margin - x[i, y_i] + x[i, j])^p / classes]
        // We assemble it as
        //   mask_y       = one_hot(target, classes)              [batch, classes]
        //   mask_others  = 1 - mask_y                            [batch, classes]
        //   score_y_b    = expand(unsqueeze(sum(x * mask_y, 1)), [batch, classes])
        //   diff         = (margin scalar) + (x - score_y_b)
        //   per_elem     = relu(diff) * mask_others              (zero at j == y)
        //   per_elem_p   = per_elem^p
        //   per_sample   = sum(per_elem_p, dim=1) / classes
        //   loss         = mean(per_sample)
        // All ops are autograd-aware. Tracked under frankentorch-x9cr —
        // previously this body extracted values, computed the
        // accumulator in plain f64, and rebuilt a non-grad leaf.
        //
        // one_hot validates that target entries are finite non-negative
        // integer indices in [0, classes), so we don't need a manual
        // pre-check.
        let mask_y = self.one_hot(target, classes)?;
        let ones = self.full(vec![batch, classes], 1.0, false)?;
        let mask_others = self.tensor_sub(ones, mask_y)?;

        let score_y_per_elem = self.tensor_mul(input, mask_y)?;
        let score_y = self.tensor_sum_dim(score_y_per_elem, 1)?; // [batch]
        let score_y_kd = self.tensor_unsqueeze(score_y, 1)?; // [batch, 1]
        let score_y_b = self.tensor_expand(score_y_kd, vec![batch, classes])?;

        let margin_t = self.full(vec![batch, classes], margin, false)?;
        let x_minus_y = self.tensor_sub(input, score_y_b)?;
        let diff = self.tensor_add(x_minus_y, margin_t)?;

        let clamped = self.tensor_relu(diff)?;
        let masked = self.tensor_mul(clamped, mask_others)?;

        let powered = self.tensor_pow(masked, p)?;

        let per_sample_sum = self.tensor_sum_dim(powered, 1)?; // [batch]
        let classes_t = self.full(vec![batch], classes as f64, false)?;
        let per_sample = self.tensor_div(per_sample_sum, classes_t)?;
        self.tensor_mean(per_sample)
    }

    /// Multi-label soft margin loss.
    ///
    /// Equivalent to `torch.nn.functional.multilabel_soft_margin_loss(input, target)`.
    /// `loss = -mean(target * log(sigmoid(input)) + (1 - target) * log(1 - sigmoid(input)))`
    pub fn multilabel_soft_margin_loss(
        &mut self,
        input: TensorNodeId,
        target: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        if shape.len() != 2 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "multilabel_soft_margin_loss: input must be 2-D [batch, classes]",
                },
            )));
        }

        // For a 2-D input [batch, classes] the per-element BCE-with-
        // logits formula
        //     bce(x, t) = max(x, 0) - x*t + log1p(exp(-|x|))
        // averaged over both dims yields mean over all (i, j) of bce —
        // exactly what bce_with_logits_loss computes via composition
        // through autograd primitives. Delegating preserves the
        // numerical-stability log1p(exp(-|x|)) form while keeping
        // the autograd tape intact. Tracked under frankentorch-4liu.
        // Previously this body extracted values, computed the
        // accumulator in plain f64, and rebuilt a non-grad leaf —
        // silently severing the tape.
        self.bce_with_logits_loss(input, target)
    }

    /// Negative log likelihood loss.
    ///
    /// Expects `log_probs` to be log-probabilities of shape [batch, classes] and
    /// `targets` to be class indices of shape [batch] (as f64 values that will be
    /// cast to usize). Returns the mean NLL loss.
    ///
    /// NLL(x, y) = -mean(log_probs[i, targets[i]] for i in batch)
    pub fn nll_loss(
        &mut self,
        log_probs: TensorNodeId,
        targets: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let log_prob_shape = self.tensor_shape(log_probs)?;
        let target_shape = self.tensor_shape(targets)?;
        let target_vals = self.tensor_values(targets)?;

        if log_prob_shape.len() != 2 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "nll_loss expects 2-D log_probs [batch, classes]",
                },
            )));
        }

        let batch_size = log_prob_shape[0];
        let num_classes = log_prob_shape[1];

        if target_shape.len() != 1
            || target_shape[0] != batch_size
            || target_vals.len() != batch_size
        {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "nll_loss expects targets shape [batch] matching log_probs batch",
                },
            )));
        }

        // Validate target indices
        for &target in &target_vals {
            let cls = Self::exact_nonnegative_index_to_usize(
                target,
                "nll_loss targets must be finite non-negative integer indices",
            )?;
            if cls >= num_classes {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "nll_loss target index out of bounds",
                    },
                )));
            }
        }

        // Build index tensor of shape [batch_size, 1] for gather along dim=1
        let index = self.tensor_variable(target_vals, vec![batch_size, 1], false)?;

        // Gather log-probabilities at target indices (autograd-tracked)
        let gathered = self.tensor_gather(log_probs, 1, index)?;

        // NLL = -mean(gathered log-probabilities)
        let neg_gathered = self.tensor_neg(gathered)?;
        self.tensor_mean(neg_gathered)
    }

    /// Conditional selection: `torch.where(condition, x, y)`.
    ///
    /// Selects elements from `x` where `condition != 0.0` and from `y` otherwise.
    /// All three tensors must have the same shape. Gradients flow to `x` and `y`
    /// but not to `condition`.
    pub fn tensor_where(
        &mut self,
        condition: TensorNodeId,
        x: TensorNodeId,
        y: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // torch.where broadcasts condition, x, and y together. The tape op
        // requires identical shapes, so equal shapes take the fast path and
        // anything broadcastable is first expanded to the common shape (a
        // non-broadcastable mismatch still errors, via broadcast_shape).
        let cond_shape = self.tensor_shape(condition)?;
        let x_shape = self.tensor_shape(x)?;
        let y_shape = self.tensor_shape(y)?;
        if cond_shape == x_shape && x_shape == y_shape {
            // No-grad fast path: the tape where clones cond/x/y + builds nodes + saves for
            // backward (~18x slower than torch's vectorized select). With grad off, borrow
            // all three contiguous f64 buffers and select directly in parallel. Bit-exact
            // (truthy == nonzero, matching the kernel). Non-f64 / non-contiguous / grad
            // fall through to the tape op.
            if !self.tensor_requires_grad(condition)?
                && !self.tensor_requires_grad(x)?
                && !self.tensor_requires_grad(y)?
                && self.tensor_dtype(condition)? == DType::F64
                && self.tensor_dtype(x)? == DType::F64
                && self.tensor_dtype(y)? == DType::F64
            {
                let built = {
                    let ct = self.tensor_tape.tensor(condition)?;
                    let xt = self.tensor_tape.tensor(x)?;
                    let yt = self.tensor_tape.tensor(y)?;
                    if ct.meta().is_contiguous()
                        && xt.meta().is_contiguous()
                        && yt.meta().is_contiguous()
                    {
                        use rayon::prelude::*;
                        let cd = ct.contiguous_values()?;
                        let xd = xt.contiguous_values()?;
                        let yd = yt.contiguous_values()?;
                        if cd.len() == xd.len() && xd.len() == yd.len() {
                            let out: Vec<f64> = (0..cd.len())
                                .into_par_iter()
                                .map(|i| if cd[i] != 0.0 { xd[i] } else { yd[i] })
                                .collect();
                            Some(out)
                        } else {
                            None
                        }
                    } else {
                        None
                    }
                };
                if let Some(out) = built {
                    return self.tensor_variable(out, x_shape, false);
                }
            }
            // F32 mirror of the f64 fast path above (where was F64-only → f32 fell through to the
            // tape clone path, ~24x SLOWER vs torch). Borrow the contiguous f32 buffers + parallel
            // select. Bit-exact (truthy == nonzero).
            if !self.tensor_requires_grad(condition)?
                && !self.tensor_requires_grad(x)?
                && !self.tensor_requires_grad(y)?
                && self.tensor_dtype(condition)? == DType::F32
                && self.tensor_dtype(x)? == DType::F32
                && self.tensor_dtype(y)? == DType::F32
            {
                let built = {
                    let ct = self.tensor_tape.tensor(condition)?;
                    let xt = self.tensor_tape.tensor(x)?;
                    let yt = self.tensor_tape.tensor(y)?;
                    if ct.meta().is_contiguous()
                        && xt.meta().is_contiguous()
                        && yt.meta().is_contiguous()
                    {
                        use rayon::prelude::*;
                        let cd = ct.contiguous_values_f32()?;
                        let xd = xt.contiguous_values_f32()?;
                        let yd = yt.contiguous_values_f32()?;
                        if cd.len() == xd.len() && xd.len() == yd.len() {
                            let out: Vec<f32> = (0..cd.len())
                                .into_par_iter()
                                .map(|i| if cd[i] != 0.0 { xd[i] } else { yd[i] })
                                .collect();
                            Some(out)
                        } else {
                            None
                        }
                    } else {
                        None
                    }
                };
                if let Some(out) = built {
                    return self.tensor_variable_f32(out, x_shape, false);
                }
            }
            return self.tensor_tape.tensor_where(condition, x, y);
        }
        if let Some(out) = self.try_where_one_scalar(condition, x, y)? {
            return Ok(out);
        }
        if let Some(out) = self.try_where_cond_tile_two(condition, x, y)? {
            return Ok(out);
        }
        let out_shape = Self::broadcast_shape(&cond_shape, &x_shape)?;
        let out_shape = Self::broadcast_shape(&out_shape, &y_shape)?;
        let cb = self.tensor_broadcast_to(condition, out_shape.clone())?;
        let xb = self.tensor_broadcast_to(x, out_shape.clone())?;
        let yb = self.tensor_broadcast_to(y, out_shape)?;
        self.tensor_tape.tensor_where(cb, xb, yb)
    }

    /// Plan for a broadcast `cond`/`mask` (shape `cs`) tiling into `out_shape`: right-align `cs` to
    /// out and require every dim to be 1 (broadcast) or equal (else `None` = non-broadcastable). Covers
    /// trailing tiles ([1,1,S,S]/[S,S]) AND MIDDLE/leading broadcasts (key-padding [B,1,1,S]). Returns
    /// `(inner, outer, block, rows_per_task)` where `inner` = length of the trailing contiguous
    /// non-broadcast run (advances with the output), `outer` = per outer-dim `(radix = out size,
    /// contrib = cond contiguous stride if non-broadcast else 0)`, and the per-row cond offset is
    /// `mbase(row) = sum over outer.rev() of (row % radix) * contrib` (advancing `row /= radix`).
    /// `block`/`rows_per_task` decouple parallel granularity from a small `inner` (block ~32K elems).
    fn broadcast_offset_plan(
        cs: &[usize],
        out_shape: &[usize],
    ) -> Option<(usize, Vec<(usize, usize)>, usize, usize)> {
        let r = out_shape.len();
        if cs.len() > r {
            return None;
        }
        let mut ma = vec![1usize; r];
        for (k, &d) in cs.iter().enumerate() {
            ma[r - cs.len() + k] = d;
        }
        for d in 0..r {
            if ma[d] != 1 && ma[d] != out_shape[d] {
                return None;
            }
        }
        let mut mstride = vec![0usize; r];
        let mut acc = 1usize;
        for d in (0..r).rev() {
            mstride[d] = acc;
            acc *= ma[d];
        }
        let mut run = 0usize;
        let mut inner = 1usize;
        for d in (0..r).rev() {
            if ma[d] == out_shape[d] && ma[d] != 1 {
                run += 1;
                inner *= out_shape[d];
            } else {
                break;
            }
        }
        let n: usize = out_shape.iter().product();
        if inner == 0 || n == 0 || n % inner != 0 {
            return None;
        }
        let outer_len = r - run;
        let outer: Vec<(usize, usize)> = (0..outer_len)
            .map(|d| (out_shape[d], if ma[d] == 1 { 0 } else { mstride[d] }))
            .collect();
        let rows_per_task = (32_768 / inner).max(1);
        let block = rows_per_task * inner;
        Some((inner, outer, block, rows_per_task))
    }

    /// No-grad fused `where(cond, x, y)` when `cond` broadcasts into the ONE full-size operand and the
    /// OTHER operand is a scalar (numel 1) — the masking pattern `where(mask, scores, -inf)` /
    /// `where(mask, fill, scores)`. Covers ANY broadcast cond: the causal tile [1,1,S,S] AND the
    /// key-padding [B,1,1,S]/[B,1,S,S] (MIDDLE/leading broadcast) via `broadcast_offset_plan`. The
    /// generic fallthrough `broadcast_to`s all THREE operands to the common shape (materializing the
    /// scalar plus clones) then selects; here we select in ONE pass with no expand (per output row,
    /// cond offset from the plan). Bit-identical (truthy == nonzero, matching the same-shape fast
    /// path). f32/f64, contiguous, no-grad, all-same-dtype; everything else falls through.
    fn try_where_one_scalar(
        &mut self,
        condition: TensorNodeId,
        x: TensorNodeId,
        y: TensorNodeId,
    ) -> Result<Option<TensorNodeId>, AutogradError> {
        if self.tensor_requires_grad(condition)?
            || self.tensor_requires_grad(x)?
            || self.tensor_requires_grad(y)?
        {
            return Ok(None);
        }
        let dtype = self.tensor_dtype(condition)?;
        if self.tensor_dtype(x)? != dtype || self.tensor_dtype(y)? != dtype {
            return Ok(None);
        }
        let cs = self.tensor_shape(condition)?;
        let xs = self.tensor_shape(x)?;
        let ys = self.tensor_shape(y)?;
        let numel = |s: &[usize]| s.iter().product::<usize>();
        // The OTHER (non-cond-matched) operand is a single scalar; the full operand has > 1 elem.
        let (full, scal, out_shape, x_is_full) = if numel(&ys) == 1 && numel(&xs) > 1 {
            (x, y, xs.clone(), true)
        } else if numel(&xs) == 1 && numel(&ys) > 1 {
            (y, x, ys.clone(), false)
        } else {
            return Ok(None);
        };
        // `cond` must broadcast into the full operand's shape (ANY broadcast: causal tile [1,1,S,S] or
        // key-padding [B,1,1,S]); the plan gives the trailing contiguous run + per-row cond offset.
        let (inner, outer, block, rows_per_task) =
            match Self::broadcast_offset_plan(&cs, &out_shape) {
                Some(p) => p,
                None => return Ok(None),
            };
        let cinner = numel(&cs);
        let n = numel(&out_shape);
        macro_rules! fused {
            ($read:ident, $build:ident, $ty:ty) => {{
                let built = {
                    let ct = self.tensor_tape.tensor(condition)?;
                    let ft = self.tensor_tape.tensor(full)?;
                    let st = self.tensor_tape.tensor(scal)?;
                    if ct.meta().is_contiguous() && ft.meta().is_contiguous() && st.meta().is_contiguous()
                    {
                        let cd = ct.$read()?;
                        let fd = ft.$read()?;
                        let sd = st.$read()?;
                        if cd.len() == cinner && fd.len() == n && sd.len() == 1 {
                            let s = sd[0];
                            use rayon::prelude::*;
                            let mbase = |mut row: usize| -> usize {
                                let mut base = 0usize;
                                for &(radix, contrib) in outer.iter().rev() {
                                    let idx = row % radix;
                                    row /= radix;
                                    base += idx * contrib;
                                }
                                base
                            };
                            // per output row, read `inner` cond elems from the plan's block offset;
                            // take the full operand when (cond truthy) matches which branch is full.
                            let fill = |row: usize, oc: &mut [$ty], fc: &[$ty]| {
                                let crow = &cd[mbase(row)..mbase(row) + inner];
                                for j in 0..inner {
                                    oc[j] = if (crow[j] != (0 as $ty)) == x_is_full {
                                        fc[j]
                                    } else {
                                        s
                                    };
                                }
                            };
                            let mut out = vec![0 as $ty; n];
                            if n >= PARALLEL_ELEMENTWISE_MIN {
                                out.par_chunks_mut(block)
                                    .zip(fd.par_chunks(block))
                                    .enumerate()
                                    .for_each(|(t, (ochunk, fchunk))| {
                                        let rb = t * rows_per_task;
                                        for (rr, (oc, fc)) in ochunk
                                            .chunks_mut(inner)
                                            .zip(fchunk.chunks(inner))
                                            .enumerate()
                                        {
                                            fill(rb + rr, oc, fc);
                                        }
                                    });
                            } else {
                                out.chunks_mut(inner)
                                    .zip(fd.chunks(inner))
                                    .enumerate()
                                    .for_each(|(row, (oc, fc))| fill(row, oc, fc));
                            }
                            Some(out)
                        } else {
                            None
                        }
                    } else {
                        None
                    }
                };
                match built {
                    Some(out) => Ok(Some(self.$build(out, out_shape.clone(), false)?)),
                    None => Ok(None),
                }
            }};
        }
        match dtype {
            DType::F64 => fused!(contiguous_values, tensor_variable, f64),
            DType::F32 => fused!(contiguous_values_f32, tensor_variable_f32, f32),
            _ => Ok(None),
        }
    }

    /// No-grad fused `where(cond, x, y)` when BOTH branches are the same full-size tensor and `cond`
    /// broadcasts into that shape (ANY broadcast: causal tile [1,1,S,S] or key-padding [B,1,1,S]) —
    /// `where(mask, a [B,H,S,S], b [B,H,S,S])`, i.e. select between two full score tensors with an
    /// attention-style broadcast mask. The generic fallthrough `broadcast_to`s the small mask to the
    /// full shape (materializing the 65536->8.4M tile) then the tape `where` clones all three + builds
    /// nodes; here we select in ONE pass (per output row, cond offset from `broadcast_offset_plan`),
    /// no expand. Sibling of `try_where_one_scalar` (that handles the y/x-scalar case). Bit-identical
    /// to the same-shape fast path (truthy == nonzero). f32/f64, contiguous, no-grad, x and y the SAME
    /// full shape; everything else falls through.
    fn try_where_cond_tile_two(
        &mut self,
        condition: TensorNodeId,
        x: TensorNodeId,
        y: TensorNodeId,
    ) -> Result<Option<TensorNodeId>, AutogradError> {
        if self.tensor_requires_grad(condition)?
            || self.tensor_requires_grad(x)?
            || self.tensor_requires_grad(y)?
        {
            return Ok(None);
        }
        let dtype = self.tensor_dtype(condition)?;
        if self.tensor_dtype(x)? != dtype || self.tensor_dtype(y)? != dtype {
            return Ok(None);
        }
        let cs = self.tensor_shape(condition)?;
        let xs = self.tensor_shape(x)?;
        let ys = self.tensor_shape(y)?;
        // Both branches must be the SAME full shape (a y/x-scalar or non-scalar-broadcast branch is
        // handled by try_where_one_scalar / falls through). cond != x_shape here (equal-shape took the
        // fast path in tensor_where already).
        if xs != ys {
            return Ok(None);
        }
        // `cond` must broadcast into the full shape (ANY broadcast: causal tile [1,1,S,S]/[S,S] or
        // key-padding [B,1,1,S]/[B,1,S,S]); the plan gives the trailing contiguous run + per-row cond
        // offset. Non-broadcastable cond falls through.
        let (inner, outer, block, rows_per_task) = match Self::broadcast_offset_plan(&cs, &xs) {
            Some(p) => p,
            None => return Ok(None),
        };
        let cinner: usize = cs.iter().product();
        let n: usize = xs.iter().product();
        if n <= 1 {
            return Ok(None);
        }
        macro_rules! fused {
            ($read:ident, $build:ident, $ty:ty) => {{
                let built = {
                    let ct = self.tensor_tape.tensor(condition)?;
                    let xt = self.tensor_tape.tensor(x)?;
                    let yt = self.tensor_tape.tensor(y)?;
                    if ct.meta().is_contiguous()
                        && xt.meta().is_contiguous()
                        && yt.meta().is_contiguous()
                    {
                        let cd = ct.$read()?;
                        let xd = xt.$read()?;
                        let yd = yt.$read()?;
                        if cd.len() == cinner && xd.len() == n && yd.len() == n {
                            use rayon::prelude::*;
                            let mbase = |mut row: usize| -> usize {
                                let mut base = 0usize;
                                for &(radix, contrib) in outer.iter().rev() {
                                    let idx = row % radix;
                                    row /= radix;
                                    base += idx * contrib;
                                }
                                base
                            };
                            // per output row, read `inner` cond elems from the plan's block offset;
                            // out[k] = cond[mbase(row)+j] != 0 ? x[k] : y[k].
                            let fill = |row: usize, oc: &mut [$ty], xc: &[$ty], yc: &[$ty]| {
                                let crow = &cd[mbase(row)..mbase(row) + inner];
                                for j in 0..inner {
                                    oc[j] = if crow[j] != (0 as $ty) { xc[j] } else { yc[j] };
                                }
                            };
                            let mut out = vec![0 as $ty; n];
                            if n >= PARALLEL_ELEMENTWISE_MIN {
                                out.par_chunks_mut(block)
                                    .zip(xd.par_chunks(block))
                                    .zip(yd.par_chunks(block))
                                    .enumerate()
                                    .for_each(|(t, ((ochunk, xchunk), ychunk))| {
                                        let rb = t * rows_per_task;
                                        for (rr, ((oc, xc), yc)) in ochunk
                                            .chunks_mut(inner)
                                            .zip(xchunk.chunks(inner))
                                            .zip(ychunk.chunks(inner))
                                            .enumerate()
                                        {
                                            fill(rb + rr, oc, xc, yc);
                                        }
                                    });
                            } else {
                                out.chunks_mut(inner)
                                    .zip(xd.chunks(inner))
                                    .zip(yd.chunks(inner))
                                    .enumerate()
                                    .for_each(|(row, ((oc, xc), yc))| fill(row, oc, xc, yc));
                            }
                            Some(out)
                        } else {
                            None
                        }
                    } else {
                        None
                    }
                };
                match built {
                    Some(out) => Ok(Some(self.$build(out, xs.clone(), false)?)),
                    None => Ok(None),
                }
            }};
        }
        match dtype {
            DType::F64 => fused!(contiguous_values, tensor_variable, f64),
            DType::F32 => fused!(contiguous_values_f32, tensor_variable_f32, f32),
            _ => Ok(None),
        }
    }

    /// `torch.where(condition, x, y)` with scalar branches — selects the scalar
    /// `x` where `condition` is truthy, else `y`, over `condition`'s shape.
    /// (For tensor branches with broadcasting, use [`Self::tensor_where`].)
    pub fn tensor_where_scalar(
        &mut self,
        condition: TensorNodeId,
        x: f64,
        y: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(condition)?;
        // No-grad fast path: the composition below builds TWO full() tensors [F64, 2×numel allocs]
        // + a tensor_where = 3 passes. For a contiguous f32/f64 condition with grad off, select in
        // ONE parallel pass `c != 0 ? x : y` — the SAME predicate as the where kernel (`c != 0.0`).
        // Output stays F64 (matching full()'s dtype), x/y are the f64 args -> BIT-EXACT. Grad /
        // non-contiguous / other-dtype condition fall through.
        if !self.tensor_requires_grad(condition)? {
            let built = {
                let ct = self.tensor_tape.tensor(condition)?;
                if ct.meta().is_contiguous() {
                    use rayon::prelude::*;
                    match ct.meta().dtype() {
                        DType::F64 => Some(
                            ct.contiguous_values()?
                                .par_iter()
                                .map(|&c| if c != 0.0 { x } else { y })
                                .collect::<Vec<f64>>(),
                        ),
                        DType::F32 => Some(
                            ct.contiguous_values_f32()?
                                .par_iter()
                                .map(|&c| if c != 0.0 { x } else { y })
                                .collect::<Vec<f64>>(),
                        ),
                        _ => None,
                    }
                } else {
                    None
                }
            };
            if let Some(out) = built {
                return self.tensor_variable(out, shape, false);
            }
        }
        let xt = self.full(shape.clone(), x, false)?;
        let yt = self.full(shape, y, false)?;
        self.tensor_where(condition, xt, yt)
    }

    /// Returns indices of non-zero elements as a tensor of shape `[M, ndim]`
    /// where M is the number of non-zero elements.
    ///
    /// NaN values are treated as non-zero (PyTorch behavior).
    /// The result is a non-differentiable leaf tensor.
    pub fn tensor_nonzero(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let dtype = self.tensor_dtype(input)?;
        if !matches!(dtype, DType::F64 | DType::F32) {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "nonzero requires f32 or f64 tensors",
                },
            )));
        }
        let shape = self.tensor_shape(input)?;
        let ndim = shape.len();

        // Compute strides for index decomposition
        let mut strides = vec![1usize; ndim];
        for i in (0..ndim.saturating_sub(1)).rev() {
            strides[i] =
                Self::checked_mul(strides[i + 1], shape[i + 1], "nonzero: stride overflow")?;
        }
        let numel = Self::checked_shape_numel(&shape, "nonzero: shape volume overflow")?;

        // No-grad parallel stream-compaction fast path (mirrors masked_select frankentorch-ucxgj).
        // The serial fallback below CLONES the input via tensor_values (8 MB at 1M) then scans +
        // decomposes each nonzero's flat index one thread. For a contiguous ndim>=1 input, BORROW the
        // native-dtype values and compact per-chunk: each chunk decomposes its own nonzero flat
        // indices (abs idx = chunk_base + j) into row-major [.,ndim] rows, and an ORDERED concat
        // reproduces the exact serial row order => BIT-IDENTICAL leaf, no f64 upcast, no clone.
        // Scalar (ndim==0) / non-contiguous / small fall through to the serial path.
        if ndim >= 1 && numel >= NONZERO_PARALLEL_MIN {
            let built: Option<Vec<f64>> = {
                let t = self.tensor_tape.tensor(input)?;
                if t.meta().is_contiguous() {
                    match dtype {
                        // F64 delegates to the proven TWO-PASS kernel (par count -> exclusive-prefix
                        // carve of disjoint output slices -> parallel decompose-write, NO serial concat):
                        // faster than a per-chunk-Vec compaction on dense inputs (the big-output concat
                        // is the wall) and already lock-tested bit-exact vs the serial scan
                        // (ft-kernel-cpu nonzero_tensor_contiguous_f64). Borrow the contiguous values
                        // (offset 0) with a fresh contiguous meta.
                        DType::F64 => {
                            let vals = t.contiguous_values()?;
                            let km = TensorMeta::from_shape(
                                shape.clone(),
                                DType::F64,
                                t.meta().device(),
                            );
                            let (indices, _total) = ft_kernel_cpu::nonzero_tensor_contiguous_f64(
                                vals, &km,
                            )
                            .map_err(|e| {
                                AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                            })?;
                            Some(indices)
                        }
                        // F32 has no dedicated kernel: per-chunk parallel compaction (native f32,
                        // ordered concat => bit-identical to the serial row-major order, no f64 upcast).
                        DType::F32 => {
                            use rayon::prelude::*;
                            let nthreads = rayon::current_num_threads().max(1);
                            let grain = (numel / nthreads).max(4096);
                            let data = t.contiguous_values_f32()?;
                            let parts: Vec<Vec<f64>> = data
                                .par_chunks(grain)
                                .enumerate()
                                .map(|(ci, chunk)| {
                                    let base = ci * grain;
                                    let mut v: Vec<f64> = Vec::new();
                                    for (j, &val) in chunk.iter().enumerate() {
                                        if val != 0.0 || val.is_nan() {
                                            let mut remaining = base + j;
                                            for &s in &strides {
                                                let dim_idx = remaining / s;
                                                remaining %= s;
                                                v.push(dim_idx as f64);
                                            }
                                        }
                                    }
                                    v
                                })
                                .collect();
                            let total: usize = parts.iter().map(Vec::len).sum();
                            let mut out = Vec::with_capacity(total);
                            for p in &parts {
                                out.extend_from_slice(p);
                            }
                            Some(out)
                        }
                        _ => None,
                    }
                } else {
                    None
                }
            };
            if let Some(indices) = built {
                let num_nonzero = indices.len() / ndim;
                return self
                    .tensor_tape
                    .leaf(indices, vec![num_nonzero, ndim], false);
            }
        }

        // Serial fallback (scalar / non-contiguous / small): clone values then scan one thread.
        let (values_f64, values_f32) = match dtype {
            DType::F64 => (Some(self.tensor_values(input)?), None),
            DType::F32 => (None, Some(self.tensor_values_f32(input)?)),
            _ => unreachable!("dtype validated above"),
        };
        let mut indices = Vec::new();
        let mut num_nonzero = 0usize;
        if let Some(values) = values_f64 {
            for (flat_idx, &val) in values.iter().enumerate().take(numel) {
                if val != 0.0 || val.is_nan() {
                    num_nonzero += 1;
                    let mut remaining = flat_idx;
                    for &s in &strides {
                        let dim_idx = remaining / s;
                        remaining %= s;
                        indices.push(dim_idx as f64);
                    }
                }
            }
        } else if let Some(values) = values_f32 {
            for (flat_idx, &val) in values.iter().enumerate().take(numel) {
                if val != 0.0 || val.is_nan() {
                    num_nonzero += 1;
                    let mut remaining = flat_idx;
                    for &s in &strides {
                        let dim_idx = remaining / s;
                        remaining %= s;
                        indices.push(dim_idx as f64);
                    }
                }
            }
        }

        // For 0-d inputs the stride loop pushes nothing, so we cannot
        // recover `num_nonzero` from `indices.len() / ndim` (0/0). Track
        // it explicitly: a non-zero scalar is shape [1, 0] and a zero
        // scalar is shape [0, 0], matching `torch.nonzero` semantics.
        let out_shape = vec![num_nonzero, ndim];
        self.tensor_tape.leaf(indices, out_shape, false)
    }

    /// Returns indices of non-zero elements as a tuple of 1-D index tensors,
    /// one per dimension. Equivalent to `torch.nonzero(input, as_tuple=True)`.
    ///
    /// The result tensors are non-differentiable leaves.
    pub fn tensor_nonzero_as_tuple(
        &mut self,
        input: TensorNodeId,
    ) -> Result<Vec<TensorNodeId>, AutogradError> {
        let dtype = self.tensor_dtype(input)?;
        let (values_f64, values_f32) = match dtype {
            DType::F64 => (Some(self.tensor_values(input)?), None),
            DType::F32 => (None, Some(self.tensor_values_f32(input)?)),
            _ => {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "nonzero requires f32 or f64 tensors",
                    },
                )));
            }
        };
        let shape = self.tensor_shape(input)?;
        let ndim = shape.len();

        let mut strides = vec![1usize; ndim];
        for i in (0..ndim.saturating_sub(1)).rev() {
            strides[i] = Self::checked_mul(
                strides[i + 1],
                shape[i + 1],
                "nonzero_as_tuple: stride overflow",
            )?;
        }

        let mut per_dim_indices: Vec<Vec<f64>> = vec![Vec::new(); ndim];
        let numel = Self::checked_shape_numel(&shape, "nonzero_as_tuple: shape volume overflow")?;
        if let Some(values) = values_f64 {
            for (flat_idx, &val) in values.iter().enumerate().take(numel) {
                if val != 0.0 || val.is_nan() {
                    let mut remaining = flat_idx;
                    for (d, &s) in strides.iter().enumerate() {
                        let dim_idx = remaining / s;
                        remaining %= s;
                        per_dim_indices[d].push(dim_idx as f64);
                    }
                }
            }
        } else if let Some(values) = values_f32 {
            for (flat_idx, &val) in values.iter().enumerate().take(numel) {
                if val != 0.0 || val.is_nan() {
                    let mut remaining = flat_idx;
                    for (d, &s) in strides.iter().enumerate() {
                        let dim_idx = remaining / s;
                        remaining %= s;
                        per_dim_indices[d].push(dim_idx as f64);
                    }
                }
            }
        }

        let mut result = Vec::with_capacity(ndim);
        for dim_indices in per_dim_indices {
            let len = dim_indices.len();
            let t = self.tensor_tape.leaf(dim_indices, vec![len], false)?;
            result.push(t);
        }
        Ok(result)
    }

    /// Count the number of non-zero elements in a tensor.
    ///
    /// Equivalent to `torch.count_nonzero(input)`. Returns a scalar tensor.
    #[inline]
    fn count_nonzero_bits_f64(values: &[f64]) -> usize {
        if values.len() >= PARALLEL_ELEMENTWISE_MIN {
            use rayon::prelude::*;
            values
                .par_chunks(262_144)
                .map(Self::count_nonzero_bits_f64_chunk)
                .sum()
        } else {
            Self::count_nonzero_bits_f64_chunk(values)
        }
    }

    #[inline]
    fn count_nonzero_bits_f64_chunk(values: &[f64]) -> usize {
        const ABS_MASK: u64 = 0x7fff_ffff_ffff_ffff;
        let mut count = 0usize;
        let mut chunks = values.chunks_exact(8);
        for chunk in &mut chunks {
            count += usize::from((chunk[0].to_bits() & ABS_MASK) != 0);
            count += usize::from((chunk[1].to_bits() & ABS_MASK) != 0);
            count += usize::from((chunk[2].to_bits() & ABS_MASK) != 0);
            count += usize::from((chunk[3].to_bits() & ABS_MASK) != 0);
            count += usize::from((chunk[4].to_bits() & ABS_MASK) != 0);
            count += usize::from((chunk[5].to_bits() & ABS_MASK) != 0);
            count += usize::from((chunk[6].to_bits() & ABS_MASK) != 0);
            count += usize::from((chunk[7].to_bits() & ABS_MASK) != 0);
        }
        count
            + chunks
                .remainder()
                .iter()
                .map(|value| usize::from((value.to_bits() & ABS_MASK) != 0))
                .sum::<usize>()
    }

    #[inline]
    fn count_nonzero_bits_f32(values: &[f32]) -> usize {
        if values.len() >= PARALLEL_ELEMENTWISE_MIN {
            use rayon::prelude::*;
            values
                .par_chunks(524_288)
                .map(Self::count_nonzero_bits_f32_chunk)
                .sum()
        } else {
            Self::count_nonzero_bits_f32_chunk(values)
        }
    }

    #[inline]
    fn count_nonzero_bits_f32_chunk(values: &[f32]) -> usize {
        const ABS_MASK: u32 = 0x7fff_ffff;
        let mut count = 0usize;
        let mut chunks = values.chunks_exact(16);
        for chunk in &mut chunks {
            count += usize::from((chunk[0].to_bits() & ABS_MASK) != 0);
            count += usize::from((chunk[1].to_bits() & ABS_MASK) != 0);
            count += usize::from((chunk[2].to_bits() & ABS_MASK) != 0);
            count += usize::from((chunk[3].to_bits() & ABS_MASK) != 0);
            count += usize::from((chunk[4].to_bits() & ABS_MASK) != 0);
            count += usize::from((chunk[5].to_bits() & ABS_MASK) != 0);
            count += usize::from((chunk[6].to_bits() & ABS_MASK) != 0);
            count += usize::from((chunk[7].to_bits() & ABS_MASK) != 0);
            count += usize::from((chunk[8].to_bits() & ABS_MASK) != 0);
            count += usize::from((chunk[9].to_bits() & ABS_MASK) != 0);
            count += usize::from((chunk[10].to_bits() & ABS_MASK) != 0);
            count += usize::from((chunk[11].to_bits() & ABS_MASK) != 0);
            count += usize::from((chunk[12].to_bits() & ABS_MASK) != 0);
            count += usize::from((chunk[13].to_bits() & ABS_MASK) != 0);
            count += usize::from((chunk[14].to_bits() & ABS_MASK) != 0);
            count += usize::from((chunk[15].to_bits() & ABS_MASK) != 0);
        }
        count
            + chunks
                .remainder()
                .iter()
                .map(|value| usize::from((value.to_bits() & ABS_MASK) != 0))
                .sum::<usize>()
    }

    pub fn tensor_count_nonzero(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let dtype = self.tensor_dtype(input)?;
        // Counting non-zeros is order-independent, so borrow the storage zero-copy (the
        // previous `tensor_values`/`tensor_values_f32` cloned the FULL input — a 128MB
        // copy at [4000,4000]) and fan the scan over Rayon. Bit-identical to the serial
        // filter-count. A non-contiguous view falls back to an owned (cloned) scan.
        #[allow(clippy::cast_precision_loss)]
        let count = match dtype {
            DType::F64 => match self.tensor_tape.values_borrowed(input) {
                Ok(v) => Self::count_nonzero_bits_f64(v) as f64,
                Err(_) => {
                    let v = self.tensor_values(input)?;
                    Self::count_nonzero_bits_f64(&v) as f64
                }
            },
            DType::F32 => match self.tensor_tape.values_f32_borrowed(input) {
                Ok(v) => Self::count_nonzero_bits_f32(v) as f64,
                Err(_) => {
                    let v = self.tensor_values_f32(input)?;
                    Self::count_nonzero_bits_f32(&v) as f64
                }
            },
            _ => {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "count_nonzero requires f32 or f64 tensors",
                    },
                )));
            }
        };
        self.tensor_variable(vec![count], vec![1], false)
    }

    /// Convert multi-dimensional indices to flat indices.
    ///
    /// Equivalent to `torch.ravel_multi_index(multi_index, shape)`.
    /// `multi_index` is a list of index tensors, one per dimension.
    /// Returns a tensor of flat indices. Tracked under frankentorch-xwas.
    pub fn ravel_multi_index(
        &mut self,
        multi_index: &[TensorNodeId],
        shape: &[usize],
    ) -> Result<TensorNodeId, AutogradError> {
        if multi_index.len() != shape.len() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "ravel_multi_index: multi_index length must match shape length",
                },
            )));
        }
        if multi_index.is_empty() {
            return self.tensor_variable(vec![], vec![0], false);
        }

        let ndim = shape.len();
        let mut strides = vec![1usize; ndim];
        for i in (0..ndim.saturating_sub(1)).rev() {
            strides[i] = strides[i + 1] * shape[i + 1];
        }

        let first_vals = self.tensor_values(multi_index[0])?;
        let n = first_vals.len();
        let mut result = vec![0.0_f64; n];

        for (dim, &idx_tensor) in multi_index.iter().enumerate() {
            let idx_vals = self.tensor_values(idx_tensor)?;
            if idx_vals.len() != n {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "ravel_multi_index: all index tensors must have same length",
                    },
                )));
            }
            for (i, &idx) in idx_vals.iter().enumerate() {
                result[i] += idx * strides[dim] as f64;
            }
        }

        self.tensor_variable(result, vec![n], false)
    }

    /// Convert flat indices to multi-dimensional indices.
    ///
    /// Equivalent to `torch.unravel_index(indices, shape)`.
    /// Returns a tuple of index tensors, one per dimension.
    /// Tracked under frankentorch-xwas.
    pub fn unravel_index(
        &mut self,
        indices: TensorNodeId,
        shape: &[usize],
    ) -> Result<Vec<TensorNodeId>, AutogradError> {
        let flat_indices = self.tensor_values(indices)?;
        let ndim = shape.len();

        if ndim == 0 {
            return Ok(vec![]);
        }

        let mut strides = vec![1usize; ndim];
        for i in (0..ndim.saturating_sub(1)).rev() {
            strides[i] = strides[i + 1] * shape[i + 1];
        }

        let n = flat_indices.len();
        let mut per_dim_indices: Vec<Vec<f64>> = vec![Vec::with_capacity(n); ndim];

        for &flat_idx in &flat_indices {
            let mut remaining = flat_idx as usize;
            for (dim, &s) in strides.iter().enumerate() {
                let dim_idx = remaining / s;
                remaining %= s;
                per_dim_indices[dim].push(dim_idx as f64);
            }
        }

        let mut result = Vec::with_capacity(ndim);
        for dim_indices in per_dim_indices {
            let t = self.tensor_variable(dim_indices, vec![n], false)?;
            result.push(t);
        }
        Ok(result)
    }

    /// Compute the n-th discrete difference along the given dimension.
    ///
    /// Equivalent to `torch.diff(input, n=1, dim=-1)`.
    /// For n=1: `out[i] = input[i+1] - input[i]`.
    /// Finite-difference gradient estimate along `dim`, with uniform `spacing`
    /// and `edge_order` (1 or 2). Equivalent to `torch.gradient(input,
    /// spacing=spacing, dim=dim, edge_order=edge_order)` for a single dim (torch
    /// returns a 1-tuple; this returns that tensor).
    ///
    /// Interior points use the central difference `(x[i+1]-x[i-1])/(2h)`;
    /// boundaries use a first- or second-order one-sided difference. Composed
    /// from autograd-aware narrow/cat/scalar ops, so the (linear) gradient flows
    /// automatically. The output has the same shape as the input.
    pub fn tensor_gradient_dim(
        &mut self,
        input: TensorNodeId,
        dim: usize,
        spacing: f64,
        edge_order: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        if dim >= shape.len() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "gradient: dim out of range",
                },
            )));
        }
        if edge_order != 1 && edge_order != 2 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "gradient: edge_order must be 1 or 2",
                },
            )));
        }
        let len = shape[dim];
        let min_len = edge_order + 1; // edge_order=1 needs >=2, edge_order=2 needs >=3
        if len < min_len {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "gradient: dimension too small for the requested edge_order",
                },
            )));
        }
        let inv_2h = 1.0 / (2.0 * spacing);
        let inv_h = 1.0 / spacing;

        // No-grad FUSED fast path: the composed path below builds ~6 intermediate tensors
        // (narrow views + sub + mul_scalar for interior/first/last) then a 3-way `cat` — every
        // interior/edge value is written twice (once into an intermediate, once by cat). torch's
        // `torch.gradient` is itself a slow Python-level composite (~46ms at [4096,4096] f64). Fuse
        // the whole thing into ONE pass per (outer,inner) lane, writing g[0]/g[interior]/g[len-1]
        // straight into the output — no intermediates, no cat. Bit-IDENTICAL to the compose: the
        // interior is `(x[j+1]-x[j-1])*inv_2h` (== `(upper-lower)` then `*inv_2h`) and the edges use
        // the exact same operation order as the composed `mul_scalar`/`add`/`sub` chains above.
        // grad / non-contiguous / non-f32-f64 fall through. frankentorch-gradient-fused.
        if !self.tensor_requires_grad(input)? {
            let outer: usize = shape[..dim].iter().product();
            let inner: usize = shape[dim + 1..].iter().product();
            let numel: usize = outer * len * inner;
            let lane_stride = len * inner;
            macro_rules! fused_grad {
                ($read:ident, $build:ident, $ty:ty) => {{
                    let built = {
                        let it = self.tensor_tape.tensor(input)?;
                        // Only fuse the LAST dim (inner == 1): each `outer` lane is then a
                        // CONTIGUOUS row, so the parallel one-pass is cache-friendly (27-35x). A
                        // non-last dim (inner > 1) would stride by `inner` per step (cache/TLB
                        // thrash) AND has outer==1 for dim 0 => serial; those keep the composed
                        // narrow+sub+cat path, which walks contiguous sub-blocks and already beats
                        // torch there. Require outer >= 2 so the fan-out has real parallelism.
                        if it.meta().is_contiguous() && inner == 1 && outer >= 2 && len >= min_len {
                            let x = it.$read()?;
                            if x.len() == numel {
                                let (i2h, ih) = (inv_2h as $ty, inv_h as $ty);
                                // per lane: read the strided column [base + s*inner], s in 0..len.
                                let compute = |outer_idx: usize, block: &mut [$ty]| {
                                    let base = outer_idx * lane_stride;
                                    for k in 0..inner {
                                        let at = |s: usize| x[base + s * inner + k];
                                        // edges match the composed edge_order formulas EXACTLY.
                                        block[k] = if edge_order == 1 {
                                            (at(1) - at(0)) * ih
                                        } else {
                                            ((at(0) * (-3.0 as $ty)) + (at(1) * (4.0 as $ty))
                                                - at(2))
                                                * i2h
                                        };
                                        for s in 1..len - 1 {
                                            block[s * inner + k] = (at(s + 1) - at(s - 1)) * i2h;
                                        }
                                        let e = len - 1;
                                        block[e * inner + k] = if edge_order == 1 {
                                            (at(e) - at(e - 1)) * ih
                                        } else {
                                            ((at(e) * (3.0 as $ty))
                                                + (at(e - 1) * (-4.0 as $ty))
                                                + at(e - 2))
                                                * i2h
                                        };
                                    }
                                };
                                let mut out = vec![0 as $ty; numel];
                                if numel >= PARALLEL_ELEMENTWISE_MIN && outer > 1 {
                                    use rayon::prelude::*;
                                    out.par_chunks_mut(lane_stride)
                                        .enumerate()
                                        .for_each(|(o, block)| compute(o, block));
                                } else {
                                    out.chunks_mut(lane_stride)
                                        .enumerate()
                                        .for_each(|(o, block)| compute(o, block));
                                }
                                Some(out)
                            } else {
                                None
                            }
                        } else {
                            None
                        }
                    };
                    match built {
                        Some(out) => return self.$build(out, shape.clone(), false),
                        None => {}
                    }
                }};
            }
            match self.tensor_dtype(input)? {
                DType::F64 => fused_grad!(contiguous_values, tensor_variable, f64),
                DType::F32 => fused_grad!(contiguous_values_f32, tensor_variable_f32, f32),
                _ => {}
            }
        }

        // Interior: (x[2:] - x[:-2]) / (2h), giving the len-2 central differences.
        let upper = self.tensor_narrow(input, dim, 2, len - 2)?;
        let lower = self.tensor_narrow(input, dim, 0, len - 2)?;
        let interior_raw = self.tensor_sub(upper, lower)?;
        let interior = self.tensor_mul_scalar(interior_raw, inv_2h)?;

        let (first, last) = if edge_order == 1 {
            // g[0] = (x[1]-x[0])/h ; g[-1] = (x[-1]-x[-2])/h
            let f = {
                let x1 = self.tensor_narrow(input, dim, 1, 1)?;
                let x0 = self.tensor_narrow(input, dim, 0, 1)?;
                let d = self.tensor_sub(x1, x0)?;
                self.tensor_mul_scalar(d, inv_h)?
            };
            let l = {
                let xn = self.tensor_narrow(input, dim, len - 1, 1)?;
                let xn1 = self.tensor_narrow(input, dim, len - 2, 1)?;
                let d = self.tensor_sub(xn, xn1)?;
                self.tensor_mul_scalar(d, inv_h)?
            };
            (f, l)
        } else {
            // edge_order == 2 (second-order one-sided):
            //   g[0]  = (-3 x[0] + 4 x[1] - x[2]) / (2h)
            //   g[-1] = ( 3 x[-1] - 4 x[-2] + x[-3]) / (2h)
            let f = {
                let x0 = self.tensor_narrow(input, dim, 0, 1)?;
                let x1 = self.tensor_narrow(input, dim, 1, 1)?;
                let x2 = self.tensor_narrow(input, dim, 2, 1)?;
                let a = self.tensor_mul_scalar(x0, -3.0)?;
                let b = self.tensor_mul_scalar(x1, 4.0)?;
                let ab = self.tensor_add(a, b)?;
                let raw = self.tensor_sub(ab, x2)?;
                self.tensor_mul_scalar(raw, inv_2h)?
            };
            let l = {
                let xn = self.tensor_narrow(input, dim, len - 1, 1)?;
                let xn1 = self.tensor_narrow(input, dim, len - 2, 1)?;
                let xn2 = self.tensor_narrow(input, dim, len - 3, 1)?;
                let a = self.tensor_mul_scalar(xn, 3.0)?;
                let b = self.tensor_mul_scalar(xn1, -4.0)?;
                let ab = self.tensor_add(a, b)?;
                let raw = self.tensor_add(ab, xn2)?;
                self.tensor_mul_scalar(raw, inv_2h)?
            };
            (f, l)
        };

        self.tensor_cat(&[first, interior, last], dim)
    }

    pub fn tensor_diff(
        &mut self,
        input: TensorNodeId,
        n: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        // Default torch.diff: along the last dim, no prepend / append.
        self.tensor_diff_full(input, n, -1, None, None)
    }

    /// `torch.diff(input, n=n, dim=dim, prepend=prepend, append=append)`.
    ///
    /// The n-th forward difference along `dim` (negative `dim` counts from
    /// the end). When `prepend` / `append` are supplied they are concatenated
    /// onto the start / end along `dim` BEFORE differencing (each must match
    /// `input`'s shape except along `dim`) — the usual trick to keep the
    /// output length equal to the input length.
    ///
    /// Composes through tensor_cat + narrow/sub so the backward pass flows to
    /// `input`, `prepend`, and `append`. Each difference shrinks `dim` by one;
    /// torch parity for a length-<2 axis is an empty (size-0) axis rather than
    /// a rank reduction. With `n == 0` torch returns the input unchanged and
    /// ignores prepend/append, which we match.
    pub fn tensor_diff_full(
        &mut self,
        input: TensorNodeId,
        n: usize,
        dim: i64,
        prepend: Option<TensorNodeId>,
        append: Option<TensorNodeId>,
    ) -> Result<TensorNodeId, AutogradError> {
        if n == 0 {
            // torch.diff(n=0) returns the input verbatim (prepend/append
            // are NOT applied — verified vs torch 2.12).
            return Ok(input);
        }
        let shape = self.tensor_shape(input)?;
        // PyTorch errors on rank-0 input ("diff expects input to be at least
        // one-dimensional"). Match that.
        if shape.is_empty() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "diff: input must have at least one dimension",
                },
            )));
        }
        let ndim = shape.len();
        let resolved = if dim < 0 { dim + ndim as i64 } else { dim };
        if resolved < 0 || resolved as usize >= ndim {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "diff: dim out of range",
                },
            )));
        }
        let dim = resolved as usize;
        let dtype = self.tensor_dtype(input)?;
        if !matches!(dtype, DType::F64 | DType::F32) {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "diff requires f32 or f64 tensors",
                },
            )));
        }

        // No-grad fast path for the common diff (order 1, no prepend/append): the
        // composition below builds narrow+narrow+sub tape nodes and subtracts two
        // NON-CONTIGUOUS views (~5x worse than bandwidth). With grad off, compute the
        // adjacent difference directly on the borrowed contiguous storage in parallel —
        // bit-exact (one fused subtract per output). Falls through for non-contiguous
        // input. Output shape = input with `shape[dim]` reduced by 1.
        if n == 1
            && prepend.is_none()
            && append.is_none()
            && shape[dim] >= 2
            && !self.tensor_requires_grad(input)?
        {
            let inner: usize = shape[dim + 1..].iter().product();
            let outer: usize = shape[..dim].iter().product();
            let reduce = shape[dim];
            let out_reduce = reduce - 1;
            let out_numel = outer * out_reduce * inner;
            let mut out_shape = shape.clone();
            out_shape[dim] = out_reduce;
            let unravel = |out_idx: usize| -> (usize, usize) {
                let inner_idx = out_idx % inner;
                let i = (out_idx / inner) % out_reduce;
                let o = out_idx / (inner * out_reduce);
                let base = o * reduce * inner + inner_idx;
                (base + (i + 1) * inner, base + i * inner)
            };
            let built = {
                let tensor = self.tensor_tape.tensor(input)?;
                if tensor.meta().is_contiguous() {
                    use rayon::prelude::*;
                    match dtype {
                        DType::F64 => {
                            let data = tensor.contiguous_values()?;
                            let out: Vec<f64> = (0..out_numel)
                                .into_par_iter()
                                .map(|k| {
                                    let (hi, lo) = unravel(k);
                                    data[hi] - data[lo]
                                })
                                .collect();
                            Some(Ok(out))
                        }
                        DType::F32 => {
                            let data = tensor.contiguous_values_f32()?;
                            let out: Vec<f32> = (0..out_numel)
                                .into_par_iter()
                                .map(|k| {
                                    let (hi, lo) = unravel(k);
                                    data[hi] - data[lo]
                                })
                                .collect();
                            Some(Err(out))
                        }
                        _ => None,
                    }
                } else {
                    None
                }
            };
            match built {
                Some(Ok(out)) => return self.tensor_variable(out, out_shape, false),
                Some(Err(out)) => return self.tensor_variable_f32(out, out_shape, false),
                None => {}
            }
        }

        // No-grad fused n>=2 path (no prepend/append): the general loop below builds `n` tape sub
        // nodes, each subtracting two NON-CONTIGUOUS narrow views (strided reads + a tape node per
        // order). Instead iterate the adjacent-difference kernel `n` times on CONTIGUOUS buffers —
        // pass 1 reads the borrowed input, later passes read the owned running Vec. Each element is
        // `cur[hi]-cur[lo]` in the SAME order as `tensor_sub(narrow(_,1,..), narrow(_,0,..))`, and the
        // intermediate Vecs equal the intermediate diff tensors exactly, so the result is bit-for-bit
        // identical to the composed loop. torch.diff(n>1) is itself iterated (slow). Gated to a
        // non-empty output (`shape[dim] > n`); grad / prepend / append / non-contiguous / len<=n fall
        // through to the composed loop. frankentorch-diff-n-fused.
        if n >= 2
            && prepend.is_none()
            && append.is_none()
            && shape[dim] > n
            && shape[dim + 1..].iter().product::<usize>() == 1 // LAST dim only (contiguous lanes)
            && shape[..dim].iter().product::<usize>() >= 2 // real fan-out
            && !self.tensor_requires_grad(input)?
        {
            let outer: usize = shape[..dim].iter().product();
            macro_rules! fused_diff_n {
                ($read:ident, $build:ident, $ty:ty) => {{
                    let built = {
                        let t = self.tensor_tape.tensor(input)?;
                        if t.meta().is_contiguous() {
                            use rayon::prelude::*;
                            let data = t.$read()?;
                            // One adjacent-difference pass over contiguous rows: each `outer` lane is
                            // a CONTIGUOUS length-`reduce` row -> length-`reduce-1` output row. Fan
                            // over lanes via par_chunks_mut (no per-element div/mod, unlike an
                            // into_par_iter unravel), first-touching the fresh buffer in parallel.
                            // `src[ibase+i+1]-src[ibase+i]` == tensor_sub(narrow(_,1,..),narrow(_,0,..))
                            // so every pass (and every intermediate buffer) is bit-for-bit == the
                            // composed loop.
                            let pass = |src: &[$ty], reduce: usize| -> Vec<$ty> {
                                let out_reduce = reduce - 1;
                                let mut out = vec![0 as $ty; outer * out_reduce];
                                out.par_chunks_mut(out_reduce).enumerate().for_each(|(o, orow)| {
                                    let ibase = o * reduce;
                                    for i in 0..out_reduce {
                                        orow[i] = src[ibase + i + 1] - src[ibase + i];
                                    }
                                });
                                out
                            };
                            let mut reduce = shape[dim];
                            let mut cur = pass(&data, reduce);
                            reduce -= 1;
                            for _ in 1..n {
                                cur = pass(&cur, reduce);
                                reduce -= 1;
                            }
                            let mut out_shape = shape.clone();
                            out_shape[dim] = reduce;
                            Some((cur, out_shape))
                        } else {
                            None
                        }
                    };
                    if let Some((out, out_shape)) = built {
                        return self.$build(out, out_shape, false);
                    }
                }};
            }
            match dtype {
                DType::F64 => fused_diff_n!(contiguous_values, tensor_variable, f64),
                DType::F32 => fused_diff_n!(contiguous_values_f32, tensor_variable_f32, f32),
                _ => {}
            }
        }

        // Concatenate prepend ++ input ++ append along `dim`. tensor_cat is
        // autograd-aware and validates that each part matches `input`'s shape
        // off `dim`, so a mismatched prepend/append fails loud there.
        let mut current = if prepend.is_some() || append.is_some() {
            let mut parts: Vec<TensorNodeId> = Vec::with_capacity(3);
            if let Some(p) = prepend {
                parts.push(p);
            }
            parts.push(input);
            if let Some(a) = append {
                parts.push(a);
            }
            self.tensor_cat(&parts, dim)?
        } else {
            input
        };

        // n iterated forward differences along `dim`. diff(x, n=1) is linear:
        //     out[.., i, ..] = x[.., i+1, ..] - x[.., i, ..]
        // i.e. narrow(x, dim, 1, len-1) - narrow(x, dim, 0, len-1).
        for _ in 0..n {
            let shape = self.tensor_shape(current)?;
            let axis = shape[dim];
            if axis < 2 {
                // PyTorch parity: a length-<2 axis becomes size 0, every
                // other dim preserved (frankentorch-rjn4), dtype preserved.
                let mut out_shape = shape.clone();
                out_shape[dim] = 0;
                return match self.tensor_dtype(current)? {
                    DType::F64 => self.tensor_variable(vec![], out_shape, false),
                    DType::F32 => self.tensor_variable_f32(vec![], out_shape, false),
                    _ => Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "diff requires f32 or f64 tensors",
                        },
                    ))),
                };
            }
            let new_len = axis - 1;
            let head = self.tensor_narrow(current, dim, 1, new_len)?;
            let tail = self.tensor_narrow(current, dim, 0, new_len)?;
            current = self.tensor_sub(head, tail)?;
        }
        Ok(current)
    }

    /// Cumulative maximum along flattened tensor.
    ///
    /// Returns `(values, indices)` where values[i] = max(input[0..=i])
    /// and indices[i] is the index of that maximum.
    pub fn tensor_cummax(
        &mut self,
        input: TensorNodeId,
    ) -> Result<(TensorNodeId, TensorNodeId), AutogradError> {
        // Wrap the values branch in tensor_apply_function with the
        // argmax-routing backward; the indices branch is integer-
        // valued and correctly non-differentiable. Tracked under
        // frankentorch-wkkw — previously this body extracted values,
        // computed cum_vals + cum_idx in plain f64, and rebuilt both
        // as requires_grad=false leaves, silently severing autograd
        // through the values branch.
        let shape = self.tensor_shape(input)?;
        let n = Self::checked_shape_numel(&shape, "cummax: shape volume overflow")?;

        // No-grad f64 fast path: the running cummax VALUE is `vals[max_idx]`, already known during
        // the argmax scan — so build cum_vals DIRECTLY instead of computing cum_idx and then
        // index_select-GATHERING x[cum_idx[i]] (a 16M random gather + tape node) plus a cum_idx
        // clone + reshape nodes (the old path's ~5×numel allocations + cache-hostile gather = the
        // wall). Borrow the input (no clone). Bit-identical: same >=/NaN-propagation rule, and
        // vals[max_idx] is exactly what the gather returned. f64 contiguous only; grad / f32 / f16 /
        // non-contiguous fall through to the autograd-aware index_select path below.
        if !self.tensor_requires_grad(input)? && self.tensor_dtype(input)? == DType::F64 {
            let built = {
                let t = self.tensor_tape.tensor(input)?;
                if t.meta().is_contiguous() {
                    let vals = t.contiguous_values()?;
                    if vals.len() == n {
                        let mut cum_vals = Vec::with_capacity(n);
                        let mut cum_idx = Vec::with_capacity(n);
                        let mut max_val = f64::NEG_INFINITY;
                        let mut max_idx = 0usize;
                        let mut seen_nan = false;
                        for (i, &v) in vals.iter().enumerate() {
                            if !seen_nan {
                                if v.is_nan() {
                                    seen_nan = true;
                                    max_idx = i;
                                } else if v >= max_val {
                                    max_val = v;
                                    max_idx = i;
                                }
                            }
                            cum_vals.push(vals[max_idx]);
                            cum_idx.push(max_idx as f64);
                        }
                        Some((cum_vals, cum_idx))
                    } else {
                        None
                    }
                } else {
                    None
                }
            };
            if let Some((cum_vals, cum_idx)) = built {
                let values = self.tensor_variable(cum_vals, shape.clone(), false)?;
                let indices = self.tensor_variable(cum_idx, shape, false)?;
                return Ok((values, indices));
            }
        }

        // No-grad F32 fast path (sibling of the f64 one). The generic path below
        // `tensor_values_lossy_f64` UPCASTS f32->f64 (128MB clone at 16M) then runs the
        // serial argmax scan AND an index_select GATHER of x[cum_idx] (16M random gather +
        // tape node + clones = ~5x numel allocations) — measured ~4x SLOWER than torch.
        // Borrow the f32 slice and build cum_vals DIRECTLY in the scan (cum_vals[i] =
        // vals[max_idx], no gather, no upcast). Bit-identical: same >=/NaN-propagation rule;
        // the value gathered by index_select is exactly vals[max_idx]; output stays f32
        // (torch.cummax(f32)->f32). f32 contiguous no-grad only.
        if !self.tensor_requires_grad(input)? && self.tensor_dtype(input)? == DType::F32 {
            let built = {
                let t = self.tensor_tape.tensor(input)?;
                if t.meta().is_contiguous() {
                    let vals = t.contiguous_values_f32()?;
                    if vals.len() == n {
                        let mut cum_vals = Vec::with_capacity(n);
                        let mut cum_idx = Vec::with_capacity(n);
                        let mut max_val = f32::NEG_INFINITY;
                        let mut max_idx = 0usize;
                        let mut seen_nan = false;
                        for (i, &v) in vals.iter().enumerate() {
                            if !seen_nan {
                                if v.is_nan() {
                                    seen_nan = true;
                                    max_idx = i;
                                } else if v >= max_val {
                                    max_val = v;
                                    max_idx = i;
                                }
                            }
                            cum_vals.push(vals[max_idx]);
                            cum_idx.push(max_idx as f64);
                        }
                        Some((cum_vals, cum_idx))
                    } else {
                        None
                    }
                } else {
                    None
                }
            };
            if let Some((cum_vals, cum_idx)) = built {
                let values = self.tensor_variable_f32(cum_vals, shape.clone(), false)?;
                let indices = self.tensor_variable(cum_idx, shape, false)?;
                return Ok((values, indices));
            }
        }

        // Compute the running-argmax positions (lossy read so f32 is accepted).
        let vals = self.tensor_values_lossy_f64(input)?;
        let mut cum_idx = Vec::with_capacity(n);
        let mut max_val = f64::NEG_INFINITY;
        let mut max_idx = 0usize;
        let mut seen_nan = false;
        for (i, &v) in vals.iter().enumerate() {
            // torch cummax updates the index on EQUALITY (>=), keeping the LATEST
            // tied maximum (cummax([5,5,5]).indices = [0,1,2], not [0,0,0]); and it
            // PROPAGATES NaN — once a NaN appears the running max stays NaN and its
            // index freezes there (cummax([1,nan,2]) = [1,nan,nan], idx [0,1,1]).
            // The values branch then gathers x[max_idx], so freezing on the NaN's
            // index yields NaN for every later position. Verified vs torch 2.12.
            // frankentorch-cmtie / cmnan.
            if !seen_nan {
                if v.is_nan() {
                    seen_nan = true;
                    max_idx = i;
                } else if v >= max_val {
                    max_val = v;
                    max_idx = i;
                }
            }
            cum_idx.push(max_idx as f64);
        }

        // Gather values[i] = x_flat[cum_idx[i]] via index_select on the flattened
        // input: preserves the input dtype (torch cummax(f32) -> f32 values) and
        // stays autograd-aware — its backward scatters grad to the cum_idx
        // positions, identical to the previous custom-op gradient (the old path
        // read f64-only values and built an F64 leaf). frankentorch-z71u.
        let flat = if shape == [n] {
            input
        } else {
            self.tensor_reshape(input, vec![n])?
        };
        let idx_leaf = self.tensor_tape.leaf(cum_idx.clone(), vec![n], false)?;
        let gathered = self.tensor_index_select(flat, 0, idx_leaf)?;
        let values = if shape == [n] {
            gathered
        } else {
            self.tensor_reshape(gathered, shape.clone())?
        };
        let indices = self.tensor_variable(cum_idx, shape, false)?;
        Ok((values, indices))
    }

    /// Cumulative maximum ALONG `dim` (`torch.cummax(x, dim)`), returning `(values, indices)` with
    /// the input's shape. `indices` are the position along `dim` (0..size). Tie keeps the LATEST max
    /// (`>=`); NaN PROPAGATES (matches torch 2.12 / the flattened [`Self::tensor_cummax`]).
    ///
    /// No-grad f64 uses the cache-friendly `cummax_dim` kernel (up to ~3.3x vs PyTorch for a strided
    /// dim, where torch runs a cache-hostile direct scan). The grad / non-f64 path gathers along
    /// `dim` by the argmax indices — differentiable + dtype-preserving, its backward scatter-adds the
    /// gradient to the argmax positions = exactly the cummax gradient. frankentorch-cummax-dim-aware.
    pub fn tensor_cummax_dim(
        &mut self,
        input: TensorNodeId,
        dim: usize,
    ) -> Result<(TensorNodeId, TensorNodeId), AutogradError> {
        let shape = self.tensor_shape(input)?;
        let is_f64 = self.tensor_dtype(input)? == DType::F64;
        let requires_grad = self.tensor_tape.tensor_requires_grad(input)?;
        let contiguous = self.tensor_tape.tensor(input)?.meta().is_contiguous();
        // f32 no-grad fast path: dedicated f32 kernel (values f32, indices f64).
        if !requires_grad && self.tensor_dtype(input)? == DType::F32 && contiguous {
            let f32_meta = TensorMeta::from_shape(shape.clone(), DType::F32, Device::Cpu);
            let (kv, idx) = {
                let v = self.tensor_tape.tensor(input)?.contiguous_values_f32()?;
                ft_kernel_cpu::cummax_dim_tensor_contiguous_f32(v, &f32_meta, dim)
                    .map_err(|e| AutogradError::Dispatch(e.into()))?
            };
            let values = self.tensor_tape.leaf_f32(kv, shape.clone(), false)?;
            let indices_out = self.tensor_variable(idx, shape, false)?;
            return Ok((values, indices_out));
        }
        let meta = TensorMeta::from_shape(shape.clone(), DType::F64, Device::Cpu);
        // Borrow f64-contiguous input (no 128MB copy); else lossy-read.
        let (kvalues, indices) = if is_f64 && contiguous {
            let v = self.tensor_tape.tensor(input)?.contiguous_values()?;
            ft_kernel_cpu::cummax_dim_tensor_contiguous_f64(v, &meta, dim)
                .map_err(|e| AutogradError::Dispatch(e.into()))?
        } else {
            let v = self.tensor_values_lossy_f64(input)?;
            ft_kernel_cpu::cummax_dim_tensor_contiguous_f64(&v, &meta, dim)
                .map_err(|e| AutogradError::Dispatch(e.into()))?
        };
        if is_f64 && !requires_grad {
            // Fast path: kernel already produced cache-friendly (f64) values; move both out.
            let values = self.tensor_tape.leaf(kvalues, shape.clone(), false)?;
            let indices_out = self.tensor_variable(indices, shape, false)?;
            Ok((values, indices_out))
        } else {
            // Grad / non-f64: gather along dim (differentiable, dtype-preserving).
            let idx_leaf = self
                .tensor_tape
                .leaf(indices.clone(), shape.clone(), false)?;
            let values = self.tensor_gather(input, dim, idx_leaf)?;
            let indices_out = self.tensor_variable(indices, shape, false)?;
            Ok((values, indices_out))
        }
    }

    /// Cumulative minimum ALONG `dim` (`torch.cummin(x, dim)`) — sister of [`Self::tensor_cummax_dim`].
    /// Tie keeps the LATEST min (`<=`) + NaN propagation. No-grad f64 uses the cache-friendly
    /// `cummin_dim` kernel (~3x vs PyTorch for a strided dim); grad / non-f64 gathers along `dim`.
    /// frankentorch-cummax-dim-aware. (BlackThrush)
    pub fn tensor_cummin_dim(
        &mut self,
        input: TensorNodeId,
        dim: usize,
    ) -> Result<(TensorNodeId, TensorNodeId), AutogradError> {
        let shape = self.tensor_shape(input)?;
        let is_f64 = self.tensor_dtype(input)? == DType::F64;
        let requires_grad = self.tensor_tape.tensor_requires_grad(input)?;
        let contiguous = self.tensor_tape.tensor(input)?.meta().is_contiguous();
        // f32 no-grad fast path: dedicated f32 kernel (values f32, indices f64).
        if !requires_grad && self.tensor_dtype(input)? == DType::F32 && contiguous {
            let f32_meta = TensorMeta::from_shape(shape.clone(), DType::F32, Device::Cpu);
            let (kv, idx) = {
                let v = self.tensor_tape.tensor(input)?.contiguous_values_f32()?;
                ft_kernel_cpu::cummin_dim_tensor_contiguous_f32(v, &f32_meta, dim)
                    .map_err(|e| AutogradError::Dispatch(e.into()))?
            };
            let values = self.tensor_tape.leaf_f32(kv, shape.clone(), false)?;
            let indices_out = self.tensor_variable(idx, shape, false)?;
            return Ok((values, indices_out));
        }
        let meta = TensorMeta::from_shape(shape.clone(), DType::F64, Device::Cpu);
        let (kvalues, indices) = if is_f64 && contiguous {
            let v = self.tensor_tape.tensor(input)?.contiguous_values()?;
            ft_kernel_cpu::cummin_dim_tensor_contiguous_f64(v, &meta, dim)
                .map_err(|e| AutogradError::Dispatch(e.into()))?
        } else {
            let v = self.tensor_values_lossy_f64(input)?;
            ft_kernel_cpu::cummin_dim_tensor_contiguous_f64(&v, &meta, dim)
                .map_err(|e| AutogradError::Dispatch(e.into()))?
        };
        if is_f64 && !requires_grad {
            let values = self.tensor_tape.leaf(kvalues, shape.clone(), false)?;
            let indices_out = self.tensor_variable(indices, shape, false)?;
            Ok((values, indices_out))
        } else {
            let idx_leaf = self
                .tensor_tape
                .leaf(indices.clone(), shape.clone(), false)?;
            let values = self.tensor_gather(input, dim, idx_leaf)?;
            let indices_out = self.tensor_variable(indices, shape, false)?;
            Ok((values, indices_out))
        }
    }

    /// Cumulative minimum along flattened tensor.
    ///
    /// Returns `(values, indices)` where values[i] = min(input[0..=i])
    /// and indices[i] is the index of that minimum.
    pub fn tensor_cummin(
        &mut self,
        input: TensorNodeId,
    ) -> Result<(TensorNodeId, TensorNodeId), AutogradError> {
        // Sister of tensor_cummax — same argmax-routing backward via
        // tensor_apply_function. Tracked under frankentorch-wkkw.
        let shape = self.tensor_shape(input)?;
        let n = Self::checked_shape_numel(&shape, "cummin: shape volume overflow")?;

        // No-grad f64 fast path (sibling of tensor_cummax): the running cummin VALUE is
        // `vals[min_idx]`, already known during the argmin scan — build cum_vals DIRECTLY instead of
        // computing cum_idx then index_select-GATHERING x[cum_idx[i]] (16M random gather + tape node)
        // plus a cum_idx clone + reshape nodes (the wall). Borrow the input. Bit-identical (same
        // <=/NaN-propagation; vals[min_idx] is exactly the gather result). f64 contiguous only;
        // grad / f32 / f16 / non-contiguous fall through to the autograd-aware index_select path.
        if !self.tensor_requires_grad(input)? && self.tensor_dtype(input)? == DType::F64 {
            let built = {
                let t = self.tensor_tape.tensor(input)?;
                if t.meta().is_contiguous() {
                    let vals = t.contiguous_values()?;
                    if vals.len() == n {
                        let mut cum_vals = Vec::with_capacity(n);
                        let mut cum_idx = Vec::with_capacity(n);
                        let mut min_val = f64::INFINITY;
                        let mut min_idx = 0usize;
                        let mut seen_nan = false;
                        for (i, &v) in vals.iter().enumerate() {
                            if !seen_nan {
                                if v.is_nan() {
                                    seen_nan = true;
                                    min_idx = i;
                                } else if v <= min_val {
                                    min_val = v;
                                    min_idx = i;
                                }
                            }
                            cum_vals.push(vals[min_idx]);
                            cum_idx.push(min_idx as f64);
                        }
                        Some((cum_vals, cum_idx))
                    } else {
                        None
                    }
                } else {
                    None
                }
            };
            if let Some((cum_vals, cum_idx)) = built {
                let values = self.tensor_variable(cum_vals, shape.clone(), false)?;
                let indices = self.tensor_variable(cum_idx, shape, false)?;
                return Ok((values, indices));
            }
        }

        // No-grad F32 fast path (sibling of the f64 one + cummax-f32): avoids the f32->f64
        // upcast + index_select gather of the generic path (~4x SLOWER than torch). Build
        // cum_vals directly in the scan. Bit-identical (same <=/NaN rule; output stays f32).
        if !self.tensor_requires_grad(input)? && self.tensor_dtype(input)? == DType::F32 {
            let built = {
                let t = self.tensor_tape.tensor(input)?;
                if t.meta().is_contiguous() {
                    let vals = t.contiguous_values_f32()?;
                    if vals.len() == n {
                        let mut cum_vals = Vec::with_capacity(n);
                        let mut cum_idx = Vec::with_capacity(n);
                        let mut min_val = f32::INFINITY;
                        let mut min_idx = 0usize;
                        let mut seen_nan = false;
                        for (i, &v) in vals.iter().enumerate() {
                            if !seen_nan {
                                if v.is_nan() {
                                    seen_nan = true;
                                    min_idx = i;
                                } else if v <= min_val {
                                    min_val = v;
                                    min_idx = i;
                                }
                            }
                            cum_vals.push(vals[min_idx]);
                            cum_idx.push(min_idx as f64);
                        }
                        Some((cum_vals, cum_idx))
                    } else {
                        None
                    }
                } else {
                    None
                }
            };
            if let Some((cum_vals, cum_idx)) = built {
                let values = self.tensor_variable_f32(cum_vals, shape.clone(), false)?;
                let indices = self.tensor_variable(cum_idx, shape, false)?;
                return Ok((values, indices));
            }
        }

        let vals = self.tensor_values_lossy_f64(input)?;
        let mut cum_idx = Vec::with_capacity(n);
        let mut min_val = f64::INFINITY;
        let mut min_idx = 0usize;
        let mut seen_nan = false;
        for (i, &v) in vals.iter().enumerate() {
            // torch cummin updates the index on EQUALITY (<=), keeping the LATEST
            // tied minimum (cummin([5,5,5]).indices = [0,1,2]); and PROPAGATES NaN
            // once seen, freezing the index there (cummin([1,nan,2]) = [1,nan,nan],
            // idx [0,1,1]). Verified vs torch 2.12. frankentorch-cmtie / cmnan.
            if !seen_nan {
                if v.is_nan() {
                    seen_nan = true;
                    min_idx = i;
                } else if v <= min_val {
                    min_val = v;
                    min_idx = i;
                }
            }
            cum_idx.push(min_idx as f64);
        }

        // Gather via index_select on the flattened input — preserves dtype +
        // autograd (see tensor_cummax). frankentorch-z71u.
        let flat = if shape == [n] {
            input
        } else {
            self.tensor_reshape(input, vec![n])?
        };
        let idx_leaf = self.tensor_tape.leaf(cum_idx.clone(), vec![n], false)?;
        let gathered = self.tensor_index_select(flat, 0, idx_leaf)?;
        let values = if shape == [n] {
            gathered
        } else {
            self.tensor_reshape(gathered, shape.clone())?
        };
        let indices = self.tensor_variable(cum_idx, shape, false)?;
        Ok((values, indices))
    }

    /// Repeat each element of a 1-D tensor a given number of times.
    ///
    /// Equivalent to `torch.repeat_interleave(input, repeats)`.
    /// `repeats` is a scalar: each element is repeated that many times.
    pub fn tensor_repeat_interleave(
        &mut self,
        input: TensorNodeId,
        repeats: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        if shape.len() != 1 {
            // Migrate to InvalidDimension (frankentorch-oitu).
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::InvalidDimension {
                    dim: shape.len(),
                    ndim: 1,
                },
            )));
        }
        let in_len = shape[0];
        let out_len =
            Self::checked_mul(in_len, repeats, "repeat_interleave: output size overflow")?;
        // Reject byte-size overflow before tensor_apply_function tries
        // to allocate (the prior body used try_reserve_exact for this;
        // checked_mul only validates element-count, but
        // (1, usize::MAX) yields usize::MAX which fits in usize but
        // not in Vec's byte budget).
        let _ = Self::checked_mul(
            out_len,
            std::mem::size_of::<f64>(),
            "repeat_interleave: output size overflow",
        )?;

        // No-grad native fast path. tensor_apply_function (below) reads the input as f64, so
        // an f32 input was UPCAST to f64, materialized into a 128MB f64 intermediate, then
        // narrowed back to f32 — a round-trip = ~6x SLOWER than torch. Here build the output
        // DIRECTLY in the input dtype with a coarse-grain parallel run-fill (out[g] =
        // vals[g/repeats]). Bit-identical (pure copy). f32/f64 contiguous fall through to the
        // tape (grad-capable) path otherwise.
        let ri_dtype = self.tensor_dtype(input)?;
        if !self.tensor_requires_grad(input)?
            && repeats > 0
            && out_len > 0
            && matches!(ri_dtype, DType::F64 | DType::F32)
        {
            let mut ri_f64: Option<Vec<f64>> = None;
            let mut ri_f32: Option<Vec<f32>> = None;
            {
                let it = self.tensor_tape.tensor(input)?;
                if it.meta().is_contiguous() {
                    use rayon::prelude::*;
                    let threads = rayon::current_num_threads().max(1);
                    let grain = (out_len / (threads * 4)).max(1);
                    // out[g] = vals[g / repeats]; coarse-grain parallel run-fill (each input
                    // lane -> `repeats` consecutive copies). Borrow `it` directly (no clone).
                    macro_rules! ri_fill {
                        ($read:ident, $zero:expr) => {{
                            let data = it.$read()?;
                            let mut out = vec![$zero; out_len];
                            // Pure fill (write-only): gate at the fault-parallelism crossover, not
                            // the compute default — parallel fill regresses small/medium 2-14x.
                            if out_len >= MOVEMENT_COPY_PARALLEL_MIN && in_len > 1 {
                                out.par_chunks_mut(grain)
                                    .enumerate()
                                    .for_each(|(ci, chunk)| {
                                        let mut g = ci * grain;
                                        let mut w = 0usize;
                                        while w < chunk.len() {
                                            let i = g / repeats;
                                            let within = g - i * repeats;
                                            let run = (repeats - within).min(chunk.len() - w);
                                            chunk[w..w + run].fill(data[i]);
                                            w += run;
                                            g += run;
                                        }
                                    });
                            } else {
                                for (i, c) in out.chunks_mut(repeats).enumerate() {
                                    c.fill(data[i]);
                                }
                            }
                            out
                        }};
                    }
                    match ri_dtype {
                        DType::F64 => ri_f64 = Some(ri_fill!(contiguous_values, 0.0_f64)),
                        DType::F32 => ri_f32 = Some(ri_fill!(contiguous_values_f32, 0.0_f32)),
                        _ => {}
                    }
                }
            }
            if let Some(out) = ri_f64 {
                return self.tensor_variable(out, vec![out_len], false);
            }
            if let Some(out) = ri_f32 {
                return self.tensor_variable_f32(out, vec![out_len], false);
            }
        }

        // Wrap in tensor_apply_function with the analytical
        // backward grad_input[i] = sum_{j: j / R == i} grad_output[j].
        // Tracked under frankentorch-5196.
        self.tensor_apply_function(
            &[input],
            move |_ctx, inputs| {
                let (vals, _shape) = inputs[0];
                if repeats == 0 || out_len == 0 {
                    return Ok((Vec::new(), vec![out_len]));
                }
                // Each input element becomes `repeats` consecutive copies. The old form
                // chunked par_chunks_mut(repeats) = one rayon task PER input lane → for a
                // small `repeats` (e.g. 4) on a 16M output that's 4M tiny tasks = scheduling
                // overhead dominates (~5.9x SLOWER than torch). Use a COARSE grain and walk
                // input lanes internally (out[g] = vals[g / repeats]); fill contiguous runs.
                // Bit-identical to the serial push.
                let mut result = vec![0.0_f64; out_len];
                // Pure fill (write-only): fault-parallelism gate (see MOVEMENT_COPY_PARALLEL_MIN),
                // not the compute default — parallel fill regresses small/medium 2-14x.
                if out_len >= MOVEMENT_COPY_PARALLEL_MIN && in_len > 1 {
                    use rayon::prelude::*;
                    let threads = rayon::current_num_threads().max(1);
                    let grain = (out_len / (threads * 4)).max(1);
                    result
                        .par_chunks_mut(grain)
                        .enumerate()
                        .for_each(|(ci, chunk)| {
                            let mut g = ci * grain;
                            let mut w = 0usize;
                            while w < chunk.len() {
                                let i = g / repeats;
                                let within = g - i * repeats;
                                let run = (repeats - within).min(chunk.len() - w);
                                chunk[w..w + run].fill(vals[i]);
                                w += run;
                                g += run;
                            }
                        });
                } else {
                    for (i, c) in result.chunks_mut(repeats).enumerate() {
                        c.fill(vals[i]);
                    }
                }
                Ok((result, vec![out_len]))
            },
            move |_ctx, grad_outputs| {
                let g = grad_outputs[0];
                let mut grad_in = vec![0.0_f64; in_len];
                if repeats == 0 || in_len == 0 {
                    return Ok(vec![Some(grad_in)]);
                }
                // grad_in[i] = sum of the i-th contiguous `repeats`-chunk of grad_output → parallel
                // over input lanes; per-lane sum order matches the serial `+=` (bit-identical).
                let sum_chunk = |i: usize, gi: &mut f64| {
                    let mut acc = 0.0_f64;
                    for &x in &g[i * repeats..(i + 1) * repeats] {
                        acc += x;
                    }
                    *gi = acc;
                };
                if out_len >= PARALLEL_ELEMENTWISE_MIN && in_len > 1 {
                    use rayon::prelude::*;
                    grad_in
                        .par_iter_mut()
                        .enumerate()
                        .for_each(|(i, gi)| sum_chunk(i, gi));
                } else {
                    for (i, gi) in grad_in.iter_mut().enumerate() {
                        sum_chunk(i, gi);
                    }
                }
                Ok(vec![Some(grad_in)])
            },
        )
    }

    /// `torch.repeat_interleave(input, repeats:int, dim:int)` — repeat each
    /// slice along `dim` a fixed number of times.
    pub fn tensor_repeat_interleave_dim(
        &mut self,
        input: TensorNodeId,
        repeats: usize,
        dim: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_repeat_interleave_tensor(input, &[repeats], Some(dim))
    }

    /// `torch.repeat_interleave(input, repeats, dim=dim)` with PER-SLICE
    /// repeat counts. `repeats` is either length 1 (broadcast to every slice)
    /// or length equal to the repeated axis (`input.size(dim)`, or
    /// `input.numel()` when `dim` is `None`, in which case the input is
    /// flattened first — matching torch). Slice `i` along the axis is emitted
    /// `repeats[i]` times (0 drops it); the output axis length is the sum of
    /// `repeats`. This is a pure copy, so it is bit-exact and autograd-aware:
    /// the backward accumulates each output copy's gradient back onto its
    /// source element.
    pub fn tensor_repeat_interleave_tensor(
        &mut self,
        input: TensorNodeId,
        repeats: &[usize],
        dim: Option<usize>,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        let rank = shape.len();
        let (axis_len, inner, outer, axis): (usize, usize, usize, Option<usize>) = match dim {
            Some(d) => {
                if d >= rank {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "repeat_interleave: dim out of range",
                        },
                    )));
                }
                let inner: usize = shape[d + 1..].iter().product();
                let outer: usize = shape[..d].iter().product();
                (shape[d], inner, outer, Some(d))
            }
            None => {
                let numel: usize = shape.iter().product();
                (numel, 1, 1, None)
            }
        };

        let rep: Vec<usize> = if repeats.len() == 1 {
            vec![repeats[0]; axis_len]
        } else if repeats.len() == axis_len {
            repeats.to_vec()
        } else {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "repeat_interleave: repeats must have length 1 or input.size(dim)",
                },
            )));
        };
        let out_axis_len: usize = rep.iter().sum();

        let per_outer = Self::checked_mul(
            out_axis_len,
            inner,
            "repeat_interleave: output size overflow",
        )?;
        let out_total =
            Self::checked_mul(outer, per_outer, "repeat_interleave: output size overflow")?;
        let _ = Self::checked_mul(
            out_total,
            std::mem::size_of::<f64>(),
            "repeat_interleave: output size overflow",
        )?;

        // No-grad block-copy fast path (f32/f64): repeat_interleave copies each `inner`-sized
        // input slice `rep_i` times into contiguous output. The general path below builds a full
        // out_total per-ELEMENT gather index (megabytes) and gathers through apply_function (which
        // UPCASTS f32->f64). Instead build a tiny per-BLOCK source map (out_total/inner entries)
        // and parallel block-copy the contiguous slices — borrow input zero-copy, output native
        // dtype. Bit-identical (pure movement). Grad / non-f32f64 / non-contiguous fall through.
        if !self.tensor_requires_grad(input)?
            && matches!(self.tensor_dtype(input)?, DType::F64 | DType::F32)
            && inner > 0
            && self.tensor_tape.tensor(input)?.meta().is_contiguous()
        {
            let final_shape: Vec<usize> = match axis {
                Some(d) => {
                    let mut s = shape.clone();
                    s[d] = out_axis_len;
                    s
                }
                None => vec![out_axis_len],
            };
            let mut block_src: Vec<usize> = Vec::with_capacity(out_total / inner);
            for o in 0..outer {
                let in_outer_base = o * axis_len * inner;
                for (i, &ri) in rep.iter().enumerate() {
                    let in_base = in_outer_base + i * inner;
                    for _ in 0..ri {
                        block_src.push(in_base);
                    }
                }
            }
            let parallel = out_total >= PARALLEL_ELEMENTWISE_MIN && block_src.len() >= 2;
            if self.tensor_dtype(input)? == DType::F64 {
                let vals = self.tensor_tape.tensor(input)?.contiguous_values()?;
                let mut result = vec![0.0_f64; out_total];
                let fill = |b: usize, out_block: &mut [f64]| {
                    let s = block_src[b];
                    out_block.copy_from_slice(&vals[s..s + inner]);
                };
                if parallel {
                    use rayon::prelude::*;
                    result
                        .par_chunks_mut(inner)
                        .enumerate()
                        .for_each(|(b, ob)| fill(b, ob));
                } else {
                    result
                        .chunks_mut(inner)
                        .enumerate()
                        .for_each(|(b, ob)| fill(b, ob));
                }
                return self.tensor_variable(result, final_shape, false);
            }
            let vals = self.tensor_tape.tensor(input)?.contiguous_values_f32()?;
            let mut result = vec![0.0_f32; out_total];
            let fill = |b: usize, out_block: &mut [f32]| {
                let s = block_src[b];
                out_block.copy_from_slice(&vals[s..s + inner]);
            };
            if parallel {
                use rayon::prelude::*;
                result
                    .par_chunks_mut(inner)
                    .enumerate()
                    .for_each(|(b, ob)| fill(b, ob));
            } else {
                result
                    .chunks_mut(inner)
                    .enumerate()
                    .for_each(|(b, ob)| fill(b, ob));
            }
            return self.tensor_variable_f32(result, final_shape, false);
        }

        // Map every output flat position to its source input flat position.
        // Output axis order is [slice0 x rep0, slice1 x rep1, ...] with `inner`
        // contiguous elements per slice, matching torch.
        let mut src_index: Vec<usize> = Vec::with_capacity(out_total);
        for o in 0..outer {
            let in_outer_base = o * axis_len * inner;
            for (i, &ri) in rep.iter().enumerate() {
                let in_base = in_outer_base + i * inner;
                for _ in 0..ri {
                    for k in 0..inner {
                        src_index.push(in_base + k);
                    }
                }
            }
        }

        let final_shape: Vec<usize> = match axis {
            Some(d) => {
                let mut s = shape.clone();
                s[d] = out_axis_len;
                s
            }
            None => vec![out_axis_len],
        };
        let in_numel: usize = shape.iter().product();
        let src_fwd = src_index.clone();
        let src_bwd = src_index;
        self.tensor_apply_function(
            &[input],
            move |_ctx, inputs| {
                let (vals, _s) = inputs[0];
                let result: Vec<f64> = src_fwd.iter().map(|&i| vals[i]).collect();
                Ok((result, final_shape.clone()))
            },
            move |_ctx, grad_outputs| {
                let g = grad_outputs[0];
                let mut grad_in = vec![0.0_f64; in_numel];
                for (out_pos, &gj) in g.iter().enumerate() {
                    grad_in[src_bwd[out_pos]] += gj;
                }
                Ok(vec![Some(grad_in)])
            },
        )
    }

    /// `torch.repeat_interleave(input, repeats: Tensor, dim=None)` — the
    /// repeats-TENSOR form (vs the `usize` / `&[usize]` host forms). Reads the
    /// 1-D non-negative-integer repeats tensor and delegates to the `&[usize]`
    /// core (which broadcasts a single-element repeats to a uniform count and
    /// validates the length, matching torch). frankentorch-c5d3a.
    pub fn tensor_repeat_interleave_repeats(
        &mut self,
        input: TensorNodeId,
        repeats: TensorNodeId,
        dim: Option<usize>,
    ) -> Result<TensorNodeId, AutogradError> {
        let rep_vals = self.tensor_values_lossy_f64(repeats)?;
        let mut reps: Vec<usize> = Vec::with_capacity(rep_vals.len());
        for &r in &rep_vals {
            if !r.is_finite() || r < 0.0 || r.fract() != 0.0 {
                return Err(Self::incompatible_tensor_args(
                    "repeat_interleave: repeats must be non-negative integers",
                ));
            }
            reps.push(r as usize);
        }
        self.tensor_repeat_interleave_tensor(input, &reps, dim)
    }

    /// Selects elements from input where mask is non-zero, returning a 1-D tensor.
    ///
    /// The mask must have the same number of elements as the input.
    /// Gradients flow to selected positions; masked-out positions receive zero gradient.
    pub fn tensor_masked_select(
        &mut self,
        input: TensorNodeId,
        mask: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let input_shape = self.tensor_shape(input)?;
        let mask_shape = self.tensor_shape(mask)?;
        // torch.masked_select broadcasts input and mask to a common shape, then
        // selects in row-major order. Broadcast both first (autograd-aware:
        // index_select's backward scatters to the broadcasted positions and
        // broadcast's backward sums the repeats back). frankentorch-ucxgj.
        let (input, mask, input_numel) = if input_shape == mask_shape {
            let n = Self::checked_shape_numel(&input_shape, "masked_select: input shape overflow")?;
            (input, mask, n)
        } else {
            let bshape = Self::broadcast_shape(&input_shape, &mask_shape)?;
            let n = Self::checked_shape_numel(&bshape, "masked_select: broadcast shape overflow")?;
            let bi = self.tensor_broadcast_to(input, bshape.clone())?;
            let bm = self.tensor_broadcast_to(mask, bshape)?;
            (bi, bm, n)
        };

        // No-grad parallel STREAM-COMPACTION fast path. The index_select path below first
        // UPCASTS the mask to f64 (lossy, 128MB at 16M) and SERIALLY filters it into an 8M
        // index Vec, then creates an index tensor + runs index_select = ~2x SLOWER than torch.
        // masked_select is a pure compaction: read input+mask SEQUENTIALLY in row-major order
        // and keep `input[i]` where `mask[i]!=0` — bandwidth-bound, not random like gather.
        // Per-chunk collect (parallel) + concat preserves row-major order => BIT-IDENTICAL to
        // the index_select gather (kept_idx is monotonic). Reads mask + input in their NATIVE
        // dtype (no f64 upcast). f32/f64 contiguous equal-shape no-grad only; broadcast-view /
        // non-contiguous / grad / other dtypes fall through.
        let ms_input_dtype = self.tensor_dtype(input)?;
        if !self.tensor_requires_grad(input)?
            && !self.tensor_requires_grad(mask)?
            && matches!(ms_input_dtype, DType::F64 | DType::F32)
        {
            use rayon::prelude::*;
            let mut built_f64: Option<Vec<f64>> = None;
            let mut built_f32: Option<Vec<f32>> = None;
            {
                let it = self.tensor_tape.tensor(input)?;
                let mt = self.tensor_tape.tensor(mask)?;
                if it.meta().is_contiguous() && mt.meta().is_contiguous() {
                    // mask -> bool in one parallel pass (native dtype, no f64 upcast).
                    let mask_true: Option<Vec<bool>> = match self.tensor_dtype(mask)? {
                        DType::F32 => Some(
                            mt.contiguous_values_f32()?
                                .par_iter()
                                .map(|&m| m != 0.0)
                                .collect(),
                        ),
                        DType::F64 => Some(
                            mt.contiguous_values()?
                                .par_iter()
                                .map(|&m| m != 0.0)
                                .collect(),
                        ),
                        _ => None,
                    };
                    if let Some(mask_true) = mask_true {
                        // ~1 chunk per thread: the per-chunk Vec alloc + concat dominates at
                        // high chunk counts (64t with threads*4 chunks was SLOWER than 8t), and
                        // a uniform compaction load-balances fine at 1 chunk/thread.
                        let nthreads = rayon::current_num_threads().max(1);
                        let grain = (mask_true.len() / nthreads).max(4096);
                        macro_rules! compact {
                            ($read:ident, $ty:ty) => {{
                                let data = it.$read()?;
                                if data.len() == mask_true.len() {
                                    let parts: Vec<Vec<$ty>> = data
                                        .par_chunks(grain)
                                        .zip(mask_true.par_chunks(grain))
                                        .map(|(dch, mch)| {
                                            let mut v: Vec<$ty> = Vec::new();
                                            for (i, &keep) in mch.iter().enumerate() {
                                                if keep {
                                                    v.push(dch[i]);
                                                }
                                            }
                                            v
                                        })
                                        .collect();
                                    let total: usize = parts.iter().map(|p| p.len()).sum();
                                    // Small outputs: serial concat is bandwidth-cheap. Large outputs
                                    // (>= copy-tier fault-parallelism crossover): the serial concat
                                    // DOMINATES (measured ~3x slower than a parallel copy at dens>=0.5,
                                    // 16M — the whole per-chunk-collect win was being eaten by the
                                    // single-threaded final concat) — so scatter the per-chunk parts
                                    // into disjoint slices of a preallocated buffer across the pool.
                                    // Order-preserving (parts are in row-major chunk order, offsets are
                                    // their prefix sums) => BIT-IDENTICAL to the serial concat /
                                    // index_select gather.
                                    if total < MOVEMENT_COPY_PARALLEL_MIN {
                                        let mut out: Vec<$ty> = Vec::with_capacity(total);
                                        for p in &parts {
                                            out.extend_from_slice(p);
                                        }
                                        Some(out)
                                    } else {
                                        let mut out: Vec<$ty> = vec![0 as $ty; total];
                                        let mut slices: Vec<&mut [$ty]> =
                                            Vec::with_capacity(parts.len());
                                        {
                                            let mut rest = &mut out[..];
                                            for p in &parts {
                                                let (l, r) = rest.split_at_mut(p.len());
                                                slices.push(l);
                                                rest = r;
                                            }
                                        }
                                        slices
                                            .into_par_iter()
                                            .zip(parts.par_iter())
                                            .for_each(|(sl, p)| sl.copy_from_slice(p));
                                        Some(out)
                                    }
                                } else {
                                    None
                                }
                            }};
                        }
                        match ms_input_dtype {
                            DType::F64 => built_f64 = compact!(contiguous_values, f64),
                            DType::F32 => built_f32 = compact!(contiguous_values_f32, f32),
                            _ => {}
                        }
                    }
                }
            }
            if let Some(out) = built_f64 {
                let len = out.len();
                return self.tensor_variable(out, vec![len], false);
            }
            if let Some(out) = built_f32 {
                let len = out.len();
                return self.tensor_variable_f32(out, vec![len], false);
            }
        }

        // Gather the kept elements via index_select on the flattened input: this
        // preserves the input dtype (incl. f16/bf16, now that index_select handles
        // them) and stays autograd-aware — index_select's backward scatters grad
        // to the selected flat positions, identical to the previous custom-op
        // gradient. The old tensor_apply_function path upcast the result to f64.
        // frankentorch-u78p.
        let mask_vals = self.tensor_values_lossy_f64(mask)?;
        let kept_idx: Vec<f64> = mask_vals
            .iter()
            .enumerate()
            .filter(|&(_, &m)| m != 0.0)
            .map(|(i, _)| i as f64)
            .collect();
        let flat = self.tensor_reshape(input, vec![input_numel])?;
        let n_kept = kept_idx.len();
        let idx = self.tensor_variable(kept_idx, vec![n_kept], false)?;
        self.tensor_index_select(flat, 0, idx)
    }

    /// Binary search for insertion positions of `values` in a sorted sequence.
    ///
    /// For 1-D `sorted_sequence`, returns a tensor where each element is the index
    /// at which the corresponding element of `values` should be inserted to maintain
    /// sorted order.
    ///
    /// * `right=false` (default): returns the leftmost suitable position (lower_bound)
    /// * `right=true`: returns the rightmost suitable position (upper_bound)
    ///
    /// The result is a non-differentiable leaf tensor.
    pub fn tensor_searchsorted(
        &mut self,
        sorted_sequence: TensorNodeId,
        values: TensorNodeId,
        right: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_searchsorted_sorter(sorted_sequence, values, right, None)
    }

    /// `torch.searchsorted(sorted_sequence, values, *, right, sorter)`.
    ///
    /// When `sorter` is supplied it is an index tensor of the SAME shape as
    /// `sorted_sequence` such that gathering `sorted_sequence` by `sorter`
    /// along the innermost dim yields an ascending sequence (i.e. `sorter`
    /// is its argsort). The returned indices are positions in that sorted
    /// order, exactly as if `sorted_sequence` had been pre-sorted — matching
    /// torch. Output is a non-differentiable integer-index leaf.
    pub fn tensor_searchsorted_sorter(
        &mut self,
        sorted_sequence: TensorNodeId,
        values: TensorNodeId,
        right: bool,
        sorter: Option<TensorNodeId>,
    ) -> Result<TensorNodeId, AutogradError> {
        let seq_shape = self.tensor_shape(sorted_sequence)?;
        let val_shape = self.tensor_shape(values)?;
        let seq_dtype = self.tensor_dtype(sorted_sequence)?;
        let val_dtype = self.tensor_dtype(values)?;

        let (seq_f64, seq_f32, val_f64, val_f32) = match (seq_dtype, val_dtype) {
            (DType::F64, DType::F64) => (
                Some(self.tensor_values(sorted_sequence)?),
                None,
                Some(self.tensor_values(values)?),
                None,
            ),
            (DType::F32, DType::F32) => (
                None,
                Some(self.tensor_values_f32(sorted_sequence)?),
                None,
                Some(self.tensor_values_f32(values)?),
            ),
            _ => {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "searchsorted requires matching f32 or f64 tensors",
                    },
                )));
            }
        };

        // Apply `sorter` by materializing the sorted sequence: each innermost
        // block of `sorted_sequence` is reordered by the block's indices in
        // `sorter`, so the downstream binary search runs on ascending data and
        // returns sorted-order ranks (torch semantics).
        let (seq_f64, seq_f32) = match sorter {
            None => (seq_f64, seq_f32),
            Some(sorter_id) => {
                let sorter_shape = self.tensor_shape(sorter_id)?;
                if sorter_shape != seq_shape {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "searchsorted: sorter must have the same shape as sorted_sequence",
                        },
                    )));
                }
                if seq_shape.len() != 1 && seq_shape.len() != 2 {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "searchsorted: sorted_sequence must be 1-D or 2-D",
                        },
                    )));
                }
                let inner = seq_shape[seq_shape.len() - 1];
                let sidx = self.tensor_values_lossy_f64(sorter_id)?;
                for &s in &sidx {
                    if !s.is_finite() || s < 0.0 || (s as usize) >= inner {
                        return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                            ft_dispatch::DispatchKeyError::IncompatibleSet {
                                reason: "searchsorted: sorter index out of range for sorted_sequence",
                            },
                        )));
                    }
                }
                let permuted_f64 = seq_f64.as_ref().map(|seq| {
                    let mut out = vec![0.0f64; seq.len()];
                    for base in (0..seq.len()).step_by(inner.max(1)) {
                        for i in 0..inner {
                            out[base + i] = seq[base + sidx[base + i] as usize];
                        }
                    }
                    out
                });
                let permuted_f32 = seq_f32.as_ref().map(|seq| {
                    let mut out = vec![0.0f32; seq.len()];
                    for base in (0..seq.len()).step_by(inner.max(1)) {
                        for i in 0..inner {
                            out[base + i] = seq[base + sidx[base + i] as usize];
                        }
                    }
                    out
                });
                (permuted_f64, permuted_f32)
            }
        };

        if seq_shape.len() == 1 {
            // 1-D sorted sequence: search for each value
            // Each value's binary search over the shared 1-D sorted sequence is
            // independent and deterministic; distribute the queries across the rayon
            // pool above the threshold (par_iter preserves index order → bit-identical
            // to the serial map). frankentorch-kgs4.99.
            let indices: Vec<f64> = if let (Some(seq_vals), Some(val_vals)) = (seq_f64, val_f64) {
                let n = seq_vals.len();
                let uniform = uniform_searchsorted_f64(&seq_vals);
                let f = |&v: &f64| match uniform {
                    Some(model) => {
                        if right {
                            upper_bound_uniform_f64(&seq_vals, v, model) as f64
                        } else {
                            lower_bound_uniform_f64(&seq_vals, v, model) as f64
                        }
                    }
                    None => {
                        if right {
                            upper_bound(&seq_vals, v, n) as f64
                        } else {
                            lower_bound(&seq_vals, v, n) as f64
                        }
                    }
                };
                if val_vals.len() >= PARALLEL_ELEMENTWISE_MIN {
                    use rayon::prelude::*;
                    val_vals.par_iter().map(f).collect()
                } else {
                    val_vals.iter().map(f).collect()
                }
            } else if let (Some(seq_vals), Some(val_vals)) = (seq_f32, val_f32) {
                let n = seq_vals.len();
                let f = |&v: &f32| {
                    if right {
                        upper_bound_f32(&seq_vals, v, n) as f64
                    } else {
                        lower_bound_f32(&seq_vals, v, n) as f64
                    }
                };
                if val_vals.len() >= PARALLEL_ELEMENTWISE_MIN {
                    use rayon::prelude::*;
                    val_vals.par_iter().map(f).collect()
                } else {
                    val_vals.iter().map(f).collect()
                }
            } else {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "searchsorted: failed to resolve storage",
                    },
                )));
            };
            self.tensor_tape.leaf(indices, val_shape, false)
        } else if seq_shape.len() == 2 && val_shape.len() == 2 {
            // 2-D batched: seq [B, S], values [B, V]
            let batch = seq_shape[0];
            let seq_len = seq_shape[1];
            if val_shape[0] != batch {
                // Surface both full shapes so caller can see
                // which batch sizes were given (frankentorch-p947).
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                    ft_kernel_cpu::KernelError::ShapeMismatch {
                        lhs: seq_shape.clone(),
                        rhs: val_shape.clone(),
                    },
                )));
            }
            let num_vals = val_shape[1];
            let total = Self::checked_mul(batch, num_vals, "searchsorted output size overflow")?;
            // Each (b, v_idx) query is an independent binary search over its batch's
            // sorted slice, written to output position b*num_vals + v_idx. Distribute
            // the queries across the rayon pool: the per-query log(seq_len) branchy
            // comparisons + slice index math are compute-bound, and `into_par_iter()
            // .map().collect()` preserves index order, so the result is bit-identical
            // to the serial nested loop. frankentorch-kgs4.99.
            let indices: Vec<f64> = if let (Some(seq_vals), Some(val_vals)) = (seq_f64, val_f64) {
                let eval = |i: usize| {
                    let b = i / num_vals;
                    let seq_slice = &seq_vals[b * seq_len..(b + 1) * seq_len];
                    let v = val_vals[i];
                    let idx = if right {
                        upper_bound(seq_slice, v, seq_len)
                    } else {
                        lower_bound(seq_slice, v, seq_len)
                    };
                    idx as f64
                };
                if total >= PARALLEL_ELEMENTWISE_MIN {
                    use rayon::prelude::*;
                    (0..total).into_par_iter().map(eval).collect()
                } else {
                    (0..total).map(eval).collect()
                }
            } else if let (Some(seq_vals), Some(val_vals)) = (seq_f32, val_f32) {
                let eval = |i: usize| {
                    let b = i / num_vals;
                    let seq_slice = &seq_vals[b * seq_len..(b + 1) * seq_len];
                    let v = val_vals[i];
                    let idx = if right {
                        upper_bound_f32(seq_slice, v, seq_len)
                    } else {
                        lower_bound_f32(seq_slice, v, seq_len)
                    };
                    idx as f64
                };
                if total >= PARALLEL_ELEMENTWISE_MIN {
                    use rayon::prelude::*;
                    (0..total).into_par_iter().map(eval).collect()
                } else {
                    (0..total).map(eval).collect()
                }
            } else {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "searchsorted: failed to resolve storage",
                    },
                )));
            };
            self.tensor_tape.leaf(indices, val_shape, false)
        } else {
            Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "searchsorted: sorted_sequence must be 1-D or 2-D",
                },
            )))
        }
    }

    /// `torch.searchsorted(sorted_sequence, values, *, side, sorter)`.
    ///
    /// `side` is torch's string alternative to the `right` boolean: `"left"`
    /// (first index where the value could be inserted keeping order, == the
    /// default `right=false`) or `"right"` (last such index, == `right=true`).
    /// torch forbids combining `side="left"` with `right=true`; here `side` is
    /// the sole selector so the two can't contradict.
    pub fn tensor_searchsorted_side(
        &mut self,
        sorted_sequence: TensorNodeId,
        values: TensorNodeId,
        side: &str,
        sorter: Option<TensorNodeId>,
    ) -> Result<TensorNodeId, AutogradError> {
        let right = match side {
            "left" => false,
            "right" => true,
            _ => {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "searchsorted: side must be \"left\" or \"right\"",
                    },
                )));
            }
        };
        self.tensor_searchsorted_sorter(sorted_sequence, values, right, sorter)
    }

    /// Maps each element of `input` to a bucket index based on `boundaries`.
    ///
    /// Equivalent to `searchsorted(boundaries, input, right)`.
    /// Returns a non-differentiable leaf tensor of bucket indices.
    pub fn tensor_bucketize(
        &mut self,
        input: TensorNodeId,
        boundaries: TensorNodeId,
        right: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_searchsorted(boundaries, input, right)
    }

    /// Sort a tensor along the given dimension.
    ///
    /// Returns `(sorted_values_tensor, indices)` where indices contains the original
    /// positions of elements along the sorted dimension. Gradients flow back through
    /// the sorted values tensor.
    pub fn tensor_sort(
        &mut self,
        input: TensorNodeId,
        dim: usize,
        descending: bool,
    ) -> Result<(TensorNodeId, Vec<usize>), AutogradError> {
        let (out, indices, event) = self.tensor_tape.sort(input, dim, descending, self.mode())?;
        self.record_tensor_sort_operation(&event);
        Ok((out, indices))
    }

    /// `torch.msort(input)` parity alias for `tensor_sort` along
    /// dim 0 in ascending order.
    ///
    /// PyTorch's `torch.msort` is a NumPy-inheritance alias that
    /// always sorts along dim=0 ascending. ft-api had only the
    /// general `tensor_sort`; PyTorch code using `torch.msort`
    /// fails to compile without this alias. Tracked under
    /// frankentorch-4bra.
    pub fn tensor_msort(
        &mut self,
        input: TensorNodeId,
    ) -> Result<(TensorNodeId, Vec<usize>), AutogradError> {
        self.tensor_sort(input, 0, false)
    }

    /// Return the k largest (or smallest) elements along the given dimension.
    ///
    /// Returns `(values_tensor, indices)`. By default, returns the k largest elements
    /// in sorted order. Gradients flow back through the values tensor.
    fn topk_dim0_nograd_fast_path(
        &mut self,
        input: TensorNodeId,
        k: usize,
        dim: usize,
        largest: bool,
        sorted: bool,
    ) -> Result<Option<(TensorNodeId, Vec<usize>)>, AutogradError> {
        if dim != 0
            || (self.tensor_tape.tensor_requires_grad(input)? && self.tensor_tape.is_grad_enabled())
        {
            return Ok(None);
        }

        let prepared = {
            let tensor = self.tensor_tape.tensor(input)?;
            let meta = tensor.meta().clone();
            let shape = meta.shape();
            if shape.is_empty() || !meta.is_contiguous() {
                return Ok(None);
            }
            let rows = shape[0];
            if k > rows || rows < 1024 || k > 64 {
                return Ok(None);
            }
            let inner_size = meta.numel() / rows.max(1);
            if inner_size < 2 {
                return Ok(None);
            }
            let mut out_shape = shape.to_vec();
            out_shape[0] = k;
            let out_meta = TensorMeta::from_shape(out_shape, meta.dtype(), meta.device());
            let keyset = dispatch_keyset_for_single_tensor_meta(&meta, false);
            let offset = meta.storage_offset();
            let input_numel = meta.numel();

            match tensor.typed_storage() {
                TensorStorage::F64(values) => {
                    if offset + input_numel > values.len() {
                        return Ok(None);
                    }
                    let (out_values, indices) = Self::topk_dim0_parallel_f64(
                        &values[offset..offset + input_numel],
                        rows,
                        inner_size,
                        k,
                        largest,
                        sorted,
                    );
                    Some((
                        out_meta,
                        TensorStorage::F64(Arc::new(out_values)),
                        indices,
                        "api::topk_dim0_nograd_parallel_f64",
                        keyset.bits(),
                    ))
                }
                TensorStorage::F32(values) => {
                    if offset + input_numel > values.len() {
                        return Ok(None);
                    }
                    let (out_values, indices) = Self::topk_dim0_parallel_f32(
                        &values[offset..offset + input_numel],
                        rows,
                        inner_size,
                        k,
                        largest,
                        sorted,
                    );
                    Some((
                        out_meta,
                        TensorStorage::F32(Arc::new(out_values)),
                        indices,
                        "api::topk_dim0_nograd_parallel_f32",
                        keyset.bits(),
                    ))
                }
                _ => None,
            }
        };

        let Some((out_meta, storage, indices, kernel, keyset_bits)) = prepared else {
            return Ok(None);
        };
        let output = DenseTensor::from_typed_storage(out_meta, storage)?;
        let out = self.tensor_tape.leaf_tensor(output, false);
        self.record_tensor_topk_operation(&TensorTopKOperationEvent {
            input,
            out,
            k,
            dim,
            decision: ft_dispatch::TopKDispatchDecision {
                k,
                dim,
                largest,
                sorted,
                mode: self.mode(),
                kernel,
                selected_key: ft_dispatch::DispatchKey::CPU,
                backend_key: ft_dispatch::DispatchKey::CPU,
                keyset_bits,
                fallback_used: false,
            },
        });
        Ok(Some((out, indices)))
    }

    fn topk_nan_greatest_cmp_f64(a: f64, b: f64) -> std::cmp::Ordering {
        match (a.is_nan(), b.is_nan()) {
            (true, true) => std::cmp::Ordering::Equal,
            (true, false) => std::cmp::Ordering::Greater,
            (false, true) => std::cmp::Ordering::Less,
            (false, false) => a.partial_cmp(&b).unwrap_or(std::cmp::Ordering::Equal),
        }
    }

    fn topk_lane_cmp_f64(a: &(usize, f64), b: &(usize, f64), largest: bool) -> std::cmp::Ordering {
        let value_order = if largest {
            Self::topk_nan_greatest_cmp_f64(b.1, a.1)
        } else {
            Self::topk_nan_greatest_cmp_f64(a.1, b.1)
        };
        value_order.then_with(|| a.0.cmp(&b.0))
    }

    fn topk_nan_greatest_cmp_f32(a: f32, b: f32) -> std::cmp::Ordering {
        match (a.is_nan(), b.is_nan()) {
            (true, true) => std::cmp::Ordering::Equal,
            (true, false) => std::cmp::Ordering::Greater,
            (false, true) => std::cmp::Ordering::Less,
            (false, false) => a.partial_cmp(&b).unwrap_or(std::cmp::Ordering::Equal),
        }
    }

    fn topk_lane_cmp_f32(a: &(usize, f32), b: &(usize, f32), largest: bool) -> std::cmp::Ordering {
        let value_order = if largest {
            Self::topk_nan_greatest_cmp_f32(b.1, a.1)
        } else {
            Self::topk_nan_greatest_cmp_f32(a.1, b.1)
        };
        value_order.then_with(|| a.0.cmp(&b.0))
    }

    fn topk_dim0_parallel_f64(
        input: &[f64],
        rows: usize,
        inner_size: usize,
        k: usize,
        largest: bool,
        sorted: bool,
    ) -> (Vec<f64>, Vec<usize>) {
        use rayon::prelude::*;

        let out_numel = k * inner_size;
        if out_numel == 0 {
            return (Vec::new(), Vec::new());
        }
        let columns: Vec<(usize, Vec<(usize, f64)>)> = (0..inner_size)
            .into_par_iter()
            .map(|inner| {
                let mut selected = Vec::with_capacity(k);
                for row in 0..rows {
                    let candidate = (row, input[row * inner_size + inner]);
                    if selected.len() < k {
                        selected.push(candidate);
                        let mut pos = selected.len() - 1;
                        while pos > 0
                            && Self::topk_lane_cmp_f64(&selected[pos], &selected[pos - 1], largest)
                                == std::cmp::Ordering::Less
                        {
                            selected.swap(pos, pos - 1);
                            pos -= 1;
                        }
                    } else if Self::topk_lane_cmp_f64(&candidate, &selected[k - 1], largest)
                        == std::cmp::Ordering::Less
                    {
                        selected[k - 1] = candidate;
                        let mut pos = k - 1;
                        while pos > 0
                            && Self::topk_lane_cmp_f64(&selected[pos], &selected[pos - 1], largest)
                                == std::cmp::Ordering::Less
                        {
                            selected.swap(pos, pos - 1);
                            pos -= 1;
                        }
                    }
                }
                if !sorted {
                    selected.sort_by_key(|(orig_idx, _)| *orig_idx);
                }
                (inner, selected)
            })
            .collect();

        let mut out_values = vec![0.0; out_numel];
        let mut out_indices = vec![0usize; out_numel];
        for (inner, selected) in columns {
            for (out_d, (orig_d, value)) in selected.into_iter().enumerate() {
                let out_idx = out_d * inner_size + inner;
                out_values[out_idx] = value;
                out_indices[out_idx] = orig_d;
            }
        }
        (out_values, out_indices)
    }

    fn topk_dim0_parallel_f32(
        input: &[f32],
        rows: usize,
        inner_size: usize,
        k: usize,
        largest: bool,
        sorted: bool,
    ) -> (Vec<f32>, Vec<usize>) {
        use rayon::prelude::*;

        let out_numel = k * inner_size;
        if out_numel == 0 {
            return (Vec::new(), Vec::new());
        }
        let columns: Vec<(usize, Vec<(usize, f32)>)> = (0..inner_size)
            .into_par_iter()
            .map(|inner| {
                let mut selected = Vec::with_capacity(k);
                for row in 0..rows {
                    let candidate = (row, input[row * inner_size + inner]);
                    if selected.len() < k {
                        selected.push(candidate);
                        let mut pos = selected.len() - 1;
                        while pos > 0
                            && Self::topk_lane_cmp_f32(&selected[pos], &selected[pos - 1], largest)
                                == std::cmp::Ordering::Less
                        {
                            selected.swap(pos, pos - 1);
                            pos -= 1;
                        }
                    } else if Self::topk_lane_cmp_f32(&candidate, &selected[k - 1], largest)
                        == std::cmp::Ordering::Less
                    {
                        selected[k - 1] = candidate;
                        let mut pos = k - 1;
                        while pos > 0
                            && Self::topk_lane_cmp_f32(&selected[pos], &selected[pos - 1], largest)
                                == std::cmp::Ordering::Less
                        {
                            selected.swap(pos, pos - 1);
                            pos -= 1;
                        }
                    }
                }
                if !sorted {
                    selected.sort_by_key(|(orig_idx, _)| *orig_idx);
                }
                (inner, selected)
            })
            .collect();

        let mut out_values = vec![0.0; out_numel];
        let mut out_indices = vec![0usize; out_numel];
        for (inner, selected) in columns {
            for (out_d, (orig_d, value)) in selected.into_iter().enumerate() {
                let out_idx = out_d * inner_size + inner;
                out_values[out_idx] = value;
                out_indices[out_idx] = orig_d;
            }
        }
        (out_values, out_indices)
    }

    pub fn tensor_topk(
        &mut self,
        input: TensorNodeId,
        k: usize,
        dim: usize,
        largest: bool,
        sorted: bool,
    ) -> Result<(TensorNodeId, Vec<usize>), AutogradError> {
        if let Some(result) = self.topk_dim0_nograd_fast_path(input, k, dim, largest, sorted)? {
            return Ok(result);
        }
        let (out, indices, event) =
            self.tensor_tape
                .topk(input, k, dim, largest, sorted, self.mode())?;
        self.record_tensor_topk_operation(&event);
        Ok((out, indices))
    }

    /// Cross-entropy loss for classification.
    ///
    /// Applies log_softmax to `logits` along the last dimension, then computes
    /// NLL loss against `targets` (class indices as f64).
    ///
    /// Equivalent to PyTorch's `F.cross_entropy(logits, targets)`.
    pub fn cross_entropy_loss(
        &mut self,
        logits: TensorNodeId,
        targets: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        self.cross_entropy_loss_with_smoothing(logits, targets, 0.0)
    }

    /// Cross-entropy loss with optional label smoothing.
    ///
    /// When `label_smoothing > 0`, the target distribution is smoothed:
    /// `y_smooth = (1 - s) * one_hot(target) + s / num_classes`
    ///
    /// Mathematically: `loss = (1 - s) * nll_loss + s * (-mean(log_probs))`
    ///
    /// Equivalent to PyTorch's `F.cross_entropy(logits, targets, label_smoothing=s)`.
    pub fn cross_entropy_loss_with_smoothing(
        &mut self,
        logits: TensorNodeId,
        targets: TensorNodeId,
        label_smoothing: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(logits)?;
        if shape.is_empty() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::InvalidDimension { dim: 0, ndim: 0 },
            )));
        }
        let last_dim = shape.len() - 1;
        let log_probs = self.tensor_log_softmax(logits, last_dim)?;

        if label_smoothing == 0.0 {
            return self.nll_loss(log_probs, targets);
        }

        // Smoothed cross-entropy:
        // loss = (1 - s) * nll_loss(log_probs, targets) + s * (-mean(log_probs))
        // Compose through tensor_lerp so the autograd tape carries
        // gradients to log_probs (and hence back to logits). The
        // previous body extracted scalar values + rebuilt a
        // requires_grad=false leaf, silently severing autograd for
        // the label-smoothing training path. Tracked under
        // frankentorch-ilwr.
        let nll = self.nll_loss(log_probs, targets)?;
        let uniform_loss = {
            let neg_log_probs = self.tensor_neg(log_probs)?;
            self.tensor_mean(neg_log_probs)?
        };
        // tensor_lerp(start, end, w) = start * (1 - w) + end * w
        // → blended = nll * (1 - s) + uniform_loss * s, exactly the
        // smoothed-CE definition.
        self.tensor_lerp(nll, uniform_loss, label_smoothing)
    }

    /// Return indices that would sort the tensor along a dimension.
    ///
    /// Returns the permutation of indices as f64 values in a new tensor.
    pub fn tensor_argsort(
        &mut self,
        input: TensorNodeId,
        dim: usize,
        descending: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        let meta = self.tensor_tape.tensor_meta(input)?.clone();
        let shape = meta.shape().to_vec();
        let indices = match meta.dtype() {
            DType::F64 => {
                let values = self.tensor_values(input)?;
                ft_kernel_cpu::argsort_tensor_contiguous_f64(&values, &meta, dim, descending)
                    .map_err(|error| {
                        AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(error))
                    })?
            }
            DType::F32 => {
                let values = self.tensor_values_f32(input)?;
                ft_kernel_cpu::argsort_tensor_contiguous_f32(&values, &meta, dim, descending)
                    .map_err(|error| {
                        AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(error))
                    })?
            }
            dtype => {
                return Err(AutogradError::DenseTensor(
                    ft_core::DenseTensorError::UnsupportedDType(dtype),
                ));
            }
        };
        let indices_f64: Vec<f64> = indices.iter().map(|&i| i as f64).collect();
        self.tensor_tape.leaf(indices_f64, shape, false)
    }

    /// One-hot encoding: converts class indices to binary vectors.
    ///
    /// Input should contain integer indices in `[0, num_classes)` stored as f64.
    /// Returns a tensor with an additional trailing dimension of size `num_classes`.
    pub fn one_hot(
        &mut self,
        indices: TensorNodeId,
        num_classes: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        if self.tensor_requires_grad(indices)? {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "one_hot: autograd not supported (binary mask from integer indices is non-differentiable). Tracked under frankentorch-sjcw.",
                },
            )));
        }
        let (idx_vals, idx_meta) = self.tensor_values_meta(indices)?;
        let idx_shape = idx_meta.shape().to_vec();
        let total = idx_vals.len();
        let mut output = vec![0.0; total * num_classes];
        for (i, &idx) in idx_vals.iter().enumerate() {
            let class = idx as usize;
            if !idx.is_finite() || class >= num_classes || idx < 0.0 || idx != idx.floor() {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "one_hot index out of range or not a finite integer",
                    },
                )));
            }
            output[i * num_classes + class] = 1.0;
        }
        let mut out_shape = idx_shape;
        out_shape.push(num_classes);
        self.tensor_tape.leaf(output, out_shape, false)
    }

    /// Constant-value padding along each dimension.
    ///
    /// `padding` is specified as pairs `[before_last, after_last, before_second_last, ...]`
    /// matching PyTorch's `F.pad` convention (innermost dimension first).
    pub fn tensor_pad(
        &mut self,
        input: TensorNodeId,
        padding: &[usize],
        value: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        // No-grad block-copy fast path. The tape pad clones the input and builds the output
        // by a per-OUTPUT-ELEMENT O(ndim) coordinate decode (~16M divides for a 4k×4k pad,
        // measured 3.7x SLOWER than torch). But constant padding is pure contiguous data
        // movement: each input row maps to exactly one contiguous run in the output (offset
        // by the last-dim pad), every other output element is `value`. Memset the border
        // value once (calloc-fast for the common value==0.0 case), then block-copy each input
        // row into its run — ~out_outer ROW decodes instead of out_numel ELEMENT decodes.
        // Bit-identical to the tape pad (same values, each output written once). f64/f32
        // contiguous no-grad only; other dtypes / non-contiguous / grad / empty fall through.
        let dtype = self.tensor_dtype(input)?;
        if padding.len().is_multiple_of(2)
            && !self.tensor_requires_grad(input)?
            && matches!(dtype, DType::F64 | DType::F32)
        {
            let shape = self.tensor_shape(input)?;
            let ndim = shape.len();
            let num_pad_dims = padding.len() / 2;
            if ndim >= 1 && num_pad_dims <= ndim && !shape.contains(&0) {
                // Build out_shape + per-dim pad_before, bailing to the tape on any overflow.
                let mut out_shape = shape.clone();
                let mut pad_before = vec![0usize; ndim];
                let mut ok = true;
                for i in 0..num_pad_dims {
                    let dim = ndim - 1 - i;
                    pad_before[dim] = padding[i * 2];
                    match padding[i * 2]
                        .checked_add(padding[i * 2 + 1])
                        .and_then(|pt| shape[dim].checked_add(pt))
                    {
                        Some(v) => out_shape[dim] = v,
                        None => {
                            ok = false;
                            break;
                        }
                    }
                }
                let out_numel = if ok {
                    out_shape
                        .iter()
                        .try_fold(1usize, |acc, &d| acc.checked_mul(d))
                } else {
                    None
                };
                if let Some(out_numel) = out_numel {
                    let in_last = shape[ndim - 1];
                    let out_last = out_shape[ndim - 1];
                    let pad_left_last = pad_before[ndim - 1];
                    if out_last > 0 && out_numel > 0 {
                        // Build into a typed Option inside a scope that drops the input borrow
                        // (`it`) before the &mut self construct call below. f64 and f32 share
                        // the identical row-decode + block-copy; only the borrow accessor, the
                        // fill cast, and the constructor differ.
                        let mut out_f64: Option<Vec<f64>> = None;
                        let mut out_f32: Option<Vec<f32>> = None;
                        {
                            let it = self.tensor_tape.tensor(input)?;
                            if it.meta().is_contiguous() {
                                use rayon::prelude::*;
                                let out_outer_strides =
                                    ft_core::contiguous_strides(&out_shape[..ndim - 1]);
                                let in_outer_strides =
                                    ft_core::contiguous_strides(&shape[..ndim - 1]);
                                match dtype {
                                    DType::F64 => {
                                        let id = it.contiguous_values()?;
                                        let mut out = vec![0.0f64; out_numel];
                                        let fill_row = value.to_bits() != 0.0f64.to_bits();
                                        let do_row = |orow: usize, chunk: &mut [_]| {
                                            if fill_row {
                                                chunk.fill(value);
                                            }
                                            let mut rem = orow;
                                            let mut in_row = 0usize;
                                            let mut interior = true;
                                            for d in 0..ndim - 1 {
                                                let oc = rem / out_outer_strides[d];
                                                rem %= out_outer_strides[d];
                                                if oc < pad_before[d]
                                                    || oc >= pad_before[d] + shape[d]
                                                {
                                                    interior = false;
                                                    break;
                                                }
                                                in_row +=
                                                    (oc - pad_before[d]) * in_outer_strides[d];
                                            }
                                            if interior {
                                                let base = in_row * in_last;
                                                chunk[pad_left_last..pad_left_last + in_last]
                                                    .copy_from_slice(&id[base..base + in_last]);
                                            }
                                        };
                                        // Pure fill+copy: gate at the fault-parallelism crossover,
                                        // not unconditionally (regresses small/medium pads 2-14x).
                                        // Bit-identical.
                                        if out_numel >= MOVEMENT_COPY_PARALLEL_MIN {
                                            out.par_chunks_mut(out_last)
                                                .enumerate()
                                                .for_each(|(orow, chunk)| do_row(orow, chunk));
                                        } else {
                                            out.chunks_mut(out_last)
                                                .enumerate()
                                                .for_each(|(orow, chunk)| do_row(orow, chunk));
                                        }
                                        out_f64 = Some(out);
                                    }
                                    DType::F32 => {
                                        let id = it.contiguous_values_f32()?;
                                        let fill = value as f32;
                                        let mut out = vec![0.0f32; out_numel];
                                        let fill_row = fill.to_bits() != 0.0f32.to_bits();
                                        let do_row = |orow: usize, chunk: &mut [_]| {
                                            if fill_row {
                                                chunk.fill(fill);
                                            }
                                            let mut rem = orow;
                                            let mut in_row = 0usize;
                                            let mut interior = true;
                                            for d in 0..ndim - 1 {
                                                let oc = rem / out_outer_strides[d];
                                                rem %= out_outer_strides[d];
                                                if oc < pad_before[d]
                                                    || oc >= pad_before[d] + shape[d]
                                                {
                                                    interior = false;
                                                    break;
                                                }
                                                in_row +=
                                                    (oc - pad_before[d]) * in_outer_strides[d];
                                            }
                                            if interior {
                                                let base = in_row * in_last;
                                                chunk[pad_left_last..pad_left_last + in_last]
                                                    .copy_from_slice(&id[base..base + in_last]);
                                            }
                                        };
                                        // Pure fill+copy: gate (see MOVEMENT_COPY_PARALLEL_MIN);
                                        // f32 mirror of the f64 pad path above. Bit-identical.
                                        if out_numel >= MOVEMENT_COPY_PARALLEL_MIN {
                                            out.par_chunks_mut(out_last)
                                                .enumerate()
                                                .for_each(|(orow, chunk)| do_row(orow, chunk));
                                        } else {
                                            out.chunks_mut(out_last)
                                                .enumerate()
                                                .for_each(|(orow, chunk)| do_row(orow, chunk));
                                        }
                                        out_f32 = Some(out);
                                    }
                                    _ => {}
                                }
                            }
                        }
                        if let Some(out) = out_f64 {
                            return self.tensor_variable(out, out_shape, false);
                        }
                        if let Some(out) = out_f32 {
                            return self.tensor_variable_f32(out, out_shape, false);
                        }
                    }
                }
            }
        }
        self.tensor_tape.pad(input, padding, value)
    }

    /// Pad a tensor with the specified mode.
    ///
    /// Equivalent to `torch.nn.functional.pad(input, pad, mode, value)`.
    ///
    /// Modes:
    /// - `"constant"`: pad with `value` (default 0.0)
    /// - `"reflect"`: reflect padding (last element not repeated)
    /// - `"replicate"`: replicate edge values
    /// - `"circular"`: circular (wrap-around) padding
    ///
    /// `padding` uses PyTorch convention: `[left, right]` for 1D,
    /// `[left, right, top, bottom]` for 2D, etc. (innermost dim first).
    pub fn tensor_pad_mode(
        &mut self,
        input: TensorNodeId,
        padding: &[usize],
        mode: &str,
        value: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        if mode == "constant" {
            return self.tensor_pad(input, padding, value);
        }

        if !padding.len().is_multiple_of(2) {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "pad: padding must have even number of elements",
                },
            )));
        }

        let meta = {
            let tensor = self.tensor_tape.tensor(input)?;
            tensor.meta().clone()
        };
        let shape = meta.shape();
        let ndim = shape.len();
        let num_pad_dims = padding.len() / 2;

        if num_pad_dims > ndim {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "pad: padding specifies more dimensions than input has",
                },
            )));
        }

        // Build output shape
        let overflow_error = || {
            AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "pad: output shape overflow",
                },
            ))
        };

        let mut out_shape = shape.to_vec();
        for i in 0..num_pad_dims {
            let dim = ndim - 1 - i;
            let pad_total = padding[i * 2]
                .checked_add(padding[i * 2 + 1])
                .ok_or_else(overflow_error)?;
            out_shape[dim] = shape[dim]
                .checked_add(pad_total)
                .ok_or_else(overflow_error)?;
        }

        // Build per-dim pad_before
        let mut pad_before = vec![0usize; ndim];
        let mut pad_after = vec![0usize; ndim];
        for i in 0..num_pad_dims {
            let dim = ndim - 1 - i;
            pad_before[dim] = padding[i * 2];
            pad_after[dim] = padding[i * 2 + 1];
        }

        let out_numel = Self::checked_shape_numel(&out_shape, "pad: output shape volume overflow")?;
        if out_numel > 0 && shape.contains(&0) {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "pad: non-constant padding requires non-empty input dimensions",
                },
            )));
        }

        // PyTorch's `reflect` padding requires each pad amount to be
        // strictly less than the corresponding input dimension — a
        // reflection that reaches the opposite boundary would have to
        // repeat past it. `torch.nn.functional.pad(x, pad, "reflect")`
        // raises a RuntimeError ("Padding size should be less than the
        // corresponding input dimension") in that case. `replicate`
        // (clamp) and `circular` (wrap) accept arbitrary pad widths.
        if mode == "reflect" {
            for i in 0..num_pad_dims {
                let dim = ndim - 1 - i;
                if padding[i * 2] >= shape[dim] || padding[i * 2 + 1] >= shape[dim] {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "pad: reflect padding size must be less than the corresponding input dimension",
                        },
                    )));
                }
            }
        }

        if !matches!(mode, "reflect" | "replicate" | "circular") {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "pad: unsupported mode (use constant, reflect, replicate, or circular)",
                },
            )));
        }

        let input_numel = Self::checked_shape_numel(shape, "pad: input shape volume overflow")?;
        let out_strides = ft_core::contiguous_strides(&out_shape);
        let in_strides = ft_core::contiguous_strides(shape);

        // For each output element, compute the source-coordinate gather index.
        // Each `flat_out` independently decomposes into per-dim coords and maps each
        // back through the reflect/clamp/wrap rule — that per-dim div/mod + boundary
        // index math (not the later gather, which is already parallel) is the
        // compute-bound cost, so build the index vector across the rayon pool above
        // PARALLEL_ELEMENTWISE_MIN. Index order preserved → bit-identical to the
        // serial loop. frankentorch-kgs4.96.
        let build = |flat_out: usize| -> f64 {
            let mut rem = flat_out;
            let mut flat_in = 0usize;
            for d in 0..ndim {
                let out_coord = rem / out_strides[d];
                rem %= out_strides[d];
                let out_c = out_coord as isize - pad_before[d] as isize;
                let dim_size = shape[d] as isize;
                let in_c = match mode {
                    "reflect" => {
                        if dim_size <= 1 {
                            0
                        } else {
                            reflect_index(out_c, dim_size)
                        }
                    }
                    "replicate" => out_c.clamp(0, dim_size - 1) as usize,
                    "circular" => out_c.rem_euclid(dim_size) as usize,
                    _ => unreachable!("mode validated above"),
                };
                flat_in += in_c * in_strides[d];
            }
            flat_in as f64
        };
        // No-grad fast path. The element-wise `build` above recomputes a full O(ndim)
        // coordinate decode + reflect/clamp/wrap for EVERY output element (measured
        // 3.3-3.8x SLOWER than torch at 4D). But the LAST dim's source-column map is
        // identical for every output row, so precompute `col_map[out_last]` ONCE; then
        // per output row decode only the OUTER coords (reflect/clamp/wrap the padded
        // outer dims → source row) and gather via `col_map`. ~out_outer ROW decodes plus
        // out_numel cheap map-lookups, instead of out_numel full ELEMENT decodes — and
        // the input is BORROWED, not cloned. Bit-identical to `build` (it computes the
        // same per-element source index, just factored last-dim vs outer). f64 contiguous
        // only; non-f64 / non-contiguous fall through to the original clone+build gather.
        if !self.tensor_requires_grad(input)? {
            if self.tensor_dtype(input)? == DType::F64 {
                let last = ndim - 1;
                let in_last = shape[last];
                let out_last = out_shape[last];
                let dim_last = shape[last] as isize;
                let col_map: Vec<usize> = (0..out_last)
                    .map(|j| {
                        let out_c = j as isize - pad_before[last] as isize;
                        match mode {
                            "reflect" => {
                                if dim_last <= 1 {
                                    0
                                } else {
                                    reflect_index(out_c, dim_last)
                                }
                            }
                            "replicate" => out_c.clamp(0, dim_last - 1) as usize,
                            "circular" => out_c.rem_euclid(dim_last) as usize,
                            _ => unreachable!("mode validated above"),
                        }
                    })
                    .collect();
                let out_outer_strides = ft_core::contiguous_strides(&out_shape[..last]);
                let in_outer_strides = ft_core::contiguous_strides(&shape[..last]);
                let build_row = |orow: usize| -> usize {
                    let mut rem = orow;
                    let mut in_row = 0usize;
                    for d in 0..last {
                        let oc = rem / out_outer_strides[d];
                        rem %= out_outer_strides[d];
                        let out_c = oc as isize - pad_before[d] as isize;
                        let dim_size = shape[d] as isize;
                        let in_c = match mode {
                            "reflect" => {
                                if dim_size <= 1 {
                                    0
                                } else {
                                    reflect_index(out_c, dim_size)
                                }
                            }
                            "replicate" => out_c.clamp(0, dim_size - 1) as usize,
                            "circular" => out_c.rem_euclid(dim_size) as usize,
                            _ => unreachable!("mode validated above"),
                        };
                        in_row += in_c * in_outer_strides[d];
                    }
                    in_row * in_last
                };
                let mut built: Option<Vec<f64>> = None;
                {
                    let it = self.tensor_tape.tensor(input)?;
                    if it.meta().is_contiguous() {
                        let id = it.contiguous_values()?;
                        let mut out = vec![0.0f64; out_numel];
                        if out_numel >= PARALLEL_ELEMENTWISE_MIN {
                            use rayon::prelude::*;
                            out.par_chunks_mut(out_last)
                                .enumerate()
                                .for_each(|(orow, chunk)| {
                                    let base = build_row(orow);
                                    for (j, slot) in chunk.iter_mut().enumerate() {
                                        *slot = id[base + col_map[j]];
                                    }
                                });
                        } else {
                            out.chunks_mut(out_last)
                                .enumerate()
                                .for_each(|(orow, chunk)| {
                                    let base = build_row(orow);
                                    for (j, slot) in chunk.iter_mut().enumerate() {
                                        *slot = id[base + col_map[j]];
                                    }
                                });
                        }
                        built = Some(out);
                    }
                }
                if let Some(out) = built {
                    return self.tensor_variable(out, out_shape, false);
                }
                // Non-contiguous f64: clone + per-element build gather.
                let input_vals = self.tensor_values(input)?;
                let output: Vec<f64> = if out_numel >= PARALLEL_ELEMENTWISE_MIN {
                    use rayon::prelude::*;
                    (0..out_numel)
                        .into_par_iter()
                        .map(|i| input_vals[build(i) as usize])
                        .collect()
                } else {
                    (0..out_numel)
                        .map(|i| input_vals[build(i) as usize])
                        .collect()
                };
                return self.tensor_variable(output, out_shape, false);
            } else if self.tensor_dtype(input)? == DType::F32 {
                // f32 MIRROR of the f64 col_map fast path above. This op previously CRASHED on
                // f32 input — it fell through to the F64-only `tensor_values` reader below and
                // returned UnsupportedDType(F32). Same last-dim col_map + per-row outer decode +
                // borrowed gather, but reads and writes f32 NATIVELY (no f32->f64 upcast). Only
                // the contiguous case is handled here; non-contiguous f32 falls through to the
                // dtype-generic index_select path below (which also fixes the crash).
                let last = ndim - 1;
                let in_last = shape[last];
                let out_last = out_shape[last];
                let dim_last = shape[last] as isize;
                let col_map: Vec<usize> = (0..out_last)
                    .map(|j| {
                        let out_c = j as isize - pad_before[last] as isize;
                        match mode {
                            "reflect" => {
                                if dim_last <= 1 {
                                    0
                                } else {
                                    reflect_index(out_c, dim_last)
                                }
                            }
                            "replicate" => out_c.clamp(0, dim_last - 1) as usize,
                            "circular" => out_c.rem_euclid(dim_last) as usize,
                            _ => unreachable!("mode validated above"),
                        }
                    })
                    .collect();
                let out_outer_strides = ft_core::contiguous_strides(&out_shape[..last]);
                let in_outer_strides = ft_core::contiguous_strides(&shape[..last]);
                let build_row = |orow: usize| -> usize {
                    let mut rem = orow;
                    let mut in_row = 0usize;
                    for d in 0..last {
                        let oc = rem / out_outer_strides[d];
                        rem %= out_outer_strides[d];
                        let out_c = oc as isize - pad_before[d] as isize;
                        let dim_size = shape[d] as isize;
                        let in_c = match mode {
                            "reflect" => {
                                if dim_size <= 1 {
                                    0
                                } else {
                                    reflect_index(out_c, dim_size)
                                }
                            }
                            "replicate" => out_c.clamp(0, dim_size - 1) as usize,
                            "circular" => out_c.rem_euclid(dim_size) as usize,
                            _ => unreachable!("mode validated above"),
                        };
                        in_row += in_c * in_outer_strides[d];
                    }
                    in_row * in_last
                };
                let it = self.tensor_tape.tensor(input)?;
                if it.meta().is_contiguous() {
                    let id = it.contiguous_values_f32()?;
                    let mut out = vec![0.0f32; out_numel];
                    if out_numel >= PARALLEL_ELEMENTWISE_MIN {
                        use rayon::prelude::*;
                        out.par_chunks_mut(out_last)
                            .enumerate()
                            .for_each(|(orow, chunk)| {
                                let base = build_row(orow);
                                for (j, slot) in chunk.iter_mut().enumerate() {
                                    *slot = id[base + col_map[j]];
                                }
                            });
                    } else {
                        out.chunks_mut(out_last)
                            .enumerate()
                            .for_each(|(orow, chunk)| {
                                let base = build_row(orow);
                                for (j, slot) in chunk.iter_mut().enumerate() {
                                    *slot = id[base + col_map[j]];
                                }
                            });
                    }
                    return self.tensor_variable_f32(out, out_shape, false);
                }
                // Non-contiguous f32: fall through to the index_select path below.
            }
        }

        let indices: Vec<f64> = if out_numel >= PARALLEL_ELEMENTWISE_MIN {
            use rayon::prelude::*;
            (0..out_numel).into_par_iter().map(build).collect()
        } else {
            (0..out_numel).map(build).collect()
        };

        let flat_input = if ndim == 1 && shape[0] == input_numel {
            input
        } else {
            self.tensor_reshape(input, vec![input_numel])?
        };
        let index_node = self.tensor_variable(indices, vec![out_numel], false)?;
        let gathered = self.tensor_index_select(flat_input, 0, index_node)?;

        if out_shape.len() == 1 && out_shape[0] == out_numel {
            Ok(gathered)
        } else {
            self.tensor_reshape(gathered, out_shape)
        }
    }

    /// Constant padding for 1D tensors (wraps tensor_pad).
    ///
    /// Equivalent to `torch.nn.functional.pad` with 1D input.
    pub fn tensor_constant_pad1d(
        &mut self,
        input: TensorNodeId,
        padding: (usize, usize),
        value: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_pad(input, &[padding.0, padding.1], value)
    }

    /// Constant padding for 2D tensors (wraps tensor_pad).
    ///
    /// Padding order: (left, right, top, bottom).
    pub fn tensor_constant_pad2d(
        &mut self,
        input: TensorNodeId,
        padding: (usize, usize, usize, usize),
        value: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_pad(input, &[padding.0, padding.1, padding.2, padding.3], value)
    }

    /// Reflection padding for 1D tensors.
    pub fn tensor_reflection_pad1d(
        &mut self,
        input: TensorNodeId,
        padding: (usize, usize),
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_pad_mode(input, &[padding.0, padding.1], "reflect", 0.0)
    }

    /// Reflection padding for 2D tensors.
