    // -------------------------------------------------------------------
    // Linear Algebra: LU Decomposition
    // -------------------------------------------------------------------

    /// Compute the LU factorization of a square matrix with partial pivoting.
    ///
    /// Returns `(lu_factor_node, pivot_indices)` where `lu_factor_node` is a
    /// tensor containing the packed LU matrix, and `pivot_indices` is a `Vec<usize>`
    /// of row pivot indices.
    ///
    /// The input must be a 2-D square tensor (n x n).
    pub fn tensor_lu_factor(
        &mut self,
        input: TensorNodeId,
    ) -> Result<(TensorNodeId, Vec<usize>), AutogradError> {
        // f32/half: compute in f64 then cast the LU factor back (pivots are
        // integer, pass through). torch keeps the input dtype. frankentorch-clqek.
        let dt = self.tensor_dtype(input)?;
        if dt != DType::F64 {
            let in64 = self.tensor_to_dtype(input, DType::F64)?;
            let (lu, piv) = self.tensor_lu_factor(in64)?;
            return Ok((self.tensor_to_dtype(lu, dt)?, piv));
        }
        let (values, meta) = self.tensor_values_meta(input)?;
        let result = ft_kernel_cpu::lu_factor_contiguous_f64(&values, &meta)
            .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?;
        let n = result.n;
        // Return torch-compatible 1-indexed LAPACK IPIV pivots (frankentorch-ibfw).
        // tensor_lu_solve / tensor_lu_unpack replay these swaps back into the
        // direct row permutation the kernels consume.
        let pivots_ipiv: Vec<usize> = result.ipiv.iter().map(|&r| r + 1).collect();

        let lu_node = if self.tensor_requires_grad(input)? {
            // Differentiable LU: the packed LU is the only differentiable output
            // (pivots are integer / non-differentiable). Backward uses the
            // standard pivoted-LU adjoint (see `lu_backward`). frankentorch-sn58.
            let in_shape = meta.shape();
            if in_shape.len() != 2 || in_shape[0] != in_shape[1] || meta.dtype() != DType::F64 {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "lu_factor: autograd only supported for a square F64 matrix",
                    },
                )));
            }
            let device = meta.device();
            self.tensor_apply_function(
                &[input],
                move |ctx, inputs| {
                    let (vals, sh) = inputs[0];
                    let m = TensorMeta::from_shape(sh.to_vec(), DType::F64, device);
                    let r = ft_kernel_cpu::lu_factor_contiguous_f64(vals, &m).map_err(|e| {
                        AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                    })?;
                    let nn = r.n;
                    // Direct row permutation: perm[i] = original row now at row i.
                    let mut perm: Vec<usize> = (0..nn).collect();
                    for (k, &p) in r.ipiv.iter().enumerate() {
                        perm.swap(k, p);
                    }
                    let perm_f: Vec<f64> = perm.iter().map(|&p| p as f64).collect();
                    ctx.save_for_backward(r.lu.clone(), vec![nn, nn]);
                    ctx.save_for_backward(perm_f, vec![nn]);
                    Ok((r.lu, vec![nn, nn]))
                },
                move |ctx, grad_outputs| {
                    let saved = ctx.saved_tensors();
                    let lu = &saved[0];
                    #[allow(clippy::cast_possible_truncation, clippy::cast_sign_loss)]
                    let nn = (lu.len() as f64).sqrt().round() as usize;
                    let perm: Vec<usize> = saved[1].iter().map(|&x| x as usize).collect();
                    let grad_a = Self::lu_backward(lu, &perm, grad_outputs[0], nn);
                    Ok(vec![Some(grad_a)])
                },
            )?
        } else {
            self.tensor_variable(result.lu, vec![n, n], false)?
        };
        Ok((lu_node, pivots_ipiv))
    }

    /// Replay LAPACK 1-indexed IPIV swaps into the direct row permutation
    /// (`perm[i]` = original row now at position `i`) that the LU kernels consume.
    /// Returns an error if any pivot is out of the valid `1..=n` range.
    fn lu_ipiv_to_permutation(ipiv: &[usize], n: usize) -> Result<Vec<usize>, AutogradError> {
        let mut perm: Vec<usize> = (0..n).collect();
        for (k, &p) in ipiv.iter().enumerate() {
            if p < 1 || p > n {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "lu pivots: IPIV value out of range (expected 1..=n)",
                    },
                )));
            }
            perm.swap(k, p - 1);
        }
        Ok(perm)
    }

    /// Compute the full LU decomposition: `P @ L @ U = A`.
    ///
    /// Returns `(P, L, U)` as three separate tensor nodes.
    /// - P: permutation matrix (n x n)
    /// - L: lower triangular with unit diagonal (n x n)
    /// - U: upper triangular (n x n)
    pub fn tensor_linalg_lu(
        &mut self,
        input: TensorNodeId,
    ) -> Result<(TensorNodeId, TensorNodeId, TensorNodeId), AutogradError> {
        // f32/half: compute in f64 then cast P/L/U back (the LU core is f64-only).
        // torch keeps the input dtype on every output. frankentorch-clqek.
        let dt = self.tensor_dtype(input)?;
        if dt != DType::F64 {
            let in64 = self.tensor_to_dtype(input, DType::F64)?;
            let (p, l, u) = self.tensor_linalg_lu(in64)?;
            return Ok((
                self.tensor_to_dtype(p, dt)?,
                self.tensor_to_dtype(l, dt)?,
                self.tensor_to_dtype(u, dt)?,
            ));
        }
        // Batched f64 path (nd>=3): parallelize per-plane lu_factor+unpack over the batch; grad via
        // batched lu_backward (parallel per-plane VJP). PyTorch loops getrf per plane and its P/L/U
        // backward is slow. frankentorch batched-lu-grad.
        {
            let bshape0 = self.tensor_shape(input)?;
            let nd0 = bshape0.len();
            if nd0 >= 3
                && bshape0[nd0 - 1] == bshape0[nd0 - 2]
                && self.tensor_dtype(input)? == DType::F64
                && self.tensor_tape.tensor(input)?.meta().is_contiguous()
            {
                let device = self.tensor_tape.tensor_meta(input)?.device();
                let nn = bshape0[nd0 - 1];
                let pmeta = self.tensor_tape.tensor_meta(input)?.clone();
                let batched = {
                    let v = self.tensor_tape.tensor(input)?.contiguous_values()?;
                    ft_kernel_cpu::lu_factor_unpack_batched_contiguous_f64(v, &pmeta).map_err(
                        |e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)),
                    )?
                };
                let p_node = self.tensor_variable(batched.p, bshape0.clone(), false)?;
                if !self.tensor_requires_grad(input)? {
                    let l_node = self.tensor_variable(batched.l, bshape0.clone(), false)?;
                    let u_node = self.tensor_variable(batched.u, bshape0.clone(), false)?;
                    return Ok((p_node, l_node, u_node));
                }
                // L node — grad masked to the strictly-lower triangle (gU := 0).
                let l_node = self.tensor_apply_function(
                    &[input],
                    move |ctx, inputs| {
                        let (vals, in_shape) = inputs[0];
                        let meta = TensorMeta::from_shape(in_shape.to_vec(), DType::F64, device);
                        let b = ft_kernel_cpu::lu_factor_unpack_batched_contiguous_f64(vals, &meta)
                            .map_err(|e| {
                                AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                            })?;
                        ctx.save_for_backward(b.packed, in_shape.to_vec());
                        let nd = in_shape.len();
                        ctx.save_for_backward(b.pivots, in_shape[..nd - 1].to_vec());
                        Ok((b.l, in_shape.to_vec()))
                    },
                    move |ctx, grad_outputs| {
                        let saved = ctx.saved_tensors();
                        let (packed, pivots) = (&saved[0], &saved[1]);
                        let grad_l = grad_outputs[0];
                        let plane = nn * nn;
                        let bb = packed.len() / plane;
                        let mut masked = vec![0.0_f64; packed.len()];
                        for p in 0..bb {
                            for i in 0..nn {
                                for j in 0..i {
                                    masked[p * plane + i * nn + j] = grad_l[p * plane + i * nn + j];
                                }
                            }
                        }
                        let grad_a = ft_kernel_cpu::lu_backward_batched_contiguous_f64(
                            packed, pivots, &masked, bb, nn,
                        );
                        Ok(vec![Some(grad_a)])
                    },
                )?;
                // U node — grad masked to the upper (incl diagonal) triangle (gL := 0).
                let u_node = self.tensor_apply_function(
                    &[input],
                    move |ctx, inputs| {
                        let (vals, in_shape) = inputs[0];
                        let meta = TensorMeta::from_shape(in_shape.to_vec(), DType::F64, device);
                        let b = ft_kernel_cpu::lu_factor_unpack_batched_contiguous_f64(vals, &meta)
                            .map_err(|e| {
                                AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                            })?;
                        ctx.save_for_backward(b.packed, in_shape.to_vec());
                        let nd = in_shape.len();
                        ctx.save_for_backward(b.pivots, in_shape[..nd - 1].to_vec());
                        Ok((b.u, in_shape.to_vec()))
                    },
                    move |ctx, grad_outputs| {
                        let saved = ctx.saved_tensors();
                        let (packed, pivots) = (&saved[0], &saved[1]);
                        let grad_u = grad_outputs[0];
                        let plane = nn * nn;
                        let bb = packed.len() / plane;
                        let mut masked = vec![0.0_f64; packed.len()];
                        for p in 0..bb {
                            for i in 0..nn {
                                for j in i..nn {
                                    masked[p * plane + i * nn + j] = grad_u[p * plane + i * nn + j];
                                }
                            }
                        }
                        let grad_a = ft_kernel_cpu::lu_backward_batched_contiguous_f64(
                            packed, pivots, &masked, bb, nn,
                        );
                        Ok(vec![Some(grad_a)])
                    },
                )?;
                return Ok((p_node, l_node, u_node));
            }
        }
        let (values, meta) = self.tensor_values_meta(input)?;
        let factor = ft_kernel_cpu::lu_factor_contiguous_f64(&values, &meta)
            .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?;
        let unpacked = ft_kernel_cpu::lu_unpack(&factor);
        let n = unpacked.n;
        // P is a permutation matrix (discrete in A) → always a non-grad leaf.
        let p_node = self.tensor_variable(unpacked.p, vec![n, n], false)?;

        if self.tensor_requires_grad(input)? {
            // Differentiable P L U = A via the two-independent-nodes pattern
            // (same as linalg_qr): the L-output and U-output each carry their own
            // term of the pivoted-LU adjoint (`lu_backward`) and the engine sums
            // them into grad[input]. L's upper/diag and U's strict-lower are
            // structural constants, so each node masks the incoming grad to its
            // free triangle. frankentorch-edyp9.
            let in_shape = meta.shape();
            if in_shape.len() != 2 || in_shape[0] != in_shape[1] || meta.dtype() != DType::F64 {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "linalg_lu: autograd only supported for a square F64 matrix",
                    },
                )));
            }
            let device = meta.device();
            // L node — masks grad to the strictly-lower triangle (gU := 0).
            let l_node = self.tensor_apply_function(
                &[input],
                move |ctx, inputs| {
                    let (vals, sh) = inputs[0];
                    let m = TensorMeta::from_shape(sh.to_vec(), DType::F64, device);
                    let r = ft_kernel_cpu::lu_factor_contiguous_f64(vals, &m).map_err(|e| {
                        AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                    })?;
                    let up = ft_kernel_cpu::lu_unpack(&r);
                    let nn = r.n;
                    let perm_f: Vec<f64> = r.pivots.iter().map(|&p| p as f64).collect();
                    ctx.save_for_backward(r.lu.clone(), vec![nn, nn]);
                    ctx.save_for_backward(perm_f, vec![nn]);
                    Ok((up.l, vec![nn, nn]))
                },
                move |ctx, grad_outputs| {
                    let saved = ctx.saved_tensors();
                    let lu = &saved[0];
                    #[allow(clippy::cast_possible_truncation, clippy::cast_sign_loss)]
                    let nn = (lu.len() as f64).sqrt().round() as usize;
                    let perm: Vec<usize> = saved[1].iter().map(|&x| x as usize).collect();
                    let grad_l = grad_outputs[0];
                    let mut packed = vec![0.0_f64; nn * nn];
                    for i in 0..nn {
                        for j in 0..i {
                            packed[i * nn + j] = grad_l[i * nn + j];
                        }
                    }
                    let grad_a = Self::lu_backward(lu, &perm, &packed, nn);
                    Ok(vec![Some(grad_a)])
                },
            )?;
            // U node — masks grad to the upper (incl diagonal) triangle (gL := 0).
            let u_node = self.tensor_apply_function(
                &[input],
                move |ctx, inputs| {
                    let (vals, sh) = inputs[0];
                    let m = TensorMeta::from_shape(sh.to_vec(), DType::F64, device);
                    let r = ft_kernel_cpu::lu_factor_contiguous_f64(vals, &m).map_err(|e| {
                        AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                    })?;
                    let up = ft_kernel_cpu::lu_unpack(&r);
                    let nn = r.n;
                    let perm_f: Vec<f64> = r.pivots.iter().map(|&p| p as f64).collect();
                    ctx.save_for_backward(r.lu.clone(), vec![nn, nn]);
                    ctx.save_for_backward(perm_f, vec![nn]);
                    Ok((up.u, vec![nn, nn]))
                },
                move |ctx, grad_outputs| {
                    let saved = ctx.saved_tensors();
                    let lu = &saved[0];
                    #[allow(clippy::cast_possible_truncation, clippy::cast_sign_loss)]
                    let nn = (lu.len() as f64).sqrt().round() as usize;
                    let perm: Vec<usize> = saved[1].iter().map(|&x| x as usize).collect();
                    let grad_u = grad_outputs[0];
                    let mut packed = vec![0.0_f64; nn * nn];
                    for i in 0..nn {
                        for j in i..nn {
                            packed[i * nn + j] = grad_u[i * nn + j];
                        }
                    }
                    let grad_a = Self::lu_backward(lu, &perm, &packed, nn);
                    Ok(vec![Some(grad_a)])
                },
            )?;
            return Ok((p_node, l_node, u_node));
        }

        let l_node = self.tensor_variable(unpacked.l, vec![n, n], false)?;
        let u_node = self.tensor_variable(unpacked.u, vec![n, n], false)?;
        Ok((p_node, l_node, u_node))
    }

    /// Unpack a packed LU factorization into `(P, L, U)` with `P @ L @ U = A`.
    ///
    /// Equivalent to `torch.lu_unpack(LU_data, LU_pivots)`. Takes the packed LU
    /// tensor and the `pivots` returned by [`tensor_lu_factor`] and produces the
    /// three separate factors:
    /// - P: permutation matrix (n x n)
    /// - L: unit lower-triangular (n x n)
    /// - U: upper-triangular (n x n)
    ///
    /// This is pure data movement (no arithmetic), so P/L/U are bit-identical to
    /// torch's `lu_unpack` output. `pivots` are torch-format 1-indexed LAPACK IPIV
    /// (as returned by [`tensor_lu_factor`]); they are replayed into the direct
    /// row permutation internally (frankentorch-ibfw).
    pub fn tensor_lu_unpack(
        &mut self,
        lu_data: TensorNodeId,
        pivots: &[usize],
    ) -> Result<(TensorNodeId, TensorNodeId, TensorNodeId), AutogradError> {
        let (values, meta) = self.tensor_values_meta(lu_data)?;
        let shape = meta.shape();
        if shape.len() != 2 || shape[0] != shape[1] {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: shape.to_vec(),
                    rhs: vec![shape.first().copied().unwrap_or(0); 2],
                },
            )));
        }
        let n = shape[0];
        if pivots.len() != n {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "lu_unpack: pivots length must equal the matrix dimension",
                },
            )));
        }
        // pivots are torch-format 1-indexed IPIV; replay into the direct row
        // permutation the kernel consumes (frankentorch-ibfw).
        let perm = Self::lu_ipiv_to_permutation(pivots, n)?;
        // P depends only on the pivots, not the packed values → non-grad leaf.
        let p_factor = ft_kernel_cpu::LuFactorResult {
            lu: vec![0.0; n * n],
            pivots: perm.clone(),
            ipiv: pivots.to_vec(),
            n,
        };
        let p_node =
            self.tensor_variable(ft_kernel_cpu::lu_unpack(&p_factor).p, vec![n, n], false)?;

        if self.tensor_requires_grad(lu_data)? {
            // L = strict-lower(packed)+unit diag and U = upper(packed) are pure
            // (constant-pattern) selections of the packed input, so each output
            // node scatters its grad straight back into the matching triangle of
            // grad[lu_data] (two-independent-nodes pattern; the engine sums them).
            // Composes with the differentiable lu_factor. frankentorch-edyp9.
            let (perm_l, piv_l) = (perm.clone(), pivots.to_vec());
            let l_node = self.tensor_apply_function(
                &[lu_data],
                move |_ctx, inputs| {
                    let f = ft_kernel_cpu::LuFactorResult {
                        lu: inputs[0].0.to_vec(),
                        pivots: perm_l.clone(),
                        ipiv: piv_l.clone(),
                        n,
                    };
                    Ok((ft_kernel_cpu::lu_unpack(&f).l, vec![n, n]))
                },
                move |_ctx, grad_outputs| {
                    let g = grad_outputs[0];
                    let mut gp = vec![0.0_f64; n * n];
                    for i in 0..n {
                        for j in 0..i {
                            gp[i * n + j] = g[i * n + j];
                        }
                    }
                    Ok(vec![Some(gp)])
                },
            )?;
            let (perm_u, piv_u) = (perm.clone(), pivots.to_vec());
            let u_node = self.tensor_apply_function(
                &[lu_data],
                move |_ctx, inputs| {
                    let f = ft_kernel_cpu::LuFactorResult {
                        lu: inputs[0].0.to_vec(),
                        pivots: perm_u.clone(),
                        ipiv: piv_u.clone(),
                        n,
                    };
                    Ok((ft_kernel_cpu::lu_unpack(&f).u, vec![n, n]))
                },
                move |_ctx, grad_outputs| {
                    let g = grad_outputs[0];
                    let mut gp = vec![0.0_f64; n * n];
                    for i in 0..n {
                        for j in i..n {
                            gp[i * n + j] = g[i * n + j];
                        }
                    }
                    Ok(vec![Some(gp)])
                },
            )?;
            return Ok((p_node, l_node, u_node));
        }

        let factor = ft_kernel_cpu::LuFactorResult {
            lu: values,
            pivots: perm,
            ipiv: pivots.to_vec(),
            n,
        };
        let unpacked = ft_kernel_cpu::lu_unpack(&factor);
        let l_node = self.tensor_variable(unpacked.l, vec![n, n], false)?;
        let u_node = self.tensor_variable(unpacked.u, vec![n, n], false)?;
        Ok((p_node, l_node, u_node))
    }

    /// Solve `A * X = B` using a pre-computed LU factorization.
    ///
    /// `lu_packed` is the packed LU tensor from `tensor_lu_factor`.
    /// `pivots` is the pivot indices from `tensor_lu_factor`.
    /// `b` is the right-hand side tensor (shape [n] or [n, m]).
    ///
    /// Returns the solution tensor X.
    pub fn tensor_lu_solve(
        &mut self,
        lu_packed: TensorNodeId,
        pivots: &[usize],
        b: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let lu_meta = self.tensor_tape.tensor_meta(lu_packed)?.clone();
        let lu_shape = lu_meta.shape();
        if lu_shape.len() != 2 || lu_shape[0] != lu_shape[1] {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: lu_shape.to_vec(),
                    rhs: vec![lu_shape.len()],
                },
            )));
        }
        let n = lu_shape[0];
        if pivots.len() != n {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "lu_solve: pivots length must equal the matrix dimension",
                },
            )));
        }
        // pivots are torch-format 1-indexed IPIV (frankentorch-ibfw); replay into
        // the direct row permutation the kernel consumes.
        let perm = Self::lu_ipiv_to_permutation(pivots, n)?;

        if self.tensor_requires_grad(lu_packed)? || self.tensor_requires_grad(b)? {
            // Differentiable solve of A X = B (A = P L U) in BOTH inputs:
            // grad_B = A^-T grad_X, grad_A = -grad_B X^T, then grad_A -> grad_LU
            // (lu_solve_backward). Single output, two grad-carrying inputs, so the
            // tape backward returns both grads. frankentorch-edyp9.
            if lu_meta.dtype() != DType::F64 {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "lu_solve: autograd only supported for F64",
                    },
                )));
            }
            let device = lu_meta.device();
            let perm_c = perm.clone();
            let piv_c = pivots.to_vec();
            return self.tensor_apply_function(
                &[lu_packed, b],
                move |ctx, inputs| {
                    let (lu_vals, lu_sh) = inputs[0];
                    let (b_vals, b_sh) = inputs[1];
                    let nn = lu_sh[0];
                    let bm = TensorMeta::from_shape(b_sh.to_vec(), DType::F64, device);
                    let factor = ft_kernel_cpu::LuFactorResult {
                        lu: lu_vals.to_vec(),
                        pivots: perm_c.clone(),
                        ipiv: piv_c.clone(),
                        n: nn,
                    };
                    let sol = ft_kernel_cpu::lu_solve_contiguous_f64(&factor, b_vals, &bm)
                        .map_err(|e| {
                            AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                        })?;
                    let perm_f: Vec<f64> = perm_c.iter().map(|&p| p as f64).collect();
                    ctx.save_for_backward(lu_vals.to_vec(), vec![nn, nn]);
                    ctx.save_for_backward(perm_f, vec![nn]);
                    ctx.save_for_backward(sol.clone(), b_sh.to_vec());
                    Ok((sol, b_sh.to_vec()))
                },
                move |ctx, grad_outputs| {
                    let saved = ctx.saved_tensors();
                    let lu = &saved[0];
                    #[allow(clippy::cast_possible_truncation, clippy::cast_sign_loss)]
                    let nn = (lu.len() as f64).sqrt().round() as usize;
                    let perm: Vec<usize> = saved[1].iter().map(|&x| x as usize).collect();
                    let x = &saved[2];
                    let mm = x.len() / nn;
                    let (grad_lu, grad_b) =
                        Self::lu_solve_backward(lu, &perm, x, grad_outputs[0], nn, mm);
                    Ok(vec![Some(grad_lu), Some(grad_b)])
                },
            );
        }

        // F32 no-grad fast path: the native lu_solve_contiguous_f32 kernel
        // (TRSM+pivot, ~1.8x) replaces the f32->f64->f32 round-trip AND keeps the
        // substitution in f32 to match torch's f32 lu_solve. frankentorch-b3o90.
        if lu_meta.dtype() == DType::F32 && self.tensor_dtype(b)? == DType::F32 {
            let lu_f32 = self.tensor_values_f32(lu_packed)?;
            let b_f32 = self.tensor_values_f32(b)?;
            let b_meta = self.tensor_tape.tensor_meta(b)?.clone();
            let b_shape = b_meta.shape().to_vec();
            let solution =
                ft_kernel_cpu::lu_solve_contiguous_f32(&lu_f32, &perm, n, &b_f32, &b_meta)
                    .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?;
            return self.tensor_variable_f32(solution, b_shape, false);
        }

        let (lu_values, _) = self.tensor_values_meta(lu_packed)?;
        let factor = ft_kernel_cpu::LuFactorResult {
            lu: lu_values,
            pivots: perm,
            ipiv: pivots.to_vec(),
            n,
        };
        let (b_values, b_meta) = self.tensor_values_meta(b)?;
        let b_shape = b_meta.shape().to_vec();
        let solution = ft_kernel_cpu::lu_solve_contiguous_f64(&factor, &b_values, &b_meta)
            .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?;

        self.tensor_variable(solution, b_shape, false)
    }

    /// Solve the linear system `A @ X = B` for X.
    ///
    /// Internally factorises A via LU decomposition then solves.
    /// A must be a square (n x n) tensor; B must be [n] or [n, m].
    /// Returns the solution tensor X with the same shape as B.
    pub fn tensor_linalg_solve(
        &mut self,
        a: TensorNodeId,
        b: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // f32/half: compute in f64 then cast to the promoted dtype (the solve
        // core is f64-only). torch keeps the input dtype. frankentorch-aqllp.
        let (da, db) = (self.tensor_dtype(a)?, self.tensor_dtype(b)?);
        // NOTE: f32 solve deliberately stays on the f64 mixed-refine path below —
        // it factors in f32 then refines in f64, which is BOTH faster (~2.8x vs a
        // pure native f32 LU at n=256/512) AND more accurate than torch's pure-f32
        // sgesv. A native f32 lu_factor_contiguous_f32 exists (used by the f32
        // inverse) but routing solve through it regressed perf, so it is not wired
        // here. frankentorch-b3o90.
        if da != DType::F64 || db != DType::F64 {
            let out_dt = Self::promote_float_pair(da, db);
            let a64 = self.tensor_to_dtype(a, DType::F64)?;
            let b64 = self.tensor_to_dtype(b, DType::F64)?;
            let out64 = self.tensor_linalg_solve(a64, b64)?;
            return self.tensor_to_dtype(out64, out_dt);
        }
        if !self.tensor_requires_grad(a)? && !self.tensor_requires_grad(b)? {
            let (a_values, a_meta) = self.tensor_values_meta(a)?;
            let (b_values, b_meta) = self.tensor_values_meta(b)?;
            let b_shape = b_meta.shape().to_vec();
            // Batched no-grad fast path (A=[..,n,n], B=[..,n,m]): one parallel batched
            // LU-solve kernel (no per-matrix LuFactorResult/meta/validation overhead, which
            // made an ft-api per-matrix loop lose 2.2x). Matches torch's batched solve API
            // (previously a 3-D ShapeMismatch). frankentorch-qe48n.
            let a_shape = a_meta.shape();
            if a_shape.len() >= 3
                && b_shape.len() == a_shape.len()
                && a_shape[a_shape.len() - 1] == a_shape[a_shape.len() - 2]
                && b_shape[..b_shape.len() - 1] == a_shape[..a_shape.len() - 1]
            {
                let nd = a_shape.len();
                let n = a_shape[nd - 1];
                let m = b_shape[nd - 1];
                let batch: usize = a_shape[..nd - 2].iter().product();
                if batch >= 2 && n > 0 && m > 0 {
                    let solution = ft_kernel_cpu::lu_solve_batched_contiguous_f64(
                        &a_values, &b_values, batch, n, m,
                    );
                    return self.tensor_variable(solution, b_shape, false);
                }
            }
            let solution = ft_kernel_cpu::lu_solve_mixed_refine_contiguous_f64(
                &a_values, &a_meta, &b_values, &b_meta,
            )
            .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?;
            return self.tensor_variable(solution, b_shape, false);
        }

        // Compose via tensor_linalg_inv + tensor_matmul so gradients
        // flow back to both A and B. Tracked under frankentorch-dlht.
        // Previous body called LU factor/solve kernels directly and
        // rebuilt a non-grad leaf, severing autograd through every
        // linear solve.
        //
        // Math: X = inv(A) @ B. The chain rule via inv backward
        // (-Y^T grad Y^T, frankentorch-frq7) and matmul backward
        // recovers the standard solve adjoint:
        //   dL/dB = A^{-T} dL/dX
        //   dL/dA = -A^{-T} dL/dX X^T
        // Trade-off: forward pass uses the explicit inverse instead
        // of LU solve — slightly less stable for ill-conditioned A,
        // but PyTorch's solve autograd uses the same inv-based path
        // for backward, so gradient correctness is identical.
        //
        // For batched B [n, m] this still works: matmul broadcasts
        // [n, n] @ [n, m] = [n, m]. For 1-D B [n], we reshape to
        // [n, 1] then squeeze to recover the [n] output shape.
        let b_shape = self.tensor_shape(b)?;
        let inv_a = self.tensor_linalg_inv(a)?;
        if b_shape.len() == 1 {
            let n = b_shape[0];
            let b_2d = self.tensor_reshape(b, vec![n, 1])?;
            let x_2d = self.tensor_matmul(inv_a, b_2d)?;
            self.tensor_reshape(x_2d, vec![n])
        } else {
            self.tensor_matmul(inv_a, b)
        }
    }

    /// Compute the Cholesky decomposition of a symmetric positive-definite matrix.
    ///
    /// Returns the lower triangular factor L such that A = L @ L^T.
    /// If `upper` is true, returns U such that A = U^T @ U.
    pub fn tensor_linalg_cholesky(
        &mut self,
        input: TensorNodeId,
        upper: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        // f32/half: compute in f64 then cast back (the Cholesky core is f64-only).
        // torch keeps the input dtype. frankentorch-aqllp.
        let dt = self.tensor_dtype(input)?;
        // F32 no-grad fast path: the native cholesky_contiguous_f32 kernel (blocked
        // SYRK, ~1.45x) replaces the f32->f64->f32 round-trip AND matches torch's f32
        // Cholesky — torch factorizes in the input dtype, so the f64-upcast path
        // diverged from torch f32. frankentorch-b3o90.
        if dt == DType::F32 && !self.tensor_requires_grad(input)? {
            let iv = self.tensor_values_f32(input)?;
            let meta = self.tensor_tape.tensor_meta(input)?.clone();
            let out = ft_kernel_cpu::cholesky_contiguous_f32(&iv, &meta, upper)
                .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?;
            let n = meta.shape()[0];
            return self.tensor_variable_f32(out, vec![n, n], false);
        }
        if dt != DType::F64 {
            let in64 = self.tensor_to_dtype(input, DType::F64)?;
            let out64 = self.tensor_linalg_cholesky(in64, upper)?;
            return self.tensor_to_dtype(out64, dt);
        }
        let input_meta = self.tensor_tape.tensor_meta(input)?.clone();
        if self.tensor_requires_grad(input)? {
            if input_meta.shape() == [1, 1] && input_meta.dtype() == DType::F64 {
                let out = self.tensor_apply_function(
                    &[input],
                    move |ctx, inputs| {
                        let values = inputs[0].0;
                        if values[0] <= 0.0 {
                            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                                ft_dispatch::DispatchKeyError::IncompatibleSet {
                                    reason: "linalg_cholesky: input is not positive definite",
                                },
                            )));
                        }
                        let factor = values[0].sqrt();
                        ctx.save_for_backward(vec![factor], vec![1, 1]);
                        Ok((vec![factor], vec![1, 1]))
                    },
                    move |ctx, grad_outputs| {
                        let factor = ctx.saved_tensors()[0][0];
                        Ok(vec![Some(vec![grad_outputs[0][0] / (2.0 * factor)])])
                    },
                )?;
                self.runtime.ledger_mut().record(
                    EvidenceKind::Dispatch,
                    format!(
                        "linalg_cholesky input={} out={} upper={upper} (autograd 1x1)",
                        input.0, out.0
                    ),
                );
                return Ok(out);
            }
            // General N x N backward. Uses the standard differentiable-Cholesky
            // result (Murray 2016 / PyTorch cholesky_backward) on the lower
            // factor: phi = tril_half_diag(L^T @ L_bar); A_bar = L^-T phi L^-1;
            // grad_A = (A_bar + A_bar^T)/2. For the upper factor U = L^T, feed
            // L = U^T and grad_L = grad_U^T (grad_A is symmetric, so no transpose
            // back). frankentorch-rl4g.
            let shape = input_meta.shape();
            if shape.len() == 2 && shape[0] == shape[1] && input_meta.dtype() == DType::F64 {
                let device = input_meta.device();
                let n_dim = shape[0];
                let out = self.tensor_apply_function_with_create_graph(
                    &[input],
                    move |ctx, inputs| {
                        let (values, in_shape) = inputs[0];
                        let meta = TensorMeta::from_shape(in_shape.to_vec(), DType::F64, device);
                        let result = ft_kernel_cpu::cholesky_contiguous_f64(values, &meta, upper)
                            .map_err(|e| {
                            AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                        })?;
                        let n = result.n;
                        ctx.save_for_backward(result.factor.clone(), vec![n, n]);
                        Ok((result.factor, vec![n, n]))
                    },
                    move |ctx, grad_outputs| {
                        let saved = ctx.saved_tensors();
                        let factor = &saved[0];
                        let grad = grad_outputs[0];
                        #[allow(clippy::cast_possible_truncation, clippy::cast_sign_loss)]
                        let n = (factor.len() as f64).sqrt().round() as usize;
                        let grad_a = if upper {
                            // L = U^T, grad_L = grad_U^T.
                            let mut l = vec![0.0_f64; n * n];
                            let mut gl = vec![0.0_f64; n * n];
                            for i in 0..n {
                                for j in 0..n {
                                    l[i * n + j] = factor[j * n + i];
                                    gl[i * n + j] = grad[j * n + i];
                                }
                            }
                            Self::cholesky_backward_lower(&l, &gl, n)
                        } else {
                            Self::cholesky_backward_lower(factor, grad, n)
                        };
                        Ok(vec![Some(grad_a)])
                    },
                    // create_graph backward: rebuild the differentiable-Cholesky VJP
                    //   phi = Φ(Lᵀ·grad_L);  grad_A = sym(L⁻ᵀ·phi·L⁻¹)
                    // from differentiable tape ops (L = a differentiable cholesky node,
                    // L⁻¹ from the differentiable inverse), so the SECOND derivative
                    // propagates instead of erroring. Φ = tril with halved diagonal is a
                    // constant element-wise mask multiply. frankentorch-nj7x8.
                    move |_ctx, grad_outs, inputs, tape| {
                        let mode = ft_core::ExecutionMode::Strict;
                        let n = n_dim;
                        let chol = Self::cg_differentiable_cholesky(tape, inputs[0], n, upper)?;
                        // Reduce to the lower form: L and grad_L.
                        let (l_node, gl_node) = if upper {
                            (
                                tape.transpose(chol, 0, 1)?,
                                tape.transpose(grad_outs[0], 0, 1)?,
                            )
                        } else {
                            (chol, grad_outs[0])
                        };
                        // L⁻¹ — mask L to its lower triangle before inverting so the
                        // inverse only responds to lower-triangular perturbations.
                        let mut lower_vals = vec![0.0_f64; n * n];
                        for i in 0..n {
                            for j in 0..=i {
                                lower_vals[i * n + j] = 1.0;
                            }
                        }
                        let lower_mask = tape.leaf(lower_vals, vec![n, n], false)?;
                        let l_tri = tape.mul(l_node, lower_mask, mode)?.0;
                        let linv = Self::cg_differentiable_inverse(tape, l_tri, n)?;
                        let linvt = tape.transpose(linv, 0, 1)?;
                        let lt = tape.transpose(l_node, 0, 1)?;
                        // phi = (Lᵀ @ grad_L) ⊙ Φ-mask  (1 below diag, 0.5 on diag, 0 above)
                        let lt_gl = tape.matmul(lt, gl_node, mode)?.0;
                        let mut phi_vals = vec![0.0_f64; n * n];
                        for i in 0..n {
                            for j in 0..n {
                                phi_vals[i * n + j] = if i > j {
                                    1.0
                                } else if i == j {
                                    0.5
                                } else {
                                    0.0
                                };
                            }
                        }
                        let phi_mask = tape.leaf(phi_vals, vec![n, n], false)?;
                        let phi = tape.mul(lt_gl, phi_mask, mode)?.0;
                        // a_bar = L⁻ᵀ @ phi @ L⁻¹
                        let t = tape.matmul(phi, linv, mode)?.0;
                        let a_bar = tape.matmul(linvt, t, mode)?.0;
                        // grad_A = (a_bar + a_barᵀ) / 2
                        let a_bar_t = tape.transpose(a_bar, 0, 1)?;
                        let sum = tape.add(a_bar, a_bar_t, mode)?.0;
                        let grad_a = tape.mul_scalar(sum, 0.5)?.0;
                        Ok(vec![Some(grad_a)])
                    },
                )?;
                self.runtime.ledger_mut().record(
                    EvidenceKind::Dispatch,
                    format!(
                        "linalg_cholesky input={} out={} upper={upper} (autograd)",
                        input.0, out.0
                    ),
                );
                return Ok(out);
            }
            // Non-square / non-F64: not yet supported.
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "linalg_cholesky: autograd only supported for a square F64 matrix",
                },
            )));
        }
        let (values, meta) = self.tensor_values_meta(input)?;
        let result = ft_kernel_cpu::cholesky_contiguous_f64(&values, &meta, upper)
            .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?;
        let n = result.n;
        self.tensor_variable(result.factor, vec![n, n], false)
    }

    /// Gradient of A through `A = L L^T` (lower Cholesky), given `l` (the n x n
    /// lower factor, row-major) and `grad_l` (the upstream gradient w.r.t. L).
    /// Returns the symmetric `grad_A` (row-major n x n). Standard differentiable
    /// Cholesky: `phi = tril_half_diag(L^T grad_L)`, `A_bar = L^-T phi L^-1`,
    /// `grad_A = (A_bar + A_bar^T)/2`.
    /// Reverse-mode VJP of the reduced SVD A = U diag(S) Vh for the tall/square
    /// case (m >= n, so k = n and V is square), distinct positive singular values.
    /// Derived from dP = U^T dA V = dS + ΩU S - S ΩV (ΩU=U^T dU, ΩV=V^T dV skew):
    ///   M[i][i] = gS_i
    ///   M[i][j] = (S_j (a_ij - a_ji) + S_i (b_ij - b_ji)) / (S_j^2 - S_i^2), i≠j
    /// with a = U^T gU, b = V^T gV; then
    ///   grad_A = U M V^T + (I - U U^T) gU diag(1/S) V^T
    /// (the projection term carries the gU component outside col(U) when m > k).
    /// Linear in (gU, gS, gV): callers zero the grads of the outputs they don't
    /// carry. `gv` is supplied in the V basis (n x k), `vh` is k x n (V = Vh^T).
    #[allow(clippy::too_many_arguments)]
    fn svd_backward_tall(
        u: &[f64],
        s: &[f64],
        vh: &[f64],
        gu: &[f64],
        gs: &[f64],
        gv: &[f64],
        m: usize,
        n: usize,
        k: usize,
    ) -> Vec<f64> {
        // The reduced-SVD VJP is a chain of matmuls; route them through the parallel
        // BLAS-3 GEMM kernel instead of scalar O(m·k·{k,n}) loops. frankentorch-kgs4.76.
        ft_kernel_cpu::svd_backward_tall_f64(u, s, vh, gu, gs, gv, m, n, k)
    }

    /// Reverse-mode VJP of the reduced QR factorization for the tall case
    /// (m >= n), full-rank R. Implements the standard formula
    ///   M  = R @ grad_R^T - grad_Q^T @ Q              (n x n)
    ///   S  = copyltu(M) = tril(M) + tril(M,-1)^T      (symmetric)
    ///   grad_A = (grad_Q + Q @ S) @ R^{-T}            (m x n)
    /// which is LINEAR in (grad_Q, grad_R); callers that only carry one of the
    /// two output gradients pass zeros for the other and the contributions sum.
    /// Q is m x n, R is n x n (upper triangular).
    fn qr_backward_tall(
        q: &[f64],
        r: &[f64],
        grad_q: &[f64],
        grad_r: &[f64],
        m: usize,
        n: usize,
    ) -> Vec<f64> {
        // The reduced-QR VJP is a chain of matmuls (M, Q·S, Z·R⁻ᵀ); route them
        // through the parallel BLAS-3 GEMM kernel instead of scalar O(m·n²) loops.
        // frankentorch-kgs4.77.
        ft_kernel_cpu::qr_backward_tall_f64(q, r, grad_q, grad_r, m, n)
    }

    fn cholesky_backward_lower(l: &[f64], grad_l: &[f64], n: usize) -> Vec<f64> {
        // The Cholesky VJP is a chain of matmuls (Lᵀ·grad_L, Φ·L⁻¹, L⁻ᵀ·t); route
        // them through the parallel BLAS-3 GEMM kernel instead of scalar O(n³) loops.
        // frankentorch-kgs4.78.
        ft_kernel_cpu::cholesky_backward_lower_f64(l, grad_l, n)
    }

    /// Build `L = cholesky(A)` (lower/upper per `upper`) as a fresh DIFFERENTIABLE
    /// tape node for use inside a create_graph backward — its own first-order
    /// backward is the standard differentiable-Cholesky VJP (`cholesky_backward_lower`),
    /// so differentiating an expression containing this node propagates the correct
    /// SECOND derivative. frankentorch-nj7x8.
    fn cg_differentiable_cholesky(
        tape: &mut ft_autograd::TensorTape,
        a: TensorNodeId,
        n: usize,
        upper: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        tape.apply_function(
            &[a],
            move |ctx, ins| {
                let (vals, in_shape) = ins[0];
                let meta = TensorMeta::from_shape(in_shape.to_vec(), DType::F64, Device::Cpu);
                let result = ft_kernel_cpu::cholesky_contiguous_f64(vals, &meta, upper)
                    .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?;
                ctx.save_for_backward(result.factor.clone(), vec![n, n]);
                Ok((result.factor, vec![n, n]))
            },
            move |ctx, grad_outputs| {
                let factor = &ctx.saved_tensors()[0];
                let grad = grad_outputs[0];
                let grad_a = if upper {
                    // L = Uᵀ, grad_L = grad_Uᵀ.
                    let mut l = vec![0.0_f64; n * n];
                    let mut gl = vec![0.0_f64; n * n];
                    for i in 0..n {
                        for j in 0..n {
                            l[i * n + j] = factor[j * n + i];
                            gl[i * n + j] = grad[j * n + i];
                        }
                    }
                    Self::cholesky_backward_lower(&l, &gl, n)
                } else {
                    Self::cholesky_backward_lower(factor, grad, n)
                };
                Ok(vec![Some(grad_a)])
            },
        )
    }

    /// Backward of the (pivoted) LU factorization `P @ L @ U = A`, where `lu` is
    /// the packed factor (unit-lower `L` in the strict-lower triangle, upper `U`
    /// on/above the diagonal) and `perm[i]` is the original row of `A` now at
    /// row `i` of `B = P^T A = L U`. `grad_lu` is the cotangent of the packed
    /// output. Standard result (B = L U, no pivot):
    ///   Φ = stril(Lᵀ·gL) + triu(gU·Uᵀ),   gB = L⁻ᵀ Φ U⁻ᵀ,   gA = P·gB
    /// where gL is the strict-lower part of `grad_lu` and gU its upper part.
    /// All triangular inverses are formed by substitution (n is small for the
    /// dense LU path). frankentorch-sn58 / lu-backward.
    fn lu_backward(lu: &[f64], perm: &[usize], grad_lu: &[f64], n: usize) -> Vec<f64> {
        // The LU VJP is a chain of matmuls (Φ from Lᵀ·gL and gU·Uᵀ, then
        // L⁻ᵀ·Φ·U⁻ᵀ); route them through the parallel BLAS-3 GEMM kernel instead of
        // scalar O(n³) loops. frankentorch-kgs4.79.
        ft_kernel_cpu::lu_backward_f64(lu, perm, grad_lu, n)
    }

    /// Backward of `lu_solve`: given the packed LU factor `lu` (unit-lower `L`,
    /// upper `U`), the direct row permutation `perm` (A = P L U), the forward
    /// solution `x` and its cotangent `grad_x` (both row-major `[n, m]`),
    /// returns `(grad_lu_packed, grad_b)`. Standard linear-solve adjoint:
    ///   grad_B = A^-T grad_X,  grad_A = -grad_B X^T,
    /// then grad_A -> grad_LU via gL = stril(P^T grad_A U^T), gU = triu(L^T P^T grad_A).
    /// A^-T grad_X is computed with transposed triangular substitution on the
    /// saved factors (no refactorization, no C BLAS). frankentorch-edyp9.
    fn lu_solve_backward(
        lu: &[f64],
        perm: &[usize],
        x: &[f64],
        grad_x: &[f64],
        n: usize,
        m: usize,
    ) -> (Vec<f64>, Vec<f64>) {
        // grad_A = −grad_B·Xᵀ and the packed grad_LU matmuls route through the
        // parallel BLAS-3 GEMM kernel; the per-column triangular solves for grad_B
        // stay scalar. frankentorch-kgs4.80.
        ft_kernel_cpu::lu_solve_backward_f64(lu, perm, x, grad_x, n, m)
    }

    /// Cholesky decomposition with info output.
    ///
    /// Returns `(L, info)` where info is 0 if successful, or positive if not
    /// positive-definite (info indicates which leading minor failed).
    /// First leading minor whose Cholesky factorization is not positive
    /// definite, 1-indexed — matching LAPACK potrf / `torch.linalg.cholesky_ex`
    /// `info`. Runs the unblocked column Cholesky (potf2 shape) over the lower
    /// triangle and returns `j + 1` at the first column whose pivot `s` is
    /// non-positive, or 0 if the whole matrix is positive definite. `values` is
    /// raw row-major storage indexed from `offset` (same convention the kernel
    /// uses). frankentorch-ibfw class (LAPACK output-encoding parity).
    fn cholesky_failing_minor(values: &[f64], offset: usize, n: usize) -> i32 {
        let mut l = vec![0.0f64; n * n];
        for j in 0..n {
            let mut s = values[offset + j * n + j];
            for p in 0..j {
                s -= l[j * n + p] * l[j * n + p];
            }
            if s <= 0.0 {
                return (j + 1) as i32;
            }
            let d = s.sqrt();
            l[j * n + j] = d;
            for i in (j + 1)..n {
                let mut t = values[offset + i * n + j];
                for p in 0..j {
                    t -= l[i * n + p] * l[j * n + p];
                }
                l[i * n + j] = t / d;
            }
        }
        0
    }

    /// Equivalent to `torch.linalg.cholesky_ex`.
    pub fn tensor_linalg_cholesky_ex(
        &mut self,
        input: TensorNodeId,
        upper: bool,
    ) -> Result<(TensorNodeId, i32), AutogradError> {
        if self.tensor_requires_grad(input)? {
            // cholesky_ex differs from cholesky only by reporting `info` instead
            // of erroring on a non-positive-definite input. Under autograd the
            // factorization must succeed for the differentiable-Cholesky backward
            // to be defined, so we delegate to the autograd-aware
            // `tensor_linalg_cholesky` — whose forward uses the same
            // `cholesky_contiguous_f64` kernel, making the returned factor
            // bit-identical to the non-grad path — and report info=0. A non-PD
            // input under requires_grad surfaces cholesky's fail-loud (backward
            // through a failed factorization is undefined). frankentorch-rl4g.
            let out = self.tensor_linalg_cholesky(input, upper)?;
            return Ok((out, 0));
        }
        let (values, meta) = self.tensor_values_meta(input)?;
        match ft_kernel_cpu::cholesky_contiguous_f64(&values, &meta, upper) {
            Ok(result) => {
                let n = result.n;
                let out = self.tensor_variable(result.factor, vec![n, n], false)?;
                Ok((out, 0))
            }
            Err(_) => {
                let shape = meta.shape();
                let n = if shape.len() >= 2 {
                    shape[shape.len() - 1]
                } else {
                    1
                };
                // torch/LAPACK report `info` = the 1-indexed order of the first
                // leading minor that is not positive definite (NOT a constant 1).
                let info = Self::cholesky_failing_minor(&values, meta.storage_offset(), n);
                let info = if info == 0 { 1 } else { info };
                let zeros = vec![0.0; n * n];
                let out = self.tensor_variable(zeros, vec![n, n], false)?;
                Ok((out, info))
            }
        }
    }

    /// Alias for tensor_linalg_cholesky.
    ///
    /// Provided for parity with older PyTorch code using `torch.cholesky`.
    pub fn tensor_cholesky(
        &mut self,
        input: TensorNodeId,
        upper: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_linalg_cholesky(input, upper)
    }

    /// Solve A @ X = B given Cholesky factor L where A = L @ L^T.
    ///
    /// More efficient than general solve for symmetric positive-definite systems.
    /// `cholesky_factor` is the result of `tensor_linalg_cholesky`.
    /// B can be [n] or [n, m].
    pub fn tensor_cholesky_solve(
        &mut self,
        b: TensorNodeId,
        cholesky_factor: TensorNodeId,
        upper: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        let factor_shape = self.tensor_shape(cholesky_factor)?;
        let b_shape = self.tensor_shape(b)?;
        if factor_shape.len() >= 3
            && factor_shape[factor_shape.len() - 1] == factor_shape[factor_shape.len() - 2]
            && self.tensor_dtype(b)? == DType::F64
            && self.tensor_dtype(cholesky_factor)? == DType::F64
            && !self.tensor_requires_grad(b)?
            && !self.tensor_requires_grad(cholesky_factor)?
            && self.tensor_tape.tensor(b)?.meta().is_contiguous()
            && self
                .tensor_tape
                .tensor(cholesky_factor)?
                .meta()
                .is_contiguous()
        {
            let nd = factor_shape.len();
            let n = factor_shape[nd - 1];
            let batch_prefix = &factor_shape[..nd - 2];
            let (batch, nrhs) = if b_shape.len() == nd
                && b_shape[..nd - 2] == *batch_prefix
                && b_shape[nd - 2] == n
            {
                (batch_prefix.iter().product::<usize>(), b_shape[nd - 1])
            } else if b_shape.len() + 1 == nd
                && b_shape[..b_shape.len() - 1] == *batch_prefix
                && b_shape[b_shape.len() - 1] == n
            {
                (batch_prefix.iter().product::<usize>(), 1usize)
            } else {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                    ft_kernel_cpu::KernelError::ShapeMismatch {
                        lhs: b_shape.clone(),
                        rhs: factor_shape.clone(),
                    },
                )));
            };
            let out = {
                let factor_values = self
                    .tensor_tape
                    .tensor(cholesky_factor)?
                    .contiguous_values()?;
                let b_values = self.tensor_tape.tensor(b)?.contiguous_values()?;
                ft_kernel_cpu::cholesky_solve_batched_contiguous_f64(
                    factor_values,
                    b_values,
                    batch,
                    n,
                    nrhs,
                    upper,
                )
            };
            return self.tensor_variable(out, b_shape, false);
        }
        if factor_shape.len() != 2 || factor_shape[0] != factor_shape[1] {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: factor_shape,
                    rhs: vec![2],
                },
            )));
        }

        // F32 no-grad fast path: the native cholesky_solve_contiguous_f32 kernel
        // (two f32 TRSM sweeps, ~1.98x) replaces the triangular-solve composition,
        // which upcasts f32->f64 per sweep; staying in f32 also matches torch's f32
        // cholesky_solve. frankentorch-b3o90.
        if self.tensor_dtype(b)? == DType::F32
            && self.tensor_dtype(cholesky_factor)? == DType::F32
            && !self.tensor_requires_grad(b)?
            && !self.tensor_requires_grad(cholesky_factor)?
        {
            let n = factor_shape[0];
            let factor_f32 = self.tensor_values_f32(cholesky_factor)?;
            let b_f32 = self.tensor_values_f32(b)?;
            let b_meta = self.tensor_tape.tensor_meta(b)?.clone();
            let b_shape = b_meta.shape().to_vec();
            let solution = ft_kernel_cpu::cholesky_solve_contiguous_f32(
                &factor_f32,
                n,
                &b_f32,
                &b_meta,
                upper,
            )
            .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?;
            return self.tensor_variable_f32(solution, b_shape, false);
        }

        // Implement cholesky_solve as a PRIMITIVE autograd op carrying torch's
        // analytic backward, so the gradient w.r.t. the factor is DENSE (torch's
        // convention) rather than masked to the triangle.
        //
        // The previous design composed two masked `tensor_triangular_solve`s
        // (frankentorch-tw0y): correct VALUE and grad_B, but each triangular
        // solve masks its factor gradient to a triangle, leaving the off-triangle
        // entries of grad_L at 0. torch's `cholesky_solve_backward` instead
        // returns a dense factor gradient (the off-triangle entries are nonzero
        // even though the forward ignores them). frankentorch-crvxw.
        //
        // Forward solves A X = B with the SAME per-column substitution arithmetic
        // as the old composition, so the VALUE is bit-identical:
        //   A = L L^T (lower):  Y = L^{-1} B,  X = L^{-T} Y
        //   A = U^T U (upper):  Y = U^{-T} B,  X = U^{-1} Y
        // torch FunctionsManual `cholesky_solve_backward`:
        //   grad_B = cholesky_solve(grad_X, L, upper)
        //   common = (grad_B · X^T) + (grad_B · X^T)^T
        //   grad_L = -(common · L)   (lower)   |   -(L · common)   (upper)
        let n = factor_shape[0];
        let nrhs = if b_shape.len() == 1 { 1 } else { b_shape[1] };
        let b_shape_fwd = b_shape.clone();
        let b_shape_cg = b_shape.clone();
        self.tensor_apply_function_with_create_graph(
            &[b, cholesky_factor],
            move |ctx, inputs| {
                let (b_vals, _b_in_shape) = inputs[0];
                let (a_vals, a_in_shape) = inputs[1];
                let x = Self::chol_solve_substitute(a_vals, n, b_vals, nrhs, upper);
                // Save L (factor) and X (solution) for the analytic backward.
                ctx.save_for_backward(a_vals.to_vec(), a_in_shape.to_vec());
                ctx.save_for_backward(x.clone(), b_shape_fwd.clone());
                Ok((x, b_shape_fwd.clone()))
            },
            move |ctx, grad_outputs| {
                let grad_x = grad_outputs[0];
                let saved = ctx.saved_tensors();
                let a_vals = &saved[0]; // L  [n, n]
                let x_vals = &saved[1]; // X  [n, nrhs]
                // grad_B = cholesky_solve(grad_X, L, upper) — same solve as forward.
                let grad_b = Self::chol_solve_substitute(a_vals, n, grad_x, nrhs, upper);
                // grad_L = -sym(grad_B·Xᵀ)·L (lower) | -L·sym(grad_B·Xᵀ) (upper) via
                // the parallel BLAS-3 GEMM kernel instead of scalar O(n³) loops.
                // frankentorch-kgs4.81.
                let grad_l = ft_kernel_cpu::cholesky_solve_backward_grad_l_f64(
                    a_vals, &grad_b, x_vals, n, nrhs, upper,
                );
                Ok(vec![Some(grad_b), Some(grad_l)])
            },
            // create_graph backward: rebuild grad_B and the DENSE grad_L from
            // differentiable tape ops (general inverse of A = L L^T / U^T U) so the
            // second derivative propagates. Math matches the analytic backward to
            // tolerance. frankentorch-crvxw.
            move |_ctx, grad_outs, inputs, tape| {
                let mode = ft_core::ExecutionMode::Strict;
                let b_in = inputs[0];
                let l = inputs[1];
                let b_is_1d = b_shape_cg.len() == 1;
                let b2 = if b_is_1d {
                    tape.reshape(b_in, vec![n, nrhs])?
                } else {
                    b_in
                };
                let gx2 = if b_is_1d {
                    tape.reshape(grad_outs[0], vec![n, nrhs])?
                } else {
                    grad_outs[0]
                };
                let lt = tape.transpose(l, 0, 1)?;
                // A = L·L^T (lower) | U^T·U (upper) — symmetric, so A^{-T} == A^{-1}.
                let a = if upper {
                    tape.matmul(lt, l, mode)?.0
                } else {
                    tape.matmul(l, lt, mode)?.0
                };
                let inv_a = Self::cg_differentiable_inverse(tape, a, n)?;
                let grad_b2 = tape.matmul(inv_a, gx2, mode)?.0; // grad_B = A^{-1} grad_X
                let x2 = tape.matmul(inv_a, b2, mode)?.0; // X = A^{-1} B
                let x2t = tape.transpose(x2, 0, 1)?;
                let m = tape.matmul(grad_b2, x2t, mode)?.0; // grad_B · X^T
                let mt = tape.transpose(m, 0, 1)?;
                let common = tape.add(m, mt, mode)?.0; // symmetrize
                let prod = if upper {
                    tape.matmul(l, common, mode)?.0
                } else {
                    tape.matmul(common, l, mode)?.0
                };
                let grad_l = tape.neg(prod, mode)?.0;
                let grad_b = if b_is_1d {
                    tape.reshape(grad_b2, b_shape_cg.clone())?
                } else {
                    grad_b2
                };
                Ok(vec![Some(grad_b), Some(grad_l)])
            },
        )
    }

    /// Solve `(L L^T) X = RHS` (lower) or `(U^T U) X = RHS` (upper) by two
    /// triangular substitutions, row-major `[n, nrhs]`. Bit-identical arithmetic
    /// to the old `triangular_solve` composition (same per-column j-order), so the
    /// `cholesky_solve` VALUE is unchanged. frankentorch-crvxw.
    fn chol_solve_substitute(
        a: &[f64],
        n: usize,
        rhs: &[f64],
        nrhs: usize,
        upper: bool,
    ) -> Vec<f64> {
        let mut x = rhs.to_vec();
        for col in 0..nrhs {
            if upper {
                // Y = U^{-T} RHS  (U^T lower: U^T[i,j] = U[j,i], j < i).
                for i in 0..n {
                    let mut s = x[i * nrhs + col];
                    for j in 0..i {
                        s -= a[j * n + i] * x[j * nrhs + col];
                    }
                    x[i * nrhs + col] = s / a[i * n + i];
                }
                // X = U^{-1} Y  (U upper: U[i,j], j > i).
                for i in (0..n).rev() {
                    let mut s = x[i * nrhs + col];
                    for j in (i + 1)..n {
                        s -= a[i * n + j] * x[j * nrhs + col];
                    }
                    x[i * nrhs + col] = s / a[i * n + i];
                }
            } else {
                // Y = L^{-1} RHS  (L lower: L[i,j], j < i).
                for i in 0..n {
                    let mut s = x[i * nrhs + col];
                    for j in 0..i {
                        s -= a[i * n + j] * x[j * nrhs + col];
                    }
                    x[i * nrhs + col] = s / a[i * n + i];
                }
                // X = L^{-T} Y  (L^T upper: L^T[i,j] = L[j,i], j > i).
                for i in (0..n).rev() {
                    let mut s = x[i * nrhs + col];
                    for j in (i + 1)..n {
                        s -= a[j * n + i] * x[j * nrhs + col];
                    }
                    x[i * nrhs + col] = s / a[i * n + i];
                }
            }
        }
        x
    }

    /// Compute the matrix inverse.
    ///
    /// Returns A^-1 where A @ A^-1 = I. Errors if A is singular.
    ///
    /// Wraps the kernel inverse in a tensor_apply_function with the
    /// analytical backward
    ///     grad_A = -Y^T @ grad_Y @ Y^T   where Y = A^{-1}
    /// (standard matrix-calculus identity: dY = -A^{-1} dA A^{-1}).
    /// Saves Y for backward to avoid recomputing the inverse.
    /// Tracked under frankentorch-frq7 (child of frankentorch-tw0y).
    /// Inverse of a multi-dimensional tensor (the multiplicative inverse for
    /// `tensordot`). Equivalent to `torch.linalg.tensorinv(A, ind)`.
    ///
    /// `A` is regarded as a matrix by splitting its dimensions at `ind`:
    /// reshape to `(prod(shape[ind:]), prod(shape[:ind]))`, which must be square,
    /// invert it, and reshape the result to `shape[ind:] ++ shape[:ind]`. Both
    /// reshapes are contiguous, matching numpy/torch exactly; the gradient flows
    /// through the autograd-aware `linalg_inv`.
    pub fn tensor_linalg_tensorinv(
        &mut self,
        input: TensorNodeId,
        ind: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        if ind == 0 || ind >= shape.len() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "tensorinv: ind must satisfy 0 < ind < input.ndim",
                },
            )));
        }
        let m: usize = shape[..ind].iter().product(); // prod(shape[:ind])
        let n: usize = shape[ind..].iter().product(); // prod(shape[ind:])
        if m != n {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "tensorinv: prod(shape[:ind]) must equal prod(shape[ind:])",
                },
            )));
        }
        let mat = self.tensor_reshape(input, vec![n, m])?;
        let inv = self.tensor_linalg_inv(mat)?;
        let mut out_shape: Vec<usize> = shape[ind..].to_vec();
        out_shape.extend_from_slice(&shape[..ind]);
        self.tensor_reshape(inv, out_shape)
    }

    /// Solve the tensor equation `tensordot(A, X) = B` for `X`. Equivalent to
    /// `torch.linalg.tensorsolve(A, B)` (default axes).
    ///
    /// `A` has shape `B.shape ++ X.shape`; it is reshaped to
    /// `(prod(B.shape), prod(X.shape))` (which must be square), `B` is
    /// flattened, the square system is solved, and the result is reshaped to
    /// `X.shape = A.shape[B.ndim:]`. Gradient flows through `linalg_solve`.
    pub fn tensor_linalg_tensorsolve(
        &mut self,
        a: TensorNodeId,
        b: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let a_shape = self.tensor_shape(a)?;
        let b_shape = self.tensor_shape(b)?;
        if a_shape.len() < b_shape.len() || a_shape[..b_shape.len()] != b_shape[..] {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "tensorsolve: A.shape must begin with B.shape",
                },
            )));
        }
        let pb: usize = b_shape.iter().product(); // prod(B.shape)
        let x_shape: Vec<usize> = a_shape[b_shape.len()..].to_vec();
        let px: usize = x_shape.iter().product(); // prod(X.shape)
        if pb != px {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "tensorsolve: prod(B.shape) must equal prod(X.shape)",
                },
            )));
        }
        let a_mat = self.tensor_reshape(a, vec![pb, px])?;
        let b_vec = self.tensor_reshape(b, vec![pb])?;
        let x_vec = self.tensor_linalg_solve(a_mat, b_vec)?;
        self.tensor_reshape(x_vec, x_shape)
    }

    /// Build `Y = inv(A)` as a fresh DIFFERENTIABLE tape node for use inside a
    /// create_graph backward. Its own first-order backward is the standard
    /// `grad_A = -Yᵀ·grad_Y·Yᵀ`, so differentiating an expression that contains
    /// this node (e.g. logdet's `grad·Yᵀ` or inverse's `-Yᵀ·G·Yᵀ`) propagates
    /// the correct SECOND derivative. `n` is the matrix dimension. frankentorch-b820k.
    fn cg_differentiable_inverse(
        tape: &mut ft_autograd::TensorTape,
        a: TensorNodeId,
        n: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        tape.apply_function(
            &[a],
            move |ctx, ins| {
                let (vals, in_shape) = ins[0];
                let meta = TensorMeta::from_shape(in_shape.to_vec(), DType::F64, Device::Cpu);
                let result = ft_kernel_cpu::inv_tensor_contiguous_f64(vals, &meta)
                    .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?;
                ctx.save_for_backward(result.clone(), in_shape.to_vec());
                Ok((result, in_shape.to_vec()))
            },
            move |ctx, grad_outputs| {
                let grad_y = grad_outputs[0];
                let saved = ctx.saved_tensors();
                let y = &saved[0];
                if grad_y.len() != n * n || y.len() != n * n {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "cg inverse backward: gradient or saved-Y shape mismatch",
                        },
                    )));
                }
                // grad_A = -Yᵀ·grad_Y·Yᵀ via the parallel BLAS-3 GEMM kernel (shared
                // with the first-order inverse backward). frankentorch-kgs4.82.
                let grad_a = ft_kernel_cpu::inv_backward_f64(y, grad_y, n);
                Ok(vec![Some(grad_a)])
            },
        )
    }

    /// Build `det(A)` as a fresh DIFFERENTIABLE 0-D tape node for use inside a
    /// create_graph backward (Jacobi's formula backward `g·det·inv(A)ᵀ`), so an
    /// expression containing it propagates the correct SECOND derivative.
    /// frankentorch-b820k.
    fn cg_differentiable_det(
        tape: &mut ft_autograd::TensorTape,
        a: TensorNodeId,
        n: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        tape.apply_function(
            &[a],
            move |ctx, ins| {
                let (vals, in_shape) = ins[0];
                let meta = TensorMeta::from_shape(in_shape.to_vec(), DType::F64, Device::Cpu);
                let result = ft_kernel_cpu::det_contiguous_f64(vals, &meta)
                    .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?;
                ctx.save_for_backward(vals.to_vec(), in_shape.to_vec());
                Ok((vec![result.det], vec![]))
            },
            move |ctx, grad_outputs| {
                let g = grad_outputs[0];
                let saved = ctx.saved_tensors();
                let a = &saved[0];
                let meta = TensorMeta::from_shape(vec![n, n], DType::F64, Device::Cpu);
                let det_result = ft_kernel_cpu::det_contiguous_f64(a, &meta)
                    .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?;
                let inv_a = match ft_kernel_cpu::inv_tensor_contiguous_f64(a, &meta) {
                    Ok(inv) => inv,
                    Err(_) => return Ok(vec![Some(vec![0.0; n * n])]),
                };
                let scale = g[0] * det_result.det;
                let mut grad_a = vec![0.0_f64; n * n];
                for i in 0..n {
                    for j in 0..n {
                        grad_a[i * n + j] = scale * inv_a[j * n + i];
                    }
                }
                Ok(vec![Some(grad_a)])
            },
        )
    }

    pub fn tensor_linalg_inv(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        // Batched no-grad f64 fast path (A=[..,n,n]): A^{-1} = solve(A, I) via the parallel
        // batched LU-solve kernel with a per-matrix identity RHS. Matches torch's batched inv
        // (previously a 3-D error). Same kernel/regime as batched solve (kgs4.160).
        // frankentorch-qe48n.
        if shape.len() >= 3
            && shape[shape.len() - 1] == shape[shape.len() - 2]
            && self.tensor_dtype(input)? == DType::F64
            && !self.tensor_requires_grad(input)?
        {
            let nd = shape.len();
            let n = shape[nd - 1];
            let batch: usize = shape[..nd - 2].iter().product();
            if batch >= 2 && n > 0 {
                let a_values = self.tensor_values(input)?;
                let mut ident = vec![0.0f64; batch * n * n];
                for bi in 0..batch {
                    for i in 0..n {
                        ident[bi * n * n + i * n + i] = 1.0;
                    }
                }
                let inv =
                    ft_kernel_cpu::lu_solve_batched_contiguous_f64(&a_values, &ident, batch, n, n);
                return self.tensor_variable(inv, shape, false);
            }
        }
        // Batched f64 GRAD path (nd>=3): A⁻¹ via parallel batched LU-solve; backward
        // grad_A = -Yᵀ·grad_Y·Yᵀ per plane (parallel). Keystone for batched pinv/lstsq
        // grad (whose torch backward is pathologically slow). frankentorch batched-inv-grad.
        if shape.len() >= 3
            && shape[shape.len() - 1] == shape[shape.len() - 2]
            && self.tensor_dtype(input)? == DType::F64
            && self.tensor_requires_grad(input)?
            && self.tensor_tape.tensor(input)?.meta().is_contiguous()
        {
            let nd = shape.len();
            let n = shape[nd - 1];
            let bb: usize = shape[..nd - 2].iter().product();
            if bb >= 1 && n > 0 {
                let out_shape = shape.clone();
                return self.tensor_apply_function(
                    &[input],
                    {
                        let out_shape = out_shape.clone();
                        move |ctx, inputs| {
                            let (vals, in_shape) = inputs[0];
                            let mut ident = vec![0.0f64; bb * n * n];
                            for bi in 0..bb {
                                for i in 0..n {
                                    ident[bi * n * n + i * n + i] = 1.0;
                                }
                            }
                            let y = ft_kernel_cpu::lu_solve_batched_contiguous_f64(
                                vals, &ident, bb, n, n,
                            );
                            ctx.save_for_backward(y.clone(), in_shape.to_vec());
                            Ok((y, out_shape.clone()))
                        }
                    },
                    move |ctx, grad_outputs| {
                        let saved = ctx.saved_tensors();
                        let y = &saved[0];
                        let grad_y = grad_outputs[0];
                        let grad_a =
                            ft_kernel_cpu::inv_backward_batched_contiguous_f64(y, grad_y, bb, n);
                        Ok(vec![Some(grad_a)])
                    },
                );
            }
        }
        if shape.len() != 2 || shape[0] != shape[1] {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: shape.clone(),
                    rhs: vec![2],
                },
            )));
        }
        let n = shape[0];

        // F32 no-grad fast path: A^{-1} = solve(A, I) via native f32 LU
        // (lu_factor_contiguous_f32 + lu_solve_contiguous_f32), all in f32. Avoids
        // the f32->f64->f32 round trip and matches torch's f32 inverse.
        // frankentorch-b3o90.
        if self.tensor_dtype(input)? == DType::F32 && !self.tensor_requires_grad(input)? {
            let av = self.tensor_values_f32(input)?;
            let a_meta = self.tensor_tape.tensor_meta(input)?.clone();
            let f = ft_kernel_cpu::lu_factor_contiguous_f32(&av, &a_meta)
                .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?;
            let mut id = vec![0.0f32; n * n];
            for i in 0..n {
                id[i * n + i] = 1.0;
            }
            let id_meta = TensorMeta::from_shape(vec![n, n], DType::F32, Device::Cpu);
            let inv = ft_kernel_cpu::lu_solve_contiguous_f32(&f.lu, &f.pivots, n, &id, &id_meta)
                .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?;
            return self.tensor_variable_f32(inv, vec![n, n], false);
        }

        let out = self.tensor_apply_function_with_create_graph(
            &[input],
            move |ctx, inputs| {
                let (vals, in_shape) = inputs[0];
                let meta = TensorMeta::from_shape(in_shape.to_vec(), DType::F64, Device::Cpu);
                let result = ft_kernel_cpu::inv_tensor_contiguous_f64(vals, &meta)
                    .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?;
                // Save Y (the inverse) for backward.
                ctx.save_for_backward(result.clone(), in_shape.to_vec());
                Ok((result, in_shape.to_vec()))
            },
            move |ctx, grad_outputs| {
                let grad_y = grad_outputs[0];
                let saved = ctx.saved_tensors();
                let y = &saved[0];
                if grad_y.len() != n * n || y.len() != n * n {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "linalg_inv backward: gradient or saved-Y shape mismatch",
                        },
                    )));
                }
                // grad_A = -Yᵀ·grad_Y·Yᵀ via the parallel BLAS-3 GEMM kernel instead
                // of two scalar O(n³) loops. frankentorch-kgs4.81.
                let grad_a = ft_kernel_cpu::inv_backward_f64(y, grad_y, n);
                Ok(vec![Some(grad_a)])
            },
            // create_graph backward: rebuild grad_A = -Yᵀ·grad_Y·Yᵀ from
            // differentiable tape ops (Y = inv(A) as a differentiable node) so the
            // SECOND derivative of the inverse propagates instead of erroring.
            // frankentorch-b820k.
            move |_ctx, grad_outs, inputs, tape| {
                let mode = ft_core::ExecutionMode::Strict;
                let y = Self::cg_differentiable_inverse(tape, inputs[0], n)?;
                let yt = tape.transpose(y, 0, 1)?;
                let tmp = tape.matmul(yt, grad_outs[0], mode)?.0;
                let prod = tape.matmul(tmp, yt, mode)?.0;
                let grad_a = tape.neg(prod, mode)?.0;
                Ok(vec![Some(grad_a)])
            },
        )?;

        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!("linalg_inv input={} out={} (autograd)", input.0, out.0),
        );
        Ok(out)
    }

    /// Matrix inverse with info output.
    ///
    /// Returns `(inverse, info)` where info is 0 if successful, or positive
    /// if the matrix is singular. Equivalent to `torch.linalg.inv_ex`.
    pub fn tensor_linalg_inv_ex(
        &mut self,
        input: TensorNodeId,
    ) -> Result<(TensorNodeId, i32), AutogradError> {
        if self.tensor_requires_grad(input)? {
            // inv_ex differs from inv only by reporting `info` instead of erroring
            // on a singular matrix. Under autograd the factorization must succeed
            // for the backward (-Y^T grad_Y Y^T) to be defined, so we delegate to
            // the autograd-aware `tensor_linalg_inv` — whose forward uses the same
            // `inv_tensor_contiguous_f64` kernel, making the returned inverse
            // bit-identical to the non-grad path — and report info=0. A singular
            // input under requires_grad surfaces inv's fail-loud (backward through
            // a singular inverse is undefined). frankentorch-rl4g.
            let out = self.tensor_linalg_inv(input)?;
            return Ok((out, 0));
        }
        let shape = self.tensor_shape(input)?;
        if shape.len() != 2 || shape[0] != shape[1] {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: shape.clone(),
                    rhs: vec![2],
                },
            )));
        }
        let n = shape[0];
        let (values, meta) = self.tensor_values_meta(input)?;
        match ft_kernel_cpu::inv_tensor_contiguous_f64(&values, &meta) {
            Ok(result) => {
                let out = self.tensor_variable(result, vec![n, n], false)?;
                Ok((out, 0))
            }
            Err(_) => {
                // torch/LAPACK report `info` = the 1-indexed first singular pivot
                // (U[k,k] == 0 in A's LU), NOT a constant 1. Re-factor A and scan
                // the U-diagonal (the LU pivot sequence matches torch IPIV after
                // ibfw, so the zero lands at torch's position). frankentorch-ibfw
                // output-encoding class.
                let mut info = 1;
                if let Ok(f) = ft_kernel_cpu::lu_factor_contiguous_f64(&values, &meta) {
                    for k in 0..f.n {
                        if f.lu[k * f.n + k] == 0.0 {
                            #[allow(clippy::cast_possible_truncation, clippy::cast_possible_wrap)]
                            let v = (k + 1) as i32;
                            info = v;
                            break;
                        }
                    }
                }
                let zeros = vec![0.0; n * n];
                let out = self.tensor_variable(zeros, vec![n, n], false)?;
                Ok((out, info))
            }
        }
    }

    /// Solve the linear system `A @ X = B` with info output.
    ///
    /// Returns `(X, info)` where info is 0 if successful, or positive
    /// if A is singular. Equivalent to `torch.linalg.solve_ex`.
    pub fn tensor_linalg_solve_ex(
        &mut self,
        a: TensorNodeId,
        b: TensorNodeId,
    ) -> Result<(TensorNodeId, i32), AutogradError> {
        if self.tensor_requires_grad(a)? || self.tensor_requires_grad(b)? {
            // solve_ex differs from solve only by reporting `info` instead of
            // erroring on a singular A. Under autograd A must be invertible for
            // the solve adjoint to be defined, so we delegate to the
            // autograd-aware `tensor_linalg_solve` — which computes inv(A) @ B via
            // the same `tensor_linalg_inv` + matmul path as the non-grad branch
            // below, making X bit-identical — and report info=0. A singular A
            // under requires_grad surfaces inv's fail-loud. frankentorch-rl4g.
            let out = self.tensor_linalg_solve(a, b)?;
            return Ok((out, 0));
        }
        let (inv_a, info) = self.tensor_linalg_inv_ex(a)?;
        if info != 0 {
            let b_shape = self.tensor_shape(b)?;
            let zeros = vec![0.0; b_shape.iter().product()];
            let out = self.tensor_variable(zeros, b_shape.to_vec(), false)?;
            return Ok((out, info));
        }
        let b_shape = self.tensor_shape(b)?;
        let x = if b_shape.len() == 1 {
            let n = b_shape[0];
            let b_2d = self.tensor_reshape(b, vec![n, 1])?;
            let x_2d = self.tensor_matmul(inv_a, b_2d)?;
            self.tensor_reshape(x_2d, vec![n])?
        } else {
            self.tensor_matmul(inv_a, b)?
        };
        Ok((x, 0))
    }

    /// Compute the matrix product of a sequence of matrices.
    ///
    /// Equivalent to `torch.linalg.multi_dot(tensors)`. Matrix multiplication
    /// is associative, so the *order* of the pairwise products is free to
    /// choose — and for a chain of differently-shaped matrices the order
    /// changes the flop/intermediate cost by orders of magnitude (the classic
    /// example: a thin dimension in the middle). This picks the optimal
    /// parenthesization via matrix-chain dynamic programming (the same thing
    /// `torch.linalg.multi_dot` does), instead of multiplying left-to-right.
    ///
    /// Requires two or more tensors. The DP applies to a chain of 2-D matrices;
    /// if any operand is not 2-D (1-D row/column-vector ends) it falls back to
    /// the left-to-right product. All products use the autograd-aware
    /// `tensor_matmul`, so gradients are correct regardless of the order.
    pub fn tensor_linalg_multi_dot(
        &mut self,
        tensors: &[TensorNodeId],
    ) -> Result<TensorNodeId, AutogradError> {
        if tensors.len() < 2 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "multi_dot: need at least two tensors",
                },
            )));
        }
        if tensors.len() == 2 {
            return self.tensor_matmul(tensors[0], tensors[1]);
        }

        // Collect 2-D shapes; bail to left-to-right if any operand isn't a matrix.
        let nmat = tensors.len();
        let mut shapes = Vec::with_capacity(nmat);
        let mut all_2d = true;
        for &t in tensors {
            let s = self.tensor_shape(t)?;
            if s.len() != 2 {
                all_2d = false;
                break;
            }
            shapes.push(s);
        }
        if !all_2d {
            let mut result = self.tensor_matmul(tensors[0], tensors[1])?;
            for t in &tensors[2..] {
                result = self.tensor_matmul(result, *t)?;
            }
            return Ok(result);
        }

        // Dimension chain: matrix i is p[i] x p[i+1].
        let mut p = vec![0usize; nmat + 1];
        p[0] = shapes[0][0];
        for i in 0..nmat {
            p[i + 1] = shapes[i][1];
        }

        // Matrix-chain DP. m[i][j] = min scalar-mult cost for the sub-chain
        // i..=j; split[i][j] = the index k where that optimum parenthesizes as
        // (i..=k)(k+1..=j). Cost is u128 to avoid overflow on large chains.
        let mut m = vec![vec![0u128; nmat]; nmat];
        let mut split = vec![vec![0usize; nmat]; nmat];
        for len in 2..=nmat {
            for i in 0..=(nmat - len) {
                let j = i + len - 1;
                let mut best = u128::MAX;
                let mut best_k = i;
                for k in i..j {
                    let cost = m[i][k]
                        + m[k + 1][j]
                        + (p[i] as u128) * (p[k + 1] as u128) * (p[j + 1] as u128);
                    if cost < best {
                        best = cost;
                        best_k = k;
                    }
                }
                m[i][j] = best;
                split[i][j] = best_k;
            }
        }

        self.multi_dot_apply(tensors, &split, 0, nmat - 1)
    }

    /// Multiply the sub-chain `tensors[i..=j]` per the optimal `split` table
    /// (recursive, autograd-aware).
    fn multi_dot_apply(
        &mut self,
        tensors: &[TensorNodeId],
        split: &[Vec<usize>],
        i: usize,
        j: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        if i == j {
            return Ok(tensors[i]);
        }
        let k = split[i][j];
        let left = self.multi_dot_apply(tensors, split, i, k)?;
        let right = self.multi_dot_apply(tensors, split, k + 1, j)?;
        self.tensor_matmul(left, right)
    }

    /// Alias for `tensor_linalg_multi_dot`.
    pub fn tensor_chain_matmul(
        &mut self,
        tensors: &[TensorNodeId],
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_linalg_multi_dot(tensors)
    }

    /// Alias for `tensor_chain_matmul`. Equivalent to `torch.linalg.multi_dot`.
    pub fn tensor_multi_dot(
        &mut self,
        tensors: &[TensorNodeId],
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_linalg_multi_dot(tensors)
    }

    /// Solve a triangular linear system: A @ X = B.
    ///
    /// Equivalent to `torch.linalg.solve_triangular(A, B, upper)`.
    /// A must be a square triangular matrix.
    /// `torch.linalg.solve_triangular`: solve a triangular system, returning only
    /// the solution X.
    ///
    /// Solves `A X = B` when `left` (the default), or `X A = B` otherwise, where A
    /// is `upper`- (or lower-) triangular and, when `unitriangular`, its stored
    /// diagonal is treated as all ones. Composes the existing autograd-aware
    /// [`Self::tensor_triangular_solve`] with transposes (for the right-hand
    /// `left = false` form — `X A = B` ⟺ `A^T X^T = B^T`, and transposing flips the
    /// triangle) and a constant diagonal mask (for `unitriangular`), so gradients
    /// flow exactly as torch's (no gradient through the ignored unit diagonal, and
    /// `grad_A` masked to A's triangle).
    pub fn tensor_linalg_solve_triangular(
        &mut self,
        a: TensorNodeId,
        b: TensorNodeId,
        upper: bool,
        left: bool,
        unitriangular: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        let a_shape = self.tensor_shape(a)?;
        let r = a_shape.len();
        if r < 2 || a_shape[r - 1] != a_shape[r - 2] {
            return Err(Self::incompatible_tensor_args(
                "linalg.solve_triangular: A must be a batch of square matrices (*, n, n)",
            ));
        }
        let n = a_shape[r - 1];
        if r > 2 {
            // Batched: flatten the leading dims, solve each 2-D slice through the
            // 2-D path below, then stack and reshape back. select/stack/reshape are
            // all autograd-aware, so the per-batch (block-diagonal) gradient flows
            // exactly as torch's batched solve_triangular.
            let g: usize = a_shape[..r - 2].iter().product();
            let b_shape = self.tensor_shape(b)?;
            let bl = b_shape.len();
            if bl < 2 {
                return Err(Self::incompatible_tensor_args(
                    "linalg.solve_triangular: batched A requires a batched B (*, n, k)",
                ));
            }
            if b_shape[..bl - 2].iter().product::<usize>() != g {
                return Err(Self::incompatible_tensor_args(
                    "linalg.solve_triangular: B batch dims must match A batch dims",
                ));
            }
            let (br, bc) = (b_shape[bl - 2], b_shape[bl - 1]);
            let a_flat = self.tensor_reshape(a, vec![g, n, n])?;
            let b_flat = self.tensor_reshape(b, vec![g, br, bc])?;
            let mut slices = Vec::with_capacity(g);
            for gi in 0..g {
                let a_i = self.tensor_select(a_flat, 0, gi)?;
                let b_i = self.tensor_select(b_flat, 0, gi)?;
                let x_i =
                    self.tensor_linalg_solve_triangular(a_i, b_i, upper, left, unitriangular)?;
                slices.push(x_i);
            }
            let stacked = self.tensor_stack(&slices, 0)?;
            return self.tensor_reshape(stacked, b_shape);
        }
        // unitriangular: replace A's diagonal with ones via `A ⊙ (1 - I) + I`. The
        // mask/identity are constants, so no gradient flows through the (ignored)
        // diagonal — matching torch's unitriangular semantics.
        let a_eff = if unitriangular {
            let mut off = vec![1.0_f64; n * n];
            let mut eye = vec![0.0_f64; n * n];
            for i in 0..n {
                off[i * n + i] = 0.0;
                eye[i * n + i] = 1.0;
            }
            let off_t = self.tensor_variable(off, vec![n, n], false)?;
            let eye_t = self.tensor_variable(eye, vec![n, n], false)?;
            let masked = self.tensor_mul(a, off_t)?;
            self.tensor_add(masked, eye_t)?
        } else {
            a
        };
        if left {
            self.tensor_triangular_solve(a_eff, b, upper)
        } else {
            let b_shape = self.tensor_shape(b)?;
            if b_shape.len() != 2 {
                return Err(Self::incompatible_tensor_args(
                    "linalg.solve_triangular: left=false requires a 2-D B",
                ));
            }
            let at = self.tensor_transpose(a_eff, 0, 1)?;
            let bt = self.tensor_transpose(b, 0, 1)?;
            let xt = self.tensor_triangular_solve(at, bt, !upper)?;
            self.tensor_transpose(xt, 0, 1)
        }
    }

    /// Alias for [`Self::tensor_linalg_solve_triangular`].
    pub fn functional_linalg_solve_triangular(
        &mut self,
        a: TensorNodeId,
        b: TensorNodeId,
        upper: bool,
        left: bool,
        unitriangular: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_linalg_solve_triangular(a, b, upper, left, unitriangular)
    }

    /// `torch.linalg.ldl_factor`: the LDLᵀ (Bunch–Kaufman) factorization of a
    /// symmetric `(*, n, n)` F64 matrix (batched over the leading dims).
    ///
    /// Returns `(LD, pivots)` in LAPACK `dsytrf` packing (lower form): `LD` holds
    /// the unit lower-triangular L below the diagonal and the block-diagonal D on
    /// the diagonal (a 2×2 block stores its off-diagonal in the subdiagonal entry).
    /// `pivots` (shape `(*, n)`) is the LAPACK IPIV vector: a positive entry `p`
    /// (1-indexed) marks a 1×1 pivot block with rows `k`/`p-1` interchanged; two
    /// equal negative entries mark a 2×2 pivot block. Only the lower triangle of
    /// `input` is read. Like torch this is a NON-differentiable primitive; pair it
    /// with [`Self::tensor_linalg_ldl_solve`].
    pub fn tensor_linalg_ldl_factor(
        &mut self,
        input: TensorNodeId,
    ) -> Result<(TensorNodeId, TensorNodeId), AutogradError> {
        // F32: upcast, run the f64 core, downcast LD; pivots are integer indices
        // (kept as the f64 index tensor). Matches torch's f32 ldl_factor.
        if self.tensor_dtype(input)? == DType::F32 {
            let in64 = self.tensor_to_f64(input)?;
            let (ld64, piv) = self.tensor_linalg_ldl_factor(in64)?;
            return Ok((self.tensor_to_f32(ld64)?, piv));
        }
        let (values, meta) = self.tensor_values_meta(input)?;
        let shape = meta.shape();
        let r = shape.len();
        if r < 2 || shape[r - 1] != shape[r - 2] {
            return Err(Self::incompatible_tensor_args(
                "linalg.ldl_factor: input must be a batch of square matrices (*, n, n)",
            ));
        }
        if meta.dtype() != DType::F64 {
            return Err(Self::incompatible_tensor_args(
                "linalg.ldl_factor: only F64 input is supported",
            ));
        }
        let n = shape[r - 1];
        let batch: usize = shape[..r - 2].iter().product();
        let mut ld_all = vec![0.0_f64; batch * n * n];
        let mut piv_all = vec![0.0_f64; batch * n];
        for b in 0..batch {
            let (ld, ipiv) = Self::ldl_factor_lower_f64(&values[b * n * n..(b + 1) * n * n], n);
            ld_all[b * n * n..(b + 1) * n * n].copy_from_slice(&ld);
            #[allow(clippy::cast_precision_loss)]
            for (i, &p) in ipiv.iter().enumerate() {
                piv_all[b * n + i] = p as f64;
            }
        }
        let ld_node = self.tensor_variable(ld_all, shape.to_vec(), false)?;
        let piv_node = self.tensor_variable(piv_all, shape[..r - 1].to_vec(), false)?;
        Ok((ld_node, piv_node))
    }

    /// Alias for [`Self::tensor_linalg_ldl_factor`].
    pub fn functional_linalg_ldl_factor(
        &mut self,
        input: TensorNodeId,
    ) -> Result<(TensorNodeId, TensorNodeId), AutogradError> {
        self.tensor_linalg_ldl_factor(input)
    }

    /// `torch.linalg.ldl_solve`: solve `A X = B` using the `(LD, pivots)` produced
    /// by [`Self::tensor_linalg_ldl_factor`] (LAPACK `dsytrs`, lower form).
    /// Batched over matching leading dims: `LD` is `(*, n, n)`, `pivots` `(*, n)`,
    /// and `B` is `(*, n)` or `(*, n, k)`.
    pub fn tensor_linalg_ldl_solve(
        &mut self,
        ld: TensorNodeId,
        pivots: TensorNodeId,
        b: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // F32: upcast LD/B, run the f64 core, downcast X — matches torch's f32.
        if self.tensor_dtype(ld)? == DType::F32 {
            let ld64 = self.tensor_to_f64(ld)?;
            let b64 = self.tensor_to_f64(b)?;
            let x64 = self.tensor_linalg_ldl_solve(ld64, pivots, b64)?;
            return self.tensor_to_f32(x64);
        }
        let (ld_vals, ld_meta) = self.tensor_values_meta(ld)?;
        let ld_shape = ld_meta.shape();
        let r = ld_shape.len();
        if r < 2 || ld_shape[r - 1] != ld_shape[r - 2] {
            return Err(Self::incompatible_tensor_args(
                "linalg.ldl_solve: LD must be a batch of square matrices (*, n, n)",
            ));
        }
        if ld_meta.dtype() != DType::F64 {
            return Err(Self::incompatible_tensor_args(
                "linalg.ldl_solve: only F64 is supported",
            ));
        }
        let n = ld_shape[r - 1];
        let batch: usize = ld_shape[..r - 2].iter().product();
        let piv_vals = self.tensor_values(pivots)?;
        if piv_vals.len() != batch * n {
            return Err(Self::incompatible_tensor_args(
                "linalg.ldl_solve: pivots must have shape (*, n) matching LD",
            ));
        }
        #[allow(clippy::cast_possible_truncation)]
        let ipiv_all: Vec<i64> = piv_vals.iter().map(|&p| p.round() as i64).collect();
        let (b_vals, b_meta) = self.tensor_values_meta(b)?;
        let b_shape = b_meta.shape();
        if b_meta.dtype() != DType::F64 {
            return Err(Self::incompatible_tensor_args(
                "linalg.ldl_solve: B must be F64",
            ));
        }
        let bl = b_shape.len();
        // B is (*, n, k) (matrix RHS) or (*, n) (vector RHS).
        let (nrhs, b_batch) = if bl >= 2 && b_shape[bl - 2] == n {
            (b_shape[bl - 1], b_shape[..bl - 2].iter().product::<usize>())
        } else if bl >= 1 && b_shape[bl - 1] == n {
            (1usize, b_shape[..bl - 1].iter().product::<usize>())
        } else {
            return Err(Self::incompatible_tensor_args(
                "linalg.ldl_solve: B must be (*, n) or (*, n, k) matching LD",
            ));
        };
        if b_batch != batch {
            return Err(Self::incompatible_tensor_args(
                "linalg.ldl_solve: B batch dims must match LD batch dims",
            ));
        }
        let mut x = b_vals.to_vec();
        for bi in 0..batch {
            Self::ldl_solve_lower_f64(
                &ld_vals[bi * n * n..(bi + 1) * n * n],
                &ipiv_all[bi * n..(bi + 1) * n],
                &mut x[bi * n * nrhs..(bi + 1) * n * nrhs],
                n,
                nrhs,
            );
        }
        self.tensor_variable(x, b_shape.to_vec(), false)
    }

    /// Alias for [`Self::tensor_linalg_ldl_solve`].
    pub fn functional_linalg_ldl_solve(
        &mut self,
        ld: TensorNodeId,
        pivots: TensorNodeId,
        b: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_linalg_ldl_solve(ld, pivots, b)
    }

    /// LAPACK `dsytf2` core (lower, partial Bunch–Kaufman pivoting): factor the
    /// row-major symmetric n×n matrix into its packed LDLᵀ form, returning
    /// `(LD, ipiv)`. Reads only the lower triangle; the strict upper triangle of
    /// the result is zeroed to match torch.
    fn ldl_factor_lower_f64(values: &[f64], n: usize) -> (Vec<f64>, Vec<i64>) {
        let mut a = values.to_vec();
        let mut ipiv = vec![0_i64; n];
        let alpha = (1.0 + 17.0_f64.sqrt()) / 8.0;
        let mut k = 0;
        while k < n {
            let mut kstep = 1;
            let absakk = a[k * n + k].abs();
            // Largest off-diagonal in column k (rows below the diagonal).
            let mut imax = 0;
            let mut colmax = 0.0_f64;
            if k < n - 1 {
                imax = k + 1;
                for i in (k + 2)..n {
                    if a[i * n + k].abs() > a[imax * n + k].abs() {
                        imax = i;
                    }
                }
                colmax = a[imax * n + k].abs();
            }
            let kp;
            if absakk.max(colmax) == 0.0 {
                kp = k;
            } else if absakk >= alpha * colmax {
                kp = k;
            } else {
                // Largest off-diagonal in row imax (its lower-triangle entries).
                let mut rowmax = 0.0_f64;
                for j in k..imax {
                    rowmax = rowmax.max(a[imax * n + j].abs());
                }
                for i in (imax + 1)..n {
                    rowmax = rowmax.max(a[i * n + imax].abs());
                }
                if absakk >= alpha * colmax * (colmax / rowmax) {
                    kp = k;
                } else if a[imax * n + imax].abs() >= alpha * rowmax {
                    kp = imax;
                } else {
                    kp = imax;
                    kstep = 2;
                }
            }
            let kk = k + kstep - 1;
            if kp != kk {
                // Symmetric interchange of rows/columns kk and kp in the trailing
                // submatrix.
                for i in (kp + 1)..n {
                    a.swap(i * n + kk, i * n + kp);
                }
                for j in (kk + 1)..kp {
                    let t = a[j * n + kk];
                    a[j * n + kk] = a[kp * n + j];
                    a[kp * n + j] = t;
                }
                a.swap(kk * n + kk, kp * n + kp);
                if kstep == 2 {
                    a.swap((k + 1) * n + k, kp * n + k);
                }
            }
            if kstep == 1 {
                let d11 = a[k * n + k];
                if d11 != 0.0 {
                    for i in (k + 1)..n {
                        a[i * n + k] /= d11;
                    }
                    for j in (k + 1)..n {
                        let lj = a[j * n + k];
                        for i in j..n {
                            a[i * n + j] -= a[i * n + k] * (d11 * lj);
                        }
                    }
                }
                ipiv[k] = (kp + 1) as i64;
            } else {
                let d21 = a[(k + 1) * n + k];
                let d11 = a[(k + 1) * n + (k + 1)] / d21;
                let d22 = a[k * n + k] / d21;
                let tt = 1.0 / (d11 * d22 - 1.0);
                for j in (k + 2)..n {
                    let wk = tt * (d11 * a[j * n + k] - a[j * n + (k + 1)]);
                    let wkp1 = tt * (d22 * a[j * n + (k + 1)] - a[j * n + k]);
                    for i in j..n {
                        a[i * n + j] -=
                            (a[i * n + k] / d21) * wk + (a[i * n + (k + 1)] / d21) * wkp1;
                    }
                    a[j * n + k] = wk / d21;
                    a[j * n + (k + 1)] = wkp1 / d21;
                }
                ipiv[k] = -((kp + 1) as i64);
                ipiv[k + 1] = -((kp + 1) as i64);
            }
            k += kstep;
        }
        for i in 0..n {
            for j in (i + 1)..n {
                a[i * n + j] = 0.0;
            }
        }
        (a, ipiv)
    }

    /// LAPACK `dsytrs` core (lower): solve `A X = B` in place on `x` (row-major
    /// n×nrhs) using the packed factor `ld` and `ipiv` from
    /// [`Self::ldl_factor_lower_f64`].
    fn ldl_solve_lower_f64(ld: &[f64], ipiv: &[i64], x: &mut [f64], n: usize, nrhs: usize) {
        // Phase 1: forward substitution, solving L * D * X = B.
        let mut k = 0;
        while k < n {
            if ipiv[k] > 0 {
                let kp = (ipiv[k] - 1) as usize;
                if kp != k {
                    for c in 0..nrhs {
                        x.swap(k * nrhs + c, kp * nrhs + c);
                    }
                }
                for i in (k + 1)..n {
                    let l = ld[i * n + k];
                    for c in 0..nrhs {
                        x[i * nrhs + c] -= l * x[k * nrhs + c];
                    }
                }
                let d = ld[k * n + k];
                for c in 0..nrhs {
                    x[k * nrhs + c] /= d;
                }
                k += 1;
            } else {
                let kp = (-ipiv[k] - 1) as usize;
                if kp != k + 1 {
                    for c in 0..nrhs {
                        x.swap((k + 1) * nrhs + c, kp * nrhs + c);
                    }
                }
                for i in (k + 2)..n {
                    let lk = ld[i * n + k];
                    let lk1 = ld[i * n + (k + 1)];
                    for c in 0..nrhs {
                        x[i * nrhs + c] -= lk * x[k * nrhs + c] + lk1 * x[(k + 1) * nrhs + c];
                    }
                }
                let akm1k = ld[(k + 1) * n + k];
                let akm1 = ld[k * n + k] / akm1k;
                let ak = ld[(k + 1) * n + (k + 1)] / akm1k;
                let denom = akm1 * ak - 1.0;
                for c in 0..nrhs {
                    let bkm1 = x[k * nrhs + c] / akm1k;
                    let bk = x[(k + 1) * nrhs + c] / akm1k;
                    x[k * nrhs + c] = (ak * bkm1 - bk) / denom;
                    x[(k + 1) * nrhs + c] = (akm1 * bk - bkm1) / denom;
                }
                k += 2;
            }
        }
        // Phase 2: backward substitution, solving Lᵀ * X = B.
        let mut k = n;
        while k > 0 {
            k -= 1;
            if ipiv[k] > 0 {
                for i in (k + 1)..n {
                    let l = ld[i * n + k];
                    for c in 0..nrhs {
                        x[k * nrhs + c] -= l * x[i * nrhs + c];
                    }
                }
                let kp = (ipiv[k] - 1) as usize;
                if kp != k {
                    for c in 0..nrhs {
                        x.swap(k * nrhs + c, kp * nrhs + c);
                    }
                }
            } else {
                // 2×2 block spanning rows (k-1, k); k is the lower row.
                for i in (k + 1)..n {
                    let lk = ld[i * n + k];
                    let lk1 = ld[i * n + (k - 1)];
                    for c in 0..nrhs {
                        x[k * nrhs + c] -= lk * x[i * nrhs + c];
                        x[(k - 1) * nrhs + c] -= lk1 * x[i * nrhs + c];
                    }
                }
                let kp = (-ipiv[k] - 1) as usize;
                if kp != k {
                    for c in 0..nrhs {
                        x.swap(k * nrhs + c, kp * nrhs + c);
                    }
                }
                k -= 1;
            }
        }
    }

    pub fn tensor_triangular_solve(
        &mut self,
        a: TensorNodeId,
        b: TensorNodeId,
        upper: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        let a_shape = self.tensor_shape(a)?;
        let b_shape = self.tensor_shape(b)?;

        if a_shape.len() != 2 || a_shape[0] != a_shape[1] {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "triangular_solve: A must be a square 2-D matrix",
                },
            )));
        }

        let n = a_shape[0];
        let nrhs = if b_shape.len() == 1 { 1 } else { b_shape[1] };

        if matches!(b_shape.len(), 1 | 2) && b_shape[0] != n {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "triangular_solve: B rows must match A dimension",
                },
            )));
        }

        // tensor_apply_function takes (forward, backward) closures.
        // The forward solves AX = B by direct substitution.
        // The backward applies the standard triangular-solve identity:
        //     grad_B = A^{-T} grad_X
        //     grad_A = -A^{-T} grad_X X^T   masked to A's triangle
        // We implement triangular_solve(A^T, grad_X, !upper) inline
        // for the grad_B leg, then outer-product with -X^T to get
        // grad_A and zero out the off-triangular half.
        // Tracked under frankentorch-skpl (child of frankentorch-tw0y).
        let b_shape_clone = b_shape.clone();
        let b_shape_for_cg = b_shape.clone();
        let out = self.tensor_apply_function_with_create_graph(
            &[a, b],
            move |ctx, inputs| {
                let (a_vals, a_in_shape) = inputs[0];
                let (b_vals, _b_in_shape) = inputs[1];
                let mut x = b_vals.to_vec();
                // Each RHS column is an INDEPENDENT substitution (no singularity
                // guard: torch divides by the diagonal directly, yielding inf/nan
                // for a zero diagonal rather than raising — match that). For large
                // multi-RHS, run the columns in parallel — one barrier-free region
                // (same recipe as lu_solve/cholesky_solve, frankentorch-otbok).
                // Bit-exact: each column reproduces the serial sum/j-order. Gated
                // 1<<29 (the single-pass substitution has a higher crossover than
                // the 2-pass cholesky solve). frankentorch-trisolve-colpar.
                let tri_par =
                    nrhs >= 8 && (n as u128) * (n as u128) * (nrhs as u128) >= (1u128 << 29);
                let solve_col = |colv: &mut [f64]| {
                    if upper {
                        for i in (0..n).rev() {
                            let diag = a_vals[i * n + i];
                            let mut sum = colv[i];
                            for j in (i + 1)..n {
                                sum -= a_vals[i * n + j] * colv[j];
                            }
                            colv[i] = sum / diag;
                        }
                    } else {
                        for i in 0..n {
                            let diag = a_vals[i * n + i];
                            let mut sum = colv[i];
                            for j in 0..i {
                                sum -= a_vals[i * n + j] * colv[j];
                            }
                            colv[i] = sum / diag;
                        }
                    }
                };
                // BLAS-3 blocked path for the large multi-RHS regime (e.g. the n-RHS
                // triangular inverse): block the substitution into row panels and
                // apply each A panel once across ALL RHS columns via a fused GEMM,
                // instead of re-streaming A per column. Reassociates vs the scalar
                // sweep (within the dense-solve tolerance policy; torch uses LAPACK
                // trsm which is itself blocked). frankentorch-kgs4.68.
                let tri_blocked = nrhs >= 64 && n >= 256;
                if tri_blocked {
                    x = ft_kernel_cpu::triangular_solve_blocked_contiguous_f64(
                        a_vals, n, b_vals, nrhs, upper,
                    );
                } else if tri_par {
                    use rayon::prelude::*;
                    let mut xt = vec![0.0f64; nrhs * n];
                    for i in 0..n {
                        for col in 0..nrhs {
                            xt[col * n + i] = x[i * nrhs + col];
                        }
                    }
                    xt.par_chunks_mut(n).for_each(solve_col);
                    for i in 0..n {
                        for col in 0..nrhs {
                            x[i * nrhs + col] = xt[col * n + i];
                        }
                    }
                } else {
                    for col in 0..nrhs {
                        let mut colv: Vec<f64> = (0..n).map(|i| x[i * nrhs + col]).collect();
                        solve_col(&mut colv);
                        for i in 0..n {
                            x[i * nrhs + col] = colv[i];
                        }
                    }
                }
                // Save A (for the backward triangular_solve(A^T, ..)) and
                // X (for the outer product in grad_A).
                ctx.save_for_backward(a_vals.to_vec(), a_in_shape.to_vec());
                ctx.save_for_backward(x.clone(), b_shape_clone.clone());
                Ok((x, b_shape_clone.clone()))
            },
            move |ctx, grad_outputs| {
                let grad_x = grad_outputs[0];
                let saved = ctx.saved_tensors();
                let a_vals = &saved[0];
                let x_vals = &saved[1];

                // Step 1: grad_B = A^{-T} grad_X = triangular_solve(A^T, grad_X, !upper).
                // We perform the substitution directly on a transposed
                // view of A (i.e. swap (i, j) → (j, i) in indexing).
                // The triangle flips: solving with A^T treats the
                // upper-tri part of A as the lower-tri part of A^T.
                let mut grad_b = grad_x.to_vec();
                let solve_upper = !upper;
                for col in 0..nrhs {
                    if solve_upper {
                        for i in (0..n).rev() {
                            // diag of A^T is same as diag of A
                            let diag = a_vals[i * n + i];
                            // a_T[i,j] = a[j,i]; relevant for j > i
                            let mut sum = grad_b[i * nrhs + col];
                            for j in (i + 1)..n {
                                sum -= a_vals[j * n + i] * grad_b[j * nrhs + col];
                            }
                            grad_b[i * nrhs + col] = sum / diag;
                        }
                    } else {
                        for i in 0..n {
                            let diag = a_vals[i * n + i];
                            let mut sum = grad_b[i * nrhs + col];
                            for j in 0..i {
                                sum -= a_vals[j * n + i] * grad_b[j * nrhs + col];
                            }
                            grad_b[i * nrhs + col] = sum / diag;
                        }
                    }
                }

                // Step 2: grad_A = tri-mask(-grad_B·Xᵀ) via the parallel BLAS-3 GEMM
                // kernel instead of a scalar O(n²·nrhs) loop. frankentorch-kgs4.82.
                let grad_a = ft_kernel_cpu::triangular_solve_backward_grad_a_f64(
                    &grad_b, x_vals, n, nrhs, upper,
                );

                Ok(vec![Some(grad_a), Some(grad_b)])
            },
            // create_graph backward: rebuild grad_B = A⁻ᵀ·grad_X and
            // grad_A = -tri(A)-masked(grad_B · Xᵀ) from differentiable tape ops.
            // For triangular A, A⁻¹ from the (now differentiable) general inverse
            // gives the same X = A⁻¹B and the same derivatives — only the triangle
            // mask is triangular-specific — so the SECOND derivative propagates
            // instead of erroring. frankentorch-nj7x8.
            move |_ctx, grad_outs, inputs, tape| {
                let mode = ft_core::ExecutionMode::Strict;
                let b_is_1d = b_shape_for_cg.len() == 1;
                // View B / grad_X as [n, nrhs] for the matmuls.
                let b2 = if b_is_1d {
                    tape.reshape(inputs[1], vec![n, nrhs])?
                } else {
                    inputs[1]
                };
                let gx2 = if b_is_1d {
                    tape.reshape(grad_outs[0], vec![n, nrhs])?
                } else {
                    grad_outs[0]
                };
                // Triangle mask of A (1.0 inside A's triangle, else 0.0).
                let mut mask_vals = vec![0.0_f64; n * n];
                for i in 0..n {
                    for k in 0..n {
                        let in_triangle = if upper { k >= i } else { k <= i };
                        if in_triangle {
                            mask_vals[i * n + k] = 1.0;
                        }
                    }
                }
                let mask = tape.leaf(mask_vals, vec![n, n], false)?;
                // Mask A to its triangle BEFORE inverting: triangular_solve ignores
                // the off-triangle entries entirely, so no gradient (1st OR 2nd
                // order) may flow to them. A is already triangular so a_tri == A in
                // value; the mask zeroes ∂/∂(off-triangle) for the general inverse.
                let a_tri = tape.mul(inputs[0], mask, mode)?.0;
                let inv_a = Self::cg_differentiable_inverse(tape, a_tri, n)?;
                let inv_at = tape.transpose(inv_a, 0, 1)?;
                // grad_B = A⁻ᵀ @ grad_X
                let grad_b2 = tape.matmul(inv_at, gx2, mode)?.0;
                // X = A⁻¹ @ B  (== forward output; differentiable for grad_A's 2nd deriv)
                let x2 = tape.matmul(inv_a, b2, mode)?.0;
                let x2t = tape.transpose(x2, 0, 1)?;
                // grad_A = -(grad_B @ Xᵀ) ⊙ triangle-mask(A)
                let gb_xt = tape.matmul(grad_b2, x2t, mode)?.0;
                let neg = tape.neg(gb_xt, mode)?.0;
                let grad_a = tape.mul(neg, mask, mode)?.0;
                let grad_b = if b_is_1d {
                    tape.reshape(grad_b2, b_shape_for_cg.clone())?
                } else {
                    grad_b2
                };
                Ok(vec![Some(grad_a), Some(grad_b)])
            },
        )?;
        Ok(out)
    }

    /// Compute the inverse of a symmetric positive-definite matrix via Cholesky.
    ///
    /// Equivalent to `torch.cholesky_inverse(L, upper)`.
    /// More numerically stable than general inverse for SPD matrices.
    pub fn tensor_cholesky_inverse(
        &mut self,
        cholesky_factor: TensorNodeId,
        upper: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(cholesky_factor)?;
        let nd = shape.len();
        if nd < 2 || shape[nd - 1] != shape[nd - 2] {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "cholesky_inverse: input must be a (batch of) square matrix",
                },
            )));
        }
        let n = shape[nd - 1];
        // Solve L @ L^T @ X = I using cholesky_solve. For BATCHED input route through the batched
        // (parallel per-plane) cholesky_solve with a broadcast identity RHS. torch.cholesky_inverse
        // has no batched potri and torch.cholesky_solve falls off a pathological large-nrhs cliff
        // (nrhs=n: ~5.5s @ B=400 n=64 vs FT ~6ms) — so batched inverse is a large win.
        // frankentorch batched-cholesky-inverse.
        let identity = self.eye(n, false)?; // [n,n]
        let eye_rhs = if nd == 2 {
            identity
        } else {
            self.tensor_broadcast_to(identity, shape.clone())?
        };
        self.tensor_cholesky_solve(eye_rhs, cholesky_factor, upper)
    }

    /// Compute a matrix norm.
    ///
    /// Equivalent to `torch.linalg.matrix_norm(input, ord)`.
    /// Supported ords: "fro" (Frobenius, default), "nuc" (nuclear, sum of singular
    /// values), 1 (max col sum), -1 (min col sum), inf (max row sum),
    /// -inf (min row sum), 2 (spectral, max singular value), -2 (min singular value).
    pub fn tensor_matrix_norm(
        &mut self,
        input: TensorNodeId,
        ord: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        // Batched fast path for the singular-value norms (ord in {2,-2,nuc}): route [...,m,n]
        // through the batched svdvals + a per-plane reduction over the singular values (~5-8x vs
        // PyTorch's per-plane svd loop). svdvals/sum_dim/max_dim/min_dim are all batched-GRAD-aware,
        // so this also serves requires_grad (torch's batched matrix_norm grad is slow: looped per-plane
        // SVD fwd+bwd ~227-521ms). frankentorch batched-matrix-norm-grad.
        if shape.len() >= 3 && matches!(ord, "2" | "-2" | "nuc") {
            let sv = self.tensor_linalg_svdvals(input)?;
            let last = self.tensor_shape(sv)?.len() - 1;
            return match ord {
                "nuc" => self.tensor_sum_dim(sv, last),
                "2" => Ok(self.tensor_max_dim(sv, last)?.0),
                _ => Ok(self.tensor_min_dim(sv, last)?.0),
            };
        }
        if shape.len() != 2 {
            // Migrate to InvalidDimension (frankentorch-oitu).
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::InvalidDimension {
                    dim: shape.len(),
                    ndim: 2,
                },
            )));
        }

        // Compose through autograd primitives so gradients flow to
        // the input. Previously the body extracted tensor_values,
        // computed the norm in plain f64, and rebuilt a
        // requires_grad=false leaf — silently severing the autograd
        // tape on tracked inputs. Same severed-autograd pattern as
        // the cov / corrcoef / mode / quantile family fixed under
        // frankentorch-1tax. Tracked under frankentorch-i4rd.
        //
        // The sum-of-row-or-column-abs paths reduce to a 1-D vector
        // and then take a scalar max/min. tensor_max_dim / min_dim
        // along the only dim of a 1-D tensor returns a 0-D scalar
        // (and discards the argmax index — gradient flows through
        // the values branch only). For shape parity with the previous
        // contract (output shape [1]), reshape via tensor_unsqueeze
        // at the end.
        let result = match ord {
            "fro" => {
                let sq = self.tensor_mul(input, input)?;
                let sum_sq = self.tensor_sum(sq)?;
                self.tensor_sqrt(sum_sq)?
            }
            "1" | "inf" | "-1" | "-inf" => {
                let reduce_dim: usize = if ord == "1" || ord == "-1" {
                    // ||A||_1 = max_j sum_i |A_ij|; sum over rows (dim=0).
                    0
                } else {
                    // ||A||_inf = max_i sum_j |A_ij|; sum over cols (dim=1).
                    1
                };
                let take_max = ord == "1" || ord == "inf";
                let abs_a = self.tensor_abs(input)?;
                let sums = self.tensor_sum_dim(abs_a, reduce_dim)?;
                let (reduced, _argidx) = if take_max {
                    self.tensor_max_dim(sums, 0)?
                } else {
                    self.tensor_min_dim(sums, 0)?
                };
                reduced
            }
            "2" | "-2" | "nuc" => {
                // Spectral / nuclear norms via the singular values:
                //   ||A||_2   = max singular value (largest σ)
                //   ||A||_-2  = min singular value (smallest σ)
                //   ||A||_nuc = sum of singular values
                // tensor_linalg_svdvals is autograd-aware (it threads the
                // gradient back as U diag(grad_σ) Vh), so composing
                // sum/max/min on top keeps these differentiable — matching
                // torch.linalg.matrix_norm. Previously these ords (and the
                // public tensor_nuclear_norm, which delegates here with
                // "nuc") fell through to the error arm and always failed.
                let sv = self.tensor_linalg_svdvals(input)?;
                if ord == "nuc" {
                    self.tensor_sum(sv)?
                } else if ord == "2" {
                    let (m, _idx) = self.tensor_max_dim(sv, 0)?;
                    m
                } else {
                    let (m, _idx) = self.tensor_min_dim(sv, 0)?;
                    m
                }
            }
            _ => {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "matrix_norm: unsupported ord (use fro, nuc, 1, -1, 2, -2, inf, -inf)",
                    },
                )));
            }
        };

        // Previous contract was a 1-D shape [1] output. tensor_sum
        // and tensor_max_dim along the only dim both yield a 0-D
        // scalar (shape [] or [1] — depends on the kernel), so
        // promote / preserve shape via reshape. We use unsqueeze if
        // the reduction left a 0-D scalar.
        let result_shape = self.tensor_shape(result)?;
        if result_shape.is_empty() {
            self.tensor_unsqueeze(result, 0)
        } else if result_shape == [1] {
            Ok(result)
        } else {
            // Defensive: reshape to [1].
            self.tensor_reshape(result, vec![1])
        }
    }

    /// Alias for tensor_matrix_norm.
    ///
    /// Equivalent to `torch.linalg.matrix_norm(input, ord)`.
    pub fn tensor_linalg_matrix_norm(
        &mut self,
        input: TensorNodeId,
        ord: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_matrix_norm(input, ord)
    }

    /// Frobenius norm of a matrix.
    ///
    /// Equivalent to `torch.linalg.norm(input, 'fro')`.
    /// The Frobenius norm is sqrt(sum of squared elements).
    pub fn tensor_frobenius_norm(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_matrix_norm(input, "fro")
    }

    /// Nuclear norm (trace norm) of a matrix.
    ///
    /// Equivalent to `torch.linalg.norm(input, 'nuc')`.
    /// The nuclear norm is the sum of singular values.
    pub fn tensor_nuclear_norm(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_matrix_norm(input, "nuc")
    }

    /// Scatter values into positions indicated by a mask.
    ///
    /// Equivalent to `torch.Tensor.masked_scatter_(mask, source)`.
    /// Copies elements from `source` into positions where `mask` is non-zero.
    pub fn tensor_masked_scatter(
        &mut self,
        input: TensorNodeId,
        mask: TensorNodeId,
        source: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // Compose tensor_masked_scatter through autograd-aware
        // primitives so the backward pass actually flows through both
        // `input` (at the un-masked positions) and `source` (at the
        // first n_true source slots). The previous body extracted
        // values and rebuilt a requires_grad=false leaf — same
        // severed-autograd pattern recently fixed in
        // index_add / index_copy / index_fill / Scatter / ScatterAdd
        // / IndexPut.
        //
        // Strategy:
        //   1. Walk the (non-tracked) mask values to compute, for
        //      each flat position i, the source slot index that
        //      masked_scatter would copy from there: it's the prefix
        //      sum of the mask, minus one. Where mask[i] == 0 we set
        //      a *valid* sentinel index (clamped to [0, src_len-1]
        //      or 0 when src_len == 0 and there are no true masks)
        //      so the gather below stays in-bounds; tensor_where
        //      below masks those positions out.
        //   2. tensor_reshape `source` to a flat 1-D view (autograd
        //      flows through reshape).
        //   3. tensor_gather(source_flat, 0, prefix_clamped_node) →
        //      a tensor of the same shape as input where each slot
        //      holds the source value that masked_scatter would put
        //      there if the mask was true. Gather's backward
        //      scatter_adds gradient back to source at the gathered
        //      positions — which are exactly the first n_true source
        //      slots, with each used exactly once.
        //   4. tensor_where(mask, scattered, input). Where's
        //      backward routes the incoming gradient to scattered
        //      at mask==1 slots and to input at mask==0 slots — the
        //      analytical adjoint of masked_scatter.
        //
        // For mask==0 positions, the gather index is irrelevant
        // (always masked out by where), but we still need the index
        // to be in-bounds. We pick `src_len-1` (or 0 if src_len==0
        // and n_true==0) so gather succeeds; the corresponding slot
        // in `scattered` is then discarded by where, and gather's
        // backward correctly accumulates 0 into source at those
        // positions because grad_scattered = 0 at mask==0 slots.
        // Validate dtype + device + shape contracts up-front, BEFORE
        // any fast path. The slow path delegates these checks to
        // tensor_where (cond / x / y must match dtype + device +
        // shape) and to tensor_gather (source dtype propagates
        // through reshape -> gather -> scattered). If the n_true == 0
        // fast path returns input directly without these checks,
        // mask/source mismatches would be silently accepted, making
        // validation data-dependent on mask contents (closes
        // frankentorch-zdpm).
        let input_dtype = self.tensor_tape.dtype(input)?;
        let mask_dtype = self.tensor_tape.dtype(mask)?;
        let source_dtype = self.tensor_tape.dtype(source)?;
        if mask_dtype != input_dtype || source_dtype != input_dtype {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "masked_scatter requires input, mask, and source to share dtype",
                },
            )));
        }
        let input_device = self.tensor_tape.tensor(input)?.meta().device();
        let mask_device = self.tensor_tape.tensor(mask)?.meta().device();
        let source_device = self.tensor_tape.tensor(source)?.meta().device();
        if mask_device != input_device || source_device != input_device {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "masked_scatter requires input, mask, and source to be on the same device",
                },
            )));
        }

        // Read the mask as f64 regardless of its float dtype — `values` is F64-only and
        // ERRORED (UnsupportedDType(F32)) for an f32 mask (FT requires mask dtype == input
        // dtype, so f32 input => f32 mask => crash). The mask is 0/1 so lossy f64 is exact.
        let mask_vals = self.tensor_tape.values_lossy_f64(mask)?;
        let shape = self.tensor_shape(input)?;
        let input_numel =
            Self::checked_shape_numel(&shape, "masked_scatter: input shape volume overflow")?;
        if input_numel != mask_vals.len() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "masked_scatter: input and mask must have same number of elements",
                },
            )));
        }

        let source_shape = self.tensor_shape(source)?;
        let source_numel = Self::checked_shape_numel(
            &source_shape,
            "masked_scatter: source shape volume overflow",
        )?;

        let n_true = mask_vals.iter().filter(|&&m| m != 0.0).count();
        if n_true > source_numel {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "masked_scatter: source doesn't have enough elements",
                },
            )));
        }

        // Empty-source fast path: source is shape-empty so its
        // gradient contract collapses to a zero-length vector that
        // cannot have come from anywhere — the autograd backward
        // produces nothing for it regardless. n_true must be 0 here
        // (validated above), so the output equals input. No gather
        // is needed and source has nothing to thread through the
        // graph.
        if source_numel == 0 {
            // n_true is provably 0 here (otherwise the size check
            // would have errored), so output == input.
            debug_assert_eq!(n_true, 0);
            return Ok(input);
        }

        // No-grad fast path (f32/f64): masked_scatter copies the first n_true source values
        // into the True positions of the mask in row-major order. The autograd composition
        // below materializes a full prefix-index tensor, gathers source through it, then runs
        // tensor_where — three tape ops + intermediates. For the no-grad case do it DIRECTLY in
        // ONE pass: read input into result, borrow source zero-copy, and walk the mask copying
        // source[count++] into each True slot. Bit-identical (same row-major source order).
        if !self.tensor_requires_grad(input)?
            && !self.tensor_requires_grad(source)?
            && matches!(input_dtype, DType::F64 | DType::F32)
        {
            if input_dtype == DType::F64 {
                let mut result = self.tensor_tape.values(input)?;
                let src_owned: Vec<f64>;
                let src_vals: &[f64] = if self.tensor_tape.tensor(source)?.meta().is_contiguous() {
                    self.tensor_tape.tensor(source)?.contiguous_values()?
                } else {
                    src_owned = self.tensor_tape.values(source)?;
                    &src_owned
                };
                let mut count = 0usize;
                for (i, &m) in mask_vals.iter().enumerate() {
                    if m != 0.0 {
                        result[i] = src_vals[count];
                        count += 1;
                    }
                }
                return self.tensor_variable(result, shape, false);
            }
            let mut result = self.tensor_tape.values_f32(input)?;
            let src_owned: Vec<f32>;
            let src_vals: &[f32] = if self.tensor_tape.tensor(source)?.meta().is_contiguous() {
                self.tensor_tape.tensor(source)?.contiguous_values_f32()?
            } else {
                src_owned = self.tensor_tape.values_f32(source)?;
                &src_owned
            };
            let mut count = 0usize;
            for (i, &m) in mask_vals.iter().enumerate() {
                if m != 0.0 {
                    result[i] = src_vals[count];
                    count += 1;
                }
            }
            return self.tensor_variable_f32(result, shape, false);
        }

        // Non-empty source: thread source through the graph via the
        // gather + where composition below in BOTH n_true == 0 and
        // n_true > 0 cases. When n_true == 0, every prefix slot is
        // the safe sentinel `source_numel - 1`; gather still copies
        // those values into `scattered`, but tensor_where's all-false
        // mask discards them so the forward output equals input bit-
        // for-bit. The backward then correctly zeros source's
        // gradient (gather backward of an all-zero grad_scattered),
        // which the previous fast-path-returns-input shortcut would
        // have left as None — closes frankentorch-c4tx.
        //
        // Build the gather index: source_numel >= 1 here, so the
        // safe sentinel index 0..source_numel is in-bounds.
        let mut prefix_idx = Vec::with_capacity(input_numel);
        let mut count: usize = 0;
        let safe_off_index = source_numel - 1;
        #[allow(clippy::cast_precision_loss)]
        for &m in &mask_vals {
            if m != 0.0 {
                prefix_idx.push(count as f64);
                count += 1;
            } else {
                prefix_idx.push(safe_off_index as f64);
            }
        }

        let prefix_node = self
            .tensor_tape
            .leaf(prefix_idx, vec![input_numel], false)?;
        let source_flat = self.tensor_reshape(source, vec![source_numel])?;
        let scattered_flat = self.tensor_gather(source_flat, 0, prefix_node)?;
        let scattered = self.tensor_reshape(scattered_flat, shape.clone())?;
        self.tensor_where(mask, scattered, input)
    }

    /// Compute A^n via binary exponentiation.
    ///
    /// n > 0: repeated squaring. n = 0: identity. n < 0: inv(A)^|n|.
    pub fn tensor_matrix_power(
        &mut self,
        input: TensorNodeId,
        n: i32,
    ) -> Result<TensorNodeId, AutogradError> {
        // f32/half: compute in f64 then cast back (the inverse/matmul core
        // upcasts). torch keeps the input dtype. frankentorch-h9ghv.
        let dt = self.tensor_dtype(input)?;
        if dt != DType::F64 {
            let in64 = self.tensor_to_dtype(input, DType::F64)?;
            let out64 = self.tensor_matrix_power(in64, n)?;
            return self.tensor_to_dtype(out64, dt);
        }
        let shape = self.tensor_shape(input)?;
        let nd = shape.len();
        // Accept 2-D AND batched (nd>=3) square inputs. The squaring loop below is built entirely
        // from tensor_matmul (batched-aware + a tiny-n high-batch WIN over torch.bmm) so batched
        // matrix_power works for free — torch's batched matrix_power loops bmm (saturating). The
        // matmul chain is grad-aware, so batched grad works too. frankentorch batched-matrix-power.
        if nd < 2 || shape[nd - 1] != shape[nd - 2] {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: shape,
                    rhs: vec![2],
                },
            )));
        }
        let dim = shape[nd - 1];

        if n == 0 {
            // Identity matching the (possibly batched) input shape; A^0 is constant (grad zero).
            if nd == 2 {
                return self.eye(dim, false);
            }
            let bb: usize = shape[..nd - 2].iter().product();
            let mut data = vec![0.0_f64; bb * dim * dim];
            for b in 0..bb {
                for d in 0..dim {
                    data[b * dim * dim + d * dim + d] = 1.0;
                }
            }
            return self.tensor_variable(data, shape, false);
        }

        // For negative n, invert first (tensor_linalg_inv is batched-aware).
        let base = if n < 0 {
            self.tensor_linalg_inv(input)?
        } else {
            input
        };

        // Binary exponentiation with lazy init — avoids needing a (batched) identity for the
        // first multiply (n>=1 guarantees at least one set bit).
        let mut exp = n.unsigned_abs();
        let mut result: Option<TensorNodeId> = None;
        let mut current = base;

        while exp > 0 {
            if exp & 1 == 1 {
                result = Some(match result {
                    None => current,
                    Some(r) => self.tensor_matmul(r, current)?,
                });
            }
            exp >>= 1;
            if exp > 0 {
                current = self.tensor_matmul(current, current)?;
            }
        }

        match result {
            Some(r) => Ok(r),
            // Unreachable: a nonzero exponent guarantees at least one set bit. Return an error
            // (not a fallible-accessor macro) to keep this lint-clean for production code.
            None => Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: shape,
                    rhs: vec![2],
                },
            ))),
        }
    }

    /// Matrix exponential: exp(A).
    ///
    /// Uses scaling-and-squaring with Padé [6/6] approximation.
    /// NOT element-wise exp — this is the matrix exponential.
    /// Matrix exponential, `expm(A)`. Equivalent to `torch.linalg.matrix_exp`
    /// (the canonical namespace; `torch.matrix_exp` is deprecated in favor of
    /// it). Delegates to the autograd-aware `tensor_matrix_exp`.
    pub fn tensor_linalg_matrix_exp(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_matrix_exp(input)
    }

    pub fn tensor_matrix_exp(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // f32/half: compute in f64 then cast back (the expm core is f64-only).
        // torch keeps the input dtype. frankentorch-h9ghv.
        let dt = self.tensor_dtype(input)?;
        // f32/f16/bf16 WITH grad: the f64 grad path below (block-2n Fréchet derivative) is
        // F64-only, so a differentiable non-f64 matrix_exp previously ERRORED ("autograd only
        // supported for a square F64 matrix"). torch.matrix_exp(f32) IS differentiable -> f32.
        // Upcast to f64, run the f64 grad path, narrow the output back (to_dtype is grad-aware,
        // so the f32 input still gets f32 grads). frankentorch-fk5l.
        if dt != DType::F64 && self.tensor_requires_grad(input)? {
            let sh = self.tensor_shape(input)?;
            if sh.len() == 2 && sh[0] == sh[1] {
                let in64 = self.tensor_to_dtype(input, DType::F64)?;
                let out64 = self.tensor_matrix_exp(in64)?;
                return self.tensor_to_dtype(out64, dt);
            }
        }
        // F32 no-grad fast path: the native matrix_exp_contiguous_f32 kernel (square
        // GEMM, ~2.0x) replaces the f32->f64->f32 round-trip AND matches torch's f32
        // expm — torch computes in the input dtype, so the f64-upcast path diverged
        // from torch f32. frankentorch-b3o90.
        if dt == DType::F32
            && !self.tensor_requires_grad(input)?
            && self.tensor_shape(input)?.len() == 2
        {
            let iv = self.tensor_values_f32(input)?;
            let meta = self.tensor_tape.tensor_meta(input)?.clone();
            let out = ft_kernel_cpu::matrix_exp_contiguous_f32(&iv, &meta)
                .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?;
            let shape = meta.shape().to_vec();
            return self.tensor_variable_f32(out, shape, false);
        }
        // Batched no-grad f32 fast path: native f32 batched matrix_exp.
        if dt == DType::F32 && !self.tensor_requires_grad(input)? {
            let shape = self.tensor_shape(input)?;
            let nd = shape.len();
            if nd >= 3
                && shape[nd - 1] == shape[nd - 2]
                && self.tensor_tape.tensor(input)?.meta().is_contiguous()
            {
                let meta = self.tensor_tape.tensor_meta(input)?.clone();
                let out = {
                    let v = self.tensor_tape.tensor(input)?.contiguous_values_f32()?;
                    ft_kernel_cpu::matrix_exp_batched_contiguous_f32(v, &meta).map_err(|e| {
                        AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                    })?
                };
                return self.tensor_variable_f32(out, shape, false);
            }
        }
        if dt != DType::F64 {
            let in64 = self.tensor_to_dtype(input, DType::F64)?;
            let out64 = self.tensor_matrix_exp(in64)?;
            return self.tensor_to_dtype(out64, dt);
        }
        // Batched no-grad f64 fast path: parallelize the verified 2-D matrix_exp over the batch
        // (3.7-10.5x vs PyTorch's per-plane scaling-squaring loop). frankentorch-batched-eigh.
        if !self.tensor_requires_grad(input)? {
            let shape = self.tensor_shape(input)?;
            let nd = shape.len();
            if nd >= 3
                && shape[nd - 1] == shape[nd - 2]
                && self.tensor_tape.tensor(input)?.meta().is_contiguous()
            {
                let meta = self.tensor_tape.tensor_meta(input)?.clone();
                let out = {
                    let v = self.tensor_tape.tensor(input)?.contiguous_values()?;
                    ft_kernel_cpu::matrix_exp_batched_contiguous_f64(v, &meta).map_err(|e| {
                        AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                    })?
                };
                return self.tensor_variable(out, shape, false);
            }
        }
        // Batched f64 grad path (nd>=3): parallelize the per-plane forward expm and the
        // per-plane augmented-expm backward over the batch, vs PyTorch's serial per-plane
        // loop. Single output -> 1x forward. frankentorch batched-matrix-exp-grad.
        if self.tensor_requires_grad(input)? {
            let bshape = self.tensor_shape(input)?;
            let nd = bshape.len();
            if nd >= 3
                && bshape[nd - 1] == bshape[nd - 2]
                && self.tensor_dtype(input)? == DType::F64
                && self.tensor_tape.tensor(input)?.meta().is_contiguous()
            {
                let device = self.tensor_tape.tensor_meta(input)?.device();
                let n = bshape[nd - 1];
                let bb: usize = bshape[..nd - 2].iter().product();
                let out = self.tensor_apply_function(
                    &[input],
                    move |ctx, inputs| {
                        let (values, in_shape) = inputs[0];
                        let meta = TensorMeta::from_shape(in_shape.to_vec(), DType::F64, device);
                        let y = ft_kernel_cpu::matrix_exp_batched_contiguous_f64(values, &meta)
                            .map_err(|e| {
                                AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                            })?;
                        ctx.save_for_backward(values.to_vec(), in_shape.to_vec());
                        Ok((y, in_shape.to_vec()))
                    },
                    move |ctx, grad_outputs| {
                        let saved = ctx.saved_tensors();
                        let a = &saved[0];
                        let grad_y = grad_outputs[0];
                        let grad_a = ft_kernel_cpu::matrix_exp_backward_batched_contiguous_f64(
                            a, grad_y, bb, n,
                        )
                        .map_err(|e| {
                            AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                        })?;
                        Ok(vec![Some(grad_a)])
                    },
                )?;
                return Ok(out);
            }
        }
        let input_meta = self.tensor_tape.tensor_meta(input)?.clone();
        if self.tensor_requires_grad(input)? {
            // Reverse-mode backward of Y = expm(A). The adjoint of the Fréchet
            // derivative of expm at A equals the Fréchet derivative at A^T, and
            // that derivative is the top-right n×n block of the matrix exponential
            // of the 2n×2n block-triangular matrix
            //     M = [[A^T, grad_Y], [0, A^T]]   →   expm(M)[0:n, n:2n] = grad_A
            // (Higham, "Functions of Matrices", §10.2 / Al-Mohy & Higham 2009).
            // Forward reuses the same matrix_exp_contiguous_f64 kernel, so the
            // returned value is bit-identical to the non-grad path; only the
            // previously-severed gradient (this op silently returned a non-grad
            // leaf) is restored. frankentorch-rl4g.
            let shape = input_meta.shape();
            if shape.len() == 2 && shape[0] == shape[1] && input_meta.dtype() == DType::F64 {
                let device = input_meta.device();
                let out = self.tensor_apply_function(
                    &[input],
                    move |ctx, inputs| {
                        let (values, in_shape) = inputs[0];
                        let meta = TensorMeta::from_shape(in_shape.to_vec(), DType::F64, device);
                        let y = ft_kernel_cpu::matrix_exp_contiguous_f64(values, &meta).map_err(
                            |e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)),
                        )?;
                        // Save A (the input) — backward needs A^T.
                        ctx.save_for_backward(values.to_vec(), in_shape.to_vec());
                        Ok((y, in_shape.to_vec()))
                    },
                    move |ctx, grad_outputs| {
                        let saved = ctx.saved_tensors();
                        let a = &saved[0];
                        let grad_y = grad_outputs[0];
                        #[allow(clippy::cast_possible_truncation, clippy::cast_sign_loss)]
                        let n = (a.len() as f64).sqrt().round() as usize;
                        // Build the 2n×2n augmented matrix M = [[A^T, grad_Y],
                        // [0, A^T]] in row-major order.
                        let m2 = 2 * n;
                        let mut aug = vec![0.0_f64; m2 * m2];
                        for i in 0..n {
                            for j in 0..n {
                                let at = a[j * n + i]; // A^T[i][j] = A[j][i]
                                aug[i * m2 + j] = at; // (0,0) block
                                aug[(i + n) * m2 + (j + n)] = at; // (1,1) block
                                aug[i * m2 + (j + n)] = grad_y[i * n + j]; // (0,1) block
                            }
                        }
                        let meta2 = TensorMeta::from_shape(vec![m2, m2], DType::F64, device);
                        let expm = ft_kernel_cpu::matrix_exp_contiguous_f64(&aug, &meta2).map_err(
                            |e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)),
                        )?;
                        // grad_A = top-right n×n block of expm(M).
                        let mut grad_a = vec![0.0_f64; n * n];
                        for i in 0..n {
                            for j in 0..n {
                                grad_a[i * n + j] = expm[i * m2 + (j + n)];
                            }
                        }
                        Ok(vec![Some(grad_a)])
                    },
                )?;
                self.runtime.ledger_mut().record(
                    EvidenceKind::Dispatch,
                    format!("matrix_exp input={} out={} (autograd)", input.0, out.0),
                );
                return Ok(out);
            }
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "matrix_exp: autograd only supported for a square F64 matrix",
                },
            )));
        }
        let (values, meta) = self.tensor_values_meta(input)?;
        let result = ft_kernel_cpu::matrix_exp_contiguous_f64(&values, &meta)
            .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?;
        let shape = meta.shape().to_vec();
        self.tensor_variable(result, shape, false)
    }

    /// Eigendecomposition of a symmetric matrix: A = V @ diag(λ) @ V^T.
    ///
    /// Returns `(eigenvalues, eigenvectors)` where eigenvalues are sorted ascending
    /// and eigenvectors are the columns of V (orthonormal).
    pub fn tensor_linalg_eigh(
        &mut self,
        input: TensorNodeId,
    ) -> Result<(TensorNodeId, TensorNodeId), AutogradError> {
        // f32/half: compute in f64 then cast BOTH outputs back (the eig core is
        // f64-only). torch keeps the input dtype on every output. frankentorch-clqek.
        let dt = self.tensor_dtype(input)?;
        // F32 no-grad fast path: native f32 symmetric eig (eigh_contiguous_f32 —
        // f32 Householder reduction + f32 QL with rotation accumulation), computed
        // in f32 like torch (dtype contract), completing the native f32 linalg
        // family alongside eigvalsh. frankentorch-b6pem follow-up.
        if dt == DType::F32
            && !self.tensor_requires_grad(input)?
            && self.tensor_shape(input)?.len() == 2
        {
            let iv = self.tensor_values_f32(input)?;
            let meta = self.tensor_tape.tensor_meta(input)?.clone();
            let r = ft_kernel_cpu::eigh_contiguous_f32(&iv, &meta)
                .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?;
            let n = r.n;
            let evals = self.tensor_variable_f32(r.eigenvalues, vec![n], false)?;
            let evecs = self.tensor_variable_f32(r.eigenvectors, vec![n, n], false)?;
            return Ok((evals, evecs));
        }
        // Batched no-grad f32 fast path: native f32 batched eigh (parallel over the batch, no f64
        // round trip). ~PyTorch f32 batched eigh loops LAPACK (142-345ms small k). frankentorch-batched-eigh.
        if dt == DType::F32 && !self.tensor_requires_grad(input)? {
            let shape = self.tensor_shape(input)?;
            let nd = shape.len();
            if nd >= 3
                && shape[nd - 1] == shape[nd - 2]
                && self.tensor_tape.tensor(input)?.meta().is_contiguous()
            {
                let meta = self.tensor_tape.tensor_meta(input)?.clone();
                let (evals, evecs) = {
                    let v = self.tensor_tape.tensor(input)?.contiguous_values_f32()?;
                    ft_kernel_cpu::eigh_batched_contiguous_f32(v, &meta).map_err(|e| {
                        AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                    })?
                };
                let mut eval_shape = shape.clone();
                eval_shape.pop();
                let evals_node = self.tensor_variable_f32(evals, eval_shape, false)?;
                let evecs_node = self.tensor_variable_f32(evecs, shape, false)?;
                return Ok((evals_node, evecs_node));
            }
        }
        if dt != DType::F64 {
            let in64 = self.tensor_to_dtype(input, DType::F64)?;
            let (v, q) = self.tensor_linalg_eigh(in64)?;
            return Ok((self.tensor_to_dtype(v, dt)?, self.tensor_to_dtype(q, dt)?));
        }
        // Batched no-grad f64 fast path: parallelize the verified 2-D eigh over the batch
        // (5.7-10.7x vs PyTorch's per-plane LAPACK-loop for small k). frankentorch-batched-eigh.
        if !self.tensor_requires_grad(input)? {
            let shape = self.tensor_shape(input)?;
            let nd = shape.len();
            if nd >= 3
                && shape[nd - 1] == shape[nd - 2]
                && self.tensor_tape.tensor(input)?.meta().is_contiguous()
            {
                let meta = self.tensor_tape.tensor_meta(input)?.clone();
                let (evals, evecs) = {
                    let v = self.tensor_tape.tensor(input)?.contiguous_values()?;
                    ft_kernel_cpu::eigh_batched_contiguous_f64(v, &meta).map_err(|e| {
                        AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                    })?
                };
                let mut eval_shape = shape.clone();
                eval_shape.pop(); // [..., k]
                let evals_node = self.tensor_tape.leaf(evals, eval_shape, false)?;
                let evecs_node = self.tensor_tape.leaf(evecs, shape, false)?;
                return Ok((evals_node, evecs_node));
            }
        }
        // Batched f64 grad path (nd>=3): the per-plane decomposition + per-plane VJP
        // both parallelize over the batch, vs PyTorch's serial per-plane syevd + per-plane
        // backward loop. Two independent single-output nodes (evals + evecs) sum their
        // grad_A contributions, mirroring the 2-D path. Each plane's eigenvector VJP is
        // bit-identical to the 2-D call; TOLERANCE-parity overall. frankentorch batched-eigh-grad.
        if self.tensor_requires_grad(input)? {
            let bshape = self.tensor_shape(input)?;
            let nd = bshape.len();
            if nd >= 3
                && bshape[nd - 1] == bshape[nd - 2]
                && self.tensor_dtype(input)? == DType::F64
                && self.tensor_tape.tensor(input)?.meta().is_contiguous()
            {
                let device = self.tensor_tape.tensor_meta(input)?.device();
                let mut eval_shape = bshape.clone();
                eval_shape.pop(); // [..., k]
                // Eigenvalues node — grad_A = V diag(grad_λ) Vᵀ per plane (parallel).
                let evals = self.tensor_apply_function(
                    &[input],
                    {
                        let eval_shape = eval_shape.clone();
                        move |ctx, inputs| {
                            let (values, in_shape) = inputs[0];
                            let meta =
                                TensorMeta::from_shape(in_shape.to_vec(), DType::F64, device);
                            let (evals, evecs) = ft_kernel_cpu::eigh_batched_contiguous_f64(
                                values, &meta,
                            )
                            .map_err(|e| {
                                AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                            })?;
                            ctx.save_for_backward(evecs, in_shape.to_vec());
                            Ok((evals, eval_shape.clone()))
                        }
                    },
                    move |ctx, grad_outputs| {
                        let saved = ctx.saved_tensors();
                        let v = &saved[0]; // [B*k*k] eigenvectors
                        let grad_l = grad_outputs[0]; // [B*k]
                        let grad_a = ft_kernel_cpu::eigvalsh_grad_batched_contiguous_f64(grad_l, v)
                            .map_err(|e| {
                                AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                            })?;
                        Ok(vec![Some(grad_a)])
                    },
                )?;
                // Eigenvectors node — grad_A = sym(V (F∘(Vᵀ grad_V)) Vᵀ) per plane (parallel).
                let evecs = self.tensor_apply_function(
                    &[input],
                    move |ctx, inputs| {
                        let (values, in_shape) = inputs[0];
                        let meta = TensorMeta::from_shape(in_shape.to_vec(), DType::F64, device);
                        let (evals, evecs) =
                            ft_kernel_cpu::eigh_batched_contiguous_f64(values, &meta).map_err(
                                |e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)),
                            )?;
                        ctx.save_for_backward(evecs.clone(), in_shape.to_vec());
                        let nd = in_shape.len();
                        let k = in_shape[nd - 1];
                        let mut ev_shape = in_shape[..nd - 1].to_vec();
                        ev_shape.push(k);
                        ctx.save_for_backward(evals, ev_shape);
                        Ok((evecs, in_shape.to_vec()))
                    },
                    move |ctx, grad_outputs| {
                        let saved = ctx.saved_tensors();
                        let v = &saved[0]; // [B*k*k]
                        let w = &saved[1]; // [B*k] eigenvalues
                        let grad_v = grad_outputs[0]; // [B*k*k]
                        let total_w = w.len();
                        if total_w == 0 || v.len() % total_w != 0 {
                            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                                ft_dispatch::DispatchKeyError::IncompatibleSet {
                                    reason: "batched eigh evecs backward: shape mismatch",
                                },
                            )));
                        }
                        let k = v.len() / total_w;
                        let bb = total_w / k;
                        let grad_a = ft_kernel_cpu::eigh_eigenvector_vjp_batched_contiguous_f64(
                            v, w, grad_v, bb, k,
                        );
                        Ok(vec![Some(grad_a)])
                    },
                )?;
                return Ok((evals, evecs));
            }
        }
        if self.tensor_requires_grad(input)? {
            // Symmetric eigendecomposition backward WITHOUT a multi-output tape
            // primitive: eigenvalues and eigenvectors are independent functions of
            // A, so the chain rule sums their contributions to grad_A. We build TWO
            // independent single-output autograd nodes from the same `input` — the
            // engine accumulates (adds) both nodes' grad_A contributions into the
            // input's gradient slot (accumulate_tensor_gradient is `+=`). Each
            // forward recomputes the (deterministic) decomposition, so both outputs
            // are bit-identical to the non-grad path. Valid for simple (distinct)
            // eigenvalues — the eigenvector term needs 1/(λ_j-λ_i). frankentorch-rl4g.
            let input_meta = self.tensor_tape.tensor_meta(input)?.clone();
            let shape = input_meta.shape();
            if shape.len() == 2 && shape[0] == shape[1] && input_meta.dtype() == DType::F64 {
                let device = input_meta.device();
                // Eigenvalues node — grad_A = V diag(grad_λ) V^T (already symmetric).
                let evals = self.tensor_apply_function(
                    &[input],
                    move |ctx, inputs| {
                        let (values, in_shape) = inputs[0];
                        let meta = TensorMeta::from_shape(in_shape.to_vec(), DType::F64, device);
                        let r = ft_kernel_cpu::eigh_contiguous_f64(values, &meta).map_err(|e| {
                            AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                        })?;
                        let n = r.n;
                        ctx.save_for_backward(r.eigenvectors, vec![n, n]);
                        Ok((r.eigenvalues, vec![n]))
                    },
                    move |ctx, grad_outputs| {
                        let saved = ctx.saved_tensors();
                        let v = &saved[0]; // V (n x n, eigenvectors in columns)
                        let grad_l = grad_outputs[0]; // [n]
                        let n = grad_l.len();
                        // grad_A = V·diag(grad_l)·Vᵀ via the parallel BLAS-3 GEMM
                        // instead of a scalar O(n³) triple loop. frankentorch-kgs4.75.
                        let grad_a = ft_kernel_cpu::eigh_eigenvalue_vjp_f64(v, grad_l, n);
                        Ok(vec![Some(grad_a)])
                    },
                )?;
                // Eigenvectors node — grad_A = sym(V (F ∘ (V^T grad_V)) V^T) with
                // F[a][b] = 1/(λ_b - λ_a) for a≠b, 0 on the diagonal.
                let evecs = self.tensor_apply_function(
                    &[input],
                    move |ctx, inputs| {
                        let (values, in_shape) = inputs[0];
                        let meta = TensorMeta::from_shape(in_shape.to_vec(), DType::F64, device);
                        let r = ft_kernel_cpu::eigh_contiguous_f64(values, &meta).map_err(|e| {
                            AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                        })?;
                        let n = r.n;
                        ctx.save_for_backward(r.eigenvectors.clone(), vec![n, n]);
                        ctx.save_for_backward(r.eigenvalues, vec![n]);
                        Ok((r.eigenvectors, vec![n, n]))
                    },
                    move |ctx, grad_outputs| {
                        let saved = ctx.saved_tensors();
                        let v = &saved[0]; // V (n x n)
                        let w = &saved[1]; // eigenvalues [n]
                        let grad_v = grad_outputs[0]; // n x n
                        let n = w.len();
                        // grad_A = sym(V·(F∘(Vᵀ·grad_V))·Vᵀ) via the parallel BLAS-3
                        // GEMMs instead of three scalar O(n³) loops. frankentorch-kgs4.75.
                        let grad_a = ft_kernel_cpu::eigh_eigenvector_vjp_f64(v, w, grad_v, n);
                        Ok(vec![Some(grad_a)])
                    },
                )?;
                self.runtime.ledger_mut().record(
                    EvidenceKind::Dispatch,
                    format!(
                        "linalg_eigh input={} evals={} evecs={} (autograd)",
                        input.0, evals.0, evecs.0
                    ),
                );
                return Ok((evals, evecs));
            }
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "linalg_eigh: autograd only supported for a square F64 matrix",
                },
            )));
        }
        let (values, meta) = self.tensor_values_meta(input)?;
        let result = ft_kernel_cpu::eigh_contiguous_f64(&values, &meta)
            .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?;
        let n = result.n;
        let evals = self.tensor_variable(result.eigenvalues, vec![n], false)?;
        let evecs = self.tensor_variable(result.eigenvectors, vec![n, n], false)?;
        Ok((evals, evecs))
    }

    /// Compute just the eigenvalues of a symmetric matrix (sorted ascending).
    pub fn tensor_linalg_eigvalsh(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // f32/half: compute in f64 then cast back (the symmetric-eig core is
        // f64-only). torch keeps the input dtype. frankentorch-aqllp.
        let dt = self.tensor_dtype(input)?;
        // F32 no-grad fast path: native f32 symmetric eigenvalues
        // (eigvalsh_contiguous_f32 — f32 Householder reduction + f32 QL). The
        // reduction is memory-bandwidth-bound, so computing in f32 (~half the
        // traffic) avoids the f32->f64->f32 round trip AND matches torch's f32
        // eigvalsh (f32 eigenvalues are ~f32-accurate, the contract for an f32
        // input). frankentorch-b6pem.
        if dt == DType::F32
            && !self.tensor_requires_grad(input)?
            && self.tensor_shape(input)?.len() == 2
        {
            let iv = self.tensor_values_f32(input)?;
            let meta = self.tensor_tape.tensor_meta(input)?.clone();
            let n = meta.shape()[0];
            let out = ft_kernel_cpu::eigvalsh_contiguous_f32(&iv, &meta)
                .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?;
            return self.tensor_variable_f32(out, vec![n], false);
        }
        // Batched no-grad f32 fast path: native f32 batched eigvalsh (no f64 round trip).
        if dt == DType::F32 && !self.tensor_requires_grad(input)? {
            let shape = self.tensor_shape(input)?;
            let nd = shape.len();
            if nd >= 3
                && shape[nd - 1] == shape[nd - 2]
                && self.tensor_tape.tensor(input)?.meta().is_contiguous()
            {
                let meta = self.tensor_tape.tensor_meta(input)?.clone();
                let evals = {
                    let v = self.tensor_tape.tensor(input)?.contiguous_values_f32()?;
                    ft_kernel_cpu::eigvalsh_batched_contiguous_f32(v, &meta).map_err(|e| {
                        AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                    })?
                };
                let mut eval_shape = shape.clone();
                eval_shape.pop();
                return self.tensor_variable_f32(evals, eval_shape, false);
            }
        }
        if dt != DType::F64 {
            let in64 = self.tensor_to_dtype(input, DType::F64)?;
            let out64 = self.tensor_linalg_eigvalsh(in64)?;
            return self.tensor_to_dtype(out64, dt);
        }
        // Batched no-grad f64 fast path: parallelize the verified 2-D eigvalsh over the batch
        // (~3-7x vs PyTorch's per-plane LAPACK-loop for small k). frankentorch-batched-eigh.
        if !self.tensor_requires_grad(input)? {
            let shape = self.tensor_shape(input)?;
            let nd = shape.len();
            if nd >= 3
                && shape[nd - 1] == shape[nd - 2]
                && self.tensor_tape.tensor(input)?.meta().is_contiguous()
            {
                let meta = self.tensor_tape.tensor_meta(input)?.clone();
                let evals = {
                    let v = self.tensor_tape.tensor(input)?.contiguous_values()?;
                    ft_kernel_cpu::eigvalsh_batched_contiguous_f64(v, &meta).map_err(|e| {
                        AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                    })?
                };
                let mut eval_shape = shape.clone();
                eval_shape.pop(); // [..., k]
                return self.tensor_tape.leaf(evals, eval_shape, false);
            }
        }
        if self.tensor_requires_grad(input)? {
            // Symmetric eigenvalue backward: with A = V diag(λ) V^T (V the
            // orthonormal eigenvectors), d λ_k / d A = v_k v_k^T, so
            //   grad_A = V diag(grad_λ) V^T = sum_k grad_λ_k · v_k v_k^T,
            // which is symmetric. eigvalsh and eigh return identical eigenvalues
            // (eigvalsh delegates to eigh), so the forward value matches the
            // non-grad path exactly. frankentorch-rl4g.
            let input_meta = self.tensor_tape.tensor_meta(input)?.clone();
            let shape = input_meta.shape();
            // Batched grad path: differentiable batched eigvalsh via a fused forward (batched eigh,
            // saving V) + a fused backward kernel (grad_A = V diag(grad_λ) Vᵀ per plane, parallel).
            // No per-plane tape; the fwd-dominated step beats PyTorch's per-plane LAPACK loop.
            // frankentorch-batched-eigh. (BlackThrush)
            if shape.len() >= 3
                && shape[shape.len() - 1] == shape[shape.len() - 2]
                && input_meta.dtype() == DType::F64
            {
                let device = input_meta.device();
                let out = self.tensor_apply_function(
                    &[input],
                    move |ctx, inputs| {
                        let (values, in_shape) = inputs[0];
                        let meta = TensorMeta::from_shape(in_shape.to_vec(), DType::F64, device);
                        let (evals, evecs) =
                            ft_kernel_cpu::eigh_batched_contiguous_f64(values, &meta).map_err(
                                |e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)),
                            )?;
                        ctx.save_for_backward(evecs, in_shape.to_vec());
                        let mut eshape = in_shape.to_vec();
                        eshape.pop();
                        Ok((evals, eshape))
                    },
                    move |ctx, grad_outputs| {
                        let saved = ctx.saved_tensors();
                        let evecs = &saved[0];
                        let grad_l = grad_outputs[0];
                        let grad_a =
                            ft_kernel_cpu::eigvalsh_grad_batched_contiguous_f64(grad_l, evecs)
                                .map_err(|e| {
                                    AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                                })?;
                        Ok(vec![Some(grad_a)])
                    },
                )?;
                self.runtime.ledger_mut().record(
                    EvidenceKind::Dispatch,
                    format!(
                        "linalg_eigvalsh input={} out={} (batched autograd)",
                        input.0, out.0
                    ),
                );
                return Ok(out);
            }
            if shape.len() == 2 && shape[0] == shape[1] && input_meta.dtype() == DType::F64 {
                let device = input_meta.device();
                let out = self.tensor_apply_function(
                    &[input],
                    move |ctx, inputs| {
                        let (values, in_shape) = inputs[0];
                        let meta = TensorMeta::from_shape(in_shape.to_vec(), DType::F64, device);
                        let r = ft_kernel_cpu::eigh_contiguous_f64(values, &meta).map_err(|e| {
                            AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                        })?;
                        let n = r.n;
                        ctx.save_for_backward(r.eigenvectors, vec![n, n]);
                        Ok((r.eigenvalues, vec![n]))
                    },
                    move |ctx, grad_outputs| {
                        let saved = ctx.saved_tensors();
                        let v = &saved[0]; // V (n x n, eigenvectors in columns).
                        let grad_l = grad_outputs[0]; // grad w.r.t. eigenvalues, [n].
                        let n = grad_l.len();
                        let mut grad_a = vec![0.0_f64; n * n];
                        for i in 0..n {
                            for j in 0..n {
                                let mut s = 0.0_f64;
                                for k in 0..n {
                                    s += v[i * n + k] * grad_l[k] * v[j * n + k];
                                }
                                grad_a[i * n + j] = s;
                            }
                        }
                        Ok(vec![Some(grad_a)])
                    },
                )?;
                self.runtime.ledger_mut().record(
                    EvidenceKind::Dispatch,
                    format!("linalg_eigvalsh input={} out={} (autograd)", input.0, out.0),
                );
                return Ok(out);
            }
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "linalg_eigvalsh: autograd only supported for a square F64 matrix",
                },
            )));
        }
        let (values, meta) = self.tensor_values_meta(input)?;
        let n = meta.shape()[0];
        let evals = ft_kernel_cpu::eigvalsh_contiguous_f64(&values, &meta)
            .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?;
        self.tensor_variable(evals, vec![n], false)
    }

    /// Alias for `tensor_linalg_eigh`. Equivalent to deprecated `torch.eigh`.
    pub fn tensor_eigh(
        &mut self,
        input: TensorNodeId,
    ) -> Result<(TensorNodeId, TensorNodeId), AutogradError> {
        self.tensor_linalg_eigh(input)
    }

    /// Alias for `tensor_linalg_eigvalsh`. Equivalent to `torch.eigvalsh`.
    pub fn tensor_eigvalsh(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        self.tensor_linalg_eigvalsh(input)
    }

    /// Compute eigendecomposition of a general (non-symmetric) square matrix.
    ///
    /// Equivalent to `torch.linalg.eig`. Returns `(eigenvalues, eigenvectors)` where:
    /// - eigenvalues: Complex tensor of shape (n, 2) with (real, imag) pairs
    /// - eigenvectors: Real tensor of shape (n, n) with right eigenvectors as columns
    ///
    /// Note: For matrices with complex eigenvalues, eigenvalues are returned as
    /// complex conjugate pairs.
    pub fn tensor_linalg_eig(
        &mut self,
        input: TensorNodeId,
    ) -> Result<(TensorNodeId, TensorNodeId), AutogradError> {
        // f32/half: compute in f64 then cast both outputs back (the geev core is f64-only; this also
        // routes batched f32 through the fast f64 batched path). torch keeps the input dtype.
        let dt = self.tensor_dtype(input)?;
        if dt != DType::F64 {
            let in64 = self.tensor_to_dtype(input, DType::F64)?;
            let (ev, vc) = self.tensor_linalg_eig(in64)?;
            return Ok((self.tensor_to_dtype(ev, dt)?, self.tensor_to_dtype(vc, dt)?));
        }
        let requires_grad = self.tensor_requires_grad(input)? && self.tensor_tape.is_grad_enabled();
        if requires_grad {
            let input_meta = self.tensor_tape.tensor_meta(input)?.clone();
            let shape = input_meta.shape();
            let nd = shape.len();
            if nd >= 3
                && shape[nd - 1] == shape[nd - 2]
                && input_meta.dtype() == DType::F64
                && input_meta.is_contiguous()
            {
                let device = input_meta.device();
                let k = shape[nd - 1];
                let bb: usize = shape[..nd - 2].iter().product();
                let mut eval_shape = shape[..nd - 2].to_vec();
                eval_shape.push(k);
                eval_shape.push(2);
                let mut evec_shape = shape[..nd - 2].to_vec();
                evec_shape.push(k);
                evec_shape.push(k);

                let evals = self.tensor_apply_function(
                    &[input],
                    {
                        let eval_shape = eval_shape.clone();
                        let evec_shape = evec_shape.clone();
                        move |ctx, inputs| {
                            let (values, in_shape) = inputs[0];
                            let meta =
                                TensorMeta::from_shape(in_shape.to_vec(), DType::F64, device);
                            let (evals, mut evecs) =
                                ft_kernel_cpu::eig_batched_contiguous_f64(values, &meta).map_err(
                                    |e| {
                                        AutogradError::Dispatch(
                                            ft_dispatch::DispatchError::Kernel(e),
                                        )
                                    },
                                )?;
                            Self::eig_normalize_encoded_eigenvectors(&mut evecs, &evals, k);
                            ctx.save_for_backward(evecs, evec_shape.clone());
                            ctx.save_for_backward(evals.clone(), eval_shape.clone());
                            Ok((evals, eval_shape.clone()))
                        }
                    },
                    move |ctx, grad_outputs| {
                        let saved = ctx.saved_tensors();
                        let vr = &saved[0];
                        let evals = &saved[1];
                        let grad_l = grad_outputs[0];
                        Self::eig_backward_batched_f64(
                            Some(grad_l),
                            None,
                            vr,
                            evals,
                            bb,
                            k,
                            "batched eig eigenvalue backward: eigenvector matrix singular (repeated/defective eigenvalues)",
                        )
                        .map(|grad_a| vec![Some(grad_a)])
                    },
                )?;
                let evecs = self.tensor_apply_function(
                    &[input],
                    {
                        let evec_shape = evec_shape.clone();
                        let eval_shape = eval_shape.clone();
                        move |ctx, inputs| {
                            let (values, in_shape) = inputs[0];
                            let meta =
                                TensorMeta::from_shape(in_shape.to_vec(), DType::F64, device);
                            let (evals, mut evecs) =
                                ft_kernel_cpu::eig_batched_contiguous_f64(values, &meta).map_err(
                                    |e| {
                                        AutogradError::Dispatch(
                                            ft_dispatch::DispatchError::Kernel(e),
                                        )
                                    },
                                )?;
                            Self::eig_normalize_encoded_eigenvectors(&mut evecs, &evals, k);
                            ctx.save_for_backward(evecs.clone(), evec_shape.clone());
                            ctx.save_for_backward(evals, eval_shape.clone());
                            Ok((evecs, evec_shape.clone()))
                        }
                    },
                    move |ctx, grad_outputs| {
                        let saved = ctx.saved_tensors();
                        let vr = &saved[0];
                        let evals = &saved[1];
                        let grad_v = grad_outputs[0];
                        Self::eig_backward_batched_f64(
                            None,
                            Some(grad_v),
                            vr,
                            evals,
                            bb,
                            k,
                            "batched eig eigenvector backward: eigenvector matrix singular (repeated/defective eigenvalues)",
                        )
                        .map(|grad_a| vec![Some(grad_a)])
                    },
                )?;
                self.runtime.ledger_mut().record(
                    EvidenceKind::Dispatch,
                    format!(
                        "linalg_eig input={} evals={} evecs={} (batched autograd)",
                        input.0, evals.0, evecs.0
                    ),
                );
                return Ok((evals, evecs));
            }
            if nd == 2
                && shape[0] == shape[1]
                && input_meta.dtype() == DType::F64
                && input_meta.is_contiguous()
            {
                let device = input_meta.device();
                let n = shape[0];
                let evals = self.tensor_apply_function(
                    &[input],
                    move |ctx, inputs| {
                        let (values, in_shape) = inputs[0];
                        let meta = TensorMeta::from_shape(in_shape.to_vec(), DType::F64, device);
                        let mut r = ft_kernel_cpu::eig_contiguous_f64(values, &meta).map_err(|e| {
                            AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                        })?;
                        Self::eig_normalize_encoded_eigenvectors(
                            &mut r.eigenvectors,
                            &r.eigenvalues,
                            n,
                        );
                        ctx.save_for_backward(r.eigenvectors.clone(), vec![n, n]);
                        ctx.save_for_backward(r.eigenvalues.clone(), vec![n, 2]);
                        Ok((r.eigenvalues, vec![n, 2]))
                    },
                    move |ctx, grad_outputs| {
                        let saved = ctx.saved_tensors();
                        let vr = &saved[0];
                        let evals = &saved[1];
                        Self::eig_backward_f64(
                            Some(grad_outputs[0]),
                            None,
                            vr,
                            evals,
                            n,
                            "eig eigenvalue backward: eigenvector matrix singular (repeated/defective eigenvalues)",
                        )
                        .map(|grad_a| vec![Some(grad_a)])
                    },
                )?;
                let evecs = self.tensor_apply_function(
                    &[input],
                    move |ctx, inputs| {
                        let (values, in_shape) = inputs[0];
                        let meta = TensorMeta::from_shape(in_shape.to_vec(), DType::F64, device);
                        let mut r = ft_kernel_cpu::eig_contiguous_f64(values, &meta).map_err(|e| {
                            AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                        })?;
                        Self::eig_normalize_encoded_eigenvectors(
                            &mut r.eigenvectors,
                            &r.eigenvalues,
                            n,
                        );
                        ctx.save_for_backward(r.eigenvectors.clone(), vec![n, n]);
                        ctx.save_for_backward(r.eigenvalues, vec![n, 2]);
                        Ok((r.eigenvectors, vec![n, n]))
                    },
                    move |ctx, grad_outputs| {
                        let saved = ctx.saved_tensors();
                        let vr = &saved[0];
                        let evals = &saved[1];
                        Self::eig_backward_f64(
                            None,
                            Some(grad_outputs[0]),
                            vr,
                            evals,
                            n,
                            "eig eigenvector backward: eigenvector matrix singular (repeated/defective eigenvalues)",
                        )
                        .map(|grad_a| vec![Some(grad_a)])
                    },
                )?;
                self.runtime.ledger_mut().record(
                    EvidenceKind::Dispatch,
                    format!(
                        "linalg_eig input={} evals={} evecs={} (autograd)",
                        input.0, evals.0, evecs.0
                    ),
                );
                return Ok((evals, evecs));
            }
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "linalg_eig: autograd only supported for contiguous square F64 matrices",
                },
            )));
        }
        // Batched no-grad f64 fast path: parallelize the verified 2-D geev eig over the batch
        // (vs PyTorch's per-plane LAPACK geev loop, 223-753ms small k). frankentorch-batched-eigh.
        {
            let bshape = self.tensor_shape(input)?;
            let nd = bshape.len();
            if nd >= 3
                && bshape[nd - 1] == bshape[nd - 2]
                && self.tensor_dtype(input)? == DType::F64
                && self.tensor_tape.tensor(input)?.meta().is_contiguous()
            {
                let k = bshape[nd - 1];
                let meta = self.tensor_tape.tensor_meta(input)?.clone();
                let (ev, mut vc) = {
                    let v = self.tensor_tape.tensor(input)?.contiguous_values()?;
                    ft_kernel_cpu::eig_batched_contiguous_f64(v, &meta).map_err(|e| {
                        AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                    })?
                };
                Self::eig_normalize_encoded_eigenvectors(&mut vc, &ev, k);
                let mut eval_shape = bshape[..nd - 2].to_vec();
                eval_shape.push(k);
                eval_shape.push(2);
                let mut evec_shape = bshape[..nd - 2].to_vec();
                evec_shape.push(k);
                evec_shape.push(k);
                let evals = self.tensor_variable(ev, eval_shape, false)?;
                let evecs = self.tensor_variable(vc, evec_shape, false)?;
                return Ok((evals, evecs));
            }
        }
        let (values, meta) = self.tensor_values_meta(input)?;
        let mut result = ft_kernel_cpu::eig_contiguous_f64(&values, &meta)
            .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?;
        let n = result.n;
        Self::eig_normalize_encoded_eigenvectors(&mut result.eigenvectors, &result.eigenvalues, n);
        // Eigenvalues as (n, 2) tensor with (real, imag) pairs
        let evals = self.tensor_variable(result.eigenvalues, vec![n, 2], false)?;
        let evecs = self.tensor_variable(result.eigenvectors, vec![n, n], false)?;
        Ok((evals, evecs))
    }

    /// Compute eigenvalues of a general (non-symmetric) square matrix.
    ///
    /// Equivalent to `torch.linalg.eigvals`. Returns complex eigenvalues as
    /// a tensor of shape (n, 2) with (real, imag) pairs for each eigenvalue.
    pub fn tensor_linalg_eigvals(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // f32/half: compute in f64 then cast back (the geev core is f64-only; this also routes batched
        // f32 through the fast f64 batched path). torch keeps the input dtype. frankentorch-batched-eigh.
        let dt = self.tensor_dtype(input)?;
        if dt != DType::F64 {
            let in64 = self.tensor_to_dtype(input, DType::F64)?;
            let out64 = self.tensor_linalg_eigvals(in64)?;
            return self.tensor_to_dtype(out64, dt);
        }
        let requires_grad = self.tensor_requires_grad(input)? && self.tensor_tape.is_grad_enabled();
        if !requires_grad {
            // Batched no-grad f64 fast path: parallelize the verified 2-D geev eigvals over the batch
            // (~12-14x vs PyTorch's per-plane LAPACK geev loop). frankentorch-batched-eigh.
            let bshape = self.tensor_shape(input)?;
            let nd = bshape.len();
            if nd >= 3
                && bshape[nd - 1] == bshape[nd - 2]
                && self.tensor_dtype(input)? == DType::F64
                && self.tensor_tape.tensor(input)?.meta().is_contiguous()
            {
                let k = bshape[nd - 1];
                let meta = self.tensor_tape.tensor_meta(input)?.clone();
                let out = {
                    let v = self.tensor_tape.tensor(input)?.contiguous_values()?;
                    ft_kernel_cpu::eigvals_batched_contiguous_f64(v, &meta).map_err(|e| {
                        AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                    })?
                };
                let mut out_shape = bshape[..nd - 2].to_vec();
                out_shape.push(k);
                out_shape.push(2);
                return self.tensor_variable(out, out_shape, false);
            }
            let (values, meta) = self.tensor_values_meta(input)?;
            let n = meta.shape()[0];
            let evals = ft_kernel_cpu::eigvals_contiguous_f64(&values, &meta)
                .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?;
            // Return as (n, 2) tensor with (real, imag) pairs.
            return self.tensor_variable(evals, vec![n, 2], false);
        }
        // Batched f64 grad path (nd>=3): eig-with-vectors forward parallel over the
        // batch (eig_batched), complex eigenvalue VJP per plane parallel in backward,
        // vs PyTorch's serial per-plane geev + backward loop. Single output (values),
        // so only 1x forward. frankentorch batched-eigvals-grad.
        {
            let bshape = self.tensor_shape(input)?;
            let nd = bshape.len();
            if nd >= 3
                && bshape[nd - 1] == bshape[nd - 2]
                && self.tensor_tape.tensor(input)?.meta().is_contiguous()
            {
                let device = self.tensor_tape.tensor_meta(input)?.device();
                let k = bshape[nd - 1];
                let bb: usize = bshape[..nd - 2].iter().product();
                let mut out_shape = bshape[..nd - 2].to_vec();
                out_shape.push(k);
                out_shape.push(2);
                let mut evec_shape = bshape[..nd - 2].to_vec();
                evec_shape.push(k);
                evec_shape.push(k);
                return self.tensor_apply_function(
                    &[input],
                    {
                        let out_shape = out_shape.clone();
                        let evec_shape = evec_shape.clone();
                        move |ctx, inputs| {
                            let (vals, in_shape) = inputs[0];
                            let meta = TensorMeta::from_shape(in_shape.to_vec(), DType::F64, device);
                            let (evals, evecs) =
                                ft_kernel_cpu::eig_batched_contiguous_f64(vals, &meta).map_err(
                                    |e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)),
                                )?;
                            ctx.save_for_backward(evecs, evec_shape.clone());
                            ctx.save_for_backward(evals.clone(), out_shape.clone());
                            Ok((evals, out_shape.clone()))
                        }
                    },
                    move |ctx, grad_outputs| {
                        use rayon::prelude::*;
                        let g = grad_outputs[0]; // [bb*2k]
                        let saved = ctx.saved_tensors();
                        let vr = &saved[0]; // [bb*k*k] right eigenvectors (dgeev real layout)
                        let evals = &saved[1]; // [bb*2k]
                        let plane_v = k * k;
                        let plane_e = 2 * k;
                        let mut grad_a = vec![0.0_f64; bb * plane_v];
                        let singular = std::sync::atomic::AtomicBool::new(false);
                        grad_a
                            .par_chunks_mut(plane_v)
                            .enumerate()
                            .for_each(|(b, o)| {
                                let vrp = &vr[b * plane_v..(b + 1) * plane_v];
                                let evp = &evals[b * plane_e..(b + 1) * plane_e];
                                let gp = &g[b * plane_e..(b + 1) * plane_e];
                                let v = Self::eig_reconstruct_complex_v(vrp, evp, k);
                                match Self::complex_mat_inverse(&v, k) {
                                    Some(minv) => {
                                        for i in 0..k {
                                            for j in 0..k {
                                                let mut acc = ft_core::Complex128::new(0.0, 0.0);
                                                for kk in 0..k {
                                                    let gl = ft_core::Complex128::new(
                                                        gp[2 * kk],
                                                        gp[2 * kk + 1],
                                                    );
                                                    acc += minv[kk * k + i].conj()
                                                        * gl
                                                        * v[j * k + kk].conj();
                                                }
                                                o[i * k + j] = acc.re;
                                            }
                                        }
                                    }
                                    None => singular
                                        .store(true, std::sync::atomic::Ordering::Relaxed),
                                }
                            });
                        if singular.load(std::sync::atomic::Ordering::Relaxed) {
                            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                                ft_dispatch::DispatchKeyError::IncompatibleSet {
                                    reason: "batched eigvals backward: eigenvector matrix singular (repeated/defective eigenvalues)",
                                },
                            )));
                        }
                        Ok(vec![Some(grad_a)])
                    },
                );
            }
        }
        // Autograd (frankentorch-ng1hw): eigenvalues of a general matrix. The output
        // is a real (n, 2) tensor of (re, im) pairs. With A = V·Λ·V⁻¹ (V right
        // eigenvectors), the eigenvalue VJP is
        //   grad_A = Re( V⁻ᴴ · diag(grad_λ) · Vᴴ )
        // i.e. grad_A[i][j] = Re( Σ_k conj(V⁻¹[k][i]) · grad_λ[k] · conj(V[j][k]) ).
        // The grad path uses eig (with eigenvectors); requires distinct eigenvalues
        // (defective/repeated spectra are non-differentiable, as in torch).
        let n = self.tensor_shape(input)?[0];
        self.tensor_apply_function(
            &[input],
            move |ctx, inputs| {
                let (vals, shape) = inputs[0];
                let meta = TensorMeta::from_shape(shape.to_vec(), DType::F64, Device::Cpu);
                let res = ft_kernel_cpu::eig_contiguous_f64(vals, &meta)
                    .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?;
                ctx.save_for_backward(res.eigenvectors.clone(), vec![n, n]);
                ctx.save_for_backward(res.eigenvalues.clone(), vec![n, 2]);
                Ok((res.eigenvalues, vec![n, 2]))
            },
            move |ctx, grad_outputs| {
                let g = grad_outputs[0]; // 2n: [gre0, gim0, gre1, gim1, ...]
                let saved = ctx.saved_tensors();
                let vr = &saved[0]; // n*n right eigenvectors in dgeev real layout
                let evals = &saved[1]; // 2n eigenvalues
                let v = Self::eig_reconstruct_complex_v(vr, evals, n);
                let minv = Self::complex_mat_inverse(&v, n).ok_or_else(|| {
                    AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "eigvals backward: eigenvector matrix singular (repeated/defective eigenvalues)",
                        },
                    ))
                })?;
                let mut grad_a = vec![0.0_f64; n * n];
                for i in 0..n {
                    for j in 0..n {
                        let mut acc = ft_core::Complex128::new(0.0, 0.0);
                        for k in 0..n {
                            let gl = ft_core::Complex128::new(g[2 * k], g[2 * k + 1]);
                            acc += minv[k * n + i].conj() * gl * v[j * n + k].conj();
                        }
                        grad_a[i * n + j] = acc.re;
                    }
                }
                Ok(vec![Some(grad_a)])
            },
        )
    }

    fn eig_backward_err(reason: &'static str) -> AutogradError {
        AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
            ft_dispatch::DispatchKeyError::IncompatibleSet { reason },
        ))
    }

    fn eig_backward_batched_f64(
        grad_l: Option<&[f64]>,
        grad_v: Option<&[f64]>,
        vr: &[f64],
        evals: &[f64],
        batch: usize,
        n: usize,
        reason: &'static str,
    ) -> Result<Vec<f64>, AutogradError> {
        use rayon::prelude::*;

        if batch == 0 || n == 0 {
            return Ok(Vec::new());
        }
        let plane_v = n * n;
        let plane_e = 2 * n;
        if vr.len() != batch * plane_v || evals.len() != batch * plane_e {
            return Err(Self::eig_backward_err(
                "eig backward: saved tensor shape mismatch",
            ));
        }
        if let Some(g) = grad_l {
            if g.len() != batch * plane_e {
                return Err(Self::eig_backward_err(
                    "eig backward: eigenvalue grad shape mismatch",
                ));
            }
        }
        if let Some(g) = grad_v {
            if g.len() != batch * plane_v {
                return Err(Self::eig_backward_err(
                    "eig backward: eigenvector grad shape mismatch",
                ));
            }
        }

        let failed = std::sync::atomic::AtomicBool::new(false);
        let mut out = vec![0.0_f64; batch * plane_v];
        out.par_chunks_mut(plane_v)
            .enumerate()
            .for_each(|(b, dst)| {
                let gl = grad_l.map(|g| &g[b * plane_e..(b + 1) * plane_e]);
                let gv = grad_v.map(|g| &g[b * plane_v..(b + 1) * plane_v]);
                let ev = &evals[b * plane_e..(b + 1) * plane_e];
                let vecs = &vr[b * plane_v..(b + 1) * plane_v];
                match Self::eig_backward_f64(gl, gv, vecs, ev, n, reason) {
                    Ok(grad_a) => dst.copy_from_slice(&grad_a),
                    Err(_) => failed.store(true, std::sync::atomic::Ordering::Relaxed),
                }
            });
        if failed.load(std::sync::atomic::Ordering::Relaxed) {
            return Err(Self::eig_backward_err(reason));
        }
        Ok(out)
    }

    fn eig_backward_f64(
        grad_l: Option<&[f64]>,
        grad_v: Option<&[f64]>,
        vr: &[f64],
        evals: &[f64],
        n: usize,
        reason: &'static str,
    ) -> Result<Vec<f64>, AutogradError> {
        if vr.len() != n * n || evals.len() != 2 * n {
            return Err(Self::eig_backward_err(
                "eig backward: saved tensor shape mismatch",
            ));
        }
        if let Some(g) = grad_l {
            if g.len() != 2 * n {
                return Err(Self::eig_backward_err(
                    "eig backward: eigenvalue grad shape mismatch",
                ));
            }
        }
        if let Some(g) = grad_v {
            if g.len() != n * n {
                return Err(Self::eig_backward_err(
                    "eig backward: eigenvector grad shape mismatch",
                ));
            }
        }
        if grad_l.is_none() && grad_v.is_none() {
            return Ok(vec![0.0; n * n]);
        }

        let zero = ft_core::Complex128::new(0.0, 0.0);
        let v = Self::eig_reconstruct_complex_v(vr, evals, n);
        let minv =
            Self::complex_mat_inverse(&v, n).ok_or_else(|| Self::eig_backward_err(reason))?;
        let mut middle = vec![zero; n * n];

        if let Some(grad_v_real) = grad_v {
            let gv = Self::eig_encoded_grad_to_complex(grad_v_real, evals, n);
            let mut vhgv = vec![zero; n * n];
            let mut gram = vec![zero; n * n];
            for i in 0..n {
                for j in 0..n {
                    let mut a = zero;
                    let mut b = zero;
                    for r in 0..n {
                        a += v[r * n + i].conj() * gv[r * n + j];
                        b += v[r * n + i].conj() * v[r * n + j];
                    }
                    vhgv[i * n + j] = a;
                    gram[i * n + j] = b;
                }
            }

            let has_complex_eigenvectors = (0..n).any(|i| evals[2 * i + 1] != 0.0);
            if has_complex_eigenvectors {
                for i in 0..n {
                    if vhgv[i * n + i].im.abs() > 1e-2 {
                        return Err(Self::eig_backward_err(
                            "linalg_eig_backward: eigenvector-dependent loss is phase-dependent",
                        ));
                    }
                }
            }

            for i in 0..n {
                for j in 0..n {
                    let diag = ft_core::Complex128::new(vhgv[j * n + j].re, 0.0);
                    let mut val = vhgv[i * n + j] - gram[i * n + j] * diag;
                    if i != j {
                        let li = ft_core::Complex128::new(evals[2 * i], evals[2 * i + 1]);
                        let lj = ft_core::Complex128::new(evals[2 * j], evals[2 * j + 1]);
                        let denom = (lj - li).conj();
                        if denom.norm_sqr() == 0.0 {
                            return Err(Self::eig_backward_err(reason));
                        }
                        val /= denom;
                    }
                    middle[i * n + j] = val;
                }
            }
        }

        if let Some(gl) = grad_l {
            for i in 0..n {
                middle[i * n + i] = ft_core::Complex128::new(gl[2 * i], gl[2 * i + 1]);
            }
        }

        let mut rhs = vec![zero; n * n];
        for i in 0..n {
            for j in 0..n {
                let mut acc = zero;
                for k in 0..n {
                    acc += middle[i * n + k] * v[j * n + k].conj();
                }
                rhs[i * n + j] = acc;
            }
        }

        let mut grad_a = vec![0.0_f64; n * n];
        for i in 0..n {
            for j in 0..n {
                let mut acc = zero;
                for k in 0..n {
                    acc += minv[k * n + i].conj() * rhs[k * n + j];
                }
                grad_a[i * n + j] = acc.re;
            }
        }
        Ok(grad_a)
    }

    fn eig_encoded_grad_to_complex(
        grad_v: &[f64],
        evals: &[f64],
        n: usize,
    ) -> Vec<ft_core::Complex128> {
        let mut gv = vec![ft_core::Complex128::new(0.0, 0.0); n * n];
        let mut c = 0;
        while c < n {
            if evals[2 * c + 1] != 0.0 && c + 1 < n {
                for r in 0..n {
                    let gr = grad_v[r * n + c];
                    let gi = grad_v[r * n + c + 1];
                    gv[r * n + c] = ft_core::Complex128::new(0.5 * gr, 0.5 * gi);
                    gv[r * n + c + 1] = ft_core::Complex128::new(0.5 * gr, -0.5 * gi);
                }
                c += 2;
            } else {
                for r in 0..n {
                    gv[r * n + c] = ft_core::Complex128::new(grad_v[r * n + c], 0.0);
                }
                c += 1;
            }
        }
        gv
    }

    fn eig_normalize_encoded_eigenvectors(vr: &mut [f64], evals: &[f64], n: usize) {
        if n == 0 {
            return;
        }
        let plane = n * n;
        let val_plane = 2 * n;
        if vr.len() % plane != 0 || evals.len() != (vr.len() / plane) * val_plane {
            return;
        }
        for b in 0..(vr.len() / plane) {
            let vecs = &mut vr[b * plane..(b + 1) * plane];
            let vals = &evals[b * val_plane..(b + 1) * val_plane];
            let mut c = 0;
            while c < n {
                if vals[2 * c + 1] != 0.0 && c + 1 < n {
                    let mut norm_sq = 0.0;
                    for r in 0..n {
                        let re = vecs[r * n + c];
                        let im = vecs[r * n + c + 1];
                        norm_sq += re * re + im * im;
                    }
                    if norm_sq > 0.0 {
                        let inv_norm = norm_sq.sqrt().recip();
                        for r in 0..n {
                            vecs[r * n + c] *= inv_norm;
                            vecs[r * n + c + 1] *= inv_norm;
                        }
                    }
                    c += 2;
                } else {
                    let mut norm_sq = 0.0;
                    for r in 0..n {
                        let value = vecs[r * n + c];
                        norm_sq += value * value;
                    }
                    if norm_sq > 0.0 {
                        let inv_norm = norm_sq.sqrt().recip();
                        for r in 0..n {
                            vecs[r * n + c] *= inv_norm;
                        }
                    }
                    c += 1;
                }
            }
        }
    }

    /// Reconstruct the complex right-eigenvector matrix V (row-major n×n, columns are
    /// eigenvectors) from the dgeev real storage: a real eigenvalue's column is the
    /// real eigenvector; a complex-conjugate pair (columns c, c+1) holds the real and
    /// imaginary parts, so v_c = VR[:,c] + i·VR[:,c+1] and v_{c+1} = conj(v_c).
    fn eig_reconstruct_complex_v(vr: &[f64], evals: &[f64], n: usize) -> Vec<ft_core::Complex128> {
        let mut v = vec![ft_core::Complex128::new(0.0, 0.0); n * n];
        let mut c = 0;
        while c < n {
            if evals[2 * c + 1] != 0.0 && c + 1 < n {
                for r in 0..n {
                    let re = vr[r * n + c];
                    let im = vr[r * n + c + 1];
                    v[r * n + c] = ft_core::Complex128::new(re, im);
                    v[r * n + c + 1] = ft_core::Complex128::new(re, -im);
                }
                c += 2;
            } else {
                for r in 0..n {
                    v[r * n + c] = ft_core::Complex128::new(vr[r * n + c], 0.0);
                }
                c += 1;
            }
        }
        v
    }

    /// Complex matrix inverse via Gauss-Jordan elimination with partial pivoting
    /// (row-major n×n). Returns `None` if the matrix is singular.
    fn complex_mat_inverse(
        a: &[ft_core::Complex128],
        n: usize,
    ) -> Option<Vec<ft_core::Complex128>> {
        let zero = ft_core::Complex128::new(0.0, 0.0);
        let one = ft_core::Complex128::new(1.0, 0.0);
        let mut m = a.to_vec();
        let mut inv = vec![zero; n * n];
        for i in 0..n {
            inv[i * n + i] = one;
        }
        for col in 0..n {
            let mut piv = col;
            let mut best = m[col * n + col].norm_sqr();
            for r in (col + 1)..n {
                let v = m[r * n + col].norm_sqr();
                if v > best {
                    best = v;
                    piv = r;
                }
            }
            if best == 0.0 {
                return None;
            }
            if piv != col {
                for k in 0..n {
                    m.swap(piv * n + k, col * n + k);
                    inv.swap(piv * n + k, col * n + k);
                }
            }
            let d = m[col * n + col];
            for k in 0..n {
                m[col * n + k] /= d;
                inv[col * n + k] /= d;
            }
            for r in 0..n {
                if r == col {
                    continue;
                }
                let f = m[r * n + col];
                if f != zero {
                    for k in 0..n {
                        m[r * n + k] = m[r * n + k] - f * m[col * n + k];
                        inv[r * n + k] = inv[r * n + k] - f * inv[col * n + k];
                    }
                }
            }
        }
        Some(inv)
    }

    /// Alias for `tensor_linalg_eig`. Equivalent to deprecated `torch.eig`.
    pub fn tensor_eig(
        &mut self,
        input: TensorNodeId,
    ) -> Result<(TensorNodeId, TensorNodeId), AutogradError> {
        self.tensor_linalg_eig(input)
    }

    /// Compute the SVD: A = U @ diag(S) @ Vh.
    ///
    /// If `full_matrices` is true, U is (m x m) and Vh is (n x n).
    /// If false (reduced), U is (m x k) and Vh is (k x n) where k = min(m,n).
    /// S is always a 1D tensor of singular values sorted descending.
    pub fn tensor_linalg_svd(
        &mut self,
        input: TensorNodeId,
        full_matrices: bool,
    ) -> Result<(TensorNodeId, TensorNodeId, TensorNodeId), AutogradError> {
        // f32/half: compute in f64 then cast U/S/Vh back (the SVD core is
        // f64-only). torch keeps the input dtype on every output. frankentorch-clqek.
        let dt = self.tensor_dtype(input)?;
        if dt != DType::F64 {
            let in64 = self.tensor_to_dtype(input, DType::F64)?;
            let (u, sv, vh) = self.tensor_linalg_svd(in64, full_matrices)?;
            return Ok((
                self.tensor_to_dtype(u, dt)?,
                self.tensor_to_dtype(sv, dt)?,
                self.tensor_to_dtype(vh, dt)?,
            ));
        }
        // Batched no-grad f64 fast path: parallelize the verified 2-D SVD over the batch (~9-16x vs
        // PyTorch's per-plane LAPACK gesdd loop; the 189x scalar penalty is large-matrix-only).
        // frankentorch-batched-eigh.
        if !self.tensor_requires_grad(input)? {
            let bshape = self.tensor_shape(input)?;
            let nd = bshape.len();
            if nd >= 3 && self.tensor_tape.tensor(input)?.meta().is_contiguous() {
                let m = bshape[nd - 2];
                let n = bshape[nd - 1];
                let kk = m.min(n);
                let (urows, ucols, vrows, vcols) = if full_matrices {
                    (m, m, n, n)
                } else {
                    (m, kk, kk, n)
                };
                let meta = self.tensor_tape.tensor_meta(input)?.clone();
                let (u, s, vh) = {
                    let v = self.tensor_tape.tensor(input)?.contiguous_values()?;
                    ft_kernel_cpu::svd_batched_contiguous_f64(v, &meta, full_matrices).map_err(
                        |e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)),
                    )?
                };
                let lead = bshape[..nd - 2].to_vec();
                let mut ushape = lead.clone();
                ushape.push(urows);
                ushape.push(ucols);
                let mut sshape = lead.clone();
                sshape.push(kk);
                let mut vshape = lead;
                vshape.push(vrows);
                vshape.push(vcols);
                let u_node = self.tensor_variable(u, ushape, false)?;
                let s_node = self.tensor_variable(s, sshape, false)?;
                let vh_node = self.tensor_variable(vh, vshape, false)?;
                return Ok((u_node, s_node, vh_node));
            }
        }
        // full_matrices=true for a SQUARE matrix (m=n): the full and reduced SVD are IDENTICAL
        // (U,S,Vh all n×n), so route to the shipped reduced grad path (torch.linalg.svd defaults to
        // full_matrices=True, so this covers the default call). torch's full square svd grad is slow
        // (looped gesdd). frankentorch batched-svd-grad-fullsquare.
        if full_matrices && self.tensor_requires_grad(input)? {
            let bshape = self.tensor_shape(input)?;
            let nd = bshape.len();
            if nd >= 2
                && bshape[nd - 1] == bshape[nd - 2]
                && self.tensor_dtype(input)? == DType::F64
            {
                return self.tensor_linalg_svd(input, false);
            }
        }
        // Batched f64 grad path for WIDE m<n (reduced): compose via Aᵀ — svd(A)=(Vhᵀ,S,Uᵀ) from
        // the tall svd of Aᵀ (which has the batched grad below). transpose+svd+transpose are all
        // grad-aware. torch's wide svd backward is very slow (looped gesdd, ~500-1220ms). frankentorch
        // batched-svd-grad-wide.
        if self.tensor_requires_grad(input)? && !full_matrices {
            let bshape = self.tensor_shape(input)?;
            let nd = bshape.len();
            if nd >= 3
                && bshape[nd - 2] < bshape[nd - 1]
                && self.tensor_dtype(input)? == DType::F64
                && self.tensor_tape.tensor(input)?.meta().is_contiguous()
            {
                let at = self.tensor_matrix_transpose(input)?; // [.., n, m] tall
                let (up, sp, vhp) = self.tensor_linalg_svd(at, false)?;
                let u = self.tensor_matrix_transpose(vhp)?; // U of A = Vhpᵀ
                let vh = self.tensor_matrix_transpose(up)?; // Vh of A = Upᵀ
                return Ok((u, sp, vh));
            }
        }
        // Batched f64 grad path (nd>=3, reduced, tall/square m>=n): parallelize the
        // per-plane SVD + per-plane VJP over the batch, vs PyTorch's serial per-plane
        // gesdd + backward loop. Three independent nodes (U,S,Vh) sum grad_A; each
        // plane's VJP is bit-identical to the 2-D call. TOLERANCE-parity. frankentorch
        // batched-svd-grad.
        if self.tensor_requires_grad(input)? && !full_matrices {
            let bshape = self.tensor_shape(input)?;
            let nd = bshape.len();
            if nd >= 3
                && bshape[nd - 2] >= bshape[nd - 1]
                && self.tensor_dtype(input)? == DType::F64
                && self.tensor_tape.tensor(input)?.meta().is_contiguous()
            {
                let device = self.tensor_tape.tensor_meta(input)?.device();
                let lead: Vec<usize> = bshape[..nd - 2].to_vec();
                let m = bshape[nd - 2];
                let n = bshape[nd - 1];
                let k = m.min(n);
                let bb: usize = lead.iter().product();
                let mut ushape = lead.clone();
                ushape.push(m);
                ushape.push(k);
                let mut sshape = lead.clone();
                sshape.push(k);
                let mut vshape = lead.clone();
                vshape.push(k);
                vshape.push(n);
                // Forward factory: batched reduced SVD, save (U,S,Vh) flat, return `output`.
                let svd_forward = move |output: u8,
                                        ush: Vec<usize>,
                                        ssh: Vec<usize>,
                                        vsh: Vec<usize>| {
                    move |ctx: &mut FunctionCtx, inputs: &[(&[f64], &[usize])]| {
                        let (values, in_shape) = inputs[0];
                        let meta = TensorMeta::from_shape(in_shape.to_vec(), DType::F64, device);
                        let (u, s, vh) =
                            ft_kernel_cpu::svd_batched_contiguous_f64(values, &meta, false)
                                .map_err(|e| {
                                    AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                                })?;
                        ctx.save_for_backward(u.clone(), ush.clone());
                        ctx.save_for_backward(s.clone(), ssh.clone());
                        ctx.save_for_backward(vh.clone(), vsh.clone());
                        match output {
                            0 => Ok((u, ush.clone())),
                            1 => Ok((s, ssh.clone())),
                            _ => Ok((vh, vsh.clone())),
                        }
                    }
                };
                let u_node = self.tensor_apply_function(
                    &[input],
                    svd_forward(0, ushape.clone(), sshape.clone(), vshape.clone()),
                    move |ctx, grad_outputs| {
                        let saved = ctx.saved_tensors();
                        let (u, s, vh) = (&saved[0], &saved[1], &saved[2]);
                        let gu = grad_outputs[0];
                        let zs = vec![0.0_f64; bb * k];
                        let zv = vec![0.0_f64; bb * n * k];
                        let grad_a = ft_kernel_cpu::svd_backward_tall_batched_contiguous_f64(
                            u, s, vh, gu, &zs, &zv, bb, m, n, k,
                        );
                        Ok(vec![Some(grad_a)])
                    },
                )?;
                let s_node = self.tensor_apply_function(
                    &[input],
                    svd_forward(1, ushape.clone(), sshape.clone(), vshape.clone()),
                    move |ctx, grad_outputs| {
                        let saved = ctx.saved_tensors();
                        let (u, s, vh) = (&saved[0], &saved[1], &saved[2]);
                        let gs = grad_outputs[0];
                        let zu = vec![0.0_f64; bb * m * k];
                        let zv = vec![0.0_f64; bb * n * k];
                        let grad_a = ft_kernel_cpu::svd_backward_tall_batched_contiguous_f64(
                            u, s, vh, &zu, gs, &zv, bb, m, n, k,
                        );
                        Ok(vec![Some(grad_a)])
                    },
                )?;
                let vh_node = self.tensor_apply_function(
                    &[input],
                    svd_forward(2, ushape, sshape, vshape),
                    move |ctx, grad_outputs| {
                        let saved = ctx.saved_tensors();
                        let (u, s, vh) = (&saved[0], &saved[1], &saved[2]);
                        let gvh = grad_outputs[0]; // [bb*k*n]
                        // Convert grad wrt Vh (k×n) to the V basis (n×k) per plane.
                        let mut gv = vec![0.0_f64; bb * n * k];
                        for b in 0..bb {
                            let vh_off = b * k * n;
                            let gv_off = b * n * k;
                            for j in 0..k {
                                for p in 0..n {
                                    gv[gv_off + p * k + j] = gvh[vh_off + j * n + p];
                                }
                            }
                        }
                        let zu = vec![0.0_f64; bb * m * k];
                        let zs = vec![0.0_f64; bb * k];
                        let grad_a = ft_kernel_cpu::svd_backward_tall_batched_contiguous_f64(
                            u, s, vh, &zu, &zs, &gv, bb, m, n, k,
                        );
                        Ok(vec![Some(grad_a)])
                    },
                )?;
                return Ok((u_node, s_node, vh_node));
            }
        }
        if self.tensor_requires_grad(input)? {
            // SVD backward via the three-independent-nodes pattern (like eigh/qr):
            // U, S, Vh are independent functions of A, so the chain rule sums
            // their grad_A contributions. Each node recomputes the deterministic
            // reduced SVD (bit-identical outputs) and calls svd_backward_tall with
            // the other two output gradients zeroed. Supported for the standard
            // differentiable case: reduced SVD, tall/square input (m >= n, so
            // V is square — no V_perp term), distinct positive singular values.
            // frankentorch-rl4g.
            let input_meta = self.tensor_tape.tensor_meta(input)?.clone();
            let shape = input_meta.shape();
            if !full_matrices
                && shape.len() == 2
                && shape[0] >= shape[1]
                && input_meta.dtype() == DType::F64
            {
                let device = input_meta.device();
                // Each forward saves (U, S, Vh); backward derives k=S.len(),
                // m=U.len()/k, n=Vh.len()/k.
                let svd_forward = move |output: u8| {
                    move |ctx: &mut FunctionCtx, inputs: &[(&[f64], &[usize])]| {
                        let (values, in_shape) = inputs[0];
                        let meta = TensorMeta::from_shape(in_shape.to_vec(), DType::F64, device);
                        let r = ft_kernel_cpu::svd_contiguous_f64(values, &meta, false).map_err(
                            |e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)),
                        )?;
                        let (mm, nn, kk) = (r.m, r.n, r.k);
                        ctx.save_for_backward(r.u.clone(), vec![mm, kk]);
                        ctx.save_for_backward(r.s.clone(), vec![kk]);
                        ctx.save_for_backward(r.vh.clone(), vec![kk, nn]);
                        match output {
                            0 => Ok((r.u, vec![mm, kk])),
                            1 => Ok((r.s, vec![kk])),
                            _ => Ok((r.vh, vec![kk, nn])),
                        }
                    }
                };
                let u_node = self.tensor_apply_function(
                    &[input],
                    svd_forward(0),
                    move |ctx, grad_outputs| {
                        let saved = ctx.saved_tensors();
                        let (u, s, vh) = (&saved[0], &saved[1], &saved[2]);
                        let k = s.len();
                        let m = u.len() / k;
                        let n = vh.len() / k;
                        let gu = grad_outputs[0];
                        let zs = vec![0.0_f64; k];
                        let zv = vec![0.0_f64; n * k];
                        let grad_a = Self::svd_backward_tall(u, s, vh, gu, &zs, &zv, m, n, k);
                        Ok(vec![Some(grad_a)])
                    },
                )?;
                let s_node = self.tensor_apply_function(
                    &[input],
                    svd_forward(1),
                    move |ctx, grad_outputs| {
                        let saved = ctx.saved_tensors();
                        let (u, s, vh) = (&saved[0], &saved[1], &saved[2]);
                        let k = s.len();
                        let m = u.len() / k;
                        let n = vh.len() / k;
                        let gs = grad_outputs[0];
                        let zu = vec![0.0_f64; m * k];
                        let zv = vec![0.0_f64; n * k];
                        let grad_a = Self::svd_backward_tall(u, s, vh, &zu, gs, &zv, m, n, k);
                        Ok(vec![Some(grad_a)])
                    },
                )?;
                let vh_node = self.tensor_apply_function(
                    &[input],
                    svd_forward(2),
                    move |ctx, grad_outputs| {
                        let saved = ctx.saved_tensors();
                        let (u, s, vh) = (&saved[0], &saved[1], &saved[2]);
                        let k = s.len();
                        let m = u.len() / k;
                        let n = vh.len() / k;
                        let gvh = grad_outputs[0]; // k x n
                        // Convert grad wrt Vh to the V basis: gV[p][j] = gVh[j][p].
                        let mut gv = vec![0.0_f64; n * k];
                        for j in 0..k {
                            for p in 0..n {
                                gv[p * k + j] = gvh[j * n + p];
                            }
                        }
                        let zu = vec![0.0_f64; m * k];
                        let zs = vec![0.0_f64; k];
                        let grad_a = Self::svd_backward_tall(u, s, vh, &zu, &zs, &gv, m, n, k);
                        Ok(vec![Some(grad_a)])
                    },
                )?;
                self.runtime.ledger_mut().record(
                    EvidenceKind::Dispatch,
                    format!(
                        "linalg_svd input={} u={} s={} vh={} (autograd)",
                        input.0, u_node.0, s_node.0, vh_node.0
                    ),
                );
                return Ok((u_node, s_node, vh_node));
            }
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "linalg_svd: autograd only supported for reduced SVD of a tall/square (m>=n) F64 matrix",
                },
            )));
        }
        let (values, meta) = self.tensor_values_meta(input)?;
        let result = ft_kernel_cpu::svd_contiguous_f64(&values, &meta, full_matrices)
            .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?;
        let m = result.m;
        let n = result.n;
        let k = result.k;
        let u_cols = if full_matrices { m } else { k };
        let vh_rows = if full_matrices { n } else { k };
        let u_node = self.tensor_variable(result.u, vec![m, u_cols], false)?;
        let s_node = self.tensor_variable(result.s, vec![k], false)?;
        let vh_node = self.tensor_variable(result.vh, vec![vh_rows, n], false)?;
        Ok((u_node, s_node, vh_node))
    }

    /// Randomized truncated SVD (Halko-Martinsson-Tropp). Returns an approximate
    /// rank-`q` reduced SVD `(U, S, Vh)` with `U: [m, k]`, `S: [k]`, `Vh: [k, n]`
    /// (`k = min(q, min(m,n))`) in `O(m·n·q)` — far cheaper than the full SVD when
    /// `q << min(m, n)` (PCA / low-rank approximation). `niter` subspace power
    /// iterations improve accuracy on slowly-decaying spectra. Equivalent to
    /// `torch.svd_lowrank` (forward / no-grad); the randomized approximation is
    /// non-differentiable here, so the outputs are detached.
    pub fn tensor_svd_lowrank(
        &mut self,
        input: TensorNodeId,
        q: usize,
        niter: usize,
    ) -> Result<(TensorNodeId, TensorNodeId, TensorNodeId), AutogradError> {
        let (values, meta) = self.tensor_values_meta(input)?;
        let result = ft_kernel_cpu::svd_lowrank_contiguous_f64(&values, &meta, q, niter)
            .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?;
        let (m, n, k) = (result.m, result.n, result.k);
        let u_node = self.tensor_variable(result.u, vec![m, k], false)?;
        let s_node = self.tensor_variable(result.s, vec![k], false)?;
        let vh_node = self.tensor_variable(result.vh, vec![k, n], false)?;
        Ok((u_node, s_node, vh_node))
    }

    /// Alias for [`tensor_svd_lowrank`]. Equivalent to `torch.svd_lowrank`.
    pub fn functional_svd_lowrank(
        &mut self,
        input: TensorNodeId,
        q: usize,
        niter: usize,
    ) -> Result<(TensorNodeId, TensorNodeId, TensorNodeId), AutogradError> {
        self.tensor_svd_lowrank(input, q, niter)
    }

    /// Randomized PCA (`torch.pca_lowrank`). With `center = true` the columns are
    /// mean-centered (rows = samples, columns = features) before the randomized
    /// truncated SVD. Returns `(U[m,k], S[k], V[n,k])` — note `V`, not `Vh`,
    /// matching `torch.pca_lowrank`. O(m·n·q); forward / no-grad.
    pub fn tensor_pca_lowrank(
        &mut self,
        input: TensorNodeId,
        q: usize,
        center: bool,
        niter: usize,
    ) -> Result<(TensorNodeId, TensorNodeId, TensorNodeId), AutogradError> {
        let (values, meta) = self.tensor_values_meta(input)?;
        let result = ft_kernel_cpu::pca_lowrank_contiguous_f64(&values, &meta, q, center, niter)
            .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?;
        let (m, n, k) = (result.m, result.n, result.k);
        // torch.pca_lowrank returns V (n x k) = Vh^T.
        let mut v = vec![0.0_f64; n * k];
        for i in 0..k {
            for j in 0..n {
                v[j * k + i] = result.vh[i * n + j];
            }
        }
        let u_node = self.tensor_variable(result.u, vec![m, k], false)?;
        let s_node = self.tensor_variable(result.s, vec![k], false)?;
        let v_node = self.tensor_variable(v, vec![n, k], false)?;
        Ok((u_node, s_node, v_node))
    }

    /// Alias for [`tensor_pca_lowrank`]. Equivalent to `torch.pca_lowrank`.
    pub fn functional_pca_lowrank(
        &mut self,
        input: TensorNodeId,
        q: usize,
        center: bool,
        niter: usize,
    ) -> Result<(TensorNodeId, TensorNodeId, TensorNodeId), AutogradError> {
        self.tensor_pca_lowrank(input, q, center, niter)
    }

    /// Top-`k` (or bottom-`k` if `largest = false`) eigenpairs of a real-symmetric
    /// matrix via LOBPCG (`torch.lobpcg`). Returns `(eigenvalues[k],
    /// eigenvectors[n, k])`, with eigenvector columns, in `O(n^2 k)` per
    /// iteration -- far cheaper than the full eigh's `O(n^3)` when `k << n`.
    /// Iterative/approximate (converges to `tol` residual within `niter` steps);
    /// forward / no-grad.
    pub fn tensor_lobpcg(
        &mut self,
        input: TensorNodeId,
        k: usize,
        largest: bool,
        niter: usize,
        tol: f64,
    ) -> Result<(TensorNodeId, TensorNodeId), AutogradError> {
        let (values, meta) = self.tensor_values_meta(input)?;
        let n = meta.shape().first().copied().unwrap_or(0);
        let (evals, evecs) =
            ft_kernel_cpu::lobpcg_contiguous_f64(&values, &meta, k, largest, niter, tol)
                .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?;
        let kk = evals.len();
        let evals_node = self.tensor_variable(evals, vec![kk], false)?;
        let evecs_node = self.tensor_variable(evecs, vec![n, kk], false)?;
        Ok((evals_node, evecs_node))
    }

    /// Alias for [`tensor_lobpcg`]. Equivalent to `torch.lobpcg`.
    pub fn functional_lobpcg(
        &mut self,
        input: TensorNodeId,
        k: usize,
        largest: bool,
        niter: usize,
        tol: f64,
    ) -> Result<(TensorNodeId, TensorNodeId), AutogradError> {
        self.tensor_lobpcg(input, k, largest, niter, tol)
    }

    /// Alias for `tensor_linalg_svd`. Equivalent to deprecated `torch.svd`.
    ///
    /// Note: PyTorch's deprecated torch.svd returns (U, S, V) where V is
    /// the transpose of Vh. This alias returns the same as linalg_svd:
    /// (U, S, Vh). For the deprecated behavior, transpose the third output.
    pub fn tensor_svd(
        &mut self,
        input: TensorNodeId,
        full_matrices: bool,
    ) -> Result<(TensorNodeId, TensorNodeId, TensorNodeId), AutogradError> {
        self.tensor_linalg_svd(input, full_matrices)
    }

    /// Compute just the singular values of a matrix.
    ///
    /// Returns a 1D tensor of singular values sorted descending.
    pub fn tensor_linalg_svdvals(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // f32/half: compute in f64 then cast back (the SVD core is f64-only; this also routes batched
        // f32 through the fast f64 batched path). torch keeps the input dtype. frankentorch-batched-eigh.
        let dt = self.tensor_dtype(input)?;
        if dt == DType::F32 && !self.tensor_requires_grad(input)? {
            let shape0 = self.tensor_shape(input)?;
            let nd = shape0.len();
            if nd >= 3 && self.tensor_tape.tensor(input)?.meta().is_contiguous() {
                let mn = shape0[nd - 2].min(shape0[nd - 1]);
                let meta = self.tensor_tape.tensor_meta(input)?.clone();
                let out = {
                    let v = self.tensor_tape.tensor(input)?.contiguous_values_f32()?;
                    ft_kernel_cpu::svdvals_batched_contiguous_f32_upcast(v, &meta).map_err(|e| {
                        AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                    })?
                };
                let mut out_shape = shape0[..nd - 2].to_vec();
                out_shape.push(mn);
                return self.tensor_variable_f32(out, out_shape, false);
            }
        }
        if dt != DType::F64 {
            let in64 = self.tensor_to_dtype(input, DType::F64)?;
            let out64 = self.tensor_linalg_svdvals(in64)?;
            return self.tensor_to_dtype(out64, dt);
        }
        if self.tensor_requires_grad(input)? {
            // Singular-value backward (SVD analog of eigvalsh): with A = U Σ Vh
            // (reduced), the gradient of the l-th singular value σ_l is the rank-1
            // outer product u_l v_l^T, so
            //   grad_A = U diag(grad_σ) V^T,  grad_A[i][j] = Σ_l grad_σ_l U[i][l] Vh[l][j].
            // svdvals_contiguous_f64 simply calls svd_contiguous_f64(.., false) and
            // returns its .s, so computing the reduced SVD here yields singular
            // values bit-identical to the non-grad path (parity preserved). Valid
            // for simple (distinct, nonzero) singular values — the standard
            // svdvals-backward assumption, matching upstream. frankentorch-rl4g.
            let input_meta = self.tensor_tape.tensor_meta(input)?.clone();
            let shape = input_meta.shape();
            // Batched grad path: differentiable batched svdvals via fused forward (batched reduced SVD,
            // saving U + Vh) + fused backward kernel (grad_A = U diag(grad_σ) Vʰ per plane, parallel).
            // No per-plane tape. frankentorch-batched-eigh. (BlackThrush)
            if shape.len() >= 3 && input_meta.dtype() == DType::F64 {
                let device = input_meta.device();
                let nd = shape.len();
                let (m, n) = (shape[nd - 2], shape[nd - 1]);
                let out = self.tensor_apply_function(
                    &[input],
                    move |ctx, inputs| {
                        let (values, in_shape) = inputs[0];
                        let meta = TensorMeta::from_shape(in_shape.to_vec(), DType::F64, device);
                        let (u, sv, vh) =
                            ft_kernel_cpu::svd_batched_contiguous_f64(values, &meta, false)
                                .map_err(|e| {
                                    AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                                })?;
                        let nd = in_shape.len();
                        let kk = in_shape[nd - 1].min(in_shape[nd - 2]);
                        ctx.save_for_backward(u, in_shape.to_vec());
                        ctx.save_for_backward(vh, in_shape.to_vec());
                        let mut sshape = in_shape[..nd - 2].to_vec();
                        sshape.push(kk);
                        Ok((sv, sshape))
                    },
                    move |ctx, grad_outputs| {
                        let saved = ctx.saved_tensors();
                        let u = &saved[0];
                        let vh = &saved[1];
                        let grad_s = grad_outputs[0];
                        let grad_a =
                            ft_kernel_cpu::svdvals_grad_batched_contiguous_f64(grad_s, u, vh, m, n)
                                .map_err(|e| {
                                    AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                                })?;
                        Ok(vec![Some(grad_a)])
                    },
                )?;
                self.runtime.ledger_mut().record(
                    EvidenceKind::Dispatch,
                    format!(
                        "linalg_svdvals input={} out={} (batched autograd)",
                        input.0, out.0
                    ),
                );
                return Ok(out);
            }
            if shape.len() == 2 && input_meta.dtype() == DType::F64 {
                let device = input_meta.device();
                let out = self.tensor_apply_function(
                    &[input],
                    move |ctx, inputs| {
                        let (values, in_shape) = inputs[0];
                        let meta = TensorMeta::from_shape(in_shape.to_vec(), DType::F64, device);
                        let r = ft_kernel_cpu::svd_contiguous_f64(values, &meta, false).map_err(
                            |e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)),
                        )?;
                        let (m, n, k) = (r.m, r.n, r.k);
                        ctx.save_for_backward(r.u, vec![m, k]); // U (m x k)
                        ctx.save_for_backward(r.vh, vec![k, n]); // Vh (k x n)
                        Ok((r.s, vec![k]))
                    },
                    move |ctx, grad_outputs| {
                        let saved = ctx.saved_tensors();
                        let u = &saved[0]; // U, m x k
                        let vh = &saved[1]; // Vh, k x n
                        let grad_s = grad_outputs[0]; // grad w.r.t. singular values, [k]
                        let k = grad_s.len();
                        let m = u.len() / k;
                        let n = vh.len() / k;
                        let mut grad_a = vec![0.0_f64; m * n];
                        for i in 0..m {
                            for j in 0..n {
                                let mut acc = 0.0_f64;
                                for l in 0..k {
                                    acc += grad_s[l] * u[i * k + l] * vh[l * n + j];
                                }
                                grad_a[i * n + j] = acc;
                            }
                        }
                        Ok(vec![Some(grad_a)])
                    },
                )?;
                self.runtime.ledger_mut().record(
                    EvidenceKind::Dispatch,
                    format!("linalg_svdvals input={} out={} (autograd)", input.0, out.0),
                );
                return Ok(out);
            }
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "linalg_svdvals: autograd only supported for a 2-D F64 matrix",
                },
            )));
        }
        // Batched no-grad f64 fast path: parallelize the verified 2-D svdvals over the batch
        // (~5-10x vs PyTorch's per-plane LAPACK-loop for small m,n). frankentorch-batched-eigh.
        {
            let shape0 = self.tensor_shape(input)?;
            let nd = shape0.len();
            if nd >= 3
                && self.tensor_dtype(input)? == DType::F64
                && self.tensor_tape.tensor(input)?.meta().is_contiguous()
            {
                let mn = shape0[nd - 2].min(shape0[nd - 1]);
                let meta = self.tensor_tape.tensor_meta(input)?.clone();
                let out = {
                    let v = self.tensor_tape.tensor(input)?.contiguous_values()?;
                    ft_kernel_cpu::svdvals_batched_contiguous_f64(v, &meta).map_err(|e| {
                        AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                    })?
                };
                let mut out_shape = shape0[..nd - 2].to_vec();
                out_shape.push(mn);
                return self.tensor_tape.leaf(out, out_shape, false);
            }
        }
        let (values, meta) = self.tensor_values_meta(input)?;
        let input_shape = meta.shape();
        let k = input_shape[0].min(input_shape[1]);
        let s = ft_kernel_cpu::svdvals_contiguous_f64(&values, &meta)
            .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?;
        self.tensor_variable(s, vec![k], false)
    }

    /// Alias for `tensor_linalg_svdvals`. Equivalent to `torch.svdvals`.
    pub fn tensor_svdvals(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        self.tensor_linalg_svdvals(input)
    }

    /// Compute the numerical rank of a matrix.
    ///
    /// Equivalent to `torch.linalg.matrix_rank(input, tol)`. Counts the number
    /// of singular values above the tolerance threshold.
    ///
    /// If `tol` is None, uses the default tolerance:
    ///     `tol = max(m, n) * eps * max_singular_value`
    /// where eps is machine epsilon (~2.2e-16 for f64).
    ///
    /// Returns a scalar tensor (0-D) containing the rank. Does not support
    /// autograd (rank is discrete).
    pub fn tensor_matrix_rank(
        &mut self,
        input: TensorNodeId,
        tol: Option<f64>,
    ) -> Result<TensorNodeId, AutogradError> {
        // f32/half: compute in f64 then cast the (integer-valued) rank back. The count extracts singular
        // values via tensor_values (f64-only); now that svdvals preserves the input dtype, an f32 input
        // would otherwise reach tensor_values as f32 and panic. frankentorch-batched-eigh.
        let dt = self.tensor_dtype(input)?;
        if dt != DType::F64 {
            let in64 = self.tensor_to_dtype(input, DType::F64)?;
            let out64 = self.tensor_matrix_rank(in64, tol)?;
            return self.tensor_to_dtype(out64, dt);
        }
        let shape = self.tensor_shape(input)?;
        if shape.len() != 2 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "matrix_rank: input must be a 2D matrix",
                },
            )));
        }
        let m = shape[0];
        let n = shape[1];
        let s_id = self.tensor_linalg_svdvals(input)?;
        let s_vals = self.tensor_values(s_id)?;
        let max_s = s_vals.iter().cloned().fold(0.0_f64, f64::max);
        let actual_tol = tol.unwrap_or_else(|| {
            let eps = f64::EPSILON;
            (m.max(n) as f64) * eps * max_s
        });
        let rank = s_vals.iter().filter(|&&v| v > actual_tol).count() as f64;
        self.tensor_variable(vec![rank], vec![], false)
    }

    /// Compute the determinant of a square matrix.
    ///
    /// Returns a 0-D tensor that participates in the autograd graph
    /// (matches `torch.linalg.det`). Backward via Jacobi's formula:
    ///     grad_A = grad_out * det(A) * (A^{-1})^T
    /// Singular A → backward emits zeros (gradient undefined).
    /// Tracked under frankentorch-pvfk.
    pub fn tensor_linalg_det(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        if shape.len() != 2 || shape[0] != shape[1] {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: shape.clone(),
                    rhs: vec![2],
                },
            )));
        }
        let n = shape[0];
        self.tensor_apply_function_with_create_graph(
            &[input],
            move |ctx, inputs| {
                let (vals, in_shape) = inputs[0];
                let meta = TensorMeta::from_shape(in_shape.to_vec(), DType::F64, Device::Cpu);
                let result = ft_kernel_cpu::det_contiguous_f64(vals, &meta)
                    .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?;
                ctx.save_for_backward(vals.to_vec(), in_shape.to_vec());
                Ok((vec![result.det], vec![]))
            },
            move |ctx, grad_outputs| {
                let g = grad_outputs[0];
                if g.len() != 1 {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "linalg_det backward: expected 0-D upstream gradient",
                        },
                    )));
                }
                let saved = ctx.saved_tensors();
                let a = &saved[0];
                if a.len() != n * n {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "linalg_det backward: saved A shape mismatch",
                        },
                    )));
                }
                let meta = TensorMeta::from_shape(vec![n, n], DType::F64, Device::Cpu);
                let det_result = ft_kernel_cpu::det_contiguous_f64(a, &meta)
                    .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?;
                let inv_a = match ft_kernel_cpu::inv_tensor_contiguous_f64(a, &meta) {
                    Ok(inv) => inv,
                    Err(_) => {
                        return Ok(vec![Some(vec![0.0; n * n])]);
                    }
                };
                let scale = g[0] * det_result.det;
                let mut grad_a = vec![0.0_f64; n * n];
                for i in 0..n {
                    for j in 0..n {
                        grad_a[i * n + j] = scale * inv_a[j * n + i];
                    }
                }
                Ok(vec![Some(grad_a)])
            },
            // create_graph backward: grad_A = grad_y · det(A) · inv(A)ᵀ, with both
            // det(A) and inv(A) as differentiable nodes so the SECOND derivative
            // (e.g. ∂²det/∂a_ii∂a_jj for 2×2 = ±1) propagates. frankentorch-b820k.
            move |_ctx, grad_outs, inputs, tape| {
                let mode = ft_core::ExecutionMode::Strict;
                let inv = Self::cg_differentiable_inverse(tape, inputs[0], n)?;
                let inv_t = tape.transpose(inv, 0, 1)?;
                let det = Self::cg_differentiable_det(tape, inputs[0], n)?;
                // scalar = grad_y · det  (both 0-D), broadcast over [n, n].
                let scalar = tape.mul(grad_outs[0], det, mode)?.0;
                let sb = tape.reshape(scalar, vec![1, 1])?;
                let sb_b = tape.expand(sb, vec![n, n])?;
                let grad_a = tape.mul(sb_b, inv_t, mode)?.0;
                Ok(vec![Some(grad_a)])
            },
        )
    }

    pub fn tensor_det(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        self.tensor_linalg_det(input)
    }

    /// Compute sign and log-absolute-determinant of a square matrix.
    ///
    /// Returns `(sign, logabsdet)` as 0-D tensors where
    /// `det(A) = sign * exp(logabsdet)`. More numerically stable than
    /// `det` for large matrices. Sign is non-differentiable (constant
    /// in {-1, 0, 1}); logabsdet participates in the autograd graph.
    /// Backward of logabsdet via Jacobi's formula:
    ///     grad_A = grad_logabsdet * (A^{-1})^T
    /// Singular A → backward emits zeros. Tracked under frankentorch-pvfk.
    pub fn tensor_linalg_slogdet(
        &mut self,
        input: TensorNodeId,
    ) -> Result<(TensorNodeId, TensorNodeId), AutogradError> {
        // f32/half: compute in f64 then cast both outputs back (the LU core is
        // f64-only). torch keeps the input dtype (also fixes logdet, which
        // extracts logabsdet from here). frankentorch-h9ghv.
        let dt = self.tensor_dtype(input)?;
        if dt != DType::F64 {
            let in64 = self.tensor_to_dtype(input, DType::F64)?;
            let (sign64, logabs64) = self.tensor_linalg_slogdet(in64)?;
            return Ok((
                self.tensor_to_dtype(sign64, dt)?,
                self.tensor_to_dtype(logabs64, dt)?,
            ));
        }
        let shape = self.tensor_shape(input)?;
        if shape.len() != 2 || shape[0] != shape[1] {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: shape.clone(),
                    rhs: vec![2],
                },
            )));
        }
        let n = shape[0];

        // Compute sign once via the kernel, return as a non-grad 0-D tensor.
        let sign_val = {
            let (vals, meta) = self.tensor_values_meta(input)?;
            let result = ft_kernel_cpu::slogdet_contiguous_f64(&vals, &meta)
                .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?;
            result.sign
        };
        let sign_id = self.tensor_variable(vec![sign_val], vec![], false)?;

        let logabsdet_id = self.tensor_apply_function_with_create_graph(
            &[input],
            move |ctx, inputs| {
                let (vals, in_shape) = inputs[0];
                let meta = TensorMeta::from_shape(in_shape.to_vec(), DType::F64, Device::Cpu);
                let result = ft_kernel_cpu::slogdet_contiguous_f64(vals, &meta)
                    .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?;
                ctx.save_for_backward(vals.to_vec(), in_shape.to_vec());
                Ok((vec![result.logabsdet], vec![]))
            },
            move |ctx, grad_outputs| {
                let g = grad_outputs[0];
                if g.len() != 1 {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "linalg_slogdet backward: expected 0-D upstream gradient",
                        },
                    )));
                }
                let saved = ctx.saved_tensors();
                let a = &saved[0];
                if a.len() != n * n {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "linalg_slogdet backward: saved A shape mismatch",
                        },
                    )));
                }
                let meta = TensorMeta::from_shape(vec![n, n], DType::F64, Device::Cpu);
                let inv_a = match ft_kernel_cpu::inv_tensor_contiguous_f64(a, &meta) {
                    Ok(inv) => inv,
                    Err(_) => {
                        return Ok(vec![Some(vec![0.0; n * n])]);
                    }
                };
                let scale = g[0];
                let mut grad_a = vec![0.0_f64; n * n];
                for i in 0..n {
                    for j in 0..n {
                        grad_a[i * n + j] = scale * inv_a[j * n + i];
                    }
                }
                Ok(vec![Some(grad_a)])
            },
            // create_graph backward: d/dA logabsdet(A) = inv(A)ᵀ, built from a
            // differentiable inverse node so the SECOND derivative propagates.
            // grad_A = broadcast(grad_y) ⊙ inv(A)ᵀ. frankentorch-b820k.
            move |_ctx, grad_outs, inputs, tape| {
                let mode = ft_core::ExecutionMode::Strict;
                let y = Self::cg_differentiable_inverse(tape, inputs[0], n)?;
                let yt = tape.transpose(y, 0, 1)?;
                // grad_y is 0-D scalar; broadcast over [n, n].
                let gy = tape.reshape(grad_outs[0], vec![1, 1])?;
                let gy_b = tape.expand(gy, vec![n, n])?;
                let grad_a = tape.mul(gy_b, yt, mode)?.0;
                Ok(vec![Some(grad_a)])
            },
        )?;

        Ok((sign_id, logabsdet_id))
    }

    /// Alias for `tensor_linalg_slogdet`.
    ///
    /// Equivalent to `torch.slogdet(input)`.
    pub fn tensor_slogdet(
        &mut self,
        input: TensorNodeId,
    ) -> Result<(TensorNodeId, TensorNodeId), AutogradError> {
        self.tensor_linalg_slogdet(input)
    }

    /// Compute the log-determinant of a square matrix.
    ///
    /// Equivalent to `torch.logdet(input)`. Returns `log(|det(A)|)`.
    /// This is the second element of `slogdet` and is more numerically
    /// stable than `log(det(A))` for large matrices. Returns `-inf`
    /// for singular matrices (det = 0).
    pub fn tensor_logdet(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let (_sign, logabsdet) = self.tensor_linalg_slogdet(input)?;
        Ok(logabsdet)
    }

    /// Compute the Moore-Penrose pseudoinverse via SVD.
    ///
    /// Equivalent to `torch.linalg.pinv(input)`.
    /// For a matrix A with SVD `A = U @ diag(S) @ V^T`, the pseudoinverse is
    /// `A+ = V @ diag(1/S) @ U^T` (with small singular values zeroed).
    /// `torch.pinverse(input)` parity alias for
    /// `tensor_linalg_pinv`. torch's legacy pinverse name is
    /// distinct from torch.linalg.pinv (still in wide use in
    /// older PyTorch codebases). Tracked under frankentorch-36op.
    pub fn tensor_pinverse(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        self.tensor_linalg_pinv(input)
    }

    /// Hermitian (symmetric) pseudo-inverse — `torch.linalg.pinv(input, hermitian=True)`.
    /// For a symmetric `[..., k, k]` input, computes `V diag(λ⁺) Vᵀ` per plane via a FUSED batched
    /// eigh+reconstruction kernel (no autograd tape / reshape-view materialization, which otherwise
    /// dominate). No-grad f64 contiguous square only; everything else falls back to the general
    /// SVD-based pinv. frankentorch-batched-eigh. (BlackThrush)
    pub fn tensor_linalg_pinv_hermitian(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let dt = self.tensor_dtype(input)?;
        if dt == DType::F64
            && !self.tensor_requires_grad(input)?
            && self.tensor_tape.tensor(input)?.meta().is_contiguous()
        {
            let shape = self.tensor_shape(input)?;
            let nd = shape.len();
            if nd >= 2 && shape[nd - 1] == shape[nd - 2] {
                let meta = self.tensor_tape.tensor_meta(input)?.clone();
                let out = {
                    let v = self.tensor_tape.tensor(input)?.contiguous_values()?;
                    ft_kernel_cpu::pinv_hermitian_batched_contiguous_f64(v, &meta).map_err(|e| {
                        AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                    })?
                };
                return self.tensor_variable(out, shape, false);
            }
        }
        self.tensor_linalg_pinv(input)
    }

    pub fn tensor_linalg_pinv(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // f32/half: compute in f64 then cast back (the linalg core is f64-only).
        // torch keeps the input dtype. frankentorch-h9ghv.
        let dt = self.tensor_dtype(input)?;
        if dt != DType::F64 {
            let in64 = self.tensor_to_dtype(input, DType::F64)?;
            let out64 = self.tensor_linalg_pinv(in64)?;
            return self.tensor_to_dtype(out64, dt);
        }
        // Autograd-aware path for full-rank A (frankentorch-d3gs):
        //   m >= n (full column rank): A^+ = (A^T A)^{-1} A^T
        //   m <= n (full row rank):    A^+ = A^T (A A^T)^{-1}
        // Both compose through tensor_transpose + tensor_matmul +
        // tensor_linalg_inv — all autograd-aware after recent fixes.
        // The SVD-based path below stays for non-grad inputs to
        // continue handling rank-deficient cases correctly. If A is
        // rank-deficient and requires_grad, the inv inside the normal
        // equations will error loud (matches torch.linalg.pinv when
        // gradient mode is on without ridge regularization).
        if self.tensor_requires_grad(input)? {
            let shape_check = self.tensor_shape(input)?;
            let ndp = shape_check.len();
            // Batched f64 grad path (nd>=3): same normal-equations composition over the
            // leading batch dims. transpose/matmul/inv are all batched-grad-aware (inv via
            // the batched-inv-grad path), so correctness is inherited from the validated
            // primitives. torch's batched lstsq/pinv backward is pathologically slow
            // (~100-210ms), so this parallel composition wins. frankentorch batched-pinv-grad.
            if ndp >= 3 && self.tensor_dtype(input)? == DType::F64 {
                let m = shape_check[ndp - 2];
                let n = shape_check[ndp - 1];
                let a_t = self.tensor_transpose(input, ndp - 2, ndp - 1)?;
                return if m >= n {
                    let ata = self.tensor_matmul(a_t, input)?;
                    let inv_ata = self.tensor_linalg_inv(ata)?;
                    self.tensor_matmul(inv_ata, a_t)
                } else {
                    let aat = self.tensor_matmul(input, a_t)?;
                    let inv_aat = self.tensor_linalg_inv(aat)?;
                    self.tensor_matmul(a_t, inv_aat)
                };
            }
            if ndp != 2 {
                // Migrate to InvalidDimension (frankentorch-pyl0).
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                    ft_kernel_cpu::KernelError::InvalidDimension { dim: ndp, ndim: 2 },
                )));
            }
            let m = shape_check[0];
            let n = shape_check[1];
            let a_t = self.tensor_transpose(input, 0, 1)?;
            return if m >= n {
                // tall: A^+ = (A^T A)^{-1} A^T
                let ata = self.tensor_matmul(a_t, input)?;
                let inv_ata = self.tensor_linalg_inv(ata)?;
                self.tensor_matmul(inv_ata, a_t)
            } else {
                // wide: A^+ = A^T (A A^T)^{-1}
                let aat = self.tensor_matmul(input, a_t)?;
                let inv_aat = self.tensor_linalg_inv(aat)?;
                self.tensor_matmul(a_t, inv_aat)
            };
        }
        // Batched no-grad f64 fast path: FUSED svd-pinv kernel (per-plane reduced SVD + V Σ⁺ Uᵀ
        // reconstruction, parallel, no tape/reshape/Option). Handles rank-deficient via the σ⁺ threshold.
        // ~vs PyTorch's per-plane gesdd pinv loop (338-690ms). frankentorch-batched-eigh.
        if !self.tensor_requires_grad(input)?
            && self.tensor_dtype(input)? == DType::F64
            && self.tensor_tape.tensor(input)?.meta().is_contiguous()
        {
            let bshape = self.tensor_shape(input)?;
            let nd = bshape.len();
            if nd >= 3 {
                let (m, n) = (bshape[nd - 2], bshape[nd - 1]);
                let meta = self.tensor_tape.tensor_meta(input)?.clone();
                let out = {
                    let v = self.tensor_tape.tensor(input)?.contiguous_values()?;
                    ft_kernel_cpu::pinv_batched_contiguous_f64(v, &meta).map_err(|e| {
                        AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                    })?
                };
                let mut out_shape = bshape[..nd - 2].to_vec();
                out_shape.push(n);
                out_shape.push(m);
                return self.tensor_variable(out, out_shape, false);
            }
        }
        let shape = self.tensor_shape(input)?;
        if shape.len() != 2 {
            // Migrate to InvalidDimension (frankentorch-pyl0).
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::InvalidDimension {
                    dim: shape.len(),
                    ndim: 2,
                },
            )));
        }
        let m = shape[0];
        let n = shape[1];

        if let Some(pinv) = {
            let (values, meta) = self.tensor_values_meta(input)?;
            ft_kernel_cpu::pinv_qr_contiguous_f64(&values, &meta)
                .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?
        } {
            return self.tensor_variable(pinv, vec![n, m], false);
        }

        // SVD: A = U @ diag(S) @ Vh
        let (u_id, s_id, vh_id) = self.tensor_linalg_svd(input, false)?;
        let s_vals = self.tensor_values(s_id)?;

        // Threshold: singular values below eps * max(S) * max(m,n) are treated as zero
        let max_s = s_vals.iter().cloned().fold(0.0f64, f64::max);
        let eps = f64::EPSILON * (m.max(n) as f64) * max_s;

        let k = s_vals.len();
        let s_inv: Vec<f64> = s_vals
            .iter()
            .map(|&s| if s > eps { 1.0 / s } else { 0.0 })
            .collect();

        // Build pinv = Vh^T @ diag(s_inv) @ U^T
        // Vh is [k, n], Vh^T is [n, k]
        let vh_t = self.tensor_transpose(vh_id, 0, 1)?;
        // U is [m, k], U^T is [k, m]
        let u_t = self.tensor_transpose(u_id, 0, 1)?;

        // Scale columns of Vh^T by s_inv: Vh^T @ diag(s_inv) = element-wise multiply
        let s_inv_tensor = self.tensor_variable(s_inv, vec![1, k], false)?;
        let s_inv_expanded = self.tensor_expand(s_inv_tensor, vec![n, k])?;
        let vh_t_scaled = self.tensor_mul(vh_t, s_inv_expanded)?;

        // Final: vh_t_scaled @ u_t = [n, k] @ [k, m] = [n, m]
        self.tensor_matmul(vh_t_scaled, u_t)
    }

    pub fn tensor_pinv(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        self.tensor_linalg_pinv(input)
    }

    /// Compute the least-squares solution to a linear matrix equation.
    ///
    /// Equivalent to `torch.linalg.lstsq(A, B)`. Computes the solution `X`
    /// that minimizes `||AX - B||_2` for an m×n matrix A and m×k matrix B.
    ///
    /// Returns only the solution X (n×k matrix). For the full output
    /// (residuals, rank, singular values), use SVD-based decomposition.
    ///
    /// Implementation: uses pseudo-inverse `X = pinv(A) @ B`.
    pub fn tensor_lstsq(
        &mut self,
        a: TensorNodeId,
        b: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // f32/half: compute in f64 then cast to the promoted dtype (the lstsq
        // core is f64-only). torch keeps the input dtype. frankentorch-aqllp.
        let (da, db) = (self.tensor_dtype(a)?, self.tensor_dtype(b)?);
        if da != DType::F64 || db != DType::F64 {
            let out_dt = Self::promote_float_pair(da, db);
            let a64 = self.tensor_to_dtype(a, DType::F64)?;
            let b64 = self.tensor_to_dtype(b, DType::F64)?;
            let out64 = self.tensor_lstsq(a64, b64)?;
            return self.tensor_to_dtype(out64, out_dt);
        }
        let a_shape = self.tensor_shape(a)?;
        let b_shape = self.tensor_shape(b)?;
        if a_shape.len() != 2 || b_shape.len() != 2 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "lstsq: A and B must be 2D matrices",
                },
            )));
        }
        if a_shape[0] != b_shape[0] {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "lstsq: A and B must have the same number of rows",
                },
            )));
        }
        // Fast path: for an overdetermined full-rank A (m >= n) with no grad
        // required, solve via QR (A = Q·R; R·X = Qᵀ·B) instead of the SVD
        // pseudo-inverse. Same unique least-squares solution, but it replaces
        // the BLAS-1 Golub–Reinsch SVD with the parallel Householder QR. The
        // kernel returns None for the underdetermined / (near-)rank-deficient
        // cases, which fall through to the SVD pinv path (minimum-norm solution,
        // matching torch). Tracked under frankentorch.
        if a_shape[0] >= a_shape[1]
            && !self.tensor_requires_grad(a)?
            && !self.tensor_requires_grad(b)?
        {
            let (a_vals, a_meta) = self.tensor_values_meta(a)?;
            let (b_vals, b_meta) = self.tensor_values_meta(b)?;
            if let Some(x) =
                ft_kernel_cpu::lstsq_qr_contiguous_f64(&a_vals, &a_meta, &b_vals, &b_meta)
                    .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?
            {
                let n = a_shape[1];
                let k = b_shape[1];
                return self.tensor_variable(x, vec![n, k], false);
            }
        }

        let a_pinv = self.tensor_pinv(a)?;
        self.tensor_matmul(a_pinv, b)
    }

    /// Return the k-th smallest element of a 1-D tensor.
    ///
    /// Equivalent to `torch.kthvalue(input, k)`.
    /// Returns `(value, index)` where value is the k-th smallest element
    /// and index is its position in the input (1-indexed k, 0-indexed index).
    pub fn tensor_kthvalue(
        &mut self,
        input: TensorNodeId,
        k: usize,
    ) -> Result<(TensorNodeId, TensorNodeId), AutogradError> {
        let shape = self.tensor_shape(input)?;
        if shape.len() != 1 {
            // Migrate to InvalidDimension (frankentorch-oitu).
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::InvalidDimension {
                    dim: shape.len(),
                    ndim: 1,
                },
            )));
        }
        let numel = shape[0];
        if k == 0 || k > numel {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "kthvalue: k must be in [1, input.size(0)]",
                },
            )));
        }

        // Quickselect the rank-k VALUE in O(n) (vs the previous O(n log n) full sort
        // of all indices), then resolve the original index to EXACTLY match a stable
        // `sort_by(total_cmp)`: among elements equal to the k-th value the stable
        // order is ascending original index, so the rank-k element is the
        // (k-1 - #strictly-less)-th of them. Bit-for-bit identical index (incl. ties)
        // to the previous full sort; the gradient (via index_select below) is
        // therefore unchanged. frankentorch-kgs4.57.
        use std::cmp::Ordering;
        // Native-f32 fast path. The generic path below reads `tensor_values_lossy_f64`,
        // which UPCASTS the whole f32 buffer into a fresh f64 Vec (8·numel bytes) and then
        // quickselects on a SECOND f64 clone — for a contiguous f32 input that is two
        // full-numel allocations + an upcast pass before any work. Borrow the f32 buffer
        // and run the identical quickselect + index resolution in f32 (one f32 scratch =
        // half the bytes, no upcast). Bit-for-bit identical index: `f32::total_cmp` induces
        // the SAME total order as `f64::total_cmp` on the losslessly-widened values
        // (f32→f64 is exact and total_cmp is monotonic), so the rank-k element and the
        // stable ascending-index tie-break are unchanged; the value is then gathered via
        // index_select on the ORIGINAL f32 tensor exactly as the f64 path does. f32-parity.
        let f32_fast = self.tensor_dtype(input)? == DType::F32
            && self.tensor_tape.tensor(input)?.meta().is_contiguous();
        let idx = if f32_fast {
            let t = self.tensor_tape.tensor(input)?;
            let vals = t.contiguous_values_f32()?;
            let kth_value = {
                let mut scratch: Vec<f32> = vals.to_vec();
                let (_, v, _) = scratch.select_nth_unstable_by(k - 1, |a, b| a.total_cmp(b));
                *v
            };
            let less = vals
                .iter()
                .filter(|&&x| x.total_cmp(&kth_value) == Ordering::Less)
                .count();
            let offset = (k - 1) - less;
            vals.iter()
                .enumerate()
                .filter(|(_, x)| x.total_cmp(&kth_value) == Ordering::Equal)
                .nth(offset)
                .map(|(i, _)| i)
                .expect("rank-k element must exist after quickselect")
        } else {
            // F64 no-grad fast path (mirror of the f32 one + the median radix-select,
            // frankentorch-median-radixselect): for a contiguous F64 input, use the parallel
            // masked-histogram radix-select on the BORROWED buffer to find the rank-k VALUE —
            // no `tensor_values_lossy_f64` clone, no second `scratch` clone, no per-compare
            // total_cmp closure (the old path was two 128MB clones + a total_cmp quickselect).
            // torch.kthvalue orders NaN LAST (total_cmp), which the u64 radix keys can't
            // represent, so fall back to the total_cmp quickselect when ANY NaN is present.
            // NaN-free => total_cmp order == numeric order, so the less-count + nth-equal index
            // resolution (stable ascending-index tie-break) is bit-identical to the total_cmp
            // path below. frankentorch-kthvalue-radixselect.
            let radix_idx = if self.tensor_dtype(input)? == DType::F64 {
                match self.tensor_tape.values_borrowed(input) {
                    Ok(vals) => {
                        use rayon::prelude::*;
                        if vals.par_iter().any(|v| v.is_nan()) {
                            None
                        } else {
                            let kth_value = Self::radix_select_f64_no_nan(vals, k - 1);
                            let less = vals.par_iter().filter(|&&x| x < kth_value).count();
                            let offset = (k - 1) - less;
                            let i = vals
                                .iter()
                                .enumerate()
                                .filter(|(_, x)| **x == kth_value)
                                .nth(offset)
                                .map(|(i, _)| i)
                                .expect("rank-k element must exist after radix-select");
                            Some(i)
                        }
                    }
                    Err(_) => None,
                }
            } else {
                None
            };
            match radix_idx {
                Some(i) => i,
                None => {
                    // Lossy read so f64/f16/bf16 inputs are accepted (tensor_values is F64-only),
                    // and the NaN-present F64 case. frankentorch-fk5l.
                    let vals = self.tensor_values_lossy_f64(input)?;
                    let kth_value = {
                        let mut scratch: Vec<f64> = vals.clone();
                        let (_, v, _) =
                            scratch.select_nth_unstable_by(k - 1, |a, b| a.total_cmp(b));
                        *v
                    };
                    let less = vals
                        .iter()
                        .filter(|&&x| x.total_cmp(&kth_value) == Ordering::Less)
                        .count();
                    let offset = (k - 1) - less;
                    vals.iter()
                        .enumerate()
                        .filter(|(_, x)| x.total_cmp(&kth_value) == Ordering::Equal)
                        .nth(offset)
                        .map(|(i, _)| i)
                        .expect("rank-k element must exist after quickselect")
                }
            }
        };

        // Gather the rank-k element via index_select so the value keeps the input
        // dtype (torch kthvalue(f32) -> f32) and stays autograd-aware:
        // index_select's backward scatters grad_value to position `idx` and 0
        // elsewhere — identical to the previous custom-op gradient
        // (frankentorch-0juq), but the old path read f64-only values and built an
        // F64 leaf. frankentorch-fk5l.
        let idx_leaf = self.tensor_tape.leaf(vec![idx as f64], vec![1], false)?;
        let value = self.tensor_index_select(input, 0, idx_leaf)?;
        let index = self.tensor_variable(vec![idx as f64], vec![1], false)?;
        Ok((value, index))
    }

    /// Compute vector norm along a dimension.
    ///
    /// Equivalent to `torch.linalg.vector_norm(input, ord=2, dim=None)`.
    /// Supports ord: 0, 1, 2, inf, -inf, and any positive float.
    pub fn tensor_linalg_vector_norm(
        &mut self,
        input: TensorNodeId,
        ord: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        // Compose via autograd-aware primitives so gradients flow back
        // to the input. Tracked under frankentorch-4yh9. Previous body
        // extracted tensor_values and rebuilt a non-grad leaf,
        // silently severing autograd through every vector_norm call
        // (used in normalization layers, regularization, gradient
        // clipping, etc).
        let shape = self.tensor_shape(input)?;
        let numel = Self::checked_shape_numel(&shape, "vector_norm: input shape volume overflow")?;
        if numel == 0 {
            // Empty input: every norm is 0 by convention, but tracked
            // empty tensors must still keep a tape edge so backward
            // yields an empty gradient rather than failing on a fresh
            // non-grad zero leaf. Tracked under frankentorch-ivel.
            return self.tensor_apply_function(
                &[input],
                |_ctx, _inputs| Ok((vec![0.0], vec![1])),
                |_ctx, _grad_outputs| Ok(vec![Some(Vec::new())]),
            );
        }
        // Flatten so the reduction has a single axis.
        let flat = self.tensor_reshape(input, vec![numel])?;
        let abs_x = self.tensor_abs(flat)?;

        if ord == 0.0 {
            // L0 norm is non-differentiable (integer count of nonzeros).
            // Fail loud when caller asked for gradients; otherwise
            // fall back to the f64 path.
            if self.tensor_requires_grad(input)? {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "vector_norm(ord=0): autograd not supported (integer count of nonzeros is not differentiable)",
                    },
                )));
            }
            let vals = self.tensor_values(input)?;
            #[allow(clippy::cast_precision_loss)]
            let count = vals.iter().filter(|&&v| v != 0.0).count() as f64;
            return self.tensor_variable(vec![count], vec![1], false);
        }
        if ord == f64::INFINITY {
            // L_inf = max(|x|). tensor_max_dim returns (vals, idx).
            let (m, _) = self.tensor_max_dim(abs_x, 0)?;
            // Result has shape [1] already after dim-0 reduction
            // because input was 1-D — but let's normalize via reshape
            // to match the legacy [1] shape contract.
            let m_shape = self.tensor_shape(m)?;
            return if m_shape == vec![1] {
                Ok(m)
            } else {
                self.tensor_reshape(m, vec![1])
            };
        }
        if ord == f64::NEG_INFINITY {
            let (m, _) = self.tensor_min_dim(abs_x, 0)?;
            let m_shape = self.tensor_shape(m)?;
            return if m_shape == vec![1] {
                Ok(m)
            } else {
                self.tensor_reshape(m, vec![1])
            };
        }
        // General p: (sum_i |x_i|^p)^(1/p).
        let pow_p = self.tensor_pow(abs_x, ord)?;
        let summed = self.tensor_sum(pow_p)?;
        // tensor_sum returns shape [1]; tensor_pow accepts that.
        self.tensor_pow(summed, 1.0 / ord)
    }

    /// Compute the least-squares solution to a linear system A @ X = B.
    ///
    /// Equivalent to `torch.linalg.lstsq(A, B)`.
    /// Returns the solution X that minimizes ||A @ X - B||_2.
    /// A is (m, n), B is (m,) or (m, k). Returns X of shape (n,) or (n, k).
    pub fn tensor_linalg_lstsq(
        &mut self,
        a: TensorNodeId,
        b: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // f32/half: compute in f64 then cast back (the lstsq core is f64-only; this also routes batched
        // f32 through the fused f64 batched path). torch promotes to a common dtype. frankentorch-batched-eigh.
        let (da, db) = (self.tensor_dtype(a)?, self.tensor_dtype(b)?);
        if da != DType::F64 || db != DType::F64 {
            let a64 = self.tensor_to_dtype(a, DType::F64)?;
            let b64 = self.tensor_to_dtype(b, DType::F64)?;
            let out64 = self.tensor_linalg_lstsq(a64, b64)?;
            let rdt = if da == db { da } else { DType::F64 };
            return self.tensor_to_dtype(out64, rdt);
        }
        let a_shape = self.tensor_shape(a)?;
        let b_shape = self.tensor_shape(b)?;

        // Batched no-grad f64 fast path for full-rank overdetermined systems:
        // PyTorch loops LAPACK lstsq over each small plane, while FrankenTorch
        // can parallelize the existing QR solver over disjoint planes. If any
        // plane falls outside the QR contract, fall through to the general
        // SVD-based batched path below.
        if a_shape.len() >= 3
            && b_shape.len() == a_shape.len()
            && !self.tensor_requires_grad(a)?
            && !self.tensor_requires_grad(b)?
            && self.tensor_dtype(a)? == DType::F64
            && self.tensor_dtype(b)? == DType::F64
            && self.tensor_tape.tensor(a)?.meta().is_contiguous()
            && self.tensor_tape.tensor(b)?.meta().is_contiguous()
        {
            let nd = a_shape.len();
            let m = a_shape[nd - 2];
            let n = a_shape[nd - 1];
            let nrhs = b_shape[nd - 1];
            if a_shape[..nd - 2] == b_shape[..nd - 2] && b_shape[nd - 2] == m && m >= n {
                let a_meta = self.tensor_tape.tensor_meta(a)?.clone();
                let b_meta = self.tensor_tape.tensor_meta(b)?.clone();
                let maybe_out = {
                    let av = self.tensor_tape.tensor(a)?.contiguous_values()?;
                    let bv = self.tensor_tape.tensor(b)?.contiguous_values()?;
                    ft_kernel_cpu::lstsq_qr_batched_contiguous_f64(av, &a_meta, bv, &b_meta)
                        .map_err(|e| {
                            AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                        })?
                };
                if let Some(out) = maybe_out {
                    let mut out_shape = a_shape[..nd - 2].to_vec();
                    out_shape.push(n);
                    out_shape.push(nrhs);
                    return self.tensor_variable(out, out_shape, false);
                }
            }
        }

        // Batched no-grad f64 fast path: FUSED svd-lstsq kernel (per-plane SVD applied to B, parallel,
        // no tape/reshape/Option). ~vs PyTorch's per-plane lstsq loop. frankentorch-batched-eigh.
        if a_shape.len() >= 3
            && b_shape.len() == a_shape.len()
            && !self.tensor_requires_grad(a)?
            && !self.tensor_requires_grad(b)?
            && self.tensor_dtype(a)? == DType::F64
            && self.tensor_dtype(b)? == DType::F64
            && self.tensor_tape.tensor(a)?.meta().is_contiguous()
            && self.tensor_tape.tensor(b)?.meta().is_contiguous()
        {
            let nd = a_shape.len();
            let (m, n) = (a_shape[nd - 2], a_shape[nd - 1]);
            let nrhs = b_shape[nd - 1];
            if a_shape[..nd - 2] == b_shape[..nd - 2] && b_shape[nd - 2] == m {
                let a_meta = self.tensor_tape.tensor_meta(a)?.clone();
                let b_meta = self.tensor_tape.tensor_meta(b)?.clone();
                let out = {
                    let av = self.tensor_tape.tensor(a)?.contiguous_values()?;
                    let bv = self.tensor_tape.tensor(b)?.contiguous_values()?;
                    ft_kernel_cpu::lstsq_batched_contiguous_f64(av, &a_meta, bv, &b_meta).map_err(
                        |e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)),
                    )?
                };
                let mut out_shape = a_shape[..nd - 2].to_vec();
                out_shape.push(n);
                out_shape.push(nrhs);
                return self.tensor_variable(out, out_shape, false);
            }
        }

        // Autograd-aware path for full-rank A (frankentorch-ea99):
        // X = A^+ @ B where A^+ = pinv(A). pinv was made autograd-
        // aware via the normal-equation formulation (frankentorch-d3gs);
        // composing matmul on top delivers gradients to both A and B.
        // Handles both 2-D and batched (nd>=3) — pinv/matmul are batched-grad-aware
        // (frankentorch batched-pinv-grad). Placed BEFORE the 2-D-only guard so batched
        // grad doesn't error out. The SVD path below stays for non-grad inputs to
        // continue handling rank-deficient cases.
        if self.tensor_requires_grad(a)? || self.tensor_requires_grad(b)? {
            let pinv = self.tensor_linalg_pinv(a)?;
            return if b_shape.len() == 1 {
                let n_dim = a_shape[1];
                let n_rhs = a_shape[0];
                let b_2d = self.tensor_reshape(b, vec![n_rhs, 1])?;
                let x_2d = self.tensor_matmul(pinv, b_2d)?;
                self.tensor_reshape(x_2d, vec![n_dim])
            } else {
                self.tensor_matmul(pinv, b)
            };
        }

        if a_shape.len() != 2 {
            // Migrate to InvalidDimension (frankentorch-oitu).
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::InvalidDimension {
                    dim: a_shape.len(),
                    ndim: 2,
                },
            )));
        }

        let m = a_shape[0];
        let n = a_shape[1];

        // Fast path: overdetermined full-rank A (m >= n), no grad. Solve via QR
        // (R·X = Qᵀ·B) instead of the SVD pseudo-inverse below — the same unique
        // least-squares solution, ~6x faster (see lstsq_qr_contiguous_f64,
        // frankentorch-2i5d). The kernel returns None for the (near-)rank-
        // deficient case, which falls through to the SVD path (minimum-norm
        // solution). B may be 1-D [m] or 2-D [m, k]; the kernel handles both.
        // This is the torch.linalg.lstsq entry (sibling of tensor_lstsq).
        if m >= n {
            let nrhs = if b_shape.len() == 1 { 1 } else { b_shape[1] };
            let (a_vals, a_meta) = self.tensor_values_meta(a)?;
            let b_vals = self.tensor_values(b)?;
            // The kernel takes a 2-D B; present a 1-D b as [m, 1].
            let b_meta = TensorMeta::from_shape(vec![m, nrhs], ft_core::DType::F64, Device::Cpu);
            if let Some(x) =
                ft_kernel_cpu::lstsq_qr_contiguous_f64(&a_vals, &a_meta, &b_vals, &b_meta)
                    .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?
            {
                let out_shape = if b_shape.len() == 1 {
                    vec![n]
                } else {
                    vec![n, nrhs]
                };
                return self.tensor_variable(x, out_shape, false);
            }
        }

        // Solve via SVD: X = V @ diag(1/sigma) @ U^T @ B (pseudoinverse approach)
        let (u, s, vt) = self.tensor_linalg_svd(a, false)?;
        let u_vals = self.tensor_values(u)?;
        let s_vals = self.tensor_values(s)?;
        let vt_vals = self.tensor_values(vt)?;
        let b_vals = self.tensor_values(b)?;

        let k = m.min(n); // number of singular values

        let nrhs = if b_shape.len() == 1 { 1 } else { b_shape[1] };

        // Compute U^T @ B -> (k, nrhs)
        let u_shape = self.tensor_shape(u)?;
        let u_cols = u_shape[1]; // k in reduced mode

        let mut utb = vec![0.0; u_cols * nrhs];
        for i in 0..u_cols {
            for j in 0..nrhs {
                let mut sum = 0.0;
                for r in 0..m {
                    let b_val = if b_shape.len() == 1 {
                        b_vals[r]
                    } else {
                        b_vals[r * nrhs + j]
                    };
                    sum += u_vals[r * u_cols + i] * b_val;
                }
                utb[i * nrhs + j] = sum;
            }
        }

        // Apply diag(1/sigma): divide each row i by s[i] (skip near-zero singular values)
        let eps = 1e-15 * s_vals.iter().cloned().fold(0.0_f64, f64::max);
        for i in 0..k {
            let inv_s = if s_vals[i].abs() > eps {
                1.0 / s_vals[i]
            } else {
                0.0
            };
            for j in 0..nrhs {
                utb[i * nrhs + j] *= inv_s;
            }
        }

        // Compute V @ (diag(1/s) @ U^T @ B) -> (n, nrhs)
        let vt_shape = self.tensor_shape(vt)?;
        let vt_rows = vt_shape[0]; // n in reduced mode

        let mut result = vec![0.0; n * nrhs];
        for i in 0..n {
            for j in 0..nrhs {
                let mut sum = 0.0;
                for r in 0..vt_rows.min(k) {
                    sum += vt_vals[r * n + i] * utb[r * nrhs + j];
                }
                result[i * nrhs + j] = sum;
            }
        }

        let out_shape = if b_shape.len() == 1 {
            vec![n]
        } else {
            vec![n, nrhs]
        };
        self.tensor_variable(result, out_shape, false)
    }

    /// Compute the condition number of a matrix.
    ///
    /// Equivalent to `torch.linalg.cond(A, p)`.
    /// For p=2 (default), uses the ratio of largest to smallest singular value.
    /// For p=1 or p=inf, uses norm(A) * norm(inv(A)).
    pub fn tensor_linalg_cond(
        &mut self,
        input: TensorNodeId,
        p: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        // Batched no-grad fast path for the SVD condition number (p = ±2): route [...,m,n] through the
        // batched svdvals + a per-plane sigma_max/sigma_min ratio (vs PyTorch's per-plane svd loop,
        // 137-240ms). frankentorch-batched-eigh.
        if shape.len() >= 3 && !self.tensor_requires_grad(input)? && (p == 2.0 || p == -2.0) {
            let s = self.tensor_linalg_svdvals(input)?;
            let last = self.tensor_shape(s)?.len() - 1;
            let smax = self.tensor_max_dim(s, last)?.0;
            let smin = self.tensor_min_dim(s, last)?.0;
            return if p == 2.0 {
                self.tensor_div(smax, smin)
            } else {
                self.tensor_div(smin, smax)
            };
        }
        // Batched f64 GRAD path for p=±2 (nd>=3): cond = σ_max/σ_min via batched svdvals
        // (grad-aware, 6-9x win) + narrow + div — all batched-grad-aware. torch's cond grad
        // is slow (looped per-plane SVD, ~93-177ms fwd+bwd). frankentorch batched-cond-grad.
        if shape.len() >= 3 && self.tensor_requires_grad(input)? && (p == 2.0 || p == -2.0) {
            let s = self.tensor_linalg_svdvals(input)?;
            let s_shape = self.tensor_shape(s)?;
            let last = s_shape.len() - 1;
            let k = s_shape[last];
            if k >= 1 {
                let sigma_max = self.tensor_narrow(s, last, 0, 1)?;
                let sigma_min = self.tensor_narrow(s, last, k - 1, 1)?;
                let smax = self.tensor_squeeze(sigma_max, last)?;
                let smin = self.tensor_squeeze(sigma_min, last)?;
                return if p == 2.0 {
                    self.tensor_div(smax, smin)
                } else {
                    self.tensor_div(smin, smax)
                };
            }
        }
        if shape.len() != 2 {
            // Migrate to InvalidDimension (frankentorch-pyl0).
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::InvalidDimension {
                    dim: shape.len(),
                    ndim: 2,
                },
            )));
        }

        // Compose via autograd-aware primitives so gradients flow back
        // to the input matrix. Tracked under frankentorch-dsif. The
        // previous body extracted intermediate scalar values from the
        // svdvals/norm tensors and rebuilt non-grad leaves, severing
        // autograd through every condition-number computation in a
        // training loop.
        if p == 2.0 || p == -2.0 {
            // SVD-based: cond = sigma_max / sigma_min (or reciprocal for p=-2).
            // tensor_linalg_svdvals is now autograd-aware (frankentorch-rl4g:
            // grad_A = U diag(grad_σ) Vh for simple singular values), and
            // tensor_narrow + tensor_div compose through autograd downstream,
            // so the whole p=±2 path threads a gradient back to the input —
            // matching torch.linalg.cond. (This previously fell back to a
            // fail-loud requires_grad guard because svdvals returned a
            // non-grad leaf; that guard is no longer needed.)
            // svdvals returns a 1-D tensor of length min(m,n) sorted
            // descending; extract first/last elements via tensor_narrow.
            let s = self.tensor_linalg_svdvals(input)?;
            let s_shape = self.tensor_shape(s)?;
            if s_shape.is_empty() || s_shape[0] == 0 {
                // Empty matrix — autograd is not meaningful here.
                return self.tensor_variable(vec![f64::NAN], vec![1], false);
            }
            let n = s_shape[0];
            let sigma_max = self.tensor_narrow(s, 0, 0, 1)?; // [1]
            let sigma_min = self.tensor_narrow(s, 0, n - 1, 1)?; // [1]
            if p == 2.0 {
                self.tensor_div(sigma_max, sigma_min)
            } else {
                self.tensor_div(sigma_min, sigma_max)
            }
        } else {
            // For other norms: cond(A) = norm(A, p) * norm(inv(A), p).
            // tensor_matrix_norm and tensor_linalg_inv are both
            // autograd-aware; just multiply the two norm tensors
            // directly instead of extracting f64 scalars.
            let ord = if p == f64::INFINITY {
                "inf"
            } else if p == f64::NEG_INFINITY {
                "-inf"
            } else if p == 1.0 {
                "1"
            } else {
                "fro"
            };
            let norm_a = self.tensor_matrix_norm(input, ord)?;
            let inv = self.tensor_linalg_inv(input)?;
            let norm_inv = self.tensor_matrix_norm(inv, ord)?;
            self.tensor_mul(norm_a, norm_inv)
        }
    }

    /// Compute the numerical rank of a matrix.
    ///
    /// Equivalent to `torch.linalg.matrix_rank(A, tol)`.
    /// Uses SVD and counts singular values above the tolerance threshold.
    pub fn tensor_linalg_matrix_rank(
        &mut self,
        input: TensorNodeId,
        tol: Option<f64>,
    ) -> Result<TensorNodeId, AutogradError> {
        // f32/half: compute in f64 then cast the (integer-valued) ranks back. Required because the rank
        // count extracts singular values via tensor_values (f64-only); now that svdvals preserves the
        // input dtype, an f32 input would otherwise reach tensor_values as f32 and panic. Also routes
        // batched f32 through the fast f64 batched path. frankentorch-batched-eigh.
        let dt = self.tensor_dtype(input)?;
        if dt != DType::F64 {
            let in64 = self.tensor_to_dtype(input, DType::F64)?;
            let out64 = self.tensor_linalg_matrix_rank(in64, tol)?;
            return self.tensor_to_dtype(out64, dt);
        }
        let shape = self.tensor_shape(input)?;
        // Batched fast path: route [...,m,n] through the batched svdvals + a per-plane threshold-count
        // (~vs PyTorch's per-plane svd loop, 139-238ms). frankentorch-batched-eigh.
        if shape.len() >= 3 {
            let nd = shape.len();
            let (m, n) = (shape[nd - 2], shape[nd - 1]);
            let kk = m.min(n);
            let bb: usize = shape[..nd - 2].iter().product();
            let s = self.tensor_linalg_svdvals(input)?;
            let s_vals = self.tensor_values(s)?;
            let mut ranks = Vec::with_capacity(bb);
            for p in 0..bb {
                let plane = &s_vals[p * kk..(p + 1) * kk];
                let threshold = match tol {
                    Some(t) => t,
                    None => {
                        // Default per plane: max(m,n) * eps * sigma_max (svdvals sorted descending).
                        let sigma_max = plane.first().copied().unwrap_or(0.0);
                        m.max(n) as f64 * f64::EPSILON * sigma_max
                    }
                };
                ranks.push(plane.iter().filter(|&&sv| sv > threshold).count() as f64);
            }
            return self.tensor_variable(ranks, shape[..nd - 2].to_vec(), false);
        }
        if shape.len() != 2 {
            // Migrate to InvalidDimension (frankentorch-pyl0).
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::InvalidDimension {
                    dim: shape.len(),
                    ndim: 2,
                },
            )));
        }

        let s = self.tensor_linalg_svdvals(input)?;
        let s_vals = self.tensor_values(s)?;

        let threshold = match tol {
            Some(t) => t,
            None => {
                // Default: max(m, n) * eps * sigma_max
                let (m, n) = (shape[0], shape[1]);
                let sigma_max = s_vals.first().copied().unwrap_or(0.0);
                m.max(n) as f64 * f64::EPSILON * sigma_max
            }
        };

        let rank = s_vals.iter().filter(|&&sv| sv > threshold).count();
        self.tensor_variable(vec![rank as f64], vec![1], false)
    }

    /// Compute the QR decomposition: `A = Q @ R`.
    ///
    /// Returns `(Q, R)` as two separate tensor nodes.
    /// - If `reduced` is true: Q is (m x k), R is (k x n) where k = min(m, n).
    /// - If `reduced` is false: Q is (m x m), R is (m x n).
    pub fn tensor_linalg_qr(
        &mut self,
        input: TensorNodeId,
        reduced: bool,
    ) -> Result<(TensorNodeId, TensorNodeId), AutogradError> {
        // f32/half: compute in f64 then cast Q/R back (the QR core is f64-only).
        // torch keeps the input dtype on every output. frankentorch-clqek.
        let dt = self.tensor_dtype(input)?;
        // F32 no-grad fast path: native f32 QR (qr_contiguous_f32 — blocked
        // compact-WY via gemm::sgemm for m>=128, scalar Householder below),
        // computed in f32. Avoids the f32->f64->f32 round trip and matches torch's
        // f32 QR. frankentorch-b3o90.
        if dt == DType::F32
            && !self.tensor_requires_grad(input)?
            && self.tensor_shape(input)?.len() == 2
        {
            let iv = self.tensor_values_f32(input)?;
            let meta = self.tensor_tape.tensor_meta(input)?.clone();
            let input_m = meta.shape()[0];
            let result = ft_kernel_cpu::qr_contiguous_f32(&iv, &meta, reduced)
                .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?;
            let q_node = self.tensor_variable_f32(result.q, vec![input_m, result.m], false)?;
            let r_node = self.tensor_variable_f32(result.r, vec![result.m, result.n], false)?;
            return Ok((q_node, r_node));
        }
        // Batched no-grad f32 fast path: native f32 batched qr (no f64 round trip).
        if dt == DType::F32 && !self.tensor_requires_grad(input)? {
            let shape = self.tensor_shape(input)?;
            let nd = shape.len();
            if nd >= 3 && self.tensor_tape.tensor(input)?.meta().is_contiguous() {
                let m = shape[nd - 2];
                let n = shape[nd - 1];
                let kq = if reduced { m.min(n) } else { m };
                let meta = self.tensor_tape.tensor_meta(input)?.clone();
                let (q, r) = {
                    let v = self.tensor_tape.tensor(input)?.contiguous_values_f32()?;
                    ft_kernel_cpu::qr_batched_contiguous_f32(v, &meta, reduced).map_err(|e| {
                        AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                    })?
                };
                let mut q_shape = shape[..nd - 2].to_vec();
                q_shape.push(m);
                q_shape.push(kq);
                let mut r_shape = shape[..nd - 2].to_vec();
                r_shape.push(kq);
                r_shape.push(n);
                let q_node = self.tensor_variable_f32(q, q_shape, false)?;
                let r_node = self.tensor_variable_f32(r, r_shape, false)?;
                return Ok((q_node, r_node));
            }
        }
        if dt != DType::F64 {
            let in64 = self.tensor_to_dtype(input, DType::F64)?;
            let (q, r) = self.tensor_linalg_qr(in64, reduced)?;
            return Ok((self.tensor_to_dtype(q, dt)?, self.tensor_to_dtype(r, dt)?));
        }
        // Batched no-grad f64 fast path: parallelize the verified 2-D qr over the batch
        // (~2.9-10x vs PyTorch's per-plane LAPACK-loop for small m,n). frankentorch-batched-eigh.
        if !self.tensor_requires_grad(input)? {
            let shape = self.tensor_shape(input)?;
            let nd = shape.len();
            if nd >= 3 && self.tensor_tape.tensor(input)?.meta().is_contiguous() {
                let m = shape[nd - 2];
                let n = shape[nd - 1];
                let kq = if reduced { m.min(n) } else { m };
                let meta = self.tensor_tape.tensor_meta(input)?.clone();
                let (q, r) = {
                    let v = self.tensor_tape.tensor(input)?.contiguous_values()?;
                    ft_kernel_cpu::qr_batched_contiguous_f64(v, &meta, reduced).map_err(|e| {
                        AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                    })?
                };
                let mut q_shape = shape[..nd - 2].to_vec();
                q_shape.push(m);
                q_shape.push(kq);
                let mut r_shape = shape[..nd - 2].to_vec();
                r_shape.push(kq);
                r_shape.push(n);
                let q_node = self.tensor_tape.leaf(q, q_shape, false)?;
                let r_node = self.tensor_tape.leaf(r, r_shape, false)?;
                return Ok((q_node, r_node));
            }
        }
        // mode='complete' for a SQUARE matrix (m=n): complete and reduced QR are IDENTICAL
        // (Q n×n, R n×n), so route to the shipped reduced grad path. torch's complete square qr grad
        // is slow (looped geqrf). frankentorch batched-qr-grad-completesquare.
        if !reduced && self.tensor_requires_grad(input)? {
            let bshape = self.tensor_shape(input)?;
            let nd = bshape.len();
            if nd >= 2
                && bshape[nd - 1] == bshape[nd - 2]
                && self.tensor_dtype(input)? == DType::F64
            {
                return self.tensor_linalg_qr(input, true);
            }
        }
        // Batched f64 grad path for WIDE m<n (reduced): compose A=QR via the SQUARE qr of the
        // first m columns — (Q,R1)=qr(A[:,:m]); R2=Qᵀ·A[:,m:]; R=[R1|R2]. Uses the batched square
        // qr grad below + matmul/narrow/cat (all grad-aware). torch's wide qr backward is slow
        // (looped geqrf). frankentorch batched-qr-grad-wide.
        if self.tensor_requires_grad(input)? && reduced {
            let bshape = self.tensor_shape(input)?;
            let nd = bshape.len();
            if nd >= 3
                && bshape[nd - 2] < bshape[nd - 1]
                && self.tensor_dtype(input)? == DType::F64
                && self.tensor_tape.tensor(input)?.meta().is_contiguous()
            {
                let m = bshape[nd - 2];
                let n = bshape[nd - 1];
                let a1 = self.tensor_narrow(input, nd - 1, 0, m)?; // [.., m, m]
                let a2 = self.tensor_narrow(input, nd - 1, m, n - m)?; // [.., m, n-m]
                let (q, r1) = self.tensor_linalg_qr(a1, true)?; // square -> batched square qr grad
                let qt = self.tensor_matrix_transpose(q)?;
                let r2 = self.tensor_matmul(qt, a2)?; // [.., m, n-m]
                let r = self.tensor_cat(&[r1, r2], nd - 1)?; // [.., m, n]
                return Ok((q, r));
            }
        }
        // Batched f64 grad path (nd>=3, reduced, tall/square m>=n): parallelize the
        // per-plane QR + per-plane VJP over the batch, vs PyTorch's serial per-plane
        // geqrf + backward loop. Two independent nodes (Q,R) sum grad_A; each plane's
        // VJP is bit-identical to the 2-D call. TOLERANCE-parity. frankentorch batched-qr-grad.
        if self.tensor_requires_grad(input)? && reduced {
            let bshape = self.tensor_shape(input)?;
            let nd = bshape.len();
            if nd >= 3
                && bshape[nd - 2] >= bshape[nd - 1]
                && self.tensor_dtype(input)? == DType::F64
                && self.tensor_tape.tensor(input)?.meta().is_contiguous()
            {
                let device = self.tensor_tape.tensor_meta(input)?.device();
                let lead: Vec<usize> = bshape[..nd - 2].to_vec();
                let m = bshape[nd - 2];
                let n = bshape[nd - 1];
                let bb: usize = lead.iter().product();
                let mut qshape = lead.clone();
                qshape.push(m);
                qshape.push(n);
                let mut rshape = lead.clone();
                rshape.push(n);
                rshape.push(n);
                let qr_forward = move |output: u8, qsh: Vec<usize>, rsh: Vec<usize>| {
                    move |ctx: &mut FunctionCtx, inputs: &[(&[f64], &[usize])]| {
                        let (values, in_shape) = inputs[0];
                        let meta = TensorMeta::from_shape(in_shape.to_vec(), DType::F64, device);
                        let (q, r) = ft_kernel_cpu::qr_batched_contiguous_f64(values, &meta, true)
                            .map_err(|e| {
                                AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                            })?;
                        ctx.save_for_backward(q.clone(), qsh.clone());
                        ctx.save_for_backward(r.clone(), rsh.clone());
                        if output == 0 {
                            Ok((q, qsh.clone()))
                        } else {
                            Ok((r, rsh.clone()))
                        }
                    }
                };
                let q_node = self.tensor_apply_function(
                    &[input],
                    qr_forward(0, qshape.clone(), rshape.clone()),
                    move |ctx, grad_outputs| {
                        let saved = ctx.saved_tensors();
                        let (q, r) = (&saved[0], &saved[1]);
                        let grad_q = grad_outputs[0];
                        let zr = vec![0.0_f64; bb * n * n];
                        let grad_a = ft_kernel_cpu::qr_backward_tall_batched_contiguous_f64(
                            q, r, grad_q, &zr, bb, m, n,
                        );
                        Ok(vec![Some(grad_a)])
                    },
                )?;
                let r_node = self.tensor_apply_function(
                    &[input],
                    qr_forward(1, qshape, rshape),
                    move |ctx, grad_outputs| {
                        let saved = ctx.saved_tensors();
                        let (q, r) = (&saved[0], &saved[1]);
                        let grad_r = grad_outputs[0];
                        let zq = vec![0.0_f64; bb * m * n];
                        let grad_a = ft_kernel_cpu::qr_backward_tall_batched_contiguous_f64(
                            q, r, &zq, grad_r, bb, m, n,
                        );
                        Ok(vec![Some(grad_a)])
                    },
                )?;
                return Ok((q_node, r_node));
            }
        }
        if self.tensor_requires_grad(input)? {
            // QR backward via the two-independent-nodes pattern (same as eigh):
            // the QR VJP grad_A = (grad_Q + Q copyltu(M)) R^{-T},
            // M = R grad_R^T - grad_Q^T Q, is LINEAR in (grad_Q, grad_R), so the
            // Q-output and R-output nodes each contribute their own term and the
            // engine sums them into grad[input]. Supported for the standard
            // differentiable case: reduced QR, tall/square input (m >= n),
            // full-rank R. Each forward recomputes the deterministic QR, so both
            // outputs are bit-identical to the non-grad path. frankentorch-rl4g.
            let input_meta = self.tensor_tape.tensor_meta(input)?.clone();
            let shape = input_meta.shape();
            if reduced
                && shape.len() == 2
                && shape[0] >= shape[1]
                && input_meta.dtype() == DType::F64
            {
                let device = input_meta.device();
                // Q node — backward carries grad_Q (grad_R := 0).
                let q_node = self.tensor_apply_function(
                    &[input],
                    move |ctx, inputs| {
                        let (values, in_shape) = inputs[0];
                        let meta = TensorMeta::from_shape(in_shape.to_vec(), DType::F64, device);
                        let r =
                            ft_kernel_cpu::qr_contiguous_f64(values, &meta, true).map_err(|e| {
                                AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                            })?;
                        let (mm, nn) = (in_shape[0], in_shape[1]);
                        ctx.save_for_backward(r.q.clone(), vec![mm, nn]);
                        ctx.save_for_backward(r.r, vec![nn, nn]);
                        Ok((r.q, vec![mm, nn]))
                    },
                    move |ctx, grad_outputs| {
                        let saved = ctx.saved_tensors();
                        let q = &saved[0];
                        let r = &saved[1];
                        let grad_q = grad_outputs[0];
                        #[allow(
                            clippy::cast_possible_truncation,
                            clippy::cast_sign_loss,
                            clippy::cast_precision_loss
                        )]
                        let n = (r.len() as f64).sqrt().round() as usize;
                        let m = q.len() / n;
                        let zero_r = vec![0.0_f64; n * n];
                        let grad_a = Self::qr_backward_tall(q, r, grad_q, &zero_r, m, n);
                        Ok(vec![Some(grad_a)])
                    },
                )?;
                // R node — backward carries grad_R (grad_Q := 0).
                let r_node = self.tensor_apply_function(
                    &[input],
                    move |ctx, inputs| {
                        let (values, in_shape) = inputs[0];
                        let meta = TensorMeta::from_shape(in_shape.to_vec(), DType::F64, device);
                        let r =
                            ft_kernel_cpu::qr_contiguous_f64(values, &meta, true).map_err(|e| {
                                AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e))
                            })?;
                        let (mm, nn) = (in_shape[0], in_shape[1]);
                        ctx.save_for_backward(r.q, vec![mm, nn]);
                        ctx.save_for_backward(r.r.clone(), vec![nn, nn]);
                        Ok((r.r, vec![nn, nn]))
                    },
                    move |ctx, grad_outputs| {
                        let saved = ctx.saved_tensors();
                        let q = &saved[0];
                        let r = &saved[1];
                        let grad_r = grad_outputs[0];
                        #[allow(
                            clippy::cast_possible_truncation,
                            clippy::cast_sign_loss,
                            clippy::cast_precision_loss
                        )]
                        let n = (r.len() as f64).sqrt().round() as usize;
                        let m = q.len() / n;
                        let zero_q = vec![0.0_f64; m * n];
                        let grad_a = Self::qr_backward_tall(q, r, &zero_q, grad_r, m, n);
                        Ok(vec![Some(grad_a)])
                    },
                )?;
                self.runtime.ledger_mut().record(
                    EvidenceKind::Dispatch,
                    format!(
                        "linalg_qr input={} q={} r={} (autograd)",
                        input.0, q_node.0, r_node.0
                    ),
                );
                return Ok((q_node, r_node));
            }
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "linalg_qr: autograd only supported for reduced QR of a tall/square (m>=n) F64 matrix",
                },
            )));
        }
        let (values, meta) = self.tensor_values_meta(input)?;
        let input_m = meta.shape()[0];
        let result = ft_kernel_cpu::qr_contiguous_f64(&values, &meta, reduced)
            .map_err(|e| AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(e)))?;
        let q_node = self.tensor_variable(result.q, vec![input_m, result.m], false)?;
        let r_node = self.tensor_variable(result.r, vec![result.m, result.n], false)?;
        Ok((q_node, r_node))
    }

    /// Alias for `tensor_linalg_qr`. Equivalent to deprecated `torch.qr`.
    pub fn tensor_qr(
        &mut self,
        input: TensorNodeId,
        some: bool,
    ) -> Result<(TensorNodeId, TensorNodeId), AutogradError> {
        self.tensor_linalg_qr(input, some)
    }

    /// `torch.geqrf`: the LAPACK `dgeqrf` Householder QR factorization of a 2-D
    /// F64 matrix.
    ///
    /// Returns `(a, tau)` in LAPACK packing: `a` has the same shape as `input`
    /// (m x n) with R in its upper triangle (including the diagonal) and, below
    /// the diagonal of column j, the j-th Householder reflector vector `v_j`
    /// (whose implicit leading entry is 1). `tau` (length `min(m, n)`) holds the
    /// reflector scalars, so `H_j = I - tau_j v_j v_j^T` and
    /// `Q = H_0 H_1 ... H_{k-1}`. Like torch this is a NON-differentiable
    /// primitive; pair it with [`Self::tensor_householder_product`] (orgqr) to
    /// build Q, or [`Self::tensor_ormqr`] to apply Q without forming it.
    pub fn tensor_geqrf(
        &mut self,
        input: TensorNodeId,
    ) -> Result<(TensorNodeId, TensorNodeId), AutogradError> {
        // F32: upcast, run the f64 core, downcast — matches torch's f32 geqrf to
        // f32 precision (torch rounds every step; we round once, which is at least
        // as accurate). torch supports f32 for this primitive; we must not error.
        if self.tensor_dtype(input)? == DType::F32 {
            let in64 = self.tensor_to_f64(input)?;
            let (a64, tau64) = self.tensor_geqrf(in64)?;
            return Ok((self.tensor_to_f32(a64)?, self.tensor_to_f32(tau64)?));
        }
        let (values, meta) = self.tensor_values_meta(input)?;
        let shape = meta.shape();
        let r = shape.len();
        if r < 2 {
            return Err(Self::incompatible_tensor_args(
                "geqrf: expected a batch of matrices (*, m, n)",
            ));
        }
        if meta.dtype() != DType::F64 {
            return Err(Self::incompatible_tensor_args(
                "geqrf: only F64 input is supported",
            ));
        }
        let (m, n) = (shape[r - 2], shape[r - 1]);
        let k = m.min(n);
        let batch: usize = shape[..r - 2].iter().product();
        let mut a_all = vec![0.0_f64; batch * m * n];
        let mut tau_all = vec![0.0_f64; batch * k];
        for b in 0..batch {
            let (a, tau) = Self::geqrf_packed_f64(&values[b * m * n..(b + 1) * m * n], m, n);
            a_all[b * m * n..(b + 1) * m * n].copy_from_slice(&a);
            tau_all[b * k..(b + 1) * k].copy_from_slice(&tau);
        }
        let a_node = self.tensor_variable(a_all, shape.to_vec(), false)?;
        let mut tau_shape = shape[..r - 2].to_vec();
        tau_shape.push(k);
        let tau_node = self.tensor_variable(tau_all, tau_shape, false)?;
        Ok((a_node, tau_node))
    }

    /// LAPACK `dgeqrf` core: factor the row-major m x n matrix `values` into its
    /// packed R/reflector form and return `(packed, tau)`. Uses the `dlarfg`
    /// sign convention (`beta = -sign(alpha) * ||x||`) so the result matches
    /// torch/LAPACK to rounding.
    fn geqrf_packed_f64(values: &[f64], m: usize, n: usize) -> (Vec<f64>, Vec<f64>) {
        let mut a = values.to_vec();
        let k = m.min(n);
        let mut tau = vec![0.0_f64; k];
        for kk in 0..k {
            let alpha = a[kk * n + kk];
            // The norm of the strictly-below-diagonal entries decides whether a
            // reflector is needed (dlarfg): if it is zero the column is already
            // upper-triangular, so tau = 0 and the diagonal is left untouched.
            let mut below_sq = 0.0_f64;
            for i in (kk + 1)..m {
                let v = a[i * n + kk];
                below_sq += v * v;
            }
            if below_sq == 0.0 {
                tau[kk] = 0.0;
                continue;
            }
            let xnorm = (alpha * alpha + below_sq).sqrt();
            let beta = if alpha >= 0.0 { -xnorm } else { xnorm };
            let t = (beta - alpha) / beta;
            tau[kk] = t;
            let denom = alpha - beta;
            for i in (kk + 1)..m {
                a[i * n + kk] /= denom;
            }
            a[kk * n + kk] = beta;
            // Apply H = I - t v v^T (v[kk] = 1, v[i>kk] = a[i,kk]) to the trailing
            // columns.
            for j in (kk + 1)..n {
                let mut w = a[kk * n + j];
                for i in (kk + 1)..m {
                    w += a[i * n + kk] * a[i * n + j];
                }
                w *= t;
                a[kk * n + j] -= w;
                for i in (kk + 1)..m {
                    a[i * n + j] -= w * a[i * n + kk];
                }
            }
        }
        (a, tau)
    }

    /// Apply `H_kk = I - tau v v^T` (with `v[kk] = 1`, `v[i>kk] = a_packed[i, kk]`)
    /// from the LEFT to a row-major `rows x ncols` matrix `c`, touching only rows
    /// `kk..rows`. `a_packed` is the m x `a_cols` geqrf output (`rows == m`).
    fn apply_reflector_left(
        c: &mut [f64],
        rows: usize,
        ncols: usize,
        a_packed: &[f64],
        a_cols: usize,
        kk: usize,
        tau: f64,
    ) {
        if tau == 0.0 {
            return;
        }
        for j in 0..ncols {
            let mut w = c[kk * ncols + j];
            for i in (kk + 1)..rows {
                w += a_packed[i * a_cols + kk] * c[i * ncols + j];
            }
            w *= tau;
            c[kk * ncols + j] -= w;
            for i in (kk + 1)..rows {
                c[i * ncols + j] -= w * a_packed[i * a_cols + kk];
            }
        }
    }

    /// Apply `H_kk` from the RIGHT to a row-major `nrows x cols` matrix `c`
    /// (`c := c H_kk`), touching only columns `kk..cols`.
    fn apply_reflector_right(
        c: &mut [f64],
        nrows: usize,
        cols: usize,
        a_packed: &[f64],
        a_cols: usize,
        kk: usize,
        tau: f64,
    ) {
        if tau == 0.0 {
            return;
        }
        for i in 0..nrows {
            let mut w = c[i * cols + kk];
            for l in (kk + 1)..cols {
                w += a_packed[l * a_cols + kk] * c[i * cols + l];
            }
            w *= tau;
            c[i * cols + kk] -= w;
            for l in (kk + 1)..cols {
                c[i * cols + l] -= w * a_packed[l * a_cols + kk];
            }
        }
    }

    /// `torch.orgqr(input, tau)`: alias for [`Self::tensor_householder_product`]
    /// (`torch.linalg.householder_product`) — form the orthogonal factor Q from
    /// the packed reflectors and `tau` of [`Self::tensor_geqrf`]. Provided so
    /// `torch.orgqr` call sites port directly.
    pub fn tensor_orgqr(
        &mut self,
        a: TensorNodeId,
        tau: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_householder_product(a, tau)
    }

    /// `torch.linalg.householder_product` (a.k.a. `torch.orgqr`): form the
    /// orthogonal factor Q (m x n, reduced) from the packed reflectors `a` and
    /// scalars `tau` produced by [`Self::tensor_geqrf`].
    pub fn tensor_householder_product(
        &mut self,
        a: TensorNodeId,
        tau: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // F32: upcast inputs, run the f64 core, downcast — matches torch's f32.
        if self.tensor_dtype(a)? == DType::F32 {
            let a64 = self.tensor_to_f64(a)?;
            let tau64 = self.tensor_to_f64(tau)?;
            let q64 = self.tensor_householder_product(a64, tau64)?;
            return self.tensor_to_f32(q64);
        }
        let (a_vals, a_meta) = self.tensor_values_meta(a)?;
        let a_shape = a_meta.shape();
        let r = a_shape.len();
        if r < 2 {
            return Err(Self::incompatible_tensor_args(
                "householder_product: expected a batch of reflector matrices (*, m, n)",
            ));
        }
        if a_meta.dtype() != DType::F64 {
            return Err(Self::incompatible_tensor_args(
                "householder_product: only F64 is supported",
            ));
        }
        let (m, n) = (a_shape[r - 2], a_shape[r - 1]);
        // torch.linalg.householder_product forms the reduced Q (m x n) explicitly,
        // so it requires at least as many rows as columns; a wide (m < n)
        // reflector matrix is rejected ("input.shape[-2] must be >=
        // input.shape[-1]"). ormqr applies Q without forming it and so accepts
        // wide matrices — the guard belongs here, not there.
        if m < n {
            return Err(Self::incompatible_tensor_args(
                "householder_product: input.shape[-2] must be >= input.shape[-1]",
            ));
        }
        let batch: usize = a_shape[..r - 2].iter().product();
        let tau_vals = self.tensor_values(tau)?;
        let tau_shape = self.tensor_shape(tau)?;
        let tr = tau_shape.len();
        let k = if tr == 0 { 0 } else { tau_shape[tr - 1] };
        if k > m.min(n) {
            return Err(Self::incompatible_tensor_args(
                "householder_product: tau has more reflectors than min(rows, cols)",
            ));
        }
        if tau_shape[..tr.saturating_sub(1)].iter().product::<usize>() != batch {
            return Err(Self::incompatible_tensor_args(
                "householder_product: tau batch dims must match a batch dims",
            ));
        }
        let mut q_all = vec![0.0_f64; batch * m * n];
        for b in 0..batch {
            let a_slice = &a_vals[b * m * n..(b + 1) * m * n];
            let tau_slice = &tau_vals[b * k..(b + 1) * k];
            // Q starts as the first n columns of the m x m identity; the k
            // reflectors are applied right-to-left so Q = H_0 H_1 ... H_{k-1}.
            let q = &mut q_all[b * m * n..(b + 1) * m * n];
            for i in 0..m.min(n) {
                q[i * n + i] = 1.0;
            }
            for kk in (0..k).rev() {
                Self::apply_reflector_left(q, m, n, a_slice, n, kk, tau_slice[kk]);
            }
        }
        self.tensor_variable(q_all, a_shape.to_vec(), false)
    }

    /// `torch.ormqr`: multiply `other` by the orthogonal factor Q (or Q^T) implied
    /// by the packed reflectors `a`/`tau` from [`Self::tensor_geqrf`], WITHOUT ever
    /// forming Q. `left` selects `Q @ other` vs `other @ Q`; `transpose` uses Q^T.
    pub fn tensor_ormqr(
        &mut self,
        a: TensorNodeId,
        tau: TensorNodeId,
        other: TensorNodeId,
        left: bool,
        transpose: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        // F32: upcast inputs, run the f64 core, downcast — matches torch's f32.
        if self.tensor_dtype(a)? == DType::F32 {
            let a64 = self.tensor_to_f64(a)?;
            let tau64 = self.tensor_to_f64(tau)?;
            let other64 = self.tensor_to_f64(other)?;
            let r64 = self.tensor_ormqr(a64, tau64, other64, left, transpose)?;
            return self.tensor_to_f32(r64);
        }
        let (a_vals, a_meta) = self.tensor_values_meta(a)?;
        let a_shape = a_meta.shape();
        let r = a_shape.len();
        if r < 2 || a_meta.dtype() != DType::F64 {
            return Err(Self::incompatible_tensor_args(
                "ormqr: a must be a batch of F64 reflector matrices (*, m, n)",
            ));
        }
        let (m, n) = (a_shape[r - 2], a_shape[r - 1]);
        // ormqr applies Q (or Q^T) WITHOUT forming it, so — unlike
        // householder_product — it accepts wide (m < n) reflector matrices,
        // matching torch.ormqr.
        let batch: usize = a_shape[..r - 2].iter().product();
        let tau_vals = self.tensor_values(tau)?;
        let tau_shape = self.tensor_shape(tau)?;
        let tr = tau_shape.len();
        let k = if tr == 0 { 0 } else { tau_shape[tr - 1] };
        if k > m.min(n) {
            return Err(Self::incompatible_tensor_args(
                "ormqr: tau has more reflectors than min(rows, cols)",
            ));
        }
        if tau_shape[..tr.saturating_sub(1)].iter().product::<usize>() != batch {
            return Err(Self::incompatible_tensor_args(
                "ormqr: tau batch dims must match a batch dims",
            ));
        }
        let (mut c_vals, c_meta) = self.tensor_values_meta(other)?;
        let c_shape = c_meta.shape();
        let cl = c_shape.len();
        if cl < 2 || c_meta.dtype() != DType::F64 {
            return Err(Self::incompatible_tensor_args(
                "ormqr: other must be a batch of F64 matrices (*, r, c)",
            ));
        }
        let (cr, cc) = (c_shape[cl - 2], c_shape[cl - 1]);
        if c_shape[..cl - 2].iter().product::<usize>() != batch {
            return Err(Self::incompatible_tensor_args(
                "ormqr: other batch dims must match a batch dims",
            ));
        }
        if left && cr != m {
            return Err(Self::incompatible_tensor_args(
                "ormqr: left=true requires other to have the same number of rows as a",
            ));
        }
        if !left && cc != m {
            return Err(Self::incompatible_tensor_args(
                "ormqr: left=false requires other to have the same number of columns as a",
            ));
        }
        // Q = H_0 ... H_{k-1}. Applying Q (or other @ Q^T) starts from H_0; applying
        // Q^T (or other @ Q) starts from H_{k-1}. `transpose == left` is exactly the
        // two forward-order cases.
        let forward: Vec<usize> = if transpose == left {
            (0..k).collect()
        } else {
            (0..k).rev().collect()
        };
        for b in 0..batch {
            let a_slice = &a_vals[b * m * n..(b + 1) * m * n];
            let tau_slice = &tau_vals[b * k..(b + 1) * k];
            let c_slice = &mut c_vals[b * cr * cc..(b + 1) * cr * cc];
            for &kk in &forward {
                if left {
                    Self::apply_reflector_left(c_slice, m, cc, a_slice, n, kk, tau_slice[kk]);
                } else {
                    Self::apply_reflector_right(c_slice, cr, m, a_slice, n, kk, tau_slice[kk]);
                }
            }
        }
        self.tensor_variable(c_vals, c_shape.to_vec(), false)
    }

    /// Compute the LU factorization of a square matrix.
    ///
    /// Equivalent to `torch.linalg.lu_factor`. Returns `(LU, pivots)` where:
    /// - LU: packed LU factorization (n x n)
    /// - pivots: pivot indices as an i64 tensor of shape [n]
    ///
    /// This is the `linalg`-prefixed version that returns pivots as a tensor
    /// for PyTorch API compatibility. Use `tensor_lu_factor` if you prefer
    /// pivots as a `Vec<usize>`.
    pub fn tensor_linalg_lu_factor(
        &mut self,
        input: TensorNodeId,
    ) -> Result<(TensorNodeId, TensorNodeId), AutogradError> {
        let (lu_node, pivots_vec) = self.tensor_lu_factor(input)?;
        let n = pivots_vec.len();
        let pivots_f64: Vec<f64> = pivots_vec.iter().map(|&p| p as f64).collect();
        let pivots_node = self.tensor_variable(pivots_f64, vec![n], false)?;
        Ok((lu_node, pivots_node))
    }

    /// Compute the LU factorization with info output.
    ///
    /// Equivalent to `torch.linalg.lu_factor_ex`. Returns `(LU, pivots, info)`:
    /// - LU: packed LU factorization (n x n)
    /// - pivots: pivot indices as an i64 tensor of shape [n]
    /// - info: scalar tensor (0 if successful, otherwise indicates error)
    pub fn tensor_linalg_lu_factor_ex(
        &mut self,
        input: TensorNodeId,
    ) -> Result<(TensorNodeId, TensorNodeId, TensorNodeId), AutogradError> {
        let (lu_node, pivots_node) = self.tensor_linalg_lu_factor(input)?;
        // torch/LAPACK getrf `info` = the 1-indexed first k with U[k,k] == 0
        // (the matrix is singular at that pivot), else 0 — NOT a constant 0.
        // Scan the packed LU's U diagonal (frankentorch-ibfw output-encoding class).
        let lu_shape = self.tensor_shape(lu_node)?;
        let n = lu_shape[0];
        let lu_vals = self.tensor_values(lu_node)?;
        let mut info = 0.0_f64;
        for k in 0..n {
            if lu_vals[k * n + k] == 0.0 {
                #[allow(clippy::cast_precision_loss)]
                let v = (k + 1) as f64;
                info = v;
                break;
            }
        }
        let info_node = self.tensor_variable(vec![info], vec![1], false)?;
        Ok((lu_node, pivots_node, info_node))
    }

    /// Solve a linear system using pre-computed LU factorization.
    ///
    /// Equivalent to `torch.linalg.lu_solve`. Takes:
    /// - LU: packed LU factorization from `tensor_linalg_lu_factor`
    /// - pivots: pivot indices tensor from `tensor_linalg_lu_factor`
    /// - B: right-hand side tensor (shape [n] or [n, m])
    ///
    /// Returns the solution X such that A @ X = B.
    pub fn tensor_linalg_lu_solve(
        &mut self,
        lu: TensorNodeId,
        pivots: TensorNodeId,
        b: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let pivots_vals = self.tensor_values(pivots)?;
        let pivots_usize: Vec<usize> = pivots_vals.iter().map(|&p| p as usize).collect();
        self.tensor_lu_solve(lu, &pivots_usize, b)
    }

    /// Cross product of two 3-element vectors.
    ///
    /// Alias for `tensor_cross` to match `torch.linalg.cross`.
    pub fn tensor_linalg_cross(
        &mut self,
        input: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // torch.linalg.cross defaults to dim=-1: broadcast the operands and take
        // the cross product along the LAST dimension, which must have size 3
        // (unlike torch.cross, which scans for the first size-3 dim).
        let bcast = self.tensor_broadcast_tensors(&[input, other])?;
        let (a, b) = (bcast[0], bcast[1]);
        let shape = self.tensor_shape(a)?;
        match shape.last() {
            Some(&3) => {}
            _ => {
                return Err(Self::incompatible_tensor_args(
                    "linalg_cross: last dimension must have size 3",
                ));
            }
        }
        let dim = shape.len() - 1;
        self.cross_along_dim(a, b, dim)
    }

    /// Compute the dot product of batches of vectors.
    ///
    /// Alias for `tensor_vecdot` to match `torch.linalg.vecdot`.
    pub fn tensor_linalg_vecdot(
        &mut self,
        x: TensorNodeId,
        y: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_vecdot(x, y)
    }

    /// Raise a square matrix to an integer power.
    ///
    /// Alias for `tensor_matrix_power` to match `torch.linalg.matrix_power`.
    /// n > 0: repeated squaring. n = 0: identity. n < 0: inv(A)^|n|.
    pub fn tensor_linalg_matrix_power(
        &mut self,
        input: TensorNodeId,
        n: i32,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_matrix_power(input, n)
    }

    // ── fft — FFT Helper Functions ─────────────────────────────────────────

    /// Shift the zero-frequency component to the center of the spectrum.
    ///
    /// Equivalent to `torch.fft.fftshift`. Rolls each dimension by half its size.
    /// If `dim` is None, shifts all dimensions.
    pub fn tensor_fft_fftshift(
        &mut self,
        input: TensorNodeId,
        dim: Option<&[usize]>,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        let ndim = shape.len();
        let dims: Vec<usize> = match dim {
            Some(d) => d.to_vec(),
            None => (0..ndim).collect(),
        };
        for &d in &dims {
            if d >= ndim {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "fft_fftshift: dimension out of range",
                    },
                )));
            }
        }
        if dims.is_empty() {
            return Ok(input);
        }
        // One tensor_roll_dims call instead of N sequential tensor_roll calls: a multi-dim shift
        // hits roll_dims' single-pass fast path (N materializing passes -> 1). Bit-identical (roll
        // is per-dim independent, so order/fusion doesn't change the result); grad falls through to
        // the sequential rolls inside roll_dims (autograd-aware, unchanged). frankentorch (BlackThrush).
        let shifts: Vec<i64> = dims.iter().map(|&d| (shape[d] / 2) as i64).collect();
        self.tensor_roll_dims(input, &shifts, &dims)
    }

    /// Inverse of `tensor_fft_fftshift`.
    ///
    /// Equivalent to `torch.fft.ifftshift`. For odd-length dimensions,
    /// this is NOT the same as fftshift.
    pub fn tensor_fft_ifftshift(
        &mut self,
        input: TensorNodeId,
        dim: Option<&[usize]>,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        let ndim = shape.len();
        let dims: Vec<usize> = match dim {
            Some(d) => d.to_vec(),
            None => (0..ndim).collect(),
        };
        for &d in &dims {
            if d >= ndim {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "fft_ifftshift: dimension out of range",
                    },
                )));
            }
        }
        if dims.is_empty() {
            return Ok(input);
        }
        // Single-pass via roll_dims (see tensor_fft_fftshift). ifftshift = roll by -(n/2) per dim
        // (the exact inverse of fftshift's +(n/2)); torch matches this for BOTH even and odd n
        // (verified n=4..7). NOTE: the previous -((n+1)/2) was WRONG for odd n (e.g. n=5 gave a
        // roll of -3 == +2, i.e. it re-applied fftshift instead of inverting it). frankentorch (BlackThrush).
        let shifts: Vec<i64> = dims.iter().map(|&d| -((shape[d] / 2) as i64)).collect();
        self.tensor_roll_dims(input, &shifts, &dims)
    }

    /// Return the Discrete Fourier Transform sample frequencies.
    ///
    /// Equivalent to `torch.fft.fftfreq(n, d)`.
    /// Returns frequencies in cycles per unit spacing: `[0, 1, ..., n/2-1, -n/2, ..., -1] / (n*d)`.
    pub fn tensor_fft_fftfreq(&mut self, n: usize, d: f64) -> Result<TensorNodeId, AutogradError> {
        if n == 0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "fft_fftfreq: n must be > 0",
                },
            )));
        }
        let scale = 1.0 / (n as f64 * d);
        let mut values = Vec::with_capacity(n);
        let half = (n + 1) / 2;
        for i in 0..half {
            values.push(i as f64 * scale);
        }
        for i in half..n {
            values.push((i as isize - n as isize) as f64 * scale);
        }
        self.tensor_variable(values, vec![n], false)
    }

    /// Return the Discrete Fourier Transform sample frequencies for real input.
    ///
    /// Equivalent to `torch.fft.rfftfreq(n, d)`.
    /// Returns frequencies: `[0, 1, ..., n//2] / (n*d)` (length n//2 + 1).
    pub fn tensor_fft_rfftfreq(&mut self, n: usize, d: f64) -> Result<TensorNodeId, AutogradError> {
        if n == 0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "fft_rfftfreq: n must be > 0",
                },
            )));
        }
        let scale = 1.0 / (n as f64 * d);
        let out_len = n / 2 + 1;
        let values: Vec<f64> = (0..out_len).map(|i| i as f64 * scale).collect();
        self.tensor_variable(values, vec![out_len], false)
    }

    // ── Signal Processing — Window Functions ───────────────────────────────

    /// Create a Hann window of size `window_length`.
    ///
    /// Equivalent to `torch.hann_window(window_length, periodic)`.
    /// The window is symmetric if `periodic=false`, periodic if `true`.
    pub fn tensor_hann_window(
        &mut self,
        window_length: usize,
        periodic: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        if window_length == 0 {
            return self.tensor_variable(vec![], vec![0], false);
        }
        if window_length == 1 {
            return self.tensor_variable(vec![1.0], vec![1], false);
        }
        let n = if periodic {
            window_length
        } else {
            window_length - 1
        };
        let values: Vec<f64> = (0..window_length)
            .map(|i| {
                let cos_val = (2.0 * std::f64::consts::PI * i as f64 / n as f64).cos();
                0.5 * (1.0 - cos_val)
            })
            .collect();
        self.tensor_variable(values, vec![window_length], false)
    }

    /// Create a Hamming window of size `window_length`.
    ///
    /// Equivalent to `torch.hamming_window(window_length, periodic, alpha, beta)`.
    /// Default alpha=0.54, beta=0.46 for standard Hamming window.
    pub fn tensor_hamming_window(
        &mut self,
        window_length: usize,
        periodic: bool,
        alpha: f64,
        beta: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        if window_length == 0 {
            return self.tensor_variable(vec![], vec![0], false);
        }
        if window_length == 1 {
            return self.tensor_variable(vec![1.0], vec![1], false);
        }
        let n = if periodic {
            window_length
        } else {
            window_length - 1
        };
        let values: Vec<f64> = (0..window_length)
            .map(|i| {
                let cos_val = (2.0 * std::f64::consts::PI * i as f64 / n as f64).cos();
                alpha - beta * cos_val
            })
            .collect();
        self.tensor_variable(values, vec![window_length], false)
    }

    /// Create a Blackman window of size `window_length`.
    ///
    /// Equivalent to `torch.blackman_window(window_length, periodic)`.
    pub fn tensor_blackman_window(
        &mut self,
        window_length: usize,
        periodic: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        if window_length == 0 {
            return self.tensor_variable(vec![], vec![0], false);
        }
        if window_length == 1 {
            return self.tensor_variable(vec![1.0], vec![1], false);
        }
        let n = if periodic {
            window_length
        } else {
            window_length - 1
        };
        let a0 = 0.42;
        let a1 = 0.5;
        let a2 = 0.08;
        let values: Vec<f64> = (0..window_length)
            .map(|i| {
                let x = i as f64 / n as f64;
                let cos1 = (2.0 * std::f64::consts::PI * x).cos();
                let cos2 = (4.0 * std::f64::consts::PI * x).cos();
                a0 - a1 * cos1 + a2 * cos2
            })
            .collect();
        self.tensor_variable(values, vec![window_length], false)
    }

    /// Create a Bartlett window of size `window_length`.
    ///
    /// Equivalent to `torch.bartlett_window(window_length, periodic)`.
    pub fn tensor_bartlett_window(
        &mut self,
        window_length: usize,
        periodic: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        if window_length == 0 {
            return self.tensor_variable(vec![], vec![0], false);
        }
        if window_length == 1 {
            return self.tensor_variable(vec![1.0], vec![1], false);
        }
        let n = if periodic {
            window_length
        } else {
            window_length - 1
        };
        let half = n as f64 / 2.0;
        let values: Vec<f64> = (0..window_length)
            .map(|i| 1.0 - ((i as f64 - half) / half).abs())
            .collect();
        self.tensor_variable(values, vec![window_length], false)
    }

    /// Create a Kaiser window of size `window_length`.
    ///
    /// Equivalent to `torch.kaiser_window(window_length, periodic, beta)`.
    /// Uses modified Bessel function I0.
    pub fn tensor_kaiser_window(
        &mut self,
        window_length: usize,
        periodic: bool,
        beta: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        if window_length == 0 {
            return self.tensor_variable(vec![], vec![0], false);
        }
        if window_length == 1 {
            return self.tensor_variable(vec![1.0], vec![1], false);
        }
        let n = if periodic {
            window_length as f64
        } else {
            (window_length - 1) as f64
        };
        let denom = Self::bessel_i0(beta);
        let values: Vec<f64> = (0..window_length)
            .map(|i| {
                let x = 2.0 * i as f64 / n - 1.0;
                let arg = beta * (1.0 - x * x).sqrt();
                Self::bessel_i0(arg) / denom
            })
            .collect();
        self.tensor_variable(values, vec![window_length], false)
    }

    /// Modified Bessel function of the first kind, order 0.
    fn bessel_i0(x: f64) -> f64 {
        let ax = x.abs();
        if ax < 3.75 {
            let y = (x / 3.75).powi(2);
            1.0 + y
                * (3.5156229
                    + y * (3.0899424
                        + y * (1.2067492 + y * (0.2659732 + y * (0.0360768 + y * 0.0045813)))))
        } else {
            let y = 3.75 / ax;
            (ax.exp() / ax.sqrt())
                * (0.39894228
                    + y * (0.01328592
                        + y * (0.00225319
                            + y * (-0.00157565
                                + y * (0.00916281
                                    + y * (-0.02057706
                                        + y * (0.02635537
                                            + y * (-0.01647633 + y * 0.00392377))))))))
        }
    }

    fn _compute_strides(shape: &[usize]) -> Vec<usize> {
        let ndim = shape.len();
        let mut strides = vec![0usize; ndim];
        if ndim > 0 {
            strides[ndim - 1] = 1;
            for d in (0..ndim - 1).rev() {
                strides[d] = strides[d + 1] * shape[d + 1];
            }
        }
        strides
    }

    // ── nn.init — Parameter Initialization Functions ───────────────────
    //
    // These functions modify tensor values in-place for parameter initialization.
    // Unlike regular in-place ops, they bypass the requires_grad leaf validation
    // because initialization is meant to set parameter values before training.
    // This mirrors PyTorch's nn.init which uses @torch.no_grad() internally.

    /// Compute (fan_in, fan_out) for a tensor based on its shape.
    ///
    /// For 2-D tensors (Linear): fan_in = shape[1], fan_out = shape[0].
    /// For N-D tensors (Conv): fan_in = shape[1] * prod(shape[2:]),
    ///                         fan_out = shape[0] * prod(shape[2:]).
    pub fn calculate_fan_in_and_fan_out(
        &self,
        tensor: TensorNodeId,
    ) -> Result<(usize, usize), AutogradError> {
        let shape = self.tensor_shape(tensor)?;
        if shape.len() < 2 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "calculate_fan_in_and_fan_out requires at least 2 dimensions",
                },
            )));
        }
        let receptive_field = Self::checked_shape_numel(
            &shape[2..],
            "calculate_fan_in_and_fan_out: receptive field overflow",
        )?;
        let fan_in = Self::checked_mul(
            shape[1],
            receptive_field,
            "calculate_fan_in_and_fan_out: fan_in overflow",
        )?;
        let fan_out = Self::checked_mul(
            shape[0],
            receptive_field,
            "calculate_fan_in_and_fan_out: fan_out overflow",
        )?;
        Ok((fan_in, fan_out))
    }

    /// Fill tensor with values drawn from uniform distribution U(a, b).
    pub fn init_uniform_(
        &mut self,
        tensor: TensorNodeId,
        a: f64,
        b: f64,
    ) -> Result<(), AutogradError> {
        let numel = self.tensor_numel(tensor)?;
        // NOTE: kept serial. The transform is trivial so this fill is writeback-bound
        // (update_tensor_values_for_float), and parallelizing the map gives ~0 (torch's
        // in-place uniform_ is a fast ~67ms; FT's writeback floor is ~160ms). See the
        // 2026-07-02 in-place-RNG negative-evidence entry (frankentorch-dist-par).
        let values: Vec<f64> = (0..numel)
            .map(|_| a + (b - a) * self.rng.next_f64())
            .collect();
        self.update_tensor_values_for_float(tensor, values, INIT_FLOAT_REASON)?;
        self.record_tensor_in_place_operation(
            "init_uniform_",
            tensor,
            Some(format!("a={a} b={b}")),
        );
        Ok(())
    }

    /// Fill tensor with values drawn from normal distribution N(mean, std^2).
    pub fn init_normal_(
        &mut self,
        tensor: TensorNodeId,
        mean: f64,
        std: f64,
    ) -> Result<(), AutogradError> {
        let numel = self.tensor_numel(tensor)?;
        // NOTE: kept serial. Writeback-bound like init_uniform_; additionally the Box-Muller
        // draw-serial/transform-parallel split needs a 256MB raw-pair buffer, so parallelizing
        // it lands ~parity-to-slower vs torch's in-place normal_ under load. See the
        // 2026-07-02 in-place-RNG negative-evidence entry (frankentorch-dist-par).
        let values: Vec<f64> = (0..numel)
            .map(|_| mean + std * self.rng.next_normal())
            .collect();
        self.update_tensor_values_for_float(tensor, values, INIT_FLOAT_REASON)?;
        self.record_tensor_in_place_operation(
            "init_normal_",
            tensor,
            Some(format!("mean={mean} std={std}")),
        );
        Ok(())
    }

    pub fn tensor_uniform_(
        &mut self,
        tensor: TensorNodeId,
        low: f64,
        high: f64,
    ) -> Result<(), AutogradError> {
        self.init_uniform_(tensor, low, high)
    }

    pub fn tensor_normal_(
        &mut self,
        tensor: TensorNodeId,
        mean: f64,
        std: f64,
    ) -> Result<(), AutogradError> {
        self.init_normal_(tensor, mean, std)
    }

    /// Fill tensor with exponentially distributed random values.
    ///
    /// Equivalent to `torch.Tensor.exponential_(lambd)`.
    /// Samples from Exp(lambda) with PDF: lambda * exp(-lambda * x)
    pub fn tensor_exponential_(
        &mut self,
        tensor: TensorNodeId,
        lambd: f64,
    ) -> Result<(), AutogradError> {
        if lambd <= 0.0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "exponential_: lambda must be positive",
                },
            )));
        }
        let numel = self.tensor_numel(tensor)?;
        // Inverse CDF: -ln(1-U)/lambda, but use -ln(U)/lambda since U is uniform.
        // Parallel transform, bit-identical to the serial `next_f64()` map.
        let values = self
            .rng
            .next_uniform_transformed(numel, |u| -u.ln() / lambd);
        self.update_tensor_values_for_float(tensor, values, INIT_FLOAT_REASON)?;
        self.record_tensor_in_place_operation(
            "exponential_",
            tensor,
            Some(format!("lambd={lambd}")),
        );
        Ok(())
    }

    /// Fill tensor with log-normally distributed random values.
    ///
    /// Equivalent to `torch.Tensor.log_normal_(mean, std)`.
    /// If X ~ N(mean, std^2), then exp(X) ~ LogNormal(mean, std).
    pub fn tensor_log_normal_(
        &mut self,
        tensor: TensorNodeId,
        mean: f64,
        std: f64,
    ) -> Result<(), AutogradError> {
        if std <= 0.0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "log_normal_: std must be positive",
                },
            )));
        }
        let numel = self.tensor_numel(tensor)?;
        let values = self
            .rng
            .next_normal_transformed(numel, |n| (mean + std * n).exp());
        self.update_tensor_values_for_float(tensor, values, INIT_FLOAT_REASON)?;
        self.record_tensor_in_place_operation(
            "log_normal_",
            tensor,
            Some(format!("mean={mean} std={std}")),
        );
        Ok(())
    }

    /// Fill tensor with Cauchy-distributed random values.
    ///
    /// Equivalent to `torch.Tensor.cauchy_(median, sigma)`.
    /// Uses inverse CDF: median + sigma * tan(pi * (U - 0.5))
    pub fn tensor_cauchy_(
        &mut self,
        tensor: TensorNodeId,
        median: f64,
        sigma: f64,
    ) -> Result<(), AutogradError> {
        if sigma <= 0.0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "cauchy_: sigma must be positive",
                },
            )));
        }
        let numel = self.tensor_numel(tensor)?;
        let values = self.rng.next_uniform_transformed(numel, |u| {
            median + sigma * (std::f64::consts::PI * (u - 0.5)).tan()
        });
        self.update_tensor_values_for_float(tensor, values, INIT_FLOAT_REASON)?;
        self.record_tensor_in_place_operation(
            "cauchy_",
            tensor,
            Some(format!("median={median} sigma={sigma}")),
        );
        Ok(())
    }

    /// Fill tensor with geometrically distributed random values.
    ///
    /// Equivalent to `torch.Tensor.geometric_(p)`.
    /// Number of Bernoulli trials until first success.
    pub fn tensor_geometric_(&mut self, tensor: TensorNodeId, p: f64) -> Result<(), AutogradError> {
        if p <= 0.0 || p > 1.0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "geometric_: p must be in (0, 1]",
                },
            )));
        }
        let numel = self.tensor_numel(tensor)?;
        // Inverse CDF: ceil(ln(1-U) / ln(1-p))
        let log_1_minus_p = (1.0 - p).ln();
        let values = self
            .rng
            .next_uniform_transformed(numel, |u| ((1.0 - u).ln() / log_1_minus_p).ceil());
        self.update_tensor_values_for_float(tensor, values, INIT_FLOAT_REASON)?;
        self.record_tensor_in_place_operation("geometric_", tensor, Some(format!("p={p}")));
        Ok(())
    }

    /// Fill tensor with Poisson-distributed random values.
    ///
    /// Equivalent to `torch.poisson(input)` where each element is drawn
    /// from Poisson(lambda). Uses Knuth's algorithm for small lambda.
    pub fn tensor_poisson_(
        &mut self,
        tensor: TensorNodeId,
        lambd: f64,
    ) -> Result<(), AutogradError> {
        if lambd < 0.0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "poisson_: lambda must be non-negative",
                },
            )));
        }
        let numel = self.tensor_numel(tensor)?;
        let l = (-lambd).exp();
        let values: Vec<f64> = (0..numel)
            .map(|_| {
                if lambd == 0.0 {
                    return 0.0;
                }
                // Knuth algorithm for Poisson sampling
                let mut k = 0i64;
                let mut p = 1.0;
                loop {
                    k += 1;
                    p *= self.rng.next_f64();
                    if p <= l {
                        break;
                    }
                }
                (k - 1) as f64
            })
            .collect();
        self.update_tensor_values_for_float(tensor, values, INIT_FLOAT_REASON)?;
        self.record_tensor_in_place_operation("poisson_", tensor, Some(format!("lambd={lambd}")));
        Ok(())
    }

    /// Sample from Poisson distribution with element-wise rates.
    ///
    /// Equivalent to `torch.poisson(rate)`. Each output element is sampled
    /// from Poisson(rate[i]). Returns a new tensor with same shape as rate.
    pub fn tensor_poisson(&mut self, rate: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(rate)?;
        let rate_vals = self.tensor_values(rate)?;
        // Per-element independent sub-stream (see `substream_sample`): the Knuth loop's
        // draw count is data-dependent, so parallelize via one seed per element.
        let values = self.rng.substream_sample(rate_vals.len(), |i, rng| {
            let lambd = rate_vals[i];
            if lambd < 0.0 {
                return f64::NAN;
            }
            if lambd == 0.0 {
                return 0.0;
            }
            let l = (-lambd).exp();
            let mut k = 0i64;
            let mut p = 1.0;
            loop {
                k += 1;
                p *= rng.next_f64();
                if p <= l {
                    break;
                }
            }
            (k - 1) as f64
        });
        self.tensor_variable(values, shape, false)
    }

    /// Fill tensor with a constant value.
    pub fn init_constant_(&mut self, tensor: TensorNodeId, val: f64) -> Result<(), AutogradError> {
        let numel = self.tensor_numel(tensor)?;
        let values = vec![val; numel];
        self.update_tensor_values_for_float(tensor, values, INIT_FLOAT_REASON)?;
        self.record_tensor_in_place_operation("init_constant_", tensor, Some(format!("val={val}")));
        Ok(())
    }

    /// Fill tensor with ones.
    pub fn init_ones_(&mut self, tensor: TensorNodeId) -> Result<(), AutogradError> {
        self.init_constant_(tensor, 1.0)
    }

    /// Fill tensor with zeros.
    pub fn init_zeros_(&mut self, tensor: TensorNodeId) -> Result<(), AutogradError> {
        self.init_constant_(tensor, 0.0)
    }

    /// Fill a 2-D tensor with the identity matrix.
    pub fn init_eye_(&mut self, tensor: TensorNodeId) -> Result<(), AutogradError> {
        let shape = self.tensor_shape(tensor)?;
        if shape.len() != 2 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "init_eye_ requires a 2-D tensor",
                },
            )));
        }
        let rows = shape[0];
        let cols = shape[1];
        let numel = rows * cols;
        let mut values = vec![0.0; numel];
        let min_dim = rows.min(cols);
        for i in 0..min_dim {
            values[i * cols + i] = 1.0;
        }
        self.update_tensor_values_for_float(tensor, values, INIT_FLOAT_REASON)?;
        self.record_tensor_in_place_operation("init_eye_", tensor, None);
        Ok(())
    }

    /// Fill a {3,4,5}-D tensor with the Dirac delta function.
    ///
    /// For Conv weight tensors: sets input channel == output channel filters to identity.
    pub fn init_dirac_(
        &mut self,
        tensor: TensorNodeId,
        groups: usize,
    ) -> Result<(), AutogradError> {
        let shape = self.tensor_shape(tensor)?;
        let ndim = shape.len();
        if !(3..=5).contains(&ndim) {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "init_dirac_ requires a 3-D, 4-D, or 5-D tensor",
                },
            )));
        }
        let out_channels = shape[0];
        let in_channels = shape[1];
        if groups == 0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "init_dirac_ requires groups > 0",
                },
            )));
        }
        if out_channels % groups != 0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "init_dirac_ requires groups to evenly divide out_channels",
                },
            )));
        }
        let out_channels_per_group = out_channels / groups;
        let min_dim = out_channels_per_group.min(in_channels);
        let numel = Self::checked_shape_numel(&shape, "init_dirac_: shape volume overflow")?;
        let mut values = vec![0.0; numel];
        let spatial: Vec<usize> = shape[2..].to_vec();
        let spatial_numel =
            Self::checked_shape_numel(&spatial, "init_dirac_: spatial shape overflow")?;

        for g in 0..groups {
            for d in 0..min_dim {
                let oc = g * out_channels_per_group + d;
                let ic = d;
                // Center index in each spatial dimension
                let mut center_offset = 0usize;
                let mut stride = 1usize;
                for &s in spatial.iter().rev() {
                    let offset =
                        Self::checked_mul(s / 2, stride, "init_dirac_: center offset overflow")?;
                    center_offset = center_offset.checked_add(offset).ok_or({
                        AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                            ft_dispatch::DispatchKeyError::IncompatibleSet {
                                reason: "init_dirac_: center offset overflow",
                            },
                        ))
                    })?;
                    stride = Self::checked_mul(stride, s, "init_dirac_: spatial stride overflow")?;
                }
                let channel_stride = Self::checked_mul(
                    in_channels,
                    spatial_numel,
                    "init_dirac_: spatial span overflow",
                )?;
                let base =
                    Self::checked_mul(oc, channel_stride, "init_dirac_: flat index overflow")?;
                let ic_offset =
                    Self::checked_mul(ic, spatial_numel, "init_dirac_: flat index overflow")?;
                let flat_idx = base
                    .checked_add(ic_offset)
                    .and_then(|value| value.checked_add(center_offset))
                    .ok_or({
                        AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                            ft_dispatch::DispatchKeyError::IncompatibleSet {
                                reason: "init_dirac_: flat index overflow",
                            },
                        ))
                    })?;
                if flat_idx < numel {
                    values[flat_idx] = 1.0;
                }
            }
        }
        self.update_tensor_values_for_float(tensor, values, INIT_FLOAT_REASON)?;
        self.record_tensor_in_place_operation(
            "init_dirac_",
            tensor,
            Some(format!("groups={groups}")),
        );
        Ok(())
    }

    /// Xavier (Glorot) uniform initialization.
    ///
    /// Fills with values from U(-a, a) where a = gain * sqrt(6 / (fan_in + fan_out)).
    pub fn init_xavier_uniform_(
        &mut self,
        tensor: TensorNodeId,
        gain: f64,
    ) -> Result<(), AutogradError> {
        let (fan_in, fan_out) = self.calculate_fan_in_and_fan_out(tensor)?;
        let a = gain * (6.0 / (fan_in + fan_out) as f64).sqrt();
        self.init_uniform_(tensor, -a, a)
    }

    /// Xavier (Glorot) normal initialization.
    ///
    /// Fills with values from N(0, std^2) where std = gain * sqrt(2 / (fan_in + fan_out)).
    pub fn init_xavier_normal_(
        &mut self,
        tensor: TensorNodeId,
        gain: f64,
    ) -> Result<(), AutogradError> {
        let (fan_in, fan_out) = self.calculate_fan_in_and_fan_out(tensor)?;
        let std = gain * (2.0 / (fan_in + fan_out) as f64).sqrt();
        self.init_normal_(tensor, 0.0, std)
    }

    /// Compute gain for a given nonlinearity.
    ///
    /// Returns the recommended gain factor for the given activation function.
    #[must_use]
    pub fn calculate_gain(nonlinearity: &str, param: f64) -> f64 {
        match nonlinearity {
            "linear" | "conv1d" | "conv2d" | "conv3d" | "conv_transpose1d" | "conv_transpose2d"
            | "conv_transpose3d" | "sigmoid" => 1.0,
            "tanh" => 5.0 / 3.0,
            "relu" => 2.0_f64.sqrt(),
            "leaky_relu" => (2.0 / (1.0 + param * param)).sqrt(),
            "selu" => 0.75,
            _ => 1.0,
        }
    }

    /// Kaiming (He) uniform initialization.
    ///
    /// Fills with values from U(-bound, bound) where bound = sqrt(3) * gain / sqrt(fan).
    /// `mode` is "fan_in" or "fan_out". `nonlinearity` determines the gain.
    pub fn init_kaiming_uniform_(
        &mut self,
        tensor: TensorNodeId,
        a: f64,
        mode: &str,
        nonlinearity: &str,
    ) -> Result<(), AutogradError> {
        let (fan_in, fan_out) = self.calculate_fan_in_and_fan_out(tensor)?;
        let fan = match mode {
            "fan_in" => fan_in,
            "fan_out" => fan_out,
            _ => {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "init_kaiming_uniform_ mode must be 'fan_in' or 'fan_out'",
                    },
                )));
            }
        };
        let gain = Self::calculate_gain(nonlinearity, a);
        let std = gain / (fan as f64).sqrt();
        let bound = 3.0_f64.sqrt() * std;
        self.init_uniform_(tensor, -bound, bound)
    }

    /// Kaiming (He) normal initialization.
    ///
    /// Fills with values from N(0, std^2) where std = gain / sqrt(fan).
    /// `mode` is "fan_in" or "fan_out". `nonlinearity` determines the gain.
    pub fn init_kaiming_normal_(
        &mut self,
        tensor: TensorNodeId,
        a: f64,
        mode: &str,
        nonlinearity: &str,
    ) -> Result<(), AutogradError> {
        let (fan_in, fan_out) = self.calculate_fan_in_and_fan_out(tensor)?;
        let fan = match mode {
            "fan_in" => fan_in,
            "fan_out" => fan_out,
            _ => {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "init_kaiming_normal_ mode must be 'fan_in' or 'fan_out'",
                    },
                )));
            }
        };
        let gain = Self::calculate_gain(nonlinearity, a);
        let std = gain / (fan as f64).sqrt();
        self.init_normal_(tensor, 0.0, std)
    }

    /// LeCun uniform initialization (for SELU activations).
    ///
    /// Fills with U(-bound, bound) where bound = sqrt(3 / fan_in).
    /// Recommended for SELU activation networks.
    pub fn init_lecun_uniform_(&mut self, tensor: TensorNodeId) -> Result<(), AutogradError> {
        let (fan_in, _) = self.calculate_fan_in_and_fan_out(tensor)?;
        let bound = (3.0 / fan_in as f64).sqrt();
        self.init_uniform_(tensor, -bound, bound)
    }

    /// LeCun normal initialization (for SELU activations).
    ///
    /// Fills with N(0, 1/fan_in). Recommended for SELU activation networks.
    pub fn init_lecun_normal_(&mut self, tensor: TensorNodeId) -> Result<(), AutogradError> {
        let (fan_in, _) = self.calculate_fan_in_and_fan_out(tensor)?;
        let std = (1.0 / fan_in as f64).sqrt();
        self.init_normal_(tensor, 0.0, std)
    }

    /// Orthogonal initialization using QR decomposition.
    ///
    /// Fills a 2-D tensor with a (semi-)orthogonal matrix. For non-square tensors,
    /// uses reduced QR decomposition.
    pub fn init_orthogonal_(
        &mut self,
        tensor: TensorNodeId,
        gain: f64,
    ) -> Result<(), AutogradError> {
        let shape = self.tensor_shape(tensor)?;
        if shape.len() < 2 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "init_orthogonal_ requires at least 2 dimensions",
                },
            )));
        }
        let rows = shape[0];
        let cols =
            Self::checked_shape_numel(&shape[1..], "init_orthogonal_: column shape overflow")?;

        // Generate a random matrix and compute QR
        let flat_shape = if rows >= cols {
            vec![rows, cols]
        } else {
            vec![cols, rows]
        };
        let random_mat = self.randn(flat_shape.clone(), false)?;
        let (q_node, r_node) = self.tensor_linalg_qr(random_mat, true)?;

        // Fix sign: make diagonal of R positive (ensures unique Q)
        let r_values = self.tensor_values(r_node)?;
        let q_values = self.tensor_values(q_node)?;
        let k = flat_shape[1]; // min(rows, cols) after our arrangement
        let n_cols_q = k;

        let mut q_fixed = q_values.clone();
        for j in 0..k {
            let r_diag = r_values[j * k + j]; // R is k x k (or k x cols)
            if r_diag < 0.0 {
                // Negate column j of Q
                for i in 0..flat_shape[0] {
                    q_fixed[i * n_cols_q + j] = -q_fixed[i * n_cols_q + j];
                }
            }
        }

        // If rows < cols, transpose Q
        let final_values = if rows < cols {
            let transposed_len =
                Self::checked_mul(rows, cols, "init_orthogonal_: transpose buffer overflow")?;
            let mut transposed = vec![0.0; transposed_len];
            for i in 0..cols {
                for j in 0..rows {
                    transposed[j * cols + i] = q_fixed[i * rows + j];
                }
            }
            transposed
        } else {
            q_fixed
        };

        // Apply gain and reshape to original tensor shape
        let numel = Self::checked_shape_numel(&shape, "init_orthogonal_: shape volume overflow")?;
        let scaled: Vec<f64> = final_values[..numel].iter().map(|&v| v * gain).collect();
        self.update_tensor_values_for_float(tensor, scaled, INIT_FLOAT_REASON)?;
        self.record_tensor_in_place_operation(
            "init_orthogonal_",
            tensor,
            Some(format!("gain={gain}")),
        );
        Ok(())
    }

    /// Sparse initialization: fill tensor with normally distributed non-zero entries.
    ///
    /// Each column has a fraction `(1 - sparsity)` of non-zero entries.
    pub fn init_sparse_(
        &mut self,
        tensor: TensorNodeId,
        sparsity: f64,
        std: f64,
    ) -> Result<(), AutogradError> {
        let shape = self.tensor_shape(tensor)?;
        if shape.len() != 2 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "init_sparse_ requires a 2-D tensor",
                },
            )));
        }
        if !(0.0..1.0).contains(&sparsity) {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "init_sparse_ requires sparsity in [0, 1)",
                },
            )));
        }
        let rows = shape[0];
        let cols = shape[1];
        let num_zeros_per_col = (sparsity * rows as f64).ceil() as usize;
        let num_zeros_per_col = num_zeros_per_col.min(rows);
        let numel = Self::checked_mul(rows, cols, "init_sparse_: shape volume overflow")?;
        let mut values = vec![0.0; numel];

        // Fill with normal values, then zero out `num_zeros_per_col` entries per column
        for j in 0..cols {
            // Generate normal values for this column
            let mut col_values: Vec<f64> =
                (0..rows).map(|_| std * self.rng.next_normal()).collect();

            // Generate random indices to zero out using Fisher-Yates partial shuffle
            let mut indices: Vec<usize> = (0..rows).collect();
            for k in 0..num_zeros_per_col {
                let swap_idx = k + (self.rng.next_u64() as usize % (rows - k));
                indices.swap(k, swap_idx);
            }
            for &idx in &indices[..num_zeros_per_col] {
                col_values[idx] = 0.0;
            }

            for (i, &val) in col_values.iter().enumerate() {
                values[i * cols + j] = val;
            }
        }

        self.update_tensor_values_for_float(tensor, values, INIT_FLOAT_REASON)?;
        self.record_tensor_in_place_operation(
            "init_sparse_",
            tensor,
            Some(format!("sparsity={sparsity} std={std}")),
        );
        Ok(())
    }

    /// Initialize tensor with truncated normal distribution.
    ///
    /// Samples from N(mean, std^2) but values are clipped to [a, b] and
    /// resampled until within bounds. Common in vision transformers (ViT).
    /// Default bounds are [-2, 2] standard deviations from mean.
    pub fn init_trunc_normal_(
        &mut self,
        tensor: TensorNodeId,
        mean: f64,
        std: f64,
        a: f64,
        b: f64,
    ) -> Result<(), AutogradError> {
        if std <= 0.0 {
            return Err(Self::incompatible_tensor_args(
                "init_trunc_normal_: std must be positive",
            ));
        }
        if a >= b {
            return Err(Self::incompatible_tensor_args(
                "init_trunc_normal_: a must be less than b",
            ));
        }
        let numel = self.tensor_numel(tensor)?;
        let mut values = Vec::with_capacity(numel);
        for _ in 0..numel {
            let mut sample;
            loop {
                sample = mean + std * self.rng.next_normal();
                if sample >= a && sample <= b {
                    break;
                }
            }
            values.push(sample);
        }
        self.update_tensor_values_for_float(tensor, values, INIT_FLOAT_REASON)?;
        self.record_tensor_in_place_operation(
            "init_trunc_normal_",
            tensor,
            Some(format!("mean={mean} std={std} a={a} b={b}")),
        );
        Ok(())
    }

    // ── nan_to_num ──────────────────────────────────────────────────────
    /// Replace NaN, positive infinity, and negative infinity with specified values.
    ///
    /// Equivalent to `torch.nan_to_num(input, nan=0.0, posinf=None, neginf=None)`.
    /// When `posinf`/`neginf` are `None`, they default to the largest/smallest
    /// finite representable value for the input dtype.
    pub fn tensor_nan_to_num(
        &mut self,
        input: TensorNodeId,
        nan: f64,
        posinf: Option<f64>,
        neginf: Option<f64>,
    ) -> Result<TensorNodeId, AutogradError> {
        let meta = self.tensor_tape.tensor_meta(input)?.clone();
        // No-grad fast path: the composed path below is ~9 passes over numel (5 full_like allocs
        // + 2 eq + 2 where + isnan). For contiguous no-grad f32/f64, replace in ONE parallel pass:
        // is_nan ? nan : x==+inf ? posinf : x==-inf ? neginf : x. The four cases are mutually
        // exclusive, the ±inf/NaN comparisons match the composed eq/isnan, and the replacement
        // constants are `posinf_val`/`neginf_val` cast the SAME way full_like casts them -> BIT-EXACT.
        // Grad / half / non-contiguous fall through to the composed (autograd-aware) path.
        if !self.tensor_requires_grad(input)? {
            match meta.dtype() {
                DType::F64 => {
                    let it = self.tensor_tape.tensor(input)?;
                    if it.meta().is_contiguous() {
                        let pv = posinf.unwrap_or(f64::MAX);
                        let nv = neginf.unwrap_or(f64::MIN);
                        let xd = it.contiguous_values()?;
                        use rayon::prelude::*;
                        let out: Vec<f64> = xd
                            .par_iter()
                            .map(|&x| {
                                if x.is_nan() {
                                    nan
                                } else if x == f64::INFINITY {
                                    pv
                                } else if x == f64::NEG_INFINITY {
                                    nv
                                } else {
                                    x
                                }
                            })
                            .collect();
                        return self.tensor_variable(out, meta.shape().to_vec(), false);
                    }
                }
                DType::F32 => {
                    let it = self.tensor_tape.tensor(input)?;
                    if it.meta().is_contiguous() {
                        #[allow(clippy::cast_possible_truncation)]
                        let pv = posinf.unwrap_or(f64::from(f32::MAX)) as f32;
                        #[allow(clippy::cast_possible_truncation)]
                        let nv = neginf.unwrap_or(f64::from(f32::MIN)) as f32;
                        #[allow(clippy::cast_possible_truncation)]
                        let nanf = nan as f32;
                        let xd = it.contiguous_values_f32()?;
                        use rayon::prelude::*;
                        let out: Vec<f32> = xd
                            .par_iter()
                            .map(|&x| {
                                if x.is_nan() {
                                    nanf
                                } else if x == f32::INFINITY {
                                    pv
                                } else if x == f32::NEG_INFINITY {
                                    nv
                                } else {
                                    x
                                }
                            })
                            .collect();
                        return self.tensor_variable_f32(out, meta.shape().to_vec(), false);
                    }
                }
                _ => {}
            }
        }
        let out = match meta.dtype() {
            DType::F64 | DType::F32 | DType::F16 | DType::BF16 => {
                // Autograd-aware path (frankentorch-vlp6 / lczj; f16/bf16 added in
                // frankentorch-u78p — the composed eq/where/isnan now all preserve
                // the half dtype).
                // Compose through tensor_eq + tensor_isnan +
                // tensor_where so gradients flow through non-replaced
                // finite positions and are zero at NaN/±inf positions
                // where the value is replaced by a constant. PyTorch's
                // nan_to_num backward has the same behavior.
                //
                // Order: replace +inf, then -inf, then NaN. The eq
                // checks for ±inf return false against NaN
                // (NaN != anything in IEEE 754), so NaN passes
                // through unchanged until the final isnan pass
                // catches it. Without this order, an isnan-first
                // approach would still work but the eq passes would
                // consume any NaN-replaced value as a finite number
                // and double-process it.
                // Default ±inf replacements are the dtype's largest/smallest
                // finite value. For f16/bf16 these MUST be the half max/min (e.g.
                // f16 65504), not f64::MAX — full_like(f16, f64::MAX) would round to
                // +inf and defeat the replacement. frankentorch-u78p.
                let (default_posinf, default_neginf) = match meta.dtype() {
                    DType::F32 => (f64::from(f32::MAX), f64::from(f32::MIN)),
                    DType::F16 => (Float16::MAX.to_f64(), Float16::MIN.to_f64()),
                    DType::BF16 => (BFloat16::MAX.to_f64(), BFloat16::MIN.to_f64()),
                    _ => (f64::MAX, f64::MIN),
                };
                let posinf_val = posinf.unwrap_or(default_posinf);
                let neginf_val = neginf.unwrap_or(default_neginf);

                let nan_const = self.full_like(input, nan, false)?;
                let posinf_const = self.full_like(input, posinf_val, false)?;
                let neginf_const = self.full_like(input, neginf_val, false)?;
                let posinf_compare = self.full_like(input, f64::INFINITY, false)?;
                let neginf_compare = self.full_like(input, f64::NEG_INFINITY, false)?;

                let is_posinf = self.tensor_eq(input, posinf_compare)?;
                let after_posinf = self.tensor_where(is_posinf, posinf_const, input)?;
                let is_neginf = self.tensor_eq(after_posinf, neginf_compare)?;
                let after_neginf = self.tensor_where(is_neginf, neginf_const, after_posinf)?;
                let is_nan = self.tensor_isnan(after_neginf)?;
                let out = self.tensor_where(is_nan, nan_const, after_neginf)?;

                self.runtime.ledger_mut().record(
                    EvidenceKind::Dispatch,
                    format!(
                        "nan_to_num input={} out={} dtype={:?} nan={nan} posinf={posinf_val} neginf={neginf_val} (autograd)",
                        input.0,
                        out.0,
                        meta.dtype()
                    ),
                );
                out
            }
            _ => {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: NAN_TO_NUM_FLOAT_REASON,
                    },
                )));
            }
        };
        Ok(out)
    }

    // ── logaddexp ───────────────────────────────────────────────────────
    /// Numerically stable `log(exp(a) + exp(b))`.
    ///
    /// Equivalent to `torch.logaddexp(input, other)`.
    /// Autograd-tracked: composed from existing tracked ops.
    pub fn tensor_logaddexp(
        &mut self,
        a: TensorNodeId,
        b: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // No-grad fast path: the finite-case path below CLONES both operands for a finite
        // check (tensor_values_lossy_f64 x2) then COMPOSES ~9 ops (max+sub x2+exp x2+add+log+
        // add) — measured 7.47x SLOWER than torch, while logaddexp2 (which routes straight to
        // the parallel single-pass `_custom`) is already 3x FASTER. `_custom`'s
        // stable_logaddexp_value handles NaN/±inf identically, so with grad off route equal-
        // shape f64 directly through it (one parallel pass, save-skipped). Bit-identical to
        // the composed finite path (same m + ((a-m).exp()+(b-m).exp()).ln()).
        if !self.tensor_requires_grad(a)?
            && !self.tensor_requires_grad(b)?
            && self.tensor_dtype(a)? == DType::F64
            && self.tensor_dtype(b)? == DType::F64
            && self.tensor_shape(a)? == self.tensor_shape(b)?
        {
            return self.tensor_logaddexp_custom(a, b, false);
        }
        // F32 sibling. Routing f32 through `_custom` (generic apply_function) is slow because
        // the tape UPCASTS both f32 inputs to f64 (2x 128MB) before the parallel map = ~215ms,
        // ~12x SLOWER than torch (the f64 path skips the upcast and is 3x FASTER). The composed
        // finite path is the same upcast x2 + ~9 separate tape ops. Instead read the f32 inputs
        // BORROWED and compute `stable_logaddexp_value(x as f64, y as f64) as f32` in one
        // parallel pass (per-element f64 math in-register, narrowed to f32). Bit-identical to
        // the f64-routed-then-narrowed `_custom` (same value), and logaddexp is a TOLERANCE op
        // (1e-9 golden vs torch — exp/log are libm-vs-SLEEF), so this is within tol. f32
        // contiguous equal-shape no-grad only; otherwise fall through to the composed path.
        if !self.tensor_requires_grad(a)?
            && !self.tensor_requires_grad(b)?
            && self.tensor_dtype(a)? == DType::F32
            && self.tensor_dtype(b)? == DType::F32
            && self.tensor_shape(a)? == self.tensor_shape(b)?
        {
            let built = {
                let ta = self.tensor_tape.tensor(a)?;
                let tb = self.tensor_tape.tensor(b)?;
                if ta.meta().is_contiguous() && tb.meta().is_contiguous() {
                    let av = ta.contiguous_values_f32()?;
                    let bv = tb.contiguous_values_f32()?;
                    if av.len() == bv.len() {
                        use rayon::prelude::*;
                        let out: Vec<f32> = if av.len() >= PARALLEL_ELEMENTWISE_MIN {
                            av.par_iter()
                                .zip(bv.par_iter())
                                .map(|(&x, &y)| {
                                    Self::stable_logaddexp_value(x as f64, y as f64) as f32
                                })
                                .collect()
                        } else {
                            av.iter()
                                .zip(bv.iter())
                                .map(|(&x, &y)| {
                                    Self::stable_logaddexp_value(x as f64, y as f64) as f32
                                })
                                .collect()
                        };
                        Some(out)
                    } else {
                        None
                    }
                } else {
                    None
                }
            };
            if let Some(out) = built {
                let shape = self.tensor_shape(a)?;
                return self.tensor_variable_f32(out, shape, false);
            }
        }
        // F64 fast path (asymmetric-dtype mirror of the F32 path above): the generic path below
        // CLONES BOTH operands via `tensor_values_lossy_f64` then COMPOSES ~9 tape ops (max, sub x2,
        // exp x2, add, log, add) — each materializing an intermediate tensor. Borrow both contiguous
        // f64 buffers + fuse into ONE parallel pass. BIT-EXACT for FINITE inputs: `stable_logaddexp_
        // value` does the IDENTICAL f64 ops (max/sub/exp/add/ln, same libm) with no f32<->f64 cast
        // (unlike the tolerance-gated F32 path). Any non-finite element falls through to the generic
        // path (which routes non-finite specially), preserving its exact behavior. frankentorch (BlackThrush).
        if !self.tensor_requires_grad(a)?
            && !self.tensor_requires_grad(b)?
            && self.tensor_dtype(a)? == DType::F64
            && self.tensor_dtype(b)? == DType::F64
            && self.tensor_shape(a)? == self.tensor_shape(b)?
        {
            let built = {
                let ta = self.tensor_tape.tensor(a)?;
                let tb = self.tensor_tape.tensor(b)?;
                if ta.meta().is_contiguous() && tb.meta().is_contiguous() {
                    let av = ta.contiguous_values()?;
                    let bv = tb.contiguous_values()?;
                    if av.len() == bv.len() {
                        use rayon::prelude::*;
                        // All-finite gate: only then is the fused single-pass provably bit-identical
                        // to the compose (whose non-finite handling routes through a custom path).
                        if av.par_iter().any(|v| !v.is_finite())
                            || bv.par_iter().any(|v| !v.is_finite())
                        {
                            None
                        } else {
                            let out: Vec<f64> = if av.len() >= PARALLEL_ELEMENTWISE_MIN {
                                av.par_iter()
                                    .zip(bv.par_iter())
                                    .map(|(&x, &y)| Self::stable_logaddexp_value(x, y))
                                    .collect()
                            } else {
                                av.iter()
                                    .zip(bv.iter())
                                    .map(|(&x, &y)| Self::stable_logaddexp_value(x, y))
                                    .collect()
                            };
                            Some(out)
                        }
                    } else {
                        None
                    }
                } else {
                    None
                }
            };
            if let Some(out) = built {
                let shape = self.tensor_shape(a)?;
                return self.tensor_variable(out, shape, false);
            }
        }
        // Lossy f64 reads (storage().to_vec() is F64-only) so f32 inputs are
        // accepted; the finite-check only needs the magnitudes, and the actual
        // logaddexp math below composes through dtype-preserving primitives, so
        // an f32 input keeps f32 (torch parity). frankentorch-fk5l.
        let a_shape_vec = self.tensor_shape(a)?;
        let b_shape = self.tensor_shape(b)?;
        // torch.logaddexp broadcasts its operands; expand to the common shape so
        // the finite check and the broadcasting compose below see equal shapes
        // (a non-broadcastable mismatch still errors via broadcast_shape).
        let (a, b) = if a_shape_vec == b_shape {
            (a, b)
        } else {
            let out_shape = Self::broadcast_shape(&a_shape_vec, &b_shape)?;
            (
                self.tensor_broadcast_to(a, out_shape.clone())?,
                self.tensor_broadcast_to(b, out_shape)?,
            )
        };
        let a_vals = self.tensor_values_lossy_f64(a)?;
        let b_vals = self.tensor_values_lossy_f64(b)?;
        if a_vals
            .iter()
            .chain(b_vals.iter())
            .any(|value| !value.is_finite())
        {
            let out = self.tensor_logaddexp_custom(a, b, false)?;
            self.runtime.ledger_mut().record(
                EvidenceKind::Dispatch,
                format!("logaddexp a={} b={} out={} nonfinite=true", a.0, b.0, out.0),
            );
            return Ok(out);
        }

        // max(a, b) + log(exp(a - max(a,b)) + exp(b - max(a,b)))
        // = max(a,b) + log1p(exp(-|a - b|))
        let m = self.tensor_max(a, b)?;
        let a_shifted = self.tensor_sub(a, m)?;
        let b_shifted = self.tensor_sub(b, m)?;
        let exp_a = self.tensor_exp(a_shifted)?;
        let exp_b = self.tensor_exp(b_shifted)?;
        let sum_exp = self.tensor_add(exp_a, exp_b)?;
        let log_sum = self.tensor_log(sum_exp)?;
        self.tensor_add(m, log_sum)
    }

    // ── logaddexp2 ──────────────────────────────────────────────────────
    /// Numerically stable `log2(2^a + 2^b)`.
    ///
    /// Equivalent to `torch.logaddexp2(input, other)`.
    pub fn tensor_logaddexp2(
        &mut self,
        a: TensorNodeId,
        b: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // Direct computation: log2(2^a + 2^b)
        // = max(a,b) + log2(2^(a-max) + 2^(b-max))
        // = max(a,b) + log2(exp2(a-max) + exp2(b-max))
        let a_shape = {
            let t = self.tensor_tape.tensor(a)?;
            t.meta().shape().to_vec()
        };
        let b_shape = {
            let t = self.tensor_tape.tensor(b)?;
            t.meta().shape().to_vec()
        };

        // torch.logaddexp2 broadcasts its operands; expand to the common shape
        // before the (equal-shape) custom compute path.
        let (a, b) = if a_shape == b_shape {
            (a, b)
        } else {
            let out_shape = Self::broadcast_shape(&a_shape, &b_shape)?;
            (
                self.tensor_broadcast_to(a, out_shape.clone())?,
                self.tensor_broadcast_to(b, out_shape)?,
            )
        };

        let out = self.tensor_logaddexp_custom(a, b, true)?;
        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!("logaddexp2 a={} b={} out={}", a.0, b.0, out.0),
        );
        Ok(out)
    }

    /// In-place logaddexp: target = log(exp(target) + exp(other)).
    pub fn tensor_logaddexp_(
        &mut self,
        target: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<(), AutogradError> {
        self.validate_tensor_in_place_target(target)?;
        // F64 borrow+parallel fast path (stable logaddexp = exp+ln, compute-heavy).
        // frankentorch-inplace-binary-fastpath.
        if self.try_inplace_binary_f64(target, other, "logaddexp_", |a, b| {
            Self::stable_logaddexp_value(a, b)
        })? {
            return Ok(());
        }
        let target_vals = self.tensor_values_lossy_f64(target)?;
        let other_vals = self.tensor_values_lossy_f64(other)?;
        if target_vals.len() != other_vals.len() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: self.tensor_shape(target)?,
                    rhs: self.tensor_shape(other)?,
                },
            )));
        }
        let result: Vec<f64> = target_vals
            .iter()
            .zip(other_vals.iter())
            .map(|(&a, &b)| Self::stable_logaddexp_value(a, b))
            .collect();
        self.update_tensor_values_for_float(target, result, INPLACE_FLOAT_REASON)?;
        self.record_tensor_in_place_operation("logaddexp_", target, None);
        Ok(())
    }

    /// In-place logaddexp2: target = log2(2^target + 2^other).
    pub fn tensor_logaddexp2_(
        &mut self,
        target: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<(), AutogradError> {
        self.validate_tensor_in_place_target(target)?;
        // F64 borrow+parallel fast path (stable logaddexp2 = exp2+log2, compute-heavy).
        // frankentorch-inplace-binary-fastpath.
        if self.try_inplace_binary_f64(target, other, "logaddexp2_", |a, b| {
            Self::stable_logaddexp2_value(a, b)
        })? {
            return Ok(());
        }
        let target_vals = self.tensor_values_lossy_f64(target)?;
        let other_vals = self.tensor_values_lossy_f64(other)?;
        if target_vals.len() != other_vals.len() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: self.tensor_shape(target)?,
                    rhs: self.tensor_shape(other)?,
                },
            )));
        }
        let result: Vec<f64> = target_vals
            .iter()
            .zip(other_vals.iter())
            .map(|(&a, &b)| Self::stable_logaddexp2_value(a, b))
            .collect();
        self.update_tensor_values_for_float(target, result, INPLACE_FLOAT_REASON)?;
        self.record_tensor_in_place_operation("logaddexp2_", target, None);
        Ok(())
    }

    fn stable_logaddexp_value(a: f64, b: f64) -> f64 {
        if a.is_nan() || b.is_nan() {
            return f64::NAN;
        }
        let m = a.max(b);
        if m.is_infinite() {
            return m;
        }
        m + ((a - m).exp() + (b - m).exp()).ln()
    }

    fn stable_logaddexp2_value(a: f64, b: f64) -> f64 {
        if a.is_nan() || b.is_nan() {
            return f64::NAN;
        }
        let m = a.max(b);
        if m.is_infinite() {
            return m;
        }
        m + (2.0_f64.powf(a - m) + 2.0_f64.powf(b - m)).log2()
    }

    fn logaddexp_backward_weight(input: f64, output: f64, base2: bool) -> f64 {
        if base2 {
            2.0_f64.powf(input - output)
        } else {
            (input - output).exp()
        }
    }

    fn tensor_logaddexp_custom(
        &mut self,
        a: TensorNodeId,
        b: TensorNodeId,
        base2: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_apply_function(
            &[a, b],
            move |ctx, inputs| {
                let (a_vals, a_shape) = inputs[0];
                let (b_vals, b_shape) = inputs[1];
                if a_shape != b_shape {
                    // Migrate to ShapeMismatch (frankentorch-c991).
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                        ft_kernel_cpu::KernelError::ShapeMismatch {
                            lhs: a_shape.to_vec(),
                            rhs: b_shape.to_vec(),
                        },
                    )));
                }
                // Skip the two backward-only clones (a_vals + b_vals = 2x numel)
                // in no-grad inference: apply_function returns a plain Leaf and
                // discards ctx unless an input needs grad, so these saves are
                // provably dead work there. Grad path byte-for-byte unchanged.
                // frankentorch-xtziq.
                if ctx.needs_input_grad().iter().any(|&g| g) {
                    ctx.save_for_backward(a_vals.to_vec(), a_shape.to_vec());
                    ctx.save_for_backward(b_vals.to_vec(), b_shape.to_vec());
                }
                // Elementwise transcendental (powf/log2 or exp/ln per element) —
                // fan the independent lanes over Rayon. par_iter().zip().collect()
                // preserves index order => bit-for-bit identical to the serial map.
                let values = par_zip_map_f64(a_vals, b_vals, |ai, bi| {
                    if base2 {
                        Self::stable_logaddexp2_value(ai, bi)
                    } else {
                        Self::stable_logaddexp_value(ai, bi)
                    }
                });
                Ok((values, a_shape.to_vec()))
            },
            move |ctx, grad_outputs| {
                let grad_out = grad_outputs[0];
                let a_vals = &ctx.saved_tensors()[0];
                let b_vals = &ctx.saved_tensors()[1];
                if grad_out.len() != a_vals.len() || a_vals.len() != b_vals.len() {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "logaddexp backward: incoming gradient length mismatch",
                        },
                    )));
                }
                let mut grad_a = Vec::with_capacity(a_vals.len());
                let mut grad_b = Vec::with_capacity(b_vals.len());
                for ((&ai, &bi), &go) in a_vals.iter().zip(b_vals.iter()).zip(grad_out.iter()) {
                    let out = if base2 {
                        Self::stable_logaddexp2_value(ai, bi)
                    } else {
                        Self::stable_logaddexp_value(ai, bi)
                    };
                    grad_a.push(go * Self::logaddexp_backward_weight(ai, out, base2));
                    grad_b.push(go * Self::logaddexp_backward_weight(bi, out, base2));
                }
                let needs_grad = ctx.needs_input_grad();
                Ok(vec![
                    needs_grad[0].then_some(grad_a),
                    needs_grad[1].then_some(grad_b),
                ])
            },
        )
    }

    // ── xlogy ───────────────────────────────────────────────────────────
    /// Compute `x * log(y)` with the convention that `0 * log(y) = 0`.
    ///
    /// Equivalent to `torch.xlogy(input, other)` / `torch.special.xlogy`.
    ///
    /// Composes through tensor_log + tensor_mul + tensor_eq +
    /// tensor_where so the autograd tape carries gradients through
    /// both x and y. Previously this extracted tensor_values and
    /// rebuilt a requires_grad=false leaf, severing the tape on
    /// tracked inputs (same severed-autograd pattern recently fixed
    /// across the activation / index_* / scatter_* family). Tracked
    /// under frankentorch-1tax.
    ///
    /// The `0 * log(y) = 0` convention is implemented via
    /// `where(x == 0, 0, x * log(y))` — when x is exactly 0, the
    /// output is 0 even if log(y) is -inf or NaN. tensor_where
    /// blocks gradients through the masked-out branch automatically.
    pub fn tensor_xlogy(
        &mut self,
        x: TensorNodeId,
        y: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let x_shape = self.tensor_shape(x)?;
        let y_shape = self.tensor_shape(y)?;
        if x_shape != y_shape {
            // Migrate to ShapeMismatch (frankentorch-c991).
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: x_shape,
                    rhs: y_shape,
                },
            )));
        }
        // f32-native fast path (same closure as the f64 path below): the f32 case fell to the
        // composed path (~8 tape passes, 5.17x SLOWER than torch). `(xi as f64).ln() as f32`
        // matches the f64-then-narrow value the composed f32 path produces (FT's tensor_log
        // routes f32 through f64), so this is bit-identical to current f32 behaviour.
        if let Some(out) = self.try_f32_binary_native(x, y, |xi, yi| {
            if xi == 0.0 && !yi.is_nan() {
                0.0
            } else {
                xi * yi.ln()
            }
        })? {
            return Ok(out);
        }
        // No-grad fast path: the composed path below (log + mul + full_like + eq + isnan +
        // eq + mul + where = ~8 passes) measured 4.32x SLOWER than torch. For no-grad
        // contiguous f64, borrow both and compute `xlogy(x,y) = (x==0 && !isnan(y)) ? 0 :
        // x*ln(y)` in ONE parallel pass. Bit-exact with the composed path (same libm ln, same
        // x*ln(y) product, same x==0-&&-!isnan(y) mask incl. x=0/y=NaN -> NaN). f32 / grad /
        // non-contiguous fall through.
        if !self.tensor_requires_grad(x)?
            && !self.tensor_requires_grad(y)?
            && self.tensor_dtype(x)? == DType::F64
            && self.tensor_dtype(y)? == DType::F64
        {
            let built = {
                let xt = self.tensor_tape.tensor(x)?;
                let yt = self.tensor_tape.tensor(y)?;
                if xt.meta().is_contiguous() && yt.meta().is_contiguous() {
                    let xd = xt.contiguous_values()?;
                    let yd = yt.contiguous_values()?;
                    if xd.len() == yd.len() {
                        use rayon::prelude::*;
                        let out: Vec<f64> = xd
                            .par_iter()
                            .zip(yd.par_iter())
                            .map(|(&xi, &yi)| {
                                if xi == 0.0 && !yi.is_nan() {
                                    0.0
                                } else {
                                    xi * yi.ln()
                                }
                            })
                            .collect();
                        Some(out)
                    } else {
                        None
                    }
                } else {
                    None
                }
            };
            if let Some(out) = built {
                return self.tensor_variable(out, x_shape, false);
            }
        }
        let log_y = self.tensor_log(y)?;
        let prod = self.tensor_mul(x, log_y)?;
        // Single zeros tensor shared between the eq mask and the
        // where-true branch (frankentorch-rbhb).
        // full_like(x) so an f32 input keeps f32 and tensor_eq matches dtype
        // (torch xlogy(f32) -> f32). frankentorch-fk5l.
        let zeros = self.full_like(x, 0.0, false)?;
        let mask_x_zero = self.tensor_eq(x, zeros)?;
        // xlogy(0, y) short-circuits to 0 ONLY when y is not NaN. scipy
        // and torch both leave xlogy(0, NaN) = 0*log(NaN) = NaN, so the
        // mask is (x == 0 && !isnan(y)), mirroring tensor_xlog1py
        // (frankentorch-duf7). tensor_isnan emits exact 0.0/1.0, so
        // (isnan_y == 0) is the bit-exact boolean negation.
        let isnan_y = self.tensor_isnan(y)?;
        let not_isnan_y = self.tensor_eq(isnan_y, zeros)?;
        let mask = self.tensor_mul(mask_x_zero, not_isnan_y)?;
        let out = self.tensor_where(mask, zeros, prod)?;
        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!("xlogy x={} y={} out={}", x.0, y.0, out.0),
        );
        Ok(out)
    }

    /// Alias for `tensor_xlogy`. Equivalent to `torch.special.xlogy`.
    pub fn tensor_special_xlogy(
        &mut self,
        x: TensorNodeId,
        y: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_xlogy(x, y)
    }

    /// In-place xlogy: target = target * log(other), with 0 * log(y) = 0 when y is not NaN.
    pub fn tensor_xlogy_(
        &mut self,
        target: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<(), AutogradError> {
        self.validate_tensor_in_place_target(target)?;
        if self.try_inplace_binary_f64(target, other, "xlogy_", |x, y| {
            if x == 0.0 && !y.is_nan() {
                0.0
            } else {
                x * y.ln()
            }
        })? {
            return Ok(());
        }
        let target_vals = self.tensor_values_lossy_f64(target)?;
        let other_vals = self.tensor_values_lossy_f64(other)?;
        if target_vals.len() != other_vals.len() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: self.tensor_shape(target)?,
                    rhs: self.tensor_shape(other)?,
                },
            )));
        }
        let result: Vec<f64> = target_vals
            .iter()
            .zip(other_vals.iter())
            .map(|(&x, &y)| {
                if x == 0.0 && !y.is_nan() {
                    0.0
                } else {
                    x * y.ln()
                }
            })
            .collect();
        self.update_tensor_values_for_float(target, result, INPLACE_FLOAT_REASON)?;
        self.record_tensor_in_place_operation("xlogy_", target, None);
        Ok(())
    }

    /// In-place xlog1py: target = target * log(1 + other).
    ///
    /// Equivalent to `torch.Tensor.xlog1py_(target, other)`.
    /// Special case: 0 * log(1 + y) = 0 regardless of y (even if y == -1).
    pub fn tensor_xlog1py_(
        &mut self,
        target: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<(), AutogradError> {
        self.validate_tensor_in_place_target(target)?;
        let result = self.tensor_xlog1py(target, other)?;
        let result_vals = self.tensor_values(result)?;
        self.update_tensor_values_for_float(target, result_vals, INPLACE_FLOAT_REASON)?;
        self.record_tensor_in_place_operation("xlog1py_", target, None);
        Ok(())
    }

    // ── torch.special functions ──────────────────────────────────────────

    /// Element-wise sigmoid (expit) function: 1 / (1 + exp(-x)).
    ///
    /// Equivalent to `torch.special.expit(input)`.
    pub fn tensor_expit(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        // expit is identical to sigmoid
        self.tensor_sigmoid(input)
    }

    /// Element-wise logit function: log(x / (1 - x)).
    ///
    /// Equivalent to `torch.special.logit(input, eps)`.
    /// Values are clamped to [eps, 1 - eps] if eps is provided.
    ///
    /// Composes through tensor_clamp / tensor_sub / tensor_div /
    /// tensor_log so the autograd tape carries gradients through the
    /// input. Previously this extracted tensor_values and rebuilt a
    /// requires_grad=false leaf, severing the tape silently — same
    /// pattern recently fixed across the activation / index_* /
    /// scatter_* family. Tracked under frankentorch-1tax.
    pub fn tensor_logit(
        &mut self,
        input: TensorNodeId,
        eps: Option<f64>,
    ) -> Result<TensorNodeId, AutogradError> {
        // f32-native fast path (eps=None): the f32 branch below UPCASTS to f64 (to_dtype) +
        // composes ~4 tape ops + narrows = ~7.4x SLOWER than torch. `try_f32_unary_native`
        // computes `(x as f64 / (1 - x as f64)).ln() as f32` directly — BIT-IDENTICAL to the
        // current f32 behaviour (which already routes through the f64 fast path then narrows).
        if eps.is_none() {
            if let Some(out) = self.try_f32_unary_native(input, |x| (x / (1.0 - x)).ln())? {
                return Ok(out);
            }
        }
        // f32/half: compute in f64 then cast back (the full()-built `1` constant
        // is F64 and upcasts the input). torch keeps the input dtype. frankentorch-x9yuq.
        let dt = self.tensor_dtype(input)?;
        if dt != DType::F64 {
            let in64 = self.tensor_to_dtype(input, DType::F64)?;
            let out64 = self.tensor_logit(in64, eps)?;
            return self.tensor_to_dtype(out64, dt);
        }
        // No-grad fast path (eps=None): the composed path below (full + sub + div + log =
        // ~4 passes) measured 3.27x SLOWER than torch. For no-grad contiguous f64, borrow the
        // input and compute logit(x) = ln(x/(1-x)) in one gated native pass. Bit-exact with
        // the composed path (same 1-x, x/(1-x), libm ln). The eps clamp variant / grad /
        // non-contiguous fall through.
        if eps.is_none() && !self.tensor_requires_grad(input)? {
            let built = {
                let it = self.tensor_tape.tensor(input)?;
                if it.meta().is_contiguous() {
                    let xd = it.contiguous_values()?;
                    let out: Vec<f64> = if xd.len() >= LOGIT_F64_PARALLEL_MIN {
                        use rayon::prelude::*;
                        xd.par_iter().map(|&x| (x / (1.0 - x)).ln()).collect()
                    } else {
                        xd.iter().map(|&x| (x / (1.0 - x)).ln()).collect()
                    };
                    Some(out)
                } else {
                    None
                }
            };
            if let Some(out) = built {
                let shape = self.tensor_shape(input)?;
                return self.tensor_variable(out, shape, false);
            }
        }
        let shape = self.tensor_shape(input)?;
        let clamped = if let Some(e) = eps {
            self.tensor_clamp(input, e, 1.0 - e)?
        } else {
            input
        };
        // 1 - x via a constant tensor + tensor_sub. Using
        // tensor_sub_scalar would also work; the explicit
        // construction keeps autograd tracking on `clamped`.
        let ones = self.full(shape, 1.0, false)?;
        let one_minus_x = self.tensor_sub(ones, clamped)?;
        let ratio = self.tensor_div(clamped, one_minus_x)?;
        let out = self.tensor_log(ratio)?;
        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!("logit in={} out={}", input.0, out.0),
        );
        Ok(out)
    }

    /// Alias for tensor_logit for torch.special.logit parity.
    ///
    /// Tracked under frankentorch-hcy0.
    pub fn tensor_special_logit(
        &mut self,
        input: TensorNodeId,
        eps: Option<f64>,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_logit(input, eps)
    }

