    /// Alias for tensor_digamma for torch.special.psi parity.
    ///
    /// psi(x) = digamma(x) = d/dx ln(Gamma(x))
    /// Tracked under frankentorch-h8ji.
    pub fn tensor_psi(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        self.tensor_digamma(input)
    }

    /// Element-wise inverse error function.
    ///
    /// Equivalent to `torch.special.erfinv(input)`.
    /// Uses a rational approximation (Winitzki, 2008).
    ///
    /// Wraps erfinv_approx in a tensor_apply_function with the
    /// analytical backward
    ///     d/dx erfinv(x) = sqrt(pi)/2 * exp(erfinv(x)^2)
    /// which is best computed from the forward output y, not from x
    /// (saves a redundant erfinv evaluation in the backward pass).
    /// Tracked under frankentorch-1tax — same severed-autograd
    /// pattern recently fixed for gammaln / digamma / polygamma /
    /// multigammaln.
    pub fn tensor_erfinv(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        // f32-native fast path (no apply_function f32->f64 upcast = ~16x SLOWER). Same value
        // (erfinv_approx in f64, narrowed) = bit-identical. frankentorch-specf32.
        if let Some(out) = self.try_f32_unary_native(input, erfinv_approx)? {
            return Ok(out);
        }
        // No-grad f64 fast path (sibling of the f32 one): the apply_function path below par_maps
        // erfinv_approx BUT also `values.clone()`s the 16M output into save_for_backward (a 128MB
        // clone even when no grad is needed) and builds a tape node. For no-grad, compute the same
        // par_map via try_f64_unary_native and return a leaf — no node, no backward-save clone.
        // Bit-exact (identical erfinv_approx). frankentorch-erfinv-f64-nograd.
        if let Some(out) = self.try_f64_unary_native(input, erfinv_approx)? {
            // Dispatch-evidence contract: this no-grad fast path returns BEFORE the end-of-fn
            // record, so emit the same Dispatch entry here (mirrors gammaln fix 70efa262).
            self.runtime.ledger_mut().record(
                EvidenceKind::Dispatch,
                format!("erfinv in={} out={}", input.0, out.0),
            );
            return Ok(out);
        }
        let out = self.tensor_apply_function_with_create_graph(
            &[input],
            |ctx, inputs| {
                let (vals, shape) = inputs[0];
                let values: Vec<f64> = par_map_f64(vals, erfinv_approx);
                // Save y (= erfinv(x)) for the backward; the
                // analytical derivative is expressed in terms of y.
                ctx.save_for_backward(values.clone(), shape.to_vec());
                Ok((values, shape.to_vec()))
            },
            |ctx, grad_outputs| {
                let grad_out = grad_outputs[0];
                let saved = ctx.saved_tensors();
                let y_vals = &saved[0];
                if grad_out.len() != y_vals.len() {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "erfinv backward: incoming gradient length mismatch",
                        },
                    )));
                }
                let half_sqrt_pi = std::f64::consts::PI.sqrt() * 0.5;
                let grad_in: Vec<f64> =
                    par_zip_map_f64(y_vals, grad_out, |y, go| go * half_sqrt_pi * (y * y).exp());
                Ok(vec![Some(grad_in)])
            },
            // create_graph backward: d/dx erfinv(x) = (√π/2)·exp(y²) with y = erfinv(x).
            // Rebuild y as a DIFFERENTIABLE node (first-order backward = (√π/2)·exp(y²),
            // i.e. dy/dx) then assemble the derivative from differentiable tape ops, so
            // a second backward yields erfinv''(x) = 2·(√π/2)²·y·exp(2y²). Raw first-order
            // backward above is untouched. 1avc3.
            |_ctx, grad_outs, inputs, tape| {
                let mode = ft_core::ExecutionMode::Strict;
                let c = std::f64::consts::PI.sqrt() * 0.5;
                let y = tape.apply_function(
                    &[inputs[0]],
                    |ctx, inp| {
                        let (vals, shape) = inp[0];
                        let yv = par_map_f64(vals, erfinv_approx);
                        ctx.save_for_backward(yv.clone(), shape.to_vec());
                        Ok((yv, shape.to_vec()))
                    },
                    move |ctx, gouts| {
                        let g = gouts[0];
                        let yv = &ctx.saved_tensors()[0];
                        Ok(vec![Some(par_zip_map_f64(yv, g, |y, go| {
                            go * c * (y * y).exp()
                        }))])
                    },
                )?;
                let y2 = tape.mul(y, y, mode)?.0;
                let ey2 = tape.exp(y2, mode)?.0;
                let deriv = tape.mul_scalar(ey2, c)?.0;
                let grad_in = tape.mul(grad_outs[0], deriv, mode)?.0;
                Ok(vec![Some(grad_in)])
            },
        )?;
        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!("erfinv in={} out={}", input.0, out.0),
        );
        Ok(out)
    }

    /// Alias for `tensor_erfinv`. Equivalent to `torch.special.erfinv`.
    pub fn tensor_special_erfinv(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_erfinv(input)
    }

    /// Inverse of the complementary error function.
    ///
    /// erfcinv(erfc(x)) = x. Computed as erfinv(1 - x).
    pub fn tensor_erfcinv(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        let ones = self.full(shape, 1.0, false)?;
        let one_minus_x = self.tensor_sub(ones, input)?;
        self.tensor_erfinv(one_minus_x)
    }

    /// Element-wise natural logarithm of the absolute value of the gamma function.
    ///
    /// Equivalent to `torch.special.gammaln(input)` / `torch.lgamma(input)`.
    ///
    /// Wraps the libm `lgamma` (via `lgamma_approx`) in a custom
    /// `tensor_apply_function` so the autograd tape carries gradients
    /// through the input. The analytical derivative is
    /// `d/dx lgamma(x) = digamma(x)`, computed via `digamma_approx`
    /// in the backward closure. Tracked under frankentorch-1tax —
    /// previously this had a fail-loud guard rejecting tracked
    /// inputs because the body just computed values and rebuilt a
    /// requires_grad=false leaf.
    /// `torch.lgamma(input)` parity alias for `tensor_gammaln`.
    ///
    /// torch exposes both `torch.lgamma` and `torch.special.gammaln`
    /// as the same op; ft-api had only `tensor_gammaln`. Code ported
    /// from PyTorch using `torch.lgamma` fails to compile without
    /// this alias. Tracked under frankentorch-ae41.
    pub fn tensor_lgamma(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        self.tensor_gammaln(input)
    }

    /// Alias for gammaln matching torch.special.gammaln.
    pub fn tensor_special_gammaln(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_gammaln(input)
    }

    pub fn tensor_gammaln(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        use rayon::prelude::*;
        // f32-native fast path: the path below reads f64 values (upcasts f32->f64 = 128MB) =
        // ~5x SLOWER for f32. Same value (lgamma_approx in f64, narrowed) = bit-identical.
        if let Some(out) = self.try_f32_unary_native(input, lgamma_approx)? {
            // Preserve the dispatch-evidence contract: these fast paths return BEFORE the
            // shared record at the end of this fn (commit 1da0c35c's borrow fast path dropped
            // it, leaving fast_evidence.last() = the session-init Policy entry). Record here
            // so the no-grad fast path emits the same "gammaln in/out" Dispatch entry as the
            // slow/tracked paths. Value-identical either way. frankentorch (BlackThrush).
            self.runtime.ledger_mut().record(
                EvidenceKind::Dispatch,
                format!("gammaln in={} out={}", input.0, out.0),
            );
            return Ok(out);
        }
        // No-grad f64 borrow fast path: the no-grad path below CLONES the input via
        // contiguous_values_as_f64().to_vec() / tensor_values; try_f64_unary_native BORROWS it.
        // Bit-exact (same lgamma_approx). frankentorch-lgamma_approx-f64-borrow.
        if let Some(out) = self.try_f64_unary_native(input, lgamma_approx)? {
            self.runtime.ledger_mut().record(
                EvidenceKind::Dispatch,
                format!("gammaln in={} out={}", input.0, out.0),
            );
            return Ok(out);
        }
        // lgamma/digamma are compute-bound per element (libm::lgamma; digamma
        // recurrence + asymptotic series), so evaluate large tensors across the
        // rayon pool. Pure per-element maps -> bit-for-bit identical to serial
        // (PARALLEL_ELEMENTWISE_MIN gate avoids thread overhead on small tensors).
        let out = if !self.tensor_tape.tensor_requires_grad(input)?
            || !self.tensor_tape.is_grad_enabled()
        {
            let (meta, values) = {
                let tensor = self.tensor_tape.tensor(input)?;
                let meta = tensor.meta().clone();
                let vals = tensor.contiguous_values_as_f64()?;
                (meta, par_map_f64(&vals, lgamma_approx))
            };
            let dtype = meta.dtype();
            let output = match dtype {
                DType::F64 => DenseTensor::from_storage(meta, values)?,
                DType::F32 => DenseTensor::from_storage_f32(
                    meta,
                    values.into_iter().map(|value| value as f32).collect(),
                )?,
                DType::F16 => DenseTensor::from_storage_f16(
                    meta,
                    values
                        .into_iter()
                        .map(|value| Float16::from_f32(value as f32))
                        .collect(),
                )?,
                DType::BF16 => DenseTensor::from_storage_bf16(
                    meta,
                    values
                        .into_iter()
                        .map(|value| BFloat16::from_f32(value as f32))
                        .collect(),
                )?,
                other => {
                    return Err(AutogradError::DenseTensor(
                        ft_core::DenseTensorError::UnsupportedDType(other),
                    ));
                }
            };
            self.tensor_variable_from_storage(output, false)
        } else {
            self.tensor_apply_function_with_create_graph(
                &[input],
                |ctx, inputs| {
                    let (vals, shape) = inputs[0];
                    // Save x for the digamma backward.
                    ctx.save_for_backward(vals.to_vec(), shape.to_vec());
                    let values: Vec<f64> = if vals.len() >= PARALLEL_ELEMENTWISE_MIN {
                        vals.par_iter().map(|&x| lgamma_approx(x)).collect()
                    } else {
                        vals.iter().map(|&x| lgamma_approx(x)).collect()
                    };
                    Ok((values, shape.to_vec()))
                },
                |ctx, grad_outputs| {
                    let grad_out = grad_outputs[0];
                    let saved = ctx.saved_tensors();
                    let x_vals = &saved[0];
                    if grad_out.len() != x_vals.len() {
                        return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                            ft_dispatch::DispatchKeyError::IncompatibleSet {
                                reason: "gammaln backward: incoming gradient length mismatch",
                            },
                        )));
                    }
                    let grad_in: Vec<f64> = if x_vals.len() >= PARALLEL_ELEMENTWISE_MIN {
                        x_vals
                            .par_iter()
                            .zip(grad_out.par_iter())
                            .map(|(&x, &go)| go * digamma_approx(x))
                            .collect()
                    } else {
                        x_vals
                            .iter()
                            .zip(grad_out.iter())
                            .map(|(&x, &go)| go * digamma_approx(x))
                            .collect()
                    };
                    Ok(vec![Some(grad_in)])
                },
                // create_graph backward: d/dx lgamma(x) = digamma(x). Build digamma
                // as a DIFFERENTIABLE node (its own first-order backward = trigamma =
                // polygamma(1, x)) so a second backward yields lgamma'' = trigamma(x)
                // instead of erroring. The raw first-order backward above is untouched,
                // so ordinary (non-create_graph) gradients are unchanged. 1avc3.
                |_ctx, grad_outs, inputs, tape| {
                    let dig = tape.apply_function(
                        &[inputs[0]],
                        |ctx, inp| {
                            let (vals, shape) = inp[0];
                            ctx.save_for_backward(vals.to_vec(), shape.to_vec());
                            Ok((par_map_f64(vals, digamma_approx), shape.to_vec()))
                        },
                        |ctx, gouts| {
                            let g = gouts[0];
                            let x = &ctx.saved_tensors()[0];
                            Ok(vec![Some(par_zip_map_f64(x, g, |x, go| {
                                go * polygamma_approx(1, x)
                            }))])
                        },
                    )?;
                    let grad_in = tape
                        .mul(grad_outs[0], dig, ft_core::ExecutionMode::Strict)?
                        .0;
                    Ok(vec![Some(grad_in)])
                },
            )?
        };
        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!("gammaln in={} out={}", input.0, out.0),
        );
        Ok(out)
    }

    /// Element-wise digamma (psi) function: d/dx ln(Gamma(x)).
    ///
    /// Equivalent to `torch.special.digamma(input)`.
    pub fn tensor_digamma(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        use rayon::prelude::*;
        // f32-native fast path: the apply_function path UPCASTS f32->f64 (128MB) + create_graph
        // clone = ~7.6x SLOWER. Same value (digamma_approx in f64, narrowed) = bit-identical.
        if let Some(out) = self.try_f32_unary_native(input, digamma_approx)? {
            return Ok(out);
        }
        // No-grad f64 sibling: the apply_function path below UNCONDITIONALLY
        // save_for_backward(vals.to_vec())s a 128MB no-grad clone + a create_graph node; par_map
        // digamma_approx into a leaf instead. Bit-exact. frankentorch-digamma-f64-nograd.
        if let Some(out) = self.try_f64_unary_native(input, digamma_approx)? {
            // Dispatch-evidence contract: this no-grad fast path returns BEFORE the end-of-fn
            // record, so emit the same Dispatch entry here (mirrors gammaln fix 70efa262).
            self.runtime.ledger_mut().record(
                EvidenceKind::Dispatch,
                format!("digamma in={} out={}", input.0, out.0),
            );
            return Ok(out);
        }
        // Wrap digamma_approx in a tensor_apply_function with a
        // trigamma backward (= polygamma(1, x)). Tracked under
        // frankentorch-1tax. Same pattern as the gammaln autograd
        // wiring just above. digamma/trigamma are compute-bound per element, so
        // large tensors are evaluated on the rayon pool (pure map -> bit-exact).
        //
        //     forward : y = digamma(x)
        //     backward: dy/dx = trigamma(x) = polygamma(1, x)
        let out = self.tensor_apply_function_with_create_graph(
            &[input],
            |ctx, inputs| {
                let (vals, shape) = inputs[0];
                ctx.save_for_backward(vals.to_vec(), shape.to_vec());
                let values: Vec<f64> = if vals.len() >= PARALLEL_ELEMENTWISE_MIN {
                    vals.par_iter().map(|&x| digamma_approx(x)).collect()
                } else {
                    vals.iter().map(|&x| digamma_approx(x)).collect()
                };
                Ok((values, shape.to_vec()))
            },
            |ctx, grad_outputs| {
                let grad_out = grad_outputs[0];
                let saved = ctx.saved_tensors();
                let x_vals = &saved[0];
                if grad_out.len() != x_vals.len() {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "digamma backward: incoming gradient length mismatch",
                        },
                    )));
                }
                let grad_in: Vec<f64> = if x_vals.len() >= PARALLEL_ELEMENTWISE_MIN {
                    x_vals
                        .par_iter()
                        .zip(grad_out.par_iter())
                        .map(|(&x, &go)| go * polygamma_approx(1, x))
                        .collect()
                } else {
                    x_vals
                        .iter()
                        .zip(grad_out.iter())
                        .map(|(&x, &go)| go * polygamma_approx(1, x))
                        .collect()
                };
                Ok(vec![Some(grad_in)])
            },
            // create_graph backward: d/dx digamma(x) = trigamma(x) = polygamma(1, x).
            // Build it as a DIFFERENTIABLE node (first-order backward = polygamma(2, x))
            // so a second backward yields digamma'' = polygamma(2, x). Raw first-order
            // backward above is untouched. 1avc3.
            |_ctx, grad_outs, inputs, tape| {
                let tri = tape.apply_function(
                    &[inputs[0]],
                    |ctx, inp| {
                        let (vals, shape) = inp[0];
                        ctx.save_for_backward(vals.to_vec(), shape.to_vec());
                        Ok((
                            par_map_f64(vals, |x| polygamma_approx(1, x)),
                            shape.to_vec(),
                        ))
                    },
                    |ctx, gouts| {
                        let g = gouts[0];
                        let x = &ctx.saved_tensors()[0];
                        Ok(vec![Some(par_zip_map_f64(x, g, |x, go| {
                            go * polygamma_approx(2, x)
                        }))])
                    },
                )?;
                let grad_in = tape
                    .mul(grad_outs[0], tri, ft_core::ExecutionMode::Strict)?
                    .0;
                Ok(vec![Some(grad_in)])
            },
        )?;
        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!("digamma in={} out={}", input.0, out.0),
        );
        Ok(out)
    }

    /// Alias for `tensor_digamma`. Equivalent to `torch.special.digamma`.
    pub fn tensor_special_digamma(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_digamma(input)
    }

    /// Element-wise polygamma function of order n.
    ///
    /// Equivalent to `torch.special.polygamma(n, input)`.
    /// Only n=0 (digamma) and n=1 (trigamma) are directly supported.
    ///
    /// Wraps polygamma_approx in a tensor_apply_function with the
    /// backward d/dx polygamma(n, x) = polygamma(n+1, x), same
    /// pattern as gammaln / digamma autograd wiring (7cc0b45 /
    /// 86fb29d). Tracked under frankentorch-1tax.
    pub fn tensor_polygamma(
        &mut self,
        n: u32,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        if n == 0 {
            return self.tensor_digamma(input);
        }
        // f32-native fast path (no apply_function upcast = ~8.6x SLOWER). Same value
        // (polygamma_approx(n, .) in f64, narrowed) = bit-identical.
        if let Some(out) = self.try_f32_unary_native(input, move |x| polygamma_approx(n, x))? {
            return Ok(out);
        }
        let out = self.tensor_apply_function(
            &[input],
            move |ctx, inputs| {
                let (vals, shape) = inputs[0];
                ctx.save_for_backward(vals.to_vec(), shape.to_vec());
                let values: Vec<f64> = par_map_f64(vals, |x| polygamma_approx(n, x));
                Ok((values, shape.to_vec()))
            },
            move |ctx, grad_outputs| {
                let grad_out = grad_outputs[0];
                let saved = ctx.saved_tensors();
                let x_vals = &saved[0];
                if grad_out.len() != x_vals.len() {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "polygamma backward: incoming gradient length mismatch",
                        },
                    )));
                }
                let next_order = n + 1;
                let grad_in: Vec<f64> = par_zip_map_f64(x_vals, grad_out, |x, go| {
                    go * polygamma_approx(next_order, x)
                });
                Ok(vec![Some(grad_in)])
            },
        )?;
        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!("polygamma n={n} in={} out={}", input.0, out.0),
        );
        Ok(out)
    }

    /// Alias for `tensor_polygamma`. Equivalent to `torch.special.polygamma`.
    pub fn tensor_special_polygamma(
        &mut self,
        n: u32,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_polygamma(n, input)
    }

    /// Second derivative of lgamma (trigamma function).
    ///
    /// Equivalent to `torch.special.polygamma(1, input)`. The trigamma
    /// function psi'(x) is the derivative of digamma, commonly used in
    /// gradient computations involving gamma functions.
    pub fn tensor_trigamma(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        self.tensor_polygamma(1, input)
    }

    /// In-place trigamma: target = polygamma(1, target).
    pub fn tensor_trigamma_(&mut self, target: TensorNodeId) -> Result<(), AutogradError> {
        self.validate_tensor_in_place_target(target)?;
        let result = self.tensor_trigamma(target)?;
        let result_vals = self.tensor_values(result)?;
        self.update_tensor_values_for_float(target, result_vals, INPLACE_FLOAT_REASON)?;
        self.record_tensor_in_place_operation("trigamma_", target, None);
        Ok(())
    }

    /// Regularized lower incomplete gamma function P(a, x).
    ///
    /// Equivalent to `torch.special.gammainc(input, other)`.
    /// Computes the regularized lower incomplete gamma function.
    pub fn tensor_igamma(
        &mut self,
        input: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // f32-native fast path (no-grad, equal-shape both-f32): the f32 branch below upcasts
        // BOTH inputs to f64 (two to_dtype allocs), recurses, then downcasts the result (a
        // third pass). Compute igamma_approx(a as f64, x as f64) as f32 in one parallel pass —
        // bit-identical (same igamma_approx the f64 path uses; f64->f32 narrow == as f32).
        // frankentorch-specf32.
        if let Some(out) = self.try_f32_binary_native(input, other, igamma_approx)? {
            return Ok(out);
        }
        // No-grad f64 fast path: the direct path below CLONES both inputs via tensor_values /
        // tensor_values_lossy_f64 (2x 128MB); try_f64_binary_native BORROWS them zero-copy + par_zip.
        // Bit-exact (same igamma_approx, index-order). frankentorch-igamma_approx-f64-borrow.
        if let Some(out) = self.try_f64_binary_native(input, other, igamma_approx)? {
            return Ok(out);
        }
        // f32/half: compute in f64, cast to the promoted dtype (the read is
        // f64-only). torch keeps the input dtype. frankentorch-77o4c.
        let (di, do_) = (self.tensor_dtype(input)?, self.tensor_dtype(other)?);
        if di != DType::F64 || do_ != DType::F64 {
            let out_dt = Self::promote_float_pair(di, do_);
            let i64v = self.tensor_to_dtype(input, DType::F64)?;
            let o64 = self.tensor_to_dtype(other, DType::F64)?;
            let out64 = self.tensor_igamma(i64v, o64)?;
            return self.tensor_to_dtype(out64, out_dt);
        }
        let input_shape = self.tensor_shape(input)?;
        let other_shape = self.tensor_shape(other)?;
        if input_shape != other_shape {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: input_shape,
                    rhs: other_shape,
                },
            )));
        }
        if self.tensor_requires_grad(input)? || self.tensor_requires_grad(other)? {
            // igamma P(a,x) is differentiable w.r.t. x (= `other`):
            //   ∂P/∂x = x^{a-1}e^{-x}/Γ(a).
            // Matching torch's derivatives.yaml, the `a` (= `input`) argument is
            // non-differentiable, so its gradient is None. Forward reuses the same
            // igamma_approx, so the value is bit-identical. frankentorch-2vxa.
            return self.tensor_apply_function(
                &[input, other],
                move |ctx, inputs| {
                    let (a, a_shape) = inputs[0];
                    let (x, _x_shape) = inputs[1];
                    let result = par_zip_map_f64(a, x, igamma_approx);
                    ctx.save_for_backward(a.to_vec(), a_shape.to_vec());
                    ctx.save_for_backward(x.to_vec(), a_shape.to_vec());
                    Ok((result, a_shape.to_vec()))
                },
                move |ctx, grad_outputs| {
                    let saved = ctx.saved_tensors();
                    let (a, x) = (&saved[0], &saved[1]);
                    let g = grad_outputs[0];
                    let grad_x: Vec<f64> = (0..g.len())
                        .map(|i| g[i] * gammainc_dx(a[i], x[i]))
                        .collect();
                    Ok(vec![None, Some(grad_x)])
                },
            );
        }
        let input_vals = self.tensor_values(input)?;
        let other_vals = self.tensor_values_lossy_f64(other)?;
        let result: Vec<f64> = par_zip_map_f64(&input_vals, &other_vals, igamma_approx);
        self.tensor_variable(result, input_shape, false)
    }

    /// Alias for tensor_igamma matching torch.special.gammainc.
    pub fn tensor_special_gammainc(
        &mut self,
        input: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_igamma(input, other)
    }

    /// In-place igamma.
    pub fn tensor_igamma_(
        &mut self,
        target: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<(), AutogradError> {
        self.validate_tensor_in_place_target(target)?;
        let result = self.tensor_igamma(target, other)?;
        let result_vals = self.tensor_values(result)?;
        self.update_tensor_values_for_float(target, result_vals, INPLACE_FLOAT_REASON)?;
        self.record_tensor_in_place_operation("igamma_", target, None);
        Ok(())
    }

    /// Regularized upper incomplete gamma function Q(a, x) = 1 - P(a, x).
    ///
    /// Equivalent to `torch.special.gammaincc(input, other)`.
    /// Computes the regularized upper incomplete gamma function.
    pub fn tensor_igammac(
        &mut self,
        input: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // f32-native fast path (no-grad, equal-shape both-f32): same 3-extra-pass upcast as
        // tensor_igamma. igammac_approx(a as f64, x as f64) as f32 in one pass = bit-identical.
        // frankentorch-specf32.
        if let Some(out) = self.try_f32_binary_native(input, other, igammac_approx)? {
            return Ok(out);
        }
        // No-grad f64 fast path: the direct path below CLONES both inputs via tensor_values /
        // tensor_values_lossy_f64 (2x 128MB); try_f64_binary_native BORROWS them zero-copy + par_zip.
        // Bit-exact (same igammac_approx, index-order). frankentorch-igammac_approx-f64-borrow.
        if let Some(out) = self.try_f64_binary_native(input, other, igammac_approx)? {
            return Ok(out);
        }
        // f32/half: compute in f64, cast to the promoted dtype (the read is
        // f64-only). torch keeps the input dtype. frankentorch-77o4c.
        let (di, do_) = (self.tensor_dtype(input)?, self.tensor_dtype(other)?);
        if di != DType::F64 || do_ != DType::F64 {
            let out_dt = Self::promote_float_pair(di, do_);
            let i64v = self.tensor_to_dtype(input, DType::F64)?;
            let o64 = self.tensor_to_dtype(other, DType::F64)?;
            let out64 = self.tensor_igammac(i64v, o64)?;
            return self.tensor_to_dtype(out64, out_dt);
        }
        let input_shape = self.tensor_shape(input)?;
        let other_shape = self.tensor_shape(other)?;
        if input_shape != other_shape {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: input_shape,
                    rhs: other_shape,
                },
            )));
        }
        if self.tensor_requires_grad(input)? || self.tensor_requires_grad(other)? {
            // igammac Q(a,x) = 1 − P(a,x), so ∂Q/∂x = −∂P/∂x = −x^{a-1}e^{-x}/Γ(a);
            // `a` (= `input`) is non-differentiable (matches torch). frankentorch-2vxa.
            return self.tensor_apply_function(
                &[input, other],
                move |ctx, inputs| {
                    let (a, a_shape) = inputs[0];
                    let (x, _x_shape) = inputs[1];
                    let result = par_zip_map_f64(a, x, igammac_approx);
                    ctx.save_for_backward(a.to_vec(), a_shape.to_vec());
                    ctx.save_for_backward(x.to_vec(), a_shape.to_vec());
                    Ok((result, a_shape.to_vec()))
                },
                move |ctx, grad_outputs| {
                    let saved = ctx.saved_tensors();
                    let (a, x) = (&saved[0], &saved[1]);
                    let g = grad_outputs[0];
                    let grad_x: Vec<f64> = (0..g.len())
                        .map(|i| -g[i] * gammainc_dx(a[i], x[i]))
                        .collect();
                    Ok(vec![None, Some(grad_x)])
                },
            );
        }
        let input_vals = self.tensor_values(input)?;
        let other_vals = self.tensor_values_lossy_f64(other)?;
        let result: Vec<f64> = par_zip_map_f64(&input_vals, &other_vals, igammac_approx);
        self.tensor_variable(result, input_shape, false)
    }

    /// Alias for tensor_igammac matching torch.special.gammaincc.
    pub fn tensor_special_gammaincc(
        &mut self,
        input: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_igammac(input, other)
    }

    /// In-place igammac.
    pub fn tensor_igammac_(
        &mut self,
        target: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<(), AutogradError> {
        self.validate_tensor_in_place_target(target)?;
        let result = self.tensor_igammac(target, other)?;
        let result_vals = self.tensor_values(result)?;
        self.update_tensor_values_for_float(target, result_vals, INPLACE_FLOAT_REASON)?;
        self.record_tensor_in_place_operation("igammac_", target, None);
        Ok(())
    }

    /// Modified Bessel function of the first kind, order 0.
    ///
    /// Equivalent to `torch.special.i0(input)`.
    /// Tracked under frankentorch-qdvs.
    pub fn tensor_i0(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        // No-grad f64 borrow fast path: the path below CLONES the input via
        // contiguous_values_as_f64().to_vec(); try_f64_unary_native BORROWS it. Bit-exact (i0_approx).
        if let Some(out) = self.try_f64_unary_native(input, i0_approx)? {
            // Dispatch-evidence contract: this no-grad fast path returns BEFORE the end-of-fn
            // record, so emit the same Dispatch entry here (mirrors gammaln fix 70efa262).
            self.runtime.ledger_mut().record(
                EvidenceKind::Dispatch,
                format!("i0 in={} out={}", input.0, out.0),
            );
            return Ok(out);
        }
        let out = if !self.tensor_tape.tensor_requires_grad(input)?
            || !self.tensor_tape.is_grad_enabled()
        {
            let (meta, values) = {
                let tensor = self.tensor_tape.tensor(input)?;
                let meta = tensor.meta().clone();
                let vals = tensor.contiguous_values_as_f64()?;
                (meta, par_map_f64(&vals, i0_approx))
            };
            let dtype = meta.dtype();
            let output = match dtype {
                DType::F64 => DenseTensor::from_storage(meta, values)?,
                DType::F32 => DenseTensor::from_storage_f32(
                    meta,
                    values.into_iter().map(|value| value as f32).collect(),
                )?,
                DType::F16 => DenseTensor::from_storage_f16(
                    meta,
                    values
                        .into_iter()
                        .map(|value| Float16::from_f32(value as f32))
                        .collect(),
                )?,
                DType::BF16 => DenseTensor::from_storage_bf16(
                    meta,
                    values
                        .into_iter()
                        .map(|value| BFloat16::from_f32(value as f32))
                        .collect(),
                )?,
                other => {
                    return Err(AutogradError::DenseTensor(
                        ft_core::DenseTensorError::UnsupportedDType(other),
                    ));
                }
            };
            self.tensor_variable_from_storage(output, false)
        } else {
            self.tensor_apply_function_with_create_graph(
                &[input],
                |ctx, inputs| {
                    let (vals, shape) = inputs[0];
                    ctx.save_for_backward(vals.to_vec(), shape.to_vec());
                    let values: Vec<f64> = par_map_f64(vals, i0_approx);
                    Ok((values, shape.to_vec()))
                },
                |ctx, grad_outputs| {
                    let grad_out = grad_outputs[0];
                    let saved = ctx.saved_tensors();
                    let x_vals = &saved[0];
                    if grad_out.len() != x_vals.len() {
                        return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                            ft_dispatch::DispatchKeyError::IncompatibleSet {
                                reason: "i0 backward: incoming gradient length mismatch",
                            },
                        )));
                    }
                    let grad_in: Vec<f64> =
                        par_zip_map_f64(x_vals, grad_out, |x, go| go * i1_approx(x));
                    Ok(vec![Some(grad_in)])
                },
                // create_graph: i0'(x) = i1(x). Rebuild i1 as a DIFFERENTIABLE node whose
                // own backward is the existing i1 derivative (i0 - i1/x), so i0''(x) = i1'(x)
                // propagates instead of erroring. Raw backward above untouched. 1avc3 vein.
                |_ctx, grad_outs, inputs, tape| {
                    let mode = ft_core::ExecutionMode::Strict;
                    let i1n = tape.apply_function(
                        &[inputs[0]],
                        |ctx, inp| {
                            let (vals, shape) = inp[0];
                            ctx.save_for_backward(vals.to_vec(), shape.to_vec());
                            Ok((par_map_f64(vals, i1_approx), shape.to_vec()))
                        },
                        |ctx, gouts| {
                            let g = gouts[0];
                            let x = &ctx.saved_tensors()[0];
                            Ok(vec![Some(par_zip_map_f64(x, g, |x, go| {
                                if x.abs() < 1e-10 {
                                    go * 0.5
                                } else {
                                    go * (i0_approx(x) - i1_approx(x) / x)
                                }
                            }))])
                        },
                    )?;
                    let grad_in = tape.mul(grad_outs[0], i1n, mode)?.0;
                    Ok(vec![Some(grad_in)])
                },
            )?
        };
        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!("i0 in={} out={}", input.0, out.0),
        );
        Ok(out)
    }

    /// Exponentially scaled modified Bessel function of the first kind, order 0.
    ///
    /// Equivalent to `torch.special.i0e(input)`.
    /// i0e(x) = exp(-|x|) * i0(x)
    /// Tracked under frankentorch-0tok.
    pub fn tensor_i0e(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        // No-grad f64 fast path: the apply_function path below UNCONDITIONALLY
        // save_for_backward(vals.to_vec())s a full-numel clone (128MB no-grad waste) + a create_graph
        // node. Compute the same par_map i0e_approx and return a leaf. Bit-exact. frankentorch-i0e-nograd.
        if let Some(out) = self.try_f64_unary_native(input, i0e_approx)? {
            // Dispatch-evidence contract: this no-grad fast path returns BEFORE the end-of-fn
            // record, so emit the same Dispatch entry here (mirrors gammaln fix 70efa262).
            self.runtime.ledger_mut().record(
                EvidenceKind::Dispatch,
                format!("i0e in={} out={}", input.0, out.0),
            );
            return Ok(out);
        }
        let out = self.tensor_apply_function_with_create_graph(
            &[input],
            |ctx, inputs| {
                let (vals, shape) = inputs[0];
                ctx.save_for_backward(vals.to_vec(), shape.to_vec());
                let values: Vec<f64> = par_map_f64(vals, i0e_approx);
                Ok((values, shape.to_vec()))
            },
            |ctx, grad_outputs| {
                let grad_out = grad_outputs[0];
                let saved = ctx.saved_tensors();
                let x_vals = &saved[0];
                if grad_out.len() != x_vals.len() {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "i0e backward: incoming gradient length mismatch",
                        },
                    )));
                }
                let grad_in: Vec<f64> = par_zip_map_f64(x_vals, grad_out, |x, go| {
                    let sign_x = if x >= 0.0 { 1.0 } else { -1.0 };
                    go * (i1e_approx(x) - sign_x * i0e_approx(x))
                });
                Ok(vec![Some(grad_in)])
            },
            // create_graph: i0e'(x) = i1e(x) - sign(x)·i0e(x). Rebuild i1e and i0e as
            // DIFFERENTIABLE nodes (their own backwards) and combine with a CONSTANT sign
            // mask (sign is locally constant, so its derivative is 0 — correct away from
            // x=0), so i0e''(x) propagates. Raw backward untouched. 1avc3 vein.
            |_ctx, grad_outs, inputs, tape| {
                let mode = ft_core::ExecutionMode::Strict;
                let (xshape, xvals) = {
                    let t = tape.tensor(inputs[0])?;
                    (t.meta().shape().to_vec(), t.contiguous_values_as_f64()?)
                };
                let signs: Vec<f64> = xvals
                    .iter()
                    .map(|&x| if x >= 0.0 { 1.0 } else { -1.0 })
                    .collect();
                let i1en = tape.apply_function(
                    &[inputs[0]],
                    |ctx, inp| {
                        let (vals, shape) = inp[0];
                        ctx.save_for_backward(vals.to_vec(), shape.to_vec());
                        Ok((par_map_f64(vals, i1e_approx), shape.to_vec()))
                    },
                    |ctx, gouts| {
                        let g = gouts[0];
                        let x = &ctx.saved_tensors()[0];
                        Ok(vec![Some(par_zip_map_f64(x, g, |x, go| {
                            let sign_x = if x >= 0.0 { 1.0 } else { -1.0 };
                            if x.abs() < 1e-10 {
                                go * 0.5
                            } else {
                                go * (i0e_approx(x) - i1e_approx(x) / x - sign_x * i1e_approx(x))
                            }
                        }))])
                    },
                )?;
                let i0en = tape.apply_function(
                    &[inputs[0]],
                    |ctx, inp| {
                        let (vals, shape) = inp[0];
                        ctx.save_for_backward(vals.to_vec(), shape.to_vec());
                        Ok((par_map_f64(vals, i0e_approx), shape.to_vec()))
                    },
                    |ctx, gouts| {
                        let g = gouts[0];
                        let x = &ctx.saved_tensors()[0];
                        Ok(vec![Some(par_zip_map_f64(x, g, |x, go| {
                            let sign_x = if x >= 0.0 { 1.0 } else { -1.0 };
                            go * (i1e_approx(x) - sign_x * i0e_approx(x))
                        }))])
                    },
                )?;
                let sign_mask = tape.leaf(signs, xshape, false)?;
                let signed_i0e = tape.mul(sign_mask, i0en, mode)?.0;
                let deriv = tape.sub(i1en, signed_i0e, mode)?.0;
                let grad_in = tape.mul(grad_outs[0], deriv, mode)?.0;
                Ok(vec![Some(grad_in)])
            },
        )?;
        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!("i0e in={} out={}", input.0, out.0),
        );
        Ok(out)
    }

    /// Modified Bessel function of the first kind, order 1.
    ///
    /// Equivalent to `torch.special.i1(input)`.
    /// Tracked under frankentorch-ngi9.
    pub fn tensor_i1(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        // f32-native fast path: without it, f32 input rode apply_function (upcast f32->f64) and
        // returned an F64 tensor — WRONG dtype (torch i1(f32)->f32) + slow. Compute i1_approx in f64
        // and narrow, matching torch's f32 kernel (same approach as the i0e/erfcx f32 paths).
        // frankentorch-i1-f32.
        if let Some(out) = self.try_f32_unary_native(input, i1_approx)? {
            return Ok(out);
        }
        // No-grad f64 fast path (sibling of i0e/i1e): skip the apply_function's unconditional 128MB
        // save_for_backward clone + create_graph node; par_map i1_approx into a leaf. Bit-exact.
        // frankentorch-i1-f64-nograd.
        if let Some(out) = self.try_f64_unary_native(input, i1_approx)? {
            // Dispatch-evidence contract: this no-grad fast path returns BEFORE the end-of-fn
            // record, so emit the same Dispatch entry here (mirrors gammaln fix 70efa262).
            self.runtime.ledger_mut().record(
                EvidenceKind::Dispatch,
                format!("i1 in={} out={}", input.0, out.0),
            );
            return Ok(out);
        }
        let out = self.tensor_apply_function_with_create_graph(
            &[input],
            |ctx, inputs| {
                let (vals, shape) = inputs[0];
                ctx.save_for_backward(vals.to_vec(), shape.to_vec());
                let values: Vec<f64> = par_map_f64(vals, i1_approx);
                Ok((values, shape.to_vec()))
            },
            |ctx, grad_outputs| {
                let grad_out = grad_outputs[0];
                let saved = ctx.saved_tensors();
                let x_vals = &saved[0];
                if grad_out.len() != x_vals.len() {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "i1 backward: incoming gradient length mismatch",
                        },
                    )));
                }
                let grad_in: Vec<f64> = par_zip_map_f64(x_vals, grad_out, |x, go| {
                    if x.abs() < 1e-10 {
                        go * 0.5
                    } else {
                        go * (i0_approx(x) - i1_approx(x) / x)
                    }
                });
                Ok(vec![Some(grad_in)])
            },
            // create_graph: i1'(x) = i0(x) - i1(x)/x. Rebuild i0 and i1 as DIFFERENTIABLE
            // nodes (i0 backward = i1; i1 backward = i0 - i1/x) and form i0 - i1·(1/x) via
            // tape ops, so i1''(x) propagates. Raw backward untouched. 1avc3 vein.
            |_ctx, grad_outs, inputs, tape| {
                let mode = ft_core::ExecutionMode::Strict;
                let i0n = tape.apply_function(
                    &[inputs[0]],
                    |ctx, inp| {
                        let (vals, shape) = inp[0];
                        ctx.save_for_backward(vals.to_vec(), shape.to_vec());
                        Ok((par_map_f64(vals, i0_approx), shape.to_vec()))
                    },
                    |ctx, gouts| {
                        let g = gouts[0];
                        let x = &ctx.saved_tensors()[0];
                        Ok(vec![Some(par_zip_map_f64(x, g, |x, go| go * i1_approx(x)))])
                    },
                )?;
                let i1n = tape.apply_function(
                    &[inputs[0]],
                    |ctx, inp| {
                        let (vals, shape) = inp[0];
                        ctx.save_for_backward(vals.to_vec(), shape.to_vec());
                        Ok((par_map_f64(vals, i1_approx), shape.to_vec()))
                    },
                    |ctx, gouts| {
                        let g = gouts[0];
                        let x = &ctx.saved_tensors()[0];
                        Ok(vec![Some(par_zip_map_f64(x, g, |x, go| {
                            if x.abs() < 1e-10 {
                                go * 0.5
                            } else {
                                go * (i0_approx(x) - i1_approx(x) / x)
                            }
                        }))])
                    },
                )?;
                let recipx = tape.reciprocal(inputs[0], mode)?.0;
                let i1_over_x = tape.mul(i1n, recipx, mode)?.0;
                let deriv = tape.sub(i0n, i1_over_x, mode)?.0;
                let grad_in = tape.mul(grad_outs[0], deriv, mode)?.0;
                Ok(vec![Some(grad_in)])
            },
        )?;
        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!("i1 in={} out={}", input.0, out.0),
        );
        Ok(out)
    }

    /// Exponentially scaled modified Bessel function of the first kind, order 1.
    ///
    /// Equivalent to `torch.special.i1e(input)`.
