    /// Standard Gaussian cumulative distribution function.
    ///
    /// Equivalent to `torch.special.ndtr(input)`.
    /// ndtr(x) = (1 + erf(x / sqrt(2))) / 2 = 0.5 * erfc(-x / sqrt(2))
    /// Tracked under frankentorch-zykd.
    pub fn tensor_ndtr(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let sqrt2_inv = 1.0 / std::f64::consts::SQRT_2;
        let sqrt_2pi_inv = 1.0 / (2.0 * std::f64::consts::PI).sqrt();
        let out = self.tensor_apply_function_with_create_graph(
            &[input],
            move |ctx, inputs| {
                let (vals, shape) = inputs[0];
                // Skip the backward-only input clone in no-grad inference:
                // apply_function returns a plain Leaf and discards ctx unless an
                // input needs grad. Grad path unchanged. frankentorch-2lmvy.
                if ctx.needs_input_grad().iter().any(|&g| g) {
                    ctx.save_for_backward(vals.to_vec(), shape.to_vec());
                }
                // erfc per element — fan the independent lanes over Rayon
                // (par_map preserves index order => bit-for-bit == serial map).
                let values = par_map_f64(vals, |x| 0.5 * libm::erfc(-x * sqrt2_inv));
                Ok((values, shape.to_vec()))
            },
            move |ctx, grad_outputs| {
                let grad_out = grad_outputs[0];
                let saved = ctx.saved_tensors();
                let x_vals = &saved[0];
                if grad_out.len() != x_vals.len() {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "ndtr backward: incoming gradient length mismatch",
                        },
                    )));
                }
                let grad_in = par_zip_map_f64(x_vals, grad_out, |x, go| {
                    go * sqrt_2pi_inv * (-0.5 * x * x).exp()
                });
                Ok(vec![Some(grad_in)])
            },
            // create_graph: ndtr'(x) = φ(x) = (1/√(2π))·exp(-x²/2), assembled from
            // differentiable tape ops so ndtr''(x) = -x·φ(x) propagates. Raw backward
            // untouched. 1avc3 vein.
            move |_ctx, grad_outs, inputs, tape| {
                let mode = ft_core::ExecutionMode::Strict;
                let x2 = tape.mul(inputs[0], inputs[0], mode)?.0;
                let nh = tape.mul_scalar(x2, -0.5)?.0;
                let e = tape.exp(nh, mode)?.0;
                let deriv = tape.mul_scalar(e, sqrt_2pi_inv)?.0;
                let grad_in = tape.mul(grad_outs[0], deriv, mode)?.0;
                Ok(vec![Some(grad_in)])
            },
        )?;
        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!("ndtr in={} out={}", input.0, out.0),
        );
        Ok(out)
    }

    /// Log of standard Gaussian cumulative distribution function.
    ///
    /// Equivalent to `torch.special.log_ndtr(input)`.
    /// Numerically stable for large negative values.
    /// Tracked under frankentorch-v0nh.
    pub fn tensor_log_ndtr(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let sqrt2_inv = 1.0 / std::f64::consts::SQRT_2;
        let sqrt_2pi_inv = 1.0 / (2.0 * std::f64::consts::PI).sqrt();
        let out = self.tensor_apply_function_with_create_graph(
            &[input],
            move |ctx, inputs| {
                let (vals, shape) = inputs[0];
                // Skip the backward-only input clone in no-grad. frankentorch-2lmvy.
                if ctx.needs_input_grad().iter().any(|&g| g) {
                    ctx.save_for_backward(vals.to_vec(), shape.to_vec());
                }
                let values = par_map_f64(vals, |x| (0.5 * libm::erfc(-x * sqrt2_inv)).ln());
                Ok((values, shape.to_vec()))
            },
            move |ctx, grad_outputs| {
                let grad_out = grad_outputs[0];
                let saved = ctx.saved_tensors();
                let x_vals = &saved[0];
                if grad_out.len() != x_vals.len() {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "log_ndtr backward: incoming gradient length mismatch",
                        },
                    )));
                }
                let grad_in = par_zip_map_f64(x_vals, grad_out, |x, go| {
                    let pdf = sqrt_2pi_inv * (-0.5 * x * x).exp();
                    let cdf = 0.5 * libm::erfc(-x * sqrt2_inv);
                    go * pdf / cdf
                });
                Ok(vec![Some(grad_in)])
            },
            // create_graph: log_ndtr'(x) = φ(x)/Φ(x). Build φ(x)=(1/√2π)exp(-x²/2) from
            // differentiable tape ops, Φ(x)=ndtr(x) as a differentiable node (backward = φ),
            // then divide, so log_ndtr''(x) = -x·(φ/Φ) - (φ/Φ)² propagates. Raw backward
            // untouched. 1avc3/double-backward vein.
            move |_ctx, grad_outs, inputs, tape| {
                let mode = ft_core::ExecutionMode::Strict;
                // φ(x) = (1/√2π)·exp(-x²/2), differentiable in x (φ' = -x·φ).
                let x2 = tape.mul(inputs[0], inputs[0], mode)?.0;
                let nh = tape.mul_scalar(x2, -0.5)?.0;
                let e = tape.exp(nh, mode)?.0;
                let phi = tape.mul_scalar(e, sqrt_2pi_inv)?.0;
                // Φ(x) = ndtr(x), as a differentiable node whose backward is φ.
                let cdf = tape.apply_function(
                    &[inputs[0]],
                    move |ctx, inp| {
                        let (vals, shape) = inp[0];
                        ctx.save_for_backward(vals.to_vec(), shape.to_vec());
                        let v: Vec<f64> = vals
                            .iter()
                            .map(|&x| 0.5 * libm::erfc(-x * sqrt2_inv))
                            .collect();
                        Ok((v, shape.to_vec()))
                    },
                    move |ctx, gouts| {
                        let g = gouts[0];
                        let x = &ctx.saved_tensors()[0];
                        Ok(vec![Some(par_zip_map_f64(x, g, |x, go| {
                            go * sqrt_2pi_inv * (-0.5 * x * x).exp()
                        }))])
                    },
                )?;
                let deriv = tape.div(phi, cdf, mode)?.0;
                let grad_in = tape.mul(grad_outs[0], deriv, mode)?.0;
                Ok(vec![Some(grad_in)])
            },
        )?;
        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!("log_ndtr in={} out={}", input.0, out.0),
        );
        Ok(out)
    }

    /// Inverse of standard Gaussian CDF (probit function).
    ///
    /// Equivalent to `torch.special.ndtri(input)`.
    /// ndtri(p) = sqrt(2) * erfinv(2*p - 1)
    /// Tracked under frankentorch-qzwe.
    pub fn tensor_ndtri(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let sqrt2 = std::f64::consts::SQRT_2;
        let sqrt_2pi = (2.0 * std::f64::consts::PI).sqrt();
        let out = self.tensor_apply_function_with_create_graph(
            &[input],
            move |ctx, inputs| {
                let (vals, shape) = inputs[0];
                // erfinv per element over Rayon (par_map preserves order).
                let values = par_map_f64(vals, |p| sqrt2 * erfinv_approx(2.0 * p - 1.0));
                // Skip the backward-only output clone in no-grad. frankentorch-2lmvy.
                if ctx.needs_input_grad().iter().any(|&g| g) {
                    ctx.save_for_backward(values.clone(), shape.to_vec());
                }
                Ok((values, shape.to_vec()))
            },
            move |ctx, grad_outputs| {
                let grad_out = grad_outputs[0];
                let saved = ctx.saved_tensors();
                let y_vals = &saved[0];
                if grad_out.len() != y_vals.len() {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "ndtri backward: incoming gradient length mismatch",
                        },
                    )));
                }
                let grad_in = par_zip_map_f64(y_vals, grad_out, |y, go| {
                    go * sqrt_2pi * (0.5 * y * y).exp()
                });
                Ok(vec![Some(grad_in)])
            },
            // create_graph: ndtri'(p) = √(2π)·exp(y²/2), y=ndtri(p). Rebuild y as a
            // DIFFERENTIABLE node (backward = √(2π)·exp(y²/2) = dy/dp) then assemble, so
            // ndtri''(p) propagates. Mirrors the erfinv recipe. Raw backward untouched.
            move |_ctx, grad_outs, inputs, tape| {
                let mode = ft_core::ExecutionMode::Strict;
                let y = tape.apply_function(
                    &[inputs[0]],
                    move |ctx, inp| {
                        let (vals, shape) = inp[0];
                        let yv: Vec<f64> = vals
                            .iter()
                            .map(|&p| sqrt2 * erfinv_approx(2.0 * p - 1.0))
                            .collect();
                        ctx.save_for_backward(yv.clone(), shape.to_vec());
                        Ok((yv, shape.to_vec()))
                    },
                    move |ctx, gouts| {
                        let g = gouts[0];
                        let yv = &ctx.saved_tensors()[0];
                        Ok(vec![Some(par_zip_map_f64(yv, g, |y, go| {
                            go * sqrt_2pi * (0.5 * y * y).exp()
                        }))])
                    },
                )?;
                let y2 = tape.mul(y, y, mode)?.0;
                let h = tape.mul_scalar(y2, 0.5)?.0;
                let e = tape.exp(h, mode)?.0;
                let deriv = tape.mul_scalar(e, sqrt_2pi)?.0;
                let grad_in = tape.mul(grad_outs[0], deriv, mode)?.0;
                Ok(vec![Some(grad_in)])
            },
        )?;
        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!("ndtri in={} out={}", input.0, out.0),
        );
        Ok(out)
    }

    /// Multivariate log-gamma function.
    ///
    /// Equivalent to `torch.special.multigammaln(input, p)`.
    /// Computes: log(pi^{p*(p-1)/4} * prod_{i=1}^{p} Gamma(input - (i-1)/2))
    ///
    /// Wraps lgamma_approx in a tensor_apply_function with the
    /// analytical backward
    ///     d/dx multigammaln(x, p) = sum_{i=0..p-1} digamma(x - i/2)
    /// computed via digamma_approx. Tracked under frankentorch-1tax.
    /// `torch.mvlgamma(input, p)` parity alias for
    /// `tensor_multigammaln`.
    ///
    /// torch exposes both `torch.mvlgamma` and
    /// `torch.special.multigammaln` for the multivariate log-gamma
    /// function. ft-api had only the torch.special name; PyTorch
    /// code using `torch.mvlgamma` fails to compile without this
    /// alias. Tracked under frankentorch-abhu.
    pub fn tensor_mvlgamma(
        &mut self,
        input: TensorNodeId,
        p: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_multigammaln(input, p)
    }

    pub fn tensor_multigammaln(
        &mut self,
        input: TensorNodeId,
        p: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let log_pi = std::f64::consts::PI.ln();
        #[allow(clippy::cast_precision_loss)]
        let constant = (p * (p - 1)) as f64 / 4.0 * log_pi;

        // f32-native fast path (no-grad): apply_function below upcasts f32->f64 and clones
        // the input twice (forward read + save_for_backward) — all dead in no-grad. Compute
        // the same constant + sum_i lgamma_approx(x - i/2) in f64, narrowed to f32, in one
        // parallel pass = bit-identical to the prior f64 compute. Also backs tensor_mvlgamma
        // (delegates here). frankentorch-specf32.
        if let Some(out) = self.try_f32_unary_native(input, move |x| {
            let mut sum = constant;
            for i in 0..p {
                #[allow(clippy::cast_precision_loss)]
                let shift = i as f64 / 2.0;
                sum += lgamma_approx(x - shift);
            }
            sum
        })? {
            return Ok(out);
        }

        let out = self.tensor_apply_function(
            &[input],
            move |ctx, inputs| {
                let (vals, shape) = inputs[0];
                ctx.save_for_backward(vals.to_vec(), shape.to_vec());
                let values: Vec<f64> = par_map_f64(vals, |x| {
                    let mut sum = constant;
                    for i in 0..p {
                        #[allow(clippy::cast_precision_loss)]
                        let shift = i as f64 / 2.0;
                        sum += lgamma_approx(x - shift);
                    }
                    sum
                });
                Ok((values, shape.to_vec()))
            },
            move |ctx, grad_outputs| {
                let grad_out = grad_outputs[0];
                let saved = ctx.saved_tensors();
                let x_vals = &saved[0];
                if grad_out.len() != x_vals.len() {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "multigammaln backward: incoming gradient length mismatch",
                        },
                    )));
                }
                let grad_in: Vec<f64> = par_zip_map_f64(x_vals, grad_out, |x, go| {
                    let mut deriv = 0.0_f64;
                    for i in 0..p {
                        #[allow(clippy::cast_precision_loss)]
                        let shift = i as f64 / 2.0;
                        deriv += digamma_approx(x - shift);
                    }
                    go * deriv
                });
                Ok(vec![Some(grad_in)])
            },
        )?;

        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!("multigammaln p={p} in={} out={}", input.0, out.0),
        );
        Ok(out)
    }

    /// Element-wise x * log1p(y) with the convention 0 * log1p(y) = 0.
    ///
    /// Equivalent to `torch.special.xlog1py(input, other)`.
    pub fn tensor_xlog1py(
        &mut self,
        x: TensorNodeId,
        y: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // f32-native fast path (sibling of xlogy): the f32 branch below UPCASTS to f64 +
        // composes ~8 passes + narrows. `(x==0 && !isnan(y)) ? 0 : x*ln1p(y)` in f64 narrowed
        // = bit-identical to current f32. Equal-shape both-f32 only (the helper checks).
        if let Some(out) = self.try_f32_binary_native(x, y, |xi, yi| {
            if xi == 0.0 && !yi.is_nan() {
                0.0
            } else {
                xi * yi.ln_1p()
            }
        })? {
            return Ok(out);
        }
        // NOTE: no try_f64_binary_native here — xlog1py's f64 compose is only ~4 SIMD ops (log1p +
        // mul + eq + where) and MEASURED ~24.8ms, which the scalar fused path (28.97ms, is_nan branch)
        // does NOT beat (REJECTED-lever). rel_entr's f64 compose is ~13 ops (418ms) so it fuses to 15x.
        // f32/half: compute in f64, cast to the promoted dtype (full()-built
        // constants are F64 and fail the matching-dtype comparison). frankentorch-77o4c.
        let (dx, dy) = (self.tensor_dtype(x)?, self.tensor_dtype(y)?);
        if dx != DType::F64 || dy != DType::F64 {
            let out_dt = Self::promote_float_pair(dx, dy);
            let x64 = self.tensor_to_dtype(x, DType::F64)?;
            let y64 = self.tensor_to_dtype(y, DType::F64)?;
            let out64 = self.tensor_xlog1py(x64, y64)?;
            return self.tensor_to_dtype(out64, out_dt);
        }
        // Composes through tensor_log1p + tensor_mul + tensor_eq +
        // tensor_where so the autograd tape carries gradients through
        // both x and y. Previously this had a fail-loud guard
        // rejecting tracked inputs because the body extracted values
        // and rebuilt a fresh requires_grad=false leaf — same
        // severed-autograd pattern as tensor_xlogy / logit / cov etc.
        // PyTorch's torch.special.xlog1py is differentiable. Tracked
        // under frankentorch-1tax.
        //
        // Math:  xlog1py(x, y) = x * log(1 + y), with the convention
        //                       0 * log(1 + y) = 0  (preserves the
        //                       y == -1 boundary where log1p(-1) is
        //                       -inf — output stays 0 when x is 0).
        //
        // Composition:
        //     where(x == 0, 0, x * log1p(y))
        //
        // Backward:
        //     d xlog1py / dx where x != 0 = log1p(y)
        //     d xlog1py / dy where x != 0 = x / (1 + y)
        //     both gradients zero where x == 0 (mask blocks flow)
        let x_shape = self.tensor_shape(x)?;
        let y_shape = self.tensor_shape(y)?;
        if x_shape != y_shape {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "xlog1py: inputs must have the same shape",
                },
            )));
        }
        // No-grad fast path mirroring tensor_xlogy (composed path was 3.77x SLOWER): for
        // no-grad contiguous f64, borrow both and compute `xlog1py(x,y) = (x==0 && !isnan(y))
        // ? 0 : x*ln_1p(y)` in ONE parallel pass. Bit-exact with the composed log1p+mul+
        // where path. f32 / grad / non-contiguous fall through.
        if !self.tensor_requires_grad(x)?
            && !self.tensor_requires_grad(y)?
            && self.tensor_dtype(x)? == DType::F64
            && self.tensor_dtype(y)? == DType::F64
        {
            let built = {
                let xt = self.tensor_tape.tensor(x)?;
                let yt = self.tensor_tape.tensor(y)?;
                if xt.meta().is_contiguous() && yt.meta().is_contiguous() {
                    let xd = xt.contiguous_values()?;
                    let yd = yt.contiguous_values()?;
                    if xd.len() == yd.len() {
                        use rayon::prelude::*;
                        let out: Vec<f64> = xd
                            .par_iter()
                            .zip(yd.par_iter())
                            .map(|(&xi, &yi)| {
                                if xi == 0.0 && !yi.is_nan() {
                                    0.0
                                } else {
                                    xi * yi.ln_1p()
                                }
                            })
                            .collect();
                        Some(out)
                    } else {
                        None
                    }
                } else {
                    None
                }
            };
            if let Some(out) = built {
                return self.tensor_variable(out, x_shape, false);
            }
        }
        let log1p_y = self.tensor_log1p(y)?;
        let prod = self.tensor_mul(x, log1p_y)?;
        // Single zeros tensor shared between the eq mask and the
        // where-true branch below (frankentorch-rbhb).
        let zeros = self.full(x_shape.clone(), 0.0, false)?;
        let mask_x_zero = self.tensor_eq(x, zeros)?;
        // scipy.special.xlog1py propagates NaN from y when x == 0 —
        // its mask is (x == 0 && !isnan(y)). Tighten the where mask
        // accordingly so a NaN y survives the masked branch as a
        // genuine NaN output, matching scipy bit-exactly. Tracked
        // under frankentorch-duf7. The previous mask was just
        // (x == 0), which short-circuited even at y=NaN and yielded
        // a spurious 0.
        let isnan_y = self.tensor_isnan(y)?;
        // NOT(isnan_y) via eq against the existing zeros tensor:
        // tensor_isnan emits exact 0.0/1.0, so (isnan_y == 0) is
        // bit-exactly the boolean negation, with no need for a
        // separate ones-filled tensor and tensor_sub. -1 full()
        // allocation per call (frankentorch-me8s).
        let not_isnan_y = self.tensor_eq(isnan_y, zeros)?;
        let mask = self.tensor_mul(mask_x_zero, not_isnan_y)?;
        // Reuse the zeros tensor allocated above for the where-true
        // branch (frankentorch-rbhb).
        let out = self.tensor_where(mask, zeros, prod)?;
        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!("xlog1py x={} y={} out={}", x.0, y.0, out.0),
        );
        Ok(out)
    }

    /// Alias for `tensor_xlog1py`. Equivalent to `torch.special.xlog1py`.
    pub fn tensor_special_xlog1py(
        &mut self,
        x: TensorNodeId,
        y: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_xlog1py(x, y)
    }

    /// Scaled complementary error function: erfcx(x) = exp(x²) * erfc(x).
    ///
    /// Equivalent to `torch.special.erfcx(input)`.
    ///
    /// erfcx is useful because it stays finite for large positive x where
    /// erfc(x) would underflow. Autograd backward:
    ///   d erfcx(x)/dx = 2x * erfcx(x) - 2/sqrt(π)
    pub fn tensor_erfcx(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        // f32-native fast path (no apply_function upcast = ~9.5x SLOWER). Bit-identical.
        if let Some(out) = self.try_f32_unary_native(input, erfcx_approx)? {
            return Ok(out);
        }
        // No-grad f64 sibling: the apply_function path below UNCONDITIONALLY save_for_backward-clones
        // the 16M output (128MB no-grad waste) + builds a create_graph node; par_map erfcx_approx into
        // a leaf instead. Bit-exact. frankentorch-erfcx-f64-nograd.
        if let Some(out) = self.try_f64_unary_native(input, erfcx_approx)? {
            // Dispatch-evidence contract: this no-grad fast path returns BEFORE the end-of-fn
            // record, so emit the same Dispatch entry here (mirrors gammaln fix 70efa262).
            self.runtime.ledger_mut().record(
                EvidenceKind::Dispatch,
                format!("erfcx in={} out={}", input.0, out.0),
            );
            return Ok(out);
        }
        // d erfcx(x)/dx = 2x * erfcx(x) - 2/sqrt(π)
        let two_over_sqrt_pi = 2.0 * 0.564_189_583_547_756_3_f64;
        let out = self.tensor_apply_function_with_create_graph(
            &[input],
            |ctx, inputs| {
                let (vals, shape) = inputs[0];
                ctx.save_for_backward(vals.to_vec(), shape.to_vec());
                let values: Vec<f64> = par_map_f64(vals, erfcx_approx);
                Ok((values, shape.to_vec()))
            },
            move |ctx, grad_outputs| {
                let grad_out = grad_outputs[0];
                let saved = ctx.saved_tensors();
                let x_vals = &saved[0];
                if grad_out.len() != x_vals.len() {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "erfcx backward: incoming gradient length mismatch",
                        },
                    )));
                }
                let grad_in: Vec<f64> = par_zip_map_f64(x_vals, grad_out, |x, go| {
                    go * (2.0 * x * erfcx_approx(x) - two_over_sqrt_pi)
                });
                Ok(vec![Some(grad_in)])
            },
            // create_graph: erfcx'(x) = 2x·erfcx(x) - 2/√π. Rebuild erfcx as a
            // DIFFERENTIABLE node (its own backward = the same derivative) then assemble
            // the linear expression from tape ops, so erfcx''(x) = 2·erfcx(x) + 2x·erfcx'(x)
            // propagates. The -2/√π constant is kept (correct create_graph 1st-grad);
            // it drops out of the 2nd derivative. Raw backward untouched. 1avc3 vein.
            move |_ctx, grad_outs, inputs, tape| {
                let mode = ft_core::ExecutionMode::Strict;
                let xshape = tape.tensor(inputs[0])?.meta().shape().to_vec();
                let n: usize = xshape.iter().product();
                let y = tape.apply_function(
                    &[inputs[0]],
                    |ctx, inp| {
                        let (vals, shape) = inp[0];
                        ctx.save_for_backward(vals.to_vec(), shape.to_vec());
                        Ok((par_map_f64(vals, erfcx_approx), shape.to_vec()))
                    },
                    move |ctx, gouts| {
                        let g = gouts[0];
                        let x = &ctx.saved_tensors()[0];
                        Ok(vec![Some(par_zip_map_f64(x, g, |x, go| {
                            go * (2.0 * x * erfcx_approx(x) - two_over_sqrt_pi)
                        }))])
                    },
                )?;
                let xy = tape.mul(inputs[0], y, mode)?.0;
                let two_xy = tape.mul_scalar(xy, 2.0)?.0;
                let cst = tape.leaf(vec![two_over_sqrt_pi; n], xshape, false)?;
                let deriv = tape.sub(two_xy, cst, mode)?.0;
                let grad_in = tape.mul(grad_outs[0], deriv, mode)?.0;
                Ok(vec![Some(grad_in)])
            },
        )?;
        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!("erfcx in={} out={}", input.0, out.0),
        );
        Ok(out)
    }

    /// Alias for `tensor_erfcx`. Equivalent to `torch.special.erfcx`.
    pub fn tensor_special_erfcx(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_erfcx(input)
    }

    /// Hurwitz zeta function: zeta(s, a) = sum_{n=0}^{inf} (n+a)^(-s).
    ///
    /// Equivalent to `torch.special.zeta(input, q)`.
    ///
    /// Requires a > 0. For s <= 1, the series diverges (returns NaN).
    /// The Riemann zeta function is zeta(s, 1).
    ///
    /// Autograd is not implemented for this function (gradients are complex).
    pub fn tensor_zeta(
        &mut self,
        s: TensorNodeId,
        a: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // f32-native fast path (no-grad, equal-shape both-f32): skip the 3-pass upcast
        // (to_dtype both inputs->f64, recurse, to_dtype back). zeta_approx now uses the Cephes
        // adaptive Euler-Maclaurin core (matches torch), so the per-element cost is small and
        // the upcast bandwidth dominates — the fast path matters more than before. Bit-identical
        // to the f64-path output narrowed to f32. frankentorch-specf32.
        if let Some(out) = self.try_f32_binary_native(s, a, zeta_approx)? {
            return Ok(out);
        }
        // No-grad f64 fast path (binary sibling of igamma): the no-grad path below CLONES both
        // inputs via `storage()?.to_vec()` (2x full-numel) before par_zip_map; try_f64_binary_native
        // BORROWS both contiguous buffers zero-copy. Bit-exact (same zeta_approx, index-order zip).
        if let Some(out) = self.try_f64_binary_native(s, a, zeta_approx)? {
            return Ok(out);
        }
        // f32/half: compute in f64, cast to the promoted dtype (the read is
        // f64-only). torch keeps the input dtype. frankentorch-77o4c.
        let (ds, da) = (self.tensor_dtype(s)?, self.tensor_dtype(a)?);
        if ds != DType::F64 || da != DType::F64 {
            let out_dt = Self::promote_float_pair(ds, da);
            let s64 = self.tensor_to_dtype(s, DType::F64)?;
            let a64 = self.tensor_to_dtype(a, DType::F64)?;
            let out64 = self.tensor_zeta(s64, a64)?;
            return self.tensor_to_dtype(out64, out_dt);
        }
        let (s_vals, s_shape) = {
            let t = self.tensor_tape.tensor(s)?;
            (t.storage()?.to_vec(), t.meta().shape().to_vec())
        };
        let (a_vals, a_shape) = {
            let t = self.tensor_tape.tensor(a)?;
            (t.storage()?.to_vec(), t.meta().shape().to_vec())
        };
        if s_shape != a_shape {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "zeta: inputs must have the same shape",
                },
            )));
        }

        if self.tensor_requires_grad(s)? || self.tensor_requires_grad(a)? {
            // Hurwitz ζ(s, a) is differentiable w.r.t. the parameter a:
            //   ∂ζ(s,a)/∂a = -s · ζ(s+1, a).
            // Matching torch's derivatives.yaml, the exponent s is
            // non-differentiable (its gradient is None). Forward reuses the same
            // zeta_approx, so the value is bit-identical. frankentorch-2vxa.
            return self.tensor_apply_function(
                &[s, a],
                move |ctx, inputs| {
                    let (sv, s_shape) = inputs[0];
                    let (av, _a_shape) = inputs[1];
                    let values = par_zip_map_f64(sv, av, zeta_approx);
                    ctx.save_for_backward(sv.to_vec(), s_shape.to_vec());
                    ctx.save_for_backward(av.to_vec(), s_shape.to_vec());
                    Ok((values, s_shape.to_vec()))
                },
                move |ctx, grad_outputs| {
                    let saved = ctx.saved_tensors();
                    let (sv, av) = (&saved[0], &saved[1]);
                    let g = grad_outputs[0];
                    let grad_a: Vec<f64> = (0..g.len())
                        .map(|i| g[i] * (-sv[i]) * zeta_approx(sv[i] + 1.0, av[i]))
                        .collect();
                    Ok(vec![None, Some(grad_a)])
                },
            );
        }

        let values: Vec<f64> = par_zip_map_f64(&s_vals, &a_vals, zeta_approx);
        let out = self.tensor_tape.leaf(values, s_shape, false)?;
        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!("zeta s={} a={} out={}", s.0, a.0, out.0),
        );
        Ok(out)
    }

    /// Alias for `tensor_zeta`. Equivalent to `torch.special.zeta`.
    pub fn tensor_special_zeta(
        &mut self,
        s: TensorNodeId,
        a: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_zeta(s, a)
    }

    /// Decompose floating-point numbers into mantissa and exponent.
    ///
    /// Equivalent to `torch.frexp(input)`. Returns `(mantissa, exponent)` where:
    /// - `mantissa` is in [0.5, 1.0) for positive values, (-1.0, -0.5] for negative
    /// - `exponent` is the integer power of 2
    /// - `input = mantissa * 2^exponent`
    ///
    /// For zero, both mantissa and exponent are 0.
    /// For infinities and NaN, the results follow IEEE 754 semantics.
    ///
    /// Autograd is not implemented (non-differentiable due to integer exponent).
    /// Tracked under frankentorch-zy52.
    pub fn tensor_frexp(
        &mut self,
        input: TensorNodeId,
    ) -> Result<(TensorNodeId, TensorNodeId), AutogradError> {
        // F32 input previously ERRORED at the F64-only `storage()` read, and even
        // had it not, the legacy path returns an F64 mantissa — torch.frexp keeps
        // the input dtype for the mantissa. Compute via f64 frexp and cast the
        // mantissa back to f32: frexp only rescales the exponent, so the significand
        // (hence `m as f32`) is bit-identical to torch's f32 mantissa. Exponent stays
        // f64 (the same representation the f64 path uses; values are exact integers).
        if self.tensor_dtype(input)? == DType::F32 {
            let vals = self.tensor_values_f32(input)?;
            let shape = self.tensor_shape(input)?;
            let mut mantissa = Vec::with_capacity(vals.len());
            let mut exponent = Vec::with_capacity(vals.len());
            for &v in &vals {
                let (m, e) = frexp_scalar(f64::from(v));
                mantissa.push(m as f32);
                exponent.push(e as f64);
            }
            let mantissa_node = self.tensor_variable_f32(mantissa, shape.clone(), false)?;
            let exponent_node = self.tensor_tape.leaf(exponent, shape, false)?;
            self.runtime.ledger_mut().record(
                EvidenceKind::Dispatch,
                format!(
                    "frexp in={} mantissa={} exponent={} (f32)",
                    input.0, mantissa_node.0, exponent_node.0
                ),
            );
            return Ok((mantissa_node, exponent_node));
        }
        let (vals, shape) = {
            let t = self.tensor_tape.tensor(input)?;
            (t.storage()?.to_vec(), t.meta().shape().to_vec())
        };
        let mut mantissa = Vec::with_capacity(vals.len());
        let mut exponent = Vec::with_capacity(vals.len());
        for &v in &vals {
            let (m, e) = frexp_scalar(v);
            mantissa.push(m);
            exponent.push(e as f64);
        }
        let mantissa_node = self.tensor_tape.leaf(mantissa, shape.clone(), false)?;
        let exponent_node = self.tensor_tape.leaf(exponent, shape, false)?;
        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!(
                "frexp in={} mantissa={} exponent={}",
                input.0, mantissa_node.0, exponent_node.0
            ),
        );
        Ok((mantissa_node, exponent_node))
    }

    /// In-place frexp: target becomes mantissa, returns exponent tensor.
    ///
    /// Equivalent to `torch.Tensor.frexp_()`. Updates target with mantissa
    /// values and returns the exponent tensor separately.
    pub fn tensor_frexp_(&mut self, target: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        self.validate_tensor_in_place_target(target)?;
        let (mantissa, exponent) = self.tensor_frexp(target)?;
        let mantissa_vals = self.tensor_values(mantissa)?;
        self.update_tensor_values_for_float(target, mantissa_vals, INPLACE_FLOAT_REASON)?;
        self.record_tensor_in_place_operation("frexp_", target, None);
        Ok(exponent)
    }

    /// Element-wise greatest common divisor of two integer tensors.
    ///
    /// Equivalent to `torch.gcd(input, other)`. Inputs are treated as integers
    /// (floor is applied implicitly). The result is always non-negative.
    ///
    /// Tracked under frankentorch-zy52.
    pub fn tensor_gcd(
        &mut self,
        input: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let (a_vals, a_shape) = {
            let t = self.tensor_tape.tensor(input)?;
            (t.storage()?.to_vec(), t.meta().shape().to_vec())
        };
        let (b_vals, b_shape) = {
            let t = self.tensor_tape.tensor(other)?;
            (t.storage()?.to_vec(), t.meta().shape().to_vec())
        };
        if a_shape != b_shape {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "gcd: inputs must have the same shape",
                },
            )));
        }
        // gcd_scalar is a compute-heavy per-element Euclidean loop; parallelize the map over the
        // independent lanes (par_zip preserves order => bit-identical to the serial map). The
        // per-element cost dwarfs dispatch, so this scales cleanly. frankentorch-gcd-par.
        let values: Vec<f64> = if a_vals.len() >= PARALLEL_ELEMENTWISE_MIN {
            use rayon::prelude::*;
            a_vals
                .par_iter()
                .zip(b_vals.par_iter())
                .map(|(&a, &b)| gcd_scalar(a as i64, b as i64) as f64)
                .collect()
        } else {
            a_vals
                .iter()
                .zip(b_vals.iter())
                .map(|(&a, &b)| gcd_scalar(a as i64, b as i64) as f64)
                .collect()
        };
        let out = self.tensor_tape.leaf(values, a_shape, false)?;
        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!("gcd a={} b={} out={}", input.0, other.0, out.0),
        );
        Ok(out)
    }

    /// Element-wise least common multiple of two integer tensors.
    ///
    /// Equivalent to `torch.lcm(input, other)`. Inputs are treated as integers
    /// (floor is applied implicitly). The result is always non-negative.
    /// Returns 0 if either input is 0.
    ///
    /// Tracked under frankentorch-zy52.
    pub fn tensor_lcm(
        &mut self,
        input: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let (a_vals, a_shape) = {
            let t = self.tensor_tape.tensor(input)?;
            (t.storage()?.to_vec(), t.meta().shape().to_vec())
        };
        let (b_vals, b_shape) = {
            let t = self.tensor_tape.tensor(other)?;
            (t.storage()?.to_vec(), t.meta().shape().to_vec())
        };
        if a_shape != b_shape {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "lcm: inputs must have the same shape",
                },
            )));
        }
        // lcm_scalar = |a*b|/gcd(a,b) — a compute-heavy per-element Euclidean loop; parallelize the
        // map over the independent lanes (par_zip preserves order => bit-identical). frankentorch-gcd-par.
        let values: Vec<f64> = if a_vals.len() >= PARALLEL_ELEMENTWISE_MIN {
            use rayon::prelude::*;
            a_vals
                .par_iter()
                .zip(b_vals.par_iter())
                .map(|(&a, &b)| lcm_scalar(a as i64, b as i64) as f64)
                .collect()
        } else {
            a_vals
                .iter()
                .zip(b_vals.iter())
                .map(|(&a, &b)| lcm_scalar(a as i64, b as i64) as f64)
                .collect()
        };
        let out = self.tensor_tape.leaf(values, a_shape, false)?;
        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!("lcm a={} b={} out={}", input.0, other.0, out.0),
        );
        Ok(out)
    }

    /// In-place gcd: target = gcd(target, other).
    pub fn tensor_gcd_(
        &mut self,
        target: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<(), AutogradError> {
        self.validate_tensor_in_place_target(target)?;
        // F64 borrow+parallel fast path (Euclidean gcd loop = compute-heavy).
        // frankentorch-inplace-binary-fastpath.
        if self.try_inplace_binary_f64(target, other, "gcd_", |a, b| {
            gcd_scalar(a as i64, b as i64) as f64
        })? {
            return Ok(());
        }
        let target_vals = self.tensor_values_lossy_f64(target)?;
        let other_vals = self.tensor_values_lossy_f64(other)?;
        if target_vals.len() != other_vals.len() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: self.tensor_shape(target)?,
                    rhs: self.tensor_shape(other)?,
                },
            )));
        }
        let result: Vec<f64> = target_vals
            .iter()
            .zip(other_vals.iter())
            .map(|(&a, &b)| gcd_scalar(a as i64, b as i64) as f64)
            .collect();
        self.update_tensor_values_for_float(target, result, INPLACE_FLOAT_REASON)?;
        self.record_tensor_in_place_operation("gcd_", target, None);
        Ok(())
    }

    /// In-place lcm: target = lcm(target, other).
    pub fn tensor_lcm_(
        &mut self,
        target: TensorNodeId,
        other: TensorNodeId,
    ) -> Result<(), AutogradError> {
        self.validate_tensor_in_place_target(target)?;
        // F64 borrow+parallel fast path (lcm via gcd = compute-heavy).
        // frankentorch-inplace-binary-fastpath.
        if self.try_inplace_binary_f64(target, other, "lcm_", |a, b| {
            lcm_scalar(a as i64, b as i64) as f64
        })? {
            return Ok(());
        }
        let target_vals = self.tensor_values_lossy_f64(target)?;
        let other_vals = self.tensor_values_lossy_f64(other)?;
        if target_vals.len() != other_vals.len() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::ShapeMismatch {
                    lhs: self.tensor_shape(target)?,
                    rhs: self.tensor_shape(other)?,
                },
            )));
        }
        let result: Vec<f64> = target_vals
            .iter()
            .zip(other_vals.iter())
            .map(|(&a, &b)| lcm_scalar(a as i64, b as i64) as f64)
            .collect();
        self.update_tensor_values_for_float(target, result, INPLACE_FLOAT_REASON)?;
        self.record_tensor_in_place_operation("lcm_", target, None);
        Ok(())
    }

