    /// Element-wise entropy: -x * log(x).
    ///
    /// Equivalent to `torch.special.entr(input)`.
    /// Returns 0 when x == 0 and -inf when x < 0.
    ///
    /// Composes through tensor_neg + tensor_log + tensor_mul +
    /// tensor_eq + tensor_lt + tensor_where so the autograd tape
    /// carries gradients through the input. Previously this had a
    /// fail-loud guard rejecting tracked inputs because the body
    /// extracted values and rebuilt a requires_grad=false leaf —
    /// same severed-autograd pattern as the recent xlogy / xlog1py
    /// / logit fixes. PyTorch's torch.special.entr is differentiable
    /// on the open positive half-line. Tracked under
    /// frankentorch-1tax.
    ///
    /// Composition (nested where):
    ///     entr(x) = where(x < 0, -inf,
    ///                    where(x == 0, 0,
    ///                          -x * log(x)))
    ///
    /// Backward (chain rule on the smooth branch):
    ///     d entr / dx where x > 0 = -log(x) - 1
    /// Where x <= 0 the masks block gradient flow through the
    /// constant branches, so the gradient is zero (rather than
    /// undefined / +inf at x = 0).
    pub fn tensor_entr(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        // f32-native fast path: the f32 branch below UPCASTS to f64 (to_dtype) then narrows.
        // Same value (`x<0 ? -inf : x==0 ? 0 : -x*ln(x)` in f64, narrowed) = bit-identical.
        if let Some(out) = self.try_f32_unary_native(input, |x| {
            if x < 0.0 {
                f64::NEG_INFINITY
            } else if x == 0.0 {
                0.0
            } else {
                -x * x.ln()
            }
        })? {
            return Ok(out);
        }
        // f32/half: compute in f64 then cast back (full()-built constants are F64
        // and fail the matching-dtype comparison). torch keeps the input dtype.
        // frankentorch-x9yuq.
        let dt = self.tensor_dtype(input)?;
        if dt != DType::F64 {
            let in64 = self.tensor_to_dtype(input, DType::F64)?;
            let out64 = self.tensor_entr(in64)?;
            return self.tensor_to_dtype(out64, dt);
        }
        // No-grad fast path: the composed path below (log + neg + mul + full + eq + where +
        // lt + full + where = ~9 passes) measured 4.97x SLOWER than torch. For no-grad
        // contiguous f64, borrow the input and compute entr(x) = x<0 ? -inf : (x==0 ? 0 :
        // -x*ln(x)) in ONE parallel pass. Bit-exact with the composed two-where path (same
        // (-x)*ln(x) grouping; x==0 -> 0, x<0 -> -inf, NaN -> NaN). grad / non-contiguous
        // fall through.
        if !self.tensor_requires_grad(input)? {
            let built = {
                let it = self.tensor_tape.tensor(input)?;
                if it.meta().is_contiguous() {
                    let xd = it.contiguous_values()?;
                    use rayon::prelude::*;
                    let out: Vec<f64> = xd
                        .par_iter()
                        .map(|&x| {
                            if x < 0.0 {
                                f64::NEG_INFINITY
                            } else if x == 0.0 {
                                0.0
                            } else {
                                -x * x.ln()
                            }
                        })
                        .collect();
                    Some(out)
                } else {
                    None
                }
            };
            if let Some(out) = built {
                let shape = self.tensor_shape(input)?;
                return self.tensor_variable(out, shape, false);
            }
        }
        let shape = self.tensor_shape(input)?;
        let log_x = self.tensor_log(input)?;
        let neg_input = self.tensor_neg(input)?;
        let neg_x_log_x = self.tensor_mul(neg_input, log_x)?;

        // Single zeros tensor shared across the eq mask, where-true
        // branch, and lt mask (frankentorch-x8r1) — tensor_eq /
        // tensor_where / tensor_lt only READ their operands.
        let zeros = self.full(shape.clone(), 0.0, false)?;
        let mask_zero = self.tensor_eq(input, zeros)?;
        let inner = self.tensor_where(mask_zero, zeros, neg_x_log_x)?;
        let mask_neg = self.tensor_lt(input, zeros)?;
        let neg_inf = self.full(shape, f64::NEG_INFINITY, false)?;
        let out = self.tensor_where(mask_neg, neg_inf, inner)?;

        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!("entr in={} out={}", input.0, out.0),
        );
        Ok(out)
    }

    /// Alias for `tensor_entr`. Equivalent to `torch.special.entr`.
    pub fn tensor_special_entr(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_entr(input)
    }

    /// Relative entropy (element-wise).
    ///
    /// Computes x * log(x / y) with special cases:
    /// - rel_entr(0, y) = 0 when y >= 0
    /// - rel_entr(x, y) = +inf when x > 0 and y <= 0
    /// - rel_entr(x, y) = +inf when x < 0
    ///
    /// Equivalent to `scipy.special.rel_entr`.
    pub fn tensor_rel_entr(
        &mut self,
        x: TensorNodeId,
        y: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // f32-native fast path: the f32 branch below UPCASTS to f64 + composes ~10 tape ops
        // (lt/le/gt/and/eq/div/log/mul/where x3) + narrows. Single-closure equivalent (same
        // where-precedence: x==0 -> 0; x<0 -> inf; x>0 && y<=0 -> inf; else x*ln(x/y)), in f64
        // narrowed = bit-identical to current f32. Equal-shape both-f32 only (helper checks).
        if let Some(out) = self.try_f32_binary_native(x, y, |xi, yi| {
            if xi == 0.0 {
                0.0
            } else if xi < 0.0 {
                f64::INFINITY
            } else if yi <= 0.0 {
                f64::INFINITY
            } else {
                xi * (xi / yi).ln()
            }
        })? {
            return Ok(out);
        }
        // f64-native no-grad fast path (the f64 compose below is ~13 tape passes). The compose's
        // where-precedence is x==0 -> 0; (y<=0 AND x>0) -> inf; x<0 -> inf; else x*ln(x/y). The y<=0
        // arm REQUIRES x>0 (via y_invalid = y_le_zero AND x_pos), so x=NaN,y<=0 -> NaN (falls to the
        // else), NOT inf — matched exactly here for bit-exactness to the compose (the f32 closure
        // above elides the x>0 guard; its edge isn't conformance-covered, kept as-is to avoid churn).
        if let Some(out) = self.try_f64_binary_native(x, y, |xi, yi| {
            if xi == 0.0 {
                0.0
            } else if yi <= 0.0 && xi > 0.0 {
                f64::INFINITY
            } else if xi < 0.0 {
                f64::INFINITY
            } else {
                xi * (xi / yi).ln()
            }
        })? {
            return Ok(out);
        }
        // f32/half: compute in f64, cast to the promoted dtype (full() constants
        // are F64 and fail the matching-dtype comparison). frankentorch-77o4c.
        let (dx, dy) = (self.tensor_dtype(x)?, self.tensor_dtype(y)?);
        if dx != DType::F64 || dy != DType::F64 {
            let out_dt = Self::promote_float_pair(dx, dy);
            let x64 = self.tensor_to_dtype(x, DType::F64)?;
            let y64 = self.tensor_to_dtype(y, DType::F64)?;
            let out64 = self.tensor_rel_entr(x64, y64)?;
            return self.tensor_to_dtype(out64, out_dt);
        }
        let shape = self.tensor_shape(x)?;
        let zeros = self.full(shape.clone(), 0.0, false)?;
        let inf = self.full(shape.clone(), f64::INFINITY, false)?;

        // x < 0 => +inf
        let x_neg = self.tensor_lt(x, zeros)?;

        // y <= 0 AND x > 0 => +inf
        let y_le_zero = self.tensor_le(y, zeros)?;
        let x_pos = self.tensor_gt(x, zeros)?;
        let y_invalid = self.tensor_logical_and(y_le_zero, x_pos)?;

        // x == 0 => 0
        let x_eq_zero = self.tensor_eq(x, zeros)?;

        // General case: x * log(x / y)
        let ratio = self.tensor_div(x, y)?;
        let log_ratio = self.tensor_log(ratio)?;
        let x_log_ratio = self.tensor_mul(x, log_ratio)?;

        // Apply conditions: x<0 => inf, y<=0 && x>0 => inf, x==0 => 0, else x*log(x/y)
        let result = self.tensor_where(x_neg, inf, x_log_ratio)?;
        let result = self.tensor_where(y_invalid, inf, result)?;
        let result = self.tensor_where(x_eq_zero, zeros, result)?;

        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!("rel_entr x={} y={} out={}", x.0, y.0, result.0),
        );
        Ok(result)
    }

    /// Alias for `tensor_rel_entr`. Equivalent to `scipy.special.rel_entr`.
    pub fn tensor_special_rel_entr(
        &mut self,
        x: TensorNodeId,
        y: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_rel_entr(x, y)
    }

    // ── logcumsumexp ─────────────────────────────────────────────────────
    /// Numerically stable cumulative log-sum-exp along a dimension.
    ///
    /// Equivalent to `torch.logcumsumexp(input, dim)`.
    /// Computes `log(cumsum(exp(input), dim))` in a numerically stable way.
    ///
    /// Wraps the stable forward in a `tensor_apply_function` so that
    /// the autograd tape carries gradients through the input. The
    /// analytical derivative for `y[i] = log(sum_{j<=i} exp(x[j]))` is
    ///     dy[i]/dx[k] = exp(x[k] - y[i])  if k <= i, else 0
    /// so the vector–Jacobian product is
    ///     dL/dx[k] = sum_{i>=k} dL/dy[i] * exp(x[k] - y[i])
    /// which is bounded since `x[k] <= y[i]` for `i >= k`. Both `x`
    /// and `y` are saved for backward. Tracked under
    /// frankentorch-1tax — same severed-autograd pattern recently
    /// fixed for gammaln / digamma / polygamma / multigammaln /
    /// erfinv.
    pub fn tensor_logcumsumexp(
        &mut self,
        input: TensorNodeId,
        dim: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        // Validate dim up front before delegating to apply_function so
        // the error path matches the previous fail-loud behavior.
        let ndim = self.tensor_tape.tensor(input)?.meta().shape().len();
        if dim >= ndim {
            // Surface actual (dim, ndim) via the dynamic-diagnostic
            // pattern (frankentorch-ovad).
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::InvalidDimension { dim, ndim },
            )));
        }

        let out = self.tensor_apply_function(
            &[input],
            move |ctx, inputs| {
                let (vals, shape) = inputs[0];

                let outer_size =
                    Self::checked_shape_numel(&shape[..dim], "logcumsumexp: outer shape overflow")?;
                let dim_size = shape[dim];
                let inner_size = Self::checked_shape_numel(
                    &shape[dim + 1..],
                    "logcumsumexp: inner shape overflow",
                )?;

                let mut result = vec![0.0_f64; vals.len()];
                let lane = dim_size * inner_size;
                // Each (outer,inner) lane is independent (private running_max/running_sum)
                // and the inner work is transcendental-heavy (exp/ln per element) =
                // compute-bound, so fan the outer blocks over Rayon. Bit-for-bit identical
                // to the serial scan (per-lane accumulation order unchanged). Mirrors the
                // cumprod/cumsum lane parallelization. frankentorch-lcse-par.
                let compute_lane = |outer_base: usize, out_chunk: &mut [f64]| {
                    for inner in 0..inner_size {
                        let mut running_max = f64::NEG_INFINITY;
                        let mut running_sum = 0.0_f64;
                        for d in 0..dim_size {
                            let local = d * inner_size + inner;
                            let val = vals[outer_base + local];
                            // When the running max equals val and both are infinite
                            // (e.g. a leading -inf, or repeated +inf), the max-shift
                            // `(val - running_max).exp()` becomes `(±inf - ±inf).exp()`
                            // = NaN, poisoning the cumulative result. torch keeps the
                            // cumulative logsumexp at that infinity, so do the same.
                            if val == running_max && val.is_infinite() {
                                out_chunk[local] = val;
                                continue;
                            }
                            if val > running_max {
                                running_sum = running_sum * (running_max - val).exp() + 1.0;
                                running_max = val;
                            } else {
                                running_sum += (val - running_max).exp();
                            }
                            out_chunk[local] = running_max + running_sum.ln();
                        }
                    }
                };
                if vals.len() >= PARALLEL_ELEMENTWISE_MIN && outer_size >= 2 {
                    use rayon::prelude::*;
                    result
                        .par_chunks_mut(lane)
                        .enumerate()
                        .for_each(|(outer, out_chunk)| compute_lane(outer * lane, out_chunk));
                } else {
                    for outer in 0..outer_size {
                        let base = outer * lane;
                        compute_lane(base, &mut result[base..base + lane]);
                    }
                }

                // Save x, then y, both as flat tensors with the full shape — the backward
                // needs to walk the same dim. Skip the 2x numel clones entirely when no
                // input needs grad (inference): apply_function returns a plain Leaf and
                // discards ctx in that case, so the saved tensors are provably dead work.
                // This removes the serial tape-clone ceiling that otherwise caps the
                // parallel forward win. frankentorch-lcsefp.
                if ctx.needs_input_grad().iter().any(|&g| g) {
                    ctx.save_for_backward(vals.to_vec(), shape.to_vec());
                    ctx.save_for_backward(result.clone(), shape.to_vec());
                }
                Ok((result, shape.to_vec()))
            },
            move |ctx, grad_outputs| {
                let grad_y = grad_outputs[0];
                let saved = ctx.saved_tensors();
                let saved_shapes = ctx.saved_shapes();
                let x_vals = &saved[0];
                let y_vals = &saved[1];
                let shape = &saved_shapes[0];

                if grad_y.len() != y_vals.len() {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "logcumsumexp backward: incoming gradient length mismatch",
                        },
                    )));
                }

                let outer_size = Self::checked_shape_numel(
                    &shape[..dim],
                    "logcumsumexp backward: outer shape overflow",
                )?;
                let dim_size = shape[dim];
                let inner_size = Self::checked_shape_numel(
                    &shape[dim + 1..],
                    "logcumsumexp backward: inner shape overflow",
                )?;

                let mut grad_x = vec![0.0_f64; x_vals.len()];
                let lane = dim_size * inner_size;
                // Each (outer,inner) lane's gradient is the direct O(D^2) sum over its
                // own dim slice (reads absolute, writes lane-local), so the outer blocks
                // are independent and fan out over Rayon bit-for-bit identically to the
                // serial loop (per-lane accumulation order unchanged). The O(D^2) exp
                // makes this compute-bound. Mirrors the cumprod_backward lane parallel.
                let compute_lane = |base: usize, out_chunk: &mut [f64]| {
                    for inner in 0..inner_size {
                        // Reverse cumulative form: walk the dim backwards accumulating
                        // dL/dy[i] * exp(-y[i]) and at each k multiply by exp(x[k]). All
                        // values of `x[k] - y[i]` are <= 0, so no overflow; underflow goes
                        // to 0 correctly. The direct O(D^2) sum avoids the precision
                        // pitfalls of an explicit reverse cumsum when y[i] is large.
                        for k in 0..dim_size {
                            let k_local = k * inner_size + inner;
                            let xk = x_vals[base + k_local];
                            let mut acc = 0.0_f64;
                            for i in k..dim_size {
                                let i_idx = base + i * inner_size + inner;
                                let yi = y_vals[i_idx];
                                acc += grad_y[i_idx] * (xk - yi).exp();
                            }
                            out_chunk[k_local] = acc;
                        }
                    }
                };
                if x_vals.len() >= PARALLEL_ELEMENTWISE_MIN && outer_size >= 2 {
                    use rayon::prelude::*;
                    grad_x
                        .par_chunks_mut(lane)
                        .enumerate()
                        .for_each(|(outer, out_chunk)| compute_lane(outer * lane, out_chunk));
                } else {
                    for outer in 0..outer_size {
                        let base = outer * lane;
                        compute_lane(base, &mut grad_x[base..base + lane]);
                    }
                }

                Ok(vec![Some(grad_x)])
            },
        )?;

        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!("logcumsumexp input={} dim={dim} out={}", input.0, out.0),
        );
        Ok(out)
    }

    // ── rot90 ───────────────────────────────────────────────────────────
    /// Rotate a tensor by 90 degrees in the plane specified by `dims`.
    ///
    /// Equivalent to `torch.rot90(input, k, dims)`.
    /// `k` is the number of times to rotate (may be negative).
    /// `dims` must be a pair `[d0, d1]` specifying the rotation plane.
    pub fn tensor_rot90(
        &mut self,
        input: TensorNodeId,
        k: i32,
        dims: [usize; 2],
    ) -> Result<TensorNodeId, AutogradError> {
        let ndim = {
            let tensor = self.tensor_tape.tensor(input)?;
            tensor.meta().shape().len()
        };

        if dims[0] == dims[1] {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "rot90: dims must specify two different dimensions",
                },
            )));
        }
        if dims[0] >= ndim || dims[1] >= ndim {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "rot90: dimension index out of range",
                },
            )));
        }

        // Normalize k to [0, 4)
        let k = k.rem_euclid(4);

        if matches!(k, 1 | 3) {
            if let Some(out) = self.tensor_rot90_2d_nograd_fast_path(input, k, dims)? {
                return Ok(out);
            }
        }

        match k {
            0 => {
                // No rotation — return a clone preserving grad behavior
                let requires_grad = self.tensor_tape.tensor_requires_grad(input)?;
                self.tensor_clone(input, requires_grad)
            }
            1 => {
                // 90° rotation: flip(transpose(input, d0, d1), d0)
                let transposed = self.tensor_transpose(input, dims[0], dims[1])?;
                self.tensor_flip(transposed, &[dims[0]])
            }
            2 => {
                // 180° rotation: flip along both dims. A single multi-dim flip does this in
                // ONE pass (the no-grad flip fast path handles multi-dim) instead of two
                // separate flip materializations — bit-identical (disjoint dims commute).
                self.tensor_flip(input, &[dims[0], dims[1]])
            }
            3 => {
                // 270° rotation: flip(transpose(input, d0, d1), d1)
                let transposed = self.tensor_transpose(input, dims[0], dims[1])?;
                self.tensor_flip(transposed, &[dims[1]])
            }
            _ => Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "rot90: normalized k out of range",
                },
            ))),
        }
    }

    fn tensor_rot90_2d_nograd_fast_path(
        &mut self,
        input: TensorNodeId,
        k: i32,
        dims: [usize; 2],
    ) -> Result<Option<TensorNodeId>, AutogradError> {
        // No-grad single-pass fast path for the common 2-D `rot90(k=1|3, [0,1])`. The default
        // path composes `flip(transpose(x))` — TWO full materializations (transpose intermediate +
        // flip). Here we gather the rotated output in ONE parallel pass. Pure positional movement
        // => bit-identical to the compose. Originally f64-only; f32 fell through to the 2-pass
        // compose (the asymmetric-dtype gap, ~31x SLOWER than torch at [2048,2048]) — now both.
        if dims != [0, 1] || self.tensor_tape.tensor_requires_grad(input)? {
            return Ok(None);
        }
        let dtype = self.tensor_dtype(input)?;
        if !matches!(dtype, DType::F64 | DType::F32) {
            return Ok(None);
        }
        let (rows, cols) = {
            let tensor = self.tensor_tape.tensor(input)?;
            let shape = tensor.meta().shape();
            if shape.len() != 2 || !tensor.meta().is_contiguous() {
                return Ok(None);
            }
            (shape[0], shape[1])
        };
        let len = match rows.checked_mul(cols) {
            Some(l) => l,
            None => return Ok(None),
        };

        // Output shape [cols, rows]:
        //   k=1: out[a,b] = in[b, cols-1-a]   (transpose then flip dim0)
        //   k=3: out[a,b] = in[rows-1-b, a]   (transpose then flip dim1)
        // A naive single-pass gather reads down a column (stride = `cols`), wasting ~15/16 of
        // every cache line — the strided-transpose wall (~20x SLOWER than torch). Instead tile
        // the output into TILE×TILE blocks: read the matching input block via CONTIGUOUS row runs
        // into an L1-resident buffer, transpose+flip inside the buffer, then write output rows
        // contiguously. Bit-identical (pure positional movement), ~sequential memory traffic.
        const TILE: usize = 64;
        macro_rules! rot90_build {
            ($read:ident, $zero:expr, $build:ident) => {{
                let vals = self.tensor_tape.tensor(input)?.$read()?;
                if vals.len() != len {
                    return Ok(None);
                }
                let mut out = vec![$zero; len];
                // Each output chunk owns TILE consecutive output rows (a-tile); a0 = t*TILE.
                let a_tile = |a0: usize, chunk: &mut [_]| {
                    let ta = TILE.min(cols - a0);
                    let mut buf = [$zero; TILE * TILE];
                    let mut b0 = 0;
                    while b0 < rows {
                        let tb = TILE.min(rows - b0);
                        match k {
                            1 => {
                                // input block: rows [b0,b0+tb), cols [cols-a0-ta, cols-a0)
                                let cbase = cols - a0 - ta;
                                for bi in 0..tb {
                                    let src = &vals[(b0 + bi) * cols + cbase..][..ta];
                                    buf[bi * TILE..bi * TILE + ta].copy_from_slice(src);
                                }
                                // out[a0+ai, b0+bi] = in[b0+bi, cols-1-(a0+ai)] = buf[bi][ta-1-ai]
                                for ai in 0..ta {
                                    let orow = &mut chunk[ai * rows + b0..][..tb];
                                    for (bi, slot) in orow.iter_mut().enumerate() {
                                        *slot = buf[bi * TILE + (ta - 1 - ai)];
                                    }
                                }
                            }
                            3 => {
                                // input block: rows [rows-b0-tb, rows-b0), cols [a0, a0+ta)
                                for bi in 0..tb {
                                    let r = rows - 1 - b0 - bi;
                                    let src = &vals[r * cols + a0..][..ta];
                                    buf[bi * TILE..bi * TILE + ta].copy_from_slice(src);
                                }
                                // out[a0+ai, b0+bi] = in[rows-1-(b0+bi), a0+ai] = buf[bi][ai]
                                for ai in 0..ta {
                                    let orow = &mut chunk[ai * rows + b0..][..tb];
                                    for (bi, slot) in orow.iter_mut().enumerate() {
                                        *slot = buf[bi * TILE + ai];
                                    }
                                }
                            }
                            _ => unreachable!("rot90 fast path only handles k=1 or k=3"),
                        }
                        b0 += TILE;
                    }
                };
                if len >= PARALLEL_ELEMENTWISE_MIN && rows >= 2 && cols >= 2 {
                    use rayon::prelude::*;
                    out.par_chunks_mut(TILE * rows)
                        .enumerate()
                        .for_each(|(t, chunk)| a_tile(t * TILE, chunk));
                } else {
                    out.chunks_mut(TILE * rows)
                        .enumerate()
                        .for_each(|(t, chunk)| a_tile(t * TILE, chunk));
                }
                return self.$build(out, vec![cols, rows], false).map(Some);
            }};
        }
        match dtype {
            DType::F64 => rot90_build!(contiguous_values, 0.0_f64, tensor_variable),
            DType::F32 => rot90_build!(contiguous_values_f32, 0.0_f32, tensor_variable_f32),
            _ => Ok(None),
        }
    }

    // ── pixel_shuffle ───────────────────────────────────────────────────
    /// Rearrange elements from channels into spatial dimensions.
    ///
    /// Equivalent to `torch.nn.functional.pixel_shuffle(input, upscale_factor)`.
    /// Input shape: `(N, C * r^2, H, W)` → Output: `(N, C, H*r, W*r)`
    pub fn tensor_pixel_shuffle(
        &mut self,
        input: TensorNodeId,
        upscale_factor: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = {
            let t = self.tensor_tape.tensor(input)?;
            t.meta().shape().to_vec()
        };

        if shape.len() != 4 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "pixel_shuffle: input must be a 4-D tensor (N, C, H, W)",
                },
            )));
        }

        let (batch, channels, h, w) = (shape[0], shape[1], shape[2], shape[3]);
        let r = upscale_factor;
        if r == 0 {
            return Err(Self::incompatible_tensor_args(
                "pixel_shuffle: upscale_factor must be greater than zero",
            ));
        }
        let r_squared = Self::checked_mul(r, r, "pixel_shuffle: upscale_factor squared overflow")?;

        if channels % r_squared != 0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "pixel_shuffle: channels must be divisible by upscale_factor^2",
                },
            )));
        }

        let oc = channels / r_squared;
        let out_h = Self::checked_mul(h, r, "pixel_shuffle: output height overflow")?;
        let out_w = Self::checked_mul(w, r, "pixel_shuffle: output width overflow")?;

        // reshape to (N, C, r, r, H, W)
        let reshaped = self.tensor_reshape(input, vec![batch, oc, r, r, h, w])?;
        // permute to (N, C, H, r, W, r)
        let permuted = self.tensor_permute(reshaped, vec![0, 1, 4, 2, 5, 3])?;
        // reshape to (N, C, H*r, W*r)
        self.tensor_reshape(permuted, vec![batch, oc, out_h, out_w])
    }

    // ── pixel_unshuffle ─────────────────────────────────────────────────
    /// Reverse of pixel_shuffle: rearrange spatial dimensions into channels.
    ///
    /// Equivalent to `torch.nn.functional.pixel_unshuffle(input, downscale_factor)`.
    /// Input shape: `(N, C, H*r, W*r)` → Output: `(N, C * r^2, H, W)`
    pub fn tensor_pixel_unshuffle(
        &mut self,
        input: TensorNodeId,
        downscale_factor: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = {
            let t = self.tensor_tape.tensor(input)?;
            t.meta().shape().to_vec()
        };

        if shape.len() != 4 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "pixel_unshuffle: input must be a 4-D tensor (N, C, H, W)",
                },
            )));
        }

        let (batch, channels, h, w) = (shape[0], shape[1], shape[2], shape[3]);
        let r = downscale_factor;
        if r == 0 {
            return Err(Self::incompatible_tensor_args(
                "pixel_unshuffle: downscale_factor must be greater than zero",
            ));
        }
        let r_squared =
            Self::checked_mul(r, r, "pixel_unshuffle: downscale_factor squared overflow")?;

        if h % r != 0 || w % r != 0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "pixel_unshuffle: H and W must be divisible by downscale_factor",
                },
            )));
        }

        let oh = h / r;
        let ow = w / r;
        let out_channels = Self::checked_mul(
            channels,
            r_squared,
            "pixel_unshuffle: output channel count overflow",
        )?;

        // reshape to (N, C, H/r, r, W/r, r)
        let reshaped = self.tensor_reshape(input, vec![batch, channels, oh, r, ow, r])?;
        // permute to (N, C, r, r, H/r, W/r)
        let permuted = self.tensor_permute(reshaped, vec![0, 1, 3, 5, 2, 4])?;
        // reshape to (N, C*r*r, H/r, W/r)
        self.tensor_reshape(permuted, vec![batch, out_channels, oh, ow])
    }

    /// Rearrange channels by splitting into groups and interleaving.
    ///
    /// Equivalent to `torch.nn.functional.channel_shuffle(input, groups)`.
    /// Input shape: `(N, C, H, W)` where C must be divisible by groups.
    /// Tracked under frankentorch-gwqo.
    pub fn tensor_channel_shuffle(
        &mut self,
        input: TensorNodeId,
        groups: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        if shape.len() != 4 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "channel_shuffle: input must be a 4-D tensor (N, C, H, W)",
                },
            )));
        }

        let (batch, channels, h, w) = (shape[0], shape[1], shape[2], shape[3]);
        if groups == 0 || channels % groups != 0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "channel_shuffle: channels must be divisible by groups",
                },
            )));
        }

        let channels_per_group = channels / groups;

        // reshape to (N, groups, channels_per_group, H, W)
        let reshaped = self.tensor_reshape(input, vec![batch, groups, channels_per_group, h, w])?;
        // transpose to (N, channels_per_group, groups, H, W)
        let transposed = self.tensor_permute(reshaped, vec![0, 2, 1, 3, 4])?;
        // reshape back to (N, C, H, W)
        self.tensor_reshape(transposed, vec![batch, channels, h, w])
    }

    // ── F.interpolate ────────────────────────────────────────────────────

    /// Interpolate (resize) a tensor using the specified mode.
    ///
    /// Equivalent to `torch.nn.functional.interpolate(input, size, scale_factor, mode, align_corners)`.
    ///
    /// Supports:
    /// - 3-D input `[N, C, L]` (temporal): nearest, linear
    /// - 4-D input `[N, C, H, W]` (spatial): nearest, bilinear, bicubic
    /// - 5-D input `[N, C, D, H, W]` (volumetric): nearest, trilinear
    ///
    /// Either `size` or `scale_factor` must be provided (not both).
    /// `align_corners` applies only to linear/bilinear/bicubic/trilinear modes.
    pub fn tensor_interpolate(
        &mut self,
        input: TensorNodeId,
        size: Option<Vec<usize>>,
        scale_factor: Option<Vec<f64>>,
        mode: &str,
        align_corners: Option<bool>,
    ) -> Result<TensorNodeId, AutogradError> {
        // Autograd-aware path for `mode="nearest"` (frankentorch-ov0v):
        // nearest interpolation is just a structured index_select per
        // spatial axis, so we can flatten the input to [N*C, Hin*Win*...],
        // compute the source-position index for each output position,
        // and tensor_index_select. Other modes (linear/bilinear/etc.)
        // need bespoke backwards via index_select + weighted sums; for
        // now, fail loud on requires_grad input to surface the silent
        // severance that the legacy plain-f64 path produced.
        let requires_grad = self.tensor_requires_grad(input)?;

        // Native f32 fast path. The legacy plain-f64 path below reads
        // `tensor.storage()` (F64-only), so F32 input previously ERRORED with
        // `UnsupportedStorageAccess { dtype: F32 }`. torch returns F32 for F32
        // input; here we sample natively in f32 (half the read+write traffic, no
        // f32->f64 widening) and return an F32 tensor. Interpolation is a
        // tolerance op (the parity goldens assert `< 1e-5`); coordinates/weights
        // are still computed in f64 for robust flooring, only the per-output
        // accumulation and storage are f32, which matches torch within ~1e-6.
        // Inference-only — requires_grad keeps the existing f64 autograd helpers.
        if !requires_grad && self.tensor_dtype(input)? == DType::F32 {
            return self.interpolate_f32(input, size, scale_factor, mode, align_corners);
        }

        let meta = self.tensor_tape.tensor(input)?.meta().clone();
        let shape = meta.shape();
        let ndim = shape.len();

        if !(3..=5).contains(&ndim) {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "interpolate: input must be 3-D, 4-D, or 5-D",
                },
            )));
        }

        if size.is_some() && scale_factor.is_some() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "interpolate: only one of size or scale_factor should be defined",
                },
            )));
        }

        let spatial_dims = ndim - 2;
        let in_spatial: Vec<usize> = shape[2..].to_vec();
        if in_spatial.contains(&0) {
            return Err(Self::incompatible_tensor_args(
                "interpolate: input spatial dimensions must be > 0",
            ));
        }

        let out_spatial: Vec<usize> = if let Some(ref s) = size {
            if s.len() != spatial_dims {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "interpolate: size length must match spatial dimensions",
                    },
                )));
            }
            if s.contains(&0) {
                return Err(Self::incompatible_tensor_args(
                    "interpolate: output spatial dimensions must be > 0",
                ));
            }
            s.clone()
        } else if let Some(ref sf) = scale_factor {
            if sf.len() != spatial_dims {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "interpolate: scale_factor length must match spatial dimensions",
                    },
                )));
            }
            in_spatial
                .iter()
                .zip(sf.iter())
                .map(|(&d, &s)| Self::checked_interpolate_scale_dim(d, s))
                .collect::<Result<Vec<_>, _>>()?
        } else {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "interpolate: either size or scale_factor must be provided",
                },
            )));
        };

        let batch = shape[0];
        let channels = shape[1];
        let mut checked_out_shape = vec![batch, channels];
        checked_out_shape.extend_from_slice(&out_spatial);
        let out_numel =
            Self::checked_shape_numel(&checked_out_shape, "interpolate: output size overflow")?;
        let _ = Self::checked_mul(
            out_numel,
            std::mem::size_of::<f64>(),
            "interpolate: output size overflow",
        )?;
        let align = align_corners.unwrap_or(false);

        match mode {
            "nearest" | "nearest-exact" => {
                // 'nearest-exact' samples the pixel center (torch's corrected
                // off-by-one); 'nearest' uses the legacy floor formula. Both share
                // the same index machinery, parameterized by `exact`.
                let exact = mode == "nearest-exact";
                if requires_grad {
                    self.interpolate_nearest_autograd(
                        input,
                        batch,
                        channels,
                        &in_spatial,
                        &out_spatial,
                        exact,
                    )
                } else {
                    let storage = self.tensor_tape.tensor(input)?.storage()?.to_vec();
                    self.interpolate_nearest(
                        &storage,
                        batch,
                        channels,
                        &in_spatial,
                        &out_spatial,
                        exact,
                    )
                }
            }
            "linear" if spatial_dims == 1 => {
                if requires_grad {
                    self.interpolate_linear_1d_autograd(
                        input,
                        batch,
                        channels,
                        in_spatial[0],
                        out_spatial[0],
                        align,
                    )
                } else {
                    let storage = self.tensor_tape.tensor(input)?.storage()?.to_vec();
                    self.interpolate_linear_1d(
                        &storage,
                        batch,
                        channels,
                        in_spatial[0],
                        out_spatial[0],
                        align,
                    )
                }
            }
            "bilinear" if spatial_dims == 2 => {
                if requires_grad {
                    self.interpolate_bilinear_autograd(
                        input,
                        batch,
                        channels,
                        &in_spatial,
                        &out_spatial,
                        align,
                    )
                } else {
                    let storage = self.tensor_tape.tensor(input)?.storage()?.to_vec();
                    self.interpolate_bilinear(
                        &storage,
                        batch,
                        channels,
                        &in_spatial,
                        &out_spatial,
                        align,
                    )
                }
            }
            "bicubic" if spatial_dims == 2 => {
                if requires_grad {
                    self.interpolate_bicubic_autograd(
                        input,
                        batch,
                        channels,
                        &in_spatial,
                        &out_spatial,
                        align,
                    )
                } else {
                    let borrowed_values = {
                        let tensor = self.tensor_tape.tensor(input)?;
                        if tensor.meta().is_contiguous() && tensor.meta().dtype() == DType::F64 {
                            let storage = tensor.contiguous_values()?;
                            Some(Self::interpolate_bicubic_values(
                                storage,
                                batch,
                                channels,
                                &in_spatial,
                                &out_spatial,
                                align,
                            ))
                        } else {
                            None
                        }
                    };
                    if let Some(values) = borrowed_values {
                        self.tensor_variable(
                            values,
                            vec![batch, channels, out_spatial[0], out_spatial[1]],
                            false,
                        )
                    } else {
                        let storage = self.tensor_tape.tensor(input)?.storage()?.to_vec();
                        self.interpolate_bicubic(
                            &storage,
                            batch,
                            channels,
                            &in_spatial,
                            &out_spatial,
                            align,
                        )
                    }
                }
            }
            "trilinear" if spatial_dims == 3 => {
                if requires_grad {
                    self.interpolate_trilinear_autograd(
                        input,
                        batch,
                        channels,
                        &in_spatial,
                        &out_spatial,
                        align,
                    )
                } else {
                    let storage = self.tensor_tape.tensor(input)?.storage()?.to_vec();
                    self.interpolate_trilinear(
                        &storage,
                        batch,
                        channels,
                        &in_spatial,
                        &out_spatial,
                        align,
                    )
                }
            }
            "area" => {
                // torch's `mode='area'` is defined as adaptive average pooling to
                // the output size (each output cell averages its input footprint),
                // which ft already provides — autograd-aware, so this path handles
                // both grad and non-grad inputs. align_corners does not apply.
                match spatial_dims {
                    1 => self.functional_adaptive_avg_pool1d(input, out_spatial[0]),
                    2 => {
                        self.functional_adaptive_avg_pool2d(input, (out_spatial[0], out_spatial[1]))
                    }
                    3 => self.functional_adaptive_avg_pool3d(
                        input,
                        (out_spatial[0], out_spatial[1], out_spatial[2]),
                    ),
                    _ => Err(Self::incompatible_tensor_args(
                        "interpolate: area mode requires 1-D, 2-D, or 3-D spatial dims",
                    )),
                }
            }
            _ => Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "interpolate: unsupported mode for given input dimensionality",
                },
            ))),
        }
    }

    fn interpolate_nearest_autograd(
        &mut self,
        input: TensorNodeId,
        batch: usize,
        channels: usize,
        in_spatial: &[usize],
        out_spatial: &[usize],
        exact: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        // Autograd-aware nearest interpolation via tensor_index_select
        // along the flattened spatial axis. Tracked under
        // frankentorch-ov0v.
        //
        // Build a flat source-index array of length out_numel: each
        // output position is mapped to a source spatial position
        // computed as floor(out_pos * in_dim / out_dim) per axis.
        // Then reshape input to [N*C, in_numel], gather the source
        // positions along dim 1, and reshape back to
        // [N, C, *out_spatial].
        let bc = Self::checked_mul(batch, channels, "interpolate: bc overflow")?;
        let in_numel =
            Self::checked_shape_numel(in_spatial, "interpolate: input spatial shape overflow")?;
        let out_numel =
            Self::checked_shape_numel(out_spatial, "interpolate: output spatial shape overflow")?;
        let mut idx_vals: Vec<f64> = Vec::with_capacity(out_numel);
        match in_spatial.len() {
            1 => {
                let (i_l, o_l) = (in_spatial[0], out_spatial[0]);
                for oi in 0..o_l {
                    let ii = Self::nearest_src_index(oi, i_l, o_l, exact);
                    #[allow(clippy::cast_precision_loss)]
                    idx_vals.push(ii as f64);
                }
            }
            2 => {
                let (i_h, i_w) = (in_spatial[0], in_spatial[1]);
                let (o_h, o_w) = (out_spatial[0], out_spatial[1]);
                for oy in 0..o_h {
                    let iy = Self::nearest_src_index(oy, i_h, o_h, exact);
                    for ox in 0..o_w {
                        let ix = Self::nearest_src_index(ox, i_w, o_w, exact);
                        #[allow(clippy::cast_precision_loss)]
                        idx_vals.push((iy * i_w + ix) as f64);
                    }
                }
            }
            3 => {
                let (i_d, i_h, i_w) = (in_spatial[0], in_spatial[1], in_spatial[2]);
                let (o_d, o_h, o_w) = (out_spatial[0], out_spatial[1], out_spatial[2]);
                for oz in 0..o_d {
                    let iz = Self::nearest_src_index(oz, i_d, o_d, exact);
                    for oy in 0..o_h {
                        let iy = Self::nearest_src_index(oy, i_h, o_h, exact);
                        for ox in 0..o_w {
                            let ix = Self::nearest_src_index(ox, i_w, o_w, exact);
                            #[allow(clippy::cast_precision_loss)]
                            idx_vals.push((iz * i_h * i_w + iy * i_w + ix) as f64);
                        }
                    }
                }
            }
            _ => {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "interpolate: nearest supports only 1-D, 2-D, or 3-D inputs",
                    },
                )));
            }
        }

        let idx_node = self.tensor_variable(idx_vals, vec![out_numel], false)?;
        let flat_input = self.tensor_reshape(input, vec![bc, in_numel])?;
        let gathered = self.tensor_index_select(flat_input, 1, idx_node)?;
        let mut out_shape = vec![batch, channels];
        out_shape.extend_from_slice(out_spatial);
        self.tensor_reshape(gathered, out_shape)
    }

    /// Compute the per-output-position source coordinate for linear /
    /// bilinear / trilinear interpolation. Returns a (low, high, frac)
    /// tuple where `low` is floor(src) clamped to [0, in-1], `high` is
    /// (low+1) clamped, and `frac = src - low`. Matches the alignment
    /// formulas in interpolate_linear_1d / interpolate_bilinear /
    /// interpolate_trilinear so the autograd path is bit-exact with
    /// the legacy plain-f64 path.
    fn interp_axis_coord(
        in_dim: usize,
        out_dim: usize,
        out_idx: usize,
        align_corners: bool,
    ) -> (usize, usize, f64) {
        let src = if align_corners && out_dim > 1 {
            out_idx as f64 * (in_dim - 1) as f64 / (out_dim - 1) as f64
        } else {
            (out_idx as f64 + 0.5) * in_dim as f64 / out_dim as f64 - 0.5
        };
        let src = src.max(0.0);
        let lo = (src.floor() as usize).min(in_dim - 1);
        let hi = (lo + 1).min(in_dim - 1);
        let t = src - lo as f64;
        (lo, hi, t)
    }

    fn interpolate_linear_1d_autograd(
        &mut self,
        input: TensorNodeId,
        batch: usize,
        channels: usize,
        in_len: usize,
        out_len: usize,
        align_corners: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        // Autograd-aware 1-D linear interpolation via two
        // index_selects + a weighted blend. Tracked under
        // frankentorch-3t1t. Each output position is a convex
        // combination of two input positions:
        //   y[oi] = (1-t)*x[lo] + t*x[hi]
        let bc = Self::checked_mul(
            batch,
            channels,
            "interpolate_linear_1d_autograd: bc overflow",
        )?;
        let mut idx_lo: Vec<f64> = Vec::with_capacity(out_len);
        let mut idx_hi: Vec<f64> = Vec::with_capacity(out_len);
        let mut w_lo: Vec<f64> = Vec::with_capacity(out_len);
        let mut w_hi: Vec<f64> = Vec::with_capacity(out_len);
        for oi in 0..out_len {
            let (lo, hi, t) = Self::interp_axis_coord(in_len, out_len, oi, align_corners);
            #[allow(clippy::cast_precision_loss)]
            {
                idx_lo.push(lo as f64);
                idx_hi.push(hi as f64);
            }
            w_lo.push(1.0 - t);
            w_hi.push(t);
        }
        let flat = self.tensor_reshape(input, vec![bc, in_len])?;
        let lo_idx = self.tensor_variable(idx_lo, vec![out_len], false)?;
        let hi_idx = self.tensor_variable(idx_hi, vec![out_len], false)?;
        let lo_g = self.tensor_index_select(flat, 1, lo_idx)?;
        let hi_g = self.tensor_index_select(flat, 1, hi_idx)?;
        let lo_w = self.tensor_variable(w_lo, vec![1, out_len], false)?;
        let hi_w = self.tensor_variable(w_hi, vec![1, out_len], false)?;
        let lo_w_b = self.tensor_expand(lo_w, vec![bc, out_len])?;
        let hi_w_b = self.tensor_expand(hi_w, vec![bc, out_len])?;
        let lo_term = self.tensor_mul(lo_g, lo_w_b)?;
        let hi_term = self.tensor_mul(hi_g, hi_w_b)?;
        let summed = self.tensor_add(lo_term, hi_term)?;
        self.tensor_reshape(summed, vec![batch, channels, out_len])
    }

    fn interpolate_bilinear_autograd(
        &mut self,
        input: TensorNodeId,
        batch: usize,
        channels: usize,
        in_spatial: &[usize],
        out_spatial: &[usize],
        align_corners: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        // Autograd-aware 2-D bilinear interpolation via four
        // index_selects of the four corner pixels per output position,
        // then a weighted blend. Tracked under frankentorch-3t1t.
        //   y[oh, ow] = (1-ty)*(1-tx)*x[y0, x0] + (1-ty)*tx*x[y0, x1]
        //             + ty*(1-tx)*x[y1, x0] + ty*tx*x[y1, x1]
        let (ih, iw) = (in_spatial[0], in_spatial[1]);
        let (oh, ow) = (out_spatial[0], out_spatial[1]);
        let bc = Self::checked_mul(
            batch,
            channels,
            "interpolate_bilinear_autograd: bc overflow",
        )?;
        let in_numel =
            Self::checked_mul(ih, iw, "interpolate_bilinear_autograd: in_numel overflow")?;
        let out_numel =
            Self::checked_mul(oh, ow, "interpolate_bilinear_autograd: out_numel overflow")?;
        let mut idx_00: Vec<f64> = Vec::with_capacity(out_numel);
        let mut idx_01: Vec<f64> = Vec::with_capacity(out_numel);
        let mut idx_10: Vec<f64> = Vec::with_capacity(out_numel);
        let mut idx_11: Vec<f64> = Vec::with_capacity(out_numel);
        let mut w_00: Vec<f64> = Vec::with_capacity(out_numel);
        let mut w_01: Vec<f64> = Vec::with_capacity(out_numel);
        let mut w_10: Vec<f64> = Vec::with_capacity(out_numel);
        let mut w_11: Vec<f64> = Vec::with_capacity(out_numel);
        for oy in 0..oh {
            let (y0, y1, ty) = Self::interp_axis_coord(ih, oh, oy, align_corners);
            for ox in 0..ow {
                let (x0, x1, tx) = Self::interp_axis_coord(iw, ow, ox, align_corners);
                #[allow(clippy::cast_precision_loss)]
                {
                    idx_00.push((y0 * iw + x0) as f64);
                    idx_01.push((y0 * iw + x1) as f64);
                    idx_10.push((y1 * iw + x0) as f64);
                    idx_11.push((y1 * iw + x1) as f64);
                }
                w_00.push((1.0 - ty) * (1.0 - tx));
                w_01.push((1.0 - ty) * tx);
                w_10.push(ty * (1.0 - tx));
                w_11.push(ty * tx);
            }
        }
        let flat = self.tensor_reshape(input, vec![bc, in_numel])?;
        let mut acc: Option<TensorNodeId> = None;
        for (idx_vec, w_vec) in [
            (idx_00, w_00),
            (idx_01, w_01),
            (idx_10, w_10),
            (idx_11, w_11),
        ] {
            let idx_n = self.tensor_variable(idx_vec, vec![out_numel], false)?;
            let g = self.tensor_index_select(flat, 1, idx_n)?;
            let w_n = self.tensor_variable(w_vec, vec![1, out_numel], false)?;
            let w_b = self.tensor_expand(w_n, vec![bc, out_numel])?;
            let term = self.tensor_mul(g, w_b)?;
            acc = Some(match acc {
                Some(a) => self.tensor_add(a, term)?,
                None => term,
            });
        }
        let summed = acc.expect("bilinear has at least one corner");
        self.tensor_reshape(summed, vec![batch, channels, oh, ow])
    }

    fn interpolate_trilinear_autograd(
        &mut self,
        input: TensorNodeId,
        batch: usize,
        channels: usize,
        in_spatial: &[usize],
        out_spatial: &[usize],
        align_corners: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        // Autograd-aware 3-D trilinear interpolation: 8 corner
        // index_selects and a 3-axis weighted blend. Tracked under
        // frankentorch-3t1t.
        let (id, ih, iw) = (in_spatial[0], in_spatial[1], in_spatial[2]);
        let (od, oh, ow) = (out_spatial[0], out_spatial[1], out_spatial[2]);
        let bc = Self::checked_mul(
            batch,
            channels,
            "interpolate_trilinear_autograd: bc overflow",
        )?;
        let plane = Self::checked_mul(ih, iw, "interpolate_trilinear_autograd: plane overflow")?;
        let in_numel = Self::checked_mul(
            id,
            plane,
            "interpolate_trilinear_autograd: in_numel overflow",
        )?;
        let out_plane =
            Self::checked_mul(oh, ow, "interpolate_trilinear_autograd: out_plane overflow")?;
        let out_numel = Self::checked_mul(
            od,
            out_plane,
            "interpolate_trilinear_autograd: out_numel overflow",
        )?;
        // Eight corners, each gets an index array and a weight array.
        let mut corners: Vec<(Vec<f64>, Vec<f64>)> = (0..8)
            .map(|_| (Vec::with_capacity(out_numel), Vec::with_capacity(out_numel)))
            .collect();
        for oz in 0..od {
            let (z0, z1, tz) = Self::interp_axis_coord(id, od, oz, align_corners);
            for oy in 0..oh {
                let (y0, y1, ty) = Self::interp_axis_coord(ih, oh, oy, align_corners);
                for ox in 0..ow {
                    let (x0, x1, tx) = Self::interp_axis_coord(iw, ow, ox, align_corners);
                    let zs = [z0, z1];
                    let ys = [y0, y1];
                    let xs = [x0, x1];
                    let tzs = [1.0 - tz, tz];
                    let tys = [1.0 - ty, ty];
                    let txs = [1.0 - tx, tx];
                    for (ci, corner) in corners.iter_mut().enumerate() {
                        let zi = (ci >> 2) & 1;
                        let yi = (ci >> 1) & 1;
                        let xi = ci & 1;
                        let pos = zs[zi] * plane + ys[yi] * iw + xs[xi];
                        #[allow(clippy::cast_precision_loss)]
                        corner.0.push(pos as f64);
                        corner.1.push(tzs[zi] * tys[yi] * txs[xi]);
                    }
                }
            }
        }
        let flat = self.tensor_reshape(input, vec![bc, in_numel])?;
        let mut acc: Option<TensorNodeId> = None;
        for (idx_vec, w_vec) in corners {
            let idx_n = self.tensor_variable(idx_vec, vec![out_numel], false)?;
            let g = self.tensor_index_select(flat, 1, idx_n)?;
            let w_n = self.tensor_variable(w_vec, vec![1, out_numel], false)?;
            let w_b = self.tensor_expand(w_n, vec![bc, out_numel])?;
            let term = self.tensor_mul(g, w_b)?;
            acc = Some(match acc {
                Some(a) => self.tensor_add(a, term)?,
                None => term,
            });
        }
        let summed = acc.expect("trilinear has 8 corners");
        self.tensor_reshape(summed, vec![batch, channels, od, oh, ow])
    }

    fn interpolate_bicubic_autograd(
        &mut self,
        input: TensorNodeId,
        batch: usize,
        channels: usize,
        in_spatial: &[usize],
        out_spatial: &[usize],
        align_corners: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        // Autograd-aware 2-D bicubic interpolation: 16 corner
        // index_selects (4 per axis) with cubic-Hermite weights.
        // Tracked under frankentorch-tm8j. Forward result agrees
        // bit-exactly with the legacy plain-f64 path because the
        // weights and source-position formulas mirror it.
        let (ih, iw) = (in_spatial[0], in_spatial[1]);
        let (oh, ow) = (out_spatial[0], out_spatial[1]);
        let bc = Self::checked_mul(batch, channels, "interpolate_bicubic_autograd: bc overflow")?;
        let in_numel =
            Self::checked_mul(ih, iw, "interpolate_bicubic_autograd: in_numel overflow")?;
        let out_numel =
            Self::checked_mul(oh, ow, "interpolate_bicubic_autograd: out_numel overflow")?;
        // 16 corners (4 dy × 4 dx); each gets an index array and weight array.
        let mut corners: Vec<(Vec<f64>, Vec<f64>)> = (0..16)
            .map(|_| (Vec::with_capacity(out_numel), Vec::with_capacity(out_numel)))
            .collect();
        for oy in 0..oh {
            let src_y = if align_corners && oh > 1 {
                oy as f64 * (ih - 1) as f64 / (oh - 1) as f64
            } else {
                (oy as f64 + 0.5) * ih as f64 / oh as f64 - 0.5
            };
            // Cubic keeps the unclamped source coordinate (PyTorch semantics); only the
            // tap indices below are clamped, matching the forward path.
            let iy = src_y.floor() as i64;
            let ty = src_y - iy as f64;
            for ox in 0..ow {
                let src_x = if align_corners && ow > 1 {
                    ox as f64 * (iw - 1) as f64 / (ow - 1) as f64
                } else {
                    (ox as f64 + 0.5) * iw as f64 / ow as f64 - 0.5
                };
                // Cubic keeps the unclamped source coordinate (see src_y above).
                let ix = src_x.floor() as i64;
                let tx = src_x - ix as f64;
                let mut ci = 0usize;
                for dy in -1..=2_i64 {
                    let wy = cubic_weight(ty - dy as f64);
                    let sy = (iy + dy).clamp(0, ih as i64 - 1) as usize;
                    for dx in -1..=2_i64 {
                        let wx = cubic_weight(tx - dx as f64);
                        let sx = (ix + dx).clamp(0, iw as i64 - 1) as usize;
                        #[allow(clippy::cast_precision_loss)]
                        corners[ci].0.push((sy * iw + sx) as f64);
                        corners[ci].1.push(wy * wx);
                        ci += 1;
                    }
                }
            }
        }
        let flat = self.tensor_reshape(input, vec![bc, in_numel])?;
        let mut acc: Option<TensorNodeId> = None;
        for (idx_vec, w_vec) in corners {
            let idx_n = self.tensor_variable(idx_vec, vec![out_numel], false)?;
            let g = self.tensor_index_select(flat, 1, idx_n)?;
            let w_n = self.tensor_variable(w_vec, vec![1, out_numel], false)?;
            let w_b = self.tensor_expand(w_n, vec![bc, out_numel])?;
            let term = self.tensor_mul(g, w_b)?;
            acc = Some(match acc {
                Some(a) => self.tensor_add(a, term)?,
                None => term,
            });
        }
        let summed = acc.expect("bicubic has 16 corners");
        self.tensor_reshape(summed, vec![batch, channels, oh, ow])
    }

    /// Source pixel index for nearest-neighbor interpolation.
    ///
    /// `'nearest'` (torch default) uses `floor(dst * in / out)`; `'nearest-exact'`
    /// shifts the sample to the pixel center, `floor((dst + 0.5) * in / out)`,
    /// matching torch's corrected formula. The two agree for integer up/downscale
    /// and diverge for non-integer ratios.
    #[inline]
    fn nearest_src_index(dst: usize, in_size: usize, out_size: usize, exact: bool) -> usize {
        let offset = if exact { 0.5 } else { 0.0 };
        #[allow(clippy::cast_precision_loss)]
        let raw = ((dst as f64 + offset) * in_size as f64 / out_size as f64).floor() as usize;
        raw.min(in_size - 1)
    }

    fn interpolate_nearest(
        &mut self,
        storage: &[f64],
        batch: usize,
        channels: usize,
        in_spatial: &[usize],
        out_spatial: &[usize],
        exact: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        let spatial_dims = in_spatial.len();
        let out_numel =
            Self::checked_shape_numel(out_spatial, "interpolate: output spatial shape overflow")?;
        let in_numel =
            Self::checked_shape_numel(in_spatial, "interpolate: input spatial shape overflow")?;
        let bc = Self::checked_mul(batch, channels, "interpolate: output size overflow")?;
        let total = Self::checked_mul(bc, out_numel, "interpolate: output size overflow")?;
        let mut values = Vec::with_capacity(total);

        for b in 0..batch {
            for c in 0..channels {
                let base = (b * channels + c) * in_numel;
                match spatial_dims {
                    1 => {
                        for oi in 0..out_spatial[0] {
                            let ii =
                                Self::nearest_src_index(oi, in_spatial[0], out_spatial[0], exact);
                            values.push(storage[base + ii]);
                        }
                    }
                    2 => {
                        let (ih, iw) = (in_spatial[0], in_spatial[1]);
                        let (oh, ow) = (out_spatial[0], out_spatial[1]);
                        for oy in 0..oh {
                            let iy = Self::nearest_src_index(oy, ih, oh, exact);
                            for ox in 0..ow {
                                let ix = Self::nearest_src_index(ox, iw, ow, exact);
                                values.push(storage[base + iy * iw + ix]);
                            }
                        }
                    }
                    3 => {
                        let (id, ih, iw) = (in_spatial[0], in_spatial[1], in_spatial[2]);
                        let (od, oh, ow) = (out_spatial[0], out_spatial[1], out_spatial[2]);
                        for oz in 0..od {
                            let iz = Self::nearest_src_index(oz, id, od, exact);
                            for oy in 0..oh {
                                let iy = Self::nearest_src_index(oy, ih, oh, exact);
                                for ox in 0..ow {
                                    let ix = Self::nearest_src_index(ox, iw, ow, exact);
                                    values.push(storage[base + iz * ih * iw + iy * iw + ix]);
                                }
                            }
                        }
                    }
                    _ => {
                        return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                            ft_dispatch::DispatchKeyError::IncompatibleSet {
                                reason: "interpolate: nearest supports only 1-D, 2-D, or 3-D inputs",
                            },
                        )));
                    }
                }
            }
        }

        let mut out_shape = vec![batch, channels];
        out_shape.extend_from_slice(out_spatial);
        self.tensor_variable(values, out_shape, false)
    }

    fn interpolate_linear_1d(
        &mut self,
        storage: &[f64],
        batch: usize,
        channels: usize,
        in_len: usize,
        out_len: usize,
        align_corners: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        let total = batch * channels * out_len;
        let mut values = Vec::with_capacity(total);

        for b in 0..batch {
            for c in 0..channels {
                let base = (b * channels + c) * in_len;
                for oi in 0..out_len {
                    let src = if align_corners && out_len > 1 {
                        oi as f64 * (in_len - 1) as f64 / (out_len - 1) as f64
                    } else {
                        (oi as f64 + 0.5) * in_len as f64 / out_len as f64 - 0.5
                    };
                    let src = src.max(0.0);
                    let lo = (src.floor() as usize).min(in_len - 1);
                    let hi = (lo + 1).min(in_len - 1);
                    let t = src - lo as f64;
                    values.push(storage[base + lo] * (1.0 - t) + storage[base + hi] * t);
                }
            }
        }

        self.tensor_variable(values, vec![batch, channels, out_len], false)
    }

    fn interpolate_bilinear(
        &mut self,
        storage: &[f64],
        batch: usize,
        channels: usize,
        in_spatial: &[usize],
        out_spatial: &[usize],
        align_corners: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        use rayon::prelude::*;
        let (ih, iw) = (in_spatial[0], in_spatial[1]);
        let (oh, ow) = (out_spatial[0], out_spatial[1]);
        let total = batch * channels * oh * ow;
        let in_plane = ih * iw;
        let mut values = vec![0.0_f64; total];

        // Output row r -> plane = r/oh, oy = r%oh (base == plane*in_plane). Each
        // element uses identical 4-tap bilinear arithmetic and the same linear
        // position as the serial push order, so distributing whole rows across
        // Rayon workers is bit-for-bit identical.
        let fill_row = |r: usize, out_row: &mut [f64]| {
            let plane = r / oh;
            let oy = r % oh;
            let base = plane * in_plane;
            let src_y = if align_corners && oh > 1 {
                oy as f64 * (ih - 1) as f64 / (oh - 1) as f64
            } else {
                (oy as f64 + 0.5) * ih as f64 / oh as f64 - 0.5
            };
            let src_y = src_y.max(0.0);
            let y0 = (src_y.floor() as usize).min(ih - 1);
            let y1 = (y0 + 1).min(ih - 1);
            let ty = src_y - y0 as f64;

            for (ox, slot) in out_row.iter_mut().enumerate() {
                let src_x = if align_corners && ow > 1 {
                    ox as f64 * (iw - 1) as f64 / (ow - 1) as f64
                } else {
                    (ox as f64 + 0.5) * iw as f64 / ow as f64 - 0.5
                };
                let src_x = src_x.max(0.0);
                let x0 = (src_x.floor() as usize).min(iw - 1);
                let x1 = (x0 + 1).min(iw - 1);
                let tx = src_x - x0 as f64;

                let v00 = storage[base + y0 * iw + x0];
                let v01 = storage[base + y0 * iw + x1];
                let v10 = storage[base + y1 * iw + x0];
                let v11 = storage[base + y1 * iw + x1];

                *slot = v00 * (1.0 - ty) * (1.0 - tx)
                    + v01 * (1.0 - ty) * tx
                    + v10 * ty * (1.0 - tx)
                    + v11 * ty * tx;
            }
        };

        if total >= PARALLEL_ELEMENTWISE_MIN {
            values
                .par_chunks_mut(ow)
                .enumerate()
                .for_each(|(r, out_row)| fill_row(r, out_row));
        } else {
            values
                .chunks_mut(ow)
                .enumerate()
                .for_each(|(r, out_row)| fill_row(r, out_row));
        }

        self.tensor_variable(values, vec![batch, channels, oh, ow], false)
    }

    fn interpolate_bicubic_values(
        storage: &[f64],
        batch: usize,
        channels: usize,
        in_spatial: &[usize],
        out_spatial: &[usize],
        align_corners: bool,
    ) -> Vec<f64> {
        use rayon::prelude::*;
        let (ih, iw) = (in_spatial[0], in_spatial[1]);
        let (oh, ow) = (out_spatial[0], out_spatial[1]);
        let total = batch * channels * oh * ow;
        let in_plane = ih * iw;
        let mut values = vec![0.0_f64; total];

        #[derive(Clone, Copy)]
        struct CubicPlan {
            indices: [usize; 4],
            weights: [f64; 4],
        }

        let build_plan = |out_size: usize, in_size: usize| -> Vec<CubicPlan> {
            (0..out_size)
                .map(|out_idx| {
                    let src = if align_corners && out_size > 1 {
                        out_idx as f64 * (in_size - 1) as f64 / (out_size - 1) as f64
                    } else {
                        (out_idx as f64 + 0.5) * in_size as f64 / out_size as f64 - 0.5
                    };
                    let base = src.floor() as i64;
                    let frac = src - base as f64;
                    let mut indices = [0usize; 4];
                    let mut weights = [0.0_f64; 4];
                    for (slot, offset) in (-1..=2_i64).enumerate() {
                        indices[slot] = (base + offset).clamp(0, in_size as i64 - 1) as usize;
                        weights[slot] = cubic_weight(frac - offset as f64);
                    }
                    CubicPlan { indices, weights }
                })
                .collect()
        };
        let y_plan = build_plan(oh, ih);
        let x_plan = build_plan(ow, iw);

        // Each output row r maps to plane = r/oh and oy = r%oh (since
        // base = (b*channels+c)*ih*iw == plane*in_plane). Every output element
        // uses the same cached cubic-weight/clamp/gather arithmetic and writes
        // the same linear position as the serial push order, so distributing
        // whole rows across Rayon workers is bit-for-bit identical.
        let fill_row = |r: usize, out_row: &mut [f64]| {
            let plane = r / oh;
            let oy = r % oh;
            let base = plane * in_plane;
            let y = y_plan[oy];

            for (ox, slot) in out_row.iter_mut().enumerate() {
                let x = x_plan[ox];
                let mut val = 0.0;
                for dy in 0..4 {
                    let wy = y.weights[dy];
                    let sy = y.indices[dy];
                    for dx in 0..4 {
                        let wx = x.weights[dx];
                        let sx = x.indices[dx];
                        val += wy * wx * storage[base + sy * iw + sx];
                    }
                }
                *slot = val;
            }
        };

        if total >= PARALLEL_ELEMENTWISE_MIN {
            values
                .par_chunks_mut(ow)
                .enumerate()
                .for_each(|(r, out_row)| fill_row(r, out_row));
        } else {
            values
                .chunks_mut(ow)
                .enumerate()
                .for_each(|(r, out_row)| fill_row(r, out_row));
        }

        values
    }

    fn interpolate_bicubic(
        &mut self,
        storage: &[f64],
        batch: usize,
        channels: usize,
        in_spatial: &[usize],
        out_spatial: &[usize],
        align_corners: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        let (oh, ow) = (out_spatial[0], out_spatial[1]);
        let values = Self::interpolate_bicubic_values(
            storage,
            batch,
            channels,
            in_spatial,
            out_spatial,
            align_corners,
        );
        self.tensor_variable(values, vec![batch, channels, oh, ow], false)
    }

    fn interpolate_trilinear(
        &mut self,
        storage: &[f64],
        batch: usize,
        channels: usize,
        in_spatial: &[usize],
        out_spatial: &[usize],
        align_corners: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        use rayon::prelude::*;
        let (id, ih, iw) = (in_spatial[0], in_spatial[1], in_spatial[2]);
        let (od, oh, ow) = (out_spatial[0], out_spatial[1], out_spatial[2]);
        let total = batch * channels * od * oh * ow;
        let in_plane = id * ih * iw;
        let mut values = vec![0.0_f64; total];

        #[derive(Clone, Copy)]
        struct LinearPlan {
            lo: usize,
            hi: usize,
            t: f64,
        }

        let build_plan = |out_size: usize, in_size: usize| -> Vec<LinearPlan> {
            (0..out_size)
                .map(|out_idx| {
                    let (lo, hi, t) =
                        Self::interp_axis_coord(in_size, out_size, out_idx, align_corners);
                    LinearPlan { lo, hi, t }
                })
                .collect()
        };
        let z_plan = build_plan(od, id);
        let y_plan = build_plan(oh, ih);
        let x_plan = build_plan(ow, iw);

        // Output row r = (((b*channels+c)*od + oz)*oh + oy) maps to
        // plane = r/(od*oh), oz = (r/oh)%od, oy = r%oh (base == plane*in_plane).
        // Every element uses identical 8-tap trilinear arithmetic and the same
        // linear position as the serial push order. Axis plans only hoist the
        // source-coordinate formula that is invariant across batch/channel
        // planes; corner accumulation order remains unchanged.
        let fill_row = |r: usize, out_row: &mut [f64]| {
            let oy = r % oh;
            let r2 = r / oh; // = plane*od + oz
            let oz = r2 % od;
            let plane = r2 / od;
            let base = plane * in_plane;

            let z = z_plan[oz];
            let y = y_plan[oy];

            for (ox, slot) in out_row.iter_mut().enumerate() {
                let x = x_plan[ox];

                let v000 = storage[base + z.lo * ih * iw + y.lo * iw + x.lo];
                let v001 = storage[base + z.lo * ih * iw + y.lo * iw + x.hi];
                let v010 = storage[base + z.lo * ih * iw + y.hi * iw + x.lo];
                let v011 = storage[base + z.lo * ih * iw + y.hi * iw + x.hi];
                let v100 = storage[base + z.hi * ih * iw + y.lo * iw + x.lo];
                let v101 = storage[base + z.hi * ih * iw + y.lo * iw + x.hi];
                let v110 = storage[base + z.hi * ih * iw + y.hi * iw + x.lo];
                let v111 = storage[base + z.hi * ih * iw + y.hi * iw + x.hi];

                *slot = v000 * (1.0 - z.t) * (1.0 - y.t) * (1.0 - x.t)
                    + v001 * (1.0 - z.t) * (1.0 - y.t) * x.t
                    + v010 * (1.0 - z.t) * y.t * (1.0 - x.t)
                    + v011 * (1.0 - z.t) * y.t * x.t
                    + v100 * z.t * (1.0 - y.t) * (1.0 - x.t)
                    + v101 * z.t * (1.0 - y.t) * x.t
                    + v110 * z.t * y.t * (1.0 - x.t)
                    + v111 * z.t * y.t * x.t;
            }
        };

        if total >= PARALLEL_ELEMENTWISE_MIN {
            values
                .par_chunks_mut(ow)
                .enumerate()
                .for_each(|(r, out_row)| fill_row(r, out_row));
        } else {
            values
                .chunks_mut(ow)
                .enumerate()
                .for_each(|(r, out_row)| fill_row(r, out_row));
        }

        self.tensor_variable(values, vec![batch, channels, od, oh, ow], false)
    }

    /// Native f32 interpolate (inference-only). Mirrors the validation of
    /// [`Self::tensor_interpolate`] then dispatches to f32 sampling kernels,
    /// returning an F32 tensor. Reached only for `!requires_grad` F32 input.
    fn interpolate_f32(
        &mut self,
        input: TensorNodeId,
        size: Option<Vec<usize>>,
        scale_factor: Option<Vec<f64>>,
        mode: &str,
        align_corners: Option<bool>,
    ) -> Result<TensorNodeId, AutogradError> {
        let meta = self.tensor_tape.tensor(input)?.meta().clone();
        let shape = meta.shape();
        let ndim = shape.len();
        if !(3..=5).contains(&ndim) {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "interpolate: input must be 3-D, 4-D, or 5-D",
                },
            )));
        }
        if size.is_some() && scale_factor.is_some() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "interpolate: only one of size or scale_factor should be defined",
                },
            )));
        }
        let spatial_dims = ndim - 2;
        let in_spatial: Vec<usize> = shape[2..].to_vec();
        if in_spatial.contains(&0) {
            return Err(Self::incompatible_tensor_args(
                "interpolate: input spatial dimensions must be > 0",
            ));
        }
        let out_spatial: Vec<usize> = if let Some(ref s) = size {
            if s.len() != spatial_dims {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "interpolate: size length must match spatial dimensions",
                    },
                )));
            }
            if s.contains(&0) {
                return Err(Self::incompatible_tensor_args(
                    "interpolate: output spatial dimensions must be > 0",
                ));
            }
            s.clone()
        } else if let Some(ref sf) = scale_factor {
            if sf.len() != spatial_dims {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "interpolate: scale_factor length must match spatial dimensions",
                    },
                )));
            }
            in_spatial
                .iter()
                .zip(sf.iter())
                .map(|(&d, &s)| Self::checked_interpolate_scale_dim(d, s))
                .collect::<Result<Vec<_>, _>>()?
        } else {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "interpolate: either size or scale_factor must be provided",
                },
            )));
        };
        let batch = shape[0];
        let channels = shape[1];
        let mut out_shape = vec![batch, channels];
        out_shape.extend_from_slice(&out_spatial);
        let out_numel = Self::checked_shape_numel(&out_shape, "interpolate: output size overflow")?;
        let _ = Self::checked_mul(
            out_numel,
            std::mem::size_of::<f32>(),
            "interpolate: output size overflow",
        )?;
        let align = align_corners.unwrap_or(false);

        // `area` is adaptive-average-pool (already dtype-preserving/autograd-aware).
        if mode == "area" {
            return match spatial_dims {
                1 => self.functional_adaptive_avg_pool1d(input, out_spatial[0]),
                2 => self.functional_adaptive_avg_pool2d(input, (out_spatial[0], out_spatial[1])),
                3 => self.functional_adaptive_avg_pool3d(
                    input,
                    (out_spatial[0], out_spatial[1], out_spatial[2]),
                ),
                _ => Err(Self::incompatible_tensor_args(
                    "interpolate: area mode requires 1-D, 2-D, or 3-D spatial dims",
                )),
            };
        }

        let storage = self.tensor_values_f32(input)?;
        let values = match mode {
            "nearest" | "nearest-exact" => {
                let exact = mode == "nearest-exact";
                Self::interp_nearest_f32(
                    &storage,
                    batch,
                    channels,
                    &in_spatial,
                    &out_spatial,
                    exact,
                )
            }
            "linear" if spatial_dims == 1 => Self::interp_linear_1d_f32(
                &storage,
                batch,
                channels,
                in_spatial[0],
                out_spatial[0],
                align,
            ),
            "bilinear" if spatial_dims == 2 => Self::interp_bilinear_f32(
                &storage,
                batch,
                channels,
                &in_spatial,
                &out_spatial,
                align,
            ),
            "bicubic" if spatial_dims == 2 => Self::interp_bicubic_f32(
                &storage,
                batch,
                channels,
                &in_spatial,
                &out_spatial,
                align,
            ),
            "trilinear" if spatial_dims == 3 => Self::interp_trilinear_f32(
                &storage,
                batch,
                channels,
                &in_spatial,
                &out_spatial,
                align,
            ),
            _ => {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "interpolate: unsupported mode for given input dimensionality",
                    },
                )));
            }
        };
        self.tensor_variable_f32(values, out_shape, false)
    }

    fn interp_nearest_f32(
        storage: &[f32],
        batch: usize,
        channels: usize,
        in_spatial: &[usize],
        out_spatial: &[usize],
        exact: bool,
    ) -> Vec<f32> {
        let spatial_dims = in_spatial.len();
        let in_numel: usize = in_spatial.iter().product();
        let out_numel: usize = out_spatial.iter().product();
        let mut values = Vec::with_capacity(batch * channels * out_numel);
        for b in 0..batch {
            for c in 0..channels {
                let base = (b * channels + c) * in_numel;
                match spatial_dims {
                    1 => {
                        for oi in 0..out_spatial[0] {
                            let ii =
                                Self::nearest_src_index(oi, in_spatial[0], out_spatial[0], exact);
                            values.push(storage[base + ii]);
                        }
                    }
                    2 => {
                        let (ih, iw) = (in_spatial[0], in_spatial[1]);
                        let (oh, ow) = (out_spatial[0], out_spatial[1]);
                        for oy in 0..oh {
                            let iy = Self::nearest_src_index(oy, ih, oh, exact);
                            for ox in 0..ow {
                                let ix = Self::nearest_src_index(ox, iw, ow, exact);
                                values.push(storage[base + iy * iw + ix]);
                            }
                        }
                    }
                    _ => {
                        let (id, ih, iw) = (in_spatial[0], in_spatial[1], in_spatial[2]);
                        let (od, oh, ow) = (out_spatial[0], out_spatial[1], out_spatial[2]);
                        for oz in 0..od {
                            let iz = Self::nearest_src_index(oz, id, od, exact);
                            for oy in 0..oh {
                                let iy = Self::nearest_src_index(oy, ih, oh, exact);
                                for ox in 0..ow {
                                    let ix = Self::nearest_src_index(ox, iw, ow, exact);
                                    values.push(storage[base + iz * ih * iw + iy * iw + ix]);
                                }
                            }
                        }
                    }
                }
            }
        }
        values
    }

    fn interp_linear_1d_f32(
        storage: &[f32],
        batch: usize,
        channels: usize,
        in_len: usize,
        out_len: usize,
        align: bool,
    ) -> Vec<f32> {
        let plan: Vec<(usize, usize, f32)> = (0..out_len)
            .map(|oi| {
                let (lo, hi, t) = Self::interp_axis_coord(in_len, out_len, oi, align);
                (lo, hi, t as f32)
            })
            .collect();
        let mut values = Vec::with_capacity(batch * channels * out_len);
        for b in 0..batch {
            for c in 0..channels {
                let base = (b * channels + c) * in_len;
                for &(lo, hi, t) in &plan {
                    values.push(storage[base + lo] * (1.0 - t) + storage[base + hi] * t);
                }
            }
        }
        values
    }

    fn interp_bilinear_f32(
        storage: &[f32],
        batch: usize,
        channels: usize,
        in_spatial: &[usize],
        out_spatial: &[usize],
        align: bool,
    ) -> Vec<f32> {
        use rayon::prelude::*;
        let (ih, iw) = (in_spatial[0], in_spatial[1]);
        let (oh, ow) = (out_spatial[0], out_spatial[1]);
        let total = batch * channels * oh * ow;
        let in_plane = ih * iw;
        let mut values = vec![0.0_f32; total];
        let x_plan: Vec<(usize, usize, f32)> = (0..ow)
            .map(|ox| {
                let (lo, hi, t) = Self::interp_axis_coord(iw, ow, ox, align);
                (lo, hi, t as f32)
            })
            .collect();
        let y_plan: Vec<(usize, usize, f32)> = (0..oh)
            .map(|oy| {
                let (lo, hi, t) = Self::interp_axis_coord(ih, oh, oy, align);
                (lo, hi, t as f32)
            })
            .collect();
        let fill_row = |r: usize, out_row: &mut [f32]| {
            let plane = r / oh;
            let oy = r % oh;
            let base = plane * in_plane;
            let (y0, y1, ty) = y_plan[oy];
            for (ox, slot) in out_row.iter_mut().enumerate() {
                let (x0, x1, tx) = x_plan[ox];
                let v00 = storage[base + y0 * iw + x0];
                let v01 = storage[base + y0 * iw + x1];
                let v10 = storage[base + y1 * iw + x0];
                let v11 = storage[base + y1 * iw + x1];
                *slot = v00 * (1.0 - ty) * (1.0 - tx)
                    + v01 * (1.0 - ty) * tx
                    + v10 * ty * (1.0 - tx)
                    + v11 * ty * tx;
            }
        };
        if total >= PARALLEL_ELEMENTWISE_MIN {
            values
                .par_chunks_mut(ow)
                .enumerate()
                .for_each(|(r, out_row)| fill_row(r, out_row));
        } else {
            values
                .chunks_mut(ow)
                .enumerate()
                .for_each(|(r, out_row)| fill_row(r, out_row));
        }
        values
    }

    fn interp_bicubic_f32(
        storage: &[f32],
        batch: usize,
        channels: usize,
        in_spatial: &[usize],
        out_spatial: &[usize],
        align: bool,
    ) -> Vec<f32> {
        use rayon::prelude::*;
        let (ih, iw) = (in_spatial[0], in_spatial[1]);
        let (oh, ow) = (out_spatial[0], out_spatial[1]);
        let total = batch * channels * oh * ow;
        let in_plane = ih * iw;
        let mut values = vec![0.0_f32; total];

        #[derive(Clone, Copy)]
        struct CubicPlanF32 {
            indices: [usize; 4],
            weights: [f32; 4],
        }
        let build_plan = |out_size: usize, in_size: usize| -> Vec<CubicPlanF32> {
            (0..out_size)
                .map(|out_idx| {
                    let src = if align && out_size > 1 {
                        out_idx as f64 * (in_size - 1) as f64 / (out_size - 1) as f64
                    } else {
                        (out_idx as f64 + 0.5) * in_size as f64 / out_size as f64 - 0.5
                    };
                    let base = src.floor() as i64;
                    let frac = src - base as f64;
                    let mut indices = [0usize; 4];
                    let mut weights = [0.0_f32; 4];
                    for (slot, offset) in (-1..=2_i64).enumerate() {
                        indices[slot] = (base + offset).clamp(0, in_size as i64 - 1) as usize;
                        weights[slot] = cubic_weight(frac - offset as f64) as f32;
                    }
                    CubicPlanF32 { indices, weights }
                })
                .collect()
        };
        let y_plan = build_plan(oh, ih);
        let x_plan = build_plan(ow, iw);

        let fill_row = |r: usize, out_row: &mut [f32]| {
            let plane = r / oh;
            let oy = r % oh;
            let base = plane * in_plane;
            let y = y_plan[oy];
            for (ox, slot) in out_row.iter_mut().enumerate() {
                let x = x_plan[ox];
                let mut val = 0.0_f32;
                for dy in 0..4 {
                    let wy = y.weights[dy];
                    let sy = y.indices[dy];
                    for dx in 0..4 {
                        let wx = x.weights[dx];
                        let sx = x.indices[dx];
                        val += wy * wx * storage[base + sy * iw + sx];
                    }
                }
                *slot = val;
            }
        };
        if total >= PARALLEL_ELEMENTWISE_MIN {
            values
                .par_chunks_mut(ow)
                .enumerate()
                .for_each(|(r, out_row)| fill_row(r, out_row));
        } else {
            values
                .chunks_mut(ow)
                .enumerate()
                .for_each(|(r, out_row)| fill_row(r, out_row));
        }
        values
    }

    fn interp_trilinear_f32(
        storage: &[f32],
        batch: usize,
        channels: usize,
        in_spatial: &[usize],
        out_spatial: &[usize],
        align: bool,
    ) -> Vec<f32> {
        use rayon::prelude::*;
        let (id, ih, iw) = (in_spatial[0], in_spatial[1], in_spatial[2]);
        let (od, oh, ow) = (out_spatial[0], out_spatial[1], out_spatial[2]);
        let total = batch * channels * od * oh * ow;
        let in_plane = id * ih * iw;
        let mut values = vec![0.0_f32; total];

        let build_plan = |out_size: usize, in_size: usize| -> Vec<(usize, usize, f32)> {
            (0..out_size)
                .map(|out_idx| {
                    let (lo, hi, t) = Self::interp_axis_coord(in_size, out_size, out_idx, align);
                    (lo, hi, t as f32)
                })
                .collect()
        };
        let z_plan = build_plan(od, id);
        let y_plan = build_plan(oh, ih);
        let x_plan = build_plan(ow, iw);

        let fill_row = |r: usize, out_row: &mut [f32]| {
            let oy = r % oh;
            let r2 = r / oh;
            let oz = r2 % od;
            let plane = r2 / od;
            let base = plane * in_plane;
            let (z_lo, z_hi, zt) = z_plan[oz];
            let (y_lo, y_hi, yt) = y_plan[oy];
            for (ox, slot) in out_row.iter_mut().enumerate() {
                let (x_lo, x_hi, xt) = x_plan[ox];
                let v000 = storage[base + z_lo * ih * iw + y_lo * iw + x_lo];
                let v001 = storage[base + z_lo * ih * iw + y_lo * iw + x_hi];
                let v010 = storage[base + z_lo * ih * iw + y_hi * iw + x_lo];
                let v011 = storage[base + z_lo * ih * iw + y_hi * iw + x_hi];
                let v100 = storage[base + z_hi * ih * iw + y_lo * iw + x_lo];
                let v101 = storage[base + z_hi * ih * iw + y_lo * iw + x_hi];
                let v110 = storage[base + z_hi * ih * iw + y_hi * iw + x_lo];
                let v111 = storage[base + z_hi * ih * iw + y_hi * iw + x_hi];
                *slot = v000 * (1.0 - zt) * (1.0 - yt) * (1.0 - xt)
                    + v001 * (1.0 - zt) * (1.0 - yt) * xt
                    + v010 * (1.0 - zt) * yt * (1.0 - xt)
                    + v011 * (1.0 - zt) * yt * xt
                    + v100 * zt * (1.0 - yt) * (1.0 - xt)
                    + v101 * zt * (1.0 - yt) * xt
                    + v110 * zt * yt * (1.0 - xt)
                    + v111 * zt * yt * xt;
            }
        };
        if total >= PARALLEL_ELEMENTWISE_MIN {
            values
                .par_chunks_mut(ow)
                .enumerate()
                .for_each(|(r, out_row)| fill_row(r, out_row));
        } else {
            values
                .chunks_mut(ow)
                .enumerate()
                .for_each(|(r, out_row)| fill_row(r, out_row));
        }
        values
    }

    // ── FFT operations ───────────────────────────────────────────────────

    /// In-place 1-D DFT. When `n` is a power of two, runs an
    /// iterative Cooley-Tukey decimation-in-time FFT in
    /// O(N log N) with O(log N · ε) accumulated rounding. For
    /// non-power-of-two `n`, falls back to the naive O(N^2) DFT.
    /// The caller passes interleaved real/imag buffers of length
    /// `n`; this function overwrites them with the transform.
    /// If `inverse` is true, computes the inverse DFT (positive
    /// twiddle exponent + 1/N normalization).
    /// frankentorch-hpo6.
    fn fft_stage_twiddles(n: usize, inverse: bool) -> Vec<(f64, f64)> {
        let sign = if inverse { 1.0 } else { -1.0 };
        let two_pi = 2.0 * std::f64::consts::PI;
        let mut twiddles = Vec::with_capacity(n.saturating_sub(1));
        let mut stage = 2usize;
        while stage <= n {
            let half = stage / 2;
            let angle_step = sign * two_pi / stage as f64;
            twiddles.extend((0..half).map(|k| {
                let angle = angle_step * k as f64;
                (angle.cos(), angle.sin())
            }));
            stage *= 2;
        }
        twiddles
    }

    fn dft_inplace_1d(re: &mut [f64], im: &mut [f64], inverse: bool) {
        Self::dft_inplace_1d_with_stage_twiddles(re, im, inverse, None);
    }

    /// Below this length the naive O(N^2) DFT is cheaper than Bluestein's three
    /// padded power-of-two FFTs (and is kept so small non-power-of-two sizes stay
    /// bit-for-bit unchanged). At/above it, Bluestein wins by O(N/log N).
    const BLUESTEIN_MIN_LEN: usize = 64;

    /// Bluestein's chirp-z transform: compute the (UN-normalized) length-`n` DFT
    /// of `re`/`im` in place for ARBITRARY `n` — including primes — in
    /// `O(N log N)` instead of the naive `O(N^2)` sum. The caller's shared
    /// `1/N` inverse normalization still runs afterwards (this returns the raw
    /// transform sum, exactly like the naive fallback it replaces).
    ///
    /// Identity `k·j = (k² + j² − (k−j)²)/2` rewrites the DFT as a convolution:
    /// with chirp `b[j] = exp(s·π·i·j²/N)` (`s = −1` forward, `+1` inverse),
    /// `X[k] = b[k] · Σ_j (x[j]·b[j]) · conj(b[k−j])`. That linear convolution is
    /// evaluated as a length-`M` cyclic convolution (`M = next_pow2(2N−1)`,
    /// chosen so the wrap-around cannot alias) via three power-of-two FFTs
    /// (the existing radix-2 butterfly path). `j²` is reduced mod `2N` before the
    /// trig call so the chirp stays accurate for large `j`.
    fn bluestein_dft(re: &mut [f64], im: &mut [f64], inverse: bool) {
        let n = re.len();
        let sign = if inverse { 1.0 } else { -1.0 };
        let pi = std::f64::consts::PI;

        // Chirp b[j] = exp(s·π·i·j²/N); reduce j² mod 2N for trig accuracy.
        let mut b_re = vec![0.0_f64; n];
        let mut b_im = vec![0.0_f64; n];
        let two_n = 2 * n as u128;
        for j in 0..n {
            let jj = ((j as u128 * j as u128) % two_n) as f64;
            let angle = sign * pi * jj / n as f64;
            b_re[j] = angle.cos();
            b_im[j] = angle.sin();
        }

        let m = (2 * n - 1).next_power_of_two();
        // a[j] = x[j] · b[j], zero-padded to length M.
        let mut a_re = vec![0.0_f64; m];
        let mut a_im = vec![0.0_f64; m];
        for j in 0..n {
            a_re[j] = re[j] * b_re[j] - im[j] * b_im[j];
            a_im[j] = re[j] * b_im[j] + im[j] * b_re[j];
        }
        // Convolution kernel h[d] = conj(b[d]) at +d and the wrapped −d ≡ M−d.
        let mut h_re = vec![0.0_f64; m];
        let mut h_im = vec![0.0_f64; m];
        h_re[0] = b_re[0];
        h_im[0] = -b_im[0];
        for d in 1..n {
            let cr = b_re[d];
            let ci = -b_im[d];
            h_re[d] = cr;
            h_im[d] = ci;
            h_re[m - d] = cr;
            h_im[m - d] = ci;
        }

        // Cyclic convolution via FFT: conv = IFFT(FFT(a) · FFT(h)). The internal
        // FFTs are power-of-two, so they take the fast butterfly path (no
        // recursion back into Bluestein); the inverse supplies the 1/M factor.
        Self::dft_inplace_1d(&mut a_re, &mut a_im, false);
        Self::dft_inplace_1d(&mut h_re, &mut h_im, false);
        for j in 0..m {
            let pr = a_re[j] * h_re[j] - a_im[j] * h_im[j];
            let pii = a_re[j] * h_im[j] + a_im[j] * h_re[j];
            a_re[j] = pr;
            a_im[j] = pii;
        }
        Self::dft_inplace_1d(&mut a_re, &mut a_im, true);

        // X[k] = b[k] · conv[k].
        for k in 0..n {
            let cr = a_re[k];
            let ci = a_im[k];
            re[k] = b_re[k] * cr - b_im[k] * ci;
            im[k] = b_re[k] * ci + b_im[k] * cr;
        }
    }

    /// Forward FFT of a REAL signal `x` (length `n`, even) returning only the
    /// non-redundant `n/2 + 1` frequencies as `(re, im)`.
    ///
    /// Uses the standard real-FFT packing: form `m = n/2` complex samples
    /// `z[j] = x[2j] + i x[2j+1]`, take an `m`-point complex FFT, and recombine
    /// (`X[k] = Even[k] + W_N^k Odd[k]`, with the even/odd split recovered from
    /// `Z[k]` and `conj Z[m-k]`). This does HALF the FFT work of the current
    /// full-`n` complex transform that `tensor_rfft`/`rfft2`/STFT run on real
    /// input. It equals the dense path up to FFT round-off (~ULP) — matching
    /// PyTorch, which is also real-FFT-based.
    ///
    /// Not yet wired into the production rfft paths (they are pinned bit-exact to
    /// the full-complex FFT by `*_parallel_match_serial` tests); validated by
    /// `real_fft_1d_matches_full_complex_within_tolerance`.
    #[must_use]
    fn real_fft_1d_f64(x: &[f64]) -> (Vec<f64>, Vec<f64>) {
        let n = x.len();
        debug_assert!(n.is_multiple_of(2), "real_fft_1d_f64 requires even length");
        let m = n / 2;
        let out_len = m + 1;
        if m == 0 {
            // n == 0: empty; n handled by caller. (n>=2 in practice.)
            return (vec![0.0; out_len.min(1)], vec![0.0; out_len.min(1)]);
        }
        let mut re = vec![0.0_f64; m];
        let mut im = vec![0.0_f64; m];
        for j in 0..m {
            re[j] = x[2 * j];
            im[j] = x[2 * j + 1];
        }
        Self::dft_inplace_1d(&mut re, &mut im, false);

        let mut out_re = vec![0.0_f64; out_len];
        let mut out_im = vec![0.0_f64; out_len];
        let two_pi = 2.0 * std::f64::consts::PI;
        for k in 0..out_len {
            let k1 = k % m;
            let k2 = (m - k) % m;
            let zk_re = re[k1];
            let zk_im = im[k1];
            // conj(Z[m-k])
            let zmk_re = re[k2];
            let zmk_im = -im[k2];
            // Even = (Z[k] + conj Z[m-k]) / 2
            let even_re = (zk_re + zmk_re) * 0.5;
            let even_im = (zk_im + zmk_im) * 0.5;
            // Odd = (Z[k] - conj Z[m-k]) * (-i/2)
            let d_re = zk_re - zmk_re;
            let d_im = zk_im - zmk_im;
            let odd_re = 0.5 * d_im;
            let odd_im = -0.5 * d_re;
            // twiddle W_N^k = exp(-2 pi i k / n)
            let ang = two_pi * (k as f64) / (n as f64);
            let tw_re = ang.cos();
            let tw_im = -ang.sin();
            // X[k] = Even + twiddle * Odd
            out_re[k] = even_re + (tw_re * odd_re - tw_im * odd_im);
            out_im[k] = even_im + (tw_re * odd_im + tw_im * odd_re);
        }
        (out_re, out_im)
    }

    /// [`real_fft_1d_f64`] with the per-call twiddles hoisted out: the (n/2)-point
    /// FFT's stage twiddles and the n/2+1 recombination twiddles are passed in so a
    /// BATCH of same-length real FFTs (e.g. STFT frames) computes them once instead
    /// of per frame. BIT-IDENTICAL to `real_fft_1d_f64` when `half_stage_twiddles`
    /// == `fft_stage_twiddles(n/2, false)` (or None for non-pow2 n/2) and
    /// `recombine[k]` == `(cos(2πk/n), -sin(2πk/n))` — the exact values it computes
    /// inline. `recombine` must have length `n/2 + 1`.
    #[must_use]
    fn real_fft_1d_f64_with_twiddles(
        x: &[f64],
        half_stage_twiddles: Option<&[(f64, f64)]>,
        recombine: &[(f64, f64)],
    ) -> (Vec<f64>, Vec<f64>) {
        let n = x.len();
        debug_assert!(
            n.is_multiple_of(2),
            "real_fft_1d_f64_with_twiddles needs even length"
        );
        let m = n / 2;
        let out_len = m + 1;
        if m == 0 {
            return (vec![0.0; out_len.min(1)], vec![0.0; out_len.min(1)]);
        }
        let mut re = vec![0.0_f64; m];
        let mut im = vec![0.0_f64; m];
        for j in 0..m {
            re[j] = x[2 * j];
            im[j] = x[2 * j + 1];
        }
        Self::dft_inplace_1d_with_stage_twiddles(&mut re, &mut im, false, half_stage_twiddles);
        let mut out_re = vec![0.0_f64; out_len];
        let mut out_im = vec![0.0_f64; out_len];
        for k in 0..out_len {
            let k1 = k % m;
            let k2 = (m - k) % m;
            let zk_re = re[k1];
            let zk_im = im[k1];
            let zmk_re = re[k2];
            let zmk_im = -im[k2];
            let even_re = (zk_re + zmk_re) * 0.5;
            let even_im = (zk_im + zmk_im) * 0.5;
            let d_re = zk_re - zmk_re;
            let d_im = zk_im - zmk_im;
            let odd_re = 0.5 * d_im;
            let odd_im = -0.5 * d_re;
            let (tw_re, tw_im) = recombine[k];
            out_re[k] = even_re + (tw_re * odd_re - tw_im * odd_im);
            out_im[k] = even_im + (tw_re * odd_im + tw_im * odd_re);
        }
        (out_re, out_im)
    }

    /// Inverse FFT producing a REAL signal of length `n` (even) from its
    /// non-redundant `n/2 + 1` frequencies `(in_re, in_im)` (Hermitian).
    ///
    /// The dual of [`real_fft_1d_f64`]: recover the `m = n/2`-point spectrum
    /// `Z[k] = Even[k] + i Odd[k]` (Even/Odd from `X[k]` & `conj X[m-k]`), take an
    /// `m`-point INVERSE FFT, and unpack `x[2j] = Re z[j]`, `x[2j+1] = Im z[j]`.
    /// Half the inverse-FFT work of the current full-`n` complex transform.
    /// Equals the dense path up to FFT round-off (~ULP), matching PyTorch.
    /// Validated by `irfft_1d_matches_full_complex_within_tolerance`.
    #[must_use]
    fn irfft_1d_f64(in_re: &[f64], in_im: &[f64], n: usize) -> Vec<f64> {
        debug_assert!(n.is_multiple_of(2), "irfft_1d_f64 requires even n");
        let m = n / 2;
        if m == 0 {
            return vec![0.0; n];
        }
        debug_assert!(in_re.len() > m && in_im.len() > m);
        let two_pi = 2.0 * std::f64::consts::PI;
        let mut zr = vec![0.0_f64; m];
        let mut zi = vec![0.0_f64; m];
        for k in 0..m {
            let xk_re = in_re[k];
            let xk_im = in_im[k];
            // conj(X[m-k]); X[m-0]=X[m], X[m-(m-1)]=X[1] — all within 0..=m.
            let xmk_re = in_re[m - k];
            let xmk_im = -in_im[m - k];
            // Even = (X[k] + conj X[m-k]) / 2
            let even_re = (xk_re + xmk_re) * 0.5;
            let even_im = (xk_im + xmk_im) * 0.5;
            // diff = (X[k] - conj X[m-k]) / 2
            let diff_re = (xk_re - xmk_re) * 0.5;
            let diff_im = (xk_im - xmk_im) * 0.5;
            // conj(W_N^k) = exp(+2 pi i k / n)
            let ang = two_pi * (k as f64) / (n as f64);
            let cw_re = ang.cos();
            let cw_im = ang.sin();
            // Odd = diff * conj(W^k)
            let odd_re = diff_re * cw_re - diff_im * cw_im;
            let odd_im = diff_re * cw_im + diff_im * cw_re;
            // Z[k] = Even + i*Odd
            zr[k] = even_re - odd_im;
            zi[k] = even_im + odd_re;
        }
        // m-point inverse FFT (includes 1/m normalization).
        Self::dft_inplace_1d(&mut zr, &mut zi, true);
        let mut out = vec![0.0_f64; n];
        for j in 0..m {
            out[2 * j] = zr[j];
            out[2 * j + 1] = zi[j];
        }
        out
    }

    fn dft_inplace_1d_with_stage_twiddles(
        re: &mut [f64],
        im: &mut [f64],
        inverse: bool,
        shared_twiddles: Option<&[(f64, f64)]>,
    ) {
        let n = re.len();
        assert_eq!(re.len(), im.len(), "dft_inplace_1d re/im length mismatch");
        if n <= 1 {
            if inverse && n == 1 {
                // 1-element inverse: divide by 1, no-op.
            }
            return;
        }

        if n.is_power_of_two() {
            // Bit-reversal permutation.
            let mut j = 0usize;
            for i in 1..n {
                let mut bit = n >> 1;
                while j & bit != 0 {
                    j ^= bit;
                    bit >>= 1;
                }
                j ^= bit;
                if i < j {
                    re.swap(i, j);
                    im.swap(i, j);
                }
            }
            // Butterfly stages.
            let sign = if inverse { 1.0 } else { -1.0 };
            let two_pi = 2.0 * std::f64::consts::PI;
            let mut stage = 2usize;
            let mut twiddle_offset = 0usize;
            while stage <= n {
                let half = stage / 2;
                if let Some(twiddles) = shared_twiddles {
                    let stage_twiddles = &twiddles[twiddle_offset..twiddle_offset + half];
                    twiddle_offset += half;
                    for start in (0..n).step_by(stage) {
                        for (k, (w_re, w_im)) in stage_twiddles.iter().copied().enumerate() {
                            let idx = start + k;
                            let jdx = start + k + half;
                            let tw_re = w_re * re[jdx] - w_im * im[jdx];
                            let tw_im = w_re * im[jdx] + w_im * re[jdx];
                            re[jdx] = re[idx] - tw_re;
                            im[jdx] = im[idx] - tw_im;
                            re[idx] += tw_re;
                            im[idx] += tw_im;
                        }
                    }
                } else {
                    let angle_step = sign * two_pi / stage as f64;
                    let twiddles: Vec<(f64, f64)> = (0..half)
                        .map(|k| {
                            let angle = angle_step * k as f64;
                            (angle.cos(), angle.sin())
                        })
                        .collect();
                    for start in (0..n).step_by(stage) {
                        for (k, (w_re, w_im)) in twiddles.iter().copied().enumerate() {
                            let idx = start + k;
                            let jdx = start + k + half;
                            let tw_re = w_re * re[jdx] - w_im * im[jdx];
                            let tw_im = w_re * im[jdx] + w_im * re[jdx];
                            re[jdx] = re[idx] - tw_re;
                            im[jdx] = im[idx] - tw_im;
                            re[idx] += tw_re;
                            im[idx] += tw_im;
                        }
                    }
                }
                stage *= 2;
            }
        } else if n >= Self::BLUESTEIN_MIN_LEN {
            // Non-power-of-two: Bluestein's chirp-z transform, O(N log N).
            Self::bluestein_dft(re, im, inverse);
        } else {
            // Small non-power-of-two: naive O(N^2) DFT (cheap at this size).
            let mut out_re = vec![0.0_f64; n];
            let mut out_im = vec![0.0_f64; n];
            let sign = if inverse { 1.0 } else { -1.0 };
            let two_pi = 2.0 * std::f64::consts::PI;
            for k in 0..n {
                let mut acc_re = 0.0_f64;
                let mut acc_im = 0.0_f64;
                for nn in 0..n {
                    let angle = sign * two_pi * k as f64 * nn as f64 / n as f64;
                    let c = angle.cos();
                    let s = angle.sin();
                    acc_re += re[nn] * c - im[nn] * s;
                    acc_im += re[nn] * s + im[nn] * c;
                }
                out_re[k] = acc_re;
                out_im[k] = acc_im;
            }
            re.copy_from_slice(&out_re);
            im.copy_from_slice(&out_im);
        }

        if inverse {
            let inv_n = 1.0 / n as f64;
            for v in re.iter_mut() {
                *v *= inv_n;
            }
            for v in im.iter_mut() {
                *v *= inv_n;
            }
        }
    }

    /// Apply FFT (or inverse FFT) along a specific dimension.
    /// Used by fftn/ifftn for iterative dimension-wise transforms.
    fn tensor_fft_along_dim(
        &mut self,
        input: TensorNodeId,
        dim: usize,
        inverse: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        let dtype = self.tensor_dtype(input)?;
        let shape = self.tensor_shape(input)?;
        let ndim = shape.len();
        if dim >= ndim {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "fft_along_dim: dimension out of range",
                },
            )));
        }
        let is_complex = dtype == DType::Complex128 || dtype == DType::Complex64;
        let requires_grad = self.tensor_requires_grad(input)? && self.tensor_tape.is_grad_enabled();
        let dim_size = shape[dim];
        let total_elements: usize = shape.iter().product();
        let stride_outer: usize = shape[..dim].iter().product();
        let stride_inner: usize = shape[dim + 1..].iter().product();
        let mut re_data;
        let mut im_data;
        if is_complex {
            // Read complex storage directly into split re/im (NOT via the
            // now-differentiable tensor_view_as_real, which would record a stray
            // node — the custom adjoint below is attached to `input` itself).
            // frankentorch-ng1hw.
            match self.tensor_tape.tensor(input)?.typed_storage() {
                TensorStorage::Complex128(values) => {
                    re_data = values.iter().map(|z| z.re).collect();
                    im_data = values.iter().map(|z| z.im).collect();
                }
                TensorStorage::Complex64(values) => {
                    re_data = values.iter().map(|z| f64::from(z.re)).collect();
                    im_data = values.iter().map(|z| f64::from(z.im)).collect();
                }
                _ => unreachable!("is_complex implies complex storage"),
            }
        } else {
            let vals = self.tensor_values(input)?;
            re_data = vals;
            im_data = vec![0.0_f64; total_elements];
        }
        // Each (outer, inner) lane is an independent 1-D DFT (O(N log N) trig
        // butterflies — compute-bound). When the transform dim is the last one
        // (stride_inner == 1) every lane is a CONTIGUOUS block of dim_size, so we
        // can run dft_inplace_1d in place on `par_chunks_mut(dim_size)` with no
        // gather/scatter and no per-lane allocation. Each lane is independent and
        // the transform is deterministic, so the result is bit-for-bit identical
        // to the serial loop. (Strided non-last-dim transforms keep the serial
        // gather/scatter — fftn drives the last dim first anyway.)
        let num_lanes = stride_outer * stride_inner;
        let shared_twiddles = (num_lanes >= 2 && dim_size.is_power_of_two())
            .then(|| Self::fft_stage_twiddles(dim_size, inverse));
        if stride_inner == 1 && num_lanes >= 2 && total_elements >= PARALLEL_ELEMENTWISE_MIN {
            use rayon::prelude::*;
            let shared_twiddles = shared_twiddles.as_deref();
            re_data
                .par_chunks_mut(dim_size)
                .zip(im_data.par_chunks_mut(dim_size))
                .for_each(|(re_slice, im_slice)| {
                    Self::dft_inplace_1d_with_stage_twiddles(
                        re_slice,
                        im_slice,
                        inverse,
                        shared_twiddles,
                    );
                });
        } else if stride_outer >= 2 && num_lanes >= 2 && total_elements >= PARALLEL_ELEMENTWISE_MIN
        {
            // Strided non-last-dim transform (stride_inner > 1): each `outer` block is a
            // disjoint contiguous `dim_size*stride_inner` chunk of re/im_data, so distribute
            // the outer blocks across workers (each gathers/dft/scatters its strided lanes in
            // place). The per-lane dft (compute-bound butterflies) is deterministic and the
            // blocks are disjoint, so this is bit-for-bit identical to the serial gather/
            // scatter. Covers fftn's non-first-dim passes (the contiguous last dim already has
            // its own parallel path above). frankentorch-fftn-stride.
            use rayon::prelude::*;
            let shared_twiddles = shared_twiddles.as_deref();
            let block = dim_size * stride_inner;
            re_data
                .par_chunks_mut(block)
                .zip(im_data.par_chunks_mut(block))
                .for_each(|(re_blk, im_blk)| {
                    let mut re_slice = vec![0.0_f64; dim_size];
                    let mut im_slice = vec![0.0_f64; dim_size];
                    for inner in 0..stride_inner {
                        for k in 0..dim_size {
                            let idx = k * stride_inner + inner;
                            re_slice[k] = re_blk[idx];
                            im_slice[k] = im_blk[idx];
                        }
                        Self::dft_inplace_1d_with_stage_twiddles(
                            &mut re_slice,
                            &mut im_slice,
                            inverse,
                            shared_twiddles,
                        );
                        for k in 0..dim_size {
                            let idx = k * stride_inner + inner;
                            re_blk[idx] = re_slice[k];
                            im_blk[idx] = im_slice[k];
                        }
                    }
                });
        } else if stride_outer == 1
            && stride_inner >= 2
            && num_lanes >= 2
            && total_elements >= PARALLEL_ELEMENTWISE_MIN
        {
            // First-dim transform of an n-D tensor (stride_outer == 1): the `stride_inner`
            // lanes are STRIDED columns (k*stride_inner+inner), not a contiguous chunk, so
            // par_chunks_mut can't apply. Parallel-map each lane to a transformed (re,im) buffer
            // (immutable strided gather + compute-bound dft), collect in lane order, then scatter
            // back serially. This covers the common 2-D-FFT row pass that the stride_outer>=2
            // branch above misses. Bit-for-bit identical to the serial loop: deterministic
            // per-lane dft, identical gather/scatter indices, lane-ordered. frankentorch-fftn-dim0.
            use rayon::prelude::*;
            let shared_twiddles = shared_twiddles.as_deref();
            let transformed: Vec<(Vec<f64>, Vec<f64>)> = (0..stride_inner)
                .into_par_iter()
                .map(|inner| {
                    let mut re_col = vec![0.0_f64; dim_size];
                    let mut im_col = vec![0.0_f64; dim_size];
                    for k in 0..dim_size {
                        let idx = k * stride_inner + inner;
                        re_col[k] = re_data[idx];
                        im_col[k] = im_data[idx];
                    }
                    Self::dft_inplace_1d_with_stage_twiddles(
                        &mut re_col,
                        &mut im_col,
                        inverse,
                        shared_twiddles,
                    );
                    (re_col, im_col)
                })
                .collect();
            for (inner, (re_col, im_col)) in transformed.into_iter().enumerate() {
                for k in 0..dim_size {
                    let idx = k * stride_inner + inner;
                    re_data[idx] = re_col[k];
                    im_data[idx] = im_col[k];
                }
            }
        } else {
            let shared_twiddles = shared_twiddles.as_deref();
            for outer in 0..stride_outer {
                for inner in 0..stride_inner {
                    let mut re_slice = vec![0.0_f64; dim_size];
                    let mut im_slice = vec![0.0_f64; dim_size];
                    for k in 0..dim_size {
                        let idx = outer * dim_size * stride_inner + k * stride_inner + inner;
                        re_slice[k] = re_data[idx];
                        im_slice[k] = im_data[idx];
                    }
                    Self::dft_inplace_1d_with_stage_twiddles(
                        &mut re_slice,
                        &mut im_slice,
                        inverse,
                        shared_twiddles,
                    );
                    for k in 0..dim_size {
                        let idx = outer * dim_size * stride_inner + k * stride_inner + inner;
                        re_data[idx] = re_slice[k];
                        im_data[idx] = im_slice[k];
                    }
                }
            }
        }
        let output = DenseTensor::from_typed_storage(
            TensorMeta::from_shape(shape.clone(), DType::Complex128, Device::Cpu),
            TensorStorage::Complex128(Arc::new(
                re_data
                    .iter()
                    .zip(im_data.iter())
                    .map(|(&r, &i)| Complex128::new(r, i))
                    .collect(),
            )),
        )?;

        // Autograd (frankentorch-ng1hw): a 1-D FFT along `dim` is a per-lane linear
        // map (no norm factor — fftn applies that separately). Its adjoint runs the
        // inverse transform per lane on grad_y: forward fft -> grad_x = L·ifft(grad_y)
        // (unnormalized iDFT); inverse fft -> grad_x = (1/L)·forwardDFT(grad_y) =
        // conj(ifft(conj(grad_y))). For a real input the grad is the real part. This
        // makes fftn/ifftn differentiable by composition. Verified vs torch.
        if requires_grad {
            self.tensor_tape
                .apply_complex_bridge(&[input], output, move |_ctx, grad_outputs| {
                    let g = grad_outputs[0]; // 2*total_elements interleaved
                    let mut gre = vec![0.0_f64; total_elements];
                    let mut gim = vec![0.0_f64; total_elements];
                    for i in 0..total_elements {
                        gre[i] = g[2 * i];
                        gim[i] = g[2 * i + 1];
                    }
                    let mut re_l = vec![0.0_f64; dim_size];
                    let mut im_l = vec![0.0_f64; dim_size];
                    for outer in 0..stride_outer {
                        for inner in 0..stride_inner {
                            for k in 0..dim_size {
                                let idx =
                                    outer * dim_size * stride_inner + k * stride_inner + inner;
                                re_l[k] = gre[idx];
                                im_l[k] = gim[idx];
                            }
                            if inverse {
                                // (1/L)·forwardDFT = conj(ifft(conj(·))).
                                for v in im_l.iter_mut() {
                                    *v = -*v;
                                }
                                Self::dft_inplace_1d(&mut re_l, &mut im_l, true);
                                for v in im_l.iter_mut() {
                                    *v = -*v;
                                }
                            } else {
                                // L·ifft (unnormalized iDFT; dft_inplace carries 1/L).
                                Self::dft_inplace_1d(&mut re_l, &mut im_l, true);
                                let l = dim_size as f64;
                                for v in re_l.iter_mut().chain(im_l.iter_mut()) {
                                    *v *= l;
                                }
                            }
                            for k in 0..dim_size {
                                let idx =
                                    outer * dim_size * stride_inner + k * stride_inner + inner;
                                gre[idx] = re_l[k];
                                gim[idx] = im_l[k];
                            }
                        }
                    }
                    if is_complex {
                        let mut grad_x = vec![0.0_f64; total_elements * 2];
                        for i in 0..total_elements {
                            grad_x[2 * i] = gre[i];
                            grad_x[2 * i + 1] = gim[i];
                        }
                        Ok(vec![Some(grad_x)])
                    } else {
                        // Real input: gradient is the real part.
                        Ok(vec![Some(gre)])
                    }
                })
        } else {
            Ok(self.tensor_tape.leaf_tensor(output, false))
        }
    }

    /// Resize tensor by padding with zeros or cropping.
    fn tensor_resize_with_pad_or_crop(
        &mut self,
        input: TensorNodeId,
        target_shape: &[usize],
    ) -> Result<TensorNodeId, AutogradError> {
        let current_shape = self.tensor_shape(input)?;
        if current_shape == target_shape {
            return Ok(input);
        }
        let vals = self.tensor_values(input)?;
        let mut result = vec![0.0_f64; target_shape.iter().product()];
        fn copy_recursive(
            src: &[f64],
            dst: &mut [f64],
            src_shape: &[usize],
            dst_shape: &[usize],
            src_idx: usize,
            dst_idx: usize,
            dim: usize,
            _src_stride: usize,
            _dst_stride: usize,
        ) {
            if dim == src_shape.len() {
                dst[dst_idx] = src[src_idx];
                return;
            }
            let copy_len = src_shape[dim].min(dst_shape[dim]);
            let new_src_stride = if dim + 1 < src_shape.len() {
                src_shape[dim + 1..].iter().product()
            } else {
                1
            };
            let new_dst_stride = if dim + 1 < dst_shape.len() {
                dst_shape[dim + 1..].iter().product()
            } else {
                1
            };
            for i in 0..copy_len {
                copy_recursive(
                    src,
                    dst,
                    src_shape,
                    dst_shape,
                    src_idx + i * new_src_stride,
                    dst_idx + i * new_dst_stride,
                    dim + 1,
                    new_src_stride,
                    new_dst_stride,
                );
            }
        }
        let src_stride: usize = if current_shape.is_empty() {
            1
        } else {
            current_shape.iter().product()
        };
        let dst_stride: usize = if target_shape.is_empty() {
            1
        } else {
            target_shape.iter().product()
        };
        copy_recursive(
            &vals,
            &mut result,
            &current_shape,
            target_shape,
            0,
            0,
            0,
            src_stride,
            dst_stride,
        );
        self.tensor_variable(result, target_shape.to_vec(), false)
    }

    /// Extend a half-spectrum complex tensor to full length using Hermitian symmetry.
    fn tensor_hermitian_extend(
        &mut self,
        input: TensorNodeId,
        dim: usize,
        full_len: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        let half_len = shape[dim];
        if half_len > full_len {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "hermitian_extend: half_len exceeds full_len",
                },
            )));
        }
        // Read complex storage directly (NOT via the now-differentiable
        // tensor_view_as_real, which would record a stray node). frankentorch-ng1hw.
        let requires_grad = self.tensor_requires_grad(input)? && self.tensor_tape.is_grad_enabled();
        let (re_data, im_data): (Vec<f64>, Vec<f64>) =
            match self.tensor_tape.tensor(input)?.typed_storage() {
                TensorStorage::Complex128(values) => (
                    values.iter().map(|z| z.re).collect(),
                    values.iter().map(|z| z.im).collect(),
                ),
                TensorStorage::Complex64(values) => (
                    values.iter().map(|z| f64::from(z.re)).collect(),
                    values.iter().map(|z| f64::from(z.im)).collect(),
                ),
                _ => {
                    let real_view = self.tensor_view_as_real(input)?;
                    let vals = self.tensor_values(real_view)?;
                    let count = vals.len() / 2;
                    (
                        (0..count).map(|i| vals[i * 2]).collect(),
                        (0..count).map(|i| vals[i * 2 + 1]).collect(),
                    )
                }
            };
        let mut out_shape = shape.clone();
        out_shape[dim] = full_len;
        let out_total: usize = out_shape.iter().product();
        let mut re_out = vec![0.0_f64; out_total];
        let mut im_out = vec![0.0_f64; out_total];
        let stride_outer: usize = shape[..dim].iter().product();
        let stride_inner: usize = shape[dim + 1..].iter().product();
        let out_stride_inner: usize = out_shape[dim + 1..].iter().product();
        for outer in 0..stride_outer {
            for inner in 0..stride_inner {
                for k in 0..half_len {
                    let src_idx = outer * half_len * stride_inner + k * stride_inner + inner;
                    let dst_idx =
                        outer * full_len * out_stride_inner + k * out_stride_inner + inner;
                    re_out[dst_idx] = re_data[src_idx];
                    im_out[dst_idx] = im_data[src_idx];
                }
                for k in half_len..full_len {
                    let conj_k = full_len - k;
                    if conj_k < half_len {
                        let src_idx =
                            outer * half_len * stride_inner + conj_k * stride_inner + inner;
                        let dst_idx =
                            outer * full_len * out_stride_inner + k * out_stride_inner + inner;
                        re_out[dst_idx] = re_data[src_idx];
                        im_out[dst_idx] = -im_data[src_idx];
                    }
                }
            }
        }
        let output = DenseTensor::from_typed_storage(
            TensorMeta::from_shape(out_shape.clone(), DType::Complex128, Device::Cpu),
            TensorStorage::Complex128(Arc::new(
                re_out
                    .iter()
                    .zip(im_out.iter())
                    .map(|(&r, &i)| Complex128::new(r, i))
                    .collect(),
            )),
        )?;

        // Autograd (frankentorch-ng1hw): hermitian_extend is a linear map from the
        // half-spectrum to the full spectrum (direct copy of bins 0..half plus a
        // conjugate-mirror of bins 1..half into half..full). Its adjoint folds each
        // output bin's cotangent back: grad_in[j] = grad_out[j] + (mirror exists ?
        // conj-flip(grad_out[full-j]) : 0). Used by irfftn -> makes it differentiable.
        if requires_grad {
            self.tensor_tape
                .apply_complex_bridge(&[input], output, move |_ctx, grad_outputs| {
                    let g = grad_outputs[0]; // 2*out_total interleaved
                    let mut grad_in = vec![0.0_f64; half_len * stride_outer * stride_inner * 2];
                    for outer in 0..stride_outer {
                        for inner in 0..stride_inner {
                            for j in 0..half_len {
                                let in_idx =
                                    outer * half_len * stride_inner + j * stride_inner + inner;
                                let out_idx = outer * full_len * out_stride_inner
                                    + j * out_stride_inner
                                    + inner;
                                let mut gr = g[2 * out_idx];
                                let mut gi = g[2 * out_idx + 1];
                                let k = full_len - j;
                                if j >= 1 && k >= half_len && k < full_len {
                                    let m_idx = outer * full_len * out_stride_inner
                                        + k * out_stride_inner
                                        + inner;
                                    gr += g[2 * m_idx];
                                    gi -= g[2 * m_idx + 1]; // conjugate mirror
                                }
                                grad_in[2 * in_idx] = gr;
                                grad_in[2 * in_idx + 1] = gi;
                            }
                        }
                    }
                    Ok(vec![Some(grad_in)])
                })
        } else {
            Ok(self.tensor_tape.leaf_tensor(output, false))
        }
    }

    /// Compute the 1-D Discrete Fourier Transform.
    ///
    /// Equivalent to `torch.fft.fft(input, n)`.
    /// Input is a 1-D real tensor. Output is a 1-D Complex128 tensor of length `n`.
    /// If `n` is None, uses the input length.
    /// Output-scale factor for `torch.fft.*(norm=...)` RELATIVE to FrankenTorch's
    /// default convention (forward FFT: unscaled "backward"; inverse FFT: already
    /// carries the 1/N). torch: backward => fft×1, ifft×1/N; forward => fft×1/N,
    /// ifft×1; ortho => both ×1/√N. Errors on an unknown mode.
    fn fft_norm_factor(norm: &str, n: usize, inverse: bool) -> Result<f64, AutogradError> {
        let nf = n as f64;
        Ok(match (norm, inverse) {
            ("backward", _) => 1.0,
            ("forward", false) => 1.0 / nf,
            ("forward", true) => nf,
            ("ortho", false) => 1.0 / nf.sqrt(),
            ("ortho", true) => nf.sqrt(),
            _ => {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "fft: norm must be \"backward\", \"forward\", or \"ortho\"",
                    },
                )));
            }
        })
    }

    pub fn tensor_fft(
        &mut self,
        input: TensorNodeId,
        n: Option<usize>,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_fft_norm(input, n, "backward")
    }

    /// `torch.fft.fft(input, n=n, norm=norm)`. `norm` is "backward" (default, no
    /// scaling), "forward" (scale by 1/N), or "ortho" (scale by 1/√N). The norm
    /// only rescales the output, so it is exact and composes with the existing
    /// DFT.
    pub fn tensor_fft_norm(
        &mut self,
        input: TensorNodeId,
        n: Option<usize>,
        norm: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        let requires_grad = self.tensor_requires_grad(input)? && self.tensor_tape.is_grad_enabled();
        let vals = self.tensor_values(input)?;
        let input_len = vals.len();
        let fft_len = n.unwrap_or(input_len);
        let factor = Self::fft_norm_factor(norm, fft_len, false)?;

        // Zero-pad or truncate input to length n. Build real
        // interleaved storage with zero imaginary part.
        let mut re_buf = vec![0.0_f64; fft_len];
        let mut im_buf = vec![0.0_f64; fft_len];
        let copy_len = input_len.min(fft_len);
        re_buf[..copy_len].copy_from_slice(&vals[..copy_len]);

        // Cooley-Tukey for power-of-two N, O(N^2) fallback otherwise.
        // frankentorch-hpo6.
        if fft_len.is_power_of_two() {
            let twiddles = Self::fft_stage_twiddles(fft_len, false);
            Self::dft_inplace_1d_with_stage_twiddles(
                &mut re_buf,
                &mut im_buf,
                false,
                Some(&twiddles),
            );
        } else {
            Self::dft_inplace_1d(&mut re_buf, &mut im_buf, false);
        }

        if factor != 1.0 {
            for v in re_buf.iter_mut().chain(im_buf.iter_mut()) {
                *v *= factor;
            }
        }

        // Build the complex output directly (interleaved [re,im] storage). The
        // forward values are unchanged from the non-grad path.
        let output = DenseTensor::from_typed_storage(
            TensorMeta::from_shape(vec![fft_len], DType::Complex128, Device::Cpu),
            TensorStorage::Complex128(Arc::new(
                re_buf
                    .iter()
                    .zip(im_buf.iter())
                    .map(|(&r, &i)| Complex128::new(r, i))
                    .collect(),
            )),
        )?;

        // Autograd (frankentorch-ng1hw): fft of a real input is the linear map
        // y = factor·DFT(x). For a real-valued input the adjoint is
        // grad_x = factor·Re(unnormalized iDFT(grad_y)) = factor·N·Re(ifft(grad_y)),
        // restricted to the copied positions (zero-padding / truncation contribute
        // no gradient). grad_y arrives as the complex output's interleaved buffer.
        if requires_grad {
            self.tensor_tape
                .apply_complex_bridge(&[input], output, move |_ctx, grad_outputs| {
                    let g = grad_outputs[0];
                    let mut gre = vec![0.0_f64; fft_len];
                    let mut gim = vec![0.0_f64; fft_len];
                    for k in 0..fft_len {
                        gre[k] = g[2 * k];
                        gim[k] = g[2 * k + 1];
                    }
                    Self::dft_inplace_1d(&mut gre, &mut gim, true);
                    let scale = factor * fft_len as f64;
                    let mut grad_x = vec![0.0_f64; input_len];
                    for j in 0..copy_len {
                        grad_x[j] = scale * gre[j];
                    }
                    Ok(vec![Some(grad_x)])
                })
        } else {
            Ok(self.tensor_tape.leaf_tensor(output, false))
        }
    }

    /// Compute the 1-D Inverse Discrete Fourier Transform.
    ///
    /// Equivalent to `torch.fft.ifft(input, n)`.
    /// Input is a Complex128 tensor. Output is Complex128.
    pub fn tensor_ifft(
        &mut self,
        input: TensorNodeId,
        n: Option<usize>,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_ifft_norm(input, n, "backward")
    }

    /// `torch.fft.ifft(input, n=n, norm=norm)`. `norm` is "backward" (default,
    /// the inverse carries the 1/N), "forward" (no 1/N — scale the default by N),
    /// or "ortho" (scale by √N so the net factor is 1/√N). Output rescale only.
    pub fn tensor_ifft_norm(
        &mut self,
        input: TensorNodeId,
        n: Option<usize>,
        norm: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        let requires_grad = self.tensor_requires_grad(input)? && self.tensor_tape.is_grad_enabled();
        let dtype = self.tensor_dtype(input)?;

        if dtype != DType::Complex128 && dtype != DType::Complex64 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "ifft: input must be complex",
                },
            )));
        }
        // Read the complex storage directly (NOT through the now-differentiable
        // tensor_view_as_real, which would record a stray graph node). The custom
        // adjoint below is attached to `input` itself. frankentorch-ng1hw.
        let (re_full, im_full): (Vec<f64>, Vec<f64>) =
            match self.tensor_tape.tensor(input)?.typed_storage() {
                TensorStorage::Complex128(values) => (
                    values.iter().map(|z| z.re).collect(),
                    values.iter().map(|z| z.im).collect(),
                ),
                TensorStorage::Complex64(values) => (
                    values.iter().map(|z| f64::from(z.re)).collect(),
                    values.iter().map(|z| f64::from(z.im)).collect(),
                ),
                _ => unreachable!("dtype checked complex above"),
            };
        let input_len = re_full.len();
        let fft_len = n.unwrap_or(input_len);

        // Extract real/imag parts (zero-pad or truncate to fft_len).
        let mut re_in = vec![0.0_f64; fft_len];
        let mut im_in = vec![0.0_f64; fft_len];
        let copy_len = input_len.min(fft_len);
        re_in[..copy_len].copy_from_slice(&re_full[..copy_len]);
        im_in[..copy_len].copy_from_slice(&im_full[..copy_len]);

        // Cooley-Tukey inverse DFT (positive sign + 1/N) when N is
        // a power of two, naive O(N^2) otherwise. frankentorch-hpo6.
        Self::dft_inplace_1d(&mut re_in, &mut im_in, true);

        let factor = Self::fft_norm_factor(norm, fft_len, true)?;
        if factor != 1.0 {
            for v in re_in.iter_mut().chain(im_in.iter_mut()) {
                *v *= factor;
            }
        }

        let output = DenseTensor::from_typed_storage(
            TensorMeta::from_shape(vec![fft_len], DType::Complex128, Device::Cpu),
            TensorStorage::Complex128(Arc::new(
                re_in
                    .iter()
                    .zip(im_in.iter())
                    .map(|(&r, &i)| Complex128::new(r, i))
                    .collect(),
            )),
        )?;

        // Autograd (frankentorch-ng1hw): ifft is the complex linear map
        // y = factor_t·(1/N)·Σ_k x_k·exp(+2πi kn/N). Its adjoint is
        // grad_x = (factor_t/N)·forwardDFT(grad_y), restricted to the copied
        // positions (zero-padding / truncation contribute no gradient). Both
        // grad_y and grad_x are interleaved complex buffers.
        if requires_grad {
            self.tensor_tape
                .apply_complex_bridge(&[input], output, move |_ctx, grad_outputs| {
                    let g = grad_outputs[0];
                    // grad_x = (factor/N)·forwardDFT(grad_y). Compute the forward DFT
                    // via the known-good inverse kernel using forwardDFT(v) =
                    // N·conj(ifft(conj(v))): dft_inplace_1d(.., true) already carries
                    // 1/N, so grad_x = factor·conj(ifft(conj(grad_y))). This sidesteps
                    // the inline-twiddle forward path. frankentorch-ng1hw.
                    let mut gre = vec![0.0_f64; fft_len];
                    let mut gim = vec![0.0_f64; fft_len];
                    for k in 0..fft_len {
                        gre[k] = g[2 * k];
                        gim[k] = -g[2 * k + 1]; // conj(grad_y)
                    }
                    Self::dft_inplace_1d(&mut gre, &mut gim, true); // ifft(conj(grad_y))
                    let mut grad_x = vec![0.0_f64; input_len * 2];
                    for k in 0..copy_len {
                        grad_x[2 * k] = factor * gre[k];
                        grad_x[2 * k + 1] = factor * (-gim[k]); // conj + scale
                    }
                    Ok(vec![Some(grad_x)])
                })
        } else {
            Ok(self.tensor_tape.leaf_tensor(output, false))
        }
    }

    /// Compute the 1-D real FFT (only positive frequencies).
    ///
    /// Equivalent to `torch.fft.rfft(input, n)`.
    /// Input is real. Output is Complex128 of length `n/2 + 1`.
    pub fn tensor_rfft(
        &mut self,
        input: TensorNodeId,
        n: Option<usize>,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_rfft_norm(input, n, "backward")
    }

    /// `torch.fft.rfft(input, n=n, norm=norm)`. Same norm convention as
    /// [`Self::tensor_fft_norm`] (the rescale uses the transform length N, not
    /// the n/2+1 output length): backward x1, forward x(1/N), ortho x(1/√N).
    pub fn tensor_rfft_norm(
        &mut self,
        input: TensorNodeId,
        n: Option<usize>,
        norm: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        let requires_grad = self.tensor_requires_grad(input)? && self.tensor_tape.is_grad_enabled();
        let vals = self.tensor_values(input)?;
        let input_len = vals.len();
        let fft_len = n.unwrap_or(input_len);
        let out_len = fft_len / 2 + 1;
        let factor = Self::fft_norm_factor(norm, fft_len, false)?;

        // Real input → only the first N/2+1 bins (the rest are conjugate-
        // symmetric). For EVEN N use the real-input FFT (real_fft_1d_f64): an
        // (N/2)-point complex transform + recombine — HALF the work of the full
        // N-point complex FFT, matching it within FFT round-off (~ULP), the same
        // path tensor_rfft2_norm already uses and torch's rfft is likewise
        // real-FFT-based. ODD N (real_fft requires even) keeps the full-complex
        // path. The inner transforms are O(N log N) (Bluestein for non-pow2).
        // frankentorch-hpo6.
        let copy_len = input_len.min(fft_len);
        let (mut re_out, mut im_out): (Vec<f64>, Vec<f64>) = if fft_len >= 2 && fft_len % 2 == 0 {
            let mut x = vec![0.0_f64; fft_len];
            x[..copy_len].copy_from_slice(&vals[..copy_len]);
            Self::real_fft_1d_f64(&x)
        } else {
            let mut re_buf = vec![0.0_f64; fft_len];
            let mut im_buf = vec![0.0_f64; fft_len];
            re_buf[..copy_len].copy_from_slice(&vals[..copy_len]);
            Self::dft_inplace_1d(&mut re_buf, &mut im_buf, false);
            (re_buf[..out_len].to_vec(), im_buf[..out_len].to_vec())
        };
        debug_assert_eq!(re_out.len(), out_len);
        if factor != 1.0 {
            for v in re_out.iter_mut().chain(im_out.iter_mut()) {
                *v *= factor;
            }
        }

        let output = DenseTensor::from_typed_storage(
            TensorMeta::from_shape(vec![out_len], DType::Complex128, Device::Cpu),
            TensorStorage::Complex128(Arc::new(
                re_out
                    .iter()
                    .zip(im_out.iter())
                    .map(|(&r, &i)| Complex128::new(r, i))
                    .collect(),
            )),
        )?;

        // Autograd (frankentorch-ng1hw): rfft of a real input keeps only the
        // first N/2+1 bins, but its adjoint is the SAME as fft's once grad_y is
        // zero-extended back to the full N bins (the unstored conjugate-symmetric
        // bins receive no cotangent). So grad_x = factor·N·Re(ifft(zero-extend(grad_y))),
        // restricted to the copied positions. Verified bit-matching torch for even
        // and odd N (no Hermitian bin-doubling needed for the forward adjoint).
        if requires_grad {
            self.tensor_tape
                .apply_complex_bridge(&[input], output, move |_ctx, grad_outputs| {
                    let g = grad_outputs[0];
                    let mut gre = vec![0.0_f64; fft_len];
                    let mut gim = vec![0.0_f64; fft_len];
                    for k in 0..out_len {
                        gre[k] = g[2 * k];
                        gim[k] = g[2 * k + 1];
                    }
                    Self::dft_inplace_1d(&mut gre, &mut gim, true);
                    let scale = factor * fft_len as f64;
                    let mut grad_x = vec![0.0_f64; input_len];
                    for j in 0..copy_len {
                        grad_x[j] = scale * gre[j];
                    }
                    Ok(vec![Some(grad_x)])
                })
        } else {
            Ok(self.tensor_tape.leaf_tensor(output, false))
        }
    }

    /// Compute the inverse of rfft.
    ///
    /// Equivalent to `torch.fft.irfft(input, n)`.
    /// Input is Complex128 of length `n/2+1`. Output is real of length `n`.
    pub fn tensor_irfft(
        &mut self,
        input: TensorNodeId,
        n: Option<usize>,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_irfft_norm(input, n, "backward")
    }

    /// `torch.fft.irfft(input, n=n, norm=norm)`. Inverse of rfft; the rescale
    /// uses the real output length N (= `n`, or `2*(freq_len-1)`): backward x1
    /// (the inverse already carries 1/N), forward xN, ortho x√N.
    pub fn tensor_irfft_norm(
        &mut self,
        input: TensorNodeId,
        n: Option<usize>,
        norm: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        let requires_grad = self.tensor_requires_grad(input)? && self.tensor_tape.is_grad_enabled();
        let dtype = self.tensor_dtype(input)?;

        if dtype != DType::Complex128 && dtype != DType::Complex64 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "irfft: input must be complex",
                },
            )));
        }
        // Read the complex storage directly into interleaved [re, im, ...] (NOT via
        // the now-differentiable tensor_view_as_real, which would record a stray
        // node). The custom adjoint is attached to `input` itself. frankentorch-ng1hw.
        let vals: Vec<f64> = match self.tensor_tape.tensor(input)?.typed_storage() {
            TensorStorage::Complex128(values) => values.iter().flat_map(|z| [z.re, z.im]).collect(),
            TensorStorage::Complex64(values) => values
                .iter()
                .flat_map(|z| [f64::from(z.re), f64::from(z.im)])
                .collect(),
            _ => unreachable!("dtype checked complex above"),
        };

        let freq_len = vals.len() / 2;
        let out_len = n.unwrap_or((freq_len - 1) * 2);

        let m = out_len / 2;
        // For even out_len with a full Hermitian half present, use the real-output
        // inverse FFT (an out_len/2-point complex IFFT + recombine) — HALF the work
        // of reconstructing the full spectrum and running a full out_len complex
        // IFFT. Matches it within ~ULP (validated by
        // irfft_1d_matches_full_complex_within_tolerance); torch's irfft is
        // likewise real-IFFT-based. Otherwise (odd out_len, or a zero-padded /
        // truncated spectrum) keep the full-complex reconstruction. frankentorch-hpo6.
        let mut result = if out_len >= 2 && out_len.is_multiple_of(2) && freq_len > m {
            let mut re_in = vec![0.0_f64; m + 1];
            let mut im_in = vec![0.0_f64; m + 1];
            for k in 0..=m {
                re_in[k] = vals[k * 2];
                im_in[k] = vals[k * 2 + 1];
            }
            Self::irfft_1d_f64(&re_in, &im_in, out_len)
        } else {
            // Reconstruct full spectrum using conjugate symmetry, then full IFFT.
            let mut re_full = vec![0.0; out_len];
            let mut im_full = vec![0.0; out_len];
            for k in 0..freq_len.min(out_len) {
                re_full[k] = vals[k * 2];
                im_full[k] = vals[k * 2 + 1];
            }
            // Mirror: X[N-k] = conj(X[k])
            for k in 1..freq_len.min(out_len) {
                let mirror = out_len - k;
                if mirror < out_len && mirror != k {
                    re_full[mirror] = vals[k * 2];
                    im_full[mirror] = -vals[k * 2 + 1];
                }
            }
            Self::dft_inplace_1d(&mut re_full, &mut im_full, true);
            // Real output: keep only the real part (imag ~0 by conjugate symmetry).
            re_full
        };

        let factor = Self::fft_norm_factor(norm, out_len, true)?;
        if factor != 1.0 {
            for v in result.iter_mut() {
                *v *= factor;
            }
        }

        let output = DenseTensor::from_storage(
            TensorMeta::from_shape(vec![out_len], DType::F64, Device::Cpu),
            result,
        )?;

        // Autograd (frankentorch-ng1hw): irfft maps an N/2+1-bin Hermitian spectrum
        // to a real length-N signal. Its adjoint (real grad_y -> complex grad_X) is
        // grad_X_k = c_k·factor·fft(grad_y)_k with c_k = 2 for interior bins and 1 for
        // DC (k=0) and, for even N, the Nyquist bin (k=N/2) — whose imaginary parts are
        // forced to zero (those bins are real in a Hermitian spectrum). The doubling
        // accounts for each interior bin standing in for its unstored conjugate twin.
        // fft(grad_y) is computed via the known-good inverse kernel:
        // fft(v) = N·conj(ifft(v)) for real v. Verified bit-matching torch (even+odd N).
        if requires_grad {
            self.tensor_tape
                .apply_complex_bridge(&[input], output, move |_ctx, grad_outputs| {
                    let gy = grad_outputs[0]; // real grad, length out_len (= N)
                    let mut pr = gy.to_vec();
                    let mut pi = vec![0.0_f64; out_len];
                    Self::dft_inplace_1d(&mut pr, &mut pi, true); // ifft(grad_y)
                    let mut grad_x = vec![0.0_f64; freq_len * 2];
                    for k in 0..freq_len.min(out_len) {
                        let is_dc = k == 0;
                        let is_nyq = out_len % 2 == 0 && k == out_len / 2;
                        let mult = if is_dc || is_nyq { 1.0 } else { 2.0 };
                        // fft(grad_y)_k = N·conj(ifft(grad_y))_k = N·(pr[k] - i·pi[k]).
                        // grad_X_k = c_k·factor·fft_k, c_k = mult/N -> the N cancels.
                        grad_x[2 * k] = factor * mult * pr[k];
                        grad_x[2 * k + 1] = if is_dc || is_nyq {
                            0.0
                        } else {
                            factor * mult * (-pi[k])
                        };
                    }
                    Ok(vec![Some(grad_x)])
                })
        } else {
            Ok(self.tensor_tape.leaf_tensor(output, false))
        }
    }

    /// Compute the 2-D Discrete Fourier Transform.
    ///
    /// Equivalent to `torch.fft.fft2(input)`.
    /// Applies FFT along the last two dimensions. Input shape must be at least 2-D.
    /// Output is Complex128.
    pub fn tensor_fft2(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        self.tensor_fft2_norm(input, "backward")
    }

    /// `torch.fft.fft2(input, norm=norm)`. The 2-D norm rescales by the TOTAL
    /// transformed size N = rows*cols (not per-dim): backward x1, forward
    /// x(1/N), ortho x(1/√N). Verified vs torch 2.12.
    pub fn tensor_fft2_norm(
        &mut self,
        input: TensorNodeId,
        norm: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        let requires_grad = self.tensor_requires_grad(input)? && self.tensor_tape.is_grad_enabled();
        let shape = self.tensor_shape(input)?;
        if shape.len() < 2 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "fft2: input must be at least 2-D",
                },
            )));
        }
        // Apply FFT along last dimension, then along second-to-last
        let ndim = shape.len();
        let vals = self.tensor_values(input)?;
        let rows = shape[ndim - 2];
        let cols = shape[ndim - 1];
        let batch_size: usize = shape[..ndim - 2].iter().product();
        let factor = Self::fft_norm_factor(norm, rows * cols, false)?;

        let mut re_out = vec![0.0_f64; batch_size * rows * cols];
        let mut im_out = vec![0.0_f64; batch_size * rows * cols];
        let plane = rows * cols;
        let parallel = batch_size * rows * cols >= PARALLEL_ELEMENTWISE_MIN;

        // FFT along columns (last dim) for each row. Every (b, r) row is a
        // contiguous `cols` block, so the per-row 1-D transform runs in place
        // across Rayon workers with no gather/scatter. Bit-for-bit identical to
        // the serial loop (independent rows, deterministic dft_inplace_1d).
        if parallel && batch_size * rows >= 2 {
            use rayon::prelude::*;
            re_out
                .par_chunks_mut(cols)
                .zip(im_out.par_chunks_mut(cols))
                .enumerate()
                .for_each(|(row, (re_row, im_row))| {
                    let start = row * cols;
                    re_row.copy_from_slice(&vals[start..start + cols]);
                    Self::dft_inplace_1d(re_row, im_row, false);
                });
        } else {
            for b in 0..batch_size {
                for r in 0..rows {
                    let start = b * rows * cols + r * cols;
                    let mut re_row: Vec<f64> = vals[start..start + cols].to_vec();
                    let mut im_row = vec![0.0_f64; cols];
                    Self::dft_inplace_1d(&mut re_row, &mut im_row, false);
                    re_out[start..start + cols].copy_from_slice(&re_row);
                    im_out[start..start + cols].copy_from_slice(&im_row);
                }
            }
        }

        // FFT along rows (second-to-last dim). Each batch plane is a contiguous
        // rows*cols block whose columns are independent; distribute the planes
        // across workers (each reuses one scratch column buffer). Bit-for-bit
        // identical to the serial loop.
        if parallel && batch_size >= 2 {
            use rayon::prelude::*;
            re_out
                .par_chunks_mut(plane)
                .zip(im_out.par_chunks_mut(plane))
                .for_each(|(re_b, im_b)| {
                    let mut re_col = vec![0.0_f64; rows];
                    let mut im_col = vec![0.0_f64; rows];
                    for c in 0..cols {
                        for r in 0..rows {
                            re_col[r] = re_b[r * cols + c];
                            im_col[r] = im_b[r * cols + c];
                        }
                        Self::dft_inplace_1d(&mut re_col, &mut im_col, false);
                        for r in 0..rows {
                            re_b[r * cols + c] = re_col[r];
                            im_b[r * cols + c] = im_col[r];
                        }
                    }
                });
        } else if parallel && rows >= 2 && cols >= 2 {
            // Single plane (batch_size == 1): the per-plane parallelism above gives
            // no concurrency, but the `cols` strided second-to-last-dim transforms
            // are mutually independent. Distribute them across workers — each gathers
            // its column into an owned scratch buffer, transforms it with the SAME
            // deterministic `dft_inplace_1d`, and returns it; the strided scatter
            // back (disjoint column indices) is serial. Bit-for-bit identical to the
            // serial loop. Closes the batch=1 fft2 column-phase serial tail
            // (frankentorch-kgs4.86).
            use rayon::prelude::*;
            let cols_out: Vec<(Vec<f64>, Vec<f64>)> = (0..cols)
                .into_par_iter()
                .map(|c| {
                    let mut re_col = vec![0.0_f64; rows];
                    let mut im_col = vec![0.0_f64; rows];
                    for r in 0..rows {
                        re_col[r] = re_out[r * cols + c];
                        im_col[r] = im_out[r * cols + c];
                    }
                    Self::dft_inplace_1d(&mut re_col, &mut im_col, false);
                    (re_col, im_col)
                })
                .collect();
            for (c, (re_col, im_col)) in cols_out.iter().enumerate() {
                for r in 0..rows {
                    re_out[r * cols + c] = re_col[r];
                    im_out[r * cols + c] = im_col[r];
                }
            }
        } else {
            for b in 0..batch_size {
                for c in 0..cols {
                    let mut re_col = vec![0.0_f64; rows];
                    let mut im_col = vec![0.0_f64; rows];
                    for r in 0..rows {
                        re_col[r] = re_out[b * rows * cols + r * cols + c];
                        im_col[r] = im_out[b * rows * cols + r * cols + c];
                    }
                    Self::dft_inplace_1d(&mut re_col, &mut im_col, false);
                    for r in 0..rows {
                        re_out[b * rows * cols + r * cols + c] = re_col[r];
                        im_out[b * rows * cols + r * cols + c] = im_col[r];
                    }
                }
            }
        }

        // Fold the `1/N`-style norm `factor` directly into the complex assembly
        // (one multiply per output, identical to the prior separate in-place scale
        // then `Complex128::new` — `r * factor` is the same IEEE product). For the
        // large planes that take the `parallel` path the assembly itself is the
        // remaining serial O(N) tail of the transform, so run it across workers;
        // `par_iter().zip().collect()` preserves index order, keeping it bit-for-bit
        // identical to the serial map. frankentorch-kgs4.86.
        let complex: Vec<Complex128> = if parallel {
            use rayon::prelude::*;
            re_out
                .par_iter()
                .zip(im_out.par_iter())
                .map(|(&r, &i)| Complex128::new(r * factor, i * factor))
                .collect()
        } else {
            re_out
                .iter()
                .zip(im_out.iter())
                .map(|(&r, &i)| Complex128::new(r * factor, i * factor))
                .collect()
        };
        let output = DenseTensor::from_typed_storage(
            TensorMeta::from_shape(shape.clone(), DType::Complex128, Device::Cpu),
            TensorStorage::Complex128(Arc::new(complex)),
        )?;

        // Autograd (frankentorch-ng1hw): fft2 of a real input is the separable 2-D
        // linear map y = factor·DFT2(x). For a real input the adjoint is
        // grad_x = factor·Re(unnormalized 2-D iDFT(grad_y)), computed per batch plane
        // by an inverse DFT along the last dim then the second-to-last (each
        // dft_inplace_1d(.., true) carries 1/len, so the two passes give the
        // 1/(rows·cols)-normalized ifft2; multiplying by rows·cols un-normalizes).
        // Verified bit-matching torch.
        if requires_grad {
            self.tensor_tape
                .apply_complex_bridge(&[input], output, move |_ctx, grad_outputs| {
                    let g = grad_outputs[0];
                    let scale = factor * (rows * cols) as f64;
                    let mut grad_x = vec![0.0_f64; batch_size * rows * cols];
                    for bp in 0..batch_size {
                        let base = bp * plane;
                        let mut re = vec![0.0_f64; plane];
                        let mut im = vec![0.0_f64; plane];
                        for idx in 0..plane {
                            re[idx] = g[2 * (base + idx)];
                            im[idx] = g[2 * (base + idx) + 1];
                        }
                        // Inverse DFT along the last dim (each row).
                        for r in 0..rows {
                            let s = r * cols;
                            Self::dft_inplace_1d(&mut re[s..s + cols], &mut im[s..s + cols], true);
                        }
                        // Inverse DFT along the second-to-last dim (each column).
                        let mut re_col = vec![0.0_f64; rows];
                        let mut im_col = vec![0.0_f64; rows];
                        for c in 0..cols {
                            for r in 0..rows {
                                re_col[r] = re[r * cols + c];
                                im_col[r] = im[r * cols + c];
                            }
                            Self::dft_inplace_1d(&mut re_col, &mut im_col, true);
                            for r in 0..rows {
                                re[r * cols + c] = re_col[r];
                                im[r * cols + c] = im_col[r];
                            }
                        }
                        for idx in 0..plane {
                            grad_x[base + idx] = scale * re[idx];
                        }
                    }
                    Ok(vec![Some(grad_x)])
                })
        } else {
            Ok(self.tensor_tape.leaf_tensor(output, false))
        }
    }

    /// Compute the 2-D Inverse Discrete Fourier Transform.
    ///
    /// Equivalent to `torch.fft.ifft2(input)`.
    /// Applies inverse FFT along the last two dimensions. Input must be Complex128.
    pub fn tensor_ifft2(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        self.tensor_ifft2_norm(input, "backward")
    }

    /// `torch.fft.ifft2(input, norm=norm)`. Inverse 2-D DFT; the rescale uses the
    /// total transformed size N = rows*cols: backward x1 (the inverse already
    /// carries 1/N), forward xN, ortho x√N. Verified vs torch 2.12.
    pub fn tensor_ifft2_norm(
        &mut self,
        input: TensorNodeId,
        norm: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        let requires_grad = self.tensor_requires_grad(input)? && self.tensor_tape.is_grad_enabled();
        let dtype = self.tensor_dtype(input)?;
        if dtype != DType::Complex128 && dtype != DType::Complex64 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "ifft2: input must be complex",
                },
            )));
        }

        let shape = self.tensor_shape(input)?;
        if shape.len() < 2 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "ifft2: input must be at least 2-D",
                },
            )));
        }

        let ndim = shape.len();
        let rows = shape[ndim - 2];
        let cols = shape[ndim - 1];
        let batch_size: usize = shape[..ndim - 2].iter().product();
        let factor = Self::fft_norm_factor(norm, rows * cols, true)?;
        let plane = rows * cols;
        let parallel = batch_size * rows * cols >= PARALLEL_ELEMENTWISE_MIN;
        let par_split = parallel;

        // Deinterleave the complex storage straight into split re/im planes — the
        // old path built an intermediate interleaved `vals` Vec and then a second
        // serial pass split it, two serial O(N) sweeps; collapse to one
        // index-order-preserving pass (parallel on large inputs) read directly
        // from the typed storage. frankentorch-ng1hw / kgs4.87.
        let (mut re_out, mut im_out): (Vec<f64>, Vec<f64>) =
            match self.tensor_tape.tensor(input)?.typed_storage() {
                TensorStorage::Complex128(values) => {
                    if par_split {
                        use rayon::prelude::*;
                        values.par_iter().map(|z| (z.re, z.im)).unzip()
                    } else {
                        values.iter().map(|z| (z.re, z.im)).unzip()
                    }
                }
                TensorStorage::Complex64(values) => {
                    if par_split {
                        use rayon::prelude::*;
                        values
                            .par_iter()
                            .map(|z| (f64::from(z.re), f64::from(z.im)))
                            .unzip()
                    } else {
                        values
                            .iter()
                            .map(|z| (f64::from(z.re), f64::from(z.im)))
                            .unzip()
                    }
                }
                _ => unreachable!("dtype checked complex above"),
            };

        // Inverse FFT along rows (second-to-last dim). Columns are strided, so
        // distribute the batch planes (each a contiguous rows*cols block) across
        // workers, each reusing one scratch column buffer. Bit-for-bit identical
        // to the serial loop (independent columns, deterministic dft_inplace_1d).
        if parallel && batch_size >= 2 {
            use rayon::prelude::*;
            re_out
                .par_chunks_mut(plane)
                .zip(im_out.par_chunks_mut(plane))
                .for_each(|(re_b, im_b)| {
                    let mut re_col = vec![0.0_f64; rows];
                    let mut im_col = vec![0.0_f64; rows];
                    for c in 0..cols {
                        for r in 0..rows {
                            re_col[r] = re_b[r * cols + c];
                            im_col[r] = im_b[r * cols + c];
                        }
                        Self::dft_inplace_1d(&mut re_col, &mut im_col, true);
                        for r in 0..rows {
                            re_b[r * cols + c] = re_col[r];
                            im_b[r * cols + c] = im_col[r];
                        }
                    }
                });
        } else if parallel && rows >= 2 && cols >= 2 {
            // Single plane (batch_size == 1): no per-plane concurrency, but the
            // `cols` strided second-to-last-dim inverse transforms are mutually
            // independent. Distribute them across workers (each gathers its column
            // into an owned buffer, runs the SAME deterministic inverse
            // dft_inplace_1d, returns it; disjoint strided scatter-back is serial).
            // Bit-for-bit identical to the serial loop. frankentorch-kgs4.87.
            use rayon::prelude::*;
            let cols_out: Vec<(Vec<f64>, Vec<f64>)> = (0..cols)
                .into_par_iter()
                .map(|c| {
                    let mut re_col = vec![0.0_f64; rows];
                    let mut im_col = vec![0.0_f64; rows];
                    for r in 0..rows {
                        re_col[r] = re_out[r * cols + c];
                        im_col[r] = im_out[r * cols + c];
                    }
                    Self::dft_inplace_1d(&mut re_col, &mut im_col, true);
                    (re_col, im_col)
                })
                .collect();
            for (c, (re_col, im_col)) in cols_out.iter().enumerate() {
                for r in 0..rows {
                    re_out[r * cols + c] = re_col[r];
                    im_out[r * cols + c] = im_col[r];
                }
            }
        } else {
            for b in 0..batch_size {
                for c in 0..cols {
                    let mut re_col = vec![0.0_f64; rows];
                    let mut im_col = vec![0.0_f64; rows];
                    for r in 0..rows {
                        re_col[r] = re_out[b * rows * cols + r * cols + c];
                        im_col[r] = im_out[b * rows * cols + r * cols + c];
                    }
                    Self::dft_inplace_1d(&mut re_col, &mut im_col, true);
                    for r in 0..rows {
                        re_out[b * rows * cols + r * cols + c] = re_col[r];
                        im_out[b * rows * cols + r * cols + c] = im_col[r];
                    }
                }
            }
        }

        // Inverse FFT along columns (last dim). Each (b, r) row is a contiguous
        // cols block, so the per-row transform runs in place across workers.
        if parallel && batch_size * rows >= 2 {
            use rayon::prelude::*;
            re_out
                .par_chunks_mut(cols)
                .zip(im_out.par_chunks_mut(cols))
                .for_each(|(re_row, im_row)| {
                    Self::dft_inplace_1d(re_row, im_row, true);
                });
        } else {
            for b in 0..batch_size {
                for r in 0..rows {
                    let start = b * rows * cols + r * cols;
                    let mut re_row: Vec<f64> = re_out[start..start + cols].to_vec();
                    let mut im_row: Vec<f64> = im_out[start..start + cols].to_vec();
                    Self::dft_inplace_1d(&mut re_row, &mut im_row, true);
                    re_out[start..start + cols].copy_from_slice(&re_row);
                    im_out[start..start + cols].copy_from_slice(&im_row);
                }
            }
        }

        // Fold the norm `factor` directly into the complex assembly (`r * factor`
        // is the same IEEE product as the prior separate in-place scale) and run
        // the assembly — the transform's remaining serial O(N) tail — across
        // workers on the `parallel` planes. par_iter().zip().collect() preserves
        // index order, so it stays bit-for-bit identical. frankentorch-kgs4.87.
        let complex: Vec<Complex128> = if parallel {
            use rayon::prelude::*;
            re_out
                .par_iter()
                .zip(im_out.par_iter())
                .map(|(&r, &i)| Complex128::new(r * factor, i * factor))
                .collect()
        } else {
            re_out
                .iter()
                .zip(im_out.iter())
                .map(|(&r, &i)| Complex128::new(r * factor, i * factor))
                .collect()
        };
        let output = DenseTensor::from_typed_storage(
            TensorMeta::from_shape(shape.clone(), DType::Complex128, Device::Cpu),
            TensorStorage::Complex128(Arc::new(complex)),
        )?;

        // Autograd (frankentorch-ng1hw): ifft2 is the separable 2-D map
        // y = factor_t·(1/(RC))·DFT2⁺(x). Its adjoint is
        // grad_x = (factor_t/(RC))·forwardDFT2(grad_y) = factor_t·conj(ifft2(conj(grad_y)))
        // (the inverse kernel carries 1/(RC), mirroring the 1-D ifft adjoint),
        // computed per batch plane. Verified bit-matching torch.
        if requires_grad {
            self.tensor_tape
                .apply_complex_bridge(&[input], output, move |_ctx, grad_outputs| {
                    let g = grad_outputs[0];
                    let mut grad_x = vec![0.0_f64; batch_size * plane * 2];
                    for bp in 0..batch_size {
                        let base = bp * plane;
                        // conj(grad_y): negate imaginary lanes.
                        let mut re = vec![0.0_f64; plane];
                        let mut im = vec![0.0_f64; plane];
                        for idx in 0..plane {
                            re[idx] = g[2 * (base + idx)];
                            im[idx] = -g[2 * (base + idx) + 1];
                        }
                        // ifft2(conj(grad_y)): inverse DFT along last dim then 2nd-last.
                        for r in 0..rows {
                            let s = r * cols;
                            Self::dft_inplace_1d(&mut re[s..s + cols], &mut im[s..s + cols], true);
                        }
                        let mut re_col = vec![0.0_f64; rows];
                        let mut im_col = vec![0.0_f64; rows];
                        for c in 0..cols {
                            for r in 0..rows {
                                re_col[r] = re[r * cols + c];
                                im_col[r] = im[r * cols + c];
                            }
                            Self::dft_inplace_1d(&mut re_col, &mut im_col, true);
                            for r in 0..rows {
                                re[r * cols + c] = re_col[r];
                                im[r * cols + c] = im_col[r];
                            }
                        }
                        // grad_x = factor·conj(result): conj negates imaginary lanes.
                        for idx in 0..plane {
                            grad_x[2 * (base + idx)] = factor * re[idx];
                            grad_x[2 * (base + idx) + 1] = factor * (-im[idx]);
                        }
                    }
                    Ok(vec![Some(grad_x)])
                })
        } else {
            Ok(self.tensor_tape.leaf_tensor(output, false))
        }
    }

    /// Compute the 2-D real FFT (non-redundant complex output).
    ///
    /// Equivalent to `torch.fft.rfft2(input)`.
    /// For real input of shape [..., H, W], outputs complex of shape [..., H, W/2+1].
    /// Tracked under frankentorch-ffpd.
    pub fn tensor_rfft2(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        self.tensor_rfft2_norm(input, "backward")
    }

    /// `torch.fft.rfft2(input, norm=norm)`. Rescales by the TOTAL transformed
    /// size N = rows*cols (the full last-dim length, not the n/2+1 output):
    /// backward x1, forward x(1/N), ortho x(1/√N). Verified vs torch 2.12.
    pub fn tensor_rfft2_norm(
        &mut self,
        input: TensorNodeId,
        norm: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        if self.tensor_requires_grad(input)? && self.tensor_tape.is_grad_enabled() {
            // Autograd (frankentorch-ng1hw): rfft2(x) is the non-redundant half of
            // fft2(x) for real input — bins 0..C/2+1 along the last dim. fft2,
            // real/imag, narrow, and complex are all differentiable, so compose the
            // grad path through them (narrowing the real/imag parts separately keeps
            // the gradient on real tensors, avoiding a complex-narrow path).
            let shape = self.tensor_shape(input)?;
            let ndim = shape.len();
            if ndim < 2 {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "rfft2: input must be at least 2-D",
                    },
                )));
            }
            let out_cols = shape[ndim - 1] / 2 + 1;
            let f = self.tensor_fft2_norm(input, norm)?;
            let re = self.tensor_real(f)?;
            let im = self.tensor_imag(f)?;
            let re_h = self.tensor_narrow(re, ndim - 1, 0, out_cols)?;
            let im_h = self.tensor_narrow(im, ndim - 1, 0, out_cols)?;
            return self.tensor_complex(re_h, im_h);
        }
        let shape = self.tensor_shape(input)?;
        if shape.len() < 2 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "rfft2: input must be at least 2-D",
                },
            )));
        }
        let ndim = shape.len();
        let vals = self.tensor_values(input)?;
        let rows = shape[ndim - 2];
        let cols = shape[ndim - 1];
        let factor = Self::fft_norm_factor(norm, rows * cols, false)?;
        let out_cols = cols / 2 + 1;
        let batch_size: usize = shape[..ndim - 2].iter().product();

        let parallel = batch_size * rows * cols >= PARALLEL_ELEMENTWISE_MIN;
        let red_plane = rows * out_cols;
        let mut re_out = vec![0.0_f64; batch_size * red_plane];
        let mut im_out = vec![0.0_f64; batch_size * red_plane];
        let total_rows = batch_size * rows;

        // Column (last-dim) transform. For an even `cols` the input row is real,
        // so use the real-input FFT directly: an n/2-point complex FFT + O(n)
        // recombine yields the onesided `out_cols` spectrum with HALF the
        // butterflies and no full-width intermediate. (Odd `cols` falls back to
        // the full complex FFT then trim.) Equals the dense path up to FFT
        // round-off (validated by `real_fft_1d_matches_full_complex_within_tolerance`).
        if cols.is_multiple_of(2) {
            if parallel && total_rows >= 2 {
                use rayon::prelude::*;
                re_out
                    .par_chunks_mut(out_cols)
                    .zip(im_out.par_chunks_mut(out_cols))
                    .enumerate()
                    .for_each(|(row, (ro, io))| {
                        let start = row * cols;
                        let (r, i) = Self::real_fft_1d_f64(&vals[start..start + cols]);
                        ro.copy_from_slice(&r);
                        io.copy_from_slice(&i);
                    });
            } else {
                for row in 0..total_rows {
                    let start = row * cols;
                    let (r, i) = Self::real_fft_1d_f64(&vals[start..start + cols]);
                    let dst = row * out_cols;
                    re_out[dst..dst + out_cols].copy_from_slice(&r);
                    im_out[dst..dst + out_cols].copy_from_slice(&i);
                }
            }
        } else {
            for row in 0..total_rows {
                let start = row * cols;
                let mut re_row: Vec<f64> = vals[start..start + cols].to_vec();
                let mut im_row = vec![0.0_f64; cols];
                Self::dft_inplace_1d(&mut re_row, &mut im_row, false);
                let dst = row * out_cols;
                re_out[dst..dst + out_cols].copy_from_slice(&re_row[..out_cols]);
                im_out[dst..dst + out_cols].copy_from_slice(&im_row[..out_cols]);
            }
        }

        // FFT along rows on the reduced [.., rows, out_cols] planes — strided
        // columns, distribute the batch planes (reused scratch per worker).
        if parallel && batch_size >= 2 {
            use rayon::prelude::*;
            re_out
                .par_chunks_mut(red_plane)
                .zip(im_out.par_chunks_mut(red_plane))
                .for_each(|(re_b, im_b)| {
                    let mut re_col = vec![0.0_f64; rows];
                    let mut im_col = vec![0.0_f64; rows];
                    for c in 0..out_cols {
                        for r in 0..rows {
                            re_col[r] = re_b[r * out_cols + c];
                            im_col[r] = im_b[r * out_cols + c];
                        }
                        Self::dft_inplace_1d(&mut re_col, &mut im_col, false);
                        for r in 0..rows {
                            re_b[r * out_cols + c] = re_col[r];
                            im_b[r * out_cols + c] = im_col[r];
                        }
                    }
                });
        } else if parallel && rows >= 2 && batch_size == 1 {
            // Single plane (batch==1): the `out_cols` row (second-to-last-dim) transforms are mutually
            // independent — distribute them across workers (each gathers its strided column into an
            // owned scratch, transforms with the SAME dft_inplace_1d, scatters back to disjoint column
            // indices). Bit-for-bit identical to the serial loop. Mirrors the fft2 single-plane
            // column-phase lever (kgs4.86); closes the batch=1 rfft2 row-phase serial tail.
            use rayon::prelude::*;
            let cols_out: Vec<(Vec<f64>, Vec<f64>)> = (0..out_cols)
                .into_par_iter()
                .map(|c| {
                    let mut re_col = vec![0.0_f64; rows];
                    let mut im_col = vec![0.0_f64; rows];
                    for r in 0..rows {
                        re_col[r] = re_out[r * out_cols + c];
                        im_col[r] = im_out[r * out_cols + c];
                    }
                    Self::dft_inplace_1d(&mut re_col, &mut im_col, false);
                    (re_col, im_col)
                })
                .collect();
            for (c, (re_col, im_col)) in cols_out.iter().enumerate() {
                for r in 0..rows {
                    re_out[r * out_cols + c] = re_col[r];
                    im_out[r * out_cols + c] = im_col[r];
                }
            }
        } else {
            for b in 0..batch_size {
                for c in 0..out_cols {
                    let mut re_col = vec![0.0_f64; rows];
                    let mut im_col = vec![0.0_f64; rows];
                    for r in 0..rows {
                        re_col[r] = re_out[b * red_plane + r * out_cols + c];
                        im_col[r] = im_out[b * red_plane + r * out_cols + c];
                    }
                    Self::dft_inplace_1d(&mut re_col, &mut im_col, false);
                    for r in 0..rows {
                        re_out[b * red_plane + r * out_cols + c] = re_col[r];
                        im_out[b * red_plane + r * out_cols + c] = im_col[r];
                    }
                }
            }
        }

        if factor != 1.0 {
            for v in re_out.iter_mut().chain(im_out.iter_mut()) {
                *v *= factor;
            }
        }
        let mut out_shape = shape[..ndim - 1].to_vec();
        out_shape.push(out_cols);
        let re_node = self.tensor_variable(re_out, out_shape.clone(), false)?;
        let im_node = self.tensor_variable(im_out, out_shape, false)?;
        self.tensor_complex(re_node, im_node)
    }

    /// Compute the inverse 2-D real FFT.
    ///
    /// Equivalent to `torch.fft.irfft2(input, s)`.
    /// Input is complex of shape [..., H, W/2+1]. Output is real of shape [..., H, W].
    /// If `s` is None, W is inferred as 2*(W/2+1 - 1) = original width.
    /// Tracked under frankentorch-ffpd.
    pub fn tensor_irfft2(
        &mut self,
        input: TensorNodeId,
        s: Option<(usize, usize)>,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_irfft2_norm(input, s, "backward")
    }

    /// `torch.fft.irfft2(input, s, norm=norm)`. Inverse 2-D real FFT; rescales
    /// by the real output size N = out_rows*out_cols: backward x1 (the inverse
    /// already carries 1/N), forward xN, ortho x√N.
    pub fn tensor_irfft2_norm(
        &mut self,
        input: TensorNodeId,
        s: Option<(usize, usize)>,
        norm: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        if self.tensor_requires_grad(input)? && self.tensor_tape.is_grad_enabled() {
            if s.is_some() {
                // The explicit-output-size path resizes via the non-autograd-aware
                // tensor_resize_with_pad_or_crop; fail loud rather than silent-drop.
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "irfft2: autograd with explicit output size (s=) not yet supported",
                    },
                )));
            }
            // Autograd (frankentorch-ng1hw): irfft2 over the last two dims is exactly
            // the 2-D case of the already-differentiable irfftn (last dim Hermitian,
            // second-to-last a full complex inverse). Delegate the grad path there.
            let ndim = self.tensor_shape(input)?.len();
            if ndim < 2 {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "irfft2: input must be at least 2-D",
                    },
                )));
            }
            let dims = [ndim - 2, ndim - 1];
            return self.tensor_irfftn_norm(input, None, Some(&dims), norm);
        }
        let dtype = self.tensor_dtype(input)?;
        if dtype != DType::Complex128 && dtype != DType::Complex64 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "irfft2: input must be complex",
                },
            )));
        }

        let shape = self.tensor_shape(input)?;
        if shape.len() < 2 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "irfft2: input must be at least 2-D",
                },
            )));
        }

        let real_view = self.tensor_view_as_real(input)?;
        let vals = self.tensor_values(real_view)?;

        let ndim = shape.len();
        let rows = shape[ndim - 2];
        let in_cols = shape[ndim - 1];
        let (out_rows, out_cols) = s.unwrap_or((rows, (in_cols - 1) * 2));
        let batch_size: usize = shape[..ndim - 2].iter().product();
        let factor = Self::fft_norm_factor(norm, out_rows * out_cols, true)?;

        let mut re_full = vec![0.0_f64; batch_size * out_rows * out_cols];
        let mut im_full = vec![0.0_f64; batch_size * out_rows * out_cols];

        // Reconstruct full spectrum using conjugate symmetry along last dim
        for b in 0..batch_size {
            for r in 0..rows.min(out_rows) {
                // Copy input frequencies
                for c in 0..in_cols.min(out_cols) {
                    let in_idx = (b * rows * in_cols + r * in_cols + c) * 2;
                    let out_idx = b * out_rows * out_cols + r * out_cols + c;
                    re_full[out_idx] = vals[in_idx];
                    im_full[out_idx] = vals[in_idx + 1];
                }
                // Mirror for remaining columns: X[N-k] = conj(X[k])
                for c in 1..in_cols.min(out_cols) {
                    let mirror = out_cols - c;
                    if mirror < out_cols && mirror >= in_cols {
                        let in_idx = (b * rows * in_cols + r * in_cols + c) * 2;
                        let out_idx = b * out_rows * out_cols + r * out_cols + mirror;
                        re_full[out_idx] = vals[in_idx];
                        im_full[out_idx] = -vals[in_idx + 1];
                    }
                }
            }
        }

        let plane = out_rows * out_cols;
        let parallel = batch_size * plane >= PARALLEL_ELEMENTWISE_MIN;

        // Inverse FFT along rows (second-to-last dim). Columns are strided, so
        // distribute the batch planes (each a contiguous out_rows*out_cols block)
        // across workers, each reusing one scratch column buffer. Bit-for-bit
        // identical to the serial loop.
        if parallel && batch_size >= 2 {
            use rayon::prelude::*;
            re_full
                .par_chunks_mut(plane)
                .zip(im_full.par_chunks_mut(plane))
                .for_each(|(re_b, im_b)| {
                    let mut re_col = vec![0.0_f64; out_rows];
                    let mut im_col = vec![0.0_f64; out_rows];
                    for c in 0..out_cols {
                        for r in 0..out_rows {
                            re_col[r] = re_b[r * out_cols + c];
                            im_col[r] = im_b[r * out_cols + c];
                        }
                        Self::dft_inplace_1d(&mut re_col, &mut im_col, true);
                        for r in 0..out_rows {
                            re_b[r * out_cols + c] = re_col[r];
                            im_b[r * out_cols + c] = im_col[r];
                        }
                    }
                });
        } else if parallel && out_rows >= 2 && batch_size == 1 {
            // Single plane (batch==1): the `out_cols` column (second-to-last-dim) inverse transforms
            // are independent — distribute across workers (gather strided column -> owned scratch ->
            // SAME dft_inplace_1d(inverse) -> scatter back to disjoint indices). Bit-for-bit identical
            // to the serial loop. Mirrors the rfft2/fft2 single-plane lever.
            use rayon::prelude::*;
            let cols_out: Vec<(Vec<f64>, Vec<f64>)> = (0..out_cols)
                .into_par_iter()
                .map(|c| {
                    let mut re_col = vec![0.0_f64; out_rows];
                    let mut im_col = vec![0.0_f64; out_rows];
                    for r in 0..out_rows {
                        re_col[r] = re_full[r * out_cols + c];
                        im_col[r] = im_full[r * out_cols + c];
                    }
                    Self::dft_inplace_1d(&mut re_col, &mut im_col, true);
                    (re_col, im_col)
                })
                .collect();
            for (c, (re_col, im_col)) in cols_out.iter().enumerate() {
                for r in 0..out_rows {
                    re_full[r * out_cols + c] = re_col[r];
                    im_full[r * out_cols + c] = im_col[r];
                }
            }
        } else {
            for b in 0..batch_size {
                for c in 0..out_cols {
                    let mut re_col = vec![0.0_f64; out_rows];
                    let mut im_col = vec![0.0_f64; out_rows];
                    for r in 0..out_rows {
                        re_col[r] = re_full[b * out_rows * out_cols + r * out_cols + c];
                        im_col[r] = im_full[b * out_rows * out_cols + r * out_cols + c];
                    }
                    Self::dft_inplace_1d(&mut re_col, &mut im_col, true);
                    for r in 0..out_rows {
                        re_full[b * out_rows * out_cols + r * out_cols + c] = re_col[r];
                        im_full[b * out_rows * out_cols + r * out_cols + c] = im_col[r];
                    }
                }
            }
        }

        // Inverse FFT along columns (last dim). Each (b, r) row is a contiguous
        // out_cols block; run the transform in place across workers (only the
        // real part is kept, so the discarded imaginary write is harmless).
        if parallel && batch_size * out_rows >= 2 {
            use rayon::prelude::*;
            re_full
                .par_chunks_mut(out_cols)
                .zip(im_full.par_chunks_mut(out_cols))
                .for_each(|(re_row, im_row)| {
                    Self::dft_inplace_1d(re_row, im_row, true);
                });
        } else {
            for b in 0..batch_size {
                for r in 0..out_rows {
                    let start = b * out_rows * out_cols + r * out_cols;
                    let mut re_row: Vec<f64> = re_full[start..start + out_cols].to_vec();
                    let mut im_row: Vec<f64> = im_full[start..start + out_cols].to_vec();
                    Self::dft_inplace_1d(&mut re_row, &mut im_row, true);
                    re_full[start..start + out_cols].copy_from_slice(&re_row);
                }
            }
        }

        if factor != 1.0 {
            for v in re_full.iter_mut() {
                *v *= factor;
            }
        }
        let mut out_shape = shape[..ndim - 2].to_vec();
        out_shape.push(out_rows);
        out_shape.push(out_cols);
        self.tensor_variable(re_full, out_shape, false)
    }

    /// Compute the N-dimensional Discrete Fourier Transform.
    ///
    /// Equivalent to `torch.fft.fftn(input, s, dim)`.
    /// If `dims` is None, transforms all dimensions. `s` can specify output sizes.
    pub fn tensor_fftn(
        &mut self,
        input: TensorNodeId,
        s: Option<&[usize]>,
        dims: Option<&[usize]>,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_fftn_norm(input, s, dims, "backward")
    }

    /// `torch.fft.fftn(input, s, dim, norm=norm)`. The N-D norm rescales by the
    /// product of the TRANSFORMED dim sizes N = prod(shape[d] for d in dims):
    /// backward x1, forward x(1/N), ortho x(1/√N). Verified vs torch 2.12 for
    /// the default `s=None` (the per-dim DFT lengths equal the input sizes).
    pub fn tensor_fftn_norm(
        &mut self,
        input: TensorNodeId,
        s: Option<&[usize]>,
        dims: Option<&[usize]>,
        norm: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        if self.tensor_requires_grad(input)? && s.is_some() {
            // fftn is differentiable via composition over tensor_fft_along_dim
            // (frankentorch-ng1hw), but the explicit-output-size (s=) resize path
            // goes through tensor_resize_with_pad_or_crop, which is not yet
            // autograd-aware — fail loud rather than silently drop the gradient.
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "fftn: autograd with explicit output size (s=) not yet supported",
                },
            )));
        }
        let shape = self.tensor_shape(input)?;
        let ndim = shape.len();
        let transform_dims: Vec<usize> = match dims {
            Some(d) => d.iter().copied().collect(),
            None => (0..ndim).collect(),
        };
        if transform_dims.is_empty() {
            let vals = self.tensor_values(input)?;
            let re_node = self.tensor_variable(vals.clone(), shape.clone(), false)?;
            let im_node = self.tensor_zeros(shape, false)?;
            return self.tensor_complex(re_node, im_node);
        }
        // N = product of the transformed dim sizes (validates dims in range too).
        let mut n_total: usize = 1;
        for &dim in &transform_dims {
            if dim >= ndim {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "fftn: dimension out of range",
                    },
                )));
            }
            n_total *= shape[dim];
        }
        let factor = Self::fft_norm_factor(norm, n_total, false)?;
        let mut current = input;
        for &dim in &transform_dims {
            current = self.tensor_fft_along_dim(current, dim, false)?;
        }
        if let Some(target_sizes) = s {
            let current_shape = self.tensor_shape(current)?;
            let mut new_shape = current_shape.clone();
            for (i, &target_sz) in target_sizes.iter().enumerate() {
                if i < transform_dims.len() {
                    new_shape[transform_dims[i]] = target_sz;
                }
            }
            if new_shape != current_shape {
                let re_view = self.tensor_real(current)?;
                let im_view = self.tensor_imag(current)?;
                let re_resized = self.tensor_resize_with_pad_or_crop(re_view, &new_shape)?;
                let im_resized = self.tensor_resize_with_pad_or_crop(im_view, &new_shape)?;
                current = self.tensor_complex(re_resized, im_resized)?;
            }
        }
        if factor != 1.0 {
            let re = self.tensor_real(current)?;
            let im = self.tensor_imag(current)?;
            let re_s = self.tensor_mul_scalar(re, factor)?;
            let im_s = self.tensor_mul_scalar(im, factor)?;
            current = self.tensor_complex(re_s, im_s)?;
        }
        Ok(current)
    }

    /// Compute the N-dimensional Inverse Discrete Fourier Transform.
    ///
    /// Equivalent to `torch.fft.ifftn(input, s, dim)`.
    /// If `dims` is None, transforms all dimensions.
    pub fn tensor_ifftn(
        &mut self,
        input: TensorNodeId,
        s: Option<&[usize]>,
        dims: Option<&[usize]>,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_ifftn_norm(input, s, dims, "backward")
    }

    /// `torch.fft.ifftn(input, s, dim, norm=norm)`. Inverse N-D DFT; the rescale
    /// uses the product of the transformed dim sizes N = prod(shape[d]):
    /// backward x1 (the inverse already carries 1/N), forward xN, ortho x√N.
    pub fn tensor_ifftn_norm(
        &mut self,
        input: TensorNodeId,
        s: Option<&[usize]>,
        dims: Option<&[usize]>,
        norm: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        if self.tensor_requires_grad(input)? && s.is_some() {
            // Differentiable via composition over tensor_fft_along_dim
            // (frankentorch-ng1hw); the s= resize path is not yet autograd-aware.
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "ifftn: autograd with explicit output size (s=) not yet supported",
                },
            )));
        }
        let dtype = self.tensor_dtype(input)?;
        if dtype != DType::Complex128 && dtype != DType::Complex64 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "ifftn: input must be complex",
                },
            )));
        }
        let shape = self.tensor_shape(input)?;
        let ndim = shape.len();
        let transform_dims: Vec<usize> = match dims {
            Some(d) => d.iter().copied().collect(),
            None => (0..ndim).collect(),
        };
        if transform_dims.is_empty() {
            return Ok(input);
        }
        let mut n_total: usize = 1;
        for &dim in &transform_dims {
            if dim >= ndim {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "ifftn: dimension out of range",
                    },
                )));
            }
            n_total *= shape[dim];
        }
        let factor = Self::fft_norm_factor(norm, n_total, true)?;
        let mut current = input;
        for &dim in &transform_dims {
            current = self.tensor_fft_along_dim(current, dim, true)?;
        }
        if let Some(target_sizes) = s {
            let current_shape = self.tensor_shape(current)?;
            let mut new_shape = current_shape.clone();
            for (i, &target_sz) in target_sizes.iter().enumerate() {
                if i < transform_dims.len() {
                    new_shape[transform_dims[i]] = target_sz;
                }
            }
            if new_shape != current_shape {
                let re_view = self.tensor_real(current)?;
                let im_view = self.tensor_imag(current)?;
                let re_resized = self.tensor_resize_with_pad_or_crop(re_view, &new_shape)?;
                let im_resized = self.tensor_resize_with_pad_or_crop(im_view, &new_shape)?;
                current = self.tensor_complex(re_resized, im_resized)?;
            }
        }
        if factor != 1.0 {
            let re = self.tensor_real(current)?;
            let im = self.tensor_imag(current)?;
            let re_s = self.tensor_mul_scalar(re, factor)?;
            let im_s = self.tensor_mul_scalar(im, factor)?;
            current = self.tensor_complex(re_s, im_s)?;
        }
        Ok(current)
    }

    /// Compute the N-dimensional real FFT.
    ///
    /// Equivalent to `torch.fft.rfftn(input, s, dim)`.
    /// Computes the FFT of real input, returning complex output with Hermitian symmetry.
    /// The last transformed dimension has size n//2+1.
    pub fn tensor_rfftn(
        &mut self,
        input: TensorNodeId,
        s: Option<&[usize]>,
        dims: Option<&[usize]>,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_rfftn_norm(input, s, dims, "backward")
    }

    /// `torch.fft.rfftn(input, s, dim, norm=norm)`. Same norm convention as
    /// fftn (N = product of transformed dim sizes); the half-spectrum narrow on
    /// the last dim does not affect the scaling. Delegates the rescale to
    /// [`Self::tensor_fftn_norm`].
    pub fn tensor_rfftn_norm(
        &mut self,
        input: TensorNodeId,
        s: Option<&[usize]>,
        dims: Option<&[usize]>,
        norm: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        if self.tensor_requires_grad(input)? && self.tensor_tape.is_grad_enabled() {
            // Autograd (frankentorch-ng1hw): rfftn(x) is the non-redundant half of
            // fftn(x) — the last transform dim truncated to L/2+1. fftn + real/imag/
            // narrow/complex are all differentiable, so compose the grad path through
            // them (same norm factor as fftn: product of the full transform-dim sizes).
            let shape = self.tensor_shape(input)?;
            let ndim = shape.len();
            let tdims: Vec<usize> = match dims {
                Some(d) => d.to_vec(),
                None => (0..ndim).collect(),
            };
            if s.is_some() || tdims.is_empty() || tdims.iter().any(|&d| d >= ndim) {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "rfftn: autograd with explicit output size (s=) / empty or out-of-range dims not yet supported",
                    },
                )));
            }
            let last_td = *tdims.last().unwrap();
            let half = shape[last_td] / 2 + 1;
            let f = self.tensor_fftn_norm(input, None, dims, norm)?;
            let re = self.tensor_real(f)?;
            let im = self.tensor_imag(f)?;
            let re_h = self.tensor_narrow(re, last_td, 0, half)?;
            let im_h = self.tensor_narrow(im, last_td, 0, half)?;
            return self.tensor_complex(re_h, im_h);
        }
        let shape = self.tensor_shape(input)?;
        let ndim = shape.len();
        let transform_dims: Vec<usize> = match dims {
            Some(d) => d.iter().copied().collect(),
            None => (0..ndim).collect(),
        };
        if transform_dims.is_empty() {
            let vals = self.tensor_values(input)?;
            let re_node = self.tensor_variable(vals, shape.clone(), false)?;
            let im_node = self.tensor_zeros(shape, false)?;
            return self.tensor_complex(re_node, im_node);
        }
        // Real-input fast path (mirrors rfft2's forward real-FFT). When the last
        // transformed dim is the contiguous last axis with an even length and no
        // resizing is requested, transform that dim with the real-input FFT (an
        // L/2-point complex FFT + O(L) recombine = HALF the butterflies, no full
        // intermediate). The remaining transformed dims then run their complex FFT
        // on the already-HALVED last dim, so they too do ~half the work — the same
        // win torch's rfftn gets from its real-FFT core. Equals the full-complex
        // path up to FFT round-off (validated by `rfftn_real_fast_path_matches_*`).
        // frankentorch-l9xod/no-gaps FFT vein.
        let last_dim = *transform_dims.last().unwrap();
        if s.is_none()
            && last_dim == ndim - 1
            && self.tensor_dtype(input)? == DType::F64
            && shape[ndim - 1] >= 2
            && shape[ndim - 1].is_multiple_of(2)
        {
            let l = shape[ndim - 1];
            let half = l / 2 + 1;
            let vals = self.tensor_values(input)?;
            let n_lines = vals.len() / l;
            let mut re_out = vec![0.0_f64; n_lines * half];
            let mut im_out = vec![0.0_f64; n_lines * half];
            let parallel = vals.len() >= PARALLEL_ELEMENTWISE_MIN && n_lines >= 2;
            if parallel {
                use rayon::prelude::*;
                re_out
                    .par_chunks_mut(half)
                    .zip(im_out.par_chunks_mut(half))
                    .enumerate()
                    .for_each(|(line, (ro, io))| {
                        let start = line * l;
                        let (r, i) = Self::real_fft_1d_f64(&vals[start..start + l]);
                        ro.copy_from_slice(&r);
                        io.copy_from_slice(&i);
                    });
            } else {
                for line in 0..n_lines {
                    let start = line * l;
                    let (r, i) = Self::real_fft_1d_f64(&vals[start..start + l]);
                    let dst = line * half;
                    re_out[dst..dst + half].copy_from_slice(&r);
                    im_out[dst..dst + half].copy_from_slice(&i);
                }
            }
            let mut half_shape = shape.clone();
            half_shape[ndim - 1] = half;
            let re_node = self.tensor_variable(re_out, half_shape.clone(), false)?;
            let im_node = self.tensor_variable(im_out, half_shape, false)?;
            let mut current = self.tensor_complex(re_node, im_node)?;
            // Complex FFT along the remaining transformed dims (last dim done above).
            for &dim in &transform_dims[..transform_dims.len() - 1] {
                current = self.tensor_fft_along_dim(current, dim, false)?;
            }
            // Normalization uses N = product of the FULL transformed dim sizes
            // (the last dim's FULL length L, not the halved spectrum), matching fftn.
            let mut n_total: usize = 1;
            for &dim in &transform_dims {
                n_total *= shape[dim];
            }
            let factor = Self::fft_norm_factor(norm, n_total, false)?;
            if factor != 1.0 {
                let re = self.tensor_real(current)?;
                let im = self.tensor_imag(current)?;
                let re_s = self.tensor_mul_scalar(re, factor)?;
                let im_s = self.tensor_mul_scalar(im, factor)?;
                current = self.tensor_complex(re_s, im_s)?;
            }
            return Ok(current);
        }
        let full_fft = self.tensor_fftn_norm(input, s, dims, norm)?;
        if let Some(&last_dim) = transform_dims.last() {
            let current_shape = self.tensor_shape(full_fft)?;
            let full_len = current_shape[last_dim];
            let half_len = full_len / 2 + 1;
            self.tensor_narrow(full_fft, last_dim, 0, half_len)
        } else {
            Ok(full_fft)
        }
    }

    /// Compute the N-dimensional inverse real FFT.
    ///
    /// Equivalent to `torch.fft.irfftn(input, s, dim)`.
    /// Computes the inverse FFT, returning real output.
    /// Input should be complex with Hermitian symmetry.
    pub fn tensor_irfftn(
        &mut self,
        input: TensorNodeId,
        s: Option<&[usize]>,
        dims: Option<&[usize]>,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_irfftn_norm(input, s, dims, "backward")
    }

    /// `torch.fft.irfftn(input, s, dim, norm=norm)`. The rescale uses the FULL
    /// (Hermitian-extended) transformed dim sizes — the inverse N-D DFT is run
    /// on the reconstructed full spectrum, so delegating to
    /// [`Self::tensor_ifftn_norm`] applies the correct N = prod(full sizes).
    pub fn tensor_irfftn_norm(
        &mut self,
        input: TensorNodeId,
        s: Option<&[usize]>,
        dims: Option<&[usize]>,
        norm: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        if self.tensor_requires_grad(input)? && s.is_some() {
            // Differentiable via composition (hermitian_extend + ifftn + real),
            // frankentorch-ng1hw; the explicit-output-size (s=) resize path is not
            // yet autograd-aware (fail loud rather than silently drop the gradient).
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "irfftn: autograd with explicit output size (s=) not yet supported",
                },
            )));
        }
        let dtype = self.tensor_dtype(input)?;
        if dtype != DType::Complex128 && dtype != DType::Complex64 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "irfftn: input must be complex",
                },
            )));
        }
        let shape = self.tensor_shape(input)?;
        let ndim = shape.len();
        let transform_dims: Vec<usize> = match dims {
            Some(d) => d.iter().copied().collect(),
            None => (0..ndim).collect(),
        };
        if transform_dims.is_empty() {
            return self.tensor_real(input);
        }
        let last_dim = *transform_dims.last().unwrap();
        let half_len = shape[last_dim];
        let full_len = match s {
            Some(sizes) if !sizes.is_empty() => sizes[sizes.len() - 1],
            _ => (half_len - 1) * 2,
        };
        let full_complex = self.tensor_hermitian_extend(input, last_dim, full_len)?;
        let ifft_result = self.tensor_ifftn_norm(full_complex, s, dims, norm)?;
        self.tensor_real(ifft_result)
    }

    /// Compute the Hermitian FFT (complex Hermitian input -> real output).
    ///
    /// Equivalent to `torch.fft.hfft(input, n)`.
    /// Input is complex of length n/2+1 representing a Hermitian-symmetric signal.
    /// Output is real of length n.
    /// Tracked under frankentorch-ffpd.
    pub fn tensor_hfft(
        &mut self,
        input: TensorNodeId,
        n: Option<usize>,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_hfft_norm(input, n, "backward")
    }

    /// `torch.fft.hfft(input, n=n, norm=norm)`. hfft is a FORWARD transform
    /// (Hermitian complex -> real of length n), so the rescale uses N = n:
    /// backward x1, forward x(1/N), ortho x(1/√N). Verified vs torch 2.12.
    pub fn tensor_hfft_norm(
        &mut self,
        input: TensorNodeId,
        n: Option<usize>,
        norm: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        if self.tensor_requires_grad(input)? && self.tensor_tape.is_grad_enabled() {
            // Autograd (frankentorch-ng1hw): hfft(x,n) = irfft(conj(x), n)·n for the
            // "backward" norm; other norms just rescale by factor_h. conj is
            // expressed as complex(real(x), -imag(x)), so the whole path composes
            // through differentiable ops (real/imag/mul_scalar/complex/irfft).
            let dtype = self.tensor_dtype(input)?;
            if dtype != DType::Complex128 && dtype != DType::Complex64 {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "hfft: input must be complex",
                    },
                )));
            }
            let shape = self.tensor_shape(input)?;
            let freq_len = *shape.last().unwrap();
            let out_len = n.unwrap_or((freq_len - 1) * 2);
            let factor_h = Self::fft_norm_factor(norm, out_len, false)?;
            let re = self.tensor_real(input)?;
            let im = self.tensor_imag(input)?;
            let neg_im = self.tensor_mul_scalar(im, -1.0)?;
            let conj_x = self.tensor_complex(re, neg_im)?;
            let ir = self.tensor_irfft_norm(conj_x, Some(out_len), "backward")?;
            return self.tensor_mul_scalar(ir, out_len as f64 * factor_h);
        }
        let dtype = self.tensor_dtype(input)?;
        if dtype != DType::Complex128 && dtype != DType::Complex64 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "hfft: input must be complex",
                },
            )));
        }

        let real_view = self.tensor_view_as_real(input)?;
        let vals = self.tensor_values(real_view)?;
        let freq_len = vals.len() / 2;
        let out_len = n.unwrap_or((freq_len - 1) * 2);
        let factor = Self::fft_norm_factor(norm, out_len, false)?;

        // Reconstruct full spectrum using conjugate symmetry, then FFT
        let mut re_full = vec![0.0; out_len];
        let mut im_full = vec![0.0; out_len];

        for k in 0..freq_len.min(out_len) {
            re_full[k] = vals[k * 2];
            im_full[k] = vals[k * 2 + 1];
        }
        for k in 1..freq_len.min(out_len) {
            let mirror = out_len - k;
            if mirror < out_len {
                re_full[mirror] = vals[k * 2];
                im_full[mirror] = -vals[k * 2 + 1];
            }
        }

        // Forward FFT (not inverse) to get real output
        Self::dft_inplace_1d(&mut re_full, &mut im_full, false);

        if factor != 1.0 {
            for v in re_full.iter_mut() {
                *v *= factor;
            }
        }
        self.tensor_variable(re_full, vec![out_len], false)
    }

    /// Compute the inverse Hermitian FFT (real input -> complex Hermitian output).
    ///
    /// Equivalent to `torch.fft.ihfft(input)`.
    /// Input is real of length n. Output is complex of length n/2+1.
    /// Tracked under frankentorch-ffpd.
    pub fn tensor_ihfft(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        self.tensor_ihfft_norm(input, "backward")
    }

    /// `torch.fft.ihfft(input, norm=norm)`. Inverse Hermitian FFT (real input of
    /// length n -> complex Hermitian of length n/2+1); the rescale uses N = n:
    /// backward x1 (the inverse already carries 1/N), forward xN, ortho x√N.
    pub fn tensor_ihfft_norm(
        &mut self,
        input: TensorNodeId,
        norm: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        if self.tensor_requires_grad(input)? && self.tensor_tape.is_grad_enabled() {
            // Autograd (frankentorch-ng1hw): ihfft(r) = conj(rfft(r))/N for the
            // "backward" norm; other norms rescale by factor_i. conj+scale is folded
            // into the real/imag parts: complex(real(c)·s, imag(c)·(-s)), s=factor_i/N,
            // c=rfft(r) — all differentiable real ops, no complex-scalar path.
            let shape = self.tensor_shape(input)?;
            let nn = *shape.last().unwrap();
            let factor_i = Self::fft_norm_factor(norm, nn, true)?;
            let s = factor_i / nn as f64;
            let c = self.tensor_rfft_norm(input, None, "backward")?;
            let re = self.tensor_real(c)?;
            let im = self.tensor_imag(c)?;
            let re_s = self.tensor_mul_scalar(re, s)?;
            let im_s = self.tensor_mul_scalar(im, -s)?;
            return self.tensor_complex(re_s, im_s);
        }

        let vals = self.tensor_values(input)?;
        let n = vals.len();
        let out_len = n / 2 + 1;
        let factor = Self::fft_norm_factor(norm, n, true)?;

        // Inverse FFT of real input
        let mut re_buf = vals;
        let mut im_buf = vec![0.0_f64; n];
        Self::dft_inplace_1d(&mut re_buf, &mut im_buf, true);

        // Keep only the first n/2+1 bins (Hermitian-symmetric)
        let mut re_out: Vec<f64> = re_buf[..out_len].to_vec();
        let mut im_out: Vec<f64> = im_buf[..out_len].to_vec();
        if factor != 1.0 {
            for v in re_out.iter_mut().chain(im_out.iter_mut()) {
                *v *= factor;
            }
        }

        let re_node = self.tensor_variable(re_out, vec![out_len], false)?;
        let im_node = self.tensor_variable(im_out, vec![out_len], false)?;
        self.tensor_complex(re_node, im_node)
    }

    /// Compute the 2-D Hermitian FFT.
    ///
    /// Equivalent to `torch.fft.hfft2(input, s)`.
    /// Input is complex with Hermitian symmetry; output is real.
    /// For complex input of shape [..., H, W/2+1], outputs real [..., H, out_W].
    /// If s is None, out_W = 2*(W/2+1 - 1).
    pub fn tensor_hfft2(
        &mut self,
        input: TensorNodeId,
        s: Option<(usize, usize)>,
    ) -> Result<TensorNodeId, AutogradError> {
        if self.tensor_requires_grad(input)? {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "hfft2: autograd not supported",
                },
            )));
        }
        let dtype = self.tensor_dtype(input)?;
        if dtype != DType::Complex128 && dtype != DType::Complex64 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "hfft2: input must be complex",
                },
            )));
        }
        let shape = self.tensor_shape(input)?;
        if shape.len() < 2 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "hfft2: input must be at least 2-D",
                },
            )));
        }

        let real_view = self.tensor_view_as_real(input)?;
        let vals = self.tensor_values(real_view)?;
        let ndim = shape.len();
        let rows = shape[ndim - 2];
        let in_cols = shape[ndim - 1];
        let (out_rows, out_cols) = s.unwrap_or((rows, (in_cols - 1) * 2));
        let batch_size: usize = shape[..ndim - 2].iter().product();

        let mut re_tmp = vec![0.0_f64; batch_size * out_rows * out_cols];
        let mut im_tmp = vec![0.0_f64; batch_size * out_rows * out_cols];

        // Reconstruct full spectrum with conjugate symmetry, then 2D FFT
        for b in 0..batch_size {
            for r in 0..rows.min(out_rows) {
                for c in 0..in_cols.min(out_cols) {
                    let in_idx = (b * rows * in_cols + r * in_cols + c) * 2;
                    let out_idx = b * out_rows * out_cols + r * out_cols + c;
                    re_tmp[out_idx] = vals[in_idx];
                    im_tmp[out_idx] = vals[in_idx + 1];
                }
                // Mirror for conjugate symmetry along last dimension
                for c in 1..in_cols.min(out_cols) {
                    let mirror = out_cols - c;
                    if mirror < out_cols && mirror >= in_cols {
                        let in_idx = (b * rows * in_cols + r * in_cols + c) * 2;
                        let out_idx = b * out_rows * out_cols + r * out_cols + mirror;
                        re_tmp[out_idx] = vals[in_idx];
                        im_tmp[out_idx] = -vals[in_idx + 1];
                    }
                }
            }
        }

        // FFT along columns (last dim)
        for b in 0..batch_size {
            for r in 0..out_rows {
                let start = b * out_rows * out_cols + r * out_cols;
                let mut re_row = re_tmp[start..start + out_cols].to_vec();
                let mut im_row = im_tmp[start..start + out_cols].to_vec();
                Self::dft_inplace_1d(&mut re_row, &mut im_row, false);
                re_tmp[start..start + out_cols].copy_from_slice(&re_row);
                im_tmp[start..start + out_cols].copy_from_slice(&im_row);
            }
        }

        // FFT along rows (second-to-last dim)
        for b in 0..batch_size {
            for c in 0..out_cols {
                let mut re_col = vec![0.0_f64; out_rows];
                let mut im_col = vec![0.0_f64; out_rows];
                for r in 0..out_rows {
                    re_col[r] = re_tmp[b * out_rows * out_cols + r * out_cols + c];
                    im_col[r] = im_tmp[b * out_rows * out_cols + r * out_cols + c];
                }
                Self::dft_inplace_1d(&mut re_col, &mut im_col, false);
                for r in 0..out_rows {
                    re_tmp[b * out_rows * out_cols + r * out_cols + c] = re_col[r];
                }
            }
        }

        let mut out_shape = shape[..ndim - 2].to_vec();
        out_shape.push(out_rows);
        out_shape.push(out_cols);
        self.tensor_variable(re_tmp, out_shape, false)
    }

    /// Compute the inverse 2-D Hermitian FFT.
    ///
    /// Equivalent to `torch.fft.ihfft2(input)`.
    /// Input is real; output is complex with Hermitian symmetry along last dim.
    /// For real input of shape [..., H, W], outputs complex [..., H, W/2+1].
    pub fn tensor_ihfft2(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        if self.tensor_requires_grad(input)? {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "ihfft2: autograd not supported",
                },
            )));
        }
        let shape = self.tensor_shape(input)?;
        if shape.len() < 2 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "ihfft2: input must be at least 2-D",
                },
            )));
        }

        let vals = self.tensor_values(input)?;
        let ndim = shape.len();
        let rows = shape[ndim - 2];
        let cols = shape[ndim - 1];
        let out_cols = cols / 2 + 1;
        let batch_size: usize = shape[..ndim - 2].iter().product();

        let mut re_tmp = vec![0.0_f64; batch_size * rows * cols];
        let mut im_tmp = vec![0.0_f64; batch_size * rows * cols];

        // Copy real input
        re_tmp.copy_from_slice(&vals);

        // Inverse FFT along rows (second-to-last dim)
        for b in 0..batch_size {
            for c in 0..cols {
                let mut re_col = vec![0.0_f64; rows];
                let mut im_col = vec![0.0_f64; rows];
                for r in 0..rows {
                    re_col[r] = re_tmp[b * rows * cols + r * cols + c];
                }
                Self::dft_inplace_1d(&mut re_col, &mut im_col, true);
                for r in 0..rows {
                    re_tmp[b * rows * cols + r * cols + c] = re_col[r];
                    im_tmp[b * rows * cols + r * cols + c] = im_col[r];
                }
            }
        }

        // Inverse FFT along columns (last dim)
        for b in 0..batch_size {
            for r in 0..rows {
                let start = b * rows * cols + r * cols;
                let mut re_row = re_tmp[start..start + cols].to_vec();
                let mut im_row = im_tmp[start..start + cols].to_vec();
                Self::dft_inplace_1d(&mut re_row, &mut im_row, true);
                re_tmp[start..start + cols].copy_from_slice(&re_row);
                im_tmp[start..start + cols].copy_from_slice(&im_row);
            }
        }

        // Keep only the first out_cols columns (Hermitian-symmetric)
        let mut re_out = Vec::with_capacity(batch_size * rows * out_cols);
        let mut im_out = Vec::with_capacity(batch_size * rows * out_cols);
        for b in 0..batch_size {
            for r in 0..rows {
                for c in 0..out_cols {
                    re_out.push(re_tmp[b * rows * cols + r * cols + c]);
                    im_out.push(im_tmp[b * rows * cols + r * cols + c]);
                }
            }
        }

        let mut out_shape = shape[..ndim - 1].to_vec();
        out_shape.push(out_cols);
        let re_node = self.tensor_variable(re_out, out_shape.clone(), false)?;
        let im_node = self.tensor_variable(im_out, out_shape, false)?;
        self.tensor_complex(re_node, im_node)
    }

    /// Compute the N-D Hermitian FFT.
    ///
    /// Equivalent to `torch.fft.hfftn(input, s, dim)`.
    /// Input is complex with Hermitian symmetry along the last dimension(s);
    /// output is real. For complex input [..., D1, D2/2+1], outputs real
    /// [..., D1, D2] (when dim is last 2 dims, or all dims if None).
    pub fn tensor_hfftn(
        &mut self,
        input: TensorNodeId,
        s: Option<Vec<usize>>,
        dim: Option<Vec<usize>>,
    ) -> Result<TensorNodeId, AutogradError> {
        if self.tensor_requires_grad(input)? {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "hfftn: autograd not supported",
                },
            )));
        }
        let dtype = self.tensor_dtype(input)?;
        if dtype != DType::Complex128 && dtype != DType::Complex64 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "hfftn: input must be complex",
                },
            )));
        }
        let shape = self.tensor_shape(input)?;
        let ndim = shape.len();

        let transform_dims: Vec<usize> = dim.unwrap_or_else(|| (0..ndim).collect());
        if transform_dims.is_empty() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "hfftn: must transform at least one dimension",
                },
            )));
        }

        // For 2D case, delegate to hfft2
        if transform_dims.len() == 2 && ndim >= 2 {
            let s_2d = s.map(|sizes| (sizes[0], sizes[1]));
            return self.tensor_hfft2(input, s_2d);
        }

        // For 1D case, delegate to hfft
        if transform_dims.len() == 1 {
            let n = s.and_then(|sizes| sizes.first().copied());
            return self.tensor_hfft(input, n);
        }

        // For >2D: apply hfft2 on last 2 dims, then fft on remaining
        let s_2d = s.as_ref().map(|sizes| {
            let len = sizes.len();
            (sizes[len.saturating_sub(2)], sizes[len - 1])
        });
        let intermediate = self.tensor_hfft2(input, s_2d)?;

        if transform_dims.len() > 2 {
            let mut result = intermediate;
            for _ in 0..transform_dims.len() - 2 {
                result = self.tensor_fft(result, None)?;
            }
            Ok(result)
        } else {
            Ok(intermediate)
        }
    }

    /// Compute the inverse N-D Hermitian FFT.
    ///
    /// Equivalent to `torch.fft.ihfftn(input, dim)`.
    /// Input is real; output is complex with Hermitian symmetry.
    /// For real input [..., D1, D2], outputs complex [..., D1, D2/2+1].
    pub fn tensor_ihfftn(
        &mut self,
        input: TensorNodeId,
        dim: Option<Vec<usize>>,
    ) -> Result<TensorNodeId, AutogradError> {
        if self.tensor_requires_grad(input)? {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "ihfftn: autograd not supported",
                },
            )));
        }
        let shape = self.tensor_shape(input)?;
        let ndim = shape.len();

        let transform_dims: Vec<usize> = dim.unwrap_or_else(|| (0..ndim).collect());
        if transform_dims.is_empty() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "ihfftn: must transform at least one dimension",
                },
            )));
        }

        // For 2D case, delegate to ihfft2
        if transform_dims.len() == 2 && ndim >= 2 {
            return self.tensor_ihfft2(input);
        }

        // For 1D case, delegate to ihfft
        if transform_dims.len() == 1 {
            return self.tensor_ihfft(input);
        }

        // For >2D: apply ifft on leading dims, then ihfft2
        if transform_dims.len() > 2 {
            let mut result = input;
            for _ in 0..transform_dims.len() - 2 {
                result = self.tensor_ifft(result, None)?;
            }
            self.tensor_ihfft2(result)
        } else {
            self.tensor_ihfft2(input)
        }
    }

    /// Shift the zero-frequency component to the center of the spectrum.
    ///
    /// Equivalent to `torch.fft.fftshift(input, dim)`. Rolls the tensor by
    /// n//2 along the specified dimension(s) to center the DC component.
    pub fn tensor_fftshift(
        &mut self,
        input: TensorNodeId,
        dim: Option<usize>,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        if let Some(d) = dim {
            if d >= shape.len() {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "fftshift: dim out of range",
                    },
                )));
            }
            let shift = (shape[d] / 2) as i64;
            self.tensor_roll(input, shift, d)
        } else {
            // Shift all dimensions sequentially
            let mut result = input;
            for (d, &dim_len) in shape.iter().enumerate() {
                let shift = (dim_len / 2) as i64;
                result = self.tensor_roll(result, shift, d)?;
            }
            Ok(result)
        }
    }

    /// Inverse of fftshift - shift zero-frequency back to the origin.
    ///
    /// Equivalent to `torch.fft.ifftshift(input, dim)`. Rolls the tensor by
    /// -(n//2) (or equivalently (n+1)//2) along the specified dimension(s).
    pub fn tensor_ifftshift(
        &mut self,
        input: TensorNodeId,
        dim: Option<usize>,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        if let Some(d) = dim {
            if d >= shape.len() {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "ifftshift: dim out of range",
                    },
                )));
            }
            let shift = -((shape[d] / 2) as i64);
            self.tensor_roll(input, shift, d)
        } else {
            let mut result = input;
            for (d, &dim_len) in shape.iter().enumerate() {
                let shift = -((dim_len / 2) as i64);
                result = self.tensor_roll(result, shift, d)?;
            }
            Ok(result)
        }
    }

    // ── logsumexp ────────────────────────────────────────────────────────
    /// Numerically stable log-sum-exp reduction along a dimension.
    ///
    /// Equivalent to `torch.logsumexp(input, dim)`.
    pub fn tensor_logsumexp(
        &mut self,
        input: TensorNodeId,
        dim: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let in_shape = self.tensor_shape(input)?;
        let ndim = in_shape.len();
        if dim >= ndim {
            // Surface the actual offending (dim, ndim) so the
            // caller can diagnose without reparsing static
            // strings (frankentorch-ovad).
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::InvalidDimension { dim, ndim },
            )));
        }

        // Wrap in tensor_apply_function with the analytical backward
        //     y = log(sum_d exp(x_d))
        //     grad_x_d = grad_y * exp(x_d - y)
        // The exp(x - y) factor is in [0, 1] (since y >= max(x) under
        // max-subtract), so the backward is numerically stable.
        // Save x and y for backward. Tracked under frankentorch-t1q4.
        let mut out_shape: Vec<usize> = in_shape.clone();
        out_shape.remove(dim);
        if out_shape.is_empty() {
            out_shape.push(1);
        }

        // No-grad f64 fast path: the tape path goes through apply_function_with_create_graph, which
        // (a) `save_for_backward(vals.to_vec())` CLONES the whole input (128MB at 4k×4k) and (b) runs
        // the per-lane reduction SERIALLY. With grad off, both are pure waste: each output lane
        // (outer,inner) is an INDEPENDENT logsumexp over `dim`, so borrow the input (no clone) and
        // fan the lanes across rayon — exp is compute-bound so it scales. Bit-identical to the serial
        // reduction (same max-pass then exp-sum-pass per lane, same +inf/-inf rule). f64 contiguous
        // only; grad / f32 / f16 / non-contiguous fall through to the autograd-aware tape path.
        if !self.tensor_requires_grad(input)? && self.tensor_dtype(input)? == DType::F64 {
            let built = {
                let t = self.tensor_tape.tensor(input)?;
                let shape = t.meta().shape();
                let outer_size =
                    Self::checked_shape_numel(&shape[..dim], "logsumexp: outer overflow")?;
                let dim_size = shape[dim];
                let inner_size =
                    Self::checked_shape_numel(&shape[dim + 1..], "logsumexp: inner overflow")?;
                let out_len =
                    Self::checked_mul(outer_size, inner_size, "logsumexp: output overflow")?;
                let numel = Self::checked_mul(out_len, dim_size, "logsumexp: numel overflow")?;
                if t.meta().is_contiguous() && out_len > 0 {
                    let vals = t.contiguous_values()?;
                    if vals.len() == numel {
                        let compute = |out: usize| -> f64 {
                            let outer = out / inner_size;
                            let inner = out % inner_size;
                            let base = outer * dim_size * inner_size + inner;
                            let mut max_val = f64::NEG_INFINITY;
                            for d in 0..dim_size {
                                let v = vals[base + d * inner_size];
                                if v > max_val {
                                    max_val = v;
                                }
                            }
                            if max_val.is_infinite() {
                                return max_val;
                            }
                            let mut sum_exp = 0.0_f64;
                            for d in 0..dim_size {
                                sum_exp += (vals[base + d * inner_size] - max_val).exp();
                            }
                            max_val + sum_exp.ln()
                        };
                        let mut result = vec![0.0_f64; out_len];
                        if numel >= PARALLEL_ELEMENTWISE_MIN && out_len > 1 {
                            use rayon::prelude::*;
                            result
                                .par_iter_mut()
                                .enumerate()
                                .for_each(|(out, r)| *r = compute(out));
                        } else {
                            for (out, r) in result.iter_mut().enumerate() {
                                *r = compute(out);
                            }
                        }
                        Some(result)
                    } else {
                        None
                    }
                } else {
                    None
                }
            };
            if let Some(result) = built {
                return self.tensor_variable(result, out_shape, false);
            }
        }

        // No-grad f32 fast path (sibling of the f64 one): f32 otherwise falls to the
        // apply_function_with_create_graph path that UPCASTS f32->f64 (128MB clone) + clones for
        // backward + serial reduction = ~8.6x SLOWER than torch. Read the f32 lane BORROWED and
        // compute the logsumexp in f64 (each `v as f64` is exact), narrow the result to f32 —
        // BIT-IDENTICAL to the current f32 behaviour (upcast-then-narrow), same max/exp/ln math.
        if !self.tensor_requires_grad(input)? && self.tensor_dtype(input)? == DType::F32 {
            let built = {
                let t = self.tensor_tape.tensor(input)?;
                let shape = t.meta().shape();
                let outer_size =
                    Self::checked_shape_numel(&shape[..dim], "logsumexp: outer overflow")?;
                let dim_size = shape[dim];
                let inner_size =
                    Self::checked_shape_numel(&shape[dim + 1..], "logsumexp: inner overflow")?;
                let out_len =
                    Self::checked_mul(outer_size, inner_size, "logsumexp: output overflow")?;
                let numel = Self::checked_mul(out_len, dim_size, "logsumexp: numel overflow")?;
                if t.meta().is_contiguous() && out_len > 0 {
                    let vals = t.contiguous_values_f32()?;
                    if vals.len() == numel {
                        let compute = |out: usize| -> f32 {
                            let outer = out / inner_size;
                            let inner = out % inner_size;
                            let base = outer * dim_size * inner_size + inner;
                            let mut max_val = f64::NEG_INFINITY;
                            for d in 0..dim_size {
                                let v = vals[base + d * inner_size] as f64;
                                if v > max_val {
                                    max_val = v;
                                }
                            }
                            if max_val.is_infinite() {
                                return max_val as f32;
                            }
                            let mut sum_exp = 0.0_f64;
                            for d in 0..dim_size {
                                sum_exp += (vals[base + d * inner_size] as f64 - max_val).exp();
                            }
                            (max_val + sum_exp.ln()) as f32
                        };
                        let mut result = vec![0.0_f32; out_len];
                        if numel >= PARALLEL_ELEMENTWISE_MIN && out_len > 1 {
                            use rayon::prelude::*;
                            result
                                .par_iter_mut()
                                .enumerate()
                                .for_each(|(out, r)| *r = compute(out));
                        } else {
                            for (out, r) in result.iter_mut().enumerate() {
                                *r = compute(out);
                            }
                        }
                        Some(result)
                    } else {
                        None
                    }
                } else {
                    None
                }
            };
            if let Some(result) = built {
                return self.tensor_variable_f32(result, out_shape, false);
            }
        }

        let out_shape_clone = out_shape.clone();
        self.tensor_apply_function_with_create_graph(
            &[input],
            move |ctx, inputs| {
                let (vals, shape) = inputs[0];
                let outer_size =
                    Self::checked_shape_numel(&shape[..dim], "logsumexp: outer overflow")?;
                let dim_size = shape[dim];
                let inner_size =
                    Self::checked_shape_numel(&shape[dim + 1..], "logsumexp: inner overflow")?;
                let out_len =
                    Self::checked_mul(outer_size, inner_size, "logsumexp: output overflow")?;
                let mut result = Vec::with_capacity(out_len);
                for outer in 0..outer_size {
                    for inner in 0..inner_size {
                        let mut max_val = f64::NEG_INFINITY;
                        for d in 0..dim_size {
                            let idx = outer * dim_size * inner_size + d * inner_size + inner;
                            if vals[idx] > max_val {
                                max_val = vals[idx];
                            }
                        }
                        // An infinite max (all -inf, or any +inf, or an empty dim)
                        // makes the max-shift `(x - ±inf).exp()` NaN. torch keeps the
                        // result at that infinity (all -inf -> -inf; any +inf -> +inf).
                        if max_val.is_infinite() {
                            result.push(max_val);
                            continue;
                        }
                        let mut sum_exp = 0.0_f64;
                        for d in 0..dim_size {
                            let idx = outer * dim_size * inner_size + d * inner_size + inner;
                            sum_exp += (vals[idx] - max_val).exp();
                        }
                        result.push(max_val + sum_exp.ln());
                    }
                }
                ctx.save_for_backward(vals.to_vec(), shape.to_vec());
                ctx.save_for_backward(result.clone(), out_shape_clone.clone());
                Ok((result, out_shape_clone.clone()))
            },
            move |ctx, grad_outputs| {
                let grad_y = grad_outputs[0];
                let saved = ctx.saved_tensors();
                let saved_shapes = ctx.saved_shapes();
                let x_vals = &saved[0];
                let y_vals = &saved[1];
                let in_shape = &saved_shapes[0];
                let outer_size = Self::checked_shape_numel(
                    &in_shape[..dim],
                    "logsumexp backward: outer overflow",
                )?;
                let dim_size = in_shape[dim];
                let inner_size = Self::checked_shape_numel(
                    &in_shape[dim + 1..],
                    "logsumexp backward: inner overflow",
                )?;
                let mut grad_x = vec![0.0_f64; x_vals.len()];
                let lane = dim_size * inner_size;
                // grad_x[idx] = g * exp(x[idx] - y) with (g,y) constant per (outer,inner)
                // lane and one exp per element = compute-bound. Lanes are independent
                // (reads absolute, writes lane-local), so fan the outer blocks over Rayon
                // bit-for-bit identically to the serial loop.
                let compute_lane = |outer: usize, out_chunk: &mut [f64]| {
                    let base = outer * lane;
                    for inner in 0..inner_size {
                        let y_idx = outer * inner_size + inner;
                        let y = y_vals[y_idx];
                        let g = grad_y[y_idx];
                        for d in 0..dim_size {
                            let local = d * inner_size + inner;
                            out_chunk[local] = g * (x_vals[base + local] - y).exp();
                        }
                    }
                };
                if x_vals.len() >= PARALLEL_ELEMENTWISE_MIN && outer_size >= 2 {
                    use rayon::prelude::*;
                    grad_x
                        .par_chunks_mut(lane)
                        .enumerate()
                        .for_each(|(outer, out_chunk)| compute_lane(outer, out_chunk));
                } else {
                    for outer in 0..outer_size {
                        let base = outer * lane;
                        compute_lane(outer, &mut grad_x[base..base + lane]);
                    }
                }
                Ok(vec![Some(grad_x)])
            },
            // create_graph backward: d/dx logsumexp(x, dim) = softmax(x, dim),
            // built from the differentiable tape softmax so the SECOND derivative
            // (Hessian = diag(p) - p pᵀ along dim) propagates instead of erroring.
            // grad_x = broadcast(grad_y over dim) ⊙ softmax(x, dim). frankentorch-t1q4.
            move |_ctx, grad_outs, inputs, tape| {
                let mode = ft_core::ExecutionMode::Strict;
                let in_shape = tape.tensor(inputs[0])?.meta().shape().to_vec();
                let sm = tape.softmax(inputs[0], dim, mode)?.0;
                // Re-insert the reduced axis as size 1, then broadcast grad_y back
                // over `dim` so it lines up element-wise with softmax.
                let mut keep_shape = in_shape.clone();
                keep_shape[dim] = 1;
                let gy = tape.reshape(grad_outs[0], keep_shape)?;
                let gy_b = tape.expand(gy, in_shape)?;
                let grad_in = tape.mul(gy_b, sm, mode)?.0;
                Ok(vec![Some(grad_in)])
            },
        )
    }

    /// Compute the p-norm distance between two tensors.
    ///
    /// Equivalent to `torch.dist(input, other, p)`.
    pub fn tensor_dist(
        &mut self,
        a: TensorNodeId,
        b: TensorNodeId,
        p: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let diff = self.tensor_sub(a, b)?;
        self.tensor_norm(diff, p)
    }

    /// Move a dimension from `source` to `destination`.
    ///
    /// Equivalent to `torch.movedim(input, source, destination)`.
    pub fn tensor_movedim(
        &mut self,
        input: TensorNodeId,
        source: usize,
        destination: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let ndim = self.tensor_shape(input)?.len();
        if source >= ndim || destination >= ndim {
            // Surface whichever offender fired (source first
            // since it's listed first in the predicate);
            // frankentorch-ovad.
            let dim = if source >= ndim { source } else { destination };
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::InvalidDimension { dim, ndim },
            )));
        }
        if source == destination {
            return Ok(input);
        }
        let mut perm: Vec<usize> = (0..ndim).collect();
        perm.remove(source);
        perm.insert(destination, source);
        self.tensor_permute(input, perm)
    }

    /// Alias for `tensor_movedim`. Equivalent to `torch.moveaxis`.
    pub fn tensor_moveaxis(
        &mut self,
        input: TensorNodeId,
        source: usize,
        destination: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_movedim(input, source, destination)
    }

    /// `torch.movedim(input, source, destination)` moving MULTIPLE dims at once.
    ///
    /// `source` and `destination` are equal-length lists of distinct dims
    /// (negatives count from the end). Each `source[i]` dim is placed at output
    /// position `destination[i]`; the dims not named in `source` fill the
    /// remaining output positions in their original relative order. This is a
    /// pure permutation, so it is bit-exact and autograd-aware.
    pub fn tensor_movedim_multi(
        &mut self,
        input: TensorNodeId,
        source: &[i64],
        destination: &[i64],
    ) -> Result<TensorNodeId, AutogradError> {
        let ndim = self.tensor_shape(input)?.len();
        if source.len() != destination.len() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "movedim: source and destination must have the same length",
                },
            )));
        }
        // Resolve negatives, range-check, and reject duplicates within a list.
        let resolve = |dims: &[i64]| -> Result<Vec<usize>, AutogradError> {
            let mut out: Vec<usize> = Vec::with_capacity(dims.len());
            for &d in dims {
                let r = if d < 0 { d + ndim as i64 } else { d };
                if r < 0 || r as usize >= ndim {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "movedim: dim out of range",
                        },
                    )));
                }
                let u = r as usize;
                if out.contains(&u) {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "movedim: repeated dim in source or destination",
                        },
                    )));
                }
                out.push(u);
            }
            Ok(out)
        };
        let src = resolve(source)?;
        let dst = resolve(destination)?;

        // order[i] = which input dim ends up at output position i.
        let mut order: Vec<Option<usize>> = vec![None; ndim];
        for (&s, &d) in src.iter().zip(dst.iter()) {
            order[d] = Some(s);
        }
        // Remaining (un-moved) input dims fill the empty slots in original order.
        let mut remaining = (0..ndim).filter(|i| !src.contains(i));
        let mut perm: Vec<usize> = Vec::with_capacity(ndim);
        for slot in order {
            match slot {
                Some(s) => perm.push(s),
                None => perm.push(remaining.next().expect("slot count matches remaining dims")),
            }
        }
        self.tensor_permute(input, perm)
    }

    /// Alias for [`Self::tensor_movedim_multi`]. Equivalent to multi-axis
    /// `torch.moveaxis`.
    pub fn tensor_moveaxis_multi(
        &mut self,
        input: TensorNodeId,
        source: &[i64],
        destination: &[i64],
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_movedim_multi(input, source, destination)
    }

    /// Compute both min and max along a dimension. Returns `(min, max)`.
    ///
    /// Equivalent to `torch.aminmax(input, dim)`.
    pub fn tensor_aminmax(
        &mut self,
        input: TensorNodeId,
        dim: usize,
    ) -> Result<(TensorNodeId, TensorNodeId), AutogradError> {
        // Compose through tensor_min_dim + tensor_max_dim so gradients
        // flow through both branches via argmin/argmax routing.
        // Tracked under frankentorch-b0y1 — previously this body
        // extracted values, computed mins/maxs in plain f64, and
        // rebuilt non-grad leaves, silently severing autograd.
        // tensor_min_dim / tensor_max_dim already implement the
        // proper backward via the tape; discard the indices since
        // aminmax doesn't return them.
        let shape = self.tensor_shape(input)?;
        if dim >= shape.len() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "aminmax: dimension out of range",
                },
            )));
        }
        // No-grad fast path: the compose below runs tensor_min_dim AND tensor_max_dim — TWO full
        // dim-reductions that ALSO compute argmin/argmax indices (which aminmax discards) =
        // measured ~32x SLOWER than torch (which fuses min+max in ONE index-free pass). Scan each
        // output lane ONCE tracking both min and max, parallel over lanes. Bit-exact: min/max are
        // the exact extrema; any-NaN -> NaN propagation matches torch.min/max. f32/f64 contiguous
        // no-grad only; grad / non-contiguous fall through to the autograd-aware compose.
        let amm_dtype = self.tensor_dtype(input)?;
        if !self.tensor_requires_grad(input)? && matches!(amm_dtype, DType::F64 | DType::F32) {
            let outer: usize = shape[..dim].iter().product();
            let dim_size = shape[dim];
            let inner: usize = shape[dim + 1..].iter().product();
            let out_numel = outer * inner;
            if dim_size > 0 && out_numel > 0 {
                let mut out_shape = shape.clone();
                out_shape.remove(dim);
                let mut built_f64: Option<(Vec<f64>, Vec<f64>)> = None;
                let mut built_f32: Option<(Vec<f32>, Vec<f32>)> = None;
                {
                    let t = self.tensor_tape.tensor(input)?;
                    if t.meta().is_contiguous() {
                        use rayon::prelude::*;
                        macro_rules! amm {
                            ($read:ident, $ty:ty, $inf:expr, $ninf:expr, $nan:expr) => {{
                                let data = t.$read()?;
                                // (min, max) per output lane o = (outer_idx*inner + inner_idx).
                                let pairs: Vec<($ty, $ty)> = (0..out_numel)
                                    .into_par_iter()
                                    .map(|o| {
                                        let outer_idx = o / inner;
                                        let inner_idx = o % inner;
                                        let base = outer_idx * dim_size * inner + inner_idx;
                                        let mut mn: $ty = $inf;
                                        let mut mx: $ty = $ninf;
                                        let mut nan = false;
                                        for d in 0..dim_size {
                                            let v = data[base + d * inner];
                                            if v.is_nan() {
                                                nan = true;
                                            } else {
                                                if v < mn {
                                                    mn = v;
                                                }
                                                if v > mx {
                                                    mx = v;
                                                }
                                            }
                                        }
                                        if nan { ($nan, $nan) } else { (mn, mx) }
                                    })
                                    .collect();
                                let mut mins: Vec<$ty> = Vec::with_capacity(out_numel);
                                let mut maxs: Vec<$ty> = Vec::with_capacity(out_numel);
                                for (mn, mx) in pairs {
                                    mins.push(mn);
                                    maxs.push(mx);
                                }
                                (mins, maxs)
                            }};
                        }
                        match amm_dtype {
                            DType::F64 => {
                                built_f64 = Some(amm!(
                                    contiguous_values,
                                    f64,
                                    f64::INFINITY,
                                    f64::NEG_INFINITY,
                                    f64::NAN
                                ))
                            }
                            DType::F32 => {
                                built_f32 = Some(amm!(
                                    contiguous_values_f32,
                                    f32,
                                    f32::INFINITY,
                                    f32::NEG_INFINITY,
                                    f32::NAN
                                ))
                            }
                            _ => {}
                        }
                    }
                }
                if let Some((mins, maxs)) = built_f64 {
                    let min_t = self.tensor_variable(mins, out_shape.clone(), false)?;
                    let max_t = self.tensor_variable(maxs, out_shape, false)?;
                    return Ok((min_t, max_t));
                }
                if let Some((mins, maxs)) = built_f32 {
                    let min_t = self.tensor_variable_f32(mins, out_shape.clone(), false)?;
                    let max_t = self.tensor_variable_f32(maxs, out_shape, false)?;
                    return Ok((min_t, max_t));
                }
            }
        }
        let (min_out, _argmin) = self.tensor_min_dim(input, dim)?;
        let (max_out, _argmax) = self.tensor_max_dim(input, dim)?;
        Ok((min_out, max_out))
    }

    /// Extract sliding windows from a tensor along a dimension.
    ///
    /// Equivalent to `torch.Tensor.unfold(dimension, size, step)`.
    pub fn tensor_unfold(
        &mut self,
        input: TensorNodeId,
        dimension: usize,
        size: usize,
        step: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        let ndim = shape.len();
        if dimension >= ndim || size == 0 || size > shape[dimension] || step == 0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "unfold: invalid dimension, size, or step",
                },
            )));
        }
        // Pre-compute the (flat_out -> in_flat) gather table; both
        // the forward and backward closures use the same mapping.
        // The forward gathers vals[in_flat] into result[flat_out];
        // the backward scatters grad_output[flat_out] into
        // grad_input[in_flat] (accumulating overlaps from
        // step < size).
        // Tracked under frankentorch-hc18.
        let n_windows = (shape[dimension] - size) / step + 1;
        let mut strides = vec![1usize; ndim];
        for d in (0..ndim - 1).rev() {
            strides[d] =
                Self::checked_mul(strides[d + 1], shape[d + 1], "unfold: stride overflow")?;
        }
        let mut out_shape = shape.clone();
        out_shape[dimension] = n_windows;
        out_shape.push(size);
        let out_ndim = out_shape.len();
        let mut out_strides = vec![1usize; out_ndim];
        for d in (0..out_ndim - 1).rev() {
            out_strides[d] = Self::checked_mul(
                out_strides[d + 1],
                out_shape[d + 1],
                "unfold: output stride overflow",
            )?;
        }
        let out_numel = Self::checked_shape_numel(&out_shape, "unfold: output shape overflow")?;
        let in_numel = Self::checked_shape_numel(&shape, "unfold: input shape overflow")?;

        if dimension + 1 == ndim
            && self.tensor_dtype(input)? == DType::F64
            && !self.tensor_tape.tensor_requires_grad(input)?
        {
            let row_len = shape[dimension];
            let row_out_len =
                Self::checked_mul(n_windows, size, "unfold: row output length overflow")?;
            let vals = self.tensor_tape.values_borrowed(input)?;
            let mut result = vec![0.0_f64; out_numel];
            if out_numel >= PARALLEL_ELEMENTWISE_MIN {
                use rayon::prelude::*;
                result
                    .par_chunks_mut(row_out_len)
                    .enumerate()
                    .for_each(|(row, out_row)| {
                        let row_start = row * row_len;
                        let row_vals = &vals[row_start..row_start + row_len];
                        for w in 0..n_windows {
                            let src = w * step;
                            let dst = w * size;
                            out_row[dst..dst + size].copy_from_slice(&row_vals[src..src + size]);
                        }
                    });
            } else {
                for (row, out_row) in result.chunks_mut(row_out_len).enumerate() {
                    let row_start = row * row_len;
                    let row_vals = &vals[row_start..row_start + row_len];
                    for w in 0..n_windows {
                        let src = w * step;
                        let dst = w * size;
                        out_row[dst..dst + size].copy_from_slice(&row_vals[src..src + size]);
                    }
                }
            }
            return self.tensor_variable(result, out_shape, false);
        }

        // f32 mirror of the F64 last-dim fast path (asymmetric-dtype): the F64 branch above
        // borrows the storage + block-copies windows, but f32 fell through to the gather-table +
        // apply_function path below, which UPCASTS the whole input f32->f64 and does a random
        // gather. Borrow the f32 storage zero-copy and block-copy the contiguous windows directly
        // — bit-identical (pure movement), correct F32 dtype, no upcast/gather/tape.
        if dimension + 1 == ndim
            && self.tensor_dtype(input)? == DType::F32
            && !self.tensor_tape.tensor_requires_grad(input)?
            && self.tensor_tape.tensor(input)?.meta().is_contiguous()
        {
            let row_len = shape[dimension];
            let row_out_len =
                Self::checked_mul(n_windows, size, "unfold: row output length overflow")?;
            let vals = self.tensor_tape.tensor(input)?.contiguous_values_f32()?;
            let mut result = vec![0.0_f32; out_numel];
            let fill = |row: usize, out_row: &mut [f32]| {
                let row_start = row * row_len;
                let row_vals = &vals[row_start..row_start + row_len];
                for w in 0..n_windows {
                    let src = w * step;
                    let dst = w * size;
                    out_row[dst..dst + size].copy_from_slice(&row_vals[src..src + size]);
                }
            };
            if out_numel >= PARALLEL_ELEMENTWISE_MIN {
                use rayon::prelude::*;
                result
                    .par_chunks_mut(row_out_len)
                    .enumerate()
                    .for_each(|(row, out_row)| fill(row, out_row));
            } else {
                result
                    .chunks_mut(row_out_len)
                    .enumerate()
                    .for_each(|(row, out_row)| fill(row, out_row));
            }
            return self.tensor_variable_f32(result, out_shape, false);
        }

        // Build the gather table once.
        let mut gather: Vec<usize> = Vec::with_capacity(out_numel);
        let mut coords = vec![0usize; out_ndim];
        for flat_out in 0..out_numel {
            let mut in_flat = 0;
            for d in 0..ndim {
                let c = if d == dimension {
                    coords[dimension] * step + coords[out_ndim - 1]
                } else {
                    coords[d]
                };
                in_flat += c * strides[d];
            }
            gather.push(in_flat);
            if flat_out + 1 < out_numel {
                for d in (0..out_ndim).rev() {
                    coords[d] += 1;
                    if coords[d] < out_shape[d] {
                        break;
                    }
                    coords[d] = 0;
                }
            }
        }
        let gather: Arc<[usize]> = gather.into();
        let gather_for_fwd = Arc::clone(&gather);
        let gather_for_bwd = gather;
        let out_shape_clone = out_shape.clone();

        self.tensor_apply_function(
            &[input],
            move |_ctx, inputs| {
                let (vals, _shape) = inputs[0];
                let result: Vec<f64> = gather_for_fwd.iter().map(|&k| vals[k]).collect();
                Ok((result, out_shape_clone.clone()))
            },
            move |_ctx, grad_outputs| {
                let g = grad_outputs[0];
                let mut grad_in = vec![0.0_f64; in_numel];
                for (flat_out, &in_flat) in gather_for_bwd.iter().enumerate() {
                    grad_in[in_flat] += g[flat_out];
                }
                Ok(vec![Some(grad_in)])
            },
        )
    }

    /// Return a copy of the unfolded tensor.
    ///
    /// Equivalent to `torch.Tensor.unfold_copy()`. Since ft-api always
    /// creates copies (no views), this is identical to `tensor_unfold`.
    pub fn tensor_unfold_copy(
        &mut self,
        input: TensorNodeId,
        dimension: usize,
        size: usize,
        step: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_unfold(input, dimension, size, step)
    }

    /// Renormalize sub-tensors so their p-norm <= maxnorm.
    ///
    /// Equivalent to `torch.renorm(input, p, dim, maxnorm)`.
    pub fn tensor_renorm(
        &mut self,
        input: TensorNodeId,
        p: f64,
        dim: usize,
        maxnorm: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        if !p.is_finite() || p <= 0.0 || !maxnorm.is_finite() || maxnorm <= 0.0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "renorm: p and maxnorm must be finite and > 0",
                },
            )));
        }
        let n = shape.len();
        if dim >= n {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "renorm: dimension out of range",
                },
            )));
        }

        // Compose through autograd primitives. The closed-form scale
        // per slice is
        //     scale_d = maxnorm / max(norm_d, maxnorm)
        // which equals 1 when norm_d <= maxnorm and maxnorm/norm_d
        // otherwise. Tracked under frankentorch-go4q. Previously this
        // body extracted values, conditionally scaled in plain f64,
        // and rebuilt a non-grad leaf — silently severing autograd
        // through embedding-regularization paths
        // (torch.nn.Embedding(max_norm=...)).
        //
        // Strategy: permute `dim` to position 0, reshape to
        // [dim_size, other_size], compute per-row L_p norm, scale
        // each row, then reshape + permute back.
        let total = Self::checked_shape_numel(&shape, "renorm: shape volume overflow")?;
        let dim_size = shape[dim];
        let other_size = total / dim_size;

        // No-grad f64 dim==0 fast path: each dim-0 slice is a CONTIGUOUS block of `other_size`
        // elements, so compute its L_p norm + conditional scale in ONE parallel pass instead of
        // composing ~10 autograd primitives (~10 numel passes; measured 2.40x slower than PyTorch).
        // Same math as the composed path (|x|^p sum, norm=sum^(1/p), scale=maxnorm/(norm+1e-7) when
        // norm>maxnorm else 1). frankentorch-renorm-fused.
        if dim == 0
            && self.tensor_dtype(input)? == DType::F64
            && !self.tensor_requires_grad(input)?
            && self.tensor_tape.tensor(input)?.meta().is_contiguous()
            && other_size > 0
        {
            use rayon::prelude::*;
            let mut out = self.tensor_values(input)?;
            out.par_chunks_mut(other_size).for_each(|slice| {
                let mut acc = 0.0_f64;
                for &x in slice.iter() {
                    acc += x.abs().powf(p);
                }
                let norm = acc.powf(1.0 / p);
                if norm > maxnorm {
                    let scale = maxnorm / (norm + 1e-7);
                    for x in slice.iter_mut() {
                        *x *= scale;
                    }
                }
            });
            return self.tensor_variable(out, shape, false);
        }

        // Same lever for f32 (the asymmetric-dtype gap): f64 dim==0 is fused above but f32 fell
        // through to the ~10-op compose (measured 9.6x SLOWER than torch). Mirror it: per dim-0
        // contiguous slice compute the L_p norm in f64 (accuracy, same as the f64 path) and scale
        // the f32 slice in place. frankentorch-specf32.
        if dim == 0
            && self.tensor_dtype(input)? == DType::F32
            && !self.tensor_requires_grad(input)?
            && self.tensor_tape.tensor(input)?.meta().is_contiguous()
            && other_size > 0
        {
            use rayon::prelude::*;
            let mut out = self
                .tensor_tape
                .tensor(input)?
                .contiguous_values_f32()?
                .to_vec();
            out.par_chunks_mut(other_size).for_each(|slice| {
                let mut acc = 0.0_f64;
                for &x in slice.iter() {
                    acc += (x as f64).abs().powf(p);
                }
                let norm = acc.powf(1.0 / p);
                if norm > maxnorm {
                    #[allow(clippy::cast_possible_truncation)]
                    let scale = (maxnorm / (norm + 1e-7)) as f32;
                    for x in slice.iter_mut() {
                        *x *= scale;
                    }
                }
            });
            return self.tensor_variable_f32(out, shape, false);
        }

        // Build the swap-(0, dim) permutation. swap is its own inverse.
        let mut perm: Vec<usize> = (0..n).collect();
        perm.swap(0, dim);
        let permuted_shape: Vec<usize> = perm.iter().map(|&i| shape[i]).collect();

        let permuted = if dim == 0 {
            input
        } else {
            self.tensor_permute(input, perm.clone())?
        };
        let flat = self.tensor_reshape(permuted, vec![dim_size, other_size])?;

        let abs_x = self.tensor_abs(flat)?;
        let pow_x = self.tensor_pow(abs_x, p)?;
        let sum_x = self.tensor_sum_dim(pow_x, 1)?; // [dim_size]
        let norm = self.tensor_pow(sum_x, 1.0 / p)?; // [dim_size]
        // torch renorm rescales a slice ONLY when its p-norm strictly exceeds
        // maxnorm, by factor maxnorm/(norm + 1e-7) (the 1e-7 guards div-by-zero
        // and matches upstream); slices within maxnorm are left unscaled
        // (factor 1.0). The prior code used maxnorm/max(norm, maxnorm) =
        // maxnorm/norm with NO epsilon, diverging from torch by ~1e-7 on every
        // over-norm slice (e.g. nn.Embedding(max_norm=...)). frankentorch-tncnq.
        // full_like(norm) keeps the scale in the input dtype (f32 stays f32),
        // frankentorch-fk5l.
        let max_t = self.full_like(norm, maxnorm, false)?;
        let eps_t = self.full_like(norm, 1e-7, false)?;
        let one_t = self.full_like(norm, 1.0, false)?;
        let norm_eps = self.tensor_add(norm, eps_t)?;
        let rescale = self.tensor_div(max_t, norm_eps)?; // maxnorm/(norm + 1e-7)
        let over = self.tensor_gt(norm, max_t)?; // norm > maxnorm (strict)
        let scale = self.tensor_where(over, rescale, one_t)?; // [dim_size]
        let scale_kd = self.tensor_unsqueeze(scale, 1)?; // [dim_size, 1]
        let scale_b = self.tensor_expand(scale_kd, vec![dim_size, other_size])?;
        let scaled = self.tensor_mul(flat, scale_b)?;

        let unflat = self.tensor_reshape(scaled, permuted_shape)?;
        if dim == 0 {
            Ok(unflat)
        } else {
            self.tensor_permute(unflat, perm)
        }
    }

    /// Test if each element is in a set of test values. Returns 0.0/1.0 mask.
    ///
    /// Equivalent to `torch.isin(elements, test_elements)`.
    pub fn tensor_isin(
        &mut self,
        elements: TensorNodeId,
        test_elements: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        if self.tensor_requires_grad(elements)? || self.tensor_requires_grad(test_elements)? {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "isin: autograd not supported (membership mask is non-differentiable). Tracked under frankentorch-gec0.",
                },
            )));
        }
        // Lossy reads so f32/f16/bf16 inputs work (tensor_values is F64-only).
        let elem_vals = self.tensor_values_lossy_f64(elements)?;
        let test_vals = self.tensor_values_lossy_f64(test_elements)?;
        let shape = self.tensor_shape(elements)?;

        // EXACT membership (`e == t`), matching torch.isin. `==` gives the correct f64
        // semantics: +0.0 == -0.0 (members), NaN never equal (never a member).
        //
        // The old path was a SERIAL O(n*m) per-element linear scan of `test_vals`, which is
        // catastrophic for a large test set (n=4M, m=5000 -> ~20e9 compares, ~24x slower than
        // torch). Two fixes, both bit-exact to the `==` scan:
        //   * LARGE m: build a hash set of test keys once (O(m)) and probe each element (O(1)),
        //     collapsing O(n*m) -> O(n+m). Keys canonicalize +0.0/-0.0 to the same bits (so the
        //     +0==-0 rule holds) and NaN test values are excluded (NaN is never a member); a NaN
        //     element is likewise never a member. splitmix64 keyer (u64 bit-pattern keys, so
        //     std SipHash is wasted overhead).
        //   * SMALL m: keep the auto-vectorizing linear scan (a tiny test set beats hashing).
        // Both are fanned over Rayon (independent per element). torch.isin is serial.
        #[derive(Default)]
        struct SplitMix64Hasher(u64);
        impl std::hash::Hasher for SplitMix64Hasher {
            #[inline]
            fn finish(&self) -> u64 {
                self.0
            }
            #[inline]
            fn write_u64(&mut self, i: u64) {
                let mut z = self.0 ^ i;
                z = (z ^ (z >> 30)).wrapping_mul(0xbf58_476d_1ce4_e5b9);
                z = (z ^ (z >> 27)).wrapping_mul(0x94d0_49bb_1331_11eb);
                self.0 = z ^ (z >> 31);
            }
            #[inline]
            fn write(&mut self, bytes: &[u8]) {
                for &b in bytes {
                    self.write_u64(u64::from(b));
                }
            }
        }
        let canon = |v: f64| -> u64 {
            if v == 0.0 {
                0.0_f64.to_bits()
            } else {
                v.to_bits()
            }
        };
        use rayon::prelude::*;
        const ISIN_HASH_MIN_M: usize = 32;
        const ISIN_PAR_MIN_N: usize = 8192;
        let par = elem_vals.len() >= ISIN_PAR_MIN_N && rayon::current_num_threads() > 1;
        let result: Vec<f64> = if test_vals.len() >= ISIN_HASH_MIN_M {
            let mut set: std::collections::HashSet<
                u64,
                std::hash::BuildHasherDefault<SplitMix64Hasher>,
            > = std::collections::HashSet::default();
            set.reserve(test_vals.len());
            for &t in &test_vals {
                if !t.is_nan() {
                    set.insert(canon(t));
                }
            }
            let probe = |&e: &f64| -> f64 {
                if !e.is_nan() && set.contains(&canon(e)) {
                    1.0
                } else {
                    0.0
                }
            };
            if par {
                elem_vals.par_iter().map(probe).collect()
            } else {
                elem_vals.iter().map(probe).collect()
            }
        } else {
            let scan = |&e: &f64| -> f64 {
                if test_vals.iter().any(|&t| e == t) {
                    1.0
                } else {
                    0.0
                }
            };
            if par {
                elem_vals.par_iter().map(scan).collect()
            } else {
                elem_vals.iter().map(scan).collect()
            }
        };
        self.tensor_tape.leaf(result, shape, false)
    }

    // ── hstack ──────────────────────────────────────────────────────────
    /// Horizontally stack tensors (along dim 1 for 2D+, dim 0 for 1D).
    ///
    /// Equivalent to `torch.hstack(tensors)`.
    pub fn tensor_hstack(
        &mut self,
        inputs: &[TensorNodeId],
    ) -> Result<TensorNodeId, AutogradError> {
        if inputs.is_empty() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "hstack: need at least one tensor",
                },
            )));
        }
        let ndim = self.tensor_shape(inputs[0])?.len();
        let dim = if ndim <= 1 { 0 } else { 1 };
        self.tensor_cat(inputs, dim)
    }

    // ── vstack ──────────────────────────────────────────────────────────
    /// Vertically stack tensors (along dim 0).
    ///
    /// Equivalent to `torch.vstack(tensors)` / `torch.row_stack(tensors)`.
    /// 1-D tensors are reshaped to `(1, N)` before stacking.
    pub fn tensor_vstack(
        &mut self,
        inputs: &[TensorNodeId],
    ) -> Result<TensorNodeId, AutogradError> {
        if inputs.is_empty() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "vstack: need at least one tensor",
                },
            )));
        }

        // Reshape 1D inputs to 2D
        let mut reshaped = Vec::with_capacity(inputs.len());
        for &inp in inputs {
            let shape = self.tensor_shape(inp)?;
            if shape.len() == 1 {
                let n = shape[0];
                reshaped.push(self.tensor_reshape(inp, vec![1, n])?);
            } else {
                reshaped.push(inp);
            }
        }

        self.tensor_cat(&reshaped, 0)
    }

    /// Alias for `tensor_vstack`.
    pub fn tensor_row_stack(
        &mut self,
        inputs: &[TensorNodeId],
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_vstack(inputs)
    }

    // ── dstack ──────────────────────────────────────────────────────────
    /// Depth-stack tensors (along dim 2).
    ///
    /// Equivalent to `torch.dstack(tensors)`.
    /// 1-D inputs are reshaped to `(1, N, 1)`, 2-D inputs to `(N, M, 1)`.
    pub fn tensor_dstack(
        &mut self,
        inputs: &[TensorNodeId],
    ) -> Result<TensorNodeId, AutogradError> {
        if inputs.is_empty() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "dstack: need at least one tensor",
                },
            )));
        }

        let mut reshaped = Vec::with_capacity(inputs.len());
        for &inp in inputs {
            let shape = self.tensor_shape(inp)?;
            match shape.len() {
                1 => {
                    let n = shape[0];
                    reshaped.push(self.tensor_reshape(inp, vec![1, n, 1])?);
                }
                2 => {
                    let (n, m) = (shape[0], shape[1]);
                    reshaped.push(self.tensor_reshape(inp, vec![n, m, 1])?);
                }
                _ => reshaped.push(inp),
            }
        }

        self.tensor_cat(&reshaped, 2)
    }

    // ── column_stack ────────────────────────────────────────────────────
    /// Stack 1-D tensors as columns and 2-D tensors horizontally.
    ///
    /// Equivalent to `torch.column_stack(tensors)`.
    pub fn tensor_column_stack(
        &mut self,
        inputs: &[TensorNodeId],
    ) -> Result<TensorNodeId, AutogradError> {
        if inputs.is_empty() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "column_stack: need at least one tensor",
                },
            )));
        }

        let mut reshaped = Vec::with_capacity(inputs.len());
        for &inp in inputs {
            let shape = self.tensor_shape(inp)?;
            if shape.len() == 1 {
                let n = shape[0];
                reshaped.push(self.tensor_reshape(inp, vec![n, 1])?);
            } else {
                reshaped.push(inp);
            }
        }

        self.tensor_cat(&reshaped, 1)
    }

    // ── hsplit ──────────────────────────────────────────────────────────
    /// Split tensor horizontally (along dim 1 for 2D+, dim 0 for 1D).
    ///
    /// Equivalent to `torch.hsplit(input, indices_or_sections)`.
    pub fn tensor_hsplit(
        &mut self,
        input: TensorNodeId,
        sections: usize,
    ) -> Result<Vec<TensorNodeId>, AutogradError> {
        let ndim = self.tensor_shape(input)?.len();
        let dim = if ndim <= 1 { 0 } else { 1 };
        self.tensor_chunk(input, sections, dim)
    }

    // ── vsplit ──────────────────────────────────────────────────────────
    /// Split tensor vertically (along dim 0).
    ///
    /// Equivalent to `torch.vsplit(input, indices_or_sections)`.
    pub fn tensor_vsplit(
        &mut self,
        input: TensorNodeId,
        sections: usize,
    ) -> Result<Vec<TensorNodeId>, AutogradError> {
        self.tensor_chunk(input, sections, 0)
    }

    // ── dsplit ──────────────────────────────────────────────────────────
    /// Split tensor along depth (dim 2).
    ///
    /// Equivalent to `torch.dsplit(input, indices_or_sections)`.
    pub fn tensor_dsplit(
        &mut self,
        input: TensorNodeId,
        sections: usize,
    ) -> Result<Vec<TensorNodeId>, AutogradError> {
        self.tensor_chunk(input, sections, 2)
    }

    // ── trapezoid ────────────────────────────────────────────────────────
    /// Compute the trapezoidal rule along a dimension.
    ///
    /// Equivalent to `torch.trapezoid(y, x, dim)`.
    /// If `x` is None, assumes uniform spacing of 1.
    /// Shared interval-width weighting for trapezoid / cumulative_trapezoid.
    ///
    /// Given the per-interval averages `avg` (shape = `y` with `dim` reduced
    /// to n-1), multiply by the interval widths. Precedence matches torch:
    /// `x` (per-sample coordinates) wins over the uniform scalar `dx`. `x`
    /// may be the full `y` shape OR a 1-D vector of length `y.size(dim)`
    /// (broadcast along `dim`). When `x` is absent and `dx == 1.0` the
    /// averages pass through untouched, keeping the default path byte-identical.
    fn trapezoid_weighted(
        &mut self,
        avg: TensorNodeId,
        y_shape: &[usize],
        x: Option<TensorNodeId>,
        dx: f64,
        dim: usize,
        new_dim_size: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let ndim = y_shape.len();
        if let Some(x_id) = x {
            let x_shape = self.tensor_shape(x_id)?;
            let one_d = x_shape.len() == 1 && x_shape[0] == y_shape[dim];
            if x_shape != y_shape && !one_d {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "trapezoid: x must equal y's shape or be 1-D of length y.size(dim)",
                    },
                )));
            }
            // Full-shape x samples along `dim`; a 1-D coordinate vector samples
            // along its only axis (0). Consecutive coordinate differences are
            // the interval widths.
            let sample_axis = if x_shape == y_shape { dim } else { 0 };
            let x0 = self.tensor_narrow(x_id, sample_axis, 0, new_dim_size)?;
            let x1 = self.tensor_narrow(x_id, sample_axis, 1, new_dim_size)?;
            let widths = self.tensor_sub(x1, x0)?;
            // A 1-D width vector [n-1] is reshaped to broadcast along `dim`.
            let widths = if one_d && ndim > 1 {
                let mut bshape = vec![1usize; ndim];
                bshape[dim] = new_dim_size;
                self.tensor_reshape(widths, bshape)?
            } else {
                widths
            };
            self.tensor_mul(avg, widths)
        } else if dx == 1.0 {
            Ok(avg)
        } else {
            let dx_t = self.full_like(avg, dx, false)?;
            self.tensor_mul(avg, dx_t)
        }
    }

    pub fn tensor_trapezoid(
        &mut self,
        y: TensorNodeId,
        x: Option<TensorNodeId>,
        dim: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_trapezoid_dx(y, x, 1.0, dim)
    }

    /// `torch.trapezoid(y, x=x, dx=dx, dim=dim)`.
    ///
    /// Trapezoidal integration of `y` along `dim`. Spacing comes from `x`'s
    /// per-interval differences when given, otherwise the uniform scalar `dx`.
    /// `x` may match `y`'s shape exactly OR be a 1-D coordinate vector of
    /// length `y.size(dim)` broadcast along `dim` (torch's common form, which
    /// was previously rejected). Composes through autograd primitives so the
    /// gradient flows to `y` (and `x`).
    pub fn tensor_trapezoid_dx(
        &mut self,
        y: TensorNodeId,
        x: Option<TensorNodeId>,
        dx: f64,
        dim: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let y_shape = self.tensor_shape(y)?;
        let ndim = y_shape.len();
        if dim >= ndim {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "trapezoid: dimension out of range",
                },
            )));
        }

        let dim_size = y_shape[dim];
        if dim_size < 2 {
            // With fewer than 2 points, integral is 0
            let mut out_shape = y_shape.clone();
            out_shape.remove(dim);
            if out_shape.is_empty() {
                out_shape.push(1);
            }
            let numel = Self::checked_shape_numel(&out_shape, "trapezoid: output shape overflow")?;
            return self.tensor_tape.leaf(vec![0.0; numel], out_shape, false);
        }

        // No-grad fused fast path for the uniform-spacing case (x = None): the compose below is
        // narrow + narrow + add + full_like + mul + sum_dim = ~5 full-size materialisations
        // (y_sum, half, avg, ...) — measured ~300x SLOWER than torch's fused reduction. Compute
        // integral[row] = dx * Σ_k 0.5·(y[k]+y[k+1]) in ONE pass over the borrowed contiguous
        // storage (f64 accumulator), matching the compose's per-interval avg then f64 sum. Grad /
        // x given / non-contiguous / non-float fall through. frankentorch-specf32.
        if x.is_none() && !self.tensor_requires_grad(y)? {
            let dt = self.tensor_dtype(y)?;
            let built: Option<(Option<Vec<f64>>, Option<Vec<f32>>, Vec<usize>)> = {
                let t = self.tensor_tape.tensor(y)?;
                if t.meta().is_contiguous() && matches!(dt, DType::F32 | DType::F64) {
                    use rayon::prelude::*;
                    let inner: usize = y_shape[dim + 1..].iter().product();
                    let outer: usize = y_shape[..dim].iter().product();
                    let d = dim_size;
                    let out_numel = outer * inner;
                    let mut out_shape = y_shape.clone();
                    out_shape.remove(dim);
                    if out_shape.is_empty() {
                        out_shape.push(1);
                    }
                    // out index oi -> (o, i): base = o*d*inner + i; step = inner.
                    match dt {
                        DType::F32 => {
                            let v = t.contiguous_values_f32()?;
                            let dxf = dx as f32;
                            let out: Vec<f32> = (0..out_numel)
                                .into_par_iter()
                                .map(|oi| {
                                    let o = oi / inner;
                                    let i = oi % inner;
                                    let base = o * d * inner + i;
                                    let mut s = 0.0_f64;
                                    for k in 0..d - 1 {
                                        let avg = (v[base + k * inner] + v[base + (k + 1) * inner])
                                            * 0.5_f32;
                                        s += (avg * dxf) as f64;
                                    }
                                    s as f32
                                })
                                .collect();
                            Some((None, Some(out), out_shape))
                        }
                        _ => {
                            let v = t.contiguous_values()?;
                            let out: Vec<f64> = (0..out_numel)
                                .into_par_iter()
                                .map(|oi| {
                                    let o = oi / inner;
                                    let i = oi % inner;
                                    let base = o * d * inner + i;
                                    let mut s = 0.0_f64;
                                    for k in 0..d - 1 {
                                        let avg =
                                            (v[base + k * inner] + v[base + (k + 1) * inner]) * 0.5;
                                        s += avg * dx;
                                    }
                                    s
                                })
                                .collect();
                            Some((Some(out), None, out_shape))
                        }
                    }
                } else {
                    None
                }
            };
            match built {
                Some((Some(out64), None, sh)) => return self.tensor_variable(out64, sh, false),
                Some((None, Some(out32), sh)) => return self.tensor_variable_f32(out32, sh, false),
                _ => {}
            }
        }

        // Compose through autograd primitives. Tracked under
        // frankentorch-b4ys. Math:
        //   y0 = narrow(y, dim, 0, n-1)
        //   y1 = narrow(y, dim, 1, n-1)
        //   width = (x1 - x0) if x else dx-scalar   (broadcast)
        //   integral = sum((y0 + y1) * 0.5 * width, dim)
        let new_dim_size = dim_size - 1;
        let y0 = self.tensor_narrow(y, dim, 0, new_dim_size)?;
        let y1 = self.tensor_narrow(y, dim, 1, new_dim_size)?;
        let y_sum = self.tensor_add(y0, y1)?;
        // full_like(y_sum) so the 0.5 factor matches the input dtype: an f32
        // input keeps f32 (torch trapezoid(f32) -> f32); full() was F64 and
        // upcast the result. frankentorch-z71u.
        let half_t = self.full_like(y_sum, 0.5, false)?;
        let avg = self.tensor_mul(y_sum, half_t)?;

        let weighted = self.trapezoid_weighted(avg, &y_shape, x, dx, dim, new_dim_size)?;

        let integral = self.tensor_sum_dim(weighted, dim)?;
        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!("trapezoid y={} dim={dim} out={}", y.0, integral.0),
        );
        Ok(integral)
    }

    /// Alias for `tensor_trapezoid`. Equivalent to `torch.trapz`.
    ///
    /// Deprecated in favor of `trapezoid`, but kept for backwards compatibility.
    pub fn tensor_trapz(
        &mut self,
        y: TensorNodeId,
        x: Option<TensorNodeId>,
        dim: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_trapezoid(y, x, dim)
    }

    // ── cumulative_trapezoid ────────────────────────────────────────────
    /// Compute the cumulative trapezoidal rule along a dimension.
    ///
    /// Equivalent to `torch.cumulative_trapezoid(y, x, dim)`.
    /// Returns a tensor with `dim_size - 1` along the specified dimension.
    pub fn tensor_cumulative_trapezoid(
        &mut self,
        y: TensorNodeId,
        x: Option<TensorNodeId>,
        dim: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_cumulative_trapezoid_dx(y, x, 1.0, dim)
    }

    /// `torch.cumulative_trapezoid(y, x=x, dx=dx, dim=dim)`.
    ///
    /// Cumulative trapezoidal integration along `dim`. Spacing semantics match
    /// `tensor_trapezoid_dx`: `x`'s per-interval differences when given (full
    /// shape or 1-D coordinates along `dim`), otherwise the uniform scalar
    /// `dx`. Composes through autograd primitives.
    pub fn tensor_cumulative_trapezoid_dx(
        &mut self,
        y: TensorNodeId,
        x: Option<TensorNodeId>,
        dx: f64,
        dim: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let y_shape = self.tensor_shape(y)?;
        let ndim = y_shape.len();
        if dim >= ndim {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "cumulative_trapezoid: dimension out of range",
                },
            )));
        }

        let dim_size = y_shape[dim];
        if dim_size < 2 {
            let mut out_shape = y_shape;
            out_shape[dim] = 0;
            return self.tensor_tape.leaf(Vec::new(), out_shape, false);
        }

        // No-grad fused fast path (x = None, LAST dim): the compose is
        // narrow+narrow+add+full_like+mul+cumsum = ~5 full-size materialisations (measured ~4x
        // SLOWER than torch). For the contiguous last-dim case each output row is an independent
        // running cumsum of 0.5·(y[k]+y[k+1])·dx — compute it in ONE parallel pass (f64 cumsum,
        // matching the compose's per-interval avg then cumsum). Grad / x-given / inner-dim /
        // non-contiguous / non-float fall through. frankentorch-specf32.
        if x.is_none() && dim == ndim - 1 && !self.tensor_requires_grad(y)? {
            let dt = self.tensor_dtype(y)?;
            let new_d = dim_size - 1;
            let outer: usize = y_shape[..dim].iter().product();
            let mut out_shape = y_shape.clone();
            out_shape[dim] = new_d;
            let built: Option<(Option<Vec<f64>>, Option<Vec<f32>>)> = {
                let t = self.tensor_tape.tensor(y)?;
                if t.meta().is_contiguous() && matches!(dt, DType::F32 | DType::F64) {
                    use rayon::prelude::*;
                    match dt {
                        DType::F32 => {
                            let v = t.contiguous_values_f32()?;
                            let dxf = dx as f32;
                            let mut out = vec![0.0_f32; outer * new_d];
                            out.par_chunks_mut(new_d).enumerate().for_each(|(o, row)| {
                                let base = o * dim_size;
                                let mut acc = 0.0_f64;
                                for j in 0..new_d {
                                    let avg = (v[base + j] + v[base + j + 1]) * 0.5_f32;
                                    acc += (avg * dxf) as f64;
                                    row[j] = acc as f32;
                                }
                            });
                            Some((None, Some(out)))
                        }
                        _ => {
                            let v = t.contiguous_values()?;
                            let mut out = vec![0.0_f64; outer * new_d];
                            out.par_chunks_mut(new_d).enumerate().for_each(|(o, row)| {
                                let base = o * dim_size;
                                let mut acc = 0.0_f64;
                                for j in 0..new_d {
                                    let avg = (v[base + j] + v[base + j + 1]) * 0.5;
                                    acc += avg * dx;
                                    row[j] = acc;
                                }
                            });
                            Some((Some(out), None))
                        }
                    }
                } else {
                    None
                }
            };
            match built {
                Some((Some(o64), None)) => return self.tensor_variable(o64, out_shape, false),
                Some((None, Some(o32))) => return self.tensor_variable_f32(o32, out_shape, false),
                _ => {}
            }
        }

        // Compose through autograd primitives. Tracked under
        // frankentorch-atg3. Same shape as tensor_trapezoid (b4ys)
        // but ends with tensor_cumsum instead of tensor_sum_dim.
        let new_dim_size = dim_size - 1;
        let y0 = self.tensor_narrow(y, dim, 0, new_dim_size)?;
        let y1 = self.tensor_narrow(y, dim, 1, new_dim_size)?;
        let y_sum = self.tensor_add(y0, y1)?;
        // full_like(y_sum) so the 0.5 factor matches the input dtype: an f32
        // input keeps f32 (torch trapezoid(f32) -> f32); full() was F64 and
        // upcast the result. frankentorch-z71u.
        let half_t = self.full_like(y_sum, 0.5, false)?;
        let avg = self.tensor_mul(y_sum, half_t)?;

        let weighted = self.trapezoid_weighted(avg, &y_shape, x, dx, dim, new_dim_size)?;

        let out = self.tensor_cumsum(weighted, dim)?;
        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!("cumulative_trapezoid y={} dim={dim} out={}", y.0, out.0),
        );
        Ok(out)
    }

    // ── addr ────────────────────────────────────────────────────────────
    /// Perform a rank-1 update: `out = beta * input + alpha * vec1 ⊗ vec2`.
    ///
    /// Equivalent to `torch.addr(input, vec1, vec2, beta, alpha)`.
    pub fn tensor_addr(
        &mut self,
        input: TensorNodeId,
        vec1: TensorNodeId,
        vec2: TensorNodeId,
        beta: f64,
        alpha: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let v1_shape = self.tensor_shape(vec1)?;
        let v2_shape = self.tensor_shape(vec2)?;
        let input_shape = self.tensor_shape(input)?;
        if v1_shape.len() != 1 || v2_shape.len() != 1 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "addr: vec1 and vec2 must be 1-D",
                },
            )));
        }
        let m = v1_shape[0];
        let n = v2_shape[0];
        if input_shape != [m, n] {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "addr: input shape must match (len(vec1), len(vec2))",
                },
            )));
        }

        // Compose through autograd-aware primitives. Tracked under
        // frankentorch-pzih. Math:
        //   out = beta * input + alpha * (vec1 ⊗ vec2)
        let outer = self.tensor_outer(vec1, vec2)?;
        let alpha_t = self.full(vec![m, n], alpha, false)?;
        let beta_t = self.full(vec![m, n], beta, false)?;
        let alpha_outer = self.tensor_mul(outer, alpha_t)?;
        let beta_input = self.tensor_mul(input, beta_t)?;
        let out = self.tensor_add(beta_input, alpha_outer)?;
        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!(
                "addr input={} vec1={} vec2={} beta={beta} alpha={alpha} out={}",
                input.0, vec1.0, vec2.0, out.0
            ),
        );
        Ok(out)
    }

    // ── inner ───────────────────────────────────────────────────────────
    /// Compute the inner product of two 1-D tensors.
    ///
    /// Equivalent to `torch.inner(input, other)` for 1-D inputs.
    /// For higher-dimensional inputs, contracts over the last dimension.
    /// Inputs must be at least 1-D.
    pub fn tensor_inner(
        &mut self,
        a: TensorNodeId,
        b: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let a_shape = self.tensor_shape(a)?;
        let b_shape = self.tensor_shape(b)?;

        if a_shape.is_empty() || b_shape.is_empty() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "inner: scalar inputs are not supported",
                },
            )));
        }

        // Compose through autograd-aware primitives so gradients flow.
        // Previously this body extracted values + rebuilt a non-grad
        // leaf — same severed-autograd pattern fixed for the linalg
        // / cross / diag_embed / matrix_norm cluster. Tracked under
        // frankentorch-ytlg.
        //
        // 1-D × 1-D → dot product (delegated to tensor_dot, which is
        // autograd-aware via the tape).
        if a_shape.len() == 1 && b_shape.len() == 1 {
            if a_shape[0] != b_shape[0] {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "inner: 1-D tensors must have same length",
                    },
                )));
            }
            let dot = self.tensor_dot(a, b)?;
            self.runtime.ledger_mut().record(
                EvidenceKind::Dispatch,
                format!("inner a={} b={} out={}", a.0, b.0, dot.0),
            );
            // tensor_dot returns a 0-D scalar; preserve the prior
            // [1]-shape contract.
            let dot_shape = self.tensor_shape(dot)?;
            return if dot_shape == [1] {
                Ok(dot)
            } else if dot_shape.is_empty() {
                self.tensor_unsqueeze(dot, 0)
            } else {
                self.tensor_reshape(dot, vec![1])
            };
        }

        // Higher-D: contract along the last axis. Reshape both inputs
        // to 2-D (outer, last) and compute matmul(a_flat, b_flat.T)
        // → (a_outer, b_outer), then reshape to the inner output
        // shape. matmul + transpose + reshape are all autograd-aware.
        let a_last =
            *a_shape
                .last()
                .ok_or(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "inner: missing last dimension on lhs",
                    },
                )))?;
        let b_last =
            *b_shape
                .last()
                .ok_or(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "inner: missing last dimension on rhs",
                    },
                )))?;
        if a_last == 0 || b_last == 0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "inner: last dimension must be non-zero",
                },
            )));
        }
        if a_last != b_last {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "inner: last dimensions must match",
                },
            )));
        }

        let a_numel = Self::checked_shape_numel(&a_shape, "inner: lhs shape volume overflow")?;
        let b_numel = Self::checked_shape_numel(&b_shape, "inner: rhs shape volume overflow")?;
        let a_outer = a_numel / a_last;
        let b_outer = b_numel / b_last;

        let a_flat = self.tensor_reshape(a, vec![a_outer, a_last])?;
        let b_flat = self.tensor_reshape(b, vec![b_outer, b_last])?;
        let b_t = self.tensor_transpose(b_flat, 0, 1)?;
        let prod = self.tensor_matmul(a_flat, b_t)?; // shape [a_outer, b_outer]

        let mut out_shape: Vec<usize> = a_shape[..a_shape.len() - 1].to_vec();
        out_shape.extend_from_slice(&b_shape[..b_shape.len() - 1]);
        if out_shape.is_empty() {
            out_shape.push(1);
        }
        let out = self.tensor_reshape(prod, out_shape)?;
        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!("inner a={} b={} out={}", a.0, b.0, out.0),
        );
        Ok(out)
    }

    // ── fliplr ──────────────────────────────────────────────────────────
    /// Flip tensor in the left/right direction (along dim 1).
    ///
    /// Equivalent to `torch.fliplr(input)`. Input must be >= 2-D.
    pub fn tensor_fliplr(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let ndim = self.tensor_shape(input)?.len();
        if ndim < 2 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "fliplr: input must be at least 2-D",
                },
            )));
        }
        self.tensor_flip(input, &[1])
    }

    // ── flipud ──────────────────────────────────────────────────────────
    /// Flip tensor in the up/down direction (along dim 0).
    ///
    /// Equivalent to `torch.flipud(input)`. Input must be >= 1-D.
    pub fn tensor_flipud(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let ndim = self.tensor_shape(input)?.len();
        if ndim < 1 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "flipud: input must be at least 1-D",
                },
            )));
        }
        self.tensor_flip(input, &[0])
    }

    // ── diagflat ────────────────────────────────────────────────────────
    /// Create a diagonal matrix from a flattened input, with optional offset.
    ///
    /// Equivalent to `torch.diagflat(input, offset)`.
    /// Flattens the input and places values along the specified diagonal.
    pub fn tensor_diagflat(
        &mut self,
        input: TensorNodeId,
        offset: i64,
    ) -> Result<TensorNodeId, AutogradError> {
        // Compose through reshape + tensor_diag_embed (the latter is
        // autograd-aware after frankentorch-d180). Tracked under
        // frankentorch-lgps. Previously this body extracted values,
        // built the matrix in plain f64, and rebuilt a non-grad leaf.
        //
        // diagflat(x, offset) == diag_embed(flatten(x), offset)
        // with input flattened to 1-D first.
        let shape = self.tensor_shape(input)?;
        let n = Self::checked_shape_numel(&shape, "diagflat: shape volume overflow")?;
        // diag_embed expects i32 offset; range-check the i64 input.
        let offset_i32 = i32::try_from(offset).map_err(|_| {
            AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "diagflat: offset out of range for i32",
                },
            ))
        })?;
        let flat = if shape.len() == 1 {
            input
        } else {
            self.tensor_reshape(input, vec![n])?
        };
        let out = self.tensor_diag_embed(flat, offset_i32)?;
        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!("diagflat input={} offset={offset} out={}", input.0, out.0),
        );
        Ok(out)
    }

    // ── tensor_select ────────────────────────────────────────────────────
    /// Select a single slice along a dimension, removing that dimension.
    ///
    /// Equivalent to `torch.select(input, dim, index)`.
    /// Returns a tensor with one fewer dimension.
    pub fn tensor_select(
        &mut self,
        input: TensorNodeId,
        dim: usize,
        index: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        if dim >= shape.len() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "select: dimension out of range",
                },
            )));
        }
        if index >= shape[dim] {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "select: index out of range for dimension",
                },
            )));
        }

        // narrow to length 1, then squeeze that dimension
        let narrowed = self.tensor_narrow(input, dim, index, 1)?;
        self.tensor_squeeze(narrowed, dim)
    }

    /// Copy variant of select.
    ///
    /// Equivalent to `tensor.select_copy(dim, index)`.
    /// Since ft-api creates copies, this is identical to `tensor_select`.
    pub fn tensor_select_copy(
        &mut self,
        input: TensorNodeId,
        dim: usize,
        index: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_select(input, dim, index)
    }

    // ── tensor_take_along_dim ──────────────────────────────────────────
    /// Gather values along a dimension using indices from another tensor.
    ///
    /// Equivalent to `torch.take_along_dim(input, indices, dim)`.
    /// Both tensors must have the same number of dimensions, and `indices`
    /// determines which elements to select along `dim`.
    pub fn tensor_take_along_dim(
        &mut self,
        input: TensorNodeId,
        indices: TensorNodeId,
        dim: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        // This is equivalent to gather
        self.tensor_gather(input, dim, indices)
    }

    // ── tensor_scatter_reduce ──────────────────────────────────────────
    /// Scatter values into a tensor with a reduction operation.
    ///
    /// Equivalent to `torch.Tensor.scatter_reduce_(dim, index, src, reduce)`.
    /// Supported reduce operations: "sum", "prod", "mean", "amax", "amin".
    /// In-place no-grad scatter-reduce kernel over a `[outer, dim_size, inner]` view.
    /// Each `outer` row owns a disjoint `[dim_size*inner]` output segment, so the rows
    /// parallelize across the rayon pool with NO write conflict. The per-row scatter walks
    /// idx in flat order, so the sequence (and thus amax/amin tie-break + float sum order)
    /// is identical to the serial loop. `reduce` must already be validated to one of
    /// sum/prod/mean/amax/amin (the `_` arm is unreachable). `mean_div(&mut v, count)`
    /// applies the include_self mean divisor `v /= (count+1)` in the element's dtype.
    #[allow(clippy::too_many_arguments)]
    fn scatter_reduce_apply<T>(
        result: &mut [T],
        idx_vals: &[f64],
        src_vals: &[T],
        reduce: &str,
        outer: usize,
        idx_dim_size: usize,
        inner: usize,
        dim_size: usize,
        parallel: bool,
        mean_div: fn(&mut T, usize),
    ) where
        T: Copy + Send + Sync + PartialOrd + std::ops::AddAssign + std::ops::MulAssign,
    {
        let seg = dim_size * inner;
        let _ = outer;
        let scatter_row = |o: usize, out_chunk: &mut [T]| {
            let idx_outer = o * idx_dim_size * inner;
            let mut local_counts: Vec<usize> = if reduce == "mean" {
                vec![0usize; seg]
            } else {
                Vec::new()
            };
            for s in 0..idx_dim_size {
                let row = idx_outer + s * inner;
                for i in 0..inner {
                    let flat_i = row + i;
                    let raw_idx = idx_vals[flat_i] as isize;
                    let target_dim_idx = if raw_idx < 0 {
                        (raw_idx + dim_size as isize) as usize
                    } else {
                        raw_idx as usize
                    };
                    let local = target_dim_idx * inner + i;
                    let sv = src_vals[flat_i];
                    match reduce {
                        "copy" => out_chunk[local] = sv,
                        "sum" => out_chunk[local] += sv,
                        "prod" => out_chunk[local] *= sv,
                        "mean" => {
                            out_chunk[local] += sv;
                            local_counts[local] += 1;
                        }
                        "amax" => {
                            if sv > out_chunk[local] {
                                out_chunk[local] = sv;
                            }
                        }
                        "amin" => {
                            if sv < out_chunk[local] {
                                out_chunk[local] = sv;
                            }
                        }
                        _ => {}
                    }
                }
            }
            if reduce == "mean" {
                for (v, &c) in out_chunk.iter_mut().zip(local_counts.iter()) {
                    if c > 0 {
                        mean_div(v, c);
                    }
                }
            }
        };
        if parallel {
            use rayon::prelude::*;
            result
                .par_chunks_mut(seg)
                .enumerate()
                .for_each(|(o, out_chunk)| scatter_row(o, out_chunk));
        } else {
            result
                .chunks_mut(seg)
                .enumerate()
                .for_each(|(o, out_chunk)| scatter_row(o, out_chunk));
        }
    }

    pub fn tensor_scatter_reduce(
        &mut self,
        input: TensorNodeId,
        dim: usize,
        index: TensorNodeId,
        src: TensorNodeId,
        reduce: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        let input_shape = self.tensor_shape(input)?;
        let idx_shape = self.tensor_shape(index)?;
        let src_shape = self.tensor_shape(src)?;

        if dim >= input_shape.len() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "scatter_reduce: dimension out of range",
                },
            )));
        }

        let ndim = input_shape.len();
        if idx_shape.len() != ndim {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "scatter_reduce: index rank must match input rank",
                },
            )));
        }
        for d in 0..ndim {
            if d != dim && idx_shape[d] != input_shape[d] {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "scatter_reduce: index shape must match input shape except at dim",
                    },
                )));
            }
        }
        if src_shape != idx_shape {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "scatter_reduce: src shape must match index shape",
                },
            )));
        }
        if !matches!(reduce, "sum" | "prod" | "mean" | "amax" | "amin") {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "scatter_reduce: unsupported reduce operation",
                },
            )));
        }

        // For requires_grad inputs/src, the 'sum' reduction has a
        // direct autograd-aware composition: tensor_scatter_add(input,
        // dim, index, src). Other reductions (prod / mean / amax /
        // amin) need bespoke backwards that aren't yet implemented;
        // surface them as fail-loud guards so users don't silently
        // get NaN gradients. Tracked under frankentorch-dhm4.
        if self.tensor_requires_grad(input)? || self.tensor_requires_grad(src)? {
            if reduce == "sum" {
                return self.tensor_scatter_add(input, dim, index, src);
            }
            if reduce == "mean" {
                // Compose mean as scatter_add(input, src) / (1 + count_per_position).
                // include_self=True semantics: positions never hit
                // get count=0, divisor=1, output = input.
                // Tracked under frankentorch-uzca.
                let src_shape = self.tensor_shape(src)?;
                let ones_src = self.full(src_shape.clone(), 1.0, false)?;
                // Seed the divisor with ones-of-input-shape so the
                // scatter_add directly produces 1 + count_per_position
                // (frankentorch-ix9k). This removes a separate
                // full(input_shape, 1.0) allocation and the trailing
                // tensor_add(count, one_t) node — the +1 represents
                // the include_self=True input contribution.
                let ones_input = self.full(input_shape, 1.0, false)?;
                let divisor = self.tensor_scatter_add(ones_input, dim, index, ones_src)?;
                let summed = self.tensor_scatter_add(input, dim, index, src)?;
                return self.tensor_div(summed, divisor);
            }
            if reduce == "amax" || reduce == "amin" {
                // Argmax-routing autograd (frankentorch-7k6a). For
                // each output position, exactly one of input[i] or
                // one src[j]→i wins; the gradient flows only to the
                // winning element. Forward: result[i] = mask_input[i]
                // * input[i] + sum over j-mapped-to-i of mask_src[j]
                // * src[j], with masks computed in plain f64 from the
                // input/src values (non-diff). The masks are
                // reconstructed exactly via a values read.
                let input_vals = self.tensor_tape.values(input)?;
                let src_vals = self.tensor_tape.values(src)?;
                let idx_vals = self.tensor_tape.values(index)?;
                let src_shape = self.tensor_shape(src)?;
                let in_numel = input_vals.len();
                let src_numel = src_vals.len();
                let dim_size = input_shape[dim];
                // Compute outer/inner strides for [outer, dim_size, inner] view.
                let outer = Self::checked_shape_numel(
                    &input_shape[..dim],
                    "scatter_reduce: outer overflow",
                )?;
                let inner = Self::checked_shape_numel(
                    &input_shape[dim + 1..],
                    "scatter_reduce: inner overflow",
                )?;
                let dim_size_i = isize::try_from(dim_size).map_err(|_| {
                    AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "scatter_reduce: dim size out of platform isize",
                        },
                    ))
                })?;
                // For each (outer, inner) cell, compute the winner across
                // input[outer, dim_size, inner] and the src values that map to it.
                // Track best value + bool flag (true = src wins) + src index.
                let mut input_winner = vec![false; in_numel];
                let mut src_winner = vec![false; src_numel];
                let mut best = vec![f64::NAN; in_numel];
                // Initialize best with input values; mark input as winner.
                #[allow(clippy::needless_range_loop)]
                for i in 0..in_numel {
                    best[i] = input_vals[i];
                    input_winner[i] = true;
                }
                // Walk src in flat order; map each (outer, src_dim, inner) → input position.
                let src_dim_size = src_shape[dim];
                let src_outer = Self::checked_shape_numel(
                    &src_shape[..dim],
                    "scatter_reduce: src outer overflow",
                )?;
                let src_inner = Self::checked_shape_numel(
                    &src_shape[dim + 1..],
                    "scatter_reduce: src inner overflow",
                )?;
                if src_outer != outer || src_inner != inner {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "scatter_reduce: src shape must match input shape except at dim",
                        },
                    )));
                }
                for o in 0..outer {
                    for s in 0..src_dim_size {
                        for i in 0..inner {
                            let src_flat = (o * src_dim_size + s) * inner + i;
                            // Validate index value.
                            let idx_f = idx_vals[src_flat];
                            let idx_i = Self::exact_integer_index_to_isize(
                                idx_f,
                                "scatter_reduce: index values must be finite integers",
                            )?;
                            if idx_i < -dim_size_i || idx_i >= dim_size_i {
                                return Err(AutogradError::Dispatch(
                                    ft_dispatch::DispatchError::Key(
                                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                                            reason: "scatter_reduce: index value out of range",
                                        },
                                    ),
                                ));
                            }
                            let target_dim = if idx_i < 0 {
                                (idx_i + dim_size_i) as usize
                            } else {
                                idx_i as usize
                            };
                            let dst_flat = (o * dim_size + target_dim) * inner + i;
                            let v = src_vals[src_flat];
                            let beats = if reduce == "amax" {
                                v > best[dst_flat]
                            } else {
                                v < best[dst_flat]
                            };
                            if beats {
                                // Demote previous winner.
                                if input_winner[dst_flat] {
                                    input_winner[dst_flat] = false;
                                }
                                // Find any prior src winner for this dst and demote.
                                // Scan back through src that hit this dst — but since
                                // we walk src in flat order, the prior winner (if any)
                                // is the most recent earlier src that beat all before
                                // it. We can simply clear src_winner for any earlier
                                // src that mapped here. Use a simpler approach: track
                                // best-src-flat per dst.
                                // (Re-scan would be O(n^2); use a dst→best_src lookup.)
                                best[dst_flat] = v;
                                src_winner[src_flat] = true;
                                // Demote any older src winner for this dst
                                for prior in 0..src_flat {
                                    if !src_winner[prior] {
                                        continue;
                                    }
                                    // Compute prior's dst:
                                    let prior_o = prior / (src_dim_size * inner);
                                    let prior_rem = prior % (src_dim_size * inner);
                                    let prior_i = prior_rem % inner;
                                    let prior_idx_f = idx_vals[prior];
                                    let prior_idx_i = prior_idx_f as isize;
                                    let prior_target = if prior_idx_i < 0 {
                                        (prior_idx_i + dim_size_i) as usize
                                    } else {
                                        prior_idx_i as usize
                                    };
                                    let prior_dst =
                                        (prior_o * dim_size + prior_target) * inner + prior_i;
                                    if prior_dst == dst_flat {
                                        src_winner[prior] = false;
                                    }
                                }
                            }
                        }
                    }
                }
                // Build mask tensors and compose final result.
                let mask_in_vals: Vec<f64> = input_winner
                    .iter()
                    .map(|&w| if w { 1.0 } else { 0.0 })
                    .collect();
                let mask_src_vals: Vec<f64> = src_winner
                    .iter()
                    .map(|&w| if w { 1.0 } else { 0.0 })
                    .collect();
                let mask_in = self.tensor_variable(mask_in_vals, input_shape.clone(), false)?;
                let mask_src = self.tensor_variable(mask_src_vals, src_shape, false)?;
                let masked_input = self.tensor_mul(mask_in, input)?;
                let masked_src = self.tensor_mul(mask_src, src)?;
                return self.tensor_scatter_add(masked_input, dim, index, masked_src);
            }
            if reduce == "prod" {
                let input_dtype = self.tensor_tape.dtype(input)?;
                let src_dtype = self.tensor_tape.dtype(src)?;
                if src_dtype != input_dtype {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "scatter_reduce requires input and src to have matching dtypes",
                        },
                    )));
                }
                if !matches!(input_dtype, DType::F64 | DType::F32) {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "scatter_reduce requires f32 or f64 tensors",
                        },
                    )));
                }

                let idx_vals = self.tensor_values(index)?;
                Self::validate_index_tensor_values(&input_shape, dim, &idx_vals)?;
                let in_numel =
                    Self::checked_shape_numel(&input_shape, "scatter_reduce prod input overflow")?;
                let src_numel =
                    Self::checked_shape_numel(&src_shape, "scatter_reduce prod src overflow")?;
                let outer = Self::checked_shape_numel(
                    &input_shape[..dim],
                    "scatter_reduce prod outer overflow",
                )?;
                let inner = Self::checked_shape_numel(
                    &input_shape[dim + 1..],
                    "scatter_reduce prod inner overflow",
                )?;
                let dim_size = input_shape[dim];
                let src_dim_size = src_shape[dim];
                let src_outer = Self::checked_shape_numel(
                    &src_shape[..dim],
                    "scatter_reduce prod src outer overflow",
                )?;
                let src_inner = Self::checked_shape_numel(
                    &src_shape[dim + 1..],
                    "scatter_reduce prod src inner overflow",
                )?;
                if src_outer != outer || src_inner != inner {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "scatter_reduce: src shape must match input shape except at dim",
                        },
                    )));
                }
                let dim_size_i = isize::try_from(dim_size).map_err(|_| {
                    AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "scatter_reduce: dim size out of platform isize",
                        },
                    ))
                })?;
                let mut dst_for_src = vec![0usize; src_numel];
                for o in 0..outer {
                    for s in 0..src_dim_size {
                        for i in 0..inner {
                            let src_flat = (o * src_dim_size + s) * inner + i;
                            let idx_i = Self::exact_integer_index_to_isize(
                                idx_vals[src_flat],
                                "scatter_reduce: index values must be finite integers",
                            )?;
                            if idx_i < -dim_size_i || idx_i >= dim_size_i {
                                return Err(AutogradError::Dispatch(
                                    ft_dispatch::DispatchError::Key(
                                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                                            reason: "scatter_reduce: index value out of range",
                                        },
                                    ),
                                ));
                            }
                            let target_dim = if idx_i < 0 {
                                (idx_i + dim_size_i) as usize
                            } else {
                                idx_i as usize
                            };
                            dst_for_src[src_flat] = (o * dim_size + target_dim) * inner + i;
                        }
                    }
                }

                let output_shape_f = input_shape.clone();
                let dst_for_src_f = dst_for_src.clone();
                let dst_for_src_b = dst_for_src;
                let out = self.tensor_apply_function(
                    &[input, src],
                    move |ctx, inputs| {
                        let (input_values, input_shape) = inputs[0];
                        let (src_values, src_shape) = inputs[1];
                        let mut output = input_values.to_vec();
                        for (src_flat, &dst_flat) in dst_for_src_f.iter().enumerate() {
                            output[dst_flat] *= src_values[src_flat];
                        }
                        ctx.save_for_backward(input_values.to_vec(), input_shape.to_vec());
                        ctx.save_for_backward(src_values.to_vec(), src_shape.to_vec());
                        Ok((output, output_shape_f.clone()))
                    },
                    move |ctx, grad_outputs| {
                        let grad_output = grad_outputs[0];
                        if grad_output.len() != in_numel {
                            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                                ft_dispatch::DispatchKeyError::IncompatibleSet {
                                    reason: "scatter_reduce prod backward: incoming gradient shape mismatch",
                                },
                            )));
                        }
                        let saved = ctx.saved_tensors();
                        let input_values = &saved[0];
                        let src_values = &saved[1];
                        let mut product_nonzero = vec![1.0_f64; in_numel];
                        let mut zero_count = vec![0usize; in_numel];
                        for (dst, &value) in input_values.iter().enumerate() {
                            if value == 0.0 {
                                zero_count[dst] += 1;
                            } else {
                                product_nonzero[dst] *= value;
                            }
                        }
                        for (src_flat, &dst_flat) in dst_for_src_b.iter().enumerate() {
                            let value = src_values[src_flat];
                            if value == 0.0 {
                                zero_count[dst_flat] += 1;
                            } else {
                                product_nonzero[dst_flat] *= value;
                            }
                        }

                        let factor_grad = |value: f64, dst: usize| -> f64 {
                            let upstream = grad_output[dst];
                            match zero_count[dst] {
                                0 => upstream * product_nonzero[dst] / value,
                                1 if value == 0.0 => upstream * product_nonzero[dst],
                                _ => 0.0,
                            }
                        };
                        let grad_input = input_values
                            .iter()
                            .enumerate()
                            .map(|(dst, &value)| factor_grad(value, dst))
                            .collect::<Vec<_>>();
                        let grad_src = src_values
                            .iter()
                            .enumerate()
                            .map(|(src_flat, &value)| factor_grad(value, dst_for_src_b[src_flat]))
                            .collect::<Vec<_>>();
                        Ok(vec![Some(grad_input), Some(grad_src)])
                    },
                )?;
                self.runtime.ledger_mut().record(
                    EvidenceKind::Dispatch,
                    format!(
                        "scatter_reduce input={} dim={dim} reduce=prod out={} (autograd)",
                        input.0, out.0
                    ),
                );
                return Ok(out);
            }
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "scatter_reduce: autograd not supported for reduce='prod' (divide-back at zero is unstable; tracked under frankentorch-dhm4)",
                },
            )));
        }

        let input_dtype = self.tensor_tape.dtype(input)?;
        let src_dtype = self.tensor_tape.dtype(src)?;
        if src_dtype != input_dtype {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "scatter_reduce requires input and src to have matching dtypes",
                },
            )));
        }

        // Validate all index values are in range (supports negative wrapping). Borrow the
        // (often large) index storage zero-copy when contiguous f64 — `tensor_values` would
        // deep-clone the whole index tensor; the validate + scatter only read `&[f64]`.
        let idx_owned: Vec<f64>;
        let idx_vals: &[f64] = if self.tensor_tape.dtype(index)? == DType::F64
            && self.tensor_tape.tensor(index)?.meta().is_contiguous()
        {
            self.tensor_tape.tensor(index)?.contiguous_values()?
        } else {
            idx_owned = self.tensor_values(index)?;
            &idx_owned
        };
        Self::validate_index_tensor_values(&input_shape, dim, idx_vals)?;
        let dim_size = input_shape[dim];

        // Compute strides with overflow checks
        let mut strides = vec![1usize; ndim];
        for d in (0..ndim - 1).rev() {
            strides[d] = Self::checked_shape_numel(
                &input_shape[d + 1..],
                "scatter_reduce input stride shape overflow",
            )?;
        }

        let total_idx =
            Self::checked_shape_numel(&idx_shape, "scatter_reduce index shape volume overflow")?;

        // Nested (outer, dim, inner) walk parameters so the flat<->multi-dim conversion is a
        // loop-carried multiply/add instead of a per-element pair of HARDWARE INTEGER DIVIDES
        // (`flat_i / idx_strides[d]`). At millions of scatter elements those divides dominated
        // (~60-70x the scatter cost). `inner` is the same in idx- and input-space because the
        // shapes match except at `dim`.
        let inner = strides[dim];
        let idx_dim_size = idx_shape[dim];
        let outer =
            Self::checked_shape_numel(&input_shape[..dim], "scatter_reduce outer shape overflow")?;
        if !matches!(reduce, "sum" | "prod" | "mean" | "amax" | "amin") {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "scatter_reduce: unsupported reduce operation",
                },
            )));
        }
        // Each outer row scatters into its OWN disjoint [dim_size*inner] output segment, so the
        // outer dimension parallelizes with no cross-row write conflict.
        let parallel = outer >= 2 && total_idx >= PARALLEL_ELEMENTWISE_MIN;

        let out = match input_dtype {
            DType::F64 => {
                // Read input straight into `result` (no separate input_vals + clone) and borrow
                // the src storage zero-copy when contiguous f64; only `&[f64]` is consumed.
                let mut result = self.tensor_tape.values(input)?;
                let src_owned: Vec<f64>;
                let src_vals: &[f64] = if self.tensor_tape.tensor(src)?.meta().is_contiguous() {
                    self.tensor_tape.tensor(src)?.contiguous_values()?
                } else {
                    src_owned = self.tensor_tape.values(src)?;
                    &src_owned
                };
                if src_vals.len() < total_idx {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "scatter_reduce: src storage too small for index shape",
                        },
                    )));
                }
                Self::scatter_reduce_apply(
                    &mut result,
                    idx_vals,
                    src_vals,
                    reduce,
                    outer,
                    idx_dim_size,
                    inner,
                    dim_size,
                    parallel,
                    |v, c| *v /= (c + 1) as f64,
                );
                self.tensor_variable(result, input_shape.clone(), false)?
            }
            DType::F32 => {
                // Read input straight into `result` and borrow the src storage zero-copy.
                let mut result = self.tensor_tape.values_f32(input)?;
                let src_owned: Vec<f32>;
                let src_vals: &[f32] = if self.tensor_tape.tensor(src)?.meta().is_contiguous() {
                    self.tensor_tape.tensor(src)?.contiguous_values_f32()?
                } else {
                    src_owned = self.tensor_tape.values_f32(src)?;
                    &src_owned
                };
                if src_vals.len() < total_idx {
                    return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                        ft_dispatch::DispatchKeyError::IncompatibleSet {
                            reason: "scatter_reduce: src storage too small for index shape",
                        },
                    )));
                }
                Self::scatter_reduce_apply(
                    &mut result,
                    idx_vals,
                    src_vals,
                    reduce,
                    outer,
                    idx_dim_size,
                    inner,
                    dim_size,
                    parallel,
                    |v, c| *v /= (c + 1) as f32,
                );
                self.tensor_variable_f32(result, input_shape.clone(), false)?
            }
            _ => {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "scatter_reduce requires f32 or f64 tensors",
                    },
                )));
            }
        };
        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!(
                "scatter_reduce input={} dim={dim} reduce={reduce} out={}",
                input.0, out.0
            ),
        );
        Ok(out)
    }

    // ── tile ────────────────────────────────────────────────────────────
    /// Repeat tensor along each dimension the specified number of times.
    ///
    /// Equivalent to `torch.tile(input, dims)` / `numpy.tile`.
    pub fn tensor_tile(
        &mut self,
        input: TensorNodeId,
        dims: &[usize],
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        let ndim = shape.len();
        let reps_len = dims.len();

        // Pad dims or shape to match lengths
        let (eff_shape, eff_reps) = if reps_len > ndim {
            let mut new_shape = vec![1; reps_len - ndim];
            new_shape.extend_from_slice(&shape);
            (new_shape, dims.to_vec())
        } else {
            let mut new_reps = vec![1; ndim - reps_len];
            new_reps.extend_from_slice(dims);
            (shape, new_reps)
        };

        // If input needs reshaping to match effective dims
        let mut current = if eff_shape.len() != {
            let t = self.tensor_tape.tensor(input)?;
            t.meta().shape().len()
        } {
            self.tensor_reshape(input, eff_shape.clone())?
        } else {
            input
        };

        // Use tensor_repeat which repeats along each dimension
        current = self.tensor_repeat(current, &eff_reps)?;
        Ok(current)
    }

    // ── cov ─────────────────────────────────────────────────────────────
    /// Compute the covariance matrix of a 2-D tensor (variables × observations).
    ///
    /// Equivalent to `torch.cov(input)`.
    /// Input shape: `(N, M)` where N is the number of variables and M is
    /// the number of observations. Returns an `(N, N)` covariance matrix.
    ///
    /// Composes through tensor_mean_dim / tensor_unsqueeze /
    /// tensor_expand / tensor_sub / tensor_matmul / tensor_transpose /
    /// tensor_div so the autograd tape carries gradients through the
    /// input. Previously this extracted tensor_values and rebuilt a
    /// requires_grad=false leaf, severing the tape (same pattern
    /// recently fixed for xlogy / xlog1py / logit / entr — tracked
    /// under frankentorch-1tax).
    pub fn tensor_cov(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        self.tensor_cov_full(input, 1, None, None)
    }

    /// Build a `[len]` weight constant matching `input`'s float dtype (so a
    /// weighted f32 covariance stays f32 — frankentorch-fk5l). Weighted cov only
    /// supports f32/f64 inputs.
    fn cov_weight_tensor(
        &mut self,
        w: &[f64],
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let node = self.tensor_variable(w.to_vec(), vec![w.len()], false)?;
        match self.tensor_dtype(input)? {
            DType::F64 => Ok(node),
            DType::F32 => self.tensor_to_f32(node),
            _ => Err(Self::incompatible_tensor_args(
                "cov: fweights/aweights require an f32 or f64 input",
            )),
        }
    }

    /// Compute the covariance matrix with torch's `correction`, `fweights`, and
    /// `aweights` parameters.
    ///
    /// Equivalent to `torch.cov(input, correction=correction, fweights=fweights,
    /// aweights=aweights)`. `input` is `(N, M)` (N variables, M observations);
    /// returns the `(N, N)` covariance. `fweights` (frequency, integer-valued)
    /// and `aweights` (analytic, real) are 1-D length-M weight vectors; the
    /// combined weight is `w = fweights * aweights` (or whichever is given).
    /// The normalization follows numpy/torch:
    /// - no weights: `fact = M - correction`
    /// - fweights only: `fact = sum(w) - correction`
    /// - with aweights: `fact = sum(w) - correction * sum(w*aweights) / sum(w)`
    ///
    /// Autograd-aware in `input` (weights are constants). [`Self::tensor_cov`]
    /// delegates here with `correction = 1` and no weights (byte-identical).
    pub fn tensor_cov_full(
        &mut self,
        input: TensorNodeId,
        correction: i64,
        fweights: Option<TensorNodeId>,
        aweights: Option<TensorNodeId>,
    ) -> Result<TensorNodeId, AutogradError> {
        // torch.cov accepts a 1-D [M] input (a single variable with M
        // observations), equivalent to a [1, M] matrix, and returns a 0-dim
        // scalar (the variance). A 2-D [1, M] is likewise squeezed to 0-dim.
        let raw_shape = self.tensor_shape(input)?;
        let (input, n, m, single_var) = match raw_shape.len() {
            1 => {
                let m = raw_shape[0];
                let reshaped = self.tensor_reshape(input, vec![1, m])?;
                (reshaped, 1usize, m, true)
            }
            2 => {
                let n = raw_shape[0]; // variables
                let m = raw_shape[1]; // observations
                (input, n, m, n == 1)
            }
            _ => {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "cov: input must be a 1-D or 2-D tensor",
                    },
                )));
            }
        };
        if m < 2 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "cov: need at least 2 observations",
                },
            )));
        }

        // Read optional weights as length-M f64 vectors.
        let fw = match fweights {
            Some(t) => {
                let ws = self.tensor_shape(t)?;
                if ws.len() != 1 || ws[0] != m {
                    return Err(Self::incompatible_tensor_args(
                        "cov: fweights must be 1-D with length M",
                    ));
                }
                Some(self.tensor_values_lossy_f64(t)?)
            }
            None => None,
        };
        let aw = match aweights {
            Some(t) => {
                let ws = self.tensor_shape(t)?;
                if ws.len() != 1 || ws[0] != m {
                    return Err(Self::incompatible_tensor_args(
                        "cov: aweights must be 1-D with length M",
                    ));
                }
                Some(self.tensor_values_lossy_f64(t)?)
            }
            None => None,
        };
        // Combined weight w = fweights * aweights (or whichever is given).
        let w: Option<Vec<f64>> = match (&fw, &aw) {
            (Some(f), Some(a)) => Some(f.iter().zip(a).map(|(x, y)| x * y).collect()),
            (Some(f), None) => Some(f.clone()),
            (None, Some(a)) => Some(a.clone()),
            (None, None) => None,
        };

        // Normalization `fact` (numpy/torch.cov).
        #[allow(clippy::cast_precision_loss)]
        let corr = correction as f64;
        let fact = match (&w, &aw) {
            (None, _) => (m as f64) - corr,
            (Some(wv), None) => wv.iter().sum::<f64>() - corr,
            (Some(wv), Some(av)) => {
                let w_sum: f64 = wv.iter().sum();
                let w_dot_a: f64 = wv.iter().zip(av).map(|(x, y)| x * y).sum();
                w_sum - corr * w_dot_a / w_sum
            }
        };

        // Per-variable mean over observations (weighted if weights are present),
        // unsqueezed + expanded to [N, M] for broadcast subtraction.
        let means_bcast = if let Some(wv) = &w {
            let w_sum: f64 = wv.iter().sum();
            let wn: Vec<f64> = wv.iter().map(|x| x / w_sum).collect();
            let wn_node = self.cov_weight_tensor(&wn, input)?;
            let wn_row = self.tensor_unsqueeze(wn_node, 0)?;
            let wn_bcast = self.tensor_expand(wn_row, vec![n, m])?;
            let weighted = self.tensor_mul(input, wn_bcast)?;
            let avg = self.tensor_sum_dim(weighted, 1)?;
            let avg_unsq = self.tensor_unsqueeze(avg, 1)?;
            self.tensor_expand(avg_unsq, vec![n, m])?
        } else {
            let means = self.tensor_mean_dim(input, 1)?;
            let means_unsq = self.tensor_unsqueeze(means, 1)?;
            self.tensor_expand(means_unsq, vec![n, m])?
        };
        let centered = self.tensor_sub(input, means_bcast)?;

        // cov[i,k] = sum_j centered[i,j] * centered[k,j] * w[j] / fact.
        // The w factor scales one side; unweighted keeps centered as-is.
        let rhs = if let Some(wv) = &w {
            let w_node = self.cov_weight_tensor(wv, input)?;
            let w_row = self.tensor_unsqueeze(w_node, 0)?;
            let w_bcast = self.tensor_expand(w_row, vec![n, m])?;
            self.tensor_mul(centered, w_bcast)?
        } else {
            centered
        };
        let rhs_t = self.tensor_transpose(rhs, 0, 1)?;
        let outer = self.tensor_matmul(centered, rhs_t)?;
        // full_like(outer) so the divisor matches the input dtype and an f32
        // input yields an f32 covariance (frankentorch-fk5l).
        let denom = self.full_like(outer, fact, false)?;
        let cov = self.tensor_div(outer, denom)?;
        // Single variable -> torch returns the variance as a 0-dim scalar.
        let cov = if single_var {
            self.tensor_reshape(cov, vec![])?
        } else {
            cov
        };

        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!("cov input={} out={}", input.0, cov.0),
        );
        Ok(cov)
    }

    // ── corrcoef ────────────────────────────────────────────────────────
    /// Compute the Pearson correlation coefficient matrix.
    ///
    /// Equivalent to `torch.corrcoef(input)`.
    /// Input shape: `(N, M)`. Returns an `(N, N)` correlation matrix.
    ///
    /// Composes through tensor_cov + tensor_diagonal + tensor_sqrt +
    /// tensor_outer + tensor_div + tensor_eq + tensor_where so the
    /// autograd tape carries gradients through the input. Previously
    /// this delegated to tensor_cov, then extracted values and rebuilt
    /// a fresh requires_grad=false leaf — severing the tape after
    /// cov's autograd graph was built. Tracked under
    /// frankentorch-1tax.
    ///
    /// Math: corr[i,j] = cov[i,j] / sqrt(cov[i,i] * cov[j,j])
    ///                 = cov[i,j] / (sqrt(diag(cov))[i] * sqrt(diag(cov))[j])
    /// The latter form admits a clean composition via the outer
    /// product of sqrt(diag). When the denominator is zero (any
    /// variable with zero variance) the result is 0 — implemented
    /// via tensor_where masking.
    pub fn tensor_corrcoef(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        // Single variable (1-D [M] or 2-D [1, M]): torch returns a 0-dim scalar
        // = cov / sqrt(cov^2) = 1.0 for non-zero variance, NaN for zero variance.
        // cov() already squeezes the single-variable case to a 0-dim scalar, so
        // the [N,N] diagonal/outer composition below does not apply.
        let raw_shape = self.tensor_shape(input)?;
        if raw_shape.len() == 1 || (raw_shape.len() == 2 && raw_shape[0] == 1) {
            let cov = self.tensor_cov(input)?;
            let sq = self.tensor_mul(cov, cov)?;
            let denom = self.tensor_sqrt(sq)?;
            let out = self.tensor_div(cov, denom)?;
            self.runtime.ledger_mut().record(
                EvidenceKind::Dispatch,
                format!("corrcoef input={} out={}", input.0, out.0),
            );
            return Ok(out);
        }
        let cov = self.tensor_cov(input)?;

        let diag = self.tensor_diagonal(cov, 0)?;
        let diag_sqrt = self.tensor_sqrt(diag)?;
        let denom = self.tensor_outer(diag_sqrt, diag_sqrt)?;

        // corr_unsafe = cov / denom (NaN/inf at zero-variance entries).
        let corr_unsafe = self.tensor_div(cov, denom)?;

        // mask = (denom == 0); where mask is true, output 0.
        // Single shared zeros tensor across the eq mask and the
        // where-true branch (frankentorch-z3rb) — both ops only
        // READ their constant operand. -1 full() + -1 tape node;
        // saves an n² f64 allocation per call.
        // full_like(denom) so the zeros constant matches the input dtype: with
        // cov now f32-preserving, an f32 input yields an f32 corrcoef (torch
        // parity) and tensor_eq matches dtype. frankentorch-fk5l.
        let zeros = self.full_like(denom, 0.0, false)?;
        let mask = self.tensor_eq(denom, zeros)?;
        let out = self.tensor_where(mask, zeros, corr_unsafe)?;

        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!("corrcoef input={} out={}", input.0, out.0),
        );
        Ok(out)
    }

    // ── mode ────────────────────────────────────────────────────────────
    /// Return the mode (most frequent value) and its index along the last dimension.
    ///
    /// Equivalent to `torch.mode(input)`.
    /// Returns `(values, indices)` as a pair of tensors.
    /// Input must have at least one dimension and a non-zero last dimension.
    ///
    /// The values tensor composes through `tensor_gather` so the
    /// autograd tape carries gradients through the input — backward
    /// scatter-adds the incoming gradient at whichever input position
    /// holds the mode value. Previously this extracted tensor_values,
    /// computed both arrays in plain f64, and rebuilt fresh
    /// requires_grad=false leaves, severing the tape. Tracked under
    /// frankentorch-1tax. (The indices output is intrinsically
    /// non-differentiable, so it stays as a constant leaf — same
    /// convention as torch.mode.)
    ///
    /// Forward also switches the per-run-length comparison from
    /// `(a - b).abs() < f64::EPSILON` to IEEE `==`, matching the
    /// `tensor_unique` parity fix for value-binning behaviour. Among
    /// values that PyTorch / numpy treat as distinct (e.g. subnormals
    /// 5e-324 vs 1e-323), the previous heuristic would fuse them
    /// into a single run.
    pub fn tensor_mode(
        &mut self,
        input: TensorNodeId,
    ) -> Result<(TensorNodeId, TensorNodeId), AutogradError> {
        let shape = self.tensor_shape(input)?;
        if shape.is_empty() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "mode: input must have at least 1 dimension",
                },
            )));
        }
        let last_dim = shape[shape.len() - 1];
        if last_dim == 0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "mode: last dimension must be non-zero",
                },
            )));
        }
        let idxs_shape = if shape.len() > 1 {
            shape[..shape.len() - 1].to_vec()
        } else {
            vec![1]
        };

        let input_requires_grad = self.tensor_requires_grad(input)?;
        let input_dtype = self.tensor_dtype(input)?;
        let numel = Self::checked_shape_numel(&shape, "mode input shape volume overflow")?;
        if !input_requires_grad && input_dtype == DType::F64 && numel >= (1 << 13) {
            const MODE_COUNTING_KEYS: usize = 256;
            const MODE_COUNTING_MAX_KEY_F64: f64 = 255.0;

            // Borrow the contiguous f64 storage for the counting fast path. A
            // non-contiguous f64 node (e.g. a transposed/sliced view) can't be
            // borrowed zero-copy, so fall through to the layout-agnostic slow
            // path below rather than erroring — preserving the prior contract.
            let counted_modes = if let Ok(vals) = self.tensor_tape.values_borrowed(input) {
                let outer: usize = vals.len() / last_dim;
                #[allow(
                    clippy::cast_possible_truncation,
                    clippy::cast_precision_loss,
                    clippy::cast_sign_loss
                )]
                let compute_counting_mode = |o: usize| -> Option<(f64, f64)> {
                    let slice = &vals[o * last_dim..(o + 1) * last_dim];
                    let mut counts = [0u32; MODE_COUNTING_KEYS];
                    let mut last_seen = [0usize; MODE_COUNTING_KEYS];
                    let mut max_key = 0usize;
                    for (idx, &value) in slice.iter().enumerate() {
                        if !value.is_finite()
                            || !(0.0..=MODE_COUNTING_MAX_KEY_F64).contains(&value)
                            || value.fract() != 0.0
                        {
                            return None;
                        }
                        let key = value as usize;
                        counts[key] += 1;
                        last_seen[key] = idx;
                        max_key = max_key.max(key);
                    }

                    let mut best_key = 0usize;
                    let mut best_count = 0u32;
                    for (key, &count) in counts[..=max_key].iter().enumerate() {
                        if count > best_count {
                            best_key = key;
                            best_count = count;
                        }
                    }
                    Some((best_key as f64, last_seen[best_key] as f64))
                };

                let mode_pairs: Vec<Option<(f64, f64)>> = if outer >= 2 {
                    use rayon::prelude::*;
                    (0..outer)
                        .into_par_iter()
                        .map(compute_counting_mode)
                        .collect()
                } else {
                    (0..outer).map(compute_counting_mode).collect()
                };

                let mut mode_vals = Vec::with_capacity(outer);
                let mut mode_idxs = Vec::with_capacity(outer);
                let mut bounded = true;
                for pair in mode_pairs {
                    if let Some((value, idx)) = pair {
                        mode_vals.push(value);
                        mode_idxs.push(idx);
                    } else {
                        bounded = false;
                        break;
                    }
                }

                if bounded {
                    Some((mode_vals, mode_idxs))
                } else {
                    None
                }
            } else {
                None
            };

            if let Some((mode_vals, mode_idxs)) = counted_modes {
                let vals_out = self
                    .tensor_tape
                    .leaf(mode_vals, idxs_shape.clone(), false)?;
                let idxs_out = self.tensor_tape.leaf(mode_idxs, idxs_shape, false)?;
                self.runtime.ledger_mut().record(
                    EvidenceKind::Dispatch,
                    format!(
                        "mode_counting input={} vals={} idxs={} key_range=0..255",
                        input.0, vals_out.0, idxs_out.0
                    ),
                );
                return Ok((vals_out, idxs_out));
            }
        }

        // F32 counting fast path — mirrors the f64 path exactly but on the f32 storage.
        // torch.mode(f32) is sort-based and slow just like the f64 case, and FT's f32 mode
        // otherwise upcasts to f64 and sorts. Borrow the contiguous f32 storage zero-copy,
        // compute the mode per lane via a 256-bucket histogram (O(n) vs the sort), and
        // build the value output as a DIRECT f32 leaf from the winning key (bounded integers
        // 0..=255 are exactly representable in f32, so `best_key as f32` IS the modal value
        // torch returns — no gather needed, keeping the path allocation-light). Index
        // tie-break is identical to the slow sort path (last occurrence of the smallest-value
        // max-count key), so values AND indices are bit-identical. Any out-of-range /
        // non-integer / non-finite value, or a non-contiguous view, falls through to the
        // unchanged slow path.
        if !input_requires_grad && input_dtype == DType::F32 && numel >= (1 << 13) {
            const MODE_COUNTING_KEYS: usize = 256;
            const MODE_COUNTING_MAX_KEY_F32: f32 = 255.0;

            let counted_modes = if let Ok(vals) = self.tensor_tape.values_f32_borrowed(input) {
                let outer: usize = vals.len() / last_dim;
                #[allow(
                    clippy::cast_possible_truncation,
                    clippy::cast_precision_loss,
                    clippy::cast_sign_loss
                )]
                let compute_counting_mode = |o: usize| -> Option<(f32, f64)> {
                    let slice = &vals[o * last_dim..(o + 1) * last_dim];
                    let mut counts = [0u32; MODE_COUNTING_KEYS];
                    let mut last_seen = [0usize; MODE_COUNTING_KEYS];
                    let mut max_key = 0usize;
                    for (idx, &value) in slice.iter().enumerate() {
                        if !value.is_finite()
                            || !(0.0..=MODE_COUNTING_MAX_KEY_F32).contains(&value)
                            || value.fract() != 0.0
                        {
                            return None;
                        }
                        let key = value as usize;
                        counts[key] += 1;
                        last_seen[key] = idx;
                        max_key = max_key.max(key);
                    }
                    let mut best_key = 0usize;
                    let mut best_count = 0u32;
                    for (key, &count) in counts[..=max_key].iter().enumerate() {
                        if count > best_count {
                            best_key = key;
                            best_count = count;
                        }
                    }
                    Some((best_key as f32, last_seen[best_key] as f64))
                };

                let mode_pairs: Vec<Option<(f32, f64)>> = if outer >= 2 {
                    use rayon::prelude::*;
                    (0..outer)
                        .into_par_iter()
                        .map(compute_counting_mode)
                        .collect()
                } else {
                    (0..outer).map(compute_counting_mode).collect()
                };

                let mut mode_vals = Vec::with_capacity(outer);
                let mut mode_idxs = Vec::with_capacity(outer);
                let mut bounded = true;
                for pair in mode_pairs {
                    if let Some((value, idx)) = pair {
                        mode_vals.push(value);
                        mode_idxs.push(idx);
                    } else {
                        bounded = false;
                        break;
                    }
                }

                if bounded {
                    Some((mode_vals, mode_idxs))
                } else {
                    None
                }
            } else {
                None
            };

            if let Some((mode_vals, mode_idxs)) = counted_modes {
                let vals_out = self
                    .tensor_tape
                    .leaf_f32(mode_vals, idxs_shape.clone(), false)?;
                let idxs_out = self.tensor_tape.leaf(mode_idxs, idxs_shape, false)?;
                self.runtime.ledger_mut().record(
                    EvidenceKind::Dispatch,
                    format!(
                        "mode_counting_f32 input={} vals={} idxs={} key_range=0..255",
                        input.0, vals_out.0, idxs_out.0
                    ),
                );
                return Ok((vals_out, idxs_out));
            }
        }

        let vals = self.tensor_values_lossy_f64(input)?;
        let outer: usize = vals.len() / last_dim;

        // Compute the mode position in each outer slice. The position
        // is non-differentiable (sort + count), so this stays in
        // plain f64; the autograd composition then uses gather on
        // these pre-computed indices to extract values from `input`.
        // Each outer slice is an INDEPENDENT O(last_dim log last_dim) sort + run-length
        // count; the slices share nothing, so fan them over Rayon (each lane's sort +
        // count is deterministic, and `collect()` preserves the `o` order, so the result
        // is identical to the serial loop). torch.mode parallelizes this; FT was serial.
        #[allow(clippy::cast_precision_loss)]
        let compute_mode = |o: usize| -> f64 {
            let slice = &vals[o * last_dim..(o + 1) * last_dim];
            let mut sorted: Vec<(f64, usize)> = slice
                .iter()
                .copied()
                .enumerate()
                .map(|(i, v)| (v, i))
                .collect();
            sorted.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal));

            let mut best_idx = sorted[0].1;
            let mut best_count = 1usize;
            let mut cur_count = 1usize;
            for i in 1..sorted.len() {
                if sorted[i].0 == sorted[i - 1].0 {
                    cur_count += 1;
                } else {
                    cur_count = 1;
                }
                if cur_count > best_count {
                    best_count = cur_count;
                    best_idx = sorted[i].1;
                }
            }
            best_idx as f64
        };
        let mode_idxs: Vec<f64> = if outer >= 2 && vals.len() >= (1 << 13) {
            use rayon::prelude::*;
            (0..outer).into_par_iter().map(compute_mode).collect()
        } else {
            (0..outer).map(compute_mode).collect()
        };

        // Build a same-rank index tensor that selects the mode
        // position along the last dim of `input`. tensor_gather
        // requires the index to have the same rank as the input
        // with size 1 along the gathered dim and matching sizes
        // elsewhere.
        let mut index_shape: Vec<usize> = shape[..shape.len() - 1].to_vec();
        index_shape.push(1);
        let dim = shape.len() - 1;
        let index_node = self
            .tensor_tape
            .leaf(mode_idxs.clone(), index_shape, false)?;
        let gathered = self.tensor_gather(input, dim, index_node)?;

        // Output shape: rank-1 input keeps shape [1] (matching the
        // pre-fix contract); rank >= 2 squeezes the last dim away.
        let vals_out = if shape.len() > 1 {
            self.tensor_squeeze(gathered, dim)?
        } else {
            gathered
        };

        let idxs_out = self.tensor_tape.leaf(mode_idxs, idxs_shape, false)?;
        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!(
                "mode input={} vals={} idxs={}",
                input.0, vals_out.0, idxs_out.0
            ),
        );
        Ok((vals_out, idxs_out))
    }

    // ── quantile ────────────────────────────────────────────────────────
    /// Compute the q-th quantile of the flattened tensor.
    ///
    /// Equivalent to `torch.quantile(input, q)`.
    /// `q` should be in [0, 1]. Uses linear interpolation between data points.
    ///
    /// Composes through `tensor_reshape`, `tensor_sort`,
    /// `tensor_narrow`, and `tensor_lerp` so the autograd tape
    /// carries gradients through the input. The lo and hi
    /// interpolation positions are picked out by narrow whose
    /// backward scatters the incoming gradient back through the sort
    /// permutation, landing on whichever original input positions
    /// held those order statistics. Previously this extracted
    /// `tensor_values` and rebuilt a fresh `requires_grad=false`
    /// leaf, severing the tape. Tracked under frankentorch-1tax.
    pub fn tensor_quantile(
        &mut self,
        input: TensorNodeId,
        q: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_quantile_interpolation(input, q, "linear")
    }

    /// `torch.quantile(input, q, interpolation=...)` with a selectable
    /// interpolation method between the two order statistics bracketing the
    /// fractional index `idx = q*(n-1)`:
    /// - `"linear"` (default): `lo + frac*(hi - lo)`.
    /// - `"lower"`: the lower order statistic (`sorted[floor(idx)]`).
    /// - `"higher"`: the upper order statistic (`sorted[ceil(idx)]`).
    /// - `"nearest"`: `sorted[round_half_to_even(idx)]` (torch rounds index ties
    ///   to even, verified vs torch 2.12).
    /// - `"midpoint"`: `(lo + hi) / 2`.
    ///
    /// All modes compose through `tensor_sort`/`tensor_narrow`/`tensor_lerp`, so
    /// gradients flow back to the input: lower/higher/nearest route to the single
    /// selected order statistic; midpoint splits 0.5/0.5; linear splits
    /// (1-frac)/frac.
    pub fn tensor_quantile_interpolation(
        &mut self,
        input: TensorNodeId,
        q: f64,
        interpolation: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        if !matches!(
            interpolation,
            "linear" | "lower" | "higher" | "nearest" | "midpoint"
        ) {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "quantile: interpolation must be one of linear, lower, higher, nearest, midpoint",
                },
            )));
        }
        if !(0.0..=1.0).contains(&q) {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "quantile: q must be in [0, 1]",
                },
            )));
        }
        let shape = self.tensor_shape(input)?;
        let n = Self::checked_shape_numel(&shape, "quantile: input shape volume overflow")?;
        if n == 0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "quantile: input must not be empty",
                },
            )));
        }

        // PyTorch propagates NaN through quantile: any NaN in the
        // input yields NaN output. Detect that up-front via a
        // values peek (no autograd contract — the result is
        // constant NaN regardless of input position) and short-
        // circuit so the autograd composition below doesn't have
        // to reason about NaN through partial_cmp.
        // Lossy read so f32 inputs are accepted; the composed path below
        // (reshape/sort/narrow/lerp) preserves the input dtype. frankentorch-z71u.
        let vals_for_nan_check = self.tensor_values_lossy_f64(input)?;
        if vals_for_nan_check.iter().any(|v| v.is_nan()) {
            let out = self.scalar_leaf_matching_dtype(input, f64::NAN)?;
            self.runtime.ledger_mut().record(
                EvidenceKind::Dispatch,
                format!("quantile input={} q={q} out={} nan=true", input.0, out.0),
            );
            return Ok(out);
        }

        let flat = self.tensor_reshape(input, vec![n])?;
        // The selected order statistic(s) are found via quickselect
        // (tensor_kthvalue, O(n)) instead of a full sort (O(n log n)). Each
        // kthvalue returns the bit-exact order-statistic value and routes the
        // gradient to that element's original position via index_select — same
        // observable value and (for unique values) the same single/split gradient
        // as the previous sort+narrow. frankentorch-kgs4.58.

        if n == 1 {
            // Trivial: only one value.
            let out = self.tensor_kthvalue(flat, 1)?.0;
            self.runtime.ledger_mut().record(
                EvidenceKind::Dispatch,
                format!("quantile input={} q={q} out={}", input.0, out.0),
            );
            return Ok(out);
        }

        #[allow(clippy::cast_precision_loss)]
        let idx = q * (n - 1) as f64;
        #[allow(clippy::cast_possible_truncation, clippy::cast_sign_loss)]
        let lo = idx.floor() as usize;
        #[allow(clippy::cast_possible_truncation, clippy::cast_sign_loss)]
        let hi = idx.ceil() as usize;
        let frac = idx - lo as f64;

        let out = if lo == hi {
            // q lands exactly on an index — every interpolation mode returns that
            // single order statistic.
            self.tensor_kthvalue(flat, lo + 1)?.0
        } else {
            match interpolation {
                "lower" => self.tensor_kthvalue(flat, lo + 1)?.0,
                "higher" => self.tensor_kthvalue(flat, hi + 1)?.0,
                "nearest" => {
                    // torch rounds the fractional index half-to-even.
                    #[allow(clippy::cast_possible_truncation, clippy::cast_sign_loss)]
                    let ni = idx.round_ties_even() as usize;
                    self.tensor_kthvalue(flat, ni + 1)?.0
                }
                "midpoint" => {
                    let lo_val = self.tensor_kthvalue(flat, lo + 1)?.0;
                    let hi_val = self.tensor_kthvalue(flat, hi + 1)?.0;
                    self.tensor_lerp(lo_val, hi_val, 0.5)?
                }
                // "linear" (default)
                _ => {
                    let lo_val = self.tensor_kthvalue(flat, lo + 1)?.0;
                    let hi_val = self.tensor_kthvalue(flat, hi + 1)?.0;
                    self.tensor_lerp(lo_val, hi_val, frac)?
                }
            }
        };

        self.runtime.ledger_mut().record(
            EvidenceKind::Dispatch,
            format!(
                "quantile input={} q={q} interp={interpolation} out={}",
                input.0, out.0
            ),
        );
        Ok(out)
    }

    /// The k-th (0-indexed) order statistic of every slice along `dim`, returned
    /// keepdim ([.., 1, ..]). Per slice this quickselects the rank-k value in O(d)
    /// (vs a full sort O(d log d)) and resolves the ORIGINAL index to exactly match
    /// a stable ascending `total_cmp` sort: `offset = k - #strictly-less`, then the
    /// `offset`-th original index among elements equal to the rank-k value (ascending
    /// index = stable order). A `tensor_gather` on those indices makes the value
    /// autograd-aware (grad routes to the selected element's original position).
    /// frankentorch-kgs4.59.
    fn kth_order_statistic_keepdim(
        &mut self,
        input: TensorNodeId,
        dim: usize,
        k: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        use rayon::prelude::*;
        use std::cmp::Ordering;
        let shape = self.tensor_shape(input)?;
        let dim_size = shape[dim];
        let inner: usize = shape[dim + 1..].iter().product();
        let outer: usize = shape[..dim].iter().product();
        let vals = self.tensor_values_lossy_f64(input)?;
        let mut index_vec = vec![0.0f64; outer * inner];
        index_vec.par_iter_mut().enumerate().for_each(|(oi, slot)| {
            let o = oi / inner;
            let i = oi % inner;
            let base = o * dim_size * inner + i;
            let mut lane: Vec<f64> = (0..dim_size).map(|d| vals[base + d * inner]).collect();
            let (_, kv_ref, _) = lane.select_nth_unstable_by(k, |a, b| a.total_cmp(b));
            let kv = *kv_ref;
            let less = (0..dim_size)
                .filter(|&d| vals[base + d * inner].total_cmp(&kv) == Ordering::Less)
                .count();
            let off = k - less;
            let idx = (0..dim_size)
                .filter(|&d| vals[base + d * inner].total_cmp(&kv) == Ordering::Equal)
                .nth(off)
                .expect("rank-k order statistic must exist after quickselect");
            #[allow(clippy::cast_precision_loss)]
            {
                *slot = idx as f64;
            }
        });
        let mut idx_shape = shape;
        idx_shape[dim] = 1;
        let index_node = self.tensor_tape.leaf(index_vec, idx_shape, false)?;
        self.tensor_gather(input, dim, index_node)
    }

    fn quantile_rank_plan(
        qs: &[f64],
        dim_size: usize,
        interpolation: &str,
    ) -> (Vec<usize>, Vec<(usize, usize, f64)>) {
        let mut raw = Vec::with_capacity(qs.len());
        let mut ranks = Vec::with_capacity(qs.len() * 2);
        for &q in qs {
            #[allow(clippy::cast_precision_loss)]
            let idx = q * (dim_size - 1) as f64;
            #[allow(clippy::cast_possible_truncation, clippy::cast_sign_loss)]
            let lo = idx.floor() as usize;
            #[allow(clippy::cast_possible_truncation, clippy::cast_sign_loss)]
            let hi = idx.ceil() as usize;
            let frac = idx - lo as f64;
            let (a, b, w) = if lo == hi {
                (lo, lo, 0.0)
            } else {
                match interpolation {
                    "lower" => (lo, lo, 0.0),
                    "higher" => (hi, hi, 0.0),
                    "nearest" => {
                        #[allow(clippy::cast_possible_truncation, clippy::cast_sign_loss)]
                        let ni = idx.round_ties_even() as usize;
                        (ni, ni, 0.0)
                    }
                    "midpoint" => (lo, hi, 0.5),
                    _ => (lo, hi, frac),
                }
            };
            ranks.push(a);
            ranks.push(b);
            raw.push((a, b, w));
        }
        ranks.sort_unstable();
        ranks.dedup();
        let plan = raw
            .into_iter()
            .map(|(a, b, w)| {
                let a_pos = ranks
                    .binary_search(&a)
                    .expect("quantile rank must be present in rank plan");
                let b_pos = ranks
                    .binary_search(&b)
                    .expect("quantile rank must be present in rank plan");
                (a_pos, b_pos, w)
            })
            .collect();
        (ranks, plan)
    }

    fn select_sorted_ranks_in_place(values: &mut [f64], ranks: &[usize], out: &mut [f64]) {
        fn recurse(values: &mut [f64], ranks: &[usize], base_rank: usize, out: &mut [f64]) {
            if ranks.is_empty() {
                return;
            }
            let mid = ranks.len() / 2;
            let rank = ranks[mid];
            let local_rank = rank - base_rank;
            let (_, pivot, _) = values.select_nth_unstable_by(local_rank, |a, b| a.total_cmp(b));
            out[mid] = *pivot;
            let (left, rest) = values.split_at_mut(local_rank);
            let right = &mut rest[1..];
            recurse(left, &ranks[..mid], base_rank, &mut out[..mid]);
            recurse(right, &ranks[mid + 1..], rank + 1, &mut out[mid + 1..]);
        }
        recurse(values, ranks, 0, out);
    }

    fn tensor_quantile_dim_multi_nograd_f64(
        &mut self,
        input: TensorNodeId,
        qs: &[f64],
        dim: usize,
        keepdim: bool,
        interpolation: &str,
        shape: &[usize],
    ) -> Result<TensorNodeId, AutogradError> {
        use rayon::prelude::*;
        let dim_size = shape[dim];
        let inner: usize = shape[dim + 1..].iter().product();
        let outer: usize = shape[..dim].iter().product();
        let lanes = outer * inner;
        // Borrow the contiguous f64 input zero-copy — the full-numel `tensor_values`
        // clone (128MB at [4000,4000]) dominated this no-grad fast path (mode's counting
        // path is ~20x faster at the same size precisely because it borrows). Fall back
        // to an owned clone only for a non-contiguous f64 view. The borrow ends (NLL) at
        // its last use in the per-lane loops below, before the `&mut self` output build.
        let vals_storage: std::borrow::Cow<[f64]> = match self.tensor_tape.values_borrowed(input) {
            Ok(v) => std::borrow::Cow::Borrowed(v),
            Err(_) => std::borrow::Cow::Owned(self.tensor_values(input)?),
        };
        let vals: &[f64] = &vals_storage;
        let (ranks, plan) = Self::quantile_rank_plan(qs, dim_size, interpolation);
        let mut lane_major = vec![0.0_f64; lanes * qs.len()];

        // Bounded-integer counting fast path. torch.quantile always sorts each lane
        // (O(d log d)) regardless of the data; when every value is a finite integer in
        // [0,255] the order statistics come from a 256-bucket histogram + prefix-sum in
        // O(d + 256) per lane with NO partition. The r-th order statistic of a multiset
        // is a unique value, so this is bit-identical to the quickselect path (and the
        // interpolation arithmetic below is unchanged). Any non-integer / out-of-range /
        // non-finite value (incl. NaN) drops the whole reduction back to quickselect,
        // which keeps the per-lane NaN-fill semantics. `ranks` is sorted ascending +
        // deduped, so one cumulative histogram walk fills `selected` in rank order.
        let bounded = {
            use rayon::prelude::*;
            // `v != 0.0 || v.is_sign_positive()` rejects -0.0: the quickselect path
            // would emit the actual -0.0 bit for a zero order statistic, but the
            // counting path emits `0u as f64` = +0.0, so excluding -0.0 keeps the
            // fast path bit-identical.
            vals.par_iter().all(|&v| {
                v.is_finite()
                    && (0.0..=255.0).contains(&v)
                    && v.fract() == 0.0
                    && (v != 0.0 || v.is_sign_positive())
            })
        };

        if bounded {
            lane_major
                .par_chunks_mut(qs.len())
                .enumerate()
                .for_each(|(lane_idx, out_chunk)| {
                    let outer_idx = lane_idx / inner;
                    let inner_idx = lane_idx % inner;
                    let base = outer_idx * dim_size * inner + inner_idx;
                    let mut hist = [0u32; 256];
                    for d in 0..dim_size {
                        // global check above guarantees an in-range integer key
                        #[allow(clippy::cast_possible_truncation, clippy::cast_sign_loss)]
                        let key = vals[base + d * inner] as usize;
                        hist[key] += 1;
                    }
                    let mut selected = vec![0.0_f64; ranks.len()];
                    let mut cum = 0u32;
                    let mut ri = 0usize;
                    for (value, &count) in hist.iter().enumerate() {
                        if ri == ranks.len() {
                            break;
                        }
                        cum += count;
                        while ri < ranks.len() && ranks[ri] < cum as usize {
                            #[allow(clippy::cast_precision_loss)]
                            {
                                selected[ri] = value as f64;
                            }
                            ri += 1;
                        }
                    }
                    for (q_idx, &(a_pos, b_pos, weight)) in plan.iter().enumerate() {
                        let a = selected[a_pos];
                        let b = selected[b_pos];
                        out_chunk[q_idx] = if a_pos == b_pos {
                            a
                        } else {
                            a + weight * (b - a)
                        };
                    }
                });
        } else {
            lane_major
                .par_chunks_mut(qs.len())
                .enumerate()
                .for_each(|(lane_idx, out_chunk)| {
                    let outer_idx = lane_idx / inner;
                    let inner_idx = lane_idx % inner;
                    let base = outer_idx * dim_size * inner + inner_idx;
                    let mut lane = Vec::with_capacity(dim_size);
                    for d in 0..dim_size {
                        let value = vals[base + d * inner];
                        if value.is_nan() {
                            out_chunk.fill(f64::NAN);
                            return;
                        }
                        lane.push(value);
                    }
                    let mut selected = vec![0.0_f64; ranks.len()];
                    Self::select_sorted_ranks_in_place(&mut lane, &ranks, &mut selected);
                    for (q_idx, &(a_pos, b_pos, weight)) in plan.iter().enumerate() {
                        let a = selected[a_pos];
                        let b = selected[b_pos];
                        out_chunk[q_idx] = if a_pos == b_pos {
                            a
                        } else {
                            a + weight * (b - a)
                        };
                    }
                });
        }

        let mut out = vec![0.0_f64; lane_major.len()];
        for lane_idx in 0..lanes {
            for q_idx in 0..qs.len() {
                out[q_idx * lanes + lane_idx] = lane_major[lane_idx * qs.len() + q_idx];
            }
        }

        let mut out_shape = Vec::with_capacity(shape.len() + 1);
        out_shape.push(qs.len());
        if keepdim {
            out_shape.extend(
                shape
                    .iter()
                    .enumerate()
                    .map(|(axis, &extent)| if axis == dim { 1 } else { extent }),
            );
        } else {
            out_shape.extend_from_slice(&shape[..dim]);
            out_shape.extend_from_slice(&shape[dim + 1..]);
        }
        self.tensor_variable(out, out_shape, false)
    }

    /// `torch.quantile(input, q, dim, keepdim, interpolation)`: the scalar
    /// quantile `q` taken along `dim` (one value per slice), with the same five
    /// interpolation modes as [`Self::tensor_quantile_interpolation`]. When
    /// `keepdim` is true the reduced dimension is kept as size 1, else it is
    /// removed. A slice containing any NaN yields NaN (torch propagates NaN —
    /// use nanquantile to ignore NaNs).
    ///
    /// Composes through `tensor_sort`/`tensor_narrow`/`tensor_lerp` along `dim`:
    /// after sorting, the k-th order statistic of every slice sits at index `k`
    /// along `dim`, so a single `narrow` selects it for all slices at once. Fully
    /// autograd-aware; gradients route through the per-slice sort permutation to
    /// the original positions of the selected order statistics.
    pub fn tensor_quantile_dim(
        &mut self,
        input: TensorNodeId,
        q: f64,
        dim: usize,
        keepdim: bool,
        interpolation: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        if !matches!(
            interpolation,
            "linear" | "lower" | "higher" | "nearest" | "midpoint"
        ) {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "quantile: interpolation must be one of linear, lower, higher, nearest, midpoint",
                },
            )));
        }
        if !(0.0..=1.0).contains(&q) {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "quantile: q must be in [0, 1]",
                },
            )));
        }
        let shape = self.tensor_shape(input)?;
        let ndim = shape.len();
        if dim >= ndim {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                ft_kernel_cpu::KernelError::InvalidDimension { dim, ndim },
            )));
        }
        let n = shape[dim];
        if n == 0 {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "quantile: reduction dim must be non-empty",
                },
            )));
        }

        // No-grad f64 fast path: reuse the parallel per-lane quickselect kernel
        // (`tensor_quantile_dim_multi_nograd_f64`) with a single quantile, instead of the
        // autograd `kth_order_statistic_keepdim` composition which builds tape nodes per
        // order statistic even with grad off (≈6x slower on big slices). Same value + NaN
        // semantics (the multi path NaN-fills any slice with a NaN). frankentorch-qntl.
        if !self.tensor_requires_grad(input)? && self.tensor_dtype(input)? == DType::F64 {
            let out = self.tensor_quantile_dim_multi_nograd_f64(
                input,
                &[q],
                dim,
                keepdim,
                interpolation,
                &shape,
            )?;
            // The multi path prepends a length-`qs.len()`=1 axis; drop it for the scalar form.
            return self.tensor_squeeze(out, 0);
        }

        // Pick the bracketing order statistic(s) via per-slice quickselect
        // (kth_order_statistic_keepdim, O(d) per slice) instead of a full sort along
        // `dim` (O(d log d)). Each returns the keepdim value with the gradient routed
        // to the original position via gather — same observable value and (for unique
        // values) the same single/split gradient as the old sort+narrow.
        let result_kd = if n == 1 {
            self.kth_order_statistic_keepdim(input, dim, 0)?
        } else {
            #[allow(clippy::cast_precision_loss)]
            let idx = q * (n - 1) as f64;
            #[allow(clippy::cast_possible_truncation, clippy::cast_sign_loss)]
            let lo = idx.floor() as usize;
            #[allow(clippy::cast_possible_truncation, clippy::cast_sign_loss)]
            let hi = idx.ceil() as usize;
            let frac = idx - lo as f64;
            if lo == hi {
                self.kth_order_statistic_keepdim(input, dim, lo)?
            } else {
                match interpolation {
                    "lower" => self.kth_order_statistic_keepdim(input, dim, lo)?,
                    "higher" => self.kth_order_statistic_keepdim(input, dim, hi)?,
                    "nearest" => {
                        #[allow(clippy::cast_possible_truncation, clippy::cast_sign_loss)]
                        let ni = idx.round_ties_even() as usize;
                        self.kth_order_statistic_keepdim(input, dim, ni)?
                    }
                    "midpoint" => {
                        let lo_v = self.kth_order_statistic_keepdim(input, dim, lo)?;
                        let hi_v = self.kth_order_statistic_keepdim(input, dim, hi)?;
                        self.tensor_lerp(lo_v, hi_v, 0.5)?
                    }
                    // "linear" (default)
                    _ => {
                        let lo_v = self.kth_order_statistic_keepdim(input, dim, lo)?;
                        let hi_v = self.kth_order_statistic_keepdim(input, dim, hi)?;
                        self.tensor_lerp(lo_v, hi_v, frac)?
                    }
                }
            }
        };

        // Per-slice NaN propagation: flag slices containing any NaN (max over
        // isnan along dim, keepdim-aligned with result_kd) and overwrite them
        // with NaN. The where blocks gradient flow through NaN slices.
        let nan_mask = self.tensor_isnan(input)?;
        let nan_kd = self.max_keepdim(nan_mask, dim)?;
        let nan_const = self.full_like(result_kd, f64::NAN, false)?;
        let masked = self.tensor_where(nan_kd, nan_const, result_kd)?;

        if keepdim {
            Ok(masked)
        } else {
            self.tensor_squeeze(masked, dim)
        }
    }

    /// `torch.quantile(input, q)` where `q` is a 1-D set of quantiles over the
    /// flattened input. Returns a tensor of shape `[qs.len()]` (the i-th entry
    /// is the `qs[i]`-quantile), matching torch's q-as-tensor form. Each
    /// quantile reuses the autograd-aware scalar path and the results are
    /// concatenated, so gradients flow back to the input.
    pub fn tensor_quantile_multi(
        &mut self,
        input: TensorNodeId,
        qs: &[f64],
        interpolation: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        if qs.is_empty() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "quantile: q must contain at least one value",
                },
            )));
        }
        // Sort-once fast path. The per-q loop below quickselects (kthvalue) the lo
        // AND hi order statistics PER q — for k quantiles on a large input that is
        // 2k quickselects + 2k full clones, measured ~1.8x SLOWER than torch (which
        // sorts ONCE). Here we sort once (parallel radix via tensor_sort) and read
        // each q's order statistic(s) by narrowing the sorted tensor, reusing the
        // SAME tensor_lerp as the loop — so values are bit-for-bit identical. Gated
        // no-grad (the loop's index_select gradient routing is bypassed), NaN-free
        // (torch propagates NaN — the loop handles it), and negative-zero-free (the
        // radix key canonicalizes -0.0/+0.0, whose tie order can differ from the
        // loop's total_cmp). Small / few-q / invalid-arg cases fall through.
        let interp_valid = matches!(
            interpolation,
            "linear" | "lower" | "higher" | "nearest" | "midpoint"
        );
        let n = Self::checked_shape_numel(
            &self.tensor_shape(input)?,
            "quantile: input shape volume overflow",
        )?;
        if qs.len() >= 3
            && n >= 8192
            && interp_valid
            && !self.tensor_requires_grad(input)?
            && qs.iter().all(|&q| (0.0..=1.0).contains(&q))
        {
            let scan = self.tensor_values_lossy_f64(input)?;
            let bad = scan
                .iter()
                .any(|v| v.is_nan() || (*v == 0.0 && v.is_sign_negative()));
            if !bad {
                let flat = self.tensor_reshape(input, vec![n])?;
                let (sorted_node, _idx) = self.tensor_sort(flat, 0, false)?;
                let mut parts = Vec::with_capacity(qs.len());
                for &q in qs {
                    parts.push(self.quantile_part_from_sorted(sorted_node, n, q, interpolation)?);
                }
                return self.tensor_cat(&parts, 0);
            }
        }
        // Each scalar quantile over the flattened input is a [1] tensor;
        // concatenating along dim 0 yields the torch [len(q)] vector.
        let mut parts = Vec::with_capacity(qs.len());
        for &q in qs {
            parts.push(self.tensor_quantile_interpolation(input, q, interpolation)?);
        }
        self.tensor_cat(&parts, 0)
    }

    /// One quantile's `[1]` result read from an already-ascending-sorted tensor,
    /// using the SAME index math + `tensor_lerp` as `tensor_quantile_interpolation`
    /// (order statistic `sorted[k]` == `kthvalue(k+1)`), so it is bit-for-bit
    /// identical to the per-q quickselect path. Used by the multi-q sort-once path.
    fn quantile_part_from_sorted(
        &mut self,
        sorted: TensorNodeId,
        n: usize,
        q: f64,
        interpolation: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        if n == 1 {
            return self.tensor_narrow(sorted, 0, 0, 1);
        }
        #[allow(clippy::cast_precision_loss)]
        let idx = q * (n - 1) as f64;
        #[allow(clippy::cast_possible_truncation, clippy::cast_sign_loss)]
        let lo = idx.floor() as usize;
        #[allow(clippy::cast_possible_truncation, clippy::cast_sign_loss)]
        let hi = idx.ceil() as usize;
        let frac = idx - lo as f64;
        if lo == hi {
            return self.tensor_narrow(sorted, 0, lo, 1);
        }
        match interpolation {
            "lower" => self.tensor_narrow(sorted, 0, lo, 1),
            "higher" => self.tensor_narrow(sorted, 0, hi, 1),
            "nearest" => {
                #[allow(clippy::cast_possible_truncation, clippy::cast_sign_loss)]
                let ni = idx.round_ties_even() as usize;
                self.tensor_narrow(sorted, 0, ni, 1)
            }
            "midpoint" => {
                let lo_val = self.tensor_narrow(sorted, 0, lo, 1)?;
                let hi_val = self.tensor_narrow(sorted, 0, hi, 1)?;
                self.tensor_lerp(lo_val, hi_val, 0.5)
            }
            // "linear" (default)
            _ => {
                let lo_val = self.tensor_narrow(sorted, 0, lo, 1)?;
                let hi_val = self.tensor_narrow(sorted, 0, hi, 1)?;
                self.tensor_lerp(lo_val, hi_val, frac)
            }
        }
    }

    /// `torch.quantile(input, q, dim, keepdim, interpolation)` where `q` is a
    /// 1-D set of quantiles. The output gains a NEW leading dimension of length
    /// `qs.len()` in front of the per-slice reduced shape (torch's q-tensor
    /// contract), e.g. `quantile([2,4], [0.25,0.75], dim=1)` -> `[2, 2]` and
    /// with `keepdim` -> `[2, 2, 1]`. Stacks the autograd-aware scalar-q
    /// results, so gradients flow to the input.
    pub fn tensor_quantile_dim_multi(
        &mut self,
        input: TensorNodeId,
        qs: &[f64],
        dim: usize,
        keepdim: bool,
        interpolation: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        if qs.is_empty() {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "quantile: q must contain at least one value",
                },
            )));
        }
        if !matches!(
            interpolation,
            "linear" | "lower" | "higher" | "nearest" | "midpoint"
        ) {
            return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                ft_dispatch::DispatchKeyError::IncompatibleSet {
                    reason: "quantile: interpolation must be one of linear, lower, higher, nearest, midpoint",
                },
            )));
        }
        if qs.iter().all(|q| (0.0..=1.0).contains(q)) {
            let shape = self.tensor_shape(input)?;
            let ndim = shape.len();
            if dim >= ndim {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(
                    ft_kernel_cpu::KernelError::InvalidDimension { dim, ndim },
                )));
            }
            if shape[dim] == 0 {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "quantile: reduction dim must be non-empty",
                    },
                )));
            }
            if !self.tensor_requires_grad(input)? && self.tensor_dtype(input)? == DType::F64 {
                return self.tensor_quantile_dim_multi_nograd_f64(
                    input,
                    qs,
                    dim,
                    keepdim,
                    interpolation,
                    &shape,
                );
            }
        }
        let mut parts = Vec::with_capacity(qs.len());
        for &q in qs {
            parts.push(self.tensor_quantile_dim(input, q, dim, keepdim, interpolation)?);
        }
        // The q values become a new leading axis: stack along dim 0.
        self.tensor_stack(&parts, 0)
    }

    // ── Sparse Tensor Operations ───────────────────────────────────────────

    /// Create a sparse COO tensor from coordinates and values.
    ///
    /// # Arguments
    /// * `coords` - List of coordinate tuples, each of length equal to sparse_dim
    /// * `values` - Values at each coordinate
    /// * `dense_shape` - The full dense shape this sparse tensor represents
    /// * `dtype` - Data type for the values
    ///
    /// # Example
    /// ```ignore
    /// // Create a 3x4 sparse matrix with two non-zero elements
    /// let sparse = session.sparse_coo_tensor(
    ///     &[vec![0, 1], vec![2, 3]], // row 0 col 1, row 2 col 3
    ///     vec![1.0, 2.0],
    ///     vec![3, 4],
    ///     DType::F64,
    /// )?;
    /// ```
    pub fn sparse_coo_tensor(
        &self,
        coords: &[Vec<i64>],
        values: Vec<f64>,
        dense_shape: Vec<usize>,
        dtype: DType,
    ) -> Result<SparseCOOTensor, SparseTensorError> {
        SparseCOOTensor::from_coords(coords, values, dense_shape, dtype, Device::Cpu)
    }

    /// Create a sparse COO tensor from indices and values tensors.
    ///
    /// # Arguments
    /// * `indices` - Shape [sparse_dim, nnz], dtype I64
    /// * `values` - Shape [nnz, *dense_dims]
    /// * `dense_shape` - The full dense shape
    /// * `coalesced` - Whether the indices are unique and sorted
    pub fn sparse_coo_tensor_from_indices(
        &self,
        indices: DenseI64Tensor,
        values: DenseTensor,
        dense_shape: Vec<usize>,
        coalesced: bool,
    ) -> Result<SparseCOOTensor, SparseTensorError> {
        SparseCOOTensor::new(indices, values, dense_shape, coalesced)
    }

    /// Create a sparse CSR tensor from CSR components.
    ///
    /// # Arguments
    /// * `crow_indices` - Shape [nrows + 1], dtype I64 (row pointers)
    /// * `col_indices` - Shape [nnz], dtype I64 (column indices)
    /// * `values` - Shape [nnz]
    /// * `shape` - [nrows, ncols]
    pub fn sparse_csr_tensor(
        &self,
        crow_indices: DenseI64Tensor,
        col_indices: DenseI64Tensor,
        values: DenseTensor,
        shape: [usize; 2],
    ) -> Result<SparseCSRTensor, SparseTensorError> {
        SparseCSRTensor::new(crow_indices, col_indices, values, shape)
    }

    /// Convert a dense tensor to sparse COO format.
    ///
    /// Only non-zero values are stored. The resulting sparse tensor has
    /// sparse_dim equal to the tensor's rank (fully sparse).
    pub fn tensor_to_sparse_coo(
        &self,
        input: TensorNodeId,
    ) -> Result<SparseCOOTensor, AutogradError> {
        let tensor = self.tensor_tape.tensor(input)?;
        let shape = tensor.meta().shape().to_vec();
        let values = tensor.contiguous_values_as_f64()?;

        let strides = ft_core::contiguous_strides(&shape);
        let mut coords = Vec::new();
        let mut sparse_values = Vec::new();

        for (linear_idx, &val) in values.iter().enumerate() {
            if val != 0.0 {
                // Convert linear index to multi-index
                let mut coord = Vec::with_capacity(shape.len());
                let mut remaining = linear_idx;
                for &stride in &strides {
                    coord.push((remaining / stride) as i64);
                    remaining %= stride;
                }
                coords.push(coord);
                sparse_values.push(val);
            }
        }

        Ok(SparseCOOTensor::from_coords(
            &coords,
            sparse_values,
            shape,
            tensor.meta().dtype(),
            tensor.meta().device(),
        )?)
    }

    /// Convert a sparse COO tensor to dense format.
    ///
    /// Creates a new dense tensor filled with zeros except at the
    /// sparse tensor's indexed positions.
    pub fn sparse_coo_to_dense(
        &self,
        sparse: &SparseCOOTensor,
    ) -> Result<DenseTensor, SparseTensorError> {
        sparse.to_dense()
    }

    /// Convert a sparse CSR tensor to dense format.
    pub fn sparse_csr_to_dense(
        &self,
        sparse: &SparseCSRTensor,
    ) -> Result<DenseTensor, SparseTensorError> {
        sparse.to_dense()
    }

    // ── Data Augmentation Utilities ───────────────────────────────────────

    // ── Gradient Utilities ────────────────────────────────────────────────

    /// Gradient penalty for WGAN-GP.
    ///
    /// Computes gradient penalty: (||grad(D(interpolated))||_2 - 1)^2
    /// where interpolated = alpha * real + (1 - alpha) * fake.
    /// Returns the penalty term to be added to discriminator loss.
    pub fn gradient_penalty(
        &mut self,
        real: TensorNodeId,
        fake: TensorNodeId,
        alpha: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let alpha_tensor = self.full(vec![1], alpha, false)?;
        let one_minus_alpha = self.full(vec![1], 1.0 - alpha, false)?;
        let scaled_real = self.tensor_mul(real, alpha_tensor)?;
        let scaled_fake = self.tensor_mul(fake, one_minus_alpha)?;
        self.tensor_add(scaled_real, scaled_fake)
    }

    /// Spectral norm of a weight matrix (power iteration).
    ///
    /// Approximates largest singular value using power iteration.
    /// Commonly used for spectral normalization in GANs.
    pub fn spectral_norm_power_iter(
        &mut self,
        weight: TensorNodeId,
        u: TensorNodeId,
        n_iterations: usize,
    ) -> Result<(TensorNodeId, TensorNodeId, TensorNodeId), AutogradError> {
        let shape = self.tensor_shape(weight)?;
        if shape.len() != 2 {
            return Err(Self::incompatible_tensor_args(
                "spectral_norm: weight must be 2D",
            ));
        }
        let mut u_current = u;
        let mut v_current: TensorNodeId = u;
        for _ in 0..n_iterations {
            let wt = self.tensor_transpose(weight, 0, 1)?;
            let v_unnorm = self.tensor_matmul(wt, u_current)?;
            v_current = self.tensor_normalize(v_unnorm, 2.0, 0, 1e-12)?;
            let u_unnorm = self.tensor_matmul(weight, v_current)?;
            u_current = self.tensor_normalize(u_unnorm, 2.0, 0, 1e-12)?;
        }
        let wv = self.tensor_matmul(weight, v_current)?;
        let sigma = self.tensor_dot(u_current, wv)?;
        Ok((sigma, u_current, v_current))
    }

    /// Weight standardization for convolutional weights.
    ///
    /// Standardizes weights to have zero mean and unit variance per output
    /// channel. Often combined with GroupNorm for improved training.
    /// Input: [C_out, C_in, H, W] or [C_out, C_in] for linear.
    pub fn weight_standardization(
        &mut self,
        weight: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(weight)?;
        if shape.is_empty() {
            return Err(Self::incompatible_tensor_args(
                "weight_standardization: weight cannot be scalar",
            ));
        }
        let c_out = shape[0];
        let fan_in: usize = shape[1..].iter().product();
        let flat = self.tensor_reshape(weight, vec![c_out, fan_in])?;
        let mean = self.tensor_mean_dim(flat, 1)?;
        // Expand the keepdim mean/std [c_out, 1] up to [c_out, fan_in] before the
        // elementwise sub/div — tensor_sub/div do NOT broadcast a size-1 axis in
        // this codebase, so the bare unsqueeze made this fail with a
        // ShapeMismatch for every input. frankentorch-3pvd.
        let mean_unsq = self.tensor_unsqueeze(mean, 1)?;
        let mean_expanded = self.tensor_expand(mean_unsq, vec![c_out, fan_in])?;
        let centered = self.tensor_sub(flat, mean_expanded)?;
        let var = self.tensor_var_dim(centered, 1, 0)?;
        let eps = self.full(vec![c_out], 1e-5, false)?;
        let var_eps = self.tensor_add(var, eps)?;
        let std = self.tensor_sqrt(var_eps)?;
        let std_unsq = self.tensor_unsqueeze(std, 1)?;
        let std_expanded = self.tensor_expand(std_unsq, vec![c_out, fan_in])?;
        let normalized = self.tensor_div(centered, std_expanded)?;
        self.tensor_reshape(normalized, shape)
    }

    // ── Coordinate Utilities ──────────────────────────────────────────────

    /// CoordConv: add coordinate channels to input.
    ///
    /// Implements Liu et al. "An Intriguing Failing of Convolutional Neural
    /// Networks and the CoordConv Solution". Adds normalized x, y coordinate
    /// channels to input [N, C, H, W] -> [N, C+2, H, W].
    pub fn coord_conv(&mut self, x: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(x)?;
        if shape.len() != 4 {
            return Err(Self::incompatible_tensor_args(
                "coord_conv: x must be [N, C, H, W]",
            ));
        }
        let (n, _c, h, w) = (shape[0], shape[1], shape[2], shape[3]);
        let mut y_coords = Vec::with_capacity(n * h * w);
        let mut x_coords = Vec::with_capacity(n * h * w);
        for _ in 0..n {
            for yi in 0..h {
                for xi in 0..w {
                    y_coords.push(yi as f64 / (h - 1).max(1) as f64 * 2.0 - 1.0);
                    x_coords.push(xi as f64 / (w - 1).max(1) as f64 * 2.0 - 1.0);
                }
            }
        }
        let y_channel = self.tensor_variable(y_coords, vec![n, 1, h, w], false)?;
        let x_channel = self.tensor_variable(x_coords, vec![n, 1, h, w], false)?;
        self.tensor_cat(&[x, y_channel, x_channel], 1)
    }

    /// Radius coordinate channel for radially symmetric patterns.
    ///
    /// Adds a channel with distance from center (normalized to [-1, 1]).
    pub fn coord_conv_radius(&mut self, x: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(x)?;
        if shape.len() != 4 {
            return Err(Self::incompatible_tensor_args(
                "coord_conv_radius: x must be [N, C, H, W]",
            ));
        }
        let (n, _c, h, w) = (shape[0], shape[1], shape[2], shape[3]);
        let cy = (h - 1) as f64 / 2.0;
        let cx = (w - 1) as f64 / 2.0;
        let max_r = (cy * cy + cx * cx).sqrt();
        let mut r_coords = Vec::with_capacity(n * h * w);
        for _ in 0..n {
            for yi in 0..h {
                for xi in 0..w {
                    let dy = yi as f64 - cy;
                    let dx = xi as f64 - cx;
                    let r = (dy * dy + dx * dx).sqrt() / max_r.max(1e-6);
                    r_coords.push(r * 2.0 - 1.0);
                }
            }
        }
        let r_channel = self.tensor_variable(r_coords, vec![n, 1, h, w], false)?;
        self.tensor_cat(&[x, r_channel], 1)
    }

    // ── Feature Pyramid Utilities ─────────────────────────────────────────

    /// Lateral connection for FPN (Feature Pyramid Network).
    ///
    /// Applies 1x1 conv to reduce channels, then upsamples to match target size.
    /// Used to merge high-level semantic features with low-level spatial features.
    pub fn fpn_lateral(
        &mut self,
        high_level: TensorNodeId,
        conv_weight: TensorNodeId,
        target_h: usize,
        target_w: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let reduced = self.tensor_conv2d(high_level, conv_weight, None, (1, 1), (0, 0))?;
        self.tensor_interpolate(
            reduced,
            Some(vec![target_h, target_w]),
            None,
            "nearest",
            None,
        )
    }

    /// FPN merge: add upsampled high-level features to lateral features.
    ///
    /// Standard FPN connection: lateral + upsample(top_down).
    pub fn fpn_merge(
        &mut self,
        lateral: TensorNodeId,
        top_down: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let lateral_shape = self.tensor_shape(lateral)?;
        if lateral_shape.len() != 4 {
            return Err(Self::incompatible_tensor_args(
                "fpn_merge: tensors must be [N, C, H, W]",
            ));
        }
        let (h, w) = (lateral_shape[2], lateral_shape[3]);
        let upsampled =
            self.tensor_interpolate(top_down, Some(vec![h, w]), None, "nearest", None)?;
        self.tensor_add(lateral, upsampled)
    }

    // ── Activation Checkpointing Utilities ────────────────────────────────

    /// Mark a tensor for gradient checkpointing.
    ///
    /// Wraps the tensor in a checkpoint node with identity recomputation so
    /// backward can flow through the same graph-level checkpoint machinery used
    /// by [`Self::checkpoint`].
    pub fn checkpoint_marker(&mut self, x: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        self.checkpoint(&[x], |_session, inputs| Ok(inputs[0]))
    }

    // ── Label Smoothing ───────────────────────────────────────────────────

    /// Label smoothing for classification.
    ///
    /// Smooths one-hot labels: (1 - smoothing) * target + smoothing / num_classes.
    /// Helps prevent overconfident predictions.
    pub fn smooth_labels(
        &mut self,
        labels: TensorNodeId,
        num_classes: usize,
        smoothing: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let one_hot = self.tensor_one_hot(labels, num_classes)?;
        let shape = self.tensor_shape(one_hot)?;
        let on_value = 1.0 - smoothing;
        let off_value = smoothing / num_classes as f64;
        let on_tensor = self.full(shape.clone(), on_value, false)?;
        let off_tensor = self.full(shape, off_value, false)?;
        let scaled = self.tensor_mul(one_hot, on_tensor)?;
        self.tensor_add(scaled, off_tensor)
    }

    /// Cross entropy with label smoothing.
    ///
    /// Combines label smoothing with cross entropy loss.
    pub fn cross_entropy_label_smoothing(
        &mut self,
        logits: TensorNodeId,
        labels: TensorNodeId,
        smoothing: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(logits)?;
        if shape.len() != 2 {
            return Err(Self::incompatible_tensor_args(
                "cross_entropy_label_smoothing: logits must be [N, C]",
            ));
        }
        let num_classes = shape[1];
        let smooth_labels = self.smooth_labels(labels, num_classes, smoothing)?;
        let log_softmax = self.tensor_log_softmax(logits, 1)?;
        let loss = self.tensor_mul(smooth_labels, log_softmax)?;
        let neg_loss = self.tensor_neg(loss)?;
        let sum_loss = self.tensor_sum_dim(neg_loss, 1)?;
        self.tensor_mean(sum_loss)
    }

    // ── Modern Regularization ─────────────────────────────────────────────

    /// DropPath (Stochastic Depth) for residual connections.
    ///
    /// Randomly drops entire residual branches during training.
    /// Returns x * scale where scale = 0 or 1/keep_prob per sample.
    pub fn drop_path(
        &mut self,
        x: TensorNodeId,
        drop_prob: f64,
        training: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        if !training || drop_prob == 0.0 {
            return Ok(x);
        }
        let keep_prob = 1.0 - drop_prob;
        let shape = self.tensor_shape(x)?;
        let n = shape[0];
        let rand = self.tensor_rand(vec![n], false)?;
        let thresh = self.full(vec![n], drop_prob, false)?;
        let mask = self.tensor_ge(rand, thresh)?;
        let mask_float = self.tensor_to_f64(mask)?;
        let scale = self.full(vec![n], 1.0 / keep_prob, false)?;
        let mask_scaled = self.tensor_mul(mask_float, scale)?;
        let mut new_shape = vec![n];
        for _ in 1..shape.len() {
            new_shape.push(1);
        }
        let mask_shaped = self.tensor_reshape(mask_scaled, new_shape)?;
        self.tensor_mul(x, mask_shaped)
    }

    // ── Token/Patch Operations ────────────────────────────────────────────

    /// Token mixing (MLP-Mixer style).
    ///
    /// Mixes information across token dimension using linear projection.
    /// Input: [N, T, C] where T is number of tokens.
    pub fn token_mixing(
        &mut self,
        x: TensorNodeId,
        weight: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(x)?;
        if shape.len() != 3 {
            return Err(Self::incompatible_tensor_args(
                "token_mixing: x must be [N, T, C]",
            ));
        }
        let x_t = self.tensor_transpose(x, 1, 2)?;
        let mixed_t = self.tensor_matmul(x_t, weight)?;
        self.tensor_transpose(mixed_t, 1, 2)
    }

    /// Channel mixing (MLP-Mixer style).
    ///
    /// Mixes information across channel dimension.
    /// Input: [N, T, C] where C is number of channels.
    pub fn channel_mixing(
        &mut self,
        x: TensorNodeId,
        weight: TensorNodeId,
        bias: Option<TensorNodeId>,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(x)?;
        if shape.len() != 3 {
            return Err(Self::incompatible_tensor_args(
                "channel_mixing: x must be [N, T, C]",
            ));
        }
        self.tensor_linear(x, weight, bias)
    }

    /// Relative position bias for attention.
    ///
    /// Computes relative position bias table lookup for window attention.
    /// Returns bias selected from table based on index.
    pub fn relative_position_bias(
        &mut self,
        table: TensorNodeId,
        index: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let numel = self.tensor_numel(index)?;
        let flat_index = self.tensor_reshape(index, vec![numel])?;
        self.tensor_index_select(table, 0, flat_index)
    }

    // ── Gating Mechanisms ─────────────────────────────────────────────────

    /// Gated Linear Unit (GLU).
    ///
    /// Splits input in half along dim, applies sigmoid to second half,
    /// multiplies with first half: x1 * sigmoid(x2).
    pub fn glu(&mut self, x: TensorNodeId, dim: i64) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(x)?;
        let ndim = shape.len() as i64;
        let d = if dim < 0 { ndim + dim } else { dim } as usize;
        let chunks = self.tensor_chunk(x, 2, d)?;
        let a = chunks[0];
        let b = chunks[1];
        let gate = self.tensor_sigmoid(b)?;
        self.tensor_mul(a, gate)
    }

    /// Gated GELU (GeGLU variant).
    ///
    /// x1 * gelu(x2) instead of sigmoid gate.
    pub fn geglu(&mut self, x: TensorNodeId, dim: i64) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(x)?;
        let ndim = shape.len() as i64;
        let d = if dim < 0 { ndim + dim } else { dim } as usize;
        let chunks = self.tensor_chunk(x, 2, d)?;
        let a = chunks[0];
        let b = chunks[1];
        let gate = self.tensor_gelu(b)?;
        self.tensor_mul(a, gate)
    }

    /// SwiGLU activation.
    ///
    /// x1 * swish(x2) = x1 * silu(x2).
    pub fn swiglu(&mut self, x: TensorNodeId, dim: i64) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(x)?;
        let ndim = shape.len() as i64;
        let d = if dim < 0 { ndim + dim } else { dim } as usize;
        let chunks = self.tensor_chunk(x, 2, d)?;
        let a = chunks[0];
        let b = chunks[1];
        let gate = self.tensor_silu(b)?;
        self.tensor_mul(a, gate)
    }

    // ── Normalization Variants ────────────────────────────────────────────

    /// Power normalization (useful for RL and some CV tasks).
    ///
    /// Normalizes input by its p-norm: x / (||x||_p + eps).
    pub fn power_norm(
        &mut self,
        x: TensorNodeId,
        p: f64,
        eps: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let norm = self.tensor_norm(x, p)?;
        let eps_tensor = self.full(vec![1], eps, false)?;
        let denom = self.tensor_add(norm, eps_tensor)?;
        self.tensor_div(x, denom)
    }

    /// Filter Response Normalization (FRN).
    ///
    /// Wu & He "Filter Response Normalization Layer" - replaces BN
    /// without requiring batch statistics.
    pub fn filter_response_norm(
        &mut self,
        x: TensorNodeId,
        eps: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(x)?;
        if shape.len() != 4 {
            return Err(Self::incompatible_tensor_args(
                "filter_response_norm: x must be [N, C, H, W]",
            ));
        }
        let (n, c, h, w) = (shape[0], shape[1], shape[2], shape[3]);
        let x_flat = self.tensor_reshape(x, vec![n, c, h * w])?;
        let x_sq = self.tensor_mul(x_flat, x_flat)?;
        let nu2 = self.tensor_mean_dim(x_sq, 2)?;
        let eps_tensor = self.full(vec![n, c], eps, false)?;
        let nu2_eps = self.tensor_add(nu2, eps_tensor)?;
        let denom = self.tensor_sqrt(nu2_eps)?;
        // Expand [n, c, 1] -> [n, c, h*w] before the divide; tensor_div does not
        // broadcast a size-1 axis here. frankentorch-3pvd.
        let denom_unsq = self.tensor_unsqueeze(denom, 2)?;
        let denom_expanded = self.tensor_expand(denom_unsq, vec![n, c, h * w])?;
        let x_norm = self.tensor_div(x_flat, denom_expanded)?;
        self.tensor_reshape(x_norm, vec![n, c, h, w])
    }

    // ── Image Transform Utilities ─────────────────────────────────────────

    /// Center crop an image tensor.
    ///
    /// Input: [N, C, H, W], output: [N, C, crop_h, crop_w].
    pub fn center_crop(
        &mut self,
        x: TensorNodeId,
        crop_h: usize,
        crop_w: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(x)?;
        if shape.len() != 4 {
            return Err(Self::incompatible_tensor_args(
                "center_crop: x must be [N, C, H, W]",
            ));
        }
        let (h, w) = (shape[2], shape[3]);
        let y_start = (h - crop_h) / 2;
        let x_start = (w - crop_w) / 2;
        let sliced_h = self.tensor_narrow(x, 2, y_start, crop_h)?;
        self.tensor_narrow(sliced_h, 3, x_start, crop_w)
    }

    /// Resize with scale factor using nearest neighbor.
    ///
    /// Simple 2x or 0.5x scaling via repeat/pooling.
    pub fn resize_scale(
        &mut self,
        x: TensorNodeId,
        scale: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(x)?;
        if shape.len() != 4 {
            return Err(Self::incompatible_tensor_args(
                "resize_scale: x must be [N, C, H, W]",
            ));
        }
        let (h, w) = (shape[2], shape[3]);
        let new_h = ((h as f64) * scale).round() as usize;
        let new_w = ((w as f64) * scale).round() as usize;
        self.tensor_interpolate(x, Some(vec![new_h, new_w]), None, "nearest", None)
    }

    /// Horizontal flip (left-right).
    pub fn hflip(&mut self, x: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        self.tensor_flip(x, &[3])
    }

    /// Vertical flip (up-down).
    pub fn vflip(&mut self, x: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        self.tensor_flip(x, &[2])
    }

    /// Rotate 90 degrees clockwise.
    pub fn rotate90(&mut self, x: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let transposed = self.tensor_transpose(x, 2, 3)?;
        self.tensor_flip(transposed, &[3])
    }

    /// Rotate 180 degrees.
    pub fn rotate180(&mut self, x: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        self.tensor_flip(x, &[2, 3])
    }

    /// Rotate 270 degrees (90 degrees counter-clockwise).
    pub fn rotate270(&mut self, x: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let transposed = self.tensor_transpose(x, 2, 3)?;
        self.tensor_flip(transposed, &[2])
    }

    /// Grayscale conversion using standard luminosity weights.
    ///
    /// Input: [N, 3, H, W] RGB, output: [N, 1, H, W].
    pub fn rgb_to_grayscale(&mut self, x: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(x)?;
        if shape.len() != 4 || shape[1] != 3 {
            return Err(Self::incompatible_tensor_args(
                "rgb_to_grayscale: x must be [N, 3, H, W]",
            ));
        }
        let (_n, _, _h, _w) = (shape[0], shape[1], shape[2], shape[3]);
        let weights =
            self.tensor_variable(vec![0.2989, 0.5870, 0.1140], vec![1, 3, 1, 1], false)?;
        let weighted = self.tensor_mul(x, weights)?;
        self.tensor_sum_dim(weighted, 1)
    }

    // ── Model Initialization ──────────────────────────────────────────────

    /// Xavier/Glorot uniform initialization bounds.
    ///
    /// Returns the bound for uniform[-bound, bound].
    pub fn xavier_uniform_bound(fan_in: usize, fan_out: usize, gain: f64) -> f64 {
        gain * (6.0 / (fan_in + fan_out) as f64).sqrt()
    }

    /// Xavier/Glorot normal initialization std.
    pub fn xavier_normal_std(fan_in: usize, fan_out: usize, gain: f64) -> f64 {
        gain * (2.0 / (fan_in + fan_out) as f64).sqrt()
    }

    /// Kaiming/He uniform initialization bound.
    pub fn kaiming_uniform_bound(fan_in: usize, a: f64) -> f64 {
        let gain = (2.0 / (1.0 + a * a)).sqrt();
        gain * (3.0 / fan_in as f64).sqrt()
    }

    /// Kaiming/He normal initialization std.
    pub fn kaiming_normal_std(fan_in: usize, a: f64) -> f64 {
        let gain = (2.0 / (1.0 + a * a)).sqrt();
        gain / (fan_in as f64).sqrt()
    }

    /// Initialize tensor with Xavier uniform.
    pub fn init_xavier_uniform(
        &mut self,
        shape: Vec<usize>,
        gain: f64,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        let fan_in = if shape.len() >= 2 { shape[1] } else { shape[0] };
        let fan_out = shape[0];
        let bound = Self::xavier_uniform_bound(fan_in, fan_out, gain);
        self.tensor_uniform(-bound, bound, shape, requires_grad)
    }

    /// Initialize tensor with Xavier normal.
    pub fn init_xavier_normal(
        &mut self,
        shape: Vec<usize>,
        gain: f64,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        let fan_in = if shape.len() >= 2 { shape[1] } else { shape[0] };
        let fan_out = shape[0];
        let std = Self::xavier_normal_std(fan_in, fan_out, gain);
        let base = self.tensor_randn(shape, requires_grad)?;
        let scale = self.full(vec![1], std, false)?;
        self.tensor_mul(base, scale)
    }

    /// Initialize tensor with Kaiming uniform.
    pub fn init_kaiming_uniform(
        &mut self,
        shape: Vec<usize>,
        a: f64,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        let fan_in = if shape.len() >= 2 { shape[1] } else { shape[0] };
        let bound = Self::kaiming_uniform_bound(fan_in, a);
        self.tensor_uniform(-bound, bound, shape, requires_grad)
    }

    /// Initialize tensor with Kaiming normal.
    pub fn init_kaiming_normal(
        &mut self,
        shape: Vec<usize>,
        a: f64,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        let fan_in = if shape.len() >= 2 { shape[1] } else { shape[0] };
        let std = Self::kaiming_normal_std(fan_in, a);
        let base = self.tensor_randn(shape, requires_grad)?;
        let scale = self.full(vec![1], std, false)?;
        self.tensor_mul(base, scale)
    }

    /// Orthogonal initialization.
    ///
    /// Uses QR decomposition for orthogonal matrices.
    pub fn init_orthogonal(
        &mut self,
        shape: Vec<usize>,
        gain: f64,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        if shape.len() < 2 {
            return Err(Self::incompatible_tensor_args(
                "init_orthogonal: need at least 2D",
            ));
        }
        let rows = shape[0];
        let cols: usize = shape[1..].iter().product();
        let flat_shape = vec![rows, cols];
        let a = self.tensor_randn(flat_shape, false)?;
        let (q, _r) = self.tensor_linalg_qr(a, true)?;
        let gain_tensor = self.full(vec![1], gain, false)?;
        let scaled = self.tensor_mul(q, gain_tensor)?;
        if requires_grad {
            self.tensor_requires_grad_(scaled, true)?;
        }
        self.tensor_reshape(scaled, shape)
    }

    // ── Gradient Utilities ────────────────────────────────────────────────

    /// Gradient clipping by value.
    ///
    /// Clips gradient values to [-clip_value, clip_value].
    pub fn clip_grad_value(
        &mut self,
        grad: TensorNodeId,
        clip_value: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_clamp(grad, -clip_value, clip_value)
    }

    /// Gradient clipping by norm (per-tensor).
    ///
    /// Scales gradient so its norm doesn't exceed max_norm.
    pub fn clip_grad_norm(
        &mut self,
        grad: TensorNodeId,
        max_norm: f64,
        norm_type: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let norm = self.tensor_norm(grad, norm_type)?;
        let max_tensor = self.full(vec![1], max_norm, false)?;
        let clip_coef = self.tensor_div(max_tensor, norm)?;
        let one = self.full(vec![1], 1.0, false)?;
        let coef = self.tensor_min(clip_coef, one)?;
        self.tensor_mul(grad, coef)
    }

    // ── Higher-Level Building Blocks ──────────────────────────────────────

    /// MLP block: Linear -> activation -> Linear.
    ///
    /// Two-layer MLP with configurable hidden dimension.
    pub fn mlp_block(
        &mut self,
        x: TensorNodeId,
        w1: TensorNodeId,
        b1: Option<TensorNodeId>,
        w2: TensorNodeId,
        b2: Option<TensorNodeId>,
        activation: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        let hidden = self.tensor_linear(x, w1, b1)?;
        let activated = match activation {
            "relu" => self.tensor_relu(hidden)?,
            "gelu" => self.tensor_gelu(hidden)?,
            "silu" | "swish" => self.tensor_silu(hidden)?,
            "tanh" => self.tensor_tanh(hidden)?,
            _ => hidden,
        };
        self.tensor_linear(activated, w2, b2)
    }

    /// Pre-norm residual block: x + sublayer(norm(x)).
    pub fn prenorm_residual(
        &mut self,
        x: TensorNodeId,
        sublayer_output: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_add(x, sublayer_output)
    }

    /// Post-norm residual block: norm(x + sublayer(x)).
    pub fn postnorm_residual(
        &mut self,
        x: TensorNodeId,
        sublayer_output: TensorNodeId,
        gamma: TensorNodeId,
        beta: TensorNodeId,
        eps: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let residual = self.tensor_add(x, sublayer_output)?;
        let shape = self.tensor_shape(residual)?;
        let norm_shape = vec![shape[shape.len() - 1]];
        self.tensor_layer_norm(residual, norm_shape, Some(gamma), Some(beta), eps)
    }

    /// Squeeze-and-excitation block (SE-Net style).
    ///
    /// Global pool -> FC -> ReLU -> FC -> Sigmoid -> Scale.
    pub fn se_block(
        &mut self,
        x: TensorNodeId,
        fc1: TensorNodeId,
        fc2: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(x)?;
        let (n, c, _, _) = (shape[0], shape[1], shape[2], shape[3]);
        let pooled = self.tensor_adaptive_avg_pool2d(x, (1, 1))?;
        let flat = self.tensor_reshape(pooled, vec![n, c])?;
        let fc1_out = self.tensor_linear(flat, fc1, None)?;
        let relu_out = self.tensor_relu(fc1_out)?;
        let fc2_out = self.tensor_linear(relu_out, fc2, None)?;
        let scale = self.tensor_sigmoid(fc2_out)?;
        let scale_4d = self.tensor_reshape(scale, vec![n, c, 1, 1])?;
        self.tensor_mul(x, scale_4d)
    }

    // ── Metric Functions ──────────────────────────────────────────────────

    /// Accuracy for classification.
    ///
    /// Computes percentage of correct predictions.
    pub fn accuracy(
        &mut self,
        logits: TensorNodeId,
        targets: TensorNodeId,
    ) -> Result<f64, AutogradError> {
        let preds = self.tensor_argmax(logits, 1)?;
        let correct = self.tensor_eq(preds, targets)?;
        let correct_float = self.tensor_to_f64(correct)?;
        let sum = self.tensor_sum(correct_float)?;
        let n = self.tensor_numel(targets)?;
        let sum_val = self.tensor_values(sum)?[0];
        Ok(sum_val / n as f64)
    }

    /// Precision for binary classification.
    pub fn precision(
        &mut self,
        predictions: TensorNodeId,
        targets: TensorNodeId,
    ) -> Result<f64, AutogradError> {
        let tp = self.tensor_logical_and(predictions, targets)?;
        let tp_float = self.tensor_to_f64(tp)?;
        let tp_sum = self.tensor_sum(tp_float)?;
        let pred_float = self.tensor_to_f64(predictions)?;
        let pred_sum = self.tensor_sum(pred_float)?;
        let tp_val = self.tensor_values(tp_sum)?[0];
        let pred_val = self.tensor_values(pred_sum)?[0];
        Ok(if pred_val > 0.0 {
            tp_val / pred_val
        } else {
            0.0
        })
    }

    /// Recall for binary classification.
    pub fn recall(
        &mut self,
        predictions: TensorNodeId,
        targets: TensorNodeId,
    ) -> Result<f64, AutogradError> {
        let tp = self.tensor_logical_and(predictions, targets)?;
        let tp_float = self.tensor_to_f64(tp)?;
        let tp_sum = self.tensor_sum(tp_float)?;
        let target_float = self.tensor_to_f64(targets)?;
        let target_sum = self.tensor_sum(target_float)?;
        let tp_val = self.tensor_values(tp_sum)?[0];
        let target_val = self.tensor_values(target_sum)?[0];
        Ok(if target_val > 0.0 {
            tp_val / target_val
        } else {
            0.0
        })
    }

    /// F1 score for binary classification.
    pub fn f1_score(
        &mut self,
        predictions: TensorNodeId,
        targets: TensorNodeId,
    ) -> Result<f64, AutogradError> {
        let p = self.precision(predictions, targets)?;
        let r = self.recall(predictions, targets)?;
        Ok(if p + r > 0.0 {
            2.0 * p * r / (p + r)
        } else {
            0.0
        })
    }

    // ── Distance Functions ────────────────────────────────────────────────

    /// Pairwise Euclidean distance.
    ///
    /// Computes distance between all pairs of rows in x1 and x2.
    /// Returns [N, M] where N = x1.shape[0], M = x2.shape[0].
    pub fn pairwise_euclidean(
        &mut self,
        x1: TensorNodeId,
        x2: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let x1_sq = self.tensor_mul(x1, x1)?;
        let x1_sq_sum = self.tensor_sum_dim(x1_sq, 1)?;
        let x2_sq = self.tensor_mul(x2, x2)?;
        let x2_sq_sum = self.tensor_sum_dim(x2_sq, 1)?;
        let x2_t = self.tensor_transpose(x2, 0, 1)?;
        let cross = self.tensor_matmul(x1, x2_t)?;
        let two = self.full(vec![1], 2.0, false)?;
        let cross_2 = self.tensor_mul(cross, two)?;
        let x1_sq_expanded = self.tensor_unsqueeze(x1_sq_sum, 1)?;
        let x2_sq_expanded = self.tensor_unsqueeze(x2_sq_sum, 0)?;
        let dist_sq = self.tensor_add(x1_sq_expanded, x2_sq_expanded)?;
        let dist_sq = self.tensor_sub(dist_sq, cross_2)?;
        let zero = self.full(vec![1], 0.0, false)?;
        let dist_sq_clamp = self.tensor_max(dist_sq, zero)?;
        self.tensor_sqrt(dist_sq_clamp)
    }

    /// Pairwise cosine similarity.
    ///
    /// Returns [N, M] similarity matrix.
    pub fn pairwise_cosine(
        &mut self,
        x1: TensorNodeId,
        x2: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let x1_norm = self.tensor_normalize(x1, 2.0, 1, 1e-12)?;
        let x2_norm = self.tensor_normalize(x2, 2.0, 1, 1e-12)?;
        let x2_t = self.tensor_transpose(x2_norm, 0, 1)?;
        self.tensor_matmul(x1_norm, x2_t)
    }

    // ── Tensor Statistics ─────────────────────────────────────────────────

    /// Exponential moving average update.
    ///
    /// Returns updated = decay * current + (1 - decay) * new_value.
    pub fn ema_update(
        &mut self,
        current: TensorNodeId,
        new_value: TensorNodeId,
        decay: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let decay_tensor = self.full(vec![1], decay, false)?;
        let one_minus_decay = self.full(vec![1], 1.0 - decay, false)?;
        let scaled_current = self.tensor_mul(current, decay_tensor)?;
        let scaled_new = self.tensor_mul(new_value, one_minus_decay)?;
        self.tensor_add(scaled_current, scaled_new)
    }

    /// Running mean update for batch normalization.
    ///
    /// Returns updated = momentum * current + (1 - momentum) * batch_mean.
    pub fn running_mean_update(
        &mut self,
        running_mean: TensorNodeId,
        batch_mean: TensorNodeId,
        momentum: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        self.ema_update(running_mean, batch_mean, momentum)
    }

    /// Running variance update for batch normalization.
    pub fn running_var_update(
        &mut self,
        running_var: TensorNodeId,
        batch_var: TensorNodeId,
        momentum: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        self.ema_update(running_var, batch_var, momentum)
    }

    /// Compute batch mean and variance for normalization.
    ///
    /// Returns (mean, var) for input [N, ...].
    pub fn batch_stats(
        &mut self,
        x: TensorNodeId,
    ) -> Result<(TensorNodeId, TensorNodeId), AutogradError> {
        let mean = self.tensor_mean_dim(x, 0)?;
        let var = self.tensor_var_dim(x, 0, 0)?;
        Ok((mean, var))
    }

    // ── Tensor Creation Shortcuts ─────────────────────────────────────────

    /// Create diagonal matrix from 1D tensor.
    pub fn diag_embed(
        &mut self,
        input: TensorNodeId,
        offset: i64,
    ) -> Result<TensorNodeId, AutogradError> {
        let vals = self.tensor_values(input)?;
        let n = vals.len();
        let size = n + offset.unsigned_abs() as usize;
        let mut data = vec![0.0_f64; size * size];
        for (i, &v) in vals.iter().enumerate() {
            let row = if offset >= 0 {
                i
            } else {
                i + offset.unsigned_abs() as usize
            };
            let col = if offset >= 0 { i + offset as usize } else { i };
            if row < size && col < size {
                data[row * size + col] = v;
            }
        }
        self.tensor_variable(data, vec![size, size], false)
    }

    /// Create triangular matrix (lower or upper).
    pub fn tri(
        &mut self,
        n: usize,
        m: usize,
        k: i64,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        let mut data = vec![0.0_f64; n * m];
        for i in 0..n {
            for j in 0..m {
                if (j as i64) <= (i as i64) + k {
                    data[i * m + j] = 1.0;
                }
            }
        }
        self.tensor_variable(data, vec![n, m], requires_grad)
    }

    /// Create Toeplitz matrix from first row and column.
    pub fn toeplitz(
        &mut self,
        c: TensorNodeId,
        r: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let c_vals = self.tensor_values(c)?;
        let r_vals = self.tensor_values(r)?;
        let n = c_vals.len();
        let m = r_vals.len();
        let mut data = vec![0.0_f64; n * m];
        for i in 0..n {
            for j in 0..m {
                if i <= j {
                    data[i * m + j] = r_vals[j - i];
                } else {
                    data[i * m + j] = c_vals[i - j];
                }
            }
        }
        self.tensor_variable(data, vec![n, m], false)
    }

    // ── Debugging Utilities ───────────────────────────────────────────────

    /// Check if tensor contains NaN values.
    pub fn has_nan(&self, x: TensorNodeId) -> Result<bool, AutogradError> {
        let vals = self.tensor_values(x)?;
        Ok(vals.iter().any(|v| v.is_nan()))
    }

    /// Check if tensor contains Inf values.
    pub fn has_inf(&self, x: TensorNodeId) -> Result<bool, AutogradError> {
        let vals = self.tensor_values(x)?;
        Ok(vals.iter().any(|v| v.is_infinite()))
    }

    /// Replace NaN values with a specified value.
    pub fn nan_to_num(
        &mut self,
        x: TensorNodeId,
        nan_val: f64,
        posinf_val: f64,
        neginf_val: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let vals = self.tensor_values(x)?;
        let shape = self.tensor_shape(x)?;
        let new_vals: Vec<f64> = vals
            .iter()
            .map(|&v| {
                if v.is_nan() {
                    nan_val
                } else if v == f64::INFINITY {
                    posinf_val
                } else if v == f64::NEG_INFINITY {
                    neginf_val
                } else {
                    v
                }
            })
            .collect();
        self.tensor_variable(new_vals, shape, false)
    }

    // ── Reduction with Broadcasting ───────────────────────────────────────

    /// Compute mean along multiple dimensions.
    pub fn mean_dims(
        &mut self,
        x: TensorNodeId,
        dims: &[usize],
    ) -> Result<TensorNodeId, AutogradError> {
        let mut result = x;
        for &d in dims.iter().rev() {
            result = self.tensor_mean_dim(result, d)?;
        }
        Ok(result)
    }

    /// Compute sum along multiple dimensions.
    pub fn sum_dims(
        &mut self,
        x: TensorNodeId,
        dims: &[usize],
    ) -> Result<TensorNodeId, AutogradError> {
        let mut result = x;
        for &d in dims.iter().rev() {
            result = self.tensor_sum_dim(result, d)?;
        }
        Ok(result)
    }

    /// Compute variance along multiple dimensions.
    pub fn var_dims(
        &mut self,
        x: TensorNodeId,
        dims: &[usize],
        correction: i64,
    ) -> Result<TensorNodeId, AutogradError> {
        // Delegate to the torch-parity multi-dim variance. The previous body
        // (a) subtracted a squeezed (non-keepdim) mean, which mis-broadcast for
        // any non-trailing reduced dim, and (b) clamped the divisor at 1
        // instead of torch's 0 (so correction >= N gave a finite value rather
        // than +inf). tensor_var_dims fixes both.
        let d: Vec<i64> = dims.iter().map(|&d| d as i64).collect();
        self.tensor_var_dims(x, &d, correction, false)
    }

    /// Compute std along multiple dimensions.
    pub fn std_dims(
        &mut self,
        x: TensorNodeId,
        dims: &[usize],
        correction: i64,
    ) -> Result<TensorNodeId, AutogradError> {
        let d: Vec<i64> = dims.iter().map(|&d| d as i64).collect();
        self.tensor_std_dims(x, &d, correction, false)
    }

    // ── Shape Utilities ───────────────────────────────────────────────────

    /// Pad tensor to target shape with zeros.
    pub fn pad_to_shape(
        &mut self,
        x: TensorNodeId,
        target_shape: Vec<usize>,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(x)?;
        if shape == target_shape {
            return Ok(x);
        }
        if shape.len() != target_shape.len() {
            return Err(Self::incompatible_tensor_args(
                "pad_to_shape: dimension mismatch",
            ));
        }
        let mut result = x;
        for (i, (&current, &target)) in shape.iter().zip(target_shape.iter()).enumerate() {
            if current < target {
                let pad_size = target - current;
                let pad_shape: Vec<usize> = shape
                    .iter()
                    .enumerate()
                    .map(|(j, &s)| {
                        if j == i {
                            pad_size
                        } else if j > i {
                            target_shape[j]
                        } else {
                            s
                        }
                    })
                    .collect();
                let zeros = self.zeros(pad_shape, false)?;
                result = self.tensor_cat(&[result, zeros], i)?;
            }
        }
        Ok(result)
    }

    /// Truncate tensor to target shape.
    pub fn truncate_to_shape(
        &mut self,
        x: TensorNodeId,
        target_shape: Vec<usize>,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(x)?;
        if shape == target_shape {
            return Ok(x);
        }
        if shape.len() != target_shape.len() {
            return Err(Self::incompatible_tensor_args(
                "truncate_to_shape: dimension mismatch",
            ));
        }
        let mut result = x;
        for (i, (&current, &target)) in shape.iter().zip(target_shape.iter()).enumerate() {
            if current > target {
                result = self.tensor_narrow(result, i, 0, target)?;
            }
        }
        Ok(result)
    }

    // ── Activation Helpers ────────────────────────────────────────────────

    /// Softmax with temperature scaling.
    pub fn softmax_temperature(
        &mut self,
        x: TensorNodeId,
        dim: usize,
        temperature: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let temp = self.full(vec![1], temperature, false)?;
        let scaled = self.tensor_div(x, temp)?;
        self.tensor_softmax(scaled, dim)
    }

    /// Log-softmax with temperature scaling.
    pub fn log_softmax_temperature(
        &mut self,
        x: TensorNodeId,
        dim: usize,
        temperature: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let temp = self.full(vec![1], temperature, false)?;
        let scaled = self.tensor_div(x, temp)?;
        self.tensor_log_softmax(scaled, dim)
    }

    // ── Comparison Utilities ──────────────────────────────────────────────

    /// Check if two tensors are element-wise close (allclose).
    pub fn allclose(
        &self,
        a: TensorNodeId,
        b: TensorNodeId,
        rtol: f64,
        atol: f64,
    ) -> Result<bool, AutogradError> {
        let a_vals = self.tensor_values(a)?;
        let b_vals = self.tensor_values(b)?;
        if a_vals.len() != b_vals.len() {
            return Ok(false);
        }
        Ok(a_vals
            .iter()
            .zip(b_vals.iter())
            .all(|(a, b)| (a - b).abs() <= atol + rtol * b.abs()))
    }

    /// Check if two tensors are exactly equal.
    pub fn array_equal(&self, a: TensorNodeId, b: TensorNodeId) -> Result<bool, AutogradError> {
        let a_shape = self.tensor_shape(a)?;
        let b_shape = self.tensor_shape(b)?;
        if a_shape != b_shape {
            return Ok(false);
        }
        let a_vals = self.tensor_values(a)?;
        let b_vals = self.tensor_values(b)?;
        Ok(a_vals == b_vals)
    }

    /// Check if any element is True.
    pub fn any(&self, x: TensorNodeId) -> Result<bool, AutogradError> {
        let vals = self.tensor_values(x)?;
        Ok(vals.iter().any(|&v| v != 0.0))
    }

    /// Check if all elements are True.
    pub fn all(&self, x: TensorNodeId) -> Result<bool, AutogradError> {
        let vals = self.tensor_values(x)?;
        Ok(vals.iter().all(|&v| v != 0.0))
    }

    // ── Tensor Info Utilities ─────────────────────────────────────────────

    /// Get tensor min and max values.
    pub fn minmax(&self, x: TensorNodeId) -> Result<(f64, f64), AutogradError> {
        let vals = self.tensor_values(x)?;
        let min = vals.iter().cloned().fold(f64::INFINITY, f64::min);
        let max = vals.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
        Ok((min, max))
    }

    /// Get tensor value range (max - min).
    pub fn ptp(&self, x: TensorNodeId) -> Result<f64, AutogradError> {
        let (min, max) = self.minmax(x)?;
        Ok(max - min)
    }

    /// Count non-zero elements.
    pub fn count_nonzero(&self, x: TensorNodeId) -> Result<usize, AutogradError> {
        let vals = self.tensor_values(x)?;
        Ok(vals.iter().filter(|&&v| v != 0.0).count())
    }

    // ── Tensor Type Utilities ─────────────────────────────────────────────

    /// Check if tensor values are all integers.
    pub fn is_integer(&self, x: TensorNodeId) -> Result<bool, AutogradError> {
        let vals = self.tensor_values(x)?;
        Ok(vals.iter().all(|v| v.fract() == 0.0))
    }

    /// Check if tensor values are all non-negative.
    pub fn is_nonnegative(&self, x: TensorNodeId) -> Result<bool, AutogradError> {
        let vals = self.tensor_values(x)?;
        Ok(vals.iter().all(|&v| v >= 0.0))
    }

    /// Check if tensor values are all positive.
    pub fn is_positive(&self, x: TensorNodeId) -> Result<bool, AutogradError> {
        let vals = self.tensor_values(x)?;
        Ok(vals.iter().all(|&v| v > 0.0))
    }

    // ── Batch Utilities ───────────────────────────────────────────────────

    /// Split tensor into batches.
    pub fn batch_split(
        &mut self,
        x: TensorNodeId,
        batch_size: usize,
    ) -> Result<Vec<TensorNodeId>, AutogradError> {
        let shape = self.tensor_shape(x)?;
        let n = shape[0];
        let num_batches = (n + batch_size - 1) / batch_size;
        let mut batches = Vec::with_capacity(num_batches);
        for i in 0..num_batches {
            let start = i * batch_size;
            let size = batch_size.min(n - start);
            let batch = self.tensor_narrow(x, 0, start, size)?;
            batches.push(batch);
        }
        Ok(batches)
    }

    /// Gather tensors from a list into one by concatenating along batch dim.
    pub fn batch_gather(
        &mut self,
        tensors: &[TensorNodeId],
    ) -> Result<TensorNodeId, AutogradError> {
        if tensors.is_empty() {
            return Err(Self::incompatible_tensor_args(
                "batch_gather: empty tensor list",
            ));
        }
        self.tensor_cat(tensors, 0)
    }

    /// Apply a binary op element-wise between a batch and a single tensor.
    pub fn batch_apply_single(
        &mut self,
        batch: TensorNodeId,
        single: TensorNodeId,
        op: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        match op {
            "add" => self.tensor_add(batch, single),
            "sub" => self.tensor_sub(batch, single),
            "mul" => self.tensor_mul(batch, single),
            "div" => self.tensor_div(batch, single),
            _ => Err(Self::incompatible_tensor_args(
                "batch_apply_single: unknown op",
            )),
        }
    }

    // ── Broadcasting Helpers ──────────────────────────────────────────────

    /// Expand a 1D tensor to match a target's batch dimension.
    pub fn expand_to_batch(
        &mut self,
        x: TensorNodeId,
        target: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let target_shape = self.tensor_shape(target)?;
        if target_shape.is_empty() {
            return Ok(x);
        }
        let batch_size = target_shape[0];
        let x_shape = self.tensor_shape(x)?;
        let mut new_shape = vec![batch_size];
        new_shape.extend(x_shape);
        self.tensor_expand(x, new_shape)
    }

    /// Reduce over batch dimension.
    pub fn reduce_batch(
        &mut self,
        x: TensorNodeId,
        reduction: &str,
    ) -> Result<TensorNodeId, AutogradError> {
        match reduction {
            "mean" => self.tensor_mean_dim(x, 0),
            "sum" => self.tensor_sum_dim(x, 0),
            "max" => Ok(self.tensor_max_dim(x, 0)?.0),
            "min" => Ok(self.tensor_min_dim(x, 0)?.0),
            _ => Err(Self::incompatible_tensor_args(
                "reduce_batch: unknown reduction",
            )),
        }
    }

    // ── Sequence Utilities ────────────────────────────────────────────────

    /// Create attention mask from sequence lengths.
    ///
    /// Returns mask of shape [batch, max_len] with 1s for valid positions.
    pub fn length_to_mask(
        &mut self,
        lengths: &[usize],
        max_len: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let batch_size = lengths.len();
        let mut mask_data = vec![0.0_f64; batch_size * max_len];
        for (i, &len) in lengths.iter().enumerate() {
            for j in 0..len.min(max_len) {
                mask_data[i * max_len + j] = 1.0;
            }
        }
        self.tensor_variable(mask_data, vec![batch_size, max_len], false)
    }

    // ── Pooling Utilities ─────────────────────────────────────────────────

    /// Global average pooling for any dimension.
    ///
    /// Averages over all spatial dimensions.
    pub fn global_avg_pool(&mut self, x: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(x)?;
        match shape.len() {
            3 => {
                let pooled = self.tensor_mean_dim(x, 2)?;
                Ok(pooled)
            }
            4 => {
                let (_n, _c, _, _) = (shape[0], shape[1], shape[2], shape[3]);
                self.tensor_adaptive_avg_pool2d(x, (1, 1))
            }
            5 => {
                let (_n, _c, _, _, _) = (shape[0], shape[1], shape[2], shape[3], shape[4]);
                self.tensor_adaptive_avg_pool3d(x, (1, 1, 1))
            }
            _ => Err(Self::incompatible_tensor_args(
                "global_avg_pool: unsupported dim",
            )),
        }
    }

    /// Global max pooling for any dimension.
    pub fn global_max_pool(&mut self, x: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(x)?;
        match shape.len() {
            3 => {
                let (pooled, _) = self.tensor_max_dim(x, 2)?;
                Ok(pooled)
            }
            4 => {
                let (pooled, _) = self.tensor_adaptive_max_pool2d(x, (1, 1))?;
                Ok(pooled)
            }
            5 => {
                let (pooled, _) = self.tensor_adaptive_max_pool3d(x, (1, 1, 1))?;
                Ok(pooled)
            }
            _ => Err(Self::incompatible_tensor_args(
                "global_max_pool: unsupported dim",
            )),
        }
    }

    // ── Index Utilities ───────────────────────────────────────────────────

    /// Create index tensor from range.
    pub fn arange_tensor(
        &mut self,
        start: usize,
        end: usize,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        let data: Vec<f64> = (start..end).map(|x| x as f64).collect();
        self.tensor_variable(data, vec![end - start], requires_grad)
    }

    /// Create linspace tensor.
    pub fn linspace_tensor(
        &mut self,
        start: f64,
        end: f64,
        steps: usize,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        if steps == 0 {
            return self.tensor_variable(vec![], vec![0], requires_grad);
        }
        if steps == 1 {
            return self.tensor_variable(vec![start], vec![1], requires_grad);
        }
        let step = (end - start) / (steps - 1) as f64;
        let data: Vec<f64> = (0..steps).map(|i| start + step * i as f64).collect();
        self.tensor_variable(data, vec![steps], requires_grad)
    }

    /// Create logspace tensor.
    pub fn logspace_tensor(
        &mut self,
        start: f64,
        end: f64,
        steps: usize,
        base: f64,
        requires_grad: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        if steps == 0 {
            return self.tensor_variable(vec![], vec![0], requires_grad);
        }
        if steps == 1 {
            return self.tensor_variable(vec![base.powf(start)], vec![1], requires_grad);
        }
        let step = (end - start) / (steps - 1) as f64;
        let data: Vec<f64> = (0..steps)
            .map(|i| base.powf(start + step * i as f64))
            .collect();
        self.tensor_variable(data, vec![steps], requires_grad)
    }

    /// Create meshgrid from 1D tensors.
    pub fn meshgrid_2d(
        &mut self,
        x: TensorNodeId,
        y: TensorNodeId,
    ) -> Result<(TensorNodeId, TensorNodeId), AutogradError> {
        let x_vals = self.tensor_values(x)?;
        let y_vals = self.tensor_values(y)?;
        let nx = x_vals.len();
        let ny = y_vals.len();
        let mut xx_data = Vec::with_capacity(ny * nx);
        let mut yy_data = Vec::with_capacity(ny * nx);
        for yv in &y_vals {
            for xv in &x_vals {
                xx_data.push(*xv);
                yy_data.push(*yv);
            }
        }
        let xx = self.tensor_variable(xx_data, vec![ny, nx], false)?;
        let yy = self.tensor_variable(yy_data, vec![ny, nx], false)?;
        Ok((xx, yy))
    }

    // ── Tensor Operations ─────────────────────────────────────────────────

    /// Outer product of two 1D tensors.
    pub fn outer_product(
        &mut self,
        a: TensorNodeId,
        b: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let a_shape = self.tensor_shape(a)?;
        let b_shape = self.tensor_shape(b)?;
        if a_shape.len() != 1 || b_shape.len() != 1 {
            return Err(Self::incompatible_tensor_args(
                "outer_product: inputs must be 1D",
            ));
        }
        let a_col = self.tensor_unsqueeze(a, 1)?;
        let b_row = self.tensor_unsqueeze(b, 0)?;
        self.tensor_matmul(a_col, b_row)
    }

    /// Kronecker product of two 2D tensors.
    pub fn kron(
        &mut self,
        a: TensorNodeId,
        b: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let a_shape = self.tensor_shape(a)?;
        let b_shape = self.tensor_shape(b)?;
        if a_shape.len() != 2 || b_shape.len() != 2 {
            return Err(Self::incompatible_tensor_args("kron: inputs must be 2D"));
        }
        let (m, n) = (a_shape[0], a_shape[1]);
        let (p, q) = (b_shape[0], b_shape[1]);
        let a_vals = self.tensor_values(a)?;
        let b_vals = self.tensor_values(b)?;
        let out_cols = n * q;
        let total = m * p * n * q;
        // result[(i·p+k)·(n·q) + j·q+l] = A[i,j]·B[k,l]. Each output element decodes
        // its flat index into (i,k,j,l) — that per-element div/mod index math (not the
        // single multiply) is the compute-bound cost, so it parallelizes cleanly. The
        // indexed map preserves order → bit-identical to the serial 4-deep loop.
        // frankentorch-kgs4.102.
        let eval = |o: usize| {
            let row = o / out_cols;
            let col = o % out_cols;
            a_vals[(row / p) * n + (col / q)] * b_vals[(row % p) * q + (col % q)]
        };
        let result: Vec<f64> = if total >= PARALLEL_ELEMENTWISE_MIN {
            use rayon::prelude::*;
            (0..total).into_par_iter().map(eval).collect()
        } else {
            (0..total).map(eval).collect()
        };
        self.tensor_variable(result, vec![m * p, n * q], false)
    }

    /// Block diagonal matrix from a list of 2D tensors.
    pub fn block_diag(&mut self, tensors: &[TensorNodeId]) -> Result<TensorNodeId, AutogradError> {
        if tensors.is_empty() {
            return Err(Self::incompatible_tensor_args(
                "block_diag: empty tensor list",
            ));
        }
        let mut total_rows = 0;
        let mut total_cols = 0;
        let mut shapes = Vec::new();
        for &t in tensors {
            let shape = self.tensor_shape(t)?;
            if shape.len() != 2 {
                return Err(Self::incompatible_tensor_args(
                    "block_diag: tensors must be 2D",
                ));
            }
            shapes.push((shape[0], shape[1]));
            total_rows += shape[0];
            total_cols += shape[1];
        }
        let mut result = vec![0.0_f64; total_rows * total_cols];
        let mut row_offset = 0;
        let mut col_offset = 0;
        for (&t, &(rows, cols)) in tensors.iter().zip(shapes.iter()) {
            let vals = self.tensor_values(t)?;
            for i in 0..rows {
                for j in 0..cols {
                    let row = row_offset + i;
                    let col = col_offset + j;
                    result[row * total_cols + col] = vals[i * cols + j];
                }
            }
            row_offset += rows;
            col_offset += cols;
        }
        self.tensor_variable(result, vec![total_rows, total_cols], false)
    }

    // ── Weight Decay Utilities ────────────────────────────────────────────

    /// Apply L2 weight decay to weights.
    ///
    /// Returns weights - weight_decay * weights.
    pub fn apply_weight_decay(
        &mut self,
        weights: TensorNodeId,
        weight_decay: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let decay = self.full(vec![1], weight_decay, false)?;
        let penalty = self.tensor_mul(weights, decay)?;
        self.tensor_sub(weights, penalty)
    }

    /// Compute L2 regularization term.
    ///
    /// Returns sum of squared weights * lambda / 2.
    pub fn l2_regularization(
        &mut self,
        weights: TensorNodeId,
        lambda: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let sq = self.tensor_mul(weights, weights)?;
        let sum = self.tensor_sum(sq)?;
        let half_lambda = self.full(vec![1], lambda / 2.0, false)?;
        self.tensor_mul(sum, half_lambda)
    }

    /// Compute L1 regularization term.
    ///
    /// Returns sum of absolute weights * lambda.
    pub fn l1_regularization(
        &mut self,
        weights: TensorNodeId,
        lambda: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let abs = self.tensor_abs(weights)?;
        let sum = self.tensor_sum(abs)?;
        let lam = self.full(vec![1], lambda, false)?;
        self.tensor_mul(sum, lam)
    }

    // ── Learning Rate Utilities ───────────────────────────────────────────

    /// Compute learning rate with linear warmup.
    pub fn lr_linear_warmup(current_step: usize, warmup_steps: usize, base_lr: f64) -> f64 {
        if current_step < warmup_steps {
            base_lr * current_step as f64 / warmup_steps as f64
        } else {
            base_lr
        }
    }

    /// Compute learning rate with cosine annealing.
    pub fn lr_cosine_annealing(
        current_step: usize,
        total_steps: usize,
        base_lr: f64,
        min_lr: f64,
    ) -> f64 {
        if current_step >= total_steps {
            return min_lr;
        }
        let progress = current_step as f64 / total_steps as f64;
        min_lr + (base_lr - min_lr) * (1.0 + (std::f64::consts::PI * progress).cos()) / 2.0
    }

    /// Compute learning rate with warmup + cosine decay.
    pub fn lr_warmup_cosine(
        current_step: usize,
        warmup_steps: usize,
        total_steps: usize,
        base_lr: f64,
        min_lr: f64,
    ) -> f64 {
        if current_step < warmup_steps {
            Self::lr_linear_warmup(current_step, warmup_steps, base_lr)
        } else {
            Self::lr_cosine_annealing(
                current_step - warmup_steps,
                total_steps - warmup_steps,
                base_lr,
                min_lr,
            )
        }
    }

    // ── Tokenizer Utilities ───────────────────────────────────────────────

    /// Add BOS (Beginning of Sequence) token.
    pub fn add_bos_token(
        &mut self,
        input: TensorNodeId,
        bos_id: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        if shape.is_empty() {
            return Err(Self::incompatible_tensor_args(
                "add_bos_token: input cannot be scalar",
            ));
        }
        let mut bos_shape = shape.clone();
        bos_shape[shape.len() - 1] = 1;
        let bos = self.full(bos_shape, bos_id, false)?;
        self.tensor_cat(&[bos, input], shape.len() - 1)
    }

    /// Add EOS (End of Sequence) token.
    pub fn add_eos_token(
        &mut self,
        input: TensorNodeId,
        eos_id: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        if shape.is_empty() {
            return Err(Self::incompatible_tensor_args(
                "add_eos_token: input cannot be scalar",
            ));
        }
        let mut eos_shape = shape.clone();
        eos_shape[shape.len() - 1] = 1;
        let eos = self.full(eos_shape, eos_id, false)?;
        self.tensor_cat(&[input, eos], shape.len() - 1)
    }

    /// Pad sequence to target length.
    pub fn pad_sequence_to_length(
        &mut self,
        input: TensorNodeId,
        target_length: usize,
        pad_id: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        let current_length = shape[shape.len() - 1];
        if current_length >= target_length {
            return Ok(input);
        }
        let pad_length = target_length - current_length;
        let mut pad_shape = shape.clone();
        pad_shape[shape.len() - 1] = pad_length;
        let pad = self.full(pad_shape, pad_id, false)?;
        self.tensor_cat(&[input, pad], shape.len() - 1)
    }

    // ── Numerical Stability Utilities ────────────────────────────────────

    /// Clamp values to avoid numerical instability (log of small numbers etc).
    pub fn clamp_for_log(
        &mut self,
        input: TensorNodeId,
        min_val: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_clamp_min(input, min_val)
    }

    /// Safe log: clamps input to avoid -inf.
    pub fn safe_log(
        &mut self,
        input: TensorNodeId,
        eps: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let clamped = self.tensor_clamp_min(input, eps)?;
        self.tensor_log(clamped)
    }

    /// Safe division: avoids div by zero by adding eps to denominator.
    pub fn safe_div(
        &mut self,
        num: TensorNodeId,
        denom: TensorNodeId,
        eps: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let eps_tensor = self.full(vec![1], eps, false)?;
        let safe_denom = self.tensor_add(denom, eps_tensor)?;
        self.tensor_div(num, safe_denom)
    }

    /// Numerically stable sigmoid using tanh: sigmoid(x) = 0.5 * (tanh(x/2) + 1).
    pub fn stable_sigmoid(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let half = self.full(vec![1], 0.5, false)?;
        let half_x = self.tensor_mul(input, half)?;
        let tanh_half = self.tensor_tanh(half_x)?;
        let one = self.full(vec![1], 1.0, false)?;
        let plus_one = self.tensor_add(tanh_half, one)?;
        self.tensor_mul(plus_one, half)
    }

    /// Softsign activation: x / (1 + |x|).
    pub fn softsign(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let abs_x = self.tensor_abs(input)?;
        let one = self.full(vec![1], 1.0, false)?;
        let denom = self.tensor_add(abs_x, one)?;
        self.tensor_div(input, denom)
    }

    /// Threshold activation: `x` where `x > threshold`, else `value`
    /// (`torch.nn.functional.threshold`).
    ///
    /// Delegates to the canonical `tensor_threshold`. The previous body
    /// reimplemented it by pulling `tensor_values` (F64-only -> errored on f32
    /// input), mapping in scalar f64, then building a FRESH `tensor_variable`
    /// detached from `input` (so backward produced NO gradient — a silent
    /// grad-breaking bug), and used the old `NaN -> value` rule. tensor_threshold
    /// composes autograd-aware ops (gradient flows), preserves the input dtype,
    /// and propagates NaN like current PyTorch.
    pub fn threshold_activation(
        &mut self,
        input: TensorNodeId,
        thresh: f64,
        value: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_threshold(input, thresh, value)
    }

    // ── Batch Utilities ──────────────────────────────────────────────────

    /// Get batch size from a batched tensor.
    pub fn batch_size(&self, input: TensorNodeId) -> Result<usize, AutogradError> {
        let shape = self.tensor_shape(input)?;
        if shape.is_empty() {
            return Err(Self::incompatible_tensor_args(
                "batch_size: scalar has no batch dimension",
            ));
        }
        Ok(shape[0])
    }

    /// Repeat tensor along batch dimension.
    pub fn repeat_batch(
        &mut self,
        input: TensorNodeId,
        repeats: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        let mut repeat_dims = vec![1; shape.len()];
        repeat_dims[0] = repeats;
        self.tensor_repeat(input, &repeat_dims)
    }

    /// Interleave batches from two tensors: [a0, b0, a1, b1, ...].
    pub fn interleave_batch(
        &mut self,
        a: TensorNodeId,
        b: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape_a = self.tensor_shape(a)?;
        let shape_b = self.tensor_shape(b)?;
        if shape_a != shape_b {
            return Err(Self::incompatible_tensor_args(
                "interleave_batch: shapes must match",
            ));
        }
        let stacked = self.tensor_stack(&[a, b], 1)?;
        let mut new_shape = shape_a.clone();
        new_shape[0] *= 2;
        self.tensor_reshape(stacked, new_shape)
    }

    // ── Sequence Utilities ───────────────────────────────────────────────

    /// Get the last token from each sequence in a batch: [B, T, D] -> [B, D].
    pub fn get_last_token(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        if shape.len() < 2 {
            return Err(Self::incompatible_tensor_args(
                "get_last_token: requires at least 2D tensor",
            ));
        }
        let t = shape[1];
        let sliced = self.tensor_narrow(input, 1, t - 1, 1)?;
        self.tensor_squeeze(sliced, 1)
    }

    /// Get the first token from each sequence in a batch: [B, T, D] -> [B, D].
    pub fn get_first_token(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let sliced = self.tensor_narrow(input, 1, 0, 1)?;
        self.tensor_squeeze(sliced, 1)
    }

    /// Shift sequence left (for causal language modeling targets).
    pub fn shift_left(
        &mut self,
        input: TensorNodeId,
        pad_value: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        if shape.len() < 2 {
            return Err(Self::incompatible_tensor_args(
                "shift_left: requires at least 2D tensor",
            ));
        }
        let t = shape[1];
        let shifted = self.tensor_narrow(input, 1, 1, t - 1)?;
        let mut pad_shape = shape.clone();
        pad_shape[1] = 1;
        let pad = self.full(pad_shape, pad_value, false)?;
        self.tensor_cat(&[shifted, pad], 1)
    }

    /// Shift sequence right (for decoder input from targets).
    pub fn shift_right(
        &mut self,
        input: TensorNodeId,
        pad_value: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        if shape.len() < 2 {
            return Err(Self::incompatible_tensor_args(
                "shift_right: requires at least 2D tensor",
            ));
        }
        let t = shape[1];
        let shifted = self.tensor_narrow(input, 1, 0, t - 1)?;
        let mut pad_shape = shape.clone();
        pad_shape[1] = 1;
        let pad = self.full(pad_shape, pad_value, false)?;
        self.tensor_cat(&[pad, shifted], 1)
    }

    // ── Tensor Norm Utilities ────────────────────────────────────────────

    /// Compute Frobenius norm: sqrt(sum(x^2)).
    pub fn frobenius_norm(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let sq = self.tensor_mul(input, input)?;
        let sum = self.tensor_sum(sq)?;
        self.tensor_sqrt(sum)
    }

    /// Compute L1 norm: sum(|x|).
    pub fn l1_norm(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let abs = self.tensor_abs(input)?;
        self.tensor_sum(abs)
    }

    /// Compute max norm: max(|x|).
    pub fn max_norm(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let abs = self.tensor_abs(input)?;
        let shape = self.tensor_shape(abs)?;
        let ndim = shape.len();
        let flat = if ndim > 1 {
            self.tensor_flatten(abs, 0, ndim - 1)?
        } else {
            abs
        };
        self.tensor_amax(flat, 0)
    }

    /// Normalize tensor to unit norm.
    pub fn normalize_to_unit(
        &mut self,
        input: TensorNodeId,
        eps: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        let norm = self.frobenius_norm(input)?;
        let eps_tensor = self.full(vec![1], eps, false)?;
        let safe_norm = self.tensor_add(norm, eps_tensor)?;
        // safe_norm is a scalar [1]; broadcast it to the input shape before the
        // divide (tensor_div does not broadcast a size-1 axis). frankentorch-3pvd.
        let ones = vec![1usize; shape.len()];
        let norm_r = self.tensor_reshape(safe_norm, ones)?;
        let norm_b = self.tensor_expand(norm_r, shape)?;
        self.tensor_div(input, norm_b)
    }

    // ── Reduction Utilities ──────────────────────────────────────────────

    /// Compute mean along last dimension.
    pub fn mean_last_dim(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        let last_dim = shape.len() - 1;
        self.tensor_mean_dim(input, last_dim)
    }

    /// Compute sum along last dimension.
    pub fn sum_last_dim(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        let last_dim = shape.len() - 1;
        self.tensor_sum_dim(input, last_dim)
    }

    /// Compute max along last dimension (values only).
    pub fn max_last_dim(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        let last_dim = shape.len() - 1;
        self.tensor_amax(input, last_dim)
    }

    /// Compute min along last dimension (values only).
    pub fn min_last_dim(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        let last_dim = shape.len() - 1;
        self.tensor_amin(input, last_dim)
    }

    // ── Shape Manipulation Utilities ─────────────────────────────────────

    /// Add a dimension at the end of the tensor.
    pub fn unsqueeze_last(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        self.tensor_unsqueeze(input, shape.len())
    }

    /// Add a dimension at the beginning of the tensor.
    pub fn unsqueeze_first(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        self.tensor_unsqueeze(input, 0)
    }

    /// Broadcast tensor to match target shape.
    pub fn broadcast_to(
        &mut self,
        input: TensorNodeId,
        target_shape: Vec<usize>,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_expand(input, target_shape)
    }

    /// Flatten all dimensions.
    pub fn flatten_all(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        let numel: usize = shape.iter().product();
        self.tensor_reshape(input, vec![numel])
    }

    /// Flatten except batch dimension.
    pub fn flatten_except_batch(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        if shape.len() <= 1 {
            return Ok(input);
        }
        let batch = shape[0];
        let rest: usize = shape[1..].iter().product();
        self.tensor_reshape(input, vec![batch, rest])
    }

    // ── Masking Utilities ────────────────────────────────────────────────

    /// Create a mask from length values (for variable-length sequences).
    pub fn lengths_to_mask(
        &mut self,
        lengths: TensorNodeId,
        max_len: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let lengths_data = self.tensor_values(lengths)?;
        let batch_size = lengths_data.len();
        let mut mask_data = vec![0.0f64; batch_size * max_len];
        for (b, &len) in lengths_data.iter().enumerate() {
            let len_usize = len as usize;
            for t in 0..len_usize.min(max_len) {
                mask_data[b * max_len + t] = 1.0;
            }
        }
        self.tensor_variable(mask_data, vec![batch_size, max_len], false)
    }

    /// Apply mask to tensor (sets masked positions to value).
    pub fn masked_fill(
        &mut self,
        input: TensorNodeId,
        mask: TensorNodeId,
        value: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let value_tensor = self.full(vec![1], value, false)?;
        self.tensor_where(mask, value_tensor, input)
    }

    // ── Embedding Utilities ──────────────────────────────────────────────

    /// Simple embedding lookup (like nn.Embedding without trainable weights).
    pub fn embedding_lookup(
        &mut self,
        weight: TensorNodeId,
        indices: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_index_select(weight, 0, indices)
    }

    /// Sum of embeddings for a bag of indices.
    pub fn embedding_bag_sum(
        &mut self,
        weight: TensorNodeId,
        indices: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let embedded = self.tensor_index_select(weight, 0, indices)?;
        self.tensor_sum_dim(embedded, 0)
    }

    /// Mean of embeddings for a bag of indices.
    pub fn embedding_bag_mean(
        &mut self,
        weight: TensorNodeId,
        indices: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let embedded = self.tensor_index_select(weight, 0, indices)?;
        self.tensor_mean_dim(embedded, 0)
    }

    // ── Distance Utilities ───────────────────────────────────────────────

    /// Compute pairwise L2 distance squared between two sets of vectors.
    pub fn pairwise_distance_squared(
        &mut self,
        x: TensorNodeId,
        y: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let diff = self.tensor_sub(x, y)?;
        let sq = self.tensor_mul(diff, diff)?;
        let shape = self.tensor_shape(sq)?;
        let last_dim = shape.len() - 1;
        self.tensor_sum_dim(sq, last_dim)
    }

    /// Compute cosine distance: 1 - cosine_similarity.
    pub fn cosine_distance(
        &mut self,
        x: TensorNodeId,
        y: TensorNodeId,
        eps: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(x)?;
        let last_dim = shape.len() - 1;
        let sim = self.tensor_cosine_similarity(x, y, last_dim, eps)?;
        let one = self.full(vec![1], 1.0, false)?;
        self.tensor_sub(one, sim)
    }

    // ── Comparison Utilities ─────────────────────────────────────────────

    /// Check if all elements are True (> 0).
    pub fn all_true(&mut self, input: TensorNodeId) -> Result<bool, AutogradError> {
        // Borrow zero-copy (the previous `tensor_values` cloned the full input just to
        // short-circuit-scan); fall back to an owned read for a non-contiguous view.
        match self.tensor_tape.values_borrowed(input) {
            Ok(v) => Ok(v.iter().all(|&x| x > 0.0)),
            Err(_) => Ok(self.tensor_values(input)?.iter().all(|&x| x > 0.0)),
        }
    }

    /// Check if any element is True (> 0).
    pub fn any_true(&mut self, input: TensorNodeId) -> Result<bool, AutogradError> {
        match self.tensor_tape.values_borrowed(input) {
            Ok(v) => Ok(v.iter().any(|&x| x > 0.0)),
            Err(_) => Ok(self.tensor_values(input)?.iter().any(|&x| x > 0.0)),
        }
    }

    // ── Gradient Control ─────────────────────────────────────────────────

    /// Detach tensor from computation graph (creates a leaf copy).
    pub fn detach_copy(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let data = self.tensor_values(input)?;
        let shape = self.tensor_shape(input)?;
        self.tensor_variable(data, shape, false)
    }

    /// Create a copy with gradients enabled.
    pub fn requires_grad_copy(
        &mut self,
        input: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let data = self.tensor_values(input)?;
        let shape = self.tensor_shape(input)?;
        self.tensor_variable(data, shape, true)
    }

    // ── Tensor Arithmetic Utilities ──────────────────────────────────────

    /// Compute element-wise power with scalar exponent.
    pub fn pow_scalar(
        &mut self,
        input: TensorNodeId,
        exponent: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        // Delegate to the canonical scalar-pow (dispatch_scalar_pow). The old
        // body built a [1] exponent leaf and went through tensor_pow_tensor,
        // which REQUIRES equal shapes — so pow_scalar errored for any non-[1]
        // input — and materialized an F64 exponent that upcast f32 bases to F64.
        // tensor_pow applies the scalar directly to the input tensor, preserving
        // both shape and dtype (weak-scalar parity, cf. bead frankentorch-cijv).
        self.tensor_pow(input, exponent)
    }

    /// Compute cube of each element.
    pub fn cube(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let sq = self.tensor_mul(input, input)?;
        self.tensor_mul(sq, input)
    }

    /// Build a 1-element scalar leaf whose dtype matches `input`.
    ///
    /// `full` always materializes an F64 leaf, and the elementwise binary ops
    /// promote `f32 + f64 -> f64`. PyTorch treats a Python scalar as a *weak*
    /// operand (`float32_tensor + 2.0 -> float32`), so a scalar op must not
    /// upcast its input. Casting the scalar to the input dtype restores parity;
    /// F64 and non-float inputs keep the original F64 scalar unchanged, so those
    /// paths are bit-identical to before.
    fn scalar_leaf_matching_dtype(
        &mut self,
        input: TensorNodeId,
        scalar: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let s = self.full(vec![1], scalar, false)?;
        match self.tensor_dtype(input)? {
            dt @ (DType::F32 | DType::F16 | DType::BF16) => self.tensor_tape.to_dtype(s, dt),
            _ => Ok(s),
        }
    }

    /// Build a full-`shape` constant whose dtype matches `input`.
    ///
    /// Like [`scalar_leaf_matching_dtype`] but materializes the constant at the
    /// input's shape (for ops that compose a const through `tensor_where`/
    /// `tensor_sub` with the input). `full` always makes an F64 leaf, which
    /// would promote an f32 input to F64; casting the const to the input dtype
    /// keeps activations dtype-preserving (PyTorch keeps `float32` activations
    /// `float32`). F64 and non-float inputs keep the original F64 const.
    fn const_tensor_like(
        &mut self,
        input: TensorNodeId,
        shape: Vec<usize>,
        value: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let t = self.full(shape, value, false)?;
        match self.tensor_dtype(input)? {
            dt @ (DType::F32 | DType::F16 | DType::BF16) => self.tensor_tape.to_dtype(t, dt),
            _ => Ok(t),
        }
    }

    /// Add scalar to tensor.
    /// No-grad fast path for a scalar elementwise map: the `*_scalar` ops below build a
    /// full-size scalar leaf (`scalar_leaf_matching_dtype`) then run a broadcasting binary
    /// op — measured ~4x SLOWER than torch. For no-grad contiguous f64, borrow the input and
    /// apply `f` directly, only using rayon at the measured scalar-map knee where parallel
    /// execution pays for itself. Returns `None` (fall through to the leaf+binary path)
    /// for grad / non-f64 / non-contiguous. Bit-exact when `f(x) == x <op> scalar` (the binary
    /// kernel computes the same per-element expression against a constant operand).
    fn no_grad_scalar_map_f64<F: Fn(f64) -> f64 + Sync>(
        &mut self,
        input: TensorNodeId,
        f: F,
    ) -> Result<Option<TensorNodeId>, AutogradError> {
        if self.tensor_requires_grad(input)? || self.tensor_dtype(input)? != DType::F64 {
            return Ok(None);
        }
        let built = {
            let it = self.tensor_tape.tensor(input)?;
            if it.meta().is_contiguous() {
                let xd = it.contiguous_values()?;
                let out: Vec<f64> = if xd.len() >= SCALAR_MAP_PARALLEL_MIN {
                    use rayon::prelude::*;
                    xd.par_iter().map(|&x| f(x)).collect()
                } else {
                    xd.iter().map(|&x| f(x)).collect()
                };
                Some(out)
            } else {
                None
            }
        };
        match built {
            Some(out) => {
                let shape = self.tensor_shape(input)?;
                Ok(Some(self.tensor_variable(out, shape, false)?))
            }
            None => Ok(None),
        }
    }

    /// F32 sibling of [`Self::no_grad_scalar_map_f64`]. The scalar ops' fallback builds an f32
    /// `scalar_leaf_matching_dtype` (= `scalar as f32`) and runs an f32 tensor op, so a single
    /// parallel `f(x_f32)` pass — where `f` already casts the scalar to f32 — is bit-exact with that
    /// fallback while skipping its clone+broadcast+tape nodes. Without this, f32 add/sub/mul/div by a
    /// scalar fell through to the tape path (~5-6x SLOWER than torch).
    fn no_grad_scalar_map_f32<F: Fn(f32) -> f32 + Sync>(
        &mut self,
        input: TensorNodeId,
        f: F,
    ) -> Result<Option<TensorNodeId>, AutogradError> {
        if self.tensor_requires_grad(input)? || self.tensor_dtype(input)? != DType::F32 {
            return Ok(None);
        }
        let built = {
            let it = self.tensor_tape.tensor(input)?;
            if it.meta().is_contiguous() {
                let xd = it.contiguous_values_f32()?;
                let out: Vec<f32> = if xd.len() >= SCALAR_MAP_PARALLEL_MIN {
                    use rayon::prelude::*;
                    xd.par_iter().map(|&x| f(x)).collect()
                } else {
                    xd.iter().map(|&x| f(x)).collect()
                };
                Some(out)
            } else {
                None
            }
        };
        match built {
            Some(out) => {
                let shape = self.tensor_shape(input)?;
                Ok(Some(self.tensor_variable_f32(out, shape, false)?))
            }
            None => Ok(None),
        }
    }

    pub fn add_scalar(
        &mut self,
        input: TensorNodeId,
        scalar: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        if let Some(out) = self.no_grad_scalar_map_f64(input, |x| x + scalar)? {
            return Ok(out);
        }
        if let Some(out) = self.no_grad_scalar_map_f32(input, |x| x + scalar as f32)? {
            return Ok(out);
        }
        let s = self.scalar_leaf_matching_dtype(input, scalar)?;
        self.tensor_add(input, s)
    }

    /// Subtract scalar from tensor.
    pub fn sub_scalar(
        &mut self,
        input: TensorNodeId,
        scalar: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        if let Some(out) = self.no_grad_scalar_map_f64(input, |x| x - scalar)? {
            return Ok(out);
        }
        if let Some(out) = self.no_grad_scalar_map_f32(input, |x| x - scalar as f32)? {
            return Ok(out);
        }
        let s = self.scalar_leaf_matching_dtype(input, scalar)?;
        self.tensor_sub(input, s)
    }

    /// Multiply tensor by scalar.
    pub fn mul_scalar(
        &mut self,
        input: TensorNodeId,
        scalar: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        if let Some(out) = self.no_grad_scalar_map_f64(input, |x| x * scalar)? {
            return Ok(out);
        }
        if let Some(out) = self.no_grad_scalar_map_f32(input, |x| x * scalar as f32)? {
            return Ok(out);
        }
        let s = self.scalar_leaf_matching_dtype(input, scalar)?;
        self.tensor_mul(input, s)
    }

    /// Divide tensor by scalar.
    pub fn div_scalar(
        &mut self,
        input: TensorNodeId,
        scalar: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        if let Some(out) = self.no_grad_scalar_map_f64(input, |x| x / scalar)? {
            return Ok(out);
        }
        if let Some(out) = self.no_grad_scalar_map_f32(input, |x| x / scalar as f32)? {
            return Ok(out);
        }
        let s = self.scalar_leaf_matching_dtype(input, scalar)?;
        self.tensor_div(input, s)
    }

