    // ── Matrix Utilities ──────────────────────────────────────────────────

    /// Transpose last two dimensions (batch matrix transpose).
    pub fn transpose_batch(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        let ndim = shape.len();
        if ndim < 2 {
            return Err(Self::incompatible_tensor_args("need at least 2 dims"));
        }
        self.tensor_transpose(input, ndim - 2, ndim - 1)
    }

    /// Swap two dimensions.
    pub fn swap_dims(
        &mut self,
        input: TensorNodeId,
        dim0: usize,
        dim1: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_transpose(input, dim0, dim1)
    }

    // ── Reduction with Keepdim ────────────────────────────────────────────

    /// Mean along dimension, keeping dimension.
    pub fn mean_keepdim(
        &mut self,
        input: TensorNodeId,
        dim: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let result = self.tensor_mean_dim(input, dim)?;
        self.tensor_unsqueeze(result, dim)
    }

    /// Sum along dimension, keeping dimension.
    pub fn sum_keepdim(
        &mut self,
        input: TensorNodeId,
        dim: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let result = self.tensor_sum_dim(input, dim)?;
        self.tensor_unsqueeze(result, dim)
    }

    /// Max along dimension, keeping dimension.
    pub fn max_keepdim(
        &mut self,
        input: TensorNodeId,
        dim: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let result = self.tensor_amax(input, dim)?;
        self.tensor_unsqueeze(result, dim)
    }

    /// Min along dimension, keeping dimension.
    pub fn min_keepdim(
        &mut self,
        input: TensorNodeId,
        dim: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let result = self.tensor_amin(input, dim)?;
        self.tensor_unsqueeze(result, dim)
    }

    /// Resolve, validate (range + no duplicates), and sort a list of reduction
    /// dims for an N-D input. An empty list means "reduce over all dims"
    /// (torch's `dim=[]` semantics for sum/mean/amax/amin). Negative dims count
    /// from the end.
    fn normalize_reduce_dims(
        &mut self,
        input: TensorNodeId,
        dims: &[i64],
    ) -> Result<Vec<usize>, AutogradError> {
        let rank = self.tensor_shape(input)?.len();
        if dims.is_empty() {
            return Ok((0..rank).collect());
        }
        let mut norm: Vec<usize> = Vec::with_capacity(dims.len());
        for &d in dims {
            let r = if d < 0 { d + rank as i64 } else { d };
            if r < 0 || r as usize >= rank {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "reduce: dim out of range",
                    },
                )));
            }
            let u = r as usize;
            if norm.contains(&u) {
                return Err(AutogradError::Dispatch(ft_dispatch::DispatchError::Key(
                    ft_dispatch::DispatchKeyError::IncompatibleSet {
                        reason: "reduce: a dim appears multiple times in the list of dims",
                    },
                )));
            }
            norm.push(u);
        }
        norm.sort_unstable();
        Ok(norm)
    }

    /// Reduce `input` over multiple `dims` by applying a single-dim reduction
    /// from the highest dim to the lowest, so the lower dim indices stay valid
    /// as higher dims collapse. With `keepdim`, a size-1 axis is re-inserted at
    /// each reduced position (ascending, reconstructing torch's keepdim shape).
    ///
    /// IMPORTANT: only valid for SELECTION reductions (amax/amin), where the
    /// staged result picks the exact same element as a single joint reduction
    /// — so it is bit-identical to torch. Arithmetic reductions (sum, mean,
    /// logsumexp) are NOT safe here: torch reduces the joined dims in one pass
    /// with a different floating-point summation/rounding order than dim-by-dim
    /// staging, so the results disagree by up to ~1e-7. Those need a true joint
    /// kernel (tracked separately) and must not be composed via this helper.
    fn reduce_over_dims(
        &mut self,
        input: TensorNodeId,
        dims: &[i64],
        keepdim: bool,
        reduce_one: fn(&mut Self, TensorNodeId, usize) -> Result<TensorNodeId, AutogradError>,
    ) -> Result<TensorNodeId, AutogradError> {
        let norm = self.normalize_reduce_dims(input, dims)?;
        let mut current = input;
        for &d in norm.iter().rev() {
            current = reduce_one(self, current, d)?;
        }
        if keepdim {
            for &d in &norm {
                current = self.tensor_unsqueeze(current, d)?;
            }
        }
        Ok(current)
    }

    /// `torch.amax(input, dim=dims, keepdim=keepdim)` over multiple dims. Empty
    /// `dims` reduces over all dims; negative dims count from the end. Bit-exact
    /// to torch because max selects an actual element (staging picks the same
    /// global maximum). Composes through the autograd-aware per-dim amax, so
    /// the gradient routes to the maximal position.
    pub fn tensor_amax_dims(
        &mut self,
        input: TensorNodeId,
        dims: &[i64],
        keepdim: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        self.reduce_over_dims(input, dims, keepdim, Self::tensor_amax)
    }

    /// `torch.amin(input, dim=dims, keepdim=keepdim)` over multiple dims.
    /// Bit-exact to torch (min selects an actual element). See
    /// [`Self::tensor_amax_dims`].
    pub fn tensor_amin_dims(
        &mut self,
        input: TensorNodeId,
        dims: &[i64],
        keepdim: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        self.reduce_over_dims(input, dims, keepdim, Self::tensor_amin)
    }

    /// Reduce `input` over multiple `dims` as a SINGLE joint reduction: permute
    /// the reduced dims to the end (keeping each group's original order),
    /// reshape to `[kept_flat, reduced_flat]`, and reduce once over the last
    /// axis. Unlike dim-by-dim staging (which drifts ~1e-7 for arithmetic
    /// reductions), this matches torch's joint reduction to ~1 ULP — well
    /// within the project's ~1e-12 reduction tolerance — because the reduced
    /// elements are summed contiguously in one pass, like torch. Use this for
    /// arithmetic reductions (sum/mean/logsumexp); amax/amin use the cheaper
    /// staging path since selection is order-independent.
    fn reduce_over_dims_joint(
        &mut self,
        input: TensorNodeId,
        dims: &[i64],
        keepdim: bool,
        reduce_last: fn(&mut Self, TensorNodeId, usize) -> Result<TensorNodeId, AutogradError>,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        let rank = shape.len();
        let norm = self.normalize_reduce_dims(input, dims)?;
        let kept: Vec<usize> = (0..rank).filter(|d| !norm.contains(d)).collect();

        // permute: kept dims (original order) ++ reduced dims (ascending order).
        let perm: Vec<usize> = kept.iter().chain(norm.iter()).copied().collect();
        let permuted = self.tensor_permute(input, perm)?;

        let kept_numel: usize = kept.iter().map(|&d| shape[d]).product();
        let reduced_numel: usize = norm.iter().map(|&d| shape[d]).product();
        let reshaped = self.tensor_reshape(permuted, vec![kept_numel, reduced_numel])?;
        // Reduce over the (now contiguous) reduced axis -> [kept_numel].
        let reduced = reduce_last(self, reshaped, 1)?;

        let out_shape: Vec<usize> = if keepdim {
            let mut s = shape.clone();
            for &d in &norm {
                s[d] = 1;
            }
            s
        } else {
            kept.iter().map(|&d| shape[d]).collect()
        };
        // out_shape's row-major layout equals the kept-ascending flatten, so a
        // plain reshape lands every value in its torch position (the size-1
        // axes for keepdim do not move elements).
        self.tensor_reshape(reduced, out_shape)
    }

    /// `torch.sum(input, dim=dims, keepdim=keepdim)` over multiple dims. Empty
    /// `dims` reduces over all dims; negative dims count from the end. Matches
    /// torch's joint reduction to ~1 ULP (within the ~1e-12 reduction
    /// tolerance) and composes through autograd, so gradients flow to input.
    pub fn tensor_sum_dims(
        &mut self,
        input: TensorNodeId,
        dims: &[i64],
        keepdim: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        self.reduce_over_dims_joint(input, dims, keepdim, Self::tensor_sum_dim)
    }

    /// `torch.mean(input, dim=dims, keepdim=keepdim)` over multiple dims.
    pub fn tensor_mean_dims(
        &mut self,
        input: TensorNodeId,
        dims: &[i64],
        keepdim: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        self.reduce_over_dims_joint(input, dims, keepdim, Self::tensor_mean_dim)
    }

    /// `torch.logsumexp(input, dim=dims, keepdim=keepdim)` over multiple dims.
    pub fn tensor_logsumexp_dims(
        &mut self,
        input: TensorNodeId,
        dims: &[i64],
        keepdim: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        self.reduce_over_dims_joint(input, dims, keepdim, Self::tensor_logsumexp)
    }

    /// `torch.var(input, dim=dims, correction=correction, keepdim=keepdim)` over
    /// multiple dims. The divisor is `max(0, N - correction)` where `N` is the
    /// product of the reduced dim sizes — so `correction >= N` yields `+inf`
    /// (or `NaN` for an all-equal slice), matching torch's degrees-of-freedom
    /// clamp. The mean is taken with keepdim so it broadcasts against the input;
    /// the sum of squared deviations uses the joint reduction (~1 ULP of torch).
    /// Fully autograd-aware — `d var / d x = 2 (x - mean) / div`, with the
    /// mean-path term vanishing because the deviations sum to zero.
    pub fn tensor_var_dims(
        &mut self,
        input: TensorNodeId,
        dims: &[i64],
        correction: i64,
        keepdim: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        let norm = self.normalize_reduce_dims(input, dims)?;
        let n: usize = norm.iter().map(|&d| shape[d]).product();

        // keepdim mean so (input - mean) broadcasts across the reduced dims.
        let mean_kd = self.tensor_mean_dims(input, dims, true)?;
        let diff = self.tensor_sub(input, mean_kd)?;
        let sq = self.tensor_mul(diff, diff)?;
        let sum_sq = self.tensor_sum_dims(sq, dims, keepdim)?;

        // torch clamps the divisor at 0; dividing by 0 gives +inf (or NaN when
        // the numerator is also 0), exactly matching torch's var with
        // correction >= N.
        let denom = (n as i64 - correction).max(0) as f64;
        let denom_t = self.full(vec![1], denom, false)?;
        self.tensor_div(sum_sq, denom_t)
    }

    /// `torch.std(input, dim=dims, correction=correction, keepdim=keepdim)` over
    /// multiple dims — `sqrt` of [`Self::tensor_var_dims`].
    pub fn tensor_std_dims(
        &mut self,
        input: TensorNodeId,
        dims: &[i64],
        correction: i64,
        keepdim: bool,
    ) -> Result<TensorNodeId, AutogradError> {
        let var = self.tensor_var_dims(input, dims, correction, keepdim)?;
        self.tensor_sqrt(var)
    }

    // ── Softmax Variants ──────────────────────────────────────────────────

    /// Softmax along last dimension.
    pub fn softmax_last(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        self.tensor_softmax(input, shape.len() - 1)
    }

    /// Log-softmax along last dimension.
    pub fn log_softmax_last(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        self.tensor_log_softmax(input, shape.len() - 1)
    }

    /// Softmax along first dimension (batch softmax).
    pub fn softmax_first(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        self.tensor_softmax(input, 0)
    }

    // ── Normalization Utilities ───────────────────────────────────────────

    /// Center data (subtract mean).
    pub fn center(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let mean = self.tensor_mean(input)?;
        self.tensor_sub(input, mean)
    }

    /// Standardize data (subtract mean, divide by std).
    pub fn standardize(
        &mut self,
        input: TensorNodeId,
        eps: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let mean = self.tensor_mean(input)?;
        let std = self.tensor_std(input, 1)?;
        let centered = self.tensor_sub(input, mean)?;
        let eps_tensor = self.full(vec![1], eps, false)?;
        let std_safe = self.tensor_add(std, eps_tensor)?;
        self.tensor_div(centered, std_safe)
    }

    // ── Distance Utilities ────────────────────────────────────────────────

    /// Squared L2 distance between two tensors.
    pub fn l2_distance_squared(
        &mut self,
        a: TensorNodeId,
        b: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let diff = self.tensor_sub(a, b)?;
        let squared = self.tensor_mul(diff, diff)?;
        self.tensor_sum(squared)
    }

    /// L1 distance (Manhattan) between two tensors.
    pub fn l1_distance(
        &mut self,
        a: TensorNodeId,
        b: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let diff = self.tensor_sub(a, b)?;
        let abs_diff = self.tensor_abs(diff)?;
        self.tensor_sum(abs_diff)
    }

    // ── Attention Helpers ─────────────────────────────────────────────────

    /// Scale queries for attention (divide by sqrt(d_k)).
    pub fn attention_scale(
        &mut self,
        queries: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(queries)?;
        let d_k = shape[shape.len() - 1] as f64;
        let scale = 1.0 / d_k.sqrt();
        let scale_tensor = self.full(vec![1], scale, false)?;
        self.tensor_mul(queries, scale_tensor)
    }

    /// Compute attention scores (Q @ K^T / sqrt(d_k)).
    pub fn attention_scores(
        &mut self,
        queries: TensorNodeId,
        keys: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        let scaled_q = self.attention_scale(queries)?;
        let keys_t = self.transpose_batch(keys)?;
        self.tensor_matmul(scaled_q, keys_t)
    }

    // ── Gradient Clipping Helpers ─────────────────────────────────────────

    /// Compute gradient norm.
    pub fn compute_grad_norm(
        &mut self,
        grads: &[TensorNodeId],
        norm_type: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        if grads.is_empty() {
            return self.full(vec![], 0.0, false);
        }
        let mut total_norm = self.full(vec![], 0.0, false)?;
        for &grad in grads {
            let norm = self.tensor_norm(grad, norm_type)?;
            let norm_pow = if norm_type == 2.0 {
                self.tensor_mul(norm, norm)?
            } else {
                self.tensor_pow(norm, norm_type)?
            };
            total_norm = self.tensor_add(total_norm, norm_pow)?;
        }
        if norm_type == 2.0 {
            self.tensor_sqrt(total_norm)
        } else {
            let inv_norm = 1.0 / norm_type;
            self.tensor_pow(total_norm, inv_norm)
        }
    }

    // ── Weight Operations ─────────────────────────────────────────────────

    /// Scale weights by factor.
    pub fn scale_weights(
        &mut self,
        weights: TensorNodeId,
        scale: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let scale_tensor = self.full(vec![1], scale, false)?;
        self.tensor_mul(weights, scale_tensor)
    }

    /// Add noise to weights for regularization.
    pub fn add_weight_noise(
        &mut self,
        weights: TensorNodeId,
        std: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(weights)?;
        let requires_grad = self.tensor_tape.tensor_requires_grad(weights)?;
        let noise = self.tensor_randn(shape, requires_grad)?;
        let scaled_noise = self.scale_weights(noise, std)?;
        self.tensor_add(weights, scaled_noise)
    }

    // ── Loss Utility Functions ────────────────────────────────────────────

    /// Hinge loss for SVM-style classification.
    pub fn hinge_loss(
        &mut self,
        pred: TensorNodeId,
        target: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        // f32 -> F64 loss; compute in f64, narrow to f32 (torch hinge_loss(f32) -> f32).
        if self.tensor_dtype(pred)? == DType::F32 {
            let p64 = self.tensor_to_dtype(pred, DType::F64)?;
            let t64 = self.tensor_to_dtype(target, DType::F64)?;
            let loss64 = self.hinge_loss(p64, t64)?;
            return self.tensor_to_dtype(loss64, DType::F32);
        }
        let one = self.full(vec![1], 1.0, false)?;
        let prod = self.tensor_mul(pred, target)?;
        let margin = self.tensor_sub(one, prod)?;
        let zero = self.full(vec![1], 0.0, false)?;
        let loss = self.tensor_maximum(margin, zero)?;
        self.tensor_mean(loss)
    }

    // ── Tensor Manipulation ───────────────────────────────────────────────

    /// Tile tensor to fill target shape.
    pub fn tile_to_shape(
        &mut self,
        input: TensorNodeId,
        target_shape: &[usize],
    ) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        let mut repeats = Vec::with_capacity(target_shape.len());
        for (i, &target_dim) in target_shape.iter().enumerate() {
            let src_dim = if i < shape.len() { shape[i] } else { 1 };
            repeats.push((target_dim + src_dim - 1) / src_dim);
        }
        self.tensor_repeat(input, &repeats)
    }

    // ── Concatenation Variants ────────────────────────────────────────────

    /// Concatenate tensors along batch dimension.
    pub fn cat_batch(&mut self, tensors: &[TensorNodeId]) -> Result<TensorNodeId, AutogradError> {
        self.tensor_cat(tensors, 0)
    }

    /// Concatenate two tensors along specified dimension.
    pub fn cat_pair(
        &mut self,
        a: TensorNodeId,
        b: TensorNodeId,
        dim: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_cat(&[a, b], dim)
    }

    /// Stack tensors along new dimension 0.
    pub fn stack_batch(&mut self, tensors: &[TensorNodeId]) -> Result<TensorNodeId, AutogradError> {
        self.tensor_stack(tensors, 0)
    }

    // ── Mask Operations ───────────────────────────────────────────────────

    /// Apply boolean mask to select elements.
    pub fn masked_select_bool(
        &mut self,
        input: TensorNodeId,
        mask: TensorNodeId,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_masked_select(input, mask)
    }

    /// Fill tensor where mask is true.
    pub fn masked_fill_value(
        &mut self,
        input: TensorNodeId,
        mask: TensorNodeId,
        value: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_masked_fill(input, mask, value)
    }

    // ── Unique Operations ─────────────────────────────────────────────────

    /// Get unique elements (sorted).
    pub fn unique_sorted(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let (unique, _, _) = self.tensor_unique(input, true, false, false)?;
        Ok(unique)
    }

    /// Count occurrences of each value.
    pub fn value_counts(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        self.tensor_bincount(input, None, 0)
    }

    // ── Interpolation ─────────────────────────────────────────────────────

    /// Linear interpolation between two tensors.
    pub fn lerp_tensors(
        &mut self,
        start: TensorNodeId,
        end: TensorNodeId,
        weight: f64,
    ) -> Result<TensorNodeId, AutogradError> {
        self.tensor_lerp(start, end, weight)
    }

    // ── Type Checking ─────────────────────────────────────────────────────

    /// Check if tensor has valid gradient.
    pub fn has_grad(&self, input: TensorNodeId) -> Result<bool, AutogradError> {
        self.tensor_tape.tensor_requires_grad(input)
    }

    // ── Positional Encoding ───────────────────────────────────────────────

    /// Create sinusoidal positional encoding.
    pub fn sinusoidal_position_encoding(
        &mut self,
        seq_len: usize,
        d_model: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        // Each position owns a contiguous d_model row, so distribute the positions
        // across Rayon workers. Sinusoidal columns share one denominator per
        // even/odd pair; compute that pair's angle once, then emit sin/cos from
        // the same f64. The original angle formula and write positions stay
        // unchanged, so the result remains bit-for-bit identical to the serial
        // per-element formula.
        let mut encoding = vec![0.0_f64; seq_len * d_model];
        let denominators: Vec<f64> = (0..d_model.div_ceil(2))
            .map(|pair| (10000_f64).powf((2 * pair) as f64 / d_model as f64))
            .collect();
        let fill_row = |pos: usize, row: &mut [f64]| {
            let pos = pos as f64;
            let mut pair = 0usize;
            let mut i = 0usize;
            while i + 1 < row.len() {
                let angle = pos / denominators[pair];
                row[i] = angle.sin();
                row[i + 1] = angle.cos();
                pair += 1;
                i += 2;
            }
            if i < row.len() {
                let angle = pos / denominators[pair];
                row[i] = angle.sin();
            }
        };
        if seq_len >= 2 && seq_len * d_model >= PARALLEL_ELEMENTWISE_MIN {
            use rayon::prelude::*;
            encoding
                .par_chunks_mut(d_model)
                .enumerate()
                .for_each(|(pos, row)| fill_row(pos, row));
        } else {
            encoding
                .chunks_mut(d_model)
                .enumerate()
                .for_each(|(pos, row)| fill_row(pos, row));
        }
        self.tensor_tape
            .leaf(encoding, vec![seq_len, d_model], false)
    }

    // ── Relative Position Bias ────────────────────────────────────────────

    /// Create relative position indices for attention.
    pub fn relative_position_indices(
        &mut self,
        seq_len: usize,
    ) -> Result<TensorNodeId, AutogradError> {
        let mut indices = Vec::with_capacity(seq_len * seq_len);
        for i in 0..seq_len {
            for j in 0..seq_len {
                indices.push((j as i64 - i as i64 + seq_len as i64 - 1) as f64);
            }
        }
        self.tensor_tape
            .leaf(indices, vec![seq_len, seq_len], false)
    }

