    /// Zero out gradients (returns zeros with same shape).
    pub fn zero_grad_like(&mut self, input: TensorNodeId) -> Result<TensorNodeId, AutogradError> {
        let shape = self.tensor_shape(input)?;
        self.full(shape, 0.0, false)
    }

