    /// Sort tensor along dimension.
    pub fn sort_tensor(
        &mut self,
        input: TensorNodeId,
        dim: usize,
        descending: bool,
    ) -> Result<(TensorNodeId, Vec<usize>), AutogradError> {
        self.tensor_sort(input, dim, descending)
    }

    /// Argsort tensor along dimension.
    pub fn argsort_tensor(
        &mut self,
        input: TensorNodeId,
        dim: usize,
        descending: bool,
    ) -> Result<Vec<usize>, AutogradError> {
        let meta = self.tensor_tape.tensor_meta(input)?.clone();
        match meta.dtype() {
            DType::F64 => {
                let values = self.tensor_values(input)?;
                ft_kernel_cpu::argsort_tensor_contiguous_f64(&values, &meta, dim, descending)
                    .map_err(|error| {
                        AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(error))
                    })
            }
            DType::F32 => {
                let values = self.tensor_values_f32(input)?;
                ft_kernel_cpu::argsort_tensor_contiguous_f32(&values, &meta, dim, descending)
                    .map_err(|error| {
                        AutogradError::Dispatch(ft_dispatch::DispatchError::Kernel(error))
                    })
            }
            dtype => Err(AutogradError::DenseTensor(
                ft_core::DenseTensorError::UnsupportedDType(dtype),
            )),
        }
    }

