// ── torch.special helper approximations ─────────────────────────────────

/// Inverse error function approximation (Winitzki 2008, refined).
///
/// Accurate to ~1e-9 over [-1, 1].
/// Numerically stable log-sum-exp for two values.
///
/// Returns log(exp(a) + exp(b)) without overflow.
fn log_sum_exp(a: f64, b: f64) -> f64 {
    if a == f64::NEG_INFINITY {
        return b;
    }
    if b == f64::NEG_INFINITY {
        return a;
    }
    let max = a.max(b);
    max + ((a - max).exp() + (b - max).exp()).ln()
}

/// Numerically-stable softplus, identical to `ft_kernel_cpu::softplus_value`
/// (the kernel that backs `tensor_softplus`): `log1p(exp(x))` with PyTorch's
/// upper-threshold short circuit (beta=1, threshold=20). The naive
/// `(1.0 + x.exp()).ln()` overflows to +inf for x ≳ 709 and returns ≠ x for
/// large x, diverging from torch (and from `tensor_softplus`). frankentorch
/// softplus-overflow parity fix.
fn stable_softplus(x: f64) -> f64 {
    if x > 20.0 { x } else { x.exp().ln_1p() }
}

fn stable_softplus_f32(x: f32) -> f32 {
    if x > 20.0 { x } else { x.exp().ln_1p() }
}

/// Cubic interpolation weight (Keys, 1981 / Catmull-Rom spline, a = -0.75).
///
/// Used by bicubic interpolation in F.interpolate.
/// Reflect an index into [0, size-1] using symmetric reflection.
///
/// For `reflect` padding mode: the boundary is not repeated.
/// E.g., for size=4: ..., 3, 2, 1, [0, 1, 2, 3], 2, 1, 0, 1, ...
fn reflect_index(idx: isize, size: isize) -> usize {
    if size <= 1 {
        return 0;
    }
    let period = 2 * (size - 1);
    let mut i = idx.rem_euclid(period);
    if i >= size {
        i = period - i;
    }
    i as usize
}

fn cubic_weight(x: f64) -> f64 {
    let a = -0.75; // PyTorch default
    let abs_x = x.abs();
    if abs_x <= 1.0 {
        (a + 2.0) * abs_x * abs_x * abs_x - (a + 3.0) * abs_x * abs_x + 1.0
    } else if abs_x <= 2.0 {
        a * abs_x * abs_x * abs_x - 5.0 * a * abs_x * abs_x + 8.0 * a * abs_x - 4.0 * a
    } else {
        0.0
    }
}

/// Inverse error function with Boost/SciPy-style f64 rational approximations.
///
/// libm does not expose `erfinv`, and refining a rough guess through
/// `libm::erf` is not enough in the far tails: `erf(y)` can round back
/// to the input before `y` is close to the inverse. Use the same
/// 64-bit approximation structure as Boost.Math instead, which is also
/// the family of algorithms SciPy and PyTorch rely on for this surface.
/// Coefficients below are adapted from Boost.Math's `erf_inv`
/// implementation (Boost Software License 1.0).
fn erfinv_approx(x: f64) -> f64 {
    if x.is_nan() {
        return f64::NAN;
    }
    if x <= -1.0 {
        if x == -1.0 {
            return f64::NEG_INFINITY;
        }
        return f64::NAN;
    }
    if x >= 1.0 {
        if x == 1.0 {
            return f64::INFINITY;
        }
        return f64::NAN;
    }
    if x == 0.0 {
        return x; // preserves the sign of ±0.0.
    }

    let sign = if x < 0.0 { -1.0 } else { 1.0 };
    let p = x.abs();
    let q = 1.0 - p;
    sign * erfinv_positive_approx(p, q)
}

// ── High-precision modified Bessel I-family (Cephes, Moshier) ───────────────
// The previous A&S 9.8.x polynomials were only ~1.6e-7 relative — single
// precision, an ~8-orders-of-magnitude regression vs torch (which wraps the
// Cephes f64 routines). These Chebyshev expansions are accurate to ~1 ULP in
// f64 and bit-align with the upstream reference. Pure Rust; no C linkage.

/// Evaluate a Chebyshev series at `x` using Cephes' `chbevl` recurrence.
fn cephes_chbevl(x: f64, coef: &[f64]) -> f64 {
    let mut b0 = coef[0];
    let mut b1 = 0.0_f64;
    let mut b2 = 0.0_f64;
    for &c in &coef[1..] {
        b2 = b1;
        b1 = b0;
        b0 = x * b1 - b2 + c;
    }
    0.5 * (b0 - b2)
}

