/// exp(-|x|) * I0(x) — Cephes f64 precision.
fn cephes_i0e(x: f64) -> f64 {
    if x.is_nan() {
        return f64::NAN;
    }
    let ax = x.abs();
    if ax <= 8.0 {
        cephes_chbevl(ax / 2.0 - 2.0, &CEPHES_I0_A)
    } else {
        cephes_chbevl(32.0 / ax - 2.0, &CEPHES_I0_B) / ax.sqrt()
    }
}

/// Modified Bessel I0(x) — Cephes f64 precision (even in x).
fn cephes_i0(x: f64) -> f64 {
    let ax = x.abs();
    cephes_i0e(x) * ax.exp()
}

/// exp(-|x|) * I1(x) — Cephes f64 precision (odd in x).
fn cephes_i1e(x: f64) -> f64 {
    if x.is_nan() {
        return f64::NAN;
    }
    let z = x.abs();
    let mut r = if z <= 8.0 {
        cephes_chbevl(z / 2.0 - 2.0, &CEPHES_I1_A) * z
    } else {
        cephes_chbevl(32.0 / z - 2.0, &CEPHES_I1_B) / z.sqrt()
    };
    if x < 0.0 {
        r = -r;
    }
    r
}

/// Modified Bessel I1(x) — Cephes f64 precision (odd in x).
fn cephes_i1(x: f64) -> f64 {
    let ax = x.abs();
    cephes_i1e(x) * ax.exp()
}

/// Scalar modified Bessel I0 (Cephes f64; ~1 ULP, bit-aligned with torch).
fn bessel_i0_scalar(x: f64) -> f64 {
    cephes_i0(x)
}

/// Exponentially scaled I0: `exp(-|x|) * i0(x)`. Uses the same
/// polynomial pieces but applies the scaling inside the small-x
/// branch and folds it into the large-x branch's prefactor so the
/// large-x result stays bounded for arbitrary x. Tracked under
/// frankentorch-2vxa.
fn bessel_i0e_scalar(x: f64) -> f64 {
    cephes_i0e(x)
}

/// Scalar modified Bessel I1 via Abramowitz & Stegun 9.8.3 / 9.8.4
/// (frankentorch-ner6). Odd in x. The polynomial pieces are rated
/// to ~1.6e-7 relative.
fn bessel_i1_scalar(x: f64) -> f64 {
    cephes_i1(x)
}

fn bessel_i1_derivative_scalar(x: f64) -> f64 {
    if x.is_nan() {
        return f64::NAN;
    }
    if x == 0.0 {
        return 0.5;
    }
    if x.is_infinite() {
        return f64::INFINITY;
    }
    bessel_i0_scalar(x) - bessel_i1_scalar(x) / x
}

/// Exponentially scaled I1: `exp(-|x|) * i1(x)`. Same A&S
/// polynomials, with the exp(|x|) cancelled inside the large-x
/// branch so the result stays bounded for arbitrary x. Tracked
/// under frankentorch-ner6.
fn bessel_i1e_scalar(x: f64) -> f64 {
    cephes_i1e(x)
}

fn bessel_i1e_derivative_scalar(x: f64) -> f64 {
    if x.is_nan() {
        return f64::NAN;
    }
    if x == 0.0 {
        return 0.5;
    }
    let i1e = bessel_i1e_scalar(x);
    bessel_i0e_scalar(x) - i1e / x - x.signum() * i1e
}

/// Bessel function of the first kind J0 via polynomial approximation.
/// Uses Abramowitz & Stegun 9.4.1 / 9.4.3 for small/large arguments.
fn bessel_j0_scalar(x: f64) -> f64 {
    // libm::j0 is f64-accurate (~1 ULP) and bit-aligns with torch, which wraps
    // the same routine; the previous Numerical-Recipes polynomial was only
    // single precision (~1e-7). J0 is entire, so no domain guard is needed
    // (libm propagates NaN). frankentorch-2vxa.
    libm::j0(x)
}

/// Bessel function of the first kind J1 via polynomial approximation.
fn bessel_j1_scalar(x: f64) -> f64 {
    // libm::j1 is f64-accurate and torch-aligned (was single-precision NR).
    // J1 is entire (odd); libm propagates NaN. frankentorch-2vxa.
    libm::j1(x)
}

/// Bessel function of the second kind Y0 via polynomial approximation.
fn bessel_y0_scalar(x: f64) -> f64 {
    // Y0 is only defined for x > 0; preserve the existing x<=0 / NaN -> NaN
    // contract and route the valid domain through libm::y0 (f64-accurate,
    // torch-aligned; was single-precision NR). frankentorch-2vxa.
    if x.is_nan() || x <= 0.0 {
        return f64::NAN;
    }
    libm::y0(x)
}

/// Bessel function of the second kind Y1 via polynomial approximation.
fn bessel_y1_scalar(x: f64) -> f64 {
    // Y1 is only defined for x > 0; preserve the x<=0 / NaN -> NaN contract and
    // route the valid domain through libm::y1 (f64-accurate, torch-aligned; was
    // single-precision NR). frankentorch-2vxa.
    if x.is_nan() || x <= 0.0 {
        return f64::NAN;
    }
    libm::y1(x)
}

/// Modified Bessel function of the second kind K0.
// ── Modified Bessel K-family (Cephes f64 precision, ~1 ULP, torch-aligned) ──
// x <= K_SPLIT: full-f64 ascending series (minimal cancellation in this range).
// x  > K_SPLIT: the Cephes asymptotic Chebyshev expansion
//   K_ν(x) = exp(-x)·chbevl(8/x - 2, B_ν)/sqrt(x)
// which is the algorithm scipy/torch use — ~1 ULP for all x>2. The previous
// table-free asymptotic series was only ~1.5e-8 worst case at x≈9
// (frankentorch-4ixyt); the Cephes B-tables fix that to ~1e-16 (verified vs
// mpmath@30dp over x∈[2,30]: worst rel 1.9e-16 K0 / 4.3e-16 K1). K_SPLIT=2
// matches Cephes's own domain boundary. Reuses the Cephes i0/i1 + cephes_chbevl.
const EULER_GAMMA: f64 = 0.577_215_664_901_532_86;
const K_SPLIT: f64 = 2.0;

