    #[test]
    fn tensor_gelu_tanh_matches_torch() {
        // F.gelu(x, approximate='tanh') — the GPT-2 / BERT form. Goldens from
        // torch 2.12 (values and the backward gradient).
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s
            .tensor_variable(vec![-1.0, 0.0, 0.5, 1.0, 2.0], vec![5], true)
            .unwrap();
        let y = s.tensor_gelu_tanh(x).unwrap();
        let vals = s.tensor_values(y).unwrap();
        let want = [
            -0.15880800939172324,
            0.0,
            0.34571400982514394,
            0.8411919906082768,
            1.954597694087775,
        ];
        for (i, (g, w)) in vals.iter().zip(want.iter()).enumerate() {
            assert!((g - w).abs() <= 1e-9, "val[{i}]: {g} vs torch {w}");
        }
        // tanh-GELU diverges from the exact erf form (different approximation).
        let mut s2 = FrankenTorchSession::new(ExecutionMode::Strict);
        let xe = s2.tensor_variable(vec![-1.0], vec![1], false).unwrap();
        let exact_y = s2.tensor_gelu(xe).unwrap();
        let exact = s2.tensor_values(exact_y).unwrap();
        assert!(
            (exact[0] - vals[0]).abs() > 1e-6,
            "tanh form must differ from exact"
        );

        let loss = s.tensor_sum(y).unwrap();
        let report = s.tensor_backward(loss).unwrap();
        let grad = s.tensor_gradient(&report, x).unwrap();
        let want_grad = [
            -0.08296408384578252,
            0.5,
            0.8673699035346424,
            1.0829640838457826,
            1.0860992566236183,
        ];
        for (i, (g, w)) in grad.iter().zip(want_grad.iter()).enumerate() {
            assert!((g - w).abs() <= 1e-9, "grad[{i}]: {g} vs torch {w}");
        }
    }

