    #[test]
    fn tensor_huber_loss_functional_matches_torch_for_nonunit_delta() {
        // Regression for frankentorch-8fwi8: the functional path
        // (tensor_huber_loss / huber_loss_tensor) used to just delegate to
        // smooth_l1_loss(beta=delta), which is wrong for delta != 1 because
        // huber(delta) == delta * smooth_l1(beta=delta). Goldens from torch 2.12
        // F.huber_loss([0.5, 2.0], [0, 0], delta=0.5):
        //   none = [0.125, 0.875]   (smooth_l1 beta=0.5 would be [0.25, 1.75])
        //   sum  = 1.0,  mean = 0.5
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let pred = s.tensor_variable(vec![0.5, 2.0], vec![2], false).unwrap();
        let target = s.tensor_variable(vec![0.0, 0.0], vec![2], false).unwrap();

        let none = s.tensor_huber_loss(pred, target, "none", 0.5).unwrap();
        let nv = s.tensor_values(none).unwrap();
        assert!(
            (nv[0] - 0.125).abs() < 1e-12 && (nv[1] - 0.875).abs() < 1e-12,
            "huber none delta=0.5 expected [0.125, 0.875], got {nv:?}"
        );

        let sum = s.tensor_huber_loss(pred, target, "sum", 0.5).unwrap();
        assert!((s.tensor_values(sum).unwrap()[0] - 1.0).abs() < 1e-12);

        let mean = s.tensor_huber_loss(pred, target, "mean", 0.5).unwrap();
        assert!((s.tensor_values(mean).unwrap()[0] - 0.5).abs() < 1e-12);

        // delta=1 must stay byte-identical to smooth_l1 (the two coincide there).
        let h1 = s.tensor_huber_loss(pred, target, "none", 1.0).unwrap();
        let s1 = s.tensor_smooth_l1_loss(pred, target, "none", 1.0).unwrap();
        let (hv, sv) = (s.tensor_values(h1).unwrap(), s.tensor_values(s1).unwrap());
        assert_eq!(hv, sv, "huber(delta=1) must equal smooth_l1(beta=1)");

        // The alias must route through the corrected path too.
        let aliased = s.huber_loss_tensor(pred, target, "none", 0.5).unwrap();
        let av = s.tensor_values(aliased).unwrap();
        assert!((av[0] - 0.125).abs() < 1e-12 && (av[1] - 0.875).abs() < 1e-12);
    }

    #[test]
    fn tensor_huber_loss_functional_rejects_non_positive_delta() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let pred = s.tensor_variable(vec![1.0], vec![1], false).unwrap();
        let target = s.tensor_variable(vec![2.0], vec![1], false).unwrap();
        assert!(s.tensor_huber_loss(pred, target, "mean", 0.0).is_err());
        assert!(s.tensor_huber_loss(pred, target, "mean", -1.0).is_err());
    }

