    #[test]
    fn cosine_embedding_loss_backward_produces_gradients() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x1 = s
            .tensor_variable(vec![1.0, 2.0, 3.0], vec![1, 3], true)
            .unwrap();
        let x2 = s
            .tensor_variable(vec![4.0, 5.0, 6.0], vec![1, 3], true)
            .unwrap();
        let target = s.tensor_variable(vec![1.0], vec![1], false).unwrap();
        let loss = s.cosine_embedding_loss(x1, x2, target, 0.0).unwrap();
        let report = s.tensor_backward(loss).unwrap();
        assert!(
            s.tensor_gradient(&report, x1).is_some(),
            "should produce gradients for x1"
        );
        assert!(
            s.tensor_gradient(&report, x2).is_some(),
            "should produce gradients for x2"
        );
    }

    #[test]
    fn cosine_embedding_loss_mixed_targets() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        // Batch of 2: first pair similar (target=1), second pair dissimilar (target=-1)
        let x1 = s
            .tensor_variable(vec![1.0, 0.0, 0.0, 1.0], vec![2, 2], false)
            .unwrap();
        let x2 = s
            .tensor_variable(vec![1.0, 0.0, 0.0, 1.0], vec![2, 2], false)
            .unwrap();
        let target = s.tensor_variable(vec![1.0, -1.0], vec![2], false).unwrap();
        let loss = s.cosine_embedding_loss(x1, x2, target, 0.0).unwrap();
        let vals = s.tensor_values(loss).unwrap();
        // pair 0: cos=1.0, target=1 -> loss=0
        // pair 1: cos=1.0, target=-1 -> loss=max(0, 1.0-0)=1.0
        // mean = 0.5
        assert!(
            (vals[0] - 0.5).abs() < 1e-4,
            "mixed targets should give mean loss ~0.5, got {}",
            vals[0]
        );
    }

    #[test]
    fn cosine_embedding_loss_rejects_invalid_target() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x1 = s
            .tensor_variable(vec![1.0, 2.0], vec![1, 2], false)
            .unwrap();
        let x2 = s
            .tensor_variable(vec![3.0, 4.0], vec![1, 2], false)
            .unwrap();
        // target=0.5 is invalid (must be 1.0 or -1.0)
        let target = s.tensor_variable(vec![0.5], vec![1], false).unwrap();
        assert!(
            s.cosine_embedding_loss(x1, x2, target, 0.0).is_err(),
            "invalid target value should be rejected"
        );
    }

    #[test]
    fn cosine_embedding_loss_f32_no_crash_returns_f32() {
        // Regression: cosine_embedding_loss on f32 inputs used to ERROR (F64 self.full
        // constants mixed with an F32 cos_sim = dtype mismatch). It must now compute (routed
        // to the f32 sibling), return F32, and match the f64 reference within tolerance.
        let x1: Vec<f32> = vec![1.0, 0.0, 0.5, 0.5, -1.0, 2.0];
        let x2: Vec<f32> = vec![0.9, 0.1, 0.4, 0.6, -0.8, 1.5];
        let tgt: Vec<f32> = vec![1.0, -1.0, 1.0];
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let a = s
            .tensor_variable_f32(x1.clone(), vec![3, 2], false)
            .unwrap();
        let b = s
            .tensor_variable_f32(x2.clone(), vec![3, 2], false)
            .unwrap();
        let t = s.tensor_variable_f32(tgt.clone(), vec![3], false).unwrap();
        let loss = s.cosine_embedding_loss(a, b, t, 0.5).unwrap(); // used to error on f32
        assert_eq!(
            s.tensor_dtype(loss).unwrap(),
            DType::F32,
            "cosine_embedding_loss(f32) -> f32"
        );
        let v = s.tensor_values_lossy_f64(loss).unwrap()[0];
        let af = s
            .tensor_variable(x1.iter().map(|&x| x as f64).collect(), vec![3, 2], false)
            .unwrap();
        let bf = s
            .tensor_variable(x2.iter().map(|&x| x as f64).collect(), vec![3, 2], false)
            .unwrap();
        let tf = s
            .tensor_variable(tgt.iter().map(|&x| x as f64).collect(), vec![3], false)
            .unwrap();
        let loss64 = s.cosine_embedding_loss(af, bf, tf, 0.5).unwrap();
        let v64 = s.tensor_values(loss64).unwrap()[0];
        assert!((v - v64).abs() < 1e-5, "f32 loss {v} vs f64 ref {v64}");
    }

