    #[test]
    fn session_tensor_where_selects_by_condition() {
        let mut session = FrankenTorchSession::new(ExecutionMode::Strict);
        let cond = session
            .tensor_variable(vec![1.0, 0.0, 1.0, 0.0], vec![4], false)
            .expect("cond");
        let x = session
            .tensor_variable(vec![10.0, 20.0, 30.0, 40.0], vec![4], false)
            .expect("x");
        let y = session
            .tensor_variable(vec![-1.0, -2.0, -3.0, -4.0], vec![4], false)
            .expect("y");
        let result = session.tensor_where(cond, x, y).expect("where");
        let vals = session.tensor_values(result).expect("vals");
        assert_eq!(vals, vec![10.0, -2.0, 30.0, -4.0]);
    }

    #[test]
    fn session_tensor_where_backward() {
        let mut session = FrankenTorchSession::new(ExecutionMode::Strict);
        let cond = session
            .tensor_variable(vec![1.0, 0.0, 1.0], vec![3], false)
            .expect("cond");
        let x = session
            .tensor_variable(vec![2.0, 4.0, 6.0], vec![3], true)
            .expect("x");
        let y = session
            .tensor_variable(vec![10.0, 20.0, 30.0], vec![3], true)
            .expect("y");
        let result = session.tensor_where(cond, x, y).expect("where");
        // result = [2.0, 20.0, 6.0], sum = 28.0
        let loss = session.tensor_sum(result).expect("sum");
        let report = session.tensor_backward(loss).expect("backward");

        let x_grad = session.tensor_gradient(&report, x).expect("x grad");
        let y_grad = session.tensor_gradient(&report, y).expect("y grad");

        // x gets gradient where condition is 1, y gets gradient where condition is 0
        assert_eq!(x_grad, &[1.0, 0.0, 1.0]);
        assert_eq!(y_grad, &[0.0, 1.0, 0.0]);
    }

    #[test]
    fn where_scalar_branches_and_broadcast_match_torch() {
        // torch.where accepts scalar branches and broadcasts condition/x/y.
        // Goldens from torch 2.12.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);

        // scalar branches: where(cond, 1.0, 0.0)
        let cond = s
            .tensor_variable(vec![1.0, 0.0, 1.0], vec![3], false)
            .unwrap();
        let o = s.tensor_where_scalar(cond, 1.0, 0.0).unwrap();
        assert_eq!(s.tensor_shape(o).unwrap(), vec![3]);
        assert_eq!(s.tensor_values(o).unwrap(), vec![1.0, 0.0, 1.0]);

        // broadcasting: cond [2,1], x [3], y [2,1] -> [2,3]
        let cond = s
            .tensor_variable(vec![1.0, 0.0], vec![2, 1], false)
            .unwrap();
        let x = s
            .tensor_variable(vec![1.0, 2.0, 3.0], vec![3], false)
            .unwrap();
        let y = s
            .tensor_variable(vec![10.0, 20.0], vec![2, 1], false)
            .unwrap();
        let o = s.tensor_where(cond, x, y).unwrap();
        assert_eq!(s.tensor_shape(o).unwrap(), vec![2, 3]);
        assert_eq!(
            s.tensor_values(o).unwrap(),
            vec![1.0, 2.0, 3.0, 20.0, 20.0, 20.0]
        );

        // mixed (tensor x, scalar y) via a broadcast [1] scalar tensor: where([3], x, 0.0)
        let cond = s
            .tensor_variable(vec![1.0, 0.0, 1.0], vec![3], false)
            .unwrap();
        let x = s
            .tensor_variable(vec![5.0, 6.0, 7.0], vec![3], false)
            .unwrap();
        let yscalar = s.full(vec![1], 0.0, false).unwrap();
        let o = s.tensor_where(cond, x, yscalar).unwrap();
        assert_eq!(s.tensor_values(o).unwrap(), vec![5.0, 0.0, 7.0]);

        // gradient flows through tensor branches under broadcasting.
        let cond = s
            .tensor_variable(vec![1.0, 0.0], vec![2, 1], false)
            .unwrap();
        let x = s
            .tensor_variable(vec![1.0, 2.0, 3.0], vec![3], true)
            .unwrap();
        let y = s
            .tensor_variable(vec![10.0, 20.0], vec![2, 1], true)
            .unwrap();
        let o = s.tensor_where(cond, x, y).unwrap();
        let loss = s.tensor_sum(o).unwrap();
        let report = s.tensor_backward(loss).unwrap();
        // row 0 (cond=1) selects x: each x element used once -> grad_x = [1,1,1].
        assert_eq!(s.tensor_gradient(&report, x).unwrap(), &[1.0, 1.0, 1.0]);
        // row 1 (cond=0) selects y[1]=20 for all 3 cols -> grad_y = [0, 3].
        assert_eq!(s.tensor_gradient(&report, y).unwrap(), &[0.0, 3.0]);
    }

