    #[test]
    fn cross_entropy_fused_matches_op_graph_within_tolerance() {
        // Fused cross-entropy must match the log_softmax + nll_loss op-graph (built
        // manually so it bypasses the fast path) to tolerance, for every reduction.
        let (batch, classes) = (5usize, 7usize);
        let logits: Vec<f64> = (0..batch * classes)
            .map(|i| ((i % 9) as f64 - 4.0) * 0.4)
            .collect();
        let tgt: Vec<f64> = vec![0.0, 3.0, 6.0, 2.0, 5.0];
        for red in ["none", "mean", "sum"] {
            let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
            let x = s
                .tensor_variable(logits.clone(), vec![batch, classes], false)
                .unwrap();
            let t = s.tensor_variable(tgt.clone(), vec![batch], false).unwrap();
            let out = s.functional_cross_entropy(x, t, red).unwrap();
            let fused = s.tensor_values(out).unwrap();

            let mut s2 = FrankenTorchSession::new(ExecutionMode::Strict);
            let x2 = s2
                .tensor_variable(logits.clone(), vec![batch, classes], false)
                .unwrap();
            let t2 = s2.tensor_variable(tgt.clone(), vec![batch], false).unwrap();
            let lp = s2.tensor_log_softmax(x2, 1).unwrap();
            let out2 = s2.tensor_nll_loss(lp, t2, red).unwrap();
            let reference = s2.tensor_values(out2).unwrap();
            assert_eq!(fused.len(), reference.len());
            for (i, (a, b)) in fused.iter().zip(reference.iter()).enumerate() {
                assert!(
                    (a - b).abs() <= 1e-12 + 1e-10 * b.abs(),
                    "red={red} [{i}]: fused {a} vs op-graph {b}"
                );
            }
        }
    }

    #[test]
    fn cross_entropy_fused_grad_matches_finite_diff() {
        let (batch, classes) = (4usize, 5usize);
        let logits: Vec<f64> = (0..batch * classes)
            .map(|i| ((i % 7) as f64 - 3.0) * 0.5)
            .collect();
        let tgt: Vec<f64> = vec![1.0, 4.0, 0.0, 2.0];
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s
            .tensor_variable(logits.clone(), vec![batch, classes], true)
            .unwrap();
        let t = s.tensor_variable(tgt.clone(), vec![batch], false).unwrap();
        let out = s.functional_cross_entropy(x, t, "mean").unwrap();
        s.tensor_backward(out).unwrap();
        let gx = s.tensor_grad(x).unwrap().unwrap();

        let loss_fn = |ls: &[f64]| -> f64 {
            let mut s2 = FrankenTorchSession::new(ExecutionMode::Strict);
            let xi = s2
                .tensor_variable(ls.to_vec(), vec![batch, classes], false)
                .unwrap();
            let ti = s2.tensor_variable(tgt.clone(), vec![batch], false).unwrap();
            let o = s2.functional_cross_entropy(xi, ti, "mean").unwrap();
            s2.tensor_values(o).unwrap()[0]
        };
        let h = 1e-6;
        for i in 0..batch * classes {
            let (mut lp, mut lm) = (logits.clone(), logits.clone());
            lp[i] += h;
            lm[i] -= h;
            let fd = (loss_fn(&lp) - loss_fn(&lm)) / (2.0 * h);
            assert!(
                (gx[i] - fd).abs() <= 1e-4 + 1e-4 * fd.abs(),
                "dx[{i}]: analytic {} vs finite-diff {fd}",
                gx[i]
            );
        }
    }

    #[test]
    fn cross_entropy_f32_fused_grad_matches_f64_path() {
        // f32 cross-entropy fused fast path (48w0b): F32 loss output + dlogits
        // within f32 precision of the trusted f64 fused path.
        let (batch, classes) = (8usize, 10usize);
        let logits: Vec<f64> = (0..batch * classes)
            .map(|i| ((i % 13) as f64 - 6.0) * 0.4 + (i as f64) * 0.01)
            .collect();
        let tgt: Vec<f64> = (0..batch).map(|i| (i % classes) as f64).collect();
        let gx64 = {
            let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
            let x = s
                .tensor_variable(logits.clone(), vec![batch, classes], true)
                .unwrap();
            let t = s.tensor_variable(tgt.clone(), vec![batch], false).unwrap();
            let out = s.functional_cross_entropy(x, t, "mean").unwrap();
            s.tensor_backward(out).unwrap();
            s.tensor_grad(x).unwrap().unwrap()
        };
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s
            .tensor_variable_f32(
                logits.iter().map(|&v| v as f32).collect(),
                vec![batch, classes],
                true,
            )
            .unwrap();
        let t = s
            .tensor_variable_f32(tgt.iter().map(|&v| v as f32).collect(), vec![batch], false)
            .unwrap();
        let out = s.functional_cross_entropy(x, t, "mean").unwrap();
        assert_eq!(
            s.tensor_dtype(out).unwrap(),
            DType::F32,
            "f32 cross_entropy loss must be F32"
        );
        s.tensor_backward(out).unwrap();
        for (a, e) in s.tensor_grad(x).unwrap().unwrap().iter().zip(gx64.iter()) {
            assert!((a - e).abs() < 2e-3, "dlogits f32 {a} vs f64 {e}");
        }
    }

    #[test]
    fn cross_entropy_borrowed_grad_zero_logits_golden_bits() {
        let (batch, classes) = (2usize, 4usize);
        let logits = vec![0.0; batch * classes];
        let targets = vec![1.0, 3.0];
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s
            .tensor_variable(logits, vec![batch, classes], true)
            .unwrap();
        let t = s.tensor_variable(targets, vec![batch], false).unwrap();
        let out = s.functional_cross_entropy(x, t, "mean").unwrap();
        let loss = s.tensor_values(out).unwrap();
        assert_eq!(loss.len(), 1);
        assert_eq!(loss[0].to_bits(), 0x3ff62e42fefa39ef);

        s.tensor_backward(out).unwrap();
        let grad = s.tensor_grad(x).unwrap().unwrap();
        let expected_bits = [
            0x3fc0000000000000,
            0xbfd8000000000000,
            0x3fc0000000000000,
            0x3fc0000000000000,
            0x3fc0000000000000,
            0x3fc0000000000000,
            0x3fc0000000000000,
            0xbfd8000000000000,
        ];
        assert_eq!(grad.len(), expected_bits.len());
        for (idx, (got, want)) in grad.iter().zip(expected_bits.iter()).enumerate() {
            assert_eq!(got.to_bits(), *want, "grad bit mismatch at {idx}");
        }
    }

    #[test]
    fn session_cross_entropy_loss_wrong_class_is_higher() {
        let mut session = FrankenTorchSession::new(ExecutionMode::Strict);
        // logits: batch=1, classes=3: class 0 has highest logit
        let logits = session
            .tensor_variable(vec![5.0, 1.0, 0.1], vec![1, 3], false)
            .expect("logits");

        // Target correct class (0) - should have low loss
        let target_correct = session
            .tensor_variable(vec![0.0], vec![1], false)
            .expect("targets_correct");
        let loss_correct = session
            .cross_entropy_loss(logits, target_correct)
            .expect("ce_correct");
        let val_correct = session.tensor_values(loss_correct).expect("vals")[0];

        // Target wrong class (2) - should have higher loss
        let logits2 = session
            .tensor_variable(vec![5.0, 1.0, 0.1], vec![1, 3], false)
            .expect("logits2");
        let target_wrong = session
            .tensor_variable(vec![2.0], vec![1], false)
            .expect("targets_wrong");
        let loss_wrong = session
            .cross_entropy_loss(logits2, target_wrong)
            .expect("ce_wrong");
        let val_wrong = session.tensor_values(loss_wrong).expect("vals")[0];

        assert!(
            val_wrong > val_correct,
            "wrong class loss ({}) should be higher than correct class loss ({})",
            val_wrong,
            val_correct
        );
    }

