    #[test]
    fn qr_reconstruction_invariant() {
        // Metamorphic invariant (sign-convention-robust): qr(A) gives Q,R with
        // Q@R==A and Q^T@Q==I. frankentorch-ncg6l.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let a_data = vec![1.0, 2.0, 3.0, 4.0];
        let a = s
            .tensor_variable(a_data.clone(), vec![2, 2], false)
            .unwrap();
        let (q, r) = s.tensor_qr(a, true).unwrap();
        let recon = s.tensor_matmul(q, r).unwrap();
        let rv = s.tensor_values(recon).unwrap();
        for (g, w) in rv.iter().zip(a_data.iter()) {
            assert!((g - w).abs() < 1e-10, "Q@R {g} != A {w}");
        }
        let qt = s.tensor_transpose(q, 0, 1).unwrap();
        let qtq = s.tensor_matmul(qt, q).unwrap();
        let qv = s.tensor_values(qtq).unwrap();
        let eye = [1.0, 0.0, 0.0, 1.0];
        for (g, w) in qv.iter().zip(eye.iter()) {
            assert!((g - w).abs() < 1e-10, "Q^T@Q {g} != I {w}");
        }
    }

