    #[test]
    fn det_inverse_linalg_golden_matches_torch() {
        // Differential golden vs torch 2.12: det([[2,1],[1,3]])==5; inverse==
        // [[0.6,-0.2],[-0.2,0.4]]; and M@inv(M)==I. frankentorch-wh9bk.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let m = s
            .tensor_variable(vec![2.0, 1.0, 1.0, 3.0], vec![2, 2], false)
            .unwrap();
        let det_id = s.tensor_det(m).unwrap();
        let det = s.tensor_values(det_id).unwrap()[0];
        assert!((det - 5.0).abs() < 1e-12, "det {det} != 5");
        let inv = s.tensor_inverse(m).unwrap();
        let iv = s.tensor_values(inv).unwrap();
        let want = [0.6, -0.2, -0.2, 0.4];
        for (g, w) in iv.iter().zip(want.iter()) {
            assert!((g - w).abs() < 1e-12, "inverse {g} != {w}");
        }
        // M @ inv(M) == I (within tolerance)
        let prod = s.tensor_matmul(m, inv).unwrap();
        let pv = s.tensor_values(prod).unwrap();
        let eye = [1.0, 0.0, 0.0, 1.0];
        for (g, w) in pv.iter().zip(eye.iter()) {
            assert!((g - w).abs() < 1e-10, "M@inv {g} != I {w}");
        }
    }

