    #[test]
    fn finite_difference_gradcheck_two_layer_mlp() {
        // Gradcheck (robust): analytic grad of f(x)=mse_loss(linear(tanh(linear(x,
        // W1,b1)),W2,b2), target) wrt x matches central finite differences. Validates
        // the full multi-layer backprop chain numerically. frankentorch-jfgi8.
        let base = vec![0.5, -1.0, 0.3];
        let w1 = vec![1.0, 0.0, -1.0, 0.5, 1.0, 0.25]; // [2,3]
        let b1 = vec![0.1, -0.2];
        let w2 = vec![1.0, -0.5]; // [1,2]
        let b2 = vec![0.3];
        let target = vec![0.7];
        let loss_at = |vals: &[f64]| -> f64 {
            let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
            let x = s.tensor_variable(vals.to_vec(), vec![1, 3], false).unwrap();
            let w1n = s.tensor_variable(w1.clone(), vec![2, 3], false).unwrap();
            let b1n = s.tensor_variable(b1.clone(), vec![2], false).unwrap();
            let w2n = s.tensor_variable(w2.clone(), vec![1, 2], false).unwrap();
            let b2n = s.tensor_variable(b2.clone(), vec![1], false).unwrap();
            let tn = s
                .tensor_variable(target.clone(), vec![1, 1], false)
                .unwrap();
            let h1 = s.tensor_linear(x, w1n, Some(b1n)).unwrap();
            let a1 = s.tensor_tanh(h1).unwrap();
            let out = s.tensor_linear(a1, w2n, Some(b2n)).unwrap();
            let loss = s.functional_mse_loss(out, tn, "mean").unwrap();
            s.tensor_values(loss).unwrap()[0]
        };
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s.tensor_variable(base.clone(), vec![1, 3], true).unwrap();
        let w1n = s.tensor_variable(w1.clone(), vec![2, 3], false).unwrap();
        let b1n = s.tensor_variable(b1.clone(), vec![2], false).unwrap();
        let w2n = s.tensor_variable(w2.clone(), vec![1, 2], false).unwrap();
        let b2n = s.tensor_variable(b2.clone(), vec![1], false).unwrap();
        let tn = s
            .tensor_variable(target.clone(), vec![1, 1], false)
            .unwrap();
        let h1 = s.tensor_linear(x, w1n, Some(b1n)).unwrap();
        let a1 = s.tensor_tanh(h1).unwrap();
        let out = s.tensor_linear(a1, w2n, Some(b2n)).unwrap();
        let loss = s.functional_mse_loss(out, tn, "mean").unwrap();
        let rep = s.tensor_backward(loss).unwrap();
        let analytic = s.tensor_gradient(&rep, x).unwrap();
        let h = 1e-6;
        for i in 0..base.len() {
            let mut p = base.clone();
            let mut m = base.clone();
            p[i] += h;
            m[i] -= h;
            let numeric = (loss_at(&p) - loss_at(&m)) / (2.0 * h);
            let rel = (analytic[i] - numeric).abs() / (1.0 + numeric.abs());
            assert!(
                rel < 1e-5,
                "MLP gradcheck idx {i}: analytic {} vs numeric {}",
                analytic[i],
                numeric
            );
        }
    }

