    #[test]
    fn linear_backward_golden_matches_torch() {
        // Differential gradient golden vs torch.autograd 2.12: linear([[1,2,3]],
        // W=[[1,0,-1],[2,1,0]],b) sum-loss -> grad_x==[3,1,-1], grad_W==
        // [1,2,3,1,2,3], grad_b==[1,1]. frankentorch-ove5m.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s
            .tensor_variable(vec![1.0, 2.0, 3.0], vec![1, 3], true)
            .unwrap();
        let w = s
            .tensor_variable(vec![1.0, 0.0, -1.0, 2.0, 1.0, 0.0], vec![2, 3], true)
            .unwrap();
        let b = s.tensor_variable(vec![0.5, -0.5], vec![2], true).unwrap();
        let y = s.tensor_linear(x, w, Some(b)).unwrap();
        let loss = s.tensor_sum(y).unwrap();
        let report = s.tensor_backward(loss).unwrap();
        for (g, ww) in s
            .tensor_gradient(&report, x)
            .unwrap()
            .iter()
            .zip([3.0, 1.0, -1.0].iter())
        {
            assert!((g - ww).abs() < 1e-12, "linear grad_x {g} != {ww}");
        }
        for (g, ww) in s
            .tensor_gradient(&report, w)
            .unwrap()
            .iter()
            .zip([1.0, 2.0, 3.0, 1.0, 2.0, 3.0].iter())
        {
            assert!((g - ww).abs() < 1e-12, "linear grad_W {g} != {ww}");
        }
        for (g, ww) in s
            .tensor_gradient(&report, b)
            .unwrap()
            .iter()
            .zip([1.0, 1.0].iter())
        {
            assert!((g - ww).abs() < 1e-12, "linear grad_b {g} != {ww}");
        }
    }

