        let loss = s.tensor_sum(prod).unwrap();
        let report = s.tensor_backward(loss).unwrap();
        let ga = s.tensor_gradient(&report, a).unwrap();
        assert_eq!(ga.len(), 2, "grad_a numel");
        for g in ga.iter() {
            assert!((g - 60.0).abs() < 1e-12, "grad_a {g} != 60");
        }
