    #[test]
    fn mse_l1_loss_backward_golden_matches_torch() {
        // Differential gradient golden vs torch.autograd 2.12: d/di mse_loss(
        // [1,2,3,4],[1.5,1.5,2,5])==[-0.25,0.25,0.5,-0.5] (2*diff/N); l1_loss'==
        // [-0.25,0.25,0.25,-0.25] (sign(diff)/N). frankentorch-uv1su.
        let grad_of = |which: u8, want: &[f64], ctx: &str| {
            let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
            let i = s
                .tensor_variable(vec![1.0, 2.0, 3.0, 4.0], vec![4], true)
                .unwrap();
            let t = s
                .tensor_variable(vec![1.5, 1.5, 2.0, 5.0], vec![4], false)
                .unwrap();
            let loss = if which == 0 {
                s.functional_mse_loss(i, t, "mean")
            } else {
                s.functional_l1_loss(i, t, "mean")
            }
            .unwrap();
            let report = s.tensor_backward(loss).unwrap();
            let g = s.tensor_gradient(&report, i).unwrap();
            for (gg, w) in g.iter().zip(want.iter()) {
                assert!((gg - w).abs() < 1e-12, "{ctx} {gg} != {w}");
            }
        };
        grad_of(0, &[-0.25, 0.25, 0.5, -0.5], "mse'");
        grad_of(1, &[-0.25, 0.25, 0.25, -0.25], "l1'");
    }

    #[test]
    fn conv2d_weight_gradient_golden_matches_torch() {
        // Differential gradient golden vs torch.autograd 2.12: d/dw sum(conv2d(
        // arange9[1,1,3,3], ones[1,1,2,2])) == [8,12,20,24] (each weight elem
        // accumulates the input patches it touches). frankentorch-etzr3.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s
            .tensor_variable((0..9).map(f64::from).collect(), vec![1, 1, 3, 3], false)
            .unwrap();
        let w = s
            .tensor_variable(vec![1.0, 1.0, 1.0, 1.0], vec![1, 1, 2, 2], true)
            .unwrap();
        let y = s.tensor_conv2d(x, w, None, (1, 1), (0, 0)).unwrap();
        let loss = s.tensor_sum(y).unwrap();
        let report = s.tensor_backward(loss).unwrap();
        let g = s.tensor_gradient(&report, w).unwrap();
        for (gg, ww) in g.iter().zip([8.0, 12.0, 20.0, 24.0].iter()) {
            assert!((gg - ww).abs() < 1e-12, "conv2d grad_w {gg} != {ww}");
        }
    }

