        // Differential golden vs torch 2.12: mse_loss([1,2,3,4],[1.5,1.5,2,5])
        // reduction='sum'==2.5; reduction='none'==[0.25,0.25,1,1]. frankentorch-2taq8.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
