    #[test]
    fn all_any_logical_golden_matches_torch() {
        // Differential golden vs torch 2.12: all([1,1,0])==false; any([0,0,1])==true;
        // logical_and([1,0,1],[1,1,0])==[1,0,0]; logical_or==[1,1,1];
        // logical_not([1,0,1])==[0,1,0]. frankentorch-kdi8p.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let has_zero = s
            .tensor_variable(vec![1.0, 1.0, 0.0], vec![3], false)
            .unwrap();
        assert!(
            !s.tensor_all(has_zero).unwrap(),
            "all([1,1,0]) should be false"
        );
        let has_one = s
            .tensor_variable(vec![0.0, 0.0, 1.0], vec![3], false)
            .unwrap();
        assert!(
            s.tensor_any(has_one).unwrap(),
            "any([0,0,1]) should be true"
        );
        let a = s
            .tensor_variable(vec![1.0, 0.0, 1.0], vec![3], false)
            .unwrap();
        let b = s
            .tensor_variable(vec![1.0, 1.0, 0.0], vec![3], false)
            .unwrap();
        let land = s.tensor_logical_and(a, b).unwrap();
        for (g, w) in s
            .tensor_values(land)
            .unwrap()
            .iter()
            .zip([1.0, 0.0, 0.0].iter())
        {
            assert!((g - w).abs() < 1e-12, "logical_and {g} != {w}");
        }
        let lor = s.tensor_logical_or(a, b).unwrap();
        for (g, w) in s
            .tensor_values(lor)
            .unwrap()
            .iter()
            .zip([1.0, 1.0, 1.0].iter())
        {
            assert!((g - w).abs() < 1e-12, "logical_or {g} != {w}");
        }
        let lnot = s.tensor_logical_not(a).unwrap();
        for (g, w) in s
            .tensor_values(lnot)
            .unwrap()
            .iter()
            .zip([0.0, 1.0, 0.0].iter())
        {
            assert!((g - w).abs() < 1e-12, "logical_not {g} != {w}");
        }
    }

    #[test]
    fn isnan_isinf_isfinite_golden_matches_torch() {
        // Differential golden vs torch 2.12 on [1,nan,inf,-inf]: isnan==[0,1,0,0];
        // isinf==[0,0,1,1]; isfinite==[1,0,0,0]. frankentorch-3qawb.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s
            .tensor_variable(
                vec![1.0, f64::NAN, f64::INFINITY, f64::NEG_INFINITY],
                vec![4],
                false,
            )
            .unwrap();
        let nan = s.tensor_isnan(x).unwrap();
        for (g, w) in s
            .tensor_values(nan)
            .unwrap()
            .iter()
            .zip([0.0, 1.0, 0.0, 0.0].iter())
        {
            assert!((g - w).abs() < 1e-12, "isnan {g} != {w}");
        }
        let inf = s.tensor_isinf(x).unwrap();
        for (g, w) in s
            .tensor_values(inf)
            .unwrap()
            .iter()
            .zip([0.0, 0.0, 1.0, 1.0].iter())
        {
            assert!((g - w).abs() < 1e-12, "isinf {g} != {w}");
        }
        let fin = s.tensor_isfinite(x).unwrap();
        for (g, w) in s
            .tensor_values(fin)
            .unwrap()
            .iter()
            .zip([1.0, 0.0, 0.0, 0.0].iter())
        {
            assert!((g - w).abs() < 1e-12, "isfinite {g} != {w}");
        }
    }

    #[test]
    fn log_softmax_normalize_golden_matches_torch() {
        // Differential golden vs torch 2.12: log_softmax([1,2,3],0)==[-2.4076059644,
        // -1.4076059644,-0.4076059644]; normalize([3,4],p2,0)==[0.6,0.8].
        // frankentorch-bt8j9.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s
            .tensor_variable(vec![1.0, 2.0, 3.0], vec![3], false)
            .unwrap();
        let ls = s.tensor_log_softmax(x, 0).unwrap();
        let want = [-2.407_605_964_4, -1.407_605_964_4, -0.407_605_964_4];
        for (g, w) in s.tensor_values(ls).unwrap().iter().zip(want.iter()) {
            assert!((g - w).abs() < 1e-9, "log_softmax {g} != {w}");
        }
        let v = s.tensor_variable(vec![3.0, 4.0], vec![2], false).unwrap();
        let n = s.functional_normalize(v, 2.0, 0).unwrap();
        for (g, w) in s.tensor_values(n).unwrap().iter().zip([0.6, 0.8].iter()) {
            assert!((g - w).abs() < 1e-12, "normalize {g} != {w}");
        }
    }

    #[test]
    fn median_var_std_full_golden_matches_torch() {
        // Differential golden vs torch 2.12: median([1,3,2,5,4])==3;
        // var([1,2,3,4],correction=1)==1.6666666667; std==1.2909944487.
        // frankentorch-7l3mo.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let m = s
            .tensor_variable(vec![1.0, 3.0, 2.0, 5.0, 4.0], vec![5], false)
            .unwrap();
        let med = s.tensor_median(m).unwrap();
        assert!(
            (s.tensor_values(med).unwrap()[0] - 3.0).abs() < 1e-12,
            "median"
        );
        let x = s
            .tensor_variable(vec![1.0, 2.0, 3.0, 4.0], vec![4], false)
            .unwrap();
        let var = s.tensor_var(x, 1).unwrap();
        assert!(
            (s.tensor_values(var).unwrap()[0] - 1.666_666_666_7).abs() < 1e-9,
            "var"
        );
        let std = s.tensor_std(x, 1).unwrap();
        assert!(
            (s.tensor_values(std).unwrap()[0] - 1.290_994_448_7).abs() < 1e-9,
            "std"
        );
    }

    #[test]
    fn inverse_trig_hyperbolic_golden_matches_torch() {
        // Differential golden vs torch 2.12: asin(0.5)==0.5235987756; acos(0.5)==
        // 1.0471975512; atan(1)==0.7853981634; sinh(1)==1.1752011936; cosh(1)==
        // 1.5430806348. frankentorch-iphhv.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let chk = |s: &mut FrankenTorchSession, id, want: f64, ctx: &str| {
            assert!(
                (s.tensor_values(id).unwrap()[0] - want).abs() < 1e-9,
                "{ctx}"
            );
        };
        let half = s.tensor_variable(vec![0.5], vec![1], false).unwrap();
        let one = s.tensor_variable(vec![1.0], vec![1], false).unwrap();
        let asin = s.tensor_asin(half).unwrap();
        chk(&mut s, asin, 0.523_598_775_6, "asin");
        let acos = s.tensor_acos(half).unwrap();
        chk(&mut s, acos, 1.047_197_551_2, "acos");
        let atan = s.tensor_atan(one).unwrap();
        chk(&mut s, atan, 0.785_398_163_4, "atan");
        let sinh = s.tensor_sinh(one).unwrap();
        chk(&mut s, sinh, 1.175_201_193_6, "sinh");
        let cosh = s.tensor_cosh(one).unwrap();
        chk(&mut s, cosh, 1.543_080_634_8, "cosh");
    }

    #[test]
    fn norm_variants_golden_matches_torch() {
        // Differential golden vs torch 2.12: vector norm([3,-4]) p2==5, p1==7,
        // pinf==4; frobenius([[1,2],[3,4]])==sqrt30. frankentorch-r8m3p.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let v = s.tensor_variable(vec![3.0, -4.0], vec![2], false).unwrap();
        let n2 = s.tensor_norm(v, 2.0).unwrap();
        assert!(
            (s.tensor_values(n2).unwrap()[0] - 5.0).abs() < 1e-12,
            "norm p2"
        );
        let n1 = s.tensor_norm(v, 1.0).unwrap();
        assert!(
            (s.tensor_values(n1).unwrap()[0] - 7.0).abs() < 1e-12,
            "norm p1"
        );
        let ninf = s.tensor_norm(v, f64::INFINITY).unwrap();
        assert!(
            (s.tensor_values(ninf).unwrap()[0] - 4.0).abs() < 1e-12,
            "norm pinf"
        );
        let m = s
            .tensor_variable(vec![1.0, 2.0, 3.0, 4.0], vec![2, 2], false)
            .unwrap();
        let fro = s.tensor_frobenius_norm(m).unwrap();
        assert!(
            (s.tensor_values(fro).unwrap()[0] - 30.0_f64.sqrt()).abs() < 1e-9,
            "frobenius"
        );
    }

    #[test]
    fn dot_mv_addmm_golden_matches_torch() {
        // Differential golden vs torch 2.12: dot([1,2,3],[4,5,6])==32;
        // mv([[1,2],[3,4]],[5,6])==[17,39]; addmm(ones2x2,[[1,2],[3,4]],I,1,1)==
        // [2,3,4,5]. frankentorch-417gk.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let u = s
            .tensor_variable(vec![1.0, 2.0, 3.0], vec![3], false)
            .unwrap();
        let v = s
            .tensor_variable(vec![4.0, 5.0, 6.0], vec![3], false)
            .unwrap();
        let d = s.tensor_dot(u, v).unwrap();
        assert!((s.tensor_values(d).unwrap()[0] - 32.0).abs() < 1e-12, "dot");
        let m = s
            .tensor_variable(vec![1.0, 2.0, 3.0, 4.0], vec![2, 2], false)
            .unwrap();
        let vec2 = s.tensor_variable(vec![5.0, 6.0], vec![2], false).unwrap();
        let mvr = s.tensor_mv(m, vec2).unwrap();
        for (g, w) in s
            .tensor_values(mvr)
            .unwrap()
            .iter()
            .zip([17.0, 39.0].iter())
        {
            assert!((g - w).abs() < 1e-12, "mv {g} != {w}");
        }
        let bias = s
            .tensor_variable(vec![1.0, 1.0, 1.0, 1.0], vec![2, 2], false)
            .unwrap();
        let eye = s
            .tensor_variable(vec![1.0, 0.0, 0.0, 1.0], vec![2, 2], false)
            .unwrap();
        let am = s.tensor_addmm(bias, m, eye, 1.0, 1.0).unwrap();
        for (g, w) in s
            .tensor_values(am)
            .unwrap()
            .iter()
            .zip([2.0, 3.0, 4.0, 5.0].iter())
        {
            assert!((g - w).abs() < 1e-12, "addmm {g} != {w}");
        }
    }

    #[test]
    fn broadcasting_forward_value_golden_matches_torch() {
        // Differential golden vs torch 2.12: [[1],[2]] (2,1) + [[10,20,30]] (1,3)
        // -> [2,3]=[11,21,31,12,22,32]; * -> [10,20,30,20,40,60]. frankentorch-fa9l9.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let a = s
            .tensor_variable(vec![1.0, 2.0], vec![2, 1], false)
            .unwrap();
        let b = s
            .tensor_variable(vec![10.0, 20.0, 30.0], vec![1, 3], false)
            .unwrap();
        let add = s.tensor_add(a, b).unwrap();
        assert_eq!(
            s.tensor_shape(add).unwrap(),
            vec![2, 3],
            "broadcast add shape"
        );
        for (g, w) in s
            .tensor_values(add)
            .unwrap()
            .iter()
            .zip([11.0, 21.0, 31.0, 12.0, 22.0, 32.0].iter())
        {
            assert!((g - w).abs() < 1e-12, "broadcast add {g} != {w}");
        }
        let mul = s.tensor_mul(a, b).unwrap();
        for (g, w) in s
            .tensor_values(mul)
            .unwrap()
            .iter()
            .zip([10.0, 20.0, 30.0, 20.0, 40.0, 60.0].iter())
        {
            assert!((g - w).abs() < 1e-12, "broadcast mul {g} != {w}");
        }
    }

    // Locks the no-grad fused broadcast add/mul fast paths (try_lastdim_bcast_addmul +
    // try_rowscalar_bcast_addmul): the fused result must be BIT-IDENTICAL to the generic grad
    // path (reshape+expand+op), for both operand orders, LAST-DIM ([M],[1,M]) and ROW-SCALAR
    // ([N,1]) broadcasts, and f32/f64.
    #[test]
    fn lastdim_bcast_addmul_fused_matches_expand_path() {
        let (n, m) = (37usize, 20usize); // != so shapes differ; small enough to also hit serial chunk
        for f32_mode in [false, true] {
            let big: Vec<f64> = (0..n * m).map(|i| (i as f64) * 0.5 - 100.0).collect();
            let mk = |s: &mut FrankenTorchSession, v: &[f64], shape: Vec<usize>, grad: bool| {
                if f32_mode {
                    s.tensor_variable_f32(v.iter().map(|&x| x as f32).collect(), shape, grad)
                        .unwrap()
                } else {
                    s.tensor_variable(v.to_vec(), shape, grad).unwrap()
                }
            };
            let read = |s: &FrankenTorchSession, id| -> Vec<f64> {
                if f32_mode {
                    s.tensor_values_f32(id)
                        .unwrap()
                        .iter()
                        .map(|&x| x as f64)
                        .collect()
                } else {
                    s.tensor_values(id).unwrap()
                }
            };
            // all 4 elementwise ops; sub/div are non-commutative so each order gets its own ref.
            for opname in ["add", "sub", "mul", "div"] {
                let apply = |s: &mut FrankenTorchSession, x, y| match opname {
                    "add" => s.tensor_add(x, y).unwrap(),
                    "sub" => s.tensor_sub(x, y).unwrap(),
                    "mul" => s.tensor_mul(x, y).unwrap(),
                    _ => s.tensor_div(x, y).unwrap(),
                };
                // last-dim vectors [M]/[1,M] (M elems) + row-scalar column [N,1] (N elems) +
                // full-scalar [1]/[1,1] (1 elem)
                for vshape in [vec![m], vec![1, m], vec![n, 1], vec![1], vec![1, 1]] {
                    let vn: usize = vshape.iter().product();
                    // avoid vec zeros so div reference is finite/deterministic
                    let vecv: Vec<f64> = (0..vn).map(|j| (j as f64) - 7.5).collect();
                    let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
                    // no-grad fused: forward (big op vec) and reversed (vec op big)
                    let a = mk(&mut s, &big, vec![n, m], false);
                    let b = mk(&mut s, &vecv, vshape.clone(), false);
                    let fwd = apply(&mut s, a, b);
                    let rev = apply(&mut s, b, a);
                    // grad path (requires_grad forces the generic reshape+expand+op) — one ref PER
                    // order, since sub/div differ by order.
                    let ag = mk(&mut s, &big, vec![n, m], true);
                    let bg = mk(&mut s, &vecv, vshape.clone(), true);
                    let ref_fwd = apply(&mut s, ag, bg);
                    let ag2 = mk(&mut s, &big, vec![n, m], true);
                    let bg2 = mk(&mut s, &vecv, vshape.clone(), true);
                    let ref_rev = apply(&mut s, bg2, ag2);
                    assert_eq!(s.tensor_shape(fwd).unwrap(), vec![n, m]);
                    assert_eq!(
                        read(&s, fwd),
                        read(&s, ref_fwd),
                        "fused != expand ({opname} v={vshape:?} f32={f32_mode})"
                    );
                    assert_eq!(
                        read(&s, rev),
                        read(&s, ref_rev),
                        "reversed fused != expand ({opname} v={vshape:?} f32={f32_mode})"
                    );
                }
            }
        }
    }

    // Locks the no-grad fused maximum/minimum broadcast (BcastBinOp::Max/Min) against the generic
    // expand path — including NaN, which must PROPAGATE (torch.maximum/minimum semantics: any-NaN
    // operand => NaN). Covers last-dim [M], row-scalar [N,1], full-scalar [1], both orders.
    #[test]
    fn maxmin_bcast_fused_matches_expand_path_with_nan() {
        let (n, m) = (23usize, 14usize);
        let big: Vec<f64> = (0..n * m)
            .map(|i| {
                if i % 17 == 0 {
                    f64::NAN
                } else {
                    (i as f64) * 0.3 - 40.0
                }
            })
            .collect();
        for opname in ["max", "min"] {
            let apply = |s: &mut FrankenTorchSession, x, y| {
                if opname == "max" {
                    s.tensor_maximum(x, y).unwrap()
                } else {
                    s.tensor_minimum(x, y).unwrap()
                }
            };
            for vshape in [vec![m], vec![1, m], vec![n, 1], vec![1]] {
                let vn: usize = vshape.iter().product();
                let vecv: Vec<f64> = (0..vn)
                    .map(|j| {
                        if j % 5 == 2 {
                            f64::NAN
                        } else {
                            (j as f64) - 6.0
                        }
                    })
                    .collect();
                let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
                let a = s.tensor_variable(big.clone(), vec![n, m], false).unwrap();
                let b = s
                    .tensor_variable(vecv.clone(), vshape.clone(), false)
                    .unwrap();
                let fwd = apply(&mut s, a, b);
                let rev = apply(&mut s, b, a);
                // grad forces the expand path (reference).
                let ag = s.tensor_variable(big.clone(), vec![n, m], true).unwrap();
                let bg = s
                    .tensor_variable(vecv.clone(), vshape.clone(), true)
                    .unwrap();
                let refr = apply(&mut s, ag, bg); // max/min commutative => one ref suffices
                assert_eq!(s.tensor_shape(fwd).unwrap(), vec![n, m]);
                let bits = |v: &[f64]| v.iter().map(|x| x.to_bits()).collect::<Vec<_>>();
                let (rf, rr, rg) = (
                    bits(&s.tensor_values(fwd).unwrap()),
                    bits(&s.tensor_values(rev).unwrap()),
                    bits(&s.tensor_values(refr).unwrap()),
                );
                assert_eq!(rf, rg, "fused != expand ({opname} v={vshape:?})");
                assert_eq!(rr, rg, "reversed fused != expand ({opname} v={vshape:?})");
            }
        }
    }

    // Locks the no-grad same-shape fused fmax/fmin fast path against the compose (broadcast_to x2
    // + max + isnan x2 + where x2, forced by requires_grad). fmax/fmin are NaN-TOLERANT (ignore a
    // NaN operand; NaN only if both), the opposite of maximum/minimum — verify with NaN seeded.
    #[test]
    fn fmaxmin_sameshape_fused_matches_compose_with_nan() {
        let n = 64usize;
        let a: Vec<f64> = (0..n)
            .map(|i| {
                if i % 7 == 0 {
                    f64::NAN
                } else {
                    (i as f64) * 0.5 - 15.0
                }
            })
            .collect();
        let b: Vec<f64> = (0..n)
            .map(|i| {
                if i % 5 == 3 {
                    f64::NAN
                } else {
                    (i as f64) * -0.3 + 4.0
                }
            })
            .collect();
        for is_max in [true, false] {
            let apply = |s: &mut FrankenTorchSession, x, y| {
                if is_max {
                    s.tensor_fmax(x, y).unwrap()
                } else {
                    s.tensor_fmin(x, y).unwrap()
                }
            };
            let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
            let af = s.tensor_variable(a.clone(), vec![n], false).unwrap();
            let bf = s.tensor_variable(b.clone(), vec![n], false).unwrap();
            let fused = apply(&mut s, af, bf);
            // grad forces the compose (reference).
            let ag = s.tensor_variable(a.clone(), vec![n], true).unwrap();
            let bg = s.tensor_variable(b.clone(), vec![n], true).unwrap();
            let refr = apply(&mut s, ag, bg);
            let bits = |v: &[f64]| v.iter().map(|x| x.to_bits()).collect::<Vec<_>>();
            assert_eq!(
                bits(&s.tensor_values(fused).unwrap()),
                bits(&s.tensor_values(refr).unwrap()),
                "fused fmax/fmin != compose (is_max={is_max})"
            );
        }
    }

    // Locks the no-grad fused where(cond, x, scalar) fast path (try_where_one_scalar) against the
    // generic broadcast fallthrough (grad forces broadcast_to x3 + where). Covers scalar in the y
    // branch and the x branch, f32/f64.
    #[test]
    fn where_one_scalar_fused_matches_broadcast_path() {
        let (n, m) = (30usize, 9usize);
        for f32_mode in [false, true] {
            let cond: Vec<f64> = (0..n * m).map(|i| ((i % 3) as f64) - 1.0).collect(); // -1/0/1 (truthy mix)
            let xf: Vec<f64> = (0..n * m).map(|i| (i as f64) * 0.5 - 20.0).collect();
            let mk = |s: &mut FrankenTorchSession, v: &[f64], shape: Vec<usize>, grad: bool| {
                if f32_mode {
                    s.tensor_variable_f32(v.iter().map(|&x| x as f32).collect(), shape, grad)
                        .unwrap()
                } else {
                    s.tensor_variable(v.to_vec(), shape, grad).unwrap()
                }
            };
            let read = |s: &FrankenTorchSession, id| -> Vec<u64> {
                if f32_mode {
                    s.tensor_values_f32(id)
                        .unwrap()
                        .iter()
                        .map(|x| (*x as f64).to_bits())
                        .collect()
                } else {
                    s.tensor_values(id)
                        .unwrap()
                        .iter()
                        .map(|x| x.to_bits())
                        .collect()
                }
            };
            // y scalar and x scalar cases
            for y_scalar in [true, false] {
                let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
                let c = mk(&mut s, &cond, vec![n, m], false);
                let (fused, refr) = if y_scalar {
                    let xt = mk(&mut s, &xf, vec![n, m], false);
                    let yt = mk(&mut s, &[3.5], vec![1], false);
                    let fused = s.tensor_where(c, xt, yt).unwrap();
                    let cg = mk(&mut s, &cond, vec![n, m], true);
                    let xg = mk(&mut s, &xf, vec![n, m], true);
                    let yg = mk(&mut s, &[3.5], vec![1], true);
                    (fused, s.tensor_where(cg, xg, yg).unwrap())
                } else {
                    let xt = mk(&mut s, &[3.5], vec![1], false);
                    let yt = mk(&mut s, &xf, vec![n, m], false);
                    let fused = s.tensor_where(c, xt, yt).unwrap();
                    let cg = mk(&mut s, &cond, vec![n, m], true);
                    let xg = mk(&mut s, &[3.5], vec![1], true);
                    let yg = mk(&mut s, &xf, vec![n, m], true);
                    (fused, s.tensor_where(cg, xg, yg).unwrap())
                };
                assert_eq!(s.tensor_shape(fused).unwrap(), vec![n, m]);
                assert_eq!(
                    read(&s, fused),
                    read(&s, refr),
                    "where(cond,x,scalar) fused != broadcast (y_scalar={y_scalar} f32={f32_mode})"
                );
            }
        }
    }

    // Locks the cond-broadcast case of the fused where (attention masking): cond broadcasts into the
    // full operand (causal tile [1,1,S,S] into scores [B,H,S,S] OR key-padding [B,1,1,S]/[B,1,S,S]),
    // y a scalar. Fused must equal the grad-forced broadcast fallthrough (ground truth).
    #[test]
    fn where_cond_tile_fused_matches_broadcast_path() {
        let (b, h, s) = (3usize, 2usize, 5usize);
        let xf: Vec<f64> = (0..b * h * s * s)
            .map(|i| (i as f64) * 0.25 - 30.0)
            .collect();
        // cond values -1/0/1 (truthy mix), broadcast by construction of each shape (incl key-padding).
        for cshape in [
            vec![1, 1, s, s],
            vec![s, s],
            vec![1, s, s],
            vec![b, h, s, s],
            vec![b, 1, 1, s],
            vec![b, 1, s, s],
        ] {
            let cn: usize = cshape.iter().product();
            let cond: Vec<f64> = (0..cn).map(|i| ((i % 3) as f64) - 1.0).collect();
            let mut ses = FrankenTorchSession::new(ExecutionMode::Strict);
            let c = ses
                .tensor_variable(cond.clone(), cshape.clone(), false)
                .unwrap();
            let xt = ses
                .tensor_variable(xf.clone(), vec![b, h, s, s], false)
                .unwrap();
            let yt = ses.tensor_variable(vec![-9.5], vec![1], false).unwrap();
            let fused = ses.tensor_where(c, xt, yt).unwrap();
            let cg = ses
                .tensor_variable(cond.clone(), cshape.clone(), true)
                .unwrap();
            let xg = ses
                .tensor_variable(xf.clone(), vec![b, h, s, s], true)
                .unwrap();
            let yg = ses.tensor_variable(vec![-9.5], vec![1], true).unwrap();
            let refr = ses.tensor_where(cg, xg, yg).unwrap();
            assert_eq!(ses.tensor_shape(fused).unwrap(), vec![b, h, s, s]);
            let bits = |v: &[f64]| v.iter().map(|x| x.to_bits()).collect::<Vec<_>>();
            assert_eq!(
                bits(&ses.tensor_values(fused).unwrap()),
                bits(&ses.tensor_values(refr).unwrap()),
                "where cond-tile fused != broadcast (cond={cshape:?})"
            );
        }
    }

    // Locks the TWO-full-tensor cond-broadcast fast path (try_where_cond_tile_two): both branches are
    // the same full [B,H,S,S] shape and cond broadcasts in (causal tile [1,1,S,S] OR key-padding
    // [B,1,1,S]/[B,1,S,S]) — attention `where(mask, a, b)`. Fused must equal the grad-forced broadcast
    // fallthrough (ground truth). f32/f64.
    #[test]
    fn where_cond_tile_two_full_matches_broadcast_path() {
        let (b, h, s) = (3usize, 2usize, 5usize);
        let n = b * h * s * s;
        let xf: Vec<f64> = (0..n).map(|i| (i as f64) * 0.25 - 30.0).collect();
        let yf: Vec<f64> = (0..n).map(|i| (i as f64) * -0.5 + 7.0).collect();
        for f32_mode in [false, true] {
            let mk = |ses: &mut FrankenTorchSession, v: &[f64], shape: Vec<usize>, grad: bool| {
                if f32_mode {
                    ses.tensor_variable_f32(v.iter().map(|&x| x as f32).collect(), shape, grad)
                        .unwrap()
                } else {
                    ses.tensor_variable(v.to_vec(), shape, grad).unwrap()
                }
            };
            let read = |ses: &FrankenTorchSession, id| -> Vec<u64> {
                if f32_mode {
                    ses.tensor_values_f32(id)
                        .unwrap()
                        .iter()
                        .map(|x| (*x as f64).to_bits())
                        .collect()
                } else {
                    ses.tensor_values(id)
                        .unwrap()
                        .iter()
                        .map(|x| x.to_bits())
                        .collect()
                }
            };
            // causal tiles + key-padding (MIDDLE/leading broadcast), all now fused == reference.
            for cshape in [
                vec![1, 1, s, s],
                vec![s, s],
                vec![1, s, s],
                vec![b, 1, s, s],
                vec![b, 1, 1, s],
            ] {
                let cn: usize = cshape.iter().product();
                let cond: Vec<f64> = (0..cn).map(|i| ((i % 3) as f64) - 1.0).collect(); // -1/0/1
                let mut ses = FrankenTorchSession::new(ExecutionMode::Strict);
                let c = mk(&mut ses, &cond, cshape.clone(), false);
                let xt = mk(&mut ses, &xf, vec![b, h, s, s], false);
                let yt = mk(&mut ses, &yf, vec![b, h, s, s], false);
                let fused = ses.tensor_where(c, xt, yt).unwrap();
                let cg = mk(&mut ses, &cond, cshape.clone(), true);
                let xg = mk(&mut ses, &xf, vec![b, h, s, s], true);
                let yg = mk(&mut ses, &yf, vec![b, h, s, s], true);
                let refr = ses.tensor_where(cg, xg, yg).unwrap();
                assert_eq!(ses.tensor_shape(fused).unwrap(), vec![b, h, s, s]);
                assert_eq!(
                    read(&ses, fused),
                    read(&ses, refr),
                    "where two-full cond-tile fused != broadcast (cond={cshape:?} f32={f32_mode})"
                );
            }
        }
    }

    // Locks the f64 max_dim/min_dim (values+indices) borrow fast path: values and indices must match
    // a manual per-row reduction (parallel path, numel > gate). Same kernel as the tape -> bit-exact.
    #[test]
    fn max_min_dim_f64_borrow_values_indices_correct() {
        let (rows, cols) = (64usize, 1024usize);
        let n = rows * cols;
        let mut data = vec![0.0_f64; n];
        for r in 0..rows {
            for c in 0..cols {
                data[r * cols + c] = ((r * 7 + c * 3) % 101) as f64 * 0.01;
            }
            data[r * cols + (r * 37) % cols] = 100.0;
            data[r * cols + (r * 53 + 11) % cols] = -100.0;
        }
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let a = s
            .tensor_variable(data.clone(), vec![rows, cols], false)
            .unwrap();
        let (mv, mi) = s.tensor_max_dim(a, 1).unwrap();
        let (nv, ni) = s.tensor_min_dim(a, 1).unwrap();
        let (mvv, miv) = (s.tensor_values(mv).unwrap(), s.tensor_values(mi).unwrap());
        let (nvv, niv) = (s.tensor_values(nv).unwrap(), s.tensor_values(ni).unwrap());
        for r in 0..rows {
            assert_eq!(mvv[r], 100.0, "max val row {r}");
            assert_eq!(miv[r] as usize, (r * 37) % cols, "max idx row {r}");
            assert_eq!(nvv[r], -100.0, "min val row {r}");
            assert_eq!(niv[r] as usize, (r * 53 + 11) % cols, "min idx row {r}");
        }
    }

    // Locks the f64 argmax/argmin borrow fast path: indices must match a manual per-row argmax and
    // exercise the parallel path (numel > gate). Uses the SAME kernel as the tape, so bit-identical.
    #[test]
    fn argmax_argmin_f64_borrow_indices_correct() {
        let (rows, cols) = (64usize, 1024usize); // 65536 > gate
        let n = rows * cols;
        // per-row: place a unique max at a pseudo-random column, min at another.
        let mut data = vec![0.0_f64; n];
        for r in 0..rows {
            for c in 0..cols {
                data[r * cols + c] = ((r * 7 + c * 3) % 101) as f64 * 0.01;
            }
            let maxc = (r * 37) % cols;
            let minc = (r * 53 + 11) % cols;
            data[r * cols + maxc] = 100.0; // unique max
            data[r * cols + minc] = -100.0; // unique min
        }
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let a = s
            .tensor_variable(data.clone(), vec![rows, cols], false)
            .unwrap();
        let amax = s.tensor_argmax(a, 1).unwrap();
        let amin = s.tensor_argmin(a, 1).unwrap();
        let midx = s.tensor_values(amax).unwrap();
        let nidx = s.tensor_values(amin).unwrap();
        for r in 0..rows {
            assert_eq!(midx[r] as usize, (r * 37) % cols, "argmax row {r}");
            assert_eq!(nidx[r] as usize, (r * 53 + 11) % cols, "argmin row {r}");
        }
    }

    // Locks the no-grad f64 borrow fast paths for gammaln/i0/airy_ai (input-read-clone lever):
    // try_f64_unary_native (borrow) == grad-forced original path (same *_approx), bit-exact.
    #[test]
    fn gammaln_i0_airy_f64_borrow_match_original() {
        let n = 200_000usize;
        let bits = |v: &[f64]| v.iter().map(|z| z.to_bits()).collect::<Vec<_>>();
        for which in ["gammaln", "i0", "airy"] {
            // gammaln: positive domain (poles at non-positive integers); i0/airy: all reals.
            let data: Vec<f64> = if which == "gammaln" {
                (0..n).map(|i| 0.05 + (i % 900) as f64 * 0.01).collect()
            } else {
                (0..n).map(|i| ((i % 800) as f64 / 100.0) - 4.0).collect()
            };
            let mut ss = FrankenTorchSession::new(ExecutionMode::Strict);
            let a = ss.tensor_variable(data.clone(), vec![n], false).unwrap();
            let ag = ss.tensor_variable(data.clone(), vec![n], true).unwrap();
            let (fast, refr) = match which {
                "gammaln" => (
                    ss.tensor_gammaln(a).unwrap(),
                    ss.tensor_gammaln(ag).unwrap(),
                ),
                "i0" => (ss.tensor_i0(a).unwrap(), ss.tensor_i0(ag).unwrap()),
                _ => (
                    ss.tensor_special_airy_ai(a).unwrap(),
                    ss.tensor_special_airy_ai(ag).unwrap(),
                ),
            };
            assert_eq!(
                bits(&ss.tensor_values(fast).unwrap()),
                bits(&ss.tensor_values(refr).unwrap()),
                "{which} f64 borrow != original"
            );
        }
    }

    // Locks the no-grad f64 zeta borrow fast path: try_f64_binary_native (borrow) == grad-forced
    // apply_function (same zeta_approx par_zip), bit-exact.
    #[test]
    fn zeta_f64_borrow_match_apply_function() {
        let n = 200_000usize;
        // Hurwitz zeta(s, a): s > 1, a > 0.
        let sv: Vec<f64> = (0..n).map(|i| 1.5 + (i % 40) as f64 * 0.1).collect();
        let av: Vec<f64> = (0..n).map(|i| 0.5 + (i % 60) as f64 * 0.1).collect();
        let bits = |v: &[f64]| v.iter().map(|z| z.to_bits()).collect::<Vec<_>>();
        let mut ss = FrankenTorchSession::new(ExecutionMode::Strict);
        let ts = ss.tensor_variable(sv.clone(), vec![n], false).unwrap();
        let ta = ss.tensor_variable(av.clone(), vec![n], false).unwrap();
        let tsg = ss.tensor_variable(sv.clone(), vec![n], true).unwrap();
        let tag = ss.tensor_variable(av.clone(), vec![n], true).unwrap();
        let fast = ss.tensor_zeta(ts, ta).unwrap();
        let refr = ss.tensor_zeta(tsg, tag).unwrap();
        assert_eq!(
            bits(&ss.tensor_values(fast).unwrap()),
            bits(&ss.tensor_values(refr).unwrap()),
            "zeta f64 borrow != apply_function"
        );
    }

