    // Locks the fused pow_tensor f64 (frankentorch-powtensor-fused): exp(e·ln x) with the 0^0->1
    // rule in one pass must be bit-identical to the grad-forced compose (log+mul+exp+eq+full+where).
    // Covers x>0, x==0 (with e==0 -> 1 and e>0 -> 0), and x<0 (-> NaN, bits must match).
    #[test]
    fn pow_tensor_f64_fused_matches_composed_path() {
        let n = 200_000usize; // > PARALLEL_ELEMENTWISE_MIN
        let base: Vec<f64> = (0..n)
            .map(|i| match i % 5 {
                0 => 0.0,                           // 0^0 and 0^e cases
                1 => -1.3 - (i % 7) as f64 * 0.1,   // negative base -> NaN
                _ => 0.05 + (i % 97) as f64 * 0.04, // positive base
            })
            .collect();
        let expo: Vec<f64> = (0..n)
            .map(|i| match i % 5 {
                0 => (i % 2) as f64, // e==0 (0^0->1) and e==1 (0^1->0)
                _ => -2.0 + (i % 11) as f64 * 0.5,
            })
            .collect();
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s.tensor_variable(base.clone(), vec![n], false).unwrap();
        let e = s.tensor_variable(expo.clone(), vec![n], false).unwrap();
        let fused = s.tensor_pow_tensor(x, e).unwrap();
        let xg = s.tensor_variable(base.clone(), vec![n], true).unwrap(); // grad -> compose
        let eg = s.tensor_variable(expo.clone(), vec![n], true).unwrap();
        let refr = s.tensor_pow_tensor(xg, eg).unwrap();
        let bits = |v: &[f64]| v.iter().map(|x| x.to_bits()).collect::<Vec<_>>();
        assert_eq!(
            bits(&s.tensor_values(fused).unwrap()),
            bits(&s.tensor_values(refr).unwrap()),
            "pow_tensor f64 fused != composed"
        );
    }

