    #[test]
    fn var_std_dim_correction_golden_matches_torch() {
        // Differential golden vs torch 2.12: var([[1,2,3],[4,6,8]],dim1,c1)==[1,4];
        // c0==[2/3,8/3]; std(dim0,c1)==[2.12132034,2.82842712,3.53553391].
        // frankentorch-6zpcj.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s
            .tensor_variable(vec![1.0, 2.0, 3.0, 4.0, 6.0, 8.0], vec![2, 3], false)
            .unwrap();
        let cmp = |s: &mut FrankenTorchSession, id, want: &[f64], ctx: &str| {
            for (g, w) in s.tensor_values(id).unwrap().iter().zip(want.iter()) {
                assert!((g - w).abs() < 1e-8, "{ctx} {g} != {w}");
            }
        };
        let v1 = s.tensor_var_dim(x, 1, 1).unwrap();
        cmp(&mut s, v1, &[1.0, 4.0], "var dim1 c1");
        let v0 = s.tensor_var_dim(x, 1, 0).unwrap();
        cmp(&mut s, v0, &[2.0 / 3.0, 8.0 / 3.0], "var dim1 c0");
        let sd = s.tensor_std_dim(x, 0, 1).unwrap();
        cmp(
            &mut s,
            sd,
            &[2.121_320_34, 2.828_427_12, 3.535_533_91],
            "std dim0 c1",
        );
    }

