    #[test]
    fn cnn_block_integration_golden_matches_torch() {
        // Integration golden vs torch 2.12: x=arange16 [1,1,4,4] -> conv2d(W=[[1,0],
        // [0,1]]) -> relu -> max_pool2d(2) -> sum. pool==15; grad_x nonzero only at
        // idx 5 & 10 (==1.0; the maxpool winner = conv diag 5+10). frankentorch-afg8v.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s
            .tensor_variable((0..16).map(f64::from).collect(), vec![1, 1, 4, 4], true)
            .unwrap();
        let w = s
            .tensor_variable(vec![1.0, 0.0, 0.0, 1.0], vec![1, 1, 2, 2], false)
            .unwrap();
        let c = s.tensor_conv2d(x, w, None, (1, 1), (0, 0)).unwrap();
        let r = s.tensor_relu(c).unwrap();
        let p = s.tensor_max_pool2d(r, (2, 2), (2, 2)).unwrap();
        let loss = s.tensor_sum(p).unwrap();
        assert!(
            (s.tensor_values(loss).unwrap()[0] - 15.0).abs() < 1e-12,
            "pool sum != 15"
        );
        let report = s.tensor_backward(loss).unwrap();
        let g = s.tensor_gradient(&report, x).unwrap();
        for (i, &gv) in g.iter().enumerate() {
            let want = if i == 5 || i == 10 { 1.0 } else { 0.0 };
            assert!((gv - want).abs() < 1e-12, "grad_x[{i}]={gv} != {want}");
        }
    }

    #[test]
    fn attention_core_integration_golden_matches_torch() {
        // Integration golden vs torch 2.12: softmax([[1,2],[3,0]],dim1)@[[10,20],
        // [30,40]] -> attn + out. Tests softmax+matmul composition (attention core).
        // frankentorch-nf0t0.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let scores = s
            .tensor_variable(vec![1.0, 2.0, 3.0, 0.0], vec![2, 2], false)
            .unwrap();
        let v = s
            .tensor_variable(vec![10.0, 20.0, 30.0, 40.0], vec![2, 2], false)
            .unwrap();
        let attn = s.tensor_softmax(scores, 1).unwrap();
        let want_attn = [0.268_941_42, 0.731_058_58, 0.952_574_13, 0.047_425_87];
        for (g, w) in s.tensor_values(attn).unwrap().iter().zip(want_attn.iter()) {
            assert!((g - w).abs() < 1e-8, "attn {g} != {w}");
        }
        let out = s.tensor_matmul(attn, v).unwrap();
        let want_out = [24.621_171_57, 34.621_171_57, 10.948_517_46, 20.948_517_46];
        for (g, w) in s.tensor_values(out).unwrap().iter().zip(want_out.iter()) {
            assert!((g - w).abs() < 1e-7, "attn out {g} != {w}");
        }
    }

    #[test]
    fn mlp_forward_backward_integration_golden_matches_torch() {
        // Integration golden vs torch 2.12: x=[1,-2,3] -> linear(W1,b1) -> relu ->
        // linear(W2,b2) -> sum. out==10, hidden==[4.5,0], grad_x==[2,0,2] (relu
        // gates one path). Tests linear+relu+backward COMPOSITION. frankentorch-bilwq.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s
            .tensor_variable(vec![1.0, -2.0, 3.0], vec![1, 3], true)
            .unwrap();
        let w1 = s
            .tensor_variable(vec![1.0, 0.0, 1.0, 0.0, 1.0, -1.0], vec![2, 3], false)
            .unwrap();
        let b1 = s.tensor_variable(vec![0.5, -0.5], vec![2], false).unwrap();
        let w2 = s
            .tensor_variable(vec![2.0, 1.0], vec![1, 2], false)
            .unwrap();
        let b2 = s.tensor_variable(vec![1.0], vec![1], false).unwrap();
        let h = s.tensor_linear(x, w1, Some(b1)).unwrap();
        let hr = s.tensor_relu(h).unwrap();
        for (g, w) in s.tensor_values(hr).unwrap().iter().zip([4.5, 0.0].iter()) {
            assert!((g - w).abs() < 1e-12, "hidden {g} != {w}");
        }
        let out = s.tensor_linear(hr, w2, Some(b2)).unwrap();
        let loss = s.tensor_sum(out).unwrap();
        assert!(
            (s.tensor_values(loss).unwrap()[0] - 10.0).abs() < 1e-12,
            "out != 10"
        );
        let report = s.tensor_backward(loss).unwrap();
        let g = s.tensor_gradient(&report, x).unwrap();
        for (gg, w) in g.iter().zip([2.0, 0.0, 2.0].iter()) {
            assert!((gg - w).abs() < 1e-12, "grad_x {gg} != {w}");
        }
    }

