    #[test]
    fn triu_tril_diagonal_golden_matches_torch() {
        // Differential golden vs torch 2.12 on [[1,2,3],[4,5,6],[7,8,9]]:
        // triu(0)/tril(0)/triu(1)/diagonal(0). frankentorch-g2ilm.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let mk = |s: &mut FrankenTorchSession| {
            s.tensor_variable((1..=9).map(f64::from).collect(), vec![3, 3], false)
                .unwrap()
        };
        let chk = |s: &mut FrankenTorchSession, id, want: &[f64], ctx: &str| {
            for (g, w) in s.tensor_values(id).unwrap().iter().zip(want.iter()) {
                assert!((g - w).abs() < 1e-12, "{ctx} {g} != {w}");
            }
        };
        let x = mk(&mut s);
        let u = s.tensor_triu(x, 0).unwrap();
        chk(
            &mut s,
            u,
            &[1.0, 2.0, 3.0, 0.0, 5.0, 6.0, 0.0, 0.0, 9.0],
            "triu0",
        );
        let l = s.tensor_tril(x, 0).unwrap();
        chk(
            &mut s,
            l,
            &[1.0, 0.0, 0.0, 4.0, 5.0, 0.0, 7.0, 8.0, 9.0],
            "tril0",
        );
        let u1 = s.tensor_triu(x, 1).unwrap();
        chk(
            &mut s,
            u1,
            &[0.0, 2.0, 3.0, 0.0, 0.0, 6.0, 0.0, 0.0, 0.0],
            "triu1",
        );
        let d = s.tensor_diagonal(x, 0).unwrap();
        chk(&mut s, d, &[1.0, 5.0, 9.0], "diag");
    }

    #[test]
    fn einsum_golden_matches_torch() {
        // Differential golden vs torch.einsum 2.12: 'ij,jk->ik' matmul ==
        // [19,22,43,50]; 'ii->' trace == 5; 'ij->ji' transpose == [1,3,2,4].
        // frankentorch-vddpd.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let a = s
            .tensor_variable(vec![1.0, 2.0, 3.0, 4.0], vec![2, 2], false)
            .unwrap();
        let b = s
            .tensor_variable(vec![5.0, 6.0, 7.0, 8.0], vec![2, 2], false)
            .unwrap();
        let mm = s.tensor_einsum("ij,jk->ik", &[a, b]).unwrap();
        for (g, w) in s
            .tensor_values(mm)
            .unwrap()
            .iter()
            .zip([19.0, 22.0, 43.0, 50.0].iter())
        {
            assert!((g - w).abs() < 1e-12, "einsum matmul {g} != {w}");
        }
        let tr = s.tensor_einsum("ii->", &[a]).unwrap();
        assert!(
            (s.tensor_values(tr).unwrap()[0] - 5.0).abs() < 1e-12,
            "einsum trace"
        );
        let t = s.tensor_einsum("ij->ji", &[a]).unwrap();
        for (g, w) in s
            .tensor_values(t)
            .unwrap()
            .iter()
            .zip([1.0, 3.0, 2.0, 4.0].iter())
        {
            assert!((g - w).abs() < 1e-12, "einsum transpose {g} != {w}");
        }
    }

    #[test]
    fn complex_arithmetic_golden_matches_torch() {
        // Differential golden vs torch 2.12: (1+2i)*(3+4i)==-5+10i; abs(3+4i)==5;
        // conj(1+2i)==1-2i. frankentorch-8bh5u.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let ar = s.tensor_variable(vec![1.0], vec![1], false).unwrap();
        let ai = s.tensor_variable(vec![2.0], vec![1], false).unwrap();
        let br = s.tensor_variable(vec![3.0], vec![1], false).unwrap();
        let bi = s.tensor_variable(vec![4.0], vec![1], false).unwrap();
        let a = s.tensor_complex(ar, ai).unwrap();
        let b = s.tensor_complex(br, bi).unwrap();
        let m = s.tensor_mul(a, b).unwrap();
        let mre = s.tensor_real(m).unwrap();
        let mim = s.tensor_imag(m).unwrap();
        assert!(
            (s.tensor_values(mre).unwrap()[0] - (-5.0)).abs() < 1e-12,
            "mul re"
        );
        assert!(
            (s.tensor_values(mim).unwrap()[0] - 10.0).abs() < 1e-12,
            "mul im"
        );
        let ab = s.tensor_abs(b).unwrap();
        assert!((s.tensor_values(ab).unwrap()[0] - 5.0).abs() < 1e-12, "abs");
        let c = s.tensor_conj(a).unwrap();
        let cre = s.tensor_real(c).unwrap();
        let cim = s.tensor_imag(c).unwrap();
        assert!(
            (s.tensor_values(cre).unwrap()[0] - 1.0).abs() < 1e-12,
            "conj re"
        );
        assert!(
            (s.tensor_values(cim).unwrap()[0] - (-2.0)).abs() < 1e-12,
            "conj im"
        );
    }

    #[test]
    fn sort_topk_golden_matches_torch() {
        // Differential golden vs torch 2.12: sort([3,1,2],ascending) -> values
        // [1,2,3] indices [1,2,0]; topk([3,1,2],k=2,largest) -> values [3,2]
        // indices [0,2]. frankentorch-bvux4.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s
            .tensor_variable(vec![3.0, 1.0, 2.0], vec![3], false)
            .unwrap();
        let (sv, si) = s.tensor_sort(x, 0, false).unwrap();
        for (g, w) in s
            .tensor_values(sv)
            .unwrap()
            .iter()
            .zip([1.0, 2.0, 3.0].iter())
        {
            assert!((g - w).abs() < 1e-12, "sort value {g} != {w}");
        }
        assert_eq!(si, vec![1, 2, 0], "sort indices");
        let (tv, ti) = s.tensor_topk(x, 2, 0, true, true).unwrap();
        for (g, w) in s.tensor_values(tv).unwrap().iter().zip([3.0, 2.0].iter()) {
            assert!((g - w).abs() < 1e-12, "topk value {g} != {w}");
        }
        assert_eq!(ti, vec![0, 2], "topk indices");
    }

