    #[test]
    fn session_topk_dim0_nograd_fast_path_matches_tracked_topk() {
        let rows = 2048usize;
        let cols = 3usize;
        let k = 5usize;
        let mut values = Vec::with_capacity(rows * cols);
        for row in 0..rows {
            values.push(if row == 17 {
                f64::NAN
            } else {
                (row % 101) as f64
            });
            values.push(((rows - row) % 113) as f64);
            values.push(if row == 200 {
                f64::INFINITY
            } else {
                (row % 37) as f64
            });
        }

        let mut fast = FrankenTorchSession::new(ExecutionMode::Strict);
        let fast_input = fast
            .tensor_variable(values.clone(), vec![rows, cols], false)
            .expect("fast input");
        let (fast_topk, fast_indices) = fast
            .tensor_topk(fast_input, k, 0, true, true)
            .expect("fast topk");

        let mut tracked = FrankenTorchSession::new(ExecutionMode::Strict);
        let tracked_input = tracked
            .tensor_variable(values, vec![rows, cols], true)
            .expect("tracked input");
        let (tracked_topk, tracked_indices) = tracked
            .tensor_topk(tracked_input, k, 0, true, true)
            .expect("tracked topk");

        assert_eq!(fast_indices, tracked_indices);
        let fast_values = fast.tensor_values(fast_topk).expect("fast values");
        let tracked_values = tracked.tensor_values(tracked_topk).expect("tracked values");
        assert_eq!(fast_values.len(), tracked_values.len());
        for (fast, tracked) in fast_values.iter().zip(tracked_values.iter()) {
            assert_eq!(fast.to_bits(), tracked.to_bits());
        }
        assert!(!fast.tensor_requires_grad(fast_topk).unwrap());
        assert!(tracked.tensor_requires_grad(tracked_topk).unwrap());
    }

    #[test]
    fn session_topk_backward() {
        let mut session = FrankenTorchSession::new(ExecutionMode::Strict);
        let t = session
            .tensor_variable(vec![3.0, 1.0, 4.0, 1.0, 5.0], vec![5], true)
            .expect("t");
        let (topk, _indices) = session.tensor_topk(t, 2, 0, true, true).expect("topk");
        // topk = [5.0, 4.0], indices = [4, 2]
        let loss = session.tensor_sum(topk).expect("sum");
        let report = session.tensor_backward(loss).expect("backward");
        // Only positions 4 and 2 should have gradient 1.0, rest 0.0
        assert_eq!(
            report.gradient(t),
            Some(vec![0.0, 0.0, 1.0, 0.0, 1.0].as_slice())
        );
    }

