    #[test]
    fn roll_dims_general_rank_fast_path_matches_sequential() {
        // The general-rank (rank != 2) single-pass fast path must be BIT-IDENTICAL to applying the
        // single-dim rolls sequentially (the fallback). Covers rank 3 & 4, multi-dim, negative and
        // zero shifts, and a rolled-then-unrolled dim. Roll is pure positional movement.
        let cases: &[(Vec<usize>, Vec<i64>, Vec<usize>)] = &[
            (vec![2, 3, 4], vec![1, -1], vec![0, 2]),
            (vec![2, 3, 4], vec![2, 1, 3], vec![0, 1, 2]),
            (vec![3, 5, 2], vec![-2], vec![1]),
            (vec![2, 2, 3, 4], vec![1, 2, -1], vec![0, 2, 3]),
            (vec![4, 3, 5], vec![0, 7], vec![0, 2]), // zero shift dim0 + wrap>size dim2
            (vec![6], vec![2], vec![0]),             // rank-1 through roll_dims
        ];
        for (shape, shifts, dims) in cases {
            let n: usize = shape.iter().product();
            let data: Vec<f64> = (0..n).map(|i| i as f64).collect();
            let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
            let t = s
                .tensor_variable(data.clone(), shape.clone(), false)
                .unwrap();
            let fast = s.tensor_roll_dims(t, shifts, dims).unwrap();
            let fast_vals = s.tensor_values(fast).unwrap();
            // reference: sequential single-dim rolls (independent of roll_dims' fast path).
            let mut r = s.tensor_variable(data, shape.clone(), false).unwrap();
            for (&sh, &d) in shifts.iter().zip(dims.iter()) {
                r = s.tensor_roll(r, sh, d).unwrap();
            }
            let ref_vals = s.tensor_values(r).unwrap();
            assert_eq!(
                fast_vals, ref_vals,
                "shape={shape:?} shifts={shifts:?} dims={dims:?}"
            );
        }
    }

    #[test]
    fn fftshift_ifftshift_delegate_matches_sequential_rolls() {
        // fftshift/ifftshift now delegate to tensor_roll_dims (single-pass); must equal the old
        // per-dim sequential rolls. Cover 2-D & 3-D, all-dims and a dim subset, even & odd sizes.
        let cases: &[(Vec<usize>, Option<Vec<usize>>)] = &[
            (vec![4, 6], None),
            (vec![5, 7], None), // odd sizes (fftshift != ifftshift)
            (vec![4, 3, 6], Some(vec![0, 2])),
            (vec![3, 5, 2], None),
        ];
        for (shape, dim) in cases {
            let n: usize = shape.iter().product();
            let data: Vec<f64> = (0..n).map(|i| i as f64).collect();
            let ndim = shape.len();
            let dims: Vec<usize> = dim.clone().unwrap_or_else(|| (0..ndim).collect());
            for fwd in [true, false] {
                let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
                let t = s
                    .tensor_variable(data.clone(), shape.clone(), false)
                    .unwrap();
                let got = if fwd {
                    s.tensor_fft_fftshift(t, dim.as_deref())
                } else {
                    s.tensor_fft_ifftshift(t, dim.as_deref())
                }
                .unwrap();
                let got_vals = s.tensor_values(got).unwrap();
                // reference: sequential rolls with the fftshift/ifftshift shift per dim.
                let mut r = s
                    .tensor_variable(data.clone(), shape.clone(), false)
                    .unwrap();
                for &d in &dims {
                    // fftshift = roll +(n/2); ifftshift = roll -(n/2) (exact inverse, matches torch
                    // for even AND odd n — the old -((n+1)/2) was wrong for odd n).
                    let sh = if fwd {
                        (shape[d] / 2) as i64
                    } else {
                        -((shape[d] / 2) as i64)
                    };
                    r = s.tensor_roll(r, sh, d).unwrap();
                }
                assert_eq!(
                    got_vals,
                    s.tensor_values(r).unwrap(),
                    "fwd={fwd} shape={shape:?} dim={dim:?}"
                );
            }
        }
        // Torch-correctness lock (odd n): ifftshift([0..5]) must equal torch's [2,3,4,0,1], and
        // ifftshift is the exact inverse of fftshift. (Regression guard for the odd-n convention.)
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let t = s
            .tensor_variable(vec![0.0, 1.0, 2.0, 3.0, 4.0], vec![5], false)
            .unwrap();
        let ifs = s.tensor_fft_ifftshift(t, None).unwrap();
        assert_eq!(s.tensor_values(ifs).unwrap(), vec![2.0, 3.0, 4.0, 0.0, 1.0]);
        let t2 = s
            .tensor_variable(vec![0.0, 1.0, 2.0, 3.0, 4.0], vec![5], false)
            .unwrap();
        let fs = s.tensor_fft_fftshift(t2, None).unwrap();
        let round = s.tensor_fft_ifftshift(fs, None).unwrap();
        assert_eq!(
            s.tensor_values(round).unwrap(),
            vec![0.0, 1.0, 2.0, 3.0, 4.0],
            "ifftshift-of-fftshift must be identity"
        );
    }

