        let report = session.backward(y).expect("backward");
        // d/dx mish(0) = tanh(softplus(0)) + 0 * ... = tanh(ln(2)) ≈ 0.6
        let expected = 2.0_f64.ln().tanh();
        assert!((session.gradient(&report, x).unwrap() - expected).abs() < 1e-10);
