    #[test]
    fn lu_primitives_fail_loud_on_requires_grad() {
        // frankentorch-sn58 / edyp9: LU primitives used to silently sever
        // autograd. ALL of lu_factor / linalg_lu / lu_unpack / lu_solve are now
        // differentiable, so each must SUCCEED on requires_grad input and
        // propagate grad (regression against re-severing autograd).
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let a = s
            .tensor_variable(vec![2.0, 0.0, 0.0, 3.0], vec![2, 2], true)
            .unwrap();
        let (lu, piv) = s
            .tensor_lu_factor(a)
            .expect("lu_factor is now autograd-aware");
        assert!(
            s.tensor_requires_grad(lu).unwrap(),
            "differentiable lu_factor output must require grad"
        );
        let (_p, l, u) = s
            .tensor_linalg_lu(a)
            .expect("linalg_lu is now autograd-aware");
        assert!(
            s.tensor_requires_grad(l).unwrap() && s.tensor_requires_grad(u).unwrap(),
            "differentiable linalg_lu L/U outputs must require grad"
        );
        let (_pu, lu_l, lu_u) = s
            .tensor_lu_unpack(lu, &piv)
            .expect("lu_unpack is now autograd-aware");
        assert!(
            s.tensor_requires_grad(lu_l).unwrap() && s.tensor_requires_grad(lu_u).unwrap(),
            "differentiable lu_unpack L/U outputs must require grad"
        );
        let b = s.tensor_variable(vec![1.0, 2.0], vec![2, 1], true).unwrap();
        let x = s
            .tensor_lu_solve(lu, &piv, b)
            .expect("lu_solve is now autograd-aware");
        assert!(
            s.tensor_requires_grad(x).unwrap(),
            "differentiable lu_solve output must require grad"
        );
    }

