    #[test]
    fn qr_ldl_f32_matches_torch() {
        // torch supports f32 for geqrf / householder_product / ormqr / ldl_*; ft-api
        // must too (upcast -> f64 core -> downcast). Compare to torch's f32 goldens
        // with an f32 tolerance (the f64-then-round path agrees to ~1e-6).
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let close = |g: &[f32], w: &[f32], tag: &str| {
            assert_eq!(g.len(), w.len(), "{tag} len");
            for (i, (x, y)) in g.iter().zip(w.iter()).enumerate() {
                assert!((x - y).abs() < 1e-4, "{tag}[{i}] = {x}, want {y}");
            }
        };
        // geqrf f32 (tall 4x3).
        let a_in = s
            .tensor_variable_f32(
                vec![1., 2., 3., 4., 5., 6., 7., 8., 10., 1., 0., 1.],
                vec![4, 3],
                false,
            )
            .unwrap();
        let (a, tau) = s.tensor_geqrf(a_in).unwrap();
        assert_eq!(s.tensor_dtype(a).unwrap(), DType::F32);
        assert_eq!(s.tensor_dtype(tau).unwrap(), DType::F32);
        close(
            &s.tensor_values_f32(a).unwrap(),
            &[
                -8.185353,
                -9.529217,
                -11.972605,
                0.43547592,
                1.4812254,
                1.2897736,
                0.7620828,
                0.5234745,
                0.99659234,
                0.10886898,
                0.83571213,
                -0.60471773,
            ],
            "geqrf_a",
        );
        close(
            &s.tensor_values_f32(tau).unwrap(),
            &[1.1221695, 1.0139723, 1.4644682],
            "geqrf_tau",
        );
        // householder_product (orgqr) f32.
        let q = s.tensor_householder_product(a, tau).unwrap();
        assert_eq!(s.tensor_dtype(q).unwrap(), DType::F32);
        close(
            &s.tensor_values_f32(q).unwrap(),
            &[
                -0.12216949,
                0.564276,
                0.8122917,
                -0.4886778,
                0.23175634,
                -0.15017119,
                -0.8551861,
                -0.10076359,
                -0.10921597,
                -0.12216945,
                -0.78595674,
                0.55290407,
            ],
            "Q",
        );
        // ormqr f32 (just exercise the path: Q^T @ Q == I columns, dtype f32).
        let i3 = s
            .tensor_variable_f32(
                vec![1., 0., 0., 0., 1., 0., 0., 0., 1., 0., 0., 0.],
                vec![4, 3],
                false,
            )
            .unwrap();
        let qi = s.tensor_ormqr(a, tau, i3, true, false).unwrap();
        assert_eq!(s.tensor_dtype(qi).unwrap(), DType::F32);

        // ldl_factor + ldl_solve f32.
        let sym = s
            .tensor_variable_f32(
                vec![4., 2., -2., 2., 5., 6., -2., 6., 14.],
                vec![3, 3],
                false,
            )
            .unwrap();
        let (ld, piv) = s.tensor_linalg_ldl_factor(sym).unwrap();
        assert_eq!(s.tensor_dtype(ld).unwrap(), DType::F32);
        close(
            &s.tensor_values_f32(ld).unwrap(),
            &[4.0, 0.0, 0.0, 0.5, 13.0, 0.0, -0.5, 0.53846157, 0.23076916],
            "ldlLD",
        );
        let b = s
            .tensor_variable_f32(vec![1., 4., 2., 5., 3., 6.], vec![3, 2], false)
            .unwrap();
        let x = s.tensor_linalg_ldl_solve(ld, piv, b).unwrap();
        assert_eq!(s.tensor_dtype(x).unwrap(), DType::F32);
        close(
            &s.tensor_values_f32(x).unwrap(),
            &[
                1.6666673, 5.666669, -1.6666675, -5.66667, 1.1666672, 3.6666684,
            ],
            "ldlX",
        );
    }

