    #[test]
    fn unique_consecutive_exact_equality_matches_torch() {
        // torch.unique_consecutive uses EXACT `==`: consecutive NaNs stay distinct
        // (NaN != NaN) and adjacent-but-distinct f64s are NOT merged. Verified vs
        // torch 2.12: [1, nan, nan, 2] -> [1, nan, nan, 2].
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let t = s
            .tensor_variable(vec![1.0, f64::NAN, f64::NAN, 2.0], vec![4], false)
            .unwrap();
        let (u, _, counts) = s.tensor_unique_consecutive(t, false, true).unwrap();
        let uv = s.tensor_values(u).unwrap();
        let cv = s.tensor_values(counts.unwrap()).unwrap();
        assert_eq!(uv.len(), 4, "each NaN is its own run: {uv:?}");
        assert_eq!(uv[0], 1.0);
        assert!(uv[1].is_nan() && uv[2].is_nan());
        assert_eq!(uv[3], 2.0);
        assert_eq!(cv, vec![1.0, 1.0, 1.0, 1.0]);
        // adjacent distinct f64s (one ULP apart) must NOT merge
        let next = f64::from_bits(1.0_f64.to_bits() + 1); // 1.0 + 1 ULP, distinct
        let t2 = s
            .tensor_variable(vec![1.0, next, 2.0], vec![3], false)
            .unwrap();
        let (u2, _, _) = s.tensor_unique_consecutive(t2, false, false).unwrap();
        assert_eq!(s.tensor_values(u2).unwrap(), vec![1.0, next, 2.0]);
    }

