        let vals = s.tensor_values(hist).unwrap();
        assert_eq!(vals, vec![0.25, 0.25]);
        assert_eq!(s.tensor_values(edges).unwrap(), vec![0.0, 2.0, 4.0]);
        let integral = vals.iter().sum::<f64>() * 2.0;
        assert!((integral - 1.0).abs() < 1e-12);
