    #[test]
    fn diff_basic() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let t = s
            .tensor_variable(vec![1.0, 3.0, 6.0, 10.0], vec![4], false)
            .unwrap();
        let out = s.tensor_diff(t, 1).unwrap();
        let vals = s.tensor_values(out).unwrap();
        assert_eq!(vals, vec![2.0, 3.0, 4.0]);
    }

    #[test]
    fn diff_nograd_fast_path_strided_and_large() {
        // The no-grad fast path computes the adjacent difference directly on borrowed
        // storage; exercise dim=0 (strided unravel) and a large input (parallel).
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        // [[0,1,4],[9,16,25]] diff along dim 0 -> [[9,15,21]]
        let x = s
            .tensor_variable(vec![0.0, 1.0, 4.0, 9.0, 16.0, 25.0], vec![2, 3], false)
            .unwrap();
        let d0 = s.tensor_diff_full(x, 1, 0, None, None).unwrap();
        assert_eq!(s.tensor_values(d0).unwrap(), vec![9.0, 15.0, 21.0]);

        // Large [256,4096] dim=1: out[r,c] = x[r,c+1]-x[r,c]; with x[r,c]=r+2c the diff is 2.
        let rows = 256usize;
        let cols = 4096usize;
        #[allow(clippy::cast_precision_loss)]
        let data: Vec<f64> = (0..rows * cols)
            .map(|k| (k / cols) as f64 + 2.0 * (k % cols) as f64)
            .collect();
        let xl = s.tensor_variable(data, vec![rows, cols], false).unwrap();
        let dl = s.tensor_diff(xl, 1).unwrap();
        let v = s.tensor_values(dl).unwrap();
        assert_eq!(v.len(), rows * (cols - 1));
        assert!(
            v.iter().all(|&d| (d - 2.0).abs() < 1e-12),
            "all diffs must be 2.0"
        );
    }

