    #[test]
    fn repeat_interleave_propagates_gradient_via_sum_of_repeats() {
        // Regression test for frankentorch-5196.
        // tensor_repeat_interleave used to extract values, repeat in
        // plain f64, and rebuild a non-grad leaf. After wrapping in
        // tensor_apply_function with the sum-of-R backward,
        // gradients flow.
        //
        // For x = [3, 5], repeats = 4:
        //   out = [3, 3, 3, 3, 5, 5, 5, 5]
        // Under sum loss: grad_x[i] = number of output entries
        // routing to i = 4 each.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s.tensor_variable(vec![3.0, 5.0], vec![2], true).unwrap();
        let out = s.tensor_repeat_interleave(x, 4).unwrap();
        let loss = s.tensor_sum(out).unwrap();
        let report = s.tensor_backward(loss).unwrap();
        let grad = s
            .tensor_gradient(&report, x)
            .expect("repeat_interleave must propagate gradient via sum-of-R");
        let expected = [4.0_f64, 4.0];
        for (i, (&g, &e)) in grad.iter().zip(expected.iter()).enumerate() {
            assert!(
                (g - e).abs() < 1e-12,
                "repeat_interleave grad[{i}] = {g}, expected {e}"
            );
        }
    }

    #[test]
    fn repeat_interleave_rejects_overflow() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let t = s.tensor_variable(vec![1.0], vec![1], false).unwrap();
        let err = s
            .tensor_repeat_interleave(t, usize::MAX)
            .expect_err("overflow should fail closed");
        assert!(format!("{err}").contains("repeat_interleave: output size overflow"));
    }

    #[test]
    fn repeat_interleave_tensor_and_dim_torch_golden() {
        // Verified vs torch 2.12.
        // Per-element repeats, flattened: [1,2,3] reps [2,1,3] -> [1,1,2,3,3,3].
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s
            .tensor_variable(vec![1.0, 2.0, 3.0], vec![3], false)
            .unwrap();
        let o = s
            .tensor_repeat_interleave_tensor(x, &[2, 1, 3], None)
            .unwrap();
        assert_eq!(s.tensor_shape(o).unwrap(), vec![6]);
        assert_eq!(
            s.tensor_values(o).unwrap(),
            vec![1.0, 1.0, 2.0, 3.0, 3.0, 3.0]
        );

        // Scalar repeats along dim=1: [[1,2],[3,4]] x2 -> [[1,1,2,2],[3,3,4,4]].
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s
            .tensor_variable(vec![1.0, 2.0, 3.0, 4.0], vec![2, 2], false)
            .unwrap();
        let o = s.tensor_repeat_interleave_dim(x, 2, 1).unwrap();
        assert_eq!(s.tensor_shape(o).unwrap(), vec![2, 4]);
        assert_eq!(
            s.tensor_values(o).unwrap(),
            vec![1.0, 1.0, 2.0, 2.0, 3.0, 3.0, 4.0, 4.0]
        );

        // Per-slice repeats along dim=0: [[1,2],[3,4]] reps [1,2]
        //   -> [[1,2],[3,4],[3,4]].
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s
            .tensor_variable(vec![1.0, 2.0, 3.0, 4.0], vec![2, 2], false)
            .unwrap();
        let o = s
            .tensor_repeat_interleave_tensor(x, &[1, 2], Some(0))
            .unwrap();
        assert_eq!(s.tensor_shape(o).unwrap(), vec![3, 2]);
        assert_eq!(
            s.tensor_values(o).unwrap(),
            vec![1.0, 2.0, 3.0, 4.0, 3.0, 4.0]
        );

        // A zero repeat drops the slice: dim=1 reps [0,2] -> [[2,2],[4,4]].
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s
            .tensor_variable(vec![1.0, 2.0, 3.0, 4.0], vec![2, 2], false)
            .unwrap();
        let o = s
            .tensor_repeat_interleave_tensor(x, &[0, 2], Some(1))
            .unwrap();
        assert_eq!(s.tensor_shape(o).unwrap(), vec![2, 2]);
        assert_eq!(s.tensor_values(o).unwrap(), vec![2.0, 2.0, 4.0, 4.0]);

        // Wrong-length repeats + bad dim rejected.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s
            .tensor_variable(vec![1.0, 2.0, 3.0, 4.0], vec![2, 2], false)
            .unwrap();
        assert!(
            s.tensor_repeat_interleave_tensor(x, &[1, 2, 3], Some(0))
                .is_err()
        );
        let x2 = s
            .tensor_variable(vec![1.0, 2.0, 3.0, 4.0], vec![2, 2], false)
            .unwrap();
        assert!(
            s.tensor_repeat_interleave_tensor(x2, &[2], Some(5))
                .is_err()
        );
    }

    #[test]
    fn repeat_interleave_tensor_propagates_gradient() {
        // dim=0 per-slice repeats [1,2]: row1 emitted twice, so under sum loss
        // grad to row0 = 1 each, row1 = 2 each.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s
            .tensor_variable(vec![1.0, 2.0, 3.0, 4.0], vec![2, 2], true)
            .unwrap();
        let o = s
            .tensor_repeat_interleave_tensor(x, &[1, 2], Some(0))
            .unwrap();
        let loss = s.tensor_sum(o).unwrap();
        let report = s.tensor_backward(loss).unwrap();
        let g = s.tensor_gradient(&report, x).expect("grad");
        assert_eq!(g, vec![1.0, 1.0, 2.0, 2.0]);
    }

