    #[test]
    fn pinv_propagates_gradient_through_full_rank_input() {
        // Regression for frankentorch-d3gs: requires_grad input now
        // takes the normal-equation path (A^T A)^{-1} A^T or
        // A^T (A A^T)^{-1}, which composes through autograd-aware
        // ops. The previous SVD-based path silently severed autograd.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        // Tall matrix (m=3, n=2) with full column rank.
        #[rustfmt::skip]
        let a = s.tensor_variable(vec![
            1.0, 0.0,
            0.0, 1.0,
            1.0, 1.0,
        ], vec![3, 2], true).unwrap();
        let pinv = s.tensor_linalg_pinv(a).unwrap();
        let pinv_shape = s.tensor_shape(pinv).unwrap();
        assert_eq!(pinv_shape, vec![2, 3]);
        // Pseudoinverse property: A @ A+ @ A ≈ A.
        let a_pinv = s.tensor_matmul(a, pinv).unwrap();
        let recon = s.tensor_matmul(a_pinv, a).unwrap();
        let a_vals = s.tensor_values(a).unwrap();
        let r = s.tensor_values(recon).unwrap();
        for (i, (&got, &exp)) in r.iter().zip(a_vals.iter()).enumerate() {
            assert!(
                (got - exp).abs() < 1e-8,
                "pinv roundtrip [{i}]: got {got}, expected {exp}"
            );
        }
        // Gradient of sum(pinv) must exist and be finite.
        let loss = s.tensor_sum(pinv).unwrap();
        let report = s.tensor_backward(loss).unwrap();
        let grad = s
            .tensor_gradient(&report, a)
            .expect("input gradient should exist (autograd not severed)");
        assert!(grad.iter().all(|g| g.is_finite()));
        // Some component must be non-zero — otherwise the chain rule
        // is silently zero, indicating a severance.
        assert!(grad.iter().any(|g| g.abs() > 1e-12));
    }

    #[test]
    fn pinv_propagates_gradient_through_wide_input() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        // Wide matrix (m=2, n=3) with full row rank.
        #[rustfmt::skip]
        let a = s.tensor_variable(vec![
            1.0, 0.0, 1.0,
            0.0, 1.0, 1.0,
        ], vec![2, 3], true).unwrap();
        let pinv = s.tensor_linalg_pinv(a).unwrap();
        let loss = s.tensor_sum(pinv).unwrap();
        let report = s.tensor_backward(loss).unwrap();
        let grad = s.tensor_gradient(&report, a).expect("wide pinv grad");
        assert!(grad.iter().all(|g| g.is_finite()));
        assert!(grad.iter().any(|g| g.abs() > 1e-12));
    }

    #[test]
    fn kthvalue_basic() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let t = s
            .tensor_variable(vec![5.0, 1.0, 3.0, 2.0, 4.0], vec![5], false)
            .unwrap();
        let (val_id, idx_id) = s.tensor_kthvalue(t, 3).unwrap();
        let val = s.tensor_values(val_id).unwrap()[0];
        let idx = s.tensor_values(idx_id).unwrap()[0];
        assert!((val - 3.0).abs() < 1e-10); // 3rd smallest is 3.0
        assert!((idx - 2.0).abs() < 1e-10); // index 2 in original
    }

    #[test]
    fn kthvalue_quickselect_matches_stable_sort_with_ties() {
        // frankentorch-kgs4.57: the quickselect path must return the SAME (value,
        // index) as the previous full stable sort_by(total_cmp), including for
        // duplicate values (ties resolve to the lowest original index) and across
        // every k. Brute-force reference = stable sort of indices by value.
        let data: Vec<f64> = vec![
            3.0, 1.0, 3.0, 2.0, 1.0, 3.0, 5.0, 2.0, 1.0, 4.0, 3.0, 0.0, 5.0, 2.0, 4.0, 1.0,
        ];
        let n = data.len();
        let mut ref_idx: Vec<usize> = (0..n).collect();
        ref_idx.sort_by(|&a, &b| data[a].total_cmp(&data[b]));
        for k in 1..=n {
            let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
            let t = s.tensor_variable(data.clone(), vec![n], false).unwrap();
            let (val_id, idx_id) = s.tensor_kthvalue(t, k).unwrap();
            let val = s.tensor_values(val_id).unwrap()[0];
            let idx = s.tensor_values(idx_id).unwrap()[0] as usize;
            let want = ref_idx[k - 1];
            assert_eq!(idx, want, "k={k}: index mismatch");
            assert_eq!(val.to_bits(), data[want].to_bits(), "k={k}: value mismatch");
        }
    }

    #[test]
    fn kthvalue_f64_radix_matches_sorted_reference_large_with_ties() {
        // Larger array (exercises the parallel radix-select path) with many duplicate
        // values; must match a stable sort (ascending-index tie-break) for value AND index.
        // frankentorch-kthvalue-radixselect.
        let n = 20_000usize;
        let data: Vec<f64> = (0..n).map(|i| ((i * 13) % 97) as f64 * 0.25).collect();
        let mut order: Vec<usize> = (0..n).collect();
        order.sort_by(|&a, &b| data[a].total_cmp(&data[b])); // stable -> ascending index on ties
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let t = s.tensor_variable(data.clone(), vec![n], false).unwrap();
        for &k in &[1usize, 2, 137, n / 3, n / 2, n - 1, n] {
            let (val_id, idx_id) = s.tensor_kthvalue(t, k).unwrap();
            let val = s.tensor_values(val_id).unwrap()[0];
            let idx = s.tensor_values(idx_id).unwrap()[0] as usize;
            let want = order[k - 1];
            assert_eq!(idx, want, "k={k}: index mismatch");
            assert_eq!(val.to_bits(), data[want].to_bits(), "k={k}: value mismatch");
        }
    }

    #[test]
    fn kthvalue_f64_nan_falls_back_and_orders_nan_last() {
        // torch.kthvalue orders NaN LAST (total_cmp); the radix path bails on NaN and the
        // total_cmp fallback must reproduce that ordering. frankentorch-kthvalue-radixselect.
        let data = vec![3.0, f64::NAN, 1.0, 2.0, f64::NAN];
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let t = s.tensor_variable(data, vec![5], false).unwrap();
        // total_cmp order: 1.0, 2.0, 3.0, NaN, NaN
        let kth = |s: &mut FrankenTorchSession, k: usize| -> f64 {
            let (v, _) = s.tensor_kthvalue(t, k).unwrap();
            s.tensor_values(v).unwrap()[0]
        };
        assert_eq!(kth(&mut s, 1), 1.0);
        assert_eq!(kth(&mut s, 2), 2.0);
        assert_eq!(kth(&mut s, 3), 3.0);
        assert!(kth(&mut s, 4).is_nan());
        assert!(kth(&mut s, 5).is_nan());
    }

    #[test]
    fn kthvalue_first_and_last() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let t = s
            .tensor_variable(vec![10.0, 20.0, 30.0], vec![3], false)
            .unwrap();
        let (min_val, _) = s.tensor_kthvalue(t, 1).unwrap();
        let (max_val, _) = s.tensor_kthvalue(t, 3).unwrap();
        assert!((s.tensor_values(min_val).unwrap()[0] - 10.0).abs() < 1e-10);
        assert!((s.tensor_values(max_val).unwrap()[0] - 30.0).abs() < 1e-10);
    }

    #[test]
    fn kthvalue_propagates_gradient_to_routed_index() {
        // Regression test for frankentorch-0juq. tensor_kthvalue used
        // to extract sort indices, build the value as a non-grad
        // leaf, and rebuild a non-grad leaf for the index — silently
        // severing autograd through the value branch. After wrapping
        // in tensor_apply_function with single-index routing
        // backward, gradient flows to the input position selected
        // by sort.
        //
        // For x = [3, 1, 4, 1, 5], k=3:
        //   sorted asc = [1, 1, 3, 4, 5] → 3rd smallest is 3 at idx 0
        //   grad_input[0] = 1 (under sum loss with grad_value = 1)
        //   grad_input[1..4] = 0
        //
        // (Note: ties go by first-occurrence in the sort comparator
        // total_cmp, which gives idx 1 for the first '1' but
        // routing for k=3 is unambiguous.)
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s
            .tensor_variable(vec![3.0, 1.0, 4.0, 1.0, 5.0], vec![5], true)
            .unwrap();
        let (val_id, _idx_id) = s.tensor_kthvalue(x, 3).unwrap();
        let report = s.tensor_backward(val_id).unwrap();
        let grad = s
            .tensor_gradient(&report, x)
            .expect("kthvalue must propagate gradient via index routing");
        // Index 0 holds the 3rd-smallest value (= 3.0).
        let expected = [1.0_f64, 0.0, 0.0, 0.0, 0.0];
        for (i, (&g, &e)) in grad.iter().zip(expected.iter()).enumerate() {
            assert!(
                (g - e).abs() < 1e-12,
                "kthvalue grad[{i}] = {g}, expected {e}"
            );
        }
    }

    #[test]
    fn kthvalue_rejects_invalid_k() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let t = s.tensor_variable(vec![1.0, 2.0], vec![2], false).unwrap();
        assert!(s.tensor_kthvalue(t, 0).is_err());
        assert!(s.tensor_kthvalue(t, 3).is_err());
    }

