        let sq = s.tensor_sum(q).unwrap();
        let sr = s.tensor_sum(r).unwrap();
        let loss = s.tensor_add(sq, sr).unwrap();
        s.tensor_backward(loss).unwrap();
        let grad_batched = s.tensor_grad(a).unwrap().expect("batched grad present");

