    #[test]
    fn cond_p2_propagates_input_gradient_torch_golden() {
        // tensor_linalg_svdvals became autograd-aware (frankentorch-rl4g), so
        // the p=±2 condition-number path (svdvals -> narrow sigma_max/min ->
        // div) now threads a gradient back to the input instead of failing
        // loud. Verified against torch 2.12 for A = [[1,2],[3,4]]:
        //   cond(A,2)  = 14.9330343736593
        //     d/dA     = [ 31.1396424604143, -20.5923442076933,
        //                 -12.0540551459668,  11.5518028482182]
        //   cond(A,-2) = 0.0669656263407472
        //     d/dA     = [-0.139642460414265,  0.0923442076933042,
        //                  0.0540551459668122, -0.051802848218195]
        let cases: &[(f64, f64, [f64; 4])] = &[
            (
                2.0,
                14.933_034_373_659_3,
                [
                    31.139_642_460_414_3,
                    -20.592_344_207_693_3,
                    -12.054_055_145_966_8,
                    11.551_802_848_218_2,
                ],
            ),
            (
                -2.0,
                0.066_965_626_340_747_2,
                [
                    -0.139_642_460_414_265,
                    0.092_344_207_693_304_2,
                    0.054_055_145_966_812_2,
                    -0.051_802_848_218_195,
                ],
            ),
        ];
        for &(p, want_val, ref want_grad) in cases {
            let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
            #[rustfmt::skip]
            let a = s.tensor_variable(vec![1.0, 2.0, 3.0, 4.0], vec![2, 2], true).unwrap();
            let c = s.tensor_linalg_cond(a, p).unwrap();
            let val = s.tensor_values(c).unwrap()[0];
            assert!((val - want_val).abs() < 1e-9, "cond(p={p}) value {val}");
            let report = s.tensor_backward(c).unwrap();
            let grad = s
                .tensor_gradient(&report, a)
                .expect("p=±2 input gradient should exist");
            for (i, (&g, &w)) in grad.iter().zip(want_grad.iter()).enumerate() {
                assert!(
                    (g - w).abs() < 1e-7,
                    "cond(p={p}) grad[{i}]: got {g} want {w}"
                );
            }
        }
    }

