    #[test]
    fn interpolate_bilinear_upsample() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        // [1, 1, 2, 2] -> [1, 1, 4, 4] with align_corners=true
        #[rustfmt::skip]
        let input = s.tensor_variable(
            vec![0.0, 1.0, 1.0, 0.0],
            vec![1, 1, 2, 2], false,
        ).unwrap();
        let out = s
            .tensor_interpolate(input, Some(vec![4, 4]), None, "bilinear", Some(true))
            .unwrap();
        let shape = s.tensor_shape(out).unwrap();
        assert_eq!(shape, vec![1, 1, 4, 4]);
        let vals = s.tensor_values(out).unwrap();
        // Corners should be preserved exactly
        assert!((vals[0] - 0.0).abs() < 1e-10, "top-left");
        assert!((vals[3] - 1.0).abs() < 1e-10, "top-right");
        assert!((vals[12] - 1.0).abs() < 1e-10, "bottom-left");
        assert!((vals[15] - 0.0).abs() < 1e-10, "bottom-right");
    }

    #[test]
    fn interpolate_matches_torch_bilinear_bicubic() {
        // Independent oracle: torch 2.12 F.interpolate of [[1,2],[3,4]] -> 4x4 for
        // bilinear and bicubic, both align_corners modes. bicubic ac=False
        // extrapolates beyond the input range (the cubic-convolution boundary
        // case), which is exactly where a wrong coefficient/coordinate shows up.
        let cases: [(&str, bool, [f64; 16]); 4] = [
            (
                "bilinear",
                true,
                [
                    1.0,
                    1.3333333333,
                    1.6666666667,
                    2.0,
                    1.6666666667,
                    2.0,
                    2.3333333333,
                    2.6666666667,
                    2.3333333333,
                    2.6666666667,
                    3.0,
                    3.3333333333,
                    3.0,
                    3.3333333333,
                    3.6666666667,
                    4.0,
                ],
            ),
            (
                "bilinear",
                false,
                [
                    1.0, 1.25, 1.75, 2.0, 1.5, 1.75, 2.25, 2.5, 2.5, 2.75, 3.25, 3.5, 3.0, 3.25,
                    3.75, 4.0,
                ],
            ),
            (
                "bicubic",
                true,
                [
                    1.0,
                    1.3148148148,
                    1.6851851852,
                    2.0,
                    1.6296296296,
                    1.9444444444,
                    2.3148148148,
                    2.6296296296,
                    2.3703703704,
                    2.6851851852,
                    3.0555555556,
                    3.3703703704,
                    3.0,
                    3.3148148148,
                    3.6851851852,
                    4.0,
                ],
            ),
            (
                "bicubic",
                false,
                [
                    0.68359375, 1.015625, 1.5625, 1.89453125, 1.34765625, 1.6796875, 2.2265625,
                    2.55859375, 2.44140625, 2.7734375, 3.3203125, 3.65234375, 3.10546875, 3.4375,
                    3.984375, 4.31640625,
                ],
            ),
        ];
        for (mode, ac, want) in cases {
            let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
            let input = s
                .tensor_variable(vec![1.0, 2.0, 3.0, 4.0], vec![1, 1, 2, 2], false)
                .unwrap();
            let out = s
                .tensor_interpolate(input, Some(vec![4, 4]), None, mode, Some(ac))
                .unwrap();
            let got = s.tensor_values(out).unwrap();
            for (g, w) in got.iter().zip(want.iter()) {
                assert!(
                    (g - w).abs() < 1e-9,
                    "interpolate {mode}/ac={ac}: got {got:?} want {want:?}"
                );
            }
        }
    }

    #[test]
    fn interpolate_f32_matches_torch_and_preserves_dtype() {
        // f32 native fast path (frankentorch): F32 input previously ERRORED with
        // `UnsupportedStorageAccess { dtype: F32 }` at the F64-only storage read.
        // Same torch goldens as `interpolate_matches_torch_bilinear_bicubic`; the
        // f32 sampler matches within the interpolate tolerance and must return F32.
        let cases: [(&str, [f64; 16]); 2] = [
            (
                "bilinear",
                [
                    1.0, 1.25, 1.75, 2.0, 1.5, 1.75, 2.25, 2.5, 2.5, 2.75, 3.25, 3.5, 3.0, 3.25,
                    3.75, 4.0,
                ],
            ),
            (
                "bicubic",
                [
                    0.68359375, 1.015625, 1.5625, 1.89453125, 1.34765625, 1.6796875, 2.2265625,
                    2.55859375, 2.44140625, 2.7734375, 3.3203125, 3.65234375, 3.10546875, 3.4375,
                    3.984375, 4.31640625,
                ],
            ),
        ];
        for (mode, want) in cases {
            let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
            let input = s
                .tensor_variable_f32(vec![1.0_f32, 2.0, 3.0, 4.0], vec![1, 1, 2, 2], false)
                .unwrap();
            let out = s
                .tensor_interpolate(input, Some(vec![4, 4]), None, mode, Some(false))
                .unwrap();
            assert_eq!(
                s.tensor_dtype(out).unwrap(),
                DType::F32,
                "interpolate {mode} must preserve F32 dtype"
            );
            let got = s.tensor_values_lossy_f64(out).unwrap();
            for (g, w) in got.iter().zip(want.iter()) {
                assert!(
                    (g - w).abs() < 1e-5,
                    "interpolate f32 {mode}: got {got:?} want {want:?}"
                );
            }
        }
        // nearest is a pure gather, so the f32 path is exact.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let input = s
            .tensor_variable_f32(vec![1.0_f32, 2.0, 3.0, 4.0], vec![1, 1, 2, 2], false)
            .unwrap();
        let out = s
            .tensor_interpolate(input, Some(vec![4, 4]), None, "nearest", None)
            .unwrap();
        assert_eq!(s.tensor_dtype(out).unwrap(), DType::F32);
        let got = s.tensor_values_lossy_f64(out).unwrap();
        assert_eq!(
            got,
            vec![
                1.0, 1.0, 2.0, 2.0, 1.0, 1.0, 2.0, 2.0, 3.0, 3.0, 4.0, 4.0, 3.0, 3.0, 4.0, 4.0
            ]
        );
    }

    #[test]
    fn interpolate_bicubic_shape() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let input = s
            .tensor_variable(vec![1.0; 16], vec![1, 1, 4, 4], false)
            .unwrap();
        let out = s
            .tensor_interpolate(input, Some(vec![8, 8]), None, "bicubic", Some(false))
            .unwrap();
        let shape = s.tensor_shape(out).unwrap();
        assert_eq!(shape, vec![1, 1, 8, 8]);
        // Constant input should stay constant through bicubic
        let vals = s.tensor_values(out).unwrap();
        for (i, &v) in vals.iter().enumerate() {
            assert!((v - 1.0).abs() < 0.1, "bicubic constant at {i}: {v}");
        }
    }

    #[test]
    fn interpolate_bicubic_unclamped_source_matches_reference() {
        // Regression for the border bug: bicubic must NOT clamp the source coordinate
        // (PyTorch's area_pixel_compute_source_index keeps it unclamped for cubic and only
        // clamps the tap indices). With input height 1 the vertical pass is the identity,
        // isolating the 1-D width interpolation so we can check against a direct reference.
        let input_vals = vec![1.0_f64, 2.0, 4.0, 8.0];
        let iw = 4usize;
        let ow = 8usize;
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let input = s
            .tensor_variable(input_vals.clone(), vec![1, 1, 1, iw], false)
            .unwrap();
        let out = s
            .tensor_interpolate(input, Some(vec![1, ow]), None, "bicubic", Some(false))
            .unwrap();
        let vals = s.tensor_values(out).unwrap();
        assert_eq!(vals.len(), ow);

        // Independent Keys (a = -0.75) cubic reference using the UNCLAMPED source coordinate.
        let kw = |x: f64| -> f64 {
            let a = -0.75;
            let ax = x.abs();
            if ax <= 1.0 {
                (a + 2.0) * ax * ax * ax - (a + 3.0) * ax * ax + 1.0
            } else if ax <= 2.0 {
                a * ax * ax * ax - 5.0 * a * ax * ax + 8.0 * a * ax - 4.0 * a
            } else {
                0.0
            }
        };
        let reference = |ox: usize| -> f64 {
            let src = (ox as f64 + 0.5) * iw as f64 / ow as f64 - 0.5; // unclamped, may be < 0
            let ix = src.floor() as i64;
            let tx = src - ix as f64;
            let mut acc = 0.0;
            for dx in -1..=2_i64 {
                let w = kw(tx - dx as f64);
                let idx = (ix + dx).clamp(0, iw as i64 - 1) as usize;
                acc += w * input_vals[idx];
            }
            acc
        };
        for ox in 0..ow {
            let expected = reference(ox);
            assert!(
                (vals[ox] - expected).abs() < 1e-9,
                "bicubic[{ox}] = {} expected {}",
                vals[ox],
                expected
            );
        }
        // The leftmost output sample maps to src = -0.25; a clamped implementation would
        // collapse it to input[0] = 1.0. The (correct) unclamped result must differ.
        assert!(
            (vals[0] - 1.0).abs() > 1e-6,
            "bicubic[0] = {} should not equal the clamped input[0]=1.0",
            vals[0]
        );

        // The autograd path must produce identical forward values (its clamp was removed too).
        let input_g = s
            .tensor_variable(input_vals.clone(), vec![1, 1, 1, iw], true)
            .unwrap();
        let out_g = s
            .tensor_interpolate(input_g, Some(vec![1, ow]), None, "bicubic", Some(false))
            .unwrap();
        let vals_g = s.tensor_values(out_g).unwrap();
        for ox in 0..ow {
            assert!(
                (vals_g[ox] - vals[ox]).abs() < 1e-12,
                "bicubic autograd path differs at {ox}: {} vs {}",
                vals_g[ox],
                vals[ox]
            );
        }
    }

    #[test]
    fn interpolate_linear_1d() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        // [1, 1, 2] -> [1, 1, 4] with align_corners=true
        let input = s
            .tensor_variable(vec![0.0, 1.0], vec![1, 1, 2], false)
            .unwrap();
        let out = s
            .tensor_interpolate(input, Some(vec![4]), None, "linear", Some(true))
            .unwrap();
        let vals = s.tensor_values(out).unwrap();
        // Should be [0, 1/3, 2/3, 1] with align_corners
        assert!((vals[0]).abs() < 1e-10);
        assert!((vals[3] - 1.0).abs() < 1e-10);
        // Monotonically increasing
        for i in 1..vals.len() {
            assert!(vals[i] >= vals[i - 1] - 1e-10);
        }
    }

