    #[test]
    fn multilabel_soft_margin_loss_parallel_matches_serial_reference_bit_exact() {
        // Both the fwd (per-row loss) and bwd (per-row grad) closures parallelize once
        // n*c >= PARALLEL_ELEMENTWISE_MIN. Compare loss ("none") and grad (from summed
        // loss, so grad_out = 1) to an INDEPENDENT serial reference, bit-for-bit.
        let (n, c) = (128usize, 512usize);
        assert!(
            n >= 2 && n * c >= super::PARALLEL_ELEMENTWISE_MIN,
            "must hit the parallel path"
        );
        let input: Vec<f64> = (0..n * c)
            .map(|i| {
                let x = (i as u64).wrapping_mul(0x9e3779b97f4a7c15).wrapping_add(3);
                (x >> 40) as f64 / (1u64 << 24) as f64 * 6.0 - 3.0
            })
            .collect();
        let target: Vec<f64> = (0..n * c).map(|i| ((i * 7 + 1) % 2) as f64).collect();
        let mut want_loss = vec![0.0f64; n];
        for i in 0..n {
            let ro = i * c;
            let mut sum = 0.0;
            for j in 0..c {
                let x = input[ro + j];
                let y = target[ro + j];
                sum += y * (-super::stable_softplus(-x)) + (1.0 - y) * (-super::stable_softplus(x));
            }
            want_loss[i] = -sum / c as f64;
        }
        let inv_c = 1.0 / c as f64;
        let mut want_grad = vec![0.0f64; n * c];
        for i in 0..n {
            let ro = i * c;
            for j in 0..c {
                let x = input[ro + j];
                let y = target[ro + j];
                let sig = 1.0 / (1.0 + (-x).exp());
                want_grad[ro + j] = inv_c * (sig - y);
            }
        }
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let inp = s.tensor_variable(input, vec![n, c], true).unwrap();
        let tgt = s.tensor_variable(target, vec![n, c], false).unwrap();
        let loss = s
            .tensor_multilabel_soft_margin_loss(inp, tgt, None, "none")
            .unwrap();
        let got_loss = s.tensor_values(loss).unwrap();
        assert_eq!(got_loss.len(), want_loss.len());
        for (i, (g, wv)) in got_loss.iter().zip(want_loss.iter()).enumerate() {
            assert_eq!(
                g.to_bits(),
                wv.to_bits(),
                "mlsm loss parallel vs serial ref @{i}"
            );
        }
        let summed = s.tensor_sum(loss).unwrap();
        let rep = s.tensor_backward(summed).unwrap();
        let grad = s.tensor_gradient(&rep, inp).expect("mlsm grad present");
        assert_eq!(grad.len(), want_grad.len());
        for (i, (g, wv)) in grad.iter().zip(want_grad.iter()).enumerate() {
            assert_eq!(
                g.to_bits(),
                wv.to_bits(),
                "mlsm grad parallel vs serial ref @{i}"
            );
        }
    }

    #[test]
    fn multilabel_soft_margin_loss_all_correct() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        // Large positive logits for target=1, large negative for target=0
        let input = s
            .tensor_variable(vec![10.0, -10.0, 10.0, -10.0], vec![1, 4], false)
            .unwrap();
        let target = s
            .tensor_variable(vec![1.0, 0.0, 1.0, 0.0], vec![1, 4], false)
            .unwrap();
        let loss = s.multilabel_soft_margin_loss(input, target).unwrap();
        let val = s.tensor_values(loss).unwrap()[0];
        assert!(val < 0.01, "well-classified should have low loss: {val}");
    }

    #[test]
    fn multilabel_soft_margin_loss_propagates_gradient_via_bce_with_logits() {
        // Regression test for frankentorch-4liu.
        // multilabel_soft_margin_loss used to extract values, sum
        // the per-element BCE-with-logits in plain f64, and rebuild
        // a requires_grad=false leaf — silently severing autograd
        // for multi-label classification training. After delegating
        // to bce_with_logits_loss (autograd-aware via composition
        // through tensor_relu + tensor_abs + tensor_log1p +
        // tensor_mean), gradients flow to logits.
        //
        // Test at x = ±1 (away from the relu/abs corner at 0) so
        // the smooth derivative is unambiguous. For BCE-with-logits:
        //   d bce(x, t) / dx = sigmoid(x) - t      (smooth interior)
        // For input = [[1.0, -1.0]], target = [[1.0, 0.0]]:
        //   d/dx_0 = sigmoid(1)  - 1 = 0.7311 - 1 = -0.2689
        //   d/dx_1 = sigmoid(-1) - 0 = 0.2689
        // After mean over 2 elements (1/2 factor):
        //   grad_logits = [[-0.13447, 0.13447]]
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let logits = s
            .tensor_variable(vec![1.0, -1.0], vec![1, 2], true)
            .unwrap();
        let targets = s
            .tensor_variable(vec![1.0, 0.0], vec![1, 2], false)
            .unwrap();
        let loss = s.multilabel_soft_margin_loss(logits, targets).unwrap();
        let report = s.tensor_backward(loss).unwrap();
        let grad = s
            .tensor_gradient(&report, logits)
            .expect("multilabel_soft_margin_loss must propagate gradient through logits");

        let sigmoid = |x: f64| 1.0 / (1.0 + (-x).exp());
        let expected = [(sigmoid(1.0) - 1.0) / 2.0, (sigmoid(-1.0) - 0.0) / 2.0];
        for (i, (&g, &e)) in grad.iter().zip(expected.iter()).enumerate() {
            assert!(
                (g - e).abs() < 1e-12,
                "multilabel_soft_margin_loss grad[{i}] = {g}, expected {e}"
            );
        }
    }

    #[test]
    fn tensor_multilabel_soft_margin_loss_f32_nograd_matches_stable_formula() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let input_values = vec![-1.0_f32, 0.0, 1.0, 2.0, -2.0, 0.5];
        let target_values = vec![0.0_f32, 1.0, 1.0, 0.0, 0.0, 1.0];
        let input = s
            .tensor_variable_f32(input_values.clone(), vec![2, 3], false)
            .unwrap();
        let target = s
            .tensor_variable_f32(target_values.clone(), vec![2, 3], false)
            .unwrap();

        let loss = s
            .tensor_multilabel_soft_margin_loss(input, target, None, "none")
            .unwrap();
        assert_eq!(s.tensor_dtype(loss).unwrap(), DType::F32);
        let got = s.tensor_values_lossy_f64(loss).unwrap();

        let expected: Vec<f64> = input_values
            .chunks(3)
            .zip(target_values.chunks(3))
            .map(|(xs, ys)| {
                let mut sum = 0.0_f32;
                for (&x, &y) in xs.iter().zip(ys.iter()) {
                    sum += y * stable_softplus_f32(-x) + (1.0 - y) * stable_softplus_f32(x);
                }
                f64::from(sum / 3.0)
            })
            .collect();

        for (i, (&g, &e)) in got.iter().zip(expected.iter()).enumerate() {
            assert!(
                (g - e).abs() < 1e-6,
                "multilabel_soft_margin_loss f32 none[{i}] = {g}, expected {e}"
            );
        }
    }

    // ── conv3d and conv_transpose tests ────────────────────────────────

    #[test]
    fn conv3d_f32_fused_matches_op_graph_within_tolerance() {
        // Isomorphism for the f32 no-grad fused conv3d
        // (ft_kernel_cpu::conv3d_forward_f32) vs the f32 op-graph (narrow/cat/bmm,
        // forced via requires_grad=true), within f32 tol. A couple stride/pad combos.
        let (n, ic, oc, d, h, w, kd, kh, kw) = (2usize, 3, 4, 5, 6, 6, 3, 3, 3);
        let xv: Vec<f32> = (0..n * ic * d * h * w)
            .map(|i| ((i % 17) as f32 - 8.0) * 0.1 + (i as f32) * 0.005)
            .collect();
        let wv: Vec<f32> = (0..oc * ic * kd * kh * kw)
            .map(|i| ((i % 11) as f32 - 5.0) * 0.05)
            .collect();
        let bv: Vec<f32> = (0..oc).map(|c| 0.05 * c as f32 - 0.1).collect();
        for &(s_, p_) in &[(1usize, 1usize), (2, 0)] {
            let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
            let x = s
                .tensor_variable_f32(xv.clone(), vec![n, ic, d, h, w], false)
                .unwrap();
            let wt = s
                .tensor_variable_f32(wv.clone(), vec![oc, ic, kd, kh, kw], false)
                .unwrap();
            let bt = s.tensor_variable_f32(bv.clone(), vec![oc], false).unwrap();
            let out = s
                .functional_conv3d(x, wt, Some(bt), (s_, s_, s_), (p_, p_, p_))
                .unwrap();
            let fused = s.tensor_values_f32(out).unwrap();

            let mut s2 = FrankenTorchSession::new(ExecutionMode::Strict);
            let x2 = s2
                .tensor_variable_f32(xv.clone(), vec![n, ic, d, h, w], true)
                .unwrap();
            let wt2 = s2
                .tensor_variable_f32(wv.clone(), vec![oc, ic, kd, kh, kw], false)
                .unwrap();
            let bt2 = s2.tensor_variable_f32(bv.clone(), vec![oc], false).unwrap();
            let out2 = s2
                .functional_conv3d(x2, wt2, Some(bt2), (s_, s_, s_), (p_, p_, p_))
                .unwrap();
            let reference = s2.tensor_values_f32(out2).unwrap();
            assert_eq!(fused.len(), reference.len());
            for (i, (a, b)) in fused.iter().zip(reference.iter()).enumerate() {
                assert!(
                    (a - b).abs() <= 1e-4 + 1e-4 * b.abs(),
                    "s={s_} p={p_} [{i}]: f32 fused {a} vs op-graph {b}"
                );
            }
        }
    }

    #[test]
    fn conv3d_dilated_matches_torch() {
        // torch F.conv3d(arange(1..=128)[1,2,4,4,4], arange(1..=16)[1,2,2,2,2]*0.1,
        //                None, stride=1, padding=0, dilation=2) -> [1,1,2,2,2]
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let xv: Vec<f64> = (1..=128).map(|v| v as f64).collect();
        let wv: Vec<f64> = (1..=16).map(|v| v as f64 * 0.1).collect();
        let x = s.tensor_variable(xv, vec![1, 2, 4, 4, 4], false).unwrap();
        let w = s.tensor_variable(wv, vec![1, 2, 2, 2, 2], false).unwrap();
        let out = s
            .functional_conv3d_dilated(x, w, None, (1, 1, 1), (0, 0, 0), (2, 2, 2), 1)
            .unwrap();
        assert_eq!(s.tensor_shape(out).unwrap(), vec![1, 1, 2, 2, 2]);
        let want = [
            997.6, 1011.2, 1052.0, 1065.6, 1215.2, 1228.8, 1269.6, 1283.2,
        ];
        let got = s.tensor_values(out).unwrap();
        for (g, w) in got.iter().zip(want.iter()) {
            assert!((g - w).abs() < 1e-9, "dil2 got {got:?} want {want:?}");
        }
    }

