    #[test]
    fn functional_conv3d_depthwise_nopad_f64_borrow_fast_path_matches_reference() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let (n, c, d, h, w) = (2usize, 3usize, 2usize, 3usize, 4usize);
        let xv: Vec<f64> = (0..n * c * d * h * w)
            .map(|i| (i as f64 - 19.0) * 0.125)
            .collect();
        let wv = vec![1.5, -0.25, 0.75];
        let bv = vec![0.5, -1.0, 2.0];
        let x = s
            .tensor_variable(xv.clone(), vec![n, c, d, h, w], false)
            .unwrap();
        let wt = s
            .tensor_variable(wv.clone(), vec![c, 1, 1, 1, 1], false)
            .unwrap();
        let bt = s.tensor_variable(bv.clone(), vec![c], false).unwrap();
        let out = s
            .functional_conv3d_dilated(x, wt, Some(bt), (1, 1, 1), (0, 0, 0), (1, 1, 1), c)
            .unwrap();
        assert_eq!(s.tensor_shape(out).unwrap(), vec![n, c, d, h, w]);
        let got = s.tensor_values(out).unwrap();
        let mut want = Vec::with_capacity(xv.len());
        for ni in 0..n {
            for ci in 0..c {
                for zi in 0..d {
                    for yi in 0..h {
                        for xi in 0..w {
                            let idx = ((((ni * c + ci) * d + zi) * h + yi) * w) + xi;
                            want.push(xv[idx] * wv[ci] + bv[ci]);
                        }
                    }
                }
            }
        }
        assert_eq!(got, want);
    }

