    #[test]
    fn conv3d_grad_matches_finite_diff() {
        // Fused conv3d grad (custom op: conv3d_forward/backward + 3-D col2im) must
        // compute the true dinput/dweight/dbias, validated against central finite
        // differences with stride 1 / padding 1 (overlapping patches exercise col2im).
        let (n, ic, oc, d, h, w, kd, kh, kw) = (2usize, 2, 3, 3, 3, 3, 2, 2, 2);
        let nin = n * ic * d * h * w;
        let nwt = oc * ic * kd * kh * kw;
        let xv: Vec<f64> = (0..nin).map(|i| ((i % 7) as f64 - 3.0) * 0.2).collect();
        let wv: Vec<f64> = (0..nwt).map(|i| ((i % 5) as f64 - 2.0) * 0.15).collect();
        let bv: Vec<f64> = (0..oc).map(|c| 0.1 * c as f64 - 0.1).collect();
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s
            .tensor_variable(xv.clone(), vec![n, ic, d, h, w], true)
            .unwrap();
        let wt = s
            .tensor_variable(wv.clone(), vec![oc, ic, kd, kh, kw], true)
            .unwrap();
        let bt = s.tensor_variable(bv.clone(), vec![oc], true).unwrap();
        let out = s
            .functional_conv3d(x, wt, Some(bt), (1, 1, 1), (1, 1, 1))
            .unwrap();
        let loss = s.tensor_sum(out).unwrap();
        s.tensor_backward(loss).unwrap();
        let gx = s.tensor_grad(x).unwrap().unwrap();
        let gw = s.tensor_grad(wt).unwrap().unwrap();
        let gb = s.tensor_grad(bt).unwrap().unwrap();
        let loss_fn = |xs: &[f64], ws: &[f64], bs: &[f64]| -> f64 {
            let mut s2 = FrankenTorchSession::new(ExecutionMode::Strict);
            let xi = s2
                .tensor_variable(xs.to_vec(), vec![n, ic, d, h, w], false)
                .unwrap();
            let wi = s2
                .tensor_variable(ws.to_vec(), vec![oc, ic, kd, kh, kw], false)
                .unwrap();
            let bi = s2.tensor_variable(bs.to_vec(), vec![oc], false).unwrap();
            let o = s2
                .functional_conv3d(xi, wi, Some(bi), (1, 1, 1), (1, 1, 1))
                .unwrap();
            s2.tensor_values(o).unwrap().iter().sum()
        };
        let hh = 1e-6;
        let chk = |g: f64, fd: f64, what: &str, i: usize| {
            assert!(
                (g - fd).abs() <= 1e-5 + 1e-4 * fd.abs(),
                "{what}[{i}]: analytic {g} vs finite-diff {fd}"
            );
        };
        for i in 0..nin {
            let (mut p, mut m) = (xv.clone(), xv.clone());
            p[i] += hh;
            m[i] -= hh;
            chk(
                gx[i],
                (loss_fn(&p, &wv, &bv) - loss_fn(&m, &wv, &bv)) / (2.0 * hh),
                "dx",
                i,
            );
        }
        for i in 0..nwt {
            let (mut p, mut m) = (wv.clone(), wv.clone());
            p[i] += hh;
            m[i] -= hh;
            chk(
                gw[i],
                (loss_fn(&xv, &p, &bv) - loss_fn(&xv, &m, &bv)) / (2.0 * hh),
                "dw",
                i,
            );
        }
        for i in 0..oc {
            let (mut p, mut m) = (bv.clone(), bv.clone());
            p[i] += hh;
            m[i] -= hh;
            chk(
                gb[i],
                (loss_fn(&xv, &wv, &p) - loss_fn(&xv, &wv, &m)) / (2.0 * hh),
                "db",
                i,
            );
        }
    }

    #[test]
    fn conv3d_f64_borrowed_input_grad_contract() {
        // Regression guard for frankentorch-kgs4.119: the f64 fused conv3d grad
        // path borrows its padded input and weight from the tape instead of
        // saving full owned copies in FunctionCtx.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let input_vals: Vec<f64> = (0..8).map(|i| i as f64 + 1.0).collect();
        let input = s
            .tensor_variable(input_vals.clone(), vec![1, 1, 2, 2, 2], true)
            .unwrap();
        let weight = s
            .tensor_variable(vec![2.0], vec![1, 1, 1, 1, 1], true)
            .unwrap();
        let out = s
            .functional_conv3d(input, weight, None, (1, 1, 1), (0, 0, 0))
            .unwrap();
        let loss = s.tensor_sum(out).unwrap();
        s.tensor_backward(loss).unwrap();

        let in_grad = s.tensor_grad(input).unwrap().unwrap();
        assert_eq!(in_grad, vec![2.0; 8]);

        let w_grad = s.tensor_grad(weight).unwrap().unwrap();
        assert_eq!(w_grad, vec![input_vals.iter().sum::<f64>()]);
    }

