    #[test]
    fn adaptive_pool2d_uneven_buckets_match_torch() {
        // Independent oracle: torch 2.12 adaptive pooling 5x5 -> 3x3, where the
        // bucket sizes are UNEVEN (start = floor(i*in/out), end = ceil((i+1)*in/out)) —
        // a classic off-by-one spot in the bucket-boundary formula.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s
            .tensor_variable(
                (1..=25).map(|v| v as f64).collect(),
                vec![1, 1, 5, 5],
                false,
            )
            .unwrap();
        let (amax, _idx) = s.functional_adaptive_max_pool2d(x, (3, 3)).unwrap();
        assert_eq!(
            s.tensor_values(amax).unwrap(),
            vec![7.0, 9.0, 10.0, 17.0, 19.0, 20.0, 22.0, 24.0, 25.0]
        );
        let aavg = s.functional_adaptive_avg_pool2d(x, (3, 3)).unwrap();
        let want = [4.0, 5.5, 7.0, 11.5, 13.0, 14.5, 19.0, 20.5, 22.0];
        let got = s.tensor_values(aavg).unwrap();
        for (g, w) in got.iter().zip(want.iter()) {
            assert!(
                (g - w).abs() < 1e-9,
                "adaptive_avg uneven: got {got:?} want {want:?}"
            );
        }
    }

