    #[test]
    fn functional_normalize_positive_scale_invariant() {
        // Metamorphic relation: for positive finite k and nonzero
        // slices, normalize(k*x, p, dim) == normalize(x, p, dim).
        // This catches denominator, dim-broadcast, and eps-clamp drift
        // without relying on a PyTorch oracle.
        let scales = [0.25, 0.5, 3.0, 17.0];
        let ps = [1.0, 2.0];

        for rows in 1..4 {
            for cols in 2..6 {
                let values: Vec<f64> = (0..rows * cols)
                    .map(|i| {
                        let raw = ((i * 37 + rows * 11 + cols * 5) % 29) as f64;
                        raw / 7.0 + 0.25
                    })
                    .collect();

                for &p in &ps {
                    for &scale in &scales {
                        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
                        let x = s
                            .tensor_variable(values.clone(), vec![rows, cols], false)
                            .unwrap();
                        let scaled_values: Vec<f64> =
                            values.iter().map(|value| value * scale).collect();
                        let xs = s
                            .tensor_variable(scaled_values, vec![rows, cols], false)
                            .unwrap();

                        let normalized = s.functional_normalize(x, p, 1).unwrap();
                        let normalized_scaled = s.functional_normalize(xs, p, 1).unwrap();
                        let base_vals = s.tensor_values(normalized).unwrap();
                        let scaled_vals = s.tensor_values(normalized_scaled).unwrap();

                        for (idx, (&base, &scaled)) in
                            base_vals.iter().zip(scaled_vals.iter()).enumerate()
                        {
                            let diff = (base - scaled).abs();
                            let tol = 32.0 * base.abs().max(scaled.abs()).max(1.0) * f64::EPSILON;
                            assert!(
                                diff <= 1e-12 || diff <= tol,
                                "normalize(k*x, p={p}, dim=1)[{idx}] = {scaled}, \
                                 normalize(x) = {base}, scale={scale}, diff={diff:e}, tol={tol:e}"
                            );
                        }
                    }
                }
            }
        }
    }

    #[test]
    fn functional_normalize_propagates_gradient_through_input() {
        // Regression test for frankentorch-c5g4. functional_normalize
        // used to extract values, divide in plain f64, and rebuild
        // a requires_grad=false leaf — silently severing autograd
        // through every L2-normalization layer (used in retrieval /
        // contrastive / metric-learning models).
        //
        // After composing through abs/pow/sum_dim/clamp_min/unsqueeze/
        // expand/div primitives, gradients flow.
        //
        // For input = [3.0, 4.0] with p=2 (L2 normalize on dim=0):
        //   norm = sqrt(9 + 16) = 5
        //   y    = [3/5, 4/5] = [0.6, 0.8]
        //   loss = sum(y) = 1.4
        // Gradient of L2 normalize:
        //   d/dx_i (x_i / ||x||_2) = (||x||_2 - x_i^2/||x||_2) / ||x||_2^2
        //                          = (1 - x_i^2/||x||_2^2) / ||x||_2
        //                          = (1 - y_i^2) / ||x||_2
        //   d/dx_j (x_i / ||x||_2) = -x_i x_j / ||x||_2^3
        //                          = -y_i y_j / ||x||_2     (j != i)
        // Under sum loss (grad_y = [1, 1]):
        //   grad_x_i = sum_j (1) * d y_j / d x_i
        //            = (1 - y_i^2)/||x||_2 - sum_{j != i} y_i y_j / ||x||_2
        //            = (1 - y_i sum_j y_j) / ||x||_2
        // For x = [3, 4]: y_i = [0.6, 0.8], sum y = 1.4, ||x||=5
        //   grad_0 = (1 - 0.6 * 1.4) / 5 = (1 - 0.84) / 5 = 0.16 / 5 = 0.032
        //   grad_1 = (1 - 0.8 * 1.4) / 5 = (1 - 1.12) / 5 = -0.12 / 5 = -0.024
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let input = s.tensor_variable(vec![3.0, 4.0], vec![2], true).unwrap();
        let out = s.functional_normalize(input, 2.0, 0).unwrap();
        let loss = s.tensor_sum(out).unwrap();
        let report = s.tensor_backward(loss).unwrap();
        let grad = s
            .tensor_gradient(&report, input)
            .expect("functional_normalize must propagate gradient through input");
        let expected = [0.032_f64, -0.024];
        for (i, (&g, &e)) in grad.iter().zip(expected.iter()).enumerate() {
            assert!(
                (g - e).abs() < 1e-12,
                "functional_normalize grad[{i}] = {g}, expected {e}"
            );
        }
    }

