    #[test]
    fn functional_conv1d_groups_and_dilation_compose_matches_torch() {
        // torch F.conv1d(arange(1..=12)[1,2,6], [[[1,2]],[[3,4]]][2,1,2], None,
        //                stride=1, padding=1, dilation=2, groups=2) -> [1,2,6]
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let xv: Vec<f64> = (1..=12).map(|v| v as f64).collect();
        let x = s.tensor_variable(xv, vec![1, 2, 6], false).unwrap();
        let w = s
            .tensor_variable(vec![1.0, 2.0, 3.0, 4.0], vec![2, 1, 2], false)
            .unwrap();
        let out = s.functional_conv1d_dilated(x, w, None, 1, 1, 2, 2).unwrap();
        assert_eq!(s.tensor_shape(out).unwrap(), vec![1, 2, 6]);
        let want = [
            4.0, 7.0, 10.0, 13.0, 16.0, 5.0, 32.0, 57.0, 64.0, 71.0, 78.0, 33.0,
        ];
        let got = s.tensor_values(out).unwrap();
        for (g, w) in got.iter().zip(want.iter()) {
            assert!((g - w).abs() < 1e-9, "grp2dil2 got {got:?} want {want:?}");
        }
    }

    #[test]
    fn functional_conv1d_dilated_plain_matches_conv1d() {
        // dilation=1, groups=1 must equal the existing functional_conv1d.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let xv: Vec<f64> = (0..18).map(|i| (i as f64 - 9.0) * 0.1).collect();
        let wv: Vec<f64> = (0..6).map(|i| (i as f64 - 3.0) * 0.2).collect();
        let x = s.tensor_variable(xv.clone(), vec![1, 3, 6], false).unwrap();
        let w = s.tensor_variable(wv.clone(), vec![1, 3, 2], false).unwrap();
        let dil = s.functional_conv1d_dilated(x, w, None, 1, 0, 1, 1).unwrap();
        let x2 = s.tensor_variable(xv, vec![1, 3, 6], false).unwrap();
        let w2 = s.tensor_variable(wv, vec![1, 3, 2], false).unwrap();
        let plain = s.functional_conv1d(x2, w2, None, 1, 0).unwrap();
        assert_eq!(
            s.tensor_values(dil).unwrap(),
            s.tensor_values(plain).unwrap()
        );
    }

