    #[test]
    fn with_no_grad_region_multi_compacts_chain_bit_exact() {
        // A shared base feeding two heads -> two outputs (like a model returning a
        // tuple). with_no_grad_region_multi must return both bit-identical to the
        // un-wrapped computation AND collapse the whole region to exactly two
        // leaves (one per live output).
        let a_vals: Vec<f64> = (0..12).map(|i| (i as f64 - 6.0) * 0.1).collect();
        let w_vals: Vec<f64> = (0..8).map(|i| (i as f64 - 4.0) * 0.25).collect();
        let h1_vals: Vec<f64> = vec![0.5, -0.25];
        let h2_vals: Vec<f64> = vec![1.0, 0.5, -0.5, 0.25];

        let two_heads = |s: &mut FrankenTorchSession,
                         a: TensorNodeId,
                         w: TensorNodeId,
                         h1: TensorNodeId,
                         h2: TensorNodeId|
         -> Result<Vec<TensorNodeId>, AutogradError> {
            let base = s.tensor_matmul(a, w)?; // [4,3]@[3,2] -> [4,2]
            let base = s.tensor_relu(base)?;
            let head_a = s.tensor_add(base, h1)?; // + bias [2]
            let head_b = s.tensor_matmul(base, h2)?; // [4,2]@[2,2] -> [4,2]
            Ok(vec![head_a, head_b])
        };

        // Reference: run directly (no region), capture both outputs.
        let mut reference = FrankenTorchSession::new(ExecutionMode::Strict);
        let r_a = reference
            .tensor_variable(a_vals.clone(), vec![4, 3], false)
            .unwrap();
        let r_w = reference
            .tensor_variable(w_vals.clone(), vec![3, 2], false)
            .unwrap();
        let r_h1 = reference
            .tensor_variable(h1_vals.clone(), vec![2], false)
            .unwrap();
        let r_h2 = reference
            .tensor_variable(h2_vals.clone(), vec![2, 2], false)
            .unwrap();
        let r_out = two_heads(&mut reference, r_a, r_w, r_h1, r_h2).unwrap();
        let ref0 = reference.tensor_values(r_out[0]).unwrap();
        let ref1 = reference.tensor_values(r_out[1]).unwrap();

        // Region: same two heads inside with_no_grad_region_multi.
        let mut region = FrankenTorchSession::new(ExecutionMode::Strict);
        let g_a = region.tensor_variable(a_vals, vec![4, 3], false).unwrap();
        let g_w = region.tensor_variable(w_vals, vec![3, 2], false).unwrap();
        let g_h1 = region.tensor_variable(h1_vals, vec![2], false).unwrap();
        let g_h2 = region.tensor_variable(h2_vals, vec![2, 2], false).unwrap();
        let boundary = region.autograd_graph_node_count();
        let g_out = region
            .with_no_grad_region_multi(|s| two_heads(s, g_a, g_w, g_h1, g_h2))
            .unwrap();
        assert_eq!(g_out.len(), 2);
        // Two live outputs -> exactly two retained leaves.
        assert_eq!(region.autograd_graph_node_count(), boundary + 2);
        assert!(!region.tensor_requires_grad(g_out[0]).unwrap());
        assert!(!region.tensor_requires_grad(g_out[1]).unwrap());
        assert_eq!(region.tensor_values(g_out[0]).unwrap(), ref0);
        assert_eq!(region.tensor_values(g_out[1]).unwrap(), ref1);
    }

    #[test]
    fn with_no_grad_region_compacts_chain_bit_exact() {
        // A multi-op inference chain: matmul -> add bias -> relu -> matmul. Each op
        // leaves a retained tape node; with_no_grad_region must (a) return the
        // bit-identical result and (b) collapse the whole region to a single leaf.
        let a_vals: Vec<f64> = (0..12).map(|i| (i as f64 - 6.0) * 0.1).collect();
        let w1_vals: Vec<f64> = (0..8).map(|i| (i as f64 - 4.0) * 0.25).collect();
        let b1_vals: Vec<f64> = vec![0.5, -0.25];
        let w2_vals: Vec<f64> = (0..2).map(|i| (i as f64 + 1.0) * 0.5).collect();

        let chain = |s: &mut FrankenTorchSession,
                     a: TensorNodeId,
                     w1: TensorNodeId,
                     b1: TensorNodeId,
                     w2: TensorNodeId|
         -> Result<TensorNodeId, AutogradError> {
            let h = s.tensor_matmul(a, w1)?; // [4,3]@[3,2] -> [4,2]
            let h = s.tensor_add(h, b1)?; // + bias broadcast [2]
            let h = s.tensor_relu(h)?;
            s.tensor_matmul(h, w2)
        };

        // Reference: run the chain directly (no region), capture values.
        let mut reference = FrankenTorchSession::new(ExecutionMode::Strict);
        let r_a = reference
            .tensor_variable(a_vals.clone(), vec![4, 3], false)
            .unwrap();
        let r_w1 = reference
            .tensor_variable(w1_vals.clone(), vec![3, 2], false)
            .unwrap();
        let r_b1 = reference
            .tensor_variable(b1_vals.clone(), vec![2], false)
            .unwrap();
        let r_w2 = reference
            .tensor_variable(w2_vals.clone(), vec![2, 1], false)
            .unwrap();
        let r_out = chain(&mut reference, r_a, r_w1, r_b1, r_w2).unwrap();
        let ref_values = reference.tensor_values(r_out).unwrap();
        let ref_shape = reference.tensor_shape(r_out).unwrap();

        // Region: same chain inside with_no_grad_region — bit-identical, 1 node.
        let mut region = FrankenTorchSession::new(ExecutionMode::Strict);
        let g_a = region.tensor_variable(a_vals, vec![4, 3], false).unwrap();
        let g_w1 = region.tensor_variable(w1_vals, vec![3, 2], false).unwrap();
        let g_b1 = region.tensor_variable(b1_vals, vec![2], false).unwrap();
        let g_w2 = region.tensor_variable(w2_vals, vec![2, 1], false).unwrap();
        let boundary = region.autograd_graph_node_count();
        let g_out = region
            .with_no_grad_region(|s| chain(s, g_a, g_w1, g_b1, g_w2))
            .unwrap();
        assert_eq!(region.tensor_shape(g_out).unwrap(), ref_shape);
        assert!(!region.tensor_requires_grad(g_out).unwrap());
        // The whole chain collapsed to exactly one retained leaf.
        assert_eq!(region.autograd_graph_node_count(), boundary + 1);
        assert_eq!(region.tensor_values(g_out).unwrap(), ref_values);
    }

    #[test]
    fn functional_conv1d_nograd_compacts_intermediates_bit_exact() {
        let input_values: Vec<f64> = (0..30).map(|i| (i as f64 - 11.0) * 0.125).collect();
        let weight_values: Vec<f64> = (0..12).map(|i| (i as f64 - 5.0) * 0.2).collect();
        let bias_values = vec![0.25, -0.5];

        let mut compact = FrankenTorchSession::new(ExecutionMode::Strict);
        let compact_input = compact
            .tensor_variable(input_values.clone(), vec![2, 3, 5], false)
            .unwrap();
        let compact_weight = compact
            .tensor_variable(weight_values.clone(), vec![2, 3, 2], false)
            .unwrap();
        let compact_bias = compact
            .tensor_variable(bias_values.clone(), vec![2], false)
            .unwrap();
        let boundary = compact.autograd_graph_node_count();
        let compact_out = compact
            .functional_conv1d(compact_input, compact_weight, Some(compact_bias), 1, 1)
            .unwrap();
        let compact_values = compact.tensor_values(compact_out).unwrap();
        assert_eq!(compact.tensor_shape(compact_out).unwrap(), vec![2, 2, 6]);
        assert!(!compact.tensor_requires_grad(compact_out).unwrap());
        assert_eq!(compact.autograd_graph_node_count(), boundary + 1);

        let mut reference = FrankenTorchSession::new(ExecutionMode::Strict);
        let reference_input = reference
            .tensor_variable(input_values, vec![2, 3, 5], true)
            .unwrap();
        let reference_weight = reference
            .tensor_variable(weight_values, vec![2, 3, 2], true)
            .unwrap();
        let reference_bias = reference
            .tensor_variable(bias_values, vec![2], true)
            .unwrap();
        let reference_out = reference
            .functional_conv1d(
                reference_input,
                reference_weight,
                Some(reference_bias),
                1,
                1,
            )
            .unwrap();
        assert!(reference.tensor_requires_grad(reference_out).unwrap());
        assert_eq!(
            compact_values,
            reference.tensor_values(reference_out).unwrap()
        );
    }

    #[test]
    fn functional_conv_unbatched_input_matches_torch() {
        // torch F.conv{1,2,3}d accept an unbatched input ([C_in, ...]) and return
        // an unbatched output ([C_out, ...]) — equivalent to unsqueeze(0) -> conv
        // -> squeeze(0). Goldens from torch 2.12 (covers the plain, grouped, and
        // dilated paths of each rank).
        let r = |v: &[f64]| v.to_vec();
        let chk = |s: &mut FrankenTorchSession, out, want_shape: Vec<usize>, want: &[f64]| {
            assert_eq!(s.tensor_shape(out).unwrap(), want_shape, "shape");
            let got = s.tensor_values(out).unwrap();
            assert_eq!(got.len(), want.len(), "len");
            for (i, (g, w)) in got.iter().zip(want).enumerate() {
                assert!((g - w).abs() <= 1e-9, "[{i}]: {g} vs torch {w}");
            }
        };

        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        // conv1d: input [C=2, L=3], weight [2,2,2]
        let x = s
            .tensor_variable((1..=6).map(|v| v as f64).collect(), vec![2, 3], false)
            .unwrap();
        let w = s
            .tensor_variable((1..=8).map(|v| v as f64).collect(), vec![2, 2, 2], false)
            .unwrap();
        let o = s.functional_conv1d(x, w, None, 1, 0).unwrap();
        chk(&mut s, o, vec![2, 2], &r(&[37.0, 47.0, 85.0, 111.0]));

        // conv1d dilated=2: input [C=2, L=5], weight [2,2,2]
        let x = s
            .tensor_variable((1..=10).map(|v| v as f64).collect(), vec![2, 5], false)
            .unwrap();
        let w = s
            .tensor_variable((1..=8).map(|v| v as f64).collect(), vec![2, 2, 2], false)
            .unwrap();
        let o = s.functional_conv1d_dilated(x, w, None, 1, 0, 2, 1).unwrap();
        chk(
            &mut s,
            o,
            vec![2, 3],
            &r(&[57.0, 67.0, 77.0, 129.0, 155.0, 181.0]),
        );

        // conv2d: input [C=2, H=3, W=3], weight [2,2,2,2]
        let x = s
            .tensor_variable((1..=18).map(|v| v as f64).collect(), vec![2, 3, 3], false)
            .unwrap();
        let w = s
            .tensor_variable(
                (1..=16).map(|v| v as f64).collect(),
                vec![2, 2, 2, 2],
                false,
            )
            .unwrap();
        let o = s.functional_conv2d(x, w, None, (1, 1), (0, 0)).unwrap();
        chk(
            &mut s,
            o,
            vec![2, 2, 2],
            &r(&[356.0, 392.0, 464.0, 500.0, 836.0, 936.0, 1136.0, 1236.0]),
        );

        // conv2d grouped=2: input [C=2, H=4, W=4], weight [2,1,2,2]
        let x = s
            .tensor_variable((1..=32).map(|v| v as f64).collect(), vec![2, 4, 4], false)
            .unwrap();
        let w = s
            .tensor_variable((1..=8).map(|v| v as f64).collect(), vec![2, 1, 2, 2], false)
            .unwrap();
        let o = s
            .functional_conv2d_grouped(x, w, None, (1, 1), (0, 0), 2)
            .unwrap();
        chk(
            &mut s,
            o,
            vec![2, 3, 3],
            &r(&[
                44.0, 54.0, 64.0, 84.0, 94.0, 104.0, 124.0, 134.0, 144.0, 516.0, 542.0, 568.0,
                620.0, 646.0, 672.0, 724.0, 750.0, 776.0,
            ]),
        );

        // conv2d dilated=2 (routes through grouped -> conv2d): [C=2, H=5, W=5]
        let x = s
            .tensor_variable((1..=50).map(|v| v as f64).collect(), vec![2, 5, 5], false)
            .unwrap();
        let w = s
            .tensor_variable(
                (1..=16).map(|v| v as f64).collect(),
                vec![2, 2, 2, 2],
                false,
            )
            .unwrap();
        let o = s
            .functional_conv2d_dilated(x, w, None, (1, 1), (0, 0), (2, 2), 1)
            .unwrap();
        chk(
            &mut s,
            o,
            vec![2, 3, 3],
            &r(&[
                946.0, 982.0, 1018.0, 1126.0, 1162.0, 1198.0, 1306.0, 1342.0, 1378.0, 2194.0,
                2294.0, 2394.0, 2694.0, 2794.0, 2894.0, 3194.0, 3294.0, 3394.0,
            ]),
        );

        // conv3d: input [C=2, D=3, H=3, W=3], weight [2,2,2,2,2]
        let x = s
            .tensor_variable(
                (1..=54).map(|v| v as f64).collect(),
                vec![2, 3, 3, 3],
                false,
            )
            .unwrap();
        let w = s
            .tensor_variable(
                (1..=32).map(|v| v as f64).collect(),
                vec![2, 2, 2, 2, 2],
                false,
            )
            .unwrap();
        let o = s
            .functional_conv3d(x, w, None, (1, 1, 1), (0, 0, 0))
            .unwrap();
        chk(
            &mut s,
            o,
            vec![2, 2, 2, 2],
            &r(&[
                3892.0, 4028.0, 4300.0, 4436.0, 5116.0, 5252.0, 5524.0, 5660.0, 9268.0, 9660.0,
                10444.0, 10836.0, 12796.0, 13188.0, 13972.0, 14364.0,
            ]),
        );
    }

    #[test]
