    #[test]
    fn functional_conv2d_grouped_depthwise_f32_grad_matches_f64_path() {
        // The f32 depthwise GRAD fast path (via the f32-output custom op,
        // frankentorch-48w0b) must (a) produce an F32 output (dtype parity) and
        // (b) yield gradients matching the trusted f64 grad path within f32
        // precision. groups == channels, with padding + bias.
        let (n, c, ih, iw, k) = (1usize, 3, 5, 5, 3);
        let xv: Vec<f64> = (0..n * c * ih * iw)
            .map(|i| (i % 23) as f64 * 0.1 - 1.0)
            .collect();
        let wv: Vec<f64> = (0..c * k * k)
            .map(|i| (i % 17) as f64 * 0.1 - 0.7)
            .collect();
        let bvv: Vec<f64> = (0..c).map(|i| i as f64 * 0.2 - 0.3).collect();
        // f64 reference grads.
        let (gx64, gw64) = {
            let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
            let xt = s
                .tensor_variable(xv.clone(), vec![n, c, ih, iw], true)
                .unwrap();
            let wt = s
                .tensor_variable(wv.clone(), vec![c, 1, k, k], true)
                .unwrap();
            let bt = s.tensor_variable(bvv.clone(), vec![c], true).unwrap();
            let o = s
                .functional_conv2d_grouped(xt, wt, Some(bt), (1, 1), (1, 1), c)
                .unwrap();
            let sm = s.tensor_sum(o).unwrap();
            s.tensor_backward(sm).unwrap();
            (
                s.tensor_grad(xt).unwrap().unwrap(),
                s.tensor_grad(wt).unwrap().unwrap(),
            )
        };
        // f32 fast-path grads + output dtype.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let xt = s
            .tensor_variable_f32(
                xv.iter().map(|&v| v as f32).collect(),
                vec![n, c, ih, iw],
                true,
            )
            .unwrap();
        let wt = s
            .tensor_variable_f32(
                wv.iter().map(|&v| v as f32).collect(),
                vec![c, 1, k, k],
                true,
            )
            .unwrap();
        let bt = s
            .tensor_variable_f32(bvv.iter().map(|&v| v as f32).collect(), vec![c], true)
            .unwrap();
        let o = s
            .functional_conv2d_grouped(xt, wt, Some(bt), (1, 1), (1, 1), c)
            .unwrap();
        assert_eq!(
            s.tensor_dtype(o).unwrap(),
            DType::F32,
            "f32 depthwise output must be F32"
        );
        let sm = s.tensor_sum(o).unwrap();
        s.tensor_backward(sm).unwrap();
        let gx32 = s.tensor_grad(xt).unwrap().unwrap();
        let gw32 = s.tensor_grad(wt).unwrap().unwrap();
        for (a, b) in gx32.iter().zip(gx64.iter()) {
            assert!((a - b).abs() < 1e-3, "dx f32 {a} vs f64 {b}");
        }
        for (a, b) in gw32.iter().zip(gw64.iter()) {
            assert!((a - b).abs() < 1e-3, "dw f32 {a} vs f64 {b}");
        }
    }

    #[test]
    fn functional_conv2d_grouped_depthwise_grad_matches_finite_difference() {
        // The f64 depthwise GRAD fast path (custom op depthwise_conv2d_forward/
        // backward) gradients must match central finite differences of
        // sum(conv). groups == channels, with padding + bias.
        let (n, c, ih, iw, k) = (1usize, 3, 5, 5, 3);
        let xv: Vec<f64> = (0..n * c * ih * iw)
            .map(|i| (i % 23) as f64 * 0.1 - 1.0)
            .collect();
        let wv: Vec<f64> = (0..c * k * k)
            .map(|i| (i % 17) as f64 * 0.1 - 0.7)
            .collect();
        let bv: Vec<f64> = (0..c).map(|i| i as f64 * 0.2 - 0.3).collect();
        let loss = |x: &[f64], w: &[f64], b: &[f64]| -> f64 {
            let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
            let xt = s
                .tensor_variable(x.to_vec(), vec![n, c, ih, iw], false)
                .unwrap();
            let wt = s
                .tensor_variable(w.to_vec(), vec![c, 1, k, k], false)
                .unwrap();
            let bt = s.tensor_variable(b.to_vec(), vec![c], false).unwrap();
            let o = s
                .functional_conv2d_grouped(xt, wt, Some(bt), (1, 1), (1, 1), c)
                .unwrap();
            let sm = s.tensor_sum(o).unwrap();
            s.tensor_values(sm).unwrap()[0]
        };
        // Analytic grads via the fast path.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let xt = s
            .tensor_variable(xv.clone(), vec![n, c, ih, iw], true)
            .unwrap();
        let wt = s
            .tensor_variable(wv.clone(), vec![c, 1, k, k], true)
            .unwrap();
        let bt = s.tensor_variable(bv.clone(), vec![c], true).unwrap();
        let o = s
            .functional_conv2d_grouped(xt, wt, Some(bt), (1, 1), (1, 1), c)
            .unwrap();
        let sm = s.tensor_sum(o).unwrap();
        s.tensor_backward(sm).unwrap();
        let gx = s.tensor_grad(xt).unwrap().unwrap();
        let gw = s.tensor_grad(wt).unwrap().unwrap();
        let eps = 1e-6;
        // Check a few input grads via central difference.
        for &i in &[0usize, 7, 37, xv.len() - 1] {
            let mut xp = xv.clone();
            xp[i] += eps;
            let mut xm = xv.clone();
            xm[i] -= eps;
            let fd = (loss(&xp, &wv, &bv) - loss(&xm, &wv, &bv)) / (2.0 * eps);
            assert!(
                (gx[i] - fd).abs() < 1e-4,
                "dx[{i}] grad {} vs fd {fd}",
                gx[i]
            );
        }
        // Check a few weight grads.
        for &i in &[0usize, 5, wv.len() - 1] {
            let mut wp = wv.clone();
            wp[i] += eps;
            let mut wm = wv.clone();
            wm[i] -= eps;
            let fd = (loss(&xv, &wp, &bv) - loss(&xv, &wm, &bv)) / (2.0 * eps);
            assert!(
                (gw[i] - fd).abs() < 1e-4,
                "dw[{i}] grad {} vs fd {fd}",
                gw[i]
            );
        }
    }

    #[test]
    fn functional_conv2d_grouped_grad_flows_to_all_channels() {
        // Backward through the narrow/cat composition must reach every input and
        // weight element (grouped conv is still fully differentiable).
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let xv: Vec<f64> = (1..=32).map(|v| v as f64 * 0.1).collect();
        let wv: Vec<f64> = (1..=32).map(|v| v as f64 * 0.1).collect();
        let x = s.tensor_variable(xv, vec![1, 4, 2, 4], true).unwrap();
        let w = s.tensor_variable(wv, vec![4, 2, 2, 2], true).unwrap();
        let out = s
            .functional_conv2d_grouped(x, w, None, (1, 1), (0, 0), 2)
            .unwrap();
        let loss = s.tensor_sum(out).unwrap();
        s.tensor_backward(loss).unwrap();
        let gx = s.tensor_grad(x).unwrap().unwrap();
        let gw = s.tensor_grad(w).unwrap().unwrap();
        assert!(
            gx.iter().all(|&g| g != 0.0),
            "all input grads nonzero: {gx:?}"
        );
        assert!(
            gw.iter().all(|&g| g != 0.0),
            "all weight grads nonzero: {gw:?}"
        );
    }

