    #[test]
    fn functional_conv2d_no_grad_fast_path_matches_composed_path_bit_exact() {
        let input_shape = vec![2, 3, 5, 6];
        let weight_shape = vec![4, 3, 3, 2];
        let bias_shape = vec![4];
        let input_values: Vec<f64> = (0..180)
            .map(|idx| ((idx * 17 + 3) % 257) as f64 * 0.01 - 1.0)
            .collect();
        let weight_values: Vec<f64> = (0..72)
            .map(|idx| ((idx * 19 + 11) % 131) as f64 * 0.005 - 0.3)
            .collect();
        let bias_values: Vec<f64> = (0..4).map(|idx| idx as f64 * 0.25 - 0.125).collect();

        let mut fast = FrankenTorchSession::new(ExecutionMode::Strict);
        let fast_input = fast
            .tensor_variable(input_values.clone(), input_shape.clone(), false)
            .unwrap();
        let fast_weight = fast
            .tensor_variable(weight_values.clone(), weight_shape.clone(), false)
            .unwrap();
        let fast_bias = fast
            .tensor_variable(bias_values.clone(), bias_shape.clone(), false)
            .unwrap();
        let fast_out = fast
            .functional_conv2d(fast_input, fast_weight, Some(fast_bias), (2, 1), (1, 2))
            .unwrap();

        let mut composed = FrankenTorchSession::new(ExecutionMode::Strict);
        let composed_input = composed
            .tensor_variable(input_values.clone(), input_shape, true)
            .unwrap();
        let composed_weight = composed
            .tensor_variable(weight_values, weight_shape, false)
            .unwrap();
        let composed_bias = composed
            .tensor_variable(bias_values, bias_shape, false)
            .unwrap();
        let composed_out = composed
            .functional_conv2d(
                composed_input,
                composed_weight,
                Some(composed_bias),
                (2, 1),
                (1, 2),
            )
            .unwrap();

        assert_eq!(fast.tensor_shape(fast_out).unwrap(), vec![2, 4, 3, 9]);
        assert_eq!(
            fast.tensor_shape(fast_out).unwrap(),
            composed.tensor_shape(composed_out).unwrap()
        );
        let fast_values = fast.tensor_values(fast_out).unwrap();
        let composed_values = composed.tensor_values(composed_out).unwrap();
        assert_eq!(fast_values.len(), composed_values.len());
        let mut out_acc = 0xcbf2_9ce4_8422_2325u64;
        for (idx, (&got, &expected)) in fast_values.iter().zip(composed_values.iter()).enumerate() {
            assert_eq!(
                got.to_bits(),
                expected.to_bits(),
                "conv2d fused/composed output @{idx}"
            );
            out_acc = (out_acc ^ got.to_bits()).wrapping_mul(0x0000_0100_0000_01b3);
        }

        let loss = composed.tensor_sum(composed_out).unwrap();
        let report = composed.tensor_backward(loss).unwrap();
        let input_grad = composed
            .tensor_gradient(&report, composed_input)
            .expect("composed conv2d input grad present");
        assert_eq!(input_grad.len(), input_values.len());
        let mut grad_acc = 0xcbf2_9ce4_8422_2325u64;
        for grad in input_grad {
            grad_acc = (grad_acc ^ grad.to_bits()).wrapping_mul(0x0000_0100_0000_01b3);
        }

        assert_eq!(out_acc, 0x1c8a_815a_c09b_13df);
        assert_eq!(grad_acc, 0x0b15_7cdb_2c35_b4bd);
    }

    #[test]
    fn functional_conv2d_f32_no_grad_fast_path_matches_composed_path() {
        // Isomorphism proof for the fused f32 no-grad conv2d
        // (ft_kernel_cpu::conv2d_forward_f32): it must match the composed op-graph
        // path (im2col + matmul, forced via requires_grad=true) — same im2col panel
        // and the same sgemm (sgemm_bt == sgemm on the materialised weight^T).
        let input_shape = vec![2usize, 3, 5, 6];
        let weight_shape = vec![4usize, 3, 3, 2];
        let bias_shape = vec![4usize];
        let input_values: Vec<f32> = (0..180)
            .map(|idx| ((idx * 17 + 3) % 257) as f32 * 0.01 - 1.0)
            .collect();
        let weight_values: Vec<f32> = (0..72)
            .map(|idx| ((idx * 19 + 11) % 131) as f32 * 0.005 - 0.3)
            .collect();
        let bias_values: Vec<f32> = (0..4).map(|idx| idx as f32 * 0.25 - 0.125).collect();

        let mut fast = FrankenTorchSession::new(ExecutionMode::Strict);
        let fi = fast
            .tensor_variable_f32(input_values.clone(), input_shape.clone(), false)
            .unwrap();
        let fw = fast
            .tensor_variable_f32(weight_values.clone(), weight_shape.clone(), false)
            .unwrap();
        let fb = fast
            .tensor_variable_f32(bias_values.clone(), bias_shape.clone(), false)
            .unwrap();
        let fast_out = fast
            .functional_conv2d(fi, fw, Some(fb), (2, 1), (1, 2))
            .unwrap();

        let mut comp = FrankenTorchSession::new(ExecutionMode::Strict);
        let ci = comp
            .tensor_variable_f32(input_values, input_shape, true)
            .unwrap();
        let cw = comp
            .tensor_variable_f32(weight_values, weight_shape, false)
            .unwrap();
        let cb = comp
            .tensor_variable_f32(bias_values, bias_shape, false)
            .unwrap();
        let comp_out = comp
            .functional_conv2d(ci, cw, Some(cb), (2, 1), (1, 2))
            .unwrap();

        assert_eq!(fast.tensor_shape(fast_out).unwrap(), vec![2, 4, 3, 9]);
        assert_eq!(
            fast.tensor_shape(fast_out).unwrap(),
            comp.tensor_shape(comp_out).unwrap()
        );
        let fv = fast.tensor_values_f32(fast_out).unwrap();
        let cv = comp.tensor_values_f32(comp_out).unwrap();
        assert_eq!(fv.len(), cv.len());
        for (idx, (&g, &e)) in fv.iter().zip(cv.iter()).enumerate() {
            assert_eq!(
                g.to_bits(),
                e.to_bits(),
                "conv2d f32 fused/composed @{idx}: {g} vs {e}"
            );
        }
    }

    #[test]
    fn functional_avg_pool1d_basic() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let input = s
            .tensor_variable(vec![1.0, 3.0, 5.0, 7.0], vec![1, 1, 4], false)
            .unwrap();
        let out = s.functional_avg_pool1d(input, 2, 2).unwrap();
        let shape = s.tensor_shape(out).unwrap();
        let vals = s.tensor_values(out).unwrap();
        assert_eq!(shape, vec![1, 1, 2]);
        assert_eq!(vals, vec![2.0, 6.0]);
    }

    #[test]
    fn functional_avg_pool1d_fused_matches_reshape_2d_forward_and_backward_bits() {
        let values: Vec<f64> = (0..2 * 3 * 9)
            .map(|i| ((i * 37 + 11) % 97) as f64 * 0.03125 - 1.5)
            .collect();

        let mut direct = FrankenTorchSession::new(ExecutionMode::Strict);
        let x_direct = direct
            .tensor_variable(values.clone(), vec![2, 3, 9], true)
            .unwrap();
        let out_direct = direct.functional_avg_pool1d(x_direct, 3, 2).unwrap();
        let loss_direct = direct.tensor_sum(out_direct).unwrap();
        let report_direct = direct.tensor_backward(loss_direct).unwrap();

        let mut via_2d = FrankenTorchSession::new(ExecutionMode::Strict);
        let x_2d = via_2d.tensor_variable(values, vec![2, 3, 9], true).unwrap();
        let x_4d = via_2d.tensor_reshape(x_2d, vec![2, 3, 1, 9]).unwrap();
        let out_4d = via_2d
            .functional_avg_pool2d(x_4d, (1, 3), (1, 2), (0, 0), false, true)
            .unwrap();
        let out_2d = via_2d.tensor_reshape(out_4d, vec![2, 3, 4]).unwrap();
        let loss_2d = via_2d.tensor_sum(out_2d).unwrap();
        let report_2d = via_2d.tensor_backward(loss_2d).unwrap();

        let direct_values = direct.tensor_values(out_direct).unwrap();
        let via_2d_values = via_2d.tensor_values(out_2d).unwrap();
        assert_eq!(direct_values.len(), via_2d_values.len());
        for (index, (&got, &want)) in direct_values.iter().zip(via_2d_values.iter()).enumerate() {
            assert_eq!(
                got.to_bits(),
                want.to_bits(),
                "avg_pool1d forward bit mismatch at index {index}"
            );
        }

        let direct_grad = direct.tensor_gradient(&report_direct, x_direct).unwrap();
        let via_2d_grad = via_2d.tensor_gradient(&report_2d, x_2d).unwrap();
        assert_eq!(direct_grad.len(), via_2d_grad.len());
        for (index, (&got, &want)) in direct_grad.iter().zip(via_2d_grad.iter()).enumerate() {
            assert_eq!(
                got.to_bits(),
                want.to_bits(),
                "avg_pool1d backward bit mismatch at index {index}"
            );
        }
    }

    /// The `tensor_sum(avg_pool1d(x))` shortcut (`frankentorch-o4782`) must be
    /// bit-identical to the unfused compose it replaces.
    ///
    /// The reference arm defeats the shortcut by retaining grad on the pooled
    /// tensor, which is the documented decline condition — that is the only way
    /// to still reach the genuine unfused path from this API now that the
    /// shortcut is registered.
    #[test]
    fn avg_pool1d_sum_shortcut_matches_unfused_compose_bits() {
        let values: Vec<f64> = (0..2 * 3 * 17)
            .map(|i| ((i * 43 + 17) % 181) as f64 * 0.015625 - 1.25)
            .collect();

        let mut unfused = FrankenTorchSession::new(ExecutionMode::Strict);
        let x_unfused = unfused
            .tensor_variable(values.clone(), vec![2, 3, 17], true)
            .unwrap();
        let pooled_unfused = unfused.functional_avg_pool1d(x_unfused, 5, 3).unwrap();
        unfused.tensor_retain_grad(pooled_unfused).unwrap();
        let loss_unfused = unfused.tensor_sum(pooled_unfused).unwrap();
        let out_unfused = unfused.tensor_values(loss_unfused).unwrap();
        let report_unfused = unfused.tensor_backward(loss_unfused).unwrap();
        let grad_unfused = unfused
            .tensor_gradient(&report_unfused, x_unfused)
            .expect("unfused input grad");

        let mut shortcut = FrankenTorchSession::new(ExecutionMode::Strict);
        let x_shortcut = shortcut
            .tensor_variable(values, vec![2, 3, 17], true)
            .unwrap();
        let pooled_shortcut = shortcut.functional_avg_pool1d(x_shortcut, 5, 3).unwrap();
        let loss_shortcut = shortcut.tensor_sum(pooled_shortcut).unwrap();
        let out_shortcut = shortcut.tensor_values(loss_shortcut).unwrap();
        let report_shortcut = shortcut.tensor_backward(loss_shortcut).unwrap();
        let grad_shortcut = shortcut
            .tensor_gradient(&report_shortcut, x_shortcut)
            .expect("shortcut input grad");

        assert_eq!(out_shortcut[0].to_bits(), out_unfused[0].to_bits());
        for (index, (&got, &want)) in grad_shortcut.iter().zip(grad_unfused.iter()).enumerate() {
            assert_eq!(
                got.to_bits(),
                want.to_bits(),
                "avg_pool1d sum shortcut input grad[{index}]"
            );
        }
    }

    /// NEGATIVE CASE: a shortcut that always fired would skip producing the
    /// pooled tensor's own gradient, which `retain_grad` makes observable. An
    /// implementation missing the decline check passes the bit-equality test
    /// above and fails this one.
    #[test]
    fn avg_pool1d_sum_shortcut_declines_when_pooled_retains_grad() {
        let values: Vec<f64> = (0..2 * 3 * 17)
            .map(|i| ((i * 43 + 17) % 181) as f64 * 0.015625 - 1.25)
            .collect();

        let mut session = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = session
            .tensor_variable(values, vec![2, 3, 17], true)
            .unwrap();
        let pooled = session.functional_avg_pool1d(x, 5, 3).unwrap();
        session.tensor_retain_grad(pooled).unwrap();
        let loss = session.tensor_sum(pooled).unwrap();
        let report = session.tensor_backward(loss).unwrap();

        let pooled_grad = session
            .tensor_gradient(&report, pooled)
            .expect("retained pooled grad must be produced, not skipped by the shortcut");
        assert_eq!(pooled_grad.len(), 2 * 3 * 5);
        for (index, &value) in pooled_grad.iter().enumerate() {
            assert!(
                (value - 1.0).abs() < 1e-12,
                "d(sum)/d(pooled)[{index}] must be 1, got {value}"
            );
        }
    }

    #[test]
    fn functional_avg_pool1d_sum_matches_pool_sum_backward_bits() {
        let values: Vec<f64> = (0..2 * 3 * 17)
            .map(|i| ((i * 43 + 17) % 181) as f64 * 0.015625 - 1.25)
            .collect();

        let mut materialized = FrankenTorchSession::new(ExecutionMode::Strict);
        let x_materialized = materialized
            .tensor_variable(values.clone(), vec![2, 3, 17], true)
            .unwrap();
        let pooled = materialized
            .functional_avg_pool1d(x_materialized, 5, 3)
            .unwrap();
        let loss_materialized = materialized.tensor_sum(pooled).unwrap();
        let out_materialized = materialized.tensor_values(loss_materialized).unwrap();
        let report_materialized = materialized.tensor_backward(loss_materialized).unwrap();

        let mut fused = FrankenTorchSession::new(ExecutionMode::Strict);
        let x_fused = fused.tensor_variable(values, vec![2, 3, 17], true).unwrap();
        let loss_fused = fused.functional_avg_pool1d_sum(x_fused, 5, 3).unwrap();
        let out_fused = fused.tensor_values(loss_fused).unwrap();
        let report_fused = fused.tensor_backward(loss_fused).unwrap();

        assert_eq!(out_fused[0].to_bits(), out_materialized[0].to_bits());

        let grad_materialized = materialized
            .tensor_gradient(&report_materialized, x_materialized)
            .expect("materialized avg_pool1d input grad");
        let grad_fused = fused
            .tensor_gradient(&report_fused, x_fused)
            .expect("fused avg_pool1d input grad");
        for (index, (&got, &want)) in grad_fused.iter().zip(grad_materialized.iter()).enumerate() {
            assert_eq!(
                got.to_bits(),
                want.to_bits(),
                "fused avg_pool1d sum input grad[{index}]"
            );
        }
    }

