    #[test]
    fn sdpa_causal_mask() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        // With causal mask, position 0 only attends to itself
        let q = s
            .tensor_variable(vec![1.0, 0.0, 0.0, 1.0], vec![1, 2, 2], false)
            .unwrap();
        let k = s
            .tensor_variable(vec![1.0, 0.0, 0.0, 1.0], vec![1, 2, 2], false)
            .unwrap();
        let v = s
            .tensor_variable(vec![10.0, 20.0, 30.0, 40.0], vec![1, 2, 2], false)
            .unwrap();
        let out = s
            .scaled_dot_product_attention(q, k, v, None, 0.0, true)
            .unwrap();
        let vals = s.tensor_values(out).unwrap();
        // Position 0 with causal mask: only sees position 0
        // softmax(score[0,0]) = 1.0, so output = V[0] = [10, 20]
        assert!((vals[0] - 10.0).abs() < 1e-6);
        assert!((vals[1] - 20.0).abs() < 1e-6);
    }

    #[test]
    fn tensor_sdpa_fused_matches_validated_and_finite_diff() {
        // tensor_scaled_dot_product_attention's new fused fast paths: with the
        // default scale it must equal the already-validated
        // scaled_dot_product_attention (same flash kernel); with a custom scale its
        // grads (dQ/dK/dV) must match central finite differences.
        let shape = vec![6usize, 5, 4]; // [batch_heads, seq, d]
        let n: usize = shape.iter().product();
        let qv: Vec<f64> = (0..n).map(|i| ((i % 7) as f64 - 3.0) * 0.2).collect();
        let kv: Vec<f64> = (0..n).map(|i| ((i % 5) as f64 - 2.0) * 0.3).collect();
        let vv: Vec<f64> = (0..n).map(|i| ((i % 9) as f64 - 4.0) * 0.15).collect();

        // Default scale == the validated scaled_dot_product_attention.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let q = s.tensor_variable(qv.clone(), shape.clone(), false).unwrap();
        let k = s.tensor_variable(kv.clone(), shape.clone(), false).unwrap();
        let vt = s.tensor_variable(vv.clone(), shape.clone(), false).unwrap();
        let a = s
            .tensor_scaled_dot_product_attention(q, k, vt, None, false, None)
            .unwrap();
        let b = s
            .scaled_dot_product_attention(q, k, vt, None, 0.0, false)
            .unwrap();
        let (av, bv) = (s.tensor_values(a).unwrap(), s.tensor_values(b).unwrap());
        for (x, y) in av.iter().zip(bv.iter()) {
            assert!(
                (x - y).abs() <= 1e-12,
                "tensor_sdpa default != scaled_dot_product_attention"
            );
        }

        // Custom-scale grad vs finite differences.
        let cs = Some(0.37_f64);
        let mut s2 = FrankenTorchSession::new(ExecutionMode::Strict);
        let q2 = s2.tensor_variable(qv.clone(), shape.clone(), true).unwrap();
        let k2 = s2.tensor_variable(kv.clone(), shape.clone(), true).unwrap();
        let v2 = s2.tensor_variable(vv.clone(), shape.clone(), true).unwrap();
        let o = s2
            .tensor_scaled_dot_product_attention(q2, k2, v2, None, false, cs)
            .unwrap();
        let loss = s2.tensor_sum(o).unwrap();
        s2.tensor_backward(loss).unwrap();
        let gq = s2.tensor_grad(q2).unwrap().unwrap();
        let gk = s2.tensor_grad(k2).unwrap().unwrap();
        let gv = s2.tensor_grad(v2).unwrap().unwrap();
        let loss_fn = |qs: &[f64], ks: &[f64], vs: &[f64]| -> f64 {
            let mut s3 = FrankenTorchSession::new(ExecutionMode::Strict);
            let qi = s3
                .tensor_variable(qs.to_vec(), shape.clone(), false)
                .unwrap();
            let ki = s3
                .tensor_variable(ks.to_vec(), shape.clone(), false)
                .unwrap();
            let vi = s3
                .tensor_variable(vs.to_vec(), shape.clone(), false)
                .unwrap();
            let oo = s3
                .tensor_scaled_dot_product_attention(qi, ki, vi, None, false, cs)
                .unwrap();
            s3.tensor_values(oo).unwrap().iter().sum()
        };
        let h = 1e-6;
        let chk = |g: &[f64], which: u8| {
            for i in 0..n {
                let mut up = (qv.clone(), kv.clone(), vv.clone());
                let mut dn = (qv.clone(), kv.clone(), vv.clone());
                match which {
                    0 => {
                        up.0[i] += h;
                        dn.0[i] -= h;
                    }
                    1 => {
                        up.1[i] += h;
                        dn.1[i] -= h;
                    }
                    _ => {
                        up.2[i] += h;
                        dn.2[i] -= h;
                    }
                }
                let fd = (loss_fn(&up.0, &up.1, &up.2) - loss_fn(&dn.0, &dn.1, &dn.2)) / (2.0 * h);
                assert!(
                    (g[i] - fd).abs() <= 1e-5 + 1e-4 * fd.abs(),
                    "grad{which}[{i}]: {} vs {fd}",
                    g[i]
                );
            }
        };
        chk(&gq, 0);
        chk(&gk, 1);
        chk(&gv, 2);
    }

    #[test]
    fn sdpa_fused_matches_reference_within_tolerance() {
        // The fused no-grad SDPA kernel must match the op-graph reference
        // (bmm + scale + softmax + bmm) to tolerance. The reference is obtained by
        // marking inputs requires_grad, which routes around the fused fast path.
        let shape = vec![4usize, 8, 4]; // num_bh4, seq8, d_k4 (bmm reference is 3-D)
        let n: usize = shape.iter().product();
        let qv: Vec<f64> = (0..n).map(|i| ((i % 7) as f64 - 3.0) * 0.2).collect();
        let kv: Vec<f64> = (0..n).map(|i| ((i % 5) as f64 - 2.0) * 0.3).collect();
        let vv: Vec<f64> = (0..n).map(|i| ((i % 9) as f64 - 4.0) * 0.15).collect();
        for &causal in &[false, true] {
            let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
            let q = s.tensor_variable(qv.clone(), shape.clone(), false).unwrap();
            let k = s.tensor_variable(kv.clone(), shape.clone(), false).unwrap();
            let vt = s.tensor_variable(vv.clone(), shape.clone(), false).unwrap();
            let out = s
                .scaled_dot_product_attention(q, k, vt, None, 0.0, causal)
                .unwrap();
            let fused = s.tensor_values(out).unwrap();

            let mut s2 = FrankenTorchSession::new(ExecutionMode::Strict);
            let q2 = s2.tensor_variable(qv.clone(), shape.clone(), true).unwrap();
            let k2 = s2.tensor_variable(kv.clone(), shape.clone(), true).unwrap();
            let v2 = s2.tensor_variable(vv.clone(), shape.clone(), true).unwrap();
            let out2 = s2
                .scaled_dot_product_attention(q2, k2, v2, None, 0.0, causal)
                .unwrap();
            let reference = s2.tensor_values(out2).unwrap();

            assert_eq!(fused.len(), reference.len());
            for (i, (a, b)) in fused.iter().zip(reference.iter()).enumerate() {
                assert!(
                    (a - b).abs() <= 1e-12 + 1e-10 * b.abs(),
                    "causal={causal} [{i}]: fused {a} vs reference {b}"
                );
            }
        }
    }

    #[test]
    fn sdpa_f32_grad_matches_f64_path() {
        // The f32 SDPA GRAD fast path (f32-output custom op, 48w0b) must produce an
        // F32 output and dq/dk/dv matching the trusted f64 grad path within f32
        // precision.
        let shape = vec![6usize, 8, 4]; // [num_bh, seq, d]
        let n: usize = shape.iter().product();
        let qv: Vec<f64> = (0..n).map(|i| ((i % 7) as f64 - 3.0) * 0.2).collect();
        let kv: Vec<f64> = (0..n).map(|i| ((i % 5) as f64 - 2.0) * 0.3).collect();
        let vv: Vec<f64> = (0..n).map(|i| ((i % 9) as f64 - 4.0) * 0.15).collect();
        let grads64 = |causal: bool| {
            let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
            let q = s.tensor_variable(qv.clone(), shape.clone(), true).unwrap();
            let k = s.tensor_variable(kv.clone(), shape.clone(), true).unwrap();
            let v = s.tensor_variable(vv.clone(), shape.clone(), true).unwrap();
            let o = s
                .scaled_dot_product_attention(q, k, v, None, 0.0, causal)
                .unwrap();
            let l = s.tensor_sum(o).unwrap();
            s.tensor_backward(l).unwrap();
            (
                s.tensor_grad(q).unwrap().unwrap(),
                s.tensor_grad(k).unwrap().unwrap(),
                s.tensor_grad(v).unwrap().unwrap(),
            )
        };
        for &causal in &[false, true] {
            let (gq64, gk64, gv64) = grads64(causal);
            let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
            let q = s
                .tensor_variable_f32(qv.iter().map(|&v| v as f32).collect(), shape.clone(), true)
                .unwrap();
            let k = s
                .tensor_variable_f32(kv.iter().map(|&v| v as f32).collect(), shape.clone(), true)
                .unwrap();
            let v = s
                .tensor_variable_f32(vv.iter().map(|&v| v as f32).collect(), shape.clone(), true)
                .unwrap();
            let o = s
                .scaled_dot_product_attention(q, k, v, None, 0.0, causal)
                .unwrap();
            assert_eq!(
                s.tensor_dtype(o).unwrap(),
                DType::F32,
                "f32 sdpa output must be F32 (causal={causal})"
            );
            let l = s.tensor_sum(o).unwrap();
            s.tensor_backward(l).unwrap();
            let gq = s.tensor_grad(q).unwrap().unwrap();
            let gk = s.tensor_grad(k).unwrap().unwrap();
            let gv = s.tensor_grad(v).unwrap().unwrap();
            for (a, b) in gq.iter().zip(gq64.iter()) {
                assert!((a - b).abs() < 1e-3, "dq causal={causal} {a} vs {b}");
            }
            for (a, b) in gk.iter().zip(gk64.iter()) {
                assert!((a - b).abs() < 1e-3, "dk causal={causal} {a} vs {b}");
            }
            for (a, b) in gv.iter().zip(gv64.iter()) {
                assert!((a - b).abs() < 1e-3, "dv causal={causal} {a} vs {b}");
            }
        }
    }

    #[test]
    fn sdpa_fused_f32_matches_f64_within_tolerance() {
        // The fused f32 SDPA kernel must match the (already op-graph-validated)
        // fused f64 path on the same values, to f32 tolerance.
        let shape = vec![4usize, 8, 4];
        let n: usize = shape.iter().product();
        let qf: Vec<f32> = (0..n).map(|i| ((i % 7) as f32 - 3.0) * 0.2).collect();
        let kf: Vec<f32> = (0..n).map(|i| ((i % 5) as f32 - 2.0) * 0.3).collect();
        let vf: Vec<f32> = (0..n).map(|i| ((i % 9) as f32 - 4.0) * 0.15).collect();
        for &causal in &[false, true] {
            let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
            let q = s
                .tensor_tape
                .leaf_f32(qf.clone(), shape.clone(), false)
                .unwrap();
            let k = s
                .tensor_tape
                .leaf_f32(kf.clone(), shape.clone(), false)
                .unwrap();
            let vt = s
                .tensor_tape
                .leaf_f32(vf.clone(), shape.clone(), false)
                .unwrap();
            let out = s
                .scaled_dot_product_attention(q, k, vt, None, 0.0, causal)
                .unwrap();
            let fused = s.tensor_values_f32(out).unwrap();

            // f64 reference (the fused f64 path, validated against the op-graph).
            let mut s2 = FrankenTorchSession::new(ExecutionMode::Strict);
            let q2 = s2
                .tensor_variable(qf.iter().map(|&x| x as f64).collect(), shape.clone(), false)
                .unwrap();
            let k2 = s2
                .tensor_variable(kf.iter().map(|&x| x as f64).collect(), shape.clone(), false)
                .unwrap();
            let v2 = s2
                .tensor_variable(vf.iter().map(|&x| x as f64).collect(), shape.clone(), false)
                .unwrap();
            let out2 = s2
                .scaled_dot_product_attention(q2, k2, v2, None, 0.0, causal)
                .unwrap();
            let reference = s2.tensor_values(out2).unwrap();

            assert_eq!(fused.len(), reference.len());
            for (i, (a, b)) in fused.iter().zip(reference.iter()).enumerate() {
                assert!(
                    (f64::from(*a) - b).abs() <= 1e-4 + 1e-4 * b.abs(),
                    "causal={causal} [{i}]: f32 fused {a} vs f64 {b}"
                );
            }
        }
    }

    #[test]
    fn sdpa_fused_grad_matches_reference_within_tolerance() {
        // The fused grad SDPA op (custom autograd: fused forward + sdpa_backward_f64)
        // must match the explicit bmm + scale + softmax + bmm op-graph backward to
        // tolerance, for dQ, dK and dV.
        let shape = vec![3usize, 6, 4]; // num_bh3, seq6, d4
        let n: usize = shape.iter().product();
        let qv: Vec<f64> = (0..n).map(|i| ((i % 7) as f64 - 3.0) * 0.2).collect();
        let kv: Vec<f64> = (0..n).map(|i| ((i % 5) as f64 - 2.0) * 0.3).collect();
        let vv: Vec<f64> = (0..n).map(|i| ((i % 9) as f64 - 4.0) * 0.15).collect();
        let scale = 1.0 / (shape[2] as f64).sqrt();

        // Fused grad path (requires_grad routes through the custom op).
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let q = s.tensor_variable(qv.clone(), shape.clone(), true).unwrap();
        let k = s.tensor_variable(kv.clone(), shape.clone(), true).unwrap();
        let vt = s.tensor_variable(vv.clone(), shape.clone(), true).unwrap();
        let out = s
            .scaled_dot_product_attention(q, k, vt, None, 0.0, false)
            .unwrap();
        let loss = s.tensor_sum(out).unwrap();
        s.tensor_backward(loss).unwrap();
        let gq = s.tensor_grad(q).unwrap().unwrap();
        let gk = s.tensor_grad(k).unwrap().unwrap();
        let gv = s.tensor_grad(vt).unwrap().unwrap();

        // Reference: explicit op-graph (bmm + scale + softmax + bmm).
        let mut s2 = FrankenTorchSession::new(ExecutionMode::Strict);
        let q2 = s2.tensor_variable(qv.clone(), shape.clone(), true).unwrap();
        let k2 = s2.tensor_variable(kv.clone(), shape.clone(), true).unwrap();
        let v2 = s2.tensor_variable(vv.clone(), shape.clone(), true).unwrap();
        let kt = s2.tensor_transpose(k2, 1, 2).unwrap();
        let scores = s2.tensor_bmm(q2, kt).unwrap();
        let sc_shape = s2.tensor_shape(scores).unwrap();
        let scale_t = s2.full(sc_shape, scale, false).unwrap();
        let scaled = s2.tensor_mul(scores, scale_t).unwrap();
        let sm = s2.tensor_softmax(scaled, 2).unwrap();
        let out2 = s2.tensor_bmm(sm, v2).unwrap();
        let loss2 = s2.tensor_sum(out2).unwrap();
        s2.tensor_backward(loss2).unwrap();
        let gq2 = s2.tensor_grad(q2).unwrap().unwrap();
        let gk2 = s2.tensor_grad(k2).unwrap().unwrap();
        let gv2 = s2.tensor_grad(v2).unwrap().unwrap();

        let close = |a: &[f64], b: &[f64], what: &str| {
            assert_eq!(a.len(), b.len());
            for (i, (p, r)) in a.iter().zip(b.iter()).enumerate() {
                assert!(
                    (p - r).abs() <= 1e-10 + 1e-8 * r.abs(),
                    "{what}[{i}]: fused {p} vs reference {r}"
                );
            }
        };
        close(&gq, &gq2, "dq");
        close(&gk, &gk2, "dk");
        close(&gv, &gv2, "dv");
    }

