    #[test]
    fn kl_div_fused_nograd_matches_composed_bit_exact() {
        // Fused no-grad mean/sum must be BIT-IDENTICAL to the composed path, for
        // both log_target branches. frankentorch-3jmy3.
        let n = 1000usize;
        // input = log-probs (negative); target positive (so log(target) finite).
        let x: Vec<f64> = (0..n)
            .map(|i| -(((i * 7 + 3) % 50) as f64 * 0.05 + 0.1))
            .collect();
        let t: Vec<f64> = (0..n)
            .map(|i| 0.05 + ((i * 11 + 1) % 40) as f64 * 0.02)
            .collect();
        // log_target=true: target is itself in log-space (use negative values).
        let tl: Vec<f64> = (0..n)
            .map(|i| -(((i * 5 + 2) % 30) as f64 * 0.07 + 0.2))
            .collect();
        for &log_target in &[false, true] {
            let tgt = if log_target { &tl } else { &t };
            for red in ["mean", "sum"] {
                let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
                let xt = s.tensor_variable(x.clone(), vec![n], false).unwrap();
                let tt = s.tensor_variable(tgt.clone(), vec![n], false).unwrap();
                let fused = s.tensor_kl_div(xt, tt, red, log_target).unwrap();
                let fv = s
                    .tensor_tape
                    .tensor(fused)
                    .unwrap()
                    .contiguous_values_as_f64()
                    .unwrap()[0];

                let mut s2 = FrankenTorchSession::new(ExecutionMode::Strict);
                let xt2 = s2.tensor_variable(x.clone(), vec![n], true).unwrap();
                let tt2 = s2.tensor_variable(tgt.clone(), vec![n], false).unwrap();
                let comp = s2.tensor_kl_div(xt2, tt2, red, log_target).unwrap();
                let cv = s2
                    .tensor_tape
                    .tensor(comp)
                    .unwrap()
                    .contiguous_values_as_f64()
                    .unwrap()[0];

                assert_eq!(
                    fv.to_bits(),
                    cv.to_bits(),
                    "kl_div log_target={log_target} {red}: fused {fv} != composed {cv}"
                );
            }
        }
    }

    #[test]
    fn cholesky_upper_backward_matches_finite_difference() {
        use ft_core::{DType, Device};
        let n = 4usize;
        let mut b = vec![0.0f64; n * n];
        for i in 0..n {
            for j in 0..n {
                b[i * n + j] = ((i * 2 + j) % 5) as f64 * 0.1 + 0.05;
            }
        }
        let mut a = vec![0.0f64; n * n];
        for i in 0..n {
            for j in 0..n {
                let mut s = 0.0;
                for k in 0..n {
                    s += b[i * n + k] * b[j * n + k];
                }
                a[i * n + j] = s;
            }
            a[i * n + i] += n as f64;
        }
        let mut v = vec![0.0f64; n * n];
        for i in 0..n {
            for j in 0..=i {
                let val = ((i + 3 * j) % 4) as f64 * 0.1 - 0.15;
                v[i * n + j] = val;
                v[j * n + i] = val;
            }
        }

        // loss(M) = sum of squares of the UPPER Cholesky factor.
        let loss_of = |mat: &[f64]| -> f64 {
            let meta = TensorMeta::from_shape(vec![n, n], DType::F64, Device::Cpu);
            let r = ft_kernel_cpu::cholesky_contiguous_f64(mat, &meta, true).unwrap();
            r.factor.iter().map(|x| x * x).sum::<f64>()
        };

        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let at = s.tensor_variable(a.clone(), vec![n, n], true).unwrap();
        let u = s.tensor_linalg_cholesky(at, true).unwrap();
        let usq = s.tensor_mul(u, u).unwrap();
        let loss = s.tensor_sum(usq).unwrap();
        let report = s.tensor_backward(loss).unwrap();
        let grad_a = s
            .tensor_gradient(&report, at)
            .expect("cholesky upper grad present");
        let analytic: f64 = grad_a.iter().zip(v.iter()).map(|(g, vv)| g * vv).sum();

        let eps = 1e-6;
        let a_plus: Vec<f64> = a.iter().zip(v.iter()).map(|(x, vv)| x + eps * vv).collect();
        let a_minus: Vec<f64> = a.iter().zip(v.iter()).map(|(x, vv)| x - eps * vv).collect();
        let fd = (loss_of(&a_plus) - loss_of(&a_minus)) / (2.0 * eps);

        assert!(
            (analytic - fd).abs() <= 1e-4 * (1.0 + fd.abs()),
            "cholesky upper backward mismatch: analytic={analytic}, fd={fd}"
        );
    }

    #[test]
    fn eigvalsh_backward_matches_finite_difference() {
        use ft_core::{DType, Device};
        let n = 4usize;
        // Symmetric A = B B^T + distinct diagonal shifts (well-separated spectrum).
        let mut b = vec![0.0f64; n * n];
        for i in 0..n {
            for j in 0..n {
                b[i * n + j] = ((i + 2 * j) % 5) as f64 * 0.1 + 0.05;
            }
        }
        let mut a = vec![0.0f64; n * n];
        for i in 0..n {
            for j in 0..n {
                let mut s = 0.0;
                for k in 0..n {
                    s += b[i * n + k] * b[j * n + k];
                }
                a[i * n + j] = s;
            }
            a[i * n + i] += (i + 1) as f64 * 2.0;
        }
        let mut v = vec![0.0f64; n * n];
        for i in 0..n {
            for j in 0..=i {
                let val = ((i + 3 * j) % 4) as f64 * 0.1 - 0.15;
                v[i * n + j] = val;
                v[j * n + i] = val;
            }
        }

        // loss(M) = sum of squares of the symmetric eigenvalues of M.
        let loss_of = |mat: &[f64]| -> f64 {
            let meta = TensorMeta::from_shape(vec![n, n], DType::F64, Device::Cpu);
            let ev = ft_kernel_cpu::eigvalsh_contiguous_f64(mat, &meta).unwrap();
            ev.iter().map(|x| x * x).sum::<f64>()
        };

        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let at = s.tensor_variable(a.clone(), vec![n, n], true).unwrap();
        let evals = s.tensor_linalg_eigvalsh(at).unwrap();
        let sq = s.tensor_mul(evals, evals).unwrap();
        let loss = s.tensor_sum(sq).unwrap();
        let report = s.tensor_backward(loss).unwrap();
        let grad_a = s
            .tensor_gradient(&report, at)
            .expect("eigvalsh grad present");
        let analytic: f64 = grad_a.iter().zip(v.iter()).map(|(g, vv)| g * vv).sum();

        let eps = 1e-6;
        let a_plus: Vec<f64> = a.iter().zip(v.iter()).map(|(x, vv)| x + eps * vv).collect();
        let a_minus: Vec<f64> = a.iter().zip(v.iter()).map(|(x, vv)| x - eps * vv).collect();
        let fd = (loss_of(&a_plus) - loss_of(&a_minus)) / (2.0 * eps);

        assert!(
            (analytic - fd).abs() <= 1e-4 * (1.0 + fd.abs()),
            "eigvalsh backward mismatch: analytic={analytic}, fd={fd}"
        );
    }

    // Build a symmetric 4x4 matrix with a well-separated spectrum + a symmetric
    // perturbation direction, shared by the two eigh backward tests.
    fn eigh_test_matrix() -> (usize, Vec<f64>, Vec<f64>) {
        let n = 4usize;
        let mut b = vec![0.0f64; n * n];
        for i in 0..n {
            for j in 0..n {
                b[i * n + j] = ((i + 2 * j) % 5) as f64 * 0.1 + 0.05;
            }
        }
        let mut a = vec![0.0f64; n * n];
        for i in 0..n {
            for j in 0..n {
                let mut s = 0.0;
                for k in 0..n {
                    s += b[i * n + k] * b[j * n + k];
                }
                a[i * n + j] = s;
            }
            a[i * n + i] += (i + 1) as f64 * 2.0;
        }
        // Symmetric perturbation direction V (eigh requires symmetric input).
        let mut v = vec![0.0f64; n * n];
        for i in 0..n {
            for j in 0..=i {
                let val = ((i + 3 * j) % 4) as f64 * 0.1 - 0.15;
                v[i * n + j] = val;
                v[j * n + i] = val;
            }
        }
        (n, a, v)
    }

    #[test]
    fn eigh_eigenvalue_backward_matches_finite_difference_and_value_parity() {
        use ft_core::{DType, Device};
        let (n, a, v) = eigh_test_matrix();

        // Forward value parity: eigh (grad path) eigenvalues vs non-grad path.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let a_ng = s.tensor_variable(a.clone(), vec![n, n], false).unwrap();
        let (ev_ng, _) = s.tensor_linalg_eigh(a_ng).unwrap();
        let ev_ng_v = s.tensor_values(ev_ng).unwrap();
        let a_g = s.tensor_variable(a.clone(), vec![n, n], true).unwrap();
        let (ev_g, _vec_g) = s.tensor_linalg_eigh(a_g).unwrap();
        let ev_g_v = s.tensor_values(ev_g).unwrap();
        for (x, y) in ev_ng_v.iter().zip(ev_g_v.iter()) {
            assert_eq!(
                x.to_bits(),
                y.to_bits(),
                "eigh eigenvalue grad/non-grad mismatch"
            );
        }

        // loss = sum(λ^2); FD-verify grad flows through the eigenvalues output.
        let loss_of = |mat: &[f64]| -> f64 {
            let meta = TensorMeta::from_shape(vec![n, n], DType::F64, Device::Cpu);
            let ev = ft_kernel_cpu::eigvalsh_contiguous_f64(mat, &meta).unwrap();
            ev.iter().map(|x| x * x).sum::<f64>()
        };
        let sq = s.tensor_mul(ev_g, ev_g).unwrap();
        let loss = s.tensor_sum(sq).unwrap();
        let report = s.tensor_backward(loss).unwrap();
        let grad_a = s
            .tensor_gradient(&report, a_g)
            .expect("eigh eigenvalue grad present");
        let analytic: f64 = grad_a.iter().zip(v.iter()).map(|(g, vv)| g * vv).sum();
        let eps = 1e-6;
        let a_plus: Vec<f64> = a.iter().zip(v.iter()).map(|(x, vv)| x + eps * vv).collect();
        let a_minus: Vec<f64> = a.iter().zip(v.iter()).map(|(x, vv)| x - eps * vv).collect();
        let fd = (loss_of(&a_plus) - loss_of(&a_minus)) / (2.0 * eps);
        assert!(
            (analytic - fd).abs() <= 1e-4 * (1.0 + fd.abs()),
            "eigh eigenvalue backward mismatch: analytic={analytic}, fd={fd}"
        );
    }

    #[test]
    fn eigh_eigenvector_backward_matches_finite_difference() {
        use ft_core::{DType, Device};
        let (n, a, v) = eigh_test_matrix();
        // Fixed projection vector; loss = Σ_k (c^T v_k)^2 is sign/gauge-invariant
        // (each eigenvector enters squared), so it is smooth across the arbitrary
        // sign convention of the solver — making the FD check well-posed.
        let c = vec![1.0, -0.5, 0.3, 0.8];

        // Analytic gradient via the eigenvectors output of eigh.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let a_g = s.tensor_variable(a.clone(), vec![n, n], true).unwrap();
        let (_ev_g, vec_g) = s.tensor_linalg_eigh(a_g).unwrap();
        let c_t = s.tensor_variable(c.clone(), vec![1, n], false).unwrap();
        let cv = s.tensor_matmul(c_t, vec_g).unwrap(); // [1, n] = c^T V
        let sq = s.tensor_mul(cv, cv).unwrap();
        let loss = s.tensor_sum(sq).unwrap();
        let report = s.tensor_backward(loss).unwrap();
        let grad_a = s
            .tensor_gradient(&report, a_g)
            .expect("eigh eigenvector grad present");
        let analytic: f64 = grad_a.iter().zip(v.iter()).map(|(g, vv)| g * vv).sum();

        // FD of the same gauge-invariant loss computed directly from the kernel.
        let loss_of = |mat: &[f64]| -> f64 {
            let meta = TensorMeta::from_shape(vec![n, n], DType::F64, Device::Cpu);
            let r = ft_kernel_cpu::eigh_contiguous_f64(mat, &meta).unwrap();
            // V is n x n, eigenvectors in columns; v_k[i] = V[i*n + k].
            let mut acc = 0.0;
            for k in 0..n {
                let mut dot = 0.0;
                for i in 0..n {
                    dot += c[i] * r.eigenvectors[i * n + k];
                }
                acc += dot * dot;
            }
            acc
        };
        let eps = 1e-6;
        let a_plus: Vec<f64> = a.iter().zip(v.iter()).map(|(x, vv)| x + eps * vv).collect();
        let a_minus: Vec<f64> = a.iter().zip(v.iter()).map(|(x, vv)| x - eps * vv).collect();
        let fd = (loss_of(&a_plus) - loss_of(&a_minus)) / (2.0 * eps);
        assert!(
            (analytic - fd).abs() <= 1e-4 * (1.0 + fd.abs()),
            "eigh eigenvector backward mismatch: analytic={analytic}, fd={fd}"
        );
    }

    // Tall 4x3 full-rank matrix with well-separated singular values, shared by
    // the three svd backward tests. m=4 > k=3 exercises the (I-UU^T) term.
    fn svd_test_matrix() -> (usize, usize, Vec<f64>, Vec<f64>) {
        let (m, n) = (4usize, 3usize);
        #[rustfmt::skip]
        let a = vec![
            3.0, 0.2, -0.1,
            0.1, 2.0, 0.3,
            -0.2, 0.4, 1.0,
            0.5, -0.3, 0.2,
        ];
        let dir: Vec<f64> = (0..m * n)
            .map(|i| ((i * 7 + 3) % 11) as f64 * 0.03 - 0.15)
            .collect();
        (m, n, a, dir)
    }

    #[test]
    fn svd_singular_value_backward_matches_finite_difference_and_value_parity() {
        use ft_core::{DType, Device};
        let (m, n, a, dir) = svd_test_matrix();

        // Value parity: grad-path S bit-identical to the non-grad path.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let a_ng = s.tensor_variable(a.clone(), vec![m, n], false).unwrap();
        let (_u0, s0, _v0) = s.tensor_linalg_svd(a_ng, false).unwrap();
        let s0_v = s.tensor_values(s0).unwrap();
        let a_g = s.tensor_variable(a.clone(), vec![m, n], true).unwrap();
        let (_ug, sg, _vg) = s.tensor_linalg_svd(a_g, false).unwrap();
        let sg_v = s.tensor_values(sg).unwrap();
        for (x, y) in s0_v.iter().zip(sg_v.iter()) {
            assert_eq!(
                x.to_bits(),
                y.to_bits(),
                "svd S grad/non-grad value mismatch"
            );
        }

        // loss = Σ σ²; FD via svdvals.
        let loss_of = |mat: &[f64]| -> f64 {
            let meta = TensorMeta::from_shape(vec![m, n], DType::F64, Device::Cpu);
            let sv = ft_kernel_cpu::svdvals_contiguous_f64(mat, &meta).unwrap();
            sv.iter().map(|x| x * x).sum::<f64>()
        };
        let sq = s.tensor_mul(sg, sg).unwrap();
        let loss = s.tensor_sum(sq).unwrap();
        let report = s.tensor_backward(loss).unwrap();
        let grad_a = s.tensor_gradient(&report, a_g).expect("svd S grad present");
        let analytic: f64 = grad_a.iter().zip(dir.iter()).map(|(g, d)| g * d).sum();
        let eps = 1e-6;
        let ap: Vec<f64> = a.iter().zip(dir.iter()).map(|(x, d)| x + eps * d).collect();
        let am: Vec<f64> = a.iter().zip(dir.iter()).map(|(x, d)| x - eps * d).collect();
        let fd = (loss_of(&ap) - loss_of(&am)) / (2.0 * eps);
        assert!(
            (analytic - fd).abs() <= 1e-4 * (1.0 + fd.abs()),
            "svd S backward mismatch: analytic={analytic}, fd={fd}"
        );
    }

    #[test]
    fn svd_left_vector_backward_matches_finite_difference() {
        use ft_core::{DType, Device};
        let (m, n, a, dir) = svd_test_matrix();
        let k = n;
        // Gauge-invariant loss on U: Σ_p (c^T u_p)² (u_p = column p of U).
        let c = vec![1.0, -0.5, 0.3, 0.8];

        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let a_g = s.tensor_variable(a.clone(), vec![m, n], true).unwrap();
        let (ug, _sg, _vg) = s.tensor_linalg_svd(a_g, false).unwrap();
        let c_t = s.tensor_variable(c.clone(), vec![1, m], false).unwrap();
        let cu = s.tensor_matmul(c_t, ug).unwrap(); // [1, k] = c^T U
        let sq = s.tensor_mul(cu, cu).unwrap();
        let loss = s.tensor_sum(sq).unwrap();
        let report = s.tensor_backward(loss).unwrap();
        let grad_a = s.tensor_gradient(&report, a_g).expect("svd U grad present");
        let analytic: f64 = grad_a.iter().zip(dir.iter()).map(|(g, d)| g * d).sum();

        let loss_of = |mat: &[f64]| -> f64 {
            let meta = TensorMeta::from_shape(vec![m, n], DType::F64, Device::Cpu);
            let r = ft_kernel_cpu::svd_contiguous_f64(mat, &meta, false).unwrap();
            let mut acc = 0.0;
            for p in 0..k {
                let mut dot = 0.0;
                for i in 0..m {
                    dot += c[i] * r.u[i * k + p];
                }
                acc += dot * dot;
            }
            acc
        };
        let eps = 1e-6;
        let ap: Vec<f64> = a.iter().zip(dir.iter()).map(|(x, d)| x + eps * d).collect();
        let am: Vec<f64> = a.iter().zip(dir.iter()).map(|(x, d)| x - eps * d).collect();
        let fd = (loss_of(&ap) - loss_of(&am)) / (2.0 * eps);
        assert!(
            (analytic - fd).abs() <= 1e-4 * (1.0 + fd.abs()),
            "svd U backward mismatch: analytic={analytic}, fd={fd}"
        );
    }

    #[test]
    fn svd_right_vector_backward_matches_finite_difference() {
        use ft_core::{DType, Device};
        let (m, n, a, dir) = svd_test_matrix();
        let k = n;
        // Gauge-invariant loss on Vh: Σ_p (Vh[p,:] · d)² (right singular vectors).
        let dd = vec![0.7, -0.4, 0.9];

        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let a_g = s.tensor_variable(a.clone(), vec![m, n], true).unwrap();
        let (_ug, _sg, vhg) = s.tensor_linalg_svd(a_g, false).unwrap();
        let d_t = s.tensor_variable(dd.clone(), vec![n, 1], false).unwrap();
        let vd = s.tensor_matmul(vhg, d_t).unwrap(); // [k, 1] = Vh d
        let sq = s.tensor_mul(vd, vd).unwrap();
        let loss = s.tensor_sum(sq).unwrap();
        let report = s.tensor_backward(loss).unwrap();
        let grad_a = s
            .tensor_gradient(&report, a_g)
            .expect("svd Vh grad present");
        let analytic: f64 = grad_a.iter().zip(dir.iter()).map(|(g, dv)| g * dv).sum();

        let loss_of = |mat: &[f64]| -> f64 {
            let meta = TensorMeta::from_shape(vec![m, n], DType::F64, Device::Cpu);
            let r = ft_kernel_cpu::svd_contiguous_f64(mat, &meta, false).unwrap();
            let mut acc = 0.0;
            for p in 0..k {
                let mut dot = 0.0;
                for q in 0..n {
                    dot += r.vh[p * n + q] * dd[q];
                }
                acc += dot * dot;
            }
            acc
        };
        let eps = 1e-6;
        let ap: Vec<f64> = a
            .iter()
            .zip(dir.iter())
            .map(|(x, dv)| x + eps * dv)
            .collect();
        let am: Vec<f64> = a
            .iter()
            .zip(dir.iter())
            .map(|(x, dv)| x - eps * dv)
            .collect();
        let fd = (loss_of(&ap) - loss_of(&am)) / (2.0 * eps);
        assert!(
            (analytic - fd).abs() <= 1e-4 * (1.0 + fd.abs()),
            "svd Vh backward mismatch: analytic={analytic}, fd={fd}"
        );
    }

    #[test]
    fn qr_backward_matches_finite_difference_and_value_parity() {
        use ft_core::{DType, Device};
        // Tall 4x3 full-rank matrix; reduced QR → Q is 4x3, R is 3x3.
        let (m, n) = (4usize, 3usize);
        #[rustfmt::skip]
        let a = vec![
            1.0, 0.5, -0.3,
            0.2, 2.0, 0.4,
            -0.4, 0.1, 1.5,
            0.6, -0.7, 0.2,
        ];
        // Fixed weights → loss = <Q, Wq> + <R, Wr> is LINEAR in (Q, R), so
        // grad_Q=Wq, grad_R=Wr and the central FD is exact to O(eps^2). QR with
        // the deterministic Householder sign convention is smooth in A at a
        // full-rank point, so no sign-flip discontinuity over the FD step.
        let wq: Vec<f64> = (0..m * n)
            .map(|i| ((i * 5 + 1) % 7) as f64 * 0.1 - 0.3)
            .collect();
        let wr: Vec<f64> = (0..n * n)
            .map(|i| ((i * 3 + 2) % 5) as f64 * 0.1 - 0.2)
            .collect();
        let dir: Vec<f64> = (0..m * n)
            .map(|i| ((i * 7 + 3) % 11) as f64 * 0.02 - 0.1)
            .collect();

        // Value parity: grad-path Q,R bit-identical to the non-grad path.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let a_ng = s.tensor_variable(a.clone(), vec![m, n], false).unwrap();
        let (q_ng, r_ng) = s.tensor_linalg_qr(a_ng, true).unwrap();
        let q_ng_v = s.tensor_values(q_ng).unwrap();
        let r_ng_v = s.tensor_values(r_ng).unwrap();
        let a_g = s.tensor_variable(a.clone(), vec![m, n], true).unwrap();
        let (q_g, r_g) = s.tensor_linalg_qr(a_g, true).unwrap();
        let q_g_v = s.tensor_values(q_g).unwrap();
        let r_g_v = s.tensor_values(r_g).unwrap();
        for (x, y) in q_ng_v.iter().zip(q_g_v.iter()) {
            assert_eq!(
                x.to_bits(),
                y.to_bits(),
                "qr Q grad/non-grad value mismatch"
            );
        }
        for (x, y) in r_ng_v.iter().zip(r_g_v.iter()) {
            assert_eq!(
                x.to_bits(),
                y.to_bits(),
                "qr R grad/non-grad value mismatch"
            );
        }

        // Analytic gradient of loss = <Q, Wq> + <R, Wr> through both outputs.
        let wq_t = s.tensor_variable(wq.clone(), vec![m, n], false).unwrap();
        let wr_t = s.tensor_variable(wr.clone(), vec![n, n], false).unwrap();
        let qw = s.tensor_mul(q_g, wq_t).unwrap();
        let rw = s.tensor_mul(r_g, wr_t).unwrap();
        let sq = s.tensor_sum(qw).unwrap();
        let sr = s.tensor_sum(rw).unwrap();
        let loss = s.tensor_add(sq, sr).unwrap();
        let report = s.tensor_backward(loss).unwrap();
        let grad_a = s.tensor_gradient(&report, a_g).expect("qr grad present");
        let analytic: f64 = grad_a.iter().zip(dir.iter()).map(|(g, d)| g * d).sum();

        let loss_of = |mat: &[f64]| -> f64 {
            let meta = TensorMeta::from_shape(vec![m, n], DType::F64, Device::Cpu);
            let r = ft_kernel_cpu::qr_contiguous_f64(mat, &meta, true).unwrap();
            let mut acc = 0.0;
            for (qi, wqi) in r.q.iter().zip(wq.iter()) {
                acc += qi * wqi;
            }
            for (ri, wri) in r.r.iter().zip(wr.iter()) {
                acc += ri * wri;
            }
            acc
        };
        let eps = 1e-6;
        let a_plus: Vec<f64> = a.iter().zip(dir.iter()).map(|(x, d)| x + eps * d).collect();
        let a_minus: Vec<f64> = a.iter().zip(dir.iter()).map(|(x, d)| x - eps * d).collect();
        let fd = (loss_of(&a_plus) - loss_of(&a_minus)) / (2.0 * eps);
        assert!(
            (analytic - fd).abs() <= 1e-4 * (1.0 + fd.abs()),
            "qr backward mismatch: analytic={analytic}, fd={fd}"
        );
    }

    #[test]
    fn svdvals_backward_matches_finite_difference_and_value_parity() {
        use ft_core::{DType, Device};
        // Rectangular 4x3 matrix with well-separated singular values.
        let (m, n) = (4usize, 3usize);
        #[rustfmt::skip]
        let a = vec![
            3.0, 0.2, -0.1,
            0.1, 2.0, 0.3,
            -0.2, 0.4, 1.0,
            0.5, -0.3, 0.2,
        ];
        let v: Vec<f64> = (0..m * n)
            .map(|i| ((i * 7 + 3) % 11) as f64 * 0.05 - 0.25)
            .collect();

        // Bit-exact forward parity: grad path (full reduced SVD) vs non-grad
        // path (svdvals_contiguous_f64, which itself calls svd(.., false).s).
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let a_ng = s.tensor_variable(a.clone(), vec![m, n], false).unwrap();
        let sv_ng = s.tensor_linalg_svdvals(a_ng).unwrap();
        let sv_ng_v = s.tensor_values(sv_ng).unwrap();
        let a_g = s.tensor_variable(a.clone(), vec![m, n], true).unwrap();
        let sv_g = s.tensor_linalg_svdvals(a_g).unwrap();
        let sv_g_v = s.tensor_values(sv_g).unwrap();
        for (x, y) in sv_ng_v.iter().zip(sv_g_v.iter()) {
            assert_eq!(
                x.to_bits(),
                y.to_bits(),
                "svdvals grad/non-grad value mismatch"
            );
        }

        // FD verification of the restored gradient: loss = sum(σ^2).
        let loss_of = |mat: &[f64]| -> f64 {
            let meta = TensorMeta::from_shape(vec![m, n], DType::F64, Device::Cpu);
            let sv = ft_kernel_cpu::svdvals_contiguous_f64(mat, &meta).unwrap();
            sv.iter().map(|x| x * x).sum::<f64>()
        };
        let sq = s.tensor_mul(sv_g, sv_g).unwrap();
        let loss = s.tensor_sum(sq).unwrap();
        let report = s.tensor_backward(loss).unwrap();
        let grad_a = s
            .tensor_gradient(&report, a_g)
            .expect("svdvals grad present");
        let analytic: f64 = grad_a.iter().zip(v.iter()).map(|(g, vv)| g * vv).sum();
        let eps = 1e-6;
        let a_plus: Vec<f64> = a.iter().zip(v.iter()).map(|(x, vv)| x + eps * vv).collect();
        let a_minus: Vec<f64> = a.iter().zip(v.iter()).map(|(x, vv)| x - eps * vv).collect();
        let fd = (loss_of(&a_plus) - loss_of(&a_minus)) / (2.0 * eps);
        assert!(
            (analytic - fd).abs() <= 1e-4 * (1.0 + fd.abs()),
            "svdvals backward mismatch: analytic={analytic}, fd={fd}"
        );
    }

    #[test]
    fn inv_ex_autograd_matches_finite_difference_and_value_parity() {
        use ft_core::{DType, Device};
        let n = 3usize;
        #[rustfmt::skip]
        let a = vec![
            4.0, 1.0, 0.5,
            1.0, 3.0, 0.7,
            0.5, 0.7, 2.0,
        ];
        // Direction for the directional-derivative FD check.
        let v = vec![0.1, -0.2, 0.05, 0.3, -0.1, 0.15, -0.25, 0.2, 0.1];

        // Bit-exact forward parity: the requires_grad path must return the same
        // inverse as the non-grad path (both use inv_tensor_contiguous_f64).
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let a_ng = s.tensor_variable(a.clone(), vec![n, n], false).unwrap();
        let (inv_ng, info_ng) = s.tensor_linalg_inv_ex(a_ng).unwrap();
        assert_eq!(info_ng, 0);
        let inv_ng_v = s.tensor_values(inv_ng).unwrap();
        let a_g = s.tensor_variable(a.clone(), vec![n, n], true).unwrap();
        let (inv_g, info_g) = s.tensor_linalg_inv_ex(a_g).unwrap();
        assert_eq!(info_g, 0);
        let inv_g_v = s.tensor_values(inv_g).unwrap();
        for (x, y) in inv_ng_v.iter().zip(inv_g_v.iter()) {
            assert_eq!(
                x.to_bits(),
                y.to_bits(),
                "inv_ex grad/non-grad value mismatch"
            );
        }

        // FD verification of the unlocked gradient: loss = sum(inv(A)^2).
        let loss_of = |mat: &[f64]| -> f64 {
            let meta = TensorMeta::from_shape(vec![n, n], DType::F64, Device::Cpu);
            let iv = ft_kernel_cpu::inv_tensor_contiguous_f64(mat, &meta).unwrap();
            iv.iter().map(|x| x * x).sum::<f64>()
        };
        let sq = s.tensor_mul(inv_g, inv_g).unwrap();
        let loss = s.tensor_sum(sq).unwrap();
        let report = s.tensor_backward(loss).unwrap();
        let grad_a = s
            .tensor_gradient(&report, a_g)
            .expect("inv_ex grad present");
        let analytic: f64 = grad_a.iter().zip(v.iter()).map(|(g, vv)| g * vv).sum();
        let eps = 1e-6;
        let a_plus: Vec<f64> = a.iter().zip(v.iter()).map(|(x, vv)| x + eps * vv).collect();
        let a_minus: Vec<f64> = a.iter().zip(v.iter()).map(|(x, vv)| x - eps * vv).collect();
        let fd = (loss_of(&a_plus) - loss_of(&a_minus)) / (2.0 * eps);
        assert!(
            (analytic - fd).abs() <= 1e-4 * (1.0 + fd.abs()),
            "inv_ex backward mismatch: analytic={analytic}, fd={fd}"
        );
    }

    #[test]
    fn cholesky_ex_autograd_matches_base_and_value_parity() {
        let n = 3usize;
        // SPD matrix.
        #[rustfmt::skip]
        let a = vec![
            4.0, 1.0, 0.5,
            1.0, 3.0, 0.7,
            0.5, 0.7, 2.0,
        ];
        // Forward value parity: grad path vs non-grad path (same kernel).
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let a_ng = s.tensor_variable(a.clone(), vec![n, n], false).unwrap();
        let (l_ng, info_ng) = s.tensor_linalg_cholesky_ex(a_ng, false).unwrap();
        assert_eq!(info_ng, 0);
        let l_ng_v = s.tensor_values(l_ng).unwrap();
        let a_g = s.tensor_variable(a.clone(), vec![n, n], true).unwrap();
        let (l_g, info_g) = s.tensor_linalg_cholesky_ex(a_g, false).unwrap();
        assert_eq!(info_g, 0);
        let l_g_v = s.tensor_values(l_g).unwrap();
        for (x, y) in l_ng_v.iter().zip(l_g_v.iter()) {
            assert_eq!(
                x.to_bits(),
                y.to_bits(),
                "cholesky_ex grad/non-grad value mismatch"
            );
        }

        // The unlocked gradient must be bit-identical to the autograd-aware base
        // op it delegates to (loss = sum(L^2)).
        let sq = s.tensor_mul(l_g, l_g).unwrap();
        let loss = s.tensor_sum(sq).unwrap();
        let report = s.tensor_backward(loss).unwrap();
        let grad_ex = s
            .tensor_gradient(&report, a_g)
            .expect("cholesky_ex grad present");

        let mut s2 = FrankenTorchSession::new(ExecutionMode::Strict);
        let a_base = s2.tensor_variable(a.clone(), vec![n, n], true).unwrap();
        let l_base = s2.tensor_linalg_cholesky(a_base, false).unwrap();
        let sq2 = s2.tensor_mul(l_base, l_base).unwrap();
        let loss2 = s2.tensor_sum(sq2).unwrap();
        let report2 = s2.tensor_backward(loss2).unwrap();
        let grad_base = s2
            .tensor_gradient(&report2, a_base)
            .expect("cholesky grad present");
        for (x, y) in grad_ex.iter().zip(grad_base.iter()) {
            assert_eq!(
                x.to_bits(),
                y.to_bits(),
                "cholesky_ex grad != cholesky grad"
            );
        }
    }

    #[test]
    fn solve_ex_autograd_matches_base_and_value_parity() {
        let n = 3usize;
        #[rustfmt::skip]
        let a = vec![
            4.0, 1.0, 0.5,
            1.0, 3.0, 0.7,
            0.5, 0.7, 2.0,
        ];
        let b = vec![1.0, 2.0, -1.0];
        // Forward value parity: grad path vs non-grad path.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let a_ng = s.tensor_variable(a.clone(), vec![n, n], false).unwrap();
        let b_ng = s.tensor_variable(b.clone(), vec![n], false).unwrap();
        let (x_ng, info_ng) = s.tensor_linalg_solve_ex(a_ng, b_ng).unwrap();
        assert_eq!(info_ng, 0);
        let x_ng_v = s.tensor_values(x_ng).unwrap();
        let a_g = s.tensor_variable(a.clone(), vec![n, n], true).unwrap();
        let b_g = s.tensor_variable(b.clone(), vec![n], true).unwrap();
        let (x_g, info_g) = s.tensor_linalg_solve_ex(a_g, b_g).unwrap();
        assert_eq!(info_g, 0);
        let x_g_v = s.tensor_values(x_g).unwrap();
        for (xv, yv) in x_ng_v.iter().zip(x_g_v.iter()) {
            assert_eq!(
                xv.to_bits(),
                yv.to_bits(),
                "solve_ex grad/non-grad value mismatch"
            );
        }

        // Unlocked gradient bit-identical to the base solve (loss = sum(X^2)).
        let sq = s.tensor_mul(x_g, x_g).unwrap();
        let loss = s.tensor_sum(sq).unwrap();
        let report = s.tensor_backward(loss).unwrap();
        let grad_a_ex = s
            .tensor_gradient(&report, a_g)
            .expect("solve_ex grad_a present");
        let grad_b_ex = s
            .tensor_gradient(&report, b_g)
            .expect("solve_ex grad_b present");

        let mut s2 = FrankenTorchSession::new(ExecutionMode::Strict);
        let a_base = s2.tensor_variable(a.clone(), vec![n, n], true).unwrap();
        let b_base = s2.tensor_variable(b.clone(), vec![n], true).unwrap();
        let x_base = s2.tensor_linalg_solve(a_base, b_base).unwrap();
        let sq2 = s2.tensor_mul(x_base, x_base).unwrap();
        let loss2 = s2.tensor_sum(sq2).unwrap();
        let report2 = s2.tensor_backward(loss2).unwrap();
        let grad_a_base = s2
            .tensor_gradient(&report2, a_base)
            .expect("solve grad_a present");
        let grad_b_base = s2
            .tensor_gradient(&report2, b_base)
            .expect("solve grad_b present");
        for (xv, yv) in grad_a_ex.iter().zip(grad_a_base.iter()) {
            assert_eq!(
                xv.to_bits(),
                yv.to_bits(),
                "solve_ex grad_a != solve grad_a"
            );
        }
        for (xv, yv) in grad_b_ex.iter().zip(grad_b_base.iter()) {
            assert_eq!(
                xv.to_bits(),
                yv.to_bits(),
                "solve_ex grad_b != solve grad_b"
            );
        }
    }

