    #[test]
    fn expit_matches_sigmoid() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let input = s
            .tensor_variable(vec![-2.0, -1.0, 0.0, 1.0, 2.0], vec![5], false)
            .unwrap();
        let result = s.tensor_expit(input).unwrap();
        let vals = s.tensor_values(result).unwrap();
        let expected = [
            1.0 / (1.0 + 2.0_f64.exp()),
            1.0 / (1.0 + 1.0_f64.exp()),
            0.5,
            1.0 / (1.0 + (-1.0_f64).exp()),
            1.0 / (1.0 + (-2.0_f64).exp()),
        ];
        for (a, b) in vals.iter().zip(expected.iter()) {
            assert!((a - b).abs() < 1e-10, "{a} != {b}");
        }
    }

    #[test]
    fn logit_inverse_of_sigmoid() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let input = s
            .tensor_variable(vec![0.1, 0.5, 0.9], vec![3], false)
            .unwrap();
        let result = s.tensor_logit(input, None).unwrap();
        let vals = s.tensor_values(result).unwrap();
        // logit(0.5) = 0, logit(0.1) < 0, logit(0.9) > 0
        assert!((vals[1]).abs() < 1e-10, "logit(0.5) should be 0");
        assert!(vals[0] < 0.0, "logit(0.1) should be negative");
        assert!(vals[2] > 0.0, "logit(0.9) should be positive");
        // logit(x) should approximately invert sigmoid
        assert!(
            (vals[0] + vals[2]).abs() < 1e-10,
            "logit should be antisymmetric around 0.5"
        );
    }

    #[test]
    fn logit_with_eps_clamping() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let input = s
            .tensor_variable(vec![0.0, 0.5, 1.0], vec![3], false)
            .unwrap();
        let result = s.tensor_logit(input, Some(0.01)).unwrap();
        let vals = s.tensor_values(result).unwrap();
        // With eps=0.01, inputs are clamped to [0.01, 0.99]
        assert!(vals[0].is_finite(), "logit(0) with eps should be finite");
        assert!(vals[2].is_finite(), "logit(1) with eps should be finite");
    }

    #[test]
    fn logit_nograd_f64_fast_path_matches_composed_bits() {
        let n = super::PARALLEL_ELEMENTWISE_MIN + 17;
        let values: Vec<f64> = (0..n)
            .map(|i| {
                let bucket = ((i.wrapping_mul(37) % 997) as f64 + 0.5) / 997.0;
                0.01 + bucket * 0.98
            })
            .collect();

        let mut fast = FrankenTorchSession::new(ExecutionMode::Strict);
        let fast_in = fast
            .tensor_variable(values.clone(), vec![n], false)
            .unwrap();
        let fast_out = fast.tensor_logit(fast_in, None).unwrap();
        let fast_vals = fast.tensor_values(fast_out).unwrap();

        let mut composed = FrankenTorchSession::new(ExecutionMode::Strict);
        let composed_in = composed.tensor_variable(values, vec![n], true).unwrap();
        let composed_out = composed.tensor_logit(composed_in, None).unwrap();
        let composed_vals = composed.tensor_values(composed_out).unwrap();

        for (i, (&got, &want)) in fast_vals.iter().zip(composed_vals.iter()).enumerate() {
            assert_eq!(
                got.to_bits(),
                want.to_bits(),
                "logit fast path changed value bits at {i}: {got} != {want}"
            );
        }
    }

    #[test]
    fn logit_propagates_gradients_through_input() {
        // tensor_logit was severed-autograd before frankentorch-1tax:
        // it extracted values and rebuilt a fresh requires_grad=false
        // leaf, dropping the gradient. After composition through
        // tensor_clamp + tensor_sub + tensor_div + tensor_log,
        // gradients flow correctly.
        //
        // d/dx logit(x) = 1 / (x * (1 - x))
        //
        // For input [0.25, 0.5, 0.75] with sum loss:
        //   grad[0] = 1 / (0.25 * 0.75) = 5.333...
        //   grad[1] = 1 / (0.5 * 0.5) = 4.0
        //   grad[2] = 1 / (0.75 * 0.25) = 5.333...
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let input = s
            .tensor_variable(vec![0.25, 0.5, 0.75], vec![3], true)
            .unwrap();
        let result = s.tensor_logit(input, None).unwrap();
        let loss = s.tensor_sum(result).unwrap();
        let report = s.tensor_backward(loss).unwrap();
        let grad = s
            .tensor_gradient(&report, input)
            .expect("logit must propagate gradient through the input");
        let expect = |x: f64| 1.0 / (x * (1.0 - x));
        for (i, (&g, &x)) in grad.iter().zip([0.25, 0.5, 0.75].iter()).enumerate() {
            let want = expect(x);
            assert!(
                (g - want).abs() < 1e-12,
                "logit grad[{i}] = {g}, expected 1/(x*(1-x)) = {want} for x={x}"
            );
        }
    }

    #[test]
    fn special_functions_match_torch() {
        // Independent oracle: torch 2.12. FT's erfinv matches a boost reference,
        // i0/digamma/lgamma their own series — verify they agree with torch.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let check = |s: &mut FrankenTorchSession, name: &str, out: TensorNodeId, want: &[f64]| {
            let got = s.tensor_values(out).unwrap();
            for (g, w) in got.iter().zip(want.iter()) {
                assert!((g - w).abs() < 1e-9, "{name}: got {got:?} want {want:?}");
            }
        };

        let xe = s
            .tensor_variable(vec![0.5, -0.3, 0.9, 0.99], vec![4], false)
            .unwrap();
        let r = s.tensor_erfinv(xe).unwrap();
        check(
            &mut s,
            "erfinv",
            r,
            &[
                0.476936276204,
                -0.272462714727,
                1.163087153677,
                1.821386367718,
            ],
        );

        let xi = s
            .tensor_variable(vec![0.5, 1.5, 3.0, 5.0], vec![4], false)
            .unwrap();
        let r = s.tensor_i0(xi).unwrap();
        check(
            &mut s,
            "i0",
            r,
            &[
                1.063483370741,
                1.646723189773,
                4.880792585865,
                27.239871823604,
            ],
        );

        let xd = s
            .tensor_variable(vec![0.5, 2.5, 5.0, 10.0], vec![4], false)
            .unwrap();
        let r = s.tensor_digamma(xd).unwrap();
        check(
            &mut s,
            "digamma",
            r,
            &[
                -1.963510026021,
                0.703156640645,
                1.506117668432,
                2.251752589067,
            ],
        );

        let xl = s
            .tensor_variable(vec![0.5, 2.5, 5.5], vec![3], false)
            .unwrap();
        let r = s.tensor_lgamma(xl).unwrap();
        check(
            &mut s,
            "lgamma",
            r,
            &[0.572364942925, 0.284682870473, 3.957813967619],
        );

        let xf = s.tensor_variable(vec![0.5, 1.5], vec![2], false).unwrap();
        let r = s.tensor_erf(xf).unwrap();
        check(&mut s, "erf", r, &[0.520499877813, 0.966105146475]);
    }

    #[test]
    fn special_functions_match_torch_extended() {
        // Independent torch 2.12 oracle for the special functions NOT covered by
        // special_functions_match_torch (i0e/i1e/ndtr/ndtri/log_ndtr/erfcx/entr/
        // polygamma/zeta). These are series/continued-fraction implementations
        // whose only prior tests were self-referential or property-based.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let check = |s: &mut FrankenTorchSession, name: &str, out: TensorNodeId, want: &[f64]| {
            let got = s.tensor_values(out).unwrap();
            assert_eq!(got.len(), want.len(), "{name} len");
            for (g, w) in got.iter().zip(want.iter()) {
                assert!((g - w).abs() < 1e-9, "{name}: got {got:?} want {want:?}");
            }
        };
        let x = vec![0.5, 1.0, 2.0, 3.0];

        let xi = s.tensor_variable(x.clone(), vec![4], false).unwrap();
        let r = s.tensor_i0e(xi).unwrap();
        check(
            &mut s,
            "i0e",
            r,
            &[
                0.6450352704491501,
                0.46575960759364043,
                0.308508322553671,
                0.24300035416182536,
            ],
        );
        let xi = s.tensor_variable(x.clone(), vec![4], false).unwrap();
        let r = s.tensor_i1e(xi).unwrap();
        check(
            &mut s,
            "i1e",
            r,
            &[
                0.15642080318487173,
                0.2079104153497085,
                0.2152692892489377,
                0.19682671329730084,
            ],
        );
        let xi = s.tensor_variable(x.clone(), vec![4], false).unwrap();
        let r = s.tensor_ndtr(xi).unwrap();
        check(
            &mut s,
            "ndtr",
            r,
            &[
                0.6914624612740131,
                0.841344746068543,
                0.9772498680518208,
                0.9986501019683699,
            ],
        );
        let xi = s.tensor_variable(x.clone(), vec![4], false).unwrap();
        let r = s.tensor_log_ndtr(xi).unwrap();
        check(
            &mut s,
            "log_ndtr",
            r,
            &[
                -0.36894641528865635,
                -0.17275377902344985,
                -0.02301290932896348,
                -0.0013508099647481923,
            ],
        );
        let xi = s.tensor_variable(x.clone(), vec![4], false).unwrap();
        let r = s.tensor_erfcx(xi).unwrap();
        check(
            &mut s,
            "erfcx",
            r,
            &[
                0.6156903441929258,
                0.427583576155807,
                0.2553956763105058,
                0.17900115118138998,
            ],
        );
        let xi = s.tensor_variable(x.clone(), vec![4], false).unwrap();
        let r = s.tensor_polygamma(2, xi).unwrap();
        check(
            &mut s,
            "polygamma2",
            r,
            &[
                -16.828796644234316,
                -2.404113806319188,
                -0.4041138063191886,
                -0.15411380631918856,
            ],
        );

        let xn = s
            .tensor_variable(vec![0.1, 0.5, 0.9], vec![3], false)
            .unwrap();
        let r = s.tensor_ndtri(xn).unwrap();
        check(
            &mut s,
            "ndtri",
            r,
            &[-1.2815515655446004, 0.0, 1.2815515655446004],
        );

        let xen = s
            .tensor_variable(vec![0.5, 0.25, 1.0], vec![3], false)
            .unwrap();
        let r = s.tensor_entr(xen).unwrap();
        check(
            &mut s,
            "entr",
            r,
            &[0.34657359027997264, 0.34657359027997264, 0.0],
        );

        let zs = s.tensor_variable(vec![2.0, 3.0], vec![2], false).unwrap();
        let za = s.tensor_variable(vec![1.0, 1.0], vec![2], false).unwrap();
        let r = s.tensor_zeta(zs, za).unwrap();
        check(&mut s, "zeta", r, &[1.6449340668482266, 1.202056903159594]);
    }

    #[test]
    fn erfinv_basic_values() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let input = s
            .tensor_variable(vec![0.0, 0.5, -0.5], vec![3], false)
            .unwrap();
        let result = s.tensor_erfinv(input).unwrap();
        let vals = s.tensor_values(result).unwrap();
        assert!((vals[0]).abs() < 1e-10, "erfinv(0) should be 0");
        // erfinv(0.5) ≈ 0.4769
        assert!(
            (vals[1] - 0.4769).abs() < 0.01,
            "erfinv(0.5) ≈ 0.4769, got {}",
            vals[1]
        );
        // Antisymmetric
        assert!(
            (vals[1] + vals[2]).abs() < 1e-10,
            "erfinv should be antisymmetric"
        );
    }

    #[test]
    fn erfinv_boundary_values() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let input = s.tensor_variable(vec![-1.0, 1.0], vec![2], false).unwrap();
        let result = s.tensor_erfinv(input).unwrap();
        let vals = s.tensor_values(result).unwrap();
        assert!(vals[0] == f64::NEG_INFINITY);
        assert!(vals[1] == f64::INFINITY);
    }

    #[test]
    fn erfinv_tail_values_match_boost_reference() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let next_before_one = f64::from_bits(0x3fefffffffffffff);
        let inputs = vec![
            0.999_999_999,
            -0.999_999_999,
            0.999_999_999_999,
            -0.999_999_999_999,
            1.0 - 1e-15,
            -(1.0 - 1e-15),
            next_before_one,
            -next_before_one,
        ];
        let expected = [
            4.320_005_388_105_362,
            -4.320_005_388_105_362,
            5.042_031_898_572_696,
            -5.042_031_898_572_696,
            5.675_915_739_744_712,
            -5.675_915_739_744_712,
            5.863_584_748_755_168,
            -5.863_584_748_755_168,
        ];
        let input = s
            .tensor_variable(inputs.clone(), vec![inputs.len()], false)
            .unwrap();
        let result = s.tensor_erfinv(input).unwrap();
        let vals = s.tensor_values(result).unwrap();

        for ((x, got), want) in inputs.iter().zip(vals.iter()).zip(expected.iter()) {
            assert!(
                (got - want).abs() <= 2e-14,
                "erfinv({x:?}) = {got:?}, want {want:?}"
            );
        }
    }

    #[test]
    fn erfinv_propagates_gradient_via_exp_y_squared() {
        // Regression test for frankentorch-1tax: tensor_erfinv used to
        // extract values, run erfinv_approx, and rebuild a
        // requires_grad=false leaf — silently severing autograd.
        // After wrapping in tensor_apply_function with the analytical
        // backward
        //     d/dx erfinv(x) = sqrt(pi)/2 * exp(erfinv(x)^2)
        // gradients flow through the input.
        //
        // Concretely with y = erfinv(x):
        //   x = 0.0 → y = 0.0 → grad = sqrt(pi)/2 * 1            ≈ 0.8862269
        //   x = 0.5 → y ≈ 0.4769362762 → grad ≈ sqrt(pi)/2 * exp(y^2) ≈ 1.1124302
        //   x =-0.5 → same grad as 0.5 (the derivative is even in y)
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let xs = [0.0, 0.5, -0.5];
        let input = s
            .tensor_variable(xs.to_vec(), vec![xs.len()], true)
            .unwrap();
        let out = s.tensor_erfinv(input).unwrap();
        let y_vals = s.tensor_values(out).unwrap();
        let loss = s.tensor_sum(out).unwrap();
        let report = s.tensor_backward(loss).unwrap();
        let grad = s
            .tensor_gradient(&report, input)
            .expect("erfinv must propagate gradient via exp(y^2) backward");

        let half_sqrt_pi = std::f64::consts::PI.sqrt() * 0.5;
        for (i, &x) in xs.iter().enumerate() {
            let y = y_vals[i];
            let expected = half_sqrt_pi * (y * y).exp();
            // erfinv_approx is Winitzki+Newton; the analytical
            // derivative is exact in y, so the only error is the y
            // approximation feeding exp(y^2). Loose 1e-6 absolute
            // tolerance (matches the precision regime of the forward
            // approximation).
            assert!(
                (grad[i] - expected).abs() < 1e-6,
                "erfinv grad[{i}] at x={x} = {g}, expected sqrt(pi)/2 * exp(y^2) = {expected} (y={y})",
                g = grad[i]
            );
        }
    }

