    #[test]
    fn i0_at_one_matches_known_value() {
        // i0(1) ≈ 1.2660658732 (standard reference).
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s.tensor_variable(vec![1.0], vec![1], false).unwrap();
        let out = s.tensor_special_i0(x).unwrap();
        let v = s.tensor_values(out).unwrap();
        // Cephes f64 expansion is ~1 ULP; tight tolerance.
        assert!(
            (v[0] - 1.2660658777520084).abs() < 1e-13,
            "i0(1) = {}",
            v[0]
        );
    }

    #[test]
    fn cephes_i_family_matches_f64_reference_values() {
        // Reference values from scipy.special (Cephes f64). Both the |x|<=8
        // Chebyshev branch and the |x|>8 asymptotic branch are exercised, to
        // catch any coefficient transcription error (which would show as ~1e-7).
        let rel = |got: f64, want: f64| (got - want).abs() <= 1e-12 * (1.0 + want.abs());
        // i0
        assert!(rel(super::bessel_i0_scalar(0.0), 1.0));
        assert!(rel(super::bessel_i0_scalar(1.0), 1.2660658777520084));
        assert!(rel(super::bessel_i0_scalar(2.0), 2.2795853023360673));
        assert!(rel(super::bessel_i0_scalar(5.0), 27.239871823604442));
        assert!(rel(super::bessel_i0_scalar(10.0), 2815.7166284662544)); // |x|>8 branch
        assert!(rel(
            super::bessel_i0_scalar(-3.0),
            super::bessel_i0_scalar(3.0)
        )); // even
        // i1
        assert!(rel(super::bessel_i1_scalar(0.0), 0.0));
        assert!(rel(super::bessel_i1_scalar(1.0), 0.5651591039924851));
        assert!(rel(super::bessel_i1_scalar(2.0), 1.5906368546373291));
        assert!(rel(super::bessel_i1_scalar(5.0), 24.335642142450524));
        assert!(rel(super::bessel_i1_scalar(10.0), 2670.988303701255)); // |x|>8 branch
        assert!(rel(super::bessel_i1_scalar(-2.0), -1.5906368546373291)); // odd
        // i0e(1) absolute (scipy), then i0e/i1e = i0/i1 · exp(-|x|) by definition
        // (i0/i1 are absolutely verified above, so this pins i0e/i1e too).
        assert!(rel(super::bessel_i0e_scalar(1.0), 0.46575960759364043));
        for &xv in &[1.0_f64, 5.0, 10.0] {
            let e = (-xv).exp();
            assert!(
                rel(
                    super::bessel_i0e_scalar(xv),
                    super::bessel_i0_scalar(xv) * e
                ),
                "i0e({xv})"
            );
            assert!(
                rel(
                    super::bessel_i1e_scalar(xv),
                    super::bessel_i1_scalar(xv) * e
                ),
                "i1e({xv})"
            );
        }
    }

    #[test]
    fn bessel_k_family_matches_f64_reference_values() {
        // K0/K1 reference values from scipy.special.kv. The previous A&S
        // polynomials were ~1.6e-7; the ascending-series branch (x <= 9) reaches
        // f64 for x <= ~5, so 1e-12 confirms the upgrade.
        let rel = |got: f64, want: f64| (got - want).abs() <= 1e-12 * (1.0 + want.abs());
        assert!(rel(super::bessel_k0_scalar(0.5), 0.9244190712276659));
        assert!(rel(super::bessel_k0_scalar(1.0), 0.42102443824070834));
        assert!(rel(super::bessel_k0_scalar(2.0), 0.11389387274953353));
        assert!(rel(super::bessel_k0_scalar(5.0), 0.0036910983340425947));
        assert!(rel(super::bessel_k1_scalar(0.5), 1.6564411200033007));
        assert!(rel(super::bessel_k1_scalar(1.0), 0.6019072301972346));
        assert!(rel(super::bessel_k1_scalar(2.0), 0.1398658818165224));
        assert!(rel(super::bessel_k1_scalar(5.0), 0.004044613445452164));
        // Scaled forms equal K·e^x.
        for &xv in &[0.5_f64, 2.0, 5.0] {
            let e = xv.exp();
            assert!(
                rel(
                    super::bessel_k0e_scalar(xv),
                    super::bessel_k0_scalar(xv) * e
                ),
                "k0e({xv})"
            );
            assert!(
                rel(
                    super::bessel_k1e_scalar(xv),
                    super::bessel_k1_scalar(xv) * e
                ),
                "k1e({xv})"
            );
        }
        // Large-x Cephes asymptotic-Chebyshev branch (x>2) is now ~1 ULP, not
        // the old ~1.5e-8 series — pin against mpmath@25dp reference values
        // (frankentorch-4ixyt).
        assert!(rel(super::bessel_k0_scalar(9.0), 5.08813129564592462e-05));
        assert!(rel(super::bessel_k1_scalar(9.0), 5.36370163794519481e-05));
        assert!(rel(super::bessel_k0_scalar(15.0), 9.81953648239643461e-08));
        assert!(rel(super::bessel_k1_scalar(15.0), 1.01417293697620920e-07));
        // Domain contract preserved: x<=0 / NaN → NaN.
        assert!(super::bessel_k0_scalar(0.0).is_nan());
        assert!(super::bessel_k1_scalar(-1.0).is_nan());
    }

    #[test]
    fn modified_bessel_i0_i1_aliases_match_torch_and_i0_i1() {
        // torch.special.modified_bessel_i0/i1 are distinct named entry points
        // with the same values as special.i0/i1 (frankentorch-9okp8). Goldens
        // from torch 2.12 (CPU, f64). i0 is even, i1 is odd.
        let xv = vec![0.5_f64, 1.0, 2.0, -1.5];
        let i0_golden = [
            1.0634833707413236,
            1.2660658777520082,
            2.279585302336067,
            1.6467231897728907,
        ];
        let i1_golden = [
            0.25789430539089636,
            0.5651591039924851,
            1.5906368546373295,
            -0.9816664285779074,
        ];
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s.tensor_variable(xv.clone(), vec![4], false).unwrap();
        let mbi0 = s.tensor_special_modified_bessel_i0(x).unwrap();
        let mbi1 = s.tensor_special_modified_bessel_i1(x).unwrap();
        let i0 = s.tensor_special_i0(x).unwrap();
        let i1 = s.tensor_special_i1(x).unwrap();
        let v_mbi0 = s.tensor_values(mbi0).unwrap();
        let v_mbi1 = s.tensor_values(mbi1).unwrap();
        let v_i0 = s.tensor_values(i0).unwrap();
        let v_i1 = s.tensor_values(i1).unwrap();
        for k in 0..4 {
            assert!(
                (v_mbi0[k] - i0_golden[k]).abs() <= 1e-12 * (1.0 + i0_golden[k].abs()),
                "modified_bessel_i0[{k}] = {}, want {}",
                v_mbi0[k],
                i0_golden[k]
            );
            assert!(
                (v_mbi1[k] - i1_golden[k]).abs() <= 1e-12 * (1.0 + i1_golden[k].abs()),
                "modified_bessel_i1[{k}] = {}, want {}",
                v_mbi1[k],
                i1_golden[k]
            );
            // Bit-exact aliases of special.i0 / special.i1.
            assert_eq!(v_mbi0[k].to_bits(), v_i0[k].to_bits());
            assert_eq!(v_mbi1[k].to_bits(), v_i1[k].to_bits());
        }
        // i1 is odd: the negative input at index 3 yields a negative value.
        assert!(v_mbi1[3] < 0.0);
    }

    #[test]
    fn special_function_first_order_gradients_match_torch() {
        // 1st-order gradient (backward) parity for the differentiable torch.special
        // ops vs torch.autograd at x=[0.1,0.3,0.5,0.7,0.9]. Goldens from torch 2.12
        // (CPU, f64). bessel_j0/j1/y0/k0 are NOT differentiable in torch (raise), so
        // they are excluded — ft provides correct analytic gradients for them anyway.
        // frankentorch-yt74t.
        let xs = vec![0.1f64, 0.3, 0.5, 0.7, 0.9];
        macro_rules! grad_eq {
            ($name:literal, $m:ident, $golden:expr) => {{
                let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
                let x = s.tensor_variable(xs.clone(), vec![5], true).unwrap();
                let y = s.$m(x).unwrap();
                let loss = s.tensor_sum(y).unwrap();
                let report = s.tensor_backward(loss).unwrap();
                let g = s.tensor_gradient(&report, x).expect($name);
                let want: [f64; 5] = $golden;
                for i in 0..5 {
                    assert!(
                        (g[i] - want[i]).abs() <= 1e-9 * (1.0 + want[i].abs()),
                        "{} grad[{}] = {}, want {}",
                        $name,
                        i,
                        g[i],
                        want[i]
                    );
                }
            }};
        }
        grad_eq!(
            "i0",
            tensor_special_i0,
            [
                5.006252604709269e-2,
                1.516938400035928e-1,
                2.578943053908964e-1,
                3.718796777770085e-1,
                4.971264481609644e-1
            ]
        );
        grad_eq!(
            "i1",
            tensor_special_i1,
            [
                5.018763024631687e-1,
                5.169807460062873e-1,
                5.476947599595309e-1,
                5.950463357682256e-1,
                6.606224455498352e-1
            ]
        );
        grad_eq!(
            "i0e",
            tensor_special_i0e,
            [
                -8.618024789734917e-1,
                -6.452030645427088e-1,
                -4.886144672642784e-1,
                -3.746355437443211e-1,
                -2.910464352238495e-1
            ]
        );
        grad_eq!(
            "i1e",
            tensor_special_i1e,
            [
                4.088180108853985e-1,
                2.706111957432461e-1,
                1.757728608945349e-1,
                1.108212826546821e-1,
                6.647251202734306e-2
            ]
        );
        grad_eq!(
            "erf",
            tensor_erf,
            [
                1.117151606788937e0,
                1.031260909618963e0,
                8.787825789354448e-1,
                6.912748604105386e-1,
                5.019685742403627e-1
            ]
        );
        grad_eq!(
            "erfc",
            tensor_erfc,
            [
                -1.117151606788937e0,
                -1.031260909618963e0,
                -8.787825789354448e-1,
                -6.912748604105386e-1,
                -5.019685742403627e-1
            ]
        );
        grad_eq!(
            "erfinv",
            tensor_special_erfinv,
            [
                8.932517253051874e-1,
                9.545203588405493e-1,
                1.112584818971950e0,
                1.516363217333764e0,
                3.428042811451842e0
            ]
        );
        grad_eq!(
            "erfcx",
            tensor_special_erfcx,
            [
                -9.490877711016872e-1,
                -6.876195663549194e-1,
                -5.126888229025868e-1,
                -3.920766948062953e-1,
                -3.066221947139020e-1
            ]
        );
        grad_eq!(
            "ndtr",
            tensor_special_ndtr,
            [
                3.969525474770118e-1,
                3.813878154605241e-1,
                3.520653267642995e-1,
                3.122539333667613e-1,
                2.660852498987548e-1
            ]
        );
        grad_eq!(
            "log_ndtr",
            tensor_special_log_ndtr,
            [
                7.353317485057806e-1,
                6.172208536127346e-1,
                5.091604338370335e-1,
                4.119247504192907e-1,
                3.261088937611196e-1
            ]
        );
        grad_eq!(
            "gammaln",
            tensor_special_gammaln,
            [
                -1.042375494041108e1,
                -3.502524222200133e0,
                -1.963510026021423e0,
                -1.220023553697935e0,
                -7.549269499470513e-1
            ]
        );
        grad_eq!(
            "digamma",
            tensor_special_digamma,
            [
                1.014332991498946e2,
                1.224536454494037e1,
                4.934802202073678e0,
                2.834049157861975e0,
                1.922539960375435e0
            ]
        );
        grad_eq!(
            "entr",
            tensor_special_entr,
            [
                1.302585092994045e0,
                2.039728043259361e-1,
                -3.068528194400547e-1,
                -6.433250560612676e-1,
                -8.946394843421737e-1
            ]
        );
    }

    #[test]
    fn bessel_jy_family_matches_f64_reference_values() {
        // Reference values from scipy.special (= libm = torch). The previous
        // Numerical-Recipes polynomials were only ~1e-7, so a 1e-12 tolerance
        // both confirms the libm upgrade and guards against regressions.
        let rel = |got: f64, want: f64| (got - want).abs() <= 1e-12 * (1.0 + want.abs());
        // J0 / J1 (entire; check small-x, large-x and sign behaviour).
        assert!(rel(super::bessel_j0_scalar(0.0), 1.0));
        assert!(rel(super::bessel_j0_scalar(1.0), 0.7651976865579666));
        assert!(rel(super::bessel_j0_scalar(5.0), -0.17759677131433826));
        assert!(rel(
            super::bessel_j0_scalar(-1.0),
            super::bessel_j0_scalar(1.0)
        )); // even
        assert!(rel(super::bessel_j1_scalar(0.0), 0.0));
        assert!(rel(super::bessel_j1_scalar(1.0), 0.4400505857449335));
        assert!(rel(super::bessel_j1_scalar(5.0), -0.3275791375914652));
        assert!(rel(
            super::bessel_j1_scalar(-2.0),
            -super::bessel_j1_scalar(2.0)
        )); // odd
        // Y0 / Y1 (x > 0; x <= 0 and NaN are NaN by contract).
        assert!(rel(super::bessel_y0_scalar(1.0), 0.08825696421567697));
        assert!(rel(super::bessel_y0_scalar(5.0), -0.30851762524903303));
        assert!(rel(super::bessel_y1_scalar(1.0), -0.7812128213002887));
        assert!(rel(super::bessel_y1_scalar(5.0), 0.14786314339122683));
        assert!(super::bessel_y0_scalar(-1.0).is_nan());
        assert!(super::bessel_y0_scalar(0.0).is_nan());
        assert!(super::bessel_y1_scalar(f64::NAN).is_nan());
    }

    #[test]
    fn complex_transcendental_and_prod_match_torch() {
        // torch supports tan/tanh/sinh/cosh/asin/acos/atan + prod on complex; ft's
        // unary/reduction dispatch rejected them. frankentorch-h9bxr (vs torch 2.12).
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let cx = |s: &mut FrankenTorchSession| {
            let r = s.tensor_variable(vec![0.5, 1.0], vec![2], false).unwrap();
            let i = s.tensor_variable(vec![0.3, -0.5], vec![2], false).unwrap();
            s.tensor_complex(r, i).unwrap()
        };
        let approx = |s: &mut FrankenTorchSession, c, want_re: &[f64], want_im: &[f64]| {
            let rn = s.tensor_real(c).unwrap();
            let re = s.tensor_values(rn).unwrap();
            let inn = s.tensor_imag(c).unwrap();
            let im = s.tensor_values(inn).unwrap();
            let ok = |a: &[f64], b: &[f64]| {
                a.len() == b.len() && a.iter().zip(b).all(|(x, y)| (x - y).abs() < 1e-12)
            };
            assert!(ok(&re, want_re) && ok(&im, want_im));
        };
        let c = cx(&mut s);
        let r = s.tensor_tanh(c).unwrap();
        approx(
            &mut s,
            r,
            &[0.49619706577350764, 0.8429662048457832],
            &[0.23840508333812327, -0.19557731006593398],
        );
        let c = cx(&mut s);
        let r = s.tensor_asin(c).unwrap();
        approx(
            &mut s,
            r,
            &[0.4930392405856185, 0.8959074812088903],
            &[0.3342998177749379, -0.7328576759736453],
        );
        // sinh/cosh/tan/acos/atan route through the same helper (type-checked):
        for op in 0..5 {
            let c = cx(&mut s);
            let r = match op {
                0 => s.tensor_sinh(c),
                1 => s.tensor_cosh(c),
                2 => s.tensor_tan(c),
                3 => s.tensor_acos(c),
                _ => s.tensor_atan(c),
            }
            .unwrap();
            assert_eq!(s.tensor_dtype(r).unwrap(), DType::Complex128);
        }
        // prod((0.5+0.3i)(1-0.5i)) = 0.65 + 0.05i.
        let c = cx(&mut s);
        let p = s.tensor_prod(c).unwrap();
        approx(&mut s, p, &[0.65], &[0.05]);
        // real-dtype tanh/prod still delegate (unchanged): prod([2,3])=6.
        let r = s.tensor_variable(vec![2.0, 3.0], vec![2], false).unwrap();
        let rp = s.tensor_prod(r).unwrap();
        assert_eq!(s.tensor_values(rp).unwrap(), vec![6.0]);
    }

    #[test]
    fn complex_unary_and_reduce_match_torch() {
        // torch supports log/sqrt/sin/cos/reciprocal + sum/mean on complex; ft's
        // unary/reduction dispatch rejected them. frankentorch-pohu8. Verified
        // vs torch 2.12. (sgn/angle stay deferred: naub/66hu.)
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let cx = |s: &mut FrankenTorchSession| {
            let r = s.tensor_variable(vec![1.0, 2.0], vec![2], false).unwrap();
            let i = s.tensor_variable(vec![2.0, -1.0], vec![2], false).unwrap();
            s.tensor_complex(r, i).unwrap()
        };
        let re = |s: &mut FrankenTorchSession, c| {
            let n = s.tensor_real(c).unwrap();
            s.tensor_values(n).unwrap()
        };
        let im = |s: &mut FrankenTorchSession, c| {
            let n = s.tensor_imag(c).unwrap();
            s.tensor_values(n).unwrap()
        };
        let approx = |a: &[f64], b: &[f64]| {
            a.len() == b.len() && a.iter().zip(b).all(|(x, y)| (x - y).abs() < 1e-12)
        };
        // log(1+2i) = 0.80472 + 1.10715i; log(2-i) = 0.80472 - 0.46365i.
        let c = cx(&mut s);
        let l = s.tensor_log(c).unwrap();
        assert!(approx(
            &re(&mut s, l),
            &[0.8047189562170503, 0.8047189562170503]
        ));
        assert!(approx(
            &im(&mut s, l),
            &[1.1071487177940904, -0.4636476090008061]
        ));
        // reciprocal(1+2i) = 0.2 - 0.4i.
        let c = cx(&mut s);
        let r = s.tensor_reciprocal(c).unwrap();
        assert!(approx(&re(&mut s, r), &[0.2, 0.4]));
        assert!(approx(&im(&mut s, r), &[-0.4, 0.2]));
        // sqrt is complex-typed; sin/cos route through the helper too.
        let c = cx(&mut s);
        let q = s.tensor_sqrt(c).unwrap();
        assert_eq!(s.tensor_dtype(q).unwrap(), DType::Complex128);
        let c = cx(&mut s);
        let sn = s.tensor_sin(c).unwrap();
        assert_eq!(s.tensor_dtype(sn).unwrap(), DType::Complex128);
        let c = cx(&mut s);
        let cs = s.tensor_cos(c).unwrap();
        assert_eq!(s.tensor_dtype(cs).unwrap(), DType::Complex128);
        // sum = (1+2i)+(2-i) = 3+1i ; mean = 1.5+0.5i.
        let c = cx(&mut s);
        let sm = s.tensor_sum(c).unwrap();
        assert!(approx(&re(&mut s, sm), &[3.0]) && approx(&im(&mut s, sm), &[1.0]));
        let c = cx(&mut s);
        let mn = s.tensor_mean(c).unwrap();
        assert!(approx(&re(&mut s, mn), &[1.5]) && approx(&im(&mut s, mn), &[0.5]));
        // real-dtype paths still delegate (unchanged): log(e)=1, sum=6.
        let r = s
            .tensor_variable(vec![1.0, 2.0, 3.0], vec![3], false)
            .unwrap();
        let rs = s.tensor_sum(r).unwrap();
        assert_eq!(s.tensor_values(rs).unwrap(), vec![6.0]);
    }

    #[test]
    fn complex_abs_neg_exp_match_torch() {
        // torch.abs/neg/exp support complex; ft's unary dispatch rejected them.
        // frankentorch-b91f3. Verified vs torch 2.12.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let cx = |s: &mut FrankenTorchSession| {
            let r = s.tensor_variable(vec![3.0, -1.0], vec![2], false).unwrap();
            let i = s.tensor_variable(vec![4.0, 0.0], vec![2], false).unwrap();
            s.tensor_complex(r, i).unwrap()
        };
        // abs: |3+4i|=5, |-1+0i|=1 (real output).
        let c = cx(&mut s);
        let a = s.tensor_abs(c).unwrap();
        assert_eq!(s.tensor_dtype(a).unwrap(), DType::F64);
        assert_eq!(s.tensor_values(a).unwrap(), vec![5.0, 1.0]);
        // neg: -(3+4i)=(-3-4i).
        let c = cx(&mut s);
        let ng = s.tensor_neg(c).unwrap();
        assert_eq!(s.tensor_dtype(ng).unwrap(), DType::Complex128);
        let re = s.tensor_real(ng).unwrap();
        let im = s.tensor_imag(ng).unwrap();
        assert_eq!(s.tensor_values(re).unwrap(), vec![-3.0, 1.0]);
        assert_eq!(s.tensor_values(im).unwrap(), vec![-4.0, 0.0]);
        // exp: e^(3+4i) re = e^3*cos4 ≈ -13.128..., im = e^3*sin4 ≈ -15.200...
        let c = cx(&mut s);
        let ex = s.tensor_exp(c).unwrap();
        assert_eq!(s.tensor_dtype(ex).unwrap(), DType::Complex128);
        let re_node = s.tensor_real(ex).unwrap();
        let re = s.tensor_values(re_node).unwrap();
        assert!((re[0] - 3.0_f64.exp() * 4.0_f64.cos()).abs() < 1e-12);
        // real-dtype abs/neg/exp still delegate (unchanged): abs(-2.0)=2.
        let r = s.tensor_variable(vec![-2.0, 3.0], vec![2], false).unwrap();
        let ra = s.tensor_abs(r).unwrap();
        assert_eq!(s.tensor_dtype(ra).unwrap(), DType::F64);
        assert_eq!(s.tensor_values(ra).unwrap(), vec![2.0, 3.0]);
    }

    #[test]
    fn repeat_interleave_repeats_tensor_matches_torch() {
        // torch.repeat_interleave(input, repeats: Tensor, dim) — the repeats-tensor
        // form. frankentorch-c5d3a. Verified vs torch 2.12.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let v = |s: &mut FrankenTorchSession, d: Vec<f64>, sh: Vec<usize>| {
            s.tensor_variable(d, sh, false).unwrap()
        };
        // 1-D per-element repeats.
        let x = v(&mut s, vec![1.0, 2.0, 3.0], vec![3]);
        let reps = v(&mut s, vec![1.0, 2.0, 3.0], vec![3]);
        let r = s.tensor_repeat_interleave_repeats(x, reps, None).unwrap();
        assert_eq!(
            s.tensor_values(r).unwrap(),
            vec![1.0, 2.0, 2.0, 3.0, 3.0, 3.0]
        );
        // scalar repeats tensor broadcasts to a uniform count.
        let x = v(&mut s, vec![1.0, 2.0, 3.0], vec![3]);
        let sc = v(&mut s, vec![2.0], vec![1]);
        let r = s.tensor_repeat_interleave_repeats(x, sc, None).unwrap();
        assert_eq!(
            s.tensor_values(r).unwrap(),
            vec![1.0, 1.0, 2.0, 2.0, 3.0, 3.0]
        );
        // per-slice repeats along dim 0.
        let y = v(&mut s, vec![1.0, 2.0, 3.0, 4.0], vec![2, 2]);
        let reps = v(&mut s, vec![1.0, 2.0], vec![2]);
        let r = s
            .tensor_repeat_interleave_repeats(y, reps, Some(0))
            .unwrap();
        assert_eq!(s.tensor_shape(r).unwrap(), vec![3, 2]);
        assert_eq!(
            s.tensor_values(r).unwrap(),
            vec![1.0, 2.0, 3.0, 4.0, 3.0, 4.0]
        );
        // negative / non-integer repeats error.
        let x = v(&mut s, vec![1.0, 2.0], vec![2]);
        let bad = v(&mut s, vec![1.0, -1.0], vec![2]);
        assert!(s.tensor_repeat_interleave_repeats(x, bad, None).is_err());
    }

    #[test]
    fn masked_select_broadcasts_mask_like_torch() {
        // torch.masked_select broadcasts input and mask to a common shape, then
        // selects row-major. ft used to require equal numel. frankentorch-ucxgj.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        // mask broadcast: input [2,3], mask [2,1] -> selects row 0 = [1,2,3].
        let a = s
            .tensor_variable((1..=6).map(|i| i as f64).collect(), vec![2, 3], true)
            .unwrap();
        let m = s
            .tensor_variable(vec![1.0, 0.0], vec![2, 1], false)
            .unwrap();
        let r = s.tensor_masked_select(a, m).unwrap();
        assert_eq!(s.tensor_values(r).unwrap(), vec![1.0, 2.0, 3.0]);
        // grad flows to the selected positions only.
        let loss = s.tensor_sum(r).unwrap();
        s.tensor_backward(loss).unwrap();
        assert_eq!(
            s.tensor_grad(a).unwrap().unwrap(),
            vec![1.0, 1.0, 1.0, 0.0, 0.0, 0.0]
        );
        // input broadcast: input [1,3], mask [2,3] -> [10,30,20].
        let a = s
            .tensor_variable(vec![10.0, 20.0, 30.0], vec![1, 3], false)
            .unwrap();
        let m = s
            .tensor_variable(vec![1.0, 0.0, 1.0, 0.0, 1.0, 0.0], vec![2, 3], false)
            .unwrap();
        let r = s.tensor_masked_select(a, m).unwrap();
        assert_eq!(s.tensor_values(r).unwrap(), vec![10.0, 30.0, 20.0]);
        // equal-shape path unchanged.
        let a = s
            .tensor_variable(vec![1.0, 2.0, 3.0, 4.0], vec![4], false)
            .unwrap();
        let m = s
            .tensor_variable(vec![1.0, 0.0, 1.0, 1.0], vec![4], false)
            .unwrap();
        let r = s.tensor_masked_select(a, m).unwrap();
        assert_eq!(s.tensor_values(r).unwrap(), vec![1.0, 3.0, 4.0]);
        // non-broadcastable shapes still error.
        let a = s
            .tensor_variable(vec![1.0, 2.0, 3.0], vec![3], false)
            .unwrap();
        let m = s.tensor_variable(vec![1.0, 0.0], vec![2], false).unwrap();
        assert!(s.tensor_masked_select(a, m).is_err());
    }

    #[test]
    fn tensordot_axis_list_matches_torch() {
        // torch.tensordot(a, b, dims=(a_dims, b_dims)) — axis-list contraction.
        // frankentorch-ctkju. Verified vs torch 2.12 (fwd incl reordered axes + bwd).
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let v = |s: &mut FrankenTorchSession, sh: Vec<usize>, rg: bool| {
            let n: usize = sh.iter().product();
            s.tensor_variable((1..=n).map(|i| i as f64).collect(), sh, rg)
                .unwrap()
        };
        // contract a[1,2] with b[0,1] -> [3,6].
        let a = v(&mut s, vec![3, 4, 5], false);
        let b = v(&mut s, vec![4, 5, 6], false);
        let r = s.tensor_tensordot_dims(a, b, &[1, 2], &[0, 1]).unwrap();
        assert_eq!(s.tensor_shape(r).unwrap(), vec![3, 6]);
        assert_eq!(s.tensor_values(r).unwrap().iter().sum::<f64>(), 736110.0);
        // reordered + negative axes: a[0,2] with b[1,0] -> [3].
        let a = v(&mut s, vec![2, 3, 4], false);
        let b = v(&mut s, vec![4, 2], false);
        let r = s.tensor_tensordot_dims(a, b, &[0, -1], &[-1, 0]).unwrap();
        assert_eq!(s.tensor_shape(r).unwrap(), vec![3]);
        assert_eq!(s.tensor_values(r).unwrap().iter().sum::<f64>(), 1482.0);
        // backward matches torch (21780, 10980).
        let a = v(&mut s, vec![3, 4, 5], true);
        let b = v(&mut s, vec![4, 5, 6], true);
        let r = s.tensor_tensordot_dims(a, b, &[1, 2], &[0, 1]).unwrap();
        let loss = s.tensor_sum(r).unwrap();
        s.tensor_backward(loss).unwrap();
        assert_eq!(
            s.tensor_grad(a).unwrap().unwrap().iter().sum::<f64>(),
            21780.0
        );
        assert_eq!(
            s.tensor_grad(b).unwrap().unwrap().iter().sum::<f64>(),
            10980.0
        );
        // mismatched-length dim lists error.
        let a = v(&mut s, vec![2, 3], false);
        let b = v(&mut s, vec![3, 2], false);
        assert!(s.tensor_tensordot_dims(a, b, &[1], &[0, 1]).is_err());
    }

    #[test]
    fn einsum_ellipsis_matches_torch() {
        // torch.einsum ellipsis ('...') support; ft used to reject it.
        // frankentorch-s3iig. Verified vs torch 2.12 (fwd shapes/sums + bwd grads).
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let v = |s: &mut FrankenTorchSession, sh: Vec<usize>, rg: bool| {
            let n: usize = sh.iter().product();
            s.tensor_variable((0..n).map(|i| i as f64).collect(), sh, rg)
                .unwrap()
        };
        // batched matmul via ellipsis.
        let a = v(&mut s, vec![2, 3, 4], false);
        let b = v(&mut s, vec![2, 4, 5], false);
        let r = s.tensor_einsum("...ij,...jk->...ik", &[a, b]).unwrap();
        assert_eq!(s.tensor_shape(r).unwrap(), vec![2, 3, 5]);
        assert_eq!(s.tensor_values(r).unwrap().iter().sum::<f64>(), 34860.0);
        // broadcast (rhs has no batch dim).
        let a = v(&mut s, vec![2, 3, 4], false);
        let b = v(&mut s, vec![4, 5], false);
        let r = s.tensor_einsum("...ij,jk->...ik", &[a, b]).unwrap();
        assert_eq!(s.tensor_shape(r).unwrap(), vec![2, 3, 5]);
        assert_eq!(s.tensor_values(r).unwrap().iter().sum::<f64>(), 13860.0);
        // batched diagonal + implicit-output ellipsis sum.
        let a = v(&mut s, vec![2, 3, 3], false);
        let r = s.tensor_einsum("...ii->...i", &[a]).unwrap();
        assert_eq!(s.tensor_shape(r).unwrap(), vec![2, 3]);
        assert_eq!(s.tensor_values(r).unwrap().iter().sum::<f64>(), 51.0);
        // non-ellipsis path unchanged.
        let a = v(&mut s, vec![2, 3], false);
        let b = v(&mut s, vec![3, 4], false);
        let r = s.tensor_einsum("ij,jk->ik", &[a, b]).unwrap();
        assert_eq!(s.tensor_shape(r).unwrap(), vec![2, 4]);
        // backward through ellipsis batched matmul matches torch (2340, 1380).
        let a = v(&mut s, vec![2, 3, 4], true);
        let b = v(&mut s, vec![2, 4, 5], true);
        let r = s.tensor_einsum("...ij,...jk->...ik", &[a, b]).unwrap();
        let loss = s.tensor_sum(r).unwrap();
        s.tensor_backward(loss).unwrap();
        assert_eq!(
            s.tensor_grad(a).unwrap().unwrap().iter().sum::<f64>(),
            2340.0
        );
        assert_eq!(
            s.tensor_grad(b).unwrap().unwrap().iter().sum::<f64>(),
            1380.0
        );
    }

    #[test]
    fn matmul_shape_polymorphism_matches_torch() {
        // torch.matmul is shape-polymorphic; tensor_matmul used to support only
        // 2D·2D. Verified vs torch 2.12 (forward shapes/values + backward grads).
        // frankentorch-6tzgt.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let mk = |s: &mut FrankenTorchSession, sh: Vec<usize>, rg: bool| {
            let n: usize = sh.iter().product();
            s.tensor_variable((0..n).map(|i| i as f64).collect(), sh, rg)
                .unwrap()
        };
        // 1D·2D -> [n]; 2D·1D -> [m]; batched 3D·3D; broadcast 3D·2D.
        let a = mk(&mut s, vec![4], false);
        let b = mk(&mut s, vec![4, 3], false);
        let r = s.tensor_matmul(a, b).unwrap();
        assert_eq!(s.tensor_shape(r).unwrap(), vec![3]);
        let a = mk(&mut s, vec![3, 4], false);
        let b = mk(&mut s, vec![4], false);
        let r = s.tensor_matmul(a, b).unwrap();
        assert_eq!(s.tensor_shape(r).unwrap(), vec![3]);
        let a = mk(&mut s, vec![2, 3, 4], false);
        let b = mk(&mut s, vec![2, 4, 5], false);
        let r = s.tensor_matmul(a, b).unwrap();
        assert_eq!(s.tensor_shape(r).unwrap(), vec![2, 3, 5]);
        assert_eq!(s.tensor_values(r).unwrap().iter().sum::<f64>(), 34860.0);
        let a = mk(&mut s, vec![2, 3, 4], false);
        let b = mk(&mut s, vec![4, 5], false); // broadcast batch
        let r = s.tensor_matmul(a, b).unwrap();
        assert_eq!(s.tensor_shape(r).unwrap(), vec![2, 3, 5]);
        // 2D·2D unchanged.
        let a = mk(&mut s, vec![3, 4], false);
        let b = mk(&mut s, vec![4, 5], false);
        let r = s.tensor_matmul(a, b).unwrap();
        assert_eq!(s.tensor_shape(r).unwrap(), vec![3, 5]);
        // backward through batched matmul matches torch grad sums for these
        // 0-based inputs (torch 2.12: grad_a=2340, grad_b=1380).
        let a = mk(&mut s, vec![2, 3, 4], true);
        let b = mk(&mut s, vec![2, 4, 5], true);
        let r = s.tensor_matmul(a, b).unwrap();
        let loss = s.tensor_sum(r).unwrap();
        s.tensor_backward(loss).unwrap();
        assert_eq!(
            s.tensor_grad(a).unwrap().unwrap().iter().sum::<f64>(),
            2340.0
        );
        assert_eq!(
            s.tensor_grad(b).unwrap().unwrap().iter().sum::<f64>(),
            1380.0
        );
    }

    #[test]
    fn tuple_factorizations_preserve_f32_dtype() {
        // torch keeps the input float dtype on EVERY tensor output of the
        // multi-output factorizations (eigh/svd/qr/lu). frankentorch-clqek.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let spd = |s: &mut FrankenTorchSession| {
            s.tensor_variable_f32(
                vec![4.0, 1.0, 0.0, 1.0, 3.0, 1.0, 0.0, 1.0, 2.0],
                vec![3, 3],
                false,
            )
            .unwrap()
        };
        let rect = |s: &mut FrankenTorchSession| {
            s.tensor_variable_f32(vec![1.0, 0.0, 0.0, 1.0, 1.0, 1.0], vec![3, 2], false)
                .unwrap()
        };
        let dt = |s: &mut FrankenTorchSession, r| s.tensor_dtype(r).unwrap();
        let m = spd(&mut s);
        let (v, q) = s.tensor_linalg_eigh(m).unwrap();
        assert_eq!(dt(&mut s, v), DType::F32);
        assert_eq!(dt(&mut s, q), DType::F32);
        let m = rect(&mut s);
        let (u, sv, vh) = s.tensor_linalg_svd(m, false).unwrap();
        assert_eq!(dt(&mut s, u), DType::F32);
        assert_eq!(dt(&mut s, sv), DType::F32);
        assert_eq!(dt(&mut s, vh), DType::F32);
        let m = rect(&mut s);
        let (qq, rr) = s.tensor_linalg_qr(m, false).unwrap();
        assert_eq!(dt(&mut s, qq), DType::F32);
        assert_eq!(dt(&mut s, rr), DType::F32);
        let m = spd(&mut s);
        let (p, l, u) = s.tensor_linalg_lu(m).unwrap();
        assert_eq!(dt(&mut s, p), DType::F32);
        assert_eq!(dt(&mut s, l), DType::F32);
        assert_eq!(dt(&mut s, u), DType::F32);
        let m = spd(&mut s);
        let (lu, _piv) = s.tensor_lu_factor(m).unwrap();
        assert_eq!(dt(&mut s, lu), DType::F32);
        // f64 path unchanged.
        let m64 = s
            .tensor_variable(
                vec![4.0, 1.0, 0.0, 1.0, 3.0, 1.0, 0.0, 1.0, 2.0],
                vec![3, 3],
                false,
            )
            .unwrap();
        let (v64, _) = s.tensor_linalg_eigh(m64).unwrap();
        assert_eq!(dt(&mut s, v64), DType::F64);
    }

    #[test]
    fn linalg_factorizations_preserve_f32_dtype() {
        // torch keeps the input float dtype: eigvalsh/cholesky/linalg_solve/lstsq
        // read f64-only. frankentorch-aqllp.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let spd = |s: &mut FrankenTorchSession| {
            s.tensor_variable_f32(
                vec![4.0, 1.0, 0.0, 1.0, 3.0, 1.0, 0.0, 1.0, 2.0],
                vec![3, 3],
                false,
            )
            .unwrap()
        };
        let dt = |s: &mut FrankenTorchSession, r| s.tensor_dtype(r).unwrap();
        let m = spd(&mut s);
        let r = s.tensor_eigvalsh(m).unwrap();
        assert_eq!(dt(&mut s, r), DType::F32);
        let m = spd(&mut s);
        let r = s.tensor_cholesky(m, false).unwrap();
        assert_eq!(dt(&mut s, r), DType::F32);
        let m = spd(&mut s);
        let b = s
            .tensor_variable_f32(vec![1.0, 2.0, 3.0], vec![3, 1], false)
            .unwrap();
        let r = s.tensor_linalg_solve(m, b).unwrap();
        assert_eq!(dt(&mut s, r), DType::F32);
        let a = s
            .tensor_variable_f32(vec![1.0, 0.0, 0.0, 1.0, 1.0, 1.0], vec![3, 2], false)
            .unwrap();
        let b = s
            .tensor_variable_f32(vec![1.0, 2.0, 3.0], vec![3, 1], false)
            .unwrap();
        let r = s.tensor_lstsq(a, b).unwrap();
        assert_eq!(dt(&mut s, r), DType::F32);
        // mixed f32 A + f64 b promotes to f64; f64 path unchanged.
        let m = spd(&mut s);
        let b64 = s
            .tensor_variable(vec![1.0, 2.0, 3.0], vec![3, 1], false)
            .unwrap();
        let r = s.tensor_linalg_solve(m, b64).unwrap();
        assert_eq!(dt(&mut s, r), DType::F64);
    }

    #[test]
    fn linalg_ops_preserve_f32_dtype() {
        // torch keeps the input float dtype: pinv/matrix_exp/logdet read f64-only,
        // matrix_power upcast to F64. frankentorch-h9ghv.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let spd = |s: &mut FrankenTorchSession| {
            s.tensor_variable_f32(
                vec![4.0, 1.0, 0.0, 1.0, 3.0, 1.0, 0.0, 1.0, 2.0],
                vec![3, 3],
                false,
            )
            .unwrap()
        };
        let dt = |s: &mut FrankenTorchSession, r| s.tensor_dtype(r).unwrap();
        let m = spd(&mut s);
        let r = s.tensor_pinv(m).unwrap();
        assert_eq!(dt(&mut s, r), DType::F32);
        let m = spd(&mut s);
        let r = s.tensor_matrix_power(m, 3).unwrap();
        assert_eq!(dt(&mut s, r), DType::F32);
        let m = spd(&mut s);
        let r = s.tensor_matrix_exp(m).unwrap();
        assert_eq!(dt(&mut s, r), DType::F32);
        let m = spd(&mut s);
        let r = s.tensor_logdet(m).unwrap();
        assert_eq!(dt(&mut s, r), DType::F32);
        // slogdet (both outputs) and f64 unchanged.
        let m = spd(&mut s);
        let (sign, logabs) = s.tensor_linalg_slogdet(m).unwrap();
        assert_eq!(dt(&mut s, sign), DType::F32);
        assert_eq!(dt(&mut s, logabs), DType::F32);
        let m64 = s
            .tensor_variable(
                vec![4.0, 1.0, 0.0, 1.0, 3.0, 1.0, 0.0, 1.0, 2.0],
                vec![3, 3],
                false,
            )
            .unwrap();
        let r = s.tensor_logdet(m64).unwrap();
        assert_eq!(dt(&mut s, r), DType::F64);
        // logdet(SPD) > 0; value sane (det = 4*5-1*2 = 18 for this matrix).
        assert!((s.tensor_values_lossy_f64(r).unwrap()[0] - 18.0_f64.ln()).abs() < 1e-9);
    }

    #[test]
    fn binary_special_and_airy_preserve_f32_dtype() {
        // torch keeps the input float dtype: airy_ai + igamma/igammac read
        // f64-only; xlog1py/rel_entr built full() F64 constants. frankentorch-77o4c.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let f4 = |s: &mut FrankenTorchSession, v: Vec<f32>| {
            s.tensor_variable_f32(v, vec![4], false).unwrap()
        };
        let p = || vec![0.5f32, 1.0, 2.0, 3.0];
        let dt = |s: &mut FrankenTorchSession, r| s.tensor_dtype(r).unwrap();
        let t = f4(&mut s, p());
        let r = s.tensor_special_airy_ai(t).unwrap();
        assert_eq!(dt(&mut s, r), DType::F32);
        let (x, y) = (f4(&mut s, p()), f4(&mut s, p()));
        let r = s.tensor_xlog1py(x, y).unwrap();
        assert_eq!(dt(&mut s, r), DType::F32);
        let (x, y) = (f4(&mut s, p()), f4(&mut s, p()));
        let r = s.tensor_rel_entr(x, y).unwrap();
        assert_eq!(dt(&mut s, r), DType::F32);
        let (sx, ax) = (f4(&mut s, vec![2.0, 3.0, 4.0, 5.0]), f4(&mut s, p()));
        let r = s.tensor_special_zeta(sx, ax).unwrap();
        assert_eq!(dt(&mut s, r), DType::F32);
        let (x, y) = (f4(&mut s, p()), f4(&mut s, p()));
        let r = s.tensor_special_gammainc(x, y).unwrap();
        assert_eq!(dt(&mut s, r), DType::F32);
        let (x, y) = (f4(&mut s, p()), f4(&mut s, p()));
        let r = s.tensor_special_gammaincc(x, y).unwrap();
        assert_eq!(dt(&mut s, r), DType::F32);
        // mixed f32+f64 promotes to f64; f64+f64 stays f64 (path unchanged).
        let x32 = f4(&mut s, p());
        let y64 = s
            .tensor_variable(vec![1.0, 2.0, 3.0, 4.0], vec![4], false)
            .unwrap();
        let r = s.tensor_xlog1py(x32, y64).unwrap();
        assert_eq!(dt(&mut s, r), DType::F64);
        let x64 = s
            .tensor_variable(vec![1.0, 2.0, 3.0, 4.0], vec![4], false)
            .unwrap();
        let y64b = s
            .tensor_variable(vec![1.0, 2.0, 3.0, 4.0], vec![4], false)
            .unwrap();
        let r = s.tensor_xlog1py(x64, y64b).unwrap();
        assert_eq!(dt(&mut s, r), DType::F64);
    }

    #[test]
    fn activations_and_special_preserve_f32_dtype() {
        // torch keeps the input float dtype: selu/relu6/celu errored on f32
        // (f64-only borrowed-inputs path), entr failed a dtype-matched comparison,
        // logit upcast via a full() F64 constant. frankentorch-x9yuq.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let mk = |s: &mut FrankenTorchSession, v: Vec<f32>| {
            s.tensor_variable_f32(v, vec![4], false).unwrap()
        };
        let g = || vec![-1.0f32, 0.5, 1.0, 2.0];
        let t = mk(&mut s, g());
        let r = s.tensor_selu(t).unwrap();
        assert_eq!(s.tensor_dtype(r).unwrap(), DType::F32);
        let t = mk(&mut s, vec![-1.0f32, 2.0, 5.0, 8.0]);
        let r = s.tensor_relu6(t).unwrap();
        assert_eq!(s.tensor_dtype(r).unwrap(), DType::F32);
        let t = mk(&mut s, g());
        let r = s.tensor_celu(t, 1.0).unwrap();
        assert_eq!(s.tensor_dtype(r).unwrap(), DType::F32);
        let t = mk(&mut s, vec![0.1f32, 0.3, 0.5, 0.9]);
        let r = s.tensor_special_entr(t).unwrap();
        assert_eq!(s.tensor_dtype(r).unwrap(), DType::F32);
        let t = mk(&mut s, vec![0.1f32, 0.3, 0.5, 0.9]);
        let r = s.tensor_logit(t, None).unwrap();
        assert_eq!(s.tensor_dtype(r).unwrap(), DType::F32);
        // relu6(8.0) == 6.0 exactly in f32; f64 path unchanged (selu(1.0)=1.0507...).
        let t6 = mk(&mut s, vec![8.0f32, 8.0, 8.0, 8.0]);
        let r6 = s.tensor_relu6(t6).unwrap();
        assert_eq!(s.tensor_values_lossy_f64(r6).unwrap()[0], 6.0);
        let t64 = s.tensor_variable(vec![1.0], vec![1], false).unwrap();
        let s64 = s.tensor_selu(t64).unwrap();
        assert_eq!(s.tensor_dtype(s64).unwrap(), DType::F64);
        assert!((s.tensor_values_lossy_f64(s64).unwrap()[0] - 1.0507009873554805).abs() < 1e-12);
    }

    #[test]
    fn special_unary_and_softsign_preserve_f32_dtype() {
        // torch keeps the input float dtype: the bessel special_unary_with_deriv
        // family used to ERROR on f32 (f64-only read) and softsign upcast to F64.
        // frankentorch-37czu. Values are checked loosely (computed in f64, cast to
        // f32); the contract under test is the OUTPUT DTYPE.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let mk = |s: &mut FrankenTorchSession| {
            s.tensor_variable_f32(vec![0.5, 1.0, 2.0, 3.0], vec![4], false)
                .unwrap()
        };
        let t = mk(&mut s);
        let j0 = s.tensor_special_bessel_j0(t).unwrap();
        assert_eq!(s.tensor_dtype(j0).unwrap(), DType::F32);
        let t = mk(&mut s);
        let k0 = s.tensor_special_modified_bessel_k0(t).unwrap();
        assert_eq!(s.tensor_dtype(k0).unwrap(), DType::F32);
        let t = mk(&mut s);
        let y0 = s.tensor_special_bessel_y0(t).unwrap();
        assert_eq!(s.tensor_dtype(y0).unwrap(), DType::F32);
        let t = mk(&mut s);
        let ss = s.tensor_softsign(t).unwrap();
        assert_eq!(s.tensor_dtype(ss).unwrap(), DType::F32);
        // softsign(1) = 0.5 exactly even in f32.
        assert_eq!(s.tensor_values_lossy_f64(ss).unwrap()[1], 0.5);
        // f64 unchanged (J0(2) ≈ 0.2238907791).
        let t64 = s.tensor_variable(vec![2.0], vec![1], false).unwrap();
        let j0_64 = s.tensor_special_bessel_j0(t64).unwrap();
        assert_eq!(s.tensor_dtype(j0_64).unwrap(), DType::F64);
        assert!((s.tensor_values_lossy_f64(j0_64).unwrap()[0] - 0.22389077914123567).abs() < 1e-12);
    }

    #[test]
    fn airy_ai_matches_f64_reference_values_across_regimes() {
        // Reference values from scipy.special.airy(x)[0] = Ai(x). All three
        // regimes are exercised: Maclaurin (|x|<=6), decaying asymptotic (x>6),
        // oscillatory asymptotic (x<-6).
        let close = |got: f64, want: f64, tol: f64| (got - want).abs() <= tol * (1.0 + want.abs());
        // Maclaurin (less cancellation near 0 → tighter).
        assert!(
            close(super::airy_ai_scalar(0.0), 0.3550280538878172, 1e-13),
            "Ai(0)={}",
            super::airy_ai_scalar(0.0)
        );
        assert!(
            close(super::airy_ai_scalar(1.0), 0.13529241631288141, 1e-12),
            "Ai(1)"
        );
        assert!(
            close(super::airy_ai_scalar(-1.0), 0.5355608832923521, 1e-12),
            "Ai(-1)"
        );
        assert!(
            close(super::airy_ai_scalar(2.0), 0.03492413042327235, 1e-12),
            "Ai(2)"
        );
        assert!(
            close(super::airy_ai_scalar(-2.0), 0.22740742820168561, 1e-12),
            "Ai(-2)"
        );
        // Larger |x| in Maclaurin: more cancellation, looser tolerance.
        assert!(
            close(super::airy_ai_scalar(5.0), 1.0834442525400821e-04, 1e-8),
            "Ai(5)={}",
            super::airy_ai_scalar(5.0)
        );
        assert!(
            close(super::airy_ai_scalar(-5.0), 0.3507610090241138, 1e-9),
            "Ai(-5)={}",
            super::airy_ai_scalar(-5.0)
        );
        // Positive asymptotic (x>6).
        assert!(
            close(super::airy_ai_scalar(10.0), 1.1047532552898687e-10, 1e-9),
            "Ai(10)={}",
            super::airy_ai_scalar(10.0)
        );
        // Negative oscillatory asymptotic (x<-6) — validates the phase.
        assert!(
            close(super::airy_ai_scalar(-10.0), 0.04024123848335255, 1e-9),
            "Ai(-10)={}",
            super::airy_ai_scalar(-10.0)
        );
        // Cross-branch continuity at the |x|=6 splits (Maclaurin vs asymptotic).
        // The transition region is the least accurate (~1e-7, like the K-family);
        // a small jump here only confirms the two branches agree, not f64 parity.
        let dp = (super::airy_ai_scalar(6.0) - super::airy_ai_scalar(6.0 + 1e-7)).abs();
        assert!(dp <= 1e-7, "Ai +split discontinuity {dp}");
        let dn = (super::airy_ai_scalar(-6.0) - super::airy_ai_scalar(-6.0 - 1e-7)).abs();
        assert!(dn <= 1e-7, "Ai -split discontinuity {dn}");
        assert!(super::airy_ai_scalar(f64::NAN).is_nan());
        // API surface produces the same values.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s
            .tensor_variable(vec![0.0, 1.0, -1.0], vec![3], false)
            .unwrap();
        let out = s.tensor_special_airy_ai(x).unwrap();
        let v = s.tensor_values(out).unwrap();
        assert!((v[0] - 0.3550280538878172).abs() < 1e-13);
        assert!((v[2] - 0.5355608832923521).abs() < 1e-12);
    }

    #[test]
    fn i0_is_even() {
        // i0 is even: i0(-x) bit-equals i0(x) since the
        // implementation uses |x| internally.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s
            .tensor_variable(vec![2.0, -2.0, 5.0, -5.0], vec![4], false)
            .unwrap();
        let out = s.tensor_special_i0(x).unwrap();
        let v = s.tensor_values(out).unwrap();
        assert_eq!(v[0].to_bits(), v[1].to_bits(), "i0(2) vs i0(-2)");
        assert_eq!(v[2].to_bits(), v[3].to_bits(), "i0(5) vs i0(-5)");
    }

    #[test]
    fn i0_propagates_nan() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s.tensor_variable(vec![f64::NAN], vec![1], false).unwrap();
        let out = s.tensor_special_i0(x).unwrap();
        let v = s.tensor_values(out).unwrap();
        assert!(v[0].is_nan());
    }

    #[test]
    fn i0_no_grad_golden_summary_matches_fixture() {
        use std::fmt::Write as _;

        let data = vec![-5.0, -3.5, -1.0, -0.0, 0.0, 1.0, 3.5, 5.0, f64::NAN];
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s
            .tensor_variable(data.clone(), vec![data.len()], false)
            .unwrap();
        let out = s.tensor_special_i0(x).unwrap();
        let values = s.tensor_values(out).unwrap();

        let mut summary = String::new();
        summary.push_str("ft_api_i0_no_grad_pass25\n");
        for (idx, (&input, &output)) in data.iter().zip(values.iter()).enumerate() {
            let _ = writeln!(
                &mut summary,
                "{idx}:{:016x}->{:016x}",
                input.to_bits(),
                output.to_bits()
            );
        }
        assert_eq!(
            summary,
            include_str!(
                "../../../artifacts/optimization/golden_outputs/ft_api_i0_no_grad_pass25.txt"
            )
        );
    }

    #[test]
    fn i0_no_grad_parallel_matches_serial_bit_exact() {
        let n_elems = 1usize << 14;
        let data: Vec<f64> = (0..n_elems)
            .map(|i| -8.0 + (i % 4099) as f64 * 0.004)
            .collect();
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s
            .tensor_variable(data.clone(), vec![n_elems], false)
            .unwrap();
        let out = s.tensor_special_i0(x).unwrap();
        let values = s.tensor_values(out).unwrap();

        for (idx, (&got, &input)) in values.iter().zip(data.iter()).enumerate() {
            assert_eq!(
                got.to_bits(),
                super::bessel_i0_scalar(input).to_bits(),
                "i0 no-grad parallel diverged at {idx}"
            );
        }
    }

    #[test]
    fn i0_propagates_gradient_via_i1() {
        // d/dx i0(x) = i1(x). At x=1: i1(1) ≈ 0.5651591.
        // (frankentorch-urmm — autograd unblock now that i1
        // is shipped.)
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s.tensor_variable(vec![1.0], vec![1], true).unwrap();
        let out = s.tensor_special_i0(x).unwrap();
        let report = s.tensor_backward(out).unwrap();
        let g = s.tensor_gradient(&report, x).unwrap();
        // i1(1) ≈ 0.56515910 (A&S polynomial accuracy ~5e-7).
        assert!(
            (g[0] - 0.56515910).abs() < 5e-7,
            "i0 grad at x=1 = {} (expected i1(1) ≈ 0.5651591)",
            g[0]
        );
    }

    #[test]
    fn i0e_at_zero_is_one() {
        // i0e(0) = exp(0) * i0(0) = 1.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s.tensor_variable(vec![0.0], vec![1], false).unwrap();
        let out = s.tensor_special_i0e(x).unwrap();
        let v = s.tensor_values(out).unwrap();
        assert!((v[0] - 1.0).abs() < 1e-7, "i0e(0) = {}", v[0]);
    }

    #[test]
    fn i0e_stays_bounded_for_large_input() {
        // i0e(100) is finite and roughly 1/sqrt(2π * 100) ≈ 0.04;
        // i0(100) would be ~1e42 (overflow risk).
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s.tensor_variable(vec![100.0], vec![1], false).unwrap();
        let out = s.tensor_special_i0e(x).unwrap();
        let v = s.tensor_values(out).unwrap();
        assert!(v[0].is_finite(), "i0e(100) must stay finite, got {}", v[0]);
        // Asymptotic: i0e(x) ≈ 1/sqrt(2π*x) ≈ 0.0398942 at x=100.
        assert!(
            (v[0] - 0.03989).abs() < 1e-3,
            "i0e(100) ≈ 0.03989, got {}",
            v[0]
        );
    }

    #[test]
    fn i0e_propagates_gradient_via_product_rule() {
        // d/dx i0e(x) = i1e(x) - sign(x) * i0e(x).
        // At x = 1: i1e(1) - i0e(1) = exp(-1) * (i1(1) - i0(1))
        //         ≈ 0.3679 * (0.5651591 - 1.2660658)
        //         ≈ 0.3679 * (-0.7009067)
        //         ≈ -0.2579.
        // (frankentorch-0wcm — autograd unblock).
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s.tensor_variable(vec![1.0], vec![1], true).unwrap();
        let out = s.tensor_special_i0e(x).unwrap();
        let report = s.tensor_backward(out).unwrap();
        let g = s.tensor_gradient(&report, x).unwrap();
        let expected = (-1.0_f64).exp() * (0.56515910 - 1.26606587);
        assert!(
            (g[0] - expected).abs() < 5e-7,
            "i0e grad at x=1 = {}, expected ≈ {}",
            g[0],
            expected
        );
    }

    // ── tensor_special_log_ndtr tests (frankentorch-2mb1) ─────────────

    #[test]
    fn log_ndtr_at_zero_matches_log_half() {
        // log_ndtr(0) = log(0.5).
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s.tensor_variable(vec![0.0], vec![1], false).unwrap();
        let out = s.tensor_special_log_ndtr(x).unwrap();
        let v = s.tensor_values(out).unwrap();
        let expected = 0.5_f64.ln();
        assert!((v[0] - expected).abs() < 1e-12, "got {}", v[0]);
    }

    #[test]
    fn log_ndtr_smooth_interior_matches_log_of_ndtr() {
        // For x in [-1, 0, 1], the direct branch must agree
        // with log(ndtr(x)) bit-tightly (same compose path).
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let xs = vec![-1.0, -0.5, 0.0, 0.5, 1.0];
        let n = xs.len();
        let x = s.tensor_variable(xs.clone(), vec![n], false).unwrap();
        let direct = s.tensor_special_log_ndtr(x).unwrap();
        let v_direct = s.tensor_values(direct).unwrap();
        let x2 = s.tensor_variable(xs, vec![n], false).unwrap();
        let ndtr = s.tensor_special_ndtr(x2).unwrap();
        let composed = s.tensor_log(ndtr).unwrap();
        let v_composed = s.tensor_values(composed).unwrap();
        for (i, (a, b)) in v_direct.iter().zip(v_composed.iter()).enumerate() {
            assert!((a - b).abs() < 1e-12, "i={i}: direct={a}, composed={b}");
        }
    }

    #[test]
    fn log_ndtr_far_negative_stays_finite() {
        // At x = -50, log(ndtr(x)) underflows in the naive form
        // (ndtr(x) ≈ 1.5e-548 — way below f64::MIN_POSITIVE), but
        // the asymptotic stays accurate. For very negative x:
        //   log_ndtr(x) ≈ -x²/2 - log(-x) - 0.5*log(2π) + tiny
        // At x = -50: -1250 - log(50) - 0.919 ≈ -1255.83.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s.tensor_variable(vec![-50.0], vec![1], false).unwrap();
        let out = s.tensor_special_log_ndtr(x).unwrap();
        let v = s.tensor_values(out).unwrap()[0];
        assert!(v.is_finite(), "log_ndtr(-50) must be finite, got {v}");
        let expected = -1250.0 - 50.0_f64.ln() - 0.5 * (2.0 * std::f64::consts::PI).ln();
        assert!(
            (v - expected).abs() < 1e-2,
            "log_ndtr(-50) = {v}, expected ≈ {expected}"
        );
    }

    #[test]
    fn log_ndtr_propagates_nan() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s.tensor_variable(vec![f64::NAN], vec![1], false).unwrap();
        let out = s.tensor_special_log_ndtr(x).unwrap();
        let v = s.tensor_values(out).unwrap();
        assert!(v[0].is_nan(), "log_ndtr(NaN) = {}", v[0]);
    }

    #[test]
    fn log_ndtr_propagates_gradient_via_inverse_mills_ratio() {
        // d/dx log_ndtr(x) = pdf(x) / ndtr(x).
        // At x=0: (1/sqrt(2π)) / 0.5 = sqrt(2/π) ≈ 0.7978845608.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s.tensor_variable(vec![0.0], vec![1], true).unwrap();
        let out = s.tensor_special_log_ndtr(x).unwrap();
        let report = s.tensor_backward(out).unwrap();
        let g = s.tensor_gradient(&report, x).unwrap();
        let expected = (2.0_f64 / std::f64::consts::PI).sqrt();
        assert!(
            (g[0] - expected).abs() < 1e-12,
            "log_ndtr grad at x=0 = {}, expected {}",
            g[0],
            expected
        );
    }

    #[test]
    fn log_ndtr_far_negative_gradient_stays_finite() {
        // For x = -10, the asymptotic gradient is approximately
        // -x = 10. The exact ratio pdf/ndtr at x=-10 is also
        // ≈ 10.0980... The Mills-ratio asymptotic must keep the
        // gradient finite where the literal pdf/ndtr would
        // collapse to NaN due to underflow.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s.tensor_variable(vec![-10.0], vec![1], true).unwrap();
        let out = s.tensor_special_log_ndtr(x).unwrap();
        let report = s.tensor_backward(out).unwrap();
        let g = s.tensor_gradient(&report, x).unwrap();
        assert!(
            g[0].is_finite(),
            "log_ndtr grad at x=-10 must be finite, got {}",
            g[0]
        );
        // Asymptotic prediction: -x * (1 - 1/x² + 3/x⁴ - 15/x⁶) = 10 * (1 - 0.01 + 0.00003 - ...)
        // ≈ 9.9003... Looser tolerance because we're comparing
        // against the same truncated series the implementation
        // uses.
        assert!(
            g[0] > 9.0 && g[0] < 11.0,
            "log_ndtr grad at x=-10 should be ~10 (Mills ratio), got {}",
            g[0]
        );
    }

