    #[test]
    fn complex_session_grad_ops_real_imag_conj_differentiable() {
        // real / imag / conj are all differentiable on grad-tracked complex inputs
        // (frankentorch-ng1hw).
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let tensor = DenseTensor::from_typed_storage(
            TensorMeta::from_shape(vec![1], DType::Complex128, Device::Cpu),
            TensorStorage::Complex128(Arc::new(vec![Complex128::new(1.0, 2.0)])),
        )
        .unwrap();
        let input = s.tensor_variable_from_storage(tensor, true);

        // real(z) differentiable: d/dz routes the incoming grad into the real lane.
        let re = s.tensor_real(input).unwrap();
        let out = s.tensor_sum(re).unwrap();
        let rep = s.tensor_backward(out).unwrap();
        assert_eq!(s.tensor_gradient(&rep, input).unwrap(), &[1.0, 0.0]);

        // imag(z) differentiable: grad routes into the imaginary lane.
        let mut s2 = FrankenTorchSession::new(ExecutionMode::Strict);
        let tensor2 = DenseTensor::from_typed_storage(
            TensorMeta::from_shape(vec![1], DType::Complex128, Device::Cpu),
            TensorStorage::Complex128(Arc::new(vec![Complex128::new(1.0, 2.0)])),
        )
        .unwrap();
        let input2 = s2.tensor_variable_from_storage(tensor2, true);
        let im = s2.tensor_imag(input2).unwrap();
        let out2 = s2.tensor_sum(im).unwrap();
        let rep2 = s2.tensor_backward(out2).unwrap();
        assert_eq!(s2.tensor_gradient(&rep2, input2).unwrap(), &[0.0, 1.0]);

        // conj(z) differentiable: d sum(real(conj(z)))/dz routes into the real lane
        // (imag lane negated by conj, but real(conj)=real so imag grad is 0).
        let cj = s.tensor_conj(input).unwrap();
        let cre = s.tensor_real(cj).unwrap();
        let out3 = s.tensor_sum(cre).unwrap();
        let rep3 = s.tensor_backward(out3).unwrap();
        assert_eq!(s.tensor_gradient(&rep3, input).unwrap(), &[1.0, 0.0]);
    }

