    #[test]
    fn tensor_complex_differentiable_for_grad_inputs() {
        // tensor_complex is now differentiable (frankentorch-ng1hw): the complex
        // output's interleaved gradient de-interleaves back to the real/imag inputs.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let real = s.tensor_variable(vec![1.0, 2.0], vec![2], true).unwrap();
        let imag = s.tensor_variable(vec![3.0, 4.0], vec![2], true).unwrap();
        let z = s.tensor_complex(real, imag).unwrap();
        assert_eq!(s.tensor_dtype(z).unwrap(), DType::Complex128);
        // loss = sum(real(z)) -> grad real = 1, grad imag = 0.
        let re = s.tensor_real(z).unwrap();
        let out = s.tensor_sum(re).unwrap();
        let rep = s.tensor_backward(out).unwrap();
        assert_eq!(s.tensor_gradient(&rep, real).unwrap(), &[1.0, 1.0]);
        assert_eq!(s.tensor_gradient(&rep, imag).unwrap(), &[0.0, 0.0]);
    }

