    #[test]
    fn tensor_view_ops_differentiable_for_grad_inputs() {
        // view_as_real / view_as_complex are now differentiable identity-on-layout
        // bridges (frankentorch-ng1hw): the gradient is copied through unchanged.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let complex_tensor = DenseTensor::from_typed_storage(
            TensorMeta::from_shape(vec![1], DType::Complex128, Device::Cpu),
            TensorStorage::Complex128(Arc::new(vec![Complex128::new(1.0, 2.0)])),
        )
        .unwrap();
        let complex_input = s.tensor_variable_from_storage(complex_tensor, true);
        let real_view = s.tensor_view_as_real(complex_input).unwrap();
        let out = s.tensor_sum(real_view).unwrap();
        let rep = s.tensor_backward(out).unwrap();
        // d sum(view_as_real(z))/dz = ones over both re/im lanes.
        assert_eq!(s.tensor_gradient(&rep, complex_input).unwrap(), &[1.0, 1.0]);

        let real_input = s.tensor_variable(vec![1.0, 2.0], vec![1, 2], true).unwrap();
        let z = s.tensor_view_as_complex(real_input).unwrap();
        assert_eq!(s.tensor_dtype(z).unwrap(), DType::Complex128);
        let back = s.tensor_view_as_real(z).unwrap();
        let out2 = s.tensor_sum(back).unwrap();
        let rep2 = s.tensor_backward(out2).unwrap();
        assert_eq!(s.tensor_gradient(&rep2, real_input).unwrap(), &[1.0, 1.0]);
    }

