    #[test]
    fn tensor_grid_sample_border_padding_zeroes_grid_grad_at_exact_boundary() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let input = s
            .tensor_variable(vec![1.0, 2.0, 3.0], vec![1, 1, 1, 3], true)
            .unwrap();
        let grid = s
            .tensor_variable(vec![-1.0, 0.0], vec![1, 1, 1, 2], true)
            .unwrap();

        let out = s
            .tensor_grid_sample(
                input,
                grid,
                GridSampleMode::Bilinear,
                GridSamplePaddingMode::Border,
                true,
            )
            .expect("border grid_sample should support autograd");
        assert_eq!(s.tensor_values(out).unwrap(), &[1.0]);

        let loss = s.tensor_sum(out).unwrap();
        let report = s.tensor_backward(loss).unwrap();
        let grad_input = s
            .tensor_gradient(&report, input)
            .expect("border grid_sample should propagate input gradient");
        let grad_grid = s
            .tensor_gradient(&report, grid)
            .expect("border grid_sample should produce grid gradient");

        assert_eq!(grad_input, &[1.0, 0.0, 0.0]);
        assert_eq!(grad_grid, &[0.0, 0.0]);
    }

    #[test]
    fn tensor_grid_sample_nearest_propagates_input_grad_and_zero_grid_grad() {
        // Regression for frankentorch-i852: nearest-mode grid_sample
        // used to fail-loud for tracked tensors. PyTorch treats nearest
        // interpolation as piecewise constant in the grid, so input
        // gradients scatter to the selected pixel while grid gradients
        // are zero almost everywhere.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let input = s
            .tensor_variable(vec![1.0, 2.0, 3.0, 4.0], vec![1, 1, 2, 2], true)
            .unwrap();
        let grid = s
            .tensor_variable(vec![-1.0, -1.0, 1.0, 1.0], vec![1, 1, 2, 2], true)
            .unwrap();

        let output = s
            .tensor_grid_sample(
                input,
                grid,
                GridSampleMode::Nearest,
                GridSamplePaddingMode::Zeros,
                true,
            )
            .expect("nearest grid_sample should support autograd");
        assert_eq!(s.tensor_values(output).unwrap(), vec![1.0, 4.0]);

        let loss = s.tensor_sum(output).unwrap();
        let report = s.tensor_backward(loss).unwrap();
        let grad_input = s
            .tensor_gradient(&report, input)
            .expect("nearest grid_sample should propagate input gradient");
        let grad_grid = s
            .tensor_gradient(&report, grid)
            .expect("nearest grid_sample should return zero grid gradient");

        assert_eq!(grad_input, &[1.0, 0.0, 0.0, 1.0]);
        assert_eq!(grad_grid, &[0.0, 0.0, 0.0, 0.0]);
    }

    #[test]
    fn tensor_grid_sample_bilinear_f32_propagates_gradients_to_input_and_grid() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let input = s
            .tensor_variable_f32(vec![1.0_f32, 2.0, 3.0, 4.0], vec![1, 1, 2, 2], true)
            .unwrap();
        let grid = s
            .tensor_variable_f32(vec![0.0_f32, 0.0], vec![1, 1, 1, 2], true)
            .unwrap();

        let output = s
            .tensor_grid_sample(
                input,
                grid,
                GridSampleMode::Bilinear,
                GridSamplePaddingMode::Zeros,
                true,
            )
            .expect("bilinear F32 grid_sample should support autograd");
        assert_eq!(s.tensor_dtype(output).unwrap(), DType::F32);
        assert_eq!(s.tensor_values_f32(output).unwrap(), vec![2.5_f32]);

        let loss = s.tensor_sum(output).unwrap();
        let report = s.tensor_backward(loss).unwrap();
        let grad_input = s
            .tensor_gradient(&report, input)
            .expect("grid_sample should propagate f32 input gradient");
        let grad_grid = s
            .tensor_gradient(&report, grid)
            .expect("grid_sample should propagate f32 grid gradient");

        assert_eq!(grad_input.len(), 4);
        for (i, &g) in grad_input.iter().enumerate() {
            assert!(
                (g - 0.25).abs() < 1e-6,
                "f32 grad_input[{i}] = {g}, expected 0.25"
            );
        }
        assert_eq!(grad_grid.len(), 2);
        assert!(
            (grad_grid[0] - 0.5).abs() < 1e-6,
            "f32 grad_grid x = {}, expected 0.5",
            grad_grid[0]
        );
        assert!(
            (grad_grid[1] - 1.0).abs() < 1e-6,
            "f32 grad_grid y = {}, expected 1.0",
            grad_grid[1]
        );
    }

