    #[test]
    fn logaddexp2_basic() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let a = s.tensor_variable(vec![1.0, 3.0], vec![2], false).unwrap();
        let b = s.tensor_variable(vec![1.0, 3.0], vec![2], false).unwrap();
        let out = s.tensor_logaddexp2(a, b).unwrap();
        let vals = s.tensor_values(out).unwrap();
        // log2(2^1 + 2^1) = log2(4) = 2
        assert!(
            (vals[0] - 2.0).abs() < 1e-8,
            "expected 2.0, got {}",
            vals[0]
        );
        // log2(2^3 + 2^3) = log2(16) = 4
        assert!(
            (vals[1] - 4.0).abs() < 1e-8,
            "expected 4.0, got {}",
            vals[1]
        );
    }

    #[test]
    fn logaddexp2_asymmetric() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let a = s.tensor_variable(vec![0.0], vec![1], false).unwrap();
        let b = s.tensor_variable(vec![4.0], vec![1], false).unwrap();
        let out = s.tensor_logaddexp2(a, b).unwrap();
        let vals = s.tensor_values(out).unwrap();
        // log2(2^0 + 2^4) = log2(1 + 16) = log2(17)
        let expected = 17.0_f64.log2();
        assert!((vals[0] - expected).abs() < 1e-8);
    }

    #[test]
    fn logaddexp2_preserves_autograd_edge() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let a = s
            .tensor_variable(vec![f64::INFINITY, 1.0], vec![2], true)
            .unwrap();
        let b = s.tensor_variable(vec![1.0, 2.0], vec![2], true).unwrap();
        let out = s.tensor_logaddexp2(a, b).unwrap();
        assert!(s.tensor_requires_grad(out).unwrap());
        let summed = s.tensor_sum(out).unwrap();
        let report = s.tensor_backward(summed).unwrap();
        let grad_a = report.gradient(a).unwrap();
        let grad_b = report.gradient(b).unwrap();
        assert!(grad_a[0].is_nan());
        assert_eq!(grad_b[0], 0.0);
        let finite_out = (2.0_f64.powf(1.0) + 2.0_f64.powf(2.0)).log2();
        assert!((grad_a[1] - 2.0_f64.powf(1.0 - finite_out)).abs() < 1e-12);
        assert!((grad_b[1] - 2.0_f64.powf(2.0 - finite_out)).abs() < 1e-12);
    }

    // ── xlogy tests ─────────────────────────────────────────────────────

    #[test]
    fn xlogy_basic() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s.tensor_variable(vec![2.0, 3.0], vec![2], false).unwrap();
        let y = s
            .tensor_variable(vec![std::f64::consts::E, 10.0], vec![2], false)
            .unwrap();
        let out = s.tensor_xlogy(x, y).unwrap();
        let vals = s.tensor_values(out).unwrap();
        // 2 * log(e) = 2 * 1 = 2
        assert!((vals[0] - 2.0).abs() < 1e-10);
        // 3 * log(10) ≈ 6.9077
        assert!((vals[1] - 3.0 * 10.0_f64.ln()).abs() < 1e-10);
    }

    #[test]
    fn xlogy_zero_times_log_is_zero() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s.tensor_variable(vec![0.0, 0.0], vec![2], false).unwrap();
        let y = s
            .tensor_variable(vec![0.0, f64::INFINITY], vec![2], false)
            .unwrap();
        let out = s.tensor_xlogy(x, y).unwrap();
        let vals = s.tensor_values(out).unwrap();
        assert_eq!(vals[0], 0.0, "0 * log(0) should be 0");
        assert_eq!(vals[1], 0.0, "0 * log(inf) should be 0");
    }

    #[test]
    fn xlogy_zero_times_nan_is_nan() {
        // scipy/torch xlogy short-circuit 0*log(y) to 0 only when y is not
        // NaN; xlogy(0, NaN) = 0*log(NaN) = 0*NaN = NaN.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s.tensor_variable(vec![0.0, 0.0], vec![2], false).unwrap();
        let y = s
            .tensor_variable(vec![f64::NAN, -1.0], vec![2], false)
            .unwrap();
        let out = s.tensor_xlogy(x, y).unwrap();
        let vals = s.tensor_values(out).unwrap();
        assert!(
            vals[0].is_nan(),
            "xlogy(0, NaN) must be NaN, got {}",
            vals[0]
        );
        assert_eq!(vals[1], 0.0, "xlogy(0, -1) short-circuits to 0");
    }

    #[test]
    fn xlogy_shape_mismatch_errors() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s.tensor_variable(vec![1.0, 2.0], vec![2], false).unwrap();
        let y = s
            .tensor_variable(vec![1.0, 2.0, 3.0], vec![3], false)
            .unwrap();
        assert!(s.tensor_xlogy(x, y).is_err());
    }

    #[test]
    fn xlogy_propagates_gradients_through_x_and_y() {
        // Regression test for frankentorch-1tax: tensor_xlogy used to
        // extract values and rebuild a fresh requires_grad=false
        // leaf, severing the tape. After the where(x==0, 0, x*log(y))
        // composition fix, gradients flow correctly through both x
        // and y for non-boundary positions.
        //
        // Analytical derivatives where x != 0:
        //   d xlogy / dx = log(y)
        //   d xlogy / dy = x / y
        // Where x == 0, the convention pins the output (and therefore
        // both gradients) to zero.
        //
        // For x = [2.0, 0.0, 3.0], y = [4.0, 1.0, 5.0]:
        //   output  = [2*log(4), 0, 3*log(5)]
        //   sum loss → incoming = ones
        //   grad_x  = [log(4), 0,         log(5)]   (mask zeros position 1)
        //   grad_y  = [2/4,    0,         3/5]      (mask zeros position 1)
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s
            .tensor_variable(vec![2.0, 0.0, 3.0], vec![3], true)
            .unwrap();
        let y = s
            .tensor_variable(vec![4.0, 1.0, 5.0], vec![3], true)
            .unwrap();
        let out = s.tensor_xlogy(x, y).unwrap();
        let loss = s.tensor_sum(out).unwrap();
        let report = s.tensor_backward(loss).unwrap();
        let grad_x = s
            .tensor_gradient(&report, x)
            .expect("xlogy must propagate gradient to x");
        let grad_y = s
            .tensor_gradient(&report, y)
            .expect("xlogy must propagate gradient to y");

        let expect_x = [4.0_f64.ln(), 0.0, 5.0_f64.ln()];
        let expect_y = [2.0 / 4.0, 0.0, 3.0 / 5.0];
        for (i, (&g, &e)) in grad_x.iter().zip(expect_x.iter()).enumerate() {
            assert!(
                (g - e).abs() < 1e-12,
                "xlogy grad_x[{i}] = {g}, expected log(y_i) (or 0 at the x==0 boundary): {e}"
            );
        }
        for (i, (&g, &e)) in grad_y.iter().zip(expect_y.iter()).enumerate() {
            assert!(
                (g - e).abs() < 1e-12,
                "xlogy grad_y[{i}] = {g}, expected x_i/y_i (or 0 at the x==0 boundary): {e}"
            );
        }
    }

