    #[test]
    fn pixel_unshuffle_values_match_torch() {
        // The existing test only checks the SHAPE; verify the actual rearrange vs
        // torch 2.12 F.pixel_unshuffle(arange(16)[1,1,4,4], 2) -> [1,4,2,2].
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s
            .tensor_variable((0..16).map(|v| v as f64).collect(), vec![1, 1, 4, 4], false)
            .unwrap();
        let out = s.tensor_pixel_unshuffle(x, 2).unwrap();
        assert_eq!(s.tensor_shape(out).unwrap(), vec![1, 4, 2, 2]);
        let want = [
            0.0, 2.0, 8.0, 10.0, 1.0, 3.0, 9.0, 11.0, 4.0, 6.0, 12.0, 14.0, 5.0, 7.0, 13.0, 15.0,
        ];
        assert_eq!(s.tensor_values(out).unwrap(), want.to_vec());
    }

    #[test]
    fn lp_pool2d_matches_torch() {
        // Independent oracle: torch 2.12 F.lp_pool2d(arange(1..=16)[1,1,4,4], p, 2)
        // = (sum |x|^p over each 2x2 window)^(1/p), for p in {1, 2, 3}.
        let cases: [(f64, [f64; 4]); 3] = [
            (1.0, [14.0, 22.0, 46.0, 54.0]),
            (
                2.0,
                [8.1240384046, 11.7473401245, 23.3666428911, 27.3130005675],
            ),
            (
                3.0,
                [7.0472987321, 9.8166591561, 18.8238568417, 21.9184307222],
            ),
        ];
        for (p, want) in cases {
            let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
            let x = s
                .tensor_variable(
                    (1..=16).map(|v| v as f64).collect(),
                    vec![1, 1, 4, 4],
                    false,
                )
                .unwrap();
            let out = s.tensor_lp_pool2d(x, p, (2, 2), None, false).unwrap();
            assert_eq!(s.tensor_shape(out).unwrap(), vec![1, 1, 2, 2]);
            let got = s.tensor_values(out).unwrap();
            for (g, w) in got.iter().zip(want.iter()) {
                assert!(
                    (g - w).abs() < 1e-8,
                    "lp_pool2d p={p}: got {got:?} want {want:?}"
                );
            }
        }
    }

