    // ── cov tests ───────────────────────────────────────────────────────

    #[test]
    fn cov_identity_correlation() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        // Two identical variables → perfect correlation, equal covariance
        let x = s
            .tensor_variable(vec![1.0, 2.0, 3.0, 1.0, 2.0, 3.0], vec![2, 3], false)
            .unwrap();
        let out = s.tensor_cov(x).unwrap();
        let vals = s.tensor_values(out).unwrap();
        let shape = s.tensor_shape(out).unwrap();
        assert_eq!(shape, &[2, 2]);
        // Variance of [1,2,3] = 1.0
        assert!((vals[0] - 1.0).abs() < 1e-10);
        // Covariance of identical variables = variance
        assert!((vals[1] - 1.0).abs() < 1e-10);
    }

    #[test]
    fn cov_uncorrelated() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        // x = [1, -1], y = [1, 1] → cov(x,y) should be 0
        let x = s
            .tensor_variable(vec![1.0, -1.0, 1.0, 1.0], vec![2, 2], false)
            .unwrap();
        let out = s.tensor_cov(x).unwrap();
        let vals = s.tensor_values(out).unwrap();
        assert!(
            (vals[1]).abs() < 1e-10,
            "uncorrelated variables should have 0 covariance"
        );
    }

    #[test]
    fn cov_1d_returns_scalar_variance() {
        // torch.cov of a 1-D input is the variance of that single variable,
        // returned as a 0-dim scalar (torch 2.12: cov([1,2,3,5])=2.9166..,
        // correction=0 -> 2.1875; corrcoef -> 1.0). A 2-D [1,M] squeezes the
        // same way.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s
            .tensor_variable(vec![1.0, 2.0, 3.0, 5.0], vec![4], false)
            .unwrap();
        let cov = s.tensor_cov(x).unwrap();
        assert_eq!(s.tensor_shape(cov).unwrap(), Vec::<usize>::new());
        assert!((s.tensor_values(cov).unwrap()[0] - 2.9166666666666665).abs() < 1e-9);

        let cov0 = s.tensor_cov_full(x, 0, None, None).unwrap();
        assert_eq!(s.tensor_shape(cov0).unwrap(), Vec::<usize>::new());
        assert!((s.tensor_values(cov0).unwrap()[0] - 2.1875).abs() < 1e-9);

        // 2-D single-row also squeezes to a 0-dim scalar.
        let x2 = s
            .tensor_variable(vec![1.0, 2.0, 3.0, 5.0], vec![1, 4], false)
            .unwrap();
        let cov2 = s.tensor_cov(x2).unwrap();
        assert_eq!(s.tensor_shape(cov2).unwrap(), Vec::<usize>::new());
        assert!((s.tensor_values(cov2).unwrap()[0] - 2.9166666666666665).abs() < 1e-9);

        // corrcoef of a single variable is 1.0 (0-dim).
        let cc = s.tensor_corrcoef(x).unwrap();
        assert_eq!(s.tensor_shape(cc).unwrap(), Vec::<usize>::new());
        assert!((s.tensor_values(cc).unwrap()[0] - 1.0).abs() < 1e-9);
    }

    #[test]
    fn cov_propagates_gradients_through_input() {
        // Regression test for frankentorch-1tax: tensor_cov used to
        // extract values and rebuild a fresh requires_grad=false leaf,
        // dropping gradients to the input. After the
        // mean_dim/unsqueeze/expand/sub/matmul/transpose/div
        // composition fix, gradients flow through.
        //
        // The exact gradient is messy to write down element-wise but
        // numerical equivalence on a small case is enough to confirm
        // the autograd graph is intact. We use a 2x3 input and
        // verify that backward through sum-loss produces a finite
        // non-trivial gradient with the expected structural property
        // that each row sums to zero (because cov is shift-invariant
        // along the observation dim — adding a constant to row i
        // doesn't change cov).
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s
            .tensor_variable(vec![1.0, 2.0, 3.0, 4.0, 6.0, 5.0], vec![2, 3], true)
            .unwrap();
        let cov = s.tensor_cov(x).unwrap();
        let loss = s.tensor_sum(cov).unwrap();
        let report = s.tensor_backward(loss).unwrap();
        let grad = s
            .tensor_gradient(&report, x)
            .expect("cov must propagate gradient through input");
        assert_eq!(grad.len(), 6);
        for &g in grad.iter() {
            assert!(
                g.is_finite(),
                "cov backward must produce finite grads, got {g}"
            );
        }
        // Row-sum invariance: shifting row i by a constant doesn't
        // change cov, so d(sum(cov))/d(x[i,j]) summed over j should
        // be ~0 for each row.
        let row0_sum: f64 = grad[..3].iter().sum();
        let row1_sum: f64 = grad[3..].iter().sum();
        assert!(
            row0_sum.abs() < 1e-12,
            "sum of row-0 grad components should be ~0 (cov shift-invariant), got {row0_sum}"
        );
        assert!(
            row1_sum.abs() < 1e-12,
            "sum of row-1 grad components should be ~0 (cov shift-invariant), got {row1_sum}"
        );
    }

    #[test]
    fn cov_full_correction_and_weights_match_torch() {
        // torch 2.12 goldens for X = [[0,2,1,3],[4,1,2,0]] (2x4):
        //   torch.cov(X), correction=0, fweights=[1,2,1,3],
        //   aweights=[0.5,0.3,0.2,0.4], and fweights+aweights together.
        let close = |s: &FrankenTorchSession, c: TensorNodeId, want: &[f64], tag: &str| {
            let got = s.tensor_values(c).unwrap();
            assert_eq!(got.len(), want.len(), "{tag} len");
            for (i, (g, w)) in got.iter().zip(want).enumerate() {
                assert!((g - w).abs() < 1e-9, "{tag}[{i}] = {g}, want {w}");
            }
        };
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s
            .tensor_variable(vec![0., 2., 1., 3., 4., 1., 2., 0.], vec![2, 4], false)
            .unwrap();

        let default = s.tensor_cov_full(x, 1, None, None).unwrap();
        close(
            &s,
            default,
            &[
                1.6666666666666667,
                -2.1666666666666665,
                -2.1666666666666665,
                2.9166666666666665,
            ],
            "default",
        );

        let corr0 = s.tensor_cov_full(x, 0, None, None).unwrap();
        close(&s, corr0, &[1.25, -1.625, -1.625, 2.1875], "corr0");

        let fw = s
            .tensor_variable(vec![1., 2., 1., 3.], vec![4], false)
            .unwrap();
        let fweights = s.tensor_cov_full(x, 1, Some(fw), None).unwrap();
        close(
            &s,
            fweights,
            &[
                1.3333333333333333,
                -1.6666666666666667,
                -1.6666666666666667,
                2.142857142857143,
            ],
            "fweights",
        );

        let aw = s
            .tensor_variable(vec![0.5, 0.3, 0.2, 0.4], vec![4], false)
            .unwrap();
        let aweights = s.tensor_cov_full(x, 1, None, Some(aw)).unwrap();
        close(
            &s,
            aweights,
            &[
                2.112676056338028,
                -2.816901408450704,
                -2.816901408450704,
                3.838028169014084,
            ],
            "aweights",
        );

        let both = s.tensor_cov_full(x, 1, Some(fw), Some(aw)).unwrap();
        close(
            &s,
            both,
            &[
                1.6037735849056605,
                -2.0754716981132075,
                -2.0754716981132075,
                2.7358490566037728,
            ],
            "fw+aw",
        );
    }

