    #[test]
    fn mode_bounded_no_grad_fast_path_matches_sort_contract() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let rows = 512usize;
        let cols = 16usize;
        const FILLERS: [f64; 11] = [
            20.0, 21.0, 22.0, 23.0, 24.0, 25.0, 26.0, 27.0, 28.0, 29.0, 30.0,
        ];

        let mut data = Vec::with_capacity(rows * cols);
        for row in 0..rows {
            for col in 0..cols {
                let value = match col {
                    2 | 6 | 10 => 3.0,
                    1 | 5 | 9 => 7.0,
                    _ => FILLERS[(row + col) % FILLERS.len()],
                };
                data.push(value);
            }
        }

        let x = s.tensor_variable(data, vec![rows, cols], false).unwrap();
        let (vals, idxs) = s.tensor_mode(x).unwrap();
        let values = s.tensor_values(vals).unwrap();
        let indices = s.tensor_values(idxs).unwrap();

        assert_eq!(values.len(), rows);
        assert_eq!(indices.len(), rows);
        for (&value, &idx) in values.iter().zip(indices.iter()) {
            assert_eq!(value, 3.0);
            assert_eq!(idx, 10.0);
        }
    }

    #[test]
    fn mode_non_contiguous_f64_bounded_falls_back_and_matches_contiguous() {
        // A transposed (non-contiguous) f64 view in the bounded-key range and large
        // enough to clear the fast-path gate must NOT error on the zero-copy borrow —
        // it falls back to the layout-agnostic slow path and matches a contiguous clone.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let rows = 128usize; // 128*128 = 16384 >= 1<<13, clears the fast-path gate
        let cols = 128usize;
        let data: Vec<f64> = (0..rows * cols).map(|i| (i % 17) as f64).collect();

        let x = s.tensor_variable(data, vec![rows, cols], false).unwrap();
        // Transpose -> non-contiguous; mode along the (now) last dim.
        let xt = s.tensor_transpose(x, 0, 1).unwrap();
        let (vt, it) = s.tensor_mode(xt).unwrap();
        let vt_vals = s.tensor_values(vt).unwrap();
        let it_vals = s.tensor_values(it).unwrap();

        // Reference: force a contiguous copy of the same view, then mode.
        let xt_contig = s.tensor_contiguous(xt).unwrap();
        let (vc, ic) = s.tensor_mode(xt_contig).unwrap();
        let vc_vals = s.tensor_values(vc).unwrap();
        let ic_vals = s.tensor_values(ic).unwrap();

        assert_eq!(vt_vals, vc_vals);
        assert_eq!(it_vals, ic_vals);
    }

    #[test]
    fn mode_f32_bounded_counting_keeps_f32_and_matches_sort_contract() {
        // f32 bounded-integer input -> the f32 counting fast path. The value is gathered
        // from the original f32 input, so the output must STAY f32 (torch.mode(f32)->f32),
        // and the value+index must match the sort contract (mode 3.0 at last occurrence,
        // col 10). rows*cols = 8192 = 1<<13 clears the gate.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let rows = 512usize;
        let cols = 16usize;
        const FILLERS: [f32; 11] = [
            20.0, 21.0, 22.0, 23.0, 24.0, 25.0, 26.0, 27.0, 28.0, 29.0, 30.0,
        ];
        let mut data: Vec<f32> = Vec::with_capacity(rows * cols);
        for row in 0..rows {
            for col in 0..cols {
                let value = match col {
                    2 | 6 | 10 => 3.0,
                    1 | 5 | 9 => 7.0,
                    _ => FILLERS[(row + col) % FILLERS.len()],
                };
                data.push(value);
            }
        }
        let x = s
            .tensor_variable_f32(data, vec![rows, cols], false)
            .unwrap();
        let (vals, idxs) = s.tensor_mode(x).unwrap();
        // Output value keeps f32 dtype (gathered from the f32 input).
        assert_eq!(s.tensor_dtype(vals).unwrap(), DType::F32);
        let values = s.tensor_values_f32(vals).unwrap();
        let indices = s.tensor_values(idxs).unwrap();
        assert_eq!(values.len(), rows);
        assert_eq!(indices.len(), rows);
        for (&value, &idx) in values.iter().zip(indices.iter()) {
            assert_eq!(value, 3.0_f32);
            assert_eq!(idx, 10.0);
        }
    }

    #[test]
    fn quantile_dim_bounded_integer_counting_matches_reference() {
        // Bounded integers in [0,255] -> the no-grad f64 counting fast path. Order
        // statistics are hand-derived from the sorted lanes; the counting histogram
        // must reproduce them across every interpolation mode.
        // Row 0 sorts to [0,1,2,3,4]; Row 1 (10,20,10,20,10) sorts to [10,10,10,20,20].
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let data = vec![0.0, 1.0, 2.0, 3.0, 4.0, 10.0, 20.0, 10.0, 20.0, 10.0];
        let x = s.tensor_variable(data, vec![2, 5], false).unwrap();

        let mut check = |q: f64, interp: &str, expected: [f64; 2]| {
            let out = s.tensor_quantile_dim(x, q, 1, false, interp).unwrap();
            let got = s.tensor_values(out).unwrap();
            assert_eq!(got.len(), 2);
            for (g, e) in got.iter().zip(expected.iter()) {
                assert!(
                    (g - e).abs() < 1e-12,
                    "q={q} interp={interp}: got {g} want {e}"
                );
            }
        };
        check(0.5, "linear", [2.0, 10.0]);
        check(0.25, "linear", [1.0, 10.0]);
        check(0.75, "linear", [3.0, 20.0]);
        check(0.1, "linear", [0.4, 10.0]); // row0 idx=0.4 -> lerp(0,1,0.4)
        check(0.6, "linear", [2.4, 14.0]); // row1 idx=2.4 -> lerp(10,20,0.4)
        check(0.6, "lower", [2.0, 10.0]);
        check(0.6, "higher", [3.0, 20.0]);
        check(0.6, "midpoint", [2.5, 15.0]);
    }

    #[test]
    fn quantile_dim_non_integer_falls_back_to_quickselect() {
        // A non-integer value fails the global bounded check -> the whole reduction
        // drops to the quickselect path, which must still produce the right medians.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        // Row 0 sorts to [0.5,1.5,2.5]; Row 1 to [50.5,75.5,100.5].
        let y = s
            .tensor_variable(vec![0.5, 2.5, 1.5, 100.5, 50.5, 75.5], vec![2, 3], false)
            .unwrap();
        let out = s.tensor_quantile_dim(y, 0.5, 1, false, "linear").unwrap();
        let got = s.tensor_values(out).unwrap();
        assert!((got[0] - 1.5).abs() < 1e-12);
        assert!((got[1] - 75.5).abs() < 1e-12);
    }

