    #[test]
    fn fold_matches_torch_overlap_sum() {
        // fold (col2im) was UNTESTED. Independent oracle: torch 2.12 F.fold sums
        // overlapping blocks back into the output.
        // Case 1: fold(unfold(arange(1..=9)[1,1,3,3], k2), out 3x3, k2). Each pixel
        // is summed once per block it appears in: corners x1, edges x2, center x4.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        // unfold of [[1,2,3],[4,5,6],[7,8,9]] with kernel 2, stride 1 -> [1,4,4]
        // rows = (kh,kw) tap, cols = the 4 blocks.
        let unfolded = vec![
            1.0, 2.0, 4.0, 5.0, // tap (0,0) over the 4 blocks
            2.0, 3.0, 5.0, 6.0, // tap (0,1)
            4.0, 5.0, 7.0, 8.0, // tap (1,0)
            5.0, 6.0, 8.0, 9.0, // tap (1,1)
        ];
        let inp = s.tensor_variable(unfolded, vec![1, 4, 4], false).unwrap();
        let out = s
            .tensor_fold(inp, (3, 3), (2, 2), (1, 1), (0, 0), (1, 1))
            .unwrap();
        assert_eq!(s.tensor_shape(out).unwrap(), vec![1, 1, 3, 3]);
        let want = [1.0, 4.0, 3.0, 8.0, 20.0, 12.0, 7.0, 16.0, 9.0];
        let got = s.tensor_values(out).unwrap();
        for (g, w) in got.iter().zip(want.iter()) {
            assert!(
                (g - w).abs() < 1e-9,
                "fold overlap-sum: got {got:?} want {want:?}"
            );
        }

        // Case 2: fold of all-ones [1,4,4] -> the overlap-count map [[1,2,1],[2,4,2],[1,2,1]].
        let ones = s
            .tensor_variable(vec![1.0; 16], vec![1, 4, 4], false)
            .unwrap();
        let out2 = s
            .tensor_fold(ones, (3, 3), (2, 2), (1, 1), (0, 0), (1, 1))
            .unwrap();
        assert_eq!(
            s.tensor_values(out2).unwrap(),
            vec![1.0, 2.0, 1.0, 2.0, 4.0, 2.0, 1.0, 2.0, 1.0]
        );
    }

