    #[test]
    fn renorm_clips() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s
            .tensor_variable(vec![3.0, 4.0, 1.0, 0.0], vec![2, 2], false)
            .unwrap();
        let out = s.tensor_renorm(x, 2.0, 0, 2.5).unwrap();
        let vals = s.tensor_values(out).unwrap();
        // Row 0 norm = 5 > maxnorm 2.5 -> scaled by 2.5/(5 + 1e-7), matching
        // torch's renorm epsilon (frankentorch-tncnq): 3 * 2.5/(5+1e-7).
        let expected0 = 3.0 * 2.5 / (5.0 + 1e-7);
        assert!(
            (vals[0] - expected0).abs() < 1e-12,
            "got {}, want {expected0}",
            vals[0]
        );
        // Row 1 norm = 1 < maxnorm -> unscaled.
        assert!((vals[2] - 1.0).abs() < 1e-10);
    }

    #[test]
    fn renorm_matches_torch_epsilon() {
        // frankentorch-tncnq: torch.renorm scales over-norm slices by
        // maxnorm/(norm + 1e-7), NOT maxnorm/norm. Goldens from torch 2.12
        // (float64): renorm([[3,4],[1,1]], p=2, dim=0, maxnorm=1).
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s
            .tensor_variable(vec![3.0, 4.0, 1.0, 1.0], vec![2, 2], false)
            .unwrap();
        let out = s.tensor_renorm(x, 2.0, 0, 1.0).unwrap();
        let got = s.tensor_values(out).unwrap();
        let want = [
            0.5999999880000002,
            0.7999999840000003,
            0.707106731186551,
            0.707106731186551,
        ];
        for (g, w) in got.iter().zip(want.iter()) {
            assert!(
                (g - w).abs() < 1e-12,
                "renorm eps: got {got:?} want {want:?}"
            );
        }

        // A slice within maxnorm is left exactly unscaled (no spurious eps).
        let x2 = s
            .tensor_variable(vec![0.5, 0.5], vec![1, 2], false)
            .unwrap();
        let out2 = s.tensor_renorm(x2, 2.0, 0, 1.0).unwrap();
        let v2 = s.tensor_values(out2).unwrap();
        assert_eq!(v2, vec![0.5, 0.5], "in-bounds slice must be unchanged");
    }

    #[test]
    fn renorm_propagates_gradient_through_input() {
        // Regression test for frankentorch-go4q. tensor_renorm used
        // to extract values, conditionally scale in plain f64, and
        // rebuild a non-grad leaf — silently severing autograd
        // through embedding-regularization paths. After composing
        // through permute/reshape/abs/pow/sum_dim/clamp/div/mul
        // primitives, gradients flow.
        //
        // For x = [[3, 4], [1, 0]] (shape [2, 2]) with p=2, dim=0,
        // maxnorm=2.5:
        //   row 0 norm = sqrt(9 + 16) = 5  > 2.5 → scale = 0.5
        //   row 1 norm = sqrt(1 + 0) = 1   <= 2.5 → scale = 1
        //   out = [[1.5, 2.0], [1.0, 0.0]]
        // Sanity check: the gradient should be finite and non-zero
        // throughout (the row-0 entries pass through a scaling
        // factor that depends on x, the row-1 entries pass through
        // the identity branch).
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s
            .tensor_variable(vec![3.0, 4.0, 1.0, 0.0], vec![2, 2], true)
            .unwrap();
        let out = s.tensor_renorm(x, 2.0, 0, 2.5).unwrap();
        let loss = s.tensor_sum(out).unwrap();
        let report = s.tensor_backward(loss).unwrap();
        let grad = s
            .tensor_gradient(&report, x)
            .expect("tensor_renorm must propagate gradient");
        assert_eq!(grad.len(), 4);
        assert!(
            grad.iter().all(|g| g.is_finite()),
            "renorm gradient must be finite, got {grad:?}"
        );
        // For row 1 (norm <= maxnorm, identity branch under sum loss):
        //   d sum(x_row_1) / d x_row_1 = 1
        // So grad[2] = 1 (x[1,0] unscaled identity contributes 1 to sum)
        // and grad[3] = 1 (x[1,1] = 0).
        assert!(
            (grad[2] - 1.0).abs() < 1e-12,
            "renorm grad[2] (row 1 identity) = {}, expected 1",
            grad[2]
        );
        assert!(
            (grad[3] - 1.0).abs() < 1e-12,
            "renorm grad[3] (row 1 identity) = {}, expected 1",
            grad[3]
        );
        // For row 0 (norm > maxnorm), gradient is more involved
        // (chain through the scale factor) — assert non-zero finite.
        assert!(
            grad[0].abs() > 1e-9 && grad[1].abs() > 1e-9,
            "renorm grad on scaled row should be non-zero, got {} {}",
            grad[0],
            grad[1]
        );
    }

    #[test]
    fn renorm_is_idempotent_and_bounds_slice_norms() {
        // Metamorphic relation: renorm(renorm(x)) == renorm(x).
        // Post-condition: every slice along dim has p-norm <= maxnorm.
        // Generated cases include both already-valid and clipped rows.
        let ps = [1.0, 2.0, 3.0];
        let maxnorms = [1.5, 3.0, 7.0];

        for rows in 1..5 {
            for cols in 2..6 {
                let values: Vec<f64> = (0..rows * cols)
                    .map(|i| ((i * 17 + rows * 13 + cols * 7) % 31) as f64 / 3.0 - 4.0)
                    .collect();

                for (&p, &maxnorm) in ps.iter().zip(maxnorms.iter()) {
                    let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
                    let x = s
                        .tensor_variable(values.clone(), vec![rows, cols], false)
                        .unwrap();
                    let once = s.tensor_renorm(x, p, 0, maxnorm).unwrap();
                    let twice = s.tensor_renorm(once, p, 0, maxnorm).unwrap();
                    let once_vals = s.tensor_values(once).unwrap();
                    let twice_vals = s.tensor_values(twice).unwrap();

                    for row in 0..rows {
                        let norm = (0..cols)
                            .map(|col| once_vals[row * cols + col].abs().powf(p))
                            .sum::<f64>()
                            .powf(1.0 / p);
                        let tol = 64.0 * maxnorm.max(norm).max(1.0) * f64::EPSILON;
                        assert!(
                            norm <= maxnorm + 1e-10 + tol,
                            "renorm row {row} p={p} norm={norm} exceeds maxnorm={maxnorm}"
                        );
                    }

                    for (idx, (&once, &twice)) in
                        once_vals.iter().zip(twice_vals.iter()).enumerate()
                    {
                        let diff = (once - twice).abs();
                        let tol = 64.0 * once.abs().max(twice.abs()).max(1.0) * f64::EPSILON;
                        assert!(
                            diff <= 1e-10 || diff <= tol,
                            "renorm idempotence failed at {idx}: once={once}, twice={twice}, \
                             p={p}, maxnorm={maxnorm}, diff={diff:e}, tol={tol:e}"
                        );
                    }
                }
            }
        }
    }

