    #[test]
    fn isin_exact_match_and_f32_support() {
        // The hash-set isin must (1) accept f32 inputs (was f64-only -> errored),
        // and (2) use EXACT equality, not the old fuzzy `< EPSILON` (which would
        // mark a value within machine-epsilon of a test value as a member).
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);

        // f32 inputs (previously UnsupportedDType(F32)).
        let ef32 = s
            .tensor_variable_f32(vec![1.0f32, 2.0, 3.0, 4.0], vec![4], false)
            .unwrap();
        let tf32 = s
            .tensor_variable_f32(vec![2.0f32, 4.0], vec![2], false)
            .unwrap();
        let out = s.tensor_isin(ef32, tf32).unwrap();
        assert_eq!(
            s.tensor_values_lossy_f64(out).unwrap(),
            vec![0.0, 1.0, 0.0, 1.0]
        );

        // Exact: 1.0 + 1 ULP is NOT a member of {1.0} (old fuzzy match would
        // wrongly include it).
        let near = 1.0_f64 + f64::EPSILON;
        let e = s.tensor_variable(vec![near, 1.0], vec![2], false).unwrap();
        let t = s.tensor_variable(vec![1.0], vec![1], false).unwrap();
        let out2 = s.tensor_isin(e, t).unwrap();
        assert_eq!(
            s.tensor_values(out2).unwrap(),
            vec![0.0, 1.0],
            "exact membership: 1.0+eps not in {{1.0}}"
        );

        // +0.0 and -0.0 are equal members.
        let e0 = s.tensor_variable(vec![-0.0, 0.0], vec![2], false).unwrap();
        let t0 = s.tensor_variable(vec![0.0], vec![1], false).unwrap();
        let out3 = s.tensor_isin(e0, t0).unwrap();
        assert_eq!(
            s.tensor_values(out3).unwrap(),
            vec![1.0, 1.0],
            "-0.0 and 0.0 are members of {{0.0}}"
        );
    }

    #[test]
    fn discrete_ops_fail_loud_on_requires_grad() {
        // Regression for frankentorch-gec0: unique, unique_consecutive,
        // histc, isin used to silently sever autograd via tensor_values.
        // Each is intrinsically non-differentiable; now fails loud on
        // requires_grad input.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s
            .tensor_variable(vec![1.0, 2.0, 2.0, 3.0], vec![4], true)
            .unwrap();
        let unique_err = s
            .tensor_unique(x, false, false, false)
            .expect_err("unique must fail loud on requires_grad");
        assert!(format!("{unique_err:?}").contains("autograd not supported"));
        let cons_err = s
            .tensor_unique_consecutive(x, false, false)
            .expect_err("unique_consecutive must fail loud on requires_grad");
        assert!(format!("{cons_err:?}").contains("autograd not supported"));
        let histc_err = s
            .tensor_histc(x, 3, 0.0, 4.0)
            .expect_err("histc must fail loud on requires_grad");
        assert!(format!("{histc_err:?}").contains("autograd not supported"));
        let test = s.tensor_variable(vec![2.0], vec![1], false).unwrap();
        let isin_err = s
            .tensor_isin(x, test)
            .expect_err("isin must fail loud on requires_grad elements");
        assert!(format!("{isin_err:?}").contains("autograd not supported"));
    }

    // ── triangular_solve tests ──────────────────────────────────────────

    #[test]
    fn triangular_solve_lower() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        // L = [[2, 0], [1, 3]], b = [4, 7]
        // Forward sub: x0 = 4/2 = 2, x1 = (7 - 1*2)/3 = 5/3
        let a = s
            .tensor_variable(vec![2.0, 0.0, 1.0, 3.0], vec![2, 2], false)
            .unwrap();
        let b = s
            .tensor_variable(vec![4.0, 7.0], vec![2, 1], false)
            .unwrap();
        let x = s.tensor_triangular_solve(a, b, false).unwrap();
        let vals = s.tensor_values(x).unwrap();
        assert!((vals[0] - 2.0).abs() < 1e-10);
        assert!((vals[1] - 5.0 / 3.0).abs() < 1e-10);
    }

    #[test]
    fn triangular_solve_upper() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        // U = [[2, 1], [0, 3]], b = [5, 6]
        // Back sub: x1 = 6/3 = 2, x0 = (5 - 1*2)/2 = 1.5
        let a = s
            .tensor_variable(vec![2.0, 1.0, 0.0, 3.0], vec![2, 2], false)
            .unwrap();
        let b = s
            .tensor_variable(vec![5.0, 6.0], vec![2, 1], false)
            .unwrap();
        let x = s.tensor_triangular_solve(a, b, true).unwrap();
        let vals = s.tensor_values(x).unwrap();
        assert!((vals[0] - 1.5).abs() < 1e-10);
        assert!((vals[1] - 2.0).abs() < 1e-10);
    }

    #[test]
    fn triangular_solve_propagates_gradient_through_a_and_b() {
        // Regression test for frankentorch-skpl. tensor_triangular_solve
        // used to extract values, run substitution, and rebuild a
        // requires_grad=false leaf — same severed-autograd pattern
        // recently fixed for cov / corrcoef / mode etc. After
        // wrapping in tensor_apply_function with the analytical
        //     grad_B = A^{-T} grad_X
        //     grad_A = -A^{-T} grad_X X^T   (masked to A's triangle)
        // gradients flow through both A and B.
        //
        // For diagonal A = diag(2, 4) and B = [10, 20] (lower):
        //   X = [10/2, 20/4] = [5, 5]
        //   Under sum loss: grad_X = [1, 1]
        //   grad_B = A^{-T} grad_X = [1/2, 1/4]
        //   grad_A_full = -A^{-T} grad_X X^T (outer):
        //     [[-1/2 * 5, -1/2 * 5],
        //      [-1/4 * 5, -1/4 * 5]]
        //     = [[-2.5, -2.5], [-1.25, -1.25]]
        //   masked to lower triangle (upper=false) keeps i >= k:
        //     grad_A = [[-2.5, 0], [-1.25, -1.25]]
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let a = s
            .tensor_variable(vec![2.0, 0.0, 0.0, 4.0], vec![2, 2], true)
            .unwrap();
        let b = s
            .tensor_variable(vec![10.0, 20.0], vec![2, 1], true)
            .unwrap();
        let x = s.tensor_triangular_solve(a, b, false).unwrap();
        let loss = s.tensor_sum(x).unwrap();
        let report = s.tensor_backward(loss).unwrap();
        let grad_a = s
            .tensor_gradient(&report, a)
            .expect("triangular_solve must propagate gradient through A");
        let grad_b = s
            .tensor_gradient(&report, b)
            .expect("triangular_solve must propagate gradient through B");

        let exp_a = [-2.5_f64, 0.0, -1.25, -1.25];
        let exp_b = [0.5_f64, 0.25];
        for (i, (&g, &e)) in grad_a.iter().zip(exp_a.iter()).enumerate() {
            assert!(
                (g - e).abs() < 1e-12,
                "triangular_solve grad_A[{i}] = {g}, expected {e}"
            );
        }
        for (i, (&g, &e)) in grad_b.iter().zip(exp_b.iter()).enumerate() {
            assert!(
                (g - e).abs() < 1e-12,
                "triangular_solve grad_B[{i}] = {g}, expected {e}"
            );
        }
    }

    // ── cholesky_inverse tests ──────────────────────────────────────────

    #[test]
    fn cholesky_inverse_identity() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let eye = s.eye(3, false).unwrap();
        let l = s.tensor_linalg_cholesky(eye, false).unwrap();
        let inv = s.tensor_cholesky_inverse(l, false).unwrap();
        let vals = s.tensor_values(inv).unwrap();
        // inv(I) = I
        assert!((vals[0] - 1.0).abs() < 1e-10);
        assert!(vals[1].abs() < 1e-10);
        assert!((vals[4] - 1.0).abs() < 1e-10);
    }

    #[test]
    fn cholesky_inverse_propagates_gradient_via_cholesky_solve() {
        // Coverage check that cholesky_inverse's autograd works
        // automatically now that cholesky_solve has been composed
        // through tensor_triangular_solve (frankentorch-tw0y).
        // cholesky_inverse(L, upper) ≡ cholesky_solve(I, L, upper),
        // so as long as cholesky_solve's tape edges are intact, we
        // just need to verify the gradient propagation runs without
        // hitting the prior fail-loud path.
        //
        // For diagonal L = diag(2, 3) (so A = L L^T = diag(4, 9)),
        // A^{-1} = diag(1/4, 1/9). Under sum loss the gradient w.r.t.
        // the cholesky factor flows back through both
        // triangular_solve calls and is non-trivially non-zero.
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let l = s
            .tensor_variable(vec![2.0, 0.0, 0.0, 3.0], vec![2, 2], true)
            .unwrap();
        let inv = s.tensor_cholesky_inverse(l, false).unwrap();
        let loss = s.tensor_sum(inv).unwrap();
        let report = s.tensor_backward(loss).unwrap();
        let grad_l = s
            .tensor_gradient(&report, l)
            .expect("cholesky_inverse must propagate gradient through L");
        // Expect a non-zero grad on the diagonal. cholesky_solve now uses torch's
        // DENSE factor-gradient convention (frankentorch-crvxw), so off-diagonals
        // are no longer masked to zero — we just sanity-check the grad is non-zero
        // on the diagonal and finite everywhere.
        assert!(grad_l[0].abs() > 1e-6, "grad on L[0,0] should be non-zero");
        assert!(grad_l[3].abs() > 1e-6, "grad on L[1,1] should be non-zero");
        assert!(
            grad_l.iter().all(|g| g.is_finite()),
            "all gradient entries must be finite"
        );
    }

