    #[test]
    fn nanquantile_quickselect_matches_sort_with_ties_and_nan() {
        // frankentorch-kgs4.60: the quickselect nan-reduction paths must equal the
        // previous full-sort-of-non-NaN-pairs bit-for-bit, including ties and NaN.
        let data: Vec<f64> = vec![
            3.0,
            f64::NAN,
            1.0,
            3.0,
            2.0,
            1.0,
            f64::NAN,
            3.0,
            5.0,
            2.0,
            1.0,
            4.0,
            0.0,
            5.0,
            2.0,
        ];
        // Reference = filter NaN, stable sort by value, index by rank.
        let reference = |q: f64, mode: &str| -> f64 {
            let mut nn: Vec<f64> = data.iter().copied().filter(|v| !v.is_nan()).collect();
            nn.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
            let n = nn.len();
            let idx = q * (n - 1) as f64;
            let (lo, hi) = (idx.floor() as usize, idx.ceil() as usize);
            let frac = idx - lo as f64;
            match mode {
                "lower" => nn[lo],
                "higher" => nn[hi],
                "nearest" => nn[idx.round_ties_even() as usize],
                "midpoint" if lo != hi => (nn[lo] + nn[hi]) * 0.5,
                "linear" if lo != hi => nn[lo] * (1.0 - frac) + nn[hi] * frac,
                _ => nn[lo],
            }
        };
        for &q in &[0.0, 0.25, 0.5, 0.7, 1.0] {
            for mode in ["linear", "lower", "higher", "nearest", "midpoint"] {
                let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
                let x = s
                    .tensor_variable(data.clone(), vec![data.len()], false)
                    .unwrap();
                let out = s.tensor_nanquantile_interpolation(x, q, mode).unwrap();
                let got = s.tensor_values(out).unwrap()[0];
                assert_eq!(
                    got.to_bits(),
                    reference(q, mode).to_bits(),
                    "q={q} mode={mode}"
                );
            }
        }
        // nanmedian == nanquantile(0.5, "lower").
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s
            .tensor_variable(data.clone(), vec![data.len()], false)
            .unwrap();
        let med = s.tensor_nanmedian(x).unwrap();
        assert_eq!(
            s.tensor_values(med).unwrap()[0].to_bits(),
            reference(0.5, "lower").to_bits()
        );
    }

