    #[test]
    fn test_index_reduce_include_self_false_keeps_untouched() {
        // torch parity (torch 2.12): index_reduce with include_self=False
        // excludes the self term ONLY at reduced positions; positions that
        // receive no source element keep their original input value. Base
        // [10,20,30,40], index [0,0], src [1,5] — only position 0 is touched.
        //   amax False: [5,  20,30,40]   amax True: [10, 20,30,40]
        //   amin False: [1,  20,30,40]   amin True: [1,  20,30,40]
        //   prod False: [5,  20,30,40]   prod True: [50, 20,30,40]
        //   mean False: [3,  20,30,40]   mean True: [16/3,20,30,40]
        let cases: &[(&str, bool, [f64; 4])] = &[
            ("amax", false, [5.0, 20.0, 30.0, 40.0]),
            ("amax", true, [10.0, 20.0, 30.0, 40.0]),
            ("amin", false, [1.0, 20.0, 30.0, 40.0]),
            ("amin", true, [1.0, 20.0, 30.0, 40.0]),
            ("prod", false, [5.0, 20.0, 30.0, 40.0]),
            ("prod", true, [50.0, 20.0, 30.0, 40.0]),
            ("mean", false, [3.0, 20.0, 30.0, 40.0]),
            ("mean", true, [16.0 / 3.0, 20.0, 30.0, 40.0]),
        ];
        for &(reduce, include_self, ref expect) in cases {
            let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
            let input = s
                .tensor_variable(vec![10.0, 20.0, 30.0, 40.0], vec![4], false)
                .unwrap();
            let index = s.tensor_variable(vec![0.0, 0.0], vec![2], false).unwrap();
            let source = s.tensor_variable(vec![1.0, 5.0], vec![2], false).unwrap();
            let result = s
                .tensor_index_reduce(input, 0, index, source, reduce, include_self)
                .unwrap();
            let vals = s.tensor_values(result).unwrap();
            for (i, (&got, &want)) in vals.iter().zip(expect.iter()).enumerate() {
                assert!(
                    (got - want).abs() < 1e-10 && got.is_finite(),
                    "{reduce} include_self={include_self} pos {i}: got {got} want {want}"
                );
            }
        }
    }

