    #[test]
    fn selu_celu_use_expm1_bit_exact_torch() {
        // Regression: the negative branch used exp(x)-1.0 (catastrophic
        // cancellation near 0), diverging from torch which uses expm1. At small
        // |x| ft must now equal the expm1 closed form bit-for-bit (== torch f64).
        const ALPHA: f64 = 1.6732632423543772848170429916717;
        const SCALE: f64 = 1.0507009873554804934193349852946;
        let xs = vec![-0.1f64, -0.001, -1e-7, -2.0];
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        // selu: (SCALE*ALPHA)*expm1(x)
        let xv = s.tensor_variable(xs.clone(), vec![4], false).unwrap();
        let selu_n = s.tensor_selu(xv).unwrap();
        let selu = s.tensor_values(selu_n).unwrap();
        for (i, &x) in xs.iter().enumerate() {
            assert_eq!(
                selu[i].to_bits(),
                (SCALE * ALPHA * x.exp_m1()).to_bits(),
                "selu({x}) not bit-exact to expm1 form"
            );
        }
        // celu (alpha=0.5): alpha*expm1(x/alpha)
        let xv2 = s.tensor_variable(xs.clone(), vec![4], false).unwrap();
        let celu_n = s.tensor_celu(xv2, 0.5).unwrap();
        let celu = s.tensor_values(celu_n).unwrap();
        for (i, &x) in xs.iter().enumerate() {
            assert_eq!(
                celu[i].to_bits(),
                (0.5 * (x / 0.5).exp_m1()).to_bits(),
                "celu({x},0.5) not bit-exact to expm1 form"
            );
        }
    }

    #[test]
    fn test_prelu_scalar_weight() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let input = s
            .tensor_variable(vec![1.0, -1.0, 2.0, -2.0], vec![4], false)
            .unwrap();
        let weight = s.tensor_variable(vec![0.25], vec![1], false).unwrap();
        let result = s.tensor_prelu(input, weight).unwrap();
        let vals = s.tensor_values(result).unwrap();
        assert!((vals[0] - 1.0).abs() < 1e-10);
        assert!((vals[1] + 0.25).abs() < 1e-10); // -1 * 0.25
        assert!((vals[2] - 2.0).abs() < 1e-10);
        assert!((vals[3] + 0.5).abs() < 1e-10); // -2 * 0.25
    }

    #[test]
    fn prelu_backward_input_and_weight_and_value_parity() {
        // Scalar weight. x = [1,-1,2,-2], w = 0.25.
        // grad_x = [1, w, 1, w] = [1, 0.25, 1, 0.25] (upstream ones).
        // grad_w = sum over x<0 of x = -1 + -2 = -3.
        let x = vec![1.0, -1.0, 2.0, -2.0];
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        // Value parity.
        let x_ng = s.tensor_variable(x.clone(), vec![4], false).unwrap();
        let w_ng = s.tensor_variable(vec![0.25], vec![1], false).unwrap();
        let o_ng = s.tensor_prelu(x_ng, w_ng).unwrap();
        let v_ng = s.tensor_values(o_ng).unwrap();
        let x_g = s.tensor_variable(x.clone(), vec![4], true).unwrap();
        let w_g = s.tensor_variable(vec![0.25], vec![1], true).unwrap();
        let o_g = s.tensor_prelu(x_g, w_g).unwrap();
        let v_g = s.tensor_values(o_g).unwrap();
        for (a, b) in v_ng.iter().zip(v_g.iter()) {
            assert_eq!(
                a.to_bits(),
                b.to_bits(),
                "prelu grad/non-grad value mismatch"
            );
        }
        let loss = s.tensor_sum(o_g).unwrap();
        let report = s.tensor_backward(loss).unwrap();
        let gx = s
            .tensor_gradient(&report, x_g)
            .expect("prelu grad_x present");
        let gw = s
            .tensor_gradient(&report, w_g)
            .expect("prelu grad_w present");
        assert_eq!(gx, vec![1.0, 0.25, 1.0, 0.25]);
        assert_eq!(gw, vec![-3.0]);

        // Per-channel weight on [N,C,L] = [1,2,2]: x = [[1,-2],[-3,4]],
        // w = [0.5, 0.1]. channel 0 = {1,-2}, channel 1 = {-3,4}.
        // grad_x = [1, w0, w1, 1] = [1, 0.5, 0.1, 1].
        // grad_w0 = sum x<0 in ch0 = -2; grad_w1 = -3.
        let x2 = vec![1.0, -2.0, -3.0, 4.0];
        let x2g = s.tensor_variable(x2, vec![1, 2, 2], true).unwrap();
        let w2g = s.tensor_variable(vec![0.5, 0.1], vec![2], true).unwrap();
        let o2 = s.tensor_prelu(x2g, w2g).unwrap();
        let loss2 = s.tensor_sum(o2).unwrap();
        let report2 = s.tensor_backward(loss2).unwrap();
        let gx2 = s
            .tensor_gradient(&report2, x2g)
            .expect("prelu grad_x2 present");
        let gw2 = s
            .tensor_gradient(&report2, w2g)
            .expect("prelu grad_w2 present");
        assert_eq!(gx2, vec![1.0, 0.5, 0.1, 1.0]);
        assert_eq!(gw2, vec![-2.0, -3.0]);
    }

    #[test]
    fn test_rrelu_basic() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let input = s
            .tensor_variable(vec![1.0, -1.0, 2.0, -2.0], vec![4], false)
            .unwrap();
        let result = s.tensor_rrelu(input, 0.1, 0.3).unwrap();
        let vals = s.tensor_values(result).unwrap();
        assert!((vals[0] - 1.0).abs() < 1e-10);
        assert!((vals[1] + 0.2).abs() < 1e-10); // -1 * 0.2 (midpoint)
        assert!((vals[2] - 2.0).abs() < 1e-10);
        assert!((vals[3] + 0.4).abs() < 1e-10); // -2 * 0.2
    }

    #[test]
    fn test_channel_shuffle_basic() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        // (1, 4, 1, 1) with channels [1, 2, 3, 4], groups=2
        // After shuffle: [1, 3, 2, 4]
        let input = s
            .tensor_variable(vec![1.0, 2.0, 3.0, 4.0], vec![1, 4, 1, 1], false)
            .unwrap();
        let result = s.tensor_channel_shuffle(input, 2).unwrap();
        let vals = s.tensor_values(result).unwrap();
        assert!((vals[0] - 1.0).abs() < 1e-10);
        assert!((vals[1] - 3.0).abs() < 1e-10);
        assert!((vals[2] - 2.0).abs() < 1e-10);
        assert!((vals[3] - 4.0).abs() < 1e-10);
    }

