        let x = s.tensor_variable(vec![2.0, 3.0], vec![2], true).unwrap();
        let y = s.tensor_mul(x, x).unwrap();
        let z = s.tensor_sum(y).unwrap();
        s.tensor_backward(z).unwrap();
        let grad = s.tensor_grad(x).unwrap();
