    #[test]
    fn test_tensor_autograd_grad() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s.tensor_variable(vec![2.0, 3.0], vec![2], true).unwrap();
        let y = s.tensor_mul(x, x).unwrap();
        let z = s.tensor_sum(y).unwrap();

        // Use autograd_grad to get gradients without accumulating
        let grads = s
            .tensor_autograd_grad(&[z], &[x], None, false, false)
            .unwrap();

        // Should return gradient d(z)/d(x) = 2*x = [4.0, 6.0]
        assert_eq!(grads.len(), 1);
        assert_eq!(grads[0].as_ref().unwrap(), &[4.0, 6.0]);

        // The accumulated gradient should NOT be set (autograd_grad doesn't accumulate)
        // But after calling autograd_grad, the backward was run so gradients ARE accumulated
        // This is a simplification - full PyTorch autograd.grad has separate code paths
    }

    #[test]
    fn autograd_grad_grad_outputs_computes_vector_jacobian_product() {
        // y = W @ x with constant W, so the Jacobian J = W is non-diagonal and
        // Jᵀv = Wᵀv. A correct VJP contracts v over the output dimension; the
        // old buggy path (ones-seed backward then elementwise scale by v) would
        // give Wᵀ·ones ⊙ v = [4,6] ⊙ [1,2] = [4,12] instead of [7,10].
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let w = s
            .tensor_variable(vec![1.0, 2.0, 3.0, 4.0], vec![2, 2], false)
            .unwrap();
        let x = s.tensor_variable(vec![5.0, 7.0], vec![2, 1], true).unwrap();
        let y = s.tensor_matmul(w, x).unwrap();
        let grads = s
            .tensor_autograd_grad(&[y], &[x], Some(&[vec![1.0, 2.0]]), false, false)
            .unwrap();
        assert_eq!(grads.len(), 1);
        assert_eq!(grads[0].as_ref().unwrap(), &[7.0, 10.0]);
    }

    #[test]
    fn autograd_grad_grad_outputs_scales_diagonal_jacobian() {
        // y = x*x, J = diag(2x) = diag([4,6]); Jᵀv = [4*1, 6*2] = [4,12].
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s.tensor_variable(vec![2.0, 3.0], vec![2], true).unwrap();
        let y = s.tensor_mul(x, x).unwrap();
        let grads = s
            .tensor_autograd_grad(&[y], &[x], Some(&[vec![1.0, 2.0]]), false, false)
            .unwrap();
        assert_eq!(grads[0].as_ref().unwrap(), &[4.0, 12.0]);
    }

    #[test]
    fn functional_vjp_contracts_over_outputs() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let w = s
            .tensor_variable(vec![1.0, 2.0, 3.0, 4.0], vec![2, 2], false)
            .unwrap();
        let x = s.tensor_variable(vec![5.0, 7.0], vec![2, 1], true).unwrap();
        let y = s.tensor_matmul(w, x).unwrap();
        let vjp = s.tensor_functional_vjp(y, &[x], vec![1.0, 2.0]).unwrap();
        assert_eq!(vjp[0].as_ref().unwrap(), &[7.0, 10.0]);
    }

    #[test]
    fn autograd_grad_rejects_grad_outputs_length_mismatch() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s.tensor_variable(vec![2.0, 3.0], vec![2], true).unwrap();
        let y = s.tensor_mul(x, x).unwrap();
        // Two grad_outputs entries for a single output must be rejected.
        let err = s.tensor_autograd_grad(
            &[y],
            &[x],
            Some(&[vec![1.0, 2.0], vec![3.0, 4.0]]),
            false,
            false,
        );
        assert!(err.is_err());
    }

    // f(x,y) = x²y + y³ ; ∇f = [2xy, x²+3y²] ; H = [[2y, 2x], [2x, 6y]].
    // At (1,2): H = [[4, 2], [2, 12]].
    fn build_xy2_plus_y3(
        s: &mut FrankenTorchSession,
    ) -> (TensorNodeId, TensorNodeId, TensorNodeId) {
        let x = s.tensor_variable(vec![1.0], vec![1], true).unwrap();
        let y = s.tensor_variable(vec![2.0], vec![1], true).unwrap();
        let x2 = s.tensor_mul(x, x).unwrap();
        let x2y = s.tensor_mul(x2, y).unwrap();
        let y2 = s.tensor_mul(y, y).unwrap();
        let y3 = s.tensor_mul(y2, y).unwrap();
        let f = s.tensor_add(x2y, y3).unwrap();
        (x, y, f)
    }

    #[test]
    fn functional_hvp_matches_hessian_vector_product() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let (x, y, f) = build_xy2_plus_y3(&mut s);
        // H @ [1, 0]ᵀ = [4, 2].
        let hv = s
            .tensor_functional_hvp(f, &[x, y], &[vec![1.0], vec![0.0]])
            .unwrap();
        assert_eq!(hv[0].as_ref().unwrap(), &[4.0]);
        assert_eq!(hv[1].as_ref().unwrap(), &[2.0]);
    }

    #[test]
    fn functional_hvp_second_column() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let (x, y, f) = build_xy2_plus_y3(&mut s);
        // H @ [0, 1]ᵀ = [2, 12].
        let hv = s
            .tensor_functional_hvp(f, &[x, y], &[vec![0.0], vec![1.0]])
            .unwrap();
        assert_eq!(hv[0].as_ref().unwrap(), &[2.0]);
        assert_eq!(hv[1].as_ref().unwrap(), &[12.0]);
    }

    #[test]
    fn functional_vhp_equals_hvp_for_symmetric_hessian() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let (x, y, f) = build_xy2_plus_y3(&mut s);
        // vᵀH with v = [1, 1] = [4+2, 2+12] = [6, 14].
        let vh = s
            .tensor_functional_vhp(f, &[x, y], &[vec![1.0], vec![1.0]])
            .unwrap();
        assert_eq!(vh[0].as_ref().unwrap(), &[6.0]);
        assert_eq!(vh[1].as_ref().unwrap(), &[14.0]);
    }

    #[test]
    fn functional_jacobian_linear_map_recovers_weight_matrix() {
        // y = W @ x with constant W ⇒ J = W (row-major [out, in]).
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let w = s
            .tensor_variable(vec![1.0, 2.0, 3.0, 4.0], vec![2, 2], false)
            .unwrap();
        let x = s.tensor_variable(vec![5.0, 7.0], vec![2, 1], true).unwrap();
        let y = s.tensor_matmul(w, x).unwrap();
        let jac = s.tensor_functional_jacobian(y, &[x]).unwrap();
        // Row 0 = ∂y0/∂x = [1,2]; row 1 = ∂y1/∂x = [3,4].
        assert_eq!(jac[0], vec![1.0, 2.0, 3.0, 4.0]);
    }

    #[test]
    fn functional_jacobian_elementwise_square_is_diagonal() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s.tensor_variable(vec![2.0, 3.0], vec![2], true).unwrap();
        let y = s.tensor_mul(x, x).unwrap(); // J = diag(2x) = diag([4,6])
        let jac = s.tensor_functional_jacobian(y, &[x]).unwrap();
        assert_eq!(jac[0], vec![4.0, 0.0, 0.0, 6.0]);
    }

    #[test]
    fn functional_hessian_quadratic_form_is_a_plus_a_transpose() {
        // f(x) = xᵀ A x ⇒ H = A + Aᵀ (off-diagonal, exercises cross terms).
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let a = s
            .tensor_variable(vec![1.0, 2.0, 3.0, 4.0], vec![2, 2], false)
            .unwrap();
        let x = s.tensor_variable(vec![5.0, 7.0], vec![2, 1], true).unwrap();
        let ax = s.tensor_matmul(a, x).unwrap();
        let prod = s.tensor_mul(x, ax).unwrap();
        let f = s.tensor_sum(prod).unwrap();
        let h = s.tensor_functional_hessian(f, x).unwrap();
        // A + Aᵀ = [[2,5],[5,8]].
        assert_eq!(h, vec![2.0, 5.0, 5.0, 8.0]);
    }

    #[test]
    fn functional_hessian_sum_of_squares_is_twice_identity() {
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let x = s.tensor_variable(vec![3.0, -1.0], vec![2], true).unwrap();
        let x2 = s.tensor_mul(x, x).unwrap();
        let f = s.tensor_sum(x2).unwrap(); // f = Σ x², H = 2I
        let h = s.tensor_functional_hessian(f, x).unwrap();
        assert_eq!(h, vec![2.0, 0.0, 0.0, 2.0]);
    }

