    #[test]
    fn activation_gradients_match_torch_at_extremes() {
        // Conformance: backward gradients of the activation family must stay finite
        // and match torch at extreme inputs x ∈ {-1000,-50,-1,1,50,1000} (the
        // numerical-stability axis where the softplus forward-overflow bug lived).
        // Golden grads = torch 2.12 autograd, rounded to 6 dp.
        let xs = vec![-1000.0f64, -50.0, -1.0, 1.0, 50.0, 1000.0];
        macro_rules! check_grad {
            ($name:literal, $m:ident, $want:expr) => {{
                let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
                let x = s.tensor_variable(xs.clone(), vec![6], true).unwrap();
                let y = s.$m(x).unwrap();
                let out = s.tensor_sum(y).unwrap();
                let rep = s.tensor_backward(out).unwrap();
                let g = s.tensor_gradient(&rep, x).unwrap();
                let want: [f64; 6] = $want;
                for i in 0..6 {
                    assert!(g[i].is_finite(), "{} grad non-finite at x={}", $name, xs[i]);
                    let (gi, wi, xi) = (g[i], want[i], xs[i]);
                    assert!(
                        (gi - wi).abs() < 1e-5,
                        "{} grad x={xi}: got {gi}, want {wi}",
                        $name
                    );
                }
            }};
        }
        check_grad!(
            "sigmoid",
            tensor_sigmoid,
            [0.0, 0.0, 0.196612, 0.196612, 0.0, 0.0]
        );
        check_grad!(
            "softplus",
            tensor_softplus,
            [0.0, 0.0, 0.268941, 0.731059, 1.0, 1.0]
        );
        check_grad!(
            "silu",
            tensor_silu,
            [0.0, 0.0, 0.072329, 0.927671, 1.0, 1.0]
        );
        check_grad!(
            "mish",
            tensor_mish,
            [0.0, 0.0, 0.059217, 1.049036, 1.0, 1.0]
        );
        check_grad!(
            "gelu",
            tensor_gelu,
            [0.0, 0.0, -0.083315, 1.083315, 1.0, 1.0]
        );
        check_grad!(
            "logsigmoid",
            tensor_logsigmoid,
            [1.0, 1.0, 0.731059, 0.268941, 0.0, 0.0]
        );
        check_grad!("elu", tensor_elu, [0.0, 0.0, 0.367879, 1.0, 1.0, 1.0]);
        check_grad!(
            "selu",
            tensor_selu,
            [0.0, 0.0, 0.646769, 1.050701, 1.050701, 1.050701]
        );
    }

    #[test]
    fn inplace_softplus_family_matches_out_of_place_and_no_overflow() {
        // Regression: softplus_/mish_/logsigmoid_ used naive ln(1+exp(x)), which
        // overflows to +inf for large x and (logsigmoid_, x>0) computed -ln1p(-x)
        // = NaN. Each in-place op must equal its out-of-place form bit-for-bit and
        // stay finite at extreme inputs (torch: softplus(800)=800, logsigmoid(800)=0).
        let xs = vec![-800.0f64, -2.0, -0.1, 0.5, 2.0, 50.0, 800.0];
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);

        let oop_sp = s.tensor_variable(xs.clone(), vec![7], false).unwrap();
        let sp_n = s.tensor_softplus(oop_sp).unwrap();
        let sp_ref = s.tensor_values(sp_n).unwrap();
        let ip_sp = s.tensor_variable(xs.clone(), vec![7], false).unwrap();
        s.tensor_softplus_(ip_sp).unwrap();
        let sp_ip = s.tensor_values(ip_sp).unwrap();

        let oop_ls = s.tensor_variable(xs.clone(), vec![7], false).unwrap();
        let ls_n = s.tensor_logsigmoid(oop_ls).unwrap();
        let ls_ref = s.tensor_values(ls_n).unwrap();
        let ip_ls = s.tensor_variable(xs.clone(), vec![7], false).unwrap();
        s.tensor_logsigmoid_(ip_ls).unwrap();
        let ls_ip = s.tensor_values(ip_ls).unwrap();

        let oop_mi = s.tensor_variable(xs.clone(), vec![7], false).unwrap();
        let mi_n = s.tensor_mish(oop_mi).unwrap();
        let mi_ref = s.tensor_values(mi_n).unwrap();
        let ip_mi = s.tensor_variable(xs.clone(), vec![7], false).unwrap();
        s.tensor_mish_(ip_mi).unwrap();
        let mi_ip = s.tensor_values(ip_mi).unwrap();

        for i in 0..xs.len() {
            assert!(sp_ip[i].is_finite() && ls_ip[i].is_finite() && mi_ip[i].is_finite());
            let (xi, spi, spr) = (xs[i], sp_ip[i].to_bits(), sp_ref[i].to_bits());
            let (lsi, lsr) = (ls_ip[i].to_bits(), ls_ref[i].to_bits());
            let (mii, mir) = (mi_ip[i].to_bits(), mi_ref[i].to_bits());
            assert_eq!(spi, spr, "softplus_ x={xi}");
            assert_eq!(lsi, lsr, "logsigmoid_ x={xi}");
            assert_eq!(mii, mir, "mish_ x={xi}");
        }
    }

    #[test]
    fn inplace_hardsigmoid_hardswish_match_out_of_place() {
        // Regression: in-place used x/6+0.5 (clamped), differing by 1 ULP from the
        // out-of-place (x+3)/6 kernel form (== torch). In-place must equal it.
        let xs = vec![-4.0f64, -3.0, -2.5, -1.0, 0.0, 1.0, 2.5, 3.0, 4.0];
        let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
        let a = s.tensor_variable(xs.clone(), vec![9], false).unwrap();
        let hs_n = s.tensor_hardsigmoid(a).unwrap();
        let hs_ref = s.tensor_values(hs_n).unwrap();
        let b = s.tensor_variable(xs.clone(), vec![9], false).unwrap();
        s.tensor_hardsigmoid_(b).unwrap();
        let hs_ip = s.tensor_values(b).unwrap();
        let c = s.tensor_variable(xs.clone(), vec![9], false).unwrap();
        let hw_n = s.tensor_hardswish(c).unwrap();
        let hw_ref = s.tensor_values(hw_n).unwrap();
        let d = s.tensor_variable(xs.clone(), vec![9], false).unwrap();
        s.tensor_hardswish_(d).unwrap();
        let hw_ip = s.tensor_values(d).unwrap();
        for i in 0..xs.len() {
            let xi = xs[i];
            let (hsi, hsr) = (hs_ip[i].to_bits(), hs_ref[i].to_bits());
            let (hwi, hwr) = (hw_ip[i].to_bits(), hw_ref[i].to_bits());
            assert_eq!(hsi, hsr, "hardsigmoid_ x={xi}");
            assert_eq!(hwi, hwr, "hardswish_ x={xi}");
        }
    }

