    #[test]
    fn dist_substream_parallel_matches_serial_and_is_deterministic() {
        // The per-element sub-stream sampler seeds each output element from one parent draw
        // and samples from `Xoshiro256PlusPlus::new(seed_i)`, so the map is order-independent
        // and the parallel (large `len`) branch must be BIT-IDENTICAL to a serial reference
        // that reproduces the same parent seed draws and per-element map. This is the parity
        // proof for the rejection-sampler parallelization (frankentorch-dist-par).
        use crate::Xoshiro256PlusPlus;
        let len = 20_000usize; // > SUBSTREAM_PAR_MIN (1<<14) -> exercises the parallel branch
        let f = |_i: usize, r: &mut Xoshiro256PlusPlus| r.next_gamma(2.5);

        let mut rng_par = Xoshiro256PlusPlus::new(12345);
        let par = rng_par.substream_sample(len, f);

        // Serial reference: same parent seed -> same seed draws -> same per-element map.
        let mut rng_ser = Xoshiro256PlusPlus::new(12345);
        let seeds: Vec<u64> = (0..len).map(|_| rng_ser.next_u64()).collect();
        let serial: Vec<f64> = seeds
            .iter()
            .map(|&sd| f(0, &mut Xoshiro256PlusPlus::new(sd)))
            .collect();
        assert_eq!(
            par, serial,
            "parallel sub-stream != serial reference (bit-exact)"
        );

        // Determinism: a second parallel run with the same parent seed is identical.
        let mut rng_par2 = Xoshiro256PlusPlus::new(12345);
        assert_eq!(
            par,
            rng_par2.substream_sample(len, f),
            "sub-stream not deterministic"
        );

        // Distributional sanity: Gamma(2.5, 1) has mean 2.5 and variance 2.5.
        let mean = par.iter().sum::<f64>() / len as f64;
        let var = par.iter().map(|&x| (x - mean).powi(2)).sum::<f64>() / len as f64;
        assert!((mean - 2.5).abs() < 0.1, "gamma mean {mean} not ~2.5");
        assert!((var - 2.5).abs() < 0.3, "gamma var {var} not ~2.5");
        assert!(
            par.iter().all(|&x| x > 0.0),
            "gamma samples must be positive"
        );
    }

    #[test]
    fn tensor_gamma_family_parallel_deterministic_and_distributional() {
        // Session-level check: the parallelized gamma-family samplers are reproducible
        // (same session seed -> identical output) and distributionally correct.
        let shape = vec![50_000usize];
        let mut s1 = FrankenTorchSession::new(ExecutionMode::Strict);
        let g1 = s1.tensor_gamma(3.0, 2.0, shape.clone(), false).unwrap();
        let v1 = s1.tensor_values(g1).unwrap();
        let mut s2 = FrankenTorchSession::new(ExecutionMode::Strict);
        let g2 = s2.tensor_gamma(3.0, 2.0, shape.clone(), false).unwrap();
        let v2 = s2.tensor_values(g2).unwrap();
        assert_eq!(v1, v2, "tensor_gamma not deterministic across sessions");
        // Gamma(conc=3, rate=2): mean = conc/rate = 1.5, var = conc/rate^2 = 0.75.
        let mean = v1.iter().sum::<f64>() / v1.len() as f64;
        assert!((mean - 1.5).abs() < 0.05, "gamma mean {mean} not ~1.5");
        assert!(
            v1.iter().all(|&x| x > 0.0),
            "gamma samples must be positive"
        );

        // Beta(2,3): mean = 2/(2+3) = 0.4, all in (0,1).
        let mut sb = FrankenTorchSession::new(ExecutionMode::Strict);
        let b = sb.tensor_beta(2.0, 3.0, shape.clone(), false).unwrap();
        let vb = sb.tensor_values(b).unwrap();
        let bmean = vb.iter().sum::<f64>() / vb.len() as f64;
        assert!((bmean - 0.4).abs() < 0.02, "beta mean {bmean} not ~0.4");
        assert!(vb.iter().all(|&x| x > 0.0 && x < 1.0), "beta in (0,1)");
    }

    #[test]
    fn multinomial_parallel_matches_serial_and_is_distributional() {
        // The per-row sub-stream sampler seeds each row from the parent stream in order, so
        // the serial branch (batch < 8) and the parallel branch (batch >= 8) draw the SAME
        // per-row seeds for shared rows -> their outputs are BIT-IDENTICAL. Prove it: rows
        // 0..4 of a serial [4,C] run must equal rows 0..4 of a parallel [16,C] run.
        let c = 50usize;
        let w: Vec<f64> = (0..c).map(|j| 1.0 + (j % 7) as f64).collect();
        let ns = 500usize;
        let mk = |rows: usize| {
            let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
            let mut data = Vec::with_capacity(rows * c);
            for _ in 0..rows {
                data.extend_from_slice(&w);
            }
            let t = s.tensor_variable(data, vec![rows, c], false).unwrap();
            let out = s.multinomial(t, ns, true).unwrap();
            s.tensor_values(out).unwrap()
        };
        let serial = mk(4); // batch 4 < MULTINOMIAL_PAR_MIN_ROWS -> serial branch
        let parallel = mk(16); // batch 16 -> parallel branch
        assert_eq!(
            &serial[..4 * ns],
            &parallel[..4 * ns],
            "multinomial serial vs parallel branch diverged (bit-exact)"
        );
        // Determinism across runs.
        assert_eq!(parallel, mk(16), "multinomial not deterministic");
        // Distributional: identical per-row weights -> empirical freq ~ weight proportion.
        let total_w: f64 = w.iter().sum();
        let mut counts = vec![0u64; c];
        for &idx in &parallel {
            counts[idx as usize] += 1;
        }
        let n = parallel.len() as f64;
        for (j, &wj) in w.iter().enumerate() {
            let expected = wj / total_w;
            let observed = counts[j] as f64 / n;
            assert!(
                (observed - expected).abs() < 0.02,
                "category {j} freq {observed} vs expected {expected}"
            );
        }
    }

    #[test]
    fn inplace_transcendental_rng_matches_out_of_place_bit_exact() {
        // The parallelized in-place transcendental fills reuse the SAME parallel primitives
        // (and identical closures) as their out-of-place counterparts, so on a fresh session
        // (same seed) the in-place fill must equal the out-of-place tensor bit-for-bit.
        let n = 40_000usize; // > the primitive's 1<<15 threshold -> parallel path

        let mut s1 = FrankenTorchSession::new(ExecutionMode::Strict);
        let t = s1.tensor_variable(vec![0.0; n], vec![n], false).unwrap();
        s1.tensor_exponential_(t, 1.5).unwrap();
        let mut s2 = FrankenTorchSession::new(ExecutionMode::Strict);
        let o = s2.tensor_exponential(1.5, vec![n], false).unwrap();
        assert_eq!(
            s1.tensor_values(t).unwrap(),
            s2.tensor_values(o).unwrap(),
            "exponential_ in-place != out-of-place (bit-exact)"
        );

        let mut s3 = FrankenTorchSession::new(ExecutionMode::Strict);
        let t3 = s3.tensor_variable(vec![0.0; n], vec![n], false).unwrap();
        s3.tensor_cauchy_(t3, 0.0, 2.0).unwrap();
        let mut s4 = FrankenTorchSession::new(ExecutionMode::Strict);
        let o4 = s4.tensor_cauchy(0.0, 2.0, vec![n], false).unwrap();
        assert_eq!(
            s3.tensor_values(t3).unwrap(),
            s4.tensor_values(o4).unwrap(),
            "cauchy_ in-place != out-of-place (bit-exact)"
        );

        let mut s5 = FrankenTorchSession::new(ExecutionMode::Strict);
        let t5 = s5.tensor_variable(vec![0.0; n], vec![n], false).unwrap();
        s5.tensor_log_normal_(t5, 0.0, 1.0).unwrap();
        let mut s6 = FrankenTorchSession::new(ExecutionMode::Strict);
        let o6 = s6.tensor_log_normal(0.0, 1.0, vec![n], false).unwrap();
        assert_eq!(
            s5.tensor_values(t5).unwrap(),
            s6.tensor_values(o6).unwrap(),
            "log_normal_ in-place != out-of-place (bit-exact)"
        );

        // geometric_ has no matching out-of-place formula; check integer + distribution.
        let p = 0.25;
        let mut s7 = FrankenTorchSession::new(ExecutionMode::Strict);
        let t7 = s7.tensor_variable(vec![0.0; n], vec![n], false).unwrap();
        s7.tensor_geometric_(t7, p).unwrap();
        let g = s7.tensor_values(t7).unwrap();
        assert!(
            g.iter().all(|&x| x >= 0.0 && x == x.floor()),
            "geometric_ must be non-negative integers"
        );
        let gmean = g.iter().sum::<f64>() / n as f64;
        assert!(
            (gmean - 1.0 / p).abs() < 0.4,
            "geometric_ mean {gmean} not ~{}",
            1.0 / p
        );
    }

