    #[test]
    #[ignore = "perf A/B; run explicitly with --ignored --nocapture"]
    fn bench_lstm_raw_vs_session() {
        // Same-process A/B (one rch exec => one worker => no worker-variance
        // confound) for frankentorch-3k4v. NEW = the raw tensor_lstm forward;
        // OLD = the previous per-timestep session-op path, replicated here by
        // driving lstm_cell in a manual loop exactly as the old tensor_lstm did.
        use std::time::Instant;
        let mk = |n: usize, shift: f64| -> Vec<f64> {
            (0..n)
                .map(|i| (((i as f64) * 0.017 + shift).sin()) * 0.2)
                .collect()
        };

        // Inference is the target use case (batch=1 streaming, no_grad); medium
        // batch is also reported. Assert on the inference config.
        let mut inference_ratio = 0.0_f64;
        for (seq_len, batch, input_size, hidden, iters) in [
            (64usize, 1usize, 128usize, 128usize, 200u32),
            (128, 1, 64, 64, 200),
            (64, 16, 128, 128, 20),
        ] {
            let four_h = 4 * hidden;

            let build = |s: &mut FrankenTorchSession| {
                let input = s
                    .tensor_variable(
                        mk(seq_len * batch * input_size, 0.0),
                        vec![seq_len, batch, input_size],
                        false,
                    )
                    .unwrap();
                let w_ih = s
                    .tensor_variable(
                        mk(four_h * input_size, 1.0),
                        vec![four_h, input_size],
                        false,
                    )
                    .unwrap();
                let w_hh = s
                    .tensor_variable(mk(four_h * hidden, 2.0), vec![four_h, hidden], false)
                    .unwrap();
                let b_ih = s
                    .tensor_variable(mk(four_h, 3.0), vec![four_h], false)
                    .unwrap();
                let b_hh = s
                    .tensor_variable(mk(four_h, 4.0), vec![four_h], false)
                    .unwrap();
                (input, w_ih, w_hh, b_ih, b_hh)
            };

            // NEW: raw tensor_lstm.
            let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
            let (input, w_ih, w_hh, b_ih, b_hh) = build(&mut s);
            let weights = vec![(w_ih, w_hh, Some(b_ih), Some(b_hh))];
            let t0 = Instant::now();
            for _ in 0..iters {
                let _ = s.tensor_lstm(input, None, &weights, false, false).unwrap();
            }
            let new_ns = t0.elapsed().as_nanos();

            // OLD: per-timestep session-op loop (what tensor_lstm used to do).
            let mut s2 = FrankenTorchSession::new(ExecutionMode::Strict);
            let (input2, w_ih2, w_hh2, b_ih2, b_hh2) = build(&mut s2);
            let input_data = s2.tensor_values(input2).unwrap();
            let t1 = Instant::now();
            for _ in 0..iters {
                let w_ih_t = s2.tensor_transpose(w_ih2, 0, 1).unwrap();
                let w_hh_t = s2.tensor_transpose(w_hh2, 0, 1).unwrap();
                let mut h = vec![0.0; batch * hidden];
                let mut c = vec![0.0; batch * hidden];
                for t in 0..seq_len {
                    let mut seq_data = Vec::with_capacity(batch * input_size);
                    for b in 0..batch {
                        for i in 0..input_size {
                            seq_data.push(input_data[t * batch * input_size + b * input_size + i]);
                        }
                    }
                    let x = s2
                        .tensor_variable(seq_data, vec![batch, input_size], false)
                        .unwrap();
                    let h_t = s2
                        .tensor_variable(h.clone(), vec![batch, hidden], false)
                        .unwrap();
                    let c_t = s2
                        .tensor_variable(c.clone(), vec![batch, hidden], false)
                        .unwrap();
                    let (nh, nc) = s2
                        .lstm_cell(x, (h_t, c_t), w_ih_t, w_hh_t, Some(b_ih2), Some(b_hh2))
                        .unwrap();
                    h = s2.tensor_values(nh).unwrap();
                    c = s2.tensor_values(nc).unwrap();
                }
                std::hint::black_box(&h);
            }
            let old_ns = t1.elapsed().as_nanos();

            let ratio = old_ns as f64 / new_ns as f64;
            println!(
                "LSTM A/B (seq={seq_len} batch={batch} in={input_size} hid={hidden}, {iters} iters): \
             old={:.2}ms new={:.2}ms  Score={ratio:.2}x",
                old_ns as f64 / 1e6,
                new_ns as f64 / 1e6,
            );
            if batch == 1 && hidden == 128 {
                inference_ratio = ratio;
            }
        }
        // Reporting-only A/B (numbers are contention-sensitive on shared workers;
        // run under RAYON_NUM_THREADS=1 on an idle box for a clean ratio). Sanity
        // guard only — the bit-exactness contract is enforced by
        // lstm_raw_forward_golden_isomorphism, not by this timing.
        assert!(inference_ratio > 0.0, "benchmark produced no measurement");
    }

    #[test]
    fn lstm_raw_forward_golden_isomorphism() {
        // Golden bit-exactness guard for the raw no-grad LSTM forward
        // (frankentorch-3k4v). Checksum folds the f64 bit-patterns of output +
        // h_n + c_n across six configs (bias on/off, bidirectional, multi-layer,
        // batch_first, supplied hx). The expected value is the checksum produced
        // by the pre-rewrite session-op implementation, so any rounding drift in
        // the raw rewrite trips this test.
        fn fold(acc: &mut u64, v: f64) {
            *acc = acc.rotate_left(7) ^ v.to_bits().wrapping_mul(0x9E37_79B9_7F4A_7C15);
        }
        fn deterministic(n: usize, scale: f64, shift: f64) -> Vec<f64> {
            // Deterministic pseudo-values (no RNG) so the checksum is stable.
            (0..n)
                .map(|i| (((i as f64) * 0.123 + shift).sin()) * scale)
                .collect()
        }

        let compute = || -> u64 {
            let mut acc: u64 = 0xCBF2_9CE4_8422_2325;
            let run = |s: &mut FrankenTorchSession,
                       output: TensorNodeId,
                       h_n: TensorNodeId,
                       c_n: TensorNodeId,
                       acc: &mut u64| {
                for t in [output, h_n, c_n] {
                    for sz in s.tensor_shape(t).unwrap() {
                        fold(acc, sz as f64);
                    }
                    for v in s.tensor_values(t).unwrap() {
                        fold(acc, v);
                    }
                }
            };

            // Config 1: 1-layer, no bias, seq3 batch2 in4 hid5.
            {
                let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
                let input = s
                    .tensor_variable(deterministic(24, 0.5, 0.0), vec![3, 2, 4], false)
                    .unwrap();
                let w_ih = s
                    .tensor_variable(deterministic(80, 0.3, 1.0), vec![20, 4], false)
                    .unwrap();
                let w_hh = s
                    .tensor_variable(deterministic(100, 0.3, 2.0), vec![20, 5], false)
                    .unwrap();
                let weights = vec![(w_ih, w_hh, None, None)];
                let (o, (hn, cn)) = s.tensor_lstm(input, None, &weights, false, false).unwrap();
                run(&mut s, o, hn, cn, &mut acc);
            }
            // Config 2: 1-layer WITH biases.
            {
                let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
                let input = s
                    .tensor_variable(deterministic(24, 0.5, 0.5), vec![3, 2, 4], false)
                    .unwrap();
                let w_ih = s
                    .tensor_variable(deterministic(80, 0.3, 1.5), vec![20, 4], false)
                    .unwrap();
                let w_hh = s
                    .tensor_variable(deterministic(100, 0.3, 2.5), vec![20, 5], false)
                    .unwrap();
                let b_ih = s
                    .tensor_variable(deterministic(20, 0.2, 3.0), vec![20], false)
                    .unwrap();
                let b_hh = s
                    .tensor_variable(deterministic(20, 0.2, 4.0), vec![20], false)
                    .unwrap();
                let weights = vec![(w_ih, w_hh, Some(b_ih), Some(b_hh))];
                let (o, (hn, cn)) = s.tensor_lstm(input, None, &weights, false, false).unwrap();
                run(&mut s, o, hn, cn, &mut acc);
            }
            // Config 3: bidirectional, with biases.
            {
                let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
                let input = s
                    .tensor_variable(deterministic(24, 0.5, 0.7), vec![3, 2, 4], false)
                    .unwrap();
                let w_ih = s
                    .tensor_variable(deterministic(80, 0.3, 1.1), vec![20, 4], false)
                    .unwrap();
                let w_hh = s
                    .tensor_variable(deterministic(100, 0.3, 2.1), vec![20, 5], false)
                    .unwrap();
                let b_ih = s
                    .tensor_variable(deterministic(20, 0.2, 3.1), vec![20], false)
                    .unwrap();
                let b_hh = s
                    .tensor_variable(deterministic(20, 0.2, 4.1), vec![20], false)
                    .unwrap();
                let weights = vec![(w_ih, w_hh, Some(b_ih), Some(b_hh))];
                let (o, (hn, cn)) = s.tensor_lstm(input, None, &weights, false, true).unwrap();
                run(&mut s, o, hn, cn, &mut acc);
            }
            // Config 4: 2-layer (layer1 input = hidden of layer0).
            {
                let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
                let input = s
                    .tensor_variable(deterministic(24, 0.5, 0.9), vec![3, 2, 4], false)
                    .unwrap();
                let w_ih0 = s
                    .tensor_variable(deterministic(80, 0.3, 1.2), vec![20, 4], false)
                    .unwrap();
                let w_hh0 = s
                    .tensor_variable(deterministic(100, 0.3, 2.2), vec![20, 5], false)
                    .unwrap();
                let w_ih1 = s
                    .tensor_variable(deterministic(100, 0.3, 1.3), vec![20, 5], false)
                    .unwrap();
                let w_hh1 = s
                    .tensor_variable(deterministic(100, 0.3, 2.3), vec![20, 5], false)
                    .unwrap();
                let weights = vec![(w_ih0, w_hh0, None, None), (w_ih1, w_hh1, None, None)];
                let (o, (hn, cn)) = s.tensor_lstm(input, None, &weights, false, false).unwrap();
                run(&mut s, o, hn, cn, &mut acc);
            }
            // Config 5: batch_first.
            {
                let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
                let input = s
                    .tensor_variable(deterministic(24, 0.5, 1.7), vec![2, 3, 4], false)
                    .unwrap();
                let w_ih = s
                    .tensor_variable(deterministic(80, 0.3, 1.4), vec![20, 4], false)
                    .unwrap();
                let w_hh = s
                    .tensor_variable(deterministic(100, 0.3, 2.4), vec![20, 5], false)
                    .unwrap();
                let weights = vec![(w_ih, w_hh, None, None)];
                let (o, (hn, cn)) = s.tensor_lstm(input, None, &weights, true, false).unwrap();
                run(&mut s, o, hn, cn, &mut acc);
            }
            // Config 6: supplied initial hx.
            {
                let mut s = FrankenTorchSession::new(ExecutionMode::Strict);
                let input = s
                    .tensor_variable(deterministic(24, 0.5, 2.7), vec![3, 2, 4], false)
                    .unwrap();
                let w_ih = s
                    .tensor_variable(deterministic(80, 0.3, 1.6), vec![20, 4], false)
                    .unwrap();
                let w_hh = s
                    .tensor_variable(deterministic(100, 0.3, 2.6), vec![20, 5], false)
                    .unwrap();
                let h0 = s
                    .tensor_variable(deterministic(10, 0.1, 5.0), vec![1, 2, 5], false)
                    .unwrap();
                let c0 = s
                    .tensor_variable(deterministic(10, 0.1, 6.0), vec![1, 2, 5], false)
                    .unwrap();
                let weights = vec![(w_ih, w_hh, None, None)];
                let (o, (hn, cn)) = s
                    .tensor_lstm(input, Some((h0, c0)), &weights, false, false)
                    .unwrap();
                run(&mut s, o, hn, cn, &mut acc);
            }

            acc
        };
        // frankentorch-qb1g2: the prior frozen bit-checksum was not portable across rch
        // workers — LSTM runs atop matmul -> matrixmultiply, whose AVX2/AVX512/FMA
        // microkernel is chosen by RUNTIME CPU detection, so output low bits differ
        // across heterogeneous workers. Assert same-worker determinism here; the raw
        // vs op-graph forward EQUIVALENCE is covered portably by ft-nn's
        // lstm_no_grad_raw_matches_op_graph (both paths, same worker, bit-exact), and
        // forward/grad correctness by lstm_single_timestep_matches_cell + the
        // finite-difference gradient tests.
        assert_eq!(
            compute(),
            compute(),
            "LSTM raw forward must be deterministic across runs on the same worker"
        );
    }

